#!/usr/bin/env bash
set -Eeuo pipefail
# H1: the descriptor signer key never reaches a child process (see
# provision_descriptor_signer_key and the two re-checks after the env files).
export -n WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
export DEBIAN_FRONTEND=noninteractive
export DEBIAN_PRIORITY=critical
export APT_LISTCHANGES_FRONTEND=none
export NEEDRESTART_MODE=a
export UCF_FORCE_CONFFOLD=1
# The fail2ban restart proof's deadline is a local of hub_f2b_prove_restart.
# One inherited from the environment would bound, and cut, every firewall read
# through hub_run (Seat C, Turn 7), so it never enters from outside.
unset _HUB_F2B_DEADLINE

# M-6: resolve this installer's own directory early (before any cd) so the
# committed vendored Cloudflare key is verified from a fixed path, like Core.
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd -P)"

# This guard must run before defaults, node state, or secrets are sourced.  A
# surprising number of fresh VPS images boot with a provider-created plaintext
# swapfile.  Leaving it active even for preflight lets secret-bearing process
# pages reach unencrypted disk.  RAM-backed zram and storage whose full block
# ancestry includes dm-crypt are safe to retain.
wins_early_swap_source_is_protected() {
  local swap_src="${1:-}" swap_real backing_src backing_real fs_type
  case "${swap_src}" in
    /dev/zram*|/dev/ram*) return 0 ;;
  esac
  swap_real="$(readlink -f "${swap_src}" 2>/dev/null || printf '%s' "${swap_src}")"
  if [[ ! -b "${swap_real}" ]]; then
    fs_type="$(findmnt -no FSTYPE -T "${swap_real}" 2>/dev/null || true)"
    [[ "${fs_type}" =~ ^(tmpfs|ramfs)$ ]] && return 0
    backing_src="$(findmnt -no SOURCE -T "${swap_real}" 2>/dev/null || true)"
    [[ -n "${backing_src}" ]] || return 1
    backing_real="$(readlink -f "${backing_src}" 2>/dev/null || printf '%s' "${backing_src}")"
  else
    backing_real="${swap_real}"
  fi
  lsblk -spno TYPE "${backing_real}" 2>/dev/null | grep -x crypt >/dev/null
}

wins_early_unprotected_swap_devices() {
  local swap_src _swap_type
  [[ -r /proc/swaps ]] || return 0
  while read -r swap_src _swap_type; do
    [[ -n "${swap_src}" && "${swap_src}" != "Filename" ]] || continue
    wins_early_swap_source_is_protected "${swap_src}" || printf '%s\n' "${swap_src}"
  done < /proc/swaps
}

wins_early_plaintext_swap_guard() {
  local validate_only=0 arg swap_src remaining
  for arg in "$@"; do
    case "${arg}" in
      --help|-h) return 0 ;;
      --preflight|--validate) validate_only=1 ;;
    esac
  done
  remaining="$(wins_early_unprotected_swap_devices | paste -sd ',' -)"
  [[ -n "${remaining}" ]] || return 0
  if ((validate_only)); then
    echo "[ERR] Unprotected swap is active (${remaining}). Run --deploy to disable it before any credential file is loaded." >&2
    return 1
  fi
  echo "[WARN] Disabling unprotected swap before loading deployment credentials: ${remaining}" >&2
  while IFS= read -r swap_src; do
    [[ -n "${swap_src}" ]] || continue
    swapoff "${swap_src}" || {
      echo "[ERR] Unable to disable unprotected swap ${swap_src}; deployment stopped before loading credentials." >&2
      return 1
    }
  done < <(wins_early_unprotected_swap_devices)
  remaining="$(wins_early_unprotected_swap_devices | paste -sd ',' -)"
  [[ -z "${remaining}" ]] || {
    echo "[ERR] Unprotected swap remains active (${remaining}); deployment stopped before loading credentials." >&2
    return 1
  }
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  wins_early_plaintext_swap_guard "$@"
fi

APT_GET=(apt-get -o DPkg::Lock::Timeout=300 -o Acquire::Retries=3 -o Dpkg::Use-Pty=0 -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold)

WINS_DEFAULTS_FILE="${WINS_DEFAULTS_FILE:-/root/winsvpn-defaults.env}"

# OI-14 (Round 36 treaty): every sourced defaults/secrets/env file must be a
# real regular file, not a symlink, root-owned, and no looser than 0600 before
# it is executed by this root installer. Mirrors the core-server installer's
# trusted-env gate. The ANCESTOR walk is the Round 37 cross-examination
# addition: a 0600 root-owned file inside a directory a non-root user can
# write is replaceable by rename, so every parent up to / must be root-owned
# without group or other write.
wins_require_trusted_env_file() {
  local path="$1" label="$2"
  [[ -f "${path}" && ! -L "${path}" ]] || {
    echo "[ERR] ${label} must be a real regular file: ${path}" >&2
    exit 1
  }
  [[ "${path}" == /* ]] || {
    echo "[ERR] ${label} must be an absolute path: ${path}" >&2
    exit 1
  }
  local parent
  parent="$(dirname -- "${path}")"
  while [[ "${parent}" != "/" ]]; do
    [[ "$(stat -c '%u' "${parent}")" == "0" ]] || {
      echo "[ERR] ${label} ancestor must be root-owned: ${parent}" >&2
      exit 1
    }
    # LSR R6: find's own status first; a failed find is an uninspected mode.
    local perm_hits perm_rc=0
    perm_hits="$(find "${parent}" -maxdepth 0 -perm /022 -print -quit)" || perm_rc=$?
    (( perm_rc == 0 )) || {
      echo "[ERR] Could not inspect the permissions of ${label} ancestor ${parent} (find failed, exit ${perm_rc})" >&2
      exit 1
    }
    [[ -z "${perm_hits}" ]] || {
      echo "[ERR] ${label} ancestor must not be group- or world-writable: ${parent}" >&2
      exit 1
    }
    parent="$(dirname "${parent}")"
  done
  [[ "$(stat -c '%u' "${path}")" == "0" ]] || {
    echo "[ERR] ${label} must be owned by root: ${path}" >&2
    exit 1
  }
  local file_hits file_rc=0
  file_hits="$(find "${path}" -prune -perm /077 -print -quit)" || file_rc=$?
  (( file_rc == 0 )) || {
    echo "[ERR] Could not inspect the permissions of ${label} ${path} (find failed, exit ${file_rc})" >&2
    exit 1
  }
  [[ -z "${file_hits}" ]] || {
    echo "[ERR] ${label} must have mode 0600 or stricter: ${path}" >&2
    exit 1
  }
}

if [[ -f "${WINS_DEFAULTS_FILE}" ]]; then
  wins_require_trusted_env_file "${WINS_DEFAULTS_FILE}" "WINS_DEFAULTS_FILE"
  set -a
  # shellcheck source=/dev/null
  . "${WINS_DEFAULTS_FILE}"
  set +a
fi
# H1: set -a above exports it; never put the signer key in the defaults file.
export -n WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64

# --- begin IA-CP-01 operator intent capture ---
# IA-CP-01 (installer audit 2026-09-29): record which settings the operator
# supplied for THIS run: the process environment plus the defaults file, which
# is sourced with `set -a` above and therefore exported. write_env loads the
# previous run's ${ENV_FILE} and then re-applies exactly these keys, so a
# changed defaults-file value is no longer silently reverted on rerun while
# --preflight validates the new one. Empty values are NOT intent: the preseed
# prepends .env.example, which carries dozens of KEY= placeholders (ADMIN_TOKEN=,
# SPA_KEY=, TUNNEL_SERVICE_TOKEN_SECRET=, HUB_ADMIN_SSH_CIDRS=, ...), and every
# consumer treats empty as "use the default" anyway. Names only; no value is
# copied here.
WINS_OPERATOR_INTENT_KEYS=()
while IFS= read -r _wins_intent_key; do
  [[ "${_wins_intent_key}" =~ ^[A-Z][A-Z0-9_]*$ && -n "${!_wins_intent_key:-}" ]] || continue
  WINS_OPERATOR_INTENT_KEYS+=("${_wins_intent_key}")
done < <(compgen -e)
unset _wins_intent_key
# --- end IA-CP-01 operator intent capture ---

# Secrets are injected once by the provider/cloud-init layer. This file is
# deliberately separate from versioned defaults and must remain root-only.
# Operator-laptop analogue (this installer never reads it): ~/.winsvpn/hub-commerce.env
# modelled on ~/.winsvpn/wfa-release.env. Deliver onto the hub with an ssh heredoc;
# never scp (auto-rejects from the Mac). Names-only template:
# server/hub-commerce.env.example. Never commit values; never paste them into a handoff.
WINS_SECRETS_FILE="${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}"

overlay_wins_secrets_file() {
  # Re-source after load_existing_envs so injected commerce values win over
  # empty runtime placeholders (KEY=''). Missing file is a no-op, matching
  # the original optional top-level load. Present file: same root-only perm
  # checks. Source failure is fatal -- never `|| true` after this (that
  # defect class let --preflight report success with no key material).
  #
  # IA-CP-16: the same trusted-env gate as WINS_DEFAULTS_FILE (regular
  # non-symlink file, root-owned, 0600 or stricter, and every ancestor
  # root-owned without group or other write). Owner and mode alone let a
  # symlink or a file in a non-root-writable directory through. The gate
  # exits, so it runs in a subshell to keep this function's return contract.
  [[ -e "${WINS_SECRETS_FILE}" || -L "${WINS_SECRETS_FILE}" ]] || return 0
  ( wins_require_trusted_env_file "${WINS_SECRETS_FILE}" "WINS_SECRETS_FILE" ) || return 1
  # Intentionally sourced without `set -a`: these names become plain shell
  # variables usable via "${VAR}" expansion in this process, but are not
  # exported into the OS environment, so every later child process this
  # script spawns (apt-get, systemctl, curl, etc.) no longer inherits every
  # secret by default. Call sites that genuinely need a specific value in a
  # child process's environment export it explicitly and narrowly instead.
  # shellcheck source=/dev/null
  . "${WINS_SECRETS_FILE}" || return 1
  # H1: an `export` line in the file must not hand the descriptor signer key
  # to children spawned after a later overlay (write_env runs this again).
  export -n WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
}

overlay_wins_secrets_file || exit 1
# H1: the descriptor signer key must never reach a child process (apt, pip,
# curl and the rest) spawned before provision_descriptor_signer_key consumes it.
export -n WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64

IONOS_HUB_IP="${IONOS_HUB_IP:-${WINS_HUB_IP:-}}"
HUB_DOMAIN="${HUB_DOMAIN:-hub.winsvpn.org}"
read -r -a SYNC_DOMAINS <<< "${SYNC_DOMAINS:-sync.winsvpn.org sync.winsvpn.com}"
WEBSITE_TLS_CERT="${WEBSITE_TLS_CERT:-/etc/winsvpn/tls/website-ev-fullchain.crt}"
WEBSITE_TLS_KEY="${WEBSITE_TLS_KEY:-/etc/winsvpn/tls/website-ev.key}"
read -r -a WEBSITE_TLS_DOMAINS <<< "${WEBSITE_TLS_DOMAINS:-winsvpn.org winsvpn.com meetmrwin.com}"

APP_DIR="/root/vpn_auth"
ENV_FILE="/root/vpn_auth.env"
LEGACY_ENV_FILE="${APP_DIR}/.env"
# wins-hub.service EnvironmentFile= is ${ENV_FILE} (/root/vpn_auth.env), NOT
# ${LEGACY_ENV_FILE} (/root/vpn_auth/.env). write_env mirrors the same buffer
# onto the legacy path for the old all-in-one script, but the process
# environment the hub actually loads is ENV_FILE. A past incident: the unit
# loaded /root/vpn_auth.env while the operator edited /root/vpn_auth/.env.
# /etc/winn/server.env is a different unit (winn-server, retired AWG PSK
# rotator) and must not receive these keys.
WINN3_INNER_POOL_CIDR_DEFAULT="${WINN3_INNER_POOL_CIDR_DEFAULT:-10.10.0.0/24}"
# Client-owned device keys (Fable 5.1 ruling 2026-09-29, IA-CP-05). 1 keeps the
# legacy hub-minted path for builds that send no winn3_static_public, and the
# legacy AWG mint for builds that send no client_public_key. Flip to 0 only
# once the client-key build is min_supported_version on the force-update gate.
WINN3_HUB_MINTED_KEYS_ALLOWED_DEFAULT="${WINN3_HUB_MINTED_KEYS_ALLOWED_DEFAULT:-1}"
# Offline-signed announcements (ruling IA-CP-06). The hub holds only the
# PUBLIC keys ANNOUNCE_PUBKEY_A1..A3 (base64 of the raw 32 Ed25519 bytes, the
# same values as the app's WINS_ANNOUNCE_PUBKEY_A* defines). 0 keeps the
# plaintext msg form accepted until the signing ceremony is complete.
ANNOUNCE_REQUIRE_SIGNED_DEFAULT="${ANNOUNCE_REQUIRE_SIGNED_DEFAULT:-0}"
# Opt-in: provision ONE node as standalone v3 (protocol_params.carrier=winn3)
# at install time. Default OFF. Production POST /admin/nodes/winn3 requires
# the exact standalone carrier winn3 and complete nonempty protocol params;
# an empty body is refused rather than stored as the retired AWG-relay.
# This flag never flips a node the operator did not name. The hub process
# reads these from ${ENV_FILE}; they are deploy-time operator intent, not a
# node self-assertion.
WINN3_SET_CARRIER_STANDALONE_DEFAULT="${WINN3_SET_CARRIER_STANDALONE:-0}"
WINN3_STANDALONE_NODE_SLUG_DEFAULT="${WINN3_STANDALONE_NODE_SLUG:-}"
WINN3_STANDALONE_PATH_MTU_DEFAULT="${WINN3_STANDALONE_PATH_MTU:-1450}"
# `tls` REMOVED from the default 2026-08-12 (ruling D24). It was a trap: the
# client's winn3DialCarrier hard-refuses carrier.ClassTLS -- the v3 host profile
# carries no trust anchors, no ECH list and no client certificate, and dialling
# TCP while reporting TLS would be a silent downgrade -- but winn3Profile
# validate() ACCEPTS class=tls at load, so the refusal only fires at dial time.
# An operator provisioning with defaults therefore believed the node had a TLS
# cover hop it does not have, and sized the deployment around a phantom.
# Re-add `tls` only when ClassTLS is genuinely dialable (trust anchors + ECH
# list + client cert in the profile, and a real cover listener on the gateway).
# Note the plan floor is computed over the named classes, so dropping tls
# slightly raises the payload floor; re-introducing it later re-sizes.
WINN3_STANDALONE_CARRIER_CLASSES_DEFAULT="${WINN3_STANDALONE_CARRIER_CLASSES:-udp}"
# Optional path to the JSON envelope from tools/winn3_sign_descriptor.py --json
# (keys descriptor_payload_b64, descriptor_sig_b64). Never generated here.
WINN3_STANDALONE_DESCRIPTOR_JSON_DEFAULT="${WINN3_STANDALONE_DESCRIPTOR_JSON:-}"
VENV_DIR="${APP_DIR}/venv"
DB_PATH="${APP_DIR}/vpn_users.db"
SERVICE_FILE="/etc/systemd/system/wins-hub.service"
NGINX_SITE="/etc/nginx/sites-available/wins-hub.conf"
DEVICE_LIMIT_DEFAULT="${DEVICE_LIMIT:-3}"

# Secret defaults stay empty; write_env reuses the root-owned environment or
# generates fresh values for a new control hub.
ADMIN_TOKEN_DEFAULT=""
SPA_KEY_DEFAULT=""
SPA_HMAC_DEFAULT=""
XRAY_UUID_DEFAULT=""
SMTP_SERVER_DEFAULT="mail.smtp2go.com"
SMTP_PORT_DEFAULT="2525"
SMTP_USER_DEFAULT=""
SMTP_PASS_DEFAULT=""
EMAIL_SENDER_DEFAULT="support@winsvpn.org"
SECURITY_ALERT_EMAIL_DEFAULT="security@winsvpn.com"
SECURITY_ALERT_EXEMPT_IPS_DEFAULT="127.0.0.1,::1"
SECURITY_EVENTS_DB_DEFAULT="/var/lib/wins-security-alerts/security_events.db"
SECURITY_EVENTS_RETENTION_DAYS_DEFAULT="180"
SECURITY_ALERT_TIMEZONE_DEFAULT="America/New_York"
SECURITY_ALERT_EMAIL_PRIORITIES_DEFAULT="1,2"
SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS_DEFAULT="2042145"
SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS_DEFAULT="ET DYN_DNS,DYNAMIC_DNS HTTP Request,from-ks"
SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS_DEFAULT=""
SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS_DEFAULT="SURICATA STREAM,SURICATA Applayer,SURICATA TCPv4 invalid checksum"
SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS_DEFAULT=""
SECURITY_TRIAGE_ENABLED_DEFAULT="${SECURITY_TRIAGE_ENABLED:-1}"
SECURITY_TRIAGE_ABSENT_PRODUCTS_DEFAULT="${SECURITY_TRIAGE_ABSENT_PRODUCTS:-coldfusion,geoserver,apache solr,tomcat manager,spring actuator,hnap,dvr,camera web interface}"
SECURITY_TRIAGE_PRESENT_PRODUCTS_DEFAULT="${SECURITY_TRIAGE_PRESENT_PRODUCTS:-nginx,fastapi,openssh,suricata}"
# FRESH-PROVISION DEFAULT AUDIT (2026-08-07), §3.2. This default used to be a
# branded product-and-version string naming this project.
# wins-gateway-canary.timer curls EVERY registered node's
# PUBLIC /healthz with it every 15 minutes, and a node's default stealth posture
# is xray_security='none' on port 80 -- so that string crossed the wire in
# cleartext, on a fixed schedule, from a fixed source address, on every node's
# public port. A censor watching a suspected node did not have to characterise
# AmneziaWG or defeat any obfuscation; the control plane announced the hub-node
# relationship for them, in ASCII.
#
# A branded UA buys nothing operationally: the canary already knows which
# request it issued, and every consumer of this value reads it back from
# vpn_auth.env rather than recognising the literal. What it cost was a
# fleet-wide identifier. curl/8.5.0 is simply what the stock curl on Ubuntu
# 24.04 sends unasked, so these requests now look like the enormous background
# of curl-driven monitoring that hits port 80 everywhere.
#
# Keep this in sync with HEALTH_USER_AGENT in the security-alert monitor: that
# module compares an observed Suricata http_user_agent against this exact value
# to recognise the hub's own health probes (expected_local_health_event), so a
# divergence turns every canary run into a security alert.
WINS_HEALTH_USER_AGENT_DEFAULT="${WINS_HEALTH_USER_AGENT:-curl/8.5.0}"
REQUIRE_LUKS_ROOT_DEFAULT="${REQUIRE_LUKS_ROOT:-0}"
# --- Disk-encryption posture ------------------------------------------------
#
# Unlike Core, this installer never had a hard verify_luks gate: REQUIRE_LUKS_ROOT
# already defaults to 0 and configure_luks_root_policy only warns on a non-LUKS
# root. That warn-and-continue path is not a control set. This knob chooses
# between two postures that this installer actually verifies:
#
#   luks       Require a LUKS-backed root. Strongest. Also implied by
#              REQUIRE_LUKS_ROOT=1 (that existing hard-require is not weakened).
#   substitute Do not require LUKS. Require the SUBSTITUTE CONTROL SET instead
#              (see verify_disk_encryption_posture) and refuse if it cannot be
#              established.
#   auto       (default) Use "luks" when the root is already LUKS-backed,
#              otherwise "substitute".
#
# There is deliberately NO "none"/"off"/"skip" value. REQUIRE_LUKS_ROOT=1 with
# CONTROL_DISK_ENCRYPTION_MODE=substitute is a contradiction and is refused.
#
# THE HONEST DIFFERENCE: the substitute set protects secrets from a RUNNING-HOST
# adversary (another local account, a non-root service, paged-out key material).
# It does NOT protect a POWERED-OFF DISK that is physically removed, imaged, or
# seized, nor a cold provider-side snapshot of the block device. That single
# case is what LUKS buys and the substitute set cannot.
CONTROL_DISK_ENCRYPTION_MODE="${CONTROL_DISK_ENCRYPTION_MODE:-auto}"
CONTROL_DISK_ENCRYPTION_EFFECTIVE=""
LUKS_REMOTE_UNLOCK_DEFAULT="${LUKS_REMOTE_UNLOCK:-1}"
LUKS_UNLOCK_SSH_PORT_DEFAULT="${LUKS_UNLOCK_SSH_PORT:-2222}"
LUKS_INITRAMFS_IP_DEFAULT="${LUKS_INITRAMFS_IP:-dhcp}"
# LUKS-FIX (2026-10-11, handoff section 42): with IP=dhcp the early-boot DEVICE
# is ALWAYS empty (dropbear's init-premount script owns DHCP alone and ipconfig
# takes every interface); "auto" resolves to the WAN interface only for a
# static LUKS_INITRAMFS_IP. The file is /etc/initramfs-tools/conf.d/winn-fde-network,
# the one deploy/fde_boot_chain.sh writes; a converted host keeps its copy.
LUKS_INITRAMFS_DEVICE_DEFAULT="${LUKS_INITRAMFS_DEVICE:-auto}"

# The early-boot network file. ONE file, ONE DHCP owner (handoff section 42).
# Byte-identical to the function in deploy/fde_boot_chain.sh (a test asserts it).
write_early_boot_network_conf() {
  # $1 = dhcp | kernel ip= spec, $2 = device name ('' = every interface)
  printf '%s\n' \
    "IP='$1'" \
    "DEVICE='$2'" \
    "DEVICE6=''" \
    "IP6='off'" \
    'BUSYBOX=y'
}

# Every bootable /boot/initrd.img-* must carry the unlock path and at most one
# early-boot network file; a miss here is a lockout at the next reboot, so the
# deploy stops before it.
verify_luks_unlock_initramfs() {
  local boot_dir="${WINS_BOOT_DIR:-/boot}" modules_dir="${WINS_MODULES_DIR:-/lib/modules}"
  local image release listing needle hooks count=0
  command -v lsinitramfs >/dev/null 2>&1 || { err "lsinitramfs is missing; cannot verify the unlock initramfs."; return 1; }
  listing="$(mktemp)" || return 1
  for image in "${boot_dir}"/initrd.img-*; do
    [[ -f "${image}" ]] || continue
    if ! lsinitramfs "${image}" > "${listing}" 2>/dev/null || [[ ! -s "${listing}" ]]; then
      rm -f -- "${listing}"; err "Cannot list ${image}; the LUKS unlock cannot be verified."; return 1
    fi
    if grep -Eq 'zz-winn-fde-v4|winn-fde-tools|conf/winn-fde-conversion-key|winn-fde-pass|winn-luks-initpass|conf/conf.d/winn-fde-layout' "${listing}"; then
      rm -f -- "${listing}"; err "${image} retains conversion code or credentials; custody is incomplete."; return 1
    fi
    release="${image##*/initrd.img-}"
    [[ -d "${modules_dir}/${release}" ]] || continue
    for needle in scripts/local-top/cryptroot scripts/init-premount/dropbear conf/conf.d/winn-fde-network; do
      grep -Fxq "${needle}" "${listing}" \
        || { rm -f -- "${listing}"; err "${image} lacks ${needle}; the LUKS unlock would fail at the next reboot."; return 1; }
    done
    grep -Eq '^(usr/)?sbin/dropbear$' "${listing}" \
      || { rm -f -- "${listing}"; err "${image} lacks dropbear; remote unlock on the LUKS port would be impossible."; return 1; }
    grep -Eq '^(usr/)?sbin/cryptsetup$' "${listing}" \
      || { rm -f -- "${listing}"; err "${image} lacks cryptsetup; the root could not be unlocked."; return 1; }
    grep -Eq '^(usr/)?s?bin/ip$' "${listing}" \
      || { rm -f -- "${listing}"; err "${image} lacks ip; the early-boot network handoff would fail."; return 1; }
    if grep -Fxq scripts/init-premount/00-winn-fde-network "${listing}"; then
      grep -Fxq scripts/init-bottom/zz-winn-fde-network-handoff "${listing}" \
        || { rm -f -- "${listing}"; err "${image} lacks the boot chain's network handoff script."; return 1; }
    fi
    if grep -Eq 'scripts/init-premount/zz-winn-fde-network$|conf/conf.d/wins-remote-unlock$' "${listing}"; then
      rm -f -- "${listing}"; err "${image} carries a duplicate early-boot network file (handoff section 42)."; return 1
    fi
    hooks="$(grep -Ec '^scripts/init-premount/.*winn-fde' "${listing}" || true)"
    (( hooks <= 1 )) || { rm -f -- "${listing}"; err "${image} carries ${hooks} winn-fde init-premount hooks; exactly one is allowed."; return 1; }
    count=$((count + 1))
  done
  rm -f -- "${listing}"
  (( count > 0 )) || { err "No bootable initramfs under ${boot_dir} was verified."; return 1; }
  log "LUKS unlock verified in ${count} bootable initramfs image(s): cryptroot, dropbear, cryptsetup, one early-boot network file."
  return 0
}
# Owner ruling 2026-09-25: swap on every server is compressed RAM (zram); it
# replaces the 2026-08-05 rule of 12 GB of disk swap. Disk swap is off by
# default and refused if requested until a separately reviewed LUKS-backed
# mechanism exists. The loop-backed random-key swap (WINS_CRYPTSWAP_ENABLED) is
# retired: setting it to 1 is refused and no installer builds that chain. Its
# backing image was a file on the root filesystem behind a loop device, so every
# swap write re-entered ext4 and needed memory when memory was exhausted. It hung Chicago and Spain on
# 2026-09-24 (dmcrypt_write blocked > 600 s) and reproduced five times in a
# 2 GiB 6.8.0-139 VM (lane L40), including with zram in front of it.
ENABLE_WINS_SWAPFILE_DEFAULT="${ENABLE_WINS_SWAPFILE:-0}"
ALLOW_UNENCRYPTED_SWAPFILE_DEFAULT="${ALLOW_UNENCRYPTED_SWAPFILE:-0}"
WINS_CRYPTSWAP_ENABLED_DEFAULT="${WINS_CRYPTSWAP_ENABLED:-0}"
ENABLE_ZRAM_SWAP_DEFAULT="${ENABLE_ZRAM_SWAP:-1}"
ZRAM_SWAP_PERCENT_DEFAULT="${ZRAM_SWAP_PERCENT:-50}"
ZRAM_SWAP_MAX_MB_DEFAULT="${ZRAM_SWAP_MAX_MB:-2048}"
WINS_PARTIAL_VAULT_ENABLED_DEFAULT="${WINS_PARTIAL_VAULT_ENABLED:-0}"
WINS_PARTIAL_VAULT_IMAGE_DEFAULT="${WINS_PARTIAL_VAULT_IMAGE:-/var/lib/winsvpn-vault.luks}"
WINS_PARTIAL_VAULT_MOUNT_DEFAULT="${WINS_PARTIAL_VAULT_MOUNT:-/srv/winsvpn-vault}"
WINS_PARTIAL_VAULT_NAME_DEFAULT="${WINS_PARTIAL_VAULT_NAME:-winsvpn-vault}"
WINS_PARTIAL_VAULT_SIZE_DEFAULT="${WINS_PARTIAL_VAULT_SIZE:-16G}"
