# re-run would delete a hand-added switch.
WINN3_RELAY_ENABLED_DEFAULT="${WINN3_RELAY_ENABLED:-0}"
# ONE range value, "MIN-MAX": the ports the owner's router forwards to the Core.
# The Core installer carries the same text as CORE_RELAY_PORT_RANGE and the two
# sides check each other at run time.
WINN3_RELAY_PORT_RANGE_DEFAULT="${WINN3_RELAY_PORT_RANGE:-9211-9218}"
WINN3_RELAY_REPORT_MAX_AGE_SECONDS_DEFAULT="${WINN3_RELAY_REPORT_MAX_AGE_SECONDS:-30}"
PAYPAL_LIFETIME_SUPPORT_MARKERS_DEFAULT="lifetime_support,tech_support"
PAYPAL_LIFETIME_NO_SUPPORT_MARKERS_DEFAULT="lifetime_no_support,no_tech_support,no_support"
PAYPAL_LIFETIME_MARKERS_DEFAULT="wins_lifetime,lifetime,life_time"
CLOUDFLARE_APPCLOUD_ACCOUNT_ID_DEFAULT=""
CLOUDFLARE_APPCLOUD_API_TOKEN_DEFAULT=""
CLOUDFLARE_APPCLOUD_ZONE_ID_DEFAULT=""
CLOUDFLARE_APPCLOUD_ZONE_NAME_DEFAULT="${CLOUDFLARE_APPCLOUD_ZONE_NAME:-app-cloud-sync.net}"
# The app-cloud zone is a separate Cloudflare account and is reserved for
# data-plane stealth hostnames. A CNAME from that account to a tunnel in the
# Wins account returns Cloudflare 530, so do not advertise it as a hub route.
CLOUDFLARE_APPCLOUD_RECORDS_DEFAULT="${CLOUDFLARE_APPCLOUD_RECORDS:-}"
CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS_DEFAULT="${CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS:-app-cloud-sync.net sync.app-cloud-sync.net}"
CLOUDFLARE_WINS_ACCOUNT_ID_DEFAULT=""
CLOUDFLARE_WINS_API_TOKEN_DEFAULT=""
CLOUDFLARE_WINSVPN_ORG_ZONE_ID_DEFAULT="CF_ZONE_ID_ORG_REDACTED"
CLOUDFLARE_WINSVPN_ORG_ZONE_NAME_DEFAULT="${CLOUDFLARE_WINSVPN_ORG_ZONE_NAME:-winsvpn.org}"
CLOUDFLARE_WINSVPN_COM_ZONE_ID_DEFAULT="CF_ZONE_ID_COM_REDACTED"
CLOUDFLARE_WINSVPN_COM_ZONE_NAME_DEFAULT="${CLOUDFLARE_WINSVPN_COM_ZONE_NAME:-winsvpn.com}"
CLOUDFLARE_WINS_RECORDS_DEFAULT="${CLOUDFLARE_WINS_RECORDS:-hub.winsvpn.org sync.winsvpn.org}"
CLOUDFLARE_WINS_COM_RECORDS_DEFAULT="${CLOUDFLARE_WINS_COM_RECORDS:-sync.winsvpn.com}"
NODE_MANAGEMENT_TUNNEL_ZONE_ID_DEFAULT="${NODE_MANAGEMENT_TUNNEL_ZONE_ID:-$CLOUDFLARE_WINSVPN_COM_ZONE_ID_DEFAULT}"
NODE_MANAGEMENT_TUNNEL_ZONE_NAME_DEFAULT="${NODE_MANAGEMENT_TUNNEL_ZONE_NAME:-winsvpn.com}"
# Cloudflare Tunnel hides the management origin, while Access adds an
# independent machine-identity check before the SSH WebSocket reaches the
# connector.  The API token is deliberately separate from the tunnel/DNS
# tokens so it can be limited to Access Apps, Policies, and Service Tokens.
REQUIRE_CLOUDFLARE_ACCESS_DEFAULT="${REQUIRE_CLOUDFLARE_ACCESS:-1}"
CLOUDFLARE_ACCESS_API_TOKEN_DEFAULT="${CLOUDFLARE_ACCESS_API_TOKEN:-}"
CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME_DEFAULT="${CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME:-winsvpn-management-hub}"
CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION_DEFAULT="${CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION:-8760h}"
CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID_DEFAULT="${CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID:-}"
TUNNEL_SERVICE_TOKEN_ID_DEFAULT="${TUNNEL_SERVICE_TOKEN_ID:-}"
TUNNEL_SERVICE_TOKEN_SECRET_DEFAULT="${TUNNEL_SERVICE_TOKEN_SECRET:-}"

log()  { echo -e "\033[1;36m[INFO]\033[0m $*"; }
warn() { echo -e "\033[1;33m[WARN]\033[0m $*"; }
err()  { echo -e "\033[1;31m[ERR]\033[0m $*"; }

curl_bearer() {
  local token="$1"
  shift
  [[ -n "${token}" && "${token}" != *$'\n'* && "${token}" != *$'\r'* && "${token}" != *'"'* ]] || {
    err "Refusing to pass an invalid bearer token to curl."
    return 1
  }
  # Process substitution keeps the secret out of argv and off persistent disk.
  curl --config <(printf 'header = "Authorization: Bearer %s"\n' "${token}") "$@"
}

curl_paypal_oauth() {
  local client_id="$1" client_secret="$2"
  shift 2
  [[ "${client_id}" =~ ^[A-Za-z0-9._~-]+$ && "${client_secret}" =~ ^[A-Za-z0-9._~-]+$ ]] || {
    err "PayPal OAuth credentials contain unsupported characters."
    return 1
  }
  curl --config <(printf 'user = "%s:%s"\n' "${client_id}" "${client_secret}") "$@"
}
trap 'err "Line $LINENO failed with exit code $?"' ERR

if [[ "${1:-}" == "--menu" ]]; then
  if [[ -x /usr/local/bin/wins-admin ]]; then
    exec /usr/local/bin/wins-admin --menu
  fi
  echo "wins-admin is not installed yet. Run this setup script once first." >&2
  exit 1
fi


require_root() {
  [[ "${EUID:-0}" -eq 0 ]] || { err "Run as root"; exit 1; }
}

valid_ipv4() {
  local ip="${1:-}" octet
  local -a octets=()
  [[ "${ip}" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
  IFS='.' read -r -a octets <<<"${ip}"
  for octet in "${octets[@]}"; do
    ((10#${octet} <= 255)) || return 1
  done
}

valid_port() {
  local port="${1:-}"
  [[ "${port}" =~ ^[0-9]+$ ]] && ((port >= 1 && port <= 65535))
}

valid_ipv4_cidr() {
  local cidr="${1:-}" addr prefix
  [[ "${cidr}" == */* ]] || return 1
  addr="${cidr%%/*}"
  prefix="${cidr#*/}"
  valid_ipv4 "${addr}" || return 1
  [[ "${prefix}" =~ ^[0-9]+$ ]] && ((prefix <= 32))
}

valid_unix_username() {
  [[ "${1:-}" =~ ^[a-z][a-z0-9_-]{0,31}$ ]]
}

public_ipv4() {
  local ip="${1:-}" first second
  valid_ipv4 "${ip}" || return 1
  IFS='.' read -r first second _ <<<"${ip}"
  ((first != 0 && first != 10 && first != 127 && first < 224)) || return 1
  ((first != 169 || second != 254)) || return 1
  ((first != 172 || second < 16 || second > 31)) || return 1
  ((first != 192 || second != 168)) || return 1
  ((first != 100 || second < 64 || second > 127)) || return 1
}

valid_dns_hostname() {
  local host="${1:-}" label
  local -a labels=()
  [[ -n "${host}" && ${#host} -le 253 && "${host}" == *.* ]] || return 1
  [[ "${host}" =~ ^[A-Za-z0-9.-]+$ && "${host}" =~ [A-Za-z] ]] || return 1
  [[ "${host}" != .* && "${host}" != *. && "${host}" != *..* ]] || return 1
  IFS='.' read -r -a labels <<<"${host}"
  for label in "${labels[@]}"; do
    [[ -n "${label}" && ${#label} -le 63 ]] || return 1
    [[ "${label}" =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$ ]] || return 1
  done
}

detect_hub_ipv4() {
  local candidate
  while IFS= read -r candidate; do
    candidate="${candidate%%/*}"
    if public_ipv4 "${candidate}"; then
      printf '%s\n' "${candidate}"
      return 0
    fi
  done < <(ip -o -4 addr show scope global 2>/dev/null | awk '{print $4}')
  return 1
}

validate_zram_policy_settings() {
  local enabled="${ENABLE_ZRAM_SWAP:-$ENABLE_ZRAM_SWAP_DEFAULT}"
  local percent="${ZRAM_SWAP_PERCENT:-$ZRAM_SWAP_PERCENT_DEFAULT}"
  local max_mb="${ZRAM_SWAP_MAX_MB:-$ZRAM_SWAP_MAX_MB_DEFAULT}"
  case "${enabled,,}" in
    0|false|no|off) return 0 ;;
    1|true|yes|on) ;;
    *)
      err "ENABLE_ZRAM_SWAP must be 0 or 1."
      return 1
      ;;
  esac
  if ! [[ "${percent}" =~ ^[1-9][0-9]*$ ]] \
      || ((10#${percent} < 25 || 10#${percent} > 100)); then
    err "ZRAM_SWAP_PERCENT must be a canonical integer from 25 through 100."
    return 1
  fi
  if ! [[ "${max_mb}" =~ ^[1-9][0-9]*$ ]] \
      || ((10#${max_mb} < 256 || 10#${max_mb} > 8192)); then
    err "ZRAM_SWAP_MAX_MB must be a canonical integer from 256 through 8192."
    return 1
  fi
}

# The client bounds each Double VPN verify attempt at 7 s, and that request
# also does work outside the readiness wait (the peer sync runs over ssh with a
# 3 s connect timeout), so the wait stays at 5 s or less. The hub clamps an
# explicit value to the same ceiling. The digit count is capped because bash
# arithmetic wraps: 18446744073709551617 compares as 1.
DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_MAX_SECONDS=5
validate_double_vpn_ready_timeout() {
  local value="${1:-${DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_SECONDS_DEFAULT}}"
  if ! [[ "${value}" =~ ^[1-9][0-9]{0,8}$ ]] \
      || ((10#${value} > DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_MAX_SECONDS)); then
    err "DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_SECONDS must be an integer from 1 to ${DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_MAX_SECONDS}; the client gives each Double VPN verify attempt 7 s."
    return 1
  fi
}

# The relay switch is 0 or 1 and the port range is the same bounded range the hub
# python enforces (1024..65535, at most 64 ports, never a reserved listener port).
validate_winn3_relay_settings() {
  local enabled="${WINN3_RELAY_ENABLED_DEFAULT}" range="${WINN3_RELAY_PORT_RANGE_DEFAULT}" low high
  local age="${WINN3_RELAY_REPORT_MAX_AGE_SECONDS_DEFAULT}" reserved
  [[ "${enabled}" == "0" || "${enabled}" == "1" ]] || {
    err "WINN3_RELAY_ENABLED must be 0 or 1."
    return 1
  }
  [[ "${range}" =~ ^([1-9][0-9]{3,4})-([1-9][0-9]{3,4})$ ]] || {
    err "WINN3_RELAY_PORT_RANGE must look like 9211-9218 (MIN-MAX)."
    return 1
  }
  low="${BASH_REMATCH[1]}"
  high="${BASH_REMATCH[2]}"
  ((low >= 1024 && low <= high && high <= 65535 && high - low < 64)) || {
    err "WINN3_RELAY_PORT_RANGE must satisfy 1024 <= min <= max <= 65535 with at most 64 ports."
    return 1
  }
  for reserved in 9210 9110 9111; do
    if ((reserved >= low && reserved <= high)); then
      err "The relay port range ${low}-${high} contains port ${reserved}, which another listener owns."
      return 1
    fi
  done
  [[ "${age}" =~ ^[0-9]{1,3}$ ]] && ((10#${age} >= 5 && 10#${age} <= 300)) || {
    err "WINN3_RELAY_REPORT_MAX_AGE_SECONDS must be an integer from 5 to 300."
    return 1
  }
}

require_supported_production_os() {
  local os_id="" os_version=""
  if [[ -r /etc/os-release ]]; then
    # shellcheck disable=SC1091
    . /etc/os-release
    os_id="${ID:-}"
    os_version="${VERSION_ID:-}"
  fi
  if [[ "${ALLOW_UNSUPPORTED_OS:-0}" == "1" ]]; then
    return 0
  fi
  if [[ "${os_id}" == "ubuntu" && "${os_version}" == "24.04" ]]; then
    return 0
  fi
  if [[ "${os_id}" == "ubuntu" && "${os_version}" == "26.04" ]]; then
    err "Ubuntu 26.04 is not a supported production host. The control-plane pip-compile lock was generated with Python 3.12 and pins C-extension per-CPython wheels; 26.04's default python3 is not that interpreter. Supported production host remains Ubuntu 24.04. Set ALLOW_UNSUPPORTED_OS=1 only for a disposable compatibility test."
    exit 1
  fi
  err "Supported production host is Ubuntu 24.04; detected ${os_id:-unknown} ${os_version:-unknown}. Set ALLOW_UNSUPPORTED_OS=1 only for a disposable compatibility test."
  exit 1
}

# `read-only` is --preflight: it changes nothing. A deploy passes no argument.
preflight_control() {
  local available_kb role_file="/etc/winsvpn/role" preflight_mode="${1:-deploy}"
  for command_name in apt-get systemctl ip df awk sed grep pgrep stat find base64 mktemp python3 ssh-keygen; do
    command -v "${command_name}" >/dev/null 2>&1 || {
      err "Required base command is missing: ${command_name}"
      exit 1
    }
  done
  [[ -x /usr/bin/python3 ]] || {
    err "Required fixed system interpreter /usr/bin/python3 is missing."
    exit 1
  }
  [[ -d /run/systemd/system ]] || { err "This script requires a systemd-based Ubuntu host."; exit 1; }
  require_supported_production_os
  if [[ -z "${IONOS_HUB_IP}" ]]; then
    IONOS_HUB_IP="$(detect_hub_ipv4 || true)"
  fi
  public_ipv4 "${IONOS_HUB_IP}" || {
    err "IONOS_HUB_IP/WINS_HUB_IP must be the control hub's public IPv4 address."
    exit 1
  }
  [[ "${HUB_DOMAIN}" =~ ^[A-Za-z0-9.-]+$ && "${HUB_DOMAIN}" == *.* ]] || {
    err "HUB_DOMAIN is not a valid hostname: ${HUB_DOMAIN}"
    exit 1
  }
  if ! [[ "${DEFAULT_NODE_MAX_PEERS_DEFAULT}" =~ ^[0-9]+$ ]] \
      || ! ((DEFAULT_NODE_MAX_PEERS_DEFAULT >= 1 && DEFAULT_NODE_MAX_PEERS_DEFAULT <= 60000)); then
      err "DEFAULT_NODE_MAX_PEERS must be an integer from 1 to 60000."
      exit 1
  fi
  if ! [[ "${NODE_RUNTIME_PEER_RESERVE_DEFAULT}" =~ ^[0-9]+$ ]] \
      || ! ((NODE_RUNTIME_PEER_RESERVE_DEFAULT >= 1 && NODE_RUNTIME_PEER_RESERVE_DEFAULT <= 64)); then
      err "NODE_RUNTIME_PEER_RESERVE must be an integer from 1 to 64."
      exit 1
  fi
  validate_double_vpn_ready_timeout || exit 1
  validate_winn3_relay_settings || exit 1
  validate_zram_policy_settings || exit 1
  available_kb="$(df -Pk / | awk 'NR==2 {print $4}')"
  [[ "${available_kb}" =~ ^[0-9]+$ && "${available_kb}" -ge 4194304 ]] || {
    err "At least 4 GiB of free root-disk space is required before deployment."
    exit 1
  }
  if [[ -s "${role_file}" && "$(tr -d '[:space:]' < "${role_file}")" != "control" ]]; then
    err "This host is already marked for a different Win's VPN role: $(cat "${role_file}")"
    exit 1
  fi
  validate_external_secret_contract
  verify_preflight_external_credentials
  validate_hub_ssh_access_contract
  refuse_hub_keys_authorized_for_root_here || exit 1
  if [[ "${preflight_mode}" == "read-only" ]]; then
    refuse_hub_abstract_brokers preflight || exit 1
  else
    # Deploy: every read-only check above has passed (role, OS, secrets),
    # so the stock storage units are masked here, then the gate is strict.
    hub_mask_stock_abstract_services || exit 1
    refuse_hub_abstract_brokers || exit 1
  fi
  validate_winn3_standalone_install_settings || exit 1
  log "Preflight passed: role=control public_ip=${IONOS_HUB_IP} free_kb=${available_kb}"
}

validate_hub_ssh_public_key() {
  local key="${1:-}" staging=""
  [[ -n "${key}" && "${key}" != *$'\n'* && "${key}" != *$'\r'* ]] || return 1
  staging="$(mktemp)"
  chmod 600 "${staging}"
  printf '%s\n' "${key}" > "${staging}"
  if ! ssh-keygen -l -f "${staging}" >/dev/null 2>&1; then
    rm -f "${staging}"
    return 1
  fi
  rm -f "${staging}"
}

host_has_authorized_ssh_key() {
  find /root/.ssh /home -maxdepth 3 -type f -name authorized_keys -size +0c \
    -exec grep -IlE '^(ssh-|ecdsa-|sk-)' {} + 2>/dev/null | grep . >/dev/null
}

validate_hub_ssh_access_contract() {
  local password_auth="${HUB_SSH_PASSWORD_AUTH:-$HUB_SSH_PASSWORD_AUTH_DEFAULT}"
  local injected_key="${HUB_SSH_PUBLIC_KEY:-$HUB_SSH_PUBLIC_KEY_DEFAULT}"
  if [[ "${password_auth}" == "0" || "${password_auth,,}" == "false" || "${password_auth,,}" == "no" ]]; then
    if [[ -n "${injected_key}" ]]; then
      validate_hub_ssh_public_key "${injected_key}" || {
        err "HUB_SSH_PUBLIC_KEY is not a valid single-line OpenSSH public key."
        return 1
      }
    elif ! host_has_authorized_ssh_key; then
      err "Password SSH is disabled but no authorized key exists. Preinstall an authorized_keys file or set HUB_SSH_PUBLIC_KEY before deployment."
      return 1
    fi
  else
    # M-21: recovery password auth is never global and never for root -- it
    # requires a named non-root account, a source CIDR to restrict it to, and
    # an operator-supplied password for that account (via root-owned
    # WINS_SECRETS_FILE, never a bare CLI arg/env var an operator has to type
    # where a shell history or process listing could capture it). Fail closed
    # rather than silently falling back to a weaker or wide-open recovery
    # posture.
    local recovery_cidr="${HUB_SSH_RECOVERY_CIDR:-$HUB_SSH_RECOVERY_CIDR_DEFAULT}"
    local recovery_account="${HUB_SSH_RECOVERY_ACCOUNT:-$HUB_SSH_RECOVERY_ACCOUNT_DEFAULT}"
    local recovery_minutes="${HUB_SSH_RECOVERY_MINUTES:-$HUB_SSH_RECOVERY_MINUTES_DEFAULT}"
    : "${HUB_SSH_RECOVERY_CIDR:?HUB_SSH_RECOVERY_CIDR is required when HUB_SSH_PASSWORD_AUTH is enabled}"
    : "${HUB_SSH_RECOVERY_PASSWORD:?HUB_SSH_RECOVERY_PASSWORD is required when HUB_SSH_PASSWORD_AUTH is enabled (inject it through root-owned ${WINS_SECRETS_FILE})}"
    valid_ipv4_cidr "${recovery_cidr}" || {
      err "HUB_SSH_RECOVERY_CIDR must be an IPv4 CIDR such as 203.0.113.4/32."
      return 1
    }
    valid_unix_username "${recovery_account}" || {
      err "HUB_SSH_RECOVERY_ACCOUNT must be a valid, non-root Unix username."
      return 1
    }
    [[ "${recovery_account}" != "root" ]] || {
      err "HUB_SSH_RECOVERY_ACCOUNT must not be root; recovery password auth never applies to root."
      return 1
    }
    [[ "${recovery_minutes}" =~ ^[0-9]+$ ]] && ((recovery_minutes >= 1 && recovery_minutes <= 1440)) || {
      err "HUB_SSH_RECOVERY_MINUTES must be an integer from 1 to 1440."
      return 1
    }
    (( ${#HUB_SSH_RECOVERY_PASSWORD} >= 16 )) || {
      err "HUB_SSH_RECOVERY_PASSWORD must be at least 16 characters."
      return 1
    }
  fi
}

install_hub_ssh_public_key() {
  local injected_key="${HUB_SSH_PUBLIC_KEY:-$HUB_SSH_PUBLIC_KEY_DEFAULT}"
  [[ -n "${injected_key}" ]] || return 0
  validate_hub_ssh_public_key "${injected_key}"
  install -d -m 700 /root/.ssh
  touch /root/.ssh/authorized_keys
  chmod 600 /root/.ssh/authorized_keys
  grep -qxF "${injected_key}" /root/.ssh/authorized_keys || printf '%s\n' "${injected_key}" >> /root/.ssh/authorized_keys
}

mark_control_role() {
  install -d -m 700 /etc/winsvpn
  printf 'control\n' > /etc/winsvpn/role
  chmod 400 /etc/winsvpn/role
}

validate_backup_retention_contract() {
  # F-8 fail-closed validation. A retention window that is unset, non-numeric,
  # zero, or above the published ceiling must abort the deploy: publishing a
  # 30-day claim while the pruner is misconfigured is worse than not deploying,
  # because the claim is what users rely on.
  local days ceiling manifest_days dry_run required
  days="${BACKUP_RETENTION_DAYS:-$BACKUP_RETENTION_DAYS_DEFAULT}"
  ceiling="${BACKUP_RETENTION_CEILING_DAYS:-$BACKUP_RETENTION_CEILING_DAYS_DEFAULT}"
  manifest_days="${BACKUP_MANIFEST_RETENTION_DAYS:-$BACKUP_MANIFEST_RETENTION_DAYS_DEFAULT}"
  dry_run="${BACKUP_PRUNE_DRY_RUN:-$BACKUP_PRUNE_DRY_RUN_DEFAULT}"
  required="${REQUIRE_BACKUP_PRUNING:-$REQUIRE_BACKUP_PRUNING_DEFAULT}"

  [[ "${days}" =~ ^[0-9]+$ ]] || {
    err "BACKUP_RETENTION_DAYS must be a whole number of days, got '${days}'."
    return 1
  }
  [[ "${ceiling}" =~ ^[0-9]+$ ]] || {
    err "BACKUP_RETENTION_CEILING_DAYS must be a whole number of days, got '${ceiling}'."
    return 1
  }
  [[ "${manifest_days}" =~ ^[0-9]+$ ]] || {
    err "BACKUP_MANIFEST_RETENTION_DAYS must be a whole number of days, got '${manifest_days}'."
    return 1
  }
  (( days >= 1 )) || {
    err "BACKUP_RETENTION_DAYS must be at least 1; a zero window would delete the backup that was just taken."
    return 1
  }
  (( days <= ceiling )) || {
    err "BACKUP_RETENTION_DAYS=${days} exceeds the published ${ceiling}-day ceiling for full sensitive backups."
    err "The privacy policy's retention claim is the constraint here, not disk space. Lower it."
    return 1
  }
  # The manifest window may be longer ONLY because manifests are sanitised.
  # Nothing in that path may carry accounts, device metadata or secrets.
  (( manifest_days >= days )) || {
    err "BACKUP_MANIFEST_RETENTION_DAYS=${manifest_days} is shorter than the sensitive window (${days}); that is almost certainly a mistake."
    return 1
  }
  [[ "${dry_run}" =~ ^[01]$ ]] || {
    err "BACKUP_PRUNE_DRY_RUN must be 0 or 1, got '${dry_run}'."
    return 1
  }
  [[ "${required}" =~ ^[01]$ ]] || {
    err "REQUIRE_BACKUP_PRUNING must be 0 or 1, got '${required}'."
    return 1
  }
  if [[ "${dry_run}" == "1" && "${required}" == "1" ]]; then
    warn "BACKUP_PRUNE_DRY_RUN=1: the pruner will REPORT what it would remove and remove NOTHING."
    warn "This hub does not enforce its ${days}-day retention window while that is set."
  fi
  log "Backup retention: ${days}d sensitive (ceiling ${ceiling}d), ${manifest_days}d sanitised manifests, dry-run=${dry_run}"
  return 0
}

backup_encryption_owner_instructions() {
  # Deliberately generates nothing. The identity halves are the only thing that
  # can ever read a hub backup; minting them here would put them on the host
  # they exist to survive, which is the whole point of recipient-only material.
  local recipients_file="$1"
  err "OWNER ACTION -- run this OFF this host, on a machine that never terminates client traffic:"
  err "  1. age-keygen -o backup-identity-1.age   (repeat for backup-identity-2.age)"
  err "  2. Escrow BOTH identity files offline, in two separate physical locations."
  err "     They are the ONLY way to read a hub backup. This host must never hold them."
  err "  3. Copy just the 'age1...' public recipient line out of each identity file"
  err "     into one text file, one recipient per line."
  err "  4. Deliver that file to this host and install it root-owned mode 600:"
  err "       install -o root -g root -m 600 recipients.txt ${recipients_file}"
  err "Alternatively set REQUIRE_BACKUP_ENCRYPTION=0 in ${WINS_SECRETS_FILE} to accept that"
  err "hub backups are protected only by the rclone crypt remote's single host-held"
  err "credential, and that the local fallback copy is written in plaintext."
}

validate_backup_encryption_contract() {
  # F-8 fail-closed validation, moved to PREFLIGHT. Before this existed the
  # requirement was unsatisfiable: BACKUP_AGE_RECIPIENTS_FILE was never assigned
  # anywhere, REQUIRE_BACKUP_ENCRYPTION defaults to 1, and the generated backup
  # script exit 1'd -- which surfaced only at run_initial_backup, after every
  # host mutation and immediately before public cutover.
  local required recipients_file line recipients=0 owner mode
  required="${REQUIRE_BACKUP_ENCRYPTION:-$REQUIRE_BACKUP_ENCRYPTION_DEFAULT}"
  recipients_file="${BACKUP_AGE_RECIPIENTS_FILE:-$BACKUP_AGE_RECIPIENTS_FILE_DEFAULT}"

  [[ "${required}" =~ ^[01]$ ]] || {
    err "REQUIRE_BACKUP_ENCRYPTION must be 0 or 1, got '${required}'."
    return 1
  }
  if [[ "${required}" != "1" ]]; then
    warn "REQUIRE_BACKUP_ENCRYPTION=0: hub backups carry the full account database and every"
    warn "hub secret protected ONLY by the rclone crypt remote, whose password sits on this host."
    warn "The local fallback copy under /var/backups/winsvpn is then written in PLAINTEXT."
    return 0
  fi

  [[ -n "${recipients_file}" && "${recipients_file}" == /* ]] || {
    err "BACKUP_AGE_RECIPIENTS_FILE must be an absolute path, got '${recipients_file}'."
    return 1
  }
  if [[ ! -e "${recipients_file}" ]]; then
    err "Hub backups must be independently encrypted, but no age recipients file exists at ${recipients_file}."
    backup_encryption_owner_instructions "${recipients_file}"
    return 1
  fi
  [[ -f "${recipients_file}" && ! -L "${recipients_file}" ]] || {
    err "BACKUP_AGE_RECIPIENTS_FILE must be a regular non-symlink file: ${recipients_file}"
    return 1
  }
  owner="$(stat -c '%u' "${recipients_file}" 2>/dev/null || printf 'unknown')"
  [[ "${owner}" == "0" ]] || {
    err "BACKUP_AGE_RECIPIENTS_FILE must be owned by root: ${recipients_file}"
    return 1
  }
  # Read is not the risk -- these are public keys. WRITE is: anyone who can
  # append a recipient can read every future backup.
  local perm_hits perm_rc=0
  perm_hits="$(find "${recipients_file}" -prune -perm /022 -print -quit)" || perm_rc=$?
  (( perm_rc == 0 )) || {
    err "Could not inspect the permissions of BACKUP_AGE_RECIPIENTS_FILE (find failed, exit ${perm_rc}): ${recipients_file}"
    return 1
  }
  [[ -z "${perm_hits}" ]] || {
    err "BACKUP_AGE_RECIPIENTS_FILE must not be writable by group or other (use chmod 600): ${recipients_file}"
    err "A writable recipients file lets anyone with local access add their own key to every future backup."
    return 1
  }
  [[ -r "${recipients_file}" ]] || {
    err "BACKUP_AGE_RECIPIENTS_FILE is not readable: ${recipients_file}"
    return 1
  }
  mode="$(stat -c '%a' "${recipients_file}" 2>/dev/null || printf '?')"

  while IFS= read -r line || [[ -n "${line}" ]]; do
    line="${line%$'\r'}"
    line="${line#"${line%%[![:space:]]*}"}"
    line="${line%"${line##*[![:space:]]}"}"
    [[ -z "${line}" || "${line}" == '#'* ]] && continue
    case "${line}" in
      AGE-SECRET-KEY-*|*'BEGIN OPENSSH PRIVATE KEY'*|*'BEGIN '*'PRIVATE KEY'*)
        err "BACKUP_AGE_RECIPIENTS_FILE contains a PRIVATE identity, not a recipient: ${recipients_file}"
        err "A private key here defeats the entire control -- a host that can decrypt its own"
        err "backups gives an adversary who takes the host every backup it ever made."
        err "Keep only the 'age1...' public recipient lines; escrow the identity files off this host."
        return 1
        ;;
    esac
    if [[ "${line}" =~ ^age1[0-9a-z]{10,}$ ]] \
        || [[ "${line}" =~ ^(ssh-ed25519|ssh-rsa)[[:space:]]+[A-Za-z0-9+/=]+([[:space:]].*)?$ ]]; then
      recipients=$(( recipients + 1 ))
      continue
    fi
    err "BACKUP_AGE_RECIPIENTS_FILE has a line that is not an age or SSH recipient: ${recipients_file}"
    err "Every non-comment line must be an 'age1...' recipient or an 'ssh-ed25519'/'ssh-rsa' public key."
    return 1
  done < "${recipients_file}"

  (( recipients >= 1 )) || {
    err "BACKUP_AGE_RECIPIENTS_FILE contains no recipients (empty, or comments only): ${recipients_file}"
    backup_encryption_owner_instructions "${recipients_file}"
    return 1
  }
  if (( recipients == 1 )); then
    warn "Only one age recipient is configured. Losing that single escrowed identity makes every"
    warn "hub backup permanently unreadable; two independently escrowed recipients are recommended."
  fi
  log "Backup encryption: ${recipients} age recipient(s) at ${recipients_file} (mode ${mode}), REQUIRE_BACKUP_ENCRYPTION=1"
  return 0
}

backup_encryption_live_check() {
  # Deploy-time only. Preflight cannot run this because `age` is installed by
  # apt_install, which runs after preflight. Structure is not validity: a
  # mistyped recipient passes the preflight regex and would fail only when the
  # first backup tried to encrypt with it. Prove `age` accepts every recipient
  # here, in configure_rclone_credentials, while a failure still costs nothing.
  local required recipients_file staging
  required="${REQUIRE_BACKUP_ENCRYPTION:-$REQUIRE_BACKUP_ENCRYPTION_DEFAULT}"
  [[ "${required}" == "1" ]] || return 0
  recipients_file="${BACKUP_AGE_RECIPIENTS_FILE:-$BACKUP_AGE_RECIPIENTS_FILE_DEFAULT}"
  command -v age >/dev/null 2>&1 || {
    err "REQUIRE_BACKUP_ENCRYPTION=1 but the age binary is not installed; hub backups could not be encrypted."
    return 1
  }
  staging="$(mktemp)"
  chmod 600 "${staging}"
  if ! printf 'wins-hub-backup-encryption-probe' | age -R "${recipients_file}" -o "${staging}" 2>/dev/null \
      || [[ ! -s "${staging}" ]]; then
    rm -f "${staging}"
    err "age refused the recipients in ${recipients_file}; the nightly backup would fail the same way."
    err "Verify by hand off the deploy path: printf x | age -R ${recipients_file} -o /dev/null"
    return 1
  fi
  rm -f "${staging}"
  log "Verified age accepts every recipient in ${recipients_file}"
  return 0
}

resolve_backup_host_id() {
  # Sets RESOLVED_BACKUP_HOST_ID. Mutating (it may mint and persist an id), so
  # it is called only from the deploy path, never from preflight.
  local explicit="${BACKUP_HOST_ID:-$BACKUP_HOST_ID_DEFAULT}"
  local id_file="${BACKUP_HOST_ID_FILE:-$BACKUP_HOST_ID_FILE_DEFAULT}"
  local short_host stored minted
  RESOLVED_BACKUP_HOST_ID=""
  if [[ -n "${explicit}" ]]; then
    [[ "${explicit}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ ]] || {
      err "BACKUP_HOST_ID must be 1-64 characters of letters, digits, dot, underscore or dash: '${explicit}'"
      return 1
    }
    RESOLVED_BACKUP_HOST_ID="${explicit}"
    return 0
  fi
  install -d -m 700 /etc/winsvpn
  if [[ -e "${id_file}" || -L "${id_file}" ]]; then
    [[ -f "${id_file}" && ! -L "${id_file}" ]] || {
      err "${id_file} must be a regular non-symlink file."
      return 1
    }
    stored="$(tr -d '[:space:]' < "${id_file}")"
    [[ "${stored}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ ]] || {
      err "${id_file} does not hold a valid backup host identity."
      err "Refusing to silently change the backup destination prefix: existing archives would stop being pruned."
      return 1
    }
    RESOLVED_BACKUP_HOST_ID="${stored}"
    return 0
  fi
  short_host="$(hostname -s 2>/dev/null || printf 'hub')"
  short_host="${short_host//[^A-Za-z0-9._-]/}"
  [[ -n "${short_host}" ]] || short_host="hub"
  minted="$(tr -d '-' < /proc/sys/kernel/random/uuid | cut -c1-12)"
  [[ "${minted}" =~ ^[0-9a-f]{12}$ ]] || {
    err "Could not mint a unique backup host identity."
    return 1
  }
  minted="${short_host:0:40}-${minted}"
  printf '%s\n' "${minted}" > "${id_file}"
  chown root:root "${id_file}"
  chmod 600 "${id_file}"
  log "Minted backup host identity ${minted} (pinned in ${id_file}; hostname -s alone is not unique in this fleet)"
  RESOLVED_BACKUP_HOST_ID="${minted}"
  return 0
}

rclone_crypt_remote_contract() {
  local config_file="$1" remote="$2" key value
  local type="" wrapped_remote="" password="" password2=""
  local filename_encryption="" directory_name_encryption="" no_data_encryption=""
  local parsed parse_rc=0

  # LSR R7 (Sol N-23): the parser's own status is checked before any of its
  # output is read; rows printed by a parser that then failed are not a
  # contract (later disabling settings could be in the part it never read).
  parsed="$(awk -v expected="[${remote}]" '
    { sub(/\r$/, "") }
    /^\[/ { active = ($0 == expected); next }
    active && /^[[:space:]]*[A-Za-z0-9_]+[[:space:]]*=/ {
      key=$0; sub(/[[:space:]]*=.*/, "", key); gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
      value=$0; sub(/^[^=]*=[[:space:]]*/, "", value); gsub(/[[:space:]]+$/, "", value)
      print key "\t" value
    }
  ' "${config_file}")" || parse_rc=$?
  (( parse_rc == 0 )) || {
    err "Could not parse the rclone configuration ${config_file} (awk exit ${parse_rc}); refusing to treat ${remote}: as a verified crypt remote."
    return 1
  }
  while IFS=$'\t' read -r key value; do
    case "${key,,}" in
      type) type="${value,,}" ;;
      remote) wrapped_remote="${value}" ;;
      password) password="${value}" ;;
      password2) password2="${value}" ;;
      filename_encryption) filename_encryption="${value,,}" ;;
      directory_name_encryption) directory_name_encryption="${value,,}" ;;
      no_data_encryption) no_data_encryption="${value,,}" ;;
    esac
  done <<<"${parsed}"

  [[ "${type}" == "crypt" ]] || {
    err "Required rclone remote ${remote}: must be a client-side encrypted crypt remote."
    return 1
  }
  [[ "${wrapped_remote}" == *:* && -n "${password}" && -n "${password2}" ]] || {
    err "Encrypted rclone remote ${remote}: must define a wrapped remote, password, and independent password2 salt."
    return 1
  }
  [[ -z "${filename_encryption}" || "${filename_encryption}" == "standard" ]] || {
    err "Encrypted rclone remote ${remote}: must use standard filename encryption."
    return 1
  }
  [[ -z "${directory_name_encryption}" || "${directory_name_encryption}" == "true" ]] || {
    err "Encrypted rclone remote ${remote}: must encrypt directory names."
    return 1
  }
  [[ -z "${no_data_encryption}" || "${no_data_encryption}" == "false" ]] || {
    err "Encrypted rclone remote ${remote}: must not disable data encryption."
    return 1
  }
}

validate_rclone_injection_contract() {
  local required="${REQUIRE_REMOTE_BACKUP:-$REQUIRE_REMOTE_BACKUP_DEFAULT}"
  local remote="${RCLONE_REMOTE:-$RCLONE_REMOTE_DEFAULT}"
  local source_file="${RCLONE_CONFIG_SOURCE:-}" encoded="${RCLONE_CONFIG_B64:-}" staging=""
  [[ "${remote}" =~ ^[A-Za-z0-9._-]+$ ]] || {
    err "RCLONE_REMOTE must contain only letters, digits, dot, underscore, or dash."
    return 1
  }
  if [[ -n "${source_file}" && -n "${encoded}" ]]; then
    err "Set only one of RCLONE_CONFIG_SOURCE or RCLONE_CONFIG_B64."
    return 1
  fi
  if [[ -z "${source_file}" && -z "${encoded}" ]]; then
    if [[ "${required}" == "1" ]]; then
      err "Remote backup is required. Inject RCLONE_CONFIG_SOURCE or RCLONE_CONFIG_B64 through ${WINS_SECRETS_FILE}."
      return 1
    fi
    return 0
  fi
  if [[ -n "${source_file}" ]]; then
    [[ -f "${source_file}" && -s "${source_file}" ]] || {
      err "RCLONE_CONFIG_SOURCE must name a non-empty regular file: ${source_file}"
      return 1
    }
    [[ "$(stat -c '%u' "${source_file}")" == "0" ]] || {
      err "RCLONE_CONFIG_SOURCE must be owned by root: ${source_file}"
      return 1
    }
    local perm_hits perm_rc=0
    perm_hits="$(find "${source_file}" -prune -perm /077 -print -quit)" || perm_rc=$?
    (( perm_rc == 0 )) || {
      err "Could not inspect the permissions of RCLONE_CONFIG_SOURCE (find failed, exit ${perm_rc}): ${source_file}"
      return 1
    }
    [[ -z "${perm_hits}" ]] || {
      err "RCLONE_CONFIG_SOURCE must not be accessible by group/other (use chmod 600): ${source_file}"
      return 1
    }
    awk -v expected="[${remote}]" '{ sub(/\r$/, ""); if ($0 == expected) found=1 } END { exit found ? 0 : 1 }' "${source_file}" || {
      err "RCLONE_CONFIG_SOURCE does not define the required [${remote}] remote."
      return 1
    }
    rclone_crypt_remote_contract "${source_file}" "${remote}" || return 1
    return 0
  fi
  ((${#encoded} <= 2097152)) || {
    err "RCLONE_CONFIG_B64 exceeds the 2 MiB preflight limit."
    return 1
  }
  staging="$(mktemp)"
  if ! printf '%s' "${encoded}" | base64 --decode > "${staging}" 2>/dev/null || [[ ! -s "${staging}" ]]; then
    rm -f "${staging}"
    err "RCLONE_CONFIG_B64 is not valid non-empty base64."
    return 1
  fi
  if ! awk -v expected="[${remote}]" '{ sub(/\r$/, ""); if ($0 == expected) found=1 } END { exit found ? 0 : 1 }' "${staging}"; then
    rm -f "${staging}"
    err "RCLONE_CONFIG_B64 does not define the required [${remote}] remote."
    return 1
  fi
  if ! rclone_crypt_remote_contract "${staging}" "${remote}"; then
    rm -f "${staging}"
    return 1
  fi
  rm -f "${staging}"
}

configure_rclone_credentials() {
  local config_dir="/root/.config/rclone" config_file="/root/.config/rclone/rclone.conf"
  local staging="" remote="${RCLONE_REMOTE:-$RCLONE_REMOTE_DEFAULT}" attempt
  [[ "${remote}" =~ ^[A-Za-z0-9._-]+$ ]] || {
    err "RCLONE_REMOTE must contain only letters, digits, dot, underscore, or dash."
    return 1
  }
  install -d -m 700 "${config_dir}" /etc/winsvpn
  if [[ -n "${RCLONE_CONFIG_B64:-}" ]]; then
    staging="$(mktemp)"
    if ! printf '%s' "${RCLONE_CONFIG_B64}" | base64 --decode > "${staging}"; then
      rm -f "${staging}"
      err "RCLONE_CONFIG_B64 is not valid base64."
      return 1
    fi
    install -m 600 "${staging}" "${config_file}"
    rm -f "${staging}"
  elif [[ -n "${RCLONE_CONFIG_SOURCE:-}" ]]; then
    [[ -f "${RCLONE_CONFIG_SOURCE}" ]] || {
      err "RCLONE_CONFIG_SOURCE does not exist: ${RCLONE_CONFIG_SOURCE}"
      return 1
    }
    install -m 600 "${RCLONE_CONFIG_SOURCE}" "${config_file}"
  fi
  validate_backup_retention_contract || return 1
  # The generated backup and prune scripts read /etc/winsvpn/backup.env and
  # nothing else -- the units carry no Environment= or EnvironmentFile= -- and
  # this function OVERWRITES that file, so anything the backup chain needs has
  # to be emitted here. Before the encryption keys were added below,
  # BACKUP_AGE_RECIPIENTS_FILE had no producer anywhere in this installer and
  # pre-seeding backup.env could not survive this write.
  validate_backup_encryption_contract || return 1
  backup_encryption_live_check || return 1
  resolve_backup_host_id || return 1
  # IA-CP-14: the pruner's stage 2 (Litestream recovery history) reads
  # WINS_LITESTREAM_REPLICA_DIR and nothing produced it, so that stage never
  # ran. Emit the local replica directory when the replica URL is a local
  # path; a remote replica (sftp://) leaves it empty, and the pruner then
  # reports the stage as not configured, as before.
  local litestream_replica_url litestream_replica_dir=""
  litestream_replica_url="${LITESTREAM_REPLICA_URL:-$LITESTREAM_REPLICA_URL_DEFAULT}"
  if [[ "${litestream_replica_url}" == /* || "${litestream_replica_url}" == file://* ]]; then
    litestream_replica_dir="${litestream_replica_url#file://}"
    [[ "${litestream_replica_dir}" =~ ^/[A-Za-z0-9._/-]+$ && "${litestream_replica_dir}" != *..* \
        && "${litestream_replica_dir}" != "/" ]] || {
      err "LITESTREAM_REPLICA_URL local path must be an absolute path of letters, digits, dot, underscore, dash and slash: ${litestream_replica_dir}"
      return 1
    }
  fi
  printf 'RCLONE_REMOTE=%s\nREQUIRE_REMOTE_BACKUP=%s\nBACKUP_RETENTION_DAYS=%s\nBACKUP_MANIFEST_RETENTION_DAYS=%s\nBACKUP_PRUNE_DRY_RUN=%s\nREQUIRE_BACKUP_PRUNING=%s\nBACKUP_AGE_RECIPIENTS_FILE=%s\nREQUIRE_BACKUP_ENCRYPTION=%s\nBACKUP_HOST_ID=%s\nWINS_LITESTREAM_REPLICA_DIR=%s\n' \
    "${remote}" "${REQUIRE_REMOTE_BACKUP:-$REQUIRE_REMOTE_BACKUP_DEFAULT}" \
    "${BACKUP_RETENTION_DAYS:-$BACKUP_RETENTION_DAYS_DEFAULT}" \
    "${BACKUP_MANIFEST_RETENTION_DAYS:-$BACKUP_MANIFEST_RETENTION_DAYS_DEFAULT}" \
    "${BACKUP_PRUNE_DRY_RUN:-$BACKUP_PRUNE_DRY_RUN_DEFAULT}" \
    "${REQUIRE_BACKUP_PRUNING:-$REQUIRE_BACKUP_PRUNING_DEFAULT}" \
    "${BACKUP_AGE_RECIPIENTS_FILE:-$BACKUP_AGE_RECIPIENTS_FILE_DEFAULT}" \
    "${REQUIRE_BACKUP_ENCRYPTION:-$REQUIRE_BACKUP_ENCRYPTION_DEFAULT}" \
    "${RESOLVED_BACKUP_HOST_ID}" "${litestream_replica_dir}" > /etc/winsvpn/backup.env
  chmod 600 /etc/winsvpn/backup.env
  if [[ ! -s "${config_file}" ]]; then
    if [[ "${REQUIRE_REMOTE_BACKUP:-$REQUIRE_REMOTE_BACKUP_DEFAULT}" == "1" ]]; then
      err "Remote backup is required. Inject RCLONE_CONFIG_SOURCE or RCLONE_CONFIG_B64 through ${WINS_SECRETS_FILE}."
      return 1
    fi
    warn "Remote backup is disabled because no rclone configuration was injected."
    return 0
  fi
  chmod 600 "${config_file}"
  rclone listremotes | grep -Fx "${remote}:" >/dev/null || {
    err "rclone remote ${remote}: is missing from ${config_file}."
    return 1
  }
  rclone_crypt_remote_contract "${config_file}" "${remote}" || return 1
  for attempt in 1 2 3; do
    if rclone lsd --max-depth 1 "${remote}:" >/dev/null 2>&1; then
      log "Verified remote backup access through ${remote}:"
      return 0
    fi
    sleep $((attempt * 2))
  done
  # LSR (2026-10-02): an unreachable backup remote (for example a Google Drive
  # OAuth client that its provider disabled) must not stop the deploy here.
  # This runs before install_litestream, and the durability barrier depends
  # only on the Litestream replica, so failing here kept a broken replica from
  # ever being repaired. The configuration itself was validated above and stays
  # fatal. Each nightly run still fails visibly while the remote is down and
  # keeps its encrypted archive root-only on this host (wins-hub-backup).
  warn "Unable to access rclone remote ${remote}: after three attempts. Deploy continues: the durability barrier does not depend on the backup remote. Nightly backups will fail and keep their encrypted archive under /var/backups/winsvpn until ${remote}: is reachable again."
  return 0
}

# LSR (2026-10-02): the one place that names the Litestream SFTP client key,
# shared by the preflight contract, configure_litestream_replication and the
# YAML it writes. It is a dedicated key, never /root/.ssh/id_rsa (which holds
# root on every data plane).
litestream_sftp_key_path() {
  printf '%s\n' "${LITESTREAM_SFTP_KEY_PATH:-$LITESTREAM_SFTP_KEY_PATH_DEFAULT}"
}

# The client key is a secret; hold it to the same floor as the secrets file:
# a real regular non-empty file, root-owned, 0600 or stricter.
litestream_sftp_key_ok() {
  local key="$1"
  [[ "${key}" =~ ^/[A-Za-z0-9._/-]+$ && "/${key}/" != */../* ]] || {
    err "LITESTREAM_SFTP_KEY_PATH must be an absolute path of letters, digits, dot, underscore, dash and slash: ${key}"
    return 1
  }
  [[ -f "${key}" && ! -L "${key}" ]] || {
    err "Litestream SFTP client key must be a regular non-symlink file: ${key}"
    return 1
  }
  [[ "$(stat -c '%u' "${key}" 2>/dev/null || printf 'unknown')" == "0" ]] || {
    err "Litestream SFTP client key must be owned by root: ${key}"
    return 1
  }
  # LSR R6 (Sol N-19): find's own status first; a failed find is an
  # uninspected mode, never "no group or other bits".
  local perm_hits perm_rc=0
  perm_hits="$(find "${key}" -prune -perm /077 -print -quit)" || perm_rc=$?
  (( perm_rc == 0 )) || {
    err "Could not inspect the permissions of the Litestream SFTP client key (find failed, exit ${perm_rc}): ${key}"
    return 1
  }
  [[ -z "${perm_hits}" ]] || {
    err "Litestream SFTP client key must have mode 0600 or stricter: ${key}"
    return 1
  }
  [[ -s "${key}" && -r "${key}" ]] || {
    err "Litestream SFTP client key is empty or unreadable: ${key}"
    return 1
  }
}

# sftp://<user>@<host>[:<port>]/<absolute path>. No password (it would sit in
# the YAML and invite password authentication), no query, no "..", and no
# character Litestream's config loader would expand ($) or YAML would parse.
litestream_sftp_url_ok() {
  local url="$1" host port path
  [[ "${url}" =~ ^sftp://[a-z_][a-z0-9_-]{0,31}@([A-Za-z0-9][A-Za-z0-9.-]{0,252})(:([0-9]{1,5}))?(/[A-Za-z0-9._/-]+)$ ]] || {
    err "LITESTREAM_REPLICA_URL must be sftp://<user>@<host>[:<port>]/<absolute path> with no password, query or special characters: ${url}"
    return 1
  }
  host="${BASH_REMATCH[1]}"
  port="${BASH_REMATCH[3]:-22}"
  path="${BASH_REMATCH[4]}"
  [[ "${host}" != *. && "${host}" != *..* && "${host}" != *-.* && "${host}" != *.-* ]] || {
    err "LITESTREAM_REPLICA_URL host is malformed: ${host}"
    return 1
  }
  ((10#${port} >= 1 && 10#${port} <= 65535)) || {
    err "LITESTREAM_REPLICA_URL port is out of range: ${port}"
    return 1
  }
  case "${path}/" in
    */../*|*/./*|*//*)
      err "LITESTREAM_REPLICA_URL path must not contain '.', '..' or empty segments: ${path}"
      return 1
      ;;
  esac
  [[ "${path}" != "/" ]] || {
    err "LITESTREAM_REPLICA_URL path must name a directory below the receiver's root: ${path}"
    return 1
  }
}

# Prints "<host> <port>" of a URL that litestream_sftp_url_ok accepted.
litestream_sftp_url_host_port() {
  local url="$1"
  [[ "${url}" =~ ^sftp://[^@]+@([^:/]+)(:([0-9]+))?/ ]] || return 1
  printf '%s %s\n' "${BASH_REMATCH[1]}" "$((10#${BASH_REMATCH[3]:-22}))"
}

# One OpenSSH public key, "<type> <base64>", whose base64 decodes to a key of
# that same type. Used for the pinned receiver host key and for the tunnel key.
litestream_ssh_public_key_ok() {
  local value="$1" label="$2"
  [[ "${value}" =~ ^(ssh-ed25519|ecdsa-sha2-nistp256|ecdsa-sha2-nistp384|ecdsa-sha2-nistp521|ssh-rsa)\ ([A-Za-z0-9+/]+={0,2})$ ]] || {
    err "${label} must be one OpenSSH public key of the form '<type> <base64>' (ssh-ed25519, ecdsa-sha2-nistp256/384/521 or ssh-rsa), with no comment or options."
    return 1
  }
  python3 - "${BASH_REMATCH[1]}" "${BASH_REMATCH[2]}" <<'PY' || {
import base64
import sys

key_type, blob = sys.argv[1], sys.argv[2]
try:
    raw = base64.b64decode(blob, validate=True)
except Exception:
    raise SystemExit(1)
if len(raw) < 4:
    raise SystemExit(1)
length = int.from_bytes(raw[:4], "big")
if length <= 0 or 4 + length > len(raw) or raw[4:4 + length] != key_type.encode("ascii"):
    raise SystemExit(1)
if key_type == "ssh-ed25519" and len(raw) != 51:
    raise SystemExit(1)
PY
    err "${label} is not a well-formed ${BASH_REMATCH[1]} public key (its base64 does not decode to a key of that type)."
    return 1
  }
  # LSR R2 (Sol N-4): the type prefix alone is not a key. ssh-keygen parses the
  # whole key (for ECDSA the curve name and the point), so a blob that carries
  # only its type string is refused here, before any host mutation.
  local key_tmp
  key_tmp="$(mktemp)" || return 1
  printf '%s\n' "${value}" > "${key_tmp}" || { rm -f -- "${key_tmp}"; return 1; }
  if ! ssh-keygen -l -f "${key_tmp}" >/dev/null 2>&1; then
    rm -f -- "${key_tmp}"
    err "${label} is not a complete public key (ssh-keygen -l cannot parse it)."
    return 1
  fi
  rm -f -- "${key_tmp}"
}

# The pinned key must not be one of THIS host's own host keys: a replica that
# answers with the hub's own key is the hub itself, not another host.
litestream_sftp_host_key_not_local() {
  local value="$1" dir="${LITESTREAM_LOCAL_SSH_HOST_KEY_DIR:-/etc/ssh}" pub blob own pubs absent_rc=0
  blob="${value#* }"
  # LSR R6: the hub's own host keys are listed with find's status checked and
  # each one is read with awk's status checked; a directory or key that cannot
  # be read is never "no matching key". A confirmed-absent directory has none.
  control_path_absent "${dir}" || absent_rc=$?
  (( absent_rc == 0 )) && return 0
  (( absent_rc == 1 )) || return 1
  # LSR R7 (Sol N-21, Claude N-22): a symlinked key directory (-H) and a
  # symlinked .pub (-type l, then followed) are this hub's keys too. Only a
  # confirmed-dangling link holds no key; an unresolvable one fails.
  local link_rc
  pubs="$(find -H "${dir}" -maxdepth 1 -name 'ssh_host_*_key.pub' \( -type f -o -type l \))" || {
    err "Could not list this hub's host keys in ${dir}; cannot prove LITESTREAM_SFTP_HOST_KEY is not one of them."
    return 1
  }
  while IFS= read -r pub; do
    [[ -n "${pub}" ]] || continue
    if [[ -L "${pub}" && ! -e "${pub}" ]]; then
      link_rc=0
      python3 -c 'import os, sys
try:
    os.stat(sys.argv[1])
except FileNotFoundError:
    sys.exit(0)
except OSError as e:
    print(f"[ERR] cannot resolve {sys.argv[1]}: {e.strerror}", file=sys.stderr)
    sys.exit(2)
sys.exit(1)' "${pub}" || link_rc=$?
      (( link_rc == 0 )) && continue
      err "Could not resolve this hub's host key link ${pub}; cannot prove LITESTREAM_SFTP_HOST_KEY is not this host's own key."
      return 1
    fi
    [[ -f "${pub}" ]] || continue
    own="$(awk 'NR == 1 {print $2}' "${pub}")" || {
      err "Could not read this hub's host key ${pub}; cannot prove LITESTREAM_SFTP_HOST_KEY is not this host's own key."
      return 1
    }
    if [[ -n "${own}" && "${own}" == "${blob}" ]]; then
      err "LITESTREAM_SFTP_HOST_KEY is this hub's own host key (${pub}); the replica would be on this host, not off it."
      return 1
    fi
  done <<<"${pubs}"
  return 0
}

# LSR R6: 0 when PATH is confirmed absent (ENOENT from lstat), 1 when it
# exists, 2 (with a message) when it cannot be inspected. Never guesses.
control_path_absent() {
  python3 - "$1" <<'CONTROL_PATH_PY'
import os, sys
try:
    os.lstat(sys.argv[1])
except FileNotFoundError:
    sys.exit(0)
except OSError as e:
    print(f"[ERR] cannot inspect {sys.argv[1]}: {e.strerror}", file=sys.stderr)
    sys.exit(2)
sys.exit(1)
CONTROL_PATH_PY
}

# LSR R6: the entries of a secret directory, for the permission floor. A
# confirmed-absent directory has none; a directory that cannot be inspected or
# listed fails, so its secrets are never silently left out of the floor.
secret_dir_entries() {
  local dir="$1" out absent_rc=0
  shift
  control_path_absent "${dir}" || absent_rc=$?
  (( absent_rc == 0 )) && return 0
  (( absent_rc == 1 )) || return 1
  # LSR R7 (Sol N-22): -H, so a directory linked into the partial vault is
  # listed through the link and every file in it is checked one by one.
  out="$(find -H "${dir}" -maxdepth 1 "$@")" || {
    err "Could not list ${dir} (find failed); its secrets cannot be checked."
    return 1
  }
  [[ -z "${out}" ]] || printf '%s\n' "${out}"
}

# The whole replica target, judged before any host mutation and again as a
# backstop in configure_litestream_replication. Prints the reason and returns 1
# for anything that is not an sftp:// replica with a pinned host key.
litestream_replica_target_ok() {
  local url="$1" host_key key tunnel_key host port
  case "${url}" in
    sftp://*) ;;
    gs://*)
      err "LITESTREAM_REPLICA_URL is a gs:// replica. Google Cloud Storage was retired as the Litestream target on 2026-10-02 (the Google Cloud project it needed was disabled); use an sftp:// replica on an owner-controlled host."
      return 1
      ;;
    /*|file://*)
      err "LITESTREAM_REPLICA_URL '${url}' is a path on this host. A replica on the hub's own disk does not take a write off the host, so the barrier would acknowledge writes that one disk failure loses; use an sftp:// replica on another host."
      return 1
      ;;
    *)
      err "LITESTREAM_REPLICA_URL '${url}' uses a scheme the durability barrier does not accept; only sftp:// with a pinned LITESTREAM_SFTP_HOST_KEY is supported."
      return 1
      ;;
  esac
  litestream_sftp_url_ok "${url}" || return 1
  host_key="${LITESTREAM_SFTP_HOST_KEY:-$LITESTREAM_SFTP_HOST_KEY_DEFAULT}"
  [[ -n "${host_key}" ]] || {
    err "LITESTREAM_SFTP_HOST_KEY is required for an sftp:// replica. Without it Litestream accepts any server key, so anything on the path could accept the replica and acknowledge the barrier. Pin the receiver's sshd host key, read from the receiver itself."
    return 1
  }
  litestream_ssh_public_key_ok "${host_key}" LITESTREAM_SFTP_HOST_KEY || return 1
  litestream_sftp_host_key_not_local "${host_key}" || return 1
  # Litestream 0.5.15's SSH client (golang.org/x/crypto v0.52.0) pins with
  # FixedHostKey but does not narrow the negotiated host-key algorithms to the
  # pinned type, and x/crypto prefers ECDSA, then RSA, then Ed25519. So the
  # pin must be of the type the receiver negotiates: ECDSA whenever the
  # receiver offers an ECDSA host key (stock Ubuntu does; measured, lane LSR
  # round trip: an Ed25519 pin failed with "ssh: host key mismatch", an
  # ECDSA pin replicated). A receiver offering only Ed25519 would negotiate
  # Ed25519 (source-based, not measured). Hence a warning, not a refusal.
  if [[ "${host_key%% *}" != "ecdsa-sha2-nistp256" ]]; then
    warn "LITESTREAM_SFTP_HOST_KEY is ${host_key%% *}. Litestream's SSH client prefers ECDSA, then RSA, then Ed25519 host keys and does not narrow that to the pinned type, so this pin matches only if the receiver offers no ECDSA host key (and, for ssh-ed25519, no RSA host key either); otherwise every barrier fails with a host key mismatch. When the receiver offers ECDSA, as stock Ubuntu does, pin its ecdsa-sha2-nistp256 host key."
  fi
  key="$(litestream_sftp_key_path)"
  if [[ -e "${key}" || -L "${key}" ]]; then
    litestream_sftp_key_ok "${key}" || return 1
  else
    [[ "${key}" =~ ^/[A-Za-z0-9._/-]+$ && "/${key}/" != */../* ]] || {
      err "LITESTREAM_SFTP_KEY_PATH must be an absolute path of letters, digits, dot, underscore, dash and slash: ${key}"
      return 1
    }
    warn "Litestream SFTP client key ${key} does not exist yet; the deploy generates it, and the receiver must authorise its public key before the postflight barrier can pass."
  fi
  tunnel_key="${LITESTREAM_SFTP_TUNNEL_PUBLIC_KEY:-$LITESTREAM_SFTP_TUNNEL_PUBLIC_KEY_DEFAULT}"
  if [[ -n "${tunnel_key}" ]]; then
    litestream_ssh_public_key_ok "${tunnel_key}" LITESTREAM_SFTP_TUNNEL_PUBLIC_KEY || return 1
    read -r host port < <(litestream_sftp_url_host_port "${url}") || return 1
    [[ "${host}" == "127.0.0.1" ]] || {
      err "LITESTREAM_SFTP_TUNNEL_PUBLIC_KEY authorises a reverse forward to a loopback port on this hub, so LITESTREAM_REPLICA_URL must name host 127.0.0.1 (got ${host})."
      return 1
    }
    ((port >= 1024)) || {
      err "The reverse-forward listen port must be 1024 or above (an unprivileged tunnel account cannot bind ${port})."
      return 1
    }
    [[ "${tunnel_key#* }" != "${host_key#* }" ]] || {
      err "LITESTREAM_SFTP_TUNNEL_PUBLIC_KEY must be the receiver's tunnel client key, not its sshd host key."
      return 1
    }
    local tunnel_user="${LITESTREAM_SFTP_TUNNEL_USER:-$LITESTREAM_SFTP_TUNNEL_USER_DEFAULT}"
    [[ "${tunnel_user}" =~ ^[a-z_][a-z0-9_-]{0,31}$ && "${tunnel_user}" != "root" ]] || {
      err "LITESTREAM_SFTP_TUNNEL_USER must be a valid non-root Unix user name: ${tunnel_user}"
      return 1
    }
  fi
  return 0
}

validate_durability_replication_contract() {
  # FRESH-PROVISION DEFAULT AUDIT (2026-08-07), §3.10 -- ordering fix.
  #
  # LITESTREAM_REPLICA_URL defaults empty and DURABILITY_BARRIER_REQUIRED
  # defaults 1, so this pair fails on a fresh provision with an otherwise
  # complete secrets file. It used to be evaluated for the first time inside
  # install_litestream, at roughly step 35 of 45 in main() -- AFTER write_systemd
  # and write_dataplane_probe have already `enable --now`'d the hub and the probe
  # timer, and BEFORE every backup unit, harden_sensitive_artifacts and
  # postflight_control. Under `set -Eeuo pipefail` that aborted the run and left
  # the single worst state available: an internet-reachable hub, running,
  # unhardened, with no backups at all, from a run the operator reads as failed.
  #
  # Nothing observed mid-run can change this verdict -- both inputs are known
  # before a single byte is written -- so it is evaluated here instead, from
  # validate_external_secret_contract, which runs in preflight_control (before
  # any host mutation) and again after write_env. install_litestream still calls
  # litestream_replication_preflight as a backstop; on the --deploy path it can
  # no longer be the first place an operator learns about this.
  #
  # Deliberately NOT added to the STRICT_ONE_TOUCH_SECRETS required list: that
  # list is unconditional, so putting it there would make the replica URL
  # mandatory even when the operator has explicitly set
  # DURABILITY_BARRIER_REQUIRED=0 -- the documented, supported way to run a hub
  # that does not claim RPO 0 -- and the only escape would be
  # STRICT_ONE_TOUCH_SECRETS=0, which also switches off PayPal/SMTP2GO
  # completeness enforcement. This check stays conditional on the barrier flag,
  # which is the thing that actually decides whether a replica is required.
  local required="${DURABILITY_BARRIER_REQUIRED:-$DURABILITY_BARRIER_REQUIRED_DEFAULT}"
  local replica_url="${LITESTREAM_REPLICA_URL:-$LITESTREAM_REPLICA_URL_DEFAULT}"
  if [[ -n "${replica_url}" ]]; then
    # LSR (2026-10-02): the barrier's guarantee is "replicated off this host".
    # Only an sftp:// replica with a valid URL, a pinned receiver host key and
    # a usable (or not yet generated) client key meets it. gs:// is retired, a
    # local path or file:// is on-host, and any other scheme is unsupported.
    # Refuse here, before any host mutation, rather than after a deploy whose
    # every critical write would 503 or be acknowledged on-host.
    if ! litestream_replica_target_ok "${replica_url}"; then
      if [[ "${required}" == "1" ]]; then
        err "LITESTREAM_REPLICA_URL is not a usable off-host replica (see above). With DURABILITY_BARRIER_REQUIRED=1 the hub"
        err "would either 503 every redemption, grant and revoke, or acknowledge writes that never left this host."
        err "Fix the replica settings, or set DURABILITY_BARRIER_REQUIRED=0 to run a hub that explicitly does NOT claim RPO 0."
        return 1
      fi
      warn "LITESTREAM_REPLICA_URL is not a usable off-host replica; this hub does NOT provide RPO 0."
    fi
    return 0
  fi
  if [[ "${required}" == "1" ]]; then
    err "LITESTREAM_REPLICA_URL is not set, so no replication target exists and no litestream"
    err "replicate daemon is configured. 'litestream sync -wait' is an IPC client against that"
    err "daemon's control socket, so every durability barrier would fail closed and every"
    err "critical write would return 503. Set LITESTREAM_REPLICA_URL to the replication"
    err "destination, or set DURABILITY_BARRIER_REQUIRED=0 and DURABILITY_BARRIER_ENABLED=0 to"
    err "run a hub that explicitly does NOT claim RPO 0."
    return 1
  fi
  warn "LITESTREAM_REPLICA_URL is unset: no replication will run and this hub does NOT provide"
  warn "RPO 0. The durability barrier is disabled by configuration."
  return 0
}

validate_site_ai_contract() {
  # Site AI provider chain: Hoppy local is primary for en/my, Vertex AI is the
  # backup billed via Google Cloud credit, AI Studio (GEMINI_API_KEY) is the
  # secondary fallback. The chain historically had no env producer and no
  # preflight check, so a deploy SUCCEEDED with the backup absent.
  local require_backup="${REQUIRE_SITE_AI_BACKUP:-$REQUIRE_SITE_AI_BACKUP_DEFAULT}"
  local chat_mode="${SITE_AI_CHAT_MODE:-$SITE_AI_CHAT_MODE_DEFAULT}"
  local vertex_project="${SITE_AI_VERTEX_PROJECT:-$SITE_AI_VERTEX_PROJECT_DEFAULT}"
  local vertex_location="${SITE_AI_VERTEX_LOCATION:-$SITE_AI_VERTEX_LOCATION_DEFAULT}"
  local vertex_creds="${SITE_AI_VERTEX_CREDENTIALS_PATH:-$SITE_AI_VERTEX_CREDENTIALS_PATH_DEFAULT}"
  local vertex_model="${SITE_AI_VERTEX_MODEL:-$SITE_AI_VERTEX_MODEL_DEFAULT}"
  local api_key="${SITE_AI_API_KEY:-${GEMINI_API_KEY:-${GOOGLE_API_KEY:-${GOOGLE_GENERATIVE_AI_API_KEY:-}}}}"
  [[ "${require_backup}" =~ ^[01]$ ]] || {
    err "REQUIRE_SITE_AI_BACKUP must be 0 or 1, got '${require_backup}'."
    return 1
  }
  case "${chat_mode,,}" in
    auto|local|ollama|gemini|vertex|fallback|"") ;;
    *)
      err "SITE_AI_CHAT_MODE must be one of auto, local, ollama, gemini, vertex, fallback (got '${chat_mode}')."
      return 1
      ;;
  esac
  if [[ -n "${vertex_project}" || -n "${vertex_creds}" || -n "${vertex_model}" || -n "${vertex_location}" ]]; then
    # Any Vertex knob set implies Vertex is intended; validate all.
    [[ -n "${vertex_project}" ]] || {
      err "SITE_AI_VERTEX_PROJECT must be set when any SITE_AI_VERTEX_* value is provided."
      return 1
    }
    [[ "${vertex_project}" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]] || {
      err "SITE_AI_VERTEX_PROJECT must be a valid GCP project ID (6-30 lowercase letters, digits, hyphens)."
      return 1
    }
    [[ "${vertex_location}" =~ ^[a-z]+-[a-z]+[0-9]$ ]] || {
      err "SITE_AI_VERTEX_LOCATION must be a GCP location like us-central1 (got '${vertex_location}')."
      return 1
    }
    [[ -n "${vertex_creds}" ]] || {
      err "SITE_AI_VERTEX_CREDENTIALS_PATH must be set when SITE_AI_VERTEX_PROJECT is set."
      return 1
    }
    [[ "${vertex_creds}" == /* ]] || {
      err "SITE_AI_VERTEX_CREDENTIALS_PATH must be an absolute path, got '${vertex_creds}'."
      return 1
    }
    [[ "${vertex_creds}" != *$'\n'* && "${vertex_creds}" != *$'\r'* ]] || {
      err "SITE_AI_VERTEX_CREDENTIALS_PATH must not contain a newline (it is a PATH to a file, not the JSON itself)."
      return 1
    }
    case "${vertex_creds}" in
      */../*|*/..|../*|*..*) err "SITE_AI_VERTEX_CREDENTIALS_PATH must not contain '..' segments."; return 1 ;;
    esac
    if [[ -e "${vertex_creds}" || -L "${vertex_creds}" ]]; then
      [[ -f "${vertex_creds}" && ! -L "${vertex_creds}" ]] || {
        err "SITE_AI_VERTEX_CREDENTIALS_PATH must be a regular non-symlink file: ${vertex_creds}"
        return 1
      }
      [[ "$(stat -c '%u' "${vertex_creds}" 2>/dev/null || printf 'unknown')" == "0" ]] || {
        err "SITE_AI_VERTEX_CREDENTIALS_PATH must be owned by root: ${vertex_creds}"
        return 1
      }
      local perm_hits perm_rc=0
      perm_hits="$(find "${vertex_creds}" -prune -perm /022 -print -quit)" || perm_rc=$?
      (( perm_rc == 0 )) || {
        err "Could not inspect the permissions of SITE_AI_VERTEX_CREDENTIALS_PATH (find failed, exit ${perm_rc}): ${vertex_creds}"
        return 1
      }
      [[ -z "${perm_hits}" ]] || {
        err "SITE_AI_VERTEX_CREDENTIALS_PATH must not be writable by group/other (use chmod 600): ${vertex_creds}"
        return 1
      }
      [[ -r "${vertex_creds}" ]] || {
        err "SITE_AI_VERTEX_CREDENTIALS_PATH is not readable: ${vertex_creds}"
        return 1
      }
      if ! python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); assert "client_email" in d and "private_key" in d and "token_uri" in d' "${vertex_creds}" 2>/dev/null; then
        err "SITE_AI_VERTEX_CREDENTIALS_PATH does not contain a valid service-account JSON (needs client_email, private_key, token_uri): ${vertex_creds}"
        return 1
      fi
    elif [[ "${require_backup}" == "1" ]]; then
      err "SITE_AI_VERTEX_CREDENTIALS_PATH does not exist: ${vertex_creds}. Provision the service-account JSON file root-owned 0600 before deploy."
      return 1
    fi
    if [[ -n "${vertex_model}" ]]; then
      [[ "${vertex_model}" =~ ^[A-Za-z0-9._-]+$ ]] || {
        err "SITE_AI_VERTEX_MODEL must be a valid model name (got '${vertex_model}')."
        return 1
      }
    fi
  fi
  if [[ -n "${api_key}" ]]; then
    [[ "${api_key}" != *$'\n'* && "${api_key}" != *$'\r'* ]] || {
      err "SITE_AI_API_KEY / GEMINI_API_KEY must not contain a newline."
      return 1
    }
    (( ${#api_key} >= 10 )) || {
      err "SITE_AI_API_KEY / GEMINI_API_KEY looks too short to be valid."
      return 1
    }
  fi
  if [[ "${require_backup}" == "1" ]]; then
    if [[ -z "${vertex_project}" || -z "${vertex_creds}" ]] && [[ -z "${api_key}" ]]; then
      err "REQUIRE_SITE_AI_BACKUP=1 but no backup credential is provisioned: set SITE_AI_VERTEX_PROJECT + SITE_AI_VERTEX_CREDENTIALS_PATH (Vertex AI via GCP credit) or SITE_AI_API_KEY/GEMINI_API_KEY (AI Studio fallback)."
      return 1
    fi
    log "Site AI backup contract: REQUIRE_SITE_AI_BACKUP=1 satisfied (vertex=${vertex_project:-none}, gemini_key=${api_key:+present})"
  else
    if [[ -z "${vertex_project}" && -z "${api_key}" ]]; then
      warn "Site AI backup is unprovisioned (no Vertex project/credentials and no GEMINI_API_KEY). REQUIRE_SITE_AI_BACKUP=0 so deploy continues, but fallback_zero_cost will serve canned text on local failure."
    fi
  fi
  return 0
}

validate_external_secret_contract() {
  local missing=() variable tunnel_account tunnel_token
  validate_rclone_injection_contract || return 1
  # An rclone remote that validates perfectly still produces no backup at all if
  # the independent-encryption gate cannot be satisfied. Both call sites of this
  # contract (preflight_control, and the post-write_env pass in main) therefore
  # check it, so the failure lands before any host mutation instead of at
  # run_initial_backup.
  validate_backup_encryption_contract || return 1
  # Same reasoning, same phase: a durability barrier that can never be satisfied
  # is knowable from the environment alone, so it fails here rather than at
  # install_litestream with the hub already serving. See the function comment.
  validate_durability_replication_contract || return 1
  validate_site_ai_contract || return 1
  if [[ "${REQUIRE_CLOUDFLARE_AUTOMATION:-$REQUIRE_CLOUDFLARE_AUTOMATION_DEFAULT}" == "1" ]]; then
    # Fleet reset TP-H7: the two Wins zone ids have built-in defaults, which
    # write_env and the DNS automation already use; apply them here too so
    # preflight does not demand what the installer knows.
    : "${CLOUDFLARE_WINSVPN_ORG_ZONE_ID:=${CLOUDFLARE_WINSVPN_ORG_ZONE_ID_DEFAULT}}"
    : "${CLOUDFLARE_WINSVPN_COM_ZONE_ID:=${CLOUDFLARE_WINSVPN_COM_ZONE_ID_DEFAULT}}"
    for variable in CLOUDFLARE_APPCLOUD_API_TOKEN CLOUDFLARE_APPCLOUD_ZONE_ID CLOUDFLARE_WINS_API_TOKEN CLOUDFLARE_WINSVPN_ORG_ZONE_ID CLOUDFLARE_WINSVPN_COM_ZONE_ID; do
      [[ -n "${!variable:-}" ]] || missing+=("${variable}")
    done
  fi
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
    tunnel_account="${CLOUDFLARE_TUNNEL_ACCOUNT_ID:-${CLOUDFLARE_WINS_ACCOUNT_ID:-$CLOUDFLARE_TUNNEL_ACCOUNT_ID_DEFAULT}}"
    tunnel_token="${CLOUDFLARE_TUNNEL_API_TOKEN:-${CLOUDFLARE_WINS_API_TOKEN:-$CLOUDFLARE_TUNNEL_API_TOKEN_DEFAULT}}"
    [[ -n "${tunnel_account}" ]] || missing+=("CLOUDFLARE_TUNNEL_ACCOUNT_ID")
    [[ -n "${tunnel_token}" ]] || missing+=("CLOUDFLARE_TUNNEL_API_TOKEN")
    if [[ "${REQUIRE_CLOUDFLARE_ACCESS:-$REQUIRE_CLOUDFLARE_ACCESS_DEFAULT}" == "1" ]]; then
      [[ -n "${CLOUDFLARE_ACCESS_API_TOKEN:-$CLOUDFLARE_ACCESS_API_TOKEN_DEFAULT}" ]] || missing+=("CLOUDFLARE_ACCESS_API_TOKEN")
    fi
  fi
  if [[ "${REQUIRE_ACTIVE_GATEWAY_AUTOMATION:-$REQUIRE_ACTIVE_GATEWAY_AUTOMATION_DEFAULT}" == "1" ]]; then
    [[ -n "${GITHUB_GIST_TOKEN:-}" ]] || missing+=("GITHUB_GIST_TOKEN")
  fi
  if [[ "${STRICT_ONE_TOUCH_SECRETS:-$STRICT_ONE_TOUCH_SECRETS_DEFAULT}" == "1" ]]; then
    for variable in ADMIN_TOKEN SMTP_USER SMTP_PASS PAYPAL_PUBLIC_CLIENT_ID PAYPAL_CLIENT_ID PAYPAL_CLIENT_SECRET PAYPAL_PLAN_1M PAYPAL_PLAN_1Y PAYPAL_PLAN_PERSONAL PAYPAL_LIFETIME_SUPPORT_URL PAYPAL_LIFETIME_NO_SUPPORT_URL PAYPAL_LIFETIME_SUPPORT_AMOUNT PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT PAYPAL_LIFETIME_CURRENCY HUB_ADMIN_SSH_CIDRS; do
      [[ -n "${!variable:-}" ]] || missing+=("${variable}")
    done
    if [[ "${PAYPAL_WEBHOOK_AUTO_ENSURE:-$PAYPAL_WEBHOOK_AUTO_ENSURE_DEFAULT}" != "1" ]]; then
      [[ -n "${PAYPAL_WEBHOOK_ID:-}" ]] || missing+=("PAYPAL_WEBHOOK_ID")
    fi
    if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" != "1" ]]; then
      for variable in SPA_KEY SPA_HMAC; do
        [[ -n "${!variable:-}" ]] || missing+=("${variable}")
      done
    fi
  fi
  if ((${#missing[@]})); then
    err "Missing required one-touch integration secrets: ${missing[*]}. Inject them through root-owned ${WINS_SECRETS_FILE}."
    return 1
  fi
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
    [[ "${tunnel_account}" =~ ^[A-Fa-f0-9]{32}$ ]] || {
      err "CLOUDFLARE_TUNNEL_ACCOUNT_ID must be a 32-character Cloudflare account ID."
      return 1
    }
    if [[ "${REQUIRE_CLOUDFLARE_ACCESS:-$REQUIRE_CLOUDFLARE_ACCESS_DEFAULT}" == "1" ]]; then
      [[ "${CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME:-$CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME_DEFAULT}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$ ]] || {
        err "CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME must be 3-64 safe characters."
        return 1
      }
      [[ "${CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION:-$CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION_DEFAULT}" =~ ^[1-9][0-9]{0,5}h$ ]] || {
        err "CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION must be a positive hour duration such as 8760h."
        return 1
      }
      if [[ -n "${TUNNEL_SERVICE_TOKEN_ID:-}" || -n "${TUNNEL_SERVICE_TOKEN_SECRET:-}" ]]; then
        [[ -n "${TUNNEL_SERVICE_TOKEN_ID:-}" && -n "${TUNNEL_SERVICE_TOKEN_SECRET:-}" ]] || {
          err "TUNNEL_SERVICE_TOKEN_ID and TUNNEL_SERVICE_TOKEN_SECRET must be supplied together."
          return 1
        }
      fi
    fi
  fi
  [[ "${STRICT_ONE_TOUCH_SECRETS:-$STRICT_ONE_TOUCH_SECRETS_DEFAULT}" == "1" ]] || {
    warn "STRICT_ONE_TOUCH_SECRETS=0: SMTP2GO/PayPal completeness is not enforced; use only for disposable simulation."
    return 0
  }
  [[ "${ADMIN_TOKEN:-}" =~ ^[^[:space:]]{32,}$ ]] || {
    err "ADMIN_TOKEN must be a pre-generated secret of at least 32 non-whitespace characters in strict one-touch mode."
    return 1
  }
  [[ "${PAYPAL_PUBLIC_CLIENT_ID}" == "${PAYPAL_CLIENT_ID}" ]] || {
    err "PAYPAL_PUBLIC_CLIENT_ID must match PAYPAL_CLIENT_ID for the live account."
    return 1
  }
  for variable in PAYPAL_LIFETIME_SUPPORT_AMOUNT PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT; do
    [[ "${!variable}" =~ ^[0-9]+([.][0-9]{1,2})?$ && ! "${!variable}" =~ ^0+([.]0+)?$ ]] || {
      err "${variable} must be a positive decimal amount with at most two fractional digits."
      return 1
    }
  done
  [[ "${PAYPAL_LIFETIME_CURRENCY}" =~ ^[A-Z]{3}$ ]] || {
    err "PAYPAL_LIFETIME_CURRENCY must be a three-letter uppercase currency code."
    return 1
  }
  # Self-hosted crypto (BTCPay) is optional but all-or-nothing: if any BTCPAY_*
  # value is supplied the whole set must be, and the base URL must be https so
  # neither invoice creation nor the buyer-facing checkout link is ever plaintext.
  # Mirrors the TUNNEL_SERVICE_TOKEN_ID/SECRET "supplied together" rule above.
  if [[ -n "${BTCPAY_URL:-}${BTCPAY_STORE_ID:-}${BTCPAY_API_KEY:-}${BTCPAY_WEBHOOK_SECRET:-}" ]]; then
    for variable in BTCPAY_URL BTCPAY_STORE_ID BTCPAY_API_KEY BTCPAY_WEBHOOK_SECRET; do
      [[ -n "${!variable:-}" ]] || {
        err "${variable} must be set when any BTCPAY_* value is provided (self-hosted crypto checkout is all-or-nothing)."
        return 1
      }
    done
    [[ "${BTCPAY_URL}" =~ ^https://[A-Za-z0-9.:_-]+(/.*)?$ ]] || {
      err "BTCPAY_URL must be a valid https:// URL for the self-hosted BTCPay Server."
      return 1
    }
  fi
  # Maximum-privacy Monero-direct path (self-hosted monero-wallet-rpc). Enabled by
  # MONERO_WALLET_RPC_URL alone and independent of BTCPay. When the URL is set it
  # must be a form the hub runtime accepts (http on loopback only, else https on
  # 443), both RPC credentials are required (the hub refuses unauthenticated
  # wallet RPC), and the tunable numerics/manual price must parse. Fail closed on anything
  # malformed so a half-configured wallet can never mint an order it cannot settle.
  case "${MONERO_WALLET_RPC_CF_ACCESS:-0}" in
    0|1) ;;
    *) err "MONERO_WALLET_RPC_CF_ACCESS must be 0 or 1."; return 1 ;;
  esac
  # Fleet reset TP-P9: the hub offers BTCPay only for these chains; anything
  # else would disable the offer at runtime, so refuse it here.
  [[ "${BTCPAY_CHECKOUT_CHAINS:-none}" =~ ^(none|(BTC|DASH)(,(BTC|DASH))*)$ ]] || {
    err "BTCPAY_CHECKOUT_CHAINS must be none or a comma-separated list of BTC and DASH (the chains whose watch-only wallet is attached to the BTCPay store)."
    return 1
  }
  if [[ -n "${MONERO_WALLET_RPC_URL:-}" ]]; then
    # Fleet reset TP-H5: mirror validate_monero_rpc_configuration in the hub
    # runtime, which disables Monero with one log line on anything else:
    # plaintext http only on loopback, https only on port 443, no userinfo,
    # query or fragment, and digest credentials always.
    [[ "${MONERO_WALLET_RPC_URL}" =~ ^http://(127\.0\.0\.1|localhost|\[::1\])(:[0-9]{1,5})?(/[A-Za-z0-9._/-]*)?$ \
       || "${MONERO_WALLET_RPC_URL}" =~ ^https://[A-Za-z0-9.-]+(:443)?(/[A-Za-z0-9._/-]*)?$ ]] || {
      err "MONERO_WALLET_RPC_URL must be http://127.0.0.1[:port] (loopback) or https://host[:443]; the hub disables any other form at runtime."
      return 1
    }
    for variable in MONERO_WALLET_RPC_USER MONERO_WALLET_RPC_PASS; do
      [[ -n "${!variable:-}" ]] || {
        err "${variable} must be set whenever MONERO_WALLET_RPC_URL is set (the hub requires authenticated wallet RPC, HTTP digest)."
        return 1
      }
    done
    if [[ "${MONERO_WALLET_RPC_CF_ACCESS:-0}" == "1" && "${MONERO_WALLET_RPC_URL}" != https://* ]]; then
      err "MONERO_WALLET_RPC_CF_ACCESS=1 presents the Access service token and needs an https:// MONERO_WALLET_RPC_URL."
      return 1
    fi
    if [[ "${MONERO_WALLET_RPC_CF_ACCESS:-0}" == "1" ]]; then
      # D7 ruling: a dedicated token, never the management token.
      [[ "${MONERO_WALLET_RPC_CF_ACCESS_CLIENT_ID:-}" =~ ^[A-Za-z0-9]+\.access$ \
          && "${MONERO_WALLET_RPC_CF_ACCESS_CLIENT_SECRET:-}" =~ ^[^[:space:]]{32,}$ ]] || {
        err "MONERO_WALLET_RPC_CF_ACCESS=1 needs MONERO_WALLET_RPC_CF_ACCESS_CLIENT_ID (<id>.access) and MONERO_WALLET_RPC_CF_ACCESS_CLIENT_SECRET (the monero-rpc Access application's own service token) in ${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}."
        return 1
      }
      [[ "${MONERO_WALLET_RPC_CF_ACCESS_CLIENT_ID}" != "${TUNNEL_SERVICE_TOKEN_ID:-}" \
          && "${MONERO_WALLET_RPC_CF_ACCESS_CLIENT_SECRET}" != "${TUNNEL_SERVICE_TOKEN_SECRET:-}" ]] || {
        err "MONERO_WALLET_RPC_CF_ACCESS_CLIENT_ID or _SECRET is the management service token; the wallet RPC hostname needs its own token."
        return 1
      }
    fi
    if [[ -n "${MONERO_CONFIRMATIONS:-}" ]]; then
      [[ "${MONERO_CONFIRMATIONS}" =~ ^[1-9][0-9]*$ ]] || {
        err "MONERO_CONFIRMATIONS must be a positive integer number of confirmations."
        return 1
      }
    fi
    if [[ -n "${MONERO_ORDER_TTL_MINUTES:-}" ]]; then
      [[ "${MONERO_ORDER_TTL_MINUTES}" =~ ^[1-9][0-9]*$ ]] || {
        err "MONERO_ORDER_TTL_MINUTES must be a positive integer number of minutes."
        return 1
      }
    fi
    if [[ -n "${MONERO_PRICE_API_URL:-}" ]]; then
      [[ "${MONERO_PRICE_API_URL}" =~ ^https://[A-Za-z0-9.:_-]+(/.*)?$ ]] || {
        err "MONERO_PRICE_API_URL must be a valid https:// URL for the XMR/USD price feed."
        return 1
      }
    fi
    if [[ -n "${MONERO_PRICE_API_URLS:-}" ]]; then
      # M-6: each comma-separated entry must be an https:// URL; the hub's Python origin
      # allowlist (api.kraken.com / api.coingecko.com / api.coinbase.com) is authoritative.
      [[ "${MONERO_PRICE_API_URLS}" =~ ^https://[^,]+(,https://[^,]+)*$ ]] || {
        err "MONERO_PRICE_API_URLS must be comma-separated https:// XMR/USD price URLs."
        return 1
      }
    fi
    if [[ -n "${MONERO_PRICE_MANUAL_USD:-}" ]]; then
      [[ "${MONERO_PRICE_MANUAL_USD}" =~ ^[0-9]+([.][0-9]{1,8})?$ && ! "${MONERO_PRICE_MANUAL_USD}" =~ ^0+([.]0+)?$ ]] || {
        err "MONERO_PRICE_MANUAL_USD must be a positive decimal USD price for one XMR."
        return 1
      }
    fi
  fi
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" != "1" ]]; then
    for variable in SPA_KEY SPA_HMAC; do
      [[ "${!variable}" =~ ^[A-Za-z0-9+/]{43}=$ ]] || {
        err "${variable} must be an independently generated 32-byte base64 secret for legacy direct SPA mode."
        return 1
      }
    done
  fi
}

verify_preflight_external_credentials() {
  if [[ "${PREFLIGHT_VERIFY_EXTERNAL_CREDENTIALS:-$PREFLIGHT_VERIFY_EXTERNAL_CREDENTIALS_DEFAULT}" != "1" ]]; then
    warn "PREFLIGHT_VERIFY_EXTERNAL_CREDENTIALS=0: non-mutating provider authentication/permission checks were skipped."
    return 0
  fi
  log "Verifying Cloudflare, optional Gist, SMTP2GO, and PayPal credentials/permissions before host mutation"
  REQUIRE_CLOUDFLARE_AUTOMATION="${REQUIRE_CLOUDFLARE_AUTOMATION:-$REQUIRE_CLOUDFLARE_AUTOMATION_DEFAULT}"
  REQUIRE_ACTIVE_GATEWAY_AUTOMATION="${REQUIRE_ACTIVE_GATEWAY_AUTOMATION:-$REQUIRE_ACTIVE_GATEWAY_AUTOMATION_DEFAULT}"
  HIDE_CONTROL_ORIGIN="${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}"
  REQUIRE_CLOUDFLARE_ACCESS="${REQUIRE_CLOUDFLARE_ACCESS:-$REQUIRE_CLOUDFLARE_ACCESS_DEFAULT}"
  STRICT_ONE_TOUCH_SECRETS="${STRICT_ONE_TOUCH_SECRETS:-$STRICT_ONE_TOUCH_SECRETS_DEFAULT}"
  export REQUIRE_CLOUDFLARE_AUTOMATION REQUIRE_ACTIVE_GATEWAY_AUTOMATION HIDE_CONTROL_ORIGIN STRICT_ONE_TOUCH_SECRETS
  export CLOUDFLARE_APPCLOUD_API_TOKEN CLOUDFLARE_APPCLOUD_ZONE_ID CLOUDFLARE_WINS_API_TOKEN
  export CLOUDFLARE_WINSVPN_ORG_ZONE_ID CLOUDFLARE_WINSVPN_COM_ZONE_ID
  export CLOUDFLARE_TUNNEL_ACCOUNT_ID CLOUDFLARE_TUNNEL_API_TOKEN CLOUDFLARE_WINS_ACCOUNT_ID
  export REQUIRE_CLOUDFLARE_ACCESS CLOUDFLARE_ACCESS_API_TOKEN CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME
  export CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID
  export TUNNEL_SERVICE_TOKEN_ID TUNNEL_SERVICE_TOKEN_SECRET
  export GITHUB_GIST_TOKEN ACTIVE_GATEWAY_GIST_ID SMTP_SERVER SMTP_PORT SMTP_USER SMTP_PASS
  export PAYPAL_MODE PAYPAL_CLIENT_ID PAYPAL_CLIENT_SECRET PAYPAL_WEBHOOK_ID PAYPAL_WEBHOOK_AUTO_ENSURE
  export PAYPAL_PLAN_1M PAYPAL_PLAN_1Y PAYPAL_PLAN_PERSONAL
  export PAYPAL_LIFETIME_SUPPORT_URL PAYPAL_LIFETIME_NO_SUPPORT_URL
  export PAYPAL_LIFETIME_SUPPORT_AMOUNT PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT PAYPAL_LIFETIME_CURRENCY
  python3 - <<'PYEOF'
import base64
import json
import os
import re
import smtplib
import ssl
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from decimal import Decimal, InvalidOperation


def enabled(name: str, default: str = "1") -> bool:
    return os.getenv(name, default).strip().lower() in {"1", "true", "yes", "on"}


class _CredentialedNoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_CREDENTIALED_NO_REDIRECT_OPENER = urllib.request.build_opener(_CredentialedNoRedirect)


def json_request(url: str, token: str = "", data: bytes | None = None, headers: dict | None = None) -> dict:
    request_headers = {"Accept": "application/json", "User-Agent": "winsvpn-preflight/1"}
    if token:
        request_headers["Authorization"] = f"Bearer {token}"
    request_headers.update(headers or {})
    request = urllib.request.Request(url, data=data, headers=request_headers)
    with _CREDENTIALED_NO_REDIRECT_OPENER.open(request, timeout=20) as response:
        return json.loads(response.read().decode())


def paypal_hosted_product_contract(url: str) -> tuple[str, str, Decimal]:
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme != "https" or not (parsed.hostname == "paypal.com" or str(parsed.hostname or "").endswith(".paypal.com")):
        raise RuntimeError("hosted product URL is not on paypal.com")
    request = urllib.request.Request(url, headers={"Accept": "text/html", "User-Agent": "winsvpn-preflight/1"})
    with urllib.request.urlopen(request, timeout=20) as response:
        final = urllib.parse.urlparse(response.geturl())
        if final.scheme != "https" or not (final.hostname == "paypal.com" or str(final.hostname or "").endswith(".paypal.com")):
            raise RuntimeError("hosted product redirected outside paypal.com")
        content = response.read().decode("utf-8", "replace")
    match = re.search(
        r'"name"\s*:\s*"item_name"\s*,\s*"value"\s*:\s*"(?P<item>[^"]+)"\s*}\s*,\s*'
        r'{\s*"name"\s*:\s*"currency_code"\s*,\s*"value"\s*:\s*"(?P<currency>[A-Z]{3})"\s*}\s*,\s*'
        r'{\s*"name"\s*:\s*"amount"\s*,\s*"value"\s*:\s*"(?P<amount>[0-9]+(?:\.[0-9]{1,2})?)"',
        content,
        re.IGNORECASE,
    )
    if not match:
        raise RuntimeError("hosted product fields missing")
    try:
        amount = Decimal(match.group("amount"))
    except InvalidOperation as exc:
        raise RuntimeError("hosted product amount invalid") from exc
    return match.group("item"), match.group("currency").upper(), amount


def retry(label: str, operation) -> None:
    last = None
    for attempt in range(3):
        try:
            operation()
            return
        except Exception as exc:
            last = exc
            if attempt < 2:
                time.sleep(attempt + 1)
    raise RuntimeError(f"{label} authentication failed") from last


errors: list[str] = []


def check(label: str, operation) -> None:
    try:
        retry(label, operation)
    except Exception:
        errors.append(label)


if enabled("REQUIRE_CLOUDFLARE_AUTOMATION"):
    zones = (
        ("Cloudflare app zone", os.getenv("CLOUDFLARE_APPCLOUD_API_TOKEN", ""), os.getenv("CLOUDFLARE_APPCLOUD_ZONE_ID", "")),
        ("Cloudflare winsvpn.org zone", os.getenv("CLOUDFLARE_WINS_API_TOKEN", ""), os.getenv("CLOUDFLARE_WINSVPN_ORG_ZONE_ID", "")),
        ("Cloudflare winsvpn.com zone", os.getenv("CLOUDFLARE_WINS_API_TOKEN", ""), os.getenv("CLOUDFLARE_WINSVPN_COM_ZONE_ID", "")),
    )
    for label, token, zone_id in zones:
        def verify_zone(token=token, zone_id=zone_id):
            result = json_request(
                f"https://api.cloudflare.com/client/v4/zones/{zone_id}/dns_records?per_page=1",
                token,
            )
            if result.get("success") is not True:
                raise RuntimeError("zone query rejected")
        check(label, verify_zone)

if enabled("HIDE_CONTROL_ORIGIN"):
    tunnel_account = os.getenv("CLOUDFLARE_TUNNEL_ACCOUNT_ID") or os.getenv("CLOUDFLARE_WINS_ACCOUNT_ID", "")
    tunnel_token = os.getenv("CLOUDFLARE_TUNNEL_API_TOKEN") or os.getenv("CLOUDFLARE_WINS_API_TOKEN", "")
    def verify_tunnel_api():
        api = f"https://api.cloudflare.com/client/v4/accounts/{tunnel_account}/cfd_tunnel"
        result = json_request(
            f"{api}?per_page=1&is_deleted=false",
            tunnel_token,
        )
        if result.get("success") is not True:
            raise RuntimeError("tunnel query rejected")
        # Prove Edit scope without creating anything: an incomplete create
        # request can only reach payload validation when authorization passes.
        # A read-only token returns 403 before Cloudflare validates the absent
        # required name. Treat any success/result ID as an unsafe hard failure.
        request = urllib.request.Request(
            api,
            data=b'{"config_src":"cloudflare"}',
            headers={
                "Accept": "application/json",
                "Authorization": f"Bearer {tunnel_token}",
                "Content-Type": "application/json",
                "User-Agent": "winsvpn-preflight/1",
            },
            method="POST",
        )
        try:
            with _CREDENTIALED_NO_REDIRECT_OPENER.open(request, timeout=20) as response:
                probe = json.loads(response.read().decode())
            if probe.get("success") is True or (probe.get("result") or {}).get("id"):
                raise RuntimeError("invalid tunnel-create probe unexpectedly mutated provider state")
            raise RuntimeError("tunnel create probe returned an unexpected successful HTTP response")
        except urllib.error.HTTPError as exc:
            body = exc.read().decode("utf-8", "replace")
            try:
                probe = json.loads(body)
            except json.JSONDecodeError:
                probe = {}
            if exc.code in {401, 403}:
                raise RuntimeError("tunnel Edit permission rejected") from exc
            if exc.code not in {400, 422}:
                raise RuntimeError(f"unexpected tunnel Edit probe HTTP {exc.code}") from exc
            if probe.get("success") is True or (probe.get("result") or {}).get("id"):
                raise RuntimeError("invalid tunnel-create probe returned an unsafe result")
    check("Cloudflare Tunnel Edit", verify_tunnel_api)

    if enabled("REQUIRE_CLOUDFLARE_ACCESS"):
        access_token = os.getenv("CLOUDFLARE_ACCESS_API_TOKEN", "")
        def verify_access_api():
            for suffix in ("access/apps?per_page=1", "access/service_tokens?per_page=1"):
                result = json_request(
                    f"https://api.cloudflare.com/client/v4/accounts/{tunnel_account}/{suffix}",
                    access_token,
                )
                if result.get("success") is not True:
                    raise RuntimeError("Access query rejected")
        check("Cloudflare Access Apps and Service Tokens", verify_access_api)

if enabled("REQUIRE_ACTIVE_GATEWAY_AUTOMATION"):
    def verify_gist():
        gist_id = os.getenv("ACTIVE_GATEWAY_GIST_ID", "325d9caf5c3cda5d6f933e0ac5ba8a02")
        result = json_request(
            f"https://api.github.com/gists/{gist_id}",
            os.getenv("GITHUB_GIST_TOKEN", ""),
            headers={"Accept": "application/vnd.github+json", "X-GitHub-Api-Version": "2026-03-10"},
        )
        if result.get("id") != gist_id:
            raise RuntimeError("gist mismatch")
    check("GitHub Gist", verify_gist)

if enabled("STRICT_ONE_TOUCH_SECRETS"):
    def verify_smtp():
        with smtplib.SMTP(os.getenv("SMTP_SERVER", "mail.smtp2go.com"), int(os.getenv("SMTP_PORT", "2525")), timeout=20) as smtp:
            smtp.ehlo()
            smtp.starttls(context=ssl.create_default_context())
            smtp.ehlo()
            smtp.login(os.getenv("SMTP_USER", ""), os.getenv("SMTP_PASS", ""))
    check("SMTP2GO", verify_smtp)

    paypal_base = "https://api-m.sandbox.paypal.com" if os.getenv("PAYPAL_MODE", "live") == "sandbox" else "https://api-m.paypal.com"
    paypal_access_token = ""

    def verify_paypal_oauth():
        global paypal_access_token
        credentials = base64.b64encode(f"{os.getenv('PAYPAL_CLIENT_ID', '')}:{os.getenv('PAYPAL_CLIENT_SECRET', '')}".encode()).decode()
        token_result = json_request(
            f"{paypal_base}/v1/oauth2/token",
            data=b"grant_type=client_credentials",
            headers={
                "Authorization": f"Basic {credentials}",
                "Content-Type": "application/x-www-form-urlencoded",
                "Accept-Language": "en_US",
            },
        )
        paypal_access_token = token_result.get("access_token") or ""
        if not paypal_access_token:
            raise RuntimeError("PayPal access token missing")
    check("PayPal OAuth", verify_paypal_oauth)

    def verify_paypal_webhook():
        if not paypal_access_token:
            raise RuntimeError("PayPal OAuth unavailable")
        webhook_id = os.getenv("PAYPAL_WEBHOOK_ID", "")
        webhook = json_request(f"{paypal_base}/v1/notifications/webhooks/{webhook_id}", paypal_access_token)
        required = {
            "BILLING.SUBSCRIPTION.ACTIVATED",
            "BILLING.SUBSCRIPTION.UPDATED",
            "BILLING.SUBSCRIPTION.RE-ACTIVATED",
            "BILLING.SUBSCRIPTION.CANCELLED",
            "BILLING.SUBSCRIPTION.SUSPENDED",
            "BILLING.SUBSCRIPTION.EXPIRED",
            "BILLING.SUBSCRIPTION.PAYMENT.FAILED",
            "PAYMENT.SALE.COMPLETED",
            "PAYMENT.SALE.REFUNDED",
            "PAYMENT.SALE.REVERSED",
            "PAYMENT.SALE.DENIED",
            "PAYMENT.CAPTURE.COMPLETED",
            "PAYMENT.CAPTURE.DENIED",
            "PAYMENT.CAPTURE.DECLINED",
            "PAYMENT.CAPTURE.REFUNDED",
            "PAYMENT.CAPTURE.REVERSED",
        }
        actual = {item.get("name") for item in webhook.get("event_types", []) if isinstance(item, dict)}
        if webhook.get("id") != webhook_id or not str(webhook.get("url") or "").endswith("/webhook/paypal") or not required.issubset(actual):
            raise RuntimeError("PayPal webhook contract mismatch")
    if enabled("PAYPAL_WEBHOOK_AUTO_ENSURE"):
        try:
            retry("PayPal webhook", verify_paypal_webhook)
        except Exception:
            print("[INFO] PayPal webhook will be created or repaired after hub health succeeds")
    else:
        check("PayPal webhook", verify_paypal_webhook)

    for variable, label in (
        ("PAYPAL_PLAN_1M", "PayPal one-month plan"),
        ("PAYPAL_PLAN_1Y", "PayPal one-year plan"),
        ("PAYPAL_PLAN_PERSONAL", "PayPal legacy personal plan"),
    ):
        def verify_paypal_plan(variable=variable):
            if not paypal_access_token:
                raise RuntimeError("PayPal OAuth unavailable")
            plan_id = os.getenv(variable, "")
            plan = json_request(f"{paypal_base}/v1/billing/plans/{plan_id}", paypal_access_token)
            if plan.get("id") != plan_id or plan.get("status") != "ACTIVE":
                raise RuntimeError(f"PayPal plan contract mismatch: {variable}")
        check(label, verify_paypal_plan)

    for url_variable, amount_variable, label, item_pattern in (
        ("PAYPAL_LIFETIME_SUPPORT_URL", "PAYPAL_LIFETIME_SUPPORT_AMOUNT", "PayPal lifetime support product", r"(?<!out)\s+tech support"),
        ("PAYPAL_LIFETIME_NO_SUPPORT_URL", "PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT", "PayPal lifetime no-support product", r"(?:without|no)\s+tech support"),
    ):
        def verify_hosted_product(url_variable=url_variable, amount_variable=amount_variable, item_pattern=item_pattern):
            item, currency, amount = paypal_hosted_product_contract(os.getenv(url_variable, ""))
            expected_amount = Decimal(os.getenv(amount_variable, ""))
            expected_currency = os.getenv("PAYPAL_LIFETIME_CURRENCY", "")
            if not re.search(r"lifetime", item, re.IGNORECASE) or not re.search(item_pattern, item, re.IGNORECASE):
                raise RuntimeError("hosted product name mismatch")
            if amount != expected_amount or currency != expected_currency:
                raise RuntimeError("hosted product amount/currency drift")
        check(label, verify_hosted_product)

if errors:
    print("[ERR] External credential/permission preflight failed: " + ", ".join(errors), file=sys.stderr)
    raise SystemExit(1)
print("[INFO] External credential/permission preflight passed")
PYEOF
  local preflight_status=$?
  # Drop the export attribute now that the one-time preflight child process
  # has exited. `export -n` keeps each value available to this script via
  # plain "${VAR}" expansion (later steps such as verify_external_integrations
  # still read SMTP_PASS directly) without leaving it in this process's own
  # environment for every subsequent child (apt-get, systemctl, curl, ...) to
  # inherit for the remainder of the run.
  export -n REQUIRE_CLOUDFLARE_AUTOMATION REQUIRE_ACTIVE_GATEWAY_AUTOMATION HIDE_CONTROL_ORIGIN STRICT_ONE_TOUCH_SECRETS
  export -n CLOUDFLARE_APPCLOUD_API_TOKEN CLOUDFLARE_APPCLOUD_ZONE_ID CLOUDFLARE_WINS_API_TOKEN
  export -n CLOUDFLARE_WINSVPN_ORG_ZONE_ID CLOUDFLARE_WINSVPN_COM_ZONE_ID
  export -n CLOUDFLARE_TUNNEL_ACCOUNT_ID CLOUDFLARE_TUNNEL_API_TOKEN CLOUDFLARE_WINS_ACCOUNT_ID
  export -n REQUIRE_CLOUDFLARE_ACCESS CLOUDFLARE_ACCESS_API_TOKEN CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME
  export -n CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID
  export -n TUNNEL_SERVICE_TOKEN_ID TUNNEL_SERVICE_TOKEN_SECRET
  export -n GITHUB_GIST_TOKEN ACTIVE_GATEWAY_GIST_ID SMTP_SERVER SMTP_PORT SMTP_USER SMTP_PASS
  export -n PAYPAL_MODE PAYPAL_CLIENT_ID PAYPAL_CLIENT_SECRET PAYPAL_WEBHOOK_ID PAYPAL_WEBHOOK_AUTO_ENSURE
  export -n PAYPAL_PLAN_1M PAYPAL_PLAN_1Y PAYPAL_PLAN_PERSONAL
  export -n PAYPAL_LIFETIME_SUPPORT_URL PAYPAL_LIFETIME_NO_SUPPORT_URL
  export -n PAYPAL_LIFETIME_SUPPORT_AMOUNT PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT PAYPAL_LIFETIME_CURRENCY
  return "${preflight_status}"
}

verify_external_integrations() {
  [[ "${STRICT_ONE_TOUCH_SECRETS:-$STRICT_ONE_TOUCH_SECRETS_DEFAULT}" == "1" ]] || return 0
  log "Verifying SMTP2GO authentication without sending mail"
  # Values are loaded from the freshly generated root-only runtime environment.
  # shellcheck disable=SC2153
  # SMTP_PASS is handed to the python3 child over a private inherited file
  # descriptor rather than argv, so it never appears in that process's
  # /proc/<pid>/cmdline or in `ps`-style process listings.
  exec {smtp_preflight_pass_fd}<<<"${SMTP_PASS}"
  python3 - "${SMTP_SERVER}" "${SMTP_PORT}" "${SMTP_USER}" "${smtp_preflight_pass_fd}" <<'PYEOF'
import os
import smtplib
import ssl
import sys

host, port, username, pass_fd = sys.argv[1], int(sys.argv[2]), sys.argv[3], int(sys.argv[4])
with os.fdopen(pass_fd) as fh:
    password = fh.readline().rstrip("\n")
with smtplib.SMTP(host, port, timeout=20) as smtp:
    smtp.ehlo()
    smtp.starttls(context=ssl.create_default_context())
    smtp.ehlo()
    smtp.login(username, password)
PYEOF
  exec {smtp_preflight_pass_fd}<&-

  log "Ensuring PayPal OAuth, webhook identity, and provisioning events"
  local paypal_base access_token webhook_json webhooks_json webhook_id webhook_url webhook_host
  local required_names_json required_events_json create_payload patch_payload previous_webhook_id
  if [[ "${PAYPAL_MODE:-live}" == "sandbox" ]]; then
    paypal_base="https://api-m.sandbox.paypal.com"
  else
    paypal_base="https://api-m.paypal.com"
  fi
  access_token="$(curl_paypal_oauth "${PAYPAL_CLIENT_ID}" "${PAYPAL_CLIENT_SECRET}" \
    -fsS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
    -H 'Accept: application/json' -H 'Accept-Language: en_US' \
    -d 'grant_type=client_credentials' "${paypal_base}/v1/oauth2/token" | jq -er '.access_token')"
  webhook_url="${PAYPAL_WEBHOOK_URL:-$PAYPAL_WEBHOOK_URL_DEFAULT}"
  [[ "${webhook_url}" =~ ^https://[A-Za-z0-9.-]+/webhook/paypal$ ]] || {
    err "PAYPAL_WEBHOOK_URL must be a path-exact HTTPS hostname ending in /webhook/paypal."
    return 1
  }
  webhook_host="${webhook_url#https://}"
  webhook_host="${webhook_host%%/*}"
  valid_dns_hostname "${webhook_host}" || {
    err "PAYPAL_WEBHOOK_URL must use a DNS hostname, not an IP literal."
    return 1
  }
  required_names_json='[
    "BILLING.SUBSCRIPTION.ACTIVATED",
    "BILLING.SUBSCRIPTION.UPDATED",
    "BILLING.SUBSCRIPTION.RE-ACTIVATED",
    "BILLING.SUBSCRIPTION.CANCELLED",
    "BILLING.SUBSCRIPTION.SUSPENDED",
    "BILLING.SUBSCRIPTION.EXPIRED",
    "BILLING.SUBSCRIPTION.PAYMENT.FAILED",
    "PAYMENT.SALE.COMPLETED",
    "PAYMENT.SALE.REFUNDED",
    "PAYMENT.SALE.REVERSED",
    "PAYMENT.SALE.DENIED",
    "PAYMENT.CAPTURE.COMPLETED",
    "PAYMENT.CAPTURE.DENIED",
    "PAYMENT.CAPTURE.DECLINED",
    "PAYMENT.CAPTURE.REFUNDED",
    "PAYMENT.CAPTURE.REVERSED"
  ]'
  required_events_json="$(jq -cn --argjson names "${required_names_json}" '$names | map({name:.})')"
  webhooks_json="$(curl_bearer "${access_token}" -fsS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
    "${paypal_base}/v1/notifications/webhooks")"
  webhook_id="$(jq -r --arg url "${webhook_url}" \
    'first(.webhooks[]? | select(.url == $url) | .id) // empty' <<<"${webhooks_json}")"
  previous_webhook_id="${PAYPAL_WEBHOOK_ID:-}"

  if [[ -z "${webhook_id}" ]]; then
    [[ "${PAYPAL_WEBHOOK_AUTO_ENSURE:-$PAYPAL_WEBHOOK_AUTO_ENSURE_DEFAULT}" == "1" ]] || {
      err "No PayPal webhook exists for ${webhook_url}, and automatic ensure is disabled."
      return 1
    }
    create_payload="$(jq -cn --arg url "${webhook_url}" --argjson events "${required_events_json}" \
      '{url:$url,event_types:$events}')"
    webhook_json="$(curl_bearer "${access_token}" -fsS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
      -X POST -H 'Content-Type: application/json' \
      --data "${create_payload}" "${paypal_base}/v1/notifications/webhooks")"
    webhook_id="$(jq -er --arg url "${webhook_url}" 'select(.url == $url) | .id' <<<"${webhook_json}")"
    log "Created the missing PayPal provisioning webhook."
  else
    webhook_json="$(curl_bearer "${access_token}" -fsS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
      "${paypal_base}/v1/notifications/webhooks/${webhook_id}")"
    if ! jq -e --argjson required "${required_names_json}" \
      '([.event_types[].name] as $actual | (($required - $actual) | length) == 0)' \
      <<<"${webhook_json}" >/dev/null; then
      [[ "${PAYPAL_WEBHOOK_AUTO_ENSURE:-$PAYPAL_WEBHOOK_AUTO_ENSURE_DEFAULT}" == "1" ]] || {
        err "The PayPal webhook is missing required provisioning events, and automatic ensure is disabled."
        return 1
      }
      patch_payload="$(jq -cn --argjson events "${required_events_json}" \
        '[{op:"replace",path:"/event_types",value:$events}]')"
      curl_bearer "${access_token}" -fsS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
        -X PATCH -H 'Content-Type: application/json' \
        --data "${patch_payload}" "${paypal_base}/v1/notifications/webhooks/${webhook_id}" >/dev/null
      log "Repaired the PayPal provisioning event subscriptions."
    fi
  fi

  webhook_json="$(curl_bearer "${access_token}" -fsS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
    "${paypal_base}/v1/notifications/webhooks/${webhook_id}")"
  jq -e --arg id "${webhook_id}" --arg url "${webhook_url}" --argjson required "${required_names_json}" '
    .id == $id and
    .url == $url and
    ([.event_types[].name] as $actual | (($required - $actual) | length) == 0)
  ' <<<"${webhook_json}" >/dev/null || {
    err "Configured PayPal webhook URL or event subscriptions do not match the provisioning contract."
    return 1
  }
  PAYPAL_WEBHOOK_ID="${webhook_id}"
  export PAYPAL_WEBHOOK_ID
  if [[ "${previous_webhook_id}" != "${webhook_id}" ]]; then
    # IA-CP-09: replace, never append. write_env already wrote this key, so an
    # append left two PAYPAL_WEBHOOK_ID lines in both runtime files.
    replace_runtime_env_kv PAYPAL_WEBHOOK_ID "${webhook_id}"
    systemctl restart wins-hub.service
    for _ in $(seq 1 30); do
      curl -A "${WINS_HEALTH_USER_AGENT:-$WINS_HEALTH_USER_AGENT_DEFAULT}" -fsS --connect-timeout 2 --max-time 5 http://127.0.0.1:8000/healthz >/dev/null 2>&1 && break
      sleep 1
    done
    curl -A "${WINS_HEALTH_USER_AGENT:-$WINS_HEALTH_USER_AGENT_DEFAULT}" -fsS --connect-timeout 2 --max-time 5 http://127.0.0.1:8000/healthz >/dev/null
  fi
}

append_runtime_env_kv() {
  local key="$1" value="$2" file escaped
  [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ && "${value}" != *$'\n'* && "${value}" != *$'\r'* ]] || return 1
  # ${LEGACY_ENV_FILE} sits in ${APP_DIR}, which the hub app can write; a link
  # there was planted, so nothing is appended through it.
  if [[ -L "${LEGACY_ENV_FILE}" ]]; then
    echo "[ERR] ${LEGACY_ENV_FILE} is a symlink; refusing to write the runtime env through it." >&2
    return 1
  fi
  # Must NOT be double-quoted: inside "${value//\'/...}" bash's double-quote
  # backslash rules leave the escaping backslashes in the *result* (proven by
  # tools/test_deployment_env_kv_quoting.py), corrupting the value and, once
  # it contains an unbalanced quote, making the env file fail to `source`.
  # Assignment RHS is exempt from word-splitting/globbing either way.
  escaped=${value//\'/\'\"\'\"\'}
  for file in "${ENV_FILE}" "${LEGACY_ENV_FILE}"; do
    printf "%s='%s'\n" "${key}" "${escaped}" >> "${file}"
    chmod 600 "${file}"
  done
}

replace_runtime_env_kv() {
  # Replace KEY=... in the live runtime files instead of appending a second
  # line. append_runtime_env_kv is last-wins-on-source; since IA-CP-09 no
  # deploy path calls it (the webhook-id auto-ensure and the Access
  # service-token writer both replace). Commerce apply must not grow
  # duplicate PAYPAL_* lines on every run.
  local key="$1" value="$2" file escaped content line
  [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ && "${value}" != *$'\n'* && "${value}" != *$'\r'* ]] || {
    echo "[ERR] Refusing to replace an invalid runtime environment key: ${key}" >&2
    return 1
  }
  # ${LEGACY_ENV_FILE} sits in ${APP_DIR}, which the hub app can write, and
  # atomic_replace_file follows a link (for the vault's ${ENV_FILE}). No step
  # links the mirror, so a link there was planted: refuse before either file
  # is rewritten, rather than read and write every hub secret through it.
  if [[ -L "${LEGACY_ENV_FILE}" ]]; then
    echo "[ERR] ${LEGACY_ENV_FILE} is a symlink; refusing to write the runtime env through it." >&2
    return 1
  fi
  escaped=${value//\'/\'\"\'\"\'}
  for file in "${ENV_FILE}" "${LEGACY_ENV_FILE}"; do
    [[ -f "${file}" ]] || continue
    content=""
    while IFS= read -r line || [[ -n "${line}" ]]; do
      [[ "${line}" == "${key}="* ]] && continue
      content+="${line}"$'\n'
    done < "${file}"
    content+="${key}='${escaped}'"$'\n'
    atomic_replace_file "${file}" "${content}" 600
  done
}

cloudflare_access_shell_json() {
  local method="$1" url="$2" payload="${3:-}" token header_file response status body
  token="${CLOUDFLARE_ACCESS_API_TOKEN:-$CLOUDFLARE_ACCESS_API_TOKEN_DEFAULT}"
  [[ -n "${token}" ]] || { err "CLOUDFLARE_ACCESS_API_TOKEN is missing."; return 1; }
  header_file="$(mktemp "${WINS_RUNTIME_DIR:-/run}/wins-cf-access-headers.XXXXXX")"
  chmod 600 "${header_file}"
  printf 'Authorization: Bearer %s\nAccept: application/json\nContent-Type: application/json\n' "${token}" > "${header_file}"
  if [[ -n "${payload}" ]]; then
    response="$(curl -sS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
      --request "${method}" --header "@${header_file}" --data-binary "${payload}" \
      --write-out $'\n%{http_code}' "${url}")" || {
        rm -f "${header_file}"
        err "Cloudflare Access API transport failed."
        return 1
      }
  else
    response="$(curl -sS --retry 3 --retry-all-errors --connect-timeout 10 --max-time 30 \
      --request "${method}" --header "@${header_file}" \
      --write-out $'\n%{http_code}' "${url}")" || {
        rm -f "${header_file}"
        err "Cloudflare Access API transport failed."
        return 1
      }
  fi
  rm -f "${header_file}"
  status="${response##*$'\n'}"
  body="${response%$'\n'*}"
  [[ "${status}" =~ ^2[0-9][0-9]$ ]] || {
    err "Cloudflare Access API returned HTTP ${status}."
    return 1
  }
  jq -e '.success == true' >/dev/null 2>&1 <<<"${body}" || {
    err "Cloudflare Access API rejected the requested operation."
    return 1
  }
  printf '%s' "${body}"
}

ensure_cloudflare_access_service_token() {
  [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]] || return 0
  [[ "${REQUIRE_CLOUDFLARE_ACCESS:-$REQUIRE_CLOUDFLARE_ACCESS_DEFAULT}" == "1" ]] || return 0

  local account name duration api listing match token_uuid client_id client_secret response
  account="${CLOUDFLARE_TUNNEL_ACCOUNT_ID:-${CLOUDFLARE_WINS_ACCOUNT_ID:-$CLOUDFLARE_TUNNEL_ACCOUNT_ID_DEFAULT}}"
  name="${CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME:-$CLOUDFLARE_ACCESS_SERVICE_TOKEN_NAME_DEFAULT}"
  duration="${CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION:-$CLOUDFLARE_ACCESS_SERVICE_TOKEN_DURATION_DEFAULT}"
  token_uuid="${CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID:-$CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID_DEFAULT}"
  client_id="${TUNNEL_SERVICE_TOKEN_ID:-$TUNNEL_SERVICE_TOKEN_ID_DEFAULT}"
  client_secret="${TUNNEL_SERVICE_TOKEN_SECRET:-$TUNNEL_SERVICE_TOKEN_SECRET_DEFAULT}"
  api="https://api.cloudflare.com/client/v4/accounts/${account}/access/service_tokens"

  listing="$(cloudflare_access_shell_json GET "${api}?per_page=1000")" || return 1
  if [[ -n "${token_uuid}" ]]; then
    match="$(jq -c --arg id "${token_uuid}" '.result | map(select(.id == $id)) | first // empty' <<<"${listing}")"
  elif [[ -n "${client_id}" ]]; then
    match="$(jq -c --arg client_id "${client_id}" '.result | map(select(.client_id == $client_id)) | first // empty' <<<"${listing}")"
  else
    match="$(jq -c --arg name "${name}" '.result | map(select(.name == $name)) | sort_by(.created_at // "") | last // empty' <<<"${listing}")"
  fi

  if [[ -n "${match}" ]]; then
    token_uuid="$(jq -r '.id // empty' <<<"${match}")"
    local provider_client_id
    provider_client_id="$(jq -r '.client_id // empty' <<<"${match}")"
    if [[ -n "${client_id}" && "${client_id}" != "${provider_client_id}" ]]; then
      err "Configured Access service-token client ID does not match Cloudflare."
      return 1
    fi
    client_id="${provider_client_id}"
    if [[ -z "${client_secret}" ]]; then
      # Cloudflare shows the secret only once. Rotating an existing token is
      # the only safe noninteractive recovery when the local secret was lost.
      # Fleet reset TP-H3: say so where it happens. The rotation invalidates
      # the secret every earlier copy of the runtime file holds.
      warn "Rotating the Cloudflare Access service token '${name}': the previous secret is now invalid. A later state restore of ${ENV_FILE} must keep THIS run's TUNNEL_SERVICE_TOKEN_SECRET, or every management SSH to every node fails. To avoid the rotation on a reinstall, restore ${ENV_FILE} before the run or carry TUNNEL_SERVICE_TOKEN_ID and TUNNEL_SERVICE_TOKEN_SECRET in ${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}."
      response="$(cloudflare_access_shell_json POST "${api}/${token_uuid}/rotate")" || return 1
      client_id="$(jq -r '.result.client_id // empty' <<<"${response}")"
      client_secret="$(jq -r '.result.client_secret // empty' <<<"${response}")"
    fi
    cloudflare_access_shell_json POST "${api}/${token_uuid}/refresh" >/dev/null || return 1
  else
    [[ -z "${client_id}" && -z "${client_secret}" ]] || {
      err "Configured Access service-token credentials do not exist in the selected Cloudflare account."
      return 1
    }
    response="$(cloudflare_access_shell_json POST "${api}" "$(jq -cn --arg name "${name}" --arg duration "${duration}" '{name:$name,duration:$duration}')")" || return 1
    token_uuid="$(jq -r '.result.id // empty' <<<"${response}")"
    client_id="$(jq -r '.result.client_id // empty' <<<"${response}")"
    client_secret="$(jq -r '.result.client_secret // empty' <<<"${response}")"
  fi

  [[ "${token_uuid}" =~ ^[A-Fa-f0-9-]{36}$ && "${client_id}" == *.access && ${#client_secret} -ge 32 ]] || {
    err "Cloudflare returned an invalid Access service-token credential set."
    return 1
  }
  CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID="${token_uuid}"
  TUNNEL_SERVICE_TOKEN_ID="${client_id}"
  TUNNEL_SERVICE_TOKEN_SECRET="${client_secret}"
  export CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID TUNNEL_SERVICE_TOKEN_ID TUNNEL_SERVICE_TOKEN_SECRET
  # IA-CP-09: replace, never append. write_env already wrote all three keys,
  # so an append left a second copy of each (the secret included) in both
  # runtime files on every run.
  replace_runtime_env_kv CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID "${token_uuid}"
  replace_runtime_env_kv TUNNEL_SERVICE_TOKEN_ID "${client_id}"
  replace_runtime_env_kv TUNNEL_SERVICE_TOKEN_SECRET "${client_secret}"
  # FLEET1 Turn 3 (Claude seat, D7): the preflight compared the wallet RPC
  # token with TUNNEL_SERVICE_TOKEN_* before this run loaded, created or rotated
  # them, which on a fresh run compares against nothing. Compare again with
  # the final management token, after it is persisted (a rotated secret is
  # never lost by this refusal).
  if [[ "${MONERO_WALLET_RPC_CF_ACCESS:-0}" == "1" ]] \
      && [[ "${MONERO_WALLET_RPC_CF_ACCESS_CLIENT_ID:-}" == "${client_id}" \
            || "${MONERO_WALLET_RPC_CF_ACCESS_CLIENT_SECRET:-}" == "${client_secret}" ]]; then
    err "MONERO_WALLET_RPC_CF_ACCESS_CLIENT_ID or _SECRET is the management service token; the wallet RPC hostname needs its own token."
    return 1
  fi
  log "Cloudflare Access management service token is present and refreshed."
}

package_manager_busy() {
  local lock_file
  if command -v fuser >/dev/null 2>&1; then
    for lock_file in /var/lib/dpkg/lock-frontend /var/lib/dpkg/lock /var/cache/apt/archives/lock /var/lib/apt/lists/lock; do
      fuser "${lock_file}" >/dev/null 2>&1 && return 0
    done
  fi
  pgrep -x '(apt|apt-get|dpkg)' >/dev/null 2>&1
}

wait_for_cloud_init() {
  command -v cloud-init >/dev/null 2>&1 || return 0
  local timeout_seconds="${CLOUD_INIT_WAIT_SECONDS:-900}" output="" status=0
  log "Waiting for provider cloud-init provisioning to finish"
  output="$(timeout "${timeout_seconds}" cloud-init status --wait 2>&1)" || status=$?
  if ((status == 0)); then
    return 0
  fi
  if grep -Eq '^status:[[:space:]]*(done|disabled)$' <<<"${output}"; then
    warn "cloud-init completed with a degraded/nonzero status; review 'cloud-init status --long' after deployment"
    return 0
  fi
  err "cloud-init did not reach a completed state within ${timeout_seconds}s. Inspect 'cloud-init status --long' before retrying."
  return 1
}

wait_for_fail2ban() {
  local attempt
  for attempt in {1..15}; do
    fail2ban-client ping >/dev/null 2>&1 && fail2ban-client status sshd >/dev/null 2>&1 && return 0
    sleep 1
  done
  err "Fail2Ban did not expose a healthy sshd jail within 15 seconds."
  return 1
}

wait_for_suricata() {
  local attempt stable=0 restarts="" previous_restarts=""
  for attempt in {1..90}; do
    if systemctl is-active --quiet suricata.service \
      && suricatasc -c uptime >/dev/null 2>&1; then
      restarts="$(systemctl show suricata.service -p NRestarts --value 2>/dev/null || printf 'unknown')"
      if [[ "${restarts}" == "${previous_restarts}" ]]; then
        stable=$((stable + 1))
      else
        stable=0
        previous_restarts="${restarts}"
      fi
      ((stable >= 10)) && return 0
    else
      stable=0
    fi
    sleep 1
  done
  err "Suricata did not remain ready with a responsive command socket for 10 consecutive seconds."
  systemctl status suricata.service --no-pager -l || true
  return 1
}

wait_for_package_manager() {
  local timeout="${APT_LOCK_WAIT_SECONDS:-300}" elapsed=0
  while package_manager_busy; do
    if ((elapsed >= timeout)); then
      err "Ubuntu package manager remained busy for ${timeout}s. Wait for provider/cloud-init updates to finish, then rerun the script."
      return 1
    fi
    ((elapsed == 0)) && log "Waiting for provider/cloud-init package updates to finish"
    sleep 5
    elapsed=$((elapsed + 5))
  done
}

recover_package_state_for_retry() {
  wait_for_package_manager
  if dpkg --force-confdef --force-confold --configure -a; then
    return 0
  fi
  warn "dpkg configuration is incomplete; attempting one bounded dependency repair before retrying"
  "${APT_GET[@]}" -f install -y || return 1
  dpkg --force-confdef --force-confold --configure -a
}

apt_retry() {
  local attempt
  for attempt in 1 2 3; do
    wait_for_package_manager
    if "$@"; then
      return 0
    fi
    if ((attempt == 3)); then
      break
    fi
    warn "Package command failed (attempt ${attempt}/3); repairing package state before retry"
    recover_package_state_for_retry || \
      warn "Package-state recovery was incomplete; the bounded retry will still continue"
    sleep $((attempt * 5))
  done
  err "Package command failed after three attempts: $*"
  return 1
}

repair_package_state() {
  wait_for_package_manager
  remove_conflicting_suricata_update_package
  if ! dpkg --force-confdef --force-confold --configure -a; then
    warn "dpkg configuration was incomplete; repairing dependencies"
    apt_retry "${APT_GET[@]}" -f install -y
    dpkg --force-confdef --force-confold --configure -a
  fi
}

suricata_repository_present() {
  grep -RqsF 'ppa.launchpadcontent.net/oisf/suricata-stable/ubuntu' \
    /etc/apt/sources.list /etc/apt/sources.list.d 2>/dev/null
}

remove_conflicting_suricata_update_package() {
  suricata_repository_present || return 0
  [[ "$(dpkg-query -W -f='${db:Status-Abbrev}' suricata-update 2>/dev/null || true)" == "ii " ]] || return 0

  local removal_plan
  local -a removal_packages=()
  removal_plan="$("${APT_GET[@]}" --simulate remove suricata-update)"
  mapfile -t removal_packages < <(awk '/^Remv / {print $2}' <<<"${removal_plan}")
  if (( ${#removal_packages[@]} != 1 )) || [[ "${removal_packages[0]}" != "suricata-update" ]]; then
    err "Unexpected Suricata migration removal plan; refusing package changes."
    printf '%s\n' "${removal_plan}" >&2
    return 1
  fi
  apt_retry "${APT_GET[@]}" remove -y suricata-update
}

ensure_suricata_stable_repository() {
  log "Enabling the official OISF Suricata stable repository"
  apt_retry "${APT_GET[@]}" install -y software-properties-common
  if ! suricata_repository_present; then
    add-apt-repository -y -n ppa:oisf/suricata-stable
  fi
  apt_retry "${APT_GET[@]}" update -y
  apt-cache policy suricata | grep -E 'https?://ppa\.launchpad(content)?\.net/oisf/suricata-stable/ubuntu' >/dev/null || {
    err "The official OISF Suricata stable repository is not an eligible package source."
    return 1
  }

  # OISF Suricata 8 bundles suricata-update. Ubuntu 24.04 ships the same path
  # in a separate package, and leaving that package installed makes dpkg abort
  # while unpacking the OISF build. Permit only this exact migration removal.
  remove_conflicting_suricata_update_package
}

verify_suricata_package() {
  local version oldest
  version="$(suricata -V 2>&1 | awk '/^This is Suricata version / {print $5; exit}')"
  [[ "${version}" =~ ^[0-9]+(\.[0-9]+){2}$ ]] || {
    err "Unable to determine the installed Suricata release version."
    return 1
  }
  oldest="$(printf '%s\n%s\n' "${SURICATA_MIN_VERSION_DEFAULT}" "${version}" | sort -V | head -n 1)"
  [[ "${oldest}" == "${SURICATA_MIN_VERSION_DEFAULT}" ]] || {
    err "Suricata ${version} is older than required stable ${SURICATA_MIN_VERSION_DEFAULT}."
    return 1
  }
  [[ -x /usr/bin/suricata-update ]] || {
    err "The OISF Suricata package did not install suricata-update."
    return 1
  }
  dpkg-query -S /usr/bin/suricata-update | grep -x 'suricata: /usr/bin/suricata-update' >/dev/null || {
    err "suricata-update is not owned by the reviewed OISF Suricata package."
    return 1
  }
  suricata --build-info | grep -Ei 'NFQ' >/dev/null
}

enable_required_ssh_service() {
  local unit
  for unit in ssh.service sshd.service; do
    if systemctl enable --now "${unit}" 2>/dev/null && \
       systemctl is-active --quiet "${unit}"; then
      log "SSH service is enabled and active via ${unit}"
      return 0
    fi
  done
  err "Neither ssh.service nor sshd.service could be enabled and verified active."
  return 1
}

# WINS-FWOS-BLOCK-BEGIN (byte-identical in the data-plane, control-plane and Core installers)
# ---------------------------------------------------------------------------
# Firmware, CPU microcode and OS currency (owner decision 2026-10-06: "bump the
# firmware and OS packages too"). The package upgrade that apt_install already
# runs brings every non-held package current, kernel included. This block adds
# what that upgrade cannot say or do:
#   * linux-firmware and the vendor microcode package are installed only where
#     they can have an effect, and the reason is recorded where they cannot.
#     The kernel's own loader (arch/x86/kernel/cpu/microcode/core.c) stays
#     disabled when CPUID.1:ECX[31] (the hypervisor bit) is set, so a VPS guest
#     has no /sys/devices/system/cpu/cpu0/microcode directory, prints no
#     "microcode:" kernel line, and cannot load anything. The decision rests on
#     that sysfs directory, not on the word "VM".
#   * a reboot that a kernel or microcode update needs is turned into the
#     standard /var/run/reboot-required flag, which pause_for_required_reboot
#     already turns into a recorded boot-id marker and exit status 75. This
#     block never reboots the host and never returns 75 itself.
#   * a state record (key=value, root 0600, same directory as the
#     <role>.reboot-required marker) says what was decided and why.
# fwupd is never installed or run to apply anything: it is recorded read-only.
# Test hooks (defaults are the real paths): WINS_FWOS_CPUINFO, WINS_FWOS_SYS_CPU_DIR,
# WINS_FWOS_DMI_DIR, WINS_FWOS_BOOT_DIR, WINS_FWOS_PROC_STAT, WINS_FWOS_STATE_DIR
# (falls back to WINSVPN_DEPLOY_STATE_DIR), plus WINSVPN_REBOOT_REQUIRED_FILE and
# WINSVPN_BOOT_ID_FILE, which pause_for_required_reboot already honours.
# Knobs: WINS_LINUX_FIRMWARE_MODE=auto|all|off (default auto: install on bare
# metal, keep an installed copy current on a VM, otherwise record not-applicable)
# and WINS_APT_INCLUDE_PHASED=1|0 (default 1: one extra upgrade pass that also
# takes Ubuntu phased updates, which apt-get upgrade otherwise defers; security
# updates are never phased).
# ---------------------------------------------------------------------------
wins_fwos_clean() {
  printf '%s' "$*" | tr -c 'A-Za-z0-9._:+/ -' '_' | tr ' ' '_' | cut -c1-80
}

wins_fwos_timeout() {
  local seconds="$1"
  shift
  if command -v timeout >/dev/null 2>&1; then
    timeout "${seconds}" "$@"
  else
    "$@"
  fi
}

wins_fwos_cpuinfo_field() {
  awk -F: -v key="$1" '$1 ~ "^" key "[[:space:]]*$" { gsub(/^[[:space:]]+|[[:space:]]+$/, "", $2); print $2; exit }' \
    "${WINS_FWOS_CPUINFO:-/proc/cpuinfo}" 2>/dev/null || true
}

wins_fwos_hypervisor_flag() {
  grep -Eq '^flags[[:space:]]*:.*[[:space:]]hypervisor([[:space:]]|$)' "${WINS_FWOS_CPUINFO:-/proc/cpuinfo}" 2>/dev/null
}

# Prints bare-metal, vm:<technology> or container:<technology>.
wins_fwos_virt_class() {
  local tech=""
  if command -v systemd-detect-virt >/dev/null 2>&1; then
    tech="$(systemd-detect-virt --container 2>/dev/null || true)"
    if [[ -n "${tech}" && "${tech}" != none ]]; then
      printf 'container:%s' "$(wins_fwos_clean "${tech}")"
      return 0
    fi
    tech="$(systemd-detect-virt --vm 2>/dev/null || true)"
    if [[ -n "${tech}" && "${tech}" != none ]]; then
      printf 'vm:%s' "$(wins_fwos_clean "${tech}")"
      return 0
    fi
    printf 'bare-metal'
    return 0
  fi
  if wins_fwos_hypervisor_flag; then
    printf 'vm:unknown'
  else
    printf 'bare-metal'
  fi
}

wins_fwos_dmi_value() {
  local file="${WINS_FWOS_DMI_DIR:-/sys/class/dmi/id}/$1" value=""
  [[ -r "${file}" ]] && value="$(head -n 1 "${file}" 2>/dev/null || true)"
  wins_fwos_clean "${value:-unknown}"
}

# Prints the installed version of a package, or nothing when it is not installed.
wins_fwos_pkg_version() {
  local status
  status="$(dpkg-query -W -f='${db:Status-Abbrev}' "$1" 2>/dev/null || true)"
  [[ "${status}" == "ii " ]] || return 0
  dpkg-query -W -f='${Version}' "$1" 2>/dev/null || true
}

wins_fwos_state_dir() {
  printf '%s' "${WINS_FWOS_STATE_DIR:-${WINSVPN_DEPLOY_STATE_DIR:-/var/lib/winsvpn-deployment}}"
}

wins_fwos_state_value() {
  local file
  file="$(wins_fwos_state_dir)/firmware-os.state"
  [[ -r "${file}" && ! -L "${file}" ]] || return 0
  sed -n "s/^$1=//p" "${file}" | head -n 1 || true
}

# Prints "<decision> <package> <evidence>" on one line. decision is install or
# not-applicable. The loader is active only when the kernel created
# /sys/devices/system/cpu/cpu0/microcode (or the late-load reload file).
wins_fwos_microcode_plan() {
  local arch="$1" vendor="$2" virt="$3" cpu_dir="${WINS_FWOS_SYS_CPU_DIR:-/sys/devices/system/cpu}"
  local loader=inactive hv=0
  [[ -e "${cpu_dir}/cpu0/microcode/version" || -e "${cpu_dir}/microcode/reload" ]] && loader=active
  wins_fwos_hypervisor_flag && hv=1
  if [[ "${arch}" != amd64 ]]; then
    printf 'not-applicable - arch=%s,x86_microcode_packages_are_amd64_only' "$(wins_fwos_clean "${arch}")"
    return 0
  fi
  if [[ "${loader}" != active ]]; then
    printf 'not-applicable - loader=inactive,virt=%s,hypervisor_flag=%s,no_cpu0_microcode_sysfs' "${virt}" "${hv}"
    return 0
  fi
  case "${vendor}" in
    GenuineIntel) printf 'install intel-microcode loader=active,virt=%s,hypervisor_flag=%s' "${virt}" "${hv}" ;;
    AuthenticAMD) printf 'install amd64-microcode loader=active,virt=%s,hypervisor_flag=%s' "${virt}" "${hv}" ;;
    *) printf 'not-applicable - cpu_vendor=%s' "$(wins_fwos_clean "${vendor:-unknown}")" ;;
  esac
}

# Prints key=value lines. $1 is the microcode package ("" when none applies).
# Kernel and microcode state come from needrestart's batch mode when it is
# installed (needrestart.pl: KSTA 1 current, 2 ABI upgrade pending, 3 version
# upgrade pending; UCSTA 1 current, 2 obsolete, 0 unknown, and it skips the
# microcode check inside a VM). Without needrestart the kernel is compared with
# the newest /boot/vmlinuz of the same flavour, and microcode counts as pending
# when dpkg changed the package's files after this boot (dpkg 1.19.3+).
wins_fwos_reboot_evidence() {
  local pkg="${1:-}" required_file="${WINSVPN_REBOOT_REQUIRED_FILE:-/var/run/reboot-required}"
  local boot_dir="${WINS_FWOS_BOOT_DIR:-/boot}" stat_file="${WINS_FWOS_PROC_STAT:-/proc/stat}"
  local running expected="" kernel_state=unknown ucode_state=unknown ucode_method=none
  local out="" ksta="" ucsta="" flavour newest changed btime file_flag=0 required=0 reasons=""
  running="$(uname -r)"
  [[ -e "${required_file}" ]] && file_flag=1
  if command -v needrestart >/dev/null 2>&1; then
    out="$(wins_fwos_timeout 120 needrestart -b -k -w -r l 2>/dev/null || true)"
    ksta="$(awk -F': ' '$1 == "NEEDRESTART-KSTA" { print $2; exit }' <<<"${out}")"
    expected="$(awk -F': ' '$1 == "NEEDRESTART-KEXP" { print $2; exit }' <<<"${out}")"
    ucsta="$(awk -F': ' '$1 == "NEEDRESTART-UCSTA" { print $2; exit }' <<<"${out}")"
    case "${ksta}" in
      1) kernel_state=current ;;
      2) kernel_state=abi_upgrade ;;
      3) kernel_state=version_upgrade ;;
    esac
    case "${ucsta}" in
      1) ucode_state=current; ucode_method=needrestart ;;
      2) ucode_state=obsolete; ucode_method=needrestart ;;
    esac
  fi
  if [[ "${kernel_state}" == unknown ]]; then
    flavour="${running##*-}"
    newest="$(ls -1 "${boot_dir}"/vmlinuz-*-"${flavour}" 2>/dev/null | sed 's#.*/vmlinuz-##' | sort -V | tail -n 1 || true)"
    if [[ -n "${newest}" ]]; then
      expected="${newest}"
      if [[ "${newest}" == "${running}" || "$(printf '%s\n%s\n' "${running}" "${newest}" | sort -V | tail -n 1)" == "${running}" ]]; then
        kernel_state=current
      else
        kernel_state=version_upgrade
      fi
    fi
  fi
  if [[ "${ucode_state}" == unknown && -n "${pkg}" ]]; then
    changed="$(dpkg-query -W -f='${db-fsys:Last-Modified}' "${pkg}" 2>/dev/null || true)"
    btime="$(awk '$1 == "btime" { print $2; exit }' "${stat_file}" 2>/dev/null || true)"
    if [[ "${changed}" =~ ^[0-9]+$ && "${btime}" =~ ^[0-9]+$ ]]; then
      ucode_method=dpkg-mtime
      if (( changed > btime )); then ucode_state=obsolete; else ucode_state=current; fi
    fi
  fi
  [[ "${file_flag}" == 1 ]] && reasons="${reasons:+${reasons},}reboot-required-file"
  case "${kernel_state}" in abi_upgrade|version_upgrade) reasons="${reasons:+${reasons},}kernel" ;; esac
  [[ "${ucode_state}" == obsolete ]] && reasons="${reasons:+${reasons},}microcode"
  [[ -n "${reasons}" ]] && required=1
  printf 'running_kernel=%s\n' "$(wins_fwos_clean "${running}")"
  printf 'expected_kernel=%s\n' "$(wins_fwos_clean "${expected:-unknown}")"
  printf 'kernel_state=%s\n' "${kernel_state}"
  printf 'microcode_state=%s\n' "${ucode_state}"
  printf 'microcode_method=%s\n' "${ucode_method}"
  printf 'reboot_required=%s\n' "${required}"
  printf 'reboot_reasons=%s\n' "${reasons:-none}"
}

# Prints the first installed kernel metapackage (a linux-image-* name without a
# release number, or a linux-generic or linux-virtual family name), else none.
wins_fwos_kernel_track() {
  local track
  track="$(dpkg-query -W -f='${db:Status-Abbrev} ${Package}\n' 'linux-image-*' 'linux-generic*' 'linux-virtual*' 2>/dev/null \
    | awk '$1 == "ii" && $2 !~ /^linux-image-(unsigned-)?[0-9]/ && $2 !~ /-dbgsym$/ { print $2; exit }' || true)"
  printf '%s' "${track:-none}"
}

# Names of packages a full upgrade that includes phased updates would still change.
# Returns 1 and prints nothing when the simulation itself fails, so a failed
# "apt-get -s" is never read as "nothing upgradable". $1=1 also counts phased
# updates (default 0: respect Ubuntu's phasing, as the weekly upgrade does).
wins_fwos_residual_upgrades() {
  local include_phased="${1:-0}" simulation
  if [[ "${include_phased}" == 1 ]]; then
    simulation="$("${APT_GET[@]}" -s -o APT::Get::Always-Include-Phased-Updates=true full-upgrade 2>/dev/null)" || return 1
  else
    simulation="$("${APT_GET[@]}" -s full-upgrade 2>/dev/null)" || return 1
  fi
  awk '/^Inst / { print $2 }' <<<"${simulation}" | sort -u | paste -sd, -
}

wins_fwos_held_packages() {
  local held
  held="$(apt-mark showhold 2>/dev/null)" || return 1
  sort -u <<<"${held}" | paste -sd, -
}

wins_fwos_write_state() {
  local role="$1" dir file tmp
  dir="$(wins_fwos_state_dir)"
  file="${dir}/firmware-os.state"
  install -d -o root -g root -m 0700 "${dir}" || return 1
  tmp="$(mktemp "${file}.XXXXXX")" || return 1
  {
    printf 'schema=1\n'
    printf 'role=%s\n' "${role}"
    printf 'recorded_at_utc=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    cat
  } > "${tmp}" || { rm -f -- "${tmp}"; return 1; }
  chown root:root "${tmp}" || { rm -f -- "${tmp}"; return 1; }
  chmod 0600 "${tmp}" || { rm -f -- "${tmp}"; return 1; }
  mv -f -- "${tmp}" "${file}" || { rm -f -- "${tmp}"; return 1; }
}

ensure_firmware_microcode() {
  local role="${1:-unknown}" arch vendor virt dmi_vendor dmi_product hv=0 rev
  local plan decision package evidence fw_mode fw_decision fw_before fw_after
  local uc_before="" uc_after="" fwupd_state=absent fwupd_devices=0 mc_pkg_field="-"
  local evidence_out reboot_required=0 reboot_reasons=none boot_id="" prior_raised="" prior_reasons=""
  local expected_kernel="" reboot_identity="" prior_identity=""
  local raised_boot_id="" unresolved=none held unexpected_holds="" residual="" kernel_track phased_pass=0
  local include_phased=0 residual_state=unknown held_state=unknown
  local required_file="${WINSVPN_REBOOT_REQUIRED_FILE:-/var/run/reboot-required}" uc_pkg=""
  local boot_id_file="${WINSVPN_BOOT_ID_FILE:-/proc/sys/kernel/random/boot_id}"
  arch="$(dpkg --print-architecture 2>/dev/null || uname -m)"
  vendor="$(wins_fwos_cpuinfo_field vendor_id)"
  virt="$(wins_fwos_virt_class)"
  dmi_vendor="$(wins_fwos_dmi_value sys_vendor)"
  dmi_product="$(wins_fwos_dmi_value product_name)"
  wins_fwos_hypervisor_flag && hv=1
  rev="$(wins_fwos_cpuinfo_field microcode)"
  [[ -r "${boot_id_file}" ]] && boot_id="$(tr -d '[:space:]' < "${boot_id_file}" 2>/dev/null || true)"

  # linux-firmware: kept current everywhere it is installed (the normal upgrade
  # does that); installed here only where a physical device can use it.
  fw_mode="${WINS_LINUX_FIRMWARE_MODE:-auto}"
  case "${fw_mode}" in auto|all|off) ;; *) err "WINS_LINUX_FIRMWARE_MODE must be auto, all or off, not ${fw_mode}."; return 1 ;; esac
  fw_before="$(wins_fwos_pkg_version linux-firmware)"
  case "${fw_mode}:${virt}" in
    off:*) fw_decision=skipped-by-operator ;;
    all:*|auto:bare-metal) fw_decision=install ;;
    *) if [[ -n "${fw_before}" ]]; then fw_decision=present-kept-current; else fw_decision="not-applicable:${virt%%:*}-guest-has-no-physical-device-firmware"; fi ;;
  esac
  if [[ "${fw_decision}" == install ]]; then
    apt_retry "${APT_GET[@]}" install -y --no-install-recommends linux-firmware || return 1
  fi
  fw_after="$(wins_fwos_pkg_version linux-firmware)"

  # CPU microcode: only where the kernel's loader is active.
  plan="$(wins_fwos_microcode_plan "${arch}" "${vendor}" "${virt}")"
  read -r decision package evidence <<<"${plan}"
  if [[ "${decision}" == install ]]; then
    uc_before="$(wins_fwos_pkg_version "${package}")"
    apt_retry "${APT_GET[@]}" install -y --no-install-recommends "${package}" || return 1
    uc_after="$(wins_fwos_pkg_version "${package}")"
    mc_pkg_field="${package}"
    log "CPU microcode: ${package} ${uc_before:-absent} -> ${uc_after:-absent} (${evidence})"
  else
    log "CPU microcode: ${decision} (${evidence}); the package is not installed for show"
  fi

  # fwupd: never installed, never asked to apply anything.
  if command -v fwupdmgr >/dev/null 2>&1; then
    if [[ "${virt}" == bare-metal ]]; then
      fwupd_state=present-readonly
      fwupd_devices="$(wins_fwos_timeout 30 fwupdmgr get-devices --json 2>/dev/null | grep -o '"DeviceId"' | wc -l | tr -d ' ' || true)"
      [[ "${fwupd_devices}" =~ ^[0-9]+$ ]] || fwupd_devices=0
    else
      fwupd_state="present-skipped-${virt%%:*}"
    fi
  fi

  # OS currency: one extra pass for phased updates, then record what is left.
  # A failed "apt-get -s" is recorded as "unknown", never as "none".
  if [[ "${WINS_APT_INCLUDE_PHASED:-1}" != 0 ]]; then
    include_phased=1
    if residual="$(wins_fwos_residual_upgrades 1)"; then
      if [[ -n "${residual}" ]]; then
        phased_pass=1
        log "Phased or deferred updates remain (${residual}); running one upgrade pass that includes phased updates"
        if [[ "${APT_ALLOW_REMOVALS:-0}" == "1" ]]; then
          apt_retry "${APT_GET[@]}" -o APT::Get::Always-Include-Phased-Updates=true full-upgrade -y || return 1
        else
          apt_retry "${APT_GET[@]}" -o APT::Get::Always-Include-Phased-Updates=true upgrade -y --with-new-pkgs || return 1
        fi
      fi
    else
      warn "apt-get -s failed; phased updates were not checked."
    fi
  fi
  if residual="$(wins_fwos_residual_upgrades "${include_phased}")"; then
    residual_state="${residual:-none}"
    [[ -z "${residual}" ]] || warn "Packages still upgradable after the upgrade (kept back, removal needed, or held): ${residual}"
  else
    residual_state=unknown
    warn "apt-get -s failed; the packages still upgradable after the upgrade are unknown."
  fi
  if held="$(wins_fwos_held_packages)"; then
    held_state="${held:-none}"
    unexpected_holds="$(tr ',' '\n' <<<"${held}" | awk '$0 != "" && $0 != "cloudflared"' | paste -sd, - || true)"
    [[ -z "${unexpected_holds}" ]] || warn "Packages other than cloudflared are on hold and will not be upgraded: ${unexpected_holds}"
  else
    held_state=unknown
    unexpected_holds=unknown
    warn "apt-mark showhold failed; the held packages are unknown."
  fi
  kernel_track="$(wins_fwos_kernel_track)"
  [[ "${kernel_track}" != none ]] || warn "No kernel metapackage is installed: apt will never bring a newer kernel than $(uname -r)."

  # Reboot evidence. The flag is raised only for a condition this block derived;
  # if a previous boot already got the same request and the condition survived
  # that reboot, the host is on a kernel the guest cannot change, so it is
  # reported as unresolved rather than raised again (no reboot loop).
  [[ "${decision}" == install ]] && uc_pkg="${package}"
  evidence_out="$(wins_fwos_reboot_evidence "${uc_pkg}")"
  reboot_required="$(sed -n 's/^reboot_required=//p' <<<"${evidence_out}")"
  reboot_reasons="$(sed -n 's/^reboot_reasons=//p' <<<"${evidence_out}")"
  # The identity of what is pending, so a newer kernel or microcode package that
  # arrives after a reboot is a new request and not the one that "survived".
  expected_kernel="$(sed -n 's/^expected_kernel=//p' <<<"${evidence_out}")"
  reboot_identity="${reboot_reasons}|${expected_kernel}|${uc_pkg}=$([[ -z "${uc_pkg}" ]] || wins_fwos_pkg_version "${uc_pkg}")"
  prior_raised="$(wins_fwos_state_value raised_boot_id)"
  prior_reasons="$(wins_fwos_state_value raised_reasons)"
  prior_identity="$(wins_fwos_state_value raised_identity)"
  raised_boot_id="${prior_raised}"
  if [[ "${reboot_required}" == 1 ]]; then
    if [[ ! -e "${required_file}" ]]; then
      if [[ -n "${prior_raised}" && "${prior_raised}" != "${boot_id}" && "${prior_reasons}" == "${reboot_reasons}" && "${prior_identity}" == "${reboot_identity}" ]]; then
        unresolved="${reboot_reasons}"
        warn "A reboot already happened for ${reboot_reasons} and the condition remains; not requesting another (provider-managed kernel or boot entry?)."
      else
        printf '*** System restart required ***\n' > "${required_file}" || {
          err "Could not write ${required_file}; stopping before the required reboot boundary is lost."
          return 1
        }
        printf 'wins-firmware-os:%s\n' "${reboot_reasons}" >> "${required_file}.pkgs" 2>/dev/null || true
        raised_boot_id="${boot_id}"
        prior_reasons="${reboot_reasons}"
        prior_identity="${reboot_identity}"
        log "Reboot required for ${reboot_reasons}; ${required_file} raised for pause_for_required_reboot (this installer never reboots the host)."
      fi
    fi
  else
    # Nothing is pending any more: forget the earlier request so a later,
    # legitimate update can raise the flag again.
    raised_boot_id=""
    prior_reasons=""
    prior_identity=""
  fi

  wins_fwos_write_state "${role}" <<EOF || { err "Could not write the firmware and OS state record under $(wins_fwos_state_dir); stopping so the reboot guard is not lost."; return 1; }
boot_id=${boot_id:-unknown}
arch=$(wins_fwos_clean "${arch}")
virt=${virt}
dmi_vendor=${dmi_vendor}
dmi_product=${dmi_product}
hypervisor_flag=${hv}
cpu_vendor=$(wins_fwos_clean "${vendor:-unknown}")
microcode_running_rev=$(wins_fwos_clean "${rev:-unknown}")
microcode_decision=${decision}
microcode_package=${mc_pkg_field}
microcode_version_before=$(wins_fwos_clean "${uc_before:-none}")
microcode_version_after=$(wins_fwos_clean "${uc_after:-none}")
microcode_evidence=${evidence}
linux_firmware_mode=${fw_mode}
linux_firmware_decision=${fw_decision}
linux_firmware_version=$(wins_fwos_clean "${fw_after:-none}")
fwupd=${fwupd_state}
fwupd_devices=${fwupd_devices}
phased_pass=${phased_pass}
held_packages=${held_state}
unexpected_holds=${unexpected_holds:-none}
upgradable_after=${residual_state}
kernel_track=${kernel_track}
$(sed 's/^reboot_reasons=.*//;/^$/d' <<<"${evidence_out}")
reboot_reasons=${reboot_reasons}
raised_boot_id=${raised_boot_id}
raised_reasons=${prior_reasons}
raised_identity=${prior_identity}
unresolved_after_reboot=${unresolved}
EOF
  return 0
}
# WINS-FWOS-BLOCK-END

apt_install() {
  local zram_enabled="${ENABLE_ZRAM_SWAP:-$ENABLE_ZRAM_SWAP_DEFAULT}"
  log "Installing system packages"
  wait_for_cloud_init
  wait_for_package_manager
  # Keep the package-manager lock deterministic during the initial upgrade, but
  # never leave the host without automatic security patching if a later install
  # step fails. The EXIT trap is cleared only after the service and timers have
  # been restored successfully.
  trap 'configure_unattended_security_updates || true' EXIT
  systemctl stop unattended-upgrades 2>/dev/null || true
  repair_package_state
  apt_retry "${APT_GET[@]}" update -y
  ensure_suricata_stable_repository
  if [[ "${APT_ALLOW_REMOVALS:-0}" == "1" ]]; then
    warn "APT_ALLOW_REMOVALS=1: full-upgrade may remove provider packages; review the APT plan after deployment."
    apt_retry "${APT_GET[@]}" full-upgrade -y
  else
    apt_retry "${APT_GET[@]}" upgrade -y --with-new-pkgs
  fi
  apt_retry "${APT_GET[@]}" install -y \
    curl ca-certificates jq sqlite3 openssl git nginx \
    python3 python3-venv python3-pip python3-full \
    python3-yaml suricata fail2ban \
    wireguard-tools iptables iptables-persistent netfilter-persistent \
    dnsutils net-tools mtr-tiny speedtest-cli iperf3 unzip procps tar gzip pigz cron rclone tzdata openssh-client openssh-server cryptsetup unattended-upgrades systemd-zram-generator kmod \
    age \
    librsvg2-bin
  case "${zram_enabled,,}" in
    1|true|yes|on)
      local kernel_release default_kernel_image default_kernel_release
      local zram_kernel_release zram_kernel_package zram_kernel_candidate
      local -a zram_kernel_releases=() zram_module_packages=()
      kernel_release="$(uname -r)"
      [[ "${kernel_release}" =~ ^[0-9A-Za-z.+_~-]+$ ]] || {
        err "The running kernel release is malformed; refusing zram module installation."
        return 1
      }
      zram_kernel_releases=("${kernel_release}")
      if [[ -e /boot/vmlinuz || -L /boot/vmlinuz ]]; then
        default_kernel_image="$(readlink -f /boot/vmlinuz 2>/dev/null || true)"
        default_kernel_release="${default_kernel_image##*/vmlinuz-}"
        if [[ "${default_kernel_image##*/}" == vmlinuz-* &&
              "${default_kernel_release}" =~ ^[0-9A-Za-z.+_~-]+$ &&
              "${default_kernel_release}" != "${kernel_release}" ]]; then
          zram_kernel_releases+=("${default_kernel_release}")
        fi
      fi
      for zram_kernel_release in "${zram_kernel_releases[@]}"; do
        if ! modinfo -k "${zram_kernel_release}" zram >/dev/null 2>&1; then
          zram_kernel_package="linux-modules-extra-${zram_kernel_release}"
          zram_kernel_candidate="$(apt-cache policy "${zram_kernel_package}" | awk '/^[[:space:]]*Candidate:/ {candidate=$2} END {print candidate}')"
          [[ -n "${zram_kernel_candidate}" && "${zram_kernel_candidate}" != "(none)" ]] || {
            err "Ubuntu package ${zram_kernel_package} is unavailable; zram cannot be enabled safely for ${zram_kernel_release}."
            return 1
          }
          zram_module_packages+=("${zram_kernel_package}")
        fi
      done
      if (( ${#zram_module_packages[@]} > 0 )); then
        apt_retry "${APT_GET[@]}" install -y --no-install-recommends "${zram_module_packages[@]}"
      fi
      for zram_kernel_release in "${zram_kernel_releases[@]}"; do
        depmod -a "${zram_kernel_release}"
        modinfo -k "${zram_kernel_release}" zram >/dev/null 2>&1 || {
          err "The zram module is unavailable for installed kernel ${zram_kernel_release}."
          return 1
        }
      done
      if ! modinfo zram >/dev/null 2>&1; then
        err "The zram module is unavailable after installing the matching Ubuntu kernel package."
        return 1
      fi
      ensure_zram_kept_across_kernel_upgrades || return 1
      ;;
  esac
  ensure_firmware_microcode control || return 1
  verify_suricata_package
  "${APT_GET[@]}" install -y linux-tools-common linux-tools-generic >/dev/null 2>&1 || \
    warn "Optional CPU governor tools are unavailable for this VPS kernel; direct sysfs performance mode will still be attempted"
  enable_required_ssh_service
  run_yabs_benchmark
  configure_unattended_security_updates
  trap - EXIT
}

pause_for_required_reboot() {
  local role="$1"
  local required_file="${WINSVPN_REBOOT_REQUIRED_FILE:-/var/run/reboot-required}"
  local boot_id_file="${WINSVPN_BOOT_ID_FILE:-/proc/sys/kernel/random/boot_id}"
  local state_dir="${WINSVPN_DEPLOY_STATE_DIR:-/var/lib/winsvpn-deployment}"
  local marker="${state_dir}/${role}.reboot-required"
  local boot_id previous_boot_id="" tmp

  [[ -r "${boot_id_file}" ]] || {
    err "Cannot read the kernel boot ID from ${boot_id_file}; refusing an ambiguous reboot boundary."
    return 1
  }
  boot_id="$(tr -d '[:space:]' < "${boot_id_file}")"
  [[ "${boot_id}" =~ ^[0-9A-Fa-f-]{8,64}$ ]] || {
    err "Kernel boot ID is malformed; refusing an ambiguous reboot boundary."
    return 1
  }

  if [[ -r "${marker}" ]]; then
    previous_boot_id="$(sed -n 's/^boot_id=//p' "${marker}" | head -n 1)"
    [[ "${previous_boot_id}" =~ ^[0-9A-Fa-f-]{8,64}$ ]] || {
      err "The saved ${role} reboot marker is malformed; refusing an ambiguous package boundary."
      return 1
    }
  fi

  if [[ ! -e "${required_file}" ]]; then
    if [[ -n "${previous_boot_id}" ]]; then
      if [[ "${previous_boot_id}" == "${boot_id}" ]]; then
        err "The ${role} package-reboot marker still records the current boot. Reboot before resuming even though ${required_file} is absent."
        return 75
      fi
      log "Verified the required package reboot for the ${role} role; resuming the idempotent deployment."
    fi
    rm -f -- "${marker}"
    return 0
  fi

  install -d -o root -g root -m 0700 "${state_dir}"
  tmp="$(mktemp "${marker}.XXXXXX")"
  {
    printf 'role=%s\n' "${role}"
    printf 'boot_id=%s\n' "${boot_id}"
    printf 'recorded_at_utc=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  } > "${tmp}"
  chown root:root "${tmp}"
  chmod 0600 "${tmp}"
  mv -f -- "${tmp}" "${marker}"
  err "Ubuntu requires a reboot after package installation. Deployment paused safely before role-service configuration or public VPN listeners; reboot and rerun the same role installer."
  return 75
}

configure_unattended_security_updates() {
  command -v unattended-upgrade >/dev/null 2>&1 || return 0
  log "Enabling automatic security updates"
  install -d -m 755 /etc/apt/apt.conf.d
  cat > /etc/apt/apt.conf.d/20auto-upgrades <<'EOF'
APT::Periodic::Enable "1";
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";
APT::Periodic::AutocleanInterval "7";
EOF
  cat > /etc/apt/apt.conf.d/52winsvpn-security-upgrades <<'EOF'
// Install Ubuntu security updates without replacing locally reviewed service
// configuration files or rebooting a VPN control plane without an operator.
Unattended-Upgrade::Allowed-Origins {
        "${distro_id}:${distro_codename}";
        "${distro_id}:${distro_codename}-security";
        "${distro_id}ESMApps:${distro_codename}-apps-security";
        "${distro_id}ESM:${distro_codename}-infra-security";
};
Unattended-Upgrade::Automatic-Reboot "false";
Unattended-Upgrade::Remove-Unused-Dependencies "false";
Unattended-Upgrade::SyslogEnable "true";
EOF
  chmod 644 /etc/apt/apt.conf.d/20auto-upgrades /etc/apt/apt.conf.d/52winsvpn-security-upgrades
  systemctl unmask unattended-upgrades.service apt-daily.timer apt-daily-upgrade.timer >/dev/null 2>&1 || true
  systemctl enable --now unattended-upgrades.service apt-daily.timer apt-daily-upgrade.timer >/dev/null 2>&1 || \
    warn "Automatic security-update services could not be started; inspect systemctl status unattended-upgrades apt-daily.timer apt-daily-upgrade.timer"
}

run_yabs_benchmark() {
  [[ "${RUN_YABS:-0}" == "1" ]] || return 0
  local yabs_script
  yabs_script="$(mktemp)"
  log "Running YABS benchmark (non-fatal; set RUN_YABS=0 to skip)"
  if curl -fsSL --connect-timeout 10 --max-time 45 \
      https://raw.githubusercontent.com/masonr/yet-another-bench-script/1d20bd9b058f425a0e3e8ac03fe2f501b0457d7c/yabs.sh \
      -o "${yabs_script}" && \
      printf '%s  %s\n' '389a0726119e4acd7fc9b20a8d1e271c423d55013f8638c6fb54e92c3443a069' "${yabs_script}" | sha256sum -c - >/dev/null; then
    bash "${yabs_script}" || warn "YABS benchmark failed; continuing deployment"
  else
    warn "Unable to download or verify the pinned YABS script; benchmark skipped"
  fi
  rm -f "${yabs_script}"
}

configure_performance_mode() {
  log "Installing persistent CPU performance governor helper"
  cat > /usr/local/bin/wins-performance-mode <<'EOF'
#!/usr/bin/env bash
set -Eeuo pipefail

if command -v cpupower >/dev/null 2>&1; then
  cpupower frequency-set -g performance >/dev/null 2>&1 || true
fi

for governor_file in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
  [[ -f "${governor_file}" ]] || continue
  echo performance > "${governor_file}" 2>/dev/null || true
done
EOF
  chmod 700 /usr/local/bin/wins-performance-mode

  cat > /etc/systemd/system/wins-performance-mode.service <<'EOF'
[Unit]
Description=Wins VPN CPU Performance Governor
After=multi-user.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/wins-performance-mode

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable --now wins-performance-mode.service >/dev/null 2>&1 || \
    warn "CPU performance mode could not be applied; many VPS providers hide cpufreq controls"
}

configure_dmcrypt_performance() {
  log "Installing persistent dm-crypt multi-core I/O helper"
  cat > /usr/local/bin/wins-dmcrypt-performance <<'EOF'
#!/usr/bin/env bash
set -Eeuo pipefail
shopt -s nullglob

command -v cryptsetup >/dev/null 2>&1 || exit 0
cryptsetup refresh --help 2>&1 | grep -- '--perf-no_read_workqueue' >/dev/null || exit 0

DMCRYPT_PERF_OPTIONS="${DMCRYPT_PERF_OPTIONS:---perf-no_read_workqueue --perf-no_write_workqueue}"
read -r -a perf_options <<<"${DMCRYPT_PERF_OPTIONS}"

for mapper in /dev/mapper/*; do
  name="$(basename "${mapper}")"
  [[ "${name}" == "control" || "${name}" == "udev" ]] && continue
  cryptsetup status "${name}" >/dev/null 2>&1 || continue
  cryptsetup refresh --persistent "${perf_options[@]}" "${name}" >/dev/null 2>&1 || \
    cryptsetup refresh "${perf_options[@]}" "${name}" >/dev/null 2>&1 || true
done

for rq_affinity in /sys/block/dm-*/queue/rq_affinity; do
  [[ -w "${rq_affinity}" ]] && echo 2 > "${rq_affinity}" 2>/dev/null || true
done
for nr_requests in /sys/block/dm-*/queue/nr_requests; do
  [[ -w "${nr_requests}" ]] && echo 1024 > "${nr_requests}" 2>/dev/null || true
done
EOF
  chmod 700 /usr/local/bin/wins-dmcrypt-performance

  cat > /etc/systemd/system/wins-dmcrypt-performance.service <<'EOF'
[Unit]
Description=Wins VPN dm-crypt Multi-Core Performance Tuning
After=local-fs.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/wins-dmcrypt-performance

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable --now wins-dmcrypt-performance.service >/dev/null 2>&1 || \
    warn "dm-crypt performance tuning could not be applied; continuing with kernel defaults"
}

root_backed_by_luks() {
  local root_src root_real
  root_src="$(findmnt -no SOURCE / 2>/dev/null || true)"
  [[ -n "${root_src}" ]] || return 1
  root_real="$(readlink -f "${root_src}" 2>/dev/null || printf '%s' "${root_src}")"
  lsblk -spno TYPE "${root_real}" 2>/dev/null | grep -x "crypt" >/dev/null
}

unencrypted_swap_devices() {
  local swap_src swap_real backing_src backing_real
  swapon --noheadings --raw --show=NAME 2>/dev/null | while IFS= read -r swap_src; do
    [[ -n "${swap_src}" ]] || continue
    swap_real="$(readlink -f "${swap_src}" 2>/dev/null || printf '%s' "${swap_src}")"
    case "${swap_real}" in
      /dev/zram*|/dev/ram*) continue ;;
    esac
    if [[ ! -b "${swap_real}" ]]; then
      backing_src="$(findmnt -no SOURCE -T "${swap_real}" 2>/dev/null || true)"
      [[ -n "${backing_src}" ]] || {
        printf '%s\n' "${swap_src}"
        continue
      }
      backing_real="$(readlink -f "${backing_src}" 2>/dev/null || printf '%s' "${backing_src}")"
    else
      backing_real="${swap_real}"
    fi
    if ! lsblk -spno TYPE "${backing_real}" 2>/dev/null | grep -x "crypt" >/dev/null; then
      printf '%s\n' "${swap_src}"
    fi
  done
}

# Legacy loop-backed swap sources: every active swap whose block ancestry
# contains a loop device, and a boot-enabled wins-cryptswap unit.
# Disk swap posture (owner ruling 2026-09-25): zram only. The file-backed loop
# swap is retired and no separately reviewed LUKS-backed disk-swap mechanism
# exists yet, so any request for disk swap is refused and reported.
refuse_disk_swap_request() {
  if [[ "$(printf '%s' "${WINS_CRYPTSWAP_ENABLED:-$WINS_CRYPTSWAP_ENABLED_DEFAULT}" | tr '[:upper:]' '[:lower:]')" =~ ^(1|true|yes|on)$ ]]; then
    err "WINS_CRYPTSWAP_ENABLED=1 is refused: the file-backed loop swap (backing image -> loop -> dm-crypt) is retired because it deadlocks under memory pressure. Set WINS_CRYPTSWAP_ENABLED=0."
    return 1
  fi
  if [[ "$(printf '%s' "${ENABLE_WINS_SWAPFILE:-$ENABLE_WINS_SWAPFILE_DEFAULT}" | tr '[:upper:]' '[:lower:]')" =~ ^(1|true|yes|on)$ ]]; then
    err "Disk swap was requested (ENABLE_WINS_SWAPFILE=1), but no separately reviewed LUKS-backed disk-swap mechanism exists yet; refusing."
    err "Swap posture on this server is compressed RAM (zram) only (owner ruling 2026-09-25). Set ENABLE_WINS_SWAPFILE=0."
    return 1
  fi
  log "Swap posture: compressed RAM (zram) only; disk swap: none (no reviewed LUKS-backed mechanism exists)."
  return 0
}

# Canonical names of the retired loop swap. Fixed on purpose, never read from
# the environment: the gates below must always inspect the real unit, helper,
# backing image and mapping. A legacy WINS_CRYPTSWAP_UNIT_PATH, _NAME or
# _BACKING override, if still set, is inspected IN ADDITION, never instead.
WINS_LEGACY_CRYPTSWAP_UNIT="wins-cryptswap.service"
WINS_LEGACY_CRYPTSWAP_UNIT_FILE="/etc/systemd/system/wins-cryptswap.service"
WINS_LEGACY_CRYPTSWAP_HELPER="/usr/local/sbin/wins-cryptswap"
WINS_LEGACY_CRYPTSWAP_BACKING="/var/lib/wins-cryptswap/backing.img"
WINS_LEGACY_CRYPTSWAP_MAPPER="wins-cryptswap"
WINS_ZRAM_CANONICAL_CONFIG="/etc/systemd/zram-generator.conf"

legacy_cryptswap_units() {
  printf '%s\n' "${WINS_LEGACY_CRYPTSWAP_UNIT}"
  if [[ -n "${WINS_CRYPTSWAP_UNIT_PATH:-}" && "$(basename "${WINS_CRYPTSWAP_UNIT_PATH}")" != "${WINS_LEGACY_CRYPTSWAP_UNIT}" ]]; then
    basename "${WINS_CRYPTSWAP_UNIT_PATH}"
  fi
  return 0
}

# A still-open mapping or an attached loop device of the legacy chain, canonical
# names first, then any legacy override.
legacy_cryptswap_block_state() {
  local name backing
  for name in "${WINS_LEGACY_CRYPTSWAP_MAPPER}" ${WINS_CRYPTSWAP_NAME:+"${WINS_CRYPTSWAP_NAME}"}; do
    if [[ -e "/dev/mapper/${name}" ]]; then
      printf 'present mapping /dev/mapper/%s\n' "${name}"
    fi
  done
  for backing in "${WINS_LEGACY_CRYPTSWAP_BACKING}" ${WINS_CRYPTSWAP_BACKING:+"${WINS_CRYPTSWAP_BACKING}"}; do
    losetup -j "${backing}" 2>/dev/null | cut -d: -f1 | sed "s|^|loop attached to ${backing}: |"
  done
  return 0
}

# Legacy loop-backed swap sources: every active swap whose block ancestry
# contains a loop device, the canonical wins-cryptswap.service (and any legacy
# override) when boot-enabled or active, and a still-open mapping or loop.
legacy_loop_swap_sources() {
  local unit swap_src swap_real enabled_state
  while IFS= read -r swap_src; do
    [[ -n "${swap_src}" ]] || continue
    swap_real="$(readlink -f "${swap_src}" 2>/dev/null || printf '%s' "${swap_src}")"
    if lsblk -snro TYPE "${swap_real}" 2>/dev/null | grep -x loop >/dev/null; then
      printf 'active loop-backed swap %s\n' "${swap_src}"
    fi
  done < <(swapon --noheadings --raw --show=NAME 2>/dev/null)
  while IFS= read -r unit; do
    [[ -n "${unit}" ]] || continue
    enabled_state="$(systemctl is-enabled "${unit}" 2>/dev/null || true)"
    case "${enabled_state}" in
      enabled|enabled-runtime|linked|linked-runtime|alias)
        printf 'boot-enabled %s (%s)\n' "${unit}" "${enabled_state}"
        ;;
    esac
    if [[ "$(systemctl is-active "${unit}" 2>/dev/null || true)" == "active" ]]; then
      printf 'active %s\n' "${unit}"
    fi
  done < <(legacy_cryptswap_units)
  legacy_cryptswap_block_state
  return 0
}

# An installer never retires a legacy loop swap live (that swapoff is itself
# memory pressure and can hang or OOM the hub) and never reports zram-only
# success while one is active or boot-enabled. It reports and stops.
refuse_legacy_loop_swap() {
  local legacy
  legacy="$(legacy_loop_swap_sources | paste -sd ';' -)"
  [[ -n "${legacy}" ]] || return 0
  err "Legacy loop-backed encrypted swap is present: ${legacy}"
  err "It deadlocks this hub under memory pressure. This installer does not retire it live and does not report zram-only swap while it is active or boot-enabled."
  err "Stop here and move this hub with the swap migration procedure: preferably a drained replacement installed zram-only; as a risk-accepted exception with console access, wins_cryptswap_to_zram_migrate.sh. Then re-run this installer."
  return 1
}

# zram-only postcondition (owner ruling 2026-09-25): /dev/zram0 active, no
# writeback device, no non-zram swap source, no active or boot-enabled
# wins-cryptswap source.
# --- Next-boot swap state (lane L40 revisions 5 to 7; Sol, Round CS3 Turns 5 to 7)
# These functions print one line per problem and never change anything. They
# evaluate what the NEXT boot will do, not only what is live now.
#
# systemd-zram-generator 1.1.2 (Ubuntu 24.04, package 1.1.2-3) reads, in merge
# order: ONE main file, the first that exists of /run, /etc, /usr/local/lib,
# /usr/lib (systemd/zram-generator.conf), then every *.conf drop-in of
# systemd/zram-generator.conf.d in those directories, sorted by file name;
# [zramN] sections are merged key by key, later files win. Sources:
# zram-generator v1.1.2 src/config.rs locate_fragments (base dirs usr/lib,
# usr/local/lib, etc, run; main file found by iterating them in reverse),
# zram-generator.conf(5) and zram-generator(8) on manpages.ubuntu.com noble.
# For a drop-in name present in several directories every copy is evaluated,
# lowest precedence first, so a key set in any copy is seen (conservative).
zram_generator_config_files() {
  local d f name
  for d in /run /etc /usr/local/lib /usr/lib; do
    if [[ -e "${d}/systemd/zram-generator.conf" ]]; then
      printf '%s\n' "${d}/systemd/zram-generator.conf"
      break
    fi
  done
  while IFS= read -r name; do
    [[ -n "${name}" ]] || continue
    for d in /usr/lib /usr/local/lib /etc /run; do
      if [[ -e "${d}/systemd/zram-generator.conf.d/${name}" ]]; then
        printf '%s\n' "${d}/systemd/zram-generator.conf.d/${name}"
      fi
    done
  done < <(for d in /usr/lib /usr/local/lib /etc /run; do
             for f in "${d}"/systemd/zram-generator.conf.d/*.conf; do
               if [[ -e "${f}" ]]; then basename "${f}"; fi
             done
           done | LC_ALL=C sort -u)
  return 0
}

# The effective configuration against the reviewed policy: exactly one device,
# [zram0], with exactly zram-size = min(ram * P / 100, M), compression-algorithm
# = zstd and swap-priority = 100. Any other section, any other key (writeback-
# device above all), any global directive, or any line outside a strict
# key = value grammar is a problem.
zram_effective_config_problems() {
  local percent="$1" max_mb="$2"
  local -a zram_cfg_files=()
  mapfile -t zram_cfg_files < <(zram_generator_config_files | grep -v "^$" || true)
  if ((${#zram_cfg_files[@]} == 0)); then
    printf 'no zram-generator configuration exists: zram would not return at the next boot\n'
    return 0
  fi
  awk -v want_size="min(ram * ${percent} / 100, ${max_mb})" '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t\r]+$/, "", s); return s }
    # Every file starts in the global section, as the generator parses each file on its own.
    FNR == 1 { sect = "" }
    { line = trim($0) }
    line == "" || line ~ /^[#;]/ { next }
    line ~ /^\[[A-Za-z0-9_-]+\]$/ { sect = substr(line, 2, length(line) - 2); seen[sect] = 1; next }
    line ~ /^[A-Za-z0-9_!.-]+[ \t]*=/ && line !~ /[\\"]/ {
      k = trim(substr(line, 1, index(line, "=") - 1)); v = trim(substr(line, index(line, "=") + 1))
      if (sect == "") { print "global directive " k " in " FILENAME; next }
      val[sect, k] = v; keys[sect, k] = 1; next
    }
    { print "line outside the reviewed key = value grammar in " FILENAME ": " line }
    END {
      for (s in seen) if (s != "zram0") print "extra section [" s "] in the zram-generator configuration"
      if (!("zram0" in seen)) print "no [zram0] section in the zram-generator configuration"
      for (sk in keys) {
        split(sk, a, SUBSEP)
        if (a[1] == "zram0" && a[2] != "zram-size" && a[2] != "compression-algorithm" && a[2] != "swap-priority")
          print "[zram0] " a[2] " = " val[sk] " is not in the reviewed policy"
      }
      if (val["zram0", "zram-size"] != want_size) print "[zram0] zram-size is \"" val["zram0", "zram-size"] "\", the reviewed policy is \"" want_size "\""
      if (val["zram0", "compression-algorithm"] != "zstd") print "[zram0] compression-algorithm is \"" val["zram0", "compression-algorithm"] "\", the reviewed policy is \"zstd\""
      if (val["zram0", "swap-priority"] != "100") print "[zram0] swap-priority is \"" val["zram0", "swap-priority"] "\", the reviewed policy is \"100\""
    }' "${zram_cfg_files[@]}"
  return 0
}

# systemd-sysctl order (sysctl.d(5), noble): *.conf in /etc, /run,
# /usr/local/lib, /usr/lib sysctl.d; a name in /etc overrides the same name in
# /run, /usr/local/lib and /usr/lib, /run overrides /usr; files are processed
# by name, the lexicographically latest assignment wins.
sysctl_config_files() {
  local d f name
  while IFS= read -r name; do
    [[ -n "${name}" ]] || continue
    for d in /etc /run /usr/local/lib /usr/lib; do
      if [[ -e "${d}/sysctl.d/${name}" ]]; then
        printf '%s\n' "${d}/sysctl.d/${name}"
        break
      fi
    done
  done < <(for d in /etc /run /usr/local/lib /usr/lib; do
             for f in "${d}"/sysctl.d/*.conf; do
               if [[ -e "${f}" ]]; then basename "${f}"; fi
             done
           done | LC_ALL=C sort -u)
  return 0
}

live_swappiness() { cat /proc/sys/vm/swappiness 2>/dev/null || true; }

# vm.swappiness is the one swap-related sysctl the policy sets (10): the value
# the next boot applies and the live value must both be 10.
swappiness_problems() {
  local -a sysctl_cfg_files=()
  local next live
  mapfile -t sysctl_cfg_files < <(sysctl_config_files | grep -v "^$" || true)
  next=""
  if ((${#sysctl_cfg_files[@]} > 0)); then
    next="$(awk '
      { line = $0; sub(/^[ \t]+/, "", line) }
      line ~ /^[#;]/ || line == "" { next }
      { i = index(line, "="); if (!i) next
        k = substr(line, 1, i - 1); v = substr(line, i + 1)
        gsub(/[ \t]/, "", k); sub(/^-/, "", k); gsub(/\//, ".", k); gsub(/^[ \t]+|[ \t\r]+$/, "", v)
        if (k == "vm.swappiness") last = v }
      END { print last }' "${sysctl_cfg_files[@]}")"
  fi
  [[ "${next}" == "10" ]] || printf 'the next boot sets vm.swappiness to "%s" (default 60 when unset), the reviewed policy is 10\n' "${next}"
  live="$(live_swappiness)"
  [[ "${live}" == "10" ]] || printf 'live vm.swappiness is "%s", the reviewed policy is 10\n' "${live}"
  return 0
}

# The kernel command line the next boot will use (lane L40 revisions 6, 7 and
# 8; Sol, Round CS3 Turns 6 and 7): the boot-path stub chain (UEFI) or the core
# image embedded in the BIOS boot partition (BIOS) is resolved to the
# configuration GRUB will load, for the root directory given as $1 ("/" in
# production; fixture roots only in tests). Prints one line per problem; notes
# that are not refusals go to stderr.
next_boot_cmdline_problems_at_root() {
  if ! command -v python3 >/dev/null 2>&1; then
    printf 'python3 is missing: the next boot kernel command line cannot be determined; refusing\n'
    return 0
  fi
  python3 - "$1" <<'PY'
import glob
import os
import re
import subprocess
import sys

# Next-boot kernel command line check (lane L40 revisions 6, 7 and 8; Sol,
# Round CS3 Turns 6 and 7; coordinator's BIOS measurement for revision 8). Prints one line per problem, changes nothing. argv[1] is
# the root directory: "/" in production. Any other root is a test fixture, and
# only then are the filesystem facts read from <root>/_l40_fixture/ instead of
# lsblk and findmnt.
#
# Which configuration GRUB loads next boot:
# * UEFI (the current boot has /sys/firmware/efi; a node keeps its firmware
#   mode across reboots): Ubuntu's signed GRUB is built with
#   grub-mkimage -p "/EFI/$efi_vendor" (grub2-unsigned debian/build-efi-images,
#   noble), so normal mode reads /EFI/ubuntu/grub.cfg on the ESP, the stub
#   grub-install writes; the stub selects a filesystem (search.fs_uuid), sets
#   prefix and configfile's the real grub.cfg (GNU GRUB manual: configfile,
#   search, normal). Every EFI/*/grub.cfg stub on the ESP is followed, the
#   chain through configfile/source/normal is resolved to readable files (depth
#   limit 5), and every resolved final configuration is checked.
# * BIOS (revision 8): the core image that will actually run is read, read
#   only, from where the MBR boot code loads it: the one GPT partition of type
#   BIOS boot, or on an MBR disk the post-MBR gap sector boot.img names. Its
#   embedded prefix and early configuration are parsed from the image (GRUB
#   2.12 layout, cited at bios_core() below) and resolved like a UEFI stub;
#   GRUB normal mode then reads $prefix/grub.cfg (kern/main.c). The file copy
#   <grubdir>/i386-pc/core.img is compared and a difference is reported on
#   stderr, never refused.
# * Ubuntu 24.04 cloud images boot GRUB 2 in BIOS or UEFI mode from one image
#   (ubuntu-cloud announcement 2013-12); systemd-boot / BLS entries and unified
#   kernel images are handled or refused as in revision 6.
# Anything the check cannot resolve unambiguously to files it can read is a
# problem: an unknown command in a stub, an unresolvable variable or device, a
# filesystem UUID that is missing, duplicated or not mounted, more than one ESP.

root = sys.argv[1] if len(sys.argv) > 1 else "/"
FIXTURE = root.rstrip("/") != ""


def p(*parts):
    return os.path.join(root, *[x.lstrip("/") for x in parts])


def rel(path):
    r = root.rstrip("/")
    return path[len(r):] if r and path.startswith(r) else path


def read(path):
    try:
        with open(path, errors="replace") as fh:
            return fh.read()
    except OSError:
        return None


problems = []


def arg_problems(args, where):
    out = []
    for tok in args.split():
        tok = tok.strip('"\'')
        k, _, v = tok.partition("=")
        if k in ("systemd.zram", "rd.systemd.zram") and v.lower() in ("0", "no", "false", "off", "n"):
            out.append("%s: %s disables zram" % (where, tok))
        elif k in ("systemd.mask", "rd.systemd.mask") and ("zram" in v or v in ("swap.target",)):
            out.append("%s: %s masks a unit zram swap needs" % (where, tok))
        elif k in ("module_blacklist", "modprobe.blacklist") and "zram" in v.split(","):
            out.append("%s: %s blacklists the zram module" % (where, tok))
        elif k == "initcall_blacklist" and "zram" in v:
            out.append("%s: %s blacklists zram initialisation" % (where, tok))
    return out


# --- filesystem facts -------------------------------------------------------
ESP_TYPE = "c12a7328-f81f-11d2-ba4b-00a0c93ec93b"


def esp_count():
    if FIXTURE:
        v = (read(p("/_l40_fixture/esp_count")) or "").strip()
        return int(v) if v.isdigit() else None
    try:
        out = subprocess.run(["lsblk", "-rno", "PARTTYPE"], capture_output=True, text=True, check=True).stdout
    except (OSError, subprocess.CalledProcessError):
        return None
    return sum(1 for l in out.split() if l.strip().lower() == ESP_TYPE)


def uuid_mounts(uuid):
    """(number of block devices carrying uuid, mountpoint or None)"""
    if FIXTURE:
        rows = [l.split() for l in (read(p("/_l40_fixture/fs")) or "").splitlines() if l.strip()]
        hits = [r for r in rows if r[0] == uuid]
        return len(hits), (hits[0][1] if hits and len(hits[0]) > 1 else None)
    try:
        devs = subprocess.run(["lsblk", "-rno", "UUID"], capture_output=True, text=True, check=True).stdout.split()
        rows = subprocess.run(["findmnt", "-rno", "TARGET,FSROOT", "-S", "UUID=" + uuid], capture_output=True, text=True).stdout.splitlines()
    except (OSError, subprocess.CalledProcessError):
        return 0, None
    # Only a mount of the filesystem's own root shows the paths GRUB sees;
    # bind mounts of subdirectories (FSROOT other than /) do not.
    tops = [r.split()[0] for r in rows if len(r.split()) == 2 and r.split()[1] == "/"]
    return sum(1 for d in devs if d == uuid), (tops[0] if tops else None)


# --- GRUB word expansion ----------------------------------------------------
class Unresolved(Exception):
    pass


def expand(word, vars_):
    """GRUB-style word: quotes removed, $var/${var} expanded outside single quotes."""
    out, i, q = [], 0, None
    while i < len(word):
        c = word[i]
        if q == "'":
            if c == "'":
                q = None
            else:
                out.append(c)
            i += 1
            continue
        if c == "'" and q is None:
            q = "'"
            i += 1
            continue
        if c == '"':
            q = None if q == '"' else '"'
            i += 1
            continue
        if c == "$":
            m = re.match(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)", word[i:])
            if m:
                name = m.group(1) or m.group(2)
                if name not in vars_:
                    raise Unresolved("variable $%s is not set" % name)
                out.append(vars_[name])
                i += m.end()
                continue
        out.append(c)
        i += 1
    if q is not None:
        raise Unresolved("unterminated quote in %s" % word)
    return "".join(out)


def host_path(path, vars_):
    """(MNT:<mountpoint>)/x or /x relative to $root -> host file path."""
    m = re.match(r"^\(MNT:([^)]*)\)(.*)$", path)
    if m:
        return p(m.group(1), m.group(2) or "/")
    if path.startswith("("):
        raise Unresolved("device %s is not one this check can map to a mounted filesystem" % path.split(")")[0] + ")")
    # GRUB device values carry no parentheses: $root is "MNT:<mountpoint>".
    r = vars_.get("root", "")
    m = re.match(r"^MNT:(.*)$", r)
    if not m:
        raise Unresolved("path %s is relative to a root device this check cannot map" % path)
    return p(m.group(1), path)


def dev_of(path):
    m = re.match(r"^(\(MNT:[^)]*\))", path)
    return m.group(1) if m else None


# --- GRUB menu parsing (revision 6) -----------------------------------------
def parse_grub(txt):
    rootnode = {"kind": "submenu", "title": "", "id": "", "children": [], "linux": []}
    stack = [rootnode]
    defaults, fallbacks = [], []
    for raw in txt.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        m = re.match(r'(menuentry|submenu)\s+(["\'])(.*?)\2(.*)\{\s*$', line)
        if m:
            idm = re.search(r'\$menuentry_id_option\s+(["\'])(.*?)\1', m.group(4)) or re.search(r'--id(?:=|\s+)(["\']?)([^\s"\']+)\1', m.group(4))
            node = {"kind": m.group(1), "title": m.group(3), "id": idm.group(2) if idm else "", "children": [], "linux": []}
            stack[-1]["children"].append(node)
            stack.append(node)
            continue
        if re.match(r'function\s+\S+\s*\{\s*$', line):
            stack.append({"kind": "function", "children": [], "linux": []})
            continue
        if line == "}":
            if len(stack) > 1:
                stack.pop()
            continue
        m = re.match(r'(linux|linuxefi|linux16)\s+(\S+)\s*(.*)$', line)
        if m and stack[-1]["kind"] == "menuentry":
            stack[-1]["linux"].append(m.group(3))
            continue
        m = re.match(r'set\s+default=(["\']?)(.*?)\1\s*$', line)
        if m and len(stack) == 1:
            defaults.append(m.group(2))
            continue
        m = re.match(r'set\s+fallback=(["\']?)(.*?)\1\s*$', line)
        if m and len(stack) == 1:
            fallbacks.append(m.group(2))
    return rootnode, defaults, fallbacks


def entries(node, path=""):
    for c in node["children"]:
        if c["kind"] == "menuentry":
            yield (path + c["title"], c)
        else:
            for x in entries(c, path + c["title"] + ">"):
                yield x


def resolve_entry(node, spec):
    cur = node
    for comp in spec.split(">"):
        kids = cur["children"]
        hit = None
        if re.fullmatch(r"\d+", comp):
            i = int(comp)
            hit = kids[i] if i < len(kids) else None
        else:
            for k in kids:
                if comp in (k["title"], k["id"]):
                    hit = k
                    break
        if hit is None:
            return None
        cur = hit
    return cur if cur["kind"] == "menuentry" else None


def grubenv(path):
    env = {}
    for line in (read(path) or "").splitlines():
        if line.startswith("#") or "=" not in line:
            continue
        k, _, v = line.partition("=")
        env[k.strip()] = v.strip()
    return env


def expand_linux(args, env, where):
    out = []

    def sub(m):
        name = m.group(1) or m.group(2)
        if name == "vt_handoff":
            return "vt.handoff=7"
        if name in env:
            return env[name]
        out.append("%s: the linux line uses $%s, which this check cannot resolve" % (where, name))
        return ""
    return re.sub(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)", sub, args), out


def check_final(final_host, final_dev_path, vars_):
    """Revision 6 entry resolution on one final configuration, plus any file it
    sources or configfile's that exists (Ubuntu's 41_custom sources custom.cfg)."""
    txt = read(final_host)
    if txt is None:
        problems.append("%s cannot be read" % rel(final_host))
        return
    label = rel(final_host)
    env = grubenv(os.path.join(os.path.dirname(final_host), "grubenv"))
    tree, defaults, fallbacks = parse_grub(txt)
    all_entries = list(entries(tree))
    ambiguous, specs = [], []
    # Files this configuration pulls in: included conservatively.
    cfgdir = final_dev_path.rsplit("/", 1)[0]
    lvars = dict(vars_, config_directory=cfgdir, config_file=final_dev_path)
    pulled = set()
    for m in re.finditer(r"^\s*(?:.*;\s*)?(source|configfile)\s+(\S+)", txt, re.M):
        try:
            tgt = host_path(expand(m.group(2).rstrip(";"), lvars), lvars)
        except Unresolved as e:
            problems.append("%s: %s %s cannot be resolved (%s); refusing" % (label, m.group(1), m.group(2), e))
            continue
        if os.path.exists(tgt) and tgt not in pulled:
            pulled.add(tgt)
            sub = read(tgt) or ""
            st, sd, sf = parse_grub(sub)
            extra = list(entries(st))
            if extra or sd or sf or re.search(r"^\s*(linux|configfile|source)\b", sub, re.M):
                ambiguous.append("%s %s adds menu entries or boot settings" % (m.group(1), rel(tgt)))
                all_entries += [(rel(tgt) + ":" + t, e) for t, e in extra]
                defaults += sd
    literal = [d for d in defaults if d not in ("${next_entry}", "$next_entry")]
    if len(set(literal)) != 1:
        ambiguous.append("%s sets default %d distinct ways (%s)" % (label, len(set(literal)), ", ".join(sorted(set(literal))) or "none"))
    else:
        d = literal[0]
        if d in ("${saved_entry}", "$saved_entry"):
            d = env.get("saved_entry", "") or "0"
        if "$" in d:
            ambiguous.append("default %s depends on a variable this check cannot resolve" % d)
        else:
            specs.append(("default", d))
    if env.get("next_entry"):
        specs.append(("grubenv next_entry (one-shot next boot)", env["next_entry"]))
    if env.get("initrdfail") or env.get("prev_entry"):
        ambiguous.append("grubenv carries initrdfail/prev_entry, so the next entry depends on boot-failure recovery")
    for fb in fallbacks:
        for part in fb.split():
            if "$" in part:
                ambiguous.append("fallback %s depends on a variable" % part)
            else:
                specs.append(("fallback", part))
    chosen = []
    for lab, spec in specs:
        e = resolve_entry(tree, spec)
        if e is None:
            ambiguous.append("%s %r does not resolve to a menu entry" % (lab, spec))
        else:
            chosen.append((lab + " " + spec + " -> " + e["title"], e))
    if ambiguous:
        chosen = [("any entry (" + "; ".join(ambiguous) + ") " + t, e) for t, e in all_entries]
    if not all_entries:
        problems.append("%s has no menu entry with a linux line" % label)
    for lab, e in chosen:
        if not e["linux"]:
            problems.append("grub entry %s has no linux line" % lab)
        for args in e["linux"]:
            text, unresolved = expand_linux(args, env, "grub entry " + lab)
            problems.extend(unresolved)
            problems.extend(arg_problems(text, label + " entry " + lab))


# --- stub chain (revision 7) ------------------------------------------------
finals = []  # (host path, device-qualified path, vars)


def follow(host, dev_path, vars_, depth, bios_load_cfg=False, text=None):
    if depth > 5:
        problems.append("GRUB configuration chain deeper than 5 at %s; refusing" % rel(host))
        return
    txt = read(host) if text is None else text
    if txt is None:
        problems.append("GRUB configuration %s is missing or unreadable; refusing" % rel(host))
        return
    if re.search(r"^\s*(menuentry|submenu)\b", txt, re.M):
        finals.append((host, dev_path, dict(vars_)))
        return
    handed = False
    for raw in txt.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        try:
            words = line.split()
            cmd = words[0]
            if cmd == "search.fs_uuid" or (cmd == "search" and "--fs-uuid" in words):
                if cmd == "search.fs_uuid":
                    uuid = words[1]
                    var = words[2] if len(words) > 2 and not words[2].startswith("-") else "root"
                else:
                    var, uuid, it = "root", None, iter(words[1:])
                    for w in it:
                        if w.startswith("--set="):
                            var = w.split("=", 1)[1]
                        elif w == "--set":
                            var = next(it, "root")
                        elif w.startswith("--hint"):
                            if "=" not in w:
                                next(it, None)
                        elif w.startswith("-"):
                            continue
                        else:
                            uuid = w
                    if uuid is None:
                        raise Unresolved("search without a UUID")
                n, mnt = uuid_mounts(uuid)
                if n != 1:
                    raise Unresolved("filesystem UUID %s is carried by %d block devices" % (uuid, n))
                if not mnt:
                    raise Unresolved("filesystem UUID %s is not mounted, so its configuration cannot be read" % uuid)
                vars_[var] = "MNT:%s" % mnt
            elif cmd == "set":
                m = re.match(r"set\s+([A-Za-z_][A-Za-z0-9_]*)=(.*)$", line)
                if not m:
                    raise Unresolved("unsupported set syntax: %s" % line)
                vars_[m.group(1)] = expand(m.group(2).strip(), vars_)
            elif cmd in ("insmod", "echo"):
                continue
            elif cmd in ("configfile", "source", "normal"):
                if cmd == "normal" and len(words) == 1:
                    target = vars_.get("prefix", "") + "/grub.cfg"
                else:
                    target = expand(words[1], vars_)
                if not dev_of(target) and not target.startswith("/"):
                    raise Unresolved("%s target %s is on a device this check cannot map to a mounted filesystem" % (cmd, target))
                hp = host_path(target, vars_)
                follow(hp, target if dev_of(target) else "(" + vars_.get("root", "") + ")" + target, vars_, depth + 1)
                if cmd in ("configfile", "normal"):
                    handed = True
                    break
            else:
                raise Unresolved("unsupported command in a boot-path stub: %s" % cmd)
        except Unresolved as e:
            problems.append("%s: %s; refusing" % (rel(host), e))
            return
    if bios_load_cfg:
        try:
            target = vars_["prefix"] + "/grub.cfg"
            follow(host_path(target, vars_), target, vars_, depth + 1)
        except (KeyError, Unresolved) as e:
            problems.append("%s: the prefix for grub.cfg cannot be resolved (%s); refusing" % (rel(host), e))
        return
    if not handed:
        problems.append("%s does not hand over to a menu configuration (no configfile or normal); refusing" % rel(host))


# --- BIOS core image (revision 8) -------------------------------------------
# GRUB 2.12 sources relied on (tag grub-2.12, git.savannah.gnu.org/cgit/grub.git):
# * include/grub/i386/pc/boot.h: boot.img (the MBR) holds the first sector of
#   core.img as a 64-bit LE value at GRUB_BOOT_MACHINE_KERNEL_SECTOR 0x5c;
#   signature 0xaa55 at 0x1fe.
# * grub-core/boot/i386/pc/diskboot.S: the first core.img sector (diskboot.img)
#   ends with a blocklist growing down from 0x200, entries of
#   GRUB_BOOT_MACHINE_LIST_SIZE 12 bytes {u64 start sector, u16 sector count,
#   u16 segment}, terminated by a count of 0.
# * include/grub/offsets.h and grub-core/boot/i386/pc/startup_raw.S: the second
#   part (lzma_decompress.img) has the compressed size at 0x08, the
#   uncompressed size at 0x0c, the Reed-Solomon redundancy at 0x10; the LZMA
#   stream starts at the decompressor's end label (decompressor_end), at most
#   GRUB_DECOMPRESSOR_I386_PC_MAX_DECOMPRESSOR_SIZE (0x9000 - 0x8200) bytes in.
# * util/mkimage.c: the stream is raw LZMA1 without header or end mark
#   (LzmaEncode, dictSize 1 << 16, lc 3, lp 0, pb 2, writeEndMark 0); the
#   decompressed image is kernel.img followed at layout.kernel_size by struct
#   grub_module_info32 {magic, offset, size} whose size runs to the end
#   (uncompressed size = kernel_size + total_module_size), then objects
#   struct grub_module_header {u32 type, u32 size including the header}.
# * include/grub/kernel.h: GRUB_MODULE_MAGIC 0x676d696d, OBJ_TYPE_ELF 0,
#   OBJ_TYPE_MEMDISK 1, OBJ_TYPE_CONFIG 2, OBJ_TYPE_PREFIX 3.
# * util/setup.c: Reed-Solomon redundancy is appended after the image; the
#   image bytes themselves are unchanged.
# * grub-core/kern/main.c: grub_load_config uses the first OBJ_TYPE_CONFIG; a
#   prefix device starting with "," takes its drive from the firmware boot
#   drive; the embedded config runs, then grub_load_normal_mode reads
#   $prefix/grub.cfg.
BIOS_BOOT_TYPE = "21686148-6449-6e6f-744e-656564454649"
bios_notes = []


class CoreError(Exception):
    pass


def blockdevs():
    """[{name, pkname, type, pttype, parttype, partn, start}] (start in 512-byte units)."""
    if FIXTURE:
        rows = []
        for line in (read(p("/_l40_fixture/blk")) or "").splitlines():
            f = line.split()
            if len(f) == 7:
                rows.append(dict(zip(("name", "pkname", "type", "pttype", "parttype", "partn", "start"), [None if x == "-" else x for x in f])))
        return rows
    import json
    out = subprocess.run(["lsblk", "-J", "-o", "NAME,PKNAME,TYPE,PTTYPE,PARTTYPE"], capture_output=True, text=True, check=True).stdout
    rows = []

    def walk(nodes):
        for n in nodes or []:
            d = {k: n.get(k) for k in ("name", "pkname", "type", "pttype", "parttype")}
            for k in ("partition", "start"):
                try:
                    with open("/sys/class/block/%s/%s" % (d["name"], k)) as fh:
                        d["partn" if k == "partition" else k] = fh.read().strip()
                except OSError:
                    d["partn" if k == "partition" else k] = None
            rows.append(d)
            walk(n.get("children"))
    walk(json.loads(out).get("blockdevices"))
    return rows


def dev_read(name, offset, length):
    path = p("/_l40_fixture/dev", name) if FIXTURE else "/dev/" + name
    fd = os.open(path, os.O_RDONLY)
    try:
        os.lseek(fd, offset, os.SEEK_SET)
        buf = b""
        while len(buf) < length:
            chunk = os.read(fd, length - len(buf))
            if not chunk:
                break
            buf += chunk
        return buf
    finally:
        os.close(fd)


def dev_mount(name):
    if FIXTURE:
        for line in (read(p("/_l40_fixture/devmnt")) or "").splitlines():
            f = line.split()
            if len(f) == 2 and f[0] == name:
                return f[1]
        return None
    rows = subprocess.run(["findmnt", "-rno", "TARGET,FSROOT", "-S", "/dev/" + name], capture_output=True, text=True).stdout.splitlines()
    tops = [r.split()[0] for r in rows if len(r.split()) == 2 and r.split()[1] == "/"]
    return tops[0] if tops else None


def u16(b, o):
    return int.from_bytes(b[o:o + 2], "little")


def u32(b, o):
    return int.from_bytes(b[o:o + 4], "little")


def u64(b, o):
    return int.from_bytes(b[o:o + 8], "little")


def core_sectors(first512):
    """Blocklist of diskboot.img: [(start, count)] up to the terminating 0 count."""
    out, off = [], 0x200 - 12
    while off >= 0x100:
        start, count = u64(first512, off), u16(first512, off + 8)
        if count == 0:
            return out
        out.append((start, count))
        off -= 12
    raise CoreError("diskboot blocklist is not terminated")


def bios_core(img):
    """Parse an i386-pc core image: {prefix, config, payload}."""
    try:
        import lzma
    except ImportError:
        raise CoreError("python3 has no lzma module, so core.img cannot be decompressed")
    if len(img) < 1024:
        raise CoreError("image shorter than two sectors")
    rest = img[512:]
    comp, unc = u32(rest, 0x08), u32(rest, 0x0c)
    if not (0 < comp <= len(rest) and 12 < unc <= 16 << 20):
        raise CoreError("implausible compressed/uncompressed sizes %d/%d" % (comp, unc))
    flt = [{"id": lzma.FILTER_LZMA1, "dict_size": 1 << 16, "lc": 3, "lp": 0, "pb": 2}]
    hits = []
    # decompressor_end is not recorded in the header: every offset the
    # decompressor could end at is tried, and exactly one must yield an image
    # whose module area is well formed.
    for o in range(0x1c, 0x9000 - 0x8200 + 1):
        if o + comp > len(rest):
            break
        try:
            out = lzma.LZMADecompressor(lzma.FORMAT_RAW, filters=flt).decompress(rest[o:o + comp], max_length=unc)
        except lzma.LZMAError:
            continue
        if len(out) != unc:
            continue
        infos = [q for q in range(0, unc - 11, 4) if out[q:q + 4] == b"mimg" and u32(out, q + 4) == 12 and q + u32(out, q + 8) == unc]
        if len(infos) == 1:
            hits.append((o, out, infos[0]))
    if len(hits) != 1:
        raise CoreError("%d candidate LZMA streams with a module area (exactly one required)" % len(hits))
    _, out, q = hits[0]
    end, q = unc, q + 12
    config = prefix = None
    while q < end:
        if q + 8 > end:
            raise CoreError("truncated module header at %d" % q)
        typ, size = u32(out, q), u32(out, q + 4)
        if size < 8 or q + size > end:
            raise CoreError("module object at %d overruns the module area" % q)
        body = out[q + 8:q + size]
        if typ == 2 and config is None:
            config = body.split(b"\0", 1)[0].decode("utf-8", "replace")
        elif typ == 3:
            prefix = body.split(b"\0", 1)[0].decode("utf-8", "replace")
        q += size
    if q != end:
        raise CoreError("module area does not end at the image end")
    return {"prefix": prefix, "config": config, "payload": out}


def locate_bios_core(devs):
    """(disk, device to read, byte offset in it, description, disk sector of
    the core's first sector) of the one core image."""
    disks = {d["name"]: d for d in devs if d.get("type") in ("disk", "loop")}
    cands, bad = [], []
    for d in devs:
        if d.get("type") == "part" and (d.get("parttype") or "").lower() == BIOS_BOOT_TYPE:
            cands.append((d["pkname"], d["name"], 0, "BIOS boot partition /dev/%s" % d["name"], int(d.get("start") or -1), int(d.get("start") or -1)))
    for name, d in disks.items():
        if (d.get("pttype") or "") != "dos":
            continue
        try:
            mbr = dev_read(name, 0, 512)
        except OSError as e:
            bad.append("/dev/%s MBR cannot be read (%s)" % (name, e))
            continue
        k = u64(mbr, 0x5c) if len(mbr) == 512 and u16(mbr, 0x1fe) == 0xaa55 else 0
        firsts = [int(x["start"]) for x in devs if x.get("pkname") == name and x.get("start")]
        if k and firsts and 1 <= k < min(firsts):
            cands.append((name, name, k * 512, "post-MBR gap of /dev/%s at sector %d" % (name, k), None, k))
    if bad:
        raise CoreError("; ".join(bad))
    if len(cands) != 1:
        kinds = ", ".join(c[3] for c in cands) or "none"
        raise CoreError("%d BIOS core image locations (BIOS boot partitions or MBR gap cores: %s); exactly one required" % (len(cands), kinds))
    disk, dev, off, what, start, first = cands[0]
    if start is not None:
        mbr = dev_read(disk, 0, 512)
        if len(mbr) != 512 or u16(mbr, 0x1fe) != 0xaa55:
            raise CoreError("/dev/%s has no boot signature in its MBR, so what BIOS runs is unknown" % disk)
        if u64(mbr, 0x5c) != start:
            raise CoreError("the MBR boot code of /dev/%s loads sector %d, not the %s at sector %d" % (disk, u64(mbr, 0x5c), what, start))
    return disk, dev, off, what, first


def read_core(dev, off, what, first_sector):
    first = dev_read(dev, off, 512)
    if len(first) != 512:
        raise CoreError("%s: first sector unreadable" % what)
    bl = core_sectors(first)
    # setup.c records absolute disk sectors; embedding is one contiguous run.
    if len(bl) != 1 or bl[0][0] != first_sector + 1:
        raise CoreError("%s: diskboot blocklist %r is not one run starting at sector %d" % (what, bl, first_sector + 1))
    return dev_read(dev, off, 512 * (1 + bl[0][1]))


def prefix_vars(prefix, disk, devs):
    m = re.match(r"^\(([^)]*)\)(/.*)?$", prefix or "")
    if not m:
        raise Unresolved("embedded prefix %r names no device" % prefix)
    drive, _, part = m.group(1).partition(",")
    if drive not in ("", "hd0") or not re.fullmatch(r"(gpt|msdos)\d+", part):
        raise Unresolved("embedded prefix device (%s) is not the boot disk's gptN/msdosN partition" % m.group(1))
    if drive == "hd0" and sum(1 for d in devs if d.get("type") == "disk") != 1:
        raise Unresolved("embedded prefix names hd0 but more than one disk exists")
    n = re.sub(r"\D", "", part)
    hits = [d["name"] for d in devs if d.get("pkname") == disk and d.get("partn") == n]
    if len(hits) != 1:
        raise Unresolved("partition %s of /dev/%s not found" % (n, disk))
    mnt = dev_mount(hits[0])
    if not mnt:
        raise Unresolved("/dev/%s (prefix %s) is not mounted, so its grub.cfg cannot be read" % (hits[0], prefix))
    return {"root": "MNT:%s" % mnt, "prefix": "(MNT:%s)%s" % (mnt, (m.group(2) or "").rstrip("/"))}


def bios_branch():
    try:
        devs = blockdevs()
        disk, dev, off, what, first = locate_bios_core(devs)
        emb = bios_core(read_core(dev, off, what, first))
    except (CoreError, OSError, subprocess.CalledProcessError, ValueError) as e:
        problems.append("BIOS boot: the core image that runs cannot be read and parsed (%s); refusing" % e)
        return
    try:
        fcopy = bios_core(open(p("/boot/grub/i386-pc/core.img"), "rb").read())
        if fcopy["payload"] != emb["payload"]:
            bios_notes.append("the core image in %s differs from /boot/grub/i386-pc/core.img (embedded prefix %r, config %r; file prefix %r, config %r); the embedded one runs and is the one checked" % (what, emb["prefix"], emb["config"], fcopy["prefix"], fcopy["config"]))
    except (CoreError, OSError) as e:
        bios_notes.append("/boot/grub/i386-pc/core.img cannot be compared with %s (%s)" % (what, e))
    lc = read(p("/boot/grub/i386-pc/load.cfg"))
    if lc is not None and lc.strip() != (emb["config"] or "").strip():
        bios_notes.append("/boot/grub/i386-pc/load.cfg differs from the configuration embedded in %s; the embedded one is checked" % what)
    label = "core.img embedded config (%s)" % what
    try:
        v = prefix_vars(emb["prefix"], disk, devs)
    except Unresolved as e:
        problems.append("%s: %s; refusing" % (label, e))
        return
    follow(label, "(%s)" % label, v, 0, bios_load_cfg=True, text=emb["config"] or "")


# 1. The current boot, and the defaults a future update-grub would write.
cur = read(p("/proc/cmdline")) or ""
problems += arg_problems(cur, "current kernel command line (/proc/cmdline)")
for f in [p("/etc/default/grub")] + sorted(glob.glob(p("/etc/default/grub.d/*.cfg"))):
    txt = read(f)
    if txt is None:
        continue
    for line in txt.splitlines():
        m = re.match(r'\s*(GRUB_CMDLINE_LINUX(?:_DEFAULT)?)\s*=\s*(.*)$', line)
        if m:
            problems += arg_problems(m.group(2).replace('"', " ").replace("'", " "), "%s %s" % (rel(f), m.group(1)))

bls_files = []
for d in ("/boot/loader/entries", "/efi/loader/entries", "/boot/efi/loader/entries"):
    bls_files += sorted(glob.glob(p(d, "*.conf")))
ukis = []
for d in ("/boot/efi/EFI/Linux", "/efi/EFI/Linux", "/boot/EFI/Linux"):
    ukis += sorted(glob.glob(p(d, "*.efi")))
if ukis:
    problems.append("unified kernel image(s) present (%s): their embedded command line is not inspected; refusing" % ", ".join(os.path.basename(u) for u in ukis))

# 2. GRUB: resolve the configuration chain the next boot will load.
grub_present = os.path.exists(p("/boot/grub/grub.cfg")) or glob.glob(p("/boot/efi/EFI/*/grub.cfg")) or os.path.exists(p("/boot/grub/i386-pc/load.cfg"))
if grub_present:
    if os.path.isdir(p("/sys/firmware/efi")):
        n = esp_count()
        if n != 1:
            problems.append("%s EFI system partitions found; exactly one must supply the boot configuration; refusing" % ("an unknown number of" if n is None else n))
        stubs = sorted(glob.glob(p("/boot/efi/EFI/*/grub.cfg")))
        if not os.path.exists(p("/boot/efi/EFI/ubuntu/grub.cfg")):
            problems.append("UEFI boot, but /boot/efi/EFI/ubuntu/grub.cfg (read by Ubuntu's signed GRUB, prefix /EFI/ubuntu) is missing; refusing")
        for stub in stubs:
            vendor = os.path.basename(os.path.dirname(stub))
            v = {"root": "MNT:/boot/efi", "prefix": "(MNT:/boot/efi)/EFI/%s" % vendor, "cmdpath": "(MNT:/boot/efi)/EFI/%s" % vendor}
            follow(stub, "(MNT:/boot/efi)/EFI/%s/grub.cfg" % vendor, v, 0)
    else:
        bios_branch()
    seen = set()
    for host, devp, v in finals:
        if host in seen:
            continue
        seen.add(host)
        check_final(host, devp, v)
    mlst = read(p("/boot/grub/menu.lst"))
    if mlst:
        for line in mlst.splitlines():
            m = re.match(r"\s*kernel\s+\S+\s*(.*)$", line)
            if m:
                problems += arg_problems(m.group(1), "/boot/grub/menu.lst")
    if "BOOT_IMAGE=" not in cur and not bls_files:
        problems.append("the current boot did not come through GRUB (no BOOT_IMAGE= in /proc/cmdline): the command line may be set outside this host; refusing")

for f in bls_files:
    for line in (read(f) or "").splitlines():
        m = re.match(r"\s*options\s+(.*)$", line)
        if m:
            problems += arg_problems(m.group(1), "BLS entry " + rel(f))

if not grub_present and not bls_files:
    problems.append("no known boot loader configuration (GRUB or BLS entries): the next boot's kernel command line cannot be determined; refusing")

for x in bios_notes:
    sys.stderr.write("note: %s\n" % x)
for x in problems:
    print(x)
PY
  return 0
}

# Everything else that the next boot would do differently from now: zram
# disabled on the kernel command line, the zram units masked, another boot-time
# zram creator enabled, an encrypted-swap crypttab entry, a next-boot kernel
# without the zram module.
zram_boot_environment_problems() {
  local u state k rel
  # Revision 6: the command line the NEXT boot uses, from the boot loader's
  # generated configuration (and the current boot and GRUB defaults).
  next_boot_cmdline_problems_at_root /
  for u in dev-zram0.swap systemd-zram-setup@zram0.service systemd-zram-setup@.service; do
    state="$(systemctl is-enabled "${u}" 2>/dev/null || true)"
    case "${state}" in masked*) printf '%s is masked: zram would not start at the next boot\n' "${u}" ;; esac
  done
  for u in zramswap.service zram-config.service; do
    state="$(systemctl is-enabled "${u}" 2>/dev/null || true)"
    case "${state}" in enabled*|linked*|alias) printf '%s is enabled: it creates another zram swap at boot\n' "${u}" ;; esac
  done
  awk '$0 !~ /^[[:space:]]*#/ && NF >= 4 && $4 ~ /(^|,)swap(,|$)/ {print "crypttab swap entry " $1 " would create a disk swap at boot"}' /etc/crypttab 2>/dev/null || true
  k="$(readlink -f /boot/vmlinuz 2>/dev/null || true)"
  rel="${k##*/vmlinuz-}"
  if [[ -n "${k}" && "${rel}" != "${k}" ]] && ! modinfo -k "${rel}" zram >/dev/null 2>&1; then
    printf 'the next-boot kernel %s has no zram module\n' "${rel}"
  fi
  return 0
}

zram_next_boot_divergences() {
  zram_effective_config_problems "$1" "$2"
  zram_boot_environment_problems
  swappiness_problems
  return 0
}
# --- end of next-boot swap state -------------------------------------------

# Writeback device of an active zram device (none when the kernel lacks writeback).
zram_backing_dev() {
  if [[ -r "/sys/block/$1/backing_dev" ]]; then
    cat "/sys/block/$1/backing_dev"
  else
    printf 'none\n'
  fi
}


# Persistent swap that would come back at boot: swap entries in the canonical
# /etc/fstab and enabled .swap units other than the generated zram one.
persistent_non_zram_swap_sources() {
  awk '$0 !~ /^[[:space:]]*#/ && NF >= 3 && $3 == "swap" {print "fstab swap entry " $1}' /etc/fstab 2>/dev/null || true
  systemctl list-unit-files --type=swap --state=enabled --no-legend 2>/dev/null | awk '$1 != "dev-zram0.swap" {print "enabled swap unit " $1}' || true
  return 0
}

# zram-only postcondition (owner ruling 2026-09-25): /dev/zram0 active, no
# writeback on any active zram device, no other swap (no other zram device
# either: the reviewed policy configures exactly one), the canonical zram
# configuration valid, no persistent non-zram swap, and no legacy loop-swap
# source (canonical wins-cryptswap.service inactive and disabled).
zram_only_swap_postcondition() {
  local swap_src swap_real zram_active=0 failures=0 backing legacy persistent nextboot
  while IFS= read -r swap_src; do
    [[ -n "${swap_src}" ]] || continue
    swap_real="$(readlink -f "${swap_src}" 2>/dev/null || printf '%s' "${swap_src}")"
    case "${swap_real}" in
      /dev/zram*)
        backing="$(zram_backing_dev "${swap_real#/dev/}")"
        if [[ "${backing}" != "none" ]]; then
          err "${swap_real} has a writeback device (${backing}); compressed pages could reach the disk."
          failures=$((failures + 1))
        fi
        if [[ "${swap_real}" == "/dev/zram0" ]]; then
          zram_active=1
        else
          err "Swap source ${swap_real} is an extra zram device; only /dev/zram0 is configured by the reviewed policy."
          failures=$((failures + 1))
        fi
        ;;
      *)
        err "Swap source ${swap_src} is not zram; only zram swap is allowed (owner ruling 2026-09-25)."
        failures=$((failures + 1))
        ;;
    esac
  done < <(swapon --noheadings --raw --show=NAME 2>/dev/null)
  if ((zram_active == 0)); then
    err "/dev/zram0 is not active as swap."
    failures=$((failures + 1))
  fi
  nextboot="$(zram_next_boot_divergences "${ZRAM_SWAP_PERCENT:-$ZRAM_SWAP_PERCENT_DEFAULT}" "${ZRAM_SWAP_MAX_MB:-$ZRAM_SWAP_MAX_MB_DEFAULT}" | paste -sd ';' -)"
  if [[ -n "${nextboot}" ]]; then
    err "The next boot would not be zram-only as reviewed: ${nextboot}"
    failures=$((failures + 1))
  fi
  if [[ -n "${WINS_ZRAM_CONFIG_PATH:-}" && "${WINS_ZRAM_CONFIG_PATH}" != "${WINS_ZRAM_CANONICAL_CONFIG}" && -f "${WINS_ZRAM_CONFIG_PATH}" ]] \
     && grep -Eq '^[[:space:]]*writeback-device[[:space:]]*=' "${WINS_ZRAM_CONFIG_PATH}"; then
    err "${WINS_ZRAM_CONFIG_PATH} configures a zram writeback device."
    failures=$((failures + 1))
  fi
  persistent="$(persistent_non_zram_swap_sources | paste -sd ';' -)"
  if [[ -n "${persistent}" ]]; then
    err "Persistent non-zram swap would return at boot: ${persistent}"
    failures=$((failures + 1))
  fi
  legacy="$(legacy_loop_swap_sources | paste -sd ';' -)"
  if [[ -n "${legacy}" ]]; then
    err "Legacy loop-backed swap is still present: ${legacy}"
    failures=$((failures + 1))
  fi
  ((failures == 0)) || return 1
  log "Swap is zram only now and at the next boot: /dev/zram0 active without writeback, effective zram-generator configuration equal to the reviewed policy, no other active or persistent swap, no wins-cryptswap source."
  # Interim-off nodes (Round CS3 OI-6) keep the disabled unit and its 12 GiB
  # image on disk. They are not a swap source; leave them to the migration.
  if [[ -e "${WINS_LEGACY_CRYPTSWAP_UNIT_FILE}" || -e "${WINS_LEGACY_CRYPTSWAP_BACKING}" || -e "${WINS_LEGACY_CRYPTSWAP_HELPER}" ]]; then
    warn "Inactive legacy loop-swap files remain (${WINS_LEGACY_CRYPTSWAP_UNIT_FILE}, ${WINS_LEGACY_CRYPTSWAP_HELPER}, ${WINS_LEGACY_CRYPTSWAP_BACKING}); remove them with wins_cryptswap_to_zram_migrate.sh apply."
  fi
}

# Kernel upgrades arrive through a kernel metapackage. linux-virtual (most of
# this fleet) pulls linux-image-<ver>-generic WITHOUT linux-modules-extra, so a
# later kernel would boot without the zram module and therefore without swap.
# linux-image-extra-virtual depends on linux-image-generic, which depends on the
# matching linux-modules-extra, so every future kernel brings zram with it.
ensure_zram_kept_across_kernel_upgrades() {
  local zram_enabled="${ENABLE_ZRAM_SWAP:-$ENABLE_ZRAM_SWAP_DEFAULT}" meta candidate
  case "$(printf '%s' "${zram_enabled}" | tr '[:upper:]' '[:lower:]')" in
    0|false|no|off) return 0 ;;
  esac
  for meta in linux-image-generic linux-generic linux-image-extra-virtual; do
    if dpkg-query -W -f='${db:Status-Abbrev}' "${meta}" 2>/dev/null | grep -Fx 'ii ' >/dev/null; then
      log "Kernel metapackage ${meta} keeps linux-modules-extra (zram) installed across kernel upgrades"
      return 0
    fi
  done
  candidate="$(apt-cache policy linux-image-extra-virtual | awk '/^[[:space:]]*Candidate:/ {candidate=$2} END {print candidate}')"
  [[ -n "${candidate}" && "${candidate}" != "(none)" ]] || {
    err "Ubuntu package linux-image-extra-virtual is unavailable; a later kernel upgrade would drop the zram module."
    return 1
  }
  apt_retry "${APT_GET[@]}" install -y --no-install-recommends linux-image-extra-virtual
  dpkg-query -W -f='${db:Status-Abbrev}' linux-image-generic 2>/dev/null | grep -Fx 'ii ' >/dev/null || {
    err "linux-image-extra-virtual did not install linux-image-generic; zram support is not kept across kernel upgrades."
    return 1
  }
  log "Installed linux-image-extra-virtual so every future kernel brings linux-modules-extra (zram)"
}

# render-only is exercised by the isolated policy test harness.
# shellcheck disable=SC2120
configure_zram_swap() {
  local mode="${1:-apply}"
  local enabled="${ENABLE_ZRAM_SWAP:-$ENABLE_ZRAM_SWAP_DEFAULT}"
  local percent="${ZRAM_SWAP_PERCENT:-$ZRAM_SWAP_PERCENT_DEFAULT}"
  local max_mb="${ZRAM_SWAP_MAX_MB:-$ZRAM_SWAP_MAX_MB_DEFAULT}"
  local config_path="${WINS_ZRAM_CONFIG_PATH:-/etc/systemd/zram-generator.conf}"
  local generator_path="${WINS_ZRAM_GENERATOR_PATH:-/usr/lib/systemd/system-generators/zram-generator}"
  local config_dir staging="" kernel_release zram_module_path zram_module_real zram_module_root
  local zram_module_package zram_owned_path zram_module_package_match=0
  local generator_real generator_owned_path generator_package_match=0
  [[ "${mode}" == "apply" || "${mode}" == "render-only" ]] || {
    err "Internal zram configuration mode is invalid."
    return 1
  }
  validate_zram_policy_settings || return 1
  case "${enabled,,}" in
    0|false|no|off) return 0 ;;
  esac
  [[ -x "${generator_path}" && -f "${generator_path}" && ! -L "${generator_path}" ]] || {
    err "The Ubuntu systemd-zram-generator executable is unavailable or unsafe."
    return 1
  }
  if [[ "${mode}" == "apply" ]]; then
    generator_real="$(readlink -f "${generator_path}")"
    while IFS= read -r generator_owned_path; do
      [[ "${generator_owned_path}" == /* && -e "${generator_owned_path}" ]] || continue
      if [[ "$(readlink -f "${generator_owned_path}")" == "${generator_real}" ]]; then
        generator_package_match=1
      fi
    done < <(dpkg-query -L systemd-zram-generator)
    (( generator_package_match == 1 )) || {
      err "The zram generator is not owned by the expected Ubuntu package."
      return 1
    }
    kernel_release="$(uname -r)"
    [[ "${kernel_release}" =~ ^[0-9A-Za-z.+_~-]+$ ]] || {
      err "The running kernel release is malformed."
      return 1
    }
    modprobe zram || {
      err "The verified zram kernel module could not be loaded."
      return 1
    }
    [[ -d /sys/class/zram-control ]] || {
      err "The kernel did not expose zram-control after module load."
      return 1
    }
    zram_module_path="$(modinfo -n zram)"
    if [[ "${zram_module_path}" == "(builtin)" ]]; then
      grep -Fxq 'CONFIG_ZRAM=y' "/boot/config-${kernel_release}" || {
        err "zram reports built-in without a matching kernel configuration."
        return 1
      }
    else
      zram_module_real="$(readlink -f "${zram_module_path}")"
      zram_module_root="$(readlink -f "/lib/modules/${kernel_release}")"
      case "${zram_module_real}" in
        "${zram_module_root}/"*) ;;
        *)
          err "The zram module escapes the running kernel module tree."
          return 1
          ;;
      esac
      [[ -f "${zram_module_real}" && ! -L "${zram_module_real}" ]] || {
        err "The zram module file is unavailable or unsafe."
        return 1
      }
      for zram_module_package in \
        "linux-modules-${kernel_release}" \
        "linux-modules-extra-${kernel_release}"; do
        dpkg-query -W -f='${db:Status-Abbrev}' "${zram_module_package}" 2>/dev/null |
          grep -Fxq 'ii ' || continue
        while IFS= read -r zram_owned_path; do
          [[ "${zram_owned_path}" == /* && -e "${zram_owned_path}" ]] || continue
          if [[ "$(readlink -f "${zram_owned_path}")" == "${zram_module_real}" ]]; then
            zram_module_package_match=1
          fi
        done < <(dpkg-query -L "${zram_module_package}")
      done
      (( zram_module_package_match == 1 )) || {
        err "The zram module is not owned by the matching Ubuntu kernel package."
        return 1
      }
    fi
  fi
  config_dir="$(dirname "${config_path}")"
  [[ ! -L "${config_dir}" && ! -L "${config_path}" ]] || {
    err "The zram configuration path must not traverse a symbolic link."
    return 1
  }
  install -d -m 755 "${config_dir}"
  staging="$(mktemp "${config_dir}/.wins-zram-generator.XXXXXX")"
  chmod 600 "${staging}"
  cat > "${staging}" <<EOF
# Managed by Win's VPN. Compressed RAM only: intentionally no writeback-device.
[zram0]
zram-size = min(ram * ${percent} / 100, ${max_mb})
compression-algorithm = zstd
swap-priority = 100
EOF
  chmod 644 "${staging}"
  mv -f -- "${staging}" "${config_path}"
  [[ "${mode}" == "render-only" ]] && return 0
  systemctl daemon-reload
  systemctl start dev-zram0.swap
  if ! swapon --noheadings --raw --show=NAME 2>/dev/null | grep -Fx '/dev/zram0' >/dev/null; then
    err "zram swap did not become active after configuration."
    return 1
  fi
  log "Enabled compressed RAM swap on /dev/zram0 (percent=${percent}, max_mb=${max_mb}, no disk writeback)"
}

# The file-backed loop swap chain (backing image -> loop -> dm-crypt plain) that
# earlier installer versions built here is removed: it deadlocks under memory
# pressure (Chicago and Spain, 2026-09-24). Nodes that still carry it are moved
# by wins_cryptswap_to_zram_migrate.sh; this installer only detects and refuses it.

configure_swap_policy() {
  local fstab_path="${WINS_FSTAB_PATH:-/etc/fstab}"
  local managed_swapfile="${WINS_SWAPFILE_PATH:-/swapfile}"
  local memory_sysctl_path="${WINS_MEMORY_SYSCTL_PATH:-/etc/sysctl.d/98-winsvpn-memory.conf}"
  log "Applying conservative swap and memory pressure policy"
  # Unconditional, before any swap or sysctl change, whatever the environment says.
  refuse_legacy_loop_swap || return 1
  refuse_disk_swap_request || return 1
  cat > "${memory_sysctl_path}" <<'EOF'
vm.swappiness=10
vm.vfs_cache_pressure=50
vm.dirty_background_ratio=5
vm.dirty_ratio=20
EOF
  sysctl -p "${memory_sysctl_path}" >/dev/null 2>&1 || \
    warn "Memory sysctl apply reported a warning; deployment will continue"

  # Establish fast, non-persistent pressure relief before provider disk swap is
  # removed. No writeback device is configured, so pages cannot spill from
  # zram onto the unencrypted root disk.
  # Production intentionally uses the default apply mode.
  # shellcheck disable=SC2119
  configure_zram_swap

  # Disk swap was refused at the top of this function (refuse_disk_swap_request).
  # The early bootstrap guard already stops active plaintext swap before any
  # credential file is sourced.  This persistent phase removes provider fstab
  # entries and the known file so plaintext swap cannot return after reboot.
  if ! root_backed_by_luks && [[ ! "${ALLOW_UNENCRYPTED_SWAPFILE:-$ALLOW_UNENCRYPTED_SWAPFILE_DEFAULT}" =~ ^(1|true|yes|on)$ ]]; then
    local plaintext_swap
    plaintext_swap="$(unencrypted_swap_devices | paste -sd ',' -)"
    if [[ -n "${plaintext_swap}" ]]; then
      warn "Disabling unencrypted swap before control-plane deployment continues: ${plaintext_swap}"
      local swap_src
      while IFS= read -r swap_src; do
        [[ -n "${swap_src}" ]] || continue
        swapoff "${swap_src}" || {
          err "Unable to disable unencrypted swap ${swap_src}; control-plane deployment stopped."
          return 1
        }
      done < <(unencrypted_swap_devices)
    fi
    if [[ -f "${fstab_path}" ]]; then
      sed -i -E '/^[[:space:]]*[^#[:space:]]+[[:space:]]+([^[:space:]]+[[:space:]]+)?swap([[:space:]]|$)/d' "${fstab_path}"
    fi
    if [[ -e "${managed_swapfile}" ]]; then
      rm -f -- "${managed_swapfile}"
    fi
    plaintext_swap="$(unencrypted_swap_devices | paste -sd ',' -)"
    [[ -z "${plaintext_swap}" ]] || {
      err "Unencrypted swap remains active after hardening: ${plaintext_swap}"
      return 1
    }
    if [[ "${ENABLE_WINS_SWAPFILE:-$ENABLE_WINS_SWAPFILE_DEFAULT}" =~ ^(1|true|yes|on)$ ]]; then
      warn "Root is not LUKS encrypted, so disk swap is disabled; compressed RAM swap remains available."
    fi
    return 0
  fi

  # Disk swap was refused at the top of this function (refuse_disk_swap_request):
  # zram, configured above, is the swap.
  return 0
}

collect_luks_unlock_authorized_keys() {
  if [[ -n "${LUKS_UNLOCK_SSH_AUTHORIZED_KEYS:-}" ]]; then
    printf '%s\n' "${LUKS_UNLOCK_SSH_AUTHORIZED_KEYS}"
    return 0
  fi
  # CP-1: inbound login keys only. id_ed25519.pub and id_rsa.pub are this
  # host's own outbound identities; their private halves sit on the locked
  # disk, so authorising them in dropbear locks every operator out at boot.
  local key_file="${WINS_ROOT_SSH_DIR:-/root/.ssh}/authorized_keys"
  if [[ -s "${key_file}" ]]; then
    cat "${key_file}"
    return 0
  fi
  return 1
}

configure_luks_root_policy() {
  local require_luks="${REQUIRE_LUKS_ROOT:-$REQUIRE_LUKS_ROOT_DEFAULT}"
  local remote_unlock="${LUKS_REMOTE_UNLOCK:-$LUKS_REMOTE_UNLOCK_DEFAULT}"
  local unlock_port="${LUKS_UNLOCK_SSH_PORT:-$LUKS_UNLOCK_SSH_PORT_DEFAULT}"
  local initramfs_ip="${LUKS_INITRAMFS_IP:-$LUKS_INITRAMFS_IP_DEFAULT}"
  local initramfs_device="${LUKS_INITRAMFS_DEVICE:-$LUKS_INITRAMFS_DEVICE_DEFAULT}"
  local dropbear_dir="${WINS_DROPBEAR_INITRAMFS_DIR:-/etc/dropbear/initramfs}"
  local initramfs_etc="${WINS_INITRAMFS_TOOLS_DIR:-/etc/initramfs-tools}"
  local unlock_conf="${WINS_INITRAMFS_UNLOCK_CONF:-${initramfs_etc}/conf.d/winn-fde-network}"
  local legacy_unlock_conf="${unlock_conf%/*}/wins-remote-unlock"
  local backup_root="${WINS_LUKS_UNLOCK_BACKUP_DIR:-/var/backups/winsvpn-luks-unlock}"
  local keys swap_plain wan_if stage backup_dir pub blob index stale foreign changed=0 chain_written=0
  local -a unlock_files stale_files

  if ! root_backed_by_luks; then
    if [[ "${require_luks}" == "1" ]]; then
      err "Root filesystem is not backed by LUKS/dm-crypt. Reset/reinstall this VPS with LUKS root encryption first, then rerun."
      exit 1
    fi
    warn "Root filesystem is not LUKS encrypted. Disk-encryption posture=${CONTROL_DISK_ENCRYPTION_EFFECTIVE:-unset}. The substitute control set does not protect a powered-off disk. Set CONTROL_DISK_ENCRYPTION_MODE=luks or REQUIRE_LUKS_ROOT=1 after reinstalling with LUKS to require full-disk encryption."
    return 0
  fi

  log "Root filesystem is backed by LUKS/dm-crypt"
  swap_plain="$(unencrypted_swap_devices | paste -sd ',' -)"
  if [[ -n "${swap_plain}" ]]; then
    if [[ "${require_luks}" == "1" ]]; then
      err "Unencrypted swap detected: ${swap_plain}. Reinstall with swap inside LUKS or disable swap before deployment."
      exit 1
    fi
    warn "Unencrypted swap detected: ${swap_plain}. Secrets may be written to disk outside LUKS."
  fi

  warn "Standard VPS remote unlock leaves /boot and /boot/efi unencrypted so initramfs can start networking. This protects root/swap at rest, not a live malicious hypervisor."

  [[ "${remote_unlock}" == "1" ]] || {
    warn "LUKS remote unlock configuration skipped because LUKS_REMOTE_UNLOCK=${remote_unlock}"
    return 0
  }

  # CP-1: a redeploy keeps the unlock keys already in dropbear. Only an
  # explicit LUKS_UNLOCK_SSH_AUTHORIZED_KEYS replaces them, because changing
  # who can unlock this disk is an access change.
  stage="$(mktemp -d)"
  if [[ -z "${LUKS_UNLOCK_SSH_AUTHORIZED_KEYS:-}" && -s "${dropbear_dir}/authorized_keys" ]]; then
    cp -- "${dropbear_dir}/authorized_keys" "${stage}/authorized_keys"
    log "Keeping the existing LUKS unlock keys in ${dropbear_dir}/authorized_keys; set LUKS_UNLOCK_SSH_AUTHORIZED_KEYS to replace them."
    for pub in "${WINS_ROOT_SSH_DIR:-/root/.ssh}/id_ed25519.pub" "${WINS_ROOT_SSH_DIR:-/root/.ssh}/id_rsa.pub"; do
      blob="$(awk 'NR == 1 {print $2}' "${pub}" 2>/dev/null || true)"
      if [[ -n "${blob}" ]] && grep -Fq -- "${blob}" "${stage}/authorized_keys"; then
        warn "The LUKS unlock keys include this host's own ${pub##*/}, whose private key is on the locked disk. Set LUKS_UNLOCK_SSH_AUTHORIZED_KEYS to the operator keys to replace them."
      fi
    done
  else
    keys="$(collect_luks_unlock_authorized_keys)" || {
      rm -rf -- "${stage}"
      err "LUKS remote unlock needs an SSH public key. Set LUKS_UNLOCK_SSH_AUTHORIZED_KEYS or install /root/.ssh/authorized_keys first."
      exit 1
    }
    printf '%s\n' "${keys}" > "${stage}/authorized_keys"
  fi
  apt_retry "${APT_GET[@]}" install -y cryptsetup-initramfs dropbear-initramfs busybox
  install -d -m 700 "${dropbear_dir}" "${unlock_conf%/*}"
  cat > "${stage}/dropbear.conf" <<EOF
DROPBEAR_OPTIONS="-I 180 -j -k -p ${unlock_port} -s -c cryptroot-unlock"
IFDOWN=none
EOF
  # Early-boot network: ONE file, ONE DHCP owner (handoff section 42, Kansas
  # 2026-09-04). deploy/fde_boot_chain.sh writes conf.d/winn-fde-network when it
  # converts a host; that file is kept here unless LUKS_INITRAMFS_IP or
  # LUKS_INITRAMFS_DEVICE is set for this run. The legacy wins-remote-unlock
  # file sorted after it and overrode it with DEVICE=<iface>: it is removed.
  # With IP=dhcp DEVICE stays empty (dropbear's init-premount script owns DHCP
  # alone), and no local init-premount script may call configure_networking.
  if [[ -s "${unlock_conf}" && ! -L "${unlock_conf}" ]]; then
    if grep -Eq "^[[:space:]]*DEVICE=['\"]?[^'\"[:space:]]+['\"]?[[:space:]]*$" "${unlock_conf}"; then
      rm -rf -- "${stage}"
      err "${unlock_conf} pins an early-boot DEVICE (the handoff section 42 shape that raced dropbear). This installer will not rebuild an initramfs from it: re-arm with the current deploy/fde_boot_chain.sh or repair the file by hand (DEVICE=''), then rerun."
      exit 1
    fi
    if write_early_boot_network_conf dhcp "" | cmp -s -- - "${unlock_conf}"; then
      chain_written=1
    fi
    if [[ -n "${LUKS_INITRAMFS_IP:-}" || -n "${LUKS_INITRAMFS_DEVICE:-}" ]]; then
      rm -rf -- "${stage}"
      err "${unlock_conf} already defines early-boot networking (converter-owned); explicit LUKS_INITRAMFS_IP or LUKS_INITRAMFS_DEVICE overrides are refused on this host. Edit the file deliberately, then rerun without the override."
      exit 1
    fi
    cp -- "${unlock_conf}" "${stage}/${unlock_conf##*/}"
    if (( chain_written )); then
      log "Keeping the early-boot network file ${unlock_conf} written by the boot chain (IP='dhcp', DEVICE='')."
    else
      log "Keeping the existing early-boot network file ${unlock_conf} (empty DEVICE, not the boot chain's exact text)."
    fi
  elif [[ "${initramfs_ip}" == "dhcp" ]]; then
    if [[ "${initramfs_device}" != "auto" && -n "${initramfs_device}" ]]; then
      rm -rf -- "${stage}"
      err "LUKS_INITRAMFS_IP=dhcp needs an EMPTY early-boot DEVICE: dropbear owns DHCP alone (handoff section 42). Unset LUKS_INITRAMFS_DEVICE=${initramfs_device}."
      exit 1
    fi
    write_early_boot_network_conf dhcp "" > "${stage}/${unlock_conf##*/}"
  else
    if [[ "${initramfs_device}" == "auto" ]]; then
      wan_if="$(ip -o route show default 2>/dev/null | awk '{print $5; exit}')"
      initramfs_device="${wan_if:-eth0}"
    fi
    write_early_boot_network_conf "${initramfs_ip}" "${initramfs_device}" > "${stage}/${unlock_conf##*/}"
  fi
  foreign="$(grep -ls 'configure_networking' "${initramfs_etc}"/scripts/init-premount/* 2>/dev/null || true)"
  if [[ -n "${foreign}" ]]; then
    rm -rf -- "${stage}"
    err "A local init-premount script calls configure_networking and would be a second early-boot DHCP owner (handoff section 42): ${foreign//$'\n'/ }. Re-arm with the current deploy/fde_boot_chain.sh or remove it, then rerun."
    exit 1
  fi
  if grep -Eqs '^[[:space:]]*(IP|IP6|DEVICE|DEVICE6|BOOTIF|VLAN)=.+' "${initramfs_etc}/initramfs.conf"; then
    rm -rf -- "${stage}"
    err "${initramfs_etc}/initramfs.conf defines a nonempty early-boot network variable; networking must live only in ${unlock_conf}."
    exit 1
  fi
  foreign="$(grep -lsE '^[[:space:]]*(IP|IP6|DEVICE|DEVICE6|BOOTIF|VLAN)=' "${initramfs_etc}"/conf.d/* 2>/dev/null \
    | grep -vxF -e "${unlock_conf}" -e "${legacy_unlock_conf}" || true)"
  if [[ -n "${foreign}" ]]; then
    rm -rf -- "${stage}"
    err "Early-boot network defined outside ${unlock_conf}: ${foreign//$'\n'/ }. Remove it, then rerun."
    exit 1
  fi
  stale_files=()
  for stale in "${legacy_unlock_conf}" "${initramfs_etc}/scripts/init-premount/zz-winn-fde-network"; do
    if [[ -e "${stale}" || -L "${stale}" ]]; then
      stale_files+=("${stale}")
    fi
  done

  # Back up all three files before any is rewritten, outside the directories
  # initramfs-tools reads, and rebuild the initramfs only when one changed.
  unlock_files=("${dropbear_dir}/authorized_keys" "${dropbear_dir}/dropbear.conf" "${unlock_conf}")
  for index in "${!unlock_files[@]}"; do
    cmp -s -- "${stage}/${unlock_files[index]##*/}" "${unlock_files[index]}" || changed=1
  done
  (( ${#stale_files[@]} == 0 )) || changed=1
  if (( changed == 0 )); then
    rm -rf -- "${stage}"
    log "LUKS remote unlock configuration unchanged on TCP ${unlock_port}; initramfs not rebuilt."
    verify_luks_unlock_initramfs || exit 1
    return 0
  fi
  backup_dir="${backup_root}/$(date -u +%Y%m%d_%H%M%SZ)-$$"
  for index in "${!unlock_files[@]}"; do
    if [[ -e "${unlock_files[index]}" ]]; then
      install -d -m 700 "${backup_root}" "${backup_dir}"
      cp -a -- "${unlock_files[index]}" "${backup_dir}/${unlock_files[index]##*/}"
    fi
  done
  for stale in "${stale_files[@]}"; do
    install -d -m 700 "${backup_root}" "${backup_dir}"
    cp -a -- "${stale}" "${backup_dir}/${stale##*/}" 2>/dev/null || true
    rm -f -- "${stale}"
    log "Removed ${stale}: a second early-boot network definition (handoff section 42); copy kept in ${backup_dir}."
  done
  [[ ! -d "${backup_dir}" ]] || log "Previous LUKS remote unlock files backed up to ${backup_dir}"
  for index in "${!unlock_files[@]}"; do
    cp -- "${stage}/${unlock_files[index]##*/}" "${unlock_files[index]}"
  done
  chmod 600 "${dropbear_dir}/authorized_keys"
  rm -rf -- "${stage}"
  update-initramfs -u -k all
  verify_luks_unlock_initramfs || exit 1
  log "LUKS remote unlock prepared on TCP ${unlock_port}. After reboot, unlock with: ssh -p ${unlock_port} root@<server-ip> cryptroot-unlock"
}

# ---------------------------------------------------------------------------
# Disk-encryption substitute control set (control plane)
#
# WHAT LUKS WAS PROTECTING HERE. The hub's at-rest secrets are not AWG private
# keys (those live on data-plane / core hops). They are: the account/node
# database, vpn_auth.env (ADMIN_TOKEN, SPA, SMTP, PayPal, Cloudflare, AI keys,
# redemption HMAC, BTCPay, Monero RPC), the rclone crypt password, origin TLS
# keys, the hub SSH key, the cloudflared connector token, optional winn-server
# credentials, local backup archives (which
# copy all of the above), the security-events DB, the optional partial-vault
# LUKS image, and paged-out copies of all of the above.
#
# WINN3_DESCRIPTOR_PUBKEY_G1 is a PUBLIC verification key stored inside
# vpn_auth.env. This installer never writes a descriptor private key. It is
# listed in the inventory comment so it is not mistaken for a secret; the
# file that contains it is still secret because of everything else in it.
#
# /etc/winsvpn itself is 750 root:cloudflared after configure_control_origin_tunnel,
# so it is NOT in the 077 inventory; the secret files inside it are listed
# individually. Suricata eve.json under /var/log/suricata is package-owned and
# is not chmod'd here (same gap the Core lane flagged).
#
# The substitute set is: (1) every secret path is unreadable to anything but
# root/its service, verified not assumed; (2) paged-out key material never
# lands on disk in the clear (random-key dm-crypt swap -- zram does not count
# as the WINS_SWAPFILE_SIZE disk swap); (3) core dumps / persistent journal /
# hibernation stay closed (harden_crash_artifacts).
#
# WHAT IT DOES NOT DO. All three are enforced by the RUNNING KERNEL. Pull the
# disk out and the file modes are just numbers in an inode. LUKS is what makes
# a powered-off disk useless, and nothing below substitutes for that.
# ---------------------------------------------------------------------------

control_flag_is_on() {
  case "$(printf '%s' "${1:-}" | tr '[:upper:]' '[:lower:]')" in
    1|true|yes|on) return 0 ;;
    *) return 1 ;;
  esac
}

# Crypt-backed DISK swap names, excluding zram/ram. Used so zram cannot satisfy
# the substitute disk-swap postcondition on this installer (unlike Core, this
# script always enables zram first).
encrypted_disk_swap_names() {
  local swap_src swap_real backing_src backing_real
  swapon --noheadings --raw --show=NAME 2>/dev/null | while IFS= read -r swap_src; do
    [[ -n "${swap_src}" ]] || continue
    case "${swap_src}" in
      /dev/zram*|/dev/ram*) continue ;;
    esac
    swap_real="$(readlink -f "${swap_src}" 2>/dev/null || printf '%s' "${swap_src}")"
    case "${swap_real}" in
      /dev/zram*|/dev/ram*) continue ;;
    esac
    if [[ ! -b "${swap_real}" ]]; then
      backing_src="$(findmnt -no SOURCE -T "${swap_real}" 2>/dev/null || true)"
      [[ -n "${backing_src}" ]] || continue
      backing_real="$(readlink -f "${backing_src}" 2>/dev/null || printf '%s' "${backing_src}")"
    else
      backing_real="${swap_real}"
    fi
    if lsblk -spno TYPE "${backing_real}" 2>/dev/null | grep -x "crypt" >/dev/null; then
      printf '%s\n' "${swap_src}"
    fi
  done
}

# The secrets inventory as data: "<path>|<max_mode_bits_that_must_be_clear>|<label>".
# Second field is a find(1) -perm /MASK argument: the check fails if ANY bit in
# the mask is set. 077 = "no group or other access at all". 007 = "no other".
# Paths that do not exist are skipped by the sweeper (optional features).
#
# `-type f -o -type l`, not `-type f` alone: a symlink is not a regular file,
# so enumerating only regular files would silently SKIP a secret that had been
# replaced by a symlink -- exactly the case the -L check downstream exists to
# refuse.
control_secret_path_specs() {
  local env_file="${ENV_FILE:-/root/vpn_auth.env}"
  local app_dir="${APP_DIR:-/root/vpn_auth}"
  local db_path="${DB_PATH:-${app_dir}/vpn_users.db}"
  local legacy_env="${LEGACY_ENV_FILE:-${app_dir}/.env}"
  local defaults_file="${WINS_DEFAULTS_FILE:-/root/winsvpn-defaults.env}"
  local secrets_file="${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}"
  local ssh_home="${CONTROL_SSH_HOME:-/root/.ssh}"
  local hub_ssh="${CONTROL_HUB_SSH_KEY:-${ssh_home}/id_rsa}"
  local rclone_conf="${CONTROL_RCLONE_CONFIG:-/root/.config/rclone/rclone.conf}"
  local backup_env="${CONTROL_BACKUP_ENV:-/etc/winsvpn/backup.env}"
  local tunnel_id_file="${CONTROL_TUNNEL_ID_FILE:-/etc/winsvpn/control-tunnel-id}"
  local cf_token="${CONTROL_CLOUDFLARED_TOKEN_FILE:-/etc/cloudflared/control-token}"
  local origin_key="${CONTROL_ORIGIN_TLS_KEY:-/etc/winsvpn/tls/hub-origin.key}"
  local website_key="${WEBSITE_TLS_KEY:-/etc/winsvpn/tls/website-ev.key}"
  local server_env="${CONTROL_WINN_SERVER_ENV:-/etc/winn/server.env}"
  local creds_dir="${WINN_CREDENTIALS_DIR:-/etc/winn/credentials}"
  local ssh_key_dir="${CONTROL_SSH_HOST_KEY_DIR:-/etc/ssh}"
  local cryptswap_backing="/var/lib/wins-cryptswap/backing.img"
  local rclone_dir="${CONTROL_RCLONE_DIR:-/root/.config/rclone}"
  local cf_dir="${CONTROL_CLOUDFLARED_DIR:-/etc/cloudflared}"
  local vault_image="${WINS_PARTIAL_VAULT_IMAGE:-${WINS_PARTIAL_VAULT_IMAGE_DEFAULT:-/var/lib/winsvpn-vault.luks}}"
  local vault_mount="${WINS_PARTIAL_VAULT_MOUNT:-${WINS_PARTIAL_VAULT_MOUNT_DEFAULT:-/srv/winsvpn-vault}}"
  local backup_dir="${WINS_LOCAL_BACKUP_DIR:-/var/backups/winsvpn}"
  local manifest_dir="${WINS_BACKUP_MANIFEST_DIR:-/var/backups/winsvpn-manifests}"
  local alerts_dir="${CONTROL_ALERTS_DIR:-/var/lib/wins-security-alerts}"
  local alerts_db="${SECURITY_EVENTS_DB:-${SECURITY_EVENTS_DB_DEFAULT:-/var/lib/wins-security-alerts/security_events.db}}"
  local tls_dir="${CONTROL_TLS_DIR:-/etc/winsvpn/tls}"
  local recovery_state="${CONTROL_SSH_RECOVERY_STATE:-/etc/winsvpn/ssh-recovery-state}"
  local legacy_backup_dir="${CONTROL_LEGACY_BACKUP_DIR:-/root/winsvpn-backups}"
  local legacy_audit_dir="${CONTROL_LEGACY_AUDIT_DIR:-/root/wins-audit-backups}"
  local conf entries

  printf '%s\n' "${env_file}|077|hub runtime env (ADMIN_TOKEN, SPA, SMTP, PayPal, Cloudflare, AI, redemption, BTCPay, Monero; also holds public WINN3_DESCRIPTOR_PUBKEY_G1)"
  printf '%s\n' "${legacy_env}|077|legacy hub env mirror"
  printf '%s\n' "${defaults_file}|077|one-touch defaults file"
  printf '%s\n' "${secrets_file}|077|injected one-touch secrets file"
  printf '%s\n' "${db_path}|077|hub account/node database"
  printf '%s\n' "${db_path}-wal|077|hub database WAL"
  printf '%s\n' "${db_path}-shm|077|hub database SHM"
  printf '%s\n' "${hub_ssh}|077|hub SSH private key (data-plane sync)"
  printf '%s\n' "${LITESTREAM_SFTP_KEY_PATH:-${LITESTREAM_SFTP_KEY_PATH_DEFAULT:-/root/.ssh/wins_litestream_ed25519}}|077|Litestream SFTP client key (writes the off-host replica)"
  printf '%s\n' "${rclone_conf}|077|rclone crypt config (backup encryption password lives here)"
  printf '%s\n' "${backup_env}|077|backup policy env"
  printf '%s\n' "${tunnel_id_file}|077|control Cloudflare tunnel id"
  printf '%s\n' "${cf_token}|007|cloudflared control-origin connector token (640 root:cloudflared)"
  printf '%s\n' "${cf_dir}/appcloud-credentials.json|007|cloudflared app-zone tunnel credentials (640 root:cloudflared)"
  printf '%s\n' "${origin_key}|077|hub origin TLS private key"
  printf '%s\n' "${website_key}|077|website TLS private key"
  printf '%s\n' "${server_env}|007|winn-server env (640)"
  printf '%s\n' "${cryptswap_backing}|077|encrypted-swap backing image"
  printf '%s\n' "${app_dir}|077|hub application directory"
  printf '%s\n' "${ssh_home}|077|hub SSH directory"
  printf '%s\n' "${creds_dir}|077|winn-server credentials directory"
  printf '%s\n' "${rclone_dir}|077|rclone config directory"
  printf '%s\n' "${cf_dir}|007|cloudflared token directory (750 root:cloudflared)"
  printf '%s\n' "${vault_image}|077|partial-vault LUKS image (optional; passphrase is never stored on the VPS)"
  printf '%s\n' "${vault_mount}|077|partial-vault mount directory"
  printf '%s\n' "${backup_dir}|077|local hub backup directory (archives hold the node DB and every hub secret)"
  printf '%s\n' "${manifest_dir}|077|hub backup manifest directory"
  printf '%s\n' "${alerts_dir}|077|security-events directory"
  printf '%s\n' "${alerts_db}|077|security-events database"
  printf '%s\n' "${tls_dir}|077|hub TLS directory"
  printf '%s\n' "${recovery_state}|077|sshd recovery-window state"
  printf '%s\n' "${legacy_backup_dir}|077|legacy local backup directory"
  printf '%s\n' "${legacy_audit_dir}|077|legacy audit backup directory"

  if [[ -n "${SITE_AI_VERTEX_CREDENTIALS_PATH:-}" ]]; then
    printf '%s\n' "${SITE_AI_VERTEX_CREDENTIALS_PATH}|077|Vertex AI service-account JSON"
  fi

  entries="$(secret_dir_entries "${creds_dir}" \( -type f -o -type l \))" || return 1
  while IFS= read -r conf; do
    [[ -n "${conf}" ]] || continue
    printf '%s\n' "${conf}|077|winn-server credential file"
  done <<<"${entries}"

  entries="$(secret_dir_entries "${ssh_key_dir}" \( -type f -o -type l \) -name 'ssh_host_*_key')" || return 1
  while IFS= read -r conf; do
    [[ -n "${conf}" ]] || continue
    printf '%s\n' "${conf}|007|SSH host private key"
  done <<<"${entries}"

  entries="$(secret_dir_entries "${backup_dir}" \( -type f -o -type l \))" || return 1
  while IFS= read -r conf; do
    [[ -n "${conf}" ]] || continue
    printf '%s\n' "${conf}|077|local hub backup archive"
  done <<<"${entries}"

  entries="$(secret_dir_entries "${manifest_dir}" \( -type f -o -type l \))" || return 1
  while IFS= read -r conf; do
    [[ -n "${conf}" ]] || continue
    printf '%s\n' "${conf}|077|hub backup manifest"
  done <<<"${entries}"

  entries="$(secret_dir_entries "${app_dir}" \( -type f -o -type l \) -name 'vpn_users.db.pre-fixed-*.bak')" || return 1
  while IFS= read -r conf; do
    [[ -n "${conf}" ]] || continue
    printf '%s\n' "${conf}|077|pre-deploy database backup"
  done <<<"${entries}"

  entries="$(secret_dir_entries "${alerts_dir}" \( -type f -o -type l \))" || return 1
  while IFS= read -r conf; do
    [[ -n "${conf}" ]] || continue
    printf '%s\n' "${conf}|077|security-events file"
  done <<<"${entries}"
}

verify_control_secret_permissions() {
  local path mask label failures=0 checked=0 owner specs perm_hits perm_rc absent_rc
  # LSR R6: the list of secret paths is produced first and its status checked
  # (a directory that cannot be listed fails), instead of being read through a
  # process substitution whose failure would only shorten the list.
  specs="$(control_secret_path_specs)" || {
    err "Could not enumerate the control-plane secret paths; refusing to finish the install."
    return 1
  }
  while IFS='|' read -r path mask label; do
    [[ -n "${path}" ]] || continue
    # -e follows symlinks and is false for a dangling one; -L catches a secret
    # path replaced by a dangling symlink, which must not be skipped. LSR R6:
    # a path neither test sees is skipped only when confirmed absent.
    if [[ ! -e "${path}" && ! -L "${path}" ]]; then
      absent_rc=0
      control_path_absent "${path}" || absent_rc=$?
      (( absent_rc == 0 )) && continue
      err "Secret path ${path} (${label}) could not be inspected; refusing to treat it as absent."
      failures=$((failures + 1))
      continue
    fi
    checked=$((checked + 1))
    if [[ -L "${path}" ]]; then
      # Intentional vault_link_file/vault_link_dir symlinks point into the
      # partial-vault mount. Those are the stronger control (a LUKS image whose
      # passphrase is never stored). A symlink anywhere else is the attack the
      # floor exists to refuse. Default WINS_PARTIAL_VAULT_ENABLED=0, so the
      # common path still refuses every symlink.
      local resolved vault_mount
      vault_mount="${WINS_PARTIAL_VAULT_MOUNT:-${WINS_PARTIAL_VAULT_MOUNT_DEFAULT:-/srv/winsvpn-vault}}"
      resolved="$(readlink -f "${path}" 2>/dev/null || true)"
      if control_flag_is_on "${WINS_PARTIAL_VAULT_ENABLED:-${WINS_PARTIAL_VAULT_ENABLED_DEFAULT:-0}}" \
         && [[ -n "${resolved}" && -n "${vault_mount}" ]] \
         && { [[ "${resolved}" == "${vault_mount}" ]] || [[ "${resolved}" == "${vault_mount}/"* ]]; }; then
        if [[ -L "${resolved}" ]]; then
          err "Secret path ${path} (${label}) is a vault symlink whose target ${resolved} is itself a symlink; refusing."
          failures=$((failures + 1))
          continue
        fi
        path="${resolved}"
      else
        err "Secret path ${path} (${label}) is a symlink; refusing to treat it as protected."
        failures=$((failures + 1))
        continue
      fi
    fi
    owner="$(stat -c '%u' "${path}" 2>/dev/null || printf 'unknown')"
    if [[ "${owner}" != "0" ]]; then
      err "Secret path ${path} (${label}) is not root-owned (uid ${owner})."
      failures=$((failures + 1))
    fi
    # LSR R6 (Sol N-19): find's own status first; a failed find is an
    # uninspected mode and fails the floor.
    perm_rc=0
    perm_hits="$(find "${path}" -prune -perm "/${mask}" -print -quit)" || perm_rc=$?
    if (( perm_rc != 0 )); then
      err "Could not inspect the permissions of secret path ${path} (${label}) (find failed, exit ${perm_rc})."
      failures=$((failures + 1))
    elif [[ -n "${perm_hits}" ]]; then
      err "Secret path ${path} (${label}) is accessible beyond its owner (mode $(stat -c '%a' "${path}" 2>/dev/null || printf '?'), forbidden bits ${mask})."
      failures=$((failures + 1))
    fi
  done <<<"${specs}"

  if ((failures > 0)); then
    err "${failures} secret path(s) failed the control-plane permission floor."
    if [[ "${CONTROL_DISK_ENCRYPTION_EFFECTIVE}" == "substitute" ]]; then
      err "This hub has no LUKS root, so file permissions ARE the at-rest control. Refusing to finish the install."
      return 1
    fi
    err "Refusing to finish the install with secrets readable beyond their owner."
    return 1
  fi
  log "Control-plane secret permission floor verified across ${checked} existing path(s)"
  return 0
}

# Postcondition gate: run AFTER configure_swap_policy. Encrypted DISK swap is
# the one substitute control that cannot be checked before it is provisioned.
# zram is RAM-backed and is already excluded from unencrypted_swap_devices; it
# must not satisfy this gate.
require_encrypted_swap_established() {
  local plain_swap
  plain_swap="$(unencrypted_swap_devices | paste -sd, -)"
  if [[ -n "${plain_swap}" ]]; then
    err "Unencrypted swap is active after swap configuration: ${plain_swap}"
    err "Paged-out memory on this host would contain secrets in the clear. Refusing to continue."
    return 1
  fi
  # Owner ruling 2026-09-25: zram is the swap on every server; disk swap was
  # refused by refuse_disk_swap_request, so the zram-only postcondition always applies.
  zram_only_swap_postcondition || {
    err "ZRAM-ONLY SWAP NOT ESTABLISHED (owner ruling 2026-09-25: zram is the swap on every server); refusing to report this deployment as complete."
    return 1
  }
}

# Preflight/deploy gate. Does not replace configure_luks_root_policy (remote
# unlock + validator contract). Resolves the posture, then checks PRECONDITIONS.
# Postconditions are require_encrypted_swap_established and
# verify_control_secret_permissions.
verify_disk_encryption_posture() {
  local mode require_luks has_luks=0 plain_swap apt_candidate
  mode="$(printf '%s' "${CONTROL_DISK_ENCRYPTION_MODE}" | tr '[:upper:]' '[:lower:]')"
  require_luks="${REQUIRE_LUKS_ROOT:-$REQUIRE_LUKS_ROOT_DEFAULT}"
  case "${mode}" in
    luks|substitute|auto) ;;
    *)
      err "CONTROL_DISK_ENCRYPTION_MODE must be one of: luks, substitute, auto (got '${CONTROL_DISK_ENCRYPTION_MODE}')."
      exit 1
      ;;
  esac

  if [[ "${require_luks}" == "1" ]]; then
    if [[ "${mode}" == "substitute" ]]; then
      err "REQUIRE_LUKS_ROOT=1 and CONTROL_DISK_ENCRYPTION_MODE=substitute cannot both be set."
      err "REQUIRE_LUKS_ROOT=1 is the existing hard-require for a LUKS root and is not weakened."
      exit 1
    fi
    mode="luks"
  fi

  root_backed_by_luks && has_luks=1

  if [[ "${mode}" == "auto" ]]; then
    if ((has_luks)); then mode="luks"; else mode="substitute"; fi
  fi

  if [[ "${mode}" == "luks" ]]; then
    if ((has_luks == 0)); then
      err "CONTROL_DISK_ENCRYPTION_MODE=luks was requested but this root filesystem is not LUKS-backed."
      err "Either reinstall the host with full-disk encryption, or set CONTROL_DISK_ENCRYPTION_MODE=substitute to deploy with the substitute control set (weaker: it does not protect a powered-off disk)."
      exit 1
    fi
    CONTROL_DISK_ENCRYPTION_EFFECTIVE="luks"
  else
    CONTROL_DISK_ENCRYPTION_EFFECTIVE="substitute"
  fi

  plain_swap="$(unencrypted_swap_devices | paste -sd ',' -)"
  if [[ -n "${plain_swap}" ]]; then
    err "Unencrypted swap detected: ${plain_swap}"
    exit 1
  fi
  # Unconditional, whatever the environment says.
  refuse_legacy_loop_swap || exit 1
  refuse_disk_swap_request || exit 1

  if [[ "${CONTROL_DISK_ENCRYPTION_EFFECTIVE}" == "luks" ]]; then
    log "Disk-encryption posture: LUKS root + encrypted swap policy verified"
    return 0
  fi

  log "Disk-encryption posture: no LUKS root; using the substitute control set"

  if ! control_flag_is_on "${ENABLE_WINS_SWAPFILE:-$ENABLE_WINS_SWAPFILE_DEFAULT}"; then
    log "Swap on this hub is compressed RAM (zram) only (owner ruling 2026-09-25); no disk swap is created."
  elif ! control_flag_is_on "${WINS_CRYPTSWAP_ENABLED:-$WINS_CRYPTSWAP_ENABLED_DEFAULT}"; then
    err "SUBSTITUTE CONTROL UNREACHABLE: ENABLE_WINS_SWAPFILE=1 requests disk swap, but this root is not LUKS-backed."
    err "A plain swapfile here would write paged-out hub secrets to disk in the clear."
    err "Set ENABLE_WINS_SWAPFILE=0 (the default: zram-only swap, owner ruling 2026-09-25), or deploy on a LUKS root."
    exit 1
  elif ! command -v cryptsetup >/dev/null 2>&1; then
    # Command substitution, never a -q grep in a pipeline: under `set -o pipefail`
    # an early -q exit can SIGPIPE apt-cache and turn this check into exit 141.
    apt_candidate="$(apt-cache policy cryptsetup 2>/dev/null || true)"
    if [[ ! "${apt_candidate}" =~ Candidate:[[:space:]]+[0-9] ]]; then
      err "SUBSTITUTE CONTROL UNREACHABLE: cryptsetup is neither installed nor installable from the configured apt sources."
      err "Random-key encrypted swap cannot be provisioned, and without a LUKS root there is no other way to keep paged-out keys off the disk."
      exit 1
    fi
  fi

  verify_control_secret_permissions || {
    err "Pre-existing hub secrets do not meet the permission floor required without a LUKS root."
    exit 1
  }

  log "Substitute control preconditions met; the postconditions are re-verified after provisioning"
  return 0
}

control_print_disk_encryption_guarantee() {
  echo
  if [[ "${CONTROL_DISK_ENCRYPTION_EFFECTIVE}" == "luks" ]]; then
    echo "Disk-encryption posture: LUKS ROOT (strongest)."
    echo "  PROTECTED: secrets at rest against a stolen, imaged or seized powered-off disk,"
    echo "             and against a cold provider-side snapshot of the block device."
    echo "  PROTECTED: paged-out key material -- swap is compressed RAM (zram) with no"
    echo "             writeback device, so a swapped-out page never reaches the disk."
    echo "  NOT PROTECTED: anything readable while the host is running and unlocked."
    return 0
  fi
  echo "Disk-encryption posture: SUBSTITUTE CONTROL SET (no LUKS root)."
  echo "  PROTECTED: every hub secret is root-owned and mode 600/640, verified by this"
  echo "             installer at the end of the run, not merely set and hoped for."
  echo "  PROTECTED: paged-out key material -- swap is compressed RAM (zram) with no"
  echo "             writeback device, so a swapped-out page never reaches the disk."
  echo "  PROTECTED: the descriptor verification key on this hub is PUBLIC; the descriptor"
  echo "             signing private key is never stored here. Announcement signing key,"
  echo "             if provisioned, is included in the permission sweep."
  echo "  PROTECTED: core dumps, persistent journal and hibernation images are suppressed."
  echo "  NOT PROTECTED -- READ THIS: a POWERED-OFF DISK. File permissions are enforced by"
  echo "             the running kernel. If the disk is removed, imaged, or seized, or if"
  echo "             the provider takes a cold snapshot of the volume, the node database,"
  echo "             vpn_auth.env, rclone crypt password, TLS keys, and hub SSH key are"
  echo "             readable in the clear. A LUKS root is the only control here that"
  echo "             covers that case."
  echo "  If this hub can be physically reached by someone you do not trust, reinstall it"
  echo "  with full-disk encryption and CONTROL_DISK_ENCRYPTION_MODE=luks."
  return 0
}

read_partial_vault_passphrase() {
  if [[ -n "${WINS_PARTIAL_VAULT_PASSPHRASE:-}" ]]; then
    printf '%s' "${WINS_PARTIAL_VAULT_PASSPHRASE}"
    return 0
  fi
  if [[ -t 0 ]]; then
    local pass pass2
    read -rsp "Win's VPN partial vault passphrase: " pass
    printf '\n' >&2
    read -rsp "Confirm partial vault passphrase: " pass2
    printf '\n' >&2
    [[ "${pass}" == "${pass2}" && -n "${pass}" ]] || {
      err "Partial vault passphrases did not match or were empty."
      exit 1
    }
    printf '%s' "${pass}"
    return 0
  fi
  err "WINS_PARTIAL_VAULT_ENABLED=1 requires WINS_PARTIAL_VAULT_PASSPHRASE or an interactive terminal. The passphrase is not stored on the VPS."
  exit 1
}

vault_link_dir() {
  local path="$1" rel="$2" mount_dir="$3" target
  target="${mount_dir}/${rel}"
  mkdir -p "$(dirname "${target}")"
  if [[ -L "${path}" ]]; then
    return 0
  fi
  if [[ -e "${path}" ]]; then
    if [[ ! -e "${target}" ]]; then
      mv "${path}" "${target}"
    else
      mv "${path}" "${path}.pre-vault.$(date +%Y%m%d%H%M%S)"
    fi
  else
    mkdir -p "${target}"
  fi
  mkdir -p "$(dirname "${path}")"
  ln -s "${target}" "${path}"
}

vault_link_file() {
  local path="$1" rel="$2" mount_dir="$3" target
  target="${mount_dir}/${rel}"
  mkdir -p "$(dirname "${target}")" "$(dirname "${path}")"
  if [[ -L "${path}" ]]; then
    return 0
  fi
  if [[ -e "${path}" ]]; then
    if [[ ! -e "${target}" ]]; then
      mv "${path}" "${target}"
    else
      mv "${path}" "${path}.pre-vault.$(date +%Y%m%d%H%M%S)"
    fi
  fi
  ln -s "${target}" "${path}"
}

write_partial_vault_unlock_tool() {
  local image="$1" name="$2" mount_dir="$3"
  cat > /usr/local/sbin/wins-vault-unlock <<EOF
#!/usr/bin/env bash
set -Eeuo pipefail
IMAGE="${image}"
NAME="${name}"
MOUNT_DIR="${mount_dir}"
if ! cryptsetup status "\${NAME}" >/dev/null 2>&1; then
  read -rsp "Win's VPN vault passphrase: " pass
  printf '\\n' >&2
  printf '%s\\n' "\${pass}" | cryptsetup open --key-file - "\${IMAGE}" "\${NAME}"
fi
mkdir -p "\${MOUNT_DIR}"
if ! mountpoint -q "\${MOUNT_DIR}"; then
  mount "/dev/mapper/\${NAME}" "\${MOUNT_DIR}"
fi
required_units=(
  wins-hub.service
  nginx.service
  wins-hub-backup.timer
  wins-hub-backup-prune.timer
  wins-weekly-maintenance.timer
  wins-gateway-canary.timer
)
if ! systemctl start "\${required_units[@]}"; then
  echo "[ERR] One or more required hub services failed to start after vault unlock." >&2
  exit 1
fi
for unit in "\${required_units[@]}"; do
  if ! systemctl is-active --quiet "\${unit}"; then
    echo "[ERR] Required hub service is not active after vault unlock: \${unit}" >&2
    exit 1
  fi
done
echo "Win's VPN partial vault is unlocked and hub services were started."
EOF
  chmod 700 /usr/local/sbin/wins-vault-unlock
}

configure_partial_vault() {
  local enabled="${WINS_PARTIAL_VAULT_ENABLED:-$WINS_PARTIAL_VAULT_ENABLED_DEFAULT}"
  [[ "${enabled}" =~ ^(1|true|yes|on)$ ]] || return 0

  local image="${WINS_PARTIAL_VAULT_IMAGE:-$WINS_PARTIAL_VAULT_IMAGE_DEFAULT}"
  local mount_dir="${WINS_PARTIAL_VAULT_MOUNT:-$WINS_PARTIAL_VAULT_MOUNT_DEFAULT}"
  local name="${WINS_PARTIAL_VAULT_NAME:-$WINS_PARTIAL_VAULT_NAME_DEFAULT}"
  local size="${WINS_PARTIAL_VAULT_SIZE:-$WINS_PARTIAL_VAULT_SIZE_DEFAULT}"
  local pass

  warn "Partial vault protects Win's VPN secrets at rest, but it does not protect an unencrypted OS root from offline password resets or boot/root tampering."
  pass="$(read_partial_vault_passphrase)"

  # IA-CP-07: never chmod the image's parent. With the default image
  # /var/lib/winsvpn-vault.luks that parent is /var/lib, and `chmod 700
  # /var/lib` locks every non-root service (cloudflared's home is
  # /var/lib/cloudflared) out of its state, taking the hidden-origin tunnel
  # down. The image itself is 0600 and LUKS-encrypted; its directory needs no
  # extra mode. A parent this run has to create is created 0700 (it is ours);
  # an existing one is left alone. Only the dedicated mount point is 0700.
  local image_dir
  image_dir="$(dirname "${image}")"
  [[ -d "${image_dir}" ]] || install -d -m 700 "${image_dir}"
  install -d -m 700 "${mount_dir}"
  # Heal the damage an earlier run of this function did to the shared system
  # directory (Debian/Ubuntu ship /var/lib as root:root 0755).
  if [[ "${image_dir}" == "/var/lib" && "$(stat -c '%a' /var/lib)" == "700" ]]; then
    warn "Restoring /var/lib to 0755: an earlier partial-vault run set it to 0700."
    chmod 755 /var/lib
  fi
  if [[ ! -f "${image}" ]]; then
    log "Creating encrypted partial vault image ${image} (${size})"
    fallocate -l "${size}" "${image}" || {
      err "Unable to allocate partial vault image ${image}"
      exit 1
    }
    chmod 600 "${image}"
    printf '%s\n' "${pass}" | cryptsetup luksFormat --type luks2 --batch-mode --key-file - "${image}"
  fi
  if ! cryptsetup status "${name}" >/dev/null 2>&1; then
    printf '%s\n' "${pass}" | cryptsetup open --key-file - "${image}" "${name}"
  fi
  if ! blkid "/dev/mapper/${name}" >/dev/null 2>&1; then
    mkfs.ext4 -F "/dev/mapper/${name}" >/dev/null
  fi
  mountpoint -q "${mount_dir}" || mount "/dev/mapper/${name}" "${mount_dir}"
  chmod 700 "${mount_dir}"

  vault_link_dir "${APP_DIR}" "control/vpn_auth" "${mount_dir}"
  vault_link_file "${ENV_FILE}" "control/vpn_auth.env" "${mount_dir}"
  vault_link_dir "/var/lib/wins-security-alerts" "control/security-events" "${mount_dir}"
  vault_link_dir "/root/.config/rclone" "shared/rclone" "${mount_dir}"
  vault_link_dir "/etc/winsvpn" "shared/etc-winsvpn" "${mount_dir}"
  write_partial_vault_unlock_tool "${image}" "${name}" "${mount_dir}"
  log "Partial encrypted vault mounted at ${mount_dir}; unlock after reboot with: wins-vault-unlock"
}

setup_control_sysctl() {
  log "Applying control-plane TCP, queue, and non-router hardening"
  cat > /etc/sysctl.d/99-winsvpn-hub.conf <<'EOF'
net.ipv4.ip_forward=0
net.ipv4.conf.all.forwarding=0
net.ipv4.conf.default.forwarding=0
net.ipv4.conf.all.rp_filter=1
net.ipv4.conf.default.rp_filter=1
net.ipv4.conf.all.accept_redirects=0
net.ipv4.conf.default.accept_redirects=0
net.ipv4.conf.all.secure_redirects=0
net.ipv4.conf.default.secure_redirects=0
net.ipv4.conf.all.send_redirects=0
net.ipv4.conf.default.send_redirects=0
net.ipv4.conf.all.accept_source_route=0
net.ipv4.conf.default.accept_source_route=0
net.core.rmem_default=262144
net.core.wmem_default=262144
net.core.rmem_max=67108864
net.core.wmem_max=67108864
net.core.netdev_max_backlog=100000
net.core.somaxconn=65535
net.core.default_qdisc=fq
net.ipv4.tcp_rmem=4096 87380 67108864
net.ipv4.tcp_wmem=4096 65536 67108864
net.ipv4.tcp_congestion_control=bbr
net.ipv4.tcp_fastopen=3
net.ipv4.tcp_mtu_probing=1
net.ipv4.ip_local_port_range=1024 65535
net.ipv4.tcp_fin_timeout=15
net.ipv4.tcp_slow_start_after_idle=0
net.ipv4.tcp_no_metrics_save=1
net.ipv4.tcp_syncookies=1
vm.swappiness=10
vm.vfs_cache_pressure=50
net.ipv6.conf.all.disable_ipv6=1
net.ipv6.conf.default.disable_ipv6=1
net.ipv6.conf.lo.disable_ipv6=1
net.ipv6.conf.all.forwarding=0
net.ipv6.conf.default.forwarding=0
net.ipv6.conf.all.accept_ra=0
net.ipv6.conf.default.accept_ra=0
net.ipv6.conf.all.accept_redirects=0
net.ipv6.conf.default.accept_redirects=0
EOF
  # R1-GLM-2 (the data plane's Mythos L04 F-1): keep the hub's fixed listeners
  # out of the ephemeral range written above (1024-65535): the hub API
  # (uvicorn --port 8000), the site-AI endpoint the Core's reverse tunnel opens
  # on loopback, and the app-zone cloudflared metrics listener. An autobound
  # socket that takes one first makes that bind fail with EADDRINUSE for as
  # long as the socket lives. Appended after the heredoc so the endpoint port
  # comes from this run.
  # A1-ARGON-F2: this runs before write_env, which keeps ${ENV_FILE}'s endpoint
  # when this run supplies none (environment, defaults or secrets file), so read
  # that value the same way load_existing_envs does, in a subshell.
  local site_ai_port site_ai_endpoint="${SITE_AI_LOCAL_ENDPOINT:-}"
  if [[ -z "${site_ai_endpoint}" && -f "${ENV_FILE:-}" ]]; then
    site_ai_endpoint="$(source "${ENV_FILE}" >/dev/null 2>&1 || true; printf '%s' "${SITE_AI_LOCAL_ENDPOINT:-}")"
  fi
  site_ai_port="$(sed -nE 's|^[A-Za-z][A-Za-z0-9+.-]*://[^/]*:([0-9]{1,5})(/.*)?$|\1|p' <<<"${site_ai_endpoint:-$SITE_AI_LOCAL_ENDPOINT_DEFAULT}")"
  [[ "${site_ai_port}" =~ ^[0-9]{1,5}$ ]] && (( 10#${site_ai_port} >= 1 && 10#${site_ai_port} <= 65535 )) || site_ai_port=11435
  printf 'net.ipv4.ip_local_reserved_ports=8000,%s,20251\n' "$((10#${site_ai_port}))" >> /etc/sysctl.d/99-winsvpn-hub.conf
  sysctl --system >/dev/null 2>&1 || warn "sysctl apply reported a warning; deployment will continue"
  sysctl -w net.ipv4.ip_forward=0 >/dev/null 2>&1 || true
  sysctl -w net.ipv4.conf.all.forwarding=0 >/dev/null 2>&1 || true
  sysctl -w net.ipv4.conf.default.forwarding=0 >/dev/null 2>&1 || true
  sysctl -w net.ipv6.conf.all.disable_ipv6=1 >/dev/null 2>&1 || true
  sysctl -w net.ipv6.conf.default.disable_ipv6=1 >/dev/null 2>&1 || true
  sysctl -w net.ipv6.conf.all.forwarding=0 >/dev/null 2>&1 || true
}

cloudflare_discover_zone_id() {
  local token="${1:-}" zone_name="${2:-}" account_id="${3:-}" response zone_id
  [[ -n "${token}" && -n "${zone_name}" ]] || return 0
  if [[ -n "${account_id}" ]]; then
    response="$(curl_bearer "${token}" -fsS -G --connect-timeout 8 --max-time 20 \
      -H "Content-Type: application/json" \
      --data-urlencode "name=${zone_name}" \
      --data-urlencode "account.id=${account_id}" \
      "https://api.cloudflare.com/client/v4/zones" 2>/dev/null || true)"
  else
    response="$(curl_bearer "${token}" -fsS -G --connect-timeout 8 --max-time 20 \
      -H "Content-Type: application/json" \
      --data-urlencode "name=${zone_name}" \
      "https://api.cloudflare.com/client/v4/zones" 2>/dev/null || true)"
  fi
  zone_id="$(jq -r '.result[0].id // empty' <<<"${response}" 2>/dev/null || true)"
  printf '%s' "${zone_id}"
}

cloudflare_upsert_dns_record() {
  local token="$1" zone_id="$2" record_type="$3" record_name="$4" content="$5" proxied="${6:-true}" ttl="${7:-1}"
  local api list id payload response success error_summary
  if [[ -z "${token}" || -z "${zone_id}" || -z "${record_type}" || -z "${record_name}" || -z "${content}" ]]; then
    err "Cloudflare DNS upsert is missing a required token, zone, record type, name, or value."
    return 1
  fi
  api="https://api.cloudflare.com/client/v4/zones/${zone_id}/dns_records"
  log "Creating/updating Cloudflare DNS: ${record_name} ${record_type} ${content} proxied=${proxied}"
  list="$(curl_bearer "${token}" -fsS --connect-timeout 8 --max-time 20 \
    -H "Content-Type: application/json" \
      "${api}?name=${record_name}" 2>/dev/null || true)"
  # IA-CP-15: never PUT over an arbitrary record that merely shares the name
  # (a TXT or MX at the same name would be rewritten into this record while
  # the real one stays). Prefer a record of the requested type. Fall back to
  # the sole record at the name only when it is an address record (A, AAAA or
  # CNAME), which keeps the A-to-CNAME migration path working; otherwise
  # create, and let Cloudflare refuse a conflicting CNAME loudly.
  id="$(jq -r --arg type "${record_type}" '
    ([.result[]? | select(.type == $type) | .id] | first)
    // (if ((.result // []) | length) == 1
           and ((.result[0].type // "") | IN("A", "AAAA", "CNAME"))
        then .result[0].id else empty end)
    // empty' <<<"${list}" 2>/dev/null || true)"
  payload="$(jq -n \
    --arg type "${record_type}" \
    --arg name "${record_name}" \
    --arg content "${content}" \
    --argjson ttl "${ttl}" \
    --argjson proxied "${proxied}" \
    '{type:$type,name:$name,content:$content,ttl:$ttl,proxied:$proxied}')"
  if [[ -n "${id}" ]]; then
    response="$(curl_bearer "${token}" -fsS -X PUT "${api}/${id}" \
      -H "Content-Type: application/json" \
      --data "${payload}" 2>/dev/null || true)"
  else
    response="$(curl_bearer "${token}" -fsS -X POST "${api}" \
      -H "Content-Type: application/json" \
      --data "${payload}" 2>/dev/null || true)"
  fi
  success="$(jq -r '.success // false' <<<"${response}" 2>/dev/null || echo false)"
  if [[ "${success}" != "true" ]]; then
    error_summary="$(jq -r '[.errors[]?.message] | join("; ")' <<<"${response}" 2>/dev/null || true)"
    err "Cloudflare DNS upsert failed for ${record_name}. ${error_summary:-Check token DNS record edit permissions.}"
    return 1
  fi
}

cloudflare_delete_dns_record_if_present() {
  local token="$1" zone_id="$2" record_name="$3" api list id response
  api="https://api.cloudflare.com/client/v4/zones/${zone_id}/dns_records"
  list="$(curl_bearer "${token}" -fsS --connect-timeout 8 --max-time 20 \
    -H 'Content-Type: application/json' \
    "${api}?name=${record_name}")"
  jq -e '.success == true' >/dev/null <<<"${list}" || {
    err "Cloudflare DNS lookup failed while retiring ${record_name}."
    return 1
  }
  while IFS= read -r id; do
    [[ -n "${id}" ]] || continue
    log "Removing retired cross-account hub DNS record: ${record_name}"
    response="$(curl_bearer "${token}" -fsS -X DELETE "${api}/${id}" \
      -H 'Content-Type: application/json')"
    jq -e '.success == true' >/dev/null <<<"${response}" || {
      err "Cloudflare refused to remove retired hub DNS record ${record_name}."
      return 1
    }
  # CP-17: only the retired hub's address records. A TXT verification, MX,
  # CAA or any other record that shares the name is someone else's and stays.
  done < <(jq -r '.result[]? | select((.type // "") | IN("A", "AAAA", "CNAME")) | .id // empty' <<<"${list}")
}

# M-6: cloudflared provenance/version pins, kept identical to the Core role so
# all three one-touch roles install the same reviewed package from the same
# committed key. Verify any change to these out-of-band before editing.
CLOUDFLARE_KEY_SHA256="${CLOUDFLARE_KEY_SHA256:-1bd95f4082b320d541bee351560fc2765aa9f9cd8efa4c9e32135e63f252721d}"
CLOUDFLARE_KEY_FINGERPRINT="${CLOUDFLARE_KEY_FINGERPRINT:-CC94B39C77AE7342A68B89628A682D308D4E5E73}"
CLOUDFLARED_VERSION="${CLOUDFLARED_VERSION:-2026.10.0}"
CLOUDFLARED_AMD64_SHA256="${CLOUDFLARED_AMD64_SHA256:-9721287c28f78cb623e77c7b95a63feea87e909054d75666a0ec9eff20e5d548}"
CLOUDFLARED_ARM64_SHA256="${CLOUDFLARED_ARM64_SHA256:-7e0d76de3858b6396bd234ae26182bee222133398667d2647b90381d00c00e98}"

install_cloudflared_package() {
  # M-6: only skip reinstall when the EXACT pinned version is present (and still
  # supports the root-only token file), not merely any version with --token-file.
  local installed_version package_arch package_sha package_file package_url
  installed_version="$(dpkg-query -W -f='${Version}' cloudflared 2>/dev/null || true)"
  if [[ -n "${CLOUDFLARED_VERSION}" && "${installed_version}" == "${CLOUDFLARED_VERSION}" ]] \
      && cloudflared tunnel run --help 2>&1 | grep -F -- '--token-file' >/dev/null; then
    cloudflared --version
    apt-mark hold cloudflared >/dev/null
    return 0
  fi
  command -v cloudflared >/dev/null 2>&1 && \
    warn "Installed cloudflared (${installed_version:-none}) is not the pinned ${CLOUDFLARED_VERSION}; reinstalling from the reviewed repository."
  # M-6: install from the committed, hash/fingerprint-verified vendored key and
  # the exact pinned version instead of curling the repo key and installing an
  # unversioned package at deploy time.
  local key_file="${SCRIPT_DIR}/vendor/cloudflare-main.gpg"
  [[ -n "${CLOUDFLARE_KEY_SHA256}" && -n "${CLOUDFLARE_KEY_FINGERPRINT}" \
      && -n "${CLOUDFLARED_VERSION}" && -n "${CLOUDFLARED_AMD64_SHA256}" \
      && -n "${CLOUDFLARED_ARM64_SHA256}" ]] || {
    err "Cloudflare key, version, or architecture-specific package digest is unpopulated."
    return 1
  }
  [[ -f "${key_file}" && ! -L "${key_file}" ]] || {
    err "Vendored Cloudflare key ${key_file} is missing or is a symlink; refusing to trust an ad hoc runtime download."
    return 1
  }
  printf '%s  %s\n' "${CLOUDFLARE_KEY_SHA256}" "${key_file}" | sha256sum -c - >/dev/null || {
    err "Vendored Cloudflare key ${key_file} does not match the pinned CLOUDFLARE_KEY_SHA256."
    return 1
  }
  command -v gpg >/dev/null 2>&1 || apt_retry "${APT_GET[@]}" install -y gnupg
  local key_fingerprints
  key_fingerprints="$(gpg --show-keys --with-colons "${key_file}" 2>/dev/null)" || true
  grep -qx "fpr:::::::::${CLOUDFLARE_KEY_FINGERPRINT}:" <<<"${key_fingerprints}" || {
    err "Vendored Cloudflare key ${key_file} does not match the pinned CLOUDFLARE_KEY_FINGERPRINT."
    return 1
  }
  install -d -m 755 /usr/share/keyrings /etc/apt/sources.list.d
  install -o root -g root -m 644 "${key_file}" /usr/share/keyrings/cloudflare-main.gpg
  printf '%s\n' 'deb [signed-by=/usr/share/keyrings/cloudflare-main.gpg] https://pkg.cloudflare.com/cloudflared any main' \
    > /etc/apt/sources.list.d/cloudflared.list
  package_arch="$(dpkg --print-architecture)"
  case "${package_arch}" in
    amd64) package_sha="${CLOUDFLARED_AMD64_SHA256}" ;;
    arm64) package_sha="${CLOUDFLARED_ARM64_SHA256}" ;;
    *) err "Unsupported cloudflared package architecture: ${package_arch}"; return 1 ;;
  esac
  package_url="https://pkg.cloudflare.com/cloudflared/pool/main/c/cloudflared/cloudflared_${CLOUDFLARED_VERSION}_${package_arch}.deb"
  package_file="$(mktemp)"
  curl -fL --retry 4 --retry-all-errors --connect-timeout 10 --max-time 180 \
    -o "${package_file}" "${package_url}" || { rm -f -- "${package_file}"; return 1; }
  printf '%s  %s\n' "${package_sha}" "${package_file}" | sha256sum -c - >/dev/null || {
    rm -f -- "${package_file}"
    err "Downloaded cloudflared package digest does not match the reviewed ${package_arch} artifact."
    return 1
  }
  apt-mark unhold cloudflared >/dev/null 2>&1 || true
  dpkg -i "${package_file}" >/dev/null || { rm -f -- "${package_file}"; return 1; }
  rm -f -- "${package_file}"
  apt-mark hold cloudflared >/dev/null
  [[ "$(dpkg-query -W -f='${Version}' cloudflared 2>/dev/null)" == "${CLOUDFLARED_VERSION}" ]] || {
    err "Installed cloudflared version does not match the pinned CLOUDFLARED_VERSION after install."
    return 1
  }
  cloudflared --version
  cloudflared tunnel run --help 2>&1 | grep -F -- '--token-file' >/dev/null || {
    err "Installed cloudflared does not support the required root-only tunnel token file (2025.4.0 or newer required)."
    return 1
  }
}

configure_control_origin_tunnel() {
  local enabled="${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}"
  local account token tunnel_name api list response tunnel_id tunnel_token
  local host hostnames_json config_payload token_file service_file
  local -a hostnames=()
  if [[ "${enabled}" != "1" ]]; then
    warn "HIDE_CONTROL_ORIGIN=0: direct origin DNS and inbound web ports remain enabled."
    systemctl disable --now wins-control-tunnel.service 2>/dev/null || true
    return 0
  fi
  account="${CLOUDFLARE_TUNNEL_ACCOUNT_ID:-${CLOUDFLARE_WINS_ACCOUNT_ID:-$CLOUDFLARE_TUNNEL_ACCOUNT_ID_DEFAULT}}"
  token="${CLOUDFLARE_TUNNEL_API_TOKEN:-${CLOUDFLARE_WINS_API_TOKEN:-$CLOUDFLARE_TUNNEL_API_TOKEN_DEFAULT}}"
  tunnel_name="${CONTROL_TUNNEL_NAME:-$CONTROL_TUNNEL_NAME_DEFAULT}"
  [[ "${account}" =~ ^[A-Fa-f0-9]{32}$ && -n "${token}" ]] || {
    err "Cloudflare Tunnel account/token contract is incomplete."
    return 1
  }
  [[ "${tunnel_name}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{2,62}$ ]] || {
    err "CONTROL_TUNNEL_NAME must be 3-63 safe characters."
    return 1
  }
  api="https://api.cloudflare.com/client/v4/accounts/${account}/cfd_tunnel"
  list="$(curl_bearer "${token}" -fsS --retry 4 --retry-all-errors --connect-timeout 10 --max-time 30 \
    -G "${api}" -H 'Content-Type: application/json' \
    --data-urlencode "name=${tunnel_name}" --data-urlencode 'is_deleted=false')" || {
      err "Unable to query Cloudflare Tunnel API. Check Tunnel Read/Edit permission."
      return 1
    }
  jq -e '.success == true' >/dev/null <<<"${list}" || {
    err "Cloudflare rejected the tunnel lookup: $(jq -r '[.errors[]?.message] | join("; ")' <<<"${list}" 2>/dev/null || true)"
    return 1
  }
  tunnel_id="$(jq -r --arg name "${tunnel_name}" '.result | map(select(.name == $name and (.deleted_at == null))) | first | .id // empty' <<<"${list}")"
  if [[ -z "${tunnel_id}" ]]; then
    log "Creating remotely managed Cloudflare Tunnel ${tunnel_name}"
    response="$(curl_bearer "${token}" -fsS --retry 4 --retry-all-errors --connect-timeout 10 --max-time 30 \
      -X POST "${api}" -H 'Content-Type: application/json' \
      --data "$(jq -n --arg name "${tunnel_name}" '{name:$name,config_src:"cloudflare"}')")" || {
        err "Unable to create Cloudflare Tunnel ${tunnel_name}."
        return 1
      }
    tunnel_id="$(jq -r 'select(.success == true) | .result.id // empty' <<<"${response}")"
  fi
  [[ "${tunnel_id}" =~ ^[A-Fa-f0-9-]{36}$ ]] || {
    err "Cloudflare did not return a valid control tunnel UUID."
    return 1
  }

  for host in ${CLOUDFLARE_APPCLOUD_RECORDS:-$CLOUDFLARE_APPCLOUD_RECORDS_DEFAULT} \
              ${CLOUDFLARE_WINS_RECORDS:-$CLOUDFLARE_WINS_RECORDS_DEFAULT} \
              ${CLOUDFLARE_WINS_COM_RECORDS:-$CLOUDFLARE_WINS_COM_RECORDS_DEFAULT}; do
    valid_dns_hostname "${host}" || { err "Invalid control tunnel hostname: ${host}"; return 1; }
    hostnames+=("${host,,}")
  done
  hostnames_json="$(printf '%s\n' "${hostnames[@]}" | awk 'NF && !seen[$0]++' | jq -Rsc 'split("\n") | map(select(length > 0))')"
  config_payload="$(jq -n --arg service 'http://127.0.0.1:80' --argjson hosts "${hostnames_json}" '
    {config:{ingress:(([$hosts[] | {hostname:.,service:$service,originRequest:{connectTimeout:10}}]) + [{service:"http_status:404"}])}}')"
  response="$(curl_bearer "${token}" -fsS --retry 4 --retry-all-errors --connect-timeout 10 --max-time 30 \
    -X PUT "${api}/${tunnel_id}/configurations" \
    -H 'Content-Type: application/json' \
    --data "${config_payload}")" || {
      err "Unable to configure Cloudflare control tunnel ingress."
      return 1
    }
  jq -e '.success == true' >/dev/null <<<"${response}" || {
    err "Cloudflare rejected the control tunnel ingress configuration."
    return 1
  }
  response="$(curl_bearer "${token}" -fsS --retry 4 --retry-all-errors --connect-timeout 10 --max-time 30 \
    "${api}/${tunnel_id}/token")" || {
      err "Unable to retrieve the tunnel-specific connector token."
      return 1
    }
  tunnel_token="$(jq -r 'select(.success == true) | .result // empty' <<<"${response}")"
  [[ ${#tunnel_token} -ge 80 && "${tunnel_token}" != *[[:space:]]* ]] || {
    err "Cloudflare returned an invalid tunnel connector token."
    return 1
  }

  install_cloudflared_package
  id -u cloudflared >/dev/null 2>&1 || useradd --system --home-dir /var/lib/cloudflared --create-home --shell /usr/sbin/nologin cloudflared
  install -d -o root -g cloudflared -m 750 /etc/cloudflared /etc/winsvpn
  token_file="/etc/cloudflared/control-token"
  service_file="/etc/systemd/system/wins-control-tunnel.service"
  printf '%s\n' "${tunnel_token}" > "${token_file}"
  chown root:cloudflared "${token_file}"
  chmod 640 "${token_file}"
  printf '%s\n' "${tunnel_id}" > "${CONTROL_TUNNEL_ID_FILE}"
  chmod 600 "${CONTROL_TUNNEL_ID_FILE}"
  cat > "${service_file}" <<EOF
[Unit]
Description=Win's VPN outbound-only Cloudflare control origin tunnel
After=network-online.target nginx.service
Wants=network-online.target
Requires=nginx.service

[Service]
Type=simple
User=cloudflared
Group=cloudflared
ExecStart=/usr/bin/cloudflared --no-autoupdate tunnel run --token-file ${token_file}
Restart=always
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
LockPersonality=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
CapabilityBoundingSet=
AmbientCapabilities=
MemoryHigh=256M
MemoryMax=384M
TasksMax=256

[Install]
WantedBy=multi-user.target
EOF
  systemd-analyze verify "${service_file}"
  systemctl daemon-reload
  systemctl enable --now wins-control-tunnel.service
  # IA-CP-08: restart the connector only when its token or unit changed. A
  # rerun used to drop the hidden origin's only ingress every time.
  wins_restart_if_changed wins-control-tunnel.service control-tunnel \
    "$(wins_files_digest "${token_file}" "${service_file}")"
  log "Cloudflare control tunnel is active; its connector token is tunnel-specific and root-protected."
}

# App-zone tunnel connector for the compiled app fronts (a..z.<app zone>).
# That tunnel lives in the app zone's own Cloudflare account and is locally
# managed: its credentials are a tunnel credentials JSON and its ingress comes
# from a local config file, so it needs its own connector beside the control
# tunnel above (a front whose tunnel has no connector answers Cloudflare 1033).
# Inputs arrive only through the root-only WINS_SECRETS_FILE:
#   APPCLOUD_TUNNEL_ID           tunnel UUID
#   APPCLOUD_TUNNEL_CREDENTIALS  credentials JSON (AccountTag, TunnelID, TunnelSecret)
#   APPCLOUD_TUNNEL_HOSTS        front host names (space or comma separated)
# All three unset: skipped, nothing written. Any partial or invalid set fails
# closed before anything is installed. The listed hosts map to the same origin
# as the control tunnel (hub nginx); every other name on the tunnel gets 404.
# Output is byte-identical to wins-appcloud-tunnel.service,
# /etc/cloudflared/appcloud.yml and /etc/cloudflared/appcloud-credentials.json
# as installed on the live hub on 2026-09-26. Nothing here prints a credential.
configure_appcloud_tunnel_connector() {
  local tunnel_id="${APPCLOUD_TUNNEL_ID:-}" credentials="${APPCLOUD_TUNNEL_CREDENTIALS:-}" hosts="${APPCLOUD_TUNNEL_HOSTS:-}"
  local zone="${CLOUDFLARE_APPCLOUD_ZONE_NAME:-$CLOUDFLARE_APPCLOUD_ZONE_NAME_DEFAULT}"
  local config_file="/etc/cloudflared/appcloud.yml"
  local credentials_file="/etc/cloudflared/appcloud-credentials.json"
  local service_file="/etc/systemd/system/wins-appcloud-tunnel.service"
  local metrics="127.0.0.1:20251" origin="http://127.0.0.1:80"
  local work first_host ready="" _
  if [[ -z "${tunnel_id}${credentials}${hosts}" ]]; then
    log "APPCLOUD_TUNNEL_ID/_CREDENTIALS/_HOSTS are not set: no app-zone tunnel connector configured."
    return 0
  fi
  [[ -n "${tunnel_id}" && -n "${credentials}" && -n "${hosts}" ]] || {
    err "APPCLOUD_TUNNEL_ID, APPCLOUD_TUNNEL_CREDENTIALS and APPCLOUD_TUNNEL_HOSTS must be set together (or all left unset)."
    return 1
  }
  install_cloudflared_package
  id -u cloudflared >/dev/null 2>&1 || useradd --system --home-dir /var/lib/cloudflared --create-home --shell /usr/sbin/nologin cloudflared
  install -d -o root -g cloudflared -m 750 /etc/cloudflared
  work="$(mktemp -d /run/wins-appcloud.XXXXXX)"
  APPCLOUD_TUNNEL_ID="${tunnel_id}" APPCLOUD_TUNNEL_CREDENTIALS="${credentials}" APPCLOUD_TUNNEL_HOSTS="${hosts}" \
    python3 - "${work}" "${credentials_file}" "${metrics}" "${origin}" "${zone}" <<'APPCLOUDPYEOF' || {
import json, os, re, sys
out, cred_path, metrics, origin, zone = sys.argv[1:6]
tid = os.environ.get("APPCLOUD_TUNNEL_ID", "").strip().lower()
if not re.fullmatch(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", tid):
    sys.exit("APPCLOUD_TUNNEL_ID is not a tunnel UUID")
try:
    cred = json.loads(os.environ.get("APPCLOUD_TUNNEL_CREDENTIALS", ""))
except ValueError:
    sys.exit("APPCLOUD_TUNNEL_CREDENTIALS is not a credentials JSON")
if not isinstance(cred, dict) or not {"AccountTag", "TunnelID", "TunnelSecret"} <= set(cred) \
        or str(cred["TunnelID"]).lower() != tid:
    sys.exit("APPCLOUD_TUNNEL_CREDENTIALS does not belong to APPCLOUD_TUNNEL_ID")
hosts = sorted({h.strip().lower() for h in re.split(r"[\s,]+", os.environ.get("APPCLOUD_TUNNEL_HOSTS", "")) if h.strip()})
suffix = "." + zone.strip().lower().rstrip(".")
label = r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?"
bad = [h for h in hosts if not h.endswith(suffix) or len(h) > 253 or not re.fullmatch(rf"(?:{label}\.)+{label}", h)]
if not hosts or bad:
    sys.exit(f"APPCLOUD_TUNNEL_HOSTS must be host names under{suffix} ({len(bad)} invalid)")
fd = os.open(os.path.join(out, "appcloud-credentials.json"), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
with os.fdopen(fd, "w") as fh:
    json.dump(cred, fh)
lines = [f"tunnel: {tid}", f"credentials-file: {cred_path}", f"metrics: {metrics}", "no-autoupdate: true",
         "originRequest:", "  connectTimeout: 10s", "ingress:"]
for h in hosts:
    lines += [f"  - hostname: {h}", f"    service: {origin}"]
lines += ["  - service: http_status:404", ""]
fd = os.open(os.path.join(out, "appcloud.yml"), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
with os.fdopen(fd, "w") as fh:
    fh.write("\n".join(lines))
with open(os.path.join(out, "first-host"), "w") as fh:
    fh.write(hosts[0])
print(f"app-zone tunnel connector rendered: hosts={len(hosts)} origin={origin} catch-all=404")
APPCLOUDPYEOF
    rm -rf -- "${work}"
    err "App-zone tunnel secrets failed validation; wins-appcloud-tunnel was not installed."
    return 1
  }
  # Local ingress checks against a copy that points at the staged credentials:
  # no network, no connector started.
  first_host="$(cat "${work}/first-host")"
  sed "s#^credentials-file: .*#credentials-file: ${work}/appcloud-credentials.json#" \
    "${work}/appcloud.yml" > "${work}/validate.yml"
  if ! cloudflared tunnel --config "${work}/validate.yml" ingress validate >/dev/null 2>&1 \
      || ! cloudflared tunnel --config "${work}/validate.yml" ingress rule "https://${first_host}/" 2>/dev/null \
        | grep -F -- "${origin}" >/dev/null; then
    rm -rf -- "${work}"
    err "cloudflared rejects the rendered app-zone tunnel ingress; wins-appcloud-tunnel was not installed."
    return 1
  fi
  cat > "${work}/unit" <<EOF
[Unit]
Description=Win's VPN app-zone Cloudflare tunnel connector (compiled app fronts)
After=network-online.target nginx.service
Wants=network-online.target
Requires=nginx.service

[Service]
Type=simple
User=cloudflared
Group=cloudflared
ExecStart=/usr/bin/cloudflared tunnel --config ${config_file} run
Restart=always
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
LockPersonality=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
CapabilityBoundingSet=
AmbientCapabilities=
MemoryHigh=256M
MemoryMax=384M
TasksMax=256

[Install]
WantedBy=multi-user.target
EOF
  install -o root -g cloudflared -m 0640 "${work}/appcloud-credentials.json" "${credentials_file}"
  install -o root -g cloudflared -m 0640 "${work}/appcloud.yml" "${config_file}"
  install -o root -g root -m 0644 "${work}/unit" "${service_file}"
  rm -rf -- "${work}"
  systemd-analyze verify "${service_file}"
  systemctl daemon-reload
  systemctl enable --now wins-appcloud-tunnel.service
  systemctl restart wins-appcloud-tunnel.service
  for _ in $(seq 1 30); do
    ready="$(curl -s -o /dev/null --max-time 3 -w '%{http_code}' "http://${metrics}/ready" 2>/dev/null || true)"
    [[ "${ready}" == "200" ]] && break
    sleep 2
  done
  # CP-7: a connector that never reaches the edge leaves every app front on
  # Cloudflare 1033 while the unit looks active, so this is fatal, not a warning.
  if [[ "${ready}" != "200" ]]; then
    err "wins-appcloud-tunnel is installed but its connector is not ready after 60 s (metrics /ready=${ready:-none}); the app fronts answer Cloudflare 1033 until it is. Check: journalctl -u wins-appcloud-tunnel"
    return 1
  fi
  log "App-zone tunnel connector wins-appcloud-tunnel is active and ready."
}

cloudflare_release_worker_domain() {
  local token="$1" account_id="$2" hostname="$3"
  local response record_id status error_summary
  [[ -n "${token}" && -n "${account_id}" && -n "${hostname}" ]] || return 0
  response="$(curl_bearer "${token}" -fsS --connect-timeout 8 --max-time 20 \
    -H "Content-Type: application/json" \
    "https://api.cloudflare.com/client/v4/accounts/${account_id}/workers/domains/records" 2>/dev/null || true)"
  record_id="$(jq -r --arg host "${hostname}" \
    'first(.result[]? | select(.hostname == $host) | .id) // empty' \
    <<<"${response}" 2>/dev/null || true)"
  [[ -n "${record_id}" ]] || return 0
  log "Removing Cloudflare Worker custom-domain binding for ${hostname}"
  response="$(curl_bearer "${token}" -fsS -X DELETE \
    "https://api.cloudflare.com/client/v4/accounts/${account_id}/workers/domains/records/${record_id}" \
    -H "Content-Type: application/json" 2>/dev/null || true)"
  status="$(jq -r '.success // true' <<<"${response}" 2>/dev/null || echo true)"
  if [[ "${status}" != "true" ]]; then
    error_summary="$(jq -r '[.errors[]?.message] | join("; ")' <<<"${response}" 2>/dev/null || true)"
    warn "Unable to remove Cloudflare Worker custom-domain binding for ${hostname}. ${error_summary:-Check Worker domain permissions.}"
  fi
}

write_cloudflare_hub_dns() {
  local app_token app_account app_zone_id app_zone_name wins_token wins_account
  local wins_org_zone_id wins_org_zone_name wins_com_zone_id wins_com_zone_name record
  local dns_type="A" dns_content="${IONOS_HUB_IP}" tunnel_id=""
  local required="${REQUIRE_CLOUDFLARE_AUTOMATION:-$REQUIRE_CLOUDFLARE_AUTOMATION_DEFAULT}" app_records
  if [[ "${required}" != "1" ]]; then
    warn "Cloudflare DNS automation is disabled; hub DNS records will not self-update."
    return 0
  fi
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
    tunnel_id="$(tr -d '[:space:]' < "${CONTROL_TUNNEL_ID_FILE}" 2>/dev/null || true)"
    [[ "${tunnel_id}" =~ ^[A-Fa-f0-9-]{36}$ ]] || {
      err "Origin hiding is enabled but no valid control tunnel ID is installed."
      return 1
    }
    dns_type="CNAME"
    dns_content="${tunnel_id}.cfargotunnel.com"
  elif [[ -z "${IONOS_HUB_IP:-}" ]]; then
    err "Cloudflare DNS automation requires IONOS_HUB_IP/WINS_HUB_IP."
    return 1
  fi
  app_token="${CLOUDFLARE_APPCLOUD_API_TOKEN:-$CLOUDFLARE_APPCLOUD_API_TOKEN_DEFAULT}"
  app_account="${CLOUDFLARE_APPCLOUD_ACCOUNT_ID:-$CLOUDFLARE_APPCLOUD_ACCOUNT_ID_DEFAULT}"
  app_zone_id="${CLOUDFLARE_APPCLOUD_ZONE_ID:-$CLOUDFLARE_APPCLOUD_ZONE_ID_DEFAULT}"
  app_zone_name="${CLOUDFLARE_APPCLOUD_ZONE_NAME:-$CLOUDFLARE_APPCLOUD_ZONE_NAME_DEFAULT}"
  if [[ -z "${app_zone_id}" ]]; then
    app_zone_id="$(cloudflare_discover_zone_id "${app_token}" "${app_zone_name}" "${app_account}")"
  fi
  [[ -n "${app_zone_id}" ]] || { err "Unable to resolve the Cloudflare zone ID for ${app_zone_name}."; return 1; }
  app_records="${CLOUDFLARE_APPCLOUD_RECORDS:-$CLOUDFLARE_APPCLOUD_RECORDS_DEFAULT}"
  if [[ -n "${app_records//[[:space:]]/}" ]]; then
    for record in ${app_records}; do
      cloudflare_upsert_dns_record "${app_token}" "${app_zone_id}" "${dns_type}" "${record}" "${dns_content}" "true"
    done
  else
    for record in ${CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS:-$CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS_DEFAULT}; do
      cloudflare_delete_dns_record_if_present "${app_token}" "${app_zone_id}" "${record}"
    done
  fi

  wins_token="${CLOUDFLARE_WINS_API_TOKEN:-$CLOUDFLARE_WINS_API_TOKEN_DEFAULT}"
  wins_account="${CLOUDFLARE_WINS_ACCOUNT_ID:-$CLOUDFLARE_WINS_ACCOUNT_ID_DEFAULT}"
  wins_org_zone_id="${CLOUDFLARE_WINSVPN_ORG_ZONE_ID:-$CLOUDFLARE_WINSVPN_ORG_ZONE_ID_DEFAULT}"
  wins_org_zone_name="${CLOUDFLARE_WINSVPN_ORG_ZONE_NAME:-$CLOUDFLARE_WINSVPN_ORG_ZONE_NAME_DEFAULT}"
  if [[ -z "${wins_org_zone_id}" ]]; then
    wins_org_zone_id="$(cloudflare_discover_zone_id "${wins_token}" "${wins_org_zone_name}" "${wins_account}")"
  fi
  [[ -n "${wins_org_zone_id}" ]] || { err "Unable to resolve the Cloudflare zone ID for ${wins_org_zone_name}."; return 1; }
  for record in ${CLOUDFLARE_WINS_RECORDS:-$CLOUDFLARE_WINS_RECORDS_DEFAULT}; do
    cloudflare_release_worker_domain "${wins_token}" "${wins_account}" "${record}"
    cloudflare_upsert_dns_record "${wins_token}" "${wins_org_zone_id}" "${dns_type}" "${record}" "${dns_content}" "true"
  done

  wins_com_zone_id="${CLOUDFLARE_WINSVPN_COM_ZONE_ID:-$CLOUDFLARE_WINSVPN_COM_ZONE_ID_DEFAULT}"
  wins_com_zone_name="${CLOUDFLARE_WINSVPN_COM_ZONE_NAME:-$CLOUDFLARE_WINSVPN_COM_ZONE_NAME_DEFAULT}"
  if [[ -z "${wins_com_zone_id}" ]]; then
    wins_com_zone_id="$(cloudflare_discover_zone_id "${wins_token}" "${wins_com_zone_name}" "${wins_account}")"
  fi
  [[ -n "${wins_com_zone_id}" ]] || { err "Unable to resolve the Cloudflare zone ID for ${wins_com_zone_name}."; return 1; }
  for record in ${CLOUDFLARE_WINS_COM_RECORDS:-$CLOUDFLARE_WINS_COM_RECORDS_DEFAULT}; do
    cloudflare_release_worker_domain "${wins_token}" "${wins_account}" "${record}"
    cloudflare_upsert_dns_record "${wins_token}" "${wins_com_zone_id}" "${dns_type}" "${record}" "${dns_content}" "true"
  done
}

publish_active_gateway_record() {
  local required="${REQUIRE_ACTIVE_GATEWAY_AUTOMATION:-$REQUIRE_ACTIVE_GATEWAY_AUTOMATION_DEFAULT}"
  local token="${GITHUB_GIST_TOKEN:-}" gist_id filename gateway_base raw_url
  local record payload response raw_body attempt payload_file
  gist_id="${ACTIVE_GATEWAY_GIST_ID:-$ACTIVE_GATEWAY_GIST_ID_DEFAULT}"
  filename="${ACTIVE_GATEWAY_GIST_FILENAME:-$ACTIVE_GATEWAY_GIST_FILENAME_DEFAULT}"
  gateway_base="${ACTIVE_GATEWAY_BASE:-$ACTIVE_GATEWAY_BASE_DEFAULT}"
  raw_url="${ACTIVE_GATEWAY_RAW_URL:-$ACTIVE_GATEWAY_RAW_URL_DEFAULT}"
  gateway_base="${gateway_base%/}"

  [[ "${gist_id}" =~ ^[A-Fa-f0-9]{20,64}$ ]] || { err "ACTIVE_GATEWAY_GIST_ID is invalid."; return 1; }
  [[ "${filename}" =~ ^[A-Za-z0-9._-]+$ ]] || { err "ACTIVE_GATEWAY_GIST_FILENAME is invalid."; return 1; }
  if [[ ! "${gateway_base}" =~ ^https:// ]] || ! valid_dns_hostname "${gateway_base#https://}"; then
    err "ACTIVE_GATEWAY_BASE must be a path-free HTTPS hostname without an IP literal or custom port."
    return 1
  fi
  [[ "${raw_url}" =~ ^https://gist\.githubusercontent\.com/ || "${raw_url}" == "https://raw.githubusercontent.com/winsvpn/winsvpn-downloads/main/active-gateway.txt" ]] || {
    err "ACTIVE_GATEWAY_RAW_URL must use an approved Win's VPN GitHub raw record."
    return 1
  }
  if [[ "${required}" == "1" && ! "${raw_url}" =~ ^https://gist\.githubusercontent\.com/ ]]; then
    err "Gist write automation requires ACTIVE_GATEWAY_RAW_URL to reference the matching public Gist file."
    return 1
  fi
  record="${gateway_base}"

  if [[ "${required}" != "1" ]]; then
    raw_body="$(curl -fsS --connect-timeout 8 --max-time 20 \
      -H 'Cache-Control: no-cache' "${raw_url}?winsvpn_deploy=$(date +%s)" 2>/dev/null || true)"
    if [[ "${raw_body//$'\r'/}" == "${record}"$'\n' || "${raw_body//$'\r'/}" == "${record}" ]]; then
      log "Verified the read-only GitHub active-gateway fallback; no GitHub write token is installed."
    else
      warn "The optional public GitHub fallback does not currently match ${record}; the Cloudflare Tunnel hostname remains authoritative."
    fi
    return 0
  fi

  [[ -n "${token}" ]] || { err "GITHUB_GIST_TOKEN is required when active-gateway write automation is enabled."; return 1; }
  payload="$(jq -n --arg filename "${filename}" --arg content "${record}" \
    '{files:{($filename):{content:($content + "\\n")}}}')"
  payload_file="$(mktemp /run/wins-active-gateway.XXXXXX)"
  chmod 600 "${payload_file}"
  printf '%s' "${payload}" > "${payload_file}"
  log "Publishing dynamic active-gateway record to GitHub Gist ${gist_id}"
  response="$({
    printf 'url = "https://api.github.com/gists/%s"\n' "${gist_id}"
    printf 'request = "PATCH"\n'
    printf 'header = "Accept: application/vnd.github+json"\n'
    printf 'header = "Authorization: Bearer %s"\n' "${token}"
    printf 'header = "X-GitHub-Api-Version: 2026-03-10"\n'
    printf 'header = "Content-Type: application/json"\n'
    printf 'data-binary = "@%s"\n' "${payload_file}"
  } | curl -fsS --retry 4 --retry-all-errors --connect-timeout 10 --max-time 45 --config -)" || {
      rm -f "${payload_file}"
      err "GitHub rejected the active-gateway Gist update."
      return 1
    }
  rm -f "${payload_file}"
  jq -e --arg id "${gist_id}" --arg filename "${filename}" --arg record "${record}" \
    '.id == $id and (.files[$filename].content | rtrimstr("\n")) == $record' \
    <<<"${response}" >/dev/null || {
      err "GitHub Gist update response did not contain the expected active-gateway record."
      return 1
    }

  for attempt in 1 2 3 4 5; do
    raw_body="$(curl -fsS --connect-timeout 8 --max-time 20 \
      -H 'Cache-Control: no-cache' "${raw_url}?winsvpn_deploy=$(date +%s)-${attempt}" 2>/dev/null || true)"
    if [[ "${raw_body//$'\r'/}" == "${record}"$'\n' || "${raw_body//$'\r'/}" == "${record}" ]]; then
      log "Verified dynamic active-gateway record through the public raw Gist URL."
      return 0
    fi
    sleep $((attempt * 2))
  done
  err "The Gist API updated, but the public raw active-gateway record did not converge."
  return 1
}

load_existing_envs() {
  # H0 (D7): ${LEGACY_ENV_FILE} is in the hub app's writable directory, so it
  # is parsed as data, never sourced. ${ENV_FILE} is root-owned and outside
  # the app's writable set; it is still sourced, after the legacy copy, and
  # still wins.
  load_env_file_as_data "${LEGACY_ENV_FILE}"
  # shellcheck disable=SC1090
  if [[ -f "${ENV_FILE}" ]]; then
    source "${ENV_FILE}" || true
  fi

  # Releases before 2026-07-13 applied both Bash %q escaping and a second
  # single-quote pass. Repeated deployments therefore accumulated literal
  # backslashes before delimiters in list/label settings. Repair only known
  # non-secret fields; never rewrite arbitrary tokens, passwords, URLs, keys,
  # or paths where a literal backslash could be meaningful.
  local field value
  for field in \
    HUB_FAIL2BAN_IGNOREIPS HUB_ADMIN_SSH_CIDRS SYNC_DOMAINS WEBSITE_TLS_DOMAINS \
    SECURITY_ALERT_EXEMPT_IPS SECURITY_ALERT_LOCAL_IPS SECURITY_ALERT_EMAIL_PRIORITIES \
    SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS \
    SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS \
    SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS SECURITY_TRIAGE_ABSENT_PRODUCTS \
    SECURITY_TRIAGE_PRESENT_PRODUCTS FREE_ACCESS_LABEL FREE_ACCESS_NODE_SLUGS \
    FREE_ACCESS_NODE_MATCHES NODE_REGISTER_BLOCKED_HOSTS DOUBLE_VPN_CORE_NAME \
    DOUBLE_VPN_CORE_REGION DOUBLE_VPN_CORE_STEALTH_TRANSPORTS \
    PAYPAL_LIFETIME_SUPPORT_MARKERS PAYPAL_LIFETIME_NO_SUPPORT_MARKERS \
    PAYPAL_LIFETIME_MARKERS PAYPAL_PLAN_MARKERS PAYPAL_DONATION_MARKERS; do
    value="${!field:-}"
    [[ -n "${value}" ]] || continue
    value="$(sed -E 's/\\+([[:space:],()])/\1/g' <<<"${value}")"
    printf -v "${field}" '%s' "${value}"
  done
}

# H0 (D7): read an env file the hub app can write without running any of it.
# Only the exact line form write_env_kv writes is parsed: KEY='value', with
# each single quote in the value spelled '"'"'. Nothing in a value is expanded.
# Only the generated keys wins_runtime_owned_key names are taken from it, and
# only into a variable that is still empty. Those are secrets and tokens, never
# a path, a binary or a shell setting, so a planted line cannot redirect the
# installer; it keeps a generated secret that only the legacy copy still holds.
# Every other line is ignored.
load_env_file_as_data() {
  local file="$1" line key body
  local -A parsed=()
  [[ -f "${file}" ]] || return 0
  if [[ -L "${file}" ]]; then
    warn "Not reading ${file}: it is a symlink."
    return 0
  fi
  while IFS= read -r line || [[ -n "${line}" ]]; do
    [[ "${line}" =~ ^([A-Z][A-Z0-9_]*)=\'(.*)\'$ ]] || continue
    key="${BASH_REMATCH[1]}"
    body="${BASH_REMATCH[2]}"
    # A quote left after removing every '"'"' means the line was not written
    # by write_env_kv (for example KEY='x'; cmd; Y='y'), so it is not data.
    [[ "${body//\'\"\'\"\'/}" != *\'* ]] || continue
    wins_runtime_owned_key "${key}" || continue
    parsed["${key}"]=${body//\'\"\'\"\'/\'}
  done < "${file}"
  for key in "${!parsed[@]}"; do
    [[ -z "${!key:-}" ]] || continue
    printf -v "${key}" '%s' "${parsed[${key}]}"
  done
}

# IA-CP-01: keys this installer generates or mints once (or that a provider
# mints for it) and whose previous value must survive every rerun. They are
# never re-applied from operator intent; ${ENV_FILE} stays their source of
# truth and the secrets file, overlaid afterwards, stays the rotation channel.
# The redemption keyring and its active version move together: a defaults
# value for either alone would orphan printed cards or fail the ring check.
wins_runtime_owned_key() {
  case "$1" in
    ADMIN_TOKEN|ADMINTOKEN|SPA_KEY|SPAKEY|SPA_HMAC|SPAHMAC|XRAY_UUID|XRAYUUID \
      |HOPPY_AGENT_HMAC|LEGAL_ACCEPTANCE_HMAC_KEY|RATE_LIMIT_SECRET|MANAGEMENT_NAME_HMAC_KEY \
      |REDEMPTION_KEYS|REDEMPTION_KEY_ACTIVE_VERSION \
      |CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID|TUNNEL_SERVICE_TOKEN_ID \
      |TUNNEL_SERVICE_TOKEN_SECRET|PAYPAL_WEBHOOK_ID)
      return 0
      ;;
  esac
  return 1
}

# IA-CP-01: snapshot the current value of every operator-intent key (see the
# capture block after the defaults file is sourced) immediately before
# load_existing_envs, then put those values back immediately after it. Order in
# write_env becomes: previous runtime file < operator intent (defaults file and
# environment) < secrets file < the three routing restores. That is the same
# precedence --preflight sees, so preflight and deploy validate and write the
# same value for every key the operator set.
declare -A WINS_OPERATOR_INTENT_PENDING=()
declare -A WINS_OPERATOR_INTENT_OWNED=()
snapshot_operator_intent() {
  local key
  WINS_OPERATOR_INTENT_PENDING=()
  WINS_OPERATOR_INTENT_OWNED=()
  for key in "${WINS_OPERATOR_INTENT_KEYS[@]}"; do
    [[ -n "${!key:-}" ]] || continue
    [[ "${!key@a}" != *r* ]] || continue
    if wins_runtime_owned_key "${key}"; then
      WINS_OPERATOR_INTENT_OWNED["${key}"]="${!key}"
      continue
    fi
    WINS_OPERATOR_INTENT_PENDING["${key}"]="${!key}"
  done
}

reapply_operator_intent() {
  local key
  for key in "${!WINS_OPERATOR_INTENT_PENDING[@]}"; do
    printf -v "${key}" '%s' "${WINS_OPERATOR_INTENT_PENDING[${key}]}"
  done
  # A runtime-owned key the operator set (defaults file or environment) keeps
  # its runtime value. Say so instead of ignoring it silently: preflight
  # validated the supplied value, deploy writes the kept one. Names only.
  for key in "${!WINS_OPERATOR_INTENT_OWNED[@]}"; do
    if [[ -n "${!key:-}" && "${!key}" != "${WINS_OPERATOR_INTENT_OWNED[${key}]}" ]]; then
      warn "${key} is set in the defaults file or environment, but it is generated or minted state kept from ${ENV_FILE}; the supplied value is ignored. Rotate it through ${WINS_SECRETS_FILE} instead."
    fi
  done
  WINS_OPERATOR_INTENT_PENDING=()
  WINS_OPERATOR_INTENT_OWNED=()
}

atomic_replace_file() {
  # ${ENV_FILE} may be a symlink into an unlocked partial vault mount
  # (see vault_link_file); resolve it so the mktemp+mv below lands on the
  # real backing file instead of replacing the symlink itself.
  local target="$1" content="$2" mode="${3:-600}" real_target tmp
  real_target="${target}"
  [[ -L "${target}" ]] && real_target="$(readlink -f "${target}")"
  tmp="$(mktemp "${real_target}.XXXXXX")"
  printf '%s' "${content}" > "${tmp}"
  chmod "${mode}" "${tmp}"
  mv -f "${tmp}" "${real_target}"
}

# --- begin winn3 hub EnvironmentFile writers ---
# Persist WINN3_DESCRIPTOR_PUBKEY_G1 and WINN3_INNER_POOL_CIDR into the file
# the hub unit actually loads (${ENV_FILE}, EnvironmentFile= on
# wins-hub.service). write_env() rebuilds that file from a fixed write_env_kv
# list; anything not in the list is deleted on re-run. These two were read
# via os.getenv in the hub PYEOF and never written, so a fresh deploy could
# not serve standalone v3 without an undocumented manual append, and a
# re-run wiped a hand-added key.
#
# PUBLIC key only. This installer never generates, reads, copies, or writes
# a descriptor private key.
winn3_inner_pool_cidr_for_env() {
  local cidr="${WINN3_INNER_POOL_CIDR:-${WINN3_INNER_POOL_CIDR_DEFAULT}}"
  cidr="${cidr#"${cidr%%[![:space:]]*}"}"
  cidr="${cidr%"${cidr##*[![:space:]]}"}"
  local canonical
  canonical="$(python3 - "${cidr}" <<'WINN3_POOL_CIDR_PY'
import ipaddress
import sys
cidr = sys.argv[1]
try:
    network = ipaddress.ip_network(cidr, strict=False)
except ValueError as exc:
    sys.stderr.write("not a valid CIDR (%s)\n" % exc)
    sys.exit(1)
if not isinstance(network, ipaddress.IPv4Network):
    sys.stderr.write("is IPv6; winn/3 inner addressing is IPv4-only\n")
    sys.exit(1)
if network.prefixlen != 24:
    sys.stderr.write("is a /%d; the pool is pinned to EXACTLY /24\n" % network.prefixlen)
    sys.exit(1)
sys.stdout.write("%s/%s" % (network.network_address, network.prefixlen))
WINN3_POOL_CIDR_PY
)" || {
    err "WINN3_INNER_POOL_CIDR is not a usable hub inner pool (must be IPv4 /24, e.g. 10.10.0.0/24). The hub unit EnvironmentFile is ${ENV_FILE}."
    return 1
  }
  if [[ "${canonical}" != "${cidr}" ]]; then
    warn "WINN3_INNER_POOL_CIDR had host bits set; writing the network address ${canonical} into ${ENV_FILE}."
  fi
  printf '%s' "${canonical}"
}

winn3_descriptor_pubkey_is_raw32_b64() {
  local encoded="$1"
  python3 - "${encoded}" <<'WINN3_PUBKEY_B64_PY'
import base64
import sys
s = sys.argv[1].strip()
if not s:
    sys.exit(2)
try:
    raw = base64.b64decode(s, validate=True)
except Exception:
    sys.exit(1)
sys.exit(0 if len(raw) == 32 else 1)
WINN3_PUBKEY_B64_PY
}

winn3_read_descriptor_pubkey_file() {
  local path="$1" slot="$2"
  python3 - "${path}" "${slot}" <<'WINN3_PUBKEY_FILE_PY'
import sys
path, slot = sys.argv[1], sys.argv[2]
key = "WINN3_DESCRIPTOR_PUBKEY_" + slot
try:
    text = open(path, "r", encoding="utf-8").read()
except OSError as exc:
    sys.stderr.write("cannot read pubkey file: %s\n" % exc)
    sys.exit(1)
if "PRIVATE KEY" in text:
    sys.stderr.write("pubkey file looks like a private key; the hub stores only the public half\n")
    sys.exit(1)
chosen = None
for raw_line in text.splitlines():
    line = raw_line.strip()
    if line.startswith(key + "="):
        chosen = line.split("=", 1)[1].strip()
        if len(chosen) >= 2 and chosen[0] == chosen[-1] and chosen[0] in "'\"":
            chosen = chosen[1:-1]
        break
if chosen is None:
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("--dart-define="):
            sys.stderr.write("pubkey file contains a client --dart-define line, not a hub public key\n")
            sys.exit(1)
        chosen = line
        break
if not chosen:
    sys.stderr.write("pubkey file has no public key for %s\n" % key)
    sys.exit(1)
sys.stdout.write(chosen)
WINN3_PUBKEY_FILE_PY
}

winn3_descriptor_pubkey_for_env() {
  local slot="$1"
  local key_name="WINN3_DESCRIPTOR_PUBKEY_${slot}"
  local file_var="WINN3_DESCRIPTOR_PUBKEY_${slot}_FILE"
  local from_env from_file encoded
  from_env="${!key_name:-}"
  from_env="${from_env#"${from_env%%[![:space:]]*}"}"
  from_env="${from_env%"${from_env##*[![:space:]]}"}"
  from_file=""
  if [[ -n "${!file_var:-}" ]]; then
    from_file="$(winn3_read_descriptor_pubkey_file "${!file_var}" "${slot}")" || return 1
    from_file="${from_file#"${from_file%%[![:space:]]*}"}"
    from_file="${from_file%"${from_file##*[![:space:]]}"}"
  fi
  if [[ -n "${from_env}" && -n "${from_file}" && "${from_env}" != "${from_file}" ]]; then
    err "${key_name} and ${file_var} both set and disagree. Refusing to guess. The hub EnvironmentFile is ${ENV_FILE}."
    return 1
  fi
  encoded="${from_env:-${from_file}}"
  if [[ -z "${encoded}" ]]; then
    printf ''
    return 0
  fi
  if [[ "${encoded}" == --dart-define=* || "${encoded}" == WINS_WINN3_DESCRIPTOR_PUBKEY_* ]]; then
    err "${key_name} looks like a client dart-define, not a hub public key. Hub name is ${key_name} (no WINS_ prefix)."
    return 1
  fi
  winn3_descriptor_pubkey_is_raw32_b64 "${encoded}" || {
    err "${key_name} is not base64 of exactly 32 raw Ed25519 public-key bytes. The hub drops unusable slots, which presents as descriptor-no-verification-keys-configured. Refusing to write a silent no-op."
    return 1
  }
  printf '%s' "${encoded}"
}

# A real external Winn3 canary is one declarative unit.  The gateway canary
# script sources all seven values below from ${ENV_FILE}; writing only some of
# them turns a periodic datapath proof into a permanent probe_error.  Validate
# the complete tuple before write_env() atomically replaces either runtime env
# file, so an interrupted or malformed reconfiguration leaves the previous
# complete tuple in place rather than publishing a partial one.
#
# SYNC-03 (2026-09-29): the serving gate refuses every winn/3 node without a
# fresh canary of its own, so one tuple proved one node and refused the rest.
# WINN3_CANARY_NODES carries one probe identity per node, whitespace separated:
#   slug|static_public|inner_v4|key_dir|gateway_endpoint|gateway_id
# key_dir holds that gateway's client.key, static.pub and admission.key (what
# winn3-probe -dir reads). WINN3_CANARY_BIN is shared and may be set alone
# beside the list. The single tuple above keeps working and counts as one
# more entry; a slug may appear once across both.
validate_winn3_canary_runtime_settings() {
  local names=(
    WINN3_CANARY_NODE_SLUG
    WINN3_CANARY_STATIC_PUBLIC
    WINN3_CANARY_INNER_V4
    WINN3_CANARY_BIN
    WINN3_CANARY_KEY_DIR
    WINN3_CANARY_GATEWAY_ENDPOINT
    WINN3_CANARY_GATEWAY_ID
  )
  local name value present=0 pool legacy=0 canonical
  WINN3_CANARY_NODES_CANONICAL=""
  for name in "${names[@]}"; do
    value="${!name:-}"
    [[ -n "${value}" ]] && present=$((present + 1))
  done
  if (( present == 0 )) && [[ -z "${WINN3_CANARY_NODES:-}" ]]; then
    return 0
  fi
  if (( present == ${#names[@]} )); then
    legacy=1
  elif (( present != 0 )) && ! [[ "${present}" == "1" && -n "${WINN3_CANARY_BIN:-}" && -n "${WINN3_CANARY_NODES:-}" ]]; then
    err "Winn3 external canary configuration is partial (${present}/${#names[@]} fields set). Set all of: ${names[*]}. No runtime env file was changed."
    return 1
  fi

  pool="$(winn3_inner_pool_cidr_for_env)" || return 1
  canonical="$(python3 - "${pool}" "${legacy}" \
    "${WINN3_CANARY_NODE_SLUG:-}" \
    "${WINN3_CANARY_STATIC_PUBLIC:-}" \
    "${WINN3_CANARY_INNER_V4:-}" \
    "${WINN3_CANARY_BIN:-/usr/local/bin/winn3-probe}" \
    "${WINN3_CANARY_KEY_DIR:-}" \
    "${WINN3_CANARY_GATEWAY_ENDPOINT:-}" \
    "${WINN3_CANARY_GATEWAY_ID:-}" \
    "${WINN3_CANARY_NODES:-}" \
    "${DB_PATH:-}" <<'WINN3_CANARY_ENV_PY'
import base64
import ipaddress
import pathlib
import re
import sys

(
    pool_text,
    legacy,
    slug,
    static_public,
    inner_text,
    binary_path,
    key_dir,
    endpoint,
    gateway_id,
    nodes_text,
    db_path,
) = sys.argv[1:]

def refuse(message: str) -> None:
    sys.stderr.write("invalid Winn3 external canary configuration: " + message + "\n")
    raise SystemExit(1)

try:
    pool = ipaddress.ip_network(pool_text, strict=True)
except ValueError as exc:
    refuse("the hub inner pool is invalid (%s)" % exc)

def check_path(field: str, raw: str) -> None:
    if raw != raw.strip() or any(ord(char) < 32 or ord(char) == 127 for char in raw):
        refuse(field + " contains whitespace at an edge or a control character")
    path = pathlib.PurePosixPath(raw)
    if not path.is_absolute() or ".." in path.parts or raw == "/":
        refuse(field + " must be a specific absolute path without '..'")
    if str(path) != raw:
        refuse(field + " must be canonical")

def check_binding(names: dict, slug, static_public, inner_text, key_dir, endpoint, gateway_id) -> None:
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", slug):
        refuse(names["slug"] + " must be 2-40 lowercase letters, digits, or hyphens")

    if static_public != static_public.strip():
        refuse(names["static_public"] + " has edge whitespace")
    try:
        static_raw = base64.b64decode(static_public, validate=True)
    except Exception:
        refuse(names["static_public"] + " is not canonical base64")
    if len(static_raw) != 32:
        refuse(names["static_public"] + " is not a raw 32-byte X25519 public key")
    if base64.b64encode(static_raw).decode("ascii") != static_public:
        refuse(names["static_public"] + " is not canonical base64")

    try:
        inner = ipaddress.IPv4Address(inner_text)
    except ValueError as exc:
        refuse(names["inner_v4"] + " is invalid (%s)" % exc)
    if inner not in pool or inner in {pool.network_address, pool.broadcast_address}:
        refuse(names["inner_v4"] + " is outside the usable hub inner pool")

    check_path(names["key_dir"], key_dir)

    match = re.fullmatch(r"([^:]+):([0-9]{1,5})", endpoint)
    if not match:
        refuse(names["gateway_endpoint"] + " must be an IPv4 literal plus port")
    try:
        gateway_address = ipaddress.IPv4Address(match.group(1))
    except ValueError as exc:
        refuse(names["gateway_endpoint"] + " is invalid (%s)" % exc)
    port = int(match.group(2))
    if port < 1 or port > 65535 or gateway_address.is_unspecified or gateway_address.is_multicast:
        refuse(names["gateway_endpoint"] + " has an unusable address or port")

    if gateway_id != gateway_id.strip():
        refuse(names["gateway_id"] + " has edge whitespace")
    if not gateway_id or len(gateway_id.encode("utf-8")) > 128:
        refuse(names["gateway_id"] + " must be 1-128 UTF-8 bytes")
    if any(ord(char) < 32 or ord(char) == 127 for char in gateway_id):
        refuse(names["gateway_id"] + " contains a control character")

check_path("WINN3_CANARY_BIN", binary_path)
seen = set()
if legacy == "1":
    check_binding({
        "slug": "WINN3_CANARY_NODE_SLUG",
        "static_public": "WINN3_CANARY_STATIC_PUBLIC",
        "inner_v4": "WINN3_CANARY_INNER_V4",
        "key_dir": "WINN3_CANARY_KEY_DIR",
        "gateway_endpoint": "WINN3_CANARY_GATEWAY_ENDPOINT",
        "gateway_id": "WINN3_CANARY_GATEWAY_ID",
    }, slug, static_public, inner_text, key_dir, endpoint, gateway_id)
    seen.add(slug)
    held = [("WINN3_CANARY_NODE_SLUG " + slug, static_public, inner_text)]
else:
    held = []

canonical = []
for index, entry in enumerate(nodes_text.split(), start=1):
    fields = entry.split("|")
    label = "WINN3_CANARY_NODES entry %d" % index
    if len(fields) != 6:
        refuse(label + " must be slug|static_public|inner_v4|key_dir|gateway_endpoint|gateway_id")
    entry_slug, entry_public, entry_inner, entry_dir, entry_endpoint, entry_id = fields
    check_binding({
        "slug": label + " slug",
        "static_public": label + " static_public",
        "inner_v4": label + " inner_v4",
        "key_dir": label + " key_dir",
        "gateway_endpoint": label + " gateway_endpoint",
        "gateway_id": label + " gateway_id",
    }, entry_slug, entry_public, entry_inner, entry_dir, entry_endpoint, entry_id)
    # The list is split on whitespace and '|', so the list form takes the
    # gateway installer's own GatewayID alphabet (WINN3_GATEWAY_ID) and a
    # plain path; nothing else can be carried without quoting.
    if not re.fullmatch(r"[A-Za-z0-9._:-]{1,128}", entry_id):
        refuse(label + " gateway_id must use only [A-Za-z0-9._:-]")
    if not re.fullmatch(r"/[A-Za-z0-9._/+-]+", entry_dir):
        refuse(label + " key_dir must use only [A-Za-z0-9._/+-]")
    if entry_slug in seen:
        refuse(label + " names " + entry_slug + ", which already has a canary binding")
    seen.add(entry_slug)
    canonical.append(entry)
    held.append((label, entry_public, entry_inner))

# SYNC-03 round 2 (Seat C N-1): the allocator reserves canary addresses and
# keys from now on, but a device issued one BEFORE this configuration keeps
# it, and that node's registry build then refuses its whole snapshot. On a
# rerun the hub database exists: refuse such a binding here, before any env
# file changes. Read-only; a fresh install has no database yet.
if db_path and pathlib.Path(db_path).is_file():
    import sqlite3
    try:
        conn = sqlite3.connect(pathlib.Path(db_path).resolve().as_uri() + "?mode=ro", uri=True, timeout=30)
        columns = {row[1] for row in conn.execute("PRAGMA table_info(devices)")}
    except sqlite3.Error as exc:
        refuse("the hub database could not be read to check canary bindings (%s)" % type(exc).__name__)
    for what, public_value, inner_value in held:
        for column, value, noun in (
            ("winn3_inner_v4", inner_value, "inner_v4"),
            ("winn3_static_public", public_value, "static_public"),
        ):
            if column in columns and conn.execute(
                "SELECT 1 FROM devices WHERE " + column + " = ? LIMIT 1", (value,)
            ).fetchone():
                refuse(what + " " + noun + " is already held by a device; choose a value no device holds")
    conn.close()
print(" ".join(canonical))
WINN3_CANARY_ENV_PY
)" || return 1
  WINN3_CANARY_NODES_CANONICAL="${canonical}"
}

write_winn3_canary_runtime_env() {
  validate_winn3_canary_runtime_settings || return 1
  if [[ -n "${WINN3_CANARY_NODES_CANONICAL:-}" ]]; then
    write_env_kv WINN3_CANARY_NODES "${WINN3_CANARY_NODES_CANONICAL}"
    if [[ -z "${WINN3_CANARY_NODE_SLUG:-}" && -n "${WINN3_CANARY_BIN:-}" ]]; then
      write_env_kv WINN3_CANARY_BIN "${WINN3_CANARY_BIN}"
    fi
  fi
  [[ -n "${WINN3_CANARY_NODE_SLUG:-}" ]] || return 0
  local name
  for name in \
    WINN3_CANARY_NODE_SLUG \
    WINN3_CANARY_STATIC_PUBLIC \
    WINN3_CANARY_INNER_V4 \
    WINN3_CANARY_BIN \
    WINN3_CANARY_KEY_DIR \
    WINN3_CANARY_GATEWAY_ENDPOINT \
    WINN3_CANARY_GATEWAY_ID; do
    write_env_kv "${name}" "${!name}"
  done
}

# Opt-in standalone carrier helpers live inside this writer block so a
# test that extracts only these markers still has the functions
# write_winn3_runtime_env calls. Default flag 0: no node is flipped.
winn3_standalone_install_flag() {
  local flag="${WINN3_SET_CARRIER_STANDALONE:-${WINN3_SET_CARRIER_STANDALONE_DEFAULT:-0}}"
  printf '%s' "${flag}"
}

winn3_standalone_install_slug() {
  local slug="${WINN3_STANDALONE_NODE_SLUG:-${WINN3_STANDALONE_NODE_SLUG_DEFAULT:-}}"
  slug="${slug#"${slug%%[![:space:]]*}"}"
  slug="${slug%"${slug##*[![:space:]]}"}"
  # bash 3.2 on macOS has no ${var,,}; tr is the portable lowercasing.
  printf '%s' "${slug}" | tr '[:upper:]' '[:lower:]'
}

validate_winn3_standalone_install_settings() {
  local flag slug mtu classes desc token
  flag="$(winn3_standalone_install_flag)"
  case "${flag}" in
    0|1) ;;
    *)
      err "WINN3_SET_CARRIER_STANDALONE must be 0 or 1 (got ${flag}). Default is 0: no node is flipped to standalone."
      return 1
      ;;
  esac
  slug="$(winn3_standalone_install_slug)"
  if [[ "${flag}" != "1" ]]; then
    return 0
  fi
  if [[ -z "${slug}" ]]; then
    err "WINN3_SET_CARRIER_STANDALONE=1 requires WINN3_STANDALONE_NODE_SLUG (one already-chosen node). Refusing to guess, which would flip every node or invent a slug."
    return 1
  fi
  if [[ ! "${slug}" =~ ^[a-z0-9][a-z0-9-]{1,39}$ ]]; then
    err "WINN3_STANDALONE_NODE_SLUG must be 2-40 lowercase letters, digits, or hyphens."
    return 1
  fi
  mtu="${WINN3_STANDALONE_PATH_MTU:-${WINN3_STANDALONE_PATH_MTU_DEFAULT:-1450}}"
  if [[ ! "${mtu}" =~ ^[0-9]+$ ]] || ((mtu < 1421 || mtu > 9000)); then
    err "WINN3_STANDALONE_PATH_MTU must be an integer 1421..9000 (fleet default 1450). Values in 1280..1420 are the never-promotes dead zone."
    return 1
  fi
  classes="${WINN3_STANDALONE_CARRIER_CLASSES:-${WINN3_STANDALONE_CARRIER_CLASSES_DEFAULT:-udp}}"
  classes="${classes#"${classes%%[![:space:]]*}"}"
  classes="${classes%"${classes##*[![:space:]]}"}"
  if [[ -z "${classes}" ]]; then
    err "WINN3_STANDALONE_CARRIER_CLASSES must be a non-empty subset of udp,tcp,tls."
    return 1
  fi
  local IFS=','
  # shellcheck disable=SC2086
  set -- ${classes}
  unset IFS
  if [[ $# -lt 1 ]]; then
    err "WINN3_STANDALONE_CARRIER_CLASSES must be a non-empty subset of udp,tcp,tls."
    return 1
  fi
  local saw_udp=0
  for token in "$@"; do
    token="${token#"${token%%[![:space:]]*}"}"
    token="${token%"${token##*[![:space:]]}"}"
    case "${token}" in
      udp) saw_udp=1 ;;
      tcp|tls) ;;
      *)
        err "WINN3_STANDALONE_CARRIER_CLASSES contains unknown token ${token}; known: udp,tcp,tls."
        return 1
        ;;
    esac
  done
  if [[ "${saw_udp}" != "1" ]]; then
    err "WINN3_STANDALONE_CARRIER_CLASSES must contain udp; the shipping datapath cannot originate a tcp/tls-only plan."
    return 1
  fi
  desc="${WINN3_STANDALONE_DESCRIPTOR_JSON:-${WINN3_STANDALONE_DESCRIPTOR_JSON_DEFAULT:-}}"
  if [[ -n "${desc}" ]]; then
    [[ -f "${desc}" && -s "${desc}" ]] || {
      err "WINN3_STANDALONE_DESCRIPTOR_JSON is set but is not a non-empty file."
      return 1
    }
  fi
  return 0
}

write_winn3_runtime_env() {
  local pool pubkey slot slot_lc active_slot standby_slot pinned
  pool="$(winn3_inner_pool_cidr_for_env)" || return 1
  write_env_kv WINN3_INNER_POOL_CIDR "${pool}"
  # Design 3.19 item 3 and 3.10: the hub verify ring carries the active signer
  # slot and the standby slot (g3, or g2 while g3 is active) from the reviewed
  # ring the signer is pinned to, so a descriptor the signer issues is never
  # refused as descriptor-key-slot-not-provisioned. A supplied active-slot key
  # must be that pinned key.
  active_slot="$(descriptor_signer_active_slot)" || return 1
  if [[ "${active_slot}" == g3 ]]; then standby_slot=g2; else standby_slot=g3; fi
  for slot in G1 G2 G3; do
    pubkey="$(winn3_descriptor_pubkey_for_env "${slot}")" || return 1
    slot_lc="$(printf '%s' "${slot}" | tr '[:upper:]' '[:lower:]')"
    if [[ "${slot_lc}" == "${active_slot}" || "${slot_lc}" == "${standby_slot}" ]]; then
      pinned="$(winn3_descriptor_ring_pinned_pubkey "${slot_lc}")" || return 1
      [[ -n "${pubkey}" ]] || pubkey="${pinned}"
      if [[ "${slot_lc}" == "${active_slot}" && "${pubkey}" != "${pinned}" ]]; then
        err "WINN3_DESCRIPTOR_PUBKEY_${slot} is not the reviewed ring key of the active signer slot ${slot_lc}; the hub would refuse every descriptor the signer issues. Remove it or set the pinned key."
        return 1
      fi
    fi
    if [[ "${slot}" == G1 ]]; then
      write_env_kv WINN3_DESCRIPTOR_PUBKEY_G1 "${pubkey}"
      if [[ -z "${pubkey}" ]]; then
        warn "WINN3_DESCRIPTOR_PUBKEY_G1 is empty in ${ENV_FILE}; the hub cannot verify standalone v3 descriptors until the operator supplies the PUBLIC key (WINN3_DESCRIPTOR_PUBKEY_G1 or WINN3_DESCRIPTOR_PUBKEY_G1_FILE). This installer never generates or writes a private key."
      fi
    elif [[ -n "${pubkey}" ]]; then
      write_env_kv "WINN3_DESCRIPTOR_PUBKEY_${slot}" "${pubkey}"
    fi
  done
  # Persist the standalone-carrier opt-in so the running hub can apply
  # carrier=winn3 on the FIRST real registration of the named slug. Default
  # 0 / empty slug: the hub writes nothing on register_node, matching today.
  validate_winn3_standalone_install_settings || return 1
  local standalone_flag standalone_slug standalone_mtu standalone_classes
  standalone_flag="$(winn3_standalone_install_flag)"
  standalone_slug="$(winn3_standalone_install_slug)"
  standalone_mtu="${WINN3_STANDALONE_PATH_MTU:-${WINN3_STANDALONE_PATH_MTU_DEFAULT}}"
  standalone_classes="${WINN3_STANDALONE_CARRIER_CLASSES:-${WINN3_STANDALONE_CARRIER_CLASSES_DEFAULT}}"
  write_env_kv WINN3_SET_CARRIER_STANDALONE "${standalone_flag}"
  write_env_kv WINN3_STANDALONE_NODE_SLUG "${standalone_slug}"
  write_env_kv WINN3_STANDALONE_PATH_MTU "${standalone_mtu}"
  write_env_kv WINN3_STANDALONE_CARRIER_CLASSES "${standalone_classes}"
  write_hub_key_custody_env || return 1
  write_winn3_canary_runtime_env || return 1
  write_descriptor_signer_env || return 1
  local auto_flag auto_value
  for auto_flag in WINN3_AUTO_SIGN WINN3_AUTO_CARRIER; do
    auto_value="${!auto_flag:-1}"
    case "${auto_value}" in 0|1) ;; *) err "${auto_flag} must be 0 or 1."; return 1 ;; esac
    write_env_kv "${auto_flag}" "${auto_value}"
  done
}

# The reviewed announcement PUBLIC keys the app compiles in
# (lib/announcement_signature.dart kReviewedAnnouncementPubkeyA1..A3). The hub
# defaults to the same ring so the two cannot drift; an operator value in
# ANNOUNCE_PUBKEY_A* (or already in ${ENV_FILE}) still wins. Public halves only.
announce_reviewed_pubkey() {
  case "$1" in
    A1) printf '%s' 'd9hwDSlQpYvnph33NJFHAbOm3hKR1wWEhC/kFiNoeoo=' ;;
    A2) printf '%s' 'Toj52qgUbbwgEBja6mtjwQYkOd76lWhoB8+hrlCINgk=' ;;
    A3) printf '%s' 'sFiAZSm+xTxXNA6uEWNfCMfy/rb6tn4Rtg1SMHU6GvI=' ;;
    *) return 1 ;;
  esac
}

# Key custody flags for the hub (Fable 5.1 ruling 2026-09-29). Validates the
# whole set before writing any of it. PUBLIC announcement keys only: this
# installer never generates, reads or writes an announcement private key.
write_hub_key_custody_env() {
  local minted require slot name encoded rc count=0
  local -a announce_names=() announce_values=()
  minted="${WINN3_HUB_MINTED_KEYS_ALLOWED:-${WINN3_HUB_MINTED_KEYS_ALLOWED_DEFAULT:-1}}"
  case "${minted}" in
    0|1) ;;
    *)
      err "WINN3_HUB_MINTED_KEYS_ALLOWED must be 0 or 1 (got ${minted}). Default 1 keeps the legacy hub-minted device keys for older builds."
      return 1
      ;;
  esac
  require="${ANNOUNCE_REQUIRE_SIGNED:-${ANNOUNCE_REQUIRE_SIGNED_DEFAULT:-0}}"
  case "${require}" in
    0|1) ;;
    *)
      err "ANNOUNCE_REQUIRE_SIGNED must be 0 or 1 (got ${require})."
      return 1
      ;;
  esac
  for slot in A1 A2 A3; do
    name="ANNOUNCE_PUBKEY_${slot}"
    encoded="${!name:-$(announce_reviewed_pubkey "${slot}")}"
    encoded="${encoded#"${encoded%%[![:space:]]*}"}"
    encoded="${encoded%"${encoded##*[![:space:]]}"}"
    [[ -n "${encoded}" ]] || continue
    if [[ "${encoded}" == *"PRIVATE KEY"* || "${encoded}" == --dart-define=* || "${encoded}" == WINS_ANNOUNCE_PUBKEY_* ]]; then
      err "${name} must be the base64 of a raw 32-byte Ed25519 PUBLIC key (hub name has no WINS_ prefix). The hub never holds an announcement private key."
      return 1
    fi
    rc=0
    winn3_descriptor_pubkey_is_raw32_b64 "${encoded}" || rc=$?
    if (( rc != 0 )); then
      err "${name} is not base64 of exactly 32 raw Ed25519 public-key bytes. Refusing to write a slot the hub would silently drop."
      return 1
    fi
    announce_names+=("${name}")
    announce_values+=("${encoded}")
    count=$((count + 1))
  done
  if [[ "${require}" == "1" ]] && (( count == 0 )); then
    err "ANNOUNCE_REQUIRE_SIGNED=1 needs at least one ANNOUNCE_PUBKEY_A1..A3; otherwise no announcement could ever be posted."
    return 1
  fi
  write_env_kv WINN3_HUB_MINTED_KEYS_ALLOWED "${minted}"
  write_env_kv ANNOUNCE_REQUIRE_SIGNED "${require}"
  local i
  for ((i = 0; i < count; i++)); do
    write_env_kv "${announce_names[i]}" "${announce_values[i]}"
  done
  if (( count == 0 )); then
    warn "No ANNOUNCE_PUBKEY_A1..A3 in ${ENV_FILE}: the hub cannot accept a signed announcement until the operator supplies the PUBLIC keys from the offline ceremony."
  fi
}

# H1 (3.8, 3.10): the descriptor signer's active slot and t1 public key, the
# two signer settings persisted in ${ENV_FILE}.
WINN3_DESCRIPTOR_SIGNER_ACTIVE_SLOT_DEFAULT="g2"
# The reviewed ring (tools/winn3_descriptor_ring_defines.py RING, ring
# 52e91c72...). An injected key must match its active slot's public half here.
winn3_descriptor_ring_pinned_pubkey() {
  case "$1" in
    g1) printf '%s' 'L2mAYdYIXPCFuNoH5ntgBBubFSnnlzIAnXwKttpehaQ=' ;;
    g2) printf '%s' 'eVCAHWXqUM1+m5nlVy2JR+Q4/mkYGTxlk119aiQh89M=' ;;
    g3) printf '%s' '53JhsQBxKH5DG145LcaBunOX4lbt+J7Js0oPyJnj9Q0=' ;;
    *) return 1 ;;
  esac
}

# The active slot is operator configuration (3.10). The payload kid and the
# pin check both derive from it, so a g3 recovery is a configuration change.
descriptor_signer_active_slot() {
  local slot="${WINN3_DESCRIPTOR_SIGNER_ACTIVE_SLOT:-${WINN3_DESCRIPTOR_SIGNER_ACTIVE_SLOT_DEFAULT}}"
  case "${slot}" in
    g1|g2|g3) printf '%s' "${slot}" ;;
    *)
      err "WINN3_DESCRIPTOR_SIGNER_ACTIVE_SLOT must be g1, g2 or g3 (got ${slot})."
      return 1
      ;;
  esac
}

# t1 is the offline ticket key, separate from the g ring (3.8). Public half
# only; empty means tickets cannot be verified yet and only renewals issue.
descriptor_signer_ticket_pubkey() {
  local encoded="${WINN3_SIGNER_TICKET_PUBKEY_T1:-}" slot rc=0
  encoded="${encoded#"${encoded%%[![:space:]]*}"}"
  encoded="${encoded%"${encoded##*[![:space:]]}"}"
  [[ -n "${encoded}" ]] || return 0
  winn3_descriptor_pubkey_is_raw32_b64 "${encoded}" || rc=$?
  if (( rc != 0 )); then
    err "WINN3_SIGNER_TICKET_PUBKEY_T1 is not base64 of exactly 32 raw Ed25519 public-key bytes."
    return 1
  fi
  # Canonical base64, so an alias with nonzero trailing bits of a ring key
  # cannot pass the string comparison below.
  encoded="$(python3 - "${encoded}" <<'T1_CANONICAL_PY'
import base64
import binascii
import sys

try:
    raw = base64.b64decode(sys.argv[1], validate=True)
except (binascii.Error, ValueError):
    sys.exit(1)
if len(raw) != 32:
    sys.exit(1)
print(base64.b64encode(raw).decode("ascii"))
T1_CANONICAL_PY
)" || {
    err "WINN3_SIGNER_TICKET_PUBKEY_T1 must encode a raw 32-byte Ed25519 public key."
    return 1
  }
  for slot in g1 g2 g3; do
    if [[ "${encoded}" == "$(winn3_descriptor_ring_pinned_pubkey "${slot}")" ]]; then
      err "WINN3_SIGNER_TICKET_PUBKEY_T1 equals descriptor ring slot ${slot}. t1 must be a separate key."
      return 1
    fi
  done
  printf '%s' "${encoded}"
}

# Persisted in ${ENV_FILE} so a rerun keeps the operator's choice. Both public.
# The private key is never written there: write_env keeps only listed keys.
write_descriptor_signer_env() {
  local slot t1
  slot="$(descriptor_signer_active_slot)" || return 1
  t1="$(descriptor_signer_ticket_pubkey)" || return 1
  write_env_kv WINN3_DESCRIPTOR_SIGNER_ACTIVE_SLOT "${slot}"
  write_env_kv WINN3_SIGNER_TICKET_PUBKEY_T1 "${t1}"
}

# --- end winn3 hub EnvironmentFile writers ---

# --- begin install-time standalone carrier=winn3 (opt-in, default OFF) ---
# Production POST /admin/nodes/winn3 refuses an empty body. These helpers
# POST {"carrier":"winn3"} plus a servable plan, and only for the one slug
# the operator named.
# Flag/slug/validate live in the EnvironmentFile writer block above so a
# writer-only extraction still defines them.
winn3_standalone_hub_base() {
  local base="${WINN3_STANDALONE_HUB_BASE:-http://127.0.0.1:8000}"
  local canonical
  # Parsed origin only. A glob on 127.0.0.1 plus a trailing star accepted
  # userinfo, fragments, and non-loopback hosts such as 127.0.0.1:8000@evil.
  if ! canonical="$(/usr/bin/python3 - "${base}" <<'WINN3_LOOPBACK_ORIGIN_PY'
import sys
import urllib.parse
raw = sys.argv[1]
if not isinstance(raw, str):
    sys.exit(1)
if raw != raw.strip():
    sys.exit(1)
for ch in raw:
    if ord(ch) < 32 or ord(ch) == 127:
        sys.exit(1)
parsed = urllib.parse.urlsplit(raw)
if parsed.scheme != "http":
    sys.exit(1)
if parsed.username is not None or parsed.password is not None:
    sys.exit(1)
if parsed.query or parsed.fragment:
    sys.exit(1)
if parsed.path not in ("", "/"):
    sys.exit(1)
host = parsed.hostname
if host is None or host != "127.0.0.1":
    sys.exit(1)
try:
    port = parsed.port
except ValueError:
    sys.exit(1)
if port is not None and not (1 <= int(port) <= 65535):
    sys.exit(1)
if port is None:
    netloc = "127.0.0.1"
else:
    netloc = "127.0.0.1:%d" % port
if parsed.netloc != netloc:
    sys.exit(1)
origin = "http://%s" % netloc
if raw != origin:
    sys.exit(1)
sys.stdout.write(origin)
WINN3_LOOPBACK_ORIGIN_PY
)"; then
    err "WINN3_STANDALONE_HUB_BASE must be loopback http://127.0.0.1[:port]; refusing a non-local hub."
    return 1
  fi
  printf '%s' "${canonical}"
}

provision_standalone_winn3_carrier() {
  # Called from main() AFTER postflight_control, so the local hub is up.
  # --preflight never reaches here. Default flag 0 is a no-op.
  validate_winn3_standalone_install_settings || return 1
  local flag slug mtu classes desc base
  flag="$(winn3_standalone_install_flag)"
  if [[ "${flag}" != "1" ]]; then
    log "WINN3_SET_CARRIER_STANDALONE=${flag:-0}: not provisioning any node as standalone (carrier=winn3). Existing nodes are unchanged; production POST /admin/nodes/winn3 still requires carrier=winn3."
    return 0
  fi
  slug="$(winn3_standalone_install_slug)"
  mtu="${WINN3_STANDALONE_PATH_MTU:-${WINN3_STANDALONE_PATH_MTU_DEFAULT}}"
  classes="${WINN3_STANDALONE_CARRIER_CLASSES:-${WINN3_STANDALONE_CARRIER_CLASSES_DEFAULT}}"
  desc="${WINN3_STANDALONE_DESCRIPTOR_JSON:-${WINN3_STANDALONE_DESCRIPTOR_JSON_DEFAULT:-}}"
  base="$(winn3_standalone_hub_base)" || return 1
  log "WINN3_SET_CARRIER_STANDALONE=1: provisioning slug=${slug} as standalone carrier=winn3 (path_mtu=${mtu} classes=${classes}) via loopback admin POST"
  local admin_token="${ADMIN_TOKEN:-${ADMINTOKEN:-}}"
  if [[ -z "${admin_token}" ]]; then
    err "ADMIN_TOKEN missing; cannot POST /admin/nodes/winn3"
    return 1
  fi
  # Never resolve the credential-bearing interpreter through caller-controlled
  # PATH, and never publish the admin token in the child's environment.  The
  # inherited anonymous descriptor is read and closed before any request is
  # constructed.
  local admin_token_fd provision_status
  exec {admin_token_fd}<<<"${admin_token}" || {
    err "cannot create private ADMIN_TOKEN descriptor"
    return 1
  }
  if /usr/bin/python3 - "${base}" "${slug}" "${mtu}" "${classes}" "${desc}" "${admin_token_fd}" <<'WINN3_SET_CARRIER_PY'
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

base, slug, path_mtu, classes, desc_path, token_fd_text = sys.argv[1:7]


def canonical_loopback_http_origin(raw):
    """Exact http://127.0.0.1[:port] origin. No userinfo, query, fragment, path, or aliases."""
    if not isinstance(raw, str):
        raise ValueError("hub base must be a string")
    if raw != raw.strip() or any(ord(ch) < 32 or ord(ch) == 127 for ch in raw):
        raise ValueError("hub base is ambiguous")
    parsed = urllib.parse.urlsplit(raw)
    if parsed.scheme != "http":
        raise ValueError("hub base must be http")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("hub base must not carry userinfo")
    if parsed.query or parsed.fragment:
        raise ValueError("hub base must not carry query or fragment")
    if parsed.path not in ("", "/"):
        raise ValueError("hub base must be an origin")
    host = parsed.hostname
    if host is None or host != "127.0.0.1":
        raise ValueError("hub base host must be 127.0.0.1")
    try:
        port = parsed.port
    except ValueError as exc:
        raise ValueError("hub base port is ambiguous") from exc
    if port is not None and not (1 <= int(port) <= 65535):
        raise ValueError("hub base port is invalid")
    netloc = "127.0.0.1" if port is None else ("127.0.0.1:%d" % port)
    if parsed.netloc != netloc:
        raise ValueError("hub base netloc is ambiguous")
    origin = "http://%s" % netloc
    if raw != origin:
        raise ValueError("hub base is ambiguous")
    return origin


try:
    base = canonical_loopback_http_origin(base)
except ValueError:
    sys.stderr.write(
        "WINN3_STANDALONE_HUB_BASE must be loopback http://127.0.0.1[:port]; "
        "refusing a non-local hub.\n"
    )
    sys.exit(1)

try:
    token_fd = int(token_fd_text, 10)
    token_bytes = os.read(token_fd, 4097)
finally:
    try:
        os.close(token_fd)
    except (NameError, OSError):
        pass
if len(token_bytes) > 4096 or not token_bytes.endswith(b"\n"):
    sys.stderr.write("ADMIN_TOKEN descriptor is malformed\n")
    sys.exit(1)
try:
    token = token_bytes[:-1].decode("utf-8")
except UnicodeDecodeError:
    sys.stderr.write("ADMIN_TOKEN descriptor is not UTF-8\n")
    sys.exit(1)
if len(token) < 32 or any(ch.isspace() for ch in token):
    sys.stderr.write("ADMIN_TOKEN descriptor did not contain a valid token\n")
    sys.exit(1)

# Explicit standalone. Never an empty {} body (production registration refuses it).
params_json = json.dumps({"carrier": "winn3"}, separators=(",", ":"))


class _LoopbackAdminNoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_LOOPBACK_ADMIN_NO_REDIRECT_OPENER = urllib.request.build_opener(_LoopbackAdminNoRedirect)


def post_form(path, fields):
    body = urllib.parse.urlencode(fields).encode()
    req = urllib.request.Request(
        base.rstrip("/") + path,
        data=body,
        headers={
            "x-admin-token": token,
            "Content-Type": "application/x-www-form-urlencoded",
        },
        method="POST",
    )
    try:
        with _LOOPBACK_ADMIN_NO_REDIRECT_OPENER.open(req, timeout=20) as resp:
            raw = resp.read().decode()
            return resp.status, raw
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode() if exc.fp else ""
        return exc.code, raw


status, raw = post_form(
    "/admin/nodes/winn3",
    {
        "slug": slug,
        "enabled": "true",
        "protocol_params_json": params_json,
        "path_mtu": path_mtu,
        "carrier_classes": classes,
    },
)
if status == 404:
    sys.stderr.write(
        "node %s is not registered yet; registration never applies carrier=winn3 "
        "(H2). Descriptor POST skipped until the node exists; re-run this step "
        "after registration, or let the H2 job flip the carrier after its proofs.\n" % slug
    )
    sys.exit(0)
if status != 200:
    sys.stderr.write(
        "POST /admin/nodes/winn3 failed status=%s (slug named, body not logged)\n"
        % status
    )
    sys.exit(1)
try:
    payload = json.loads(raw)
except Exception:
    sys.stderr.write("POST /admin/nodes/winn3 returned non-JSON\n")
    sys.exit(1)
carrier = payload.get("carrier")
if carrier != "winn3":
    sys.stderr.write(
        "refusing to accept a standalone provision that reported carrier=%r "
        "(want winn3). Production registration requires exact carrier=winn3.\n"
        % (carrier,)
    )
    sys.exit(1)
sys.stderr.write(
    "provisioned slug=%s protocol_version=%s carrier=winn3\n"
    % (payload.get("slug"), payload.get("protocol_version"))
)

if not desc_path:
    sys.stderr.write(
        "WINN3_STANDALONE_DESCRIPTOR_JSON unset; readiness will list "
        "winn3_descriptor_missing_or_invalid until a signed envelope is posted.\n"
    )
    sys.exit(0)
try:
    text = open(desc_path, "r", encoding="utf-8").read()
except OSError as exc:
    sys.stderr.write("cannot read descriptor JSON: %s\n" % exc)
    sys.exit(1)
if "PRIVATE KEY" in text:
    sys.stderr.write(
        "descriptor file looks like a private key; this installer never "
        "uploads private key material\n"
    )
    sys.exit(1)
try:
    envelope = json.loads(text)
except Exception:
    sys.stderr.write("descriptor file is not JSON\n")
    sys.exit(1)
payload_b64 = str(envelope.get("descriptor_payload_b64") or "").strip()
sig_b64 = str(envelope.get("descriptor_sig_b64") or "").strip()
if not payload_b64 or not sig_b64:
    sys.stderr.write(
        "descriptor JSON missing descriptor_payload_b64 / descriptor_sig_b64\n"
    )
    sys.exit(1)
status, raw = post_form(
    "/admin/nodes/winn3/descriptor",
    {
        "slug": slug,
        "enabled": "true",
        "descriptor_payload_b64": payload_b64,
        "descriptor_sig_b64": sig_b64,
    },
)
if status != 200:
    sys.stderr.write(
        "POST /admin/nodes/winn3/descriptor failed status=%s\n" % status
    )
    sys.exit(1)
sys.stderr.write("posted signed descriptor for slug=%s\n" % slug)
WINN3_SET_CARRIER_PY
  then
    provision_status=0
  else
    provision_status=$?
  fi
  exec {admin_token_fd}<&-
  return "${provision_status}"
}
# --- end install-time standalone carrier=winn3 ---

# --- begin commerce secrets apply (PayPal + BTCPay, no full re-provision) ---
# Modelled on ~/.winsvpn/wfa-release.env: a file the operator fills once,
# sourced into the process, fail-closed if any required name is missing.
# This path rewrites only commerce keys in vpn_auth.env and restarts
# wins-hub. It does not apt, rewrite main.py, regenerate REDEMPTION_KEYS,
# or touch ADMIN_TOKEN.

commerce_paypal_required_keys() {
  printf '%s\n' \
    PAYPAL_PUBLIC_CLIENT_ID \
    PAYPAL_CLIENT_ID \
    PAYPAL_CLIENT_SECRET \
    PAYPAL_PLAN_1M \
    PAYPAL_PLAN_1Y \
    PAYPAL_PLAN_PERSONAL \
    PAYPAL_LIFETIME_SUPPORT_URL \
    PAYPAL_LIFETIME_NO_SUPPORT_URL \
    PAYPAL_LIFETIME_SUPPORT_AMOUNT \
    PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT \
    PAYPAL_LIFETIME_CURRENCY
}

commerce_paypal_optional_overlay_keys() {
  printf '%s\n' \
    PAYPAL_MODE \
    PAYPAL_WEBHOOK_ID \
    PAYPAL_WEBHOOK_AUTO_ENSURE \
    PAYPAL_WEBHOOK_URL \
    PAYPAL_DONATION_URL
}

commerce_btcpay_required_keys() {
  printf '%s\n' \
    BTCPAY_URL \
    BTCPAY_STORE_ID \
    BTCPAY_API_KEY \
    BTCPAY_WEBHOOK_SECRET
}

wins_secret_value_configured() {
  local v="${1:-}"
  v="${v#"${v%%[![:space:]]*}"}"
  v="${v%"${v##*[![:space:]]}"}"
  [[ -n "${v}" ]]
}

require_wins_secrets_file() {
  [[ -f "${WINS_SECRETS_FILE}" ]] || {
    err "Missing ${WINS_SECRETS_FILE}. Create it root-owned mode 600. Names-only template: server/hub-commerce.env.example. Never commit values."
    return 1
  }
  overlay_wins_secrets_file || return 1
}

validate_commerce_secrets_for_apply() {
  local missing=() variable
  if [[ "${PAYPAL_ALLOW_UNVERIFIED_WEBHOOKS:-}" == "true" || "${PAYPAL_ALLOW_UNVERIFIED_WEBHOOKS:-}" == "1" ]]; then
    err "PAYPAL_ALLOW_UNVERIFIED_WEBHOOKS is refused; it is a silent-accept grant hole and is absent from this installer."
    return 1
  fi
  while IFS= read -r variable; do
    [[ -n "${variable}" ]] || continue
    wins_secret_value_configured "${!variable:-}" || missing+=("${variable}")
  done < <(commerce_paypal_required_keys)
  if [[ "${PAYPAL_WEBHOOK_AUTO_ENSURE:-$PAYPAL_WEBHOOK_AUTO_ENSURE_DEFAULT}" != "1" ]]; then
    wins_secret_value_configured "${PAYPAL_WEBHOOK_ID:-}" || missing+=("PAYPAL_WEBHOOK_ID")
  fi
  if ((${#missing[@]})); then
    err "Missing required commerce secrets: ${missing[*]}. Inject them through root-owned ${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}. Runtime ${ENV_FILE:-/root/vpn_auth.env} was not modified."
    return 1
  fi
  [[ "${PAYPAL_PUBLIC_CLIENT_ID}" == "${PAYPAL_CLIENT_ID}" ]] || {
    err "PAYPAL_PUBLIC_CLIENT_ID must match PAYPAL_CLIENT_ID for the live account. Runtime ${ENV_FILE} was not modified."
    return 1
  }
  for variable in PAYPAL_LIFETIME_SUPPORT_AMOUNT PAYPAL_LIFETIME_NO_SUPPORT_AMOUNT; do
    [[ "${!variable}" =~ ^[0-9]+([.][0-9]{1,2})?$ && ! "${!variable}" =~ ^0+([.]0+)?$ ]] || {
      err "${variable} must be a positive decimal amount with at most two fractional digits. Runtime ${ENV_FILE} was not modified."
      return 1
    }
  done
  [[ "${PAYPAL_LIFETIME_CURRENCY}" =~ ^[A-Z]{3}$ ]] || {
    err "PAYPAL_LIFETIME_CURRENCY must be a three-letter uppercase currency code. Runtime ${ENV_FILE} was not modified."
    return 1
  }
  if [[ -n "${BTCPAY_URL:-}${BTCPAY_STORE_ID:-}${BTCPAY_API_KEY:-}${BTCPAY_WEBHOOK_SECRET:-}" ]]; then
    missing=()
    while IFS= read -r variable; do
      [[ -n "${variable}" ]] || continue
      wins_secret_value_configured "${!variable:-}" || missing+=("${variable}")
    done < <(commerce_btcpay_required_keys)
    if ((${#missing[@]})); then
      err "BTCPay is all-or-nothing; missing: ${missing[*]}. Runtime ${ENV_FILE} was not modified."
      return 1
    fi
    [[ "${BTCPAY_URL}" =~ ^https://[A-Za-z0-9.:_-]+(/.*)?$ ]] || {
      err "BTCPAY_URL must be a valid https:// URL for the self-hosted BTCPay Server. Runtime ${ENV_FILE} was not modified."
      return 1
    }
  fi
  return 0
}

apply_commerce_secrets() {
  local key updated=()
  require_root
  [[ -f "${ENV_FILE}" ]] || {
    err "Missing ${ENV_FILE}. --apply-commerce-secrets updates a live hub; it is not a first deploy. Use --deploy for a new hub."
    return 1
  }
  require_wins_secrets_file || return 1
  load_existing_envs
  overlay_wins_secrets_file || return 1
  validate_commerce_secrets_for_apply || return 1
  while IFS= read -r key; do
    [[ -n "${key}" ]] || continue
    replace_runtime_env_kv "${key}" "${!key}"
    updated+=("${key}")
  done < <(commerce_paypal_required_keys)
  while IFS= read -r key; do
    [[ -n "${key}" ]] || continue
    wins_secret_value_configured "${!key:-}" || continue
    replace_runtime_env_kv "${key}" "${!key}"
    updated+=("${key}")
  done < <(commerce_paypal_optional_overlay_keys)
  if [[ -n "${BTCPAY_URL:-}${BTCPAY_STORE_ID:-}${BTCPAY_API_KEY:-}${BTCPAY_WEBHOOK_SECRET:-}" ]]; then
    while IFS= read -r key; do
      [[ -n "${key}" ]] || continue
      replace_runtime_env_kv "${key}" "${!key}"
      updated+=("${key}")
    done < <(commerce_btcpay_required_keys)
  fi
  chmod 600 "${ENV_FILE}"
  [[ -f "${LEGACY_ENV_FILE}" && ! -L "${LEGACY_ENV_FILE}" ]] && chmod 600 "${LEGACY_ENV_FILE}"
  log "Commerce overlay wrote ${#updated[@]} keys into ${ENV_FILE} from ${WINS_SECRETS_FILE}: ${updated[*]}. Values not logged."
  systemctl restart wins-hub.service
  local _i
  for _i in $(seq 1 30); do
    curl -A "${WINS_HEALTH_USER_AGENT:-$WINS_HEALTH_USER_AGENT_DEFAULT}" -fsS --connect-timeout 2 --max-time 5 http://127.0.0.1:8000/healthz >/dev/null 2>&1 && break
    sleep 1
  done
  curl -A "${WINS_HEALTH_USER_AGENT:-$WINS_HEALTH_USER_AGENT_DEFAULT}" -fsS --connect-timeout 2 --max-time 5 http://127.0.0.1:8000/healthz >/dev/null
  log "wins-hub restarted after commerce overlay. Confirm GET /api/site/wallet-config enabled=true (public client id only). Do not echo ${ENV_FILE}."
}

# --- end commerce secrets apply ---

write_env() {
  mkdir -p "${APP_DIR}"
  # Capture explicitly supplied fresh-deploy routing values before loading the
  # previous runtime file. Secrets and generated identities are preserved, but
  # a stale public gateway/payment URL must not override the current preseed.
  local desired_active_gateway_base="${ACTIVE_GATEWAY_BASE:-$ACTIVE_GATEWAY_BASE_DEFAULT}"
  local desired_public_payment_base="${PUBLIC_PAYMENT_BASE:-$PUBLIC_PAYMENT_BASE_DEFAULT}"
  local desired_paypal_webhook_url="${PAYPAL_WEBHOOK_URL:-$PAYPAL_WEBHOOK_URL_DEFAULT}"
  # IA-CP-01: the previous runtime file supplies generated secrets and any key
  # the operator did not set this run; it must not revert a key the operator
  # did set (defaults file or environment). See snapshot_operator_intent.
  snapshot_operator_intent
  load_existing_envs
  reapply_operator_intent
  # Secrets file was sourced at process start, then load_existing_envs
  # sourced vpn_auth.env which can contain KEY='' placeholders. Re-source
  # so non-empty injected PayPal/BTCPay values win. Routing restores below
  # still beat the secrets file for the three preseed URL keys, as before.
  overlay_wins_secrets_file || exit 1
  ACTIVE_GATEWAY_BASE="${desired_active_gateway_base}"
  PUBLIC_PAYMENT_BASE="${desired_public_payment_base}"
  PAYPAL_WEBHOOK_URL="${desired_paypal_webhook_url}"

  local admin_token spa_key spa_hmac xray_uuid smtp_server smtp_port smtp_user smtp_pass email_sender
  local security_alert_email security_alert_exempt_ips
  local legal_acceptance_hmac_key rate_limit_secret
  admin_token="${ADMIN_TOKEN:-${ADMINTOKEN:-$ADMIN_TOKEN_DEFAULT}}"
  spa_key="${SPA_KEY:-${SPAKEY:-$SPA_KEY_DEFAULT}}"
  spa_hmac="${SPA_HMAC:-${SPAHMAC:-$SPA_HMAC_DEFAULT}}"
  xray_uuid="${XRAY_UUID:-${XRAYUUID:-$XRAY_UUID_DEFAULT}}"
  hoppy_agent_hmac="${HOPPY_AGENT_HMAC:-}"
  [[ -n "${admin_token}" ]] || admin_token="$(openssl rand -hex 32)"
  [[ -n "${spa_key}" ]] || spa_key="$(openssl rand -base64 32 | tr -d '\n')"
  [[ -n "${spa_hmac}" ]] || spa_hmac="$(openssl rand -base64 32 | tr -d '\n')"
  [[ -n "${hoppy_agent_hmac}" ]] || hoppy_agent_hmac="$(openssl rand -hex 32)"
  if [[ -z "${xray_uuid}" ]]; then
    xray_uuid="$(cat /proc/sys/kernel/random/uuid 2>/dev/null || python3 -c 'import uuid; print(uuid.uuid4())')"
  fi
  legal_acceptance_hmac_key="${LEGAL_ACCEPTANCE_HMAC_KEY:-}"
  if [[ -z "${legal_acceptance_hmac_key}" ]]; then
    # L-13: never fall back to hashing wall-clock time -- that is guessable
    # to within a tiny search space by anyone who can estimate the
    # deployment time, which defeats the point of a secret HMAC key. Try the
    # kernel CSPRNG directly as the only fallback if OpenSSL is unavailable,
    # and fail closed (abort deployment) rather than proceed with a weak key
    # if neither real entropy source is usable.
    legal_acceptance_hmac_key="$(openssl rand -hex 32 2>/dev/null)" || true
    if [[ -z "${legal_acceptance_hmac_key}" ]]; then
      legal_acceptance_hmac_key="$(od -An -N32 -tx1 /dev/urandom 2>/dev/null | tr -d ' \n')"
    fi
    [[ "${legal_acceptance_hmac_key}" =~ ^[0-9a-fA-F]{64}$ ]] || {
      err "Unable to generate a legal-acceptance HMAC key from OpenSSL or /dev/urandom; refusing to deploy with a weak or missing key."
      exit 1
    }
  fi
  rate_limit_secret="${RATE_LIMIT_SECRET:-}"
  [[ -n "${rate_limit_secret}" ]] || rate_limit_secret="$(openssl rand -hex 32)"
  # IA-SYNC SYNC-24: the key behind management hostnames and Core assignment
  # revisions. Seeded once from the rate-limit secret's current value, so no
  # existing name changes, then persisted and kept across reruns like every
  # other generated secret here. Never derive it again from RATE_LIMIT_SECRET.
  local management_name_hmac_key
  management_name_hmac_key="${MANAGEMENT_NAME_HMAC_KEY:-}"
  [[ -n "${management_name_hmac_key}" ]] || management_name_hmac_key="${rate_limit_secret}"

  # Phase 3: the redemption keyring. Generated independently of every other
  # secret here -- no fallback to ADMIN_TOKEN, SPA_HMAC or RATE_LIMIT_SECRET,
  # because a database-only attacker holding one of those must still not be
  # able to test candidate redemption codes. Existing versions are preserved
  # verbatim by load_existing_envs so a redeploy never orphans printed cards;
  # only a keyring that is entirely absent is seeded.
  local redemption_keys redemption_key_active_version
  redemption_keys="${REDEMPTION_KEYS:-}"
  redemption_key_active_version="${REDEMPTION_KEY_ACTIVE_VERSION:-$REDEMPTION_KEY_ACTIVE_VERSION_DEFAULT}"
  if [[ -z "${redemption_keys}" ]]; then
    local redemption_seed=""
    redemption_seed="$(openssl rand -hex 32 2>/dev/null)" || true
    if [[ -z "${redemption_seed}" ]]; then
      redemption_seed="$(od -An -N32 -tx1 /dev/urandom 2>/dev/null | tr -d ' \n')"
    fi
    [[ "${redemption_seed}" =~ ^[0-9a-fA-F]{64}$ ]] || {
      err "Unable to generate a redemption HMAC key from OpenSSL or /dev/urandom; refusing to deploy with a weak or missing key."
      exit 1
    }
    redemption_keys="${redemption_key_active_version}:${redemption_seed}"
  fi
  # Fail closed if the active version is not actually in the ring: a hub that
  # cannot mint under its own configured version would silently 503 every
  # batch issuance instead of failing at deploy time.
  if [[ ",${redemption_keys}," != *",${redemption_key_active_version}:"* ]]; then
    err "REDEMPTION_KEY_ACTIVE_VERSION=${redemption_key_active_version} is not present in REDEMPTION_KEYS; refusing to deploy a hub that cannot mint the batches it is configured for."
    exit 1
  fi

  smtp_server="${SMTP_SERVER:-$SMTP_SERVER_DEFAULT}"
  smtp_port="${SMTP_PORT:-$SMTP_PORT_DEFAULT}"
  smtp_user="${SMTP_USER:-$SMTP_USER_DEFAULT}"
  smtp_pass="${SMTP_PASS:-$SMTP_PASS_DEFAULT}"
  email_sender="${EMAIL_SENDER:-$EMAIL_SENDER_DEFAULT}"
  security_alert_email="${SECURITY_ALERT_EMAIL:-$SECURITY_ALERT_EMAIL_DEFAULT}"
  security_alert_exempt_ips="${SECURITY_ALERT_EXEMPT_IPS:-$SECURITY_ALERT_EXEMPT_IPS_DEFAULT}"
  # Buffer every KV pair in memory and replace ${ENV_FILE} atomically at the
  # end (see atomic_replace_file) instead of truncating it up front and
  # appending line-by-line. The old truncate-then-append sequence left a
  # window where an interrupted run (Ctrl+C, OOM, lost SSH session) could
  # strand this root-owned secrets file empty or partially written, which
  # then either fails `source "${ENV_FILE}"` validation later in main() or,
  # on a re-run of an already-deployed hub, gets loaded by a subsequent
  # `systemctl restart wins-hub.service` with missing/garbled secrets.
  local env_kv_buffer='# Wins VPN control plane runtime configuration.
# Keep this root-owned file private; it contains live service credentials.
'
  write_env_kv() {
    local key="$1" value="$2"
    [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ ]] || {
      err "Refusing to write an invalid runtime environment key: ${key}"
      return 1
    }
    [[ "${value}" != *$'\n'* && "${value}" != *$'\r'* ]] || {
      err "Runtime environment value for ${key} contains a forbidden newline."
      return 1
    }
    # See append_runtime_env_kv's comment: this must stay unquoted or the
    # escaping backslashes leak into the written secret instead of being
    # consumed, and a value with an odd quote count breaks `source` later.
    value=${value//\'/\'\"\'\"\'}
    env_kv_buffer+="${key}='${value}'"$'\n'
  }
  write_env_kv ADMIN_TOKEN "${admin_token}"
  write_env_kv ADMINTOKEN "${admin_token}"
  write_env_kv SPA_KEY "${spa_key}"
  write_env_kv SPAKEY "${spa_key}"
  write_env_kv SPA_HMAC "${spa_hmac}"
  write_env_kv SPAHMAC "${spa_hmac}"
  write_env_kv HOPPY_AGENT_HMAC "${hoppy_agent_hmac}"
  write_env_kv DATABASE_PATH "${DB_PATH}"
  write_env_kv DATABASEPATH "${DB_PATH}"
  write_env_kv IONOS_HUB_IP "${IONOS_HUB_IP}"
  write_env_kv IONOSHUBIP "${IONOS_HUB_IP}"
  write_env_kv ACTIVE_GATEWAY_BASE "${desired_active_gateway_base}"
  write_env_kv ACTIVE_GATEWAY_RAW_URL "${ACTIVE_GATEWAY_RAW_URL:-$ACTIVE_GATEWAY_RAW_URL_DEFAULT}"
  write_env_kv XRAY_UUID "${xray_uuid}"
  write_env_kv XRAYUUID "${xray_uuid}"
  write_env_kv DEVICE_LIMIT "${DEVICE_LIMIT_DEFAULT}"
  write_env_kv SMTP_SERVER "${smtp_server}"
  write_env_kv SMTP_PORT "${smtp_port}"
  write_env_kv SMTP_USER "${smtp_user}"
  write_env_kv SMTP_PASS "${smtp_pass}"
  write_env_kv EMAIL_SENDER "${email_sender}"
  write_env_kv SECURITY_ALERT_EMAIL "${security_alert_email}"
  write_env_kv SECURITY_ALERT_EXEMPT_IPS "${security_alert_exempt_ips}"
  write_env_kv SECURITY_ALERT_LOCAL_IPS "${SECURITY_ALERT_LOCAL_IPS:-127.0.0.1,::1,$IONOS_HUB_IP}"
  write_env_kv SECURITY_ALERT_THROTTLE_SECONDS "${SECURITY_ALERT_THROTTLE_SECONDS:-300}"
  write_env_kv SECURITY_ALERT_MAX_EMAILS_PER_RUN "${SECURITY_ALERT_MAX_EMAILS_PER_RUN:-20}"
  write_env_kv SECURITY_EVENTS_DB "${SECURITY_EVENTS_DB:-$SECURITY_EVENTS_DB_DEFAULT}"
  write_env_kv SECURITY_EVENTS_RETENTION_DAYS "${SECURITY_EVENTS_RETENTION_DAYS:-$SECURITY_EVENTS_RETENTION_DAYS_DEFAULT}"
  write_env_kv SECURITY_ALERT_TIMEZONE "${SECURITY_ALERT_TIMEZONE:-$SECURITY_ALERT_TIMEZONE_DEFAULT}"
  write_env_kv SECURITY_ALERT_EMAIL_PRIORITIES "${SECURITY_ALERT_EMAIL_PRIORITIES:-$SECURITY_ALERT_EMAIL_PRIORITIES_DEFAULT}"
  write_env_kv SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS "${SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS:-$SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS_DEFAULT}"
  write_env_kv SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS "${SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS:-$SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS_DEFAULT}"
  write_env_kv SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS "${SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS:-$SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS_DEFAULT}"
  write_env_kv SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS "${SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS:-$SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS_DEFAULT}"
  write_env_kv SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS "${SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS:-$SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS_DEFAULT}"
  write_env_kv SECURITY_TRIAGE_ENABLED "${SECURITY_TRIAGE_ENABLED:-$SECURITY_TRIAGE_ENABLED_DEFAULT}"
  write_env_kv SECURITY_TRIAGE_ABSENT_PRODUCTS "${SECURITY_TRIAGE_ABSENT_PRODUCTS:-$SECURITY_TRIAGE_ABSENT_PRODUCTS_DEFAULT}"
  write_env_kv SECURITY_TRIAGE_PRESENT_PRODUCTS "${SECURITY_TRIAGE_PRESENT_PRODUCTS:-$SECURITY_TRIAGE_PRESENT_PRODUCTS_DEFAULT}"
  write_env_kv WINS_HEALTH_USER_AGENT "${WINS_HEALTH_USER_AGENT:-$WINS_HEALTH_USER_AGENT_DEFAULT}"
  write_env_kv PAYPAL_MODE "${PAYPAL_MODE:-live}"
  write_env_kv PAYPAL_PUBLIC_CLIENT_ID "${PAYPAL_PUBLIC_CLIENT_ID:-$PAYPAL_PUBLIC_CLIENT_ID_DEFAULT}"
  write_env_kv PAYPAL_CLIENT_ID "${PAYPAL_CLIENT_ID:-$PAYPAL_PUBLIC_CLIENT_ID_DEFAULT}"
  write_env_kv PAYPAL_CLIENT_SECRET "${PAYPAL_CLIENT_SECRET:-$PAYPAL_CLIENT_SECRET_DEFAULT}"
  write_env_kv PAYPAL_WEBHOOK_ID "${PAYPAL_WEBHOOK_ID:-$PAYPAL_WEBHOOK_ID_DEFAULT}"
  write_env_kv PAYPAL_WEBHOOK_AUTO_ENSURE "${PAYPAL_WEBHOOK_AUTO_ENSURE:-$PAYPAL_WEBHOOK_AUTO_ENSURE_DEFAULT}"
  write_env_kv PAYPAL_WEBHOOK_URL "${desired_paypal_webhook_url}"
  write_env_kv PAYPAL_SYNC_LOOKAHEAD_HOURS "${PAYPAL_SYNC_LOOKAHEAD_HOURS:-48}"
  write_env_kv PAYPAL_SYNC_STALE_HOURS "${PAYPAL_SYNC_STALE_HOURS:-24}"
  write_env_kv PAYPAL_API_MAX_RETRIES "${PAYPAL_API_MAX_RETRIES:-4}"
  write_env_kv RATE_LIMIT_SECRET "${rate_limit_secret}"
  write_env_kv MANAGEMENT_NAME_HMAC_KEY "${management_name_hmac_key}"
  write_env_kv REDEMPTION_KEYS "${redemption_keys}"
  write_env_kv REDEMPTION_KEY_ACTIVE_VERSION "${redemption_key_active_version}"
  write_env_kv REDEMPTION_FULFILLMENT_TTL_SECONDS "${REDEMPTION_FULFILLMENT_TTL_SECONDS:-$REDEMPTION_FULFILLMENT_TTL_SECONDS_DEFAULT}"
