  write_env_kv PAYPAL_LIFETIME_NO_SUPPORT_MARKERS "${PAYPAL_LIFETIME_NO_SUPPORT_MARKERS:-$PAYPAL_LIFETIME_NO_SUPPORT_MARKERS_DEFAULT}"
  write_env_kv PAYPAL_LIFETIME_MARKERS "${PAYPAL_LIFETIME_MARKERS:-$PAYPAL_LIFETIME_MARKERS_DEFAULT}"
  write_env_kv PAYPAL_PLAN_MARKERS "${PAYPAL_PLAN_MARKERS:-$PAYPAL_PLAN_MARKERS_DEFAULT}"
  write_env_kv DONOR_ACK_AUTO_ISSUE "${DONOR_ACK_AUTO_ISSUE:-$DONOR_ACK_AUTO_ISSUE_DEFAULT}"
  write_env_kv DONOR_TREAT_UNCLASSIFIED_ONE_TIME_AS_DONATION "${DONOR_TREAT_UNCLASSIFIED_ONE_TIME_AS_DONATION:-$DONOR_TREAT_UNCLASSIFIED_ONE_TIME_AS_DONATION_DEFAULT}"
  write_winn3_runtime_env || return 1
  write_awg_canary_runtime_env || return 1
  unset -f write_env_kv
  # ${LEGACY_ENV_FILE} sits in ${APP_DIR}, which the hub app can write, and
  # atomic_replace_file follows a link (for the vault's ${ENV_FILE}). No step
  # links the mirror, so a link there was planted: refuse it before either
  # file is written, rather than write every hub secret through it.
  if [[ -L "${LEGACY_ENV_FILE}" ]]; then
    err "${LEGACY_ENV_FILE} is a symlink; refusing to write the hub env through it. Nothing was changed."
    return 1
  fi
  atomic_replace_file "${ENV_FILE}" "${env_kv_buffer}" 600

  # Compatibility for the original all-in-one script, which used /root/vpn_auth/.env.
  atomic_replace_file "${LEGACY_ENV_FILE}" "${env_kv_buffer}" 600
  if [[ -z "${smtp_user}" || -z "${smtp_pass}" ]]; then
    warn "SMTP_USER / SMTP_PASS are empty. /admin/provision still creates accounts, but email sending will be skipped until SMTP credentials are added to ${ENV_FILE}."
  fi
}

# H0 (D3): inspect effective root authorization, without changing access.
refuse_hub_keys_authorized_for_root_here() {
  local effective address
  for address in 127.0.0.1 ::1 "${IONOS_HUB_IP:-127.0.0.1}"; do
    effective="$(sshd -T -C "user=root,host=localhost,addr=${address}")" || {
      err "Could not inspect effective root SSH authorization."
      return 1
    }
    python3 -I - "${WINS_ROOT_SSH_DIR:-/root/.ssh}" "${effective}" <<'ROOTKEYEOF' || return 1
import os
import pathlib
import re
import shlex
import subprocess
import sys

def authorized_key_options(line):
    """The option names of one authorized_keys line, as sshd reads it: the
    options field comes first unless the line starts with a key type, and it
    ends at the first blank outside double quotes. The comment after the key
    is free text and may hold a quote (for example "Win's MacBook")."""
    text = line.strip()
    if not text or re.match(r'(ssh-|ecdsa-|sk-)', text):
        return set()
    options, current, quoted = [], '', False
    for index, char in enumerate(text):
        if char == '"' and text[index - 1:index] != '\\':
            quoted = not quoted
        if not quoted and char in ' \t':
            break
        if not quoted and char == ',':
            options.append(current)
            current = ''
        else:
            current += char
    options.append(current)
    return {option.split('=', 1)[0].strip().lower() for option in options}

ssh_dir = pathlib.Path(sys.argv[1])
settings = dict(line.split(None, 1) for line in sys.argv[2].splitlines() if len(line.split(None, 1)) == 2)
if 'authorizedkeysfile' not in settings:
    raise SystemExit('Cannot inspect effective AuthorizedKeysFile for root')
for name in ('authorizedkeyscommand', 'trustedusercakeys'):
    if settings.get(name, 'none') != 'none':
        raise SystemExit('Root SSH authorization uses an unreviewed command or certificate authority')
blobs = set()
if ssh_dir.exists():
    for private in ssh_dir.iterdir():
        if not private.is_file() or private.name.endswith('.pub'):
            continue
        with private.open('rb') as stream:
            marker = stream.read(80)
        if b'PRIVATE KEY-----' not in marker:
            continue
        derived = subprocess.run(['ssh-keygen', '-y', '-P', '', '-f', str(private)],
                                 capture_output=True, text=True, timeout=10)
        public = pathlib.Path(str(private) + '.pub')
        candidates = [derived.stdout] if derived.returncode == 0 else []
        if public.is_file():
            candidates.append(public.read_text())
        if not candidates:
            raise SystemExit('Cannot inspect a private SSH identity readable by the hub')
        for candidate in candidates:
            fields = candidate.split()
            if len(fields) < 2:
                raise SystemExit('Cannot inspect the public half of a hub SSH identity')
            blobs.add(fields[1])
for entry in shlex.split(settings['authorizedkeysfile']):
    if entry == 'none':
        continue
    entry = entry.replace('%%', '\x00').replace('%h', str(ssh_dir.parent)).replace('%u', 'root').replace('%U', '0').replace('\x00', '%')
    if '%' in entry:
        raise SystemExit('Unsupported token in root AuthorizedKeysFile')
    target = pathlib.Path(entry)
    if not target.is_absolute():
        target = ssh_dir.parent / target
    if target.exists():
        for line in target.read_text().splitlines():
            if line.lstrip().startswith('#'):
                continue
            if 'cert-authority' in authorized_key_options(line):
                raise SystemExit('Root AuthorizedKeysFile uses an unreviewed certificate authority')
            if blobs.intersection(line.split()):
                raise SystemExit('A hub-readable SSH identity is authorized for root here; remove that authorization before continuing')
ROOTKEYEOF
  done
}

# Abstract AF_UNIX endpoints share the host network namespace. Refuse an
# unreviewed endpoint rather than treating the filesystem bind as isolation.
# With no argument (deploy and postflight) every abstract endpoint is refused.
# `preflight` is the read-only --preflight pass only: when the sole endpoints
# are the stock storage daemons' listeners, by exact name and kind, and this
# host does not use those daemons, it reports them and passes, because a
# deploy masks their units before it runs this gate strictly. Any other
# endpoint is still refused.
refuse_hub_abstract_brokers() {
  local mode="${1:-strict}" rc=0
  [[ "${mode}" == "strict" || "${mode}" == "preflight" ]] || {
    err "Unknown abstract-broker gate mode: ${mode}"
    return 1
  }
  WINS_HUB_ABSTRACT_GATE_MODE="${mode}" python3 -I - <<'ABSTRACTEOF' || rc=$?
import os
import pathlib
SO_ACCEPTCON, STREAM, DGRAM, SEQPACKET = 0x10000, 1, 2, 5
# multipathd.socket and iscsid.socket on the stock Ubuntu 24.04 server image
# (multipath-tools, open-iscsi). Exact name and kind; nothing else is reviewed.
STOCK_STORAGE_LISTENERS = {('@/org/kernel/linux/storage/multipathd', STREAM),
                           ('@ISCSIADM_ABSTRACT_NAMESPACE', STREAM)}
endpoints = set()
seen = set()
for row in pathlib.Path('/proc/net/unix').read_text().splitlines()[1:]:
    fields = row.split(None, 7)
    if len(fields) != 8 or not fields[7].startswith('@'):
        continue
    flags, kind = int(fields[3], 16), int(fields[4], 16)
    inode, name = fields[6], fields[7]
    if kind in (STREAM, SEQPACKET) and not flags & SO_ACCEPTCON:
        continue
    # State 03 does not establish that a datagram socket has a peer.
    # Refuse abstract datagrams until peer isolation is independently proved.
    kind_name = {STREAM: 'stream', DGRAM: 'datagram', SEQPACKET: 'seqpacket'}.get(kind, str(kind))
    endpoints.add(f"{name} ({kind_name}, inode {inode})")
    seen.add((name, kind))
if endpoints and os.environ.get('WINS_HUB_ABSTRACT_GATE_MODE') == 'preflight' \
        and seen <= STOCK_STORAGE_LISTENERS:
    print('Stock storage-daemon abstract AF_UNIX listeners on this host: ' + ', '.join(sorted(endpoints)))
    raise SystemExit(10)
if endpoints:
    raise SystemExit('Unreviewed abstract AF_UNIX endpoints remain on this host; H0 broker '
                     'isolation is not established: ' + ', '.join(sorted(endpoints))
                     + '. `ss -xlp` names the owning process; stop and mask its service, then re-run.')
ABSTRACTEOF
  ((rc == 10)) || return "${rc}"
  refuse_hub_storage_brokers_in_use || return 1
  log "Only the stock multipathd and iscsid listeners remain, and this host uses neither; --deploy masks their units before this gate runs strictly. Nothing was changed."
}

# The official Ubuntu 24.04 server cloud image ships multipath-tools and
# open-iscsi. multipathd listens on @/org/kernel/linux/storage/multipathd and
# iscsid on @ISCSIADM_ABSTRACT_NAMESPACE, which the strict gate above refuses.
# A hub uses neither, so a deploy masks these units before the gate and again
# before postflight (a package upgrade may bring them back). The inverse is
# `systemctl unmask <unit>` and `systemctl enable --now <unit>`.
hub_stock_abstract_units() {
  printf '%s\n' multipathd.socket multipathd.service iscsid.socket iscsid.service open-iscsi.service
}

# Masking is safe only where those daemons are idle. Refuse, and mask nothing,
# when any dm-multipath map or iSCSI session exists, or when the root or boot
# filesystem sits on a dm-multipath or iSCSI device. Read-only.
refuse_hub_storage_brokers_in_use() {
  local listed="" rc=0
  if command -v multipath >/dev/null 2>&1; then
    # -k: a multipath that ignores SIGTERM is killed 5 s later instead of
    # holding --preflight or --deploy. A killed listing is incomplete, whether
    # timeout reports it as 124 or as 137 (KILL).
    listed="$(timeout -k 5 60 multipath -ll 2>/dev/null)" || rc=$?
    if ((rc == 124 || rc == 137)); then
      err "multipath -ll did not finish within 60 s, so this host's dm-multipath use is unknown. Nothing was masked."
      return 1
    fi
    if [[ -n "${listed//[[:space:]]/}" ]]; then
      err "This host uses dm-multipath (multipath -ll lists a map), so multipathd and open-iscsi were not masked. The hub installer does not support multipath or iSCSI storage: the H0 abstract-broker gate refuses their sockets."
      return 1
    fi
  fi
  python3 -I - <<'STORAGEEOF'
import os
import re
SYS = '/sys'
MOUNTINFO = '/proc/self/mountinfo'
MPATH_UUID = re.compile(r'(part[0-9]+-)*mpath-')
found = []


def read(path):
    with open(path) as handle:
        return handle.read().strip()


def multipath_map(path):
    uuid = os.path.join(path, 'dm', 'uuid')
    return os.path.exists(uuid) and bool(MPATH_UUID.match(read(uuid)))


def stack(path, seen):
    path = os.path.realpath(path)
    if path in seen:
        return
    seen.add(path)
    # A partition's sysfs path already contains its disk's path.
    yield path
    slaves = os.path.join(path, 'slaves')
    if os.path.isdir(slaves):
        for name in sorted(os.listdir(slaves)):
            yield from stack(os.path.join(slaves, name), seen)


try:
    for name in sorted(os.listdir(os.path.join(SYS, 'block'))):
        if multipath_map(os.path.join(SYS, 'block', name)):
            found.append(f'dm-multipath map {name}')
    sessions = os.path.join(SYS, 'class', 'iscsi_session')
    if os.path.isdir(sessions):
        found.extend(f'iSCSI session {name}' for name in sorted(os.listdir(sessions)))
    for row in read(MOUNTINFO).splitlines():
        fields = row.split()
        if len(fields) < 5 or fields[4] not in ('/', '/boot', '/boot/efi'):
            continue
        # Major 0 has no block device (btrfs, zfs, overlay). Such a root is
        # still refused above if any multipath map or iSCSI session exists.
        if fields[2].split(':')[0] == '0':
            continue
        device = os.path.join(SYS, 'dev', 'block', fields[2])
        if not os.path.exists(device):
            raise SystemExit(f'Cannot resolve the block device under {fields[4]} ({fields[2]}); nothing was masked.')
        for path in stack(device, set()):
            if multipath_map(path):
                found.append(f'{fields[4]} is on dm-multipath device {os.path.basename(path)}')
            if re.search(r'/session[0-9]+/', path + '/'):
                found.append(f'{fields[4]} is on iSCSI device {os.path.basename(path)}')
except OSError as error:
    raise SystemExit(f'Cannot establish whether this host uses dm-multipath or iSCSI ({error}); nothing was masked.')
if found:
    raise SystemExit('This host uses dm-multipath or iSCSI storage (' + '; '.join(found) + '), so multipathd '
                     'and open-iscsi were not masked. The hub installer does not support multipath or iSCSI '
                     'storage: the H0 abstract-broker gate refuses their sockets.')
STORAGEEOF
}

# Deploy only: mask the stock units that are installed, after refusing a host
# that uses them. A unit that cannot be stopped keeps its socket, and the
# strict gate that follows refuses the host.
hub_mask_stock_abstract_services() {
  local unit listed
  local -a present=()
  while IFS= read -r unit; do
    listed="$(systemctl list-unit-files --no-legend "${unit}" 2>/dev/null)" || listed=""
    [[ -n "${listed}" ]] && present+=("${unit}")
  done < <(hub_stock_abstract_units)
  ((${#present[@]})) || return 0
  refuse_hub_storage_brokers_in_use || return 1
  for unit in "${present[@]}"; do
    systemctl disable --now "${unit}" >/dev/null 2>&1 || true
    systemctl mask "${unit}" >/dev/null 2>&1 || {
      err "Could not mask ${unit}. The H0 abstract-broker gate will refuse this host until that unit is masked."
      return 1
    }
  done
  log "Masked the stock storage units this hub does not use: ${present[*]} (inverse: systemctl unmask, then systemctl enable --now)."
}

require_root_owned_venv() {
  python3 -I - "${VENV_DIR}" "${APP_DIR}" <<'VENVEOF'
import os
import stat
import sys

venv, app_dir = map(os.path.abspath, sys.argv[1:3])
app_writable = (app_dir, '/var/lib/wins-hub-ssh', '/var/lib/wins-site-ai-tunnel',
                '/var/lib/wins-security-alerts', '/var/log/winsvpn')
def trusted(path):
    info = os.lstat(path)
    if info.st_uid != 0 or info.st_gid != 0 or info.st_mode & 0o022:
        raise SystemExit('Refusing dependency code with insecure ownership or permissions')
if os.path.islink(venv):
    raise SystemExit('VENV_DIR must not be a symlink')
if os.path.exists(venv):
    trusted(venv)
    for directory, dirs, files in os.walk(venv, followlinks=False):
        trusted(directory)
        for name in dirs + files:
            path = os.path.join(directory, name)
            if os.path.islink(path):
                target = os.path.realpath(path)
                if any(target == root or target.startswith(root + os.sep) for root in app_writable) and not target.startswith(venv + os.sep):
                    raise SystemExit('A dependency link points into app-writable code')
                while target != '/':
                    trusted(target)
                    target = os.path.dirname(target)
            else:
                trusted(path)
VENVEOF
}

ensure_hub_ssh_key() {
  mkdir -p /root/.ssh
  chmod 700 /root/.ssh
  # /root/.ssh is writable by the hub app (wins-hub.service ReadWritePaths), so
  # a link at either key name was planted; ssh-keygen and chmod would follow it.
  if [[ -L /root/.ssh/id_rsa || -L /root/.ssh/id_rsa.pub ]]; then
    err "The hub SSH key path is a symlink; refusing to create or change the key through it."
    return 1
  fi
  if [[ ! -f /root/.ssh/id_rsa ]]; then
    log "Generating hub SSH key for data-plane peer synchronization"
    ssh-keygen -t rsa -b 4096 -N "" -f /root/.ssh/id_rsa >/dev/null
  fi
  chmod 600 /root/.ssh/id_rsa
  chmod 644 /root/.ssh/id_rsa.pub
}

# H5 (design 3.15, ruling E): the hub-held AmneziaWG carrying-canary keypair.
# The private key is a probe credential, not a signing key: on a node it
# authorizes only the canary address 10.8.255.1/32. It sits in this root-only
# directory and is read by the carrying probe alone. The hub app and the env
# file carry the PUBLIC key only, but the app runs as root with ${APP_DIR}
# writable (H0), so this directory is not hidden from it. An existing key is
# kept, never rotated: nothing here revokes an old canary peer from the nodes,
# so a replaced private key is refused rather than adopted.
AWG_CANARY_DIR="${AWG_CANARY_DIR:-${APP_DIR}/awg-canary}"

awg_canary_key_is_raw32_b64() {
  local value="$1"
  [[ "${value}" =~ ^[A-Za-z0-9+/]{43}=$ ]] || return 1
  [[ "$(printf '%s' "${value}" | base64 -d 2>/dev/null | wc -c | tr -d ' ')" == "32" ]]
}

ensure_awg_canary_keypair() {
  local private_file="${AWG_CANARY_DIR}/private.key" public_key
  command -v wg >/dev/null 2>&1 || {
    err "wg (wireguard-tools) is required to create the hub AWG carrying-canary key." >&2
    return 1
  }
  if [[ -L "${AWG_CANARY_DIR}" || -L "${private_file}" ]]; then
    err "The hub AWG carrying-canary key path is a symlink; nothing was changed." >&2
    return 1
  fi
  # The app can plant a link at any name in this directory, so the two staging
  # names and the public-key record are refused as links too, and every write
  # below goes to a freshly unlinked name under noclobber (O_EXCL), which a
  # link planted in between cannot satisfy.
  if [[ -L "${private_file}.new" || -L "${AWG_CANARY_DIR}/public.key" || -L "${AWG_CANARY_DIR}/public.key.new" ]]; then
    err "A hub AWG carrying-canary record path is a symlink; nothing was changed." >&2
    return 1
  fi
  install -d -m 0700 -o root -g root "${AWG_CANARY_DIR}" || return 1
  if [[ -e "${private_file}" && ! -f "${private_file}" ]]; then
    err "The hub AWG carrying-canary private key is not a regular file; nothing was changed." >&2
    return 1
  fi
  if [[ ! -s "${private_file}" ]]; then
    log "Generating the hub AWG carrying-canary keypair" >&2
    rm -f -- "${private_file}.new" || return 1
    ( umask 077; set -C; wg genkey > "${private_file}.new" ) || { rm -f -- "${private_file}.new"; return 1; }
    chmod 600 "${private_file}.new"
    mv -f -- "${private_file}.new" "${private_file}" || return 1
  fi
  chown root:root "${private_file}"
  chmod 600 "${private_file}"
  public_key="$(wg pubkey < "${private_file}")" || {
    err "The hub AWG carrying-canary private key is unreadable; nothing was changed." >&2
    return 1
  }
  awg_canary_key_is_raw32_b64 "${public_key}" || {
    err "The hub AWG carrying-canary public key is not a 32-byte base64 key." >&2
    return 1
  }
  if [[ -s "${AWG_CANARY_DIR}/public.key" ]] \
     && [[ "$(tr -d '[:space:]' < "${AWG_CANARY_DIR}/public.key")" != "${public_key}" ]]; then
    err "The hub AWG carrying-canary private key no longer matches the public key this hub recorded. Rotation is not supported: every node still holds the old public key, and it would stay there and fail the off-node gate. Restore the original key, or revoke the old canary peer from every node, then remove ${AWG_CANARY_DIR}/public.key to adopt the new one." >&2
    return 1
  fi
  rm -f -- "${AWG_CANARY_DIR}/public.key.new" || return 1
  ( set -C; printf '%s\n' "${public_key}" > "${AWG_CANARY_DIR}/public.key.new" ) || { rm -f -- "${AWG_CANARY_DIR}/public.key.new"; return 1; }
  chmod 644 "${AWG_CANARY_DIR}/public.key.new" || return 1
  mv -f -- "${AWG_CANARY_DIR}/public.key.new" "${AWG_CANARY_DIR}/public.key" || return 1
  printf '%s' "${public_key}"
}

# The hub's userspace AmneziaWG carrying canary client (design 3.15, ruling
# E): wins-awg-carry-client, built reproducibly from tools/awg_carry_client
# (receipt: awg-carry-client.build.json beside this script) and staged
# root-only under /usr/local/bin by install_awg_carry_client. One digest per
# architecture, the only source of truth for the pin the env carries and the
# bytes the staging step accepts; the carry probe refuses any other bytes
# (carry_client_unpinned).
AWG_CARRY_CLIENT_STAGED="/usr/local/bin/wins-awg-carry-client"
awg_carry_client_pin() {
  case "${1:-$(uname -m)}" in
    x86_64|amd64) printf '%s' "7b9bd0531e20c420842c92ec088711ab53b948901056f8e9ff1f9032b0caf1b1" ;;
    aarch64|arm64) printf '%s' "38ac4772dd07467191e1b66ce46b7032cf7beeddfe96356fbe483c91fbf868c1" ;;
    *) err "No pinned AWG carry client for this architecture."; return 1 ;;
  esac
}

# Env: the public key, the root-only private key path the carrying probe reads,
# and the DNS name it asks for. AWG_CARRY_CLIENT_BIN names the userspace
# AmneziaWG client the probe drives, AWG_CARRY_CLIENT_SHA256 pins its bytes.
# By default they name the client this installer stages
# (install_awg_carry_client) and its pin for this architecture; an operator
# may name another client, and then must pin it too.
write_awg_canary_runtime_env() {
  local public_key client_sha256
  public_key="$(ensure_awg_canary_keypair)" || return 1
  write_env_kv AWG_CANARY_PUBLIC_KEY "${public_key}" || return 1
  write_env_kv AWG_CANARY_KEY_FILE "${AWG_CANARY_DIR}/private.key" || return 1
  write_env_kv AWG_CANARY_DNS_NAME "${HUB_DOMAIN}" || return 1
  if [[ -z "${AWG_CARRY_CLIENT_BIN:-}" && -n "${AWG_CARRY_CLIENT_SHA256:-}" ]]; then
    err "AWG_CARRY_CLIENT_SHA256 is set without AWG_CARRY_CLIENT_BIN; the staged client carries its own pin. Unset it, or name the client it pins."
    return 1
  fi
  # The staged path always carries this installer's pin: install_awg_carry_client
  # overwrites it with exactly those bytes, and on a rerun load_existing_envs
  # has already read the previous run's AWG_CARRY_CLIENT_BIN and _SHA256 back,
  # so treating them as an operator's choice would keep an older release's pin
  # and refuse every probe after a client upgrade.
  if [[ -n "${AWG_CARRY_CLIENT_BIN:-}" && "${AWG_CARRY_CLIENT_BIN}" != "${AWG_CARRY_CLIENT_STAGED}" ]]; then
    # H0 (D6): the root carry unit executes this file, so it must sit where the
    # hub app cannot write: under /usr, read-only to the app (ProtectSystem=
    # strict), never in ${APP_DIR} or any other app-writable path.
    [[ "${AWG_CARRY_CLIENT_BIN}" =~ ^/usr/(local/)?(bin|sbin|lib|libexec)(/[A-Za-z0-9_.-]+)+$ \
       && "${AWG_CARRY_CLIENT_BIN}/" != *"/../"* && "${AWG_CARRY_CLIENT_BIN}/" != *"/./"* ]] || {
      err "AWG_CARRY_CLIENT_BIN must be a path under /usr/bin, /usr/sbin, /usr/lib, /usr/libexec or their /usr/local forms, of letters, digits and _ . - only."
      return 1
    }
    [[ "${AWG_CARRY_CLIENT_SHA256:-}" =~ ^[0-9a-f]{64}$ ]] || {
      err "AWG_CARRY_CLIENT_BIN needs AWG_CARRY_CLIENT_SHA256, the 64 lowercase hex digits of the staged client."
      return 1
    }
    write_env_kv AWG_CARRY_CLIENT_BIN "${AWG_CARRY_CLIENT_BIN}" || return 1
    write_env_kv AWG_CARRY_CLIENT_SHA256 "${AWG_CARRY_CLIENT_SHA256}" || return 1
  else
    client_sha256="$(awg_carry_client_pin)" || return 1
    write_env_kv AWG_CARRY_CLIENT_BIN "${AWG_CARRY_CLIENT_STAGED}" || return 1
    write_env_kv AWG_CARRY_CLIENT_SHA256 "${client_sha256}" || return 1
  fi
}

backup_existing_db() {
  if [[ -f "${DB_PATH}" ]]; then
    local stamp backup
    stamp="$(date +%Y%m%d_%H%M%S)"
    backup="${DB_PATH}.pre-fixed-${stamp}.bak"
    # ${APP_DIR} is writable by the hub app, which can plant a link at this
    # predictable name; cp would copy the whole database through it.
    if [[ -e "${backup}" || -L "${backup}" ]]; then
      err "${backup} already exists or is a symlink; refusing to copy the hub database onto it."
      return 1
    fi
    # The hub stays live during a rerun, so committed rows may exist only in
    # its WAL. Use SQLite's online snapshot, as the nightly backup does.
    ( umask 077; sqlite3 "${DB_PATH}" ".timeout 30000" ".backup '${backup}'" ) || return 1
    [[ "$(sqlite3 -readonly "${backup}" 'PRAGMA quick_check;')" == "ok" ]] || {
      err "Pre-deploy database snapshot ${backup} failed its integrity check."
      return 1
    }
    chmod 600 "${backup}" || return 1
    log "Database backup written: ${backup}"
  fi
}

# Path of the provenance stamp write_app() maintains for the hub application
# code. It holds the SHA-256 of exactly the bytes this installer last wrote to
# main.py, so the next run can tell "unchanged since I wrote it" apart from
# "someone edited it on the host".
APP_CODE_STAMP="${APP_DIR}/.main.py.deployed.sha256"

# ---------------------------------------------------------------------------
# HAND-PATCH RECONCILIATION CHECK
#
# WHY THIS EXISTS, and why the drift guard alone was not enough.
#
# guard_app_code_drift() below refuses when it cannot prove provenance, which is
# correct. But on a host that was hand-patched BEFORE the guard shipped there is
# no stamp to compare against, so the guard refuses unconditionally and the only
# way past it is ALLOW_MAIN_PY_OVERWRITE=1 -- which proceeds BLIND. That left the
# operator with two bad options on deploy night: be blocked, or overwrite without
# knowing whether the host-side work had been reconciled into this installer.
#
# The four documented host-side patches ARE reconciled into this installer (see
# docs/handoff/CONTROL_PLANE_HAND_PATCH_RECONCILIATION_20260807.md and
# docs/handoff/HUB_HAND_PATCH_RECONCILED_20260808.md). So the missing piece was
# never the code -- it was a way for the installer to PROVE, on the host, that
# what it is about to write still contains everything the host's copy has.
#
# That is what these two functions do. They are evidence, not permission:
#
#   extract_incoming_app_code()      pulls the main.py this run WOULD write back
#                                    out of this script file, so it can be
#                                    compared against the host's copy before a
#                                    single byte is truncated.
#   app_code_reconciliation_report() compares the two, and refuses on anything it
#                                    cannot account for.
#
# FAIL-CLOSED IN EVERY DIRECTION. If the incoming code cannot be extracted, if
# either file will not parse, or if anything at all is found on the host that
# this installer does not reproduce, the report fails and the guard refuses
# exactly as it does today. It can only ever turn a refusal into a proceed by
# producing positive evidence; it can never turn a proceed into a refusal.
# ---------------------------------------------------------------------------

# Recover the hub source this run would install, from this script file itself.
# Writes it to $1. Returns non-zero if it cannot be recovered, in which case the
# caller must fall back to refusing.
extract_incoming_app_code() {
  local dest="$1"
  local self="${BASH_SOURCE[0]:-}"
  local start end marker head tail
  [[ -n "${self}" && -f "${self}" && -r "${self}" ]] || return 1
  # The marker is assembled from two halves ON PURPOSE. Spelled out in one
  # piece, this line would itself be the first match for its own search and the
  # extractor would slice from here instead of from the real heredoc.
  head='cat > "${APP_DIR}'
  tail='/main.py" <<'
  marker="${head}${tail}"
  start="$(grep -Fn -- "${marker}" "${self}" | head -1 | cut -d: -f1)"
  [[ -n "${start}" ]] || return 1
  end="$(awk -v s="${start}" 'NR>s && $0=="PYEOF" {print NR; exit}' "${self}")"
  [[ -n "${end}" && "${end}" -gt "$((start + 1))" ]] || return 1
  sed -n "$((start + 1)),$((end - 1))p" "${self}" > "${dest}" 2>/dev/null || return 1
  [[ -s "${dest}" ]] || return 1
  return 0
}

# Compare the host's main.py against the main.py this run would write.
#   $1  the host's copy (possibly hand-patched)
#   $2  the copy this installer would write
# Prints a report. Exit 0 means: everything the host has is reproduced, so
# overwriting loses nothing. Exit non-zero means something would be lost, and
# the report names it.
app_code_reconciliation_report() {
  local on_disk="$1" incoming="$2" baseline=""
  local candidate

  # Find a PRE-HAND-PATCH baseline among the backups already on this host. A
  # backup that contains no data_plane_* content at all predates every one of
  # the four patches by definition, so it is self-identifying -- no filename
  # convention is trusted. The NEWEST such backup is chosen because it is the
  # closest clean ancestor, which keeps the delta down to host-side work rather
  # than months of ordinary repo evolution.
  #
  # This is what makes the check exact rather than approximate: with a baseline,
  # "added on the host by hand" is a set difference, not a guess.
  for candidate in $(ls -1t "${APP_DIR}"/main.py.bak* "${APP_DIR}"/main.py.*.bak 2>/dev/null); do
    [[ -f "${candidate}" ]] || continue
    if ! grep -q 'data_plane_' "${candidate}" 2>/dev/null; then
      baseline="${candidate}"
      break
    fi
  done

  python3 - "${on_disk}" "${incoming}" "${baseline}" <<'RECONEOF'
import ast
import sys

on_disk_path, incoming_path = sys.argv[1], sys.argv[2]
baseline_path = sys.argv[3] if len(sys.argv) > 3 else ""

# The four host-side patches this installer reconciled, each identified by
# tokens that appear ONLY in that patch's code. Substring matching against
# source text is used deliberately in preference to matching quoted expressions:
# the live file's exact spacing and quoting cannot be assumed, but these bare
# identifiers cannot be spelled any other way.
MANIFEST = [
    ("P1  data-plane reachability gate       (patch_main_dataplane.py)",
     ("data_plane_status",
      "DATA_PLANE_AVAILABLE_SQL",
      "node_data_plane_is_available",
      "DATA_PLANE_HARD_STALE_MINUTES")),
    ("P2  platform-aware transport gate      (patch_main_transport.py)",
     ("STEALTH_INCAPABLE_PLATFORMS",
      "platform_can_use_stealth",
      "data_plane_sql",
      "node_transport_availability",
      "DATA_PLANE_UDP_AVAILABLE_SQL")),
    # P3 had no patch script on the host and was reconstructed by diffing
    # backups. Its one unique token is the client-contract key; the aggregate
    # gate tokens it shares with P1 are not distinctive, so they are not listed.
    ("P3  GET /nodes listing-reach contract  (no patch script; reconstructed)",
     ("reachabletransports",)),
    ("P4  Linux TLS-stealth branch           (patch_main_stealth_tls.py)",
     ("DATA_PLANE_STEALTH_TLS_PROVEN_SQL",
      "data_plane_stealth_tls_status",
      "stealth_tls_tcp_ws")),
]


def read(path):
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        return handle.read()


def toplevel_names(src):
    """Module-level def/class/assignment names. None if the source will not
    parse, which the caller treats as a refusal rather than an empty set."""
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return None
    names = set()
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    names.add(target.id)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            names.add(node.target.id)
    return names


try:
    disk_src = read(on_disk_path)
    incoming_src = read(incoming_path)
except OSError as exc:
    print("  Could not read both copies for comparison: %s" % exc)
    sys.exit(1)

print("  Hand-patch reconciliation check")
print("  -------------------------------")

failures = []

# ---- 1. The four documented patches, by name --------------------------------
for label, markers in MANIFEST:
    present = [m for m in markers if m in disk_src]
    if not present:
        print("  n/a      %s" % label)
        print("           not present on this host")
        continue
    missing = [m for m in present if m not in incoming_src]
    if missing:
        failures.append("%s -- this installer does not reproduce: %s"
                        % (label.split("(")[0].strip(), ", ".join(missing)))
        print("  WOULD BE LOST  %s" % label)
        for name in missing:
            print("           missing from the incoming hub code: %s" % name)
    else:
        print("  carried  %s" % label)
        print("           %d/%d markers present here and reproduced"
              % (len(present), len(markers)))

# ---- 2. Anything else that was added on the host ----------------------------
disk_names = toplevel_names(disk_src)
incoming_names = toplevel_names(incoming_src)
if disk_names is None or incoming_names is None:
    print("  UNPARSEABLE  one of the two copies is not valid Python; cannot")
    print("               account for host-side additions. Refusing.")
    sys.exit(1)

baseline_names = None
baseline_note = "none found on this host -- coarse comparison only"
if baseline_path:
    try:
        baseline_names = toplevel_names(read(baseline_path))
    except OSError:
        baseline_names = None
    if baseline_names is None:
        # Name it anyway. "Found but unusable" and "not there at all" send an
        # operator to two different places, and the coarse path that follows is
        # stricter, so the difference is worth a line.
        baseline_note = "%s -- will not parse, coarse comparison only" % baseline_path
    else:
        baseline_note = baseline_path
print("  baseline %s" % baseline_note)

if baseline_names is not None:
    # EXACT: names on the host that its own pre-patch ancestor did not have are
    # precisely the host-side additions. Ordinary repo churn cannot show up here,
    # because anything the repo removed since is absent from the host too.
    added_by_hand = (disk_names - baseline_names) - incoming_names
    if added_by_hand:
        failures.append("host-side additions this installer does not define: %s"
                        % ", ".join(sorted(added_by_hand)))
        print("  WOULD BE LOST  %d host-side definition(s) not in the incoming code:"
              % len(added_by_hand))
        for name in sorted(added_by_hand):
            print("           %s" % name)
    else:
        print("  carried  every host-side definition is reproduced")
else:
    # COARSE: with no clean ancestor, "on the host but not incoming" also
    # catches anything the repo legitimately removed since this host was
    # provisioned. Still fatal -- a named list an operator can dismiss in
    # seconds is worth more than a silent overwrite -- but the message says so.
    residue = disk_names - incoming_names
    if residue:
        failures.append("%d definition(s) on this host are absent from the "
                        "incoming code and no clean ancestor was available to "
                        "tell host-side work apart from repo removals"
                        % len(residue))
        print("  UNACCOUNTED  %d definition(s) present here, absent incoming:"
              % len(residue))
        for name in sorted(residue):
            print("           %s" % name)
    else:
        print("  carried  no host-side definition is absent from the incoming code")

print("  -------------------------------")
if failures:
    for line in failures:
        print("  ! %s" % line)
    sys.exit(1)
print("  RESULT: overwriting this host's main.py loses nothing.")
sys.exit(0)
RECONEOF
}

# Guard against silently destroying host-side edits to the hub application.
#
# WHY THIS EXISTS. write_app() used to do an unconditional
# `cat > "${APP_DIR}/main.py"` with no drift check and no backup of main.py --
# only backup_existing_db() ran, and that backs up the database, not the code --
# followed by `systemctl restart wins-hub.service`. In August 2026 that
# combination was one deploy away from destroying four hand-authored patches
# (the external data-plane reachability gate and its client contract) that
# existed in no commit. The reversion would have been SILENT: SQLite never drops
# columns, so the data_plane_* columns and the probe timer would have survived
# and kept writing verdicts that nothing read. Nothing would have logged,
# nothing would have 500'd, and the client's _boolDefaultTrue(item['reachable'])
# would have quietly flipped every node back to "reachable" and resumed offering
# unreachable servers to real users.
#
# So: back up first, then refuse. A hand-patch must be DISCOVERED at the next
# deploy, not overwritten by it.
#
# Cases:
#   no main.py            -> first install. Proceed.
#   no stamp file         -> provenance unprovable. This is exactly the state a
#                            host hand-patched before this guard shipped is in,
#                            so it is treated as drift, not waved through.
#   stamp matches on-disk -> this installer wrote what is there. Proceed.
#   stamp differs         -> DRIFT.
#
# On the last two cases the guard does NOT refuse on the spot. It first asks
# app_code_reconciliation_report() whether the code it is about to write still
# contains everything the host's copy has (see the long note above that
# function). Only two outcomes are possible:
#
#   report passes -> the host's edits are reconciled INTO this installer. There
#                    is nothing left to lose, the operator is told exactly which
#                    host-side work was recognised, and the deploy proceeds
#                    WITHOUT an override.
#   report fails  -> refuse, naming what would be lost. That list is the
#                    reconciliation to-do, not a riddle.
#
# ALLOW_MAIN_PY_OVERWRITE=1 survives as the last resort for the case where an
# operator has reconciled something by hand that the report cannot see. It is no
# longer the expected route through, and it is the only route that proceeds
# without evidence. The backup is taken on every path, so no route can lose the
# host's copy.
guard_app_code_drift() {
  local target="${APP_DIR}/main.py"
  local stamp backup on_disk recorded nonce
  if [[ ! -e "${target}" && ! -L "${target}" ]]; then
    log "No existing ${target}; first install of the hub application."
    return 0
  fi

  # H0: ${APP_DIR} is writable by the hub app (wins-hub.service
  # ReadWritePaths), so a link at main.py or at the provenance stamp was
  # planted by it. Reading the code or the stamp through one, or writing the
  # backup, main.py or the stamp through one, would let that root app reach
  # any host path. Refuse, exactly as ensure_hub_ssh_key and backup_existing_db
  # refuse their own app-writable names.
  if [[ -L "${target}" || -L "${APP_CODE_STAMP}" ]]; then
    err "REFUSING: ${target} or ${APP_CODE_STAMP} is a symlink (the hub app can plant one in ${APP_DIR}); the hub application was not backed up, compared or overwritten through it."
    exit 1
  fi
  [[ -f "${target}" ]] || {
    err "REFUSING: ${target} exists but is not a regular file; the hub application was not backed up, compared or overwritten."
    exit 1
  }

  # Back up BEFORE any decision, and before `cat >` truncates the file. This is
  # the copy that makes a hand-patch recoverable and diffable. The name carries
  # a random suffix the app cannot predict and the file is created with O_EXCL
  # (noclobber), so a link planted at the backup name is refused rather than
  # written through, and a copy made through the fresh descriptor is the
  # host's bytes and nothing else.
  stamp="$(date -u +%Y%m%d_%H%M%SZ)"
  nonce="$(od -An -N6 -tx1 /dev/urandom | tr -d ' \n')"
  [[ "${nonce}" =~ ^[0-9a-f]{12}$ ]] || {
    err "Could not mint a backup name for ${target}; refusing to continue."
    exit 1
  }
  backup="${target}.pre-deploy-${stamp}-${nonce}.bak"
  if ! ( umask 077; set -C; cat -- "${target}" > "${backup}" ); then
    err "Could not write the hub application backup ${backup} (a file or link already sits at that name, or the copy failed); refusing to continue."
    exit 1
  fi
  log "Hub application backup written: ${backup}"

  on_disk="$(sha256sum "${target}" | awk '{print $1}')"
  recorded=""
  if [[ -f "${APP_CODE_STAMP}" ]]; then
    recorded="$(awk 'NR==1{print $1}' "${APP_CODE_STAMP}" 2>/dev/null || true)"
  fi

  if [[ -n "${recorded}" && "${recorded}" == "${on_disk}" ]]; then
    log "Hub application matches the last version this installer wrote; no drift."
    return 0
  fi

  # The stamp does not vouch for what is on disk. Before refusing, find out
  # whether that actually matters: if everything the host's copy carries is
  # reproduced by the code about to be written, overwriting it loses nothing and
  # there is no reason to make the operator reach for a blind override.
  local incoming report
  incoming="$(mktemp "${TMPDIR:-/tmp}/wins-incoming-app.XXXXXX")" || incoming=""
  report="$(mktemp "${TMPDIR:-/tmp}/wins-recon-report.XXXXXX")" || report=""
  if [[ -n "${incoming}" && -n "${report}" ]] && extract_incoming_app_code "${incoming}"; then
    if app_code_reconciliation_report "${target}" "${incoming}" > "${report}" 2>&1; then
      log "Hub application differs from the last version this installer wrote."
      while IFS= read -r line; do log "${line}"; done < "${report}"
      log "Host-side work is reconciled into this installer; proceeding without an override."
      log "The host's copy remains at ${backup}."
      rm -f "${incoming}" "${report}"
      return 0
    fi
  fi

  err "REFUSING TO OVERWRITE ${target} -- it is not what this installer last wrote."
  if [[ -n "${report}" && -s "${report}" ]]; then
    while IFS= read -r line; do err "${line}"; done < "${report}"
    err ""
  elif [[ -n "${incoming}" ]]; then
    err "  The hub code this run would write could not be recovered from this"
    err "  script for comparison, so nothing could be ruled out. Refusing."
    err ""
  fi
  rm -f "${incoming}" "${report}"
  if [[ -z "${recorded}" ]]; then
    err "  No provenance stamp at ${APP_CODE_STAMP}."
    err "  Either this host predates the drift guard, or the stamp was removed."
    err "  Its contents cannot be assumed to match this installer's."
  else
    err "  recorded sha256: ${recorded}"
    err "  on-disk sha256:  ${on_disk}"
  fi
  err ""
  err "  The running hub has been modified on the host. Overwriting it now would"
  err "  revert those changes and restart the service, and because SQLite never"
  err "  drops columns the reversion would not surface as an error anywhere."
  err ""
  err "  The host's copy is preserved at:"
  err "    ${backup}"
  err "  Reconcile it into server/wins_control_plane_setup_ONETOUCH.sh first. The"
  err "  report above names what is missing; each entry is one thing to port."
  err "  When they are all ported, this guard proceeds on its own -- a"
  err "  reconciled host does NOT need an override."
  err ""
  err "  ALLOW_MAIN_PY_OVERWRITE=1 exists only for work you have reconciled by"
  err "  hand in a way the report cannot see. It is the one path that proceeds"
  err "  without evidence, so prefer fixing the report:"
  err "    ALLOW_MAIN_PY_OVERWRITE=1 $0 ..."

  if [[ "${ALLOW_MAIN_PY_OVERWRITE:-0}" == "1" ]]; then
    warn "ALLOW_MAIN_PY_OVERWRITE=1 set -- proceeding and OVERWRITING ${target}."
    warn "The host's previous copy remains at ${backup}."
    return 0
  fi
  exit 1
}

# Record the SHA-256 of exactly what we just wrote, so the next run can detect
# any edit made between now and then.
record_app_code_stamp() {
  local target="${APP_DIR}/main.py" tmp
  [[ -f "${target}" && ! -L "${target}" ]] || return 0
  # H0: the stamp sits in the app-writable ${APP_DIR}. Write it to an
  # unguessable name with O_EXCL and rename it into place (-T: a planted link
  # at the stamp name is replaced, never followed, and never treated as a
  # directory to move into).
  tmp="$(mktemp -u "${APP_CODE_STAMP}.XXXXXXXX")" || return 1
  if ! ( umask 077; set -C; {
    sha256sum "${target}" | awk '{print $1}'
    printf 'written_at=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    printf '# Provenance stamp for %s, maintained by write_app().\n' "${target}"
    printf '# Do not hand-edit. If you patch main.py on this host, expect the\n'
    printf '# next installer run to refuse until the patch is in the repo.\n'
  } > "${tmp}" ); then
    rm -f -- "${tmp}"
    err "Could not write the hub application provenance stamp ${APP_CODE_STAMP}."
    return 1
  fi
  mv -f -T -- "${tmp}" "${APP_CODE_STAMP}" || { rm -f -- "${tmp}"; return 1; }
  log "Hub application provenance stamp recorded: ${APP_CODE_STAMP}"
}

write_app() {
  # Drift guard first: this must run BEFORE any `cat >` below truncates a file
  # that may carry host-side edits.
  guard_app_code_drift

  # H0: every name written below is in the app-writable ${APP_DIR}. A link the
  # hub app planted at any of them is refused (the guard above already refused
  # one at main.py and the stamp), the SVG goes through an O_EXCL temp file and
  # a rename, and main.py is written under noclobber so a link that appears
  # between the check and the write fails the write instead of being followed.
  local app_asset_dir="${APP_DIR}/assets"
  local app_svg="${app_asset_dir}/certificate-of-recognition.svg" app_svg_tmp
  if [[ -L "${app_asset_dir}" || -L "${app_svg}" ]]; then
    err "REFUSING: ${app_asset_dir} or ${app_svg} is a symlink (the hub app can plant one in ${APP_DIR}); nothing was written."
    exit 1
  fi

  # Donor certificate artwork, installed beside main.py. The acknowledgment
  # engine populates THIS file; rsvg-convert (librsvg2-bin, installed above)
  # turns the populated copy into the PDF the donor receives, so the
  # presentable document and the IRS-compliant document are the same file.
  mkdir -p "${app_asset_dir}"
  app_svg_tmp="$(mktemp -u "${app_svg}.XXXXXXXX")"
  ( set -C; cat > "${app_svg_tmp}" ) <<'SVGEOF'
