# and skips the network call entirely. On any live-price failure the create-order
# endpoint returns 503 and NEVER guesses a rate.
MONERO_PRICE_API_URL = os.getenv("MONERO_PRICE_API_URL", "https://api.kraken.com/0/public/Ticker?pair=XMRUSD").strip()
MONERO_PRICE_MANUAL_USD = os.getenv("MONERO_PRICE_MANUAL_USD", "").strip()
