except (TypeError, ValueError):
    MONERO_ORDER_TTL_MINUTES = 45
# Clamp the quote-validity window to a sane 15-120 minute band: long enough for a
# buyer to fund and confirm, short enough that a locked-in exchange rate cannot go
# badly stale before the order expires.
MONERO_ORDER_TTL_MINUTES = max(15, min(MONERO_ORDER_TTL_MINUTES, 120))
MONERO_ATOMIC_UNITS_PER_XMR = 10 ** 12  # 1 XMR = 1e12 piconero (atomic units)
MONERO_SETTLE_BATCH_LIMIT = 200
# M-6: Monero price-oracle bounds. Only these HTTPS origins may be queried for an
# XMR/USD quote; a compromised/misconfigured price URL pointing anywhere else is
# rejected rather than trusted. Kraken, CoinGecko and Coinbase are the response
# shapes extract_xmr_usd_price already understands.
MONERO_PRICE_ORIGINS = {
    "https://api.kraken.com",
    "https://api.coingecko.com",
    "https://api.coinbase.com",
}
# Independent XMR/USD sources (comma-separated). Two by default so the median-of->=2
# sanity check works from a cold start with no prior persisted quote; MONERO_PRICE_API_URL
# stays supported and is folded in when set.
_MONERO_PRICE_DEFAULT_URLS = (
    "https://api.kraken.com/0/public/Ticker?pair=XMRUSD,"
    "https://api.coingecko.com/api/v3/simple/price?ids=monero&vs_currencies=usd"
)
def _monero_price_source_urls() -> list:
    raw = (os.getenv("MONERO_PRICE_API_URLS", "").strip() or _MONERO_PRICE_DEFAULT_URLS)
    urls = []
    for candidate in raw.split(","):
        candidate = candidate.strip()
        if candidate and candidate not in urls:
            urls.append(candidate)
    if MONERO_PRICE_API_URL and MONERO_PRICE_API_URL not in urls:
        urls.append(MONERO_PRICE_API_URL)
    return urls
MONERO_PRICE_SOURCE_URLS = _monero_price_source_urls()
MONERO_PRICE_MAX_BYTES = 64 * 1024        # M-6/L-10: cap a price-feed response body
MONERO_PRICE_MAX_DEVIATION = Decimal("0.20")  # M-6: reject a quote >20% off the last persisted one
MONERO_RPC_MAX_BYTES = 512 * 1024         # L-10: cap a wallet-RPC response body
MONERO_POLL_CONCURRENCY = 4               # M-4: bounded concurrent wallet-RPC calls, off the event loop
MONERO_POLL_LEASE_MINUTES = 5             # M-4: per-order + whole-sweep lease so polls never double-work
# L-10: keep polling an expired order this long for a LATE payment before it is
# finally retired; any funds seen after expiry are routed to manual_review instead.
try:
    MONERO_LATE_PAYMENT_GRACE_MINUTES = int(os.getenv("MONERO_LATE_PAYMENT_GRACE_MINUTES", "1440"))
