def paypal_link_markers(url: str) -> tuple[str, ...]:
    """Extract opaque product IDs from the configured PayPal URL without hardcoding them."""
    if not url:
        return ()
    try:
        parsed = urllib.parse.urlparse(url)
    except Exception:
        return ()
    candidates = [urllib.parse.unquote(part) for part in parsed.path.split("/")]
    for values in urllib.parse.parse_qs(parsed.query, keep_blank_values=False).values():
        candidates.extend(urllib.parse.unquote(value) for value in values)
    markers = []
    for value in candidates:
        value = value.strip().lower()
        if (
            8 <= len(value) <= 64
            and re.fullmatch(r"[a-z0-9_-]+", value)
            and any(ch.isalpha() for ch in value)
            and any(ch.isdigit() for ch in value)
        ):
            markers.append(value)
    return tuple(dict.fromkeys(markers))

def configured_paypal_markers(variable: str, defaults: str, url: str = "") -> tuple[str, ...]:
    configured = [value.strip().lower() for value in os.getenv(variable, defaults).split(",") if value.strip()]
    return tuple(dict.fromkeys(configured + list(paypal_link_markers(url))))

