def _awg_canary_public_key_from_env() -> str:
    value = str(os.getenv("AWG_CANARY_PUBLIC_KEY", "") or "").strip()
    if not value:
        return ""
    try:
        raw = base64.b64decode(value, validate=True)
    except Exception:
        raw = b""
    if len(raw) != 32:
        logger.error("AWG_CANARY_PUBLIC_KEY is not a 32-byte base64 key; the AWG canary peer is disabled")
        return ""
    return value

AWG_CANARY_PUBLIC_KEY = _awg_canary_public_key_from_env()

def security_event_hash(value: Any) -> str:
    return hmac.new(RATE_LIMIT_SECRET.encode(), str(value or "").encode(), hashlib.sha256).hexdigest()[:16]

_SECURITY_DETAIL_HASH_KEYS = {
    "src_ip", "transport_src_ip", "source_ip", "http_url",
    "http_user_agent", "request_path", "path", "url",
}

def minimize_security_details(value: Any) -> Any:
    """Return a fixed-point copy safe for persistence or outbound email."""
    if isinstance(value, dict):
        minimized = {}
        for raw_key, raw_value in value.items():
            key = str(raw_key)
            if key.endswith(("_hash", "_bucket", "_fingerprint")):
                minimized[key] = raw_value
            elif key in _SECURITY_DETAIL_HASH_KEYS:
                serialized = json.dumps(raw_value, sort_keys=True, default=str, separators=(",", ":"))
                minimized[f"{key}_hash"] = security_event_hash(serialized)
            else:
                minimized[key] = minimize_security_details(raw_value)
        return minimized
    if isinstance(value, list):
        return [minimize_security_details(item) for item in value]
    return value

def security_now_utc() -> datetime:
    return datetime.now(timezone.utc)

def security_time_text(dt_utc: datetime) -> tuple[str, str]:
    utc_text = dt_utc.astimezone(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
    local_text = dt_utc.astimezone(SECURITY_ALERT_TZ).strftime("%Y-%m-%d %H:%M:%S %Z")
    return utc_text, local_text

def security_details_json(details: Optional[dict]) -> str:
    return json.dumps(minimize_security_details(details or {}), sort_keys=True, default=str, indent=2)

def configure_security_events_connection(conn: sqlite3.Connection) -> None:
    conn.execute("PRAGMA busy_timeout=10000")
    journal_mode = conn.execute("PRAGMA journal_mode=WAL").fetchone()[0]
    if str(journal_mode).lower() != "wal":
        raise RuntimeError("security events database refused WAL mode")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA foreign_keys=ON")

def ensure_security_events_db(conn: sqlite3.Connection):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS security_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE,
            observed_at_utc TEXT NOT NULL,
            observed_at_eastern TEXT NOT NULL,
            priority INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            source_ip TEXT,
            source_ip_bucket TEXT,
            request_path TEXT,
            details_hash TEXT,
            details_json TEXT,
            email_status TEXT,
            email_error TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_observed_at ON security_events(observed_at_utc)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_priority_type ON security_events(priority, event_type)")
    # payment_clicks and free_access_events already prove a keyed-hash bucket
    # is sufficient for exact-match investigation without ever retaining the
    # reversible raw address; security_events is the one place that kept
    # both. The retention window (SECURITY_EVENTS_RETENTION_DAYS, longer than
    # the general operational-data policy) stays as-is -- it's the plaintext
    # column, not the duration, that the policy's own security/fraud
    # carve-out doesn't cover. source_ip is kept only as a legacy column for
    # rows written before this fix; new rows never populate it.
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_source ON security_events(source_ip_bucket)")
    cutoff = security_now_utc() - timedelta(days=SECURITY_EVENTS_RETENTION_DAYS)
    conn.execute("DELETE FROM security_events WHERE observed_at_utc < ?", (cutoff.isoformat(),))
    # M-17: idempotently scrub any legacy plaintext source_ip left by rows
    # written before new writes switched to keyed buckets only. Runs in the same
    # transaction as the schema/retention maintenance above; a no-op once clean.
    # The partial index keeps that no-op a lookup instead of a full table
    # scan on every recorded event.
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_security_events_source_plaintext "
        "ON security_events(source_ip) WHERE source_ip IS NOT NULL AND source_ip != ''"
    )
    conn.execute("UPDATE security_events SET source_ip = NULL WHERE source_ip IS NOT NULL AND source_ip != ''")
    os.chmod(SECURITY_EVENTS_DB, 0o600)

def record_security_event(priority: int, event_type: str, source_ip: str, path: str, details: Optional[dict], email_status: str) -> str:
    event_id = hmac.new(
        RATE_LIMIT_SECRET.encode(),
        json.dumps({
            "ts": time.time_ns(),
            "p": priority,
            "event": event_type,
            "source": source_ip,
            "path": path,
            "details": details or {},
        }, sort_keys=True, default=str).encode(),
        hashlib.sha256,
    ).hexdigest()[:32]
    try:
        os.makedirs(os.path.dirname(SECURITY_EVENTS_DB), mode=0o700, exist_ok=True)
        now_utc = security_now_utc()
        utc_text, local_text = security_time_text(now_utc)
        detail_text = security_details_json(details)
        with closing(sqlite3.connect(SECURITY_EVENTS_DB, timeout=10)) as conn:
            configure_security_events_connection(conn)
            with conn:
                ensure_security_events_db(conn)
                conn.execute("""
                    INSERT OR IGNORE INTO security_events (
                        event_id, observed_at_utc, observed_at_eastern, priority, event_type,
                        source_ip, source_ip_bucket, request_path, details_hash, details_json, email_status
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (
                    event_id,
                    now_utc.isoformat(),
                    local_text,
                    int(priority),
                    event_type,
                    None,
                    security_event_hash(source_ip or "unknown"),
                    security_event_hash(path) if path else "",
                    security_event_hash(detail_text),
                    detail_text,
                    email_status,
                ))
    except Exception as exc:
        logger.warning("Security event DB write failed: %s", exc)
    return event_id

def update_security_event_email_status(event_id: str, status: str, error: str = ""):
    if not event_id:
        return
    try:
        with closing(sqlite3.connect(SECURITY_EVENTS_DB, timeout=10)) as conn:
            configure_security_events_connection(conn)
            with conn:
                conn.execute(
                    "UPDATE security_events SET email_status = ?, email_error = ? WHERE event_id = ?",
                    (status, error[:500], event_id),
                )
    except Exception as exc:
        logger.warning("Security event DB email-status update failed: %s", exc)

def format_security_alert_body(priority: int, event_type: str, source_ip: str, path: str, details: Optional[dict], event_id: str) -> str:
    _, local_text = security_time_text(security_now_utc())
    # M-17 CONTRACT, EXTENDED TO THE NOTIFICATION PATH (2026-08-07 audit §3.5).
    # ensure_security_events_db() scrubs security_events.source_ip to NULL and
    # keeps only the keyed bucket, precisely because the raw client address is
    # the one identifier this schema refuses to retain. This email leaves the
    # host through a third-party SMTP relay and lands in a mailbox, so emitting
    # the raw value here exported exactly what the storage layer was written to
    # withhold -- for a Myanmar user on a lossy link, tripping a rate limiter
    # was enough to put their real address into a US relay's logs.
    #
    # The bucket keeps the operator's ability to diagnose: distinct sources
    # still produce distinct strings, so "one source or fifty" is answerable
    # from the mailbox alone. The expression below is character-for-character
    # the one record_security_event() writes into source_ip_bucket, so the
    # value in the email is the value in the row -- if one changes the other
    # must change with it. The raw address stays available on the host via
    # `wins-security-events --source-ip <ip>`, which hashes the operator's
    # query the same way.
    rows = [
        ("Time (ET)", local_text),
        ("Priority", f"P{priority}"),
        ("Event", event_type),
        ("Source bucket", security_event_hash(source_ip or "unknown")),
        ("Path bucket", security_event_hash(path) if path else "n/a"),
        ("Event ID", event_id or "n/a"),
    ]
    lines = [f"{label:<14}: {value}" for label, value in rows]
    lines.append("Details       :")
    lines.append(security_details_json(details))
    return "\n".join(lines)

# Only these immediate TCP peers are permitted to hand us a forwarded-IP
# header (CF-Connecting-IP / X-Real-IP / X-Forwarded-For) that we then trust
# for rate-limiting and security-event attribution. Nginx/cloudflared always
# proxy to this app over loopback, so any request whose *direct* socket peer
# is not loopback did not come through that trusted local proxy and must not
# be allowed to set its own attributed IP via a spoofed header.
TRUSTED_PROXY_NETWORKS = (
    ipaddress.ip_network("127.0.0.1/32"),
    ipaddress.ip_network("::1/128"),
)

def _trusted_forwarded_client_ip(request: Request) -> str:
    client_host = request.client.host if request.client else ""
    try:
        peer = ipaddress.ip_address(client_host)
    except ValueError:
        return ""
    if not any(peer in network for network in TRUSTED_PROXY_NETWORKS):
        return ""
    # M-10: the local nginx overwrites X-Real-IP / X-Forwarded-For /
    # CF-Connecting-IP with the address it resolved itself ($remote_addr, via
    # set_real_ip_from over loopback + the reviewed Cloudflare ranges), so
    # X-Real-IP is nginx's authoritative view of the client and is preferred
    # here. The loopback peer check above -- not nginx merely being the
    # immediate TCP peer -- is what makes any of these headers trustworthy; we
    # never honor an arbitrary client-supplied forwarded header on its own.
    for header in ("x-real-ip", "cf-connecting-ip"):
        candidate = (request.headers.get(header) or "").strip()
        if not candidate:
            continue
        try:
            return str(ipaddress.ip_address(candidate))
        except ValueError:
            continue
    forwarded_for = (request.headers.get("x-forwarded-for") or "").split(",", 1)[0].strip()
    if forwarded_for:
        try:
            return str(ipaddress.ip_address(forwarded_for))
        except ValueError:
            pass
    return ""

def request_origin_ip(request: Optional[Request]) -> str:
    if not request:
        return "unknown"
    return _trusted_forwarded_client_ip(request) or (request.client.host if request.client else "unknown")

def security_alert_exempt(source_ip: str, details: Optional[dict] = None) -> bool:
    candidates = {source_ip or ""}
    for key in ("src_ip", "source_ip", "dest_ip", "destination_ip", "client_ip", "remote_ip"):
        value = (details or {}).get(key)
        if value:
            candidates.add(str(value))
    return bool(candidates & (SECURITY_ALERT_EXEMPT_IPS | SECURITY_ALERT_LOOPBACK_EXEMPT_IPS))

def email_enabled_for_priority(priority: int) -> bool:
    return int(priority) in SECURITY_ALERT_EMAIL_PRIORITIES

def security_alert_text(details: Optional[dict] = None) -> str:
    data = details or {}
    return " ".join(str(data.get(k) or "") for k in ("signature", "category")).lower()

def security_alert_inbound_to_local(details: Optional[dict] = None) -> bool:
    data = details or {}
    dest_ip = str(data.get("dest_ip") or data.get("destination_ip") or "").strip()
    src_ip = str(data.get("src_ip") or data.get("source_ip") or "").strip()
    return bool(dest_ip and dest_ip in SECURITY_ALERT_LOCAL_IPS and src_ip not in SECURITY_ALERT_LOCAL_IPS)

def security_alert_no_record_by_policy(event_type: str, details: Optional[dict] = None) -> bool:
    if event_type != "suricata alert":
        return False
    data = details or {}
    signature_id = str(data.get("signature_id") or "").strip()
    if signature_id and signature_id in SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS:
        return True
    signature_text = security_alert_text(data)
    if any(pattern in signature_text for pattern in SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS):
        return True
    if security_alert_inbound_to_local(data):
        return any(pattern in signature_text for pattern in SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS)
    return False

def security_alert_throttle_identity(priority: int, event_type: str, source_ip: str, details: Optional[dict] = None) -> dict:
    data = details or {}
    signature_text = security_alert_text(data)
    if event_type == "suricata alert":
        family = str(data.get("signature_id") or "")
        if any(marker in signature_text for marker in (
            "/etc/passwd",
            "path traversal",
            "webshell",
            "mirai",
            "exploit",
        )):
            family = "http-exploit-probe"
        return {
            "p": int(priority),
            "event": event_type,
            "family": family,
            "source": source_ip or "unknown",
            "dest": str(data.get("dest_ip") or data.get("destination_ip") or ""),
            "port": str(data.get("dest_port") or ""),
        }
    return {
        "p": int(priority),
        "event": event_type,
        "source": source_ip or "unknown",
        "details": data,
    }

def security_alert_suppressed_by_policy(event_type: str, details: Optional[dict] = None) -> bool:
    data = details or {}
    signature_id = str(data.get("signature_id") or "").strip()
    if signature_id and signature_id in SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS:
        return True
    if event_type != "suricata alert" and "signature" not in data and "category" not in data:
        return False
    signature_text = " ".join(str(data.get(k) or "") for k in ("signature", "category")).lower()
    return any(pattern in signature_text for pattern in SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS)

def _security_alert_budget_state(path: str, now: float, window: float) -> tuple:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            start_text, count_text = handle.read().split()
        start, count = float(start_text), int(count_text)
    except Exception:
        return now, 0
    if now - start >= window or count < 0:
        return now, 0
    return start, count

def _security_alert_prune_state(now: float) -> None:
    try:
        with os.scandir(SECURITY_ALERT_STATE_DIR) as entries:
            for entry in entries:
                if not re.fullmatch(r"[0-9a-f]{16}\.(last|budget)", entry.name):
                    continue
                try:
                    if entry.stat().st_mtime < now - 3600:
                        os.unlink(entry.path)
                except OSError:
                    continue
    except OSError:
        pass

def should_send_security_alert(priority: int, event_type: str, source_ip: str, details: Optional[dict] = None) -> bool:
    os.makedirs(SECURITY_ALERT_STATE_DIR, exist_ok=True)
    key = security_event_hash(json.dumps(
        security_alert_throttle_identity(priority, event_type, source_ip, details),
        sort_keys=True,
        default=str,
    ))
    path = os.path.join(SECURITY_ALERT_STATE_DIR, f"{key}.last")
    window = max(1.0, float(SECURITY_ALERT_THROTTLE_SECONDS))
    budgets = []
    for identity, limit in (
        ({"p": int(priority), "event": event_type, "source": source_ip or "unknown"},
         SECURITY_ALERT_MAX_PER_SOURCE_WINDOW),
        ({"p": int(priority), "event": event_type},
         SECURITY_ALERT_MAX_PER_EVENT_WINDOW),
    ):
        budget_key = security_event_hash(json.dumps(identity, sort_keys=True, default=str))
        budgets.append((os.path.join(SECURITY_ALERT_STATE_DIR, f"{budget_key}.budget"), limit))
    now = time.time()
    with _SECURITY_ALERT_SEND_LOCK:
        try:
            previous = float(open(path, "r", encoding="utf-8").read().strip() or "0") if os.path.exists(path) else 0.0
        except Exception:
            previous = 0.0
        if now - previous < SECURITY_ALERT_THROTTLE_SECONDS:
            return False
        states = [_security_alert_budget_state(budget_path, now, window) for budget_path, _ in budgets]
        if any(count >= limit for (_, count), (_, limit) in zip(states, budgets)):
            return False
        for (budget_path, _), (start, count) in zip(budgets, states):
            with open(budget_path, "w", encoding="utf-8") as f:
                f.write(f"{start} {count + 1}")
        with open(path, "w", encoding="utf-8") as f:
            f.write(str(now))
        if secrets.randbelow(128) == 0:
            _security_alert_prune_state(now)
    return True

def _send_security_alert_email(priority: int, event_type: str, source_ip: str, path: str = "", details: Optional[dict] = None, event_id: str = ""):
    if not (SECURITY_ALERT_EMAIL and SMTP_USER and SMTP_PASS):
        logger.warning("Security alert email skipped because SMTP/security recipient is not configured")
        update_security_event_email_status(event_id, "skipped")
        return
    msg = MIMEText(
        format_security_alert_body(priority, event_type, source_ip, path, details, event_id),
        "plain",
    )
    # Same contract as format_security_alert_body above: the subject line is the
    # part that survives in mailbox indexes, previews and relay logs, so it
    # carries the keyed bucket rather than the raw address. Same expression as
    # record_security_event()'s source_ip_bucket write.
    msg["Subject"] = (
        f"[Wins VPN Security P{priority}] {event_type} "
        f"from source {security_event_hash(source_ip or 'unknown')}"
    )
    msg["From"] = EMAIL_SENDER
    msg["To"] = SECURITY_ALERT_EMAIL
    try:
        with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=20) as server:
            server.ehlo()
            server.starttls(context=ssl.create_default_context())
            server.ehlo()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(msg["From"], [SECURITY_ALERT_EMAIL], msg.as_string())
        update_security_event_email_status(event_id, "sent")
    except Exception as exc:
        update_security_event_email_status(event_id, "failed", str(exc))
        logger.error("Security alert email failed: %s", exc)

def security_alert(priority: int, event_type: str, request: Optional[Request] = None, source_ip: str = "", details: Optional[dict] = None):
    source_ip = source_ip or request_origin_ip(request)
    path = request.url.path if request else ""
    event_details = dict(details or {})
    if request:
        event_details.setdefault("method", request.method)
        ua = request.headers.get("user-agent", "")
        if ua:
            event_details["user_agent_hash"] = security_event_hash(ua)
    if security_alert_no_record_by_policy(event_type, event_details):
        return
    if security_alert_exempt(source_ip, event_details):
        record_security_event(priority, event_type, source_ip, path, event_details, "exempt")
        return
    if security_alert_suppressed_by_policy(event_type, event_details):
        record_security_event(priority, event_type, source_ip, path, event_details, "suppressed")
        return
    if not email_enabled_for_priority(priority):
        record_security_event(priority, event_type, source_ip, path, event_details, "log_only")
        return
    if not should_send_security_alert(priority, event_type, source_ip, event_details):
        record_security_event(priority, event_type, source_ip, path, event_details, "throttled")
        return
    event_id = record_security_event(priority, event_type, source_ip, path, event_details, "queued")
    threading.Thread(
        target=_send_security_alert_email,
        args=(priority, event_type, source_ip, path, event_details, event_id),
        daemon=True,
    ).start()

def alert_failed_login(request: Request, reason: str, account_number: str, detail: str = "Account Inactive or Invalid", status_code: int = 401):
    security_alert(3, "failed app login", request=request, details={
        "reason": reason,
        "account_hash": security_event_hash(normalize_account_number(account_number)),
    })
    raise HTTPException(status_code=status_code, detail=detail)

def mask_id(value: Any) -> str:
    value = str(value or "")
    if len(value) <= 8:
        return "***"
    return f"{value[:4]}...{value[-4:]}"

def key_fingerprint(value: Any) -> str:
    return hashlib.sha256(str(value or "").encode()).hexdigest()[:16]

def normalize_client_platform(platform: Any) -> str:
    value = str(platform or "unknown").strip().lower().replace("-", "_")
    aliases = {
        "darwin": "macos",
        "mac": "macos",
        "mac_os": "macos",
        "osx": "macos",
        "iphone": "ios",
        "ipad": "ios",
        "ipados": "ios",
        "win32": "windows",
        "win64": "windows",
    }
    return aliases.get(value, value or "unknown")[:64]

def winn3_capability_bool(value: Any, name: str) -> bool:
    """Strict boolean for a client capability flag.

    Absent (None) is False: a client that predates the flag sends nothing.
    True and False are accepted as-is. Every other value -- "true", 1, "yes"
    -- is malformed and refused rather than coerced. bool("false") is True,
    which is the silent upgrade this parser exists to prevent.
    """
    if value is None:
        return False
    if isinstance(value, bool):
        return value
    raise Winn3ContractError("client-capability-malformed", [name])


def request_client_capabilities(payload: Any) -> dict[str, bool]:
    return {
        "supports_awg": bool(getattr(payload, "supports_awg", True)),
        "supports_xray": bool(getattr(payload, "supports_xray", True)),
        "supports_split_tunnel": bool(getattr(payload, "supports_split_tunnel", False)),
        "supports_per_app_split_tunnel": bool(getattr(payload, "supports_per_app_split_tunnel", False)),
        "supports_double_vpn": bool(getattr(payload, "supports_double_vpn", True)),
        # Winn Protocol v3. DEFAULT FALSE, and that default is the entire
        # backward-compatibility argument: a client that predates these flags
        # sends neither, so resolve_served_winn_protocol never offers it
        # winn/3 and it is served exactly the winn/1 config it is served today.
        #
        # Not inferred from app_version, deliberately. Shipping the code that
        # understands winn/3 and holding the SPA key that makes a knock verify
        # are separate events, and only the device knows whether the second has
        # happened (lib/winn_protocol_dispatch.dart:229-244). A version check
        # would serve SPA to a keyless client, which fails every connection.
        "supports_winn3": bool(getattr(payload, "supports_winn3", False)),
        "supports_winn3_spa": bool(getattr(payload, "supports_winn3_spa", False)),
        # Standalone v3: this device can consume a SIGNED GATEWAY DESCRIPTOR.
        # Separate from supports_winn3 on purpose. AWG-carried winn/3 and
        # standalone winn/3 are different datapaths with different client code,
        # and a client that has the first is not thereby able to verify an
        # Ed25519 envelope, check a per-node sequence floor and configure an
        # admission key. Inferring one from the other would serve a descriptor
        # to a client that ignores it at best.
        "supports_winn3_descriptor": bool(
            getattr(payload, "supports_winn3_descriptor", False)
        ),
        # Dual-signature attestation keys. DEFAULT FALSE and STRICT. The hub
        # serves auth_ed25519/auth_mldsa65 only to a client that sent this
        # flag as an explicit JSON true. A malformed value is refused, never
        # coerced: bool("false") is True.
        "supports_winn3_dualauth": winn3_capability_bool(
            getattr(payload, "supports_winn3_dualauth", None),
            "supports_winn3_dualauth",
        ),
        # w3r/1 (ciphertext relay Double VPN). Present in the echo ONLY when
        # the client sent true, so the capability map every other client is
        # served is byte for byte what it was. STRICT like dualauth: a
        # non-bool value is malformed and refused, never coerced.
        **(
            {"supports_winn3_relay": True}
            if winn3_capability_bool(
                getattr(payload, "supports_winn3_relay", None),
                "supports_winn3_relay",
            )
            else {}
        ),
    }

APPLE_RELEASE_BLOCKERS = [
    "app_store_metadata_owner_review",
    "app_store_connect_privacy_labels",
    "xcode_privacy_report_review",
    "testflight_or_app_store_upload",
    "app_store_review_submission",
    "macos_app_store_package_install_smoke",
]

def platform_support_metadata(platform: Any = "unknown") -> dict[str, Any]:
    normalized = normalize_client_platform(platform)
    apple = normalized in {"ios", "macos"}
    consumer_per_app = normalized in {"android", "windows", "linux"}
    per_app_scope = (
        "native_os"
        if normalized in {"android", "windows"}
        else "launcher_cgroup"
        if normalized == "linux"
        else "mdm_managed_only"
        if apple
        else "unavailable"
    )
    return {
        "schema_version": 2,
        "platform": normalized,
        "server_managed": True,
        "dynamic_node_config": True,
        "client_key_generation_required": True,
        "legal_acceptance_required": True,
        "capabilities": {
            "direct_awg": True,
            "xray_fallback": True,
            "smart_protocol": True,
            "double_vpn": DOUBLE_VPN_ENABLED,
            "free_access": FREE_ACCESS_ENABLED,
            "split_tunnel": True,
            "destination_split_tunnel": True,
            "per_app_split_tunnel": consumer_per_app,
            "per_app_split_tunnel_scope": per_app_scope,
            "per_app_split_tunnel_requires_launcher": normalized == "linux",
            "per_app_split_tunnel_mdm_only": apple,
        },
        "apple": {
            "applies": apple,
            "production_ready": False,
            "production_ready_reason": (
                "Apple builds remain gated on App Store Connect upload/submission, "
                "final privacy and metadata review, and clean Mac package-install "
                "smoke."
                if apple else "Not an Apple platform."
            ),
            "release_blockers": APPLE_RELEASE_BLOCKERS if apple else [],
            "network_extension_required": apple,
            "packet_tunnel_provider_required": apple,
            "app_group_required": apple,
            "keychain_storage_required": apple,
            "calculator_camouflage_allowed": False,
            "bundle_ids": {
                "ios_app": "org.winsvpn.app",
                "ios_packet_tunnel": "org.winsvpn.app.PacketTunnel",
                "macos_app": "org.winsvpn.app",
                "macos_packet_tunnel": "org.winsvpn.app.PacketTunnel",
            },
        },
        # Backward-compatible fields for public clients built before schema 2.
        "direct_awg_supported": True,
        "xray_fallback_supported": True,
        "double_vpn_supported": True,
        "split_tunnel_supported": True,
        "per_app_split_tunnel_supported": consumer_per_app,
        "per_app_split_tunnel_scope": per_app_scope,
        "packet_tunnel_required": apple,
        "network_extension_required": apple,
        "production_ready": False if apple else True,
        "notes": "Apple clients require App Store submission gates before public release." if apple else "Platform supported by the current public API contract.",
    }

class LoginRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="ignore")
    account_number: str = Field(validation_alias=AliasChoices("account_number", "accountnumber"))
    device_id: str = Field(validation_alias=AliasChoices("device_id", "deviceid"))
    device_fingerprint: str = Field(default="", validation_alias=AliasChoices("device_fingerprint", "devicefingerprint", "hardware_hash", "hardwarehash"))
    device_model: str = Field(default="Android", validation_alias=AliasChoices("device_model", "devicemodel"))
    platform: str = "app"
    app_version: str = Field(default="unknown", validation_alias=AliasChoices("app_version", "appversion"))
    locale: str = "unknown"
    location: str = "auto"
    stealth_mode: bool = Field(default=False, validation_alias=AliasChoices("stealth_mode", "stealthmode"))
    double_vpn: bool = Field(default=False, validation_alias=AliasChoices("double_vpn", "doublevpn", "double_vpn_enabled", "doublevpnenabled"))
    client_public_key: Optional[str] = Field(default=None, validation_alias=AliasChoices("client_public_key", "clientpublickey"))
    # Client-owned winn/3 identity (Fable 5.1 ruling, 2026-09-29, IA-CP-05).
    # The device generates its own X25519 static pair and sends ONLY the
    # public half; the hub stores it beside the inner address and never holds
    # the private half. Absent/None keeps today's behaviour for older builds.
    winn3_static_public: Optional[str] = Field(default=None, validation_alias=AliasChoices("winn3_static_public", "winn3staticpublic"))
    # The build owns its winn/3 key. STRICT like supports_winn3_dualauth: a
    # client that says so is never handed a hub-minted private key, even when
    # it failed to send its public half.
    supports_winn3_client_key: Any = Field(default=None, validation_alias=AliasChoices("supports_winn3_client_key", "supportswinn3clientkey"))
    supports_awg: bool = Field(default=True, validation_alias=AliasChoices("supports_awg", "supportsawg"))
    supports_xray: bool = Field(default=True, validation_alias=AliasChoices("supports_xray", "supportsxray"))
    supports_split_tunnel: bool = Field(default=False, validation_alias=AliasChoices("supports_split_tunnel", "supportssplittunnel"))
    supports_per_app_split_tunnel: bool = Field(default=False, validation_alias=AliasChoices("supports_per_app_split_tunnel", "supportsperappsplittunnel"))
    supports_double_vpn: bool = Field(default=True, validation_alias=AliasChoices("supports_double_vpn", "supportsdoublevpn"))
    # Winn Protocol v3 capability, advertised by the device, DEFAULT FALSE.
    # These models set extra="ignore", so until these two fields existed the
    # hub silently DISCARDED the flags the client already sends -- it could not
    # record a client's v3 capability at all. Default False is what keeps every
    # already-shipped client on winn/1 (see request_client_capabilities).
    supports_winn3: bool = Field(default=False, validation_alias=AliasChoices("supports_winn3", "supportswinn3"))
    supports_winn3_spa: bool = Field(default=False, validation_alias=AliasChoices("supports_winn3_spa", "supportswinn3spa"))
    # Standalone v3 signed gateway descriptor. Same discipline as the two
    # above: DEFAULT FALSE and both wire spellings, so a client that predates
    # the field is served exactly what it is served today.
    supports_winn3_descriptor: bool = Field(default=False, validation_alias=AliasChoices("supports_winn3_descriptor", "supportswinn3descriptor"))
    # Dual-signature attestation. Same discipline: DEFAULT FALSE and both
    # wire spellings. A client that predates the field is served no dual-auth
    # keys. Malformed values are refused in request_client_capabilities, not
    # coerced.
    supports_winn3_dualauth: bool = Field(default=False, validation_alias=AliasChoices("supports_winn3_dualauth", "supportswinn3dualauth"))
    # w3r/1: this device can dial a Core relay endpoint for a Double VPN
    # (winn3_relay). DEFAULT FALSE and both wire spellings, so a client that
    # predates the field is served exactly what it is served today.
    # request_client_capabilities adds the key to the echo only when true.
    supports_winn3_relay: Any = Field(default=False, validation_alias=AliasChoices("supports_winn3_relay", "supportswinn3relay"))
    # Exact Smart Router RequestId: 8-64 [A-Za-z0-9._:-] chars, or absent.
    # Empty is "no generation" (v1 stays unauthorized). Malformed non-empty
    # values are refused at the typed helper, not silently stripped.
    selection_generation: Optional[str] = Field(
        default=None,
        max_length=64,
        pattern=r"^(?:[A-Za-z0-9][A-Za-z0-9._:-]{7,63})?$",
        validation_alias=AliasChoices("selection_generation", "selectiongeneration"),
    )
    ordinary_v3_failure_generation: Optional[str] = Field(
        default=None,
        max_length=64,
        pattern=r"^(?:[A-Za-z0-9][A-Za-z0-9._:-]{7,63})?$",
        validation_alias=AliasChoices("ordinary_v3_failure_generation", "ordinaryv3failuregeneration"),
    )
    free_access: bool = Field(default=False, validation_alias=AliasChoices("free_access", "freeaccess"))
    legal_version: str = Field(default="", validation_alias=AliasChoices("legal_version", "legalversion"))
    legal_hash: str = Field(default="", validation_alias=AliasChoices("legal_hash", "legalhash"))
    accepted_terms: bool = Field(default=False, validation_alias=AliasChoices("accepted_terms", "acceptedterms"))
    accepted_hold_harmless: bool = Field(default=False, validation_alias=AliasChoices("accepted_hold_harmless", "acceptedholdharmless"))
    accepted_limitation_liability: bool = Field(default=False, validation_alias=AliasChoices("accepted_limitation_liability", "acceptedlimitationliability"))
    accepted_electronic_records: bool = Field(default=False, validation_alias=AliasChoices("accepted_electronic_records", "acceptedelectronicrecords"))
    accepted_android_vpn_service_disclosure: bool = False
    android_vpn_service_disclosure_version: str = ""
    android_vpn_service_disclosure_accepted_at: str = ""
    acceptance_method: str = Field(default=LEGAL_ACCEPTANCE_METHOD_DEFAULT, validation_alias=AliasChoices("acceptance_method", "acceptancemethod"))

