    # distinguishable from one that reported and could not prove itself: ""
    # becomes NULL in the row ("never told"), "unprovable" is stored verbatim
    # ("told, cannot prove"). Validated by sanitize_data_plane_code_revision()
    # before it reaches SQL -- see register_node().
    data_plane_code_revision: str = Field(
        default="",
        validation_alias=AliasChoices("data_plane_code_revision", "dataplanecoderevision"),
    )
    endpoint: str
    tunnel_gateway_ipv4: str = Field(default="", validation_alias=AliasChoices("tunnel_gateway_ipv4", "tunnelgatewayipv4"))
    stealth_endpoint: str = Field(default="", validation_alias=AliasChoices("stealth_endpoint", "stealthendpoint"))
    public_key: str = Field(default="", validation_alias=AliasChoices("public_key", "publickey"))
    preshared_key: Optional[str] = Field(default=None, validation_alias=AliasChoices("preshared_key", "presharedkey"))
    # H-2: the only way to obtain (or rotate) this slug's node_token is
    # /api/v1/nodes/bootstrap (grant-gated); secret_token here must always be
    # this slug's own existing node_token. The fleet-wide admin token is
    # never accepted on this routine registration path at all.
    secret_token: str = Field(validation_alias=AliasChoices("secret_token", "secrettoken"))
    status: str = "online"
    obfuscation_json: Optional[str] = Field(default=None, validation_alias=AliasChoices("obfuscation_json", "obfuscationjson"))
    ssh_host: str = Field(default="", validation_alias=AliasChoices("ssh_host", "sshhost"))
    wg_port: int = Field(default=9110, ge=1, le=65535, validation_alias=AliasChoices("wg_port", "wgport"))
    xray_uuid: str = Field(default="", validation_alias=AliasChoices("xray_uuid", "xrayuuid"))
    xray_path: str = Field(default="/wins-stealth-tunnel", validation_alias=AliasChoices("xray_path", "xraypath"))
    xray_security: str = Field(default="none", validation_alias=AliasChoices("xray_security", "xraysecurity"))
    xray_sni: str = Field(default="", validation_alias=AliasChoices("xray_sni", "xraysni"))
    stealth_public_port: int = Field(default=80, ge=1, le=65535, validation_alias=AliasChoices("stealth_public_port", "stealthpublicport"))
    xray_inbound_port: int = Field(default=10085, ge=1, le=65535, validation_alias=AliasChoices("xray_inbound_port", "xrayinboundport"))
    regional_aliases: list[str] = Field(default_factory=list, validation_alias=AliasChoices("regional_aliases", "regionalaliases", "stealth_aliases", "stealthaliases"))
    stealth_transports: list[dict[str, Any]] = Field(default_factory=list, validation_alias=AliasChoices("stealth_transports", "stealthtransports", "xray_transports", "xraytransports"))
    awg_rx_bytes: int = Field(default=0, validation_alias=AliasChoices("awg_rx_bytes", "awgrxbytes"))
    awg_tx_bytes: int = Field(default=0, validation_alias=AliasChoices("awg_tx_bytes", "awgtxbytes"))
    wan_rx_bytes: int = Field(default=0, validation_alias=AliasChoices("wan_rx_bytes", "wanrxbytes"))
    wan_tx_bytes: int = Field(default=0, validation_alias=AliasChoices("wan_tx_bytes", "wantxbytes"))
    peer_count: int = Field(default=0, validation_alias=AliasChoices("peer_count", "peercount"))
    max_peers: int = Field(default=0, ge=0, le=60000, validation_alias=AliasChoices("max_peers", "maxpeers"))
    direct_awg_enabled: Optional[bool] = Field(default=None, validation_alias=AliasChoices("direct_awg_enabled", "directawgenabled"))
    # Lane L85 / Round LD2 load inputs, percentages the node computed. CPU is
    # measured over its own heartbeat interval; load_sessions_pct is ACTIVE USERS
    # on every transport over the node's user capacity (or v3 session slots in
    # use, if larger); load_net_pct exists only when an operator configured a
    # link capacity. Typed Any on purpose: sanitize_node_load_ratio() narrows
    # them, so a malformed value becomes "unknown" instead of a 422 on the
    # heartbeat.
    load_cpu_pct: Any = Field(default=None, validation_alias=AliasChoices("load_cpu_pct", "loadcpupct"))
    load_net_pct: Any = Field(default=None, validation_alias=AliasChoices("load_net_pct", "loadnetpct"))
    load_sessions_pct: Any = Field(default=None, validation_alias=AliasChoices("load_sessions_pct", "loadsessionspct"))
    # SYNC-15/16 (2026-09-29): what this node's winn3-gateway unit actually
    # runs, as wins-node-register parsed it from the unit and its env file.
    # SYNC-22: the node's origin certificate notAfter. Both are REPORTS that
    # change nothing served; typed Any and narrowed by
    # sanitize_winn3_gateway_report() / sanitize_origin_cert_not_after(), so a
    # malformed value is "not reported", never a 422 on the heartbeat.
    winn3_gateway: Any = Field(default=None, validation_alias=AliasChoices("winn3_gateway", "winn3gateway"))
    origin_cert_not_after: Any = Field(default=None, validation_alias=AliasChoices("origin_cert_not_after", "origincertnotafter"))
    # Design 10.2 (P1): the node's read-only performance read-backs (drop
    # deltas, session counts, sysctl floor, queue read-backs, NIC evidence).
    # A REPORT like the two above: typed Any and narrowed by
    # sanitize_performance_report(), so a malformed value is "not reported",
    # never a 422 on the heartbeat. Only the session counts feed a decision
    # (node_v3_sessions_full); the rest is evidence and the drift alert.
    performance: Any = Field(default=None, validation_alias=AliasChoices("performance", "performancereport"))

