@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH, timeout=30)
    try:
        conn.row_factory = sqlite3.Row
        # Switching a not-yet-WAL file into WAL mode needs a brief exclusive
        # lock; busy_timeout (set below, so not yet active on the very first
        # PRAGMA here) doesn't reliably cover that specific lock, so multiple
        # workers/threads opening their first-ever connection to a fresh
        # DB_PATH at the same instant (e.g. several uvicorn workers booting
        # together) can otherwise race and raise "database is locked" here.
        # Once any one connection completes the switch it's persisted in the
        # file header, so a handful of short retries is enough to ride out
        # the one-time settling window; a real, non-transient error still
        # surfaces after the final attempt.
        for attempt in range(5):
            try:
                row = conn.execute("PRAGMA journal_mode=WAL").fetchone()
                if row and str(row[0]).lower() == "wal":
                    break
                if attempt == 4:
                    raise sqlite3.OperationalError(
                        f"PRAGMA journal_mode=WAL returned unexpected mode: {row[0] if row else None}"
                    )
            except sqlite3.OperationalError:
                if attempt == 4:
                    raise
                time.sleep(0.05 * (attempt + 1))
        conn.execute("PRAGMA foreign_keys=ON")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute("PRAGMA busy_timeout=30000")
        yield conn
        conn.commit()
    finally:
        conn.close()

def table_exists(conn: sqlite3.Connection, table: str) -> bool:
    return conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)).fetchone() is not None

def table_columns(conn: sqlite3.Connection, table: str) -> set[str]:
    if not table_exists(conn, table):
        return set()
    return {row["name"] for row in conn.execute(f"PRAGMA table_info({table})").fetchall()}

def add_column_if_missing(conn: sqlite3.Connection, table: str, column: str, ddl: str):
    if column not in table_columns(conn, table):
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {ddl}")

