def nodes_schema_with_dark_start_default(create_sql: str) -> str:
    """Return the live nodes DDL with only its stored latch default changed."""
    header = re.match(
        r"(?is)^(\s*CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?)"
        r"(?:nodes|\"nodes\"|`nodes`|\[nodes\]|'nodes')(\s*\()",
        str(create_sql or ""),
    )
    if not header:
        raise RuntimeError("cannot parse live nodes CREATE TABLE statement")
    open_paren = header.end() - 1
    depth = 0
    quote = ""
    close_paren = -1
    index = open_paren
    while index < len(create_sql):
        character = create_sql[index]
        if quote:
            quote_end = "]" if quote == "[" else quote
            if character == quote_end:
                if quote != "[" and index + 1 < len(create_sql) and create_sql[index + 1] == quote_end:
                    index += 2
                    continue
                quote = ""
        elif character in {"'", '"', "`", "["}:
            quote = character
        elif character == "(":
            depth += 1
        elif character == ")":
            depth -= 1
            if depth == 0:
                close_paren = index
                break
        index += 1
    if close_paren < 0:
        raise RuntimeError("cannot find the end of live nodes CREATE TABLE statement")

    body = create_sql[open_paren + 1:close_paren]
    definitions = []
    start = 0
    depth = 0
    quote = ""
    index = 0
    while index < len(body):
        character = body[index]
        if quote:
            quote_end = "]" if quote == "[" else quote
            if character == quote_end:
                if quote != "[" and index + 1 < len(body) and body[index + 1] == quote_end:
                    index += 2
                    continue
                quote = ""
        elif character in {"'", '"', "`", "["}:
            quote = character
        elif character == "(":
            depth += 1
        elif character == ")":
            depth -= 1
        elif character == "," and depth == 0:
            definitions.append(body[start:index])
            start = index + 1
        index += 1
    definitions.append(body[start:])

    operator_indexes = [
        position for position, definition in enumerate(definitions)
        if re.match(
            r"(?is)^\s*(?:operator_enabled|\"operator_enabled\"|`operator_enabled`|"
            r"\[operator_enabled\]|'operator_enabled')(?:\s|$)",
            definition,
        )
    ]
    if len(operator_indexes) != 1:
        raise RuntimeError("live nodes schema does not contain exactly one operator_enabled column")
    operator_index = operator_indexes[0]
    dark_definition, replacements = re.subn(
        r"(?is)\bDEFAULT\s+(?:\(\s*)?(?:1|'1'|\"1\")(?:\s*\))?",
        "DEFAULT 0",
        definitions[operator_index],
        count=1,
    )
    if replacements != 1:
        raise RuntimeError("unsupported historical operator_enabled default declaration")
    definitions[operator_index] = dark_definition
    return (
        header.group(1)
        + '"nodes_dark_start_migration"'
        + header.group(2)
        + ",".join(definitions)
        + create_sql[close_paren:]
    )

def migrate_nodes_operator_enabled_default(conn: sqlite3.Connection) -> None:
    """Change the historical DEFAULT 1 declaration without trusting old rows.

    SQLite cannot ALTER an existing column default. Rebuild the table under an
    immediate write lock, preserving every known row value and database-owned
    index/trigger, then require a clean foreign-key check before commit. This
    changes what future omitted-column inserts do; registration has its own
    explicit dark-start value and never relies on this migration.
    """
    operator_column = next(
        (row for row in conn.execute("PRAGMA table_info(nodes)") if row["name"] == "operator_enabled"),
        None,
    )
    if operator_column is None or str(operator_column["dflt_value"] or "").strip("()'\" ") == "0":
        return
    if conn.in_transaction:
        raise RuntimeError("cannot migrate nodes.operator_enabled default inside an active transaction")

    foreign_keys_enabled = int(conn.execute("PRAGMA foreign_keys").fetchone()[0]) == 1
    conn.execute("PRAGMA foreign_keys=OFF")
    try:
        conn.execute("BEGIN IMMEDIATE")
        # Another process may have completed the one-time rebuild while this
        # connection waited for the write lock.
        current = next(
            (row for row in conn.execute("PRAGMA table_info(nodes)") if row["name"] == "operator_enabled"),
            None,
        )
        if current is None or str(current["dflt_value"] or "").strip("()'\" ") == "0":
            conn.commit()
            return
        if table_exists(conn, "nodes_dark_start_migration"):
            raise RuntimeError("refusing to overwrite an unexpected nodes migration table")

        schema_row = conn.execute(
            "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'nodes'"
        ).fetchone()
        if not schema_row or not schema_row["sql"]:
            raise RuntimeError("live nodes CREATE TABLE statement is unavailable")
        replacement_sql = nodes_schema_with_dark_start_default(schema_row["sql"])
        owned_objects = conn.execute(
            "SELECT type, name, sql FROM sqlite_master "
            "WHERE tbl_name = 'nodes' AND type IN ('index', 'trigger') "
            "AND sql IS NOT NULL ORDER BY type, name"
        ).fetchall()
        conn.execute(replacement_sql)
        old_columns = table_columns(conn, "nodes")
        new_columns = table_columns(conn, "nodes_dark_start_migration")
        if new_columns != old_columns:
            raise RuntimeError("nodes dark-start migration did not preserve the complete column set")
        copied_columns = [
            row["name"] for row in conn.execute("PRAGMA table_info(nodes)")
        ]
        if "slug" not in copied_columns or "operator_enabled" not in copied_columns:
            raise RuntimeError("nodes dark-start migration cannot preserve required columns")
        quoted_columns = ", ".join(f'"{column}"' for column in copied_columns)
        select_columns = ", ".join(
            "COALESCE(operator_enabled, 0)" if column == "operator_enabled" else f'"{column}"'
            for column in copied_columns
        )
        conn.execute(
            f"INSERT INTO nodes_dark_start_migration ({quoted_columns}) "
            f"SELECT {select_columns} FROM nodes"
        )
        conn.execute("DROP TABLE nodes")
        conn.execute("ALTER TABLE nodes_dark_start_migration RENAME TO nodes")
        for owned_object in owned_objects:
            conn.execute(owned_object["sql"])
        migrated = next(
            row for row in conn.execute("PRAGMA table_info(nodes)")
            if row["name"] == "operator_enabled"
        )
        if str(migrated["dflt_value"] or "").strip("()'\" ") != "0":
            raise RuntimeError("nodes.operator_enabled default migration did not produce DEFAULT 0")
        violations = conn.execute("PRAGMA foreign_key_check").fetchall()
        if violations:
            raise RuntimeError("nodes dark-start migration failed foreign-key validation")
        conn.commit()
        logger.warning(
            "migrated nodes.operator_enabled declaration to DEFAULT 0; existing latch values preserved"
        )
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.execute(f"PRAGMA foreign_keys={'ON' if foreign_keys_enabled else 'OFF'}")

def create_node_retirements_table(conn: sqlite3.Connection):
    # Node retirement tombstone (admin node-retirement lane, 2026-08-07).
    #
    # The register-lane analysis of the deleted-node case
    # (CONTROL_PLANE_REGISTER_IDENTITY_COLLISION_GUARD_20260807.md 4.4) found
    # that a destroyed node row had NO recovery path at all: no undo log, no
    # tombstone, no audit row, and not even a security event. That was the
    # single strongest argument for refusing rather than deleting. Retirement
    # is a deliberate, admin-gated operation, so it is allowed -- but it is
    # only allowed because this table exists first. Every retirement writes
    # one row here BEFORE the nodes row is modified, inside the same
    # transaction, so a retirement that cannot be recorded cannot happen.
    #
    # state_json holds the complete pre-retirement nodes row EXCEPT the two
    # secret columns (node_token_hash, preshared_key) -- see
    # NODE_RETIREMENT_UNRECORDED_COLUMNS. Those two are deliberately left ON
    # the live row and never copied here: retirement is a soft delete, the row
    # keeps them, and duplicating a credential into a second table would
    # extend its lifetime past the thing it authenticates for no gain.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS node_retirements (
            retirement_id TEXT PRIMARY KEY,
            slug TEXT NOT NULL,
            retired_at TEXT NOT NULL,
            reason TEXT,
            was_servable INTEGER DEFAULT 0,
            servable_before INTEGER DEFAULT 0,
            servable_after INTEGER DEFAULT 0,
            last_servable_confirmed INTEGER DEFAULT 0,
            state_json TEXT NOT NULL,
            restored_at TEXT
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_node_retirements_slug ON node_retirements(slug, retired_at)")

def create_node_promotion_events_table(conn: sqlite3.Connection):
    # Durable, secret-free proof that the customer-serving latch was opened by
    # an authenticated operator, never by registration or a heartbeat. The
    # evidence digest binds the action to the separately frozen deployment
    # evidence without copying that evidence (which may contain sensitive host
    # details) into the hub database.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS node_promotion_events (
            promotion_id TEXT PRIMARY KEY,
            slug TEXT NOT NULL,
            promoted_at TEXT NOT NULL,
            tier TEXT NOT NULL,
            evidence_sha256 TEXT NOT NULL,
            operator_source_hash TEXT NOT NULL,
            node_status TEXT NOT NULL,
            management_status TEXT NOT NULL,
            management_checked_at TEXT,
            data_plane_status TEXT NOT NULL,
            data_plane_ok_at TEXT NOT NULL,
            data_plane_code_revision TEXT,
            FOREIGN KEY(slug) REFERENCES nodes(slug)
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_node_promotion_events_slug "
        "ON node_promotion_events(slug, promoted_at)"
    )
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS node_promotion_events_no_update
        BEFORE UPDATE ON node_promotion_events
        BEGIN
            SELECT RAISE(ABORT, 'node promotion evidence is immutable');
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS node_promotion_events_no_delete
        BEFORE DELETE ON node_promotion_events
        BEGIN
            SELECT RAISE(ABORT, 'node promotion evidence is immutable');
        END
    """)

def create_node_latch_events_table(conn: sqlite3.Connection):
    # L84 (Round SC): one row per operator_enabled transition, written by a
    # trigger so that EVERY writer is recorded in the writer's own
    # transaction: the hub, the out-of-process data-plane prober, and any
    # direct SQL. A writer that does not name itself in nodes.latch_cause is
    # recorded as 'unattributed'. Alternating directions always carry
    # different causes, so an unchanged latch_cause means the writer did not
    # set one. The hub drains unalerted rows into security_alert().
    conn.execute("""
        CREATE TABLE IF NOT EXISTS node_latch_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            slug TEXT NOT NULL,
            changed_at TEXT NOT NULL,
            from_value INTEGER NOT NULL,
            to_value INTEGER NOT NULL,
            cause TEXT NOT NULL,
            health_closed_reason TEXT,
            data_plane_status TEXT,
            detail_json TEXT,
            alerted_at TEXT
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_node_latch_events_pending "
        "ON node_latch_events(alerted_at, event_id)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_node_latch_events_slug "
        "ON node_latch_events(slug, changed_at)"
    )
    # L84 turn 2: throttle for "ready except for the off-node gate" notices.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS node_auto_reopen_notices (
            slug TEXT PRIMARY KEY,
            health_closed_at TEXT NOT NULL,
            noticed_at TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS node_latch_events_no_delete
        BEFORE DELETE ON node_latch_events
        BEGIN
            SELECT RAISE(ABORT, 'node latch events are append-only');
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS nodes_operator_enabled_transition
        AFTER UPDATE OF operator_enabled ON nodes
        WHEN COALESCE(OLD.operator_enabled, 0) != COALESCE(NEW.operator_enabled, 0)
        BEGIN
            INSERT INTO node_latch_events (
                slug, changed_at, from_value, to_value, cause,
                health_closed_reason, data_plane_status
            ) VALUES (
                NEW.slug,
                strftime('%Y-%m-%dT%H:%M:%f', 'now'),
                COALESCE(OLD.operator_enabled, 0),
                COALESCE(NEW.operator_enabled, 0),
                CASE
                    WHEN NEW.latch_cause IS NULL OR NEW.latch_cause IS OLD.latch_cause
                    THEN 'unattributed'
                    ELSE NEW.latch_cause
                END,
                NEW.health_closed_reason,
                NEW.data_plane_status
            );
        END
    """)

