def create_core_relay_tables(conn: sqlite3.Connection):
    # w3r/1 (ciphertext relay Double VPN). Two new tables and no ALTER of an
    # existing one: the relay is inert until WINN3_RELAY_ENABLED=1 and a row
    # here is enabled, and dropping both tables restores today's schema.
    #   core_relay_exits   one relay port per (Core, exit). The port is
    #                      allocated once and kept, so the owner's router
    #                      forward never moves.
    #   core_relay_reports the Core's last sanitized relay report.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS core_relay_exits (
            core_id TEXT NOT NULL,
            exit_slug TEXT NOT NULL,
            relay_port INTEGER NOT NULL,
            enabled INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (core_id, exit_slug),
            UNIQUE (core_id, relay_port)
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS core_relay_reports (
            core_id TEXT PRIMARY KEY,
            report_json TEXT NOT NULL,
            reported_at TEXT NOT NULL
        )
    """)

