def create_activation_extra_keys_table(conn: sqlite3.Connection):
    # Setup keys 2..N of an account's key set. Slot 1 is the users-row key
    # (activation_secret_*) that every earlier build reads and writes. An extra
    # key is hashed exactly like slot 1 and carries its own single-use mark and
    # an optional expiry (NULL: valid until used). Deleting the account deletes
    # its keys.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS activation_extra_keys (
            key_id TEXT PRIMARY KEY,
            account_number TEXT NOT NULL REFERENCES users(account_number) ON DELETE CASCADE,
            slot INTEGER NOT NULL CHECK (slot >= 2),
