    """)
    # IA-SYNC SYNC-08: who produced the record. 'operator' (every existing and
    # admin-posted row) or 'hub' (a hub-run check, accepted only for an
    # installer_rerun or fresh_install reopen; see verify_offnode_gate_for_use).
    add_column_if_missing(conn, "node_offnode_gates", "source", "TEXT NOT NULL DEFAULT 'operator'")

