def create_monero_orders_table(conn: sqlite3.Connection):
    # One row per Monero-direct checkout. hub_order_id is the opaque local order
    # reference AND the create_address label; subaddress/subaddress_index are the
    # freshly-minted receive address the poller watches. amount_atomic is the exact
    # piconero owed, locked at the XMR/USD rate in force when the order was created.
    # status walks pending -> settled | expired | manual_review and never moves off a
    # terminal state. lease_until is the M-4 poll claim token; quote_* record the M-6
    # priced XMR/USD rate, its source(s) and timestamp for settlement/incident review.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS monero_orders (
            hub_order_id TEXT PRIMARY KEY,
            subaddress TEXT NOT NULL,
            subaddress_index INTEGER NOT NULL,
            plan_key TEXT NOT NULL,
            amount_atomic INTEGER NOT NULL,
            referral_code TEXT DEFAULT '',
            buyer_email TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'pending',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            expires_at TEXT,
            tx_hash TEXT DEFAULT '',
            lease_until TEXT,
            quote_usd_per_xmr TEXT DEFAULT '',
            quote_source TEXT DEFAULT '',
            quote_at TEXT
        )
    """)

def create_payment_orders_table(conn: sqlite3.Connection):
    # H-1: the hub-owned provenance ledger. One row per create-invoice /
    # create-order call across ALL three providers (BTCPay, PayPal wallet,
    # Monero). Coexists with monero_orders/paypal_events: it does not replace
    # them, it binds each provider settlement back to an order THIS hub created.
    # provider_order_id is the id the provider returns (BTCPay invoice id, PayPal
    # order id, or the minted Monero subaddress) and is UNIQUE so a settlement
    # can claim exactly one order. expected_amount/expected_currency are the
    # SERVER-resolved price locked BEFORE the provider call, so a settlement is
    # granted only when the provider's requested/paid amount matches what the hub
    # itself priced. status walks creating -> pending -> processing -> settled,
    # or -> expired/failed/manual_review; a grant is allowed only after an atomic
    # claim of the matching pending row, so a foreign or underpaid provider
    # settlement can never reach provisioning.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS payment_orders (
            hub_order_id TEXT PRIMARY KEY,
            provider TEXT NOT NULL,
            provider_order_id TEXT UNIQUE,
            plan_key TEXT NOT NULL,
            expected_amount TEXT NOT NULL,
            expected_currency TEXT NOT NULL,
            buyer_email TEXT NOT NULL DEFAULT '',
            referral_code TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL DEFAULT 'creating',
            created_at TEXT NOT NULL,
            settled_at TEXT,
            CHECK (provider IN ('btcpay', 'paypal_wallet', 'monero')),
            CHECK (status IN (
                'creating', 'pending', 'processing', 'settled',
                'expired', 'failed', 'manual_review'
            ))
        )
    """)

def create_payment_order_archive_table(conn: sqlite3.Connection):
    # M-7: cold storage for terminal payment_orders rows purged from the hot
    # table after PAYMENT_ORDER_RETENTION_DAYS. Mirrors payment_orders' columns
    # (plus archived_at) so archiving is a plain INSERT ... SELECT; kept for
    # long-tail late-payment / manual-refund forensics after the hot row is gone.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS payment_order_archive (
            hub_order_id TEXT PRIMARY KEY,
            provider TEXT NOT NULL,
            provider_order_id TEXT,
            plan_key TEXT NOT NULL,
            expected_amount TEXT NOT NULL,
            expected_currency TEXT NOT NULL,
            buyer_email TEXT NOT NULL DEFAULT '',
            referral_code TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            settled_at TEXT,
            archived_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now')),
            promo_code TEXT NOT NULL DEFAULT ''
        )
    """)

def archive_terminal_payment_orders(conn: sqlite3.Connection) -> None:
    # M-7: bound the durable growth of the public order-creation surface. Copy,
    # then delete, only orders in a TRULY terminal state (settled/expired/failed)
    # older than the retention window. manual_review rows are deliberately
    # excluded -- they await human reconciliation -- as are creating/pending/
    # processing rows, so nothing still needed for a late payment or a refund is
    # ever removed. Archive first so a crash between the two statements can only
    # duplicate a row into the archive, never lose one.
    cutoff = (utcnow() - timedelta(days=PAYMENT_ORDER_RETENTION_DAYS)).isoformat()
    conn.execute(
        """
        INSERT OR IGNORE INTO payment_order_archive (
            hub_order_id, provider, provider_order_id, plan_key, expected_amount,
            expected_currency, buyer_email, referral_code, status, created_at, settled_at, promo_code
        )
        SELECT hub_order_id, provider, provider_order_id, plan_key, expected_amount,
               expected_currency, buyer_email, referral_code, status, created_at, settled_at, promo_code
        FROM payment_orders
        WHERE status IN ('settled', 'expired', 'failed') AND created_at < ?
        """,
        (cutoff,),
    )
    conn.execute(
        "DELETE FROM payment_orders WHERE status IN ('settled', 'expired', 'failed') AND created_at < ?",
        (cutoff,),
    )

