def create_account_deletion_tables(conn: sqlite3.Connection):
    # Apple Guideline 5.1.1(v) / Play Data Safety in-app account deletion.
    # A request is an explicit, resumable, cancellable state machine rather
    # than a single destructive call, because the quorum rule needs to hold
    # partial consent across separate requests from separate devices.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS account_deletion_requests (
            request_id TEXT PRIMARY KEY,
            account_number TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            active_device_count INTEGER NOT NULL DEFAULT 0,
            required_confirmations INTEGER NOT NULL DEFAULT 0,
            single_device_path INTEGER NOT NULL DEFAULT 0,
            execute_after TEXT,
            requested_at TEXT NOT NULL,
            resolved_at TEXT,
            resolution TEXT
        )
    """)
    # At most one pending request per account. A partial unique index (rather
    # than UNIQUE(account_number)) keeps resolved history addressable while
    # making a second concurrent request impossible at the storage layer, so
    # two devices racing to open a request cannot create two half-confirmed
    # requests that each sit below quorum forever.
    conn.execute("""
        CREATE UNIQUE INDEX IF NOT EXISTS account_deletion_requests_pending_idx
        ON account_deletion_requests(account_number) WHERE status = 'pending'
    """)
    # One row per (request, confirming device). The composite primary key is
    # the replay defence: a confirmation is not a bearer artefact the client
    # hands back, it is a server-side row the hub writes only after THAT
    # device proved its own scoped device_auth_token. device_binding pins the
    # row to the exact device credential generation that produced it, so a
    # confirmation stops counting if the device is logged out, evicted, or
    # re-enrolled -- otherwise a thief could confirm, log the device out,
    # re-enrol it, and confirm again to manufacture a two-device quorum from
    # one physical device.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS account_deletion_confirmations (
            request_id TEXT NOT NULL,
            device_id TEXT NOT NULL,
            account_number TEXT NOT NULL,
            device_binding TEXT NOT NULL,
            confirmed_at TEXT NOT NULL,
            PRIMARY KEY (request_id, device_id)
        )
    """)
    # Deliberately PII-free: this row must survive the deletion it records,
    # so it stores only one-way hashes of the account number and request id
    # plus non-identifying counters. No account number, email, device id,
    # IP address, or public key is written here.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS account_deletion_audit (
            audit_id TEXT PRIMARY KEY,
            account_ref TEXT NOT NULL,
            request_ref TEXT NOT NULL,
            active_device_count INTEGER DEFAULT 0,
            required_confirmations INTEGER DEFAULT 0,
            confirmations_received INTEGER DEFAULT 0,
            single_device_path INTEGER DEFAULT 0,
            devices_deleted INTEGER DEFAULT 0,
            legal_acceptances_deleted INTEGER DEFAULT 0,
            referral_rows_tombstoned INTEGER DEFAULT 0,
            outcome TEXT,
            completed_at TEXT
        )
    """)

def migrate_legacy_table(conn: sqlite3.Connection, table: str, canonical_col: str, create_func, copy_sql_builder):
    cols = table_columns(conn, table)
    if cols and canonical_col not in cols:
        stamp = utcnow().strftime("%Y%m%d%H%M%S")
        legacy_table = f"{table}_legacy_{stamp}"
        logger.warning("Migrating legacy %s table to canonical snake_case schema; old table saved as %s", table, legacy_table)
        conn.execute(f"ALTER TABLE {table} RENAME TO {legacy_table}")
        create_func(conn)
        conn.execute(copy_sql_builder(legacy_table))

def ensure_unique_winn3_inner_addresses(conn: sqlite3.Connection) -> int:
    """Repair legacy duplicate assignments, then enforce uniqueness in SQLite.

    Every member of a duplicate set is cleared. Choosing an arbitrary winner
    would silently bless one device as the owner of an address that the old
    schema never proved it owned. The X25519 identity is deliberately retained;
    the next capable login allocates a fresh address and republishes the same
    authenticated identity through the gateway registry.
    """
    # Once the unique index exists it enforces this invariant on every write,
    # so the duplicate scan below can only find rows the index already made
    # impossible. ensure_schema runs on ordinary requests; skip the scan.
    if conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='index' "
        "AND name='idx_devices_winn3_inner_v4_unique'"
    ).fetchone():
        return 0
    duplicate_rows = conn.execute(
        "SELECT TRIM(winn3_inner_v4) AS inner_v4 "
        "FROM devices WHERE winn3_inner_v4 IS NOT NULL "
        "AND TRIM(winn3_inner_v4) != '' GROUP BY TRIM(winn3_inner_v4) "
        "HAVING COUNT(*) > 1"
    ).fetchall()
    duplicate_addresses = [str(row["inner_v4"] or "") for row in duplicate_rows]
    cleared = 0
    for inner_v4 in duplicate_addresses:
        cursor = conn.execute(
            "UPDATE devices SET winn3_inner_v4 = NULL "
            "WHERE TRIM(COALESCE(winn3_inner_v4, '')) = ?",
            (inner_v4,),
        )
        cleared += max(int(cursor.rowcount or 0), 0)
    conn.execute(
        "UPDATE devices SET winn3_inner_v4 = TRIM(winn3_inner_v4) "
        "WHERE winn3_inner_v4 IS NOT NULL "
        "AND winn3_inner_v4 != TRIM(winn3_inner_v4)"
    )
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_devices_winn3_inner_v4_unique "
        "ON devices(winn3_inner_v4) WHERE winn3_inner_v4 IS NOT NULL "
        "AND winn3_inner_v4 != ''"
    )
    if cleared:
        logger.warning(
            "cleared %d legacy device rows across %d duplicate Winn3 inner "
            "address set(s); preserved their static identities for safe reallocation",
            cleared, len(duplicate_addresses),
        )
    return cleared


WINN3_STATIC_PUBLIC_UNIQUE_INDEX = "idx_devices_winn3_static_public_unique"


def ensure_unique_winn3_static_publics(conn: sqlite3.Connection) -> bool:
    """Backstop UNIQUE index on devices.winn3_static_public (ruling Q1 review).

    The admission-time check (winn3_static_public_in_use) is the primary
    guard; this index makes a duplicate impossible to COMMIT even on a path
    that re-begins its transaction. It is NEVER forced over existing data: if
    duplicate keys are already stored, they are counted and logged (sets and
    rows, never the key values) and the index is skipped, so the hub keeps
    starting. Unlike inner addresses, nothing is cleared automatically: a
    duplicated static identity needs an operator to decide which device owns
    it. Returns True when the index exists after the call.
    """
    if conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='index' AND name=?",
        (WINN3_STATIC_PUBLIC_UNIQUE_INDEX,),
    ).fetchone():
        return True
    duplicates = conn.execute(
        "SELECT COUNT(*) AS n FROM devices WHERE winn3_static_public IS NOT NULL "
        "AND winn3_static_public != '' GROUP BY winn3_static_public "
        "HAVING COUNT(*) > 1"
    ).fetchall()
    if duplicates:
        logger.error(
            "NOT creating %s: %d winn/3 static public key(s) are stored on "
            "%d device rows in total. The gateway refuses a registry holding a "
            "duplicate; resolve them (keep one owner, NULL the rest) and the "
            "index is created on the next start.",
            WINN3_STATIC_PUBLIC_UNIQUE_INDEX, len(duplicates),
            sum(int(row["n"]) for row in duplicates),
        )
        return False
    conn.execute(
        f"CREATE UNIQUE INDEX IF NOT EXISTS {WINN3_STATIC_PUBLIC_UNIQUE_INDEX} "
        "ON devices(winn3_static_public) WHERE winn3_static_public IS NOT NULL "
        "AND winn3_static_public != ''"
    )
    return True


def winn3_static_public_conflict(exc: Exception) -> bool:
    return "devices.winn3_static_public" in str(exc)


def migrate_legacy_lifetime(conn: sqlite3.Connection, anchor_default: Optional[datetime] = None) -> int:
    anchor_default = anchor_default or now_utc()

    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS users_pre_lifetime_migration_2025
        AS SELECT * FROM users
        """
    )

    rows = conn.execute(
        """
        SELECT account_number, COALESCE(created_at, ?) AS anchor
          FROM users
         WHERE expiration_date IS NULL
            OR expiration_date = ''
            OR UPPER(TRIM(expiration_date)) IN (?, ?, ?)
        """,
        (
            anchor_default.isoformat(timespec="seconds"),
            "LIFETIME ACCESS",
            "LIFETIME",
            "PERPETUAL",
        ),
    ).fetchall()

    migrated = 0
    for row in rows:
        account_number = row["account_number"]
        anchor = row["anchor"]
        anchor_dt = parse_iso_datetime(anchor) or anchor_default
        expiry = serialize_dt(anchor_dt + relativedelta(years=10))
        conn.execute(
            """
            UPDATE users
               SET expiration_date = ?
             WHERE account_number = ?
            """,
            (expiry, account_number),
        )
        migrated += 1

    return migrated


def create_winn3_registry_refresh_table(conn: sqlite3.Connection):
    existed = table_exists(conn, "winn3_registry_refreshes")
    conn.execute("""
        CREATE TABLE IF NOT EXISTS winn3_registry_refreshes (
            node_slug TEXT PRIMARY KEY,
            attempts INTEGER NOT NULL DEFAULT 0,
            next_attempt_at REAL NOT NULL DEFAULT 0
        )
    """)
    for event, records in (
        ("INSERT", ("NEW",)),
        ("DELETE", ("OLD",)),
        ("UPDATE OF location_slug, winn3_static_public, winn3_inner_v4", ("OLD", "NEW")),
    ):
        trigger_name = "winn3_registry_devices_" + event.split()[0].lower()
        statements = []
        for record in records:
            statements.append(f"""
                INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
                SELECT {record}.location_slug, 0, 0
                WHERE COALESCE({record}.winn3_static_public, '') != ''
                  AND COALESCE({record}.location_slug, '') != ''
                ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0;
            """)
        conn.execute(
            f"CREATE TRIGGER IF NOT EXISTS {trigger_name} AFTER {event} ON devices "
            "BEGIN " + " ".join(statements) + " END"
        )
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS winn3_registry_account_authority
        AFTER UPDATE OF status, expiration_date ON users
        BEGIN
            INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
            SELECT DISTINCT location_slug, 0, 0 FROM devices
            WHERE account_number=NEW.account_number
              AND COALESCE(winn3_static_public, '') != ''
              AND COALESCE(location_slug, '') != ''
            ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0;
        END
    """)
    if not existed:
        # Reconcile registered v3 nodes when this durable queue first exists.
        conn.execute("""
            INSERT OR IGNORE INTO winn3_registry_refreshes (node_slug)
            SELECT slug FROM nodes WHERE protocol_version='winn/3' AND slug != ''
        """)


# Winn3 departure grace (lane L17, 2026-09-23; v2 after Round O). A server
# switch made while connected sends its /verify request through the CURRENT
# tunnel. Removing the device from the previous gateway's registry before the
# reply is sent lets that gateway's one-second registry refresh refuse the
# reply and every retry, which strands the phone on a node that no longer
# admits it. Instead, the previous gateway keeps the device's unchanged
# identity for a bounded grace, published as that entry's `not_after`. The
# gateway enforces `not_after` on every packet in both directions and at every
# handshake by itself (peer_registry.go innerForPeer and reloadLocked).
#
# Certified policy (Round O), implemented here and in the authority ledger:
#   * the nominal allowance is WINN3_DEPARTURE_GRACE_SECONDS (120 s), capped by
#     the account expiry represented in the publication, and never 0 (0 means
#     "no expiry" to the gateway). The bound assumes a verified, maintained
#     hub-to-gateway clock-skew bound (WINN3_GATEWAY_CLOCK_SKEW_SECONDS). The
#     ceiling is 120 s: raising it needs a policy amendment, not a constant;
#   * no destination authorization is published if doing so could exceed
#     WINN3_MAX_EFFECTIVE_AUTHORIZATIONS simultaneously effective gateway
#     authorizations for the identity. Pending, stale and uncertain
#     publications count until effective withdrawal or expiry is established
#     (winn3_effective_authorizations);
#   * at most WINN3_DEPARTURE_GRANTS_PER_ACCOUNT_HOUR allowances are charged
#     per account in any rolling 3,600 s. A charge is recorded before the
#     publication that carries it and survives request failure and rollback;
#   * an exhausted budget or capacity rejects the switch with a retryable 503
#     BEFORE any remote authorization changes (winn3_switch_deferral);
#   * device deletion, identity or account change and account deactivation
#     retire database grants in the same transaction (triggers below). A
#     shortened account expiry queues propagation; the grant row is not retired
#     and the next publication caps not_after by the new expiry;
#   * no grant is issued when the request rotates the v3 identity. A grant only
#     re-publishes the device's CURRENT key and address, and only while they
#     still equal the values captured at departure.
WINN3_DEPARTURE_GRACE_SECONDS = 120
WINN3_DEPARTURE_GRACE_CEILING_SECONDS = 120
WINN3_DEPARTURE_GRANTS_PER_ACCOUNT_HOUR = 6
WINN3_DEPARTURE_LEDGER_SECONDS = 3600
WINN3_MAX_EFFECTIVE_AUTHORIZATIONS = 3
# A destination authorization published inside a transaction that can still
# roll back is provisional and finite, then finalized after commit.
WINN3_PROVISIONAL_DESTINATION_SECONDS = 600
# peer_registry.go registryFreshness is 1 s: a replaced file can still be
# answered from the cached snapshot for up to that long after it lands.
WINN3_GATEWAY_REFRESH_SECONDS = 2.0
# Assumed hub-to-gateway clock skew bound. UNVERIFIED on the hub itself; the
# allowance is conditional on it (policy, Round O).
WINN3_GATEWAY_CLOCK_SKEW_SECONDS = 5.0
WINN3_AUTHORITY_LEDGER_RETENTION_SECONDS = 600
# The epoch shared by the main database (system_settings) and the ledger. A
# missing or mismatched epoch is the recovery barrier's trigger (Round O v3).
WINN3_AUTHORITY_EPOCH_SETTING = "winn3_authority_epoch"
# Round O v4. Trust in the two files is held by THIS PROCESS, never by the
# files alone: a restored pair can match itself but cannot know the epoch this
# process last wrote or the highest sequence it recorded. Every process start
# therefore begins in recovery, and a regression observed while running (an
# epoch this process did not write, a ledger behind its high-water sequence)
# re-enters it.
# Round O v6. A detected regression is counted, never merely flagged:
# `regressions` counts every detection, `entered` is the count a recovery
# covered when it was entered (with `recovery_since`, the entry it wrote), and
# `cleared` the count its completion satisfied. A regression detected after an
# entry leaves regressions > entered, which invalidates that recovery until a
# new one is entered, however many ordinary publications follow; completion
# clears only up to its own entry. No wall-clock latch time is involved.
# Round O v7. `covered` maps each node the current recovery entry covered to
# the gateway host it had then. A node outside it (registered winn/3 or named
# by the ledger after the entry), or a covered slug now registered at another
# host, is NEWLY ENCOUNTERED: `node_entries` holds the hub time it was first
# seen and the host it was seen at,
# and until a fenced read-back or confirmed publication made after that time
# has had its refresh allowance, and its charge journal has been read after
# that time (or that time is a full charge window past), it is unknown
# authority and unknown charge history. Neither a recovery_complete marker
# nor an earlier recovery's charge-window wait covers it.
# Round O v8. Ledger evidence is keyed by PHYSICAL GATEWAY as well as slug:
# every publication and read-back records the host it was sent to. A host a
# slug has moved away from is a RETIRED GATEWAY of that slug. It stays a
# separate possible authority and charge-history source, which no
# publication or read-back at the slug's new host can replace. It is released
# only by its own recorded expiry or its own confirmed read-back.
_WINN3_PROCESS_TRUST = {"epoch": "", "high_water": 0, "recovery_since": "",
                        "regressions": 0, "entered": 0, "cleared": 0,
                        "covered": {}, "node_entries": {}}
_WINN3_PROCESS_TRUST_LOCK = threading.Lock()
# Per-node departure-charge journal, written under the same flock as the
# registry and BEFORE it, read back during recovery. Lines are
# "<charge_id> <charged_at> <key_id> <token>"; the token is an HMAC of the key
# id, the account and the charge id under a dedicated hub-only key (Round O
# v5), so the node learns no account identifier.
WINN3_CHARGE_JOURNAL_PATH = "/etc/winn/.winn3-charges.log"
# The journal-token keyring: its own file, never derived from another secret,
# so rotating an unrelated secret cannot orphan charge history. Retired keys
# are kept until every line they signed has aged out of the window.
WINN3_CHARGE_KEYRING_PATH = os.path.join(
    os.path.dirname(os.path.abspath(DB_PATH)), "winn3_charge_keys.json"
)
_WINN3_KEYRING_LOCK = threading.Lock()
WINN3_RECOVERY_OBSERVATIONS_PER_PASS = 16
# The authority ledger is a SEPARATE SQLite file because a publication intent
# must be durable before the remote write, while the admission transaction
# that triggered it still holds the main database's writer lock and may yet
# roll back. It holds public material only: static public keys, inner
# addresses, node slugs, account numbers for the budget, and times.
WINN3_AUTHORITY_LEDGER_PATH = os.path.join(
    os.path.dirname(os.path.abspath(DB_PATH)), "winn3_authority_ledger.db"
)


def winn3_clock() -> float:
    return time.time()


_WINN3_LEDGER_INITIALIZED: set[tuple[str, int, int]] = set()
_WINN3_LEDGER_INIT_LOCK = threading.Lock()


@contextmanager
def winn3_authority_ledger():
    conn = sqlite3.connect(WINN3_AUTHORITY_LEDGER_PATH, timeout=30)
    try:
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=FULL")
        conn.execute("PRAGMA busy_timeout=30000")
        ledger_key = None
        try:
            st = os.stat(WINN3_AUTHORITY_LEDGER_PATH)
            ledger_key = (os.path.realpath(WINN3_AUTHORITY_LEDGER_PATH), int(st.st_dev), int(st.st_ino))
        except OSError:
            ledger_key = None
        if ledger_key is None or ledger_key not in _WINN3_LEDGER_INITIALIZED or not table_exists(conn, "winn3_journal_reads"):
            conn.execute("""
                CREATE TABLE IF NOT EXISTS winn3_publications (
                    seq INTEGER PRIMARY KEY,
                    node_slug TEXT NOT NULL,
                    started_at REAL NOT NULL,
                    outcome TEXT NOT NULL,
                    finished_at REAL
                )
            """)
            if "gateway" not in {row[1] for row in conn.execute("PRAGMA table_info(winn3_publications)")}:
                conn.execute("ALTER TABLE winn3_publications ADD COLUMN gateway TEXT NOT NULL DEFAULT ''")
            # IA-SYNC OI-SYNC_HUB-6: why a publication was refused. 'group_absent'
            # is the node saying it has no winn3-gateway group, before anything was
            # written; a stale-sequence refusal (the node already holds a newer
            # file) keeps ''. Only 'group_absent' lets winn3_recovery_node_set drop
            # a never-v3 node.
            if "refusal" not in {row[1] for row in conn.execute("PRAGMA table_info(winn3_publications)")}:
                conn.execute("ALTER TABLE winn3_publications ADD COLUMN refusal TEXT NOT NULL DEFAULT ''")
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_winn3_publications_node "
                "ON winn3_publications(node_slug, seq)"
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_winn3_publications_gateway "
                "ON winn3_publications(node_slug, gateway, seq)"
            )
            conn.execute("""
                CREATE TABLE IF NOT EXISTS winn3_publication_entries (
                    seq INTEGER NOT NULL,
                    static_public TEXT NOT NULL,
                    inner_v4 TEXT NOT NULL,
                    not_after INTEGER NOT NULL,
                    kind TEXT NOT NULL,
                    PRIMARY KEY (seq, static_public)
                )
            """)
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_winn3_publication_entries_key "
                "ON winn3_publication_entries(static_public, seq)"
            )
            conn.execute("""
                CREATE TABLE IF NOT EXISTS winn3_departure_charges (
                    charge_id TEXT PRIMARY KEY,
                    account_number TEXT NOT NULL,
                    node_slug TEXT NOT NULL,
                    static_public TEXT NOT NULL,
                    charged_at REAL NOT NULL
                )
            """)
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_winn3_departure_charges_account "
                "ON winn3_departure_charges(account_number, charged_at)"
            )
            conn.execute(
                "CREATE TABLE IF NOT EXISTS winn3_ledger_meta "
                "(key TEXT PRIMARY KEY, value TEXT NOT NULL)"
            )
            conn.execute("""
                CREATE TABLE IF NOT EXISTS winn3_observed_charges (
                    charge_id TEXT PRIMARY KEY,
                    node_slug TEXT NOT NULL,
                    charged_at REAL NOT NULL,
                    token TEXT NOT NULL,
                    observed_at REAL NOT NULL,
                    key_id TEXT NOT NULL DEFAULT ''
                )
            """)
            if "key_id" not in {row[1] for row in conn.execute("PRAGMA table_info(winn3_observed_charges)")}:
                conn.execute("ALTER TABLE winn3_observed_charges ADD COLUMN key_id TEXT NOT NULL DEFAULT ''")
            reads = {row[1] for row in conn.execute("PRAGMA table_info(winn3_journal_reads)")}
            if reads and "gateway" not in reads:
                # A read that names no gateway proves nothing about a particular
                # machine; dropping it only asks recovery to read again.
                conn.execute("DROP TABLE winn3_journal_reads")
            conn.execute("""
                CREATE TABLE IF NOT EXISTS winn3_journal_reads (
                    node_slug TEXT NOT NULL,
                    gateway TEXT NOT NULL,
                    recovery_since REAL NOT NULL,
                    read_at REAL NOT NULL,
                    PRIMARY KEY (node_slug, gateway, recovery_since)
                )
            """)
            conn.commit()
            if ledger_key is not None:
                with _WINN3_LEDGER_INIT_LOCK:
                    _WINN3_LEDGER_INITIALIZED.add(ledger_key)
        yield conn
        if conn.in_transaction:
            conn.commit()
    finally:
        conn.close()


def winn3_gateway_of(host) -> str:
    """The physical gateway identity the ledger keys evidence by: the host the
    hub addressed."""
    return str(host or "").strip().lower()


def record_winn3_publication_intent(node_slug: str, document: dict, meta: list,
                                    gateway: str = "") -> int:
    """Durably record a publication BEFORE its remote write can happen.

    Every entry is recorded, with its kind, and every departure allowance it
    carries is charged to its account. The row starts 'uncertain' and stays so
    unless the remote write is acknowledged or provably refused.
    """
    slug = str(node_slug or "").strip().lower()
    now = winn3_clock()
    with winn3_authority_ledger() as ledger:
        ledger.execute("BEGIN IMMEDIATE")
        # Under the ledger's writer lock, BEFORE this row can advance the
        # sequence past a restored ledger: a regression is counted, and the
        # count outlives the sequence this row advances.
        _winn3_note_regression(ledger)
        last = ledger.execute("SELECT COALESCE(MAX(seq), 0) FROM winn3_publications").fetchone()[0]
        floor = ledger.execute(
            "SELECT value FROM winn3_ledger_meta WHERE key='seq_floor'"
        ).fetchone()
        # Monotonic across ledger loss as long as the clock does not step back;
        # a node that refused a stale sequence raises the floor past its own.
        seq = max(int(last) + 1, int(now * 1_000_000), int(floor[0] if floor else 0) + 1)
        ledger.execute(
            "INSERT INTO winn3_publications (seq, node_slug, started_at, outcome, gateway) "
            "VALUES (?, ?, ?, 'uncertain', ?)",
            (seq, slug, now, winn3_gateway_of(gateway)),
        )
        for entry, info in zip(document.get("peers", []), meta):
            ledger.execute(
                "INSERT INTO winn3_publication_entries "
                "(seq, static_public, inner_v4, not_after, kind) VALUES (?, ?, ?, ?, ?)",
                (seq, entry["static_public"], entry["inner_v4"],
                 int(entry["not_after"]), info.get("kind", "live")),
            )
            if info.get("kind") == "departure" and info.get("grant_id"):
                ledger.execute(
                    "INSERT OR IGNORE INTO winn3_departure_charges "
                    "(charge_id, account_number, node_slug, static_public, charged_at) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (info["grant_id"], info.get("account_number") or "", slug,
                     entry["static_public"], now),
                )
        ledger.commit()
    with _WINN3_PROCESS_TRUST_LOCK:
        _WINN3_PROCESS_TRUST["high_water"] = max(_WINN3_PROCESS_TRUST["high_water"], int(seq))
    return seq


def settle_winn3_publication(seq: int, outcome: str, node_seq: int = 0,
                             refusal: str = "") -> None:
    if outcome not in {"confirmed", "refused", "uncertain"}:
        outcome = "uncertain"
    refusal = refusal if outcome == "refused" and refusal in {"group_absent"} else ""
    with winn3_authority_ledger() as ledger:
        ledger.execute(
            "UPDATE winn3_publications SET outcome=?, finished_at=?, refusal=? "
            "WHERE seq=? AND outcome='uncertain'",
            (outcome, winn3_clock(), refusal, int(seq)),
        )
        if node_seq > 0:
            ledger.execute(
                "INSERT INTO winn3_ledger_meta (key, value) VALUES ('seq_floor', ?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value "
                "WHERE CAST(excluded.value AS INTEGER) > CAST(winn3_ledger_meta.value AS INTEGER)",
                (str(int(node_seq)),),
            )


def winn3_effective_authorizations(static_public: str, now: Optional[float] = None,
                                   hosts: Optional[dict] = None) -> dict:
    """Gateways where this identity may still be authorized by a published file.

    Keys are node slugs for the gateway each slug is registered at (or, for a
    slug no longer registered, last published to), and "slug@host" for a
    retired gateway of that slug: a machine the slug has moved away from,
    which a publication or read-back at the new machine never replaces
    (Round O v8). `hosts` is winn3_node_hosts(); it is read if not given.

    Maps each key to the hub time from which the authorization is established
    to have ended: its published not_after plus the skew bound, or, for a file
    that a LATER CONFIRMED publication replaced, that confirmation plus the
    gateway refresh interval. math.inf means "not established". An uncertain
    publication is never treated as replaced by an earlier one, and the remote
    sequence guard in sync_winn3_registry_to_node stops it landing after a
    later confirmed one.
    """
    now = winn3_clock() if now is None else float(now)
    key = str(static_public or "").strip()
    if not key:
        return {}
    if hosts is None:
        with get_db() as conn:
            hosts = winn3_node_hosts(conn)
    with winn3_authority_ledger() as ledger:
        rows = ledger.execute(
            """
            SELECT p.node_slug, p.gateway, p.seq, e.not_after
            FROM winn3_publication_entries e
            JOIN winn3_publications p ON p.seq = e.seq
            WHERE e.static_public = ? AND p.outcome != 'refused'
            """,
            (key,),
        ).fetchall()
        confirmed = {}
        reference = {}
        for slug, gateway in {(row["node_slug"], row["gateway"]) for row in rows}:
            latest = ledger.execute(
                "SELECT seq, finished_at FROM winn3_publications "
                "WHERE node_slug=? AND gateway=? AND outcome='confirmed' ORDER BY seq DESC LIMIT 1",
                (slug, gateway),
            ).fetchone()
            if latest is not None:
                confirmed[(slug, gateway)] = (int(latest["seq"]), float(latest["finished_at"] or 0.0))
            if slug not in reference:
                last = ledger.execute(
                    "SELECT gateway FROM winn3_publications WHERE node_slug=? ORDER BY seq DESC LIMIT 1",
                    (slug,),
                ).fetchone()
                reference[slug] = hosts.get(slug) or (last["gateway"] if last else "")
    effective = {}
    for row in rows:
        slug, gateway = row["node_slug"], row["gateway"]
        not_after = int(row["not_after"])
        relief = math.inf if not_after == 0 else not_after + WINN3_GATEWAY_CLOCK_SKEW_SECONDS
        # Only a later confirmed publication to the SAME gateway replaces it.
        replaced = confirmed.get((slug, gateway))
        if replaced is not None and int(row["seq"]) < replaced[0]:
            relief = min(relief, replaced[1] + WINN3_GATEWAY_REFRESH_SECONDS)
        if relief > now:
            name = slug if gateway == reference.get(slug) else f"{slug}@{gateway}"
            effective[name] = max(effective.get(name, 0.0), relief)
    return effective


def winn3_retired_gateways(ledger, hosts: dict, now: float) -> dict:
    """{(slug, gateway): still_authorizing} for every gateway the ledger names
    for a registered slug other than the host that slug is registered at now.
    `still_authorizing` is True while any entry recorded there may be in
    force: not replaced by a later confirmed publication to that same
    gateway, and not past its not_after plus the skew bound."""
    retired = {}
    for row in ledger.execute(
        "SELECT DISTINCT node_slug, gateway FROM winn3_publications WHERE gateway != ''"
    ).fetchall():
        slug, gateway = row["node_slug"], row["gateway"]
        if slug not in hosts or gateway == hosts[slug]:
            continue
        latest = ledger.execute(
            "SELECT seq, finished_at FROM winn3_publications "
            "WHERE node_slug=? AND gateway=? AND outcome='confirmed' ORDER BY seq DESC LIMIT 1",
            (slug, gateway),
        ).fetchone()
        live = False
        for entry in ledger.execute(
            "SELECT p.seq, e.not_after FROM winn3_publication_entries e "
            "JOIN winn3_publications p ON p.seq = e.seq "
            "WHERE p.node_slug=? AND p.gateway=? AND p.outcome != 'refused'",
            (slug, gateway),
        ).fetchall():
            not_after = int(entry["not_after"])
            relief = math.inf if not_after == 0 else not_after + WINN3_GATEWAY_CLOCK_SKEW_SECONDS
            if latest is not None and int(entry["seq"]) < int(latest["seq"]):
                relief = min(relief, float(latest["finished_at"] or 0.0) + WINN3_GATEWAY_REFRESH_SECONDS)
            if relief > now:
                live = True
                break
        retired[(slug, gateway)] = live
    return retired


def _winn3_write_keyring(ring: dict) -> None:
    path = Path(WINN3_CHARGE_KEYRING_PATH)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.{secrets.token_hex(6)}.tmp")
    try:
        with temporary.open("x", encoding="utf-8") as handle:
            json.dump(ring, handle, sort_keys=True)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary, 0o600)
        os.replace(temporary, path)
        # The rename is durable only once the directory is synced; the hub
        # signs with this key right away, and a lost rename is key loss.
        directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        temporary.unlink(missing_ok=True)


def _winn3_new_charge_key() -> tuple:
    return secrets.token_hex(8), {"key": secrets.token_hex(32), "created_at": winn3_clock(), "retired_at": None}


def winn3_charge_keyring() -> dict:
    """{'active': key_id, 'keys': {key_id: {key, created_at, retired_at}}}.

    A missing keyring is KEY LOSS: a fresh one is created, and every journal
    line signed by a lost key becomes unattributable, which keeps budget trust
    withheld until those lines age out (winn3_recovery_state). An unreadable
    keyring is set aside, never overwritten, and handled the same way.
    """
    with _WINN3_KEYRING_LOCK:
        path = Path(WINN3_CHARGE_KEYRING_PATH)
        try:
            ring = json.loads(path.read_text(encoding="utf-8"))
            keys = ring["keys"]
            if not isinstance(keys, dict) or ring["active"] not in keys or not all(
                re.fullmatch(r"[0-9a-f]{16}", key_id)
                and re.fullmatch(r"[0-9a-f]{64}", str(item.get("key", "")))
                for key_id, item in keys.items()
            ):
                raise ValueError("malformed keyring")
            return ring
        except FileNotFoundError:
            logger.warning("Winn3 charge keyring absent; creating a new one (earlier journal lines become unattributable)")
        except (ValueError, KeyError, TypeError, OSError):
            logger.error("Winn3 charge keyring unreadable; setting it aside and creating a new one")
            try:
                os.replace(path, path.with_name(f"{path.name}.unreadable.{int(winn3_clock())}"))
            except OSError:
                pass
        key_id, item = _winn3_new_charge_key()
        ring = {"active": key_id, "keys": {key_id: item}}
        _winn3_write_keyring(ring)
        return ring


def rotate_winn3_charge_key() -> str:
    """Start signing with a new key; keep retired ones until their lines have
    aged out of the window plus retention, then drop them."""
    ring = winn3_charge_keyring()
    with _WINN3_KEYRING_LOCK:
        now = winn3_clock()
        ring["keys"][ring["active"]]["retired_at"] = now
        key_id, item = _winn3_new_charge_key()
        ring["keys"][key_id] = item
        ring["active"] = key_id
        keep_after = now - WINN3_DEPARTURE_LEDGER_SECONDS - WINN3_AUTHORITY_LEDGER_RETENTION_SECONDS
        ring["keys"] = {
            kid: value for kid, value in ring["keys"].items()
            if value.get("retired_at") is None or float(value["retired_at"]) > keep_after
        }
        _winn3_write_keyring(ring)
    return key_id


def winn3_charge_token(key_id: str, key_hex: str, account_number: str, charge_id: str) -> str:
    """Opaque per-charge attribution written to the node journal. Without the
    hub's key the node cannot tell which account, or whether two charges are
    the same account's."""
    return hmac.new(
        bytes.fromhex(key_hex), f"{key_id}:{account_number}:{charge_id}".encode(), hashlib.sha256
    ).hexdigest()[:32]


def winn3_departure_charges_in_window(account_number: str, now: Optional[float] = None) -> list:
    """Charge times for this account in the rolling window: the ledger's own
    records plus charges read back from node journals during recovery."""
    now = winn3_clock() if now is None else float(now)
    horizon = now - WINN3_DEPARTURE_LEDGER_SECONDS
    charges = {}
    with winn3_authority_ledger() as ledger:
        for row in ledger.execute(
            "SELECT charge_id, charged_at FROM winn3_departure_charges "
            "WHERE account_number=? AND charged_at>?",
            (account_number, horizon),
        ):
            charges[row["charge_id"]] = float(row["charged_at"])
        rows = ledger.execute(
            "SELECT charge_id, charged_at, key_id, token FROM winn3_observed_charges "
            "WHERE charged_at>?",
            (horizon,),
        ).fetchall()
    keys = winn3_charge_keyring()["keys"] if rows else {}
    for row in rows:
        item = keys.get(str(row["key_id"] or ""))
        if item is None:
            continue  # unattributable: winn3_recovery_state withholds trust
        if hmac.compare_digest(
            str(row["token"]),
            winn3_charge_token(row["key_id"], item["key"], account_number, row["charge_id"]),
        ):
            charges.setdefault(row["charge_id"], float(row["charged_at"]))
    return sorted(charges.values())


def winn3_switch_deferral(
    conn: sqlite3.Connection,
    *,
    identity: dict,
    destination_slug: str,
    current_slug: str,
    departing: bool,
):
    """(deferral, allowance) for publishing `identity` at a new destination.

    `deferral` is None when publication may proceed, else (error_code, detail,
    retry_after). `allowance` says whether a departure allowance may be issued
    at the node being left. Runs under the admission writer lock and before
    ANY remote authorization of this request (AWG or v3), so a deferral leaves
    every gateway as it was and the current tunnel keeps working.

    Unknown authority is not capacity: during recovery every node that has not
    been re-established counts as authorizing the identity. Unknown charge
    history is not budget: a switch that needs a departure allowance is
    deferred until every recovery node's charge journal has been read back or
    every potentially missing charge is outside the rolling window.
    """
    detail = "Server switch deferred while the previous server releases this device. Please retry shortly."
    now = winn3_clock()
    destination = str(destination_slug or "").strip().lower()
    current = str(current_slug or "").strip().lower()
    try:
        recovery = winn3_recovery_state(conn, now)
        effective = winn3_effective_authorizations(
            identity["static_public"], now, winn3_node_hosts(conn))
        for row in conn.execute(
            "SELECT node_slug, expires_at FROM winn3_departure_grants "
            "WHERE device_id=? AND static_public=? AND expires_at>?",
            (identity["device_id"], identity["static_public"], now),
        ).fetchall():
            relief = float(row["expires_at"]) + WINN3_GATEWAY_CLOCK_SKEW_SECONDS
            effective[row["node_slug"]] = max(effective.get(row["node_slug"], 0.0), relief)
        if current:
            effective[current] = math.inf
        known = set(effective) | {destination}
        for slug in recovery["unrecovered"]:
            effective[slug] = math.inf
        after = set(effective) | {destination}
        if len(after) > int(WINN3_MAX_EFFECTIVE_AUTHORIZATIONS):
            if len(known) <= int(WINN3_MAX_EFFECTIVE_AUTHORIZATIONS):
                return (("winn3_switch_deferred_recovery", detail, 60), False)
            releasable = [
                relief for slug, relief in effective.items()
                if slug not in {destination, current} and relief != math.inf
            ]
            wait = math.ceil(min(releasable) - now) if releasable else 60
            return (("winn3_switch_deferred_capacity", detail, max(1, min(int(wait), 900))), False)
        # An explicitly disabled grace is a configuration: the switch removes
        # immediately. Missing charge history is not: an unchanged identity
        # that needs an allowance is deferred until history is trusted again.
        allowance = departing and winn3_departure_grace_seconds() > 0
        if allowance and not recovery["budget_trusted"]:
            wait = recovery["budget_trusted_after"] - now
            return (("winn3_switch_deferred_budget", detail,
                     max(1, min(int(math.ceil(wait)) if wait != math.inf else 60, 60))), False)
        if allowance:
            charges = winn3_departure_charges_in_window(identity["account_number"], now)
            budget = max(0, int(WINN3_DEPARTURE_GRANTS_PER_ACCOUNT_HOUR))
            if len(charges) >= budget:
                ages_out = charges[len(charges) - budget] if budget else now + 60
                wait = math.ceil(ages_out + WINN3_DEPARTURE_LEDGER_SECONDS - now) if budget else 60
                return (("winn3_switch_deferred_budget", detail, max(1, min(int(wait), 3600))), False)
    except Exception as exc:
        # An unreadable ledger cannot bound anything: defer, never publish.
        logger.warning("Winn3 switch deferred: authority ledger unavailable (%s)", type(exc).__name__)
        return (("winn3_switch_deferred_capacity", detail, 60), False)
    return (None, allowance)


def winn3_ledger_meta(ledger) -> dict:
    return {row["key"]: row["value"] for row in ledger.execute(
        "SELECT key, value FROM winn3_ledger_meta")}


def winn3_recovery_node_set(conn: sqlite3.Connection, ledger) -> set:
    """Every node that may hold v3 authority this ledger does not account for:
    each node registered winn/3 (retired or not) and each node the ledger has
    ever named."""
    nodes = {
        str(row["slug"]).strip().lower()
        for row in conn.execute(
            "SELECT slug FROM nodes WHERE protocol_version='winn/3' AND slug != ''"
        )
    }
    nodes.update(
        str(row["node_slug"]).strip().lower()
        for row in ledger.execute("SELECT DISTINCT node_slug FROM winn3_publications")
    )
    nodes -= winn3_proven_unwritten_slugs(conn, ledger)
    nodes.discard("")
    return nodes


def winn3_proven_unwritten_slugs(conn: sqlite3.Connection, ledger) -> set:
    """IA-SYNC OI-SYNC_HUB-6 (round 3): slugs that hold no v3 authority although
    the ledger names them. All of these must hold:
      * the node row exists, is not winn/3 and holds no stored descriptor;
      * the ledger has no confirmed publication or read-back for the slug
        (compared as LOWER(TRIM(node_slug))), so the hub never knew it to
        hold anything;
      * the LATEST ledger row for the slug, by seq, is refused with
        refusal='group_absent': at the most recent contact the node had no
        winn3-gateway group, so no gateway can be running there (the unit runs
        as Group=winn3-gateway) and nothing was written.
    One transient failure (an ssh timeout, a crash, a lost ack) therefore
    keeps the slug in only until the next group-absent contact. Used for the
    current set AND to prune saved recovery membership, so an excluded slug
    can never keep recovery incomplete. An operator's waiver of a lost, closed
    node (winn3_waive_recovery_node) is returned with them."""
    latest = {}
    confirmed = set()
    for row in ledger.execute(
        "SELECT LOWER(TRIM(node_slug)) AS slug, seq, outcome, refusal FROM winn3_publications "
        "ORDER BY seq"
    ):
        slug = str(row["slug"] or "")
        latest[slug] = (str(row["outcome"] or ""), str(row["refusal"] or ""))
        if row["outcome"] == "confirmed":
            confirmed.add(slug)
    proven = set()
    for row in conn.execute(
        "SELECT slug, protocol_version, winn3_descriptor_json FROM nodes WHERE slug != ''"
    ):
        slug = str(row["slug"]).strip().lower()
        if slug in confirmed or latest.get(slug) != ("refused", "group_absent"):
            continue
        if str(row["protocol_version"] or "").strip().lower() == "winn/3":
            continue
        if str(row["winn3_descriptor_json"] or "").strip():
            continue
        proven.add(slug)
    return proven | winn3_recovery_waived_slugs(conn, ledger)


def winn3_slug_authority_in_force(ledger, slug: str, now: float) -> bool:
    """True while a gateway holding a file the ledger recorded for `slug`, at any
    of its gateways, could still honour one of its entries: the publication was
    not refused, the entry is not past its not_after plus the skew bound (a
    not_after of 0 never lapses), and no later confirmed publication to the same
    gateway has replaced it and had its refresh interval (the rule of
    winn3_retired_gateways). The hub's own canary binding is not customer
    authority and does not count, whether it was published (kind 'canary') or
    read back from the node ('observed', which records every entry it finds)."""
    try:
        canary_keys = winn3_canary_reserved_publics()
    except Exception:  # fail closed: an unreadable canary config excuses nothing
        canary_keys = set()
    latest = {}
    for row in ledger.execute(
        "SELECT gateway, seq, finished_at FROM winn3_publications "
        "WHERE node_slug=? AND outcome='confirmed' ORDER BY seq", (slug,)
    ):
        latest[row["gateway"]] = (int(row["seq"]), float(row["finished_at"] or 0.0))
    for entry in ledger.execute(
        "SELECT p.gateway, p.seq, e.static_public, e.not_after FROM winn3_publication_entries e "
        "JOIN winn3_publications p ON p.seq = e.seq "
        "WHERE p.node_slug=? AND p.outcome != 'refused' AND e.kind != 'canary'", (slug,)
    ):
        if entry["static_public"] in canary_keys:
            continue
        not_after = int(entry["not_after"])
        relief = math.inf if not_after == 0 else not_after + WINN3_GATEWAY_CLOCK_SKEW_SECONDS
        replaced = latest.get(entry["gateway"])
        if replaced is not None and int(entry["seq"]) < replaced[0]:
            relief = min(relief, replaced[1] + WINN3_GATEWAY_REFRESH_SECONDS)
        if relief > now:
            return True
    return False


def winn3_recovery_waived_slugs(conn: sqlite3.Connection, ledger) -> set:
    """Slugs an operator took out of authority recovery (winn3_waive_recovery_node),
    kept only while the evidence behind the waiver holds: the node row is still
    closed or gone and still at the gateway named when it was granted, the ledger
    still shows nothing of the slug in force, and the slug has no retired
    gateway. A waiver the evidence no longer supports simply
    stops applying, and maintain_winn3_authority_epoch drops them all when a new
    recovery is entered."""
    row = ledger.execute(
        "SELECT value FROM winn3_ledger_meta WHERE key='recovery_waived'").fetchone()
    if row is None:
        return set()
    try:
        recorded = json.loads(row["value"])
    except ValueError:
        return set()
    if not isinstance(recorded, dict) or not recorded:
        return set()
    now = winn3_clock()
    retired = {pair[0] for pair in winn3_retired_gateways(ledger, winn3_node_hosts(conn), now)}
    hosts = winn3_recovery_hosts(conn)
    waived = set()
    for name, record in recorded.items():
        slug = str(name).strip().lower()
        node = conn.execute("SELECT operator_enabled FROM nodes WHERE slug=?", (slug,)).fetchone()
        if node is not None and int(node["operator_enabled"] or 0) != 0:
            continue
        # The waiver is for the machine named when it was granted. A slug now
        # registered at another host is another machine with its own recovery,
        # whether or not the ledger names the old one.
        if node is not None and (
                not isinstance(record, dict) or str(record.get("gateway") or "") != hosts.get(slug, "")):
            continue
        if slug in retired or winn3_slug_authority_in_force(ledger, slug, now):
            continue
        waived.add(slug)
    return waived


def _winn3_node_recovered(ledger, slug: str, since: float, now: float,
                          gateway: Optional[str] = None) -> bool:
    # A confirmed publication made after recovery began replaces whatever the
    # node held. The remote sequence guard stops any older write landing after
    # it, and the refresh allowance covers the gateway's cached snapshot.
    # With `gateway`, only evidence from that physical gateway counts.
    if gateway is None:
        row = ledger.execute(
            "SELECT 1 FROM winn3_publications WHERE node_slug=? AND outcome='confirmed' "
            "AND started_at>=? AND finished_at<=? LIMIT 1",
            (slug, since, now - WINN3_GATEWAY_REFRESH_SECONDS),
        ).fetchone()
    else:
        row = ledger.execute(
            "SELECT 1 FROM winn3_publications WHERE node_slug=? AND gateway=? "
            "AND outcome='confirmed' AND started_at>=? AND finished_at<=? LIMIT 1",
            (slug, gateway, since, now - WINN3_GATEWAY_REFRESH_SECONDS),
        ).fetchone()
    return row is not None


def _winn3_note_regression(ledger, main_epoch: Optional[str] = None) -> bool:
    """Count a regression if the files have regressed under this process.

    Called under the ledger's writer lock by every sequence-advancing write,
    and by every trust check. EVERY detection is counted, including one made
    while an earlier regression is still unrecovered, so a later regression
    can never shelter behind an earlier recovery. Only a recovery entered
    after the detection covers it (maintain_winn3_authority_epoch); ordinary
    publications cannot, however far they advance the sequence.

    The ledger is read and compared while holding the process lock, which
    the recovery entry also holds across its commit, so each detection falls
    wholly before an entry (and is covered by it) or wholly after it (and
    invalidates it); neither side can see the other half-applied.
    """
    with _WINN3_PROCESS_TRUST_LOCK:
        mine = _WINN3_PROCESS_TRUST["epoch"]
        if not mine:
            return False  # not yet trusted at all: nothing to conceal
        meta = winn3_ledger_meta(ledger)
        top = ledger.execute("SELECT COALESCE(MAX(seq), 0) FROM winn3_publications").fetchone()[0]
        regressed = (
            meta.get("epoch", "") != mine
            or (main_epoch is not None and main_epoch != mine)
            or int(top) < int(_WINN3_PROCESS_TRUST["high_water"])
            or str(meta.get("recovery_since") or "") != _WINN3_PROCESS_TRUST["recovery_since"]
        )
        if regressed:
            _WINN3_PROCESS_TRUST["regressions"] += 1
            logger.error(
                "Winn3 authority ledger regressed under the running hub (detection %d); "
                "recovery required", _WINN3_PROCESS_TRUST["regressions"])
        return regressed


def _winn3_trust_broken(main_epoch: str, meta: dict, ledger) -> bool:
    """True when this process cannot vouch for the pair: it has not recovered
    since it started, the files carry an epoch it did not write last, the
    ledger is behind the highest sequence it recorded, or a regression has
    been detected since the current recovery was entered."""
    regressed = _winn3_note_regression(ledger, main_epoch)
    with _WINN3_PROCESS_TRUST_LOCK:
        mine = _WINN3_PROCESS_TRUST["epoch"]
        uncovered = _WINN3_PROCESS_TRUST["regressions"] > _WINN3_PROCESS_TRUST["entered"]
    ledger_epoch = meta.get("epoch", "")
    if not main_epoch or not mine or main_epoch != ledger_epoch or ledger_epoch != mine or regressed:
        return True
    return uncovered


def winn3_node_hosts(conn: sqlite3.Connection) -> dict:
    """The gateway host each registered winn/3 node slug points at."""
    return {
        str(row["slug"]).strip().lower(): winn3_gateway_of(
            row["ssh_host"] or extract_node_host(row["endpoint"] or ""))
        for row in conn.execute(
            "SELECT slug, ssh_host, endpoint FROM nodes WHERE protocol_version='winn/3' AND slug != ''"
        )
    }


def winn3_recovery_hosts(conn: sqlite3.Connection) -> dict:
    """The gateway host every registered node slug points at, whatever its
    carrier: the host its own publications and read-backs are recorded
    against (sync_winn3_registry_to_node, observe_winn3_node).

    HL-F2: the recovery set (winn3_recovery_node_set) holds every slug the
    ledger names, a released node not yet flipped to winn/3 included. Matching
    such a node's own evidence through winn3_node_hosts, which maps winn/3
    rows only, made its needed journal read (slug, "") and its new-node
    barrier host "", which no read-back can ever match. Retired gateways and
    effective authorizations keep winn3_node_hosts."""
    return {
        str(row["slug"]).strip().lower(): winn3_gateway_of(
            row["ssh_host"] or extract_node_host(row["endpoint"] or ""))
        for row in conn.execute("SELECT slug, ssh_host, endpoint FROM nodes WHERE slug != ''")
    }


def _winn3_new_node_barrier(ledger, nodes: set, hosts: dict, since: float, now: float):
    """(authority_unknown, charges_unknown, charges_known_after) for nodes this
    recovery's entry did not cover (Round O v7). Every call records the first
    sighting of each such node, or of a covered slug now registered at another
    host (a different gateway); the sighting is its own recovery entry, and
    nothing recorded before it counts as evidence for that node."""
    with _WINN3_PROCESS_TRUST_LOCK:
        covered = _WINN3_PROCESS_TRUST["covered"]
        entries = _WINN3_PROCESS_TRUST["node_entries"]
        for slug in nodes:
            host = hosts.get(slug, "")
            moved = slug in covered and bool(host) and covered[slug] != host
            if slug not in covered or moved:
                if slug not in entries or (host and entries[slug][1] != host):
                    entries[slug] = (now, host)
        pending = {slug: entries[slug] for slug in nodes if slug in entries}
    authority, charges, after = set(), set(), -math.inf
    for slug, (seen, host) in pending.items():
        if not _winn3_node_recovered(ledger, slug, seen, now, host):
            authority.add(slug)
        journal = ledger.execute(
            "SELECT 1 FROM winn3_journal_reads WHERE node_slug=? AND gateway=? "
            "AND recovery_since=? AND read_at>=? LIMIT 1",
            (slug, host, since, seen),
        ).fetchone()
        if journal is None and now < seen + WINN3_DEPARTURE_LEDGER_SECONDS:
            charges.add(slug)
            after = max(after, seen + WINN3_DEPARTURE_LEDGER_SECONDS)
    return authority, charges, after


def winn3_recovery_state(conn: sqlite3.Connection, now: Optional[float] = None) -> dict:
    """Read-only view of the authority-recovery barrier.

    `paired` is False until THIS PROCESS has entered recovery (every start
    does), and again whenever the files regress under it. Then nothing the
    ledger lacks can be ruled out: every recovery node is unknown and counted,
    and charge history is untrusted. Once paired, a recovery node stays
    unknown and counted until a confirmed publication or a fenced read-back
    of it, made after recovery began, has had its refresh allowance. Charge
    history is trusted again once every recovery node's journal has been read
    back in this recovery, or once every potentially missing charge is outside
    the rolling window.
    """
    now = winn3_clock() if now is None else float(now)
    main_epoch = get_setting(conn, WINN3_AUTHORITY_EPOCH_SETTING, "")
    hosts = winn3_node_hosts(conn)
    own_hosts = winn3_recovery_hosts(conn)  # HL-F2
    with winn3_authority_ledger() as ledger:
        meta = winn3_ledger_meta(ledger)
        nodes = winn3_recovery_node_set(conn, ledger)
        retired = winn3_retired_gateways(ledger, hosts, now)
        if _winn3_trust_broken(main_epoch, meta, ledger):
            # Every retired gateway is as unknown as every node.
            return {"paired": False, "complete": False,
                    "unrecovered": nodes | {f"{s}@{g}" for s, g in retired},
                    "budget_trusted": False, "budget_trusted_after": math.inf,
                    "retired_pending": set(retired)}
        since = float(meta.get("recovery_since") or math.inf)
        try:
            recovery_nodes = set(json.loads(meta.get("recovery_nodes") or "[]")) | nodes
        except ValueError:
            recovery_nodes = nodes
        # OI-SYNC_HUB-6 (round 3): saved membership loses a slug as soon as
        # current evidence proves it never held authority.
        recovery_nodes -= winn3_proven_unwritten_slugs(conn, ledger)
        read = {
            (row["node_slug"], row["gateway"]) for row in ledger.execute(
                "SELECT node_slug, gateway FROM winn3_journal_reads WHERE recovery_since=?", (since,))
        }
        # Budget history needs every machine a recovery slug may have used:
        # its current gateway and each retired gateway the ledger names.
        # FINAL4 F4-HL: whatever the slug's carrier now. A slug that is not
        # winn/3 (released before its flip, or rolled back) may have left a
        # machine whose journal holds charges; that machine counts on its own
        # (Round O v8) and is read back at its own host below. Authority
        # recovery keeps the winn/3-only retired set (fix_hl).
        budget_retired = winn3_retired_gateways(ledger, own_hosts, now)
        # A waived node (winn3_waive_recovery_node) leaves authority recovery,
        # not the charge window: its journal cannot be read, so budget trust
        # waits for the window exactly as it did.
        budget_nodes = recovery_nodes | winn3_recovery_waived_slugs(conn, ledger)
        journals_needed = {(slug, own_hosts.get(slug, "")) for slug in budget_nodes} | {
            pair for pair in budget_retired if pair[0] in budget_nodes
        }
        trusted_after = float(meta.get("budget_trusted_after") or math.inf)
        observed = ledger.execute(
            "SELECT o.key_id, o.charged_at FROM winn3_observed_charges o "
            "WHERE o.charged_at>? AND NOT EXISTS ("
            "SELECT 1 FROM winn3_departure_charges c WHERE c.charge_id=o.charge_id)",
            (now - WINN3_DEPARTURE_LEDGER_SECONDS,),
        ).fetchall()
    # A read journal proves the reads, not the attribution: a charge signed by
    # a key this hub no longer holds (loss, restore of an older keyring, or a
    # legacy line) may be anyone's, so trust waits until it has aged out.
    keys = winn3_charge_keyring()["keys"] if observed else {}
    unattributable = [
        float(row["charged_at"]) for row in observed if str(row["key_id"] or "") not in keys
    ]
    attribution_ok_after = (
        max(unattributable) + WINN3_DEPARTURE_LEDGER_SECONDS if unattributable else -math.inf
    )
    journals_ok = journals_needed <= read and now >= attribution_ok_after
    budget_trusted = now >= trusted_after or journals_ok
    budget_trusted_after = now if budget_trusted else (
        min(trusted_after, attribution_ok_after) if journals_needed <= read else trusted_after
    )
    with winn3_authority_ledger() as ledger:
        if meta.get("recovery_complete") == "1":
            unrecovered = set()
            unknown_retired = set()
        else:
            unrecovered = {
                slug for slug in recovery_nodes
                if not _winn3_node_recovered(ledger, slug, since, now, hosts.get(slug))
            }
            # A retired gateway's recorded state may predate a restore: it is
            # unknown until read back in this recovery.
            unknown_retired = {
                pair for pair in retired
                if not _winn3_node_recovered(ledger, pair[0], since, now, pair[1])
            }
        # A node first seen after the entry is counted and its charges are
        # withheld whatever the marker or the entry's own wait says.
        new_authority, new_charges, new_after = _winn3_new_node_barrier(
            ledger, nodes, own_hosts, since, now)
    unrecovered |= new_authority | {f"{s}@{g}" for s, g in unknown_retired}
    if new_charges:
        budget_trusted = False
        budget_trusted_after = max(budget_trusted_after, new_after)
    # Retired gateways worth reading back: unknown, still authorizing by the
    # record, or owed a journal read while budget history is untrusted.
    retired_pending = {
        pair for pair, live in retired.items()
        if pair in unknown_retired or live or (not budget_trusted and pair not in read)
    }
    if not budget_trusted:
        # FINAL4 F4-HL: and every other machine budget history waits for.
        retired_pending |= {pair for pair in budget_retired if pair in journals_needed and pair not in read}
    return {"paired": True, "complete": not unrecovered, "unrecovered": unrecovered,
            "budget_trusted": budget_trusted, "budget_trusted_after": budget_trusted_after,
            "retired_pending": retired_pending}


def maintain_winn3_authority_epoch(conn: sqlite3.Connection) -> str:
    """Pair, progress and rotate the ledger epoch. The caller holds the main
    database's writer lock and commits it.

    The ledger is always written and committed first. If the main commit is
    then lost, the epochs disagree and recovery is entered again, which is the
    conservative direction. Rotating on every pass means a copy of either file
    older than one pass no longer matches the other when restored, and the
    process-held epoch and high-water sequence (_winn3_trust_broken) catch a
    restored pair that matches itself.
    """
    now = winn3_clock()
    main_epoch = get_setting(conn, WINN3_AUTHORITY_EPOCH_SETTING, "")
    fresh = secrets.token_hex(16)
    with winn3_authority_ledger() as ledger:
        ledger.execute("BEGIN IMMEDIATE")
        meta = winn3_ledger_meta(ledger)

        def put(key, value):
            ledger.execute(
                "INSERT OR REPLACE INTO winn3_ledger_meta (key, value) VALUES (?, ?)",
                (key, str(value)),
            )

        entered_since = ""
        hosts = winn3_node_hosts(conn)
        own_hosts = winn3_recovery_hosts(conn)  # HL-F2
        if _winn3_trust_broken(main_epoch, meta, ledger):
            # A waiver rests on the evidence of the recovery it was granted in;
            # a new recovery starts with none (winn3_waive_recovery_node).
            ledger.execute("DELETE FROM winn3_ledger_meta WHERE key='recovery_waived'")
            nodes = winn3_recovery_node_set(conn, ledger)
            entered_since = repr(now)
            put("recovery_since", entered_since)
            put("recovery_nodes", json.dumps(sorted(nodes)))
            put("budget_trusted_after", repr(now + WINN3_DEPARTURE_LEDGER_SECONDS))
            ledger.execute("DELETE FROM winn3_ledger_meta WHERE key='recovery_complete'")
            state = "entered"
            logger.warning(
                "Winn3 authority recovery entered: %d node(s) counted as unknown, "
                "departure allowances withheld until the charge window has passed",
                len(nodes),
            )
        elif meta.get("recovery_complete") != "1":
            since = float(meta.get("recovery_since") or math.inf)
            try:
                nodes = set(json.loads(meta.get("recovery_nodes") or "[]"))
            except ValueError:
                nodes = set()
            nodes |= winn3_recovery_node_set(conn, ledger)
            nodes -= winn3_proven_unwritten_slugs(conn, ledger)  # OI-SYNC_HUB-6 (round 3)
            if all(_winn3_node_recovered(ledger, slug, since, now, hosts.get(slug)) for slug in nodes) \
                    and all(_winn3_node_recovered(ledger, slug, since, now, gateway)
                            for slug, gateway in winn3_retired_gateways(ledger, hosts, now)):
                if winn3_recovery_waived_slugs(conn, ledger):
                    # Completion that rests on an operator waiver is not final. The
                    # marker would stop winn3_recovery_state and this pass from
                    # looking at the waiver again, so a node opened or republished
                    # afterwards would stay waived. Leave it unwritten: the waiver
                    # is re-checked on every read, and the state is not "recovering".
                    state = "normal"
                else:
                    put("recovery_complete", "1")
                    state = "completed"
                    logger.info("Winn3 authority recovery complete for %d node(s)", len(nodes))
            else:
                state = "recovering"
        else:
            state = "normal"
        settled = {}
        if state != "entered":
            current = winn3_recovery_node_set(conn, ledger)
            authority, charges, _after = _winn3_new_node_barrier(
                ledger, current, own_hosts, float(meta.get("recovery_since") or math.inf), now)
            with _WINN3_PROCESS_TRUST_LOCK:
                settled = {
                    slug: entry for slug, entry in _WINN3_PROCESS_TRUST["node_entries"].items()
                    if slug in current and slug not in authority and slug not in charges
                }
        put("epoch", fresh)
        top = ledger.execute("SELECT COALESCE(MAX(seq), 0) FROM winn3_publications").fetchone()[0]
        # The process lock is held across the commit, so no detection can
        # compare the committed ledger with the process state before this
        # entry's half of it is applied (_winn3_note_regression). If the
        # commit fails, the process holds an epoch the ledger lacks, which is
        # a mismatch: recovery again, the conservative direction.
        with _WINN3_PROCESS_TRUST_LOCK:
            # The caller commits the main setting; until then admission, which
            # reads the committed main epoch, sees a mismatch and defers.
            _WINN3_PROCESS_TRUST["epoch"] = fresh
            if state == "entered":
                _WINN3_PROCESS_TRUST["high_water"] = int(top)
                _WINN3_PROCESS_TRUST["recovery_since"] = entered_since
                # This recovery covers every regression detected so far, and
                # only those: one detected later invalidates it.
                _WINN3_PROCESS_TRUST["entered"] = _WINN3_PROCESS_TRUST["regressions"]
            covering = _WINN3_PROCESS_TRUST["entered"]
            for slug, entry in settled.items():
                if _WINN3_PROCESS_TRUST["node_entries"].get(slug) == entry:
                    del _WINN3_PROCESS_TRUST["node_entries"][slug]
                    _WINN3_PROCESS_TRUST["covered"][slug] = entry[1]
                    logger.info("Winn3 newly encountered node %s recovered", slug)
            if state == "entered":
                # The new entry covers every node it named, and only those.
                _WINN3_PROCESS_TRUST["covered"] = {slug: own_hosts.get(slug, "") for slug in nodes}
                _WINN3_PROCESS_TRUST["node_entries"] = {}
            ledger.commit()
    set_setting(conn, WINN3_AUTHORITY_EPOCH_SETTING, fresh)
    if state in {"completed", "normal"}:
        view = winn3_recovery_state(conn, now)
        with _WINN3_PROCESS_TRUST_LOCK:
            # Completion satisfies the requirement of the recovery it belongs
            # to, never a regression detected after that recovery's entry.
            if view["complete"] and view["budget_trusted"] and \
                    _WINN3_PROCESS_TRUST["entered"] == covering and \
                    _WINN3_PROCESS_TRUST["cleared"] < covering:
                _WINN3_PROCESS_TRUST["cleared"] = covering
                logger.info("Winn3 latched recovery cleared: authority and budget re-established")
    return state


def create_winn3_departure_grant_table(conn: sqlite3.Connection):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS winn3_departure_grants (
            grant_id TEXT PRIMARY KEY,
            device_id TEXT NOT NULL,
            account_number TEXT NOT NULL,
            node_slug TEXT NOT NULL,
            static_public TEXT NOT NULL,
            inner_v4 TEXT NOT NULL,
            issued_at REAL NOT NULL,
            expires_at REAL NOT NULL,
            cleanup_queued INTEGER NOT NULL DEFAULT 0
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_winn3_departure_grants_node "
        "ON winn3_departure_grants(node_slug, expires_at)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_winn3_departure_grants_device "
        "ON winn3_departure_grants(device_id, expires_at)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_winn3_departure_grants_account "
        "ON winn3_departure_grants(account_number, issued_at)"
    )
    # Retiring a grant (expires_at moved earlier) republishes its node, so the
    # gateway drops the binding at the next drain instead of at its not_after.
    # The SQL triggers retire by setting expires_at to 0, which needs no clock:
    # every not-yet-retired grant of the affected device or account ends.
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS winn3_departure_grants_retired
        AFTER UPDATE OF expires_at ON winn3_departure_grants
        WHEN NEW.expires_at < OLD.expires_at
        BEGIN
            INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
            VALUES (NEW.node_slug, 0, 0)
            ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0;
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS winn3_departure_grants_device_delete
        AFTER DELETE ON devices
        BEGIN
            UPDATE winn3_departure_grants SET expires_at = 0
            WHERE device_id = OLD.device_id AND expires_at > 0;
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS winn3_departure_grants_device_identity
        AFTER UPDATE OF device_id, account_number, winn3_static_public, winn3_inner_v4
        ON devices
        WHEN OLD.device_id IS NOT NEW.device_id
          OR OLD.account_number IS NOT NEW.account_number
          OR OLD.winn3_static_public IS NOT NEW.winn3_static_public
          OR OLD.winn3_inner_v4 IS NOT NEW.winn3_inner_v4
        BEGIN
            UPDATE winn3_departure_grants SET expires_at = 0
            WHERE device_id = OLD.device_id AND expires_at > 0;
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS winn3_departure_grants_account_authority
        AFTER UPDATE OF status, expiration_date ON users
        BEGIN
            UPDATE winn3_departure_grants SET expires_at = 0
            WHERE account_number = NEW.account_number
              AND expires_at > 0
              AND COALESCE(NEW.status, '') != 'active';
            INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
            SELECT DISTINCT node_slug, 0, 0 FROM winn3_departure_grants
            WHERE account_number = NEW.account_number
              AND expires_at > 0
            ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0;
        END
    """)


def winn3_departure_grace_seconds() -> int:
    try:
        grace = int(WINN3_DEPARTURE_GRACE_SECONDS)
    except (TypeError, ValueError):
        return 0
    return max(0, min(grace, int(WINN3_DEPARTURE_GRACE_CEILING_SECONDS)))


def retire_winn3_departure_grants(
    conn: sqlite3.Connection, device_id: str, node_slugs
) -> int:
    """End this device's live grants at the named nodes now.

    This retires DATABASE authority and queues publication. It releases no
    authorization capacity: winn3_effective_authorizations keeps counting the
    published entry until a confirmed replacement has had time to take effect.
    """
    now = winn3_clock()
    retired = 0
    for slug in {str(value or "").strip().lower() for value in node_slugs}:
        if not slug:
            continue
        cursor = conn.execute(
            "UPDATE winn3_departure_grants SET expires_at=? "
            "WHERE device_id=? AND node_slug=? AND expires_at>?",
            (now, device_id, slug, now),
        )
        retired += max(int(cursor.rowcount or 0), 0)
    return retired


def issue_winn3_departure_grant(
    conn: sqlite3.Connection,
    *,
    device_id: str,
    account_number: str,
    node_slug: str,
    static_public: str,
    inner_v4: str,
) -> float:
    """Keep a departing identity authorized at its previous node, bounded.

    Returns the grant's expiry as Unix seconds, or 0.0 when the grace is
    disabled and the caller falls back to immediate removal. Capacity and the
    account budget were already reserved by winn3_switch_deferral under this
    same writer lock; the charge itself is recorded, durably and before the
    remote write, by the publication that carries the grant.
    """
    grace = winn3_departure_grace_seconds()
    slug = str(node_slug or "").strip().lower()
    fields = (device_id, account_number, slug, static_public, inner_v4)
    if grace <= 0 or not all(str(value or "").strip() for value in fields):
        return 0.0
    now = winn3_clock()
    expires_at = now + grace
    conn.execute(
        "INSERT INTO winn3_departure_grants (grant_id, device_id, account_number, "
        "node_slug, static_public, inner_v4, issued_at, expires_at) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (secrets.token_hex(16), device_id, account_number, slug,
         str(static_public).strip(), str(inner_v4).strip(), now, expires_at),
    )
    logger.info("Winn3 departure grace issued for node %s: %ds", slug, grace)
    return expires_at


def expire_winn3_departure_grants() -> dict:
    """Queue a clean republish for every lapsed grant, then prune the ledger.

    Housekeeping only. The gateway already stopped honouring each lapsed entry
    at its not_after; this removes the stale line from the file.
    """
    now = winn3_clock()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        lapsed = conn.execute(
            "SELECT DISTINCT node_slug FROM winn3_departure_grants "
            "WHERE expires_at<=? AND cleanup_queued=0",
            (now,),
        ).fetchall()
        for row in lapsed:
            conn.execute("""
                INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
                VALUES (?, 0, 0)
                ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0
            """, (row["node_slug"],))
        conn.execute(
            "UPDATE winn3_departure_grants SET cleanup_queued=1 "
            "WHERE expires_at<=? AND cleanup_queued=0",
            (now,),
        )
        pruned = conn.execute(
            "DELETE FROM winn3_departure_grants "
            "WHERE cleanup_queued=1 AND expires_at<=? AND issued_at<=?",
            (now, now - WINN3_DEPARTURE_LEDGER_SECONDS),
        ).rowcount
    return {"queued": len(lapsed), "pruned": max(int(pruned or 0), 0)}


def reconcile_winn3_authority_ledger() -> dict:
    """Queue a republish wherever a published file may differ from authority.

    A node is queued when its latest recorded publication is uncertain (lost
    acknowledgement, crash, timeout), or when it was confirmed but no longer
    equals the document the database now wants (a rolled-back switch, a
    provisional destination awaiting finalization, a lapsed grant). It also
    maintains the recovery barrier (maintain_winn3_authority_epoch) and queues
    every node still unknown to it. Existing queue rows keep their backoff.
    Dead history is pruned.
    """
    now = winn3_clock()
    queued = set()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        recovery_state = maintain_winn3_authority_epoch(conn)
    # Read back every node recovery still needs, outside the writer lock: its
    # registry settles its authority, its journal the account budgets.
    with get_db() as conn:
        view = winn3_recovery_state(conn, winn3_clock())
        with winn3_authority_ledger() as ledger:
            meta = winn3_ledger_meta(ledger)
            since = float(meta.get("recovery_since") or 0.0)
            node_hosts = winn3_recovery_hosts(conn)  # HL-F2: the host its read-back records
            read = {
                row["node_slug"] for row in ledger.execute(
                    "SELECT node_slug, gateway FROM winn3_journal_reads WHERE recovery_since=?", (since,))
                if row["gateway"] == node_hosts.get(row["node_slug"], "")
            }
            try:
                wanted_nodes = set(json.loads(meta.get("recovery_nodes") or "[]"))
            except ValueError:
                wanted_nodes = set()
            wanted_nodes |= winn3_recovery_node_set(conn, ledger)
            wanted_nodes -= winn3_proven_unwritten_slugs(conn, ledger)  # OI-SYNC_HUB-6 (round 3)
        pending = sorted(
            slug for slug in view["unrecovered"] | (set() if view["budget_trusted"] else wanted_nodes - read)
            if "@" not in slug  # retired gateways are read back at their own host below
        )
        hosts = {
            row["slug"]: (row["ssh_host"] or extract_node_host(row["endpoint"] or ""))
            for row in conn.execute("SELECT slug, ssh_host, endpoint FROM nodes")
        }
    observed = 0
    for slug in pending[:WINN3_RECOVERY_OBSERVATIONS_PER_PASS]:
        if hosts.get(slug) and observe_winn3_node(hosts[slug], slug):
            observed += 1
    # A retired gateway is read back at its own host, never inferred from the
    # slug's new one; its read counts only for itself.
    for slug, gateway in sorted(view.get("retired_pending", ()))[:WINN3_RECOVERY_OBSERVATIONS_PER_PASS]:
        if observe_winn3_node(gateway, slug, gateway=gateway):
            observed += 1
    with winn3_authority_ledger() as ledger:
        latest = {}
        for row in ledger.execute(
            """
            SELECT p.node_slug, p.seq, p.outcome FROM winn3_publications p
            WHERE p.seq = (
                SELECT MAX(q.seq) FROM winn3_publications q
                WHERE q.node_slug = p.node_slug AND q.outcome != 'refused'
            )
            """
        ).fetchall():
            entries = {
                (entry["static_public"], entry["inner_v4"], int(entry["not_after"]))
                for entry in ledger.execute(
                    "SELECT static_public, inner_v4, not_after "
                    "FROM winn3_publication_entries WHERE seq=?",
                    (row["seq"],),
                )
            }
            latest[row["node_slug"]] = (row["outcome"], entries)
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        # Queuing does not complete recovery: a node leaves the barrier only
        # through a confirmed publication or read-back (winn3_recovery_state).
        queued.update(winn3_recovery_state(conn, winn3_clock())["unrecovered"])
        for slug, (outcome, entries) in latest.items():
            if outcome != "confirmed":
                queued.add(slug)
                continue
            try:
                wanted = winn3_peer_registry_document(conn, slug)
            except Exception:
                queued.add(slug)
                continue
            if {
                (peer["static_public"], peer["inner_v4"], int(peer["not_after"]))
                for peer in wanted["peers"]
            } != entries:
                queued.add(slug)
        for slug in sorted(queued):
            conn.execute(
                "INSERT OR IGNORE INTO winn3_registry_refreshes "
                "(node_slug, attempts, next_attempt_at) VALUES (?, 0, 0)",
                (slug,),
            )
    with winn3_authority_ledger() as ledger:
        ledger.execute("BEGIN IMMEDIATE")
        horizon = now - WINN3_GATEWAY_REFRESH_SECONDS - WINN3_AUTHORITY_LEDGER_RETENTION_SECONDS
        dead = [
            row["seq"] for row in ledger.execute(
                """
                SELECT p.seq FROM winn3_publications p
                WHERE EXISTS (
                    SELECT 1 FROM winn3_publications c
                    WHERE c.node_slug = p.node_slug AND c.gateway = p.gateway
                      AND c.outcome = 'confirmed'
                      AND c.seq > p.seq AND c.finished_at <= ?
                )
                """,
                (horizon,),
            )
        ]
        if recovery_state == "normal":
            # A retired gateway whose record authorizes nothing any more, and
            # whose last publication is older than the charge window plus
            # retention, is forgotten: nothing it held can still count. Only
            # outside recovery, when the record is trusted.
            with get_db() as conn:
                node_hosts = winn3_node_hosts(conn)
                own_hosts = winn3_recovery_hosts(conn)
            stale = now - WINN3_DEPARTURE_LEDGER_SECONDS - WINN3_AUTHORITY_LEDGER_RETENTION_SECONDS
            forgettable = winn3_retired_gateways(ledger, node_hosts, now)
            # FINAL4 F4-HL: a machine left by a slug that is not winn/3 is a
            # charge-journal source only (winn3_recovery_state), and authority
            # recovery never reads it. It is forgotten by the same rule, but
            # only once this recovery has settled its charges: its journal was
            # read, or the departure window since the entry has passed. Until
            # then a restored record may understate its last use. Once it is
            # forgotten, an unreadable old machine no longer holds the budget
            # at each hub start. One still authorizing by the record (a
            # lifetime entry) is kept, as for a winn/3 slug.
            meta = winn3_ledger_meta(ledger)
            settled = {
                (row["node_slug"], row["gateway"]) for row in ledger.execute(
                    "SELECT node_slug, gateway FROM winn3_journal_reads WHERE recovery_since=?",
                    (float(meta.get("recovery_since") or math.inf),))
            }
            window_passed = now >= float(meta.get("budget_trusted_after") or math.inf)
            for pair, live in winn3_retired_gateways(ledger, own_hosts, now).items():
                if pair[0] not in node_hosts and (window_passed or pair in settled):
                    forgettable.setdefault(pair, live)
            for (slug, gateway), live in forgettable.items():
                seqs = [
                    row["seq"] for row in ledger.execute(
                        "SELECT seq FROM winn3_publications WHERE node_slug=? AND gateway=?",
                        (slug, gateway))
                ]
                last = ledger.execute(
                    "SELECT MAX(COALESCE(finished_at, started_at)) FROM winn3_publications "
                    "WHERE node_slug=? AND gateway=?", (slug, gateway)).fetchone()[0]
                if not live and last is not None and float(last) <= stale:
                    dead.extend(seq for seq in seqs if seq not in dead)
        for seq in dead:
            ledger.execute("DELETE FROM winn3_publication_entries WHERE seq=?", (seq,))
            ledger.execute("DELETE FROM winn3_publications WHERE seq=?", (seq,))
        ledger.execute(
            "DELETE FROM winn3_departure_charges WHERE charged_at<=?",
            (now - WINN3_DEPARTURE_LEDGER_SECONDS - WINN3_AUTHORITY_LEDGER_RETENTION_SECONDS,),
        )
        ledger.commit()
    return {"queued": len(queued), "pruned": len(dead), "recovery": recovery_state,
            "observed": observed}


def drain_winn3_registry_refreshes(limit: int = 4, node_slugs=None) -> dict:
    published = 0
    retry = 0
    wanted = sorted({str(slug or "").strip().lower() for slug in (node_slugs or ())} - {""})
    with get_db() as conn:
        ensure_schema(conn)
        pending = conn.execute(
            "SELECT node_slug FROM winn3_registry_refreshes WHERE next_attempt_at<=? "
            + ("AND node_slug IN (" + ",".join("?" * len(wanted)) + ") " if wanted else "")
            + "ORDER BY next_attempt_at, node_slug LIMIT ?",
            (time.time(), *wanted, max(1, min(int(limit), 32))),
        ).fetchall()
    for item in pending:
        with get_db() as conn:
            conn.execute("BEGIN IMMEDIATE")
            queued = conn.execute(
                "SELECT attempts FROM winn3_registry_refreshes "
                "WHERE node_slug=? AND next_attempt_at<=?",
                (item["node_slug"], time.time()),
            ).fetchone()
            if queued is None:
                continue
            node = conn.execute(
                "SELECT ssh_host, endpoint FROM nodes WHERE slug=?", (item["node_slug"],)
            ).fetchone()
            node_ip = (node["ssh_host"] or extract_node_host(node["endpoint"] or "")) if node else ""
            if node_ip and sync_winn3_registry_to_node(conn, node_ip, item["node_slug"]):
                conn.execute("DELETE FROM winn3_registry_refreshes WHERE node_slug=?", (item["node_slug"],))
                published += 1
            else:
                attempts = int(queued["attempts"]) + 1
                conn.execute(
                    "UPDATE winn3_registry_refreshes SET attempts=?, next_attempt_at=? WHERE node_slug=?",
                    (attempts, time.time() + peer_revocation_backoff_seconds(attempts), item["node_slug"]),
                )
                retry += 1
    return {"published": published, "retry": retry}


# Per-node cover-set PUBLIC digests (Round GK OI-GK-3, 2026-09-26).
#
# Each node generates its own ECH key (and later its own Winn leaf) on the
# node, and reports only SHA-256 digests of the PUBLIC halves here. The hub
# never sees a private key, an ECH key file, or a certificate private key, and
# it does not serve any of this to clients: the v3 descriptor is a closed field
# set that the shipping Dart client refuses to extend
# (lib/winn_protocol_dispatch.dart, descriptor-unknown-fields).
#
# What the table is FOR is the uniqueness guard. Eight nodes sharing one ECH
# key is the measured state this replaces (one distinct ech-keys.json across
# the fleet); a second node registering a public key another node already holds
# means per-node generation did not happen there, and it is refused rather
# than recorded. The unique indexes enforce the same rule under concurrent
# registrations, where the handler's own pre-check could race. The leaf digest
# is optional and NULL is not unique, because step 1 rotates only ECH and every
# node still holds the fleet-shared leaf until step 2.
def create_winn3_node_key_digests_table(conn: sqlite3.Connection):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS winn3_node_key_digests (
            slug TEXT PRIMARY KEY,
            ech_public_key_sha256 TEXT NOT NULL,
            ech_config_list_sha256 TEXT NOT NULL,
            leaf_spki_sha256 TEXT,
            recorded_at TEXT NOT NULL
        )
    """)
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_winn3_node_key_digests_ech "
        "ON winn3_node_key_digests(ech_public_key_sha256)"
    )
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_winn3_node_key_digests_leaf "
        "ON winn3_node_key_digests(leaf_spki_sha256) "
        "WHERE leaf_spki_sha256 IS NOT NULL"
    )


def create_winn3_signer_tickets_table(conn: sqlite3.Connection):
    # H4 (3.8): the exact signed t1 ticket bytes the hub stores when the
    # operator posts them (POST /admin/nodes/winn3/signer-ticket). The signer
    # verifies them at spend; the hub re-verifies the stored bytes at use
    # (3.17). payload and sig are the posted bytes verbatim.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS winn3_signer_tickets (
            slug TEXT NOT NULL,
            action TEXT NOT NULL,
            epoch INTEGER NOT NULL,
            nonce TEXT NOT NULL,
            payload TEXT NOT NULL,
            sig TEXT NOT NULL,
            go_live TEXT,
            tier TEXT,
            not_after INTEGER NOT NULL,
            posted_at TEXT NOT NULL,
            PRIMARY KEY (slug, nonce)
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_winn3_signer_tickets_slug_action "
        "ON winn3_signer_tickets(slug, action)"
    )


def create_node_fresh_completions_table(conn: sqlite3.Connection):
    # H7 (design 3.17): one row per (slug, deployment epoch). The epoch is the
    # node's node_bootstrapped_at at completion, so a re-bootstrap (a provider
    # reset that keeps its slug) starts a new row and never reuses the old one.
    # installer_sha256 makes POST .../deployment/complete-fresh idempotent for
    # the same digest and refuses a different one. ticket_nonce records which
    # t1 ticket authorised the completion: the signer alone knows when a nonce
    # is spent at sign, so the hub cannot read that, and it uses this record
    # to refuse a reset ticket that an EARLIER epoch's completion already used.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS node_fresh_completions (
            slug TEXT NOT NULL,
            epoch TEXT NOT NULL,
            installer_sha256 TEXT NOT NULL,
            ticket_nonce TEXT,
            completed_at TEXT NOT NULL,
            PRIMARY KEY (slug, epoch)
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_node_fresh_completions_nonce "
        "ON node_fresh_completions(slug, ticket_nonce)"
    )


# Schema check cache. ensure_schema runs on ordinary requests (141 call sites)
# and the full pass is 511 statements, 136 of them write-class, about 9 ms and
# one SQLite writer lock per call, so every request, GET /nodes included,
# queued behind every other writer. The hub runs as one process (see the note
# on process-local state at the lock below), so the full pass runs once per
# database file and again only when the schema cookie moved (another writer
# ran DDL, or the file was replaced). Every call still runs the per-row
# backfills, read first so the common case takes no writer lock, and the
# retention work at most once per SCHEMA_MAINTENANCE_INTERVAL_SECONDS. A
# caller that needs the full pass unconditionally calls _ensure_schema_full.
_SCHEMA_READY: dict = {}
_SCHEMA_READY_LOCK = threading.Lock()
SCHEMA_MAINTENANCE_INTERVAL_SECONDS = 3600


def _schema_identity(conn: sqlite3.Connection) -> tuple:
    row = conn.execute("PRAGMA database_list").fetchone()
    path = str(row[2] if row else "")
    try:
        info = os.stat(path)
    except OSError:
        return (path, 0, 0)
    return (path, info.st_dev, info.st_ino)


def _schema_version(conn: sqlite3.Connection) -> int:
    return int(conn.execute("PRAGMA schema_version").fetchone()[0])


def _schema_row_backfills(conn: sqlite3.Connection) -> None:
    """Row backfills the full pass used to run unconditionally. Each one reads
    first: a matching row is rare, and an UPDATE that matches nothing still
    takes SQLite's writer lock."""
    if conn.execute(
        "SELECT 1 FROM nodes WHERE node_bootstrapped_at IS NULL LIMIT 1"
    ).fetchone():
        conn.execute("UPDATE nodes SET node_bootstrapped_at='0001-01-01T00:00:00' "
                     "WHERE node_bootstrapped_at IS NULL")
    if conn.execute(
        "SELECT 1 FROM nodes WHERE winn3_bootstrap_authorized=0 "
        "AND EXISTS (SELECT 1 FROM bootstrap_grants b WHERE b.role='node' "
        "AND b.subject_id=nodes.slug AND b.used_at IS NOT NULL) LIMIT 1"
    ).fetchone():
        conn.execute("UPDATE nodes SET winn3_bootstrap_authorized=1 WHERE winn3_bootstrap_authorized=0 "
                     "AND EXISTS (SELECT 1 FROM bootstrap_grants b WHERE b.role='node' "
                     "AND b.subject_id=nodes.slug AND b.used_at IS NOT NULL)")
    legacy_promoted_core_ids = [
        row["core_id"] for row in conn.execute(
            "SELECT core_id FROM core_servers WHERE COALESCE(promoted, 0)=1 "
            "AND active_promotion_id IS NULL"
        ).fetchall()
    ]
    if legacy_promoted_core_ids:
        now_iso = utcnow().isoformat()
        placeholders = ",".join("?" for _ in legacy_promoted_core_ids)
        conn.execute(
            "UPDATE double_vpn_assignments "
            "SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL, updated_at=? "
            f"WHERE status='active' AND core_id IN ({placeholders})",
            (now_iso, *legacy_promoted_core_ids),
        )
        conn.execute(
            "UPDATE core_servers SET promoted=0, runtime_ready=0 "
            f"WHERE core_id IN ({placeholders})",
            tuple(legacy_promoted_core_ids),
        )
        logger.warning(
            "darkened %d legacy Core promotion(s) without a build-exclusion acknowledgement",
            len(legacy_promoted_core_ids),
        )


def _schema_maintenance(conn: sqlite3.Connection) -> None:
    cutoff = (utcnow() - timedelta(days=FREE_ACCESS_EVENTS_RETENTION_DAYS)).isoformat()
    conn.execute("DELETE FROM free_access_events WHERE created_at < ?", (cutoff,))
    archive_terminal_payment_orders(conn)


def ensure_schema(conn: sqlite3.Connection):
    identity = _schema_identity(conn)
    version = _schema_version(conn)
    now = time.monotonic()
    with _SCHEMA_READY_LOCK:
        state = _SCHEMA_READY.get(identity)
    if state is not None and state[0] == version:
        _schema_row_backfills(conn)
        if now - state[1] >= SCHEMA_MAINTENANCE_INTERVAL_SECONDS:
            _schema_maintenance(conn)
            with _SCHEMA_READY_LOCK:
                _SCHEMA_READY[identity] = (version, now)
        return
    _ensure_schema_full(conn)
    with _SCHEMA_READY_LOCK:
        _SCHEMA_READY[identity] = (_schema_version(conn), now)


def _ensure_schema_full(conn: sqlite3.Connection):
    migrate_legacy_table(
        conn, "users", "account_number", create_users_table,
        lambda legacy: f"""
            INSERT OR IGNORE INTO users (account_number, email, subscriber_name, status, expiration_date, hardware_hash, created_at)
            SELECT accountnumber, email, COALESCE(subscribername, 'Wins VPN User'), COALESCE(status, 'active'), expirationdate, hardwarehash, COALESCE(createdat, CURRENT_TIMESTAMP)
            FROM {legacy}
            WHERE accountnumber IS NOT NULL
        """,
    )
    migrate_legacy_table(
        conn, "devices", "device_id", create_devices_table,
        lambda legacy: f"""
            INSERT OR IGNORE INTO devices (device_id, account_number, device_model, vpn_internal_ip, client_private_key, client_public_key, preshared_key, last_seen, location_slug)
            SELECT deviceid, accountnumber, COALESCE(devicemodel, 'Unknown Android'), vpninternalip, clientprivatekey, clientpublickey, presharedkey, lastseen, locationslug
            FROM {legacy}
            WHERE deviceid IS NOT NULL
        """,
    )
    migrate_legacy_table(
        conn, "nodes", "public_key", create_nodes_table,
        lambda legacy: f"""
            INSERT OR REPLACE INTO nodes (slug, name, flag, endpoint, stealth_endpoint, public_key, preshared_key, status, last_heartbeat, obfuscation_json)
            SELECT slug, name, flag, endpoint, stealthendpoint, publickey, presharedkey, COALESCE(status, 'online'), lastheartbeat, obfuscationjson
            FROM {legacy}
            WHERE slug IS NOT NULL
        """,
    )

    create_users_table(conn)
    create_devices_table(conn)
    create_nodes_table(conn)
    migrate_nodes_operator_enabled_default(conn)
    create_core_servers_table(conn)
    create_bootstrap_grants_table(conn)
    create_node_retirements_table(conn)
    create_node_promotion_events_table(conn)
    create_core_promotion_events_table(conn)
    create_double_vpn_assignments_table(conn)
    create_double_vpn_enrollment_leases_table(conn)
    create_node_closure_cleanup_table(conn)
    create_node_offnode_gates_table(conn)
    create_core_exit_peers_table(conn)
    create_core_relay_tables(conn)
    create_settings_table(conn)
    create_paypal_events_table(conn)
    create_activation_delivery_outbox_table(conn)
    create_activation_extra_keys_table(conn)
    create_monero_orders_table(conn)
    create_payment_orders_table(conn)
    # R2: promo campaign typed at checkout, validated at order creation and
    # honoured (bonus days) when the stored order settles.
    add_column_if_missing(conn, "payment_orders", "promo_code", "TEXT NOT NULL DEFAULT ''")
    create_payment_order_archive_table(conn)
    # R2-AUDIT-08: archived orders keep their promo attribution.
    add_column_if_missing(conn, "payment_order_archive", "promo_code", "TEXT NOT NULL DEFAULT ''")
    create_rate_limits_table(conn)
    create_payment_clicks_table(conn)
    create_peer_revocations_table(conn)
    create_referral_rewards_table(conn)
    add_column_if_missing(conn, "referral_rewards", "clawed_back_at", "TEXT")
    create_free_access_events_table(conn)
    create_legal_documents_table(conn)
    create_legal_acceptances_table(conn)
    create_account_deletion_tables(conn)
    create_donation_acknowledgments_table(conn)
    # Phase 3 prepaid redemption (A7 / A7a). Defined in the contiguous
    # redemption block at the end of this module; resolved at call time.
    create_redemption_tables(conn)
    # Duress emergency relay outbox (POST /emergency/dispatch). Defined in
    # the contiguous emergency block at the end of this module.
    create_emergency_dispatch_tables(conn)
    # Hoppy agent Tier 1 control-plane endpoints. Defined in the contiguous
    # Hoppy block at the end of this module. Additive and idempotent, so an
    # older hub build that does not yet know this function simply skips it --
    # there is nothing here that an old build must be able to read.
    create_hoppy_agent_tables(conn)
    # H4 (3.8): the stored t1 signer tickets (POST /admin/nodes/winn3/signer-ticket).
    create_winn3_signer_tickets_table(conn)
    # H7 (3.17): which installer digest and t1 ticket each deployment epoch's
    # fresh completion used.
    create_node_fresh_completions_table(conn)

    add_column_if_missing(conn, "nodes", "ssh_host", "TEXT")
    add_column_if_missing(conn, "nodes", "tunnel_gateway_ipv4", "TEXT")
    add_column_if_missing(conn, "nodes", "wg_port", "INTEGER DEFAULT 9110")
    add_column_if_missing(conn, "nodes", "xray_uuid", "TEXT")
    add_column_if_missing(conn, "nodes", "xray_path", "TEXT DEFAULT '/wins-stealth-tunnel'")
    add_column_if_missing(conn, "nodes", "xray_security", "TEXT DEFAULT 'none'")
    add_column_if_missing(conn, "nodes", "xray_sni", "TEXT")
    add_column_if_missing(conn, "nodes", "stealth_public_port", "INTEGER DEFAULT 80")
    add_column_if_missing(conn, "nodes", "xray_inbound_port", "INTEGER DEFAULT 10085")
    add_column_if_missing(conn, "nodes", "regional_aliases", "TEXT DEFAULT '[]'")
    add_column_if_missing(conn, "nodes", "stealth_transports", "TEXT DEFAULT '[]'")
    add_column_if_missing(conn, "nodes", "awg_rx_bytes", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "awg_tx_bytes", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "wan_rx_bytes", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "wan_tx_bytes", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "rx_mbps", "REAL DEFAULT 0")
    add_column_if_missing(conn, "nodes", "tx_mbps", "REAL DEFAULT 0")
    add_column_if_missing(conn, "nodes", "peer_count", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "max_peers", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "load_band", "TEXT")
    add_column_if_missing(conn, "nodes", "load_candidate", "TEXT")
    add_column_if_missing(conn, "nodes", "load_candidate_count", "INTEGER")
    add_column_if_missing(conn, "nodes", "load_reported_at", "TEXT")
    add_column_if_missing(conn, "nodes", "load_band_at", "TEXT")
    add_column_if_missing(conn, "nodes", "free_access_enabled", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "direct_awg_enabled", "INTEGER DEFAULT 1")
    add_column_if_missing(conn, "nodes", "direct_awg_node_enabled", "INTEGER")
    add_column_if_missing(conn, "nodes", "direct_awg_admin_override", "INTEGER")
    # An older database with no operator latch is unproven by definition. The
    # additive migration therefore darkens those rows; an operator must promote
    # them explicitly after fresh evidence rather than silently grandfathering
    # them into customer service.
    add_column_if_missing(conn, "nodes", "operator_enabled", "INTEGER NOT NULL DEFAULT 0")
    add_column_if_missing(conn, "nodes", "management_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "management_checked_at", "TEXT")
    add_column_if_missing(conn, "nodes", "management_error", "TEXT")
    # External data-plane reachability, written ONLY by
    # wins_node_dataplane_probe.py (wins-dataplane-probe.timer). Five aggregate
    # columns, then three per transport: direct AWG/UDP, plaintext stealth
    # WS, and stealth WS inside TLS. Additive and never dropped, so an older
    # hub build simply stops reading them rather than erroring -- which is
    # precisely the silent failure the deploy guard in write_app() exists to
    # catch.
    add_column_if_missing(conn, "nodes", "data_plane_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_checked_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_fail_streak", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "data_plane_error", "TEXT DEFAULT ''")
    add_column_if_missing(conn, "nodes", "data_plane_udp_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_udp_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_udp_fail_streak", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_fail_streak", "INTEGER DEFAULT 0")
    # Stealth-over-TLS is tracked separately from plaintext stealth because
    # exactly one platform distinction rides on it: Linux accepts the TLS
    # stealth transport and refuses the plaintext one.
    add_column_if_missing(conn, "nodes", "data_plane_stealth_tls_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_tls_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_tls_fail_streak", "INTEGER DEFAULT 0")
    # H5 (design 3.15, ruling E): the hub-side AWG carrying canary, one status
    # and one last-success time per transport, written ONLY by
    # wins_node_dataplane_probe.py --carry. Status is ok, failed (the test ran
    # and no reply came back), probe_error (the test could not run),
    # unconfigured (the node does not advertise it) or unknown. A failure here
    # never closes an open node; that stays the reachability prober's job. A
    # stale or failed carry proof does block the rerun reopen
    # (installer_rerun_carry_failures).
    add_column_if_missing(conn, "nodes", "data_plane_udp_carry_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_udp_carry_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_carry_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_carry_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_tls_carry_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_tls_carry_ok_at", "TEXT")
    # The attempt time per transport (additive). A failed transport is retried
    # at its cadence counted from this, not on every run; `_ok_at` stays the
    # time of the last success and is the only time the rerun gate reads.
    add_column_if_missing(conn, "nodes", "data_plane_udp_carry_checked_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_carry_checked_at", "TEXT")
    add_column_if_missing(conn, "nodes", "data_plane_stealth_tls_carry_checked_at", "TEXT")
    # A real external Winn3 session probe, distinct from port reachability.
    # The canary must authenticate, reach StateCarrying, and receive a reply
    # through the gateway. Unknown is intentionally not success.
    add_column_if_missing(conn, "nodes", "winn3_canary_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "nodes", "winn3_canary_checked_at", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_canary_ok_at", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_canary_error", "TEXT DEFAULT ''")
    # H0: migrations belong to the app, never to the read-only canary.
    add_column_if_missing(conn, "nodes", "winn3_identity_sha256", "TEXT")
    add_column_if_missing(conn, "nodes", "deployment_generation", "INTEGER NOT NULL DEFAULT 0")
    add_column_if_missing(conn, "nodes", "winn3_carrier_flipped_at", "TEXT")
    # H3: fleet-wide reservations remain unique while the carrier is winn/1.
    conn.execute("CREATE TABLE IF NOT EXISTS winn3_canary_bindings ("
                 "slug TEXT PRIMARY KEY REFERENCES nodes(slug), static_public TEXT NOT NULL UNIQUE, "
                 "inner_v4 TEXT NOT NULL UNIQUE, key_dir TEXT NOT NULL, "
                 "gateway_endpoint TEXT NOT NULL, gateway_id TEXT NOT NULL)")
    # H2: authorization, serialized jobs and generation-bound proofs.
    add_column_if_missing(conn, "nodes", "winn3_operator_hold", "INTEGER NOT NULL DEFAULT 0")
    add_column_if_missing(conn, "nodes", "winn3_bootstrap_authorized", "INTEGER NOT NULL DEFAULT 0")
    add_column_if_missing(conn, "nodes", "deployment_released_at", "TEXT")
    add_column_if_missing(conn, "nodes", "node_bootstrapped_at", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_expected_transition_json", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_pre_sign_result_json", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_served_profile_result_json", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_cycle_started_at", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_job_lease", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_job_lease_until", "REAL")
    add_column_if_missing(conn, "nodes", "winn3_canary_identity_sha256", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_canary_seq", "INTEGER")
    add_column_if_missing(conn, "nodes", "winn3_canary_generation", "INTEGER")
    # SYNC-15/16/22 (2026-09-29): what the node's own register reports about
    # its v3 gateway unit and its origin certificate, overwritten on every
    # register (NULL when that register did not report it). Compared by
    # winn3_gateway_report_blockers(); never served to a client.
    add_column_if_missing(conn, "nodes", "winn3_gateway_report_json", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_gateway_reported_at", "TEXT")
    add_column_if_missing(conn, "nodes", "origin_cert_not_after", "TEXT")
    add_column_if_missing(conn, "nodes", "node_token_hash", "TEXT")
    # Admin node-retirement lane (2026-08-07). NULL means "in service"; an ISO
    # timestamp means an operator retired this row through
    # POST /admin/nodes/retire. Additive and nullable, so an existing hub
    # database migrates by taking NULL for every row -- i.e. nothing is
    # retroactively retired.
    add_column_if_missing(conn, "nodes", "retired_at", "TEXT")
    # Installer reruns acquire this hub-side deployment latch before touching
    # the host. Registration may refresh health while it is held, but only the
    # matching postflight completion can release it, and release never promotes.
    add_column_if_missing(conn, "nodes", "deployment_withdrawal_id", "TEXT")
    add_column_if_missing(conn, "nodes", "deployment_withdrawn_at", "TEXT")
    # IA-SYNC SYNC-08: identity at withdrawal, and when the rerun completed.
    add_column_if_missing(conn, "nodes", "deployment_prior_state_json", "TEXT")
    add_column_if_missing(conn, "nodes", "deployment_completed_at", "TEXT")
    add_column_if_missing(conn, "nodes", "last_online_registered_at", "TEXT")
    # L84 (Round SC). Written by wins_node_dataplane_probe.py and the stale
    # sweep: consecutive aggregate probe_error runs, consecutive healthy
    # proofs and when that streak began. health_closed_at/_reason mark an
    # AUTOMATIC health closure (NULL for every operator closure); latch_cause
    # names the writer of the latest operator_enabled change and is copied
    # into node_latch_events by the transition trigger.
    add_column_if_missing(conn, "nodes", "data_plane_probe_error_streak", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "data_plane_green_streak", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "nodes", "data_plane_green_since", "TEXT")
    add_column_if_missing(conn, "nodes", "health_closed_at", "TEXT")
    add_column_if_missing(conn, "nodes", "health_closed_reason", "TEXT")
    add_column_if_missing(conn, "nodes", "latch_cause", "TEXT")
    # Design 10.2 (P1): the node's performance read-backs, overwritten on every
    # register (NULL when that register did not report them).
    add_column_if_missing(conn, "nodes", "performance_report_json", "TEXT")
    add_column_if_missing(conn, "nodes", "performance_reported_at", "TEXT")
    create_node_latch_events_table(conn)
    # Winn Protocol forward-compat seam: migrate existing node databases so the
    # protocol slot EXISTS and defaults to the shipping v1 protocol. Nothing
    # computes a non-default value today (see parse_protocol_params / served
    # vpn_config); Winn Protocol v3 populates protocol_params_json later.
    add_column_if_missing(conn, "nodes", "protocol_version", "TEXT DEFAULT 'winn/1'")
    add_column_if_missing(conn, "nodes", "protocol_params_json", "TEXT")
    # Standalone Winn v3 control-plane binding (2026-08-08). Two additive,
    # nullable columns; NULL on every existing row means "no descriptor", which
    # is exactly today's behaviour, so this migration changes nothing for any
    # node until an operator uploads a signed envelope.
    #
    #   winn3_descriptor_json  the offline-signed envelope, stored VERBATIM
    #                          ({"payload": b64, "sig": b64}). Stored as signed
    #                          rather than re-serialized because the client must
    #                          verify the exact bytes that were signed, and a
    #                          hub that re-encodes the payload is a hub that can
    #                          invalidate every signature with a JSON library
    #                          upgrade.
    #   winn3_admission_json   rotation bookkeeping (when each generation became
    #                          the served one). Not a second source of truth for
    #                          the key material -- that is inside the signature.
    add_column_if_missing(conn, "nodes", "winn3_descriptor_json", "TEXT")
    add_column_if_missing(conn, "nodes", "winn3_admission_json", "TEXT")
    # Standalone winn/3 plan registration (2026-08-10, ds_iosconfig3). Two
    # additive, nullable columns; NULL on every existing row reads as "this
    # node registered no plan", which for carrier=winn3 is a servability
    # refusal (it would be the empty-plan-handling defect re-shipped by the
    # control plane), never a silently-udp-only default.
    #
    #   path_mtu         the OUTER path MTU the plan floor is computed at. NULL
    #                    means carrier.DefaultPathMTU (1450), the fleet default
    #                    this hub shares with every host that resolves one.
    #   carrier_classes  the comma-separated migration plan -- every carrier
    #                    class the session may escalate TO, exactly the plan
    #                    the gateway runs. Stored as the same text the client
    #                    emits in `carrier_classes = udp,tcp,tls`.
    add_column_if_missing(conn, "nodes", "path_mtu", "INTEGER")
    add_column_if_missing(conn, "nodes", "carrier_classes", "TEXT")
    # Data-plane provenance (2026-08-09). Additive and nullable: every existing
    # row migrates to NULL, which reads as "this hub has never been told what
    # code this node runs" -- true, and the honest starting state. It is NOT
    # the same as the string 'unprovable', which a node writes when it was
    # asked and could not answer. Never part of NODE_IDENTITY_ATTRIBUTES, so it
    # can never participate in collision detection or node deletion, and no
    # selection path reads it: this column is evidence, not authority.
    add_column_if_missing(conn, "nodes", "data_plane_code_revision", "TEXT")
    add_column_if_missing(conn, "core_servers", "region", "TEXT")
    add_column_if_missing(conn, "core_servers", "management_host", "TEXT")
    add_column_if_missing(conn, "core_servers", "management_user", "TEXT DEFAULT 'ubuntu'")
    add_column_if_missing(conn, "core_servers", "management_status", "TEXT DEFAULT 'unknown'")
    add_column_if_missing(conn, "core_servers", "management_checked_at", "TEXT")
    add_column_if_missing(conn, "core_servers", "management_error", "TEXT")
    add_column_if_missing(conn, "core_servers", "ingress_endpoint", "TEXT")
    add_column_if_missing(conn, "core_servers", "tunnel_gateway_ipv4", "TEXT")
    add_column_if_missing(conn, "core_servers", "stealth_endpoint", "TEXT")
    add_column_if_missing(conn, "core_servers", "ingress_public_key", "TEXT")
    add_column_if_missing(conn, "core_servers", "exit_public_key", "TEXT")
    add_column_if_missing(conn, "core_servers", "xray_uuid", "TEXT")
    add_column_if_missing(conn, "core_servers", "xray_path", "TEXT DEFAULT '/wins-core-tunnel'")
    add_column_if_missing(conn, "core_servers", "xray_security", "TEXT DEFAULT 'none'")
    add_column_if_missing(conn, "core_servers", "stealth_transports", "TEXT DEFAULT '[]'")
    add_column_if_missing(conn, "core_servers", "regional_aliases", "TEXT DEFAULT '[]'")
    add_column_if_missing(conn, "core_servers", "direct_awg_enabled", "INTEGER NOT NULL DEFAULT 1")
    add_column_if_missing(conn, "core_servers", "status", "TEXT DEFAULT 'online'")
    add_column_if_missing(conn, "core_servers", "runtime_ready", "INTEGER NOT NULL DEFAULT 0")
    # Existing Core rows are unproven by definition. A hub upgrade therefore
    # darkens them until an authenticated operator supplies fresh gate evidence.
    add_column_if_missing(conn, "core_servers", "promoted", "INTEGER NOT NULL DEFAULT 0")
    add_column_if_missing(conn, "core_servers", "pending_promotion_id", "TEXT")
    add_column_if_missing(conn, "core_servers", "pending_promotion_evidence_sha256", "TEXT")
    add_column_if_missing(conn, "core_servers", "pending_promotion_operator_source_hash", "TEXT")
    add_column_if_missing(conn, "core_servers", "pending_promotion_requested_at", "TEXT")
    add_column_if_missing(conn, "core_servers", "active_promotion_id", "TEXT")
    add_column_if_missing(conn, "core_servers", "deployment_withdrawal_id", "TEXT")
    add_column_if_missing(conn, "core_servers", "deployment_withdrawn_at", "TEXT")
    add_column_if_missing(conn, "core_servers", "last_heartbeat", "TEXT")
    add_column_if_missing(conn, "core_servers", "runtime_checked_at", "TEXT")
    add_column_if_missing(conn, "core_servers", "core_token_hash", "TEXT")
    # SYNC-02: the core0 ingress profile the Core reports. NULL means an older
    # Core agent that never reported one (see _verify_account_sync).
    add_column_if_missing(conn, "core_servers", "obfuscation_json", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "core_id", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "exit_slug", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "client_public_key", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "client_ip", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "preshared_key", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "status", "TEXT DEFAULT 'active'")
    add_column_if_missing(conn, "double_vpn_assignments", "applied_revision", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "runtime_validated_at", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "assigned_at", "TEXT")
    add_column_if_missing(conn, "double_vpn_assignments", "updated_at", "TEXT")
    add_column_if_missing(conn, "core_exit_peers", "core_exit_ip", "TEXT")
    add_column_if_missing(conn, "core_exit_peers", "table_id", "INTEGER")
    add_column_if_missing(conn, "core_exit_peers", "iface", "TEXT")
    add_column_if_missing(conn, "core_exit_peers", "updated_at", "TEXT")
    add_column_if_missing(conn, "users", "paypal_subscription_id", "TEXT")
    add_column_if_missing(conn, "users", "paypal_plan_id", "TEXT")
    add_column_if_missing(conn, "users", "paypal_payer_id", "TEXT")
    add_column_if_missing(conn, "users", "paypal_status", "TEXT")
    add_column_if_missing(conn, "users", "paypal_purchase_reference", "TEXT")
    add_column_if_missing(conn, "users", "last_paypal_sync", "TEXT")
    add_column_if_missing(conn, "users", "renewal_source", "TEXT")
    add_column_if_missing(conn, "users", "referral_code", "TEXT")
    add_column_if_missing(conn, "users", "referred_by_account_number", "TEXT")
    add_column_if_missing(conn, "users", "referral_bonus_days", "INTEGER DEFAULT 0")
    add_column_if_missing(conn, "users", "referral_bonus_applied_at", "TEXT")
    # H-1: separates the low-entropy, routinely-shared account_number
    # (support lookups, on-screen display, email) from the actual
    # enrollment/rotation credential. Only ever stored hashed; the
    # plaintext is minted by issue_activation_secret and returned exactly
    # once per (re)issue for delivery over the account email.
    add_column_if_missing(conn, "users", "activation_secret_hash", "TEXT")
    add_column_if_missing(conn, "users", "activation_secret_expires_at", "TEXT")
    add_column_if_missing(conn, "users", "activation_secret_used_at", "TEXT")
    add_column_if_missing(conn, "devices", "hardware_hash", "TEXT")
    add_column_if_missing(conn, "devices", "source_ip_bucket", "TEXT")
    add_column_if_missing(conn, "devices", "updated_at", "TEXT")
    add_column_if_missing(conn, "devices", "device_auth_token_hash", "TEXT")
    # Owner ruling 2026-10-25 ("Key returns"): which setup key enrolled the
    # device, written in the transaction that consumed it. The slot (1 is the
    # users-row key, 2..N activation_extra_keys) and the stored secret_hash of
    # that slot at that moment; never the plaintext. NULL on a device enrolled
    # before the ruling, which therefore returns no key when it is removed.
    # activation_key_slot 0 marks a Double VPN Core enrolment that has not yet
    # spent its key (see record_device_activation_key). activation_key_bearer_hash
    # is the device bearer issued with the recorded key: a later enrolment, by
    # this build or an older one, rotates the bearer and so voids the record.
    add_column_if_missing(conn, "devices", "activation_key_slot", "INTEGER")
    add_column_if_missing(conn, "devices", "activation_key_hash", "TEXT")
    add_column_if_missing(conn, "devices", "activation_key_bearer_hash", "TEXT")
    # Winn Protocol v3 STANDALONE per-device material.
    #
    # These are NOT the AmneziaWG columns beside them and must never be
    # conflated with them. `winn3_static_private` is a SECOND X25519 identity:
    # reusing client_private_key would give one key material two protocols'
    # worth of exposure and would make a v3 compromise a v1 compromise, which
    # is exactly the coupling the standalone ruling removes
    # (apple/WinsTunnelCore/WinsWinn3SessionStart.swift:82-87).
    # `winn3_inner_v4` is likewise a SECOND address, in the gateway's inner
    # space rather than the AWG pool -- the v3 tun layer drops every packet
    # whose source does not match its assignment, so an AWG address here is a
    # session that starts, reports up, and carries nothing.
    add_column_if_missing(conn, "devices", "winn3_inner_v4", "TEXT")
    add_column_if_missing(conn, "devices", "winn3_static_private", "TEXT")
    add_column_if_missing(conn, "devices", "winn3_static_public", "TEXT")
    ensure_unique_winn3_inner_addresses(conn)
    ensure_unique_winn3_static_publics(conn)
    add_column_if_missing(conn, "payment_clicks", "referral_code", "TEXT")
    add_column_if_missing(conn, "payment_clicks", "referrer_account_number", "TEXT")
    # L-1: lease column backing the atomic idempotency claim in
    # reserve_paypal_event. A row left 'processing' by a crashed handler becomes
    # reclaimable only once its lease_until has elapsed; a live lease blocks a
    # concurrent second claim of the same event.
    add_column_if_missing(conn, "paypal_events", "lease_until", "TEXT")
    # M-4 / M-6: poll claim lease + persisted price-quote provenance on existing
    # monero_orders databases created before these columns shipped.
    add_column_if_missing(conn, "monero_orders", "lease_until", "TEXT")
    add_column_if_missing(conn, "monero_orders", "quote_usd_per_xmr", "TEXT DEFAULT ''")
    add_column_if_missing(conn, "monero_orders", "quote_source", "TEXT DEFAULT ''")
    add_column_if_missing(conn, "monero_orders", "quote_at", "TEXT")

    # Migrate the split-script settings table if it exists. ensure_schema runs
    # on ordinary requests, so import only keys the current table lacks: a
    # legacy value must never replace a setting changed after the import.
    if table_exists(conn, "systemsettings"):
        for row in conn.execute("SELECT key, value FROM systemsettings").fetchall():
            key = row["key"]
            if key == "globalannouncement":
                key = "global_announcement"
            elif key == "maintenancemode":
                key = "maintenance_mode"
            conn.execute(
                "INSERT OR IGNORE INTO system_settings (key, value) VALUES (?, ?)",
                (key, row["value"]),
            )

    conn.execute("INSERT OR IGNORE INTO system_settings (key, value) VALUES (?, ?)", ("global_announcement", WELCOME_MESSAGE_DEFAULT))
    conn.execute("INSERT OR IGNORE INTO system_settings (key, value) VALUES (?, ?)", ("maintenance_mode", "false"))
    conn.execute("INSERT OR IGNORE INTO system_settings (key, value) VALUES (?, ?)", ("double_vpn_free_access_enabled", "true" if DOUBLE_VPN_FREE_ACCESS_ENABLED else "false"))
    # Owner ruling 2026-10-13: Double VPN is for paid accounts only. A hub that
    # already holds the release's seeded 'true' keeps it through INSERT OR IGNORE,
    # so flip it once; the marker lets an admin turn it back on afterwards.
    if get_setting(conn, "double_vpn_free_paid_only_applied", "false") != "true":
        set_setting(conn, "double_vpn_free_access_enabled", "false")
        set_setting(conn, "double_vpn_free_paid_only_applied", "true")
    if get_setting(conn, "free_access_flags_seeded", "false") != "true":
        for row in conn.execute("SELECT slug, name, endpoint, ssh_host FROM nodes").fetchall():
            if node_matches_free_access_defaults(row["slug"] or "", row["name"] or "", row["endpoint"] or "", row["ssh_host"] or ""):
                conn.execute("UPDATE nodes SET free_access_enabled = 1 WHERE slug = ?", (row["slug"],))
        set_setting(conn, "free_access_flags_seeded", "true")
    if DOUBLE_VPN_CORE_INGRESS_ENDPOINT and DOUBLE_VPN_CORE_INGRESS_PUBLIC_KEY and DOUBLE_VPN_CORE_EXIT_PUBLIC_KEY:
        # The env seed only creates an absent, dark Core row. ensure_schema runs
        # on ordinary requests, and an existing row belongs to the Core's
        # authenticated register_core: a seed must never overwrite it.
        conn.execute("""
            INSERT INTO core_servers (
                core_id, name, region, ingress_endpoint, stealth_endpoint,
                ingress_public_key, exit_public_key, xray_uuid, xray_path,
                xray_security, stealth_transports, status, runtime_ready,
                last_heartbeat, runtime_checked_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'maintenance', 0, NULL, NULL)
            ON CONFLICT(core_id) DO NOTHING
        """, (
            DOUBLE_VPN_CORE_ID,
            DOUBLE_VPN_CORE_NAME,
            DOUBLE_VPN_CORE_REGION,
            DOUBLE_VPN_CORE_INGRESS_ENDPOINT,
            DOUBLE_VPN_CORE_STEALTH_ENDPOINT,
            DOUBLE_VPN_CORE_INGRESS_PUBLIC_KEY,
            DOUBLE_VPN_CORE_EXIT_PUBLIC_KEY,
            DOUBLE_VPN_CORE_XRAY_UUID,
            DOUBLE_VPN_CORE_XRAY_PATH,
            DOUBLE_VPN_CORE_XRAY_SECURITY,
            json.dumps(parse_xray_transports(
                DOUBLE_VPN_CORE_STEALTH_TRANSPORTS,
                split_host_port(DOUBLE_VPN_CORE_STEALTH_ENDPOINT, 80)[1],
                DOUBLE_VPN_CORE_XRAY_SECURITY,
                keep_plaintext=True,
            )),
        ))
    conn.execute("CREATE INDEX IF NOT EXISTS idx_devices_account_number ON devices(account_number)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_devices_account_hardware ON devices(account_number, hardware_hash)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_devices_last_seen ON devices(account_number, last_seen)")
    # P-8 (node_v3_sessions_full) and node_capacity_snapshot count a node's devices by location_slug.
    conn.execute("CREATE INDEX IF NOT EXISTS idx_devices_location_slug ON devices(location_slug)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_nodes_status ON nodes(status)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_nodes_free_access ON nodes(free_access_enabled, status)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_core_servers_status ON core_servers(status)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_double_vpn_assignments_core_exit ON double_vpn_assignments(core_id, exit_slug, status)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_double_vpn_assignments_account ON double_vpn_assignments(account_number)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_core_exit_peers_core ON core_exit_peers(core_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_users_paypal_subscription_id ON users(paypal_subscription_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_users_paypal_purchase_reference ON users(paypal_purchase_reference)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_paypal_events_subscription_id ON paypal_events(paypal_subscription_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_paypal_events_status ON paypal_events(status)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_monero_orders_status ON monero_orders(status, created_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_payment_orders_provider_order ON payment_orders(provider, provider_order_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_payment_orders_status_created ON payment_orders(status, created_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_payment_clicks_clicked_at ON payment_clicks(clicked_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_payment_clicks_option_source ON payment_clicks(option_key, source)")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_users_referral_code ON users(referral_code) WHERE referral_code IS NOT NULL AND referral_code != ''")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_users_referred_by ON users(referred_by_account_number)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_payment_clicks_referral_code ON payment_clicks(referral_code)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_referral_rewards_referrer ON referral_rewards(referrer_account_number)")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_referral_rewards_purchase_reference ON referral_rewards(purchase_reference) WHERE purchase_reference IS NOT NULL AND purchase_reference != ''")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_free_access_events_created_at ON free_access_events(created_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_free_access_events_device ON free_access_events(device_id_bucket)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_free_access_events_source ON free_access_events(source_ip_bucket)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_legal_acceptances_account ON legal_acceptances(account_number)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_legal_acceptances_device ON legal_acceptances(device_id_bucket)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_legal_acceptances_document ON legal_acceptances(document_version, document_hash)")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_legal_acceptances_unique_current ON legal_acceptances(account_number, device_id_bucket, document_version, document_hash)")
    conn.execute("""
        INSERT INTO legal_documents (version, document_hash, title, body_text, effective_date, is_current, created_at)
        VALUES (?, ?, ?, ?, ?, 1, ?)
        ON CONFLICT(version) DO UPDATE SET
            document_hash=excluded.document_hash,
            title=excluded.title,
            body_text=excluded.body_text,
            effective_date=excluded.effective_date,
            is_current=1
        WHERE legal_documents.document_hash IS NOT excluded.document_hash
           OR legal_documents.title IS NOT excluded.title
           OR legal_documents.body_text IS NOT excluded.body_text
           OR legal_documents.effective_date IS NOT excluded.effective_date
           OR legal_documents.is_current IS NOT 1
    """, (
        LEGAL_DOCUMENT_VERSION,
        LEGAL_DOCUMENT_HASH,
        LEGAL_DOCUMENT_TITLE,
        LEGAL_DOCUMENT_TEXT,
        LEGAL_EFFECTIVE_DATE,
        utcnow().isoformat(),
    ))
    # Migrate the legacy snapshot once. Later missing expirations must fail closed.
    if not table_exists(conn, "users_pre_lifetime_migration_2025"):
        migrate_legacy_lifetime(conn)
    create_winn3_registry_refresh_table(conn)
    create_winn3_departure_grant_table(conn)
    create_winn3_node_key_digests_table(conn)
    # The backfills run after every column they read exists; the retention
    # work last, as before.
    _schema_row_backfills(conn)
    _schema_maintenance(conn)

def get_setting(conn: sqlite3.Connection, key: str, default: str) -> str:
    row = conn.execute("SELECT value FROM system_settings WHERE key = ?", (key,)).fetchone()
    return row["value"] if row else default

def set_setting(conn: sqlite3.Connection, key: str, value: str):
    conn.execute("""
        INSERT INTO system_settings (key, value) VALUES (?, ?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value
    """, (key, value))

def setting_bool(conn: sqlite3.Connection, key: str, default: bool = False) -> bool:
    fallback = "true" if default else "false"
    return get_setting(conn, key, fallback).strip().lower() in {"1", "true", "yes", "on"}

def double_vpn_free_access_enabled(conn: sqlite3.Connection) -> bool:
    # Owner ruling 2026-10-13: Double VPN is for paid accounts only. The legacy
    # stored setting (and the admin route that writes it) stay so nothing else
    # changes, but they are INERT: no flag may serve Double VPN, relay or
    # AmneziaWG, to a free account, and every surface that reports this value to
    # a client must say false. The stored value is therefore never read here.
    return False

# --- Announcement authenticity (Ed25519) ----------------------------------
#
# /admin/announce is gated only by require_admin_token, one fleet-wide shared
# secret. Possession of that token is enough to push arbitrary text to every
# installed app inside ~60 seconds. A detached Ed25519 signature the client
# verifies against a public key compiled into the signed app is the only
# control that makes a leaked admin token insufficient.
#
# Why the openssl CLI rather than a Python library: server/control-plane-
# requirements.lock is a hash-pinned, pip-compile-generated lock and
# `cryptography` is NOT in it -- the same constraint already documented at
# seal_fulfillment_secret. Adding a dependency there means regenerating the
# lock on linux/amd64 with network access, which is a separate, reviewable
# supply-chain change and not something to smuggle in behind an announcement.
# openssl(1) is already an apt dependency of this installer and the Ubuntu
# 24.04 target ships OpenSSL 3.x with Ed25519, so this uses a well-audited
# constant-time implementation rather than a hand-rolled pure-Python one.
#
# WHERE THE KEY LIVES (Fable 5.1 ruling 2026-09-29, IA-CP-06): NOT HERE.
# Announcements are signed OFFLINE by tools/winn3_sign_announcement.py,
# exactly like descriptors (tools/winn3_sign_descriptor.py). The hub holds only
# the a1..a3 PUBLIC keys (ANNOUNCE_PUBKEY_A1..A3 in the unit EnvironmentFile),
# verifies an uploaded envelope, enforces a strictly increasing sequence, and
# stores the envelope verbatim. A seized hub yields three public keys, one
# verified envelope and a sequence number: nothing that writes to the channel.
#
# Cost: one verification per admin post, never on a client-facing request.
# The four polled routes serve a stored string and do no crypto at all.
ANNOUNCE_SIGNATURE_DOMAIN = b"winsvpn-announcement/v1"
# a1..a3, disjoint from the descriptor (g1..g3) and discovery (d1..d3)
# families. Same slots the client compiles in (lib/announcement_signature.dart).
ANNOUNCE_KEY_SLOTS = ("a1", "a2", "a3")
# RFC 8410 SubjectPublicKeyInfo prefix for a raw Ed25519 public key; the same
# bytes as WINN3_ED25519_SPKI_PREFIX, kept local so this block stands alone.
ANNOUNCE_ED25519_SPKI_PREFIX = bytes.fromhex("302a300506032b6570032100")
# The client's own ceilings (lib/announcement_signature.dart): 8192 payload
# bytes before the signature is checked, and 900 rendered characters.
ANNOUNCE_MAX_PAYLOAD_BYTES = 8192
ANNOUNCE_MAX_TEXT_CHARS = 900
# The exact payload fields the offline tool signs and the client reads.
ANNOUNCE_PAYLOAD_FIELDS = frozenset({"kid", "seq", "iat", "text"})
# While 0 (default) the plaintext `msg` form still posts, unsigned, so a hub
# upgrade alone never blocks an urgent notice. Flip to 1 only after a signed
# post has been served on all four routes and verified with the public key
# only, and the a1 private key plus the a2/a3 successors are in offline
# custody (ruling, Q2 Step 4).
ANNOUNCE_REQUIRE_SIGNED = os.getenv(
    "ANNOUNCE_REQUIRE_SIGNED", "0"
).strip().lower() in {"1", "true", "yes", "on"}
# Largest sequence every client platform represents exactly (JS safe integer).
ANNOUNCE_MAX_SEQ = 2 ** 53 - 1


class AnnouncementContractError(Exception):
    """An uploaded announcement envelope the hub refuses. Carries a reason
    string only, never payload bytes or text."""

    def __init__(self, reason: str):
        super().__init__(reason)
        self.reason = reason


def announcement_public_keys() -> dict:
    """slot -> raw 32-byte Ed25519 public key, from ANNOUNCE_PUBKEY_A1..A3.

    Same rule as winn3_descriptor_public_keys: a slot that is set but unusable
    is DROPPED, so a typo degrades to "that key does not exist", never to a
    verifier that accepts something it should not.
    """
    keys: dict = {}
    for slot in ANNOUNCE_KEY_SLOTS:
        encoded = (os.getenv(f"ANNOUNCE_PUBKEY_{slot.upper()}") or "").strip()
        if not encoded:
            continue
        try:
            raw = base64.b64decode(encoded, validate=True)
        except Exception:
            continue
        if len(raw) == 32:
            keys[slot] = raw
    return keys


def verify_announcement_signature(payload: bytes, signature: bytes, kid: str) -> str:
    """Verify DOMAIN || 0x00 || payload under the slot named by `kid`.

    Returns the accepting slot. Raises AnnouncementContractError otherwise.
    openssl(1), for the lock-file reason recorded above.
    """
    slot = (kid or "").strip().lower()
    if slot not in ANNOUNCE_KEY_SLOTS:
        raise AnnouncementContractError("announcement-unknown-key-slot")
    if len(signature) != 64:
        raise AnnouncementContractError("announcement-signature-length")
    ring = announcement_public_keys()
    if not ring:
        raise AnnouncementContractError("announcement-no-verification-keys-configured")
    raw = ring.get(slot)
    if raw is None:
        raise AnnouncementContractError("announcement-key-slot-not-provisioned")
    message = ANNOUNCE_SIGNATURE_DOMAIN + b"\x00" + payload
    with tempfile.TemporaryDirectory() as work_dir:
        key_path = os.path.join(work_dir, "announce.der")
        msg_path = os.path.join(work_dir, "announce.bin")
        sig_path = os.path.join(work_dir, "announce.sig")
        with open(key_path, "wb") as handle:
            handle.write(ANNOUNCE_ED25519_SPKI_PREFIX + raw)
        with open(msg_path, "wb") as handle:
            handle.write(message)
        with open(sig_path, "wb") as handle:
            handle.write(signature)
        completed = subprocess.run(
            [
                "openssl", "pkeyutl", "-verify", "-rawin", "-pubin",
                "-inkey", key_path, "-keyform", "DER",
                "-sigfile", sig_path, "-in", msg_path,
            ],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15,
        )
    if completed.returncode != 0:
        raise AnnouncementContractError("announcement-signature-invalid")
    return slot


def validate_announcement_payload(payload_bytes: bytes) -> dict:
    """The decoded payload, held to the shape the client accepts.

    Exactly kid/seq/iat/text; seq and iat JSON integers (not booleans), seq
    positive; text a non-blank string within the client's render cap.
    """
    if not payload_bytes or len(payload_bytes) > ANNOUNCE_MAX_PAYLOAD_BYTES:
        raise AnnouncementContractError("announcement-payload-size")
    try:
        decoded = json.loads(payload_bytes.decode("utf-8"))
    except Exception:
        raise AnnouncementContractError("announcement-payload-not-json") from None
    if not isinstance(decoded, dict) or set(decoded) != ANNOUNCE_PAYLOAD_FIELDS:
        raise AnnouncementContractError("announcement-payload-fields")
    kid, seq, iat, text = decoded["kid"], decoded["seq"], decoded["iat"], decoded["text"]
    if not isinstance(kid, str) or kid not in ANNOUNCE_KEY_SLOTS:
        raise AnnouncementContractError("announcement-unknown-key-slot")
    if isinstance(seq, bool) or not isinstance(seq, int) or not 1 <= seq <= ANNOUNCE_MAX_SEQ:
        raise AnnouncementContractError("announcement-seq-invalid")
    if isinstance(iat, bool) or not isinstance(iat, int) or iat < 0:
        raise AnnouncementContractError("announcement-iat-invalid")
    if not isinstance(text, str) or not text.strip():
        raise AnnouncementContractError("announcement-text-empty")
    if len(text) > ANNOUNCE_MAX_TEXT_CHARS:
        raise AnnouncementContractError("announcement-text-too-long")
    return decoded


def announcement_sequence_floor(conn: sqlite3.Connection) -> int:
    try:
        return max(0, int(get_setting(conn, "global_announcement_seq", "0") or "0"))
    except ValueError:
        return 0


def store_verified_announcement(
    conn: sqlite3.Connection, payload_b64: str, sig_b64: str
) -> tuple:
    """Verify an offline-signed envelope and store it verbatim.

    Returns (seq, kid). Every check runs BEFORE anything is written, so a
    refusal leaves the previous announcement and its envelope untouched. The
    plaintext `global_announcement` is set to the VERIFIED text, so clients
    that predate signing keep seeing the same words.
    """
    payload_b64 = (payload_b64 or "").strip()
    sig_b64 = (sig_b64 or "").strip()
    if not payload_b64 or not sig_b64:
        raise AnnouncementContractError("announcement-envelope-incomplete")
    try:
        payload_bytes = base64.b64decode(payload_b64, validate=True)
        signature = base64.b64decode(sig_b64, validate=True)
    except Exception:
        raise AnnouncementContractError("announcement-envelope-not-base64") from None
    decoded = validate_announcement_payload(payload_bytes)
    slot = verify_announcement_signature(payload_bytes, signature, decoded["kid"])
    seq = int(decoded["seq"])
    if seq <= announcement_sequence_floor(conn):
        # Strictly increasing, and the floor is never lowered (the unsigned
        # path below leaves it in place), so a leaked admin token cannot
        # re-post an older signed envelope.
        raise AnnouncementContractError("announcement-seq-not-increasing")
    set_setting(conn, "global_announcement", decoded["text"])
    set_setting(conn, "global_announcement_payload", base64.b64encode(payload_bytes).decode())
    set_setting(conn, "global_announcement_sig", base64.b64encode(signature).decode())
    set_setting(conn, "global_announcement_seq", str(seq))
    return seq, slot


def store_unsigned_announcement(conn: sqlite3.Connection, text: str) -> None:
    """Pre-ceremony plaintext post (ANNOUNCE_REQUIRE_SIGNED=0 only).

    The envelope is CLEARED rather than left in place: a stale signature over
    older text would let enforcing clients keep showing the PREVIOUS
    announcement as authentic after the owner had replaced it. The sequence
    floor is kept, so clearing never reopens a replay.
    """
    set_setting(conn, "global_announcement", text)
    set_setting(conn, "global_announcement_payload", "")
    set_setting(conn, "global_announcement_sig", "")


def announcement_fields(conn: sqlite3.Connection) -> dict:
    """The announcement half of every client-facing response.

    One helper for all four polled routes -- /nodes, /account/status, /verify
    and /free/status -- because if one route carried a signature and another
    carried bare text, clients would flip between valid and invalid depending
    on which call happened last.

    The plaintext "announcement" field is kept unchanged and unconditionally,
    so already-shipped clients are completely unaffected by this change.
    """
    fields = {
        "announcement": get_setting(conn, "global_announcement", WELCOME_MESSAGE_DEFAULT),
    }
    payload = get_setting(conn, "global_announcement_payload", "")
    signature = get_setting(conn, "global_announcement_sig", "")
    if payload and signature:
        fields["announcement_signed"] = {"payload": payload, "sig": signature}
    return fields

def normalize_account_number(raw: Any) -> str:
    digits = "".join(filter(str.isdigit, str(raw or "")))
    return f"{digits[0:4]}-{digits[4:8]}-{digits[8:12]}" if len(digits) == 12 else str(raw or "").strip()

def request_origin_bucket_value(request: Request) -> str:
    return _trusted_forwarded_client_ip(request) or (request.client.host if request.client else "unknown")

def device_identity_bucket(value: Any) -> str:
    raw = str(value or "").strip()[:256]
    if not raw:
        return ""
    return security_event_hash(f"device-identity:{raw}")

def rate_limit_bucket(label: str, value: Any) -> str:
    digest = hmac.new(RATE_LIMIT_SECRET.encode(), str(value or "").encode(), hashlib.sha256).hexdigest()
    return f"{label}:{digest[:40]}"

def check_rate_limit(conn: sqlite3.Connection, bucket: str, limit: int, window_seconds: int):
    if limit <= 0:
        return
    now = time.time()
    # A prior SELECT-then-UPDATE here let concurrent requests on the same
    # bucket all read the pre-increment count and pass the limit check
    # before any of their writes landed, letting a burst of parallel
    # requests exceed `limit` (M-5). INSERT .. ON CONFLICT DO UPDATE ..
    # RETURNING is a single statement that SQLite executes indivisibly
    # against the committed row, so the increment and the value the limit
    # check sees can never be split across two connections' requests.
    row = conn.execute(
        """
        INSERT INTO rate_limits (bucket, count, reset_at) VALUES (?, 1, ?)
        ON CONFLICT(bucket) DO UPDATE SET
          count = CASE WHEN rate_limits.reset_at <= ? THEN 1 ELSE rate_limits.count + 1 END,
          reset_at = CASE WHEN rate_limits.reset_at <= ? THEN excluded.reset_at ELSE rate_limits.reset_at END
        RETURNING count
        """,
        (bucket, now + window_seconds, now, now),
    ).fetchone()
    # Opportunistic, low-overhead eviction of long-expired buckets instead of
    # an unconditional DELETE on every call: keeps the table from growing
    # without bound as new high-cardinality bucket keys (e.g. per-IP) appear.
    if secrets.randbelow(128) == 0:
        conn.execute("DELETE FROM rate_limits WHERE reset_at < ?", (now - 3600,))
    if int(row["count"]) > limit:
        raise HTTPException(status_code=429, detail="Too many attempts. Please wait and try again.")

# --- C3: two layers, and only one of them counts requests -------------------
# EDGE/WAF load shedding counts ALL HTTP requests. That layer is nginx
# (limit_req, below) and the Cloudflare Worker; it exists to keep the box up.
#
# APPLICATION AUTHENTICATION BACKOFF counts ONLY genuine credential and
# redemption FAILURES. It exists to slow credential guessing, and it must never
# be consumed by a malformed request, a network error, a successful redemption,
# an idempotent recovery, an acknowledgement, or a normal bearer reconnect.
#
# WHY THIS IS NOT A STYLE PREFERENCE: consuming an auth bucket on success means
# every client behind one carrier-grade NAT egress, one university, or one
# corporate network shares a budget that their SUCCESSFUL reconnects exhaust.
# That is a self-inflicted outage for exactly the users who did nothing wrong,
# and no attacker is slowed by it.
#
# The shape is: read-only precheck (cheap, non-consuming, rejects an ALREADY
# exhausted bucket) -> do the work -> determine the outcome -> and only on a
# genuine failure, atomically consume.
def rate_limit_current_count(conn: sqlite3.Connection, bucket: str) -> int:
    # Read-only. An expired window reads as zero without rewriting the row:
    # a precheck must never have a side effect, or it is not a precheck.
    row = conn.execute(
        "SELECT count, reset_at FROM rate_limits WHERE bucket = ?", (bucket,)
    ).fetchone()
    if not row:
        return 0
    try:
        if float(row["reset_at"]) <= time.time():
            return 0
    except (TypeError, ValueError):
        return 0
    try:
        return int(row["count"])
    except (TypeError, ValueError):
        return 0

def precheck_rate_limit(conn: sqlite3.Connection, bucket: str, limit: int):
    # Optional read-only precheck for an ALREADY-exhausted bucket. Lets a
    # caller that has already burned its failure budget be rejected before the
    # endpoint does expensive work, without that rejection itself counting.
    if limit <= 0:
        return
    if rate_limit_current_count(conn, bucket) >= limit:
        raise HTTPException(status_code=429, detail="Too many attempts. Please wait and try again.")

def consume_auth_failure(conn: sqlite3.Connection, bucket: str, limit: int, window_seconds: int):
    # Atomic consume, AFTER failure has been determined. Reuses the same single
    # INSERT .. ON CONFLICT .. RETURNING primitive, so concurrent failures on
    # one bucket still cannot split the increment from the limit check (M-5).
    check_rate_limit(conn, bucket, limit, window_seconds)

def enforce_verify_rate_limits(conn: sqlite3.Connection, request: Request, account_number: str):
    # C3: READ-ONLY PRECHECK. This used to consume both buckets on every call,
    # at the top of /verify, before any credential was examined -- so an
    # ordinary bearer-token reconnect that SUCCEEDED still burned budget. Behind
    # carrier-grade NAT that made the per-IP bucket a shared quota which normal
    # traffic exhausted on its own.
    #
    # Nothing is consumed here. The bucket is consumed by
    # consume_verify_auth_failure() once a genuine credential failure is known.
    precheck_rate_limit(
        conn,
        rate_limit_bucket("verify-ip", request_origin_bucket_value(request)),
        VERIFY_IP_RATE_LIMIT_PER_MINUTE,
    )
    if account_number:
        precheck_rate_limit(
            conn,
            rate_limit_bucket("verify-account", account_number),
            VERIFY_ACCOUNT_RATE_LIMIT_PER_HOUR,
        )

def consume_verify_auth_failure(conn: sqlite3.Connection, request: Request, account_number: str):
    # Called ONLY for a genuine credential failure on /verify -- an account
    # number that does not exist, or a bearer token that does not match. NOT
    # called for a malformed request, an inactive or expired account (the
    # credential was correct; that is business state, and charging a legitimate
    # user's retries for it is the same self-inflicted outage), a device-limit
    # rejection, or any successful reconnect.
    try:
        consume_auth_failure(
            conn,
            rate_limit_bucket("verify-ip", request_origin_bucket_value(request)),
            VERIFY_IP_RATE_LIMIT_PER_MINUTE,
            60,
        )
        if account_number:
            consume_auth_failure(
                conn,
                rate_limit_bucket("verify-account", account_number),
                VERIFY_ACCOUNT_RATE_LIMIT_PER_HOUR,
                3600,
            )
    except HTTPException:
        # The consume tripped the limit. The caller is about to raise its own
        # 401 anyway; commit the increment so it is not rolled back, then let
        # the original credential failure be what the caller sees.
        conn.commit()
        raise
    conn.commit()

def enforce_free_verify_rate_limits(conn: sqlite3.Connection, request: Request, device_id: str):
    check_rate_limit(
        conn,
        rate_limit_bucket("free-verify-ip", request_origin_bucket_value(request)),
        FREE_VERIFY_IP_RATE_LIMIT_PER_MINUTE,
        60,
    )
    if device_id:
        check_rate_limit(
            conn,
            rate_limit_bucket("free-verify-device", device_id),
            FREE_VERIFY_DEVICE_RATE_LIMIT_PER_HOUR,
            3600,
        )
    # Persist the increments now: get_db() rolls back on any later handler
    # failure (no free node, maintenance, collision), which would otherwise
    # refund this attempt and let a failing shape retry without limit. The
    # sole caller runs this before any admission write, so committing here
    # only seals ensure_schema and the buckets.
    conn.commit()

def free_identity_for_device(device_id: str) -> tuple[str, str, str]:
    raw = str(device_id or "").strip()[:256] or "unknown"
    digest = hmac.new(RATE_LIMIT_SECRET.encode(), f"free-access:{raw}".encode(), hashlib.sha256).hexdigest()
    synthetic_device_id = f"free-{digest[:32]}"
    fingerprint = f"free:{digest[:32]}"
    return FREE_ACCESS_ACCOUNT_NUMBER, synthetic_device_id, fingerprint

def record_free_access_event(
    conn: sqlite3.Connection,
    request: Request,
    action: str,
    account_number: str,
    device_id_bucket: str,
    client_public_key: str,
    platform: str,
    device_model: str,
    node_slug: str,
    stealth_mode: bool,
):
    conn.execute("""
        INSERT INTO free_access_events (
            action, account_number, device_id_bucket, source_ip_bucket,
            client_public_key_fingerprint, platform, device_model, node_slug,
            stealth_mode, user_agent_hash, created_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        action,
        account_number,
        device_id_bucket,
        security_event_hash(request_origin_bucket_value(request)),
        key_fingerprint(client_public_key),
        str(platform or "unknown")[:64],
        str(device_model or "Device")[:128],
        str(node_slug or "")[:128],
        1 if stealth_mode else 0,
        security_event_hash(request.headers.get("user-agent", "")),
        utcnow().isoformat(),
    ))

def current_legal_payload(locale: str = "en", compact: bool = False) -> dict:
    payload = {
        "status": "ok",
        "title": LEGAL_DOCUMENT_TITLE,
        "version": LEGAL_DOCUMENT_VERSION,
        "document_version": LEGAL_DOCUMENT_VERSION,
        "hash": LEGAL_DOCUMENT_HASH,
        "document_hash": LEGAL_DOCUMENT_HASH,
        "effective_date": LEGAL_EFFECTIVE_DATE,
        "controlling_language": "en",
        "translations_notice": "English is the controlling legal version. Translations are for convenience only.",
        "operator": "Win's VPN Inc.",
        "builder": "Win Empire LLC",
        "urls": {
            "terms": LEGAL_TERMS_URL,
            "privacy": LEGAL_PRIVACY_URL,
            "billing": LEGAL_BILLING_URL,
            "trusted_contact": LEGAL_TRUSTED_CONTACT_URL,
            "vulnerability_disclosure": LEGAL_VDP_URL,
            "hold_harmless": LEGAL_HOLD_HARMLESS_URL,
            "limitation_of_liability": LEGAL_LIMITATION_URL,
        },
        "acceptance_statements": [
            "I agree to the Terms of Service.",
            "I agree to the Hold Harmless Agreement.",
            "I agree to the Limitation of Liability.",
            "I consent to receive service records electronically.",
        ],
    }
    if not compact:
        payload["body_text"] = LEGAL_DOCUMENT_TEXT
        payload["display_body_text"] = localized_legal_display_text(locale)
    return payload

def legal_device_bucket(device_id: Any) -> str:
    return security_event_hash(f"legal-device:{str(device_id or '').strip()[:256]}")

def legal_source_bucket(request: Request) -> str:
    return security_event_hash(f"legal-source:{request_origin_bucket_value(request)}")

def legal_payload_is_current(version: str, document_hash: str) -> bool:
    v = str(version or "").strip()
    if v not in LEGAL_DOCUMENT_ACCEPTED_VERSIONS:
        return False
    supplied_hash = str(document_hash or "").strip()
    return not supplied_hash or supplied_hash in LEGAL_DOCUMENT_ACCEPTED_HASHES

def legal_acceptance_flags_ok(payload: Any) -> bool:
    base_flags_ok = bool(
        getattr(payload, "accepted_terms", False)
        and getattr(payload, "accepted_hold_harmless", False)
        and getattr(payload, "accepted_limitation_liability", False)
        and getattr(payload, "accepted_electronic_records", False)
    )
    if not base_flags_ok:
        return False
    if str(getattr(payload, "platform", "") or "").strip().lower() != "android":
        return True
    if not getattr(payload, "accepted_android_vpn_service_disclosure", False):
        return False
    disc_ver = str(getattr(payload, "android_vpn_service_disclosure_version", "") or "").strip()
    if disc_ver not in ANDROID_VPN_SERVICE_DISCLOSURE_ACCEPTED_VERSIONS:
        return False
    disc_at_raw = str(getattr(payload, "android_vpn_service_disclosure_accepted_at", "") or "").strip()
    if not disc_at_raw:
        return disc_ver == "2026-07-20.v2"
    try:
        accepted_at = datetime.fromisoformat(disc_at_raw.replace("Z", "+00:00"))
    except ValueError:
        return False
    return accepted_at.tzinfo is not None

def legal_signature_material(row: dict) -> str:
    fields = {
        "acceptance_id": row.get("acceptance_id") or "",
        "account_number": normalize_account_number(row.get("account_number") or ""),
        "email": (row.get("email") or "").strip().lower(),
        "device_id_bucket": row.get("device_id_bucket") or "",
        "source_ip_bucket": row.get("source_ip_bucket") or "",
        "user_agent_hash": row.get("user_agent_hash") or "",
        "platform": row.get("platform") or "",
        "app_version": row.get("app_version") or "",
        "locale": row.get("locale") or "",
        "acceptance_method": row.get("acceptance_method") or LEGAL_ACCEPTANCE_METHOD_DEFAULT,
        "document_version": row.get("document_version") or "",
        "document_hash": row.get("document_hash") or "",
        "accepted_terms": int(row.get("accepted_terms") or 0),
        "accepted_hold_harmless": int(row.get("accepted_hold_harmless") or 0),
        "accepted_limitation_liability": int(row.get("accepted_limitation_liability") or 0),
        "accepted_electronic_records": int(row.get("accepted_electronic_records") or 0),
        "accepted_android_vpn_service_disclosure": int(row.get("accepted_android_vpn_service_disclosure") or 0),
        "android_vpn_service_disclosure_version": row.get("android_vpn_service_disclosure_version") or "",
        "android_vpn_service_disclosure_accepted_at": row.get("android_vpn_service_disclosure_accepted_at") or "",
        "accepted_at": row.get("accepted_at") or "",
    }
    return json.dumps(fields, sort_keys=True, separators=(",", ":"))

def legal_acceptance_signature(row: dict) -> str:
    return hmac.new(
        LEGAL_ACCEPTANCE_HMAC_KEY.encode(),
        legal_signature_material(row).encode(),
        hashlib.sha256,
    ).hexdigest()

def legal_acceptance_signature_valid(row: sqlite3.Row) -> bool:
    data = dict(row)
    expected = legal_acceptance_signature(data)
    return hmac.compare_digest(expected, data.get("signature_hmac") or "")

def has_current_legal_acceptance(conn: sqlite3.Connection, account_number: str, device_id: str) -> bool:
    rows = conn.execute(
        """
        SELECT * FROM legal_acceptances
        WHERE account_number = ?
          AND device_id_bucket = ?
          AND document_version IN (?, ?)
          AND document_hash IN (?, ?, ?)
          AND accepted_terms = 1
          AND accepted_hold_harmless = 1
          AND accepted_limitation_liability = 1
          AND accepted_electronic_records = 1
        ORDER BY accepted_at DESC
        LIMIT 5
        """,
        (
            normalize_account_number(account_number),
            legal_device_bucket(device_id),
            LEGAL_DOCUMENT_VERSION,
            "2026-07-21.v1",
            LEGAL_DOCUMENT_HASH,
            LEGAL_DOCUMENT_HASH_SUPERSEDED_20260721,
            "6a031f0b4112ac49b16dec8a074c2b56bbfa6e5a02c2536e4be2ac886a9ee041",
        ),
    ).fetchall()
    for row in rows:
        data = dict(row)
        if str(data.get("platform") or "").strip().lower() == "android":
            if not int(data.get("accepted_android_vpn_service_disclosure") or 0):
                continue
            disc_ver = str(data.get("android_vpn_service_disclosure_version") or "").strip()
            if disc_ver not in ANDROID_VPN_SERVICE_DISCLOSURE_ACCEPTED_VERSIONS:
                continue
            if not str(data.get("android_vpn_service_disclosure_accepted_at") or ""):
                if disc_ver != "2026-07-20.v2":
                    continue
        if legal_acceptance_signature_valid(row):
            return True
    return False

def record_legal_acceptance(
    conn: sqlite3.Connection,
    request: Request,
    payload: Any,
    account_number: str,
    email: str = "",
    device_id: str = "",
) -> str:
    acc = normalize_account_number(account_number or getattr(payload, "account_number", ""))
    dev = device_id or getattr(payload, "device_id", "")
    if not acc or not dev:
        raise HTTPException(status_code=400, detail="Legal acceptance requires account and device identity.")
    if not legal_payload_is_current(getattr(payload, "legal_version", ""), getattr(payload, "legal_hash", "")):
        raise HTTPException(status_code=409, detail="Legal terms changed. Please review the current terms and try again.")
    if not legal_acceptance_flags_ok(payload):
        raise HTTPException(status_code=451, detail="Legal acceptance is required before activation.")

    accepted_at = utcnow().isoformat()
    row = {
        "acceptance_id": f"wa-{secrets.token_hex(16)}",
        "account_number": acc,
        "email": (email or getattr(payload, "email", "") or "").strip().lower()[:256],
        "device_id_bucket": legal_device_bucket(dev),
        "source_ip_bucket": legal_source_bucket(request),
        "user_agent_hash": security_event_hash(request.headers.get("user-agent", "")),
        "platform": str(getattr(payload, "platform", "unknown") or "unknown")[:64],
        "app_version": str(getattr(payload, "app_version", "unknown") or "unknown")[:64],
        "locale": str(getattr(payload, "locale", "unknown") or "unknown")[:32],
        "acceptance_method": str(getattr(payload, "acceptance_method", LEGAL_ACCEPTANCE_METHOD_DEFAULT) or LEGAL_ACCEPTANCE_METHOD_DEFAULT)[:32],
        "document_version": str(getattr(payload, "legal_version", "") or LEGAL_DOCUMENT_VERSION)[:64],
        "document_hash": str(getattr(payload, "legal_hash", "") or LEGAL_DOCUMENT_HASH)[:128],
        "accepted_terms": 1,
        "accepted_hold_harmless": 1,
        "accepted_limitation_liability": 1,
        "accepted_electronic_records": 1,
        "accepted_android_vpn_service_disclosure": int(
            bool(getattr(payload, "accepted_android_vpn_service_disclosure", False))
        ),
        "android_vpn_service_disclosure_version": str(
            getattr(payload, "android_vpn_service_disclosure_version", "") or ""
        )[:64],
        "android_vpn_service_disclosure_accepted_at": (
            str(getattr(payload, "android_vpn_service_disclosure_accepted_at", "") or "")[:64]
            or (accepted_at if str(getattr(payload, "android_vpn_service_disclosure_version", "") or "").strip() == "2026-07-20.v2" else "")
        ),
        "accepted_at": accepted_at,
    }
    row["signature_hmac"] = legal_acceptance_signature(row)
    conn.execute(
        """
        INSERT OR REPLACE INTO legal_acceptances (
            acceptance_id, account_number, email, device_id_bucket, source_ip_bucket,
            user_agent_hash, platform, app_version, locale, acceptance_method,
            document_version, document_hash, accepted_terms, accepted_hold_harmless,
            accepted_limitation_liability, accepted_electronic_records,
            accepted_android_vpn_service_disclosure,
            android_vpn_service_disclosure_version,
            android_vpn_service_disclosure_accepted_at,
            signature_hmac, accepted_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            row["acceptance_id"], row["account_number"], row["email"], row["device_id_bucket"], row["source_ip_bucket"],
            row["user_agent_hash"], row["platform"], row["app_version"], row["locale"], row["acceptance_method"],
            row["document_version"], row["document_hash"], row["accepted_terms"], row["accepted_hold_harmless"],
            row["accepted_limitation_liability"], row["accepted_electronic_records"],
            row["accepted_android_vpn_service_disclosure"],
            row["android_vpn_service_disclosure_version"],
            row["android_vpn_service_disclosure_accepted_at"],
            row["signature_hmac"], row["accepted_at"],
        ),
    )
    existing = conn.execute(
        """
        SELECT acceptance_id FROM legal_acceptances
        WHERE account_number = ? AND device_id_bucket = ?
          AND document_version = ? AND document_hash = ?
        ORDER BY accepted_at DESC
        LIMIT 1
        """,
        (row["account_number"], row["device_id_bucket"], LEGAL_DOCUMENT_VERSION, LEGAL_DOCUMENT_HASH),
    ).fetchone()
    return existing["acceptance_id"] if existing else row["acceptance_id"]

def ensure_legal_acceptance_for_activation(
    conn: sqlite3.Connection,
    request: Request,
    payload: Any,
    account_number: str,
    email: str,
    device_id: str,
) -> None:
    if has_current_legal_acceptance(conn, account_number, device_id):
        return
    if legal_acceptance_flags_ok(payload):
        record_legal_acceptance(conn, request, payload, account_number, email=email, device_id=device_id)
        return
    logger.warning(
        "LEGAL_REJECTION: has_cur=%s accepted_terms=%s accepted_hold=%s accepted_limit=%s accepted_elec=%s plat=%s accepted_disc=%s disc_ver=%s disc_at=%s expected_ver=%s",
        has_current_legal_acceptance(conn, account_number, device_id),
        getattr(payload, "accepted_terms", None),
        getattr(payload, "accepted_hold_harmless", None),
        getattr(payload, "accepted_limitation_liability", None),
        getattr(payload, "accepted_electronic_records", None),
        getattr(payload, "platform", None),
        getattr(payload, "accepted_android_vpn_service_disclosure", None),
        getattr(payload, "android_vpn_service_disclosure_version", None),
        getattr(payload, "android_vpn_service_disclosure_accepted_at", None),
        ANDROID_VPN_SERVICE_DISCLOSURE_VERSION,
    )
    raise HTTPException(
        status_code=451,
        detail={
            "message": "Legal acceptance is required before activation.",
            "legal": current_legal_payload(getattr(payload, "locale", "en")),
        },
    )

def free_node_match_terms() -> list[str]:
    terms = list(FREE_ACCESS_NODE_SLUGS)
    terms.append(FREE_ACCESS_NODE_SLUG)
    terms.extend(FREE_ACCESS_NODE_MATCHES)
    cleaned: list[str] = []
    for term in terms:
        normalized = str(term or "").strip().lower()
        if normalized and normalized not in cleaned:
            cleaned.append(normalized)
    return cleaned

def is_free_node(row: sqlite3.Row | dict[str, Any] | None) -> bool:
    if not row:
        return False
    data = dict(row)
    return int(data.get("free_access_enabled") or 0) == 1

def node_matches_free_access_defaults(slug: str, name: str = "", endpoint: str = "", ssh_host: str = "") -> bool:
    normalized_slug = (slug or "").strip().lower()
    if normalized_slug in FREE_ACCESS_NODE_SLUGS:
        return True
    label = f"{normalized_slug} {name or ''} {endpoint or ''} {ssh_host or ''}".lower()
    return any(term in label for term in free_node_match_terms())

def initial_node_free_access_enabled(
    conn: sqlite3.Connection,
    slug: str,
    name: str = "",
    endpoint: str = "",
    ssh_host: str = "",
) -> bool:
    if not FREE_ACCESS_ENABLED:
        return False
    if node_matches_free_access_defaults(slug, name, endpoint, ssh_host):
        return True
    # In a zero-touch fleet an empty selector means "use the first plane",
    # not "advertise free access but make it impossible to use". Once a free
    # node exists, later registrations remain premium unless explicitly named.
    if free_node_match_terms():
        return False
    row = conn.execute(
        "SELECT COUNT(*) AS cnt FROM nodes WHERE COALESCE(free_access_enabled, 0) = 1"
    ).fetchone()
    return int(row["cnt"] if row else 0) == 0

def normalized_node_max_peers(value: Any) -> int:
    try:
        parsed = int(value or 0)
    except (TypeError, ValueError):
        parsed = 0
    if parsed <= 0:
        parsed = DEFAULT_NODE_MAX_PEERS
    return max(1, min(MAX_NODE_MAX_PEERS, parsed))

def sanitize_node_load_ratio(value: Any) -> Optional[float]:
    """One load percentage from a node, clamped to 0..100.

    Returns None for anything that is not a finite JSON number. Never raises:
    it runs on /api/v1/nodes/register, the node's only heartbeat, and a bad
    optional load field must degrade the figure to unknown rather than fail the
    registration (a failed registration ages the node into the stale sweep,
    which closes it for customers).
    """
    if value is None or isinstance(value, (bool, str, bytes)):
        return None
    try:
        number = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    if not math.isfinite(number):
        return None
    return min(100.0, max(0.0, number))


def node_load_raw_pct(payload: Any) -> Optional[float]:
    """Raw congestion: the largest of the node's reported ratios.

    CPU (how busy the server is) and the active-users ratio (how many people
    are on it, across every transport) are both REQUIRED: a CPU-only figure can
    read low while a crowd is on the node, and a users-only figure can read low
    while the CPU is pinned, so a report missing either is unknown. The WAN
    ratio needs an operator-configured link capacity that most nodes do not
    have, so it is optional and only ever raises the figure.
    """
    cpu = sanitize_node_load_ratio(getattr(payload, "load_cpu_pct", None))
    users = sanitize_node_load_ratio(getattr(payload, "load_sessions_pct", None))
    if cpu is None or users is None:
        return None
    net = sanitize_node_load_ratio(getattr(payload, "load_net_pct", None))
    return max(cpu, users, net if net is not None else 0.0)


def node_load_report_is_fresh(reported_at: Any, now: datetime) -> bool:
    reported = parse_iso_datetime(reported_at) if isinstance(reported_at, str) else None
    if reported is None:
        return False
    age = (now - reported).total_seconds()
    # A report stamped in the future is clock damage, not freshness.
    return 0 <= age <= NODE_LOAD_REPORT_STALE_SECONDS


def node_load_hold_is_valid(band_at: Any, now: datetime) -> bool:
    """True while a held band, last set by a usable report, may be carried."""
    stamped = parse_iso_datetime(band_at) if isinstance(band_at, str) else None
    if stamped is None:
        return False
    age = (now - stamped).total_seconds()
    return 0 <= age <= NODE_LOAD_HOLD_SECONDS


def node_load_prior_state(previous: Any, now: datetime) -> tuple[Optional[str], Optional[str], int]:
    """(band, candidate, count) carried into this report.

    A fresh previous report carries everything. A previous report that was
    UNKNOWN (load_reported_at cleared) carries only its band, and only while the
    last usable report is within NODE_LOAD_HOLD_SECONDS, so one missed sampler
    or a gateway restart does not send a node back to the plain, unconfirmed
    boundaries. A previous report that is merely old (the node stopped
    reporting) carries nothing.
    """
    if not previous:
        return None, None, 0
    if node_load_report_is_fresh(previous["load_reported_at"], now):
        return previous["load_band"], previous["load_candidate"], previous["load_candidate_count"]
    if previous["load_reported_at"] is None and node_load_hold_is_valid(previous["load_band_at"], now):
        return previous["load_band"], None, 0
    return None, None, 0


def node_load_band_target(raw: float, current: Optional[str]) -> str:
    """The band one raw sample points at, given the band currently shown."""
    busy_at = NODE_LOAD_BOUNDARY_BUSY_PCT
    full_at = NODE_LOAD_BOUNDARY_FULL_PCT
    margin = NODE_LOAD_HYSTERESIS_PCT
    if current == "low":
        if raw >= full_at + margin:
            return "full"
        return "busy" if raw >= busy_at + margin else "low"
    if current == "busy":
        if raw < busy_at - margin:
            return "low"
        return "full" if raw >= full_at + margin else "busy"
    if current == "full":
        if raw < busy_at - margin:
            return "low"
        return "busy" if raw < full_at - margin else "full"
    # No confirmed band yet: plain boundaries, still confirmed below.
    if raw < busy_at:
        return "low"
    return "busy" if raw < full_at else "full"


def node_load_band_step(
    raw: Optional[float], band: Any, candidate: Any, count: Any
) -> tuple[Optional[str], Optional[str], int]:
    """Advance (band, candidate, candidate_count) by one report.

    The caller passes the previous state only when the previous report is
    fresh; otherwise None, None, 0, so a gap restarts confirmation.
    """
    if raw is None:
        return None, None, 0
    band = band if band in NODE_LOAD_BAND_PCT else None
    candidate = candidate if candidate in NODE_LOAD_BAND_PCT else None
    try:
        count = max(0, int(count or 0))
    except (TypeError, ValueError):
        count = 0
    target = node_load_band_target(raw, band)
    if target == band:
        return band, None, 0
    if band is None:
        # Nothing confirmed yet (first reports, or after a gap): the reports
        # must agree on the band itself.
        count = count + 1 if target == candidate else 1
        merged = target
    else:
        # Consecutive reports that all point the same way out of the shown
        # band confirm the LEAST extreme band they point at, so a load rising
        # low -> busy -> full across two reports shows "busy" instead of
        # staying hidden because the two targets differ.
        rank = {"low": 0, "busy": 1, "full": 2}
        up = rank[target] > rank[band]
        if candidate is not None and (rank[candidate] > rank[band]) == up:
            count += 1
            merged = candidate if abs(rank[candidate] - rank[band]) <= abs(rank[target] - rank[band]) else target
        else:
            count = 1
            merged = target
    if count >= NODE_LOAD_CONFIRM_REPORTS:
        return merged, None, 0
    return band, merged, count


def public_node_load_pct(node: Any, listed_status: Any, reachable: bool, now: datetime) -> Optional[int]:
    """The load_pct a public listing shows for one node row: 25, 60, 90 or None.

    A "congested" node is still listed with its confirmed band. The status
    "congested" comes from placement capacity (provisioned devices or peers
    against max_peers) or from the node's single-sample loadavg/memory check;
    neither is confirmed active-user congestion, so it is left to the status
    field and to placement, which already refuse new peers on a congested node.
    """
    if listed_status not in ("online", "congested") or reachable is not True:
        return None
    data = dict(node)
    if not node_load_report_is_fresh(data.get("load_reported_at"), now):
        return None
    band = data.get("load_band")
    if band not in NODE_LOAD_BAND_PCT:
        return None
    return int(NODE_LOAD_BAND_PCT[band])


def node_capacity_snapshot(conn: sqlite3.Connection, node: Any) -> tuple[int, int, int]:
    data = dict(node)
    maximum = normalized_node_max_peers(data.get("max_peers"))
    assigned_row = conn.execute(
        "SELECT COUNT(*) AS cnt FROM devices WHERE location_slug = ?",
        (str(data.get("slug") or ""),),
    ).fetchone()
    assigned = max(0, int(assigned_row["cnt"] if assigned_row else 0))
    # Heartbeats count the few system peers used by Double VPN and health
    # plumbing. Reserve a small fixed allowance so those do not consume a
    # customer slot, while still detecting drift when the hub database is low.
    heartbeat = max(0, int(data.get("peer_count") or 0) - NODE_RUNTIME_PEER_RESERVE)
    used = max(assigned, heartbeat)
    return used, maximum, max(0, maximum - used)

def node_accepts_new_peer(conn: sqlite3.Connection, node: Any) -> bool:
    used, maximum, _ = node_capacity_snapshot(conn, node)
    return used < maximum

def node_is_operator_enabled(row: sqlite3.Row | dict[str, Any] | None) -> bool:
    """Operator "off" switch.

    Unlike nodes.status -- which the node's own heartbeat overwrites every
    120s -- operator_enabled is never written by the heartbeat upsert, so an
    operator decision to withdraw a node survives until an operator reverses
    it. Missing/NULL is dark: only the literal integer 1 opens the latch.
    """
    if row is None:
        return False
    data = dict(row)
    if str(data.get("retired_at") or "").strip():
        return False
    if str(data.get("deployment_withdrawal_id") or "").strip():
        return False
    value = data.get("operator_enabled")
    return int(value if value is not None else 0) == 1

def node_admits_peer(
    node: sqlite3.Row | dict[str, Any] | None,
    device: sqlite3.Row | dict[str, Any] | None = None,
    system_peer: Optional[tuple[str, str]] = None,
) -> bool:
    """THE off-node peer policy (lane L46, F2). One predicate, one place.

    Decides whether `node` may carry runtime authorization for `device` (a
    devices row) or, with device=None, for a system peer such as the Double
    VPN Core exit peer. Every path that pushes or publishes authorization to a
    node outside a /verify admission asks this: the AWG peer resync, the Core
    exit peer resync, the closure cleanup, and the v3 registry snapshot. In
    the repo lineage (lane L57) that snapshot applies it to departure grants
    as well, and /verify asks it before issuing a departure allowance at the
    node a device is leaving.
    /verify admission itself is gated by selection (node_is_online_and_managed),
    which applies the same latch.

    Today the answer is the operator latch alone: operator_enabled off, an
    active installer withdrawal, or retirement (including an automatic health
    closure by the stale sweep or the prober, which sets operator_enabled=0
    and health_closed_at) means no customer or system peer.
    `device` is deliberately unused for now. A future reviewed single-device
    exception (for example a time-limited test grant on an off node) must be
    added HERE and nowhere else, so that resync, cleanup and the registry
    change together.

    The one reviewed exception (H5, design 3.15, ruling E) is the hub's AWG
    carrying-canary system peer. `system_peer` is (public key, allowed-ips) of
    the peer about to be pushed. Only the hub canary key with allowed-ips
    exactly 10.8.255.1/32 is admitted on a node that is closed, and never on a
    retired node or one under an installer withdrawal. Every other system peer
    in 10.8.255.0/24, Core exit peers included, keeps the answer above, and so
    does every call that passes no `system_peer`.
    """
    if node_is_operator_enabled(node):
        return True
    return awg_canary_peer_admitted(node, device, system_peer)

def awg_canary_peer_admitted(
    node: sqlite3.Row | dict[str, Any] | None,
    device: sqlite3.Row | dict[str, Any] | None,
    system_peer: Optional[tuple[str, str]],
) -> bool:
    """The exact canary exception for a node that is not operator-enabled."""
    if node is None or device is not None or system_peer is None or not AWG_CANARY_PUBLIC_KEY:
        return False
    try:
        key, allowed_ips = system_peer
    except (TypeError, ValueError):
        return False
    if not isinstance(key, str) or not isinstance(allowed_ips, str):
        return False
    if key != AWG_CANARY_PUBLIC_KEY or allowed_ips.strip() != AWG_CANARY_ALLOWED_IPS:
        return False
    data = dict(node)
    if str(data.get("retired_at") or "").strip():
        return False
    return not str(data.get("deployment_withdrawal_id") or "").strip()

def peer_push_still_admitted(
    node_slug: str, device_id: Optional[str] = None,
    system_peer: Optional[tuple[str, str]] = None,
    expected_public_key: Optional[str] = None,
    core_id: Optional[str] = None,
) -> bool:
    """L46 F2: re-read the latch (and the device or Core exit binding) right
    before, and right after, an external peer push, so a resync snapshot taken
    before a concurrent closure cannot restore a peer after it. `system_peer` is
    the H5 canary exception, passed through to node_admits_peer unchanged.
    `expected_public_key` is the AWG key the snapshot is about to push: a
    device or Core server that rotated its key since the snapshot no longer
    admits the old one, whose revocation may already have completed."""
    with get_db() as check_conn:
        node = check_conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        if node is None:
            return False
        device = None
        if device_id is not None:
            device = check_conn.execute(
                "SELECT * FROM devices WHERE device_id = ?", (device_id,)
            ).fetchone()
            if device is None or str(device["location_slug"] or "") != node_slug:
                return False
            if (expected_public_key is not None
                    and str(device["client_public_key"] or "").strip() != expected_public_key.strip()):
                return False
        if core_id is not None:
            core_row = check_conn.execute(
                """
                SELECT cs.exit_public_key, cs.status, cs.runtime_ready, cs.promoted,
                       cs.active_promotion_id, cs.deployment_withdrawal_id
                FROM double_vpn_assignments a
                JOIN core_servers cs ON cs.core_id = a.core_id
                JOIN core_exit_peers cep ON cep.core_id = a.core_id AND cep.exit_slug = a.exit_slug
                WHERE a.core_id = ? AND a.exit_slug = ? AND a.status = 'active'
                LIMIT 1
                """,
                (core_id, node_slug),
            ).fetchone()
            # The structural part of select_double_vpn_core's filter (online,
            # runtime-ready, promoted with an active promotion, not withdrawn);
            # heartbeat freshness is not a race signal and stays out.
            if core_row is None or not (
                core_row["status"] == "online"
                and int(core_row["runtime_ready"] or 0) == 1
                and int(core_row["promoted"] or 0) == 1
                and core_row["active_promotion_id"]
                and core_row["deployment_withdrawal_id"] is None
            ):
                return False
            if (expected_public_key is not None
                    and str(core_row["exit_public_key"] or "").strip() != expected_public_key.strip()):
                return False
        return node_admits_peer(node, device, system_peer)

def node_tier_label(row: sqlite3.Row | dict[str, Any] | None) -> str:
    """Operator-facing name for the two columns that decide advertisement.

    "premium" is not, and never was, a stored column -- it is the absence of
    free_access_enabled. It is derived here rather than duplicated.
    """
    if not row:
        return "unknown"
    if not node_is_operator_enabled(row):
        return "off"
    return "free" if is_free_node(row) else "premium"

# --- external data-plane reachability gate ---------------------------------
# A node heartbeats "online" when its AmneziaWG process is alive. That says
# nothing about whether a single packet from the internet can reach it. On
# 2026-08-05 a production node heartbeat "online" continuously while ALL
# inbound UDP was being dropped at the provider edge, so the hub advertised it
# and handed real users a complete, valid-looking config for a server they
# could never reach -- with no signal anywhere that anything was wrong.
#
# wins_node_dataplane_probe.py proves ingress from OUTSIDE the node (the hub
# sends nonce-tagged UDP to the node's advertised endpoint; the node reports,
# over the Cloudflare-tunnelled TCP management channel, whether its own NIC saw
# that nonce) and records the verdict in nodes.data_plane_*. The gates below
# keep a node that failed that proof out of every path that can hand a user a
# config.
#
# Two independent conditions, covering two different failures:
#   1. data_plane_status = 'unreachable' -- the probe RAN and the node's own
#      kernel saw nothing, FAIL_THRESHOLD times consecutively. Fast, affirmative.
#   2. data_plane_ok_at older than DATA_PLANE_HARD_STALE_MINUTES -- the node was
#      verified reachable once but has not been re-verified since, i.e. the
#      prober itself stopped running. Slow, and the genuinely fail-closed half.
# A node that has NEVER been probed (data_plane_ok_at IS NULL) is still allowed,
# so introducing this check can never dark-start a fleet before its first probe;
# condition 1 still demotes it as soon as a probe actually fails.
#
# ---------------------------------------------------------------------------
# HOW THIS COMPOSES WITH operator_enabled -- read before editing either one.
#
# These are two different questions and both are load-bearing:
#
#   operator_enabled  POLICY. "Has a human promoted this node?" Opened only by
#                     an evidenced off-to-free/premium operator transition via
#                     /admin/nodes/tier. The node's own heartbeat upsert cannot
#                     open it, so explicit 0 remains off until fresh promotion.
#   data_plane_*      HEALTH. "Can packets from the internet actually reach this
#                     node, on a transport this client's platform can use?"
#                     Measured every 120s by the prober. Once a promoted node
#                     becomes stale or affirmatively unreachable, the stale
#                     sweep consumes the promotion by closing operator_enabled.
#
# PRECEDENCE: policy is the OUTER filter and is dispositive; health is evaluated
# only among the nodes policy already allows. Concretely --
#
#   operator_enabled = 0            -> the node is ABSENT everywhere: not
#                                      selected, and not listed by GET /nodes.
#                                      Its health is irrelevant. A green
#                                      data-plane must never be able to
#                                      re-advertise a node an operator withdrew.
#   operator_enabled = 1, unhealthy -> the next stale sweep atomically closes
#                                      policy and invalidates live assignments.
#                                      A later green probe updates health only;
#                                      fresh evidence promotion is still needed.
#
# Why this order and not the reverse. (a) Fail-safe direction: the health gate
# grants grace on unknowns by design ("never probed" is allowed) so it cannot
# dark-start a fleet, whereas operator_enabled is restrictive by design. If
# health decided listing membership for withdrawn nodes, a never-probed
# operator-off node would be published as reachable=true. (b) Authority: a
# measurement must not be able to countermand a human's withdrawal, and equally
# a human re-enabling a node must not force a measurably dead server on users --
# which is why health still gates selection inside the enabled set.
#
# The two filters therefore CONJOIN in the four selection queries, and diverge
# in exactly one place -- GET /nodes -- where policy filters rows out and health
# only annotates them. That divergence is the whole point: dropping an
# unreachable node from the listing pushes the client to
# _loadCachedNodesFromDisk()/_useBootstrapNodesIfEmpty() and stale bootstrap
# servers, which is no better than offering a dead one.
# ---------------------------------------------------------------------------
DATA_PLANE_HARD_STALE_MINUTES = int(os.getenv("DATA_PLANE_HARD_STALE_MINUTES", "30") or 30)
# L84 (Round SC). probe_error means "the prober could not run the test"
# (usually the management SSH during a reboot). It still removes the node from
# NEW selection at once (DATA_PLANE_AVAILABLE_SQL below), but it consumes the
# promotion only after this many CONSECUTIVE aggregate probe_error runs. The
# timer fires every 120 s (measured median 121 s, p95 130 s), so 5 runs is
# about 10 min, the same as NODE_HEARTBEAT_STALE_SECONDS=600, and well inside
# the 30 min hard-stale bound, which still closes regardless. The prober reads
# the same variable.
DATA_PLANE_PROBE_ERROR_CLOSE_STREAK = max(
    1, int(os.getenv("DATAPLANE_PROBE_ERROR_CLOSE_STREAK", "5") or 5))
# Automatic reopening of an AUTOMATIC health closure. Off unless explicitly
# enabled (owner decision, Round SC OI-SC-5). When on, it uses
# node_promotion_readiness_failures(), the complete manual gate including the
# operator-posted off-node gate record, which it consumes exactly as manual
# promotion does, plus NODE_AUTO_REOPEN_PROOFS consecutive healthy prober runs
# counted after the closure and after this hub process saw authority recovery
# complete. It saves the operator the tier call, never the node-side gate.
NODE_AUTO_REOPEN_ENABLED = os.getenv("NODE_AUTO_REOPEN_ENABLED", "0").strip() == "1"
NODE_AUTO_REOPEN_PROOFS = max(2, int(os.getenv("NODE_AUTO_REOPEN_PROOFS", "5") or 5))
NODE_AUTO_REOPEN_HEARTBEAT_MAX_AGE_SECONDS = max(
    60, int(os.getenv("NODE_AUTO_REOPEN_HEARTBEAT_MAX_AGE_SECONDS", "300") or 300))
NODE_AUTO_REOPEN_MAX_PER_DAY = max(0, int(os.getenv("NODE_AUTO_REOPEN_MAX_PER_DAY", "3") or 3))
# IA-SYNC SYNC-08 (Fable 5.1 ruling 2026-09-29, Q1). A rerun of a node that
# was live at withdrawal, with unchanged identity and an evidenced installer
# revision, is closed as health_closed_reason='installer_rerun' and may be
# reopened by the L84 path under THIS switch only, after every L84 condition
# plus carrying proof on each advertised transport newer than the completion,
# a per-slug v3 canary for winn/3, a hub-verified off-node gate and a re-check
# of identity and lineage, inside the window below. NODE_AUTO_REOPEN_ENABLED
# keeps its default 0 and still covers health closures only. The daily budget
# NODE_AUTO_REOPEN_MAX_PER_DAY is shared by both classes.
NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED = (
    os.getenv("NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED", "1").strip() == "1")
NODE_INSTALLER_RERUN_REOPEN_WINDOW_SECONDS = max(
    600, int(os.getenv("NODE_INSTALLER_RERUN_REOPEN_WINDOW_SECONDS", "21600") or 21600))
# Optional fleet pin for lineage rule (a): when set, a rerun is eligible only
# at exactly this revision, and rules (b) and (c) are not consulted.
WINS_EXPECTED_DATA_PLANE_REVISION = os.getenv("WINS_EXPECTED_DATA_PLANE_REVISION", "").strip().lower()
# H7 (design 3.17): the fresh_install go-live class. A freshly installed node
# (or a same-slug provider reset) is closed as health_closed_reason=
# 'fresh_install' when its own verified t1 ticket carries go_live=auto, and this
# switch lets the L84 path open it after every proof inside the same window as
# an installer rerun. The switch never grants a node the right to go live: the
# ticket does (winn3_golive_ticket).
WINN3_FRESH_INSTALL_AUTO_GOLIVE = (
    os.getenv("WINN3_FRESH_INSTALL_AUTO_GOLIVE", "1").strip() == "1")
NODE_AUTO_REOPEN_CAUSES = (
    "auto_reopen", "auto_reopen_installer_rerun", "auto_golive_fresh_install")
# The fixed operator_source_hash values the hub itself writes into
# node_promotion_events. A manual promotion writes security_event_hash(...),
# exactly 16 lowercase hex characters, and only such a row evidences an
# installer revision (installer_rerun_reopen_eligibility): neither name below
# matches that pattern.
AUTOMATIC_PROMOTION_SOURCES = ("auto_reopen_installer_rerun", "auto_golive_fresh_install")
MANUAL_PROMOTION_SOURCE_GLOB = "[0-9a-f]" * 16
DATA_PLANE_AVAILABLE_SQL = (
    "AND COALESCE(data_plane_status, 'unknown') NOT IN ('unreachable', 'probe_error') "
    "AND (data_plane_ok_at IS NULL OR data_plane_ok_at >= "
    f"strftime('%Y-%m-%dT%H:%M:%S', 'now', '-{DATA_PLANE_HARD_STALE_MINUTES} minutes'))"
)
DATA_PLANE_AVAILABLE_SQL_N = (
    "AND COALESCE(n.data_plane_status, 'unknown') NOT IN ('unreachable', 'probe_error') "
    "AND (n.data_plane_ok_at IS NULL OR n.data_plane_ok_at >= "
    f"strftime('%Y-%m-%dT%H:%M:%S', 'now', '-{DATA_PLANE_HARD_STALE_MINUTES} minutes'))"
)

# Stealth reachability is NOT universal, and the dividing line is the OUTER
# SECURITY of the stealth transport, not the platform on its own.
#
# Linux clients hard-reject a `security=none` outer transport at
# linux/runner/linux_tunnel_backend.cc:1035-1045 unless the
# `allowplaintexttransport` compatibility flag is set, and no client code emits
# that key. That refusal is deliberate and stays: it is what stops a
# censorship-circumvention client from silently shipping its VLESS UUID and
# WebSocket metadata in the clear.
#
# A `security=tls` stealth transport carries the identical tunnel inside TLS and
# every platform accepts it, Linux included. So:
#
#     any platform          -> can use a TLS stealth transport
#     any platform but Linux -> can ALSO use a plaintext stealth transport
#
# platform_can_use_stealth() answers the narrower question it always answered:
# "can this platform be carried by a node whose only stealth route is
# plaintext?". The name is kept because that is still exactly what its three
# callers mean.
STEALTH_INCAPABLE_PLATFORMS = {"linux"}

def platform_can_use_stealth(platform: Any = "") -> bool:
    """True when this platform accepts a PLAINTEXT (security=none) stealth
    transport. TLS stealth is accepted by every platform -- see
    DATA_PLANE_STEALTH_TLS_PROVEN_SQL."""
    value = normalize_client_platform(platform)
    if value in {"", "unknown"}:
        return True  # unknown platform: do not over-restrict
    return value not in STEALTH_INCAPABLE_PLATFORMS

DATA_PLANE_UDP_AVAILABLE_SQL = (
    "COALESCE(data_plane_udp_status, 'unknown') NOT IN ('unreachable', 'probe_error') "
    "AND (data_plane_udp_ok_at IS NULL OR data_plane_udp_ok_at >= "
    f"strftime('%Y-%m-%dT%H:%M:%S', 'now', '-{DATA_PLANE_HARD_STALE_MINUTES} minutes'))"
)

# Deliberately stricter than every other clause here: POSITIVE proof, not the
# "no news is good news" grace. This branch can only ever ADD availability, so a
# permissive default would invent a route instead of merely failing to hide one.
# 'unknown' and 'unconfigured' therefore fall through to the UDP rule, and a
# node with no TLS stealth transport is gated exactly as it was before.
DATA_PLANE_STEALTH_TLS_PROVEN_SQL = (
    "COALESCE(data_plane_stealth_tls_status, 'unknown') = 'ok' "
    "AND data_plane_stealth_tls_ok_at IS NOT NULL "
    "AND data_plane_stealth_tls_ok_at >= "
    f"strftime('%Y-%m-%dT%H:%M:%S', 'now', '-{DATA_PLANE_HARD_STALE_MINUTES} minutes')"
)

def data_plane_sql(platform: Any = "") -> str:
    """Aggregate gate, plus -- for platforms that cannot use a plaintext stealth
    transport -- a requirement that the aggregate 'ok' be carried by a transport
    they CAN use: direct UDP, or stealth inside TLS."""
    sql = DATA_PLANE_AVAILABLE_SQL
    if not platform_can_use_stealth(platform):
        sql = (f"{sql} AND (({DATA_PLANE_UDP_AVAILABLE_SQL})"
               f" OR ({DATA_PLANE_STEALTH_TLS_PROVEN_SQL}))")
    return sql

def node_transport_availability(node: Any) -> dict[str, str]:
    """Per-transport state, so the hub can steer clients to a working route
    instead of a blanket up/down."""
    data = dict(node)
    return {
        "direct_awg_udp": str(data.get("data_plane_udp_status") or "unknown"),
        "stealth_tcp_ws": str(data.get("data_plane_stealth_status") or "unknown"),
        "stealth_tls_tcp_ws": str(data.get("data_plane_stealth_tls_status") or "unknown"),
    }

def _fresh_enough(value: Any) -> bool:
    text = str(value or "")
    if not text:
        return True  # never verified yet: grace, so this can never dark-start
    cutoff = (utcnow() - timedelta(minutes=DATA_PLANE_HARD_STALE_MINUTES)).isoformat()
    return text >= cutoff

def node_data_plane_is_available(node: Any, platform: Any = "") -> bool:
    """Python mirror of data_plane_sql() for already-fetched rows.

    HEALTH ONLY. It deliberately does not consult operator_enabled: the two are
    separate questions and callers that need both say so (see
    node_is_online_and_managed). list_public_nodes needs exactly this one --
    health without policy -- because it reports reachability for rows policy has
    already admitted.
    """
    data = dict(node)
    if str(data.get("data_plane_status") or "unknown") in {
        "unreachable", "probe_error"
    }:
        return False
    if not _fresh_enough(data.get("data_plane_ok_at")):
        return False
    if not platform_can_use_stealth(platform):
        # A PLAINTEXT stealth route cannot help this client, so the aggregate
        # 'ok' must be carried by a transport it can actually use: direct UDP,
        # or stealth inside TLS. Mirrors data_plane_sql() exactly, including the
        # asymmetry -- UDP gets the usual "not known to be broken" grace, TLS
        # stealth must be positively proven.
        udp_usable = (
            str(data.get("data_plane_udp_status") or "unknown") not in {
                "unreachable", "probe_error"
            }
            and _fresh_enough(data.get("data_plane_udp_ok_at"))
        )
        stealth_tls_proven = (
            str(data.get("data_plane_stealth_tls_status") or "unknown") == "ok"
            and bool(data.get("data_plane_stealth_tls_ok_at"))
            and _fresh_enough(data.get("data_plane_stealth_tls_ok_at"))
        )
        if not (udp_usable or stealth_tls_proven):
            return False
    return True

def node_data_plane_is_proven(node: Any) -> bool:
    """Positive, fresh external proof required to open a dark node's latch.

    General selection deliberately grants never-probed nodes a compatibility
    grace period. Promotion is the opposite boundary: absence of proof cannot
    authorize the first customer-serving transition.
    """
    data = dict(node)
    return (
        str(data.get("data_plane_status") or "unknown") == "ok"
        and bool(data.get("data_plane_ok_at"))
        and _fresh_enough(data.get("data_plane_ok_at"))
    )

def node_promotion_transport_plan(node: Any) -> dict[str, Optional[list[str]]]:
    """L77: the data-plane transports a client is OFFERED for this row, each
    with the row fields that make it unusable or untestable.

    None means the row does not offer that transport. A list (empty when
    nothing is missing) means it does, so promotion must prove it. "Offered"
    is decided by the same code the client config builder (verify) and the
    public listing use, so no row shape a client is handed can be skipped:
      udp          verify hands every client the direct endpoint (it refuses
                   the whole config without endpoint and public_key). It is
                   used unless direct_awg_enabled is 0; a winn/3 node's
                   standalone datagram path is the same UDP port, so a winn/3
                   row always offers it.
      stealth,     offered exactly when verify would serve stealth mode: a
      stealth_tls  non-empty stealth_endpoint string (verify's 503 test is
                   `not stealth_endpoint`, unstripped). The flavours are the
                   entries of parse_xray_transports(stealth_transports, port,
                   xray_security) with port from split_host_port(
                   stealth_endpoint, stealth_public_port or 80): the list the
                   client config carries, including the fallback entry for an
                   empty list and a portless or IPv6-literal endpoint.
    An offered transport stays required even when a field is blank or
    malformed: the gate then refuses and names what is missing, because the
    external probe cannot prove it (the probe reports such a transport as
    'unconfigured' or skips the node).
    """
    data = dict(node)
    direct = data.get("direct_awg_enabled")
    protocol = str(data.get("protocol_version") or "").strip().lower()
    try:
        direct_off = direct is not None and int(str(direct).strip()) == 0
    except (TypeError, ValueError):
        direct_off = False
    udp_offered = protocol == "winn/3" or not direct_off
    udp_missing = [name for name, present in (
        ("endpoint", data.get("endpoint") or ""),
        ("public_key", data.get("public_key") or ""),
        ("ssh_host", str(data.get("ssh_host") or "").strip()),
    ) if not present]
    plan: dict[str, Optional[list[str]]] = {
        "udp": udp_missing if udp_offered else None,
        "stealth": None,
        "stealth_tls": None,
    }
    stealth_endpoint = data.get("stealth_endpoint") or ""
    if not stealth_endpoint:
        return plan
    stealth_missing: list[str] = []
    try:
        stealth_host, stealth_port = split_host_port(
            stealth_endpoint, int(data.get("stealth_public_port") or 80))
    except (TypeError, ValueError):
        # verify itself would fail on this row; offer both flavours as
        # unprovable rather than skip them.
        stealth_host, stealth_port = "", 80
        stealth_missing.append("a parsable stealth_endpoint/stealth_public_port")
    transports = parse_xray_transports(
        data.get("stealth_transports"), stealth_port,
        str(data.get("xray_security") or "none").lower(),
    )
    if not str(stealth_host or "").strip() and not parse_aliases(data.get("regional_aliases")):
        stealth_missing.append("a stealth host (stealth_endpoint host or regional_aliases)")
    if not re.fullmatch(
        r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}",
        str(data.get("xray_uuid") or "").strip(),
    ):
        stealth_missing.append("xray_uuid")
    for name, present in (
        ("xray_path", str(data.get("xray_path") or "").strip()),
        ("ssh_host", str(data.get("ssh_host") or "").strip()),
    ):
        if not present:
            stealth_missing.append(name)
    # parse_xray_transports always returns at least one entry (its fallback),
    # each with security "none" or "tls".
    securities = {item["security"] for item in transports}
    if "none" in securities:
        plan["stealth"] = list(stealth_missing)
    if "tls" in securities:
        plan["stealth_tls"] = list(stealth_missing)
    return plan

def node_promotion_transports(node: Any) -> dict[str, bool]:
    """L77: which data-plane transports promotion must prove for this row:
    every one it advertises (see node_promotion_transport_plan)."""
    return {name: missing is not None
            for name, missing in node_promotion_transport_plan(node).items()}

def node_promotion_data_plane_failures(node: Any) -> list[str]:
    """L77: promotion needs EVERY advertised transport proven ok and fresh.

    Routing is deliberately different: data_plane_sql() and the Smart Router
    call a node usable when ANY transport a client can use works, because the
    client falls back across transports. Promotion is the first
    customer-serving transition, so a node must not be admitted on one
    transport while another one it advertises (and clients will try first)
    is failing. Returns human-readable reasons; empty means proven.
    """
    data = dict(node)
    failures = []
    if not node_data_plane_is_proven(data):
        failures.append("aggregate is not a fresh ok")
    plan = node_promotion_transport_plan(data)
    if all(missing is None for missing in plan.values()):
        failures.append("the node row advertises no data-plane transport")
    for name, column in (
        ("udp", "data_plane_udp"),
        ("stealth", "data_plane_stealth"),
        ("stealth_tls", "data_plane_stealth_tls"),
    ):
        missing = plan[name]
        if missing is None:
            continue
        if missing:
            # Advertised to clients, but the probe cannot test it as the row
            # stands: refuse and say what is missing, never skip it.
            failures.append(f"{name} is advertised but cannot be probed (missing {', '.join(missing)})")
            continue
        status = str(data.get(f"{column}_status") or "unknown").strip().lower()
        ok_at = data.get(f"{column}_ok_at")
        if status != "ok":
            failures.append(f"{name} is {status}")
        elif not ok_at or not _fresh_enough(ok_at):
            failures.append(f"{name} proof is stale")
    return failures

def node_promotion_readiness_failures(
    conn: sqlite3.Connection, node: Any, offnode_gate_sha256: str,
    allow_hub_gate: bool = False,
) -> list[str]:
    """The complete readiness gate for opening a closed node's latch, shared by
    the manual /admin/nodes/tier promotion and the L84 automatic reopen so the
    two can never drift: heartbeat status, management verification, every
    advertised transport proven ok and fresh (Round PG / L77), a confirmed
    closed-node runtime cleanup (L46 F2), and the node-side off-node gate record
    this hub verified (L46 F2 v3, verify_offnode_gate_for_use). The manual path
    adds only confirm_slug and the evidence digest format on top; both paths
    consume the gate with consume_offnode_gate()."""
    data = dict(node)
    failures = []
    if str(data.get("status") or "").strip().lower() != "online":
        failures.append("node heartbeat is not online")
    if str(data.get("management_status") or "").strip().lower() != "ok":
        failures.append("management verification is not ok")
    data_plane_failures = node_promotion_data_plane_failures(data)
    if data_plane_failures:
        failures.append(
            "positive external data-plane proof is absent or stale ("
            + ", ".join(data_plane_failures) + ")"
        )
    # L46 F2: a closed node whose runtime cleanup is not confirmed must
    # not return to service. Run a resync and the node-side gate first.
    cleanup = conn.execute(
        "SELECT state FROM node_closure_cleanup WHERE slug = ?", (data.get("slug"),)
    ).fetchone()
    if cleanup is None:
        failures.append("closed-node runtime cleanup was never recorded (resync the node)")
    elif cleanup["state"] != "confirmed":
        failures.append("closed-node runtime cleanup is pending")
    # L46 F2 v3: the digest names a node-side gate record this hub verified and
    # recorded (POST /admin/nodes/offnode-gate).
    failures += [
        "offnode gate: " + reason
        for reason in verify_offnode_gate_for_use(
            conn, data.get("slug"), offnode_gate_sha256, allow_hub_source=allow_hub_gate)
    ]
    return failures

def node_is_online_and_managed(node: Any, platform: Any = "") -> bool:
    """Both gates, in precedence order: policy first, then health.

    Every caller of this is a path that can hand a user a config, so both vetoes
    apply. GET /nodes deliberately does NOT use this -- it applies policy in SQL
    and health as a label.
    """
    data = dict(node)
    return (
        data.get("status") == "online"
        and data.get("management_status") == "ok"
        and node_is_operator_enabled(data)
        and node_data_plane_is_available(data, platform)
    )

class _SmartRouterNoRedirect(urllib.request.HTTPRedirectHandler):
    """A route request may never follow a redirect with its HMAC headers."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def _smart_router_endpoint() -> str:
    if not SMART_ROUTER_URL:
        return ""
    parsed = urllib.parse.urlparse(SMART_ROUTER_URL)
    path = parsed.path.rstrip("/")
    if (
        parsed.scheme != "https"
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
        or path not in {"", "/route"}
    ):
        raise ValueError("SMART_ROUTER_URL must be a credential-free HTTPS origin or /route URL")
    return urllib.parse.urlunparse(("https", parsed.netloc, "/route", "", "", ""))

def _smart_router_open(request: urllib.request.Request, timeout: float):
    opener = urllib.request.build_opener(_SmartRouterNoRedirect())
    return opener.open(request, timeout=timeout)

def _smart_router_candidate_payload(
    conn: sqlite3.Connection,
    rows: list[Any],
    existing_slug: str,
) -> tuple[list[dict], dict[str, sqlite3.Row]]:
    existing_slug = (existing_slug or "").strip().lower()
    payload = []
    by_slug = {}
    for row in rows:
        slug = str(row["slug"] or "").strip().lower()
        if not slug:
            continue
        used, maximum, remaining = node_capacity_snapshot(conn, row)
        if remaining <= 0 and slug != existing_slug:
            continue
        meta = node_protocol_route_metadata(row)
        if meta is None:
            continue
        data = dict(row)
        fail_streak = data.get("data_plane_fail_streak")
        # `data_plane_sql()` grants a never-probed node admission grace so a
        # new fleet does not dark-start. That is not affirmative reachability
        # proof. The advisory schema has no unknown boolean state, so report
        # True only for a fresh aggregate probe success. Final hub selection
        # still performs its existing health and capacity revalidation.
        reachable = (
            str(data.get("data_plane_status") or "unknown").strip().lower() == "ok"
            and bool(data.get("data_plane_ok_at"))
            and _fresh_enough(data.get("data_plane_ok_at"))
        )
        item = {
            "route_id": slug,
            "reachable": reachable,
            "load_ratio": min(1.0, max(0.0, used / maximum)),
            # No per-route measurements exist for these fields. Preserve that
            # unknown state instead of fabricating values from reachability.
            "handshake_ms": None,
            "packet_loss_pct": None,
            "jitter_ms": None,
            "dns_ok": None,
            "recent_failures": int(fail_streak) if fail_streak is not None else None,
            "protocol_version": meta["protocol_version"],
            "carrier": meta["carrier"],
        }
        if meta["protocol_version"] == WINN_PROTOCOL_V1:
            item["v1_engine_order"] = list(meta.get("v1_engine_order") or WINN_V1_ENGINE_ORDER)
        payload.append(item)
        by_slug[slug] = row
    return payload, by_slug

def _smart_router_json_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    parsed: dict[str, Any] = {}
    for key, value in pairs:
        if key in parsed:
            raise ValueError("duplicate Smart Router response key")
        parsed[key] = value
    return parsed

def _reject_smart_router_json_constant(token: str) -> None:
    raise ValueError(f"non-finite Smart Router JSON constant: {token}")

def smart_router_recommend_node(
    conn: sqlite3.Connection,
    existing_slug: str = "",
    platform: Any = "",
    free_only: bool = False,
    trigger: str = "connection_initiation",
    selection_generation: str = "",
    ordinary_v3_failure_generation: str = "",
) -> str:
    """Return a closed-set advisory slug, or empty for deterministic fallback.

    This function is called before the activation writer transaction. It sends
    no account, device, endpoint, address, key, or credential data. Its result
    is revalidated under the writer transaction before use.
    """
    if not SMART_ROUTER_URL and not SMART_ROUTER_HMAC_SECRET:
        return ""
    if not SMART_ROUTER_URL or len(SMART_ROUTER_HMAC_SECRET) < 32:
        logger.warning("Smart Router configuration incomplete; using deterministic selection")
        return ""
    if trigger not in {"connection_initiation", "distress"}:
        raise ValueError("unsupported Smart Router trigger")
    try:
        endpoint = _smart_router_endpoint()
        free_clause = "AND COALESCE(free_access_enabled, 0) = 1" if free_only else ""
        # Include data-plane-unhealthy rows so a present winn/3 candidate can
        # block unauthorized v1 even when it is not currently reachable.
        rows = conn.execute(f"""
            SELECT * FROM nodes
            WHERE status = 'online'
              AND management_status = 'ok'
              AND COALESCE(operator_enabled, 0) = 1
              AND retired_at IS NULL
              {free_clause}
            ORDER BY LOWER(name) ASC, LOWER(slug) ASC
        """).fetchall()
        candidates, by_slug = _smart_router_candidate_payload(conn, rows, existing_slug)
        if not candidates:
            return ""
        current = (existing_slug or "").strip().lower()
        if current not in by_slug:
            current = None
        body_obj = {
            "request_id": "hub-" + secrets.token_urlsafe(12),
            "current_route_id": current,
            "candidates": candidates,
            "trigger": trigger,
        }
        try:
            generation = typed_selection_generation(selection_generation)
            authorized_generation = typed_selection_generation(
                ordinary_v3_failure_generation
            )
        except ValueError:
            generation = ""
            authorized_generation = ""
        if generation:
            body_obj["selection_generation"] = generation
        if authorized_generation:
            body_obj["ordinary_v3_failure_generation"] = authorized_generation
        body = json.dumps(
            body_obj,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        timestamp = str(int(time.time()))
        nonce = secrets.token_urlsafe(18)
        body_hash = hashlib.sha256(body).hexdigest()
        signing_input = f"POST\n/route\n{timestamp}\n{nonce}\n{body_hash}".encode("ascii")
        signature = hmac.new(
            SMART_ROUTER_HMAC_SECRET.encode("utf-8"),
            signing_input,
            hashlib.sha256,
        ).hexdigest()
        request = urllib.request.Request(
            endpoint,
            data=body,
            method="POST",
            headers={
                "Content-Type": "application/json",
                "X-Smart-Router-Timestamp": timestamp,
                "X-Smart-Router-Nonce": nonce,
                "X-Smart-Router-Signature": signature,
            },
        )
        with _smart_router_open(request, SMART_ROUTER_TIMEOUT_SECONDS) as response:
            raw = response.read(SMART_ROUTER_MAX_RESPONSE_BYTES + 1)
        if len(raw) > SMART_ROUTER_MAX_RESPONSE_BYTES:
            raise ValueError("Smart Router response exceeded size limit")
        decision = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=_smart_router_json_object,
            parse_constant=_reject_smart_router_json_constant,
        )
        expected_keys = {
            "selected_route_id", "decision", "confidence", "reason_codes", "source"
        }
        if type(decision) is not dict or set(decision) != expected_keys:
            raise ValueError("Smart Router response schema keys are not exact")
        selected_value = decision["selected_route_id"]
        if type(selected_value) is not str or not re.fullmatch(
            r"[a-z0-9][a-z0-9-]{1,39}", selected_value
        ):
            raise ValueError("Smart Router selected_route_id is malformed")
        selected = selected_value
        response_decision = decision["decision"]
        if response_decision not in {"keep", "switch"}:
            raise ValueError("Smart Router decision is invalid")
        confidence = decision["confidence"]
        if type(confidence) is not float or not 0.0 <= confidence <= 1.0:
            raise ValueError("Smart Router confidence is invalid")
        reason_codes = decision["reason_codes"]
        if (
            type(reason_codes) is not list
            or not 1 <= len(reason_codes) <= 3
            or any(
                type(code) is not str
                or not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", code)
                for code in reason_codes
            )
        ):
            raise ValueError("Smart Router reason_codes are invalid")
        if decision["source"] not in {
            "explicit", "local_gemma", "google_gemini", "fallback"
        }:
            raise ValueError("Smart Router source is invalid")
        expected_decision = "keep" if current is not None and selected == current else "switch"
        if response_decision != expected_decision:
            raise ValueError("Smart Router decision contradicts the selected route")
        if selected not in by_slug:
            raise ValueError("Smart Router selected outside the closed candidate set")
        eligible_rows = protocol_eligible_node_rows(
            [by_slug[item["route_id"]] for item in candidates],
            selection_generation=generation,
            ordinary_v3_failure_generation=authorized_generation,
            healthy=lambda row: bool(
                next(
                    (
                        item["reachable"]
                        for item in candidates
                        if item["route_id"] == str(row["slug"] or "").strip().lower()
                    ),
                    False,
                )
            ),
        )
        eligible_slugs = {
            str(row["slug"] or "").strip().lower() for row in eligible_rows
        }
        if selected not in eligible_slugs:
            raise ValueError("Smart Router selected a protocol-ineligible route")
        logger.info("Smart Router advisory accepted source=%s", str(decision.get("source") or "unknown")[:32])
        return selected
    except Exception as exc:
        logger.warning(
            "Smart Router unavailable; using deterministic selection (%s)",
            type(exc).__name__,
        )
        return ""

def smart_router_trigger_for_existing_node(
    conn: sqlite3.Connection,
    existing_slug: str,
) -> str:
    """Derive distress only from hub-measured node health telemetry.

    The client cannot set this result. A normal first connection, an unknown
    allocation, and a clean existing allocation all remain deterministic
    connection initiation. A recent external data-plane probe failure is the
    smallest available machine signal that the current route is distressed.
    """
    existing_slug = (existing_slug or "").strip().lower()
    if not existing_slug:
        return "connection_initiation"
    row = conn.execute(
        "SELECT data_plane_status, data_plane_fail_streak FROM nodes WHERE slug = ? AND retired_at IS NULL",
        (existing_slug,),
    ).fetchone()
    if not row:
        return "connection_initiation"
    data = dict(row)
    status = str(data.get("data_plane_status") or "unknown").strip().lower()
    try:
        fail_streak = max(0, int(data.get("data_plane_fail_streak") or 0))
    except (TypeError, ValueError):
        fail_streak = 0
    if status in {"degraded", "unreachable", "probe_error"} or fail_streak > 0:
        return "distress"
    return "connection_initiation"

def select_online_node(
    conn: sqlite3.Connection,
    selected_slug: str,
    require_selected: bool = False,
    existing_slug: str = "",
    platform: Any = "",
    preferred_slug: str = "",
    advisory_is_distress: bool = False,
    selection_generation: str = "",
    ordinary_v3_failure_generation: str = "",
    free_only: bool = False,
) -> Optional[sqlite3.Row]:
    selected_slug = (selected_slug or "auto").strip().lower()
    existing_slug = (existing_slug or "").strip().lower()
    preferred_slug = (preferred_slug or "").strip().lower()
    try:
        selection_generation = typed_selection_generation(selection_generation)
        ordinary_v3_failure_generation = typed_selection_generation(
            ordinary_v3_failure_generation
        )
    except ValueError:
        selection_generation = ""
        ordinary_v3_failure_generation = ""

    def protocol_selectable(node: Any, *, allow_unclassified_v3: bool = False) -> bool:
        if not node:
            return False
        slug = str(node["slug"] or "").strip().lower()
        if not slug:
            return False
        if free_only and not is_free_node(node):
            return False
        if allow_unclassified_v3:
            version = str(
                _node_field(node, "protocol_version") or WINN_PROTOCOL_V1
            ).strip().lower()
            if version == WINN_PROTOCOL_V3:
                return True
        return slug in _protocol_eligible_slugs(
            conn,
            platform,
            existing_slug,
            selection_generation,
            ordinary_v3_failure_generation,
            free_only=free_only,
        )

    node_row = None
    if selected_slug not in {"", "auto"}:
        node_row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (selected_slug,)).fetchone()
        if node_row and node_is_online_and_managed(node_row, platform):
            if node_accepts_new_peer(conn, node_row) or selected_slug == existing_slug:
                if protocol_selectable(node_row, allow_unclassified_v3=True):
                    return node_row
        if require_selected:
            return None

    # A distress advisory is allowed to move a device away from a current node
    # whose hub-measured data-plane telemetry is failing. The recommendation is
    # still revalidated here for policy, health, capacity, and protocol. Recommending
    # the existing node itself remains valid at the exact ceiling because reconnect
    # does not consume a new slot.
    if selected_slug in {"", "auto"} and preferred_slug and advisory_is_distress:
        preferred = conn.execute("SELECT * FROM nodes WHERE slug = ?", (preferred_slug,)).fetchone()
        if preferred and node_is_online_and_managed(preferred, platform):
            if preferred_slug == existing_slug or (
                node_accepts_new_peer(conn, preferred) and not node_v3_sessions_full(conn, preferred)
            ):
                if protocol_selectable(preferred):
                    return preferred

    # An ordinary existing allocation may reconnect to its current node at the
    # exact ceiling because it does not consume a new slot. Keep it ahead of a
    # normal initiation advisory so a healthy reconnect is not moved. Protocol
    # eligibility still applies: a v1 allocation cannot bypass winn/3 primacy.
    if selected_slug in {"", "auto"} and existing_slug:
        existing_row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (existing_slug,)).fetchone()
        if existing_row and node_is_online_and_managed(existing_row, platform):
            if protocol_selectable(existing_row, allow_unclassified_v3=True):
                return existing_row

    if selected_slug in {"", "auto"} and preferred_slug:
        preferred = conn.execute("SELECT * FROM nodes WHERE slug = ?", (preferred_slug,)).fetchone()
        if preferred and node_is_online_and_managed(preferred, platform):
            if node_accepts_new_peer(conn, preferred) and not node_v3_sessions_full(conn, preferred):
                if protocol_selectable(preferred):
                    return preferred

    # Policy filter and health gate conjoin here: operator_enabled decides
    # whether the node may be advertised at all, data_plane_sql(platform)
    # decides whether it can actually carry this client. See the precedence
    # note above node_is_online_and_managed.
    candidates = conn.execute(f"""
        SELECT * FROM nodes
        WHERE status = 'online'
          AND management_status = 'ok'
          AND COALESCE(operator_enabled, 0) = 1
          AND retired_at IS NULL
          {data_plane_sql(platform)}
        ORDER BY LOWER(name) ASC, LOWER(slug) ASC
    """).fetchall()
    available = []
    for candidate in candidates:
        if free_only and not is_free_node(candidate):
            continue
        used, maximum, remaining = node_capacity_snapshot(conn, candidate)
        if remaining > 0:
            available.append((used / maximum, used, str(candidate["name"] or "").lower(), str(candidate["slug"] or "").lower(), candidate))
    if available:
        eligible_slugs = _protocol_eligible_slugs(
            conn,
            platform,
            existing_slug,
            selection_generation,
            ordinary_v3_failure_generation,
            free_only=free_only,
        )
        available = [item for item in available if item[3] in eligible_slugs]
    # P-8: a node whose gateway is at 90 percent of -max-sessions is full for a
    # new assignment. Walk the candidates in the old order and take the first
    # that is not full, so the steering never leaves a client with no node the
    # old rule would have given: when every candidate is full, the first one in
    # the old order is used. The walk stops at the first node with room, so the
    # per-node session check (a devices query) runs for as few nodes as it must.
    first = None
    for item in sorted(available, key=lambda item: item[:4]):
        if first is None:
            first = item
        if not node_v3_sessions_full(conn, item[4]):
            return item[4]
    return first[4] if first else None


def _select_online_query_rows(
    conn: sqlite3.Connection,
    platform: Any,
    existing_slug: str,
    *,
    require_data_plane: bool = True,
    free_only: bool = False,
) -> list:
    existing_slug = (existing_slug or "").strip().lower()
    extra = data_plane_sql(platform) if require_data_plane else ""
    rows = conn.execute(f"""
        SELECT * FROM nodes
        WHERE status = 'online'
          AND management_status = 'ok'
          AND COALESCE(operator_enabled, 0) = 1
          AND retired_at IS NULL
          {extra}
        ORDER BY LOWER(name) ASC, LOWER(slug) ASC
    """).fetchall()
    out = []
    for row in rows:
        used, maximum, remaining = node_capacity_snapshot(conn, row)
        slug = str(row["slug"] or "").strip().lower()
        if remaining > 0 or slug == existing_slug:
            if free_only and not is_free_node(row):
                continue
            out.append(row)
    return out


def _protocol_eligible_slugs(
    conn: sqlite3.Connection,
    platform: Any,
    existing_slug: str,
    selection_generation: Any = "",
    ordinary_v3_failure_generation: Any = "",
    *,
    free_only: bool = False,
) -> set:
    fleet = _select_online_query_rows(
        conn,
        platform,
        existing_slug,
        require_data_plane=False,
        free_only=free_only,
    )
    eligible = protocol_eligible_node_rows(
        fleet,
        selection_generation=selection_generation,
        ordinary_v3_failure_generation=ordinary_v3_failure_generation,
        healthy=lambda row: node_data_plane_is_available(row, platform),
    )
    return {str(row["slug"] or "").strip().lower() for row in eligible}


def select_free_node(
    conn: sqlite3.Connection,
    requested_slug: str = "auto",
    existing_slug: str = "",
    platform: Any = "",
    preferred_slug: str = "",
    advisory_is_distress: bool = False,
    selection_generation: str = "",
    ordinary_v3_failure_generation: str = "",
) -> Optional[sqlite3.Row]:
    if not FREE_ACCESS_ENABLED:
        return None
    requested_slug = (requested_slug or "auto").strip().lower()
    preferred_slug = (preferred_slug or "").strip().lower()
    existing_slug = (existing_slug or "").strip().lower()
    shared = {
        "existing_slug": existing_slug,
        "platform": platform,
        "selection_generation": selection_generation,
        "ordinary_v3_failure_generation": ordinary_v3_failure_generation,
        "free_only": False,
    }
    if requested_slug not in {"", "auto"}:
        requested = select_online_node(
            conn, requested_slug, require_selected=True, **shared
        )
        return requested
    if preferred_slug:
        preferred = select_online_node(
            conn,
            "auto",
            preferred_slug=preferred_slug,
            advisory_is_distress=advisory_is_distress,
            **shared,
        )
        if preferred:
            return preferred
    if existing_slug:
        existing = select_online_node(
            conn, existing_slug, require_selected=True, **shared
        )
        if existing:
            return existing
    picked = select_online_node(conn, "auto", **shared)
    return picked

def current_free_node_slugs(conn: sqlite3.Connection, platform: Any = "") -> list[str]:
    rows = conn.execute(f"""
        SELECT * FROM nodes
        WHERE status = 'online'
          AND management_status = 'ok'
          AND COALESCE(operator_enabled, 0) = 1
          AND retired_at IS NULL
          {data_plane_sql(platform)}
        ORDER BY LOWER(name) ASC, LOWER(slug) ASC
    """).fetchall()
    slugs = [row["slug"] for row in rows if row["slug"] and node_accepts_new_peer(conn, row)]
    return slugs

def normalize_country_flag(value: Optional[str]) -> str:
    raw = (value or "").strip()
    if not raw:
        return "🌐"
    upper = raw.upper()
    if len(upper) == 2 and upper.isalpha():
        return "".join(chr(0x1F1E6 + ord(ch) - ord("A")) for ch in upper)
    return raw

def parse_iso_datetime(value: Optional[str]) -> Optional[datetime]:
    if not isinstance(value, str):
        return None
    raw = value.strip()
    if not raw or raw == "Lifetime Access":
        return None
    if raw.endswith("Z"):
        raw = raw[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except (ValueError, OverflowError):
        return None

class DurationParseError(ValueError):
    """An invalid or unsupported account access duration."""


def parse_duration(duration: str):
    raw = duration.strip().lower() if isinstance(duration, str) else ""
    if raw in {"lifetime", "life", "10y"}:
        return relativedelta(years=10)
    match = re.fullmatch(r"([1-9][0-9]{0,3})([dmy])", raw)
    if match is None:
        raise DurationParseError("duration must be 1d to 3650d, 1m to 120m, or 1y to 10y")
    amount = int(match.group(1))
    unit = match.group(2)
    if amount > {"d": 3650, "m": 120, "y": 10}[unit]:
        raise DurationParseError("duration exceeds the 10-year maximum")
    if unit == "d":
        return relativedelta(days=amount)
    if unit == "m":
        return relativedelta(months=amount)
    return relativedelta(years=amount)

AWG_OBFUSCATION_MAX = 0xFFFFFFFF

class ObfuscationProfileError(ValueError):
    """A stored obfuscation profile that cannot be served exactly as recorded.

    Carries a short machine-readable ``reason`` and the offending key *names*.
    It deliberately carries no values: H1..H4 and S1..S4 are the parameters
    whose whole purpose is to not be publicly known, and a server log is a
    published surface. Names and a reason are enough to diagnose.
    """

    def __init__(self, reason: str, keys: Optional[list] = None):
        self.reason = reason
        self.keys = sorted(keys or [])
        super().__init__(reason)

# H1..H4 are the only parameters AmneziaWG lets a node express as a RANGE.
# device/magic-header.go parses "<start>-<end>" on exactly these four fields,
# and device/send.go calls Generate() once per packet, so a range makes the
# header word vary per datagram instead of being fixed for the life of the
# flow. Jc/Jmin/Jmax and S1..S4 are counts and byte lengths -- the engine
# parses them with strconv.Atoi and a range there is simply malformed.
AWG_OBFUSCATION_RANGE_KEYS = frozenset({"H1", "H2", "H3", "H4"})

def coerce_obfuscation_value(raw: Any, key: str = "") -> Any:
    # Only an exact, non-negative integer inside the uint32 the AmneziaWG wire
    # format can carry. bool is an int subclass and must not ride through as
    # 0/1; a float is accepted only when it is exact; a string only when it is
    # plain decimal. Everything else is a value this process cannot reproduce
    # faithfully, and "close enough" here is a silent rewrite of a parameter
    # that is never negotiated.
    #
    # For H1..H4 a "<start>-<end>" string is additionally accepted and returned
    # as a CANONICAL STRING, not decomposed. The hub is a courier here: it must
    # hand the client exactly what the node reported, and a range that came
    # back as two integers would have to be reassembled by every one of five
    # client platforms. A scalar still returns an int, so every existing
    # profile round-trips through the database and the served JSON unchanged --
    # byte for byte the same payload the fleet gets today.
    if isinstance(raw, str) and key in AWG_OBFUSCATION_RANGE_KEYS:
        text = raw.strip()
        match = re.fullmatch(r"([0-9]+)-([0-9]+)", text)
        if match:
            start = int(match.group(1))
            end = int(match.group(2))
            if not 0 <= start <= AWG_OBFUSCATION_MAX:
                raise ValueError("out-of-range")
            if not 0 <= end <= AWG_OBFUSCATION_MAX:
                raise ValueError("out-of-range")
            if end < start:
                raise ValueError("inverted-range")
            # A range spanning the entire keyspace wraps the engine's own
            # `end - start + 1` in uint32 and panics crypto/rand.Int. Refusing
            # it here is the difference between a 400 at registration and a
            # node that crashes on its first packet.
            if end - start + 1 > AWG_OBFUSCATION_MAX:
                raise ValueError("range-too-wide")
            return "%d-%d" % (start, end)
    if isinstance(raw, bool):
        raise ValueError("bool")
    if isinstance(raw, int):
        value = raw
    elif isinstance(raw, float):
        if not raw.is_integer():
            raise ValueError("fractional")
        value = int(raw)
    elif isinstance(raw, str):
        text = raw.strip()
        if not re.fullmatch(r"[0-9]+", text):
            raise ValueError("non-numeric")
        value = int(text)
    else:
        raise ValueError("unsupported-type")
    if not 0 <= value <= AWG_OBFUSCATION_MAX:
        raise ValueError("out-of-range")
    return value

def parse_obfuscation(value: Optional[str]) -> dict:
    """Return exactly the obfuscation profile a node reported, or raise.

    This used to be a bare ``try`` wrapped around the whole parse, so one
    unreadable value -- or an absent column -- silently reset all eleven
    parameters to DEFAULT_OBFUSCATION and served them to clients with no error
    and no log. AmneziaWG parameters are **not negotiated**: the client's
    packets simply stop matching what the node expects, so a substituted
    profile is not a weaker tunnel, it is a tunnel that cannot handshake, and
    it presents to the user as "the VPN is broken" with nothing anywhere
    saying why.

    The profile is therefore treated as **atomic and fail-closed**: either the
    hub can reproduce every parameter the node reported, or it refuses and the
    caller turns that into a loud, diagnosable error. Falling back to the
    node's real values is not an option available here -- if the stored blob
    cannot be read, the hub does not know the node's real values; the choice is
    only between refusing and guessing, and guessing is what broke.

    Unknown keys are the one non-fatal case: they are dropped (they are not in
    the client contract) but logged, so a future parameter cannot disappear in
    silence the way these did.
    """
    if not value or not str(value).strip():
        raise ObfuscationProfileError("missing")
    try:
        data = json.loads(value)
    except Exception:
        raise ObfuscationProfileError("not-json") from None
    if not isinstance(data, dict):
        raise ObfuscationProfileError("not-an-object")
    unknown = [k for k in data if k not in DEFAULT_OBFUSCATION]
    if unknown:
        logger.warning(
            "obfuscation profile carries %d key(s) outside the client contract (%s); dropping them",
            len(unknown), ",".join(sorted(str(k) for k in unknown)),
        )
    missing = [k for k in DEFAULT_OBFUSCATION if k not in data]
    if missing:
        raise ObfuscationProfileError("missing-keys", missing)
    parsed: dict = {}
    unusable: list = []
    for key in DEFAULT_OBFUSCATION:
        try:
            parsed[key] = coerce_obfuscation_value(data[key], key)
        except ValueError:
            unusable.append(key)
    if unusable:
        raise ObfuscationProfileError("unusable-values", unusable)
    return parsed

def parse_protocol_params(value: Optional[str]) -> dict:
    # Winn Protocol forward-compat seam -- mirrors parse_obfuscation above.
    # The shipping v1 protocol carries no protocol-specific material, so an
    # unset / blank slot yields an empty dict (a strict no-op).
    #
    # CORRECTED 2026-08-08 (hub winn/3 serving path lane). This comment used to
    # say v3 would serialize "its own material (ML-KEM public key, etc.)" into
    # protocol_params_json. It cannot: the shipped client sweeps every
    # protocol_params key against a closed allowlist and REFUSES the whole
    # connection on any key outside it -- post-quantum material explicitly
    # included (lib/winn_protocol_dispatch.dart:259-265 and :1055-1074). Key
    # material is named by device-local path and is never served
    # (lib/winn_carrier_profile_keys.dart:19-24). What may be stored here is
    # exactly WINN3_KNOWN_PROTOCOL_PARAMS below, and validate_winn3_protocol_params
    # is what keeps it that way.
    #
    # This function stays a verbatim pass-through on purpose: it is on the read
    # path, and a reader that silently repaired a bad stored blob would hide the
    # very drift the write-path validator exists to prevent. Validation belongs
    # at the write (admin) path, and the serving gate re-checks before serving.
    #
    # Malformed JSON and non-objects fail closed. Returning {} here would make a
    # corrupted winn/3 row look like an empty advertisement (direct-awg).
    if value is None:
        return {}
    text = str(value).strip()
    if not text:
        return {}
    try:
        data = json.loads(text)
    except Exception:
        raise Winn3ContractError("protocol-params-malformed") from None
    if not isinstance(data, dict):
        raise Winn3ContractError("protocol-params-not-an-object")
    return data

# --- Winn Protocol v3 serving contract (D1) ---------------------------------
#
# WHAT THIS IS. The hub can now advertise a node as winn/3 and a client can
# discover it. Everything below is a restatement of what the SHIPPED CLIENT
# will accept; nothing here is invented hub-side. The client is the authority
# because it fails CLOSED: a winn/3 config it cannot honour stops the
# connection and never falls back to winn/1 (the anti-downgrade rule,
# lib/main.dart:10764-10781). The hub matches that: a node registered winn/3
# is never rewritten to winn/1 when a check fails; the request is refused.
# Explicit winn/1 nodes, and client-requested v1 behaviour against those nodes,
# stay winn/1. A hub that advertised winn/3 loosely would not degrade a client,
# it would disconnect it -- so the hub must not advertise winn/3 by rewriting.
#
# Citations are to lib/winn_protocol_dispatch.dart unless stated otherwise.
# The full derivation is in docs/handoff/HUB_WINN3_SERVING_PATH_20260808.md.
WINN_PROTOCOL_V1 = "winn/1"
WINN_PROTOCOL_V3 = "winn/3"
WINN_V1_ENGINE_ORDER = ("amneziawg", "xray")
WINN_V1_LISTING_CARRIER = "amneziawg"

# datapath.CarrierDirectAWG / WinnEngineConfig.CARRIER_DIRECT_AWG (:163). The
# carrier an absent `carrier` normalizes to, and the only one that needs no
# carrier profile and no server-side component -- internal/directawg/candidate.go:1-4
# is explicit that it rides the node's EXISTING AmneziaWG UDP path and adds no
# second authentication protocol.
WINN3_CARRIER_DIRECT_AWG = "direct-awg"
# connectivity.CarrierHTTP3 (:168). Needs winn-carrier-server plus fourteen
# credential files on the node (wins_data_plane_setup_ONETOUCH.sh:7981-8003).
WINN3_CARRIER_HTTP3 = "http3-connect-udp"
# The STANDALONE carrier. `WinsTunnelConfig.supportedWinnCarrierWinn3`,
# `WinsWinn3.carrierName`, and the Go archive's `winn3Carrier` -- all three
# spell it `winn3`, and this constant exists so the hub spells it the same way
# once rather than three times.
#
# IT IS CATEGORICALLY DIFFERENT FROM THE OTHER TWO, and every special case
# below follows from the one difference. direct-awg and http3-connect-udp are
# RELAY carriers: AmneziaWG owns the tun, does all of the cryptography, and
# Winn carries its already-encapsulated outer datagrams. `winn3` is
# STANDALONE -- there is no AmneziaWG anywhere in it, the winn/3 session owns
# the datapath, and the bytes crossing the engine boundary are inner IP
# packets. So it needs no carrier profile (it is not a MASQUE transport), it
# cannot knock (SPA belongs to the http3 dialer), and the key-bearing fields it
# needs cannot travel through protocol_params at all -- see
# WINN3_PARAM_NAME_NEVER_SERVED, which would refuse `static_private` by design.
# They travel on the signed descriptor and on the per-device vpn_config keys.
WINN3_CARRIER_WINN3 = "winn3"
# kWinnSupportedCarriers (:186-189). `http2-stream` is deliberately absent.
WINN3_SUPPORTED_CARRIERS = (
    WINN3_CARRIER_DIRECT_AWG, WINN3_CARRIER_HTTP3, WINN3_CARRIER_WINN3,
)
# The carriers that need a carrier profile -- i.e. everything that is neither
# the profile-free relay default nor the standalone session. Written as a set
# difference rather than a literal so a carrier added above is refused a
# profile it does not have rather than silently exempted from one it needs.
WINN3_CARRIER_PROFILE_CARRIERS = tuple(
    c for c in WINN3_SUPPORTED_CARRIERS
    if c not in (WINN3_CARRIER_DIRECT_AWG, WINN3_CARRIER_WINN3)
)

# kWinnServedCarrierProfileKeys, generated from carrierhost.Profile's own json
# tags (lib/winn_carrier_profile_keys.dart:27-43).
WINN3_CARRIER_PROFILE_PARAMS = (
    "masque_template", "public_target", "server_name", "suite",
    "controller_id", "device_id", "device_pq_algorithm", "manifest_digest",
    "sequence_epoch", "max_inner_datagram", "privacy_profile",
    "spa_mode", "spa_target", "spa_packet_size",
    "spa_bucket_window_seconds", "spa_max_skew_seconds",
)
# kWinnRequiredCarrierProfileKeys (lib/winn_carrier_profile_keys.dart:46-55).
# Required only when the carrier is not direct-awg. No spa_* key is required,
# and a Go test (TestNoSPAKeyIsRequired) enforces that.
WINN3_REQUIRED_CARRIER_PARAMS = (
    "masque_template", "public_target", "server_name", "suite",
    "controller_id", "device_id", "device_pq_algorithm", "manifest_digest",
)
# kWinnSpaCarrierProfileKeys (lib/winn_carrier_profile_keys.dart:69-75).
WINN3_SPA_PARAMS = (
    "spa_mode", "spa_target", "spa_packet_size",
    "spa_bucket_window_seconds", "spa_max_skew_seconds",
)
# kWinnKnownProtocolParams (:259-265). TWENTY keys. Anything else is a refused
# connection on the client, so it must be a refused REGISTRATION here.
#
# h1..h4 are absent on purpose and must never be added: they have to match the
# headers the AmneziaWG engine is actually configured with, which come from
# obfuscation, so obfuscation stays their single source of truth (:255-258).
WINN3_KNOWN_PROTOCOL_PARAMS = (
    "gateway_endpoint", "max_datagram", "session_id", "carrier",
) + WINN3_CARRIER_PROFILE_PARAMS

WINN3_SPA_MODE_OFF = "off"
WINN3_SPA_MODE_REQUIRED = "required"

# datapath.MinDatagram / MaxDatagramCeiling (:148,151).
WINN3_MIN_DATAGRAM = 32
WINN3_MAX_DATAGRAM = 1500
# datapath.normalize: session_id may not exceed 128 bytes (:154).
WINN3_MAX_SESSION_ID_BYTES = 128
# knock.HeaderSize .. carrier.AbsoluteMaxDatagram (:1293,1299).
WINN3_SPA_MIN_PACKET_SIZE = 48
WINN3_SPA_MAX_PACKET_SIZE = 1500
# (:1303)
WINN3_SPA_MIN_BUCKET_WINDOW_SECONDS = 1
# WinnEngineConfig.from -- the MTU bound the native host enforces (:157-158).
# The hub serves 1280, which is inside it; asserted rather than assumed.
WINN3_MIN_MTU = 576
WINN3_MAX_MTU = 9000
# _isSafeIniValue (:1473-1483). A newline would forge an extra INI key -- and
# the keys around it include `endpoint` -- while [ and ] would forge a section
# header and could reopen [Interface] or [Peer].
WINN3_MAX_INI_VALUE_LEN = 512

# The STANDALONE winn/3 plan (ADDED 2026-08-10, ds_iosconfig3). These two
# assets are the client->engine seam the control plane had never touched:
# `path_mtu` and `carrier_classes` had ZERO occurrences in the control-plane
# source while every other host in the tree planned at carrier.DefaultPathMTU.
# The standalone client reads them per-device off vpn_config
# (winn_protocol_dispatch.dart:2173-2175, _winn3StandaloneStart) and hands them
# to driver.NewSizing, which REFUSES a plan that lands in the inner-IPv6 dead
# zone (winn3/driver/params.go:142-231) -- so a hub that advertised such a plan
# would disconnect every standalone client with no fallback, which is the
# fail-closed anti-downgrade rule this whole serving surface exists to keep.
#
# Every number below is mirrored from the Go source and PINNED against it by
# test_winn3_pathmtu_hub.py::test_plan_constants_do_not_drift, in the same
# spirit as the tag/bucket mirrors in test_winn3_descriptor_hub.py -- a second
# copy of a constant that silently disagrees with the implementation is the
# failure this project has already had once.
#
#   winn3/session/config.go:519  MinPathMTUForInnerIPv6 =
#                                  IPv6MinimumLinkMTU
#                                + core.TransportOverhead()
#                                + frameHeaderSize
#                                + carrier.Overhead(class, ipv6)
#   core/session.go:186          TransportOverhead = DemuxToken(8)
#                                                  + transportHeader(2)
#                                                  + AEADTag(16)   = 26
#   core/frame.go:65             frameHeaderSize = 3
#                              -> envelope = 29 bytes of Winn3 per message.
#   winn3/carrier/sizing.go:46   Overhead over IPv6:
#                                  udp = 40 + 8            = 48
#                                  tcp = 40 + 32 + 18       = 90
#                                  tls = 40 + 32 + 22 + 18  = 112
WINN3_TUN_ENVELOPE_OVERHEAD = 29
WINN3_IPV6_MINIMUM_LINK_MTU = 1280
WINN3_PLAN_IPV6_CARRIER_OVERHEAD = {
    "udp": 48,
    "tcp": 90,
    "tls": 112,
}
# winn3/carrier/carrier.go:80-95 -- the only classes the engine knows. Anything
# else parses to carrier.ClassUnknown and driver.NewSizing refuses the plan.
WINN3_CARRIER_CLASSES = ("udp", "tcp", "tls")
# winn3/carrier/sizing.go:137 -- carrier.DefaultPathMTU. THE FLEET DEFAULT that
# every host entry point resolves a missing `path_mtu` through, raised from
# 1280 on 2026-08-10 because 1280..1420 is the never-promotes dead zone. A node
# that registers no path_mtu plans at this.
WINN3_DEFAULT_PATH_MTU = 1450

# The client capability flags this hub understands, as winnClientCapabilities
# reports them (:1448-1457). Both default to FALSE for an absent field, which
# is what makes this whole change a no-op for every client already in the
# field: they do not send these, so they are never offered winn/3.
WINN3_CLIENT_CAPABILITY = "supports_winn3"
WINN3_SPA_CLIENT_CAPABILITY = "supports_winn3_spa"


class Winn3ContractError(Exception):
    """A winn/3 advertisement the shipped client would refuse.

    Carries key NAMES and a reason, never values -- the values are endpoints
    and profile identifiers.
    """

    def __init__(self, reason: str, keys: Optional[list] = None):
        self.reason = reason
        self.keys = sorted(str(k) for k in (keys or []))
        super().__init__(
            f"{reason}" + (f" ({', '.join(self.keys)})" if self.keys else "")
        )


def winn3_is_ip_literal_endpoint(value: Any) -> bool:
    """Mirror of isWinnIpLiteralEndpoint (:883-955).

    The Winn engine refuses a hostname because resolving one would leave the
    device outside the tunnel, so an endpoint that is not a literal is a
    refused connection rather than a slow one. Loopback IS accepted (the
    stacked stealth arrangement points at a local Xray inbound); the
    unspecified address and multicast are not.
    """
    text = str(value or "").strip()
    if not text:
        return False
    host, sep, port = "", "", ""
    if text.startswith("[") and "]:" in text:
        host, _, port = text.partition("]:")
        host = host[1:]
        sep = ":"
    elif text.count(":") == 1:
        host, sep, port = text.partition(":")
    else:
        return False
    if not sep or not host or not port.isdigit():
        return False
    if not (1 <= int(port) <= 65535):
        return False
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        return False
    return not (address.is_unspecified or address.is_multicast)


def winn3_is_inner_ipv4(value: Any) -> bool:
    """A bare dotted-quad IPv4 address, the form the `[winn]` inner fields take.

    NOT the endpoint form. `inner_v4` and `inner_router_v4` are addresses INSIDE
    the v3 tunnel and carry no port: `WinsWinn3SessionStart` reads them as the
    interface address and the inner next hop, and the winn/3 tun layer validates
    the source address of every packet the host offers against the assignment.
    A value with a port, a hostname, or an IPv6 literal is not something any
    host can turn into an interface address, so it is refused here rather than
    at a device that would fail closed at the deadline with
    `winn3_rx_dropped_invalid` as the only clue.

    Unspecified, multicast and loopback are refused for the same reason the
    endpoint validator refuses the first two: none of them can be a tunnel
    assignment or a next hop, and accepting one produces a session that starts
    and carries nothing.
    """
    text = str(value or "").strip()
    if not text or text.count(".") != 3:
        return False
    try:
        address = ipaddress.IPv4Address(text)
    except ValueError:
        return False
    return not (
        address.is_unspecified or address.is_multicast or address.is_loopback
    )


def winn3_operator_text_has_edge_whitespace(raw: bytes) -> bool:
    """True when decoded operator text carries leading or trailing whitespace.

    THIS IS THE THIRD SILENT-FAILURE TRAP, and the hub is the only place it can
    be caught before it ships. `gateway_id` is an authenticated input to the
    admission tag and is NEVER TRANSMITTED, so the two ends never discover they
    disagree about it. The hosts do not normalise it consistently -- the
    conformance suite MEASURED this on 2026-08-09 and holds it as the
    `operator-value-whitespace-normalisation` divergence:

        cmd/winn3-gateway    "winsgw01 " -> 9 bytes (the space kept)
        apple/WinsTunnelCore "winsgw01 " -> 9 bytes (agrees, by accident: its
                                            trim lands on the BASE64 text and
                                            never reaches the decoded bytes)
        android WinnV3Keys   "winsgw01 " -> 8 bytes (diverges: its value is
                                            plain text and .trim() lands on it)
        linux/runner         same position as Android -- its INI reader Trim()s
                                            every value on read

    So one stray space in an operator value ships a fleet where iOS connects and
    Android does not, with no error on either side, and the bug report reads
    "Android is broken". The suite's own Fix note names refusing whitespace
    everywhere as the safer of the two resolutions; this is that refusal, at the
    one surface every device's copy of the value passes through.
    """
    if not raw:
        return False
    return raw[:1].isspace() or raw[-1:].isspace()


def winn3_obfuscation_problems(obfuscation: dict) -> list:
    """Key names in `obfuscation` that would make a winn/3 start refuse.

    winn/3 is STRICTER here than winn/1, which is the trap this function
    exists for. winnAwgHeaderTypes (:1556-1579) requires H1..H4 to be present,
    non-blank, parseable as a 32-bit unsigned value (>= 5) or a range, and
    PAIRWISE NON-OVERLAPPING; winnAwgPaddingSizes (:1599-1618) requires S1..S4
    to be 0..65535. The client's own refusal message says why H1..H4 cannot be
    defaulted: "without them the transport convergence gate cannot fire and a
    dead tunnel would be reported as connected" (:1152-1155).

    Ranges are accepted by the client's parser but the fleet runs
    AWG_HEADER_RANGES=0 and the four native winn/3 hosts parse h1..h4 into a
    uint32 apiece (wins_data_plane_setup_ONETOUCH.sh:442-452), so a range here
    is reported as a problem rather than quietly allowed.
    """
    problems: list = []
    values: dict = {}
    for key in ("H1", "H2", "H3", "H4"):
        raw = str(obfuscation.get(key, "") or "").strip()
        if not raw:
            problems.append(key)
            continue
        if "-" in raw:
            # A range. Legal to the Dart parser, not to the native hosts.
            problems.append(key)
            continue
        try:
            parsed = int(raw)
        except (TypeError, ValueError):
            problems.append(key)
            continue
        if parsed < 5 or parsed > 0xFFFFFFFF:
            problems.append(key)
            continue
        values[key] = parsed
    seen: dict = {}
    for key, parsed in values.items():
        if parsed in seen:
            problems.append(key)
        else:
            seen[parsed] = key
    for key in ("S1", "S2", "S3", "S4"):
        raw = obfuscation.get(key)
        if raw is None or str(raw).strip() == "":
            continue  # client defaults 16/80/16/0
        try:
            parsed = int(str(raw).strip())
        except (TypeError, ValueError):
            problems.append(key)
            continue
        if parsed < 0 or parsed > 0xFFFF:
            problems.append(key)
    return sorted(set(problems))


def _winn3_int_param(params: dict, key: str) -> Optional[int]:
    raw = str(params.get(key, "") or "").strip()
    if not raw:
        return None
    try:
        return int(raw)
    except ValueError:
        raise Winn3ContractError("param-not-an-integer", [key]) from None


def validate_winn3_protocol_params(params: Any) -> dict:
    """Normalize and validate a winn/3 protocol_params blob, or raise.

    This is the validator the node-registration path explicitly declined to
    write ("Writing that validator is Winn Protocol v3 design work", see
    register_node). It runs on the WRITE path -- POST /admin/nodes/winn3 --
    so that a malformed advertisement is one 400 to one operator instead of a
    refused connection for every client that node ever serves.

    Returns a dict with lowercase keys and string values, ready to be stored
    as protocol_params_json and handed to the client verbatim. Every rule is
    the client's rule; see the citation on each check.
    """
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise Winn3ContractError("params-not-an-object")

    # The client compares k.toString().trim().toLowerCase() against the
    # allowlist (:1067-1070), so a key that differs only in case is a DIFFERENT
    # key to storage and the SAME key to the sweep. Normalize, and refuse a
    # collision rather than pick a winner.
    normalized: dict = {}
    for raw_key, raw_value in params.items():
        key = str(raw_key or "").strip().lower()
        if not key:
            raise Winn3ContractError("blank-param-name")
        if key in normalized:
            raise Winn3ContractError("duplicate-param-after-normalization", [key])
        if isinstance(raw_value, bool):
            raise Winn3ContractError("param-not-a-scalar", [key])
        if isinstance(raw_value, (dict, list)):
            raise Winn3ContractError("param-not-a-scalar", [key])
        normalized[key] = "" if raw_value is None else str(raw_value).strip()

    unknown = [k for k in normalized if k not in WINN3_KNOWN_PROTOCOL_PARAMS]
    if unknown:
        # The client refuses the whole connection on any of these (:1071-1081).
        # h1..h4 land here, which is correct: obfuscation owns them (:255-258).
        raise Winn3ContractError("unknown-params", unknown)

    # gateway_endpoint (:1084-1099). Optional: absent means the client falls
    # back to vpn_config.server_endpoint, which is the node's own AWG endpoint.
    endpoint = normalized.get("gateway_endpoint", "")
    if endpoint and not winn3_is_ip_literal_endpoint(endpoint):
        raise Winn3ContractError("gateway-endpoint-not-ip-literal", ["gateway_endpoint"])

    # max_datagram (:1104-1119).
    max_datagram = _winn3_int_param(normalized, "max_datagram")
    if max_datagram is not None and not (
        WINN3_MIN_DATAGRAM <= max_datagram <= WINN3_MAX_DATAGRAM
    ):
        raise Winn3ContractError("max-datagram-out-of-range", ["max_datagram"])

    # session_id (:1121-1142). The forbidden characters are the ones that
    # would forge an extra INI key or a section header.
    session_id = normalized.get("session_id", "")
    if len(session_id.encode("utf-8")) > WINN3_MAX_SESSION_ID_BYTES:
        raise Winn3ContractError("session-id-too-long", ["session_id"])
    if any(ch in session_id for ch in ("\n", "\r", "[", "]")):
        raise Winn3ContractError("session-id-malformed", ["session_id"])

    # carrier (:1183-1206). Absent normalizes to direct-awg (:1194-1195).
    carrier = normalized.get("carrier", "").lower()
    resolved_carrier = carrier or WINN3_CARRIER_DIRECT_AWG
    if resolved_carrier not in WINN3_SUPPORTED_CARRIERS:
        raise Winn3ContractError("carrier-unsupported", ["carrier"])
    if carrier:
        normalized["carrier"] = resolved_carrier

    if resolved_carrier not in WINN3_CARRIER_PROFILE_CARRIERS:
        # Carrier-profile params are inert on direct-awg -- the client never
        # reads them into a profile (:1219-1245). Storing them anyway would be
        # an operator believing a profile is in force that is not, which is the
        # exact failure mode the spa_* refusal was written against. Refuse.
        #
        # `winn3` takes this branch for a DIFFERENT reason that lands in the
        # same place: a standalone session dials its own transport with its own
        # handshake and reads no MASQUE profile at all, so a profile param on a
        # winn3 node is exactly as inert as one on a direct-awg node, and
        # exactly as misleading to the operator who set it.
        #
        # The spa_* subset is deliberately EXCLUDED from this sweep and left to
        # the SPA block below, which is the order the client validates in
        # (carrier first, then SPA, ":1247-1249") and which produces the
        # accurate reason: an operator who put spa_mode=required on a direct-awg
        # node needs to be told the carrier cannot carry a knock, not that a
        # profile field is stray.
        stray = [
            k for k in WINN3_CARRIER_PROFILE_PARAMS
            if k not in WINN3_SPA_PARAMS and normalized.get(k, "")
        ]
        if stray:
            raise Winn3ContractError("carrier-profile-params-without-carrier", stray)
    else:
        missing = [
            k for k in WINN3_REQUIRED_CARRIER_PARAMS
            if not normalized.get(k, "")
        ]
        if missing:
            raise Winn3ContractError("carrier-profile-incomplete", missing)
        # _isSafeIniValue (:1473-1483), applied to every carrier param rather
        # than a chosen few: they all travel the same untrusted path.
        unsafe = []
        for key in WINN3_CARRIER_PROFILE_PARAMS:
            value = normalized.get(key, "")
            if not value:
                continue
            if len(value) > WINN3_MAX_INI_VALUE_LEN:
                unsafe.append(key)
                continue
            if any(ord(ch) < 0x20 or ord(ch) == 0x7F or ch in "[]" for ch in value):
                unsafe.append(key)
        if unsafe:
            raise Winn3ContractError("carrier-param-unsafe-for-ini", unsafe)

    # SPA (_spaRefusal, :1315-1421). Validated AFTER the carrier, because
    # whether SPA can be honoured at all depends on which carrier this is.
    mode = normalized.get("spa_mode", "").lower()
    if mode:
        normalized["spa_mode"] = mode
    other_spa = sorted(
        k for k in WINN3_SPA_PARAMS
        if k != "spa_mode" and normalized.get(k, "")
    )
    if not mode or mode == WINN3_SPA_MODE_OFF:
        if other_spa:
            # The engine's own rule (ErrSPAFieldWithoutMode): a target left
            # behind after SPA was turned off is an operator believing a
            # defence is armed that is not.
            raise Winn3ContractError("spa-params-without-mode", other_spa)
    else:
        if mode != WINN3_SPA_MODE_REQUIRED:
            raise Winn3ContractError("spa-mode-unsupported", ["spa_mode"])
        if resolved_carrier != WINN3_CARRIER_HTTP3:
            # knockdial.New refuses both other cases at CONSTRUCTION (:1352-1361).
            raise Winn3ContractError("spa-carrier-cannot-knock", ["spa_mode", "carrier"])
        if not winn3_is_ip_literal_endpoint(normalized.get("spa_target", "")):
            raise Winn3ContractError("spa-target-not-ip-literal", ["spa_target"])
        packet = _winn3_int_param(normalized, "spa_packet_size")
        if packet is not None and not (
            WINN3_SPA_MIN_PACKET_SIZE <= packet <= WINN3_SPA_MAX_PACKET_SIZE
        ):
            raise Winn3ContractError("spa-packet-size-out-of-range", ["spa_packet_size"])
        bucket = _winn3_int_param(normalized, "spa_bucket_window_seconds")
        skew = _winn3_int_param(normalized, "spa_max_skew_seconds")
        if bucket is not None and bucket < WINN3_SPA_MIN_BUCKET_WINDOW_SECONDS:
            raise Winn3ContractError("spa-timing-unusable", ["spa_bucket_window_seconds"])
        if skew is not None and skew < 0:
            raise Winn3ContractError("spa-timing-unusable", ["spa_max_skew_seconds"])
        if bucket is not None and skew is not None and skew < bucket:
            # A mismatch fails CLOSED and is completely silent: no knock ever
            # verifies and nothing reports an error anywhere (:1394-1398).
            raise Winn3ContractError(
                "spa-timing-unusable", ["spa_bucket_window_seconds", "spa_max_skew_seconds"]
            )

    # Drop keys that normalized to empty. An empty value is indistinguishable
    # from absent to the client, and omission cannot be misread
    # (lib/winn_carrier_profile_keys.dart:58-67).
    return {k: v for k, v in normalized.items() if v != ""}


def require_production_winn3_registration_params(params: Any) -> dict:
    """Production winn/3 registration: exact standalone carrier, nonempty params."""
    if not isinstance(params, dict) or not params:
        raise Winn3ContractError("protocol-params-empty", ["carrier"])
    carrier = str(params.get("carrier") or "").strip().lower()
    if carrier != WINN3_CARRIER_WINN3:
        raise Winn3ContractError("carrier-not-standalone-winn3", ["carrier"])
    validated = validate_winn3_protocol_params(params)
    if not validated:
        raise Winn3ContractError("protocol-params-empty", ["carrier"])
    if str(validated.get("carrier") or "") != WINN3_CARRIER_WINN3:
        raise Winn3ContractError("carrier-not-standalone-winn3", ["carrier"])
    return validated


# Exact Smart Router RequestId: 8-64 chars, first alphanumeric, then
# alphanumerics plus . _ : -. Empty/absent is "no generation".
SELECTION_GENERATION_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{7,63}$")


def typed_selection_generation(value: Any) -> str:
    """Return a RequestId-shaped generation, or empty. Reject malformed values."""
    if value is None:
        return ""
    if not isinstance(value, str):
        raise ValueError("selection generation must be a string")
    if not value:
        return ""
    if not SELECTION_GENERATION_RE.fullmatch(value):
        raise ValueError("selection generation is malformed")
    return value


def typed_selection_generations(payload: Any) -> tuple[str, str]:
    """Exact typed pair from a LoginRequest or FreeAccessRequest."""
    try:
        generation = typed_selection_generation(
            getattr(payload, "selection_generation", None)
        )
        authorized = typed_selection_generation(
            getattr(payload, "ordinary_v3_failure_generation", None)
        )
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid selection generation.")
    return generation, authorized


def v1_ordinary_failure_authorized(
    selection_generation: Any = "",
    ordinary_v3_failure_generation: Any = "",
) -> bool:
    """True only for a positively matching generation-bound ordinary v3 failure."""
    try:
        generation = typed_selection_generation(selection_generation)
        authorized = typed_selection_generation(ordinary_v3_failure_generation)
    except ValueError:
        return False
    return bool(generation) and generation == authorized


def _node_field(node: Any, name: str) -> Any:
    """Read a column off a node row OR a dict, whichever the caller holds."""
    if hasattr(node, "keys") and name in node.keys():
        return node[name]
    if hasattr(node, "get"):
        return node.get(name)
    return None


def strict_stored_protocol_version(node: Any) -> str:
    raw = _node_field(node, "protocol_version")
    if not isinstance(raw, str):
        raise Winn3ContractError(
            "protocol-version-invalid",
            ["protocol_version"],
        )
    version = raw.strip().lower()
    if version not in (WINN_PROTOCOL_V1, WINN_PROTOCOL_V3):
        raise Winn3ContractError(
            "protocol-version-invalid",
            ["protocol_version"],
        )
    return version


def node_protocol_route_metadata(node: Any) -> Optional[dict]:
    """Exact public/smart-router protocol classification, or None if unusable.

    A registered winn/3 row with missing carrier or malformed params never
    becomes an empty/defaulted advertisement.
    """
    try:
        version = strict_stored_protocol_version(node)
    except Winn3ContractError:
        return None
    try:
        params = parse_protocol_params(_node_field(node, "protocol_params_json"))
    except Winn3ContractError:
        if version == WINN_PROTOCOL_V3:
            return None
        params = {}
    if version == WINN_PROTOCOL_V3:
        carrier = str(params.get("carrier") or "").strip().lower()
        if not carrier or carrier not in WINN3_SUPPORTED_CARRIERS:
            return None
        return {
            "protocol_version": WINN_PROTOCOL_V3,
            "carrier": carrier,
        }
    return {
        "protocol_version": WINN_PROTOCOL_V1,
        "carrier": WINN_V1_LISTING_CARRIER,
        "v1_engine_order": list(WINN_V1_ENGINE_ORDER),
    }


def node_is_compatible_standalone_winn3(node: Any) -> bool:
    meta = node_protocol_route_metadata(node)
    return bool(
        meta
        and meta.get("protocol_version") == WINN_PROTOCOL_V3
        and meta.get("carrier") == WINN3_CARRIER_WINN3
    )


def protocol_eligible_node_rows(
    rows: list,
    *,
    selection_generation: Any = "",
    ordinary_v3_failure_generation: Any = "",
    healthy: Optional[Any] = None,
) -> list:
    """Restrict a node row set the same way Smart Router protocol selection does."""
    classified = []
    for row in list(rows or []):
        if node_protocol_route_metadata(row) is None:
            continue
        classified.append(row)
    rows = classified
    def is_healthy(row: Any) -> bool:
        if healthy is None:
            return True
        return bool(healthy(row))

    standalone = [row for row in rows if node_is_compatible_standalone_winn3(row)]
    healthy_v3 = [row for row in standalone if is_healthy(row)]
    if healthy_v3:
        return healthy_v3
    authorized = v1_ordinary_failure_authorized(
        selection_generation, ordinary_v3_failure_generation
    )
    if standalone and not authorized:
        return standalone
    if standalone and authorized:
        v1_rows = [
            row for row in rows
            if (node_protocol_route_metadata(row) or {}).get("protocol_version")
            == WINN_PROTOCOL_V1
        ]
        return v1_rows or standalone
    return rows


def winn3_params_require_spa(params: dict) -> bool:
    return str(params.get("spa_mode", "") or "").strip().lower() == WINN3_SPA_MODE_REQUIRED



def parse_winn3_carrier_classes(value: Optional[Any]) -> list:
    """The migration plan stored on the node, as a list of class names.

    Stored comma-separated (the same shape the client emits as the INI
    `carrier_classes = udp,tcp,tls` line that the engine splits on). Blank or
    absent yields an empty list -- a standalone node with no plan is a
    registration error, NEVER a silently-udp-only default, for the reason
    documented on the client side: the engine substitutes an empty plan with
    {"udp"}, which forbids migration and disagrees with the gateway's floor
    (the empty-plan-handling divergence). This function never invents a plan.
    """
    if value is None:
        return []
    raw = str(value).strip()
    if not raw:
        return []
    out: list = []
    for piece in raw.split(","):
        name = piece.strip().lower()
        if name:
            out.append(name)
    return out


def winn3_effective_path_mtu(node: Any) -> int:
    """The OUTER path MTU this node plans at: its registration or the fleet
    default, exactly the resolution driver/carrier make for a missing path_mtu."""
    raw = _node_field(node, "path_mtu")
    if raw is None:
        return WINN3_DEFAULT_PATH_MTU
    try:
        value = int(raw)
    except (TypeError, ValueError):
        return WINN3_DEFAULT_PATH_MTU
    return value if value > 0 else WINN3_DEFAULT_PATH_MTU


def winn3_plan_floor_threshold(carrier_classes) -> int:
    """The outer path MTU where this plan stops being the never-promotes dead
    zone: 1280 + envelope(29) + the widest class's IPv6 overhead, which is the
    value driver.NewSizing compares against (winn3/driver/params.go:220-231,
    computed as the MAX of MinPathMTUForInnerIPv6 over the plan's classes and
    both address families -- IPv6 always binds, being 20 bytes wider)."""
    classes = list(carrier_classes or [])
    if not classes:
        return WINN3_IPV6_MINIMUM_LINK_MTU + WINN3_TUN_ENVELOPE_OVERHEAD
    widest = max(
        WINN3_PLAN_IPV6_CARRIER_OVERHEAD[c]
        for c in classes
        if c in WINN3_PLAN_IPV6_CARRIER_OVERHEAD
    )
    return (
        WINN3_IPV6_MINIMUM_LINK_MTU
        + WINN3_TUN_ENVELOPE_OVERHEAD
        + widest
    )


def winn3_standalone_plan_servable(path_mtu: int, carrier_classes: list) -> tuple:
    """Whether the CLIENT's engine will accept this standalone plan.

    Returns (servable, reason). The mirror of driver.NewSizing exactly: it
    refuses an empty plan, an unknown or duplicated class, and any plan whose
    path MTU lands in the 1280..threshold dead zone -- a session there
    resolves, bootstraps and CARRIES and can never promote, while the client
    would refuse the config outright. Saying yes here and having the client
    refuse is worse than saying no (winn/1 works); the client anti-downgrade
    rule means there is no partial state.
    """
    classes = list(carrier_classes or [])
    if not classes:
        return False, "path-mtu-plan-empty"
    if any(c not in WINN3_CARRIER_CLASSES for c in classes):
        return False, "path-mtu-plan-unknown-class"
    if len(set(classes)) != len(classes):
        return False, "path-mtu-plan-duplicate-class"
    if "udp" not in classes:
        # The current production datapath can size tcp/tls cover classes but
        # opens its actual carrier socket over UDP. Accepting a tcp/tls-only
        # plan would advertise a session every shipping client must refuse at
        # engine creation. Keep cover classes optional, but require the one
        # transport the deployed datapath can originate.
        return False, "path-mtu-plan-missing-udp"
    if path_mtu <= 0 or path_mtu > WINN3_MAX_MTU:
        return False, "path-mtu-out-of-range"
    if path_mtu < winn3_plan_floor_threshold(classes):
        return False, "path-mtu-dead-zone"
    return True, ""


def winn3_standalone_plan_for_node(node: Any) -> tuple:
    """The full standalone plan decision for one node.

    Returns (servable, reason, effective_path_mtu, classes). ONE function on
    the gate path AND the emission path so the two can never disagree about
    what a node is allowed to serve -- serving a plan the gate refused would be
    the "second piece of logic" the descriptor serving gate refuses to keep.
    """
    classes = parse_winn3_carrier_classes(_node_field(node, "carrier_classes"))
    path_mtu = winn3_effective_path_mtu(node)
    servable, reason = winn3_standalone_plan_servable(path_mtu, classes)
    return servable, reason, path_mtu, classes

WINN3_CANARY_HARD_STALE_MINUTES = int(
    os.getenv("WINN3_CANARY_HARD_STALE_MINUTES", "30") or 30
)

WINN3_CANARY_RESULT_DIR = Path("/var/lib/wins-canary-results")

def winn3_result_binding(node: Any) -> dict:
    data = dict(node)
    # Until H2 stores an identity digest the identity binds as "" (design
    # 3.17's pre-identity value), and a row with no valid stored descriptor
    # binds seq 0. The canary computes the same values, so a result still
    # binds to the slug's descriptor and generation, and a later identity,
    # descriptor or generation makes it stale.
    identity = data.get("winn3_identity_sha256") or ""
    generation = data.get("deployment_generation")
    if not isinstance(identity, str) or (identity and not re.fullmatch(r"[0-9a-f]{64}", identity)):
        raise ValueError("invalid identity binding")
    try:
        envelope = json.loads(data.get("winn3_descriptor_json") or "")
        seq = json.loads(base64.b64decode(envelope["payload"], validate=True))["seq"]
    except (ValueError, TypeError, KeyError):
        seq = 0
    if type(seq) is not int or seq <= 0:
        seq = 0
    if type(generation) is not int or generation < 0:
        raise ValueError("invalid deployment generation")
    return {"identity_sha256": identity, "seq": seq, "generation": generation}

def ingest_winn3_canary_result(conn: sqlite3.Connection, result: Any, expected_slug: str) -> bool:
    fields = {"slug", "status", "detail", "identity_sha256", "seq", "generation", "checked_at"}
    if not isinstance(result, dict) or set(result) != fields:
        return False
    slug = result["slug"]
    if not isinstance(slug, str) or not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,62}", slug) or slug != expected_slug:
        return False
    if result["status"] not in ("ok", "fail") or not isinstance(result["detail"], str) or len(result["detail"]) > 300:
        return False
    if type(result["seq"]) is not int or type(result["generation"]) is not int:
        return False
    try:
        checked = datetime.fromisoformat(result["checked_at"])
        if checked.tzinfo is None:
            return False
        checked = checked.astimezone(timezone.utc).replace(tzinfo=None)
        now = utcnow()
        if now.tzinfo is not None:
            now = now.astimezone(timezone.utc).replace(tzinfo=None)
        if checked > now + timedelta(seconds=60) or checked < now - timedelta(minutes=WINN3_CANARY_HARD_STALE_MINUTES):
            return False
        row = conn.execute("SELECT * FROM nodes WHERE slug=?", (slug,)).fetchone()
        if row is None or dict(row).get("retired_at"):
            return False
        binding = winn3_result_binding(row)
        if any(result[key] != value for key, value in binding.items()):
            return False
        previous = row["winn3_canary_checked_at"]
        if previous and checked <= datetime.fromisoformat(previous).replace(tzinfo=None):
            return False
    except (ValueError, TypeError, KeyError, OverflowError):
        return False
    stamp = checked.isoformat()
    cursor = conn.execute(
        "UPDATE nodes SET winn3_canary_status=?, winn3_canary_checked_at=?, "
        "winn3_canary_ok_at=CASE WHEN ?='ok' THEN ? ELSE winn3_canary_ok_at END, "
        "winn3_canary_error=?, winn3_canary_identity_sha256=?, winn3_canary_seq=?, winn3_canary_generation=? "
        "WHERE slug=? AND COALESCE(winn3_identity_sha256, '')=? AND deployment_generation=? AND winn3_descriptor_json IS ? "
        "AND winn3_canary_checked_at IS ? AND (retired_at IS NULL OR retired_at='')",
        (result["status"], stamp, result["status"], stamp, result["detail"], binding["identity_sha256"],
         binding["seq"], binding["generation"], slug, binding["identity_sha256"], binding["generation"],
         row["winn3_descriptor_json"], previous),
    )
    return cursor.rowcount == 1

# Cache only successfully committed results; refused results remain retryable.
# A sweep opens at most one connection, only once a result reaches the
# database, and commits or rolls back each result on its own (Sol-H0-T3-PERF-1).
# A failed rollback aborts the sweep, so no later result commits on a
# connection whose transaction state is unknown (Sol-H0-T5-1).
WINN3_CANARY_RESULTS_SEEN: dict = {}
_WINN3_CANARY_RESULT_CURSOR = ""
_WINN3_CANARY_RESULT_CURSOR_LOCK = threading.Lock()

def ingest_winn3_canary_results_once() -> int:
    global _WINN3_CANARY_RESULT_CURSOR
    accepted = 0
    try:
        directory = os.open(WINN3_CANARY_RESULT_DIR, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    except FileNotFoundError:
        return 0
    with ExitStack() as session:
        session.callback(os.close, directory)
        conn = None
        with _WINN3_CANARY_RESULT_CURSOR_LOCK:
            names = sorted(
                name for name in os.listdir(directory)
                if re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,62}\.json", name)
            )
            for name in set(WINN3_CANARY_RESULTS_SEEN).difference(names):
                del WINN3_CANARY_RESULTS_SEEN[name]
            if not names:
                _WINN3_CANARY_RESULT_CURSOR = ""
                return 0
            start = next(
                (index for index, name in enumerate(names)
                 if name > _WINN3_CANARY_RESULT_CURSOR),
                0,
            )
            batch = (names[start:] + names[:start])[:64]
            _WINN3_CANARY_RESULT_CURSOR = batch[-1]
        for name in batch:
            try:
                fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory)
                with os.fdopen(fd, "rb") as stream:
                    info = os.fstat(stream.fileno())
                    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o022:
                        continue
                    key = (info.st_ino, info.st_dev, info.st_mtime_ns, info.st_ctime_ns, info.st_size)
                    if WINN3_CANARY_RESULTS_SEEN.get(name) == key:
                        continue
                    encoded = stream.read(4097)
                if len(encoded) > 4096:
                    continue
                result = json.loads(encoded)
                if conn is None:
                    conn = session.enter_context(get_db())
                try:
                    applied = ingest_winn3_canary_result(conn, result, name[:-5])
                    conn.commit()
                except BaseException:
                    try:
                        conn.rollback()
                    except BaseException as rollback_error:
                        raise RuntimeError("Canary result rollback failed; sweep aborted") from rollback_error
                    raise
                if applied:
                    accepted += 1
                    WINN3_CANARY_RESULTS_SEEN[name] = key
            except (OSError, ValueError, TypeError, sqlite3.Error):
                logger.warning("Canary result refused for %s", name[:-5])
    return accepted

async def winn3_canary_result_sweep_loop() -> None:
    while True:
        try:
            await asyncio.to_thread(ingest_winn3_canary_results_once)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("Canary result ingestion failed: %s", type(exc).__name__)
        await asyncio.sleep(5)

def winn3_canary_is_fresh(node: Any) -> bool:
    """Positive, recent proof that a real external Winn3 session carried data."""
    if str(_node_field(node, "winn3_canary_status") or "unknown") != "ok":
        return False
    data = dict(node)
    try:
        binding = winn3_result_binding(node)
        if not binding["identity_sha256"]:
            return False
        if any(data.get("winn3_canary_" + key) != value for key, value in binding.items()):
            return False
        released = parse_iso_datetime(data.get("deployment_released_at"))
        flipped = parse_iso_datetime(data.get("winn3_carrier_flipped_at"))
        if released is None or flipped is None or flipped < released:
            return False
        checked = parse_iso_datetime(data.get("winn3_canary_ok_at"))
        now = utcnow().replace(tzinfo=timezone.utc)
        if checked is None or not now - timedelta(minutes=WINN3_CANARY_HARD_STALE_MINUTES) <= checked <= now + timedelta(seconds=60):
            return False
        # A live result must follow the deployment completion and the carrier
        # flip. A fresh pre-sign or prospective proof cannot satisfy go-live.
        for field in ("deployment_completed_at", "deployment_released_at", "winn3_carrier_flipped_at"):
            raw = data.get(field)
            boundary = parse_iso_datetime(raw)
            if raw not in (None, "") and boundary is None:
                return False
            if boundary is not None and checked <= boundary:
                return False
        return True
    except (ValueError, KeyError, TypeError):
        return False


# SYNC-03 (2026-09-29): one canary probe identity per winn/3 node. The
# installer validates both forms before writing either (see
# validate_winn3_canary_runtime_settings); this reader trusts the shape it
# needs and nothing more, and reads the environment at call time.
#   legacy tuple: WINN3_CANARY_NODE_SLUG, _STATIC_PUBLIC, _INNER_V4
#   list:         WINN3_CANARY_NODES = "slug|static_public|inner_v4|key_dir|gateway_endpoint|gateway_id ..."
WINN3_CANARY_NODES_FIELD_COUNT = 6


def winn3_canary_bindings() -> tuple:
    """({slug: {"static_public", "inner_v4"}}, {slugs bound more than once}).

    A slug named twice is returned as a conflict rather than resolved, so the
    registry build for that node refuses instead of guessing which probe
    identity is meant. An entry without six fields cannot be attributed to a
    node and is skipped (logged); that node then carries no canary and its
    canary fails closed exactly as an unconfigured one does.
    """
    bindings: dict = {}
    conflicts: set = set()

    def add(slug: str, public: str, inner: str, key_dir: str = "", endpoint: str = "", gateway_id: str = "") -> None:
        slug = str(slug or "").strip().lower()
        if not slug:
            return
        if slug in bindings:
            conflicts.add(slug)
            return
        bindings[slug] = {
            "static_public": str(public or "").strip(),
            "inner_v4": str(inner or "").strip(),
            "key_dir": key_dir, "gateway_endpoint": endpoint, "gateway_id": gateway_id,
        }

    legacy_slug = str(os.getenv("WINN3_CANARY_NODE_SLUG", "") or "").strip().lower()
    if legacy_slug:
        add(
            legacy_slug,
            os.getenv("WINN3_CANARY_STATIC_PUBLIC", ""),
            os.getenv("WINN3_CANARY_INNER_V4", ""),
            os.getenv("WINN3_CANARY_KEY_DIR", ""),
            os.getenv("WINN3_CANARY_GATEWAY_ENDPOINT", ""),
            os.getenv("WINN3_CANARY_GATEWAY_ID", ""),
        )
    for index, entry in enumerate(str(os.getenv("WINN3_CANARY_NODES", "") or "").split(), start=1):
        fields = entry.split("|")
        if len(fields) != WINN3_CANARY_NODES_FIELD_COUNT:
            logger.error("WINN3_CANARY_NODES entry %d is malformed; skipped", index)
            continue
        add(*fields)
    if not legacy_slug and not os.getenv("WINN3_CANARY_NODES", "").strip():
        with get_db() as conn:
            if conn.execute("SELECT 1 FROM sqlite_master WHERE name='winn3_canary_bindings'").fetchone():
                for row in conn.execute("SELECT * FROM winn3_canary_bindings ORDER BY slug"):
                    add(*(row[name] for name in ("slug", "static_public", "inner_v4", "key_dir", "gateway_endpoint", "gateway_id")))
    return bindings, conflicts


def winn3_canary_binding_for(node_slug: str) -> Optional[dict]:
    """The canary binding published on one node, or None when it has none."""
    slug = str(node_slug or "").strip().lower()
    bindings, conflicts = winn3_canary_bindings()
    if slug in conflicts:
        raise ValueError("configured Winn3 canary names this node more than once")
    return bindings.get(slug)


def winn3_canary_reserved_inner_addresses() -> set:
    """Every inner address a configured canary uses, on any node."""
    bindings, _ = winn3_canary_bindings()
    return {b["inner_v4"] for b in bindings.values() if b["inner_v4"]}


def winn3_canary_reserved_publics() -> set:
    """Every static public key a configured canary uses, on any node."""
    bindings, _ = winn3_canary_bindings()
    return {b["static_public"] for b in bindings.values() if b["static_public"]}


def winn3_canary_device_collisions(conn: sqlite3.Connection) -> dict:
    """{slug: [blocker, ...]} for canary bindings a device already holds.

    The reservation above stops NEW allocations; a device issued the address
    (or holding the key) before the canary was configured still collides, and
    winn3_peer_registry_publication then refuses that node's whole snapshot.
    Checked against every device, not only the node's own: the inner address
    is fleet-unique and a device keeps it when it moves.
    """
    bindings, _ = winn3_canary_bindings()
    collisions: dict = {}
    for slug, binding in bindings.items():
        names = []
        if binding["inner_v4"] and conn.execute(
            "SELECT 1 FROM devices WHERE winn3_inner_v4 = ? LIMIT 1", (binding["inner_v4"],)
        ).fetchone():
            names.append("winn3_canary_inner_v4_held_by_device")
        if binding["static_public"] and conn.execute(
            "SELECT 1 FROM devices WHERE winn3_static_public = ? LIMIT 1", (binding["static_public"],)
        ).fetchone():
            names.append("winn3_canary_static_public_held_by_device")
        if names:
            collisions[slug] = names
    return collisions


def maybe_apply_install_time_standalone_carrier(
    conn: sqlite3.Connection,
    slug: str,
    *,
    prior_endpoint: Optional[str] = None,
) -> None:
    """Opt-in: on FIRST insert of the operator-named slug, store carrier=winn3.

    Default OFF. Never flips a node that already existed (prior_endpoint set),
    never flips a slug the operator did not name,     never overwrites a stored
    non-empty protocol_params_json. Production POST /admin/nodes/winn3
    requires carrier=winn3 and nonempty params -- this function is not that
    path. register_node does not call it (H2): a registration could not
    carry the sticky operator hold or a served-profile proof into this write.
    """
    flag = (os.getenv("WINN3_SET_CARRIER_STANDALONE") or "0").strip()
    if flag != "1":
        return
    wanted = (os.getenv("WINN3_STANDALONE_NODE_SLUG") or "").strip().lower()
    node_slug = (slug or "").strip().lower()
    if not wanted or not node_slug or node_slug != wanted:
        return
    if prior_endpoint is not None:
        # Re-registration of an existing row. Do not change operator-set state.
        return
    row = conn.execute(
        "SELECT protocol_params_json, protocol_version FROM nodes WHERE slug = ?",
        (node_slug,),
    ).fetchone()
    if row is None:
        return
    stored_params = row["protocol_params_json"]
    if stored_params not in (None, "", "{}"):
        return
    stored_version = str(row["protocol_version"] or "").strip().lower()
    if stored_version and stored_version not in (WINN_PROTOCOL_V1, ""):
        return
    mtu_raw = (os.getenv("WINN3_STANDALONE_PATH_MTU") or str(WINN3_DEFAULT_PATH_MTU)).strip()
    classes_raw = (os.getenv("WINN3_STANDALONE_CARRIER_CLASSES") or "udp").strip()
    try:
        mtu = int(mtu_raw)
    except (TypeError, ValueError):
        logger.error(
            "install-time standalone carrier: WINN3_STANDALONE_PATH_MTU is not "
            "an integer; leaving %s unchanged",
            node_slug,
        )
        return
    classes = parse_winn3_carrier_classes(classes_raw)
    ok, reason = winn3_standalone_plan_servable(mtu, classes)
    if not ok:
        logger.error(
            "install-time standalone carrier: plan not servable (%s); leaving %s unchanged",
            reason, node_slug,
        )
        return
    try:
        params = validate_winn3_protocol_params({"carrier": WINN3_CARRIER_WINN3})
    except Winn3ContractError as exc:
        logger.error(
            "install-time standalone carrier: params refused (%s); leaving %s unchanged",
            exc.reason, node_slug,
        )
        return
    stored = json.dumps(params, sort_keys=True, separators=(",", ":"))
    conn.execute(
        "UPDATE nodes SET protocol_version = ?, protocol_params_json = ?,"
        " path_mtu = ?, carrier_classes = ? WHERE slug = ?",
        (WINN_PROTOCOL_V3, stored, mtu, ",".join(classes) or None, node_slug),
    )
    logger.info(
        "install-time standalone carrier applied to %s (carrier=winn3 path_mtu=%s classes=%s)",
        node_slug, mtu, ",".join(classes) or "-",
    )


def refuse_winn3_implicit_downgrade(node: Any, reason: str, keys: Optional[list] = None) -> None:
    """Fail closed for a node registered winn/3. Never rewrite the served protocol to winn/1.

    Explicit winn/1 nodes never reach this helper. A client that selected such a
    node, or that requested a v1-only behaviour against one, is served winn/1
    by resolve_served_winn_protocol's node-not-winn3 path.
    """
    slug = "?"
    try:
        if hasattr(node, "keys") and "slug" in node.keys():
            slug = node["slug"]
        elif hasattr(node, "get"):
            slug = node.get("slug") or "?"
    except Exception:
        slug = "?"
    logger.error(
        "node %s is registered winn/3; refusing implicit winn/1 (reason=%s)",
        slug, reason,
    )
    raise Winn3ContractError(reason, keys)


def resolve_served_winn_protocol(
    node: Any,
    *,
    capabilities: dict,
    obfuscation: dict,
    stealth_mode: bool,
    double_vpn_active: bool,
    mtu: int,
) -> tuple:
    """Decide what protocol_version / protocol_params THIS request is served.

    Returns (version, params, reason). `reason` is "winn3" when winn/3 is served.

    THE GATE IS BINARY. Two facts force that:

      * The client fails CLOSED. A winn/3 config it cannot honour stops the
        connection and never falls back (lib/main.dart:10764-10781).
      * protocol_params is consumed atomically: ONE unrecognised or incoherent
        key refuses the whole config. There is no "serve some of it" mode.

    EXPLICIT winn/1 IS PRESERVED. A node that is not registered winn/3 is served
    winn/1 with empty params, which is byte-for-byte what this hub serves today
    for that node. Client-requested v1 behaviour against such a node -- stealth,
    Double VPN, a client that never advertised supports_winn3 -- stays winn/1.

    REGISTERED winn/3 FAILS CLOSED. If this request cannot be served winn/3
    (unusable params, missing descriptor, stale canary, missing capability,
    stealth_mode, Double VPN, unclassifiable obfuscation, out-of-range MTU,
    non-literal endpoint, unservable standalone plan), the gate raises
    Winn3ContractError. The verify path turns that into HTTP 503. Rewriting the
    served protocol to winn/1 would be the implicit downgrade the client rule
    exists to prevent.
    """
    stored_version = strict_stored_protocol_version(node)
    if stored_version != WINN_PROTOCOL_V3:
        return WINN_PROTOCOL_V1, {}, "node-not-winn3"

    try:
        raw_params = parse_protocol_params(
            node.get("protocol_params_json") if hasattr(node, "get") else node["protocol_params_json"]
        )
        params = validate_winn3_protocol_params(raw_params)
    except Winn3ContractError as exc:
        # Re-validated on the READ path even though the write path validates.
        # The stored blob can predate the validator (direct SQL was the only
        # way to set it before this endpoint existed). Serving that blob as
        # winn/3 would disconnect the client; rewriting it to winn/1 would be
        # an implicit downgrade. Fail closed. Reason and key names only --
        # never the values, which are endpoints and identifiers.
        logger.error(
            "node %s is registered winn/3 but its protocol_params are unusable "
            "(reason=%s keys=%s); refusing implicit winn/1",
            (node["slug"] if "slug" in node.keys() else "?") if hasattr(node, "keys") else "?",
            exc.reason, ",".join(exc.keys) or "-",
        )
        refuse_winn3_implicit_downgrade(node, "params-invalid", exc.keys)

    # Double VPN rewrites server_endpoint to the CORE's ingress, so the winn/3
    # advertisement registered against THIS node would describe a gateway the
    # session does not use. Serving winn/1 with empty parameters routes through
    # the Core relay's AmneziaWG ingress on port 9210 to the exit node.
    if double_vpn_active:
        return WINN_PROTOCOL_V1, {}, "double-vpn-active"

    # stealth_active + winn/3 is a client-side refusal unless the config also
    # carries the stacked opt-in (:1044-1053). stealth_active is
    # login.stealth_mode -- a PER-REQUEST client choice. On an explicit winn/1
    # node that choice is served as winn/1. On a registered winn/3 node it
    # must not rewrite the protocol; fail closed instead.
    if stealth_mode:
        refuse_winn3_implicit_downgrade(node, "stealth-mode-active")

    if not (WINN3_MIN_MTU <= int(mtu or 0) <= WINN3_MAX_MTU):
        refuse_winn3_implicit_downgrade(node, "mtu-out-of-range")

    # h1..h4 are REQUIRED for winn/3 and stricter than winn/1 tolerates.
    if winn3_obfuscation_problems(obfuscation):
        logger.error(
            "node %s is registered winn/3 but its obfuscation profile is not "
            "winn/3-classifiable (keys=%s); refusing implicit winn/1",
            (node["slug"] if "slug" in node.keys() else "?") if hasattr(node, "keys") else "?",
            ",".join(winn3_obfuscation_problems(obfuscation)),
        )
        refuse_winn3_implicit_downgrade(node, "obfuscation-not-classifiable")

    # gateway_endpoint may be omitted, in which case the client uses
    # server_endpoint (:1085-1090). If it is going to do that, the fallback has
    # to be a literal or every connection refuses.
    if not params.get("gateway_endpoint"):
        server_endpoint = (
            node.get("endpoint") if hasattr(node, "get") else node["endpoint"]
        )
        if not winn3_is_ip_literal_endpoint(server_endpoint):
            refuse_winn3_implicit_downgrade(node, "server-endpoint-not-ip-literal")

    # THE CAPABILITY GATE. Absent means False; every client in the field today
    # is absent. Against an explicit winn/1 node that absence is served winn/1.
    # Against a registered winn/3 node it is not a license to rewrite the
    # protocol.
    if not bool(capabilities.get(WINN3_CLIENT_CAPABILITY)):
        refuse_winn3_implicit_downgrade(node, "client-not-winn3-capable")
    if winn3_params_require_spa(params) and not bool(
        capabilities.get(WINN3_SPA_CLIENT_CAPABILITY)
    ):
        # Serving spa_* to a client that cannot knock stops that client's
        # connection (:236-244). Serving the same node WITHOUT the spa params
        # is not an option either: the gate on the node is dropping
        # unauthorized packets, so the client would reach a black hole. Serving
        # the node as winn/1 would be an implicit downgrade.
        refuse_winn3_implicit_downgrade(node, "client-not-spa-capable")

    # THE STANDALONE PLAN GATE (ADDED 2026-08-10, ds_iosconfig3).
    #
    # path_mtu and carrier_classes are only EVER read by the standalone start
    # (carrier=winn3): the relay carriers pass the bytes to an AmneziaWG engine
    # that knows nothing of a migration-plan floor. For the standalone carrier
    # they are the one property of the request the client's NewSizing refuses
    # on, and a refused config is a disconnected client with no fallback -- so
    # a node with an empty plan, an unknown class, or a path MTU inside the
    # 1280..1421 never-promotes dead zone must NEVER be served winn/3. This
    # gate mirrors winn3/driver/params.go:142-231 through ONE helper that the
    # emission path re-derives from, so serving and emitting cannot disagree.
    carrier = params.get("carrier", WINN3_CARRIER_DIRECT_AWG)
    if carrier == WINN3_CARRIER_WINN3:
        # STANDALONE REQUIRES DESCRIPTOR CAPABILITY (ADDED 2026-08-11,
        # ds_iosconfig3). carrier=winn3 IS the standalone branch -- the client
        # takes it at _winn3StandaloneStart and refuses the whole connection if
        # it cannot verify a descriptor (winn3DescriptorUnverified,
        # lib/winn_protocol_dispatch.dart:2141-2149). A device that advertises
        # supports_winn3 but not supports_winn3_descriptor (datapath present,
        # no verifier ring carried) would be handed a carrier=winn3 config it
        # refuses by name. Do not rewrite the node to winn/1; fail closed so
        # the advertisement and the descriptor gate cannot disagree.
        if not bool(capabilities.get(WINN3_DESCRIPTOR_CLIENT_CAPABILITY)):
            refuse_winn3_implicit_downgrade(node, "client-not-descriptor-capable")
        plan_servable, plan_reason, _, _ = winn3_standalone_plan_for_node(node)
        if not plan_servable:
            logger.error(
                "node %s is registered standalone winn/3 but its plan is not "
                "servable (reason=%s); refusing implicit winn/1",
                (node["slug"] if "slug" in node.keys() else "?") if hasattr(node, "keys") else "?",
                plan_reason,
            )
            refuse_winn3_implicit_downgrade(node, plan_reason)
        # THE STORED DESCRIPTOR GATE (ADDED 2026-08-12,
        # hub_descriptor_before_serve).
        #
        # Readiness already names winn3_descriptor_missing_or_invalid as a
        # blocker for carrier=winn3. Serving winn/3 + empty descriptor lets the
        # client fail closed on the device. Serving winn/1 would be an implicit
        # downgrade. Fail closed here, using the SAME reason readiness already
        # reports, so the two cannot disagree. winn3_stored_descriptor returns
        # {} for both missing and invalid, matching the readiness name.
        stored_descriptor = winn3_stored_descriptor(node)
        if not stored_descriptor:
            logger.error(
                "node %s is registered standalone winn/3 but has no stored "
                "valid descriptor; refusing implicit winn/1",
                (node["slug"] if "slug" in node.keys() else "?") if hasattr(node, "keys") else "?",
            )
            refuse_winn3_implicit_downgrade(node, "winn3_descriptor_missing_or_invalid")
        if not winn3_canary_is_fresh(node):
            logger.error(
                "node %s is registered standalone winn/3 but has no fresh "
                "successful external Winn3 canary; refusing implicit winn/1",
                (node["slug"] if "slug" in node.keys() else "?")
                if hasattr(node, "keys") else "?",
            )
            refuse_winn3_implicit_downgrade(node, "winn3_external_canary_not_fresh")
        # SYNC-15 round 2: the node's own report that its gateway runs without
        # the resolver the descriptor advertises, or without forwarding.
        report_refusal = winn3_gateway_report_serving_refusal(node, stored_descriptor)
        if report_refusal:
            logger.error(
                "node %s is registered standalone winn/3 but reports a gateway "
                "no client can use (reason=%s); refusing implicit winn/1",
                (node["slug"] if "slug" in node.keys() else "?")
                if hasattr(node, "keys") else "?",
                report_refusal,
            )
            refuse_winn3_implicit_downgrade(node, report_refusal)

    return WINN_PROTOCOL_V3, params, "winn3"


# SYNC-15/16 (2026-09-29). Every value below is typed by hand in two or three
# places (gateway installer env, offline signer, hub admin form) and nothing
# negotiates it: a disagreement is a session that builds and carries nothing.
# The node now reports what its winn3-gateway unit runs; these are the
# blockers that name each disagreement. Readiness and the contract audit
# report them all; the serving gate refuses only the two a node reports about
# itself that no client can survive (winn3_gateway_report_serving_refusal).
WINN3_GATEWAY_REPORT_BLOCKERS = (
    "winn3_gateway_not_reported",
    "winn3_gateway_not_installed",
    "winn3_gateway_not_running",
    "winn3_gateway_report_incomplete",
    "winn3_gateway_not_forwarding",
    "winn3_gateway_forward_cidr_differs_from_node_pool",
    "winn3_gateway_resolver_off",
    "winn3_gateway_id_differs_from_descriptor",
    "winn3_gateway_inner_v4_differs_from_descriptor",
    "winn3_gateway_listen_port_differs_from_descriptor",
    "winn3_gateway_path_mtu_differs_from_hub",
    "winn3_gateway_plan_differs_from_hub",
    "winn3_descriptor_endpoint_differs_from_registered_endpoint",
)


def _winn3_endpoint_host_port(value: Any) -> tuple:
    text = str(value or "").strip()
    if text.startswith("[") and "]:" in text:
        host, _, port = text.partition("]:")
        return host[1:], port
    host, sep, port = text.rpartition(":")
    return (host, port) if sep else (text, "")


def winn3_gateway_report_blockers(node: Any, descriptor: Optional[dict]) -> list:
    """Where the node's report of its gateway unit disagrees with what the hub serves.

    `descriptor` is the node's stored, validated descriptor ({} or None when it
    has none); descriptor comparisons are skipped without one, because
    winn3_descriptor_missing_or_invalid already names that.
    """
    blockers: list = []
    descriptor = descriptor or {}
    if descriptor:
        registered_host, _ = _winn3_endpoint_host_port(_node_field(node, "endpoint"))
        descriptor_host, _ = _winn3_endpoint_host_port(descriptor.get("endpoint"))
        try:
            registered_ip = ipaddress.ip_address(registered_host)
            descriptor_ip = ipaddress.ip_address(descriptor_host)
        except ValueError:
            registered_ip = descriptor_ip = None
        # A node whose public address changed re-registers its v1 endpoint on
        # the next heartbeat; its signed descriptor keeps the old address
        # until someone re-signs. Compared only when both are IP literals
        # (endpoint_not_ip_literal already names the other case).
        if registered_ip is not None and registered_ip != descriptor_ip:
            blockers.append("winn3_descriptor_endpoint_differs_from_registered_endpoint")
    report = parse_winn3_gateway_report(_node_field(node, "winn3_gateway_report_json"))
    if report is None:
        blockers.append("winn3_gateway_not_reported")
        return blockers
    if report["state"] == "absent":
        blockers.append("winn3_gateway_not_installed")
        return blockers
    if report["state"] != "active":
        blockers.append("winn3_gateway_not_running")
    if any(report[key] in (None, "") for key in (
        "forward", "resolver", "listen", "gateway_id", "inner_v4", "plan", "path_mtu",
    )):
        blockers.append("winn3_gateway_report_incomplete")
    if report["forward"] is False:
        # A reflector answers the handshake and forwards nothing: every client
        # connects and reaches nothing past the gateway.
        blockers.append("winn3_gateway_not_forwarding")
    if report["forward"] is True:
        # The gateway routes and NATs only -forward-cidr; a client the hub
        # addressed outside it has no route back (G: "THIS MUST BE THE SAME
        # SUBNET the control plane assigns client inner_v4 addresses from").
        # Compared with THIS node's pool (the /24 around its descriptor
        # router, fable_ruling_sync08_sync06 Q2), not with the envelope: the
        # two are the same /24 until per-node slices, and differ after.
        node_pool = winn3_node_inner_slice(node)
        try:
            forward_net = ipaddress.ip_network(report["forward_cidr"], strict=False)
        except ValueError:
            forward_net = None
        if forward_net is None:
            blockers.append("winn3_gateway_report_incomplete")
        elif node_pool is not None and forward_net != node_pool:
            blockers.append("winn3_gateway_forward_cidr_differs_from_node_pool")
    if report["resolver"] is False and descriptor.get("inner_resolver_v4"):
        # Every descriptor advertises inner_resolver_v4 (it must equal
        # inner_router_v4), so a gateway without -resolver hands clients a DNS
        # server nobody answers on.
        blockers.append("winn3_gateway_resolver_off")
    if descriptor:
        if report["gateway_id"]:
            try:
                descriptor_id = base64.b64decode(str(descriptor.get("gateway_id") or ""), validate=True)
            except Exception:
                descriptor_id = b""
            if descriptor_id != report["gateway_id"].encode("utf-8"):
                blockers.append("winn3_gateway_id_differs_from_descriptor")
        if report["inner_v4"] and report["inner_v4"] != str(descriptor.get("inner_router_v4") or "").strip():
            blockers.append("winn3_gateway_inner_v4_differs_from_descriptor")
        if report["listen"]:
            _, listen_port = _winn3_endpoint_host_port(report["listen"])
            _, descriptor_port = _winn3_endpoint_host_port(descriptor.get("endpoint"))
            if listen_port != descriptor_port:
                blockers.append("winn3_gateway_listen_port_differs_from_descriptor")
    if report["path_mtu"] is not None and report["path_mtu"] != winn3_effective_path_mtu(node):
        blockers.append("winn3_gateway_path_mtu_differs_from_hub")
    if report["plan"]:
        # Compared as sets: the hub and the gateway each keep their own
        # operator order, and only membership is checked here.
        hub_classes = set(parse_winn3_carrier_classes(_node_field(node, "carrier_classes")))
        if set(report["plan"].split(",")) != hub_classes:
            blockers.append("winn3_gateway_plan_differs_from_hub")
    return blockers


def winn3_gateway_report_serving_refusal(node: Any, descriptor: Optional[dict]) -> str:
    """The serve-path refusal a node's own gateway report forces, or "".

    SYNC-15, round 2 (OI-SYNC_V3-7). Only a DEFINITE admission of a defect
    that no client survives refuses: a gateway unit that runs without
    -resolver while the signed descriptor hands every client an inner
    resolver (DNS black hole), or one that runs without -forward (a
    reflector: connects, carries nothing). A node that reports nothing, or
    reports a field as unknown, is served as before: an older data plane
    sends no report, and "unknown" is not evidence. Trusting the report in
    this direction is safe: a node that falsely claims a defect only takes
    itself out of v3. The external canary's DNS query measures the same
    resolver independently of the report.
    """
    report = parse_winn3_gateway_report(_node_field(node, "winn3_gateway_report_json"))
    if report is None or report["state"] == "absent":
        return ""
    if report["forward"] is False:
        return "winn3_gateway_not_forwarding"
    if report["resolver"] is False and (descriptor or {}).get("inner_resolver_v4"):
        return "winn3_gateway_resolver_off"
    return ""


def winn3_node_readiness(node: Any, obfuscation: dict, *,
                         canary_collisions: Optional[dict] = None) -> dict:
    """Everything an operator needs to know before flipping a node to winn/3.

    Node-scoped only: it deliberately says nothing about any one client
    request, because the per-request gate above depends on stealth_mode and
    the client's advertised capabilities, neither of which exist here.

    `canary_collisions` is winn3_canary_device_collisions(conn) from a caller
    that holds a connection; this function opens none itself.
    """
    slug = node["slug"] if hasattr(node, "keys") and "slug" in node.keys() else ""
    endpoint = node["endpoint"] if hasattr(node, "keys") and "endpoint" in node.keys() else ""
    blockers: list = []
    if not winn3_is_ip_literal_endpoint(endpoint):
        blockers.append("endpoint_not_ip_literal")
    obfuscation_problems = winn3_obfuscation_problems(obfuscation)
    if obfuscation_problems:
        blockers.append("obfuscation_not_classifiable")
    params_reason = ""
    params_unusable = False
    try:
        params = validate_winn3_protocol_params(
            parse_protocol_params(
                node["protocol_params_json"]
                if hasattr(node, "keys") and "protocol_params_json" in node.keys()
                else None
            )
        )
    except Winn3ContractError as exc:
        params = {}
        params_reason = exc.reason
        params_unusable = True
        blockers.append("protocol_params_invalid")
    carrier = (
        ""
        if params_unusable
        else params.get("carrier", WINN3_CARRIER_DIRECT_AWG)
    )
    plan_mtu = winn3_effective_path_mtu(node)
    plan_classes = parse_winn3_carrier_classes(_node_field(node, "carrier_classes"))
    plan_reason = None
    if carrier in WINN3_CARRIER_PROFILE_CARRIERS:
        # Not a blocker the hub can see -- it is a fact about the NODE that the
        # hub cannot verify from here. Named so it is never assumed.
        blockers.append("carrier_requires_node_side_winn_carrier_server")
    elif carrier == WINN3_CARRIER_WINN3:
        # The standalone equivalent, and it is a DIFFERENT node-side component:
        # not winn-carrier-server (a MASQUE relay in front of AmneziaWG) but
        # cmd/winn3-gateway, which terminates the v3 handshake itself and owns
        # the inner address space. The hub cannot verify it is running, and the
        # failure if it is not is the silent one this whole surface is written
        # against -- a gateway that never answers is indistinguishable from a
        # censored path -- so it is NAMED rather than assumed.
        blockers.append("carrier_requires_node_side_winn3_gateway")
        # The standalone start needs six key-bearing [winn] fields and not one
        # of them can travel through protocol_params. Four arrive on the signed
        # descriptor; a node advertising carrier=winn3 with no stored, valid
        # descriptor can only produce a config the client refuses by name.
        descriptor = winn3_stored_descriptor(node)
        if not descriptor:
            blockers.append("winn3_descriptor_missing_or_invalid")
        if not winn3_canary_is_fresh(node):
            blockers.append("winn3_external_canary_not_fresh")
        # SYNC-15/16: the node's own report of what its gateway runs.
        blockers.extend(winn3_gateway_report_blockers(node, descriptor))
        # THE PLAN (ADDED 2026-08-10, ds_iosconfig3). A standalone node with an
        # unservable plan -- empty, unknown class, or a path MTU inside the
        # never-promotes dead zone -- is refused by the client's NewSizing, so
        # it can never serve winn/3 to anyone. Node-scoped here, so an operator
        # can read WHY before a deploy night; same helper as the per-request
        # gate, so the report and the serving decision cannot disagree.
        plan_servable, plan_reason, plan_mtu, plan_classes = (
            winn3_standalone_plan_for_node(node)
        )
        if not plan_servable:
            blockers.append(plan_reason)
    # SYNC-03 round 2 (Seat C N-1): a device that already held an address or
    # key later configured as this node's canary makes the node's registry
    # build refuse, so every push to it stops. Named here; refused at
    # configuration time by the hub installer.
    blockers.extend((canary_collisions or {}).get(str(slug or "").strip().lower(), []))
    return {
        "slug": slug,
        "protocol_version": str(
            (node["protocol_version"] if hasattr(node, "keys") and "protocol_version" in node.keys() else "")
            or WINN_PROTOCOL_V1
        ),
        "carrier": carrier,
        "spa_required": winn3_params_require_spa(params),
        "param_keys": sorted(params.keys()),
        "obfuscation_problem_keys": obfuscation_problems,
        "protocol_params_error": params_reason,
        "path_mtu": plan_mtu,
        "carrier_classes": ",".join(plan_classes) if plan_classes else "",
        "plan_reason": plan_reason or None,
        # SYNC-15/16: what the node last reported its gateway runs (None when
        # its register did not report). No key material is ever in it.
        "gateway_report": parse_winn3_gateway_report(
            _node_field(node, "winn3_gateway_report_json")
        ),
        "blockers": sorted(set(blockers)),
        "ready": not blockers,
    }


# --- Winn Protocol v3 standalone: signed node descriptors + admission rotation
#
# WHAT THIS IS. Item 3 of the ten in WINN3_STANDALONE_PROTOCOL_DESIGN_20260808
# section 8: "Control-plane binding -- gateway descriptors carrying the static
# key, the per-gateway admission key, tag length and padding profile, signed by
# the existing ML-DSA-65 chain, plus the rotation path for the admission key."
#
# WHY IT IS NOT A protocol_params KEY, which is the first thing to get right.
# protocol_params is a CLOSED twenty-key allowlist and the shipped client
# refuses the whole connection on any key outside it
# (lib/winn_protocol_dispatch.dart:259-265, :1055-1074). More to the point, the
# admission key is a SECRET, and the one discipline that surface enforces
# without exception is that nothing key-shaped is ever served through it --
# spa_key_path is excluded for exactly that reason
# (lib/winn_carrier_profile_keys.dart:19-24). So the descriptor is a SEPARATE,
# SIGNED, TOP-LEVEL object with its own gate, and WINN3_PARAM_NAME_NEVER_SERVED
# below makes the discipline machine-checkable rather than a convention.
#
# WHY THE APP HOLDS NO SIGNING KEY, AND WHAT SIGNS INSTEAD. The hub app holds
# NO descriptor signing key and cannot read one: the active slot's private key
# is held by the separate signer service (system user wins-desc-signer, key at
# /etc/winsvpn/descriptor-signer/<active-slot>.ed25519.pem, 0400 in a 0700
# directory that the hub unit's InaccessiblePaths= hides from it). The app
# holds the PUBLIC halves, verifies an uploaded envelope, and stores it
# verbatim; it asks the signer to sign over the signer socket, and the signer
# signs only within policy: a new or changed identity needs an unused t1
# ticket binding the slug, action, endpoint IP, gateway ID and pinned host
# key, plus verification of the node's signed identity. Renewal uses the
# retained payload within its renewal window and per-slug renewal limit.
# Normal fleet quotas apply unless a ticketed identity issuance spends an
# operator-granted recovery allowance. /admin/* uses a fleet-wide shared
# token; a leaked token cannot read the signing key or bypass signer policy.
# That boundary matters because a forged descriptor hands a client an
# attacker's static key, an attacker's admission key and an attacker's
# endpoint in one object. This is the
# announcement lane's own reasoning (see ANNOUNCE_SIGNATURE_DOMAIN above)
# applied where the blast radius is strictly larger -- and it is cheaper here,
# because unlike an announcement a descriptor changes only when a gateway
# rotates.
#
# A leaked admin token can WITHHOLD a descriptor, attempt to REPLAY an older
# one, or request policy-bounded signing. Ticketless renewal uses the pinned
# identity. New or changed identities require the matching unused t1 ticket.
# An app attacker with root on the ticketed node can choose the keys that
# node signs while its ticket remains unused. Ticket bindings, canary checks
# and the spend audit bound and expose that residual.
# Withholding is handled by resolve_served_winn_protocol: a carrier=winn3
# node with no stored valid descriptor is refused, never rewritten to winn/1.
# Replay is handled by the
# strictly-increasing per-node seq enforced in store_winn3_descriptor: without
# it, a retired admission key could be reinstated, which is the one move that
# turns a burnt secret back into a live one.
WINN3_DESCRIPTOR_DOMAIN = b"winsvpn-winn3-descriptor/v1"
# VERSION 3, 2026-08-12: `inner_resolver_v4` joined the closed field set below.
#   (VERSION 2, 2026-08-09 added `inner_router_v4`.)
#
# WHY THE BUMP IS UNAVOIDABLE AND WHAT IT COSTS.
# `v` is inside the signed bytes, and validation requires the supported
# format version. Changing that version makes older-format descriptors
# unusable until supported envelopes are issued and stored.
# Renewal preserves the retained format version. A format migration needs a
# reviewed issuance procedure that also handles retained and orphaned
# envelopes; ordinary renewal does not perform that migration.
#
# WHY inner_router_v4 HAD TO BE A DESCRIPTOR FIELD RATHER THAN ANYWHERE CHEAPER.
# It is the inner next hop -- the gateway's own address inside the tunnel -- so
# it is a property of the GATEWAY, identical for every device, exactly like
# `endpoint` and `static_pub` beside it. The two cheaper places both fail:
# protocol_params cannot carry it honestly (it is a twenty-key closed allowlist
# whose whole discipline is that the client interprets nothing it is handed),
# and an unsigned vpn_config key would let anyone who can forge a hub response
# repoint the client's only included route in the bootstrap posture. Signing it
# alongside the endpoint it belongs to is what makes those two consistent by
# construction.
#
# WHY inner_resolver_v4 JOINS IT. It is the inner
# DNS responder address. It must be a descriptor field for the same reason
# inner_router_v4 must: it is a property of the GATEWAY, identical for every
# device, and an unsigned vpn_config key would let a forged hub response
# repoint DNS while the tunnel stays up. A -forward gateway can lawfully host
# DNS responder address. The shipping gateway binds its resolver to -inner-v4
# and has no second-address flag, so a distinct signed value is a false claim:
# clients route DNS to an address where this gateway cannot listen. Require
# equality until a separately addressed resolver exists end to end. Keeping the
# explicit signed field still permits that future change under a format bump.
#
# The retirement is NOT silent, which is the one mercy here: an old descriptor
# fails `descriptor-unsupported-format-version` at validation, and resolve_
# served_winn3_descriptor then reports that reason (falling back to
# `descriptor-does-not-validate` only for blobs that fail outside the contract).
# Format rejection makes a winn/3 carrier unavailable. The serve path does
# not implicitly rewrite it to winn/1. An explicit carrier rollback is
# required while a supported descriptor is prepared.
WINN3_DESCRIPTOR_FORMAT_VERSION = 3
# g1..g3, disjoint from the announcement family (a1..a3) and the discovery
# family (d1..d3). Three families, three blast radii: an announcement is TEXT a
# user might act on, a discovery record is WHERE THE APP CONNECTS, and a
# descriptor is where it connects AND under whose secret. Announcement and
# discovery signing remain offline. The active descriptor-slot private key
# lives in the separate signer service; the hub app holds public halves and
# cannot read the descriptor signing key.
WINN3_DESCRIPTOR_KEY_SLOTS = ("g1", "g2", "g3")
WINN3_DESCRIPTOR_ALG_ED25519 = "ed25519"
# The one algorithm the SHIPPED client can verify. lib/ carries exactly two
# signature verifiers -- discovery_keys.dart:281 and
# announcement_signature.dart:255 -- and both are Ed25519 via
# package:cryptography, which has no ML-DSA. The design calls for ML-DSA-65;
# see HUB_V3_DESCRIPTORS_ROTATION_20260808.md section 2 for the gap and its
# cost. `alg` is inside the signed bytes so that adding ML-DSA later is a new
# value here, not an ambiguity about which algorithm produced a signature.
WINN3_DESCRIPTOR_SUPPORTED_ALGS = (WINN3_DESCRIPTOR_ALG_ED25519,)
WINN3_ED25519_PUBLIC_KEY_BYTES = 32
WINN3_ED25519_SIGNATURE_BYTES = 64
# RFC 8410 SubjectPublicKeyInfo prefix for Ed25519. The key ceremony emits raw
# 32 bytes (base64) because that is what a --dart-define carries; openssl wants
# an SPKI, so one is rebuilt around the raw key rather than asking the operator
# for a second encoding of the same value.
WINN3_ED25519_SPKI_PREFIX = bytes.fromhex("302a300506032b6570032100")
# The t1 signer-ticket family (3.8): offline Ed25519, separate from the g
# ring, so a descriptor signature can never pass as a ticket, or the reverse.
# The signer's config holds the pinned public half (WINN3_SIGNER_TICKET_PUBKEY_T1,
# written by the control-plane installer); the hub re-verifies stored ticket
# bytes against it at post and at use (3.17).
WINN3_TICKET_DOMAIN = b"winsvpn-winn3-signer-ticket/v1"
WINN3_SIGNER_TICKET_FIELDS = (
    "action", "endpoint_ip", "epoch", "gateway_id", "go_live",
    "host_key_sha256", "nonce", "not_after", "slug", "tier",
)
WINN3_SIGNER_TICKET_ACTIONS = ("new", "reset", "endpoint", "rekey", "suspend", "unsuspend")
WINN3_SIGNER_TICKET_MAX_LIFETIME_S = 7 * 86400
WINN3_SIGNER_SOCKET_PATH = "/run/wins-descriptor-signer/sock"

# Bounds mirrored from winn_protocol_experimental/winn3/core/params.go. Every
# one of these is checked against the Go source by
# test_winn3_descriptor_hub.py::test_core_constants_do_not_drift, in the same
# spirit as the Dart allowlist drift test: a hand-maintained second copy of a
# constant that silently disagrees with the implementation is the failure this
# project has already had once.
WINN3_MIN_TAG_SIZE = 16            # core MinTagSize
WINN3_MAX_TAG_SIZE = 32            # core MaxTagSize
WINN3_DEFAULT_TAG_SIZE = 32        # core DefaultTagSize
WINN3_MIN_ADMISSION_SECRET_BYTES = 32   # core minAdmissionKeySize
WINN3_STATIC_PUBLIC_KEY_BYTES = 32      # X25519 public key
# Dual-signature attestation public-key sizes (DUAL_SIGNATURE_SPEC.md).
WINN3_DUAL_AUTH_ED25519_PUBLIC_KEY_BYTES = 32
WINN3_DUAL_AUTH_MLDSA65_PUBLIC_KEY_BYTES = 1952

WINN3_MIN_GATEWAY_ID_BYTES = 1     # core validate(): non-empty
WINN3_MAX_GATEWAY_ID_BYTES = 255   # core validate(): <= 255
WINN3_DEFAULT_BUCKET_WINDOW_SECONDS = 10   # core DefaultBucketWindow
WINN3_DEFAULT_MAX_SKEW_SECONDS = 60        # core DefaultMaxSkew
WINN3_MIN_BUCKET_WINDOW_SECONDS_CORE = 1   # core Freshness.resolve(): >= 1s
WINN3_MAX_BUCKET_CANDIDATES = 4096         # core maxBucketCandidates
WINN3_MAX_HANDSHAKE_MESSAGE = 1024         # core MaxHandshakeMessage
# core PaddingPolicy: PadNone, PadBucket (default), PadMimic. Named on the wire
# rather than numbered so a descriptor is readable in an incident.
WINN3_PADDING_POLICIES = ("none", "bucket", "mimic")
WINN3_DEFAULT_PADDING_POLICY = "bucket"

# ROTATION BUDGET, and it is the number this whole section turns on.
#
# verifyAdmission (winn3/core/admission.go:150-179) iterates KEYS OUTERMOST and
# BUCKETS INNERMOST, so an unauthenticated datagram costs
# len(AdmissionKeys) * (2*spread+1) truncated HMACs before it is dropped. A
# second live key during a rotation DOUBLES that. Measured on an Apple M5 Max,
# Go 1.26, one admission-tag HMAC over a 131-byte initiation is 0.292 us, so
# the default 13 candidate buckets cost 3.8 us with one key and 7.6 us with
# two.
#
# Two live keys is therefore affordable and 2 is the hard ceiling. What is NOT
# affordable is a WIDE freshness window during a rotation: candidates grow as
# 2*ceil(skew/window)+1, so a max_skew of one hour at a ten-second window is
# 721 candidates -- 1,442 HMACs per dropped packet with two keys, which is a
# gift to anyone who can send garbage at a gateway. The budget below caps the
# PRODUCT, which is the only quantity that matters, at 64 HMACs -- 18.7 us per
# unauthenticated datagram at the measured rate, about 53,000 dropped
# datagrams per second per core.
#
# This is the coupling that makes rotation and freshness inseparable: widening
# the window makes a rotation SAFER (a longer grace for a stale client) and the
# gateway CHEAPER TO FLOOD (more HMACs per reject), and the hub is the only
# place that sees both numbers at once.
WINN3_MAX_LIVE_ADMISSION_KEYS = 2
WINN3_MAX_ADMISSION_HMAC_BUDGET = 64

# Descriptor freshness. not_after is what bounds how stale a CACHED descriptor
# can be, and the client caches vpn_config in `_cachedVpnConfig`
# (lib/main.dart:704) and can fast-connect from it in
# `_cachedDirectConfigForFastConnect` (lib/main.dart:5059-5066). Without a ttl
# the hub could never compute a safe retirement instant for an old admission
# key, because there would be no bound on how long a client might still be
# holding it.
WINN3_MIN_DESCRIPTOR_TTL_SECONDS = 3600            # 1 hour
WINN3_MAX_DESCRIPTOR_TTL_SECONDS = 30 * 24 * 3600  # 30 days
WINN3_MAX_DESCRIPTOR_BYTES = 4096

# The payload's exact key set. Closed, like protocol_params, and for the same
# reason: an unknown field is either a typo that will strand a node or a
# newer format this hub must not pretend to understand.
WINN3_DESCRIPTOR_REQUIRED_FIELDS = (
    "admission_gen", "admission_secret", "alg", "bucket_window_s", "endpoint",
    "gateway_id", "iat", "inner_resolver_v4", "inner_router_v4", "kid",
    "max_skew_s", "node", "not_after", "padding", "seq", "static_pub",
    "tag_size", "v",
)
# Optional dual-signature attestation fields (docs/DUAL_SIGNATURE_SPEC.md).
# Present only on dual-provisioned nodes; legacy clients ignore them because
# every descriptor consumer reads named keys and never rejects extras. Both
# are base64 of raw key bytes, validated for exact size when present.
WINN3_DESCRIPTOR_OPTIONAL_FIELDS = ("auth_ed25519", "auth_mldsa65")
# The descriptor fields that are DOTTED-QUAD PLAIN TEXT rather than base64.
#
# Enumerated because the descriptor's own rule is "every byte-valued field is
# base64", and inner_router_v4 and inner_resolver_v4 are the fields that are
# not byte-valued at all. Each is an ADDRESS, and reaches its `[winn]` key as
# text -- `WinsWinn3SessionStart` parses it as an address, not as bytes.
# Base64-encoding it would give every host one more decode to disagree about,
# which is precisely how the gateway_id defect happened.
WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS = ("inner_resolver_v4", "inner_router_v4")
# Fields whose VALUE is a secret. Never logged, never echoed in an error body,
# never returned by any admin endpoint. Enumerated rather than pattern-matched
# so the disclosure test can assert on the list itself.
WINN3_DESCRIPTOR_SECRET_FIELDS = ("admission_secret",)

# The protocol_params discipline, made machine-checkable.
#
# The twenty-key allowlist already refuses everything below by construction.
# This is a SECOND, NAMED line of defence, added by the lane that introduced
# admission material to the hub, because the failure it guards against is a
# future maintainer widening the allowlist by one "obviously harmless" key.
# It is applied to protocol_params ONLY. The descriptor is a different surface
# with a different rule -- it deliberately DOES carry a secret, which is why it
# is signed, gated, and covered by WINN3_DESCRIPTOR_SECRET_FIELDS instead.
#
# NOTE ON THE PATTERN, because the obvious spelling has a hole. The natural
# form of this rule is `_key$|secret|private|seed`, and that form does NOT
# match `spa_key_path` -- which is the single most dangerous name this surface
# has ever had to exclude, precisely because it does not END in _key. The
# anchor is therefore `_key` followed by end-of-string OR an underscore.
# Verified in both directions by test_param_names_that_are_never_served: every
# dangerous name matches, and none of the twenty allowlisted params does.
WINN3_PARAM_NAME_NEVER_SERVED = re.compile(r"(?:_key(?:$|_)|secret|private|seed)")

# The client capability that gates the descriptor, on the same terms as
# supports_winn3: DEFAULT FALSE, so every client in the field -- including a
# client that already speaks AWG-carried winn/3 -- is served exactly what it is
# served today. A client that understands winn/3 but not standalone descriptors
# must not be handed one.
WINN3_DESCRIPTOR_CLIENT_CAPABILITY = "supports_winn3_descriptor"
# Dual-signature attestation keys. DEFAULT FALSE, same terms as the
# descriptor flag: a client that predates it, or that cannot consume both
# keys, is served the signed envelope without the pair being released onto
# the session. The exact name is supports_winn3_dualauth; do not infer it
# from supports_winn3 or supports_winn3_descriptor.
WINN3_DUALAUTH_CLIENT_CAPABILITY = "supports_winn3_dualauth"


def winn3_client_advertises_dualauth(capabilities: Optional[dict]) -> bool:
    """True only when the client sent supports_winn3_dualauth as JSON true.

    Missing is False. A non-bool value is malformed and refused.
    """
    if not capabilities:
        return False
    if WINN3_DUALAUTH_CLIENT_CAPABILITY not in capabilities:
        return False
    return winn3_capability_bool(
        capabilities.get(WINN3_DUALAUTH_CLIENT_CAPABILITY),
        WINN3_DUALAUTH_CLIENT_CAPABILITY,
    )


def winn3_descriptor_has_dual_auth(descriptor: Optional[dict]) -> bool:
    if not descriptor:
        return False
    ed = descriptor.get("auth_ed25519")
    ml = descriptor.get("auth_mldsa65")
    return bool(isinstance(ed, str) and ed.strip()) and bool(
        isinstance(ml, str) and ml.strip()
    )


def winn3_dual_auth_keys_for_capabilities(
    descriptor: Optional[dict],
    capabilities: Optional[dict],
) -> dict:
    """The dual-auth public keys THIS client is served.

    Both keys, or neither. The pair is included only when the client
    explicitly advertised supports_winn3_dualauth=true AND the descriptor
    carries both keys. A true advertisement against a dual-provisioned
    descriptor that would drop either key is a silent authentication
    downgrade and is refused. A legacy descriptor with neither key is
    preserved for dual-auth-capable clients and everyone else.
    """
    advertised = winn3_client_advertises_dualauth(capabilities)
    raw = descriptor or {}
    ed = raw.get("auth_ed25519")
    ml = raw.get("auth_mldsa65")
    has_ed = isinstance(ed, str) and bool(ed.strip())
    has_ml = isinstance(ml, str) and bool(ml.strip())
    if advertised:
        if has_ed and has_ml:
            return {
                "auth_ed25519": str(ed).strip(),
                "auth_mldsa65": str(ml).strip(),
            }
        if has_ed or has_ml:
            raise Winn3ContractError(
                "descriptor-dual-auth-half-provisioned",
                ["auth_ed25519", "auth_mldsa65"],
            )
        return {}
    return {}


def winn3_key_shaped_names_in_params_allowlist() -> list:
    """Any protocol_params key whose NAME says it carries key material.

    Must always be empty. It is reported by GET /admin/nodes/winn3/descriptor
    rather than merely asserted in a test, so the guard is on a live path: the
    threat it exists for is a future maintainer widening the twenty-key
    allowlist by one obviously-harmless key, and that person reads the
    readiness report, not this file.
    """
    return sorted(
        k for k in WINN3_KNOWN_PROTOCOL_PARAMS
        if WINN3_PARAM_NAME_NEVER_SERVED.search(k)
    )


def winn3_unguarded_descriptor_secret_fields() -> list:
    """Any descriptor field whose NAME says it is a secret but which is not in
    WINN3_DESCRIPTOR_SECRET_FIELDS.

    The same guard pointed the other way. The descriptor deliberately DOES
    carry a secret, so the rule there is not "no key-shaped names" but "every
    key-shaped name is on the redaction list". A field added to the descriptor
    without being added to that list would be logged and echoed in an admin
    response, which for the admission secret means burning it.
    """
    return sorted(
        f for f in WINN3_DESCRIPTOR_REQUIRED_FIELDS
        if WINN3_PARAM_NAME_NEVER_SERVED.search(f)
        and f not in WINN3_DESCRIPTOR_SECRET_FIELDS
    )


def winn3_freshness_geometry(bucket_window_s: int, max_skew_s: int) -> tuple:
    """(spread, candidates, acceptance_span_seconds), mirroring core exactly.

    core Freshness.resolve() (params.go:253-273):
        spread     = ceil(skew / window)      -- integer ceiling
        candidates = 2*spread + 1
    and NewResponder (handshake.go:494-506) sets the handshake replay cache
    lifetime to exactly (2*spread+1)*window.

    THE TWO ARE THE SAME NUMBER ON PURPOSE. The cache must remember a captured
    initiation for as long as that initiation could still verify; if the two
    ever drift apart, the gap is a span in which a censor's recorded packet is
    a working gateway detector again -- the exact hole the acceptance-window
    test in the gateway-table lane pins. Every rotation deadline this hub
    computes is expressed in terms of this one function so that a change to the
    freshness parameters moves both at once and cannot separate them.
    """
    window = int(bucket_window_s)
    skew = int(max_skew_s)
    if window < WINN3_MIN_BUCKET_WINDOW_SECONDS_CORE:
        raise Winn3ContractError("bucket-window-below-one-second", ["bucket_window_s"])
    if skew < window:
        raise Winn3ContractError("max-skew-below-bucket-window", ["max_skew_s"])
    spread = -(-skew // window)
    candidates = 2 * spread + 1
    if candidates > WINN3_MAX_BUCKET_CANDIDATES:
        raise Winn3ContractError("bucket-candidates-over-core-ceiling", ["max_skew_s"])
    return spread, candidates, candidates * window


def winn3_admission_hmac_cost(candidates: int, live_keys: int) -> int:
    """HMACs an unauthenticated datagram costs the gateway before it is dropped.

    keys outermost, buckets innermost, no early exit on a failure -- so it is
    exactly the product. See the budget note above.
    """
    return int(candidates) * int(live_keys)


def winn3_descriptor_public_keys() -> dict:
    """slot -> raw 32-byte Ed25519 public key, from the environment.

    Base64 of the RAW key, which is what `openssl pkey -pubout -outform DER |
    tail -c 32 | base64` produces and what the client's --dart-define carries.
    A slot that is set but unusable is DROPPED rather than tolerated: a typo
    must degrade to "that key does not exist", never to a verifier that accepts
    something it should not.
    """
    keys: dict = {}
    for slot in WINN3_DESCRIPTOR_KEY_SLOTS:
        encoded = (os.getenv(f"WINN3_DESCRIPTOR_PUBKEY_{slot.upper()}") or "").strip()
        if not encoded:
            continue
        try:
            raw = base64.b64decode(encoded, validate=True)
        except Exception:
            continue
        if len(raw) == WINN3_ED25519_PUBLIC_KEY_BYTES:
            keys[slot] = raw
    return keys


def winn3_descriptor_verification_available() -> bool:
    return bool(winn3_descriptor_public_keys())


WINN3_DESCRIPTOR_SIGNATURE_CACHE_LIMIT = 256
_WINN3_DESCRIPTOR_SIGNATURE_CACHE = OrderedDict()
_WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING = None
_WINN3_DESCRIPTOR_SIGNATURE_CACHE_LOCK = threading.Lock()


def winn3_verify_descriptor_signature(payload: bytes, signature: bytes, kid: str) -> str:
    """Verify DOMAIN || 0x00 || payload under the slot named by `kid`.

    openssl(1) rather than a Python library for the reason already recorded at
    the announcement block (ANNOUNCE_SIGNATURE_DOMAIN): control-plane-requirements.lock is hash-pinned
    and `cryptography` is not in it. Ed25519 verification is one-shot, so
    openssl needs seekable files for both the message and the signature.

    Returns the accepting slot id. Raises Winn3ContractError otherwise, with a
    reason and NEVER any bytes.

    P-15 caches successful signature checks only. Shape, node binding and
    clock checks remain in winn3_stored_descriptor on every consumption.
    """
    global _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING
    slot = (kid or "").strip().lower()
    if slot not in WINN3_DESCRIPTOR_KEY_SLOTS:
        raise Winn3ContractError("descriptor-unknown-key-slot", ["kid"])
    if len(signature) != WINN3_ED25519_SIGNATURE_BYTES:
        raise Winn3ContractError("descriptor-signature-length", ["sig"])
    ring = winn3_descriptor_public_keys()
    ring_digest = hashlib.sha256(json.dumps(
        {name: key.hex() for name, key in ring.items()},
        sort_keys=True, separators=(",", ":"),
    ).encode("ascii")).digest()
    # Length framing makes the tuple unambiguous. Retain only the digest and
    # accepting slot, never payload or signature bytes in the cache.
    digest = hashlib.sha256()
    for field in (slot.encode("ascii"), payload, signature, ring_digest):
        digest.update(len(field).to_bytes(8, "big"))
        digest.update(field)
    cache_key = digest.digest()
    with _WINN3_DESCRIPTOR_SIGNATURE_CACHE_LOCK:
        if _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING != ring_digest:
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE.clear()
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING = ring_digest
        accepted_slot = _WINN3_DESCRIPTOR_SIGNATURE_CACHE.get(cache_key)
        if accepted_slot is not None:
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE.move_to_end(cache_key)
            return accepted_slot
    if not ring:
        raise Winn3ContractError("descriptor-no-verification-keys-configured", ["kid"])
    raw = ring.get(slot)
    if raw is None:
        raise Winn3ContractError("descriptor-key-slot-not-provisioned", ["kid"])
    message = WINN3_DESCRIPTOR_DOMAIN + b"\x00" + payload
    with tempfile.TemporaryDirectory() as work_dir:
        key_path = os.path.join(work_dir, "descriptor.der")
        msg_path = os.path.join(work_dir, "descriptor.bin")
        sig_path = os.path.join(work_dir, "descriptor.sig")
        with open(key_path, "wb") as handle:
            handle.write(WINN3_ED25519_SPKI_PREFIX + raw)
        with open(msg_path, "wb") as handle:
            handle.write(message)
        with open(sig_path, "wb") as handle:
            handle.write(signature)
        completed = subprocess.run(
            [
                "openssl", "pkeyutl", "-verify", "-rawin", "-pubin",
                "-inkey", key_path, "-keyform", "DER",
                "-sigfile", sig_path, "-in", msg_path,
            ],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15,
        )
    if completed.returncode != 0:
        raise Winn3ContractError("descriptor-signature-invalid", ["sig"])
    with _WINN3_DESCRIPTOR_SIGNATURE_CACHE_LOCK:
        # A concurrent verifier may have observed a ring change while openssl
        # ran. Its cleared cache must not regain entries from the old ring.
        if _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING == ring_digest:
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE[cache_key] = slot
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE.move_to_end(cache_key)
            while len(_WINN3_DESCRIPTOR_SIGNATURE_CACHE) > WINN3_DESCRIPTOR_SIGNATURE_CACHE_LIMIT:
                _WINN3_DESCRIPTOR_SIGNATURE_CACHE.popitem(last=False)
    return slot


def winn3_signer_ticket_pubkey() -> Optional[bytes]:
    """The pinned t1 public half (raw 32 bytes) from the hub environment."""
    encoded = (os.getenv("WINN3_SIGNER_TICKET_PUBKEY_T1") or "").strip()
    if not encoded:
        return None
    try:
        raw = base64.b64decode(encoded, validate=True)
    except Exception:
        return None
    return raw if len(raw) == WINN3_ED25519_PUBLIC_KEY_BYTES else None


def winn3_verify_signer_ticket_signature(payload: bytes, signature: bytes) -> None:
    """Verify the t1 signature over TICKET_DOMAIN || 0x00 || payload (3.8).

    Same openssl(1) discipline as the descriptor verifier: control-plane-
    requirements.lock is hash-pinned and `cryptography` is not in it. Raises
    Winn3ContractError otherwise, with a reason and NEVER any bytes.
    """
    raw = winn3_signer_ticket_pubkey()
    if raw is None:
        raise Winn3ContractError("signer-ticket-key-not-configured", ["sig"])
    if len(signature) != WINN3_ED25519_SIGNATURE_BYTES:
        raise Winn3ContractError("signer-ticket-signature-length", ["sig"])
    message = WINN3_TICKET_DOMAIN + b"\x00" + payload
    with tempfile.TemporaryDirectory() as work_dir:
        key_path = os.path.join(work_dir, "ticket.der")
        msg_path = os.path.join(work_dir, "ticket.bin")
        sig_path = os.path.join(work_dir, "ticket.sig")
        with open(key_path, "wb") as handle:
            handle.write(WINN3_ED25519_SPKI_PREFIX + raw)
        with open(msg_path, "wb") as handle:
            handle.write(message)
        with open(sig_path, "wb") as handle:
            handle.write(signature)
        completed = subprocess.run(
            [
                "openssl", "pkeyutl", "-verify", "-rawin", "-pubin",
                "-inkey", key_path, "-keyform", "DER",
                "-sigfile", sig_path, "-in", msg_path,
            ],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15,
        )
    if completed.returncode != 0:
        raise Winn3ContractError("signer-ticket-signature-invalid", ["sig"])


def winn3_decode_signer_ticket(payload_bytes: bytes, *, slug: str) -> dict:
    """Stateless re-verification of the stored ticket bytes (3.17).

    Canonical JSON (sorted keys, compact separators, ensure_ascii=False), the
    closed field set, the enums and the lifetime bound. The signer stays the
    authority for the epoch and the nonce at spend (3.8); the hub re-verifies
    the stored bytes again at use, reading go_live and tier from them.
    """
    try:
        ticket = json.loads(payload_bytes.decode("utf-8"))
    except Exception:
        raise Winn3ContractError("signer-ticket-malformed", ["payload"]) from None
    if not isinstance(ticket, dict):
        raise Winn3ContractError("signer-ticket-malformed", ["payload"])
    canonical = json.dumps(ticket, sort_keys=True, separators=(",", ":"),
                           ensure_ascii=False).encode("utf-8")
    if canonical != payload_bytes:
        raise Winn3ContractError("signer-ticket-not-canonical", ["payload"])
    if set(ticket) != set(WINN3_SIGNER_TICKET_FIELDS):
        raise Winn3ContractError("signer-ticket-fields", ["payload"])
    if ticket["slug"] != slug:
        raise Winn3ContractError("signer-ticket-wrong-slug", ["slug"])
    if ticket["action"] not in WINN3_SIGNER_TICKET_ACTIONS:
        raise Winn3ContractError("signer-ticket-action", ["action"])
    epoch = ticket["epoch"]
    if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 1:
        raise Winn3ContractError("signer-ticket-epoch", ["epoch"])
    try:
        endpoint = ipaddress.IPv4Address(str(ticket["endpoint_ip"]))
    except ValueError:
        raise Winn3ContractError("signer-ticket-endpoint", ["endpoint_ip"]) from None
    if str(endpoint) != str(ticket["endpoint_ip"]) or endpoint.is_unspecified \
            or endpoint.is_multicast or endpoint.is_loopback:
        raise Winn3ContractError("signer-ticket-endpoint", ["endpoint_ip"])
    if not isinstance(ticket["gateway_id"], str) or not ticket["gateway_id"].strip():
        raise Winn3ContractError("signer-ticket-gateway-id", ["gateway_id"])
    if not re.fullmatch(r"SHA256:[A-Za-z0-9+/]{43}", str(ticket["host_key_sha256"])):
        raise Winn3ContractError("signer-ticket-host-key", ["host_key_sha256"])
    if ticket["go_live"] not in ("auto", "manual") or ticket["tier"] not in ("free", "premium"):
        raise Winn3ContractError("signer-ticket-go-live-tier", ["go_live", "tier"])
    if not re.fullmatch(r"[0-9a-f]{32,64}", str(ticket["nonce"])):
        raise Winn3ContractError("signer-ticket-nonce", ["nonce"])
    not_after = ticket["not_after"]
    if isinstance(not_after, bool) or not isinstance(not_after, int):
        raise Winn3ContractError("signer-ticket-not-after", ["not_after"])
    now = time.time()
    if not_after <= now or not_after > now + WINN3_SIGNER_TICKET_MAX_LIFETIME_S:
        raise Winn3ContractError("signer-ticket-lifetime", ["not_after"])
    return ticket


def winn3_signer_status(timeout: float = 5.0) -> Optional[dict]:
    """Ask the signer's status verb over its socket (3.4).

    The ticket epoch lives in the signer's config directory, which the app can
    neither read nor write (3.8), so the ticket route answers the operator's
    minting query from the signer itself. Returns None when the signer is
    unreachable; callers fail closed.
    """
    try:
        conn = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        conn.settimeout(timeout)
        try:
            conn.connect(WINN3_SIGNER_SOCKET_PATH)
            conn.sendall(b'{"verb":"status"}\n')
            data = b""
            while b"\n" not in data and len(data) <= 65536:
                chunk = conn.recv(65537 - len(data))
                if not chunk:
                    break
                data += chunk
        finally:
            conn.close()
    except OSError:
        return None
    try:
        reply = json.loads(data.partition(b"\n")[0])
    except (ValueError, RecursionError):
        return None
    return reply if isinstance(reply, dict) else None


def _winn3_descriptor_b64_field(payload: dict, key: str, *, exact_len: int = 0,
                                min_len: int = 0, max_len: int = 0) -> bytes:
    value = payload.get(key)
    if not isinstance(value, str) or not value.strip():
        raise Winn3ContractError("descriptor-field-not-base64", [key])
    try:
        raw = base64.b64decode(value.strip(), validate=True)
    except Exception:
        raise Winn3ContractError("descriptor-field-not-base64", [key]) from None
    if exact_len and len(raw) != exact_len:
        raise Winn3ContractError("descriptor-field-wrong-length", [key])
    if min_len and len(raw) < min_len:
        raise Winn3ContractError("descriptor-field-too-short", [key])
    if max_len and len(raw) > max_len:
        raise Winn3ContractError("descriptor-field-too-long", [key])
    return raw


def _winn3_looks_like_ascii_hex(raw: bytes) -> bool:
    """True when every byte is an ASCII hex digit -- the shape keygen writes.

    Used only to TELL THE TWO ENCODINGS APART for the warning above, never to
    accept or refuse. The secret is opaque bytes by contract and nothing here
    may decode it.
    """
    if not raw:
        return False
    try:
        text = raw.decode("ascii")
    except Exception:
        return False
    return all(ch in "0123456789abcdefABCDEF" for ch in text)


def _winn3_descriptor_int_field(payload: dict, key: str) -> int:
    value = payload.get(key)
    if isinstance(value, bool) or not isinstance(value, int):
        raise Winn3ContractError("descriptor-field-not-an-integer", [key])
    return value


def validate_winn3_descriptor_payload(payload: Any, *, slug: str) -> dict:
    """Every rule a descriptor must satisfy, checked before it is ever stored.

    The hub validates for the same reason it validates protocol_params: a bad
    value here is not a warning, it is every winn/3 client of that node unable
    to complete a handshake, silently, because the gateway drops a failed
    admission tag without answering (design section 4.3). A 400 to one operator
    is the cheap version of that.

    Returns a normalized dict. Never returns, logs or raises with any secret
    value -- see WINN3_DESCRIPTOR_SECRET_FIELDS.
    """
    if not isinstance(payload, dict):
        raise Winn3ContractError("descriptor-not-an-object")
    present = {str(k).strip() for k in payload.keys()}
    missing = sorted(set(WINN3_DESCRIPTOR_REQUIRED_FIELDS) - present)
    if missing:
        raise Winn3ContractError("descriptor-missing-fields", missing)
    unknown = sorted(
        present - set(WINN3_DESCRIPTOR_REQUIRED_FIELDS) - set(WINN3_DESCRIPTOR_OPTIONAL_FIELDS)
    )
    if unknown:
        raise Winn3ContractError("descriptor-unknown-fields", unknown)

    if _winn3_descriptor_int_field(payload, "v") != WINN3_DESCRIPTOR_FORMAT_VERSION:
        raise Winn3ContractError("descriptor-unsupported-format-version", ["v"])
    alg = str(payload.get("alg") or "").strip().lower()
    if alg not in WINN3_DESCRIPTOR_SUPPORTED_ALGS:
        raise Winn3ContractError("descriptor-unsupported-algorithm", ["alg"])
    kid = str(payload.get("kid") or "").strip().lower()
    if kid not in WINN3_DESCRIPTOR_KEY_SLOTS:
        raise Winn3ContractError("descriptor-unknown-key-slot", ["kid"])

    node_slug = str(payload.get("node") or "").strip().lower()
    if not node_slug:
        raise Winn3ContractError("descriptor-missing-node", ["node"])
    if node_slug != (slug or "").strip().lower():
        # A descriptor names the node it describes, INSIDE the signed bytes.
        # Without this, a signed descriptor for gateway A could be installed on
        # gateway B and every client of B would seal initiations that only A
        # can open -- and would do so silently, since the gateway never answers
        # a failed tag. It is the control-plane half of the GatewayID binding
        # core already does on the wire (params.go:284-288).
        raise Winn3ContractError("descriptor-node-mismatch", ["node"])

    endpoint = str(payload.get("endpoint") or "").strip()
    if not winn3_is_ip_literal_endpoint(endpoint):
        raise Winn3ContractError("descriptor-endpoint-not-ip-literal", ["endpoint"])

    plain_ipv4: dict = {}
    for field in WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS:
        text = str(payload.get(field) or "").strip()
        if not winn3_is_inner_ipv4(text):
            raise Winn3ContractError("descriptor-inner-address-not-ipv4", [field])
        plain_ipv4[field] = text
    if plain_ipv4["inner_resolver_v4"] != plain_ipv4["inner_router_v4"]:
        raise Winn3ContractError(
            "descriptor-resolver-does-not-match-gateway-bind",
            ["inner_resolver_v4", "inner_router_v4"],
        )

    _winn3_descriptor_b64_field(
        payload, "static_pub", exact_len=WINN3_STATIC_PUBLIC_KEY_BYTES)
    gateway_id_raw = _winn3_descriptor_b64_field(
        payload, "gateway_id",
        min_len=WINN3_MIN_GATEWAY_ID_BYTES, max_len=WINN3_MAX_GATEWAY_ID_BYTES)
    if winn3_operator_text_has_edge_whitespace(gateway_id_raw):
        # Trap 3. See winn3_operator_text_has_edge_whitespace: one trailing
        # space here keys 9 bytes on the gateway and on Apple and 8 on Android,
        # and neither end can ever discover the disagreement because the value
        # is never transmitted. Refused at upload, where it costs one operator
        # one 400, rather than shipped to a fleet.
        raise Winn3ContractError(
            "descriptor-gateway-id-has-edge-whitespace", ["gateway_id"])
    admission_raw = _winn3_descriptor_b64_field(
        payload, "admission_secret", min_len=WINN3_MIN_ADMISSION_SECRET_BYTES)
    if winn3_operator_text_has_edge_whitespace(admission_raw):
        # The same asymmetry applies to the admission secret -- Android trims
        # it, the gateway does not -- with the same silent outcome. The key
        # file's trailing newline is stripped by every consumer by rule; any
        # OTHER edge whitespace is an accident, and an accident here is a
        # session that builds and then never answers.
        raise Winn3ContractError(
            "descriptor-admission-secret-has-edge-whitespace",
            ["admission_secret"])
    # TRAP 2, made checkable. The admission secret is OPAQUE BYTES: keygen
    # writes 64 ASCII hex characters and every consumer keys with the file's
    # bytes after trimming a trailing CR/LF and nothing else. base64 of the 32
    # DECODED bytes is 32 bytes here and is the exact defect the conformance
    # suite pins as `admission-secret-is-opaque-bytes`: the gateway admits the
    # datagram, BUILDS a session, and then goes completely silent.
    #
    # This hub, installer, gateway, signer and provisioner are one shipping
    # toolchain. Its canonical secret is exactly the 64 lowercase ASCII hex
    # bytes keygen writes, used opaquely without hex decoding. Accepting any
    # other shape here publishes a descriptor the installed gateway refuses,
    # so reject it while the operator can still correct one upload.
    if len(admission_raw) != 64 or not re.fullmatch(
        rb"[0-9a-f]{64}", admission_raw
    ):
        raise Winn3ContractError(
            "descriptor-admission-secret-noncanonical", ["admission_secret"]
        )

    tag_size = _winn3_descriptor_int_field(payload, "tag_size")
    if not (WINN3_MIN_TAG_SIZE <= tag_size <= WINN3_MAX_TAG_SIZE):
        raise Winn3ContractError("descriptor-tag-size-out-of-range", ["tag_size"])

    padding = str(payload.get("padding") or "").strip().lower()
    if padding not in WINN3_PADDING_POLICIES:
        raise Winn3ContractError("descriptor-unknown-padding-policy", ["padding"])

    window = _winn3_descriptor_int_field(payload, "bucket_window_s")
    skew = _winn3_descriptor_int_field(payload, "max_skew_s")
    spread, candidates, span = winn3_freshness_geometry(window, skew)
    # The rotation budget, checked at the WORST case rather than the current
    # one: a descriptor is accepted only if it would still be affordable while
    # a rotation is in flight, because otherwise the refusal would land on the
    # operator mid-rotation, which is the worst possible moment for it.
    if winn3_admission_hmac_cost(
        candidates, WINN3_MAX_LIVE_ADMISSION_KEYS
    ) > WINN3_MAX_ADMISSION_HMAC_BUDGET:
        raise Winn3ContractError(
            "descriptor-freshness-exceeds-rotation-budget",
            ["bucket_window_s", "max_skew_s"],
        )

    gen = _winn3_descriptor_int_field(payload, "admission_gen")
    if gen < 0:
        raise Winn3ContractError("descriptor-negative-admission-generation", ["admission_gen"])
    seq = _winn3_descriptor_int_field(payload, "seq")
    if seq < 0:
        raise Winn3ContractError("descriptor-negative-sequence", ["seq"])
    iat = _winn3_descriptor_int_field(payload, "iat")
    not_after = _winn3_descriptor_int_field(payload, "not_after")
    ttl = not_after - iat
    if ttl < WINN3_MIN_DESCRIPTOR_TTL_SECONDS:
        raise Winn3ContractError("descriptor-ttl-too-short", ["not_after"])
    if ttl > WINN3_MAX_DESCRIPTOR_TTL_SECONDS:
        # An unbounded ttl is an unbounded retirement deadline: the hub could
        # never say when an old admission key stops being reachable from a
        # cached config.
        raise Winn3ContractError("descriptor-ttl-too-long", ["not_after"])

    # Wall-clock lifetime. The store path checks shape; the clock is checked
    # here so the SERVE path (which re-runs this validator on every read)
    # refuses expired or not-yet-valid descriptors, not just the store path.
    now = int(time.time())
    if now < iat:
        raise Winn3ContractError("descriptor-not-yet-valid", ["iat"])
    if now >= not_after:
        raise Winn3ContractError("descriptor-expired", ["not_after"])

    # Dual-signature attestation keys are OPTIONAL as a pair: absent on
    # legacy nodes; both present, exactly sized, on dual-provisioned nodes. A
    # half-provisioned descriptor is refused.
    if payload.get("auth_ed25519") is not None or payload.get("auth_mldsa65") is not None:
        _winn3_descriptor_b64_field(
            payload, "auth_ed25519",
            exact_len=WINN3_DUAL_AUTH_ED25519_PUBLIC_KEY_BYTES)
        _winn3_descriptor_b64_field(
            payload, "auth_mldsa65",
            exact_len=WINN3_DUAL_AUTH_MLDSA65_PUBLIC_KEY_BYTES)

    descriptor = {
        "v": WINN3_DESCRIPTOR_FORMAT_VERSION,
        "alg": alg,
        "kid": kid,
        "node": node_slug,
        "endpoint": endpoint,
        # Plain dotted-quad text, NOT base64 -- see
        # WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS. Each reaches its `[winn]` key
        # exactly as it is written here, with no decode anywhere to disagree
        # about.
        **plain_ipv4,
        "static_pub": str(payload["static_pub"]).strip(),
        "gateway_id": str(payload["gateway_id"]).strip(),
        "admission_secret": str(payload["admission_secret"]).strip(),
        "admission_gen": gen,
        "tag_size": tag_size,
        "padding": padding,
        "bucket_window_s": window,
        "max_skew_s": skew,
        "seq": seq,
        "iat": iat,
        "not_after": not_after,
        # Derived, not signed -- recomputed anywhere it is needed so the two
        # can never disagree.
        "_spread": spread,
        "_bucket_candidates": candidates,
        "_acceptance_span_s": span,
        "_ttl_s": ttl,
    }
    # The attestation keys ride the descriptor to the client, so a dual-auth
    # node's client learns the exact keys the gateway will accept. Included
    # only after the pair validated above; a legacy descriptor has neither.
    if payload.get("auth_ed25519") is not None:
        descriptor["auth_ed25519"] = str(payload["auth_ed25519"]).strip()
        descriptor["auth_mldsa65"] = str(payload["auth_mldsa65"]).strip()
    return descriptor


def winn3_descriptor_public_fields(descriptor: dict) -> dict:
    """Everything about a descriptor that is safe to return or log.

    Secrets are replaced by their LENGTH, which is the only property an
    operator needs (it is the thing that has to be at least 32 bytes) and the
    only one that discloses nothing.
    """
    safe = {
        k: v for k, v in (descriptor or {}).items()
        if k not in WINN3_DESCRIPTOR_SECRET_FIELDS and not k.startswith("_")
    }
    for field in WINN3_DESCRIPTOR_SECRET_FIELDS:
        value = (descriptor or {}).get(field)
        if value is None:
            continue
        try:
            safe[f"{field}_bytes"] = len(base64.b64decode(str(value), validate=True))
        except Exception:
            safe[f"{field}_bytes"] = 0
    return safe


def parse_winn3_descriptor_envelope(value: Optional[str]) -> dict:
    """Read a stored descriptor envelope. Mirrors parse_protocol_params: a
    blank or malformed slot is an EMPTY dict, never an exception, because this
    is on the request path and a stored-blob problem must degrade to "no
    descriptor", not to a 500 for a paying user.
    """
    if not value:
        return {}
    try:
        data = json.loads(value)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    payload = str(data.get("payload") or "")
    signature = str(data.get("sig") or "")
    if not payload or not signature:
        return {}
    return {"payload": payload, "sig": signature}


def winn3_stored_descriptor(node: Any, *, reason_sink: Optional[dict] = None,
                            clock_tolerant: bool = False) -> dict:
    """The validated payload of whatever descriptor is stored on a node row.

    Returns {} when there is none or it no longer validates. Re-validated on
    the READ path for the same reason protocol_params is: a row can predate the
    validator, and serving a descriptor the gateway will not honour is worse
    than serving none.

    `reason_sink`, when given, is a dict that receives {"reason": ...} from
    the Winn3ContractError that refused the blob. Serve-path callers use it so
    a forged signature, an expired descriptor and an unclassifiable blob do
    not all read as one generic refusal.

    `clock_tolerant=True` tolerates ONLY the two clock refusals
    (descriptor-expired, descriptor-not-yet-valid) and exists for ONE serving
    caller: the inner-address allocator. (winn3_descriptor_expiry also uses it,
    read-only, to report an expired descriptor's not_after; it decides nothing.)
    A gateway keeps answering on its
    inner_router_v4 after the hub's descriptor clock lapses -- expiry is a
    SERVING control, not a gateway stop -- so an authentic expired
    descriptor's address claim must still be reserved (F-02, final audit
    2026-08-28) or the hub can hand a device the address of a live gateway.
    Every other check (shape, node binding, and above all the SIGNATURE)
    applies in full; only the clock is forgiven. It must NEVER be used on a
    serve path: the payload it returns failed the clock check.
    """
    try:
        raw = (
            node["winn3_descriptor_json"]
            if hasattr(node, "keys") and "winn3_descriptor_json" in node.keys()
            else (node.get("winn3_descriptor_json") if hasattr(node, "get") else None)
        )
    except Exception:
        raw = None
    envelope = parse_winn3_descriptor_envelope(raw)
    if not envelope:
        return {}
    slug = ""
    try:
        slug = str(node["slug"] if hasattr(node, "keys") else node.get("slug") or "")
    except Exception:
        slug = ""
    try:
        payload_bytes = base64.b64decode(envelope["payload"], validate=True)
        signature_bytes = base64.b64decode(envelope["sig"], validate=True)
        decoded = json.loads(payload_bytes.decode("utf-8"))
        try:
            normalized = validate_winn3_descriptor_payload(decoded, slug=slug)
        except Winn3ContractError as clock_exc:
            # F-02: forgive ONLY the clock. Every check that ran before the
            # clock in validate_winn3_descriptor_payload (shape, field set,
            # alg, kid slot, node binding, sizes, ttl bounds) has passed by
            # construction; the signature is still verified below. The value
            # returned is the raw decoded payload, whose field set the
            # missing/unknown checks already pinned to the closed schema.
            if not (clock_tolerant and clock_exc.reason in (
                    "descriptor-expired", "descriptor-not-yet-valid")):
                raise
            normalized = decoded
        kid = str(normalized.get("kid") or "").strip().lower()
        # Serve path re-verification (P0-1): the cryptographic control must be
        # enforced where the descriptor is consumed, not only where it is
        # stored. A forged or tampered row (e.g. a GCS-replica restore) fails
        # here and is served to no client -- and, with clock_tolerant, is
        # trusted by no allocator either.
        winn3_verify_descriptor_signature(payload_bytes, signature_bytes, kid)
        return normalized
    except Winn3ContractError as exc:
        if reason_sink is not None:
            reason_sink["reason"] = exc.reason
        return {}
    except Exception:
        return {}


def resolve_served_winn3_descriptor(
    node: Any,
    *,
    capabilities: dict,
    served_protocol_version: str,
) -> tuple:
    """Decide whether THIS request is served a descriptor. Returns (envelope, reason).

    THE DESCRIPTOR RIDES THE winn/3 GATE AND ADDS ONE FLAG. It is never served
    unless resolve_served_winn_protocol already decided this request gets
    winn/3, which means every refusal that gate makes is inherited here for
    free and cannot be bypassed:

      * stealth_active + winn/3 is a client-side refusal, and stealth_active is
        a PER-REQUEST choice, so the same node is winn/3-servable to one
        request and not the next. Because the descriptor is downstream of the
        gate, a stealth request against a registered winn/3 node is refused
        (not rewritten to winn/1) and no descriptor is served, with no second
        piece of logic that could disagree with the first. An explicit winn/1
        node still gets winn/1 and no descriptor.
      * Double VPN, an unusable obfuscation profile, an out-of-range MTU, a
        non-literal endpoint, an invalid params blob -- all already refused
        upstream.

    The added flag is supports_winn3_descriptor, DEFAULT FALSE. A client that
    speaks AWG-carried winn/3 but knows nothing about standalone descriptors
    must not be handed one; it would at best ignore it and at worst refuse.

    Dual-auth public keys are a second, stricter gate on the same envelope.
    The signed payload is stored and returned verbatim (the client verifies
    those exact bytes). The pair is RELEASED onto the served envelope only
    when the client sent supports_winn3_dualauth as an explicit true. A
    dual-auth-required request (true, against a dual-provisioned descriptor)
    that would drop either key is refused rather than silently downgraded.
    A legacy descriptor with neither key is preserved. Malformed capability
    values are refused, never coerced.
    """
    advertised = winn3_client_advertises_dualauth(capabilities)
    if served_protocol_version != WINN_PROTOCOL_V3:
        return {}, "not-serving-winn3"
    if not bool((capabilities or {}).get(WINN3_DESCRIPTOR_CLIENT_CAPABILITY)):
        return {}, "client-not-descriptor-capable"
    try:
        raw = (
            node["winn3_descriptor_json"]
            if hasattr(node, "keys") and "winn3_descriptor_json" in node.keys()
            else (node.get("winn3_descriptor_json") if hasattr(node, "get") else None)
        )
    except Exception:
        raw = None
    envelope = parse_winn3_descriptor_envelope(raw)
    if not envelope:
        return {}, "no-descriptor-registered"
    refusal: dict = {}
    stored = winn3_stored_descriptor(node, reason_sink=refusal)
    if not stored:
        # The specific Winn3ContractError reason when there is one (a forged
        # signature, an expired descriptor, a field the client would refuse),
        # the generic class when the blob failed outside the contract (unreadable
        # bytes): a GCS-replica restore that is not even a descriptor names no
        # contract reason.
        return {}, refusal.get("reason") or "descriptor-does-not-validate"
    keys = winn3_dual_auth_keys_for_capabilities(stored, capabilities)
    if advertised and winn3_descriptor_has_dual_auth(stored):
        if (
            keys.get("auth_ed25519") != stored.get("auth_ed25519")
            or keys.get("auth_mldsa65") != stored.get("auth_mldsa65")
        ):
            raise Winn3ContractError(
                "client-dual-auth-downgrade",
                ["auth_ed25519", "auth_mldsa65"],
            )
    served = dict(envelope)
    served.update(keys)
    return served, "winn3-descriptor"


def parse_winn3_admission_ledger(value: Optional[str]) -> dict:
    """The rotation bookkeeping stored on a node row.

    Bookkeeping ONLY. The generations themselves live in the signed
    descriptors; this records WHEN each became the served one, which is the
    single fact a signature cannot carry because it is not known at signing
    time.
    """
    if not value:
        return {}
    try:
        data = json.loads(value)
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def winn3_admission_sequence_floor(descriptor: dict, ledger: dict) -> int:
    """Highest descriptor sequence this node has ever accepted.

    The descriptor is deliberately removable: enabled=false must withhold it
    immediately. The replay floor is not removable, because accepting the same
    signed envelope after a disable would resurrect an admission secret the
    operator may already have retired. Only nonsecret integers are retained.
    """
    candidates = []
    for value in (
        (descriptor or {}).get("seq"),
        (ledger or {}).get("sequence_floor"),
        ((ledger or {}).get("current") or {}).get("seq")
        if isinstance((ledger or {}).get("current"), dict) else None,
        ((ledger or {}).get("previous") or {}).get("seq")
        if isinstance((ledger or {}).get("previous"), dict) else None,
    ):
        if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
            candidates.append(value)
    return max(candidates, default=-1)


def winn3_rotation_state(node: Any, *, now: Optional[Any] = None) -> dict:
    """Where this node is in an admission-key rotation, and when it is safe to
    retire the previous key.

    THE RETIREMENT FLOOR, and why it is not a guess:

        retire_after = promoted_at
                     + previous_descriptor_ttl        (cached-config staleness)
                     + acceptance_span                ((2*spread+1)*window)

    Term 2 is how long a client that fetched the OLD descriptor immediately
    before the promotion may still legitimately be using it from cache -- the
    client caches vpn_config in `_cachedVpnConfig` (lib/main.dart:704) and
    fast-connects from it in `_cachedDirectConfigForFastConnect`
    (lib/main.dart:5059-5066), so this is a real bound and not a formality.

    Term 3 is the freshness coupling, and it is added rather than assumed to be
    absorbed. An initiation sealed at the last instant a client used the old
    key is still acceptable across the whole (2*spread+1)*window span -- that
    span is BOTH the acceptance window and the replay-cache lifetime
    (handshake.go:494-506). Retiring at promoted_at + ttl exactly would strand
    the tail of that span. At the defaults it is 130 s against a ttl measured
    in hours, which is precisely why it would be tempting to drop it and
    precisely why it is computed from the descriptor's own parameters instead:
    a descriptor that widens max_skew widens this term with it.

    `safe_to_retire` is a floor, not a guarantee. A client that fast-connected
    from a cache older than the ttl AND cannot reach the hub still holds the
    old key. That residual is named in the handoff and is why the previous key
    is retired by an operator looking at this report, never by a timer.
    """
    now = now or utcnow()
    ledger = {}
    try:
        raw = (
            node["winn3_admission_json"]
            if hasattr(node, "keys") and "winn3_admission_json" in node.keys()
            else (node.get("winn3_admission_json") if hasattr(node, "get") else None)
        )
    except Exception:
        raw = None
    ledger = parse_winn3_admission_ledger(raw)
    current = ledger.get("current") if isinstance(ledger.get("current"), dict) else {}
    previous = ledger.get("previous") if isinstance(ledger.get("previous"), dict) else {}
    descriptor = winn3_stored_descriptor(node)

    state = {
        "phase": "none",
        "current_generation": None,
        "current_seq": None,
        "promoted_at": "",
        "previous_generation": None,
        "previous_promoted_at": "",
        "retire_after": "",
        "seconds_until_retire": None,
        "safe_to_retire_previous": False,
        "acceptance_span_s": None,
        "bucket_candidates": None,
        "gateway_admission_keys_expected": 0,
        "reject_path_hmacs": 0,
    }
    if not descriptor:
        return state

    state["current_generation"] = descriptor["admission_gen"]
    state["current_seq"] = descriptor["seq"]
    state["acceptance_span_s"] = descriptor["_acceptance_span_s"]
    state["bucket_candidates"] = descriptor["_bucket_candidates"]
    state["promoted_at"] = str(current.get("promoted_at") or "")

    if not previous or previous.get("generation") is None:
        state["phase"] = "steady"
        state["gateway_admission_keys_expected"] = 1
        state["reject_path_hmacs"] = winn3_admission_hmac_cost(
            descriptor["_bucket_candidates"], 1)
        return state

    state["phase"] = "overlap"
    state["previous_generation"] = previous.get("generation")
    state["previous_promoted_at"] = str(previous.get("promoted_at") or "")
    state["gateway_admission_keys_expected"] = 2
    state["reject_path_hmacs"] = winn3_admission_hmac_cost(
        descriptor["_bucket_candidates"], WINN3_MAX_LIVE_ADMISSION_KEYS)

    promoted_at = str(current.get("promoted_at") or "")
    previous_ttl = previous.get("ttl_s")
    if not promoted_at or not isinstance(previous_ttl, int):
        return state
    try:
        promoted = datetime.fromisoformat(promoted_at)
    except Exception:
        return state
    # Ensure both timestamps are timezone-aware UTC before subtraction.
    if promoted.tzinfo is not None:
        promoted = promoted.astimezone(timezone.utc)
    else:
        promoted = promoted.replace(tzinfo=timezone.utc)
    if now.tzinfo is not None:
        now = now.astimezone(timezone.utc)
    else:
        now = now.replace(tzinfo=timezone.utc)
    retire_after = promoted + timedelta(
        seconds=previous_ttl + descriptor["_acceptance_span_s"])
    state["retire_after"] = retire_after.isoformat()
    remaining = int((retire_after - now).total_seconds())
    state["seconds_until_retire"] = max(remaining, 0)
    state["safe_to_retire_previous"] = remaining <= 0
    return state


def extract_node_host(endpoint: str) -> str:
    endpoint = (endpoint or "").strip()
    if not endpoint:
        return ""
    if endpoint.startswith("[") and "]:" in endpoint:
        return endpoint.split("]:", 1)[0].strip("[]")
    if ":" in endpoint:
        return endpoint.rsplit(":", 1)[0]
    return endpoint

def split_host_port(endpoint: str, default_port: int) -> tuple[str, int]:
    endpoint = (endpoint or "").strip()
    if not endpoint:
        return "", default_port
    if endpoint.startswith("[") and "]:" in endpoint:
        host, port = endpoint.split("]:", 1)
        return host.strip("[]"), int(port or default_port)
    if ":" in endpoint and endpoint.rsplit(":", 1)[1].isdigit():
        host, port = endpoint.rsplit(":", 1)
        return host, int(port)
    return endpoint, default_port

def normalize_private_tunnel_gateway_ipv4(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        address = ipaddress.IPv4Address(raw)
    except ipaddress.AddressValueError:
        return ""
    rfc1918 = (
        ipaddress.IPv4Network("10.0.0.0/8"),
        ipaddress.IPv4Network("172.16.0.0/12"),
        ipaddress.IPv4Network("192.168.0.0/16"),
    )
    if not any(address in network for network in rfc1918):
        return ""
    if int(address) & 0xff in {0, 255}:
        return ""
    return str(address)

def node_registration_is_blocked(
    slug: str,
    endpoint: str,
    stealth_endpoint: str,
    ssh_host: str,
    source_ip: str,
) -> bool:
    if not NODE_REGISTER_BLOCKED_HOSTS:
        return False
    stealth_host, _ = split_host_port(stealth_endpoint, 443)
    candidates = {
        (slug or "").strip().lower(),
        extract_node_host(endpoint).strip().lower(),
        (stealth_host or "").strip().lower(),
        (ssh_host or "").strip().lower(),
        (source_ip or "").strip().lower(),
    }
    candidates.discard("")
    return bool(candidates & NODE_REGISTER_BLOCKED_HOSTS)

# --- node identity collision guard -----------------------------------------
#
# WHY THIS EXISTS. /api/v1/nodes/register used to run, immediately before its
# upsert:
#
#     DELETE FROM nodes
#      WHERE slug != ?
#        AND (endpoint = ?
#             OR (? != '' AND stealth_endpoint = ?)
#             OR (? != '' AND public_key = ?)
#             OR (? != '' AND ssh_host IS NOT NULL AND ssh_host != '' AND ssh_host = ?))
#
# The intent was de-duplication: when the same physical box is re-provisioned
# under a NEW slug (the data-plane installer derives NODE_SLUG from `hostname
# -s`, and it is also prompt-overridable, so a rename or a lost .env produces
# exactly this), the row under the old slug is stale and would otherwise be
# advertised alongside the new one -- splitting node_capacity_snapshot()
# accounting across two rows for one machine, listing one location twice, and
# pointing sync_peer_to_node() at the same ssh_host from two directions.
#
# WHY IT WAS UNSAFE. None of those four columns is UNIQUE (see
# create_nodes_table: `slug TEXT PRIMARY KEY` is the only key), so the DELETE
# enforced no database invariant -- it was pure application-level cleanup. And
# the only gate in front of it is this endpoint's per-node token, which proves
# exactly one thing: that the caller holds the token issued for `payload.slug`.
# It proves nothing whatsoever about any OTHER slug. So an authenticated
# registration for slug A could destroy the row for slug B, unbounded, with no
# ceiling on how many rows went. With one node in the fleet, a registration
# colliding on any one of four attributes deleted the only production node.
#
# It was worse than "a row disappears". The replacement row the upsert then
# creates does NOT carry management_status (the INSERT column list omits it),
# so it takes the CREATE TABLE default 'unknown' -- and every selection path
# (select_online_node, select_free_node, current_free_node_slugs) requires
# management_status='ok'. The same is true of protocol_version /
# protocol_params_json, which no endpoint writes and which therefore reset to
# 'winn/1' / NULL. So the successful path was: delete the only servable node,
# insert one that no client can be given, and return {"ok": True}.
#
# WHAT REPLACES IT. Nothing is deleted here, ever. A collision is *reported*,
# because the hub cannot tell the three cases apart on the wire -- a deliberate
# re-provision under a new slug, an operator mistyping a host into a second
# node's config, and a stolen node token being used to knock a different node
# out of the fleet all arrive looking identical. Resolving that ambiguity by
# destroying data is the wrong default; surfacing it as an error is the right
# one. Reclaiming a genuinely stale identity is an operator decision, taken
# deliberately against a backup, not a side effect of an HTTP request.
#
# This cannot regress a fleet that works today. All four attributes are
# per-node by construction (endpoint is host:port of one box, public_key is
# generated on that box, ssh_host is either that box's address or
# node_management_hostname(slug), and the installer's default stealth record is
# "${NODE_SLUG}.${zone}"), and a fleet that DID share one of them across two
# slugs was already having a row deleted on every registration. The only
# configuration this turns into an error is one the old code silently
# destroyed.
NODE_IDENTITY_ATTRIBUTES = ("endpoint", "stealth_endpoint", "public_key", "ssh_host")

class NodeIdentityCollision(Exception):
    """A registration claims an identity attribute another slug already holds.

    Carries slug/attribute NAMES only -- never the colliding values, which are
    endpoints and public keys.
    """

    def __init__(self, collisions: list[tuple[str, str]]):
        self.collisions = collisions
        super().__init__(
            "; ".join(f"{attribute} already claimed by {other}" for other, attribute in collisions)
        )

    @property
    def attributes(self) -> list[str]:
        return sorted({attribute for _, attribute in self.collisions})

    @property
    def slugs(self) -> list[str]:
        return sorted({other for other, _ in self.collisions})

def node_identity_collisions(
    conn: sqlite3.Connection,
    slug: str,
    *,
    endpoint: str,
    stealth_endpoint: str,
    public_key: str,
    ssh_host: str,
) -> list[tuple[str, str]]:
    """Rows OTHER THAN `slug` that already claim one of these attributes.

    Returns sorted (other_slug, attribute) pairs. Compares exactly the values
    the upsert is about to store, so the question asked is "will this row claim
    something another row already claims", not "does some normalized form of it
    look similar". Blank claims never collide -- a registration that supplies no
    stealth_endpoint is not claiming one, and the placeholder rows
    /api/v1/nodes/bootstrap creates (slug + token only) hold no identity at all.
    """
    claimed = {
        "endpoint": (endpoint or "").strip(),
        "stealth_endpoint": (stealth_endpoint or "").strip(),
        "public_key": (public_key or "").strip(),
        "ssh_host": (ssh_host or "").strip(),
    }
    rows = conn.execute(
        "SELECT slug, endpoint, stealth_endpoint, public_key, ssh_host FROM nodes WHERE slug != ?",
        (slug,),
    ).fetchall()
    collisions: set[tuple[str, str]] = set()
    for row in rows:
        other = str(row["slug"] or "")
        if not other:
            continue
        for attribute in NODE_IDENTITY_ATTRIBUTES:
            wanted = claimed[attribute]
            if wanted and str(row[attribute] or "").strip() == wanted:
                collisions.add((other, attribute))
    return sorted(collisions)

# --- admin node retirement --------------------------------------------------
#
# Added by the admin node-retirement lane (2026-08-07) to close the gap named
# in CONTROL_PLANE_REGISTER_IDENTITY_COLLISION_GUARD_20260807.md 6.3: once
# /api/v1/nodes/register refuses a colliding registration instead of deleting
# the other row, an operator has no supported way to retire a node at all.
# /admin/nodes/tier with "off" sets operator_enabled = 0, which withdraws the
# node from every selection path but leaves its four identity attributes
# claimed -- so it cannot clear the collision that produced the 409. Direct SQL
# against a live database was the only remaining answer, and it is the answer
# that leaves no record.
#
# WHY SOFT, AND WHY THAT DIFFERS FROM THE REGISTER LANE'S CHOICE. That lane
# refused rather than soft-deleting because the caller there is a NODE, holding
# a token that proves ownership of exactly one slug, and a soft delete would
# still have handed any single node token a fleet-wide denial-of-service
# primitive. That reasoning is about who is asking, not about what soft delete
# is, and it does not carry over: this endpoint is gated by
# require_admin_token, the same gate as every other /admin/ surface, and an
# operator retiring a node is exercising authority they already have. What the
# register lane's finding DOES demand of this endpoint is that the retirement
# be recoverable, because it established that a lost node row was not
# recoverable at all. Hence: nothing is deleted here either. The row survives
# with retired_at set, and its pre-retirement state is copied into
# node_retirements first.
#
# WHAT RETIREMENT ACTUALLY DOES, and why that combination and not another:
#
#   retired_at = now          the explicit state. A dedicated nullable column
#                             rather than a new nodes.status value, because
#                             status is overwritten by the node's own heartbeat
#                             and by mark_stale_nodes_offline(); a magic status
#                             string would not survive either one.
#   operator_enabled = 0      the existing "withdrawn" switch every selection
#                             path already honours.
#   management_status =       so the node fails the management_status = 'ok'
#     'unknown'               conjunct that select_online_node(),
#                             select_free_node(), current_free_node_slugs() and
#                             GET /nodes all require. Never 'ok' -- see below.
#   status = 'offline'        honest, and already what mark_stale_nodes_offline
#                             would converge on.
#   endpoint, stealth_        blanked. THIS is the part /admin/nodes/tier "off"
#     endpoint, public_key,   cannot do and the whole reason this endpoint
#     ssh_host                exists: node_identity_collisions() treats a blank
#                             claim as no claim, so releasing these four is
#                             what lets the renamed box register under its new
#                             slug. Their values are preserved in the tombstone.
#
# Left deliberately untouched on the row: node_token_hash and preshared_key
# (retirement is not a credential rotation, and the node may legitimately be
# restored), protocol_version and protocol_params_json (no endpoint writes
# these; losing them is exactly the damage the register lane documented), the
# byte counters, max_peers, free_access_enabled, and the data_plane_* history.
#
# THE COMBINATION IS WHAT MAKES IT STICK. A retired row cannot become servable
# again by accident, because every selection path needs all three of
# status = 'online', management_status = 'ok' and operator_enabled = 1, and
# reaching the middle one requires a REAL management probe: both writers of
# 'ok' (resync_active_peers_to_node and the Double VPN exit sync) reach the box
# over SSH at ssh_host / extract_node_host(endpoint), and both of those are now
# blank, so the probe can only ever mark 'failed'. A node's own heartbeat can
# still flip status back to 'online' and an operator can still flip
# operator_enabled back to 1 via the evidenced /admin/nodes/tier promotion,
# and neither is enough.
# Registration is handled separately and explicitly, in register_node().
NODE_RETIREMENT_IDENTITY_RELEASE = NODE_IDENTITY_ATTRIBUTES

# Never copied into the node_retirements tombstone. Both are secrets that stay
# on the live row; duplicating them would extend their lifetime into a second
# table for no recovery benefit, since a soft-deleted row still has them.
NODE_RETIREMENT_UNRECORDED_COLUMNS = ("node_token_hash", "preshared_key")

# "Servable", for the last-node guard. The specified predicate, verbatim:
#
#     status = 'online' AND management_status = 'ok'
#                       AND COALESCE(operator_enabled, 0) = 1
#
# It is the platform-independent core of the selection predicate, deliberately
# WITHOUT data_plane_sql(platform) and without the capacity check.
#
# That omission makes the guard STRONGER, not weaker, and it is the important
# design point here. The data_plane_* columns are refreshed by an external
# prober on its own timer, so a node having a bad five minutes reads as
# not-servable -- and if the last-node guard counted that way, the moment the
# fleet's only node failed a probe would be the exact moment the guard stopped
# protecting it. What this counts is what POLICY and MANAGEMENT admit: rows the
# operator has enabled, that are heartbeating, and whose management tunnel has
# been verified. Retiring the last of those empties the fleet whatever the
# probe happens to say today.
NODE_SERVABLE_PREDICATE_SQL = (
    "status = 'online'"
    " AND management_status = 'ok'"
    " AND COALESCE(operator_enabled, 0) = 1"
)

# The ONE conjunct added on top, and why a guard that counts differently from
# the selector is not the defect this project keeps finding.
#
# A row retired by this endpoint already fails the predicate above three times
# over (status='offline', management_status='unknown', operator_enabled=0), so
# for anything this code path produces the two are identical. The conjunct is
# for the row someone puts back BY HAND -- the direct-SQL habit this endpoint
# exists to replace -- which is exactly the row that would otherwise be counted
# as a servable fleet member while carrying no endpoint, no public key and no
# management host.
#
# The direction of the divergence is the point, and it is proved rather than
# asserted: this set is a strict SUBSET of the predicate above, so the guard can
# only ever count FEWER nodes as servable, never more. A guard that under-counts
# refuses a retirement it could have allowed; a guard that over-counts allows one
# that empties the fleet. Only the second is a defect, and this cannot produce it.
SERVABLE_NODES_SQL = f"""
    SELECT slug FROM nodes
    WHERE {NODE_SERVABLE_PREDICATE_SQL}
      AND retired_at IS NULL
    ORDER BY LOWER(slug) ASC
"""

def servable_node_slugs(conn: sqlite3.Connection) -> list[str]:
    return [str(row["slug"] or "") for row in conn.execute(SERVABLE_NODES_SQL).fetchall() if row["slug"]]

FLEET_AVAILABILITY_AUDIT_SECONDS = max(
    30, int(os.getenv("FLEET_AVAILABILITY_AUDIT_SECONDS", "120") or 120)
)

# IA-SYNC SYNC-07: every v3 descriptor expires (the ttl ceiling is 30 days)
# and re-signing is an offline ceremony by design, so the hub warns before the
# serve path starts refusing. Priority 2 is in the default email set; the
# finding's priority 3 would only have been logged. One alert per descriptor
# and state per WINN3_DESCRIPTOR_EXPIRY_REALERT_SECONDS, because the fleet
# audit runs every two minutes. The warning starts a day after
# winn3_auto_provision() starts renewing (under 7 days left), so a renewal that
# works never mails; only one that has failed for a day does.
WINN3_DESCRIPTOR_EXPIRY_WARN_SECONDS = 6 * 24 * 3600
WINN3_DESCRIPTOR_EXPIRY_REALERT_SECONDS = 24 * 3600
_WINN3_DESCRIPTOR_EXPIRY_ALERTED: dict[tuple[str, int, str], float] = {}

def winn3_descriptor_expiry(node: Any, now: Optional[float] = None) -> dict:
    """Expiry of a node's stored descriptor, for reporting only.

    Read through winn3_stored_descriptor(clock_tolerant=True), so the
    signature and node binding are still verified and an expired descriptor
    is still reported by its real not_after. state is "none" (no authentic
    descriptor), "ok", "expiring" (under WINN3_DESCRIPTOR_EXPIRY_WARN_SECONDS
    left) or "expired". Never a serve decision.
    """
    now = time.time() if now is None else float(now)
    payload = winn3_stored_descriptor(node, clock_tolerant=True)
    try:
        not_after = int(payload.get("not_after")) if payload else 0
    except (TypeError, ValueError):
        not_after = 0
    if not_after <= 0:
        return {"state": "none", "not_after": None, "seconds_left": None}
    seconds_left = int(not_after - now)
    if seconds_left <= 0:
        state = "expired"
    elif seconds_left < WINN3_DESCRIPTOR_EXPIRY_WARN_SECONDS:
        state = "expiring"
    else:
        state = "ok"
    return {"state": state, "not_after": not_after, "seconds_left": seconds_left}

def alert_winn3_descriptor_expiry(rows: list, now: Optional[float] = None) -> list[dict]:
    """Alert for every winn/3 node whose descriptor expires soon or has expired."""
    now = time.time() if now is None else float(now)
    findings = []
    for row in rows:
        data = dict(row)
        if str(data.get("protocol_version") or "").strip().lower() != "winn/3":
            continue
        # A closed node serves nobody and is checked again once reopened; its
        # lapsed descriptor mailed daily for weeks (spain-madrid, 2026-10).
        if not int(data.get("operator_enabled") or 0):
            continue
        expiry = winn3_descriptor_expiry(row, now)
        if expiry["state"] not in {"expiring", "expired"}:
            continue
        slug = str(data.get("slug") or "")
        finding = {"slug": slug, **expiry}
        findings.append(finding)
        key = (slug, int(expiry["not_after"]), expiry["state"])
        last = _WINN3_DESCRIPTOR_EXPIRY_ALERTED.get(key)
        if last is not None and now - last < WINN3_DESCRIPTOR_EXPIRY_REALERT_SECONDS:
            continue
        _WINN3_DESCRIPTOR_EXPIRY_ALERTED[key] = now
        event = (
            "winn3 descriptor expires soon" if expiry["state"] == "expiring"
            else "winn3 descriptor expired"
        )
        security_alert(2, event, details={
            "slug": slug,
            "not_after": int(expiry["not_after"]),
            "warn_window_seconds": WINN3_DESCRIPTOR_EXPIRY_WARN_SECONDS,
        })
        logger.warning(
            "%s: node %s not_after=%d seconds_left=%d; re-sign offline with "
            "tools/winn3_sign_descriptor.py and POST /admin/nodes/winn3/descriptor",
            event, slug, int(expiry["not_after"]), int(expiry["seconds_left"]),
        )
    return findings

# IA-SYNC round 2 (Seat C N-2): the health-forging keepalive (SYNC-04) set
# operator_enabled=1 by direct SQL on its nine slugs, france-fr1 included.
# Quarantining it changes no row, so every such opening persists until a
# health closure. REPORT ONLY (changing rows needs a ruling): an open node
# counts as evidenced when an operator promotion was recorded after its last
# closure, or its last opening was an automatic reopen after that closure.
_UNEVIDENCED_OPEN_ALERTED: dict[str, float] = {}

def open_nodes_without_promotion_evidence(conn: sqlite3.Connection) -> list[dict]:
    report = []
    rows = conn.execute(
        "SELECT slug FROM nodes WHERE COALESCE(operator_enabled, 0) = 1 AND retired_at IS NULL "
        "ORDER BY slug"
    ).fetchall()
    for row in rows:
        slug = str(row["slug"] or "")
        closed = conn.execute(
            "SELECT event_id, changed_at FROM node_latch_events WHERE slug = ? AND to_value = 0 "
            "ORDER BY event_id DESC LIMIT 1", (slug,)).fetchone()
        opened = conn.execute(
            "SELECT event_id, changed_at, cause FROM node_latch_events WHERE slug = ? AND to_value = 1 "
            "ORDER BY event_id DESC LIMIT 1", (slug,)).fetchone()
        closed_at = parse_iso_datetime(closed["changed_at"]) if closed else None
        promoted = False
        for event in conn.execute(
                "SELECT promoted_at FROM node_promotion_events WHERE slug = ?", (slug,)):
            at = parse_iso_datetime(event["promoted_at"])
            if at is not None and (closed_at is None or at > closed_at):
                promoted = True
                break
        # Latch events order by event_id (their timestamps share milliseconds).
        auto = bool(opened) and str(opened["cause"] or "") in (*NODE_AUTO_REOPEN_CAUSES, "operator_promotion") and \
            (closed is None or int(opened["event_id"]) > int(closed["event_id"]))
        if not (promoted or auto):
            report.append({
                "slug": slug,
                "last_closure_at": closed["changed_at"] if closed else None,
                "last_opening_cause": opened["cause"] if opened else None,
            })
    return report

def alert_unevidenced_open_nodes(conn: sqlite3.Connection, now: Optional[float] = None) -> list[dict]:
    now = time.time() if now is None else float(now)
    report = open_nodes_without_promotion_evidence(conn)
    for item in report:
        last = _UNEVIDENCED_OPEN_ALERTED.get(item["slug"])
        if last is not None and now - last < 24 * 3600:
            continue
        _UNEVIDENCED_OPEN_ALERTED[item["slug"]] = now
        security_alert(2, "open node without promotion evidence", details=dict(item))
        logger.warning(
            "node %s is open with no promotion record since its last closure (last opening cause=%s); "
            "reported only, no row changed", item["slug"], item["last_opening_cause"],
        )
    return report

def audit_fleet_availability_once() -> dict:
    """Alert when no node can actually be selected for a new connection."""
    with get_db() as conn:
        ensure_schema(conn)
        mark_stale_nodes_offline(conn)
        rows = conn.execute("SELECT * FROM nodes WHERE retired_at IS NULL").fetchall()
        servable = [
            row for row in rows
            if node_is_online_and_managed(row) and node_accepts_new_peer(conn, row)
        ]
    result = {"registered": len(rows), "servable": len(servable)}
    if not servable:
        security_alert(
            1,
            "fleet has zero currently servable nodes",
            details=result,
        )
        logger.error(
            "fleet availability audit: zero currently servable nodes "
            "(registered=%d)", len(rows),
        )
    # After the zero-servable alert, whose details (and so its throttle
    # identity) stay exactly {registered, servable}. The key is added only
    # when something is expiring, so the result shape is otherwise unchanged.
    try:
        expiring = alert_winn3_descriptor_expiry(rows)
    except Exception as exc:
        logger.warning("winn3 descriptor expiry check failed: %s", type(exc).__name__)
        expiring = []
    if expiring:
        result["winn3_descriptor_expiry"] = expiring
    try:
        with get_db() as conn:
            unevidenced = alert_unevidenced_open_nodes(conn)
    except Exception as exc:
        logger.warning("unevidenced open-node check failed: %s", type(exc).__name__)
        unevidenced = []
    if unevidenced:
        result["open_without_promotion_evidence"] = unevidenced
    return result


# Days of origin certificate validity below which the contract audit alerts.
# The node renews below 30 days (SYNC-22 timer), so a certificate still under
# this threshold means renewal has been failing for two weeks.
ORIGIN_CERT_ALERT_DAYS = max(1, int(os.getenv("ORIGIN_CERT_ALERT_DAYS", "14") or 14))


def audit_winn3_contract_once() -> dict:
    """Alert on hub-visible contract drift that would otherwise surface as an outage.

    SYNC-06 (Q2 Stage 0): a winn/3 node whose inner pool has fewer than
    WINN3_INNER_FREE_ALERT_BELOW free addresses. Under the single shared
    slice every node reports the same fleet-wide count.
    SYNC-03: a canary binding a device already holds (that node's registry
    build refuses, so every push to it stops).
    SYNC-15/16: a winn/3 standalone node whose gateway report disagrees with
    its descriptor or plan (definite disagreements only; "not reported" is a
    readiness blocker, not an alert).
    SYNC-22: a node origin certificate close to expiry.
    Alerts only; changes nothing served or allocated. Runs from the fleet
    availability sweep, right after audit_fleet_availability_once.
    """
    quiet = {"winn3_gateway_not_reported", "winn3_gateway_report_incomplete"}
    now = utcnow()
    result = {"inner_pools": {}, "inner_pool_low_nodes": 0, "canary_collision_nodes": 0,
              "gateway_mismatch_nodes": 0, "origin_cert_expiring_nodes": 0}
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute("SELECT * FROM nodes WHERE retired_at IS NULL").fetchall()
        collisions = winn3_canary_device_collisions(conn)
        in_use = winn3_inner_addresses_in_use(conn)
        pool_usage = {}
        for row in rows:
            if strict_stored_protocol_version(row) != WINN_PROTOCOL_V3:
                continue
            node_pool = winn3_node_inner_slice(row)
            if node_pool is not None:
                pool_usage[str(row["slug"] or "")] = winn3_inner_slice_usage(conn, node_pool, in_use)
    for usage in pool_usage.values():
        result["inner_pools"][usage["pool"]] = usage
    for row in rows:
        slug = str(row["slug"] or "")
        usage = pool_usage.get(slug)
        if usage and usage["free"] < WINN3_INNER_FREE_ALERT_BELOW:
            result["inner_pool_low_nodes"] += 1
            security_alert(3, "winn3 inner pool low", details={
                "slug": slug, "free": usage["free"], "pool": usage["pool"],
            })
            logger.warning(
                "winn3 inner pool %s for %s has %d of %d addresses free; a device gets no v3 address when it is full",
                usage["pool"], slug, usage["free"], usage["capacity"],
            )
        if slug.lower() in collisions:
            result["canary_collision_nodes"] += 1
            security_alert(2, "winn3 canary binding held by a device", details={
                "slug": slug, "blockers": collisions[slug.lower()],
            })
        if strict_stored_protocol_version(row) == WINN_PROTOCOL_V3:
            try:
                obfuscation = parse_obfuscation(row["obfuscation_json"])
            except ObfuscationProfileError:
                obfuscation = {}
            readiness = winn3_node_readiness(row, obfuscation)
            mismatches = sorted(
                b for b in readiness["blockers"]
                if b in WINN3_GATEWAY_REPORT_BLOCKERS and b not in quiet
            )
            if mismatches:
                result["gateway_mismatch_nodes"] += 1
                security_alert(3, "winn3 gateway disagrees with the hub", details={
                    "slug": slug, "blockers": mismatches,
                })
        not_after = sanitize_origin_cert_not_after(_node_field(row, "origin_cert_not_after"))
        if not_after:
            left = datetime.strptime(not_after, "%Y-%m-%dT%H:%M:%SZ") - now.replace(tzinfo=None)
            if left < timedelta(days=ORIGIN_CERT_ALERT_DAYS):
                result["origin_cert_expiring_nodes"] += 1
                security_alert(2, "node origin certificate close to expiry", details={
                    "slug": slug, "not_after": not_after,
                })
        # Design 10.2 (P1): a current report that names a read-back drift. A
        # harness arm or an operator's queue override is shown at the log-only
        # priority, every other reason at an emailed one. The key is added only
        # when a node drifts, so the result shape is otherwise unchanged.
        drift = node_performance_drift(row, now)
        if drift:
            result["performance_drift_nodes"] = result.get("performance_drift_nodes", 0) + 1
            hard = [reason for reason in drift if reason not in NODE_PERF_NOTICE_REASONS]
            # A drift that persists is one alert per node and reason set, then a
            # reminder every NODE_PERF_DRIFT_REALERT_SECONDS: the sweep runs every
            # FLEET_AVAILABILITY_AUDIT_SECONDS and the throttle is only 300 s, so
            # alerting on every sweep would send ten emails an hour per node.
            signature = tuple(drift)
            last = _NODE_PERF_DRIFT_ALERTED.get(slug)
            stamp = time.monotonic()
            if last is None or last[0] != signature or stamp - last[1] >= NODE_PERF_DRIFT_REALERT_SECONDS:
                _NODE_PERF_DRIFT_ALERTED[slug] = (signature, stamp)
                security_alert(2 if hard else 3, "node performance read-back drift", details={
                    "slug": slug, "reasons": drift,
                })
        else:
            _NODE_PERF_DRIFT_ALERTED.pop(slug, None)
    return result

# --- L84 (Round SC): reversible automatic closure, alert on every flip --------
#
# An AUTOMATIC health closure (stale sweep or data-plane prober) sets
# nodes.health_closed_at. An operator closure (tier off, installer withdrawal,
# retirement) clears it. Only a row that still carries it can be reopened
# automatically, and only when NODE_AUTO_REOPEN_ENABLED=1, through
# node_promotion_readiness_failures() (the complete manual promotion gate,
# including verify_offnode_gate_for_use() on the newest unused gate record,
# consumed on success by consume_offnode_gate()) plus:
#   * NODE_AUTO_REOPEN_PROOFS consecutive healthy prober runs (every configured
#     transport reachable, heartbeat online and fresh) in a streak that began
#     after the closure, all counted AFTER this hub process saw authority
#     recovery complete (the streak length seen at arming is the baseline);
#   * a closed-node cleanup confirmed after the closure;
#   * a fresh heartbeat now, and at most NODE_AUTO_REOPEN_MAX_PER_DAY reopens.
# The arm and the baselines are process memory: every hub start begins
# disarmed, and both are dropped again whenever winn3_recovery_state() is not
# paired, complete and budget-trusted. Nothing is reopened during authority
# recovery, and after it completes every counted proof is new.
_NODE_AUTO_REOPEN_ARMED_AT: Optional[str] = None
_NODE_AUTO_REOPEN_BASELINE: dict[str, tuple[str, int]] = {}

def node_auto_reopen_arm(conn: sqlite3.Connection) -> Optional[str]:
    global _NODE_AUTO_REOPEN_ARMED_AT
    try:
        view = winn3_recovery_state(conn)
        quiescent = bool(view.get("paired")) and bool(view.get("complete")) \
            and bool(view.get("budget_trusted"))
    except Exception as exc:
        logger.warning("node auto-reopen disarmed: recovery state unreadable (%s)",
                       type(exc).__name__)
        quiescent = False
    if not quiescent:
        _NODE_AUTO_REOPEN_ARMED_AT = None
        _NODE_AUTO_REOPEN_BASELINE.clear()
        return None
    if _NODE_AUTO_REOPEN_ARMED_AT is None:
        _NODE_AUTO_REOPEN_BASELINE.clear()
        _NODE_AUTO_REOPEN_ARMED_AT = utcnow().isoformat()
        logger.info("node auto-reopen armed: authority recovery complete in this process")
    return _NODE_AUTO_REOPEN_ARMED_AT

def node_auto_reopen_failures(
    conn: sqlite3.Connection, node: Any, armed_at: Optional[str]
) -> list[str]:
    data = dict(node)
    slug = str(data.get("slug") or "")
    failures = []
    if data.get("winn3_operator_hold"):
        failures.append("winn3 operator hold is active")
    if str(data.get("retired_at") or "").strip():
        failures.append("node is retired")
    if str(data.get("deployment_withdrawal_id") or "").strip():
        failures.append("installer deployment withdrawal is active")
    if int(data.get("operator_enabled") or 0) != 0:
        failures.append("latch is not closed")
    closed_at = str(data.get("health_closed_at") or "")
    if not closed_at:
        failures.append("not an automatic health closure; operator closures are never reopened")
    if not armed_at:
        failures.append("authority recovery is not complete in this hub process")
    heartbeat_cutoff = (
        utcnow() - timedelta(seconds=NODE_AUTO_REOPEN_HEARTBEAT_MAX_AGE_SECONDS)
    ).isoformat()
    if not data.get("last_heartbeat") or str(data.get("last_heartbeat")) < heartbeat_cutoff:
        failures.append("heartbeat is absent or stale")
    streak = int(data.get("data_plane_green_streak") or 0)
    since = str(data.get("data_plane_green_since") or "")
    if not since or not closed_at or since <= closed_at:
        failures.append("no healthy-proof streak that began after the closure")
    if armed_at:
        # Proofs counted only after arming: the streak seen at the first armed
        # look is the baseline; a streak that restarted since is all new.
        base_since, base_streak = _NODE_AUTO_REOPEN_BASELINE.setdefault(slug, (since, streak))
        after = streak - base_streak if since == base_since else streak
        if after < NODE_AUTO_REOPEN_PROOFS:
            failures.append(
                f"{max(0, after)} of {NODE_AUTO_REOPEN_PROOFS} consecutive healthy proofs "
                "since authority recovery completed in this process")
    cleanup = conn.execute(
        "SELECT state, confirmed_at FROM node_closure_cleanup WHERE slug = ?", (slug,)
    ).fetchone()
    if cleanup is not None and cleanup["state"] == "confirmed" and \
            str(cleanup["confirmed_at"] or "") <= closed_at:
        failures.append("closed-node runtime cleanup is not later than this closure (resync the node)")
    # The complete manual gate, off-node gate included, against the newest
    # unused gate record an operator posted for this node.
    failures += node_promotion_readiness_failures(
        conn, data, node_auto_reopen_gate_record(conn, slug),
        allow_hub_gate=str(data.get("health_closed_reason") or "") in HUB_OFFNODE_GATE_CLOSURE_REASONS)
    day_ago = (utcnow() - timedelta(hours=24)).isoformat()
    # IA-SYNC SYNC-08: the budget is shared by health and installer-rerun
    # reopens; H7: and by the fresh_install go-live (design 3.17).
    reopened = int(conn.execute(
        "SELECT COUNT(*) FROM node_latch_events WHERE slug = ? AND cause IN ("
        + ", ".join("?" for _ in NODE_AUTO_REOPEN_CAUSES) + ") AND changed_at >= ?",
        (slug, *NODE_AUTO_REOPEN_CAUSES, day_ago),
    ).fetchone()[0])
    if reopened >= NODE_AUTO_REOPEN_MAX_PER_DAY:
        failures.append(
            f"automatic reopen used {reopened} times in 24 h; manual promotion required")
    return failures

def node_auto_reopen_gate_record(conn: sqlite3.Connection, slug: str) -> str:
    """The newest unused, unexpired off-node gate record for this node, or ""
    (which verify_offnode_gate_for_use() then refuses). Cleanup match and the
    node report are verified by that function, not here. IA-SYNC round 2
    (OI-SYNC_HUB-2): a record past OFFNODE_GATE_MAX_AGE_SECONDS can never be
    used, so it is not selected; otherwise it would stand in for "a gate
    exists" and stop a replacement from being built."""
    cutoff = (utcnow() - timedelta(seconds=OFFNODE_GATE_MAX_AGE_SECONDS)).isoformat()
    row = conn.execute(
        "SELECT gate_sha256 FROM node_offnode_gates WHERE slug = ? AND used_at IS NULL "
        "AND recorded_at >= ? ORDER BY recorded_at DESC LIMIT 1",
        (slug, cutoff),
    ).fetchone()
    return str(row["gate_sha256"]) if row is not None else ""

# --- IA-SYNC SYNC-08: installer rerun reopen (Fable 5.1 ruling 2026-09-29, Q1)
#
# Withdrawal snapshots the node's identity (A). Completion closes an eligible
# rerun as health_closed_reason='installer_rerun' (B). auto_reopen_health_
# closed_nodes() may reopen it under NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED
# only after every L84 condition plus D.i to D.iv, inside the window.
#
# One prerequisite does not exist yet, so every rerun is RECORDED but HELD, and
# the checks below fail closed by name until it lands:
#   * the hub-side AWG carrying canary (ruling E) exists since H5: its columns
#     data_plane_{udp,stealth,stealth_tls}_carry_status/_ok_at are written by
#     wins_node_dataplane_probe.py --carry, and a transport with no carrying
#     proof newer than the rerun completion holds the rerun by name (an old row
#     without the columns is still refused as "awg carrying canary not
#     available");
#   * the hub-run off-node gate (ruling D.ii) exists since H6:
#     installer_rerun_hub_offnode_gate runs the pinned node-side check over
#     node_ssh_command when every other condition passes, evaluates it with
#     offnode_node_report_failures and records a source='hub' row; a failed
#     check holds the rerun with its reasons, and an operator-posted record
#     still satisfies the gate condition.
# The per-slug v3 canary (SYNC-03) is consumed by name through the existing
# per-row columns winn3_canary_status / winn3_canary_ok_at; until SYNC-03
# writes them for every winn/3 slug, a winn/3 node other than the configured
# canary slug is held.
NODE_RERUN_IDENTITY_FIELDS = (
    "public_key", "endpoint", "wg_port", "ssh_host", "stealth_endpoint",
    "stealth_public_port", "stealth_transports", "xray_uuid", "xray_path",
    "xray_security", "regional_aliases", "obfuscation_sha256", "protocol_version",
    "carrier_classes", "path_mtu", "winn3_identity_sha256",
)
# H7 (design 3.17, "the first v3 transition is expected, not a change"): the
# four fields the carrier flip itself changes. A difference in exactly these is
# accepted only against the transition the job recorded in the same generation-
# checked transaction as the flip (winn3_expected_transition_json).
NODE_RERUN_TRANSITION_FIELDS = (
    "protocol_version", "carrier_classes", "path_mtu", "winn3_identity_sha256",
)
NODE_RERUN_AWG_CARRY_COLUMNS = (
    ("udp", "data_plane_udp_carry"),
    ("stealth", "data_plane_stealth_carry"),
    ("stealth_tls", "data_plane_stealth_tls_carry"),
)
NODE_RERUN_REVISION_RE = re.compile(r"sha256:[0-9a-f]{64}")

def _node_obfuscation_sha256(value: Any) -> str:
    """SHA-256 of the canonical served obfuscation JSON (sort_keys, compact)."""
    try:
        canonical = json.dumps(parse_obfuscation(value), sort_keys=True, separators=(",", ":"))
    except Exception:
        canonical = "raw:" + str(value or "")
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

def node_winn3_identity_sha256(node: Any) -> str:
    """Design 3.17: SHA-256 over the descriptor-signed identity fields of the
    stored, verified descriptor (winn3_stored_descriptor, clock tolerant), with
    the admission fingerprint in place of the secret; "" when there is none.
    A renewal re-signs only seq, iat and not_after, so it does not change this
    value, which is why it replaces the raw descriptor hash as the rerun
    identity field."""
    try:
        descriptor = winn3_stored_descriptor(dict(node), clock_tolerant=True)
        return winn3_identity_digest(descriptor) if descriptor else ""
    except Exception:
        return ""

def node_deployment_prior_state(node: Any, withdrawn_at: str) -> dict:
    """Ruling A: the identity a later completion is compared with. Secret-free:
    the token is already a hash, and the identity and obfuscation are digests."""
    data = dict(node)
    return {
        "withdrawn_at": withdrawn_at,
        "operator_enabled": int(data.get("operator_enabled") or 0),
        "free_access_enabled": int(data.get("free_access_enabled") or 0),
        "node_token_hash": data.get("node_token_hash") or "",
        "public_key": data.get("public_key"),
        "endpoint": data.get("endpoint"),
        "wg_port": data.get("wg_port"),
        "ssh_host": data.get("ssh_host"),
        "stealth_endpoint": data.get("stealth_endpoint"),
        "stealth_public_port": data.get("stealth_public_port"),
        "stealth_transports": data.get("stealth_transports"),
        "xray_uuid": data.get("xray_uuid"),
        "xray_path": data.get("xray_path"),
        "xray_security": data.get("xray_security"),
        "regional_aliases": data.get("regional_aliases"),
        "obfuscation_sha256": _node_obfuscation_sha256(data.get("obfuscation_json")),
        "protocol_version": data.get("protocol_version"),
        "carrier_classes": data.get("carrier_classes"),
        "path_mtu": data.get("path_mtu"),
        "winn3_identity_sha256": node_winn3_identity_sha256(data),
        "data_plane_code_revision": data.get("data_plane_code_revision") or "",
    }

def node_deployment_prior(node: Any) -> dict:
    try:
        prior = json.loads(dict(node).get("deployment_prior_state_json") or "")
    except (TypeError, ValueError):
        return {}
    return prior if isinstance(prior, dict) else {}

def _iso_after(value: Any, reference: Any) -> bool:
    later = parse_iso_datetime(value if isinstance(value, str) else None)
    earlier = parse_iso_datetime(reference if isinstance(reference, str) else None)
    return later is not None and earlier is not None and later > earlier

def node_expected_transition_fields(
    conn: sqlite3.Connection, node: Any, prior: dict, current: dict, changed: list[str]
) -> set[str]:
    """Design 3.17, "the first v3 transition is expected, not a change". Which
    of the changed identity fields the recorded carrier transition accepts.

    The job writes winn3_expected_transition_json in the generation-checked
    transaction of the carrier flip: the generation and the exact post-flip
    protocol_version, carrier_classes, path_mtu and winn3_identity_sha256. A
    difference in exactly those four fields is accepted when the current values
    equal the recorded ones and the recorded generation is the slug's current
    deployment_generation. A change of winn3_identity_sha256 is accepted only
    from "" (the first identity) and only when a verified t1 ticket of action
    new or reset authorised it; every other change keeps its name and holds
    the node."""
    moved = [field for field in changed if field in NODE_RERUN_TRANSITION_FIELDS]
    if not moved:
        return set()
    data = dict(node)
    try:
        recorded = json.loads(data.get("winn3_expected_transition_json") or "")
    except (TypeError, ValueError):
        return set()
    if not isinstance(recorded, dict) or set(recorded) != set(NODE_RERUN_TRANSITION_FIELDS) | {"generation"}:
        return set()
    generation = data.get("deployment_generation")
    if type(recorded["generation"]) is not int or type(generation) is not int \
            or recorded["generation"] != generation:
        return set()
    for field in NODE_RERUN_TRANSITION_FIELDS:
        wanted, actual = recorded.get(field), current.get(field)
        if ("" if wanted is None else str(wanted)) != ("" if actual is None else str(actual)):
            return set()
    accepted = set(moved)
    if "winn3_identity_sha256" in moved:
        ticket, _reason = winn3_golive_ticket(conn, str(data.get("slug") or ""))
        if str(prior.get("winn3_identity_sha256") or "") != "" or ticket is None:
            accepted.discard("winn3_identity_sha256")
    return accepted

def installer_rerun_reopen_eligibility(
    conn: sqlite3.Connection, node: Any, prior: dict
) -> tuple[list[str], str]:
    """Ruling B: the reasons a completed rerun may NOT be reopened by the hub,
    and the lineage rule that proved its revision ("" when none did). Empty
    reasons means eligible. Re-run at reopen time against the row as it then
    stands (D.iii)."""
    data = dict(node)
    reasons: list[str] = []
    if not prior:
        return ["no withdrawal snapshot was recorded for this deployment"], ""
    if int(prior.get("operator_enabled") or 0) != 1:
        reasons.append("prior operator_enabled != 1 (the node was not live when withdrawn)")
    if str(prior.get("node_token_hash") or "") != str(data.get("node_token_hash") or ""):
        reasons.append("node token changed since the withdrawal (re-bootstrapped)")
    current = node_deployment_prior_state(data, str(prior.get("withdrawn_at") or ""))
    changed = [
        field for field in NODE_RERUN_IDENTITY_FIELDS
        if ("" if prior.get(field) is None else str(prior.get(field)))
        != ("" if current.get(field) is None else str(current.get(field)))
    ]
    # H7 (3.17): the four fields the carrier flip itself changes are accepted
    # against the transition the job recorded, and only then.
    expected = node_expected_transition_fields(conn, data, prior, current, changed)
    for field in changed:
        if field not in expected:
            reasons.append(f"identity changed: {field}")
    # Ruling B.4: a full registration (identity and revision), not a
    # status-only heartbeat, after the withdrawal, and the node online now.
    if str(data.get("status") or "").strip().lower() != "online" or not _iso_after(
            data.get("last_online_registered_at"), prior.get("withdrawn_at")):
        reasons.append("no online registration since the withdrawal")
    revision = str(data.get("data_plane_code_revision") or "").strip().lower()
    rule = ""
    if not NODE_RERUN_REVISION_RE.fullmatch(revision):
        reasons.append(f"installer revision is not provable ({revision or 'none'})")
    elif WINS_EXPECTED_DATA_PLANE_REVISION:
        if revision == WINS_EXPECTED_DATA_PLANE_REVISION:
            rule = "expected_revision"
        else:
            reasons.append("installer revision differs from WINS_EXPECTED_DATA_PLANE_REVISION")
    elif revision == str(prior.get("data_plane_code_revision") or "").strip().lower():
        rule = "same_revision"
    elif conn.execute(
        "SELECT 1 FROM node_promotion_events WHERE data_plane_code_revision = ? "
        "AND tier IN ('free', 'premium') AND operator_source_hash GLOB ? "
        "AND operator_source_hash NOT IN (" + ", ".join("?" for _ in AUTOMATIC_PROMOTION_SOURCES) + ") "
        "LIMIT 1",
        (revision, MANUAL_PROMOTION_SOURCE_GLOB, *AUTOMATIC_PROMOTION_SOURCES),
    ).fetchone() is not None:
        # Only an operator's evidenced promotion counts: a positive match on the
        # 16 hex characters security_event_hash writes (H7, design 3.17), so a
        # hub reopen or go-live never evidences a revision for the next one.
        rule = "evidenced_revision"
    else:
        reasons.append("installer revision was never evidenced by a manual promotion")
    return reasons, rule

def _carry_proof_fresh(value: Any) -> bool:
    """H5: a carrying proof is read only while it is younger than
    AWG_CARRY_PROOF_MAX_AGE_SECONDS. An unreadable time is not fresh."""
    taken = parse_iso_datetime(value if isinstance(value, str) else None)
    return taken is not None and (utcnow() - taken).total_seconds() <= AWG_CARRY_PROOF_MAX_AGE_SECONDS

def installer_rerun_carry_failures(node: Any) -> list[str]:
    """Ruling D.i: carrying proof newer than the completion on every advertised
    transport, and for winn/3 a per-slug v3 canary. The AWG carrying canary is
    written by wins_node_dataplane_probe.py --carry (H5); a row whose carry
    columns are absent still fails closed by name."""
    data = dict(node)
    completed = data.get("deployment_completed_at")
    failures: list[str] = []
    plan = node_promotion_transport_plan(data)
    direct = data.get("direct_awg_enabled")
    try:
        direct_awg = direct is None or int(str(direct).strip()) != 0
    except (TypeError, ValueError):
        direct_awg = True
    for name, column in NODE_RERUN_AWG_CARRY_COLUMNS:
        advertised = direct_awg if name == "udp" else plan.get(name) is not None
        if not advertised:
            continue
        if f"{column}_status" not in data:
            failures.append(f"{name}: awg carrying canary not available")
            continue
        status = str(data.get(f"{column}_status") or "unknown").strip().lower()
        if status != "ok" or not _iso_after(data.get(f"{column}_ok_at"), completed):
            failures.append(f"{name}: no carrying proof newer than the rerun completion ({status})")
        elif not _carry_proof_fresh(data.get(f"{column}_ok_at")):
            failures.append(
                f"{name}: carrying proof is older than {AWG_CARRY_PROOF_MAX_AGE_SECONDS} s "
                "(the carrying probe is not refreshing it)")
    if str(data.get("protocol_version") or "").strip().lower() == "winn/3":
        status = str(data.get("winn3_canary_status") or "unknown").strip().lower()
        if status != "ok" or not _iso_after(data.get("winn3_canary_ok_at"), completed):
            failures.append(
                "winn/3: no per-slug v3 canary newer than the rerun completion "
                f"(status {status}; needs the SYNC-03 per-node canary)")
    return failures

# --- H6 (design 2.9, 3.16): the hub-run off-node gate, ruling D.ii -----------
#
# When every other reopen condition passes and no unused gate record exists,
# the hub runs the node-side check itself over node_ssh_command, evaluates the
# report with offnode_node_report_failures() (the rules of POST
# /admin/nodes/offnode-gate, plus the one AWGSYSPEER rule), recomputes the v3
# snapshot digest and the canonical gate digest exactly as that route does, and
# records the row with source='hub'. Only a node closed as installer_rerun or
# fresh_install may use such a row (verify_offnode_gate_for_use); manual
# promotion and retirement still accept operator records only.
HUB_OFFNODE_CHECK_PATH = "/usr/local/libexec/winsvpn/wins-offnode-check"
# SHA-256 of the installed node-side check: the L46 v5 script with the one
# canary exemption (design 2.9). The data-plane installer pins the same value
# (WINN3_OFFNODE_CHECK_SHA256); the two change together, and the hub refuses a
# node whose installed file differs.
HUB_OFFNODE_CHECK_SHA256 = "19dfd36a1a65551416d51d9b669e5b318f7fdc84387765205741c596b2f79e34"
HUB_OFFNODE_CHECK_TIMEOUT_SECONDS = 90
# Where the remote command makes its private working directory on the node.
HUB_OFFNODE_CHECK_WORKDIR = "/run"
# A failed or refused hub-run check is not repeated for this long (per slug,
# process memory), so a broken node is not hit over SSH on every sweep.
HUB_OFFNODE_GATE_RETRY_SECONDS = 60
# H6-PERF: one auto_reopen_health_closed_nodes() call starts at most this many
# hub-run checks, and starts no new one once the checks so far have taken this
# long; the nodes left over wait for the next sweep, so N failing nodes cannot
# hold the sweep thread for N x HUB_OFFNODE_CHECK_TIMEOUT_SECONDS. The seconds
# value is a threshold for starting another check, not a hard limit: two checks
# that each run to the timeout spend about 2 x HUB_OFFNODE_CHECK_TIMEOUT_SECONDS.
HUB_OFFNODE_SWEEP_MAX_CHECKS = 2
HUB_OFFNODE_SWEEP_MAX_SECONDS = 120
# The check attempts (count, seconds) since auto_reopen_health_closed_nodes()
# last started; hub_offnode_gate_attempt() adds every call it makes to
# hub_offnode_check_run(), the sweep resets it. A call that refuses on the hub
# before SSH (no canary key, no host, node_ssh_command refusal) counts too, at
# about zero seconds; precondition refusals and throttled nodes count nothing.
_HUB_OFFNODE_SWEEP_BUDGET: dict[str, Any] = {"checks": 0, "seconds": 0.0}
HUB_OFFNODE_GATE_CLOSURE_REASONS = ("installer_rerun", "fresh_install")
HUB_OFFNODE_CHECK_EXIT_DIGEST = 97
HUB_OFFNODE_CHECK_EXIT_MISSING = 98
HUB_OFFNODE_CHECK_EXIT_WORKDIR = 99
# A closed node whose ONLY gate failure is timing: the hub published the
# registry after the gateway started and nothing restarts it, so "started after
# the file's last change" stays no. The report has just proved the node holds no
# customer peer and only the hub's own snapshot, so the hub restarts the gateway
# once, the way the node's own wins_serving_start starts serving: under
# /run/lock/wins-serving-activation.lock and in a wins-serving-activation-*.scope,
# which the late-failure handlers synchronize on and stop, through the serving
# activator (which refuses under a late-failure hold). The next check follows
# after HUB_OFFNODE_GATE_RETRY_SECONDS.
#
# R25 R2-G2: the check and the restart are two SSH round trips and the hub's
# write lock is released for each, so the node can be reopened and its customers
# published in between. The restart is therefore bound to the snapshot the check
# found: the command takes the registry publication lock (/etc/winn/.winn3-peers.lock,
# the one every registry publisher takes) and holds it through the activator,
# and refuses with exit 76 unless the node's registry file is still exactly the
# closed snapshot whose SHA-256 the hub appends as the one argument. A customer
# publication either lands before the check (the digest differs, nothing is
# restarted) or waits for the restart to end.
HUB_OFFNODE_STARTED_AFTER_FAILURE = "gateway started after the file's last change: no"
HUB_OFFNODE_GATEWAY_RESTART_COMMAND = (
    "install -d -m 755 /run/lock; exec 6>/run/lock/wins-serving-activation.lock; "
    "flock -w 20 6 || exit 75; "
    "timeout -k 5 100 systemd-run --scope --quiet --collect "
    "--unit=wins-serving-activation-hub-offnode-$$ "
    "--property=RuntimeMaxSec=100 --property=TimeoutStopSec=5 "
    "sh -c 'set -eu; "
    "exec 9>>/etc/winn/.winn3-peers.lock; flock -w 10 9 || exit 75; "
    "[ -f /etc/winn/winn3-peers.json ] && [ ! -L /etc/winn/winn3-peers.json ] || exit 76; "
    "actual=$(sha256sum /etc/winn/winn3-peers.json); actual=${actual%% *}; "
    '[ "$actual" = "$1" ] || exit 76; '
    "exec /usr/local/libexec/winsvpn/wins-serving-activate "
    "systemctl restart winn3-gateway.service' wins-hub-offnode "
)
# 20 s for the lock, up to 105 s for the restart, and margin.
HUB_OFFNODE_GATEWAY_RESTART_TIMEOUT_SECONDS = 140
HUB_OFFNODE_GATEWAY_RESTART_LATE_HOLD_EXIT = 3
HUB_OFFNODE_GATEWAY_RESTART_LOCK_EXIT = 75
HUB_OFFNODE_GATEWAY_RESTART_CHANGED_EXIT = 76
# Node row fields that must not move while the check runs outside the database
# transaction. deployment_generation is read only if the column exists.
HUB_OFFNODE_GATE_STABLE_FIELDS = (
    "operator_enabled", "retired_at", "deployment_withdrawal_id", "health_closed_at",
    "health_closed_reason", "deployment_completed_at", "deployment_generation",
    "ssh_host", "endpoint", "protocol_version",
)
_HUB_OFFNODE_GATE_LAST: dict[str, tuple[float, list[str]]] = {}

def hub_offnode_check_remote_command(canary_public_key: str) -> str:
    """The one remote command. It copies the installed check to a private
    directory, compares the copy with the pinned digest and runs that same
    copy, so the bytes that were verified are the bytes that run. The canary
    key is passed always (design 3.16); its alphabet is checked here, so
    nothing but base64 reaches the remote shell."""
    if not re.fullmatch(r"[A-Za-z0-9+/]{43}=", str(canary_public_key or "")):
        raise ValueError("the hub canary public key is not a 32-byte base64 key")
    return (
        f"f={shlex.quote(HUB_OFFNODE_CHECK_PATH)}; "
        f"d=$(mktemp -d {shlex.quote(HUB_OFFNODE_CHECK_WORKDIR)}/wins-offnode.XXXXXX) "
        f"|| exit {HUB_OFFNODE_CHECK_EXIT_WORKDIR}; "
        "trap 'rm -rf -- \"$d\"' EXIT; "
        f'[ -f "$f" ] && [ ! -L "$f" ] || exit {HUB_OFFNODE_CHECK_EXIT_MISSING}; '
        f'cp -- "$f" "$d/check" || exit {HUB_OFFNODE_CHECK_EXIT_MISSING}; '
        f'[ "$(sha256sum "$d/check" | cut -d" " -f1)" = {HUB_OFFNODE_CHECK_SHA256} ] '
        f"|| exit {HUB_OFFNODE_CHECK_EXIT_DIGEST}; "
        f'bash "$d/check" --canary-pubkey {canary_public_key}'
    )

def hub_offnode_check_run(node_host: str) -> tuple[Optional[str], list[str]]:
    """Run the node-side check once. Returns (report, []) when it ran and
    exited 0, else (None, reasons). Nothing here touches the database."""
    host = str(node_host or "").strip()
    if not AWG_CANARY_PUBLIC_KEY:
        return None, ["no hub AWG canary public key is configured (AWG_CANARY_PUBLIC_KEY)"]
    if not host:
        return None, ["the node has no management host"]
    try:
        command = node_ssh_command(
            host, hub_offnode_check_remote_command(AWG_CANARY_PUBLIC_KEY), connect_timeout=5)
        # H0 (D3): node_ssh_command refuses this hub by name.
        result = run_management_ssh_bounded(
            command, timeout=HUB_OFFNODE_CHECK_TIMEOUT_SECONDS, check=False, stdin=subprocess.DEVNULL,
            max_stdout=OFFNODE_GATE_REPORT_MAX_BYTES,
            capture_output=True, text=True, errors="replace", env=management_ssh_env())
    except subprocess.TimeoutExpired:
        return None, [f"the node-side check did not finish within {HUB_OFFNODE_CHECK_TIMEOUT_SECONDS} s"]
    except Exception as exc:  # fail closed: the sweep must survive any single node
        return None, [f"the node-side check could not be started: {type(exc).__name__}: {exc}"]
    if result.returncode != 0:
        logger.warning("Off-node check failed on %s (exit %s): %s", mask_id(host), result.returncode,
                       (result.stderr or "").strip()[-200:])
    if result.returncode == HUB_OFFNODE_CHECK_EXIT_DIGEST:
        return None, ["the installed node-side check does not match the pinned digest"]
    if result.returncode == HUB_OFFNODE_CHECK_EXIT_MISSING:
        return None, ["the node-side check is not installed"]
    if result.returncode == HUB_OFFNODE_CHECK_EXIT_WORKDIR:
        return None, ["the node could not make a private working directory for the check"]
    if result.returncode == 255:
        return None, ["management SSH to the node failed"]
    if result.returncode != 0:
        return None, [f"the node-side check exited {result.returncode} (some runtime state was unreadable)"]
    report = result.stdout or ""
    raw = report.encode("utf-8")
    if not raw.strip() or len(raw) > OFFNODE_GATE_REPORT_MAX_BYTES:
        return None, ["the node-side report is empty or too large"]
    return report, []

def hub_offnode_gateway_restart(node_host: str, registry_sha256: str) -> str:
    """Restart a closed node's winn3 gateway once, only while its registry is
    still the closed snapshot registry_sha256 names. "" when it was restarted,
    else the reason it was not. Nothing here touches the database."""
    host = str(node_host or "").strip()
    if not host:
        return "the node has no management host"
    if not re.fullmatch(r"[0-9a-f]{64}", str(registry_sha256 or "")):
        return "the checked registry digest is unavailable, so the gateway was not restarted"
    try:
        command = node_ssh_command(
            host, HUB_OFFNODE_GATEWAY_RESTART_COMMAND + shlex.quote(registry_sha256), connect_timeout=5)
        # H0 (D3): node_ssh_command refuses this hub by name.
        result = run_management_ssh_bounded(
            command, timeout=HUB_OFFNODE_GATEWAY_RESTART_TIMEOUT_SECONDS, check=False,
            stdin=subprocess.DEVNULL, max_stdout=4096, env=management_ssh_env(),
            capture_output=True, text=True, errors="replace")
    except subprocess.TimeoutExpired:
        return "the gateway restart did not finish in time"
    except Exception as exc:  # fail closed: one refused node never stops the sweep
        return f"the gateway restart could not be started: {type(exc).__name__}"
    if result.returncode == HUB_OFFNODE_GATEWAY_RESTART_LATE_HOLD_EXIT:
        return "the node holds serving back after a late failure, so the gateway was not restarted"
    if result.returncode == HUB_OFFNODE_GATEWAY_RESTART_LOCK_EXIT:
        return "the node's serving activation lock or registry publication lock stayed busy, so the gateway was not restarted"
    if result.returncode == HUB_OFFNODE_GATEWAY_RESTART_CHANGED_EXIT:
        return "the node's registry changed after the check, so the gateway was not restarted"
    if result.returncode != 0:
        logger.warning("Gateway restart failed on %s (exit %s): %s", mask_id(host), result.returncode,
                       (result.stderr or "").strip()[-200:])
        return f"the gateway restart exited {result.returncode}"
    logger.info("hub restarted the winn3 gateway on closed node %s", mask_id(host))
    return ""

def hub_offnode_gate_precondition_failures(conn: sqlite3.Connection, node: Any) -> list[str]:
    """What must hold before the hub spends an SSH check: the same closed,
    not retired and cleanup-confirmed conditions POST /admin/nodes/offnode-gate
    enforces, for a node closed as an installer rerun or a fresh install."""
    data = dict(node)
    slug = str(data.get("slug") or "")
    failures = []
    if str(data.get("health_closed_reason") or "") not in HUB_OFFNODE_GATE_CLOSURE_REASONS:
        failures.append("the node is not closed as an installer rerun or a fresh install")
    if node_admits_peer(data) or str(data.get("retired_at") or "").strip():
        failures.append("node latch is open or the node is retired")
    if str(data.get("deployment_withdrawal_id") or "").strip():
        failures.append("installer deployment withdrawal is active")
    cleanup = conn.execute("SELECT state FROM node_closure_cleanup WHERE slug = ?", (slug,)).fetchone()
    if cleanup is None or cleanup["state"] != "confirmed":
        failures.append("closure cleanup is not confirmed (resync the node first)")
    return failures

def hub_offnode_gate_record(
    conn: sqlite3.Connection, slug: str, report: str
) -> tuple[str, list[str]]:
    """Evaluate a node report and record it as a source='hub' gate, inside the
    caller's transaction, as POST /admin/nodes/offnode-gate does. Returns
    (gate_sha256, []) or ("", reasons); nothing stays recorded on a refusal."""
    node = conn.execute("SELECT * FROM nodes WHERE slug = ?", (slug,)).fetchone()
    if node is None:
        return "", ["node not found"]
    failures = hub_offnode_gate_precondition_failures(conn, node)
    cleanup = conn.execute("SELECT * FROM node_closure_cleanup WHERE slug = ?", (slug,)).fetchone()
    try:
        expected = offnode_expected_v3_sha256(conn, slug)
    except Exception:
        expected = ""
        failures.append("the node's v3 snapshot cannot be computed")
    failures += offnode_node_report_failures(report, node["protocol_version"], expected)
    if failures:
        return "", failures
    confirmed_at = str(cleanup["confirmed_at"] or "")
    report_sha = hashlib.sha256(report.encode("utf-8")).hexdigest()
    digest = offnode_gate_digest(slug, expected, confirmed_at, "", report_sha)
    # No INSERT OR REPLACE: an identical report under an identical confirmation
    # hashes to a digest that may already be used, and a used record must not
    # become usable again.
    conn.execute(
        "INSERT OR IGNORE INTO node_offnode_gates (gate_sha256, slug, recorded_at, cleanup_confirmed_at,"
        " expected_v3_sha256, external_evidence_sha256, node_report, node_report_sha256, used_at, used_for,"
        " source) VALUES (?, ?, ?, ?, ?, '', ?, ?, NULL, NULL, 'hub')",
        (digest, slug, utcnow().isoformat(), confirmed_at, expected, report, report_sha),
    )
    stored = conn.execute(
        "SELECT source, used_at FROM node_offnode_gates WHERE gate_sha256 = ? AND slug = ?",
        (digest, slug),
    ).fetchone()
    if stored is None or stored["source"] != "hub" or stored["used_at"]:
        return "", ["an identical gate record exists and is not an unused hub record"]
    verify = verify_offnode_gate_for_use(conn, slug, digest, allow_hub_source=True)
    if verify:
        conn.execute(
            "DELETE FROM node_offnode_gates WHERE gate_sha256 = ? AND slug = ? "
            "AND source = 'hub' AND used_at IS NULL", (digest, slug))
        return "", verify
    return digest, []

def hub_offnode_gate_attempt(conn: sqlite3.Connection, node: Any) -> tuple[str, list[str]]:
    """One hub-run gate build for a closed node (design 3.16). Returns
    (gate_sha256, []) when a source='hub' record was written, else ("", reasons).

    The node check runs on SSH, so the caller's write transaction is released
    for its duration and a new one is begun before this returns; the row is
    then re-read, and a node that changed meanwhile gets no record. Every call
    this makes to hub_offnode_check_run is counted in _HUB_OFFNODE_SWEEP_BUDGET."""
    data = dict(node)
    slug = str(data.get("slug") or "")
    reasons = hub_offnode_gate_precondition_failures(conn, data)
    if reasons:
        return "", reasons
    last = _HUB_OFFNODE_GATE_LAST.get(slug)
    if last is not None and time.monotonic() - last[0] < HUB_OFFNODE_GATE_RETRY_SECONDS:
        return "", list(last[1])
    host = str(data.get("ssh_host") or "").strip() or extract_node_host(str(data.get("endpoint") or ""))
    conn.commit()
    started = time.monotonic()
    try:
        report, reasons = hub_offnode_check_run(host)
    finally:
        _HUB_OFFNODE_SWEEP_BUDGET["checks"] += 1
        _HUB_OFFNODE_SWEEP_BUDGET["seconds"] += time.monotonic() - started
        conn.execute("BEGIN IMMEDIATE")
    fresh = conn.execute("SELECT * FROM nodes WHERE slug = ?", (slug,)).fetchone()
    if fresh is None:
        return "", ["node not found"]
    moved = [k for k in HUB_OFFNODE_GATE_STABLE_FIELDS
             if str(dict(fresh).get(k) or "") != str(data.get(k) or "")]
    gate = ""
    restart = False
    if report is not None and moved:
        reasons = ["the node changed while the check ran (" + ", ".join(moved) + ")"]
    elif report is not None:
        gate, reasons = hub_offnode_gate_record(conn, slug, report)
        restart = not gate and reasons == [HUB_OFFNODE_STARTED_AFTER_FAILURE]
    if gate:
        _HUB_OFFNODE_GATE_LAST.pop(slug, None)
        logger.info("hub-run off-node gate recorded for node %s (gate %s)", slug, gate[:16])
        return gate, []
    if restart:
        # Nothing stays recorded on a refusal, so the lock is released for the
        # restart's SSH round trip as it was for the check. The snapshot the
        # check just matched goes with it (R25 R2-G2): the node refuses to
        # restart once its registry is anything else.
        try:
            registry_sha256 = offnode_expected_v3_sha256(conn, slug)
        except Exception:
            registry_sha256 = ""
        conn.commit()
        began = time.monotonic()
        try:
            problem = hub_offnode_gateway_restart(host, registry_sha256)
        finally:
            _HUB_OFFNODE_SWEEP_BUDGET["seconds"] += time.monotonic() - began
            conn.execute("BEGIN IMMEDIATE")
        reasons = [HUB_OFFNODE_STARTED_AFTER_FAILURE + "; " + (
            problem or f"the hub restarted the gateway, the next check follows in {int(HUB_OFFNODE_GATE_RETRY_SECONDS)} s")]
    reasons = ["hub-run check: " + reason for reason in reasons]
    _HUB_OFFNODE_GATE_LAST[slug] = (time.monotonic(), list(reasons))
    logger.warning("hub-run off-node gate held node %s: %s", slug, "; ".join(reasons))
    return "", reasons

def installer_rerun_hub_offnode_gate(conn: sqlite3.Connection, node: Any) -> str:
    """Ruling D.ii (design 3.16): the gate digest of a freshly recorded
    source='hub' row, or "" when the hub-run check did not pass (the reasons
    come from hub_offnode_gate_attempt, which the reopen sweep calls)."""
    return hub_offnode_gate_attempt(conn, node)[0]

def installer_rerun_reopen_failures(conn: sqlite3.Connection, node: Any) -> list[str]:
    """What an installer_rerun closure needs beyond node_auto_reopen_failures()."""
    data = dict(node)
    failures: list[str] = []
    if not str(data.get("deployment_completed_at") or "").strip():
        failures.append("no recorded rerun completion")
    reasons, _rule = installer_rerun_reopen_eligibility(conn, data, node_deployment_prior(data))
    failures += ["eligibility: " + reason for reason in reasons]
    failures += installer_rerun_carry_failures(data)
    return failures

def installer_rerun_window_expired(node: Any) -> bool:
    completed = parse_iso_datetime(str(dict(node).get("deployment_completed_at") or "") or None)
    if completed is None:
        return True
    return (utcnow() - completed).total_seconds() > NODE_INSTALLER_RERUN_REOPEN_WINDOW_SECONDS

# --- H7 (design v17 3.17): automatic go-live, the fresh_install class --------
#
# A fresh install has no withdrawal, so it never reaches the rerun completion
# route. POST /api/v1/nodes/{slug}/deployment/complete-fresh is its completion,
# and the rerun route (complete_node_deployment) classifies a never-live node
# the same way. Either records health_closed_reason='fresh_install' ONLY when
# the node's own signed t1 ticket carries go_live=auto and the hub switch
# WINN3_FRESH_INSTALL_AUTO_GOLIVE is on. The ticket is read at use: the stored
# bytes are re-verified against WINN3_SIGNER_TICKET_PUBKEY_T1 and the ticket
# domain, and go_live and tier come from those verified bytes, never from a
# column (winn3_golive_ticket). The same re-verification runs again at the
# go-live flip, so a ticket altered after signing leaves the plain closure and
# can never change the final tier. Neither completion route opens
# operator_enabled; only auto_reopen_health_closed_nodes does, after every proof.
WINN3_GOLIVE_TICKET_ACTIONS = ("new", "reset")
NODE_BOOTSTRAP_EPOCH_ZERO = "0001-01-01T00:00:00"
# winn3_identity_digest (and WINN3_IDENTITY_DIGEST_FIELDS, winn3_canonical)
# is the job slice's (H2) definition further down; this slice reads it.

def winn3_golive_ticket(
    conn: sqlite3.Connection, slug: str, actions: tuple = WINN3_GOLIVE_TICKET_ACTIONS
) -> tuple[Optional[dict], str]:
    """Design 3.17 ticket authority. The newest stored t1 ticket of the slug
    whose action is in `actions`, re-verified now: t1 signature under the
    ticket domain, canonical form, closed field set, enums and lifetime. Returns
    (the decoded fields, "") or (None, reason). A ticket that fails any check,
    including one whose stored bytes were altered after signing, authorises
    nothing, and there is no fallback to an older ticket. The action column and
    posted_at only choose WHICH ticket; the action, go_live and tier that are
    used come from the verified bytes."""
    marks = ", ".join("?" for _ in actions)
    row = conn.execute(
        "SELECT payload, sig FROM winn3_signer_tickets WHERE slug = ? AND action IN (" + marks + ") "
        "ORDER BY posted_at DESC, nonce DESC LIMIT 1",
        (slug, *actions),
    ).fetchone()
    if row is None:
        return None, "no-stored-ticket"
    try:
        payload = base64.b64decode(row["payload"], validate=True)
        signature = base64.b64decode(row["sig"], validate=True)
        winn3_verify_signer_ticket_signature(payload, signature)
        ticket = winn3_decode_signer_ticket(payload, slug=slug)
    except Winn3ContractError as exc:
        return None, exc.reason
    except Exception:
        return None, "signer-ticket-unverifiable"
    if ticket["action"] not in actions:
        return None, "signer-ticket-action"
    return ticket, ""

def node_bootstrap_epoch(node: Any) -> str:
    """COALESCE(node_bootstrapped_at, '0001-01-01T00:00:00'): the epoch
    "since bootstrap" is counted from. A row written by an older code path has
    no value and is read as the zero epoch, so its promotions still count."""
    return str(dict(node).get("node_bootstrapped_at") or "").strip() or NODE_BOOTSTRAP_EPOCH_ZERO

def node_promoted_since_bootstrap(conn: sqlite3.Connection, slug: str, epoch: str) -> bool:
    return conn.execute(
        "SELECT 1 FROM node_promotion_events WHERE slug = ? AND promoted_at >= ? LIMIT 1",
        (slug, epoch),
    ).fetchone() is not None

def node_never_live_since_bootstrap(conn: sqlite3.Connection, node: Any) -> bool:
    """Design 3.17: operator_enabled is 0, no deployment withdrawal is open, and
    no node_promotion_events row for the slug is at or after the node's latest
    bootstrap. The immutable promotion history is never rewritten; only events
    since the latest bootstrap count."""
    data = dict(node)
    return (
        int(data.get("operator_enabled") or 0) == 0
        and not str(data.get("deployment_withdrawal_id") or "").strip()
        and not node_promoted_since_bootstrap(
            conn, str(data.get("slug") or ""), node_bootstrap_epoch(data))
    )

def fresh_install_authority(conn: sqlite3.Connection, node: Any) -> tuple[Optional[dict], list[str]]:
    """Whether a completion of this node is a fresh_install go-live candidate:
    (the verified ticket, []) or (None, reasons). Both completion routes and
    the go-live flip use this one function."""
    slug = str(dict(node).get("slug") or "")
    if not WINN3_FRESH_INSTALL_AUTO_GOLIVE:
        return None, ["fresh install automatic go-live is off (WINN3_FRESH_INSTALL_AUTO_GOLIVE=0)"]
    ticket, reason = winn3_golive_ticket(conn, slug)
    if ticket is None:
        return None, [f"no verified go-live ticket ({reason})"]
    if ticket["go_live"] != "auto":
        return None, ["the go-live ticket carries go_live=manual"]
    return ticket, []

def fresh_completion_reset_failures(
    conn: sqlite3.Connection, node: Any
) -> tuple[list[str], Optional[str]]:
    """Design 3.17 "reset authority" for complete-fresh. If any promotion row of
    the slug predates its latest bootstrap (the slug was live before this
    bootstrap), the completion needs a stored t1 ticket of action reset that
    verifies now, is unexpired and has not been used by an earlier epoch's
    completion. Returns (failures, the reset ticket's nonce).

    H7-TICKET (Turn 2 ruling, the hub-side check; design 3.17 "covers the
    Singapore reset and the 3.9 step 4 provider-rebuild default"): the signer
    consumes the nonce later, at sign, and sign is refused until this
    completion has set deployment_released_at (design 3.5 step 3, 3.17), so a
    nonce the signer has already spent can only come from an earlier epoch;
    that is what node_fresh_completions records and what the hub checks. The
    signer's ledger stays the authority on consumption and refuses a spent
    nonce at sign ("ticket-already-spent"), so a spent reset ticket yields no
    descriptor, and the go-live canary must be bound to the current verified
    descriptor's sequence after the carrier flip. The rerun route applies the
    same function before it classes a reset slug fresh_install."""
    data = dict(node)
    slug = str(data.get("slug") or "")
    epoch = node_bootstrap_epoch(data)
    if conn.execute(
        "SELECT 1 FROM node_promotion_events WHERE slug = ? AND promoted_at < ? LIMIT 1",
        (slug, epoch),
    ).fetchone() is None:
        return [], None
    ticket, reason = winn3_golive_ticket(conn, slug, actions=("reset",))
    if ticket is None:
        return [f"this slug was live before its latest bootstrap and needs a verified, "
                f"unexpired t1 reset ticket ({reason})"], None
    if conn.execute(
        "SELECT 1 FROM node_fresh_completions WHERE slug = ? AND ticket_nonce = ? AND epoch != ? LIMIT 1",
        (slug, ticket["nonce"], epoch),
    ).fetchone() is not None:
        return ["the t1 reset ticket was already used by an earlier completion"], ticket["nonce"]
    return [], ticket["nonce"]

def fresh_install_carry_binding_failures(node: Any) -> list[str]:
    """The post-flip per-slug v3 canary must be bound to this identity digest,
    this deployment generation and the sequence of the current verified
    descriptor, and must be newer than the carrier flip (design 3.1 step 4,
    3.11, 3.17): a stale success, a pre-flip (pre-sign or prospective) proof,
    or a proof of an older descriptor cannot vouch for the node now. H7 fix
    (Sol T1 item 1)."""
    data = dict(node)
    failures: list[str] = []
    identity = str(data.get("winn3_identity_sha256") or "")
    if not identity:
        failures.append("winn/3: no recorded identity digest to bind the v3 canary to")
    elif str(data.get("winn3_canary_identity_sha256") or "") != identity:
        failures.append("winn/3: the per-slug v3 canary result is bound to another identity")
    generation = data.get("deployment_generation")
    canary_generation = data.get("winn3_canary_generation")
    if type(generation) is not int or type(canary_generation) is not int \
            or canary_generation != generation:
        failures.append("winn/3: the per-slug v3 canary result is bound to another deployment generation")
    try:
        descriptor = winn3_stored_descriptor(data)
    except Exception:
        descriptor = {}
    canary_seq = data.get("winn3_canary_seq")
    # winn3_stored_descriptor returns {} (not None) when nothing verifies.
    if not descriptor or type(canary_seq) is not int \
            or canary_seq != descriptor.get("seq"):
        failures.append("winn/3: the per-slug v3 canary result is not bound to the current verified descriptor")
    if not _iso_after(
            data.get("winn3_canary_ok_at"), data.get("winn3_carrier_flipped_at")):
        failures.append("winn/3: no per-slug v3 canary newer than the carrier flip")
    if not winn3_canary_is_fresh(data):
        failures.append("winn/3: the per-slug v3 canary is absent, stale or incorrectly bound")
    return list(dict.fromkeys(failures))

def fresh_install_existing_gate(conn: sqlite3.Connection, slug: str) -> str:
    """H6's record rule (design 3.16), applied to the fresh branch at the H7
    rebase (H7-QUESTIONS (3)): the newest unused, unexpired gate record, except
    that an unused source='hub' record that no longer verifies counts as
    absent, so the hub may build again. An operator record is never replaced
    by a hub-run check."""
    record = node_auto_reopen_gate_record(conn, slug)
    if record:
        stored = conn.execute(
            "SELECT source FROM node_offnode_gates WHERE gate_sha256 = ?", (record,)
        ).fetchone()
        if stored is not None and stored["source"] == "hub" \
                and verify_offnode_gate_for_use(conn, slug, record, allow_hub_source=True):
            return ""
    return record

def fresh_install_check_budget_spent() -> bool:
    """H6-PERF's per-sweep limit on hub-run checks, as the installer_rerun
    branch applies it: no new check once this sweep's count or time is spent."""
    return (_HUB_OFFNODE_SWEEP_BUDGET["checks"] >= HUB_OFFNODE_SWEEP_MAX_CHECKS
            or _HUB_OFFNODE_SWEEP_BUDGET["seconds"] >= HUB_OFFNODE_SWEEP_MAX_SECONDS)

def fresh_install_reopen_failures(conn: sqlite3.Connection, node: Any) -> list[str]:
    """What a fresh_install closure needs beyond node_auto_reopen_failures()
    (which carries the full node_promotion_readiness_failures gate: online,
    management ok, every advertised transport ok and fresh, cleanup confirmed,
    the off-node gate): the recorded completion, the ticket re-verified now,
    the carrier open, carrying proof newer than the completion on every
    advertised transport, the v3 canary bound to identity and generation, and
    the operator hold clear. Re-run at flip time against the row as it then
    stands."""
    data = dict(node)
    slug = str(data.get("slug") or "")
    failures: list[str] = []
    if not WINN3_FRESH_INSTALL_AUTO_GOLIVE:
        failures.append("fresh install automatic go-live is off (WINN3_FRESH_INSTALL_AUTO_GOLIVE=0)")
    if not str(data.get("deployment_completed_at") or "").strip():
        failures.append("no recorded fresh install completion")
    if not str(data.get("deployment_released_at") or "").strip():
        failures.append("the hub never released this deployment")
    if int(data.get("winn3_operator_hold") or 0):
        failures.append("winn3 operator hold is active")
    if node_promoted_since_bootstrap(conn, slug, node_bootstrap_epoch(data)):
        failures.append("the node has been live since its bootstrap; manual promotion required")
    # Ticket authority is read at use (3.17): re-verified here, never cached.
    if WINN3_FRESH_INSTALL_AUTO_GOLIVE:
        ticket, reasons = fresh_install_authority(conn, data)
        if ticket is None:
            failures += ["go-live ticket: " + reason for reason in reasons]
    if str(data.get("protocol_version") or "").strip().lower() != "winn/3":
        failures.append("the carrier is not winn/3 (no v3 profile is served yet)")
    failures += installer_rerun_carry_failures(data)
    if str(data.get("winn3_canary_status") or "").strip().lower() == "ok":
        failures += fresh_install_carry_binding_failures(data)
    return list(dict.fromkeys(failures))

NODE_AUTO_REOPEN_NOTICE_SECONDS = max(
    600, int(os.getenv("NODE_AUTO_REOPEN_NOTICE_SECONDS", "21600") or 21600))

def node_auto_reopen_gate_notice_due(
    conn: sqlite3.Connection, slug: str, closed_at: str
) -> bool:
    """One notice per closure, repeated at most every NODE_AUTO_REOPEN_NOTICE_SECONDS,
    that a node is ready except for its off-node gate. Recorded in the caller's
    transaction so restarts do not repeat it."""
    now_iso = utcnow().isoformat()
    row = conn.execute(
        "SELECT health_closed_at, noticed_at FROM node_auto_reopen_notices WHERE slug = ?",
        (slug,),
    ).fetchone()
    cutoff = (utcnow() - timedelta(seconds=NODE_AUTO_REOPEN_NOTICE_SECONDS)).isoformat()
    if row is not None and str(row["health_closed_at"] or "") == closed_at \
            and str(row["noticed_at"] or "") >= cutoff:
        return False
    conn.execute(
        "INSERT INTO node_auto_reopen_notices (slug, health_closed_at, noticed_at) VALUES (?, ?, ?) "
        "ON CONFLICT(slug) DO UPDATE SET health_closed_at = excluded.health_closed_at, "
        "noticed_at = excluded.noticed_at",
        (slug, closed_at, now_iso),
    )
    return True

def auto_reopen_health_closed_nodes(only_slug: Optional[str] = None) -> dict:
    """The fleet pass the audit loop runs every FLEET_AVAILABILITY_AUDIT_SECONDS.
    only_slug (design 10.3, P-13) narrows it to one node, with every condition
    and switch unchanged; it spends the current sweep's hub-run check budget
    and never resets it. The loop stays the backstop."""
    result: dict[str, Any] = {"enabled": NODE_AUTO_REOPEN_ENABLED, "reopened": [], "held": {},
                              "gate_notices": [],
                              "installer_rerun_enabled": NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED,
                              "installer_rerun_expired": [],
                              "fresh_install_enabled": WINN3_FRESH_INSTALL_AUTO_GOLIVE,
                              "fresh_install_expired": []}
    if not (NODE_AUTO_REOPEN_ENABLED or NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED
            or WINN3_FRESH_INSTALL_AUTO_GOLIVE):
        return result
    notices = []
    expired_alerts = []
    fresh_expired_alerts = []
    golive_alerts = []
    with get_db() as conn:
        ensure_schema(conn)
        slugs = [
            str(row["slug"]) for row in conn.execute(
                "SELECT slug FROM nodes WHERE COALESCE(operator_enabled, 0) = 0 "
                "AND health_closed_at IS NOT NULL AND retired_at IS NULL "
                "AND (? IS NULL OR slug = ?) "
                "ORDER BY slug",
                (only_slug, only_slug),
            ).fetchall()
        ]
    if only_slug is None:
        # H6-PERF: the check budget is the fleet sweep's. A one-slug pass
        # (P-13, the proof watch) spends from it and never resets it, so the
        # sweep's cap holds while the watch runs beside it, and the watch can
        # start no more hub-run checks per sweep than the sweep itself.
        _HUB_OFFNODE_SWEEP_BUDGET.update(checks=0, seconds=0.0)
    # H6-PERF: least recently attempted first (never-attempted, then oldest
    # failed check), so nodes whose check keeps failing cannot use up every
    # sweep's budget and starve a later slug until its rerun window expires.
    slugs.sort(
        key=lambda slug: (
            _HUB_OFFNODE_GATE_LAST.get(slug, (float("-inf"), []))[0],
            slug,
        )
    )
    for slug in slugs:
        with get_db() as conn:
            conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (slug,)).fetchone()
            if row is None:
                continue
            # IA-SYNC SYNC-08 (ruling C): each closure class under its own switch.
            rerun = str(row["health_closed_reason"] or "") == "installer_rerun"
            # H7 (design 3.17): the fresh_install class under its own switch,
            # and never judged as a health closure.
            fresh = str(row["health_closed_reason"] or "") == "fresh_install"
            if (rerun and not NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED) or \
                    (fresh and not WINN3_FRESH_INSTALL_AUTO_GOLIVE) or \
                    (not rerun and not fresh and not NODE_AUTO_REOPEN_ENABLED):
                continue
            armed_at = node_auto_reopen_arm(conn)
            failures = node_auto_reopen_failures(conn, row, armed_at)
            if rerun:
                failures += installer_rerun_reopen_failures(conn, row)
                # Ruling D.ii order: the hub builds its own gate only when every
                # other condition passes and no usable (unused, unexpired)
                # record exists, and not for a window that has already expired.
                # The check runs outside the write lock (H6); a failed check
                # holds the rerun with its reasons and raises the gate notice.
                existing_gate = node_auto_reopen_gate_record(conn, slug)
                if existing_gate:
                    held = conn.execute("SELECT source FROM node_offnode_gates WHERE gate_sha256 = ?", (existing_gate,)).fetchone()
                    if held is not None and held["source"] == "hub" and verify_offnode_gate_for_use(conn, slug, existing_gate, allow_hub_source=True):
                        existing_gate = ""   # a stale hub record counts as absent; an operator record is never replaced
                builder_due = not [f for f in failures if not f.startswith("offnode gate: ")] and \
                        not existing_gate and \
                        not installer_rerun_window_expired(row)
                if builder_due and (_HUB_OFFNODE_SWEEP_BUDGET["checks"] >= HUB_OFFNODE_SWEEP_MAX_CHECKS or
                                    _HUB_OFFNODE_SWEEP_BUDGET["seconds"] >= HUB_OFFNODE_SWEEP_MAX_SECONDS):
                    # H6-PERF: this sweep's SSH budget is spent; the node waits
                    # for the next sweep. Not a gate failure (no "offnode gate: "
                    # prefix), so it raises no notice.
                    failures.append("hub-run off-node check deferred to the next sweep (per-sweep check limit)")
                elif builder_due:
                    checked_node = dict(row)
                    gate, gate_reasons = hub_offnode_gate_attempt(conn, row)
                    # The write transaction was released for the SSH check, so
                    # the row and the recovery authorization are read again
                    # whether the check passed or not (H6 round 2).
                    row = conn.execute(
                        "SELECT * FROM nodes WHERE slug = ?", (slug,)
                    ).fetchone()
                    if row is None:
                        result["held"][slug] = [
                            "offnode gate: node disappeared while the hub-run check ran"
                        ]
                        continue
                    current_node = dict(row)
                    moved = [
                        field for field in HUB_OFFNODE_GATE_STABLE_FIELDS
                        if str(current_node.get(field) or "")
                        != str(checked_node.get(field) or "")
                    ]
                    if moved:
                        result["held"][slug] = [
                            "offnode gate: node changed while the hub-run check ran ("
                            + ", ".join(moved) + ")"
                        ]
                        continue
                    armed_at = node_auto_reopen_arm(conn)
                    failures = node_auto_reopen_failures(conn, row, armed_at)
                    failures += installer_rerun_reopen_failures(conn, row)
                    if not gate:
                        failures += [
                            "offnode gate: " + reason for reason in gate_reasons
                        ]
                if installer_rerun_window_expired(row):
                    # Ruling D.iv: eligibility never lingers. Convert to an
                    # operator closure; only a manual evidenced promotion opens it.
                    conn.execute(
                        "UPDATE nodes SET health_closed_at = NULL, health_closed_reason = NULL, "
                        "latch_cause = 'installer_rerun_expired' WHERE slug = ? "
                        "AND health_closed_reason = 'installer_rerun' "
                        "AND COALESCE(operator_enabled, 0) = 0",
                        (slug,),
                    )
                    result["installer_rerun_expired"].append(slug)
                    expired_alerts.append((slug, failures))
                    continue
            elif fresh:
                generation = row["deployment_generation"]
                failures += fresh_install_reopen_failures(conn, row)
                if installer_rerun_window_expired(row):
                    # Eligibility never lingers (the same window as a rerun):
                    # the closure becomes an operator closure, and only a
                    # manual evidenced promotion opens it.
                    conn.execute(
                        "UPDATE nodes SET health_closed_at = NULL, health_closed_reason = NULL, "
                        "latch_cause = 'fresh_install_expired' WHERE slug = ? "
                        "AND health_closed_reason = 'fresh_install' "
                        "AND COALESCE(operator_enabled, 0) = 0",
                        (slug,),
                    )
                    result["fresh_install_expired"].append(slug)
                    fresh_expired_alerts.append((slug, list(dict.fromkeys(failures))))
                    continue
                # Ruling D.ii order (design 3.16): the hub builds its own gate
                # only when every other condition passes and no usable record
                # exists (the window was checked above, so never for an expired
                # one). H7-QUESTIONS (3): H6's hub_offnode_gate_attempt under the
                # installer_rerun branch's rules: a stale hub record counts as
                # absent and an operator record is never replaced
                # (fresh_install_existing_gate), the per-sweep check budget
                # applies, and the check runs outside the write lock, so the row
                # is read again and must still be the node that was checked, at
                # the generation read above.
                fresh_gate_record = fresh_install_existing_gate(conn, slug)
                fresh_builder_due = not [f for f in failures if not f.startswith("offnode gate: ")] and \
                        not fresh_gate_record
                if fresh_builder_due and fresh_install_check_budget_spent():
                    # Not a gate failure (no "offnode gate: " prefix): no notice.
                    failures += ["hub-run off-node check deferred to the next sweep (per-sweep check limit)"]
                elif fresh_builder_due:
                    checked_node = dict(row)
                    gate, gate_reasons = hub_offnode_gate_attempt(conn, row)
                    row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (slug,)).fetchone()
                    if row is None or row["deployment_generation"] != generation:
                        result["held"][slug] = ["the deployment generation moved while the hub-run off-node gate ran"]
                        continue
                    changed_fields = [
                        field for field in HUB_OFFNODE_GATE_STABLE_FIELDS
                        if str(dict(row).get(field) or "") != str(checked_node.get(field) or "")
                    ]
                    if changed_fields:
                        result["held"][slug] = ["offnode gate: node changed while the hub-run check ran ("
                                                + ", ".join(changed_fields) + ")"]
                        continue
                    armed_at = node_auto_reopen_arm(conn)
                    failures = node_auto_reopen_failures(conn, row, armed_at)
                    failures += fresh_install_reopen_failures(conn, row)
                    if not gate:
                        failures += ["offnode gate: " + reason for reason in (gate_reasons or [
                            "the hub-run off-node gate produced no record; "
                            "an operator-posted gate record is required"])]
                failures = list(dict.fromkeys(failures))
            if failures:
                result["held"][slug] = failures
                gate_failures = [f for f in failures if f.startswith("offnode gate: ")]
                if gate_failures and len(gate_failures) == len(failures) and \
                        node_auto_reopen_gate_notice_due(conn, slug, str(row["health_closed_at"])):
                    notices.append((slug, dict(row), gate_failures))
                continue
            gate = node_auto_reopen_gate_record(conn, slug)
            evidence = {
                "slug": slug,
                "health_closed_at": row["health_closed_at"],
                "health_closed_reason": row["health_closed_reason"],
                "armed_at": armed_at,
                "green_streak": int(row["data_plane_green_streak"] or 0),
                "green_since": row["data_plane_green_since"],
                "last_heartbeat": row["last_heartbeat"],
                "offnode_gate_sha256": gate,
                "transports": {
                    name: [row[f"{column}_status"], row[f"{column}_ok_at"]]
                    for name, column in (
                        ("udp", "data_plane_udp"),
                        ("stealth", "data_plane_stealth"),
                        ("stealth_tls", "data_plane_stealth_tls"),
                    )
                },
            }
            if rerun:
                # Ruling D.v: the tier the node had before withdrawal, and the
                # full eligibility record on the latch event.
                prior = node_deployment_prior(row)
                _reasons, lineage_rule = installer_rerun_reopen_eligibility(conn, row, prior)
                evidence["installer_rerun"] = {
                    "deployment_completed_at": row["deployment_completed_at"],
                    "prior_state": prior,
                    "revision": row["data_plane_code_revision"],
                    "lineage_rule": lineage_rule,
                    "carry_proofs": {
                        name: [row[f"{column}_status"], row[f"{column}_ok_at"]]
                        for name, column in NODE_RERUN_AWG_CARRY_COLUMNS
                        if f"{column}_status" in row.keys()
                    },
                    "winn3_canary": [row["winn3_canary_status"], row["winn3_canary_ok_at"]],
                }
                claimed = conn.execute(
                    "UPDATE nodes SET operator_enabled = 1, free_access_enabled = ?, "
                    "latch_cause = 'auto_reopen_installer_rerun', "
                    "health_closed_at = NULL, health_closed_reason = NULL "
                    "WHERE slug = ? AND COALESCE(operator_enabled, 0) = 0 AND retired_at IS NULL "
                    "AND deployment_withdrawal_id IS NULL AND COALESCE(winn3_operator_hold,0)=0 "
                    "AND deployment_generation=? AND health_closed_at = ? "
                    "AND health_closed_reason = 'installer_rerun'",
                    (int(prior.get("free_access_enabled") or 0), slug, row["deployment_generation"], row["health_closed_at"]),
                )
            elif fresh:
                # The ticket is re-verified at the flip and the tier is the
                # verified ticket's, never a column's (design 3.17).
                ticket, _why = fresh_install_authority(conn, row)
                if ticket is None or ticket["tier"] not in ("free", "premium"):
                    result["held"][slug] = ["go-live ticket: re-verification failed at the flip"]
                    continue
                fresh_tier = ticket["tier"]
                evidence["fresh_install"] = {
                    "deployment_completed_at": row["deployment_completed_at"],
                    "deployment_generation": generation,
                    "identity_sha256": row["winn3_identity_sha256"],
                    "ticket": {"action": ticket["action"], "nonce": ticket["nonce"],
                               "epoch": ticket["epoch"], "go_live": ticket["go_live"],
                               "tier": ticket["tier"]},
                    "revision": row["data_plane_code_revision"],
                    "carry_proofs": {
                        name: [row[f"{column}_status"], row[f"{column}_ok_at"]]
                        for name, column in NODE_RERUN_AWG_CARRY_COLUMNS
                        if f"{column}_status" in row.keys()
                    },
                    "winn3_canary": [row["winn3_canary_status"], row["winn3_canary_ok_at"]],
                }
                # H7 fix (Sol T1 item 3): the window can run out while the
                # hub-run gate builds (H6 runs it outside the write lock), so
                # it is checked again right before the flip; eligibility never
                # lingers past it.
                if installer_rerun_window_expired(row):
                    conn.execute(
                        "UPDATE nodes SET health_closed_at = NULL, health_closed_reason = NULL, "
                        "latch_cause = 'fresh_install_expired' WHERE slug = ? "
                        "AND health_closed_reason = 'fresh_install' "
                        "AND COALESCE(operator_enabled, 0) = 0",
                        (slug,),
                    )
                    result["fresh_install_expired"].append(slug)
                    fresh_expired_alerts.append((slug, ["the go-live window expired before the flip"]))
                    continue
                claimed = conn.execute(
                    "UPDATE nodes SET operator_enabled = 1, free_access_enabled = ?, "
                    "latch_cause = 'auto_golive_fresh_install', "
                    "health_closed_at = NULL, health_closed_reason = NULL "
                    "WHERE slug = ? AND COALESCE(operator_enabled, 0) = 0 AND retired_at IS NULL "
                    "AND deployment_withdrawal_id IS NULL AND COALESCE(winn3_operator_hold, 0) = 0 "
                    "AND deployment_generation = ? AND health_closed_at = ? "
                    "AND health_closed_reason = 'fresh_install'",
                    (1 if fresh_tier == "free" else 0, slug, generation, row["health_closed_at"]),
                )
            else:
                claimed = conn.execute(
                    "UPDATE nodes SET operator_enabled = 1, latch_cause = 'auto_reopen', "
                    "health_closed_at = NULL, health_closed_reason = NULL "
                    "WHERE slug = ? AND COALESCE(operator_enabled, 0) = 0 AND retired_at IS NULL "
                    "AND deployment_withdrawal_id IS NULL AND COALESCE(winn3_operator_hold,0)=0 "
                    "AND deployment_generation=? AND health_closed_at = ?",
                    (slug, row["deployment_generation"], row["health_closed_at"]),
                )
            if claimed.rowcount != 1:
                continue
            # The same consumption as manual promotion: marks the gate used and
            # moves the cleanup record to 'auto_reopened', so the next opening
            # of any kind needs a fresh cleanup and a fresh gate.
            if not consume_offnode_gate(conn, slug, gate, "auto_reopened"):
                conn.rollback()
                result["held"][slug] = ["offnode gate: record was used concurrently"]
                continue
            conn.execute(
                "UPDATE node_latch_events SET detail_json = ? WHERE event_id = "
                "(SELECT MAX(event_id) FROM node_latch_events WHERE slug = ?)",
                (json.dumps(evidence, sort_keys=True, default=str), slug),
            )
            if rerun or fresh:
                # The promotion ledger stays the single history of every opening.
                conn.execute(
                    "INSERT INTO node_promotion_events ("
                    " promotion_id, slug, promoted_at, tier, evidence_sha256, operator_source_hash,"
                    " node_status, management_status, management_checked_at, data_plane_status,"
                    " data_plane_ok_at, data_plane_code_revision"
                    ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        secrets.token_hex(16), slug, utcnow().isoformat(),
                        fresh_tier if fresh else (
                            "free" if int(prior.get("free_access_enabled") or 0) else "premium"),
                        gate, AUTOMATIC_PROMOTION_SOURCES[1] if fresh else AUTOMATIC_PROMOTION_SOURCES[0],
                        str(row["status"] or "unknown"), str(row["management_status"] or "unknown"),
                        row["management_checked_at"], str(row["data_plane_status"] or "unknown"),
                        row["data_plane_ok_at"] or "", row["data_plane_code_revision"],
                    ),
                )
        result["reopened"].append(slug)
        if fresh:
            golive_alerts.append((slug, {
                "slug": slug, "tier": fresh_tier, "offnode_gate_sha256": gate,
                "ticket_nonce": ticket["nonce"], "deployment_generation": generation,
                "identity_sha256": row["winn3_identity_sha256"],
            }))
        logger.warning(
            "node %s latch reopened automatically (operator_enabled 0->1) after %d healthy proofs",
            slug, int(row["data_plane_green_streak"] or 0),
        )
    for slug, last_failures in expired_alerts:
        security_alert(2, "installer rerun reopen window expired; manual evidenced promotion required",
                       details={"slug": slug, "last_failures": last_failures})
        logger.warning("node %s installer rerun reopen window expired; closure is now an operator closure", slug)
    for slug, last_failures in fresh_expired_alerts:
        security_alert(2, "fresh install go-live window expired; manual evidenced promotion required",
                       details={"slug": slug, "last_failures": last_failures})
        logger.warning("node %s fresh install go-live window expired; closure is now an operator closure", slug)
    for slug, details in golive_alerts:
        security_alert(3, "fresh install node went live automatically", details=details)
    for slug, row, gate_failures in notices:
        security_alert(2, "data-plane node waits on off-node gate", details={
            "slug": slug,
            "health_closed_at": row.get("health_closed_at"),
            "health_closed_reason": row.get("health_closed_reason") or "",
            "offnode_gate": gate_failures,
            "action": "run the node-side check and POST /admin/nodes/offnode-gate; "
                      "every other reopen condition is met",
        })
        logger.warning("node %s is ready to reopen except for its off-node gate", slug)
        result["gate_notices"].append(slug)
    return result

def drain_node_latch_events(limit: int = 50) -> int:
    """Alert on every recorded latch transition, at least once. The row is
    marked only after security_alert() has written its security_events row,
    so a crash in between repeats an alert and never loses one."""
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT * FROM node_latch_events WHERE alerted_at IS NULL "
            "ORDER BY event_id LIMIT ?",
            (max(1, int(limit)),),
        ).fetchall()
    sent = 0
    for row in rows:
        closed = int(row["to_value"] or 0) == 0
        details = {
            "slug": row["slug"],
            "latch_event_id": int(row["event_id"]),
            "transition": f"{int(row['from_value'] or 0)}->{int(row['to_value'] or 0)}",
            "cause": row["cause"],
            "health_closed_reason": row["health_closed_reason"] or "",
            "data_plane_status": row["data_plane_status"] or "",
            "changed_at": row["changed_at"],
        }
        if closed:
            details["automatic_reopen"] = (
                "not eligible: operator or unattributed closure"
                if not row["health_closed_reason"] else
                ("enabled; needs the promotion gate, a fresh off-node gate record and "
                 f"{NODE_AUTO_REOPEN_PROOFS} fresh healthy proofs"
                 if NODE_AUTO_REOPEN_ENABLED else
                 "disabled; manual promotion required")
            )
        security_alert(
            2,
            "data-plane node latch closed" if closed else "data-plane node latch opened",
            details=details,
        )
        with get_db() as conn:
            conn.execute(
                "UPDATE node_latch_events SET alerted_at = ? "
                "WHERE event_id = ? AND alerted_at IS NULL",
                (utcnow().isoformat(), int(row["event_id"])),
            )
        logger.warning(
            "node %s latch %s (cause=%s, event=%d)",
            row["slug"], "closed" if closed else "opened", row["cause"], int(row["event_id"]),
        )
        sent += 1
    return sent

async def fleet_availability_sweep_loop():
    while True:
        try:
            await asyncio.to_thread(audit_fleet_availability_once)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("fleet availability audit failed: %s", type(exc).__name__)
        try:
            await asyncio.to_thread(audit_winn3_contract_once)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("winn3 contract audit failed: %s", type(exc).__name__)
        # H6-PERF: security alerts for recorded latch transitions go out before
        # the reopen pass, which can spend minutes on node SSH checks. The
        # drain after the pass stays, so a reopen it records is alerted at once.
        try:
            await asyncio.to_thread(drain_node_latch_events)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("node latch alert drain failed: %s", type(exc).__name__)
        try:
            await asyncio.to_thread(auto_reopen_health_closed_nodes)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("node auto-reopen pass failed: %s", type(exc).__name__)
        try:
            await asyncio.to_thread(drain_node_latch_events)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("node latch alert drain failed: %s", type(exc).__name__)
        await asyncio.sleep(FLEET_AVAILABILITY_AUDIT_SECONDS)

async def awg_canary_sync_loop():
    """H5: the canary peer pushes. A separate task, never a step of the audit
    and reopen loop above: a push to a dead node waits out its SSH timeout, and
    a pass over many of them must not delay the next audit or reopen pass."""
    while True:
        try:
            await asyncio.to_thread(sync_awg_canary_peers_once)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("awg canary peer sync failed: %s", type(exc).__name__)
        await asyncio.sleep(FLEET_AVAILABILITY_AUDIT_SECONDS)

# --- Design 10.3 and 10.4 (slice P2): go-live latency and hub cost ----------
#
# P-11 completion-triggered provisioning, P-12 the on-demand proof request
# (A-3), P-13 reopen on the last proof. P-15 is the verified descriptor cache
# inside winn3_verify_descriptor_signature, and P-16 (one long-lived AWG
# carrying client per transport) lives in H5's carrying probe
# (wins_node_dataplane_probe.py --carry), inside H5's unit and sandbox.
#
# None of this removes or weakens a proof. Each item only runs a proof sooner,
# and the 5-minute sweep, the 120 s audit loop and the 15 minute canary timer
# stay as backstops. Integration with H2, H3 and H5 (P2-SEAM-H2, P2-SEAM-H3,
# P2-SEAM-H5):
#   * winn3_auto_provision and deployment_released_at are H2's;
#   * the request file, its consumer, its path unit and the result ingest are
#     H3's; only the app-side gate in front of H3's writer is P2's;
#   * the carrying proofs are written by H5's probe in its own unit, so they
#     are noticed here by watching their columns, and
#     note_winn3_proof_ingested() is the single call an in-process ingest makes.

WINN3_NODE_SLUG_RE = re.compile(r"[a-z0-9][a-z0-9-]{1,39}")

def winn3_node_slug_or_empty(value: Any) -> str:
    """A slug in the fleet's one pattern, or "". Used before any path or
    command is built from a name. Every slug it accepts also matches H3's
    request pattern, so every request written here is one H3 consumes."""
    if not isinstance(value, str):
        return ""
    slug = value.strip().lower()
    return slug if WINN3_NODE_SLUG_RE.fullmatch(slug) else ""

# ---- P-11: completion-triggered provisioning --------------------------------
#
# One scheduler starts winn3_auto_provision in this process. Its triggers are
# every committed deployment release (both completion routes, design 10.3
# P-11) and every committed registration or heartbeat (H2's post-commit job,
# the design 10.3 "Trigger" row). The final registration that reports a
# published v3 identity is one of those registrations, so it needs no trigger
# of its own. At most one pass per slug runs here, and a trigger that lands
# while a pass runs costs exactly one more pass after it, so the earliest
# trigger that can see the released row is never lost. The job's own lease
# still refuses a pass that the 5-minute sweep starts meanwhile.
WINN3_PROVISION_TRIGGER_REASONS = ("deployment-released", "registration")
_WINN3_PROVISION_LOCK = threading.Lock()
_WINN3_PROVISION_STATE: dict[str, str] = {}

def winn3_auto_provision_triggers_enabled() -> bool:
    """H2's rule: with both automatic switches off a pass has nothing to do."""
    return (os.getenv("WINN3_AUTO_SIGN", "1").strip() == "1"
            or os.getenv("WINN3_AUTO_CARRIER", "1").strip() == "1")

def _winn3_provision_start_thread(target, slug: str) -> None:
    threading.Thread(
        target=target, args=(slug,), name="winn3-provision-" + slug, daemon=True,
    ).start()

def _winn3_provision_worker(slug: str) -> None:
    while True:
        try:
            winn3_auto_provision(slug)
        except Exception as exc:
            # The type only: the job's message can carry node material.
            logger.error("winn3 provisioning pass for %s failed: %s", slug, type(exc).__name__)
        with _WINN3_PROVISION_LOCK:
            if _WINN3_PROVISION_STATE.get(slug) == "again":
                # A trigger arrived while this pass ran. One more pass sees
                # whatever it changed; any number of triggers coalesce.
                _WINN3_PROVISION_STATE[slug] = "running"
                continue
            _WINN3_PROVISION_STATE.pop(slug, None)
            return

def trigger_winn3_auto_provision(slug: Any, reason: str) -> str:
    """Start winn3_auto_provision for one slug now, off the request thread.
    The job keeps its lease, its preconditions and its generation checks;
    this only decides when it runs. Returns "started", "coalesced",
    "disabled" (both automatic switches off) or "ignored"."""
    clean = winn3_node_slug_or_empty(slug)
    if not clean or reason not in WINN3_PROVISION_TRIGGER_REASONS:
        return "ignored"
    if not winn3_auto_provision_triggers_enabled():
        return "disabled"
    with _WINN3_PROVISION_LOCK:
        if clean in _WINN3_PROVISION_STATE:
            _WINN3_PROVISION_STATE[clean] = "again"
            return "coalesced"
        _WINN3_PROVISION_STATE[clean] = "running"
    try:
        _winn3_provision_start_thread(_winn3_provision_worker, clean)
    except Exception:
        with _WINN3_PROVISION_LOCK:
            _WINN3_PROVISION_STATE.pop(clean, None)
        logger.warning("Winn3 provisioning worker unavailable for %s", clean)
        return "ignored"
    return "started"

def trigger_winn3_golive_after_release(slug: str) -> None:
    """What a committed deployment release starts (P-11 and, after completion,
    P-12). Neither can fail or delay the completion that called it."""
    try:
        trigger_winn3_auto_provision(slug, "deployment-released")
    except Exception as exc:
        logger.error("winn3 provisioning trigger failed: %s", type(exc).__name__)
    try:
        request_winn3_canary_proof(slug, "completion")
    except Exception as exc:
        logger.error("winn3 canary request failed: %s", type(exc).__name__)

# ---- P-12: the on-demand proof request (A-3), in front of H3's writer ---------
#
# The request is H3's: <slug>.json holding {"slug": slug}, written by
# winn3_request_canary into WINN3_CANARY_REQUEST_DIR, and H3's path unit,
# consumer and result ingest run it. The app writes DATA, never starts a unit
# and never names a command. What stays here is P2's app-side gate: only a
# known, unretired fleet slug, at most once per slug per 60 s, a request
# inside the limit deferred to the end of the limit instead of dropped, and
# retirement cancelling both.
WINN3_CANARY_REQUEST_MIN_INTERVAL_SECONDS = 60
WINN3_CANARY_REQUEST_REASONS = ("completion", "carrier-flip")
_WINN3_CANARY_REQUEST_LOCK = threading.Lock()
_WINN3_CANARY_REQUEST_LAST: dict[str, float] = {}
# slug -> the timer that writes its deferred request (at most one per slug).
_WINN3_CANARY_REQUEST_DEFERRED: dict[str, Any] = {}

def _winn3_canary_defer_start(delay: float, slug: str, reason: str) -> Any:
    timer = threading.Timer(delay, _winn3_canary_deferred_fire, args=(slug, reason))
    timer.daemon = True
    timer.start()
    return timer

def _winn3_canary_deferred_fire(slug: str, reason: str) -> None:
    with _WINN3_CANARY_REQUEST_LOCK:
        _WINN3_CANARY_REQUEST_DEFERRED.pop(slug, None)
    try:
        request_winn3_canary_proof(slug, reason)
    except Exception as exc:
        logger.error("deferred winn3 canary request failed: %s", type(exc).__name__)

def request_winn3_canary_proof(slug: Any, reason: str) -> bool:
    """Ask for an immediate per-slug canary run, after a completion and again
    after the carrier flip. Only for a known, unretired slug, at most once per
    slug per WINN3_CANARY_REQUEST_MIN_INTERVAL_SECONDS. True means H3's
    request file is now in the spool; False means nothing was written now. A
    request inside the limit is deferred, not dropped: one request per slug is
    written when the limit ends, so the proof after a carrier flip that lands
    within 60 s of the completion still runs then instead of at the next 15
    minute timer."""
    clean = winn3_node_slug_or_empty(slug)
    if not clean or reason not in WINN3_CANARY_REQUEST_REASONS:
        return False
    with get_db() as conn:
        row = conn.execute("SELECT retired_at FROM nodes WHERE slug = ?", (clean,)).fetchone()
    if row is None or node_is_retired(row):
        return False
    now = time.monotonic()
    with _WINN3_CANARY_REQUEST_LOCK:
        last = _WINN3_CANARY_REQUEST_LAST.get(clean)
        if last is not None and now - last < WINN3_CANARY_REQUEST_MIN_INTERVAL_SECONDS:
            if clean not in _WINN3_CANARY_REQUEST_DEFERRED:
                delay = WINN3_CANARY_REQUEST_MIN_INTERVAL_SECONDS - (now - last) + 0.05
                try:
                    _WINN3_CANARY_REQUEST_DEFERRED[clean] = _winn3_canary_defer_start(delay, clean, reason)
                except Exception as exc:
                    logger.warning("winn3 canary request could not be deferred: %s", type(exc).__name__)
            return False
        _WINN3_CANARY_REQUEST_LAST[clean] = now
    # H3's writer: the installer's directory is opened without following a
    # symlink and never created, and the file is written under a dot name and
    # renamed into place, so a planted link is replaced, never written through.
    if winn3_request_canary(clean):
        return True
    with _WINN3_CANARY_REQUEST_LOCK:
        # Nothing reached the spool, so the attempt uses up no limit.
        if _WINN3_CANARY_REQUEST_LAST.get(clean) == now:
            del _WINN3_CANARY_REQUEST_LAST[clean]
    return False

def remove_winn3_canary_request(slug: Any) -> None:
    """POST /admin/nodes/retire removes the slug's pending request, its limit
    entry and its deferred request, so a retired slug leaves nothing behind.
    The request file is H3's, so it is named by H3's request pattern, which
    every fleet slug matches; nothing else is ever joined to the directory."""
    clean = winn3_node_slug_or_empty(slug)
    if clean:
        with _WINN3_CANARY_REQUEST_LOCK:
            _WINN3_CANARY_REQUEST_LAST.pop(clean, None)
            deferred = _WINN3_CANARY_REQUEST_DEFERRED.pop(clean, None)
        if deferred is not None:
            try:
                deferred.cancel()
            except Exception:
                pass
    name = slug.strip().lower() if isinstance(slug, str) else ""
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,62}", name):
        return
    try:
        (WINN3_CANARY_REQUEST_DIR / (name + ".json")).unlink(missing_ok=True)
    except OSError:
        logger.warning("Retired node canary request removal failed for %s", name)

# ---- P-13: reopen on the last proof -----------------------------------------
WINN3_PROOF_WATCH_SECONDS = max(2, int(os.getenv("WINN3_PROOF_WATCH_SECONDS", "10") or 10))
# The closure classes whose reopen waits for proofs newer than the completion:
# installer_rerun (L84, ruling D) and fresh_install (H7 go-live, design 3.17).
WINN3_PROOF_REOPEN_CLASSES = ("installer_rerun", "fresh_install")
_WINN3_PROOF_SEEN: dict[str, tuple] = {}

def winn3_proof_reopen_class_enabled(reason: str) -> bool:
    """Each class under the same switch the fleet pass applies to it."""
    if reason == "installer_rerun":
        return bool(NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED)
    if reason == "fresh_install":
        return bool(WINN3_FRESH_INSTALL_AUTO_GOLIVE)
    return False

def reopen_proof_columns(available: Any) -> list[str]:
    """The row columns whose change can complete a reopen's proof set."""
    wanted = ["deployment_completed_at", "protocol_version", "winn3_canary_status", "winn3_canary_ok_at"]
    for _name, column in NODE_RERUN_AWG_CARRY_COLUMNS:
        wanted += [f"{column}_status", f"{column}_ok_at"]
    return [column for column in wanted if column in available]

def reopen_last_proof_arrived(node: Any) -> bool:
    """True when this closed installer_rerun or fresh_install node holds every
    proof its reopen needs, each newer than the completion. A missing carrying
    column keeps it False, exactly as installer_rerun_carry_failures refuses
    it. A fresh_install node goes live only on winn/3, so its proof set
    includes the v3 canary."""
    data = dict(node)
    reason = str(data.get("health_closed_reason") or "")
    if reason not in WINN3_PROOF_REOPEN_CLASSES:
        return False
    if int(data.get("operator_enabled") or 0) != 0 or str(data.get("retired_at") or "").strip():
        return False
    if not str(data.get("deployment_completed_at") or "").strip():
        return False
    if reason == "fresh_install" and str(data.get("protocol_version") or "").strip().lower() != "winn/3":
        return False
    return not installer_rerun_carry_failures(data)

def evaluate_reopen_on_last_proof(slug: Any) -> Optional[dict]:
    """Evaluate one slug's reopen now, but only when its last required proof is
    in. The evaluation is the fleet pass restricted to the slug: the same
    conditions, switches and daily budget, and every proof still has to be
    newer than deployment_completed_at. Returns that pass's result, or None
    when a proof is still missing."""
    clean = winn3_node_slug_or_empty(slug)
    if not clean:
        return None
    with get_db() as conn:
        row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (clean,)).fetchone()
    if row is None or not reopen_last_proof_arrived(row):
        return None
    return auto_reopen_health_closed_nodes(only_slug=clean)

def note_winn3_proof_ingested(slug: Any) -> None:
    """The call a proof ingest makes after it records a proof. Never raises."""
    try:
        evaluate_reopen_on_last_proof(slug)
    except Exception as exc:
        logger.error("reopen evaluation after a proof failed: %s", type(exc).__name__)

def evaluate_reopen_on_new_proofs() -> list[str]:
    """The carrying proofs are written by H5's probe in its own unit, so they
    are noticed here: one read of the few nodes waiting in an installer_rerun
    or fresh_install window, and an evaluation only for a slug whose proof
    columns changed since this process last looked."""
    classes = [reason for reason in WINN3_PROOF_REOPEN_CLASSES if winn3_proof_reopen_class_enabled(reason)]
    if not classes:
        _WINN3_PROOF_SEEN.clear()
        return []
    with get_db() as conn:
        rows = conn.execute(
            "SELECT * FROM nodes WHERE COALESCE(operator_enabled, 0) = 0 "
            "AND health_closed_reason IN (" + ", ".join("?" for _ in classes) + ") "
            "AND retired_at IS NULL AND deployment_completed_at IS NOT NULL ORDER BY slug",
            classes,
        ).fetchall()
    seen: dict[str, tuple] = {}
    changed: list[str] = []
    for row in rows:
        slug = str(row["slug"])
        fingerprint = tuple(row[column] for column in reopen_proof_columns(row.keys()))
        seen[slug] = fingerprint
        if _WINN3_PROOF_SEEN.get(slug) != fingerprint:
            changed.append(slug)
    _WINN3_PROOF_SEEN.clear()
    _WINN3_PROOF_SEEN.update(seen)
    evaluated: list[str] = []
    for slug in changed:
        try:
            if evaluate_reopen_on_last_proof(slug) is not None:
                evaluated.append(slug)
        except Exception as exc:
            logger.error("reopen evaluation on a new proof failed: %s", type(exc).__name__)
    return evaluated

async def winn3_proof_reopen_watch_loop():
    while True:
        try:
            await asyncio.to_thread(evaluate_reopen_on_new_proofs)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("proof watch failed: %s", type(exc).__name__)
        await asyncio.sleep(WINN3_PROOF_WATCH_SECONDS)

def node_is_retired(row: Any) -> bool:
    if row is None:
        return False
    return bool(str(dict(row).get("retired_at") or "").strip())

def node_retirement_state_json(row: Any) -> str:
    """The pre-retirement row, minus the secret columns, as JSON.

    Everything else is captured verbatim rather than by an allow-list, so a
    column added to nodes by a later lane is recorded automatically instead of
    being silently dropped from the recovery record.
    """
    data = {
        key: value
        for key, value in dict(row).items()
        if key not in NODE_RETIREMENT_UNRECORDED_COLUMNS
    }
    return json.dumps(data, sort_keys=True, default=str)

def latest_node_retirement(conn: sqlite3.Connection, slug: str) -> Optional[sqlite3.Row]:
    return conn.execute(
        "SELECT * FROM node_retirements WHERE slug = ? AND restored_at IS NULL"
        " ORDER BY retired_at DESC, retirement_id DESC LIMIT 1",
        (slug,),
    ).fetchone()

def normalize_hostname(value: Any) -> str:
    host = str(value or "").strip().lower()
    if not host:
        return ""
    if "://" in host:
        try:
            host = urllib.parse.urlparse(host).hostname or ""
        except Exception:
            host = ""
    host = host.split("/", 1)[0].strip().strip("[]")
    if ":" in host and host.rsplit(":", 1)[1].isdigit():
        host = host.rsplit(":", 1)[0]
    if not re.match(r"^[a-z0-9.-]{1,253}$", host):
        return ""
    if "." not in host:
        return ""
    return host

def parse_aliases(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        raw_items = value.split(",")
        if value.strip().startswith("["):
            try:
                decoded = json.loads(value)
                if isinstance(decoded, list):
                    raw_items = decoded
            except Exception:
                pass
    elif isinstance(value, list):
        raw_items = value
    else:
        raw_items = []
    aliases: list[str] = []
    for item in raw_items:
        host = normalize_hostname(item)
        if host and host not in aliases:
            aliases.append(host)
    return aliases[:12]

def parse_xray_transports(
    value: Any,
    fallback_port: int,
    fallback_security: str,
    *,
    strict: bool = False,
    keep_plaintext: bool = False,
) -> list[dict[str, Any]]:
    raw_items: list[Any]
    if isinstance(value, str):
        try:
            decoded = json.loads(value)
            raw_items = decoded if isinstance(decoded, list) else []
        except Exception:
            raw_items = []
    elif isinstance(value, list):
        raw_items = value
    else:
        raw_items = []
    try:
        safe_port = int(fallback_port)
    except (TypeError, ValueError):
        safe_port = 80
    if not 1 <= safe_port <= 65535:
        safe_port = 80
    safe_security = str(fallback_security or "").strip().lower()
    if safe_security not in {"none", "tls"}:
        if strict:
            raise ValueError("primary security must be none or tls")
        safe_security = "none"
    transports: list[dict[str, Any]] = []
    seen_ports: dict[int, str] = {}
    for item in raw_items:
        if not isinstance(item, dict):
            if strict:
                raise ValueError("each transport must be an object")
            continue
        try:
            port = int(item.get("port"))
        except (TypeError, ValueError):
            if strict:
                raise ValueError("transport port must be an integer")
            continue
        security = str(item.get("security") or "").strip().lower()
        if not 1 <= port <= 65535 or security not in {"none", "tls"}:
            if strict:
                raise ValueError("transport port/security is invalid")
            continue
        previous_security = seen_ports.get(port)
        if previous_security is not None:
            if previous_security != security and strict:
                raise ValueError(f"port {port} cannot be both TLS and plaintext")
            continue
        seen_ports[port] = security
        transports.append({"port": port, "security": security})
    if not transports:
        transports.append({"port": safe_port, "security": safe_security})
    elif strict and (transports[0]["port"], transports[0]["security"]) != (safe_port, safe_security):
        raise ValueError("the first ordered transport must match the primary port/security")
    if not strict and not keep_plaintext:
        # Client-serving callers get no plaintext route when a TLS route
        # exists. Nodes register "80:none,443:tls" by default and the old
        # served order put port 80 first, so the WebSocket path, the Host
        # header and the unencrypted VLESS header (node UUID) crossed the
        # client's access network in the clear. Registration refuses a TLS
        # route that no client can attempt (xray_tls_dns_candidate_available),
        # so a list with a TLS entry keeps a route every client can try. A
        # plaintext-only list is served unchanged. Storage and core-to-exit
        # callers pass keep_plaintext=True and keep the registered list.
        tls_only = [t for t in transports if t["security"] == "tls"]
        if tls_only:
            transports = tls_only
    return transports[:6]


def xray_tls_dns_candidate_available(stealth_endpoint: Any, regional_aliases: Any, default_port: int) -> bool:
    """True when at least one client host candidate can carry an Xray TLS route.

    Mirrors the clients: the stealth host plus the regional aliases are the
    candidates, and a TLS candidate must be a DNS name (clients skip TLS for
    an IP literal; lib/xray_transport_options.dart _isDnsName, and
    VpnConfigValidator.isPublicHost's label rules).
    """
    try:
        primary = split_host_port(str(stealth_endpoint or ""), default_port)[0]
    except (TypeError, ValueError):
        primary = ""
    for raw in [primary] + parse_aliases(regional_aliases):
        host = str(raw or "").strip().lower().strip("[]")
        if not host or "." not in host or not re.fullmatch(r"[a-z0-9.-]{1,253}", host):
            continue
        try:
            ipaddress.ip_address(host)
            continue
        except ValueError:
            pass
        if all(label and len(label) <= 63 and not label.startswith("-") and not label.endswith("-")
               for label in host.split(".")):
            return True
    return False

def generate_wireguard_material():
    private_key = subprocess.check_output(["wg", "genkey"]).decode().strip()
    public_key = subprocess.run(["wg", "pubkey"], input=private_key.encode(), capture_output=True, check=True).stdout.decode().strip()
    preshared_key = subprocess.check_output(["wg", "genpsk"]).decode().strip()
    return private_key, public_key, preshared_key

def generate_preshared_key() -> str:
    return base64.b64encode(secrets.token_bytes(32)).decode()

def maybe_generate_preshared_key() -> str:
    return generate_preshared_key() if AWG_PRESHARED_KEYS_ENABLED else ""

def validate_wireguard_public_key(value: Optional[str]) -> str:
    value = (value or "").strip()
    if not value:
        return ""
    try:
        raw = base64.b64decode(value, validate=True)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid client public key.")
    if len(raw) != 32:
        raise HTTPException(status_code=400, detail="Invalid client public key.")
    return value

# Client-owned winn/3 identity (Fable 5.1 ruling 2026-09-29, IA-CP-05).
#
# Devices generate their own X25519 static pair and send only the public half
# on /verify; the hub stores winn3_static_public and winn3_inner_v4 and never
# the private half. Hub minting survives ONLY as the legacy path for builds
# that send no public key, behind this flag, and the same lever gates the
# legacy AmneziaWG minting path (client_public_key absent). Default 1 keeps
# every shipped client working; flip to 0 once the client-key release is the
# minimum supported version on the force-update gate (ruling, Step 4).
WINN3_HUB_MINTED_KEYS_ALLOWED = os.getenv(
    "WINN3_HUB_MINTED_KEYS_ALLOWED", "1"
).strip().lower() in {"1", "true", "yes", "on"}


def validate_winn3_static_public(value: Optional[str]) -> str:
    """Twin of validate_wireguard_public_key for the winn/3 identity.

    Stricter on purpose: the gateway decodes static_public with
    base64.StdEncoding.Strict() and refuses the WHOLE registry snapshot on a
    malformed entry (cmd/winn3-gateway/peer_registry.go), so only the canonical
    encoding of 32 raw bytes is accepted, and the all-zero key is refused.
    Returns "" when absent. Never echoes the value in an error.
    """
    value = (value or "").strip()
    if not value:
        return ""
    try:
        raw = base64.b64decode(value, validate=True)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid winn3 static public key.")
    if (
        len(raw) != 32
        or raw == bytes(32)
        or base64.b64encode(raw).decode("ascii") != value
    ):
        raise HTTPException(status_code=400, detail="Invalid winn3 static public key.")
    return value


def winn3_static_public_in_use(
    conn: sqlite3.Connection, public_key: str, *, own_device_ids: set
) -> bool:
    """True when another device row, or the hub canary, already holds this key.

    The gateway refuses a registry snapshot with a duplicate static_public and
    the hub's own builder raises on one, so a device-chosen key that collides
    would take every device on that node offline. Refused at admission instead.
    """
    public_key = (public_key or "").strip()
    if not public_key:
        return False
    if (public_key == str(os.getenv("WINN3_CANARY_STATIC_PUBLIC", "") or "").strip()
            or public_key in winn3_canary_reserved_publics()):
        return True
    owners = [str(item) for item in own_device_ids if str(item or "")]
    placeholders = ",".join("?" for _ in owners) or "''"
    row = conn.execute(
        "SELECT 1 FROM devices WHERE winn3_static_public = ? "
        f"AND device_id NOT IN ({placeholders}) LIMIT 1",
        (public_key, *owners),
    ).fetchone()
    return row is not None

def allocate_internal_ip(conn: sqlite3.Connection) -> str:
    # Data-plane client tunnel assignment only. The control hub must not bind,
    # route, NAT, or expose services on this range. 10.8.255.0/24 is reserved
    # for Double VPN core-to-exit peers (the Core's exit address defaults to
    # 10.8.255.2/32, CORE_EXIT_ADDR), and ruling E sets 10.8.255.1/32 inside it
    # aside for the AWG carrying canary's system peer (slice H5; nothing in
    # this file or the Core enforces that reservation yet). The /24 must never
    # be issued to an ordinary client, and this function cannot issue it: the
    # third octet stops at VPN_CLIENT_POOL_THIRD_OCTET_MAX (254).
    used = {row["vpn_internal_ip"] for row in conn.execute("SELECT vpn_internal_ip FROM devices WHERE vpn_internal_ip IS NOT NULL").fetchall()}
    reserved = {
        item.strip()
        for item in os.getenv("VPN_RESERVED_IPS", "10.8.1.1,10.8.1.2").split(",")
        if item.strip()
    }
    for x in range(1, VPN_CLIENT_POOL_THIRD_OCTET_MAX + 1):
        for y in range(2, 255):
            candidate = f"10.8.{x}.{y}"
            if candidate not in used and candidate not in reserved:
                return candidate
    raise HTTPException(status_code=503, detail="No VPN addresses available.")

# --- Winn Protocol v3 standalone: per-device inner addresses and identities ---
#
# THE POOL IS AN OPERATOR SETTING AND THE HUB REFUSES TO GUESS IT.
#
# The inner address space belongs to the GATEWAY -- cmd/winn3-gateway owns the
# assignment and drops every packet whose source does not match it. The hub
# allocates a host address inside that space, so the two MUST agree, and nothing
# on the wire can tell them they do not: a client assigned outside the gateway's
# space starts a session, reports up, and carries nothing.
#
# So the pool is declared here and the descriptor's own `inner_router_v4` is
# checked against it before anything is served. A mismatch is a NAMED refusal
# that falls back to winn/1, never a served config. This is the one binding the
# hub can actually verify, and it is why the pool is an environment setting an
# operator sets to match the gateway rather than a constant this file invents.
#
# 10.10.0.0/24 by default: disjoint from the AmneziaWG client pool (10.8/16) and
# from the Double VPN core pool (10.9/16), because sharing either would put v3
# inner traffic in an address space the relay already routes.
#
# Pinned to /24 because the mobile clients derive the inner space against a hard
# /24 floor -- Android WinnV3Resolvers.sameInnerBlock (0xFFFFFF00) in
# WinnV3Posture.kt, Apple WinsWinn3Resolvers.sameInnerBlock (0xFFFF_FF00) in
# WinsWinn3SessionStart.swift -- so a /16 would silently split the fleet at
# device 254: the first ~253 clients in 10.10.0.0/24 can derive 10.10.0.1 while
# any client allocated in 10.10.1.x cannot. A wider pool is refused at startup
# rather than served half-working; see winn3_inner_pool().
#
# Windows/Linux do NOT check this themselves -- winn3_posture.h carries
# `dns_servers_are_inner` as a host DECLARATION ("a declaration rather than a
# check because this header cannot know the inner subnet"), so a wider pool does
# not refuse there. The descriptor's inner_resolver_v4 is not consumed on desktop
# at all (linux_winn3_host.h: "PARSED AND STORED, DELIBERATELY NOT CONSUMED"), so a
# wider pool produces no desktop refusal and no desktop derivation -- only whatever
# silent mismatch follows downstream. Do not claim the tun layer drops it; that is
# the cross-space v1 scenario, not this one.
# (Corrected 2026-08-12, lane d7_subnet_pin: this block previously cited a
# `winn3_posture.h sameInnerBlock` that does not exist in either host.)
WINN3_INNER_POOL_CIDR = (os.getenv("WINN3_INNER_POOL_CIDR") or "10.10.0.0/24").strip()
# EXACTLY this width, not a floor. See _winn3_inner_pool_or_reason().
WINN3_INNER_POOL_PREFIXLEN = 24


def _winn3_inner_pool_or_reason() -> tuple:
    """(network, None) for a usable pool, or (None, the exact reason).

    THE ONE IMPLEMENTATION OF THE POOL RULE (D15, 2026-08-12). Everything that
    needs to know whether the pool is usable -- the runtime validator
    winn3_inner_pool() and the startup guard require_winn3_inner_pool() --
    comes through here, so the two cannot reach different verdicts.

    They previously could, and did. D7 pinned the pool to /24 but left a second
    copy of the rule inline in startup_event(), and the two disagreed three
    ways: a malformed CIDR returned None silently here and was swallowed by
    `except ValueError: pass` there; a non-IPv4 pool was silent in both; only a
    too-wide pool was ever reported. So `10.10.0/24` -- one missing octet --
    started the hub cleanly, returned "" from every allocation, failed every
    in-pool check (misreporting healthy descriptors as "outside pool" in the
    readiness path), and downgraded the entire fleet to winn/1 with no
    diagnostic anywhere. Zero-working dressed as running, which is strictly
    worse than the half-working state D7 already refuses to serve. Divergence
    between a guard and its validator is how that happened, so the fix is that
    the guard no longer has an opinion of its own to diverge with.

    THE WIDTH IS EXACTLY /24, in both directions:

      WIDER breaks client derivation. The mobile hosts derive inner
      reachability against a hard /24 floor -- Android
      WinnV3Resolvers.sameInnerBlock (0xFFFFFF00) in WinnV3Posture.kt, Apple
      WinsWinn3Resolvers.sameInnerBlock (0xFFFF_FF00) in
      WinsWinn3SessionStart.swift -- so a /16 silently splits the fleet at
      device 254: the first ~253 clients in 10.10.0.0/24 can derive 10.10.0.1
      while any client allocated in 10.10.1.x cannot. Windows/Linux do not
      check it at all (winn3_posture.h takes `dns_servers_are_inner` as a host
      DECLARATION), so there it fails even quieter.

      NARROWER has no articulated use and includes the degenerate case: a /32
      offers one address for the entire fleet -- the gateway's own inner
      address and nothing else -- so every device after the first gets "".

    A future /25 sharding scheme is a deliberate revisit that owes a
    client-derivation analysis, not latitude left open by an inequality.

    Returns the reason as a sentence fragment that reads correctly after
    "WINN3_INNER_POOL_CIDR=<value> ", so the log line and the startup refusal
    say the same words.
    """
    try:
        network = ipaddress.ip_network(WINN3_INNER_POOL_CIDR, strict=False)
    except ValueError as exc:
        return None, (
            "is not a valid CIDR ({}). Give a dotted-quad network and a "
            "prefix, e.g. 10.10.0.0/24. An abbreviated form such as "
            "'10.10.0/24' is NOT accepted -- that typo used to start the hub "
            "silently and downgrade every device to winn/1.".format(exc)
        )
    if not isinstance(network, ipaddress.IPv4Network):
        return None, (
            "is IPv6, and winn/3 inner addressing is IPv4-only: the "
            "descriptor's inner_router_v4 and inner_resolver_v4 are dotted "
            "quads and the gateway's -forward carries IPv4 only. Give an "
            "IPv4 /24, e.g. 10.10.0.0/24."
        )
    if network.prefixlen != WINN3_INNER_POOL_PREFIXLEN:
        return None, (
            "is a /{}, and the pool is pinned to EXACTLY /24. A wider pool "
            "(e.g. /16) allocates clients outside the derivable /24 and "
            "silently breaks their sessions at device 254, because the mobile "
            "clients derive inner reachability against a hard /24 floor "
            "(Android WinnV3Resolvers.sameInnerBlock 0xFFFFFF00 in "
            "WinnV3Posture.kt, Apple WinsWinn3Resolvers.sameInnerBlock in "
            "WinsWinn3SessionStart.swift), and Windows/Linux winn3_posture.h "
            "does not check it at all (dns_servers_are_inner is a host "
            "declaration) so there the same pool declares a resolver inner "
            "that the tun layer drops. A narrower pool has no supported use "
            "and a /32 allocates nothing at all. Pin the pool to /24 (e.g. "
            "10.10.0.0/24) and set WINN3_GATEWAY_INNER_V4 / descriptor "
            "inner_router_v4 to an address inside it.".format(network.prefixlen)
        )
    return network, None


def winn3_inner_pool() -> Optional[Any]:
    """The configured inner pool, or None -- reason logged -- when unusable.

    THE single validator. Every None is accompanied by an error line naming the
    value and the exact reason: malformed, IPv6, or the wrong width. A pool
    refused without a reason is the silent fleet-wide downgrade D15 removes.

    None degrades to "standalone v3 unavailable" everywhere it is consulted --
    never to an allocation from a guessed range. Since require_winn3_inner_pool()
    now refuses to start on exactly these inputs, the None path is unreachable
    in production and is kept as defence in depth: a 503 from an allocation
    would take down an ORDINARY winn/1 login, and v1 is the product while v3 is
    the addition.
    """
    network, reason = _winn3_inner_pool_or_reason()
    if network is None:
        logger.error("WINN3_INNER_POOL_CIDR=%s %s", WINN3_INNER_POOL_CIDR, reason)
        return None
    return network


def require_winn3_inner_pool() -> None:
    """Refuse to start when the pool is unusable. Called from startup_event().

    The guard CANNOT DISAGREE WITH ITS VALIDATOR: it asks winn3_inner_pool()
    and parses nothing itself. That is the durable half of D15 -- a second
    inline copy of the rule is precisely how one sentence of policy grew three
    behaviours -- so do not reintroduce an ipaddress call here.

    ACCEPTED COST: a control-plane restart with a malformed pool now fails
    loudly, winn/1 included. Deliberate, per the D7 precedent. An operator is
    watching a deploy when this fires; the alternative is a silent fleet-wide
    downgrade to winn/1 discovered weeks later, with the readiness path
    misreporting healthy descriptors as "outside pool" the whole time.
    """
    pool = winn3_inner_pool()
    if pool is None:
        _, reason = _winn3_inner_pool_or_reason()
        raise RuntimeError(
            "WINN3_INNER_POOL_CIDR={} {} Refusing to start.".format(
                WINN3_INNER_POOL_CIDR, reason)
        )
    # HOST BITS SET ARE ACCEPTED BUT NOT SILENTLY. ip_network(strict=False)
    # masks `10.10.0.5/24` to `10.10.0.0/24`, which is almost certainly what the
    # operator meant -- but silently normalising an operator's stated value is
    # the same class of quiet fixup D15 exists to remove, and the gateway is
    # stricter: parseForwardCIDR in cmd/winn3-gateway/main.go REFUSES a
    # -forward-cidr with host bits set and tells the operator to give the
    # network address. Warned rather than refused because the masked pool is
    # unambiguous and usable, and turning a working deploy into a failed one
    # over a cosmetic difference is a cost D15 did not license. Startup-only, so
    # it cannot become per-request log spam.
    declared = WINN3_INNER_POOL_CIDR.split("/", 1)[0].strip()
    try:
        if ipaddress.IPv4Address(declared) != pool.network_address:
            logger.warning(
                "WINN3_INNER_POOL_CIDR=%s has host bits set in the network "
                "portion and was read as %s. That is how it will be used. "
                "State the network address instead (%s) -- the gateway's own "
                "-forward-cidr refuses this shape rather than masking it, so "
                "the two configurations do not read alike.",
                WINN3_INNER_POOL_CIDR, pool, pool,
            )
    except ValueError:
        # Unreachable: the pool validated above, so the address half parses.
        pass


def winn3_inner_router_in_pool(inner_router_v4: str) -> bool:
    """Whether a descriptor's inner address lives in the hub's pool.

    Named for inner_router_v4 but true of any inner address checked against
    WINN3_INNER_POOL_CIDR -- used for both inner_router_v4 and
    inner_resolver_v4, same pool, same shape, no equality enforced.

    THE NETWORK AND BROADCAST ADDRESSES ARE NOT MEMBERS. This matches the
    gateway binary's own rule: cmd/winn3-gateway/main.go parseForwardCIDR
    refuses an -inner-v4 equal to the network or broadcast address of
    -forward-cidr, because `ip addr add` accepts either but neither is a usable
    host address. A plain `in pool` accepted both, so the hub could accept,
    store and serve a descriptor the gateway itself would refuse to start with
    -- and that mismatch surfaces only as a session that carries nothing.

    Consistent with allocate_winn3_inner_ip(), which issues pool.hosts() and so
    never hands out either address either. THAT CONSISTENCY DEPENDS ON THE /24
    PIN: at /31 pool.hosts() yields both the network and broadcast addresses,
    and at /32 it yields the single address which IS both, so relaxing the pin
    without revisiting this check would make the hub refuse addresses its own
    allocator issues. _winn3_inner_pool_or_reason() enforces the pin, and this
    is one of the reasons it is exact rather than a floor.
    """
    pool = winn3_inner_pool()
    if pool is None:
        return False
    try:
        address = ipaddress.IPv4Address(str(inner_router_v4 or "").strip())
    except ValueError:
        return False
    if address not in pool:
        return False
    if address == pool.network_address or address == pool.broadcast_address:
        return False
    return True


def allocate_winn3_inner_ip(conn: sqlite3.Connection) -> str:
    """A free inner address for one device, or "" when none can be issued.

    Returns "" rather than raising, and every caller treats "" as "standalone v3
    unavailable for this device". A 503 here would take down an ORDINARY winn/1
    login, which is the wrong trade: v3 is the addition, v1 is the product.
    """
    pool = winn3_inner_pool()
    if pool is None:
        return ""
    used = winn3_inner_addresses_in_use(conn)
    for candidate in pool.hosts():
        text = str(candidate)
        if text not in used:
            return text
    return ""


def winn3_inner_addresses_in_use(conn: sqlite3.Connection) -> set:
    """Every pool address the allocator must not issue: devices, gateways, canaries.

    The one implementation of that set: allocate_winn3_inner_ip() and the
    pool-usage guard (winn3_inner_slice_usage) both read it, so the alert and
    the allocator cannot disagree about how full a pool is.
    """
    used = {
        (row["winn3_inner_v4"] or "").strip()
        for row in conn.execute(
            "SELECT winn3_inner_v4 FROM devices WHERE winn3_inner_v4 IS NOT NULL"
        ).fetchall()
    }
    # Every inner address any node advertises (inner_router_v4, inner_resolver_v4)
    # is reserved: each is the gateway's own address inside the tunnel, and
    # issuing it to a device would collide the client with its own next hop or
    # its own resolver. Reserved exactly the same way for both -- shape-only via
    # WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS, in-pool checked on the serving path,
    # no equality enforced between the two (a -forward gateway may host DNS at a
    # second inner address).
    #
    # A-DEP-002 + F-02: addresses are reserved ONLY from descriptors that pass
    # winn3_stored_descriptor() -- shape, node binding AND signature
    # verification, the same checks the serving path enforces. This loop used
    # to raw-decode the stored envelope without any verification, so a forged
    # row (written without the ceremony key, or a tampered GCS-replica restore)
    # reserved addresses it had no right to: a write-capable attacker could
    # exhaust the /24 pool with junk descriptors and deny v3 to every later
    # device. A descriptor no client can be served must reserve no address
    # either. Unverified rows are skipped, never trusted.
    #
    # clock_tolerant=True (F-02): an EXPIRED but authentic descriptor still
    # reserves. Expiry is a serving control, not a gateway stop -- the node's
    # gateway keeps answering on its inner_router_v4 after the clock lapses --
    # so dropping the reservation would let the allocator hand a device the
    # address of a live gateway. The signature still verifies in full, so the
    # forged-row exhaustion attack stays closed through this path too.
    for row in conn.execute(
        "SELECT winn3_descriptor_json, slug FROM nodes WHERE winn3_descriptor_json IS NOT NULL"
    ).fetchall():
        decoded = winn3_stored_descriptor(row, clock_tolerant=True)
        if not decoded:
            continue
        for field in WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS:
            value = str(decoded.get(field) or "").strip()
            if value:
                used.add(value)
    # SYNC-03: a canary's inner address is published in its node's registry
    # beside the devices, and the registry build refuses a duplicate address,
    # so issuing it to a device would stop every registry push to that node.
    used.update(winn3_canary_reserved_inner_addresses())
    return used


# SYNC-06 guard (2026-09-29, round 2 per fable_ruling_sync08_sync06_20260929
# Q2, Stage 0). WINN3_INNER_POOL_CIDR is the fleet ENVELOPE; a node's POOL is
# the /24 containing its signed descriptor's inner_router_v4. Today the
# envelope is one /24, every node's router is 10.10.0.1, and every node shares
# that one slice, so each node's free count is the fleet's. This measures and
# alerts per node; it changes no allocation (the Stage 1 allocator is a
# separate lane).
WINN3_INNER_FREE_ALERT_BELOW = max(1, int(os.getenv("WINN3_INNER_FREE_ALERT_BELOW", "20") or 20))


def winn3_node_inner_slice(node: Any) -> Optional[Any]:
    """This node's inner pool: the /24 around its descriptor router, or None.

    The descriptor is read with clock_tolerant=True, as the allocator reads it:
    a gateway keeps its inner address after the descriptor clock lapses, so
    the slice it serves from does not move at expiry. The signature is still
    verified in full. A node without a verified descriptor falls back to the
    envelope when the envelope is itself a single /24 (the legacy shared
    slice), and has no slice otherwise. A router outside the envelope has no
    slice: winn3_descriptor_missing_or_invalid already names it.
    """
    envelope = winn3_inner_pool()
    if envelope is None:
        return None
    decoded = winn3_stored_descriptor(node, clock_tolerant=True)
    router = str((decoded or {}).get("inner_router_v4") or "").strip()
    if router:
        try:
            node_pool = ipaddress.ip_network(router + "/24", strict=False)
        except ValueError:
            return None
        return node_pool if node_pool.subnet_of(envelope) else None
    return envelope if envelope.prefixlen == 24 else None


def winn3_inner_slice_usage(conn: sqlite3.Connection, node_pool: Any,
                            in_use: Optional[set] = None) -> dict:
    """{"pool", "capacity", "used", "free"} for one node pool.

    Counted with the allocator's own in-use set (winn3_inner_addresses_in_use),
    so the alert and the allocator cannot disagree about how full a pool is.
    """
    hosts = {str(address) for address in node_pool.hosts()}
    used_set = (winn3_inner_addresses_in_use(conn) if in_use is None else in_use) & hosts
    return {
        "pool": str(node_pool),
        "capacity": len(hosts),
        "used": len(used_set),
        "free": len(hosts) - len(used_set),
    }


# RFC 8410 SubjectPublicKeyInfo prefix for X25519, and the PKCS#8 length for an
# X25519 private key. openssl emits both wrapped; winn/3 wants the RAW 32 bytes
# base64, which is what `[winn] static_private` and the descriptor's static_pub
# carry. Same shape of unwrapping as WINN3_ED25519_SPKI_PREFIX above, and the
# lengths are asserted rather than assumed so a future openssl that changed the
# encoding fails loudly instead of yielding 32 bytes of the wrong thing.
WINN3_X25519_SPKI_PREFIX = bytes.fromhex("302a300506032b656e032100")
WINN3_X25519_SPKI_BYTES = 44
WINN3_X25519_PKCS8_BYTES = 48
WINN3_X25519_KEY_BYTES = 32


def generate_winn3_static_material() -> tuple:
    """A fresh X25519 (private, public) pair, base64, for one device.

    openssl(1) rather than a Python library, for the reason already recorded at
    winn3_verify_descriptor_signature: control-plane-requirements.lock is
    hash-pinned and `cryptography` is not in it. openssl is already a hard
    dependency of this surface.

    DELIBERATELY NOT `wg genkey`. That tool would produce a perfectly valid
    X25519 scalar -- X25519 clamps at use time, so a clamped key and an
    unclamped one are both correct inputs -- but reaching for the WireGuard
    keygen to mint a winn/3 identity is precisely the coupling the standalone
    ruling removes, and the next reader would be entitled to wonder whether
    this key and client_private_key were the same thing. They are not, ever:
    separate column, separate name, separate protocol.

    Returns ("", "") on failure, which every caller treats as "standalone v3
    unavailable for this device". Never logs or returns the private half.
    """
    try:
        with tempfile.TemporaryDirectory() as work_dir:
            key_path = os.path.join(work_dir, "winn3_static.der")
            subprocess.run(
                ["openssl", "genpkey", "-algorithm", "X25519",
                 "-outform", "DER", "-out", key_path],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                check=True, timeout=15,
            )
            with open(key_path, "rb") as handle:
                pkcs8 = handle.read()
            spki = subprocess.run(
                ["openssl", "pkey", "-inform", "DER", "-in", key_path,
                 "-pubout", "-outform", "DER"],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                check=True, timeout=15,
            ).stdout
        if len(pkcs8) != WINN3_X25519_PKCS8_BYTES:
            raise ValueError("unexpected X25519 private key encoding")
        if len(spki) != WINN3_X25519_SPKI_BYTES or not spki.startswith(
            WINN3_X25519_SPKI_PREFIX
        ):
            raise ValueError("unexpected X25519 public key encoding")
        private_raw = pkcs8[-WINN3_X25519_KEY_BYTES:]
        public_raw = spki[-WINN3_X25519_KEY_BYTES:]
    except Exception:
        # Reason class only. Nothing about the key material, successful or not.
        logger.error(
            "could not generate winn/3 standalone static material; refusing "
            "rather than rewriting to winn/1"
        )
        return "", ""
    return (
        base64.b64encode(private_raw).decode(),
        base64.b64encode(public_raw).decode(),
    )


def _log_winn3_material_outcome(device_cfg: dict, reason: str) -> None:
    """One log line per outcome, the operator's counter for the ruling's
    Step 4 gate (winn3-material-issued must reach zero before the legacy mint
    is deleted). Device named by a short keyed-HMAC prefix; no key, no address.
    """
    material_correlator = security_event_hash(
        f"winn3-material-issue:{device_cfg.get('device_id') or ''}"
    )
    if reason == "winn3-material-issued":
        logger.info(
            "issued winn/3 standalone material for device %s outcome=winn3-material-issued",
            (material_correlator or "?")[:6],
        )
    else:
        logger.info(
            "winn/3 device material for device %s outcome=%s",
            (material_correlator or "?")[:6], reason,
        )


def ensure_winn3_device_material(
    conn: sqlite3.Connection,
    device_cfg: dict,
    requested_static_public: str = "",
    client_owns_key: bool = False,
) -> tuple:
    """(inner_v4, static_private, reason) for THIS device, provisioning if needed.

    LAZY ON PURPOSE. It is called only once the winn/3 gate and the descriptor
    gate have both already said yes, so a device that will never be served
    standalone v3 never consumes an inner address and never has a second private
    key minted for it. Every client in the field today is in that case.

    IDEMPOTENT. Once a device has material it keeps it: the address is what the
    gateway's session table is provisioned against and the public key is what it
    admits, so re-rolling either on an ordinary reconnect would silently strand
    the device -- the gateway would drop its packets and answer nothing.

    CLIENT-OWNED KEYS (Fable 5.1 ruling 2026-09-29). When the device supplied
    `requested_static_public` (already validated), the hub NEVER mints and
    NEVER serves a private key: it stores that public key, NULLs any private
    copy it still holds, and keeps an existing inner address when only the key
    changed. static_private is then "" and the caller echoes the public key.
    With no public supplied, the legacy mint runs only while
    WINN3_HUB_MINTED_KEYS_ALLOWED is on and the client did not claim to own
    its key; otherwise the reason is winn3-client-key-required.

    Returns ("", "", reason) when material cannot be issued. Every caller treats
    that as "no standalone v3 for this request" and serves winn/1, because a
    partial standalone config is a config the client refuses by name at best and
    a black hole at worst.
    """
    inner = (device_cfg.get("winn3_inner_v4") or "").strip()
    private_key = (device_cfg.get("winn3_static_private") or "").strip()
    public_key = (device_cfg.get("winn3_static_public") or "").strip()
    requested = (requested_static_public or "").strip()
    device_id = device_cfg.get("device_id") or ""

    if requested:
        if inner and public_key == requested:
            reason = "winn3-client-key-on-file"
            if private_key:
                # Never keep, and never serve, a hub copy of a key the device
                # says it owns.
                conn.execute(
                    "UPDATE devices SET winn3_static_private = NULL WHERE device_id = ?",
                    (device_id,),
                )
                device_cfg["winn3_static_private"] = ""
            _log_winn3_material_outcome(device_cfg, reason)
            return inner, "", reason
        if inner:
            # The key changed and the address is kept: the address is the
            # hub's allocation, the key is the device's. The registry snapshot
            # is a full replacement, so the old key stops being admitted when
            # the node is republished (the devices UPDATE trigger queues it).
            conn.execute("SAVEPOINT winn3_key_adopt")
            try:
                conn.execute(
                    "UPDATE devices SET winn3_static_public = ?, winn3_static_private = NULL "
                    "WHERE device_id = ?",
                    (requested, device_id),
                )
                conn.execute("RELEASE SAVEPOINT winn3_key_adopt")
            except sqlite3.IntegrityError as exc:
                conn.execute("ROLLBACK TO SAVEPOINT winn3_key_adopt")
                conn.execute("RELEASE SAVEPOINT winn3_key_adopt")
                if not winn3_static_public_conflict(exc):
                    raise
                return "", "", "winn3-static-public-in-use"
            device_cfg["winn3_static_public"] = requested
            device_cfg["winn3_static_private"] = ""
            reason = "winn3-client-key-adopted"
            _log_winn3_material_outcome(device_cfg, reason)
            return inner, "", reason
        private_key, public_key = "", requested
        issued_reason = "winn3-client-key-adopted"
    else:
        if client_owns_key or not WINN3_HUB_MINTED_KEYS_ALLOWED:
            reason = "winn3-client-key-required"
            _log_winn3_material_outcome(device_cfg, reason)
            return "", "", reason
        if inner and private_key and public_key:
            return inner, private_key, "winn3-material-on-file"
        issued_reason = "winn3-material-issued"
        if inner:
            # Legacy build on a row whose key the device used to own (a
            # client-key build was replaced by an older one). Mint a
            # replacement pair at the SAME address; only while the flag is on.
            private_key, public_key = generate_winn3_static_material()
            if not (private_key and public_key):
                return "", "", "winn3-static-material-unavailable"
            cursor = conn.execute(
                "UPDATE devices SET winn3_static_private = ?, winn3_static_public = ? "
                "WHERE device_id = ? AND winn3_inner_v4 = ?",
                (private_key, public_key, device_id, inner),
            )
            if int(cursor.rowcount or 0) == 0:
                return "", "", "winn3-device-row-changed-during-allocation"
            device_cfg["winn3_static_private"] = private_key
            device_cfg["winn3_static_public"] = public_key
            _log_winn3_material_outcome(device_cfg, issued_reason)
            return inner, private_key, issued_reason

    if not inner:
        inner = allocate_winn3_inner_ip(conn)
        if not inner:
            return "", "", "winn3-inner-pool-exhausted-or-unconfigured"
    if not requested and not (private_key and public_key):
        private_key, public_key = generate_winn3_static_material()
        if not (private_key and public_key):
            return "", "", "winn3-static-material-unavailable"

    # The UNIQUE index is the authority. Allocation's SELECT is only a
    # candidate search and two hub workers may choose the same candidate before
    # either writes it. A savepoint lets the loser retry without rolling back
    # the surrounding activation transaction.
    claim_pool = winn3_inner_pool()
    if claim_pool is None:
        return "", "", "winn3-inner-pool-exhausted-or-unconfigured"
    max_claim_attempts = max(1, int(claim_pool.num_addresses))
    for _claim_attempt in range(max_claim_attempts):
        conn.execute("SAVEPOINT winn3_inner_claim")
        try:
            cursor = conn.execute(
                "UPDATE devices SET winn3_inner_v4 = ?, winn3_static_private = ?,"
                " winn3_static_public = ? WHERE device_id = ? AND "
                "(winn3_inner_v4 IS NULL OR TRIM(winn3_inner_v4) = '')",
                (inner, private_key or None, public_key, device_id),
            )
            conn.execute("RELEASE SAVEPOINT winn3_inner_claim")
        except sqlite3.IntegrityError as exc:
            conn.execute("ROLLBACK TO SAVEPOINT winn3_inner_claim")
            conn.execute("RELEASE SAVEPOINT winn3_inner_claim")
            if winn3_static_public_conflict(exc):
                return "", "", "winn3-static-public-in-use"
            if "devices.winn3_inner_v4" not in str(exc):
                raise
            inner = allocate_winn3_inner_ip(conn)
            if not inner:
                return "", "", "winn3-inner-pool-exhausted-or-unconfigured"
            continue
        if int(cursor.rowcount or 0) == 0:
            # A concurrent activation of this same device won. Return exactly
            # its durable tuple rather than overwriting it with our candidate.
            stored = conn.execute(
                "SELECT winn3_inner_v4, winn3_static_private, winn3_static_public "
                "FROM devices WHERE device_id = ?",
                (device_id,),
            ).fetchone()
            stored_inner = str((stored["winn3_inner_v4"] if stored else "") or "").strip()
            stored_private = str((stored["winn3_static_private"] if stored else "") or "").strip()
            stored_public = str((stored["winn3_static_public"] if stored else "") or "").strip()
            if requested and stored_inner and stored_public == requested:
                inner, private_key, public_key = stored_inner, "", requested
            elif not requested and stored_inner and stored_private and stored_public:
                inner, private_key, public_key = stored_inner, stored_private, stored_public
            else:
                return "", "", "winn3-device-row-changed-during-allocation"
        break
    else:
        return "", "", "winn3-inner-allocation-contention"
    device_cfg["winn3_inner_v4"] = inner
    device_cfg["winn3_static_private"] = private_key
    device_cfg["winn3_static_public"] = public_key
    # A hub-minted private key is served to its own device and appears in no
    # log line anywhere, on the same terms as client_private_key beside it. A
    # client-owned key has no private half here at all. The outcome is
    # logged; the material is not (see _log_winn3_material_outcome).
    _log_winn3_material_outcome(device_cfg, issued_reason)
    return inner, private_key, issued_reason


def resolve_served_winn3_device_config(
    conn: sqlite3.Connection,
    device_cfg: dict,
    *,
    descriptor_envelope: dict,
    requested_static_public: str = "",
    client_owns_key: bool = False,
) -> tuple:
    """The per-device half of a standalone config. Returns (fields, reason).

    `fields` is either empty or carries `winn3_inner_v4` AND
    `winn3_static_public`, plus `winn3_static_private`, which is non-empty only
    on the legacy hub-minted path and "" for a client-owned key (the device
    attaches its own). There is no partial state: the client needs all six
    key-bearing `[winn]` fields to start, so half of them is a refusal with
    extra steps.

    THE POOL CHECK IS THE ONE BINDING THE HUB CAN VERIFY. The descriptor names
    the gateway's inner next hop; the hub allocates the client's inner address.
    If they are not in the same space the session establishes and carries
    nothing, and neither end can tell -- so a mismatch refuses here.
    """
    if not descriptor_envelope:
        return {}, "no-descriptor"
    try:
        decoded = json.loads(
            base64.b64decode(descriptor_envelope["payload"], validate=True).decode("utf-8")
        )
    except Exception:
        return {}, "descriptor-unreadable"
    router = str((decoded or {}).get("inner_router_v4") or "").strip()
    if not winn3_inner_router_in_pool(router):
        # Named, not silent. An operator who moved the gateway's inner space
        # without moving WINN3_INNER_POOL_CIDR sees this in the readiness
        # report. The verify path then refuses rather than rewriting to winn/1.
        logger.error(
            "winn/3 descriptor inner next hop is not a usable address in "
            "WINN3_INNER_POOL_CIDR (%s); refusing rather than rewriting to "
            "winn/1. Either it is outside "
            "the pool -- the gateway's inner space and the hub's allocation "
            "pool must be the same space -- or it is the pool's network or "
            "broadcast address, which the gateway itself refuses as an "
            "-inner-v4 (parseForwardCIDR in cmd/winn3-gateway/main.go), so a "
            "descriptor naming one could never have been served.",
            WINN3_INNER_POOL_CIDR,
        )
        return {}, "inner-router-outside-hub-pool"
    resolver = str((decoded or {}).get("inner_resolver_v4") or "").strip()
    if not winn3_inner_router_in_pool(resolver):
        # Same check, same shape-only discipline, same pool -- but a distinct
        # reason string so the operator can tell which field is outside. Do NOT
        # enforce resolver == router: a -forward gateway may host DNS at a
        # second inner address and the explicit field preserves that.
        logger.error(
            "winn/3 descriptor inner resolver is not a usable address in "
            "WINN3_INNER_POOL_CIDR (%s); refusing rather than rewriting to "
            "winn/1. Either it is outside "
            "the pool -- the gateway's resolver and the hub's allocation pool "
            "must be the same space -- or it is the pool's network or "
            "broadcast address, which is not an address anything can answer "
            "DNS at.",
            WINN3_INNER_POOL_CIDR,
        )
        return {}, "inner-resolver-outside-hub-pool"
    if resolver != router:
        logger.error(
            "winn/3 descriptor inner resolver does not equal inner next hop; "
            "the shipping gateway resolver binds only to -inner-v4. Refusing "
            "rather than rewriting to winn/1."
        )
        return {}, "inner-resolver-does-not-match-gateway-bind"
    inner, private_key, reason = ensure_winn3_device_material(
        conn,
        device_cfg,
        requested_static_public=requested_static_public,
        client_owns_key=client_owns_key,
    )
    public_key = (device_cfg.get("winn3_static_public") or "").strip()
    if not (inner and public_key):
        return {}, reason
    if not private_key and not (requested_static_public or "").strip():
        # A legacy request must receive its private half; a client-key request
        # must receive none. Anything else is the partial state refused above.
        return {}, reason
    if private_key and (requested_static_public or "").strip():
        return {}, "winn3-private-for-client-key"
    return {
        # NOT protocol_params keys, and this is the whole point of item (C):
        # WINN3_PARAM_NAME_NEVER_SERVED matches `static_private` and would
        # refuse it there by design. These sit in vpn_config beside
        # client_private_key, which is the surface that already carries a
        # per-device private key to its own device over the authenticated
        # session.
        "winn3_inner_v4": inner,
        "winn3_static_private": private_key,
        # The echo the client-key app binds against (winn3_key_mismatch).
        "winn3_static_public": public_key,
    }, "winn3-device-config"


def allocate_core_client_ip(conn: sqlite3.Connection) -> str:
    used = {
        row["client_ip"]
        for row in conn.execute("SELECT client_ip FROM double_vpn_assignments WHERE client_ip IS NOT NULL").fetchall()
        if row["client_ip"]
    }
    reserved = {"10.9.1.1"}
    for x in range(1, 256):
        for y in range(2, 255):
            candidate = f"10.9.{x}.{y}"
            if candidate not in used and candidate not in reserved:
                return candidate
    raise HTTPException(status_code=503, detail="No Double VPN core addresses available.")

def allocate_core_exit_ip(conn: sqlite3.Connection) -> str:
    used = {
        row["core_exit_ip"]
        for row in conn.execute("SELECT core_exit_ip FROM core_exit_peers WHERE core_exit_ip IS NOT NULL").fetchall()
        if row["core_exit_ip"]
    }
    for y in range(2, 255):
        candidate = f"10.8.255.{y}"
        # H5: an explicit reserved set (the AWG canary address), independent of
        # where the range starts, so a later range change cannot issue it.
        if candidate in AWG_CORE_EXIT_RESERVED_ADDRESSES:
            continue
        if candidate not in used:
            return candidate
    raise HTTPException(status_code=503, detail="No Double VPN exit peer addresses available.")

def next_core_exit_index(conn: sqlite3.Connection, core_id: str) -> int:
    rows = conn.execute("SELECT table_id, iface FROM core_exit_peers WHERE core_id = ?", (core_id,)).fetchall()
    used = set()
    for row in rows:
        if row["table_id"]:
            used.add(max(0, int(row["table_id"]) - 52000))
        iface = row["iface"] or ""
        match = re.match(r"^corex(\d+)$", iface)
        if match:
            used.add(int(match.group(1)))
    for idx in range(1, 512):
        if idx not in used:
            return idx
    raise HTTPException(status_code=503, detail="No Double VPN route table slots available.")

CORE_SELF_READY_SQL = """
status = 'online'
AND runtime_ready = 1
AND deployment_withdrawal_id IS NULL
AND management_status = 'ok'
AND management_checked_at IS NOT NULL AND management_checked_at >= ?
AND last_heartbeat IS NOT NULL AND last_heartbeat >= ?
AND runtime_checked_at IS NOT NULL AND runtime_checked_at >= ?
AND ingress_endpoint IS NOT NULL AND ingress_endpoint != ''
AND tunnel_gateway_ipv4 IS NOT NULL AND tunnel_gateway_ipv4 != ''
AND ingress_public_key IS NOT NULL AND ingress_public_key != ''
AND exit_public_key IS NOT NULL AND exit_public_key != ''
AND regional_aliases IS NOT NULL
AND direct_awg_enabled IN (0, 1)
"""


def core_promotion_readiness_failures(row: sqlite3.Row, cutoff: str) -> list[str]:
    failures: list[str] = []
    if str(row["deployment_withdrawal_id"] or "").strip():
        failures.append("installer deployment withdrawal is active")
    if str(row["status"] or "").strip().lower() != "online":
        failures.append("core heartbeat is not online")
    if not bool(row["runtime_ready"]):
        failures.append("core runtime is not ready")
    if str(row["management_status"] or "").strip().lower() != "ok":
        failures.append("management verification is not ok")
    if not row["management_checked_at"] or str(row["management_checked_at"]) < cutoff:
        failures.append("management verification is absent or stale")
    if not row["last_heartbeat"] or str(row["last_heartbeat"]) < cutoff:
        failures.append("core heartbeat is absent or stale")
    if not row["runtime_checked_at"] or str(row["runtime_checked_at"]) < cutoff:
        failures.append("runtime verification is absent or stale")
    for column, label in (
        ("ingress_endpoint", "ingress endpoint"),
        ("tunnel_gateway_ipv4", "tunnel gateway"),
        ("ingress_public_key", "ingress public key"),
        ("exit_public_key", "exit public key"),
    ):
        if not str(row[column] or "").strip():
            failures.append(f"{label} is absent")
    if row["regional_aliases"] is None:
        failures.append("regional aliases metadata is absent")
    if row["direct_awg_enabled"] not in (0, 1):
        failures.append("direct AWG policy is invalid")
    return failures


def select_double_vpn_core(conn: sqlite3.Connection) -> Optional[sqlite3.Row]:
    if not DOUBLE_VPN_ENABLED:
        return None
    cutoff = (utcnow() - timedelta(seconds=DOUBLE_VPN_CORE_STALE_SECONDS)).isoformat()
    return conn.execute(
        f"""
        SELECT * FROM core_servers
        WHERE core_id = ?
          AND promoted = 1
          AND active_promotion_id IS NOT NULL
          AND {CORE_SELF_READY_SQL}
          AND EXISTS (
            SELECT 1 FROM nodes n
            WHERE n.status = 'online'
              AND n.management_status = 'ok'
              AND COALESCE(n.operator_enabled, 0) = 1
              AND n.retired_at IS NULL
              {DATA_PLANE_AVAILABLE_SQL_N}
              AND n.endpoint IS NOT NULL AND n.endpoint != ''
              AND n.public_key IS NOT NULL AND n.public_key != ''
          )
        """,
        (DOUBLE_VPN_CORE_ID, cutoff, cutoff, cutoff),
    ).fetchone()

def mark_stale_nodes_offline(conn: sqlite3.Connection) -> None:
    """Atomically close stale production latches and their live assignments.

    Callers that refresh heartbeat timestamps must invoke this while holding the
    same write transaction and before writing the fresh timestamp. Once either
    latch reaches zero, routine registration preserves zero; only a new
    evidence-bearing admin promotion, or (L84, when enabled) the automatic
    reopen of an automatic health closure through the same readiness gate,
    can advertise that role again. Every Data closure here is marked as an
    automatic health closure; the transition trigger records and the hub
    alerts on each one. A single probe_error run no longer closes: it takes
    DATA_PLANE_PROBE_ERROR_CLOSE_STREAK consecutive runs (new selection
    already excludes the node from the first one).
    """
    now_iso = utcnow().isoformat()
    node_cutoff = (
        utcnow() - timedelta(seconds=NODE_HEARTBEAT_STALE_SECONDS)
    ).isoformat()
    core_cutoff = (
        utcnow() - timedelta(seconds=DOUBLE_VPN_CORE_STALE_SECONDS)
    ).isoformat()
    data_cutoff = (
        utcnow() - timedelta(minutes=DATA_PLANE_HARD_STALE_MINUTES)
    ).isoformat()

    # Read-only pre-check. Every UPDATE below is a writer even when it matches
    # no row, and a writer waits behind whichever /verify currently holds the
    # lock through its node pushes (up to three 15-second SSH sessions). The
    # public reads (/nodes, /free/status, the site snapshot) call this on every
    # request, so without this check one slow node push stalls the server list
    # for everyone and, past busy_timeout, fails it. The predicate is a SUPERSET
    # of every WHERE below, on the same cutoffs: when it finds nothing, no
    # UPDATE could match and the write lock is never taken; when it finds
    # anything, the statements run exactly as before. Callers that already
    # hold BEGIN IMMEDIATE see no difference.
    due = conn.execute(
        """
        SELECT 1 WHERE EXISTS (
            SELECT 1 FROM nodes
            WHERE retired_at IS NULL
              AND (
                ((last_heartbeat IS NULL OR last_heartbeat < ?)
                 AND (status != 'offline' OR COALESCE(operator_enabled, 0) != 0))
                OR (COALESCE(operator_enabled, 0) = 1
                    AND (COALESCE(data_plane_status, 'unknown') IN ('unreachable', 'probe_error')
                         OR (data_plane_ok_at IS NOT NULL AND data_plane_ok_at < ?)))
              )
        ) OR EXISTS (
            SELECT 1 FROM double_vpn_assignments a
            JOIN nodes n ON n.slug = a.exit_slug
            WHERE a.status = 'active' AND n.retired_at IS NULL
              AND (n.last_heartbeat IS NULL OR n.last_heartbeat < ?
                   OR COALESCE(n.data_plane_status, 'unknown') IN ('unreachable', 'probe_error')
                   OR (n.data_plane_ok_at IS NOT NULL AND n.data_plane_ok_at < ?))
        ) OR EXISTS (
            SELECT 1 FROM core_servers
            WHERE (COALESCE(promoted, 0) = 1 OR pending_promotion_id IS NOT NULL)
              AND (last_heartbeat IS NULL OR last_heartbeat < ?
                   OR runtime_checked_at IS NULL OR runtime_checked_at < ?
                   OR management_checked_at IS NULL OR management_checked_at < ?)
        )
        """,
        (node_cutoff, data_cutoff, node_cutoff, data_cutoff, core_cutoff, core_cutoff, core_cutoff),
    ).fetchone()
    if due is None:
        return

    stale_data_sql = """
        COALESCE(operator_enabled, 0) = 1
        AND (
            COALESCE(data_plane_status, 'unknown') = 'unreachable'
            OR (
                COALESCE(data_plane_status, 'unknown') = 'probe_error'
                AND COALESCE(data_plane_probe_error_streak, 0) >= ?
            )
            OR (data_plane_ok_at IS NOT NULL AND data_plane_ok_at < ?)
        )
    """
    health_reason_sql = """
        CASE
            WHEN COALESCE(data_plane_status, 'unknown') = 'unreachable' THEN 'unreachable'
            WHEN COALESCE(data_plane_status, 'unknown') = 'probe_error'
                 AND COALESCE(data_plane_probe_error_streak, 0) >= ? THEN 'probe_error_streak'
            ELSE 'proof_stale'
        END
    """

    conn.execute(
        """
        UPDATE double_vpn_assignments
        SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL,
            updated_at=?
        WHERE status='active' AND exit_slug IN (
            SELECT slug FROM nodes
            WHERE retired_at IS NULL
              AND (
                last_heartbeat IS NULL OR last_heartbeat < ?
                OR (
                  COALESCE(operator_enabled, 0) = 1
                  AND (
                    COALESCE(data_plane_status, 'unknown') = 'unreachable'
                    OR (
                      COALESCE(data_plane_status, 'unknown') = 'probe_error'
                      AND COALESCE(data_plane_probe_error_streak, 0) >= ?
                    )
                    OR (data_plane_ok_at IS NOT NULL AND data_plane_ok_at < ?)
                  )
                )
              )
        )
        """,
        (now_iso, node_cutoff, DATA_PLANE_PROBE_ERROR_CLOSE_STREAK, data_cutoff),
    )
    conn.execute(
        f"""
        UPDATE nodes
        SET operator_enabled=0,
            health_closed_at=?,
            health_closed_reason={health_reason_sql},
            latch_cause='health_' || {health_reason_sql},
            data_plane_green_streak=0,
            data_plane_green_since=NULL
        WHERE retired_at IS NULL AND {stale_data_sql}
        """,
        (now_iso, DATA_PLANE_PROBE_ERROR_CLOSE_STREAK, DATA_PLANE_PROBE_ERROR_CLOSE_STREAK,
         DATA_PLANE_PROBE_ERROR_CLOSE_STREAK, data_cutoff),
    )
    # SET expressions read the pre-update row, so only a 1->0 flip here is
    # marked as an automatic closure; a row that is already 0 keeps whatever
    # closure (operator or health) it already carries.
    # FINAL4 F4-HL: each automatic closure here ends the healthy-proof streak
    # in the same write (as HL-F3 did for fresh_install, installer_rerun and
    # the re-bootstrap). The reopen gate counts only a streak that began after
    # the closure; a kept streak would carry its pre-closure green_since into
    # the next green probe and hold the node. A row that was already closed
    # keeps a streak that began after its own closure.
    conn.execute(
        """
        UPDATE nodes
        SET status='offline',
            health_closed_at=CASE WHEN COALESCE(operator_enabled, 0) = 1
                                  THEN ? ELSE health_closed_at END,
            health_closed_reason=CASE WHEN COALESCE(operator_enabled, 0) = 1
                                      THEN 'heartbeat_stale' ELSE health_closed_reason END,
            latch_cause=CASE WHEN COALESCE(operator_enabled, 0) = 1
                             THEN 'health_heartbeat_stale' ELSE latch_cause END,
            data_plane_green_streak=CASE WHEN COALESCE(operator_enabled, 0) = 1
                                         THEN 0 ELSE data_plane_green_streak END,
            data_plane_green_since=CASE WHEN COALESCE(operator_enabled, 0) = 1
                                        THEN NULL ELSE data_plane_green_since END,
            operator_enabled=0
        WHERE retired_at IS NULL
          AND (last_heartbeat IS NULL OR last_heartbeat < ?)
          AND (status != 'offline' OR COALESCE(operator_enabled, 0) != 0)
        """,
        (now_iso, node_cutoff),
    )

    stale_core_sql = """
        (COALESCE(promoted, 0) = 1 OR pending_promotion_id IS NOT NULL)
        AND (
            last_heartbeat IS NULL OR last_heartbeat < ?
            OR runtime_checked_at IS NULL OR runtime_checked_at < ?
            OR management_checked_at IS NULL OR management_checked_at < ?
        )
    """
    conn.execute(
        f"""
        UPDATE double_vpn_assignments
        SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL,
            updated_at=?
        WHERE status='active' AND core_id IN (
            SELECT core_id FROM core_servers WHERE {stale_core_sql}
        )
        """,
        (now_iso, core_cutoff, core_cutoff, core_cutoff),
    )
    conn.execute(
        f"""
        UPDATE core_servers
        SET status='offline', runtime_ready=0, promoted=0,
            pending_promotion_id=NULL,
            pending_promotion_evidence_sha256=NULL,
            pending_promotion_operator_source_hash=NULL,
            pending_promotion_requested_at=NULL,
            active_promotion_id=NULL
        WHERE {stale_core_sql}
        """,
        (core_cutoff, core_cutoff, core_cutoff),
    )

def close_data_plane_promotion(
    conn: sqlite3.Connection, slug: str, now_iso: str, cause: str = "operator_closure"
) -> int:
    """Close Data policy and assignments inside the caller's transaction.

    Every caller is an operator or installer action, so this also clears any
    automatic-health-closure mark: an operator closure is never reopened
    automatically (L84)."""
    conn.execute(
        "UPDATE nodes SET operator_enabled=0, latch_cause=?, "
        "health_closed_at=NULL, health_closed_reason=NULL WHERE slug=?",
        (cause, slug),
    )
    invalidated = conn.execute(
        "UPDATE double_vpn_assignments "
        "SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL, updated_at=? "
        "WHERE exit_slug=? AND status='active'",
        (now_iso, slug),
    )
    return max(0, int(invalidated.rowcount or 0))

def close_core_promotion(
    conn: sqlite3.Connection, core_id: str, now_iso: str
) -> int:
    """Close Core policy, pending generations, and assignments atomically."""
    conn.execute(
        "UPDATE core_servers SET promoted=0, runtime_ready=0, "
        "pending_promotion_id=NULL, pending_promotion_evidence_sha256=NULL, "
        "pending_promotion_operator_source_hash=NULL, pending_promotion_requested_at=NULL, "
        "active_promotion_id=NULL WHERE core_id=?",
        (core_id,),
    )
    invalidated = conn.execute(
        "UPDATE double_vpn_assignments "
        "SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL, updated_at=? "
        "WHERE core_id=? AND status='active'",
        (now_iso, core_id),
    )
    return max(0, int(invalidated.rowcount or 0))

def ensure_core_exit_peer(conn: sqlite3.Connection, core_id: str, exit_slug: str) -> sqlite3.Row:
    row = conn.execute(
        "SELECT * FROM core_exit_peers WHERE core_id = ? AND exit_slug = ?",
        (core_id, exit_slug),
    ).fetchone()
    if row:
        return row
    idx = next_core_exit_index(conn, core_id)
    now = utcnow().isoformat()
    conn.execute(
        """
        INSERT INTO core_exit_peers (core_id, exit_slug, core_exit_ip, table_id, iface, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (core_id, exit_slug, allocate_core_exit_ip(conn), 52000 + idx, f"corex{idx}", now),
    )
    return conn.execute(
        "SELECT * FROM core_exit_peers WHERE core_id = ? AND exit_slug = ?",
        (core_id, exit_slug),
    ).fetchone()

CORE_ASSIGNMENT_REVISION_FIELDS = (
    "device_id", "core_id", "exit_slug", "client_public_key", "client_ip",
    "preshared_key", "core_exit_ip", "table_id", "iface", "exit_endpoint",
    "exit_public_key", "exit_wg_port", "exit_stealth_endpoint", "exit_xray_uuid",
    "exit_xray_path", "exit_xray_security", "exit_xray_sni",
    "exit_xray_transports", "exit_direct_awg_enabled", "authority_expires_at_epoch", "traffic_tier",
)

def core_assignment_revision(assignment: dict[str, Any]) -> str:
    canonical = {
        field: assignment.get(field)
        for field in CORE_ASSIGNMENT_REVISION_FIELDS
    }
    encoded = json.dumps(
        canonical, sort_keys=True, separators=(",", ":"), ensure_ascii=True
    ).encode()
    secret = (MANAGEMENT_NAME_HMAC_KEY or ADMIN_SECRET_TOKEN).encode()
    return hmac.new(secret, b"core-assignment-v1\0" + encoded, hashlib.sha256).hexdigest()

def active_core_assignment_payloads(
    conn: sqlite3.Connection, core_id: str
) -> list[dict[str, Any]]:
    now = utcnow()
    rows = conn.execute(
        """
        SELECT
            a.device_id, a.account_number, a.core_id, a.exit_slug, a.client_public_key,
            a.client_ip, a.preshared_key, a.status, a.updated_at,
            e.core_exit_ip, e.table_id, e.iface,
            n.name AS exit_name, n.endpoint AS exit_endpoint,
            n.public_key AS exit_public_key, n.wg_port AS exit_wg_port,
            n.status AS exit_status, n.stealth_endpoint AS exit_stealth_endpoint,
            n.xray_uuid AS exit_xray_uuid, n.xray_path AS exit_xray_path,
            n.xray_security AS exit_xray_security, n.xray_sni AS exit_xray_sni,
            n.stealth_public_port AS exit_stealth_public_port,
            n.stealth_transports AS exit_stealth_transports,
            n.direct_awg_enabled AS exit_direct_awg_enabled,
            n.obfuscation_json AS exit_obfuscation_json,
            u.expiration_date, u.renewal_source
        FROM double_vpn_assignments a
        JOIN devices d ON d.device_id = a.device_id AND d.account_number = a.account_number
        JOIN users u ON u.account_number = a.account_number
        JOIN core_exit_peers e ON e.core_id = a.core_id AND e.exit_slug = a.exit_slug
        JOIN nodes n ON n.slug = a.exit_slug
        WHERE a.core_id = ?
          AND a.status = 'active'
          AND u.status = 'active'
          AND n.status NOT IN ('offline', 'maintenance')
          AND n.retired_at IS NULL
          AND COALESCE(n.operator_enabled, 0) = 1
        """,
        (core_id,),
    ).fetchall()
    assignments: list[dict[str, Any]] = []
    for row in rows:
        expiry = parse_iso_datetime(row["expiration_date"])
        if expiry is None or expiry <= now:
            continue
        try:
            exit_obfuscation = parse_obfuscation(row["exit_obfuscation_json"])
        except ObfuscationProfileError as exc:
            # SYNC-02: the Core would have to guess the exit's parameters, and
            # a guess is a silent handshake failure. Withhold the assignment;
            # the login then fails as "still being prepared". Names only.
            logger.error(
                "withholding Double VPN assignment for exit %s: obfuscation registration is unusable (reason=%s keys=%s)",
                row["exit_slug"], exc.reason, ",".join(exc.keys) or "-",
            )
            continue
        assignment = {
            "device_id": row["device_id"],
            "account_number_hash": security_event_hash(row["account_number"]),
            "core_id": row["core_id"],
            "exit_slug": row["exit_slug"],
            "client_public_key": row["client_public_key"],
            "client_ip": row["client_ip"],
            "traffic_tier": freecap_tier(row["account_number"], row["expiration_date"], str(row["renewal_source"] or "")),
            "preshared_key": row["preshared_key"] or "",
            "core_exit_ip": row["core_exit_ip"],
            "table_id": int(row["table_id"] or 0),
            "iface": row["iface"],
            "exit_name": row["exit_name"],
            "exit_endpoint": row["exit_endpoint"],
            "exit_public_key": row["exit_public_key"],
            "exit_wg_port": int(row["exit_wg_port"] or 9110),
            "exit_status": row["exit_status"],
            "exit_stealth_endpoint": row["exit_stealth_endpoint"] or "",
            "exit_xray_uuid": row["exit_xray_uuid"] or "",
            "exit_xray_path": row["exit_xray_path"] or "/wins-stealth-tunnel",
            "exit_xray_security": (row["exit_xray_security"] or "none").lower(),
            "exit_xray_sni": row["exit_xray_sni"] or "",
            "exit_xray_transports": parse_xray_transports(
                row["exit_stealth_transports"],
                int(row["exit_stealth_public_port"] or 80),
                (row["exit_xray_security"] or "none").lower(),
                keep_plaintext=True,
            ),
            "exit_direct_awg_enabled": bool(
                row["exit_direct_awg_enabled"]
                if row["exit_direct_awg_enabled"] is not None else 1
            ),
            "exit_obfuscation": exit_obfuscation,
            "updated_at": row["updated_at"],
            "authority_expires_at_epoch": int(expiry.timestamp()),
        }
        assignment["assignment_revision"] = core_assignment_revision(assignment)
        assignments.append(assignment)
    return assignments

# SYNC-02: the Core renders the exit's AmneziaWG profile into corexN, so a
# changed exit profile must change the revision the Core acknowledges.
CORE_ASSIGNMENT_REVISION_FIELDS = CORE_ASSIGNMENT_REVISION_FIELDS + ("exit_obfuscation",)

async def wait_for_core_assignment_ready(
    core_id: str, device_id: str, expected_revision: str
) -> bool:
    return await asyncio.to_thread(
        _wait_for_core_assignment_ready_sync, core_id, device_id, expected_revision
    )


def _wait_for_core_assignment_ready_sync(
    core_id: str, device_id: str, expected_revision: str
) -> bool:
    if not re.fullmatch(r"[0-9a-f]{64}", expected_revision or ""):
        return False
    deadline = time.monotonic() + DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_SECONDS
    while True:
        cutoff = (utcnow() - timedelta(seconds=DOUBLE_VPN_CORE_STALE_SECONDS)).isoformat()
        with get_db() as ready_conn:
            current_assignment = next(
                (
                    item
                    for item in active_core_assignment_payloads(ready_conn, core_id)
                    if item["device_id"] == device_id
                ),
                None,
            )
            row = ready_conn.execute(
                """
                SELECT a.applied_revision, a.runtime_validated_at, a.status,
                       c.runtime_ready, c.status AS core_status,
                       c.last_heartbeat, c.runtime_checked_at
                FROM double_vpn_assignments a
                JOIN core_servers c ON c.core_id = a.core_id
                WHERE a.core_id = ? AND a.device_id = ?
                """,
                (core_id, device_id),
            ).fetchone()
        if (
            row
            and current_assignment
            and hmac.compare_digest(
                current_assignment["assignment_revision"], expected_revision
            )
            and row["status"] == "active"
            and row["core_status"] == "online"
            and int(row["runtime_ready"] or 0) == 1
            and hmac.compare_digest(row["applied_revision"] or "", expected_revision)
            and (row["runtime_validated_at"] or "") >= cutoff
            and (row["last_heartbeat"] or "") >= cutoff
            and (row["runtime_checked_at"] or "") >= cutoff
        ):
            return True
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return False
        time.sleep(min(0.5, remaining))

# ---------------------------------------------------------------------------
# w3r/1: ciphertext relay Double VPN ("B: Core relays").
#
# The phone's winn3 session terminates at the EXIT's own winn3-gateway exactly
# as in single hop (the exit's own signed descriptor, the phone's own admission
# at the exit). The Core only forwards ciphertext datagrams from one UDP port
# per exit to that exit's signed endpoint. The hub therefore serves a relay
# Double VPN as a plain single-hop winn/3 response plus the Double labels and
# one unsigned path field (winn3_relay), writes no Core assignment and waits
# for no Core acknowledgement. Every gate below fails to TODAY's behaviour
# (the AmneziaWG Double VPN), which is also the rollback.
#
#   WINN3_RELAY_ENABLED                  hub env, "1" to allow it at all
#   WINN3_RELAY_PORT_RANGE               ONE value, "MIN-MAX", default 9211-9218: the ports the
#                                        owner's router forwards to the Core. The Core reads the
#                                        same text from CORE_RELAY_PORT_RANGE and the two sides
#                                        check each other (port_range_mismatch keeps the relay off).
#   WINN3_RELAY_REPORT_MAX_AGE_SECONDS   freshness of the Core's relay report
#   core_relay_exits.enabled             per (Core, exit) switch, admin route
# ---------------------------------------------------------------------------
WINN3_RELAY_CAPABILITY = "supports_winn3_relay"
WINN3_RELAY_ENABLED = (os.getenv("WINN3_RELAY_ENABLED") or "0").strip() == "1"
# The ports the relay range may never contain: the Core AmneziaWG ingress and
# the data plane's AmneziaWG and winn3 listeners.
WINN3_RELAY_FORBIDDEN_PORTS = frozenset({9210, 9110, 9111})
WINN3_RELAY_PORT_RANGE_DEFAULT = "9211-9218"
WINN3_RELAY_PORT_RANGE_PATTERN = re.compile(r"[0-9]{4,5}-[0-9]{4,5}")
WINN3_RELAY_MAX_RANGE_WIDTH = 64
WINN3_RELAY_REPORT_MAX_LISTENS = 32
WINN3_RELAY_REPORT_MAX_BYTES = 4096
WINN3_RELAY_SLUG_PATTERN = re.compile(r"[a-z0-9][a-z0-9-]{1,39}")
WINN3_RELAY_IFACE_PATTERN = re.compile(r"[A-Za-z0-9_.:-]{1,15}")
WINN3_RELAY_REASON_PATTERN = re.compile(r"[a-z0-9_]{1,40}")
WINN3_RELAY_BLOCKERS = (
    "relay_flag_off",
    "core_not_ready",
    "report_missing",
    "report_stale",
    "report_inactive",
    "listen_missing",
    "listen_down",
    "ingress_host_not_ipv4_literal",
    "exit_not_winn3",
    "exit_descriptor_missing",
    "port_range_mismatch",
    "winn3_inner_pool_exhausted",
)


def winn3_relay_parse_range(raw: Any) -> Optional[tuple]:
    """(min, max) for a "MIN-MAX" text, or None. The ONE range rule of the relay,
    used for the hub's own environment value and for the range a Core reports."""
    text = str(raw).strip() if isinstance(raw, str) else ""
    if not WINN3_RELAY_PORT_RANGE_PATTERN.fullmatch(text):
        return None
    low_text, high_text = text.split("-")
    low, high = int(low_text), int(high_text)
    if not (1024 <= low <= high <= 65535) or (high - low + 1) > WINN3_RELAY_MAX_RANGE_WIDTH:
        return None
    if any(low <= port <= high for port in WINN3_RELAY_FORBIDDEN_PORTS):
        return None
    return low, high


def _winn3_relay_range_from_env() -> Optional[tuple]:
    """(min, max) from WINN3_RELAY_PORT_RANGE ("MIN-MAX"), or None when unusable.

    ONE value on purpose: the Core carries the same text in CORE_RELAY_PORT_RANGE
    and the two sides compare it at run time, so the range the hub allocates from
    can never silently differ from the range the owner's router forwards.

    An unusable range turns the relay OFF (logged once, reason only) instead of
    falling back to a guess: a relay port the owner never forwarded is a silent
    dead path, and OFF is today's behaviour.
    """
    raw = (os.getenv("WINN3_RELAY_PORT_RANGE") or WINN3_RELAY_PORT_RANGE_DEFAULT).strip()
    parsed = winn3_relay_parse_range(raw)
    if parsed is None:
        logger.error("WINN3_RELAY_PORT_RANGE is not a usable MIN-MAX range (1024..65535, at most %s ports, "
                     "no reserved listener port); the winn3 relay stays off", WINN3_RELAY_MAX_RANGE_WIDTH)
    return parsed


WINN3_RELAY_PORT_RANGE = _winn3_relay_range_from_env()
# The canonical text of the range ("9211-9218"), the one value the Core must echo.
WINN3_RELAY_PORT_RANGE_TEXT = (
    "%d-%d" % WINN3_RELAY_PORT_RANGE if WINN3_RELAY_PORT_RANGE else ""
)
try:
    WINN3_RELAY_REPORT_MAX_AGE_SECONDS = max(
        5, min(300, int((os.getenv("WINN3_RELAY_REPORT_MAX_AGE_SECONDS") or "30").strip())))
except ValueError:
    WINN3_RELAY_REPORT_MAX_AGE_SECONDS = 30


def winn3_relay_enabled() -> bool:
    return bool(WINN3_RELAY_ENABLED and WINN3_RELAY_PORT_RANGE)


def winn3_relay_port_in_range(port: Any) -> bool:
    if not WINN3_RELAY_PORT_RANGE or isinstance(port, bool) or not isinstance(port, int):
        return False
    return WINN3_RELAY_PORT_RANGE[0] <= port <= WINN3_RELAY_PORT_RANGE[1]


def winn3_relay_global_ipv4(host: Any) -> str:
    """The dotted quad when `host` is a global unicast IPv4 literal, else "".

    A hostname, an IPv6 literal, a private, loopback, link local, multicast,
    CGNAT or reserved address all answer "": the client is told to dial this
    address and the Core's router forwards to it, so it must be a public one.
    """
    text = str(host or "").strip()
    if not re.fullmatch(r"[0-9]{1,3}(?:\.[0-9]{1,3}){3}", text):
        return ""
    try:
        address = ipaddress.IPv4Address(text)
    except ValueError:
        return ""
    if (
        address.is_private or address.is_loopback or address.is_link_local
        or address.is_multicast or address.is_reserved or address.is_unspecified
        or not address.is_global
    ):
        return ""
    return str(address)


def sanitize_core_relay_report(raw: Any) -> tuple:
    """(clean report, "") or (None, reason). Reason words only, never a value.

    Strict: a malformed object is dropped whole (it never fails the Core's
    registration, which also keeps the AmneziaWG Double VPN alive), unknown
    keys are dropped, and nothing the Core sends is stored unchecked.
    """
    if not isinstance(raw, dict):
        return None, "relay-report-not-object"
    version = raw.get("v")
    if isinstance(version, bool) or version != 1 or not isinstance(version, int):
        return None, "relay-report-version"
    state = raw.get("state")
    if state not in ("active", "inactive"):
        return None, "relay-report-state"
    iface = raw.get("wan_iface")
    if not isinstance(iface, str) or not WINN3_RELAY_IFACE_PATTERN.fullmatch(iface):
        return None, "relay-report-wan-iface"
    # The range the Core itself runs with, same text and same rules as the hub's
    # own value. A well formed range that differs from the hub's is STORED so the
    # gate can name port_range_mismatch; a malformed one drops the report.
    reported_range = raw.get("port_range")
    reported_bounds = winn3_relay_parse_range(reported_range)
    if reported_bounds is None:
        return None, "relay-report-port-range"
    applied_at = raw.get("applied_at")
    if isinstance(applied_at, bool) or not isinstance(applied_at, int) or not 0 <= applied_at <= 2 ** 53:
        return None, "relay-report-applied-at"
    rules_sha256 = raw.get("rules_sha256")
    if not isinstance(rules_sha256, str) or not re.fullmatch(r"[0-9a-f]{64}", rules_sha256):
        return None, "relay-report-rules-sha256"
    listens = raw.get("listens")
    if not isinstance(listens, list) or len(listens) > WINN3_RELAY_REPORT_MAX_LISTENS:
        return None, "relay-report-listens"
    clean_listens = []
    seen_slugs: set = set()
    seen_ports: set = set()
    for item in listens:
        if not isinstance(item, dict):
            return None, "relay-report-listen-shape"
        slug = item.get("exit_slug")
        port = item.get("port")
        listen_state = item.get("state")
        packets = item.get("packets")
        if not isinstance(slug, str) or not WINN3_RELAY_SLUG_PATTERN.fullmatch(slug):
            return None, "relay-report-listen-slug"
        if (
            isinstance(port, bool) or not isinstance(port, int)
            or not reported_bounds[0] <= port <= reported_bounds[1]
        ):
            return None, "relay-report-listen-port"
        if listen_state not in ("up", "down"):
            return None, "relay-report-listen-state"
        if isinstance(packets, bool) or not isinstance(packets, int) or not 0 <= packets <= 2 ** 53:
            return None, "relay-report-listen-packets"
        if slug in seen_slugs or port in seen_ports:
            return None, "relay-report-listen-duplicate"
        seen_slugs.add(slug)
        seen_ports.add(port)
        entry = {"exit_slug": slug, "port": port, "state": listen_state, "packets": packets}
        if listen_state == "down":
            reason = item.get("reason")
            if reason is not None:
                if not isinstance(reason, str) or not WINN3_RELAY_REASON_PATTERN.fullmatch(reason):
                    return None, "relay-report-listen-reason"
                entry["reason"] = reason
        clean_listens.append(entry)
    clean = {
        "v": 1,
        "state": state,
        "port_range": "%d-%d" % reported_bounds,
        "wan_iface": iface,
        "applied_at": applied_at,
        "rules_sha256": rules_sha256,
        "listens": clean_listens,
    }
    if len(json.dumps(clean, sort_keys=True, separators=(",", ":"))) > WINN3_RELAY_REPORT_MAX_BYTES:
        return None, "relay-report-oversize"
    return clean, ""


def store_core_relay_report(conn: sqlite3.Connection, core_id: str, raw: Any, now_iso: str) -> str:
    """Store the sanitized report, or delete the stored one. Returns a reason
    word ("" when a report was stored, "absent" when none was sent).

    An absent report (an older Core agent, or a Core with the relay off) and a
    malformed one both leave NO stored report, so the hub stops serving the
    relay at once instead of trusting the previous report until it ages out.
    """
    if raw is None:
        conn.execute("DELETE FROM core_relay_reports WHERE core_id = ?", (core_id,))
        return "absent"
    clean, reason = sanitize_core_relay_report(raw)
    if clean is None:
        conn.execute("DELETE FROM core_relay_reports WHERE core_id = ?", (core_id,))
        logger.warning("dropped the winn3 relay report of core %s (reason=%s)", core_id, reason)
        return reason
    conn.execute(
        "INSERT INTO core_relay_reports (core_id, report_json, reported_at) VALUES (?, ?, ?) "
        "ON CONFLICT(core_id) DO UPDATE SET report_json = excluded.report_json, "
        "reported_at = excluded.reported_at",
        (core_id, json.dumps(clean, sort_keys=True, separators=(",", ":")), now_iso),
    )
    return ""


def core_relay_blockers(
    conn: sqlite3.Connection,
    *,
    core_id: str,
    relay_row: Any,
    node: Any,
    capabilities: dict,
    core: Any = None,
    device_row: Any = None,
    rotates_identity: bool = False,
    check_inner_pool: bool = False,
) -> list:
    """Every reason this (Core, exit) pair cannot serve a relay, by NAME.

    One function for the serving gate and the admin readiness report so the two
    cannot disagree. `core` is the row select_double_vpn_core returned for this
    request; the readiness report passes None and the function selects it.
    `check_inner_pool` is True only on the serving path, where there is a device:
    the readiness report has none and never evaluates the pool.
    Names only: no address, key or descriptor byte.
    """
    blockers: list = []
    if not winn3_relay_enabled():
        blockers.append("relay_flag_off")
    if core is None:
        candidate = select_double_vpn_core(conn)
        core = candidate if candidate is not None and candidate["core_id"] == core_id else None
    if core is None or core["core_id"] != core_id:
        blockers.append("core_not_ready")
    # The report is read by THIS core id and no other.
    report_row = conn.execute(
        "SELECT report_json, reported_at FROM core_relay_reports WHERE core_id = ?", (core_id,)
    ).fetchone()
    report: dict = {}
    if report_row is None:
        blockers.append("report_missing")
    else:
        reported = parse_iso_datetime(report_row["reported_at"])
        cutoff = utcnow() - timedelta(seconds=WINN3_RELAY_REPORT_MAX_AGE_SECONDS)
        if reported is None or reported < cutoff:
            blockers.append("report_stale")
        try:
            loaded = json.loads(report_row["report_json"])
            report = loaded if isinstance(loaded, dict) else {}
        except (TypeError, ValueError):
            report = {}
        if report.get("state") != "active":
            blockers.append("report_inactive")
        elif report.get("port_range") != WINN3_RELAY_PORT_RANGE_TEXT:
            # The Core runs with a different range than this hub allocates from
            # (or reported none). One of the two values is wrong and the owner's
            # router forwards only one of them: keep the relay off until they
            # agree, and say which gate it was.
            blockers.append("port_range_mismatch")
        else:
            wanted_slug = str(relay_row["exit_slug"])
            wanted_port = int(relay_row["relay_port"])
            match = next(
                (
                    item for item in (report.get("listens") or [])
                    if isinstance(item, dict)
                    and item.get("exit_slug") == wanted_slug
                    and item.get("port") == wanted_port
                ),
                None,
            )
            if match is None:
                blockers.append("listen_missing")
            elif match.get("state") != "up":
                blockers.append("listen_down")
    if core is not None and not winn3_relay_global_ipv4(
        split_host_port(core["ingress_endpoint"], 9210)[0]
    ):
        blockers.append("ingress_host_not_ipv4_literal")
    # The exit must serve as a standalone winn/3 single hop for this request:
    # the SAME resolvers the ordinary single-hop path runs, evaluated early.
    exit_ok = False
    descriptor_ok = False
    try:
        obfuscation = parse_obfuscation(node.get("obfuscation_json"))
        version, params, _reason = resolve_served_winn_protocol(
            node,
            capabilities=capabilities,
            obfuscation=obfuscation,
            stealth_mode=False,
            double_vpn_active=False,
            mtu=1280,
        )
        if version == WINN_PROTOCOL_V3 and (params or {}).get("carrier") == WINN3_CARRIER_WINN3:
            exit_ok = True
            envelope, _why = resolve_served_winn3_descriptor(
                node, capabilities=capabilities, served_protocol_version=version
            )
            descriptor_ok = bool(envelope)
    except (Winn3ContractError, ObfuscationProfileError):
        exit_ok = False
    if not exit_ok:
        blockers.append("exit_not_winn3")
    elif not descriptor_ok:
        blockers.append("exit_descriptor_missing")
    if check_inner_pool and not winn3_relay_inner_pool_available(
        conn, device_row, rotates_identity=rotates_identity
    ):
        blockers.append("winn3_inner_pool_exhausted")
    return blockers


def winn3_relay_inner_pool_available(
    conn: sqlite3.Connection, device_row: Any, *, rotates_identity: bool = False
) -> bool:
    """Whether a relay login can be issued an inner address, decided exactly as
    the single hop allocator will decide it LATER in the same request.

    A relay Double device is a plain single hop winn/3 device, so it needs an
    address in the fleet's inner pool (WINN3_INNER_POOL_CIDR, pinned to one /24;
    every exit's slice is that /24, see winn3_node_inner_slice). The pool is
    shared with every single hop device and holds at most 253 addresses, so it
    can be full. When it is, the allocator answers "" and the verify path
    refuses with a 503, so this gate asks first and the caller serves the
    AmneziaWG Double instead (its own pool is the Core's 10.9.0.0/16), before
    anything is deactivated or consumed.

    The device keeps its address only when the request will not rotate its
    winn3 identity (the caller predicts that from the same conditions the
    verify path uses); otherwise, and for a new device, a free address must
    exist. allocate_winn3_inner_ip is read only here (it returns a candidate and
    claims nothing).
    """
    existing = ""
    if device_row is not None and not rotates_identity:
        try:
            existing = str(device_row["winn3_inner_v4"] or "").strip()
        except (KeyError, IndexError, TypeError):
            existing = ""
    if existing and winn3_inner_router_in_pool(existing):
        return True
    return bool(allocate_winn3_inner_ip(conn))


def resolve_served_double_relay(
    conn: sqlite3.Connection,
    *,
    login: Any,
    node: Any,
    core: Any,
    capabilities: Optional[dict] = None,
    device_row: Any = None,
    rotates_identity: bool = False,
) -> Optional[dict]:
    """The relay plan for THIS Double VPN request, or None (today's AWG Double).

    Never raises and never logs an address: a failing gate is logged by NAME.
    The caller has already established that the request asks for Double and
    is a PAID account (free accounts never reach Double), and that `core` is the
    row select_double_vpn_core returned. `device_row` and `rotates_identity`
    feed the inner pool gate (winn3_inner_pool_exhausted).
    """
    if not winn3_relay_enabled() or core is None:
        return None
    reason = ""
    try:
        if capabilities is None:
            capabilities = request_client_capabilities(login)
        if bool(getattr(login, "stealth_mode", False)):
            reason = "stealth"
        elif not (
            bool(capabilities.get(WINN3_CLIENT_CAPABILITY))
            and bool(capabilities.get(WINN3_DESCRIPTOR_CLIENT_CAPABILITY))
            and bool(capabilities.get(WINN3_RELAY_CAPABILITY))
        ):
            reason = "capability"
        else:
            core_id = str(core["core_id"])
            relay_row = conn.execute(
                "SELECT exit_slug, relay_port, enabled FROM core_relay_exits "
                "WHERE core_id = ? AND exit_slug = ?",
                (core_id, str(node["slug"])),
            ).fetchone()
            if relay_row is None:
                reason = "relay_row_missing"
            elif not int(relay_row["enabled"] or 0):
                reason = "relay_row_disabled"
            elif not winn3_relay_port_in_range(int(relay_row["relay_port"])):
                reason = "relay_port_out_of_range"
            else:
                blockers = core_relay_blockers(
                    conn, core_id=core_id, relay_row=relay_row, node=node,
                    capabilities=capabilities, core=core,
                    device_row=device_row, rotates_identity=rotates_identity,
                    check_inner_pool=True,
                )
                if blockers:
                    reason = blockers[0]
                else:
                    host = winn3_relay_global_ipv4(split_host_port(core["ingress_endpoint"], 9210)[0])
                    port = int(relay_row["relay_port"])
                    return {
                        "core_id": core_id,
                        "host": host,
                        "port": port,
                        "endpoint": f"{host}:{port}",
                    }
    except Winn3ContractError:
        reason = "capability_malformed"
    except Exception:
        logger.exception("winn3 relay gate failed unexpectedly; serving the AmneziaWG Double VPN")
        reason = "gate_error"
    logger.info("winn3 relay not served (reason=%s)", reason)
    return None


def core_relay_list_payload(conn: sqlite3.Connection, core_id: str) -> Optional[dict]:
    """The `relay` object of GET /api/v1/core/assignments, or None (the key is
    then ABSENT and the response is byte for byte today's).

    Static per exit: no device, account or key is in it. Each item carries the
    exit's stored SIGNED envelope, which the Core verifies against the pinned
    ring and from which it takes the one forwarding target, so the hub can
    never aim the Core's forwarder at an address the owner did not sign.
    """
    if not winn3_relay_enabled():
        return None
    rows = conn.execute(
        """
        SELECT r.exit_slug AS relay_exit_slug, r.relay_port AS relay_port, n.*
        FROM core_relay_exits r
        JOIN nodes n ON n.slug = r.exit_slug
        WHERE r.core_id = ?
          AND r.enabled = 1
          AND n.retired_at IS NULL
          AND COALESCE(n.operator_enabled, 0) = 1
          AND n.status NOT IN ('offline', 'maintenance')
        ORDER BY r.relay_port
        """,
        (core_id,),
    ).fetchall()
    relays = []
    for row in rows:
        if not winn3_relay_port_in_range(int(row["relay_port"])):
            continue
        if not winn3_stored_descriptor(row):
            continue
        envelope = parse_winn3_descriptor_envelope(row["winn3_descriptor_json"])
        if not envelope:
            continue
        relays.append({
            "exit_slug": row["relay_exit_slug"],
            "port": int(row["relay_port"]),
            "descriptor": {"payload": envelope["payload"], "sig": envelope["sig"]},
        })
    if not relays:
        return None
    # port_range is the hub's own value; the Core refuses the whole object when it
    # differs from the range it runs with (the owner's router forwards one range).
    return {"v": 1, "port_range": WINN3_RELAY_PORT_RANGE_TEXT, "relays": relays}


# ---------------------------------------------------------------------------
# w3r/1 admin routes. Admin token only (never the Core token).
# ---------------------------------------------------------------------------
def core_relay_admin_core_id(value: str) -> str:
    core_key = (value or "").strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", core_key):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    return core_key


def winn3_relay_choose_port(
    conn: sqlite3.Connection,
    core_id: str,
    slug: str,
    existing_port: Optional[int],
    pin: Optional[int],
) -> tuple:
    """(port, [slugs whose rows were reclaimed]) for enabling (core_id, slug).

    The port is ALWAYS inside the configured range (the range the owner's router
    forwards). A row is ACTIVE when it is enabled and its exit is a live, non
    retired node; a port held by an active row is never taken. A port held only
    by a disabled row, a retired exit or an exit that no longer exists can be
    reclaimed (that row is deleted by the caller). Raises HTTPException 400 for
    a pin outside the range and 409 when nothing can be allocated.
    """
    low, high = WINN3_RELAY_PORT_RANGE
    others = conn.execute(
        """
        SELECT r.exit_slug AS exit_slug, r.relay_port AS relay_port, r.enabled AS enabled,
               r.updated_at AS updated_at, n.slug AS node_slug, n.retired_at AS retired_at
        FROM core_relay_exits r
        LEFT JOIN nodes n ON n.slug = r.exit_slug
        WHERE r.core_id = ? AND r.exit_slug != ?
        """,
        (core_id, slug),
    ).fetchall()
    held: dict = {}
    for row in others:
        port = int(row["relay_port"])
        active = bool(int(row["enabled"] or 0)) and row["node_slug"] is not None and not node_is_retired(row)
        held[port] = {"slug": row["exit_slug"], "active": active, "updated_at": str(row["updated_at"] or "")}
    if pin is not None:
        if isinstance(pin, bool) or not isinstance(pin, int) or not winn3_relay_port_in_range(pin):
            raise HTTPException(status_code=400, detail="The relay port is outside the configured range.")
        holder = held.get(pin)
        if holder is not None and holder["active"]:
            raise HTTPException(status_code=409, detail="That relay port belongs to another enabled exit.")
        return pin, ([holder["slug"]] if holder is not None else [])
    if existing_port is not None and winn3_relay_port_in_range(existing_port) and existing_port not in held:
        return existing_port, []
    free = [candidate for candidate in range(low, high + 1) if candidate not in held]
    if free:
        return free[0], []
    reclaimable = sorted(
        ((info["updated_at"], port) for port, info in held.items() if not info["active"]),
    )
    if reclaimable:
        port = reclaimable[0][1]
        return port, [held[port]["slug"]]
    raise HTTPException(status_code=409, detail="No free relay port in the configured range.")


@app.post("/admin/cores/relay/exit")
def admin_set_core_relay_exit(
    request: Request,
    core_id: str = Form(...),
    exit_slug: str = Form(...),
    enabled: bool = Form(...),
    port: Optional[int] = Form(None),
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "set core relay exit")
    core_key = core_relay_admin_core_id(core_id)
    slug = (exit_slug or "").strip().lower()
    if not WINN3_RELAY_SLUG_PATTERN.fullmatch(slug):
        raise HTTPException(status_code=400, detail="Exit slug is invalid.")
    if slug.startswith("core-"):
        raise HTTPException(status_code=400, detail="A Core slug is never an exit.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT relay_port, enabled FROM core_relay_exits WHERE core_id = ? AND exit_slug = ?",
            (core_key, slug),
        ).fetchone()
        now_iso = utcnow().isoformat()
        if not enabled:
            # The rollback: never validated, never refused. The row (and its port)
            # stays until a later allocation needs the port.
            if existing is not None:
                conn.execute(
                    "UPDATE core_relay_exits SET enabled = 0, updated_at = ? "
                    "WHERE core_id = ? AND exit_slug = ?",
                    (now_iso, core_key, slug),
                )
            logger.info("core %s relay for exit %s disabled", core_key, slug)
            return {
                "ok": True, "core_id": core_key, "exit_slug": slug, "enabled": False,
                "port": int(existing["relay_port"]) if existing is not None else None,
            }
        if not WINN3_RELAY_PORT_RANGE:
            raise HTTPException(status_code=409, detail="The relay port range is invalid.")
        if conn.execute("SELECT 1 FROM core_servers WHERE core_id = ?", (core_key,)).fetchone() is None:
            raise HTTPException(status_code=404, detail="Core not found.")
        node = conn.execute("SELECT slug, retired_at FROM nodes WHERE slug = ?", (slug,)).fetchone()
        if node is None:
            raise HTTPException(status_code=404, detail="Exit node not found.")
        if node_is_retired(node):
            raise HTTPException(status_code=409, detail="Exit node is retired.")
        chosen, reclaimed = winn3_relay_choose_port(
            conn, core_key, slug,
            int(existing["relay_port"]) if existing is not None else None,
            port,
        )
        for reclaimed_slug in reclaimed:
            conn.execute(
                "DELETE FROM core_relay_exits WHERE core_id = ? AND exit_slug = ?",
                (core_key, reclaimed_slug),
            )
            logger.info("core %s relay port %s reclaimed from exit %s", core_key, chosen, reclaimed_slug)
        if existing is None:
            conn.execute(
                "INSERT INTO core_relay_exits (core_id, exit_slug, relay_port, enabled, created_at, updated_at) "
                "VALUES (?, ?, ?, 1, ?, ?)",
                (core_key, slug, chosen, now_iso, now_iso),
            )
        else:
            conn.execute(
                "UPDATE core_relay_exits SET relay_port = ?, enabled = 1, updated_at = ? "
                "WHERE core_id = ? AND exit_slug = ?",
                (chosen, now_iso, core_key, slug),
            )
    logger.info("core %s relay for exit %s enabled", core_key, slug)
    return {"ok": True, "core_id": core_key, "exit_slug": slug, "enabled": True, "port": chosen}


@app.get("/admin/cores/relay")
def admin_core_relay_readiness(
    request: Request,
    core_id: str = "",
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "core relay readiness")
    core_key = core_relay_admin_core_id(core_id or DOUBLE_VPN_CORE_ID)
    # A fully capable client, for the exit side of the readiness question.
    capabilities = {
        "supports_winn3": True,
        "supports_winn3_spa": True,
        "supports_winn3_descriptor": True,
        WINN3_RELAY_CAPABILITY: True,
    }
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT exit_slug, relay_port, enabled FROM core_relay_exits "
            "WHERE core_id = ? ORDER BY relay_port",
            (core_key,),
        ).fetchall()
        exits = []
        for row in rows:
            node_row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (row["exit_slug"],)).fetchone()
            if node_row is None:
                blockers = ["exit_not_winn3"]
            else:
                blockers = core_relay_blockers(
                    conn, core_id=core_key, relay_row=row, node=dict(node_row),
                    capabilities=capabilities,
                )
            exits.append({
                "exit_slug": row["exit_slug"],
                "port": int(row["relay_port"]),
                "enabled": bool(int(row["enabled"] or 0)),
                "blockers": blockers,
            })
    return {
        "ok": True,
        "core_id": core_key,
        "relay_enabled": winn3_relay_enabled(),
        "port_range": WINN3_RELAY_PORT_RANGE_TEXT or None,
        "report_max_age_seconds": WINN3_RELAY_REPORT_MAX_AGE_SECONDS,
        "known_blockers": list(WINN3_RELAY_BLOCKERS),
        "exits": exits,
    }


def acquire_double_vpn_enrollment_lease(
    conn: sqlite3.Connection,
    account_number: str,
    device_id: str,
) -> str:
    now = time.time()
    ttl_seconds = max(
        60,
        DOUBLE_VPN_ASSIGNMENT_READY_TIMEOUT_SECONDS + 30,
    )
    conn.execute(
        "DELETE FROM double_vpn_enrollment_leases WHERE expires_at <= ?",
        (now,),
    )
    lease_token = secrets.token_urlsafe(32)
    try:
        conn.execute(
            """
            INSERT INTO double_vpn_enrollment_leases (
                account_number, device_id, lease_token, expires_at, created_at
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (
                account_number,
                device_id,
                lease_token,
                now + ttl_seconds,
                utcnow().isoformat(),
            ),
        )
    except sqlite3.IntegrityError as exc:
        raise HTTPException(
            status_code=409,
            detail="A Double VPN enrollment is already being prepared for this account.",
            headers={
                "X-Wins-Error-Code": "double_vpn_enrollment_in_flight",
                "Retry-After": "5",
            },
        ) from exc
    return lease_token


def release_double_vpn_enrollment_lease(
    account_number: str,
    lease_token: str,
) -> None:
    try:
        with get_db() as cleanup_conn:
            cleanup_conn.execute("BEGIN IMMEDIATE")
            cleanup_conn.execute(
                "DELETE FROM double_vpn_enrollment_leases "
                "WHERE account_number = ? AND lease_token = ?",
                (account_number, lease_token),
            )
    except sqlite3.Error:
        logger.exception(
            "Double VPN enrollment lease cleanup failed for account_hash=%s",
            security_event_hash(account_number),
        )


def cleanup_stale_devices(conn: sqlite3.Connection, background_tasks: Optional[BackgroundTasks] = None) -> int:
    rows = []
    if STALE_DEVICE_RETENTION_DAYS > 0:
        cutoff = (utcnow() - timedelta(days=STALE_DEVICE_RETENTION_DAYS)).isoformat()
        rows = conn.execute(
            """
            SELECT d.device_id, d.account_number, d.client_public_key, d.location_slug,
                   n.endpoint, n.ssh_host
            FROM devices d
            LEFT JOIN nodes n ON n.slug = d.location_slug
            WHERE d.last_seen IS NULL OR d.last_seen < ?
            """,
            (cutoff,),
        ).fetchall()
        for row in rows:
            client_key = (row["client_public_key"] or "").strip()
            node_ip = row["ssh_host"] or extract_node_host(row["endpoint"] or "")
            if client_key and node_ip:
                queue_peer_revocation(conn, node_ip, client_key, background_tasks)
        conn.execute("DELETE FROM devices WHERE last_seen IS NULL OR last_seen < ?", (cutoff,))
    # Double VPN assignments deliberately retain their client IP while the
    # owning device still exists, including when Double VPN is temporarily
    # disabled. Once a stale device is purged, however, its assignment must be
    # removed in this same transaction. Otherwise the Core keeps advertising an
    # orphan ingress peer and allocate_core_client_ip() can never reclaim the
    # unique 10.9.x address. This also repairs historical orphans created by a
    # device-ID rotation before this invariant was enforced.
    conn.execute("""
        DELETE FROM double_vpn_assignments
        WHERE NOT EXISTS (
            SELECT 1 FROM devices d
            WHERE d.device_id = double_vpn_assignments.device_id
        )
    """)
    return len(rows)

def admin_secret_matches(candidate: Optional[str]) -> bool:
    return bool(ADMIN_SECRET_TOKEN) and hmac.compare_digest(
        str(candidate or ""), ADMIN_SECRET_TOKEN
    )

def require_admin_token(token: Optional[str], request: Optional[Request] = None, action: str = "admin api"):
    if not admin_secret_matches(token):
        security_alert(2, "invalid admin token", request=request, details={"action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")

def token_digest(token: str) -> str:
    return hashlib.sha256((token or "").encode()).hexdigest()

def node_token_matches(stored_hash: Optional[str], supplied: Optional[str]) -> bool:
    # Per-node tokens are issued at registration (H-9) and scope heartbeat,
    # pubkey-update, and resync calls to the single node they were issued to
    # -- unlike ADMIN_SECRET_TOKEN, a stored hash here is never a valid match
    # for any *other* node's supplied token.
    return bool(stored_hash) and bool(supplied) and hmac.compare_digest(
        token_digest(supplied), stored_hash
    )

def fetch_node_token_hash(conn: sqlite3.Connection, slug: str) -> Optional[str]:
    row = conn.execute("SELECT node_token_hash FROM nodes WHERE slug = ?", (slug,)).fetchone()
    return row["node_token_hash"] if row else None

def require_node_token(conn: sqlite3.Connection, slug: str, supplied: Optional[str], request: Optional[Request] = None, action: str = "node api") -> None:
    if not node_token_matches(fetch_node_token_hash(conn, slug), supplied):
        security_alert(2, "invalid node token", request=request, details={"slug": slug, "action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")

# H-2: BOOTSTRAP_GRANT_TTL_SECONDS bounds how long a bootstrap grant can sit
# unused (e.g. handed to an operator, or embedded in a one-touch invocation)
# before it is worthless -- long enough to cover a normal deployment
# sitting, short enough that a leaked/abandoned grant cannot be replayed
# hours or days later the way the fleet-wide admin token it replaces could.
BOOTSTRAP_GRANT_TTL_SECONDS = 600
BOOTSTRAP_GRANT_ROLES = {"node", "core"}

BOOTSTRAP_GRANT_MAX_TTL_SECONDS = 3600

def create_bootstrap_grant(conn: sqlite3.Connection, role: str, subject_id: str,
                           ttl_seconds: int = BOOTSTRAP_GRANT_TTL_SECONDS) -> str:
    token = secrets.token_urlsafe(32)
    expires_at = (utcnow() + timedelta(seconds=ttl_seconds)).isoformat()
    conn.execute(
        "INSERT INTO bootstrap_grants (token_hash, role, subject_id, expires_at) VALUES (?, ?, ?, ?)",
        (token_digest(token), role, subject_id, expires_at),
    )
    return token

def consume_bootstrap_grant(conn: sqlite3.Connection, token: Optional[str], role: str, subject_id: str) -> bool:
    # H-2: looks up candidates by (role, subject_id) -- neither secret, like
    # a node slug or core_id -- then compares the supplied token against
    # each candidate's hash with the constant-time helper below, mirroring
    # node_token_matches/device_auth_token_matches rather than letting a
    # secret token_hash flow into a SQL WHERE equality. The final UPDATE's
    # WHERE clause is what makes this single-use and scoped: it can only
    # ever flip used_at from NULL to non-NULL once, for the exact matched
    # grant, so a grant minted for node "tokyo" can never bootstrap node
    # "berlin" or core "north-america-core", and a captured grant can never
    # be replayed after its first successful (or first attempted) use.
    if not token:
        return False
    now_iso = utcnow().isoformat()
    supplied_digest = token_digest(token)
    candidates = conn.execute(
        "SELECT token_hash FROM bootstrap_grants WHERE role = ? AND subject_id = ? AND used_at IS NULL AND expires_at > ?",
        (role, subject_id, now_iso),
    ).fetchall()
    matched_hash = next(
        (row["token_hash"] for row in candidates if hmac.compare_digest(supplied_digest, row["token_hash"])),
        None,
    )
    if not matched_hash:
        return False
    cursor = conn.execute(
        "UPDATE bootstrap_grants SET used_at = ? WHERE token_hash = ? AND used_at IS NULL",
        (now_iso, matched_hash),
    )
    return cursor.rowcount == 1

def core_token_matches(stored_hash: Optional[str], supplied: Optional[str]) -> bool:
    # Mirrors node_token_matches: a stored hash here is never a valid match
    # for any *other* core's supplied token, and an empty stored hash never
    # matches anything (a core that has not yet exchanged a bootstrap grant
    # for a token cannot be impersonated via an empty/missing credential).
    return bool(stored_hash) and bool(supplied) and hmac.compare_digest(
        token_digest(supplied), stored_hash
    )

def fetch_core_token_hash(conn: sqlite3.Connection, core_id: str) -> Optional[str]:
    row = conn.execute("SELECT core_token_hash FROM core_servers WHERE core_id = ?", (core_id,)).fetchone()
    return row["core_token_hash"] if row else None

def require_core_token(conn: sqlite3.Connection, core_id: str, supplied: Optional[str], request: Optional[Request] = None, action: str = "core api") -> None:
    # H-2: every routine core-scoped endpoint calls this instead of
    # require_admin_token, so the fleet-wide admin token is no longer a
    # routine credential on core hosts -- only /api/v1/core/bootstrap
    # (grant-gated) and the operator-driven /admin/core/* management-tunnel
    # endpoints (admin-token-gated) ever authorize a core by any other means.
    if not core_token_matches(fetch_core_token_hash(conn, core_id), supplied):
        security_alert(2, "invalid core token", request=request, details={"core_id": core_id, "action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")

def bearer_token_from_request(request: Request) -> str:
    header = request.headers.get("authorization") or ""
    scheme, _, token = header.partition(" ")
    return token.strip() if scheme.lower() == "bearer" else ""

def device_auth_token_matches(stored_hash: Optional[str], supplied: Optional[str]) -> bool:
    # M-5: mirrors node_token_matches -- a device's own bearer token never
    # matches another device's stored hash, and an empty stored hash (a
    # legacy row from before this control existed) never matches anything
    # supplied, by design; callers decide whether to fail closed or allow a
    # one-time legacy fallback for that specific case.
    return bool(stored_hash) and bool(supplied) and hmac.compare_digest(
        token_digest(supplied), stored_hash
    )

def require_device_auth_token(conn: sqlite3.Connection, account_number: str, device_id: str, request: Request, action: str = "device api") -> None:
    # H-1: fail closed unconditionally. Every device row gets a
    # device_auth_token_hash the moment /verify creates or backfills it, so
    # a missing/empty hash here is never a legitimate pre-existing device --
    # it means this device_id was never actually activated through /verify,
    # and must not be trusted with a device-mutation call either way.
    row = conn.execute(
        "SELECT device_auth_token_hash FROM devices WHERE account_number = ? AND device_id = ?",
        (account_number, device_id),
    ).fetchone()
    stored_hash = (row["device_auth_token_hash"] if row else "") or ""
    supplied = bearer_token_from_request(request)
    if not device_auth_token_matches(stored_hash, supplied):
        security_alert(2, "invalid device auth token", request=request, details={
            "account_hash": security_event_hash(account_number),
            "action": action,
        })
        raise HTTPException(status_code=401, detail="Unauthorized")

_ACTIVATION_SECRET_PEPPER = (
    os.environ.get("ACTIVATION_SECRET_PEPPER")
    or RATE_LIMIT_SECRET
    or ""
).encode("utf-8")
if not _ACTIVATION_SECRET_PEPPER:
    raise RuntimeError("Activation hashing requires a configured server secret")
_ACTIVATION_DUMMY_HASH = hmac.new(_ACTIVATION_SECRET_PEPPER, b"dummy", hashlib.sha256).hexdigest()


def _hash_activation_secret(secret: str) -> str:
    return hmac.new(_ACTIVATION_SECRET_PEPPER, (secret or "").encode("utf-8"), hashlib.sha256).hexdigest()


def activation_secret_matches(stored_hash: Optional[str], supplied: Optional[str]) -> bool:
    if not stored_hash or not supplied:
        return False
    if hmac.compare_digest(stored_hash, _hash_activation_secret(supplied)):
        return True
    return hmac.compare_digest(stored_hash, token_digest(supplied))


def issue_activation_secret(
    conn: sqlite3.Connection,
    account_number: str,
    ttl: Optional[timedelta] = None,
) -> str:
    # Owner ruling 2026-10-22: a setup key is valid until it is used. With no
    # ttl the key carries no expiry (NULL); a caller that passes a ttl still
    # gets an expiring key. A key stops working when it activates a device, when
    # a newer key set replaces it, or when its account is no longer active.
    # Owner ruling 2026-10-25: deactivating the device it activated makes it
    # valid again (return_device_activation_key).
    secret = secrets.token_urlsafe(32)
    secret_hash = _hash_activation_secret(secret)
    now = now_utc()
    expires_at = (now + ttl).isoformat(timespec="seconds") if ttl is not None else None
    conn.execute(
        """
        UPDATE users
           SET activation_secret_hash = ?,
               activation_secret_expires_at = ?,
               activation_secret_used_at = NULL
         WHERE account_number = ?
        """,
        (secret_hash, expires_at, account_number),
    )
    return secret


# A new account gets one setup key per device slot of the DEFAULT limit, all in
# one email. The set is stored in two places that older builds already
# understand: slot 1 is the users-row key issue_activation_secret has always
# written (activation_secret_*), slots 2..N are rows of activation_extra_keys.
# Every slot is a full key: 32 random bytes, HMAC hashed at rest, no expiry
# (valid until used) and its own single-use mark, rotated together with the
# others.
ACTIVATION_KEY_SEPARATOR = "\n"

# What a client is told when a setup key does not enrol a device. One message
# covers a wrong, used, replaced or revoked key, so the reply never tells a
# guesser which of those it was (the server-side alert names the real cause).
# Sent only when a key was presented; a request with no key is told one is
# required. Both keep the 401 status and the failure rate limits.
SETUP_KEY_REFUSED_DETAIL = "That setup key is not valid or has already been used. Check your welcome email or contact support."
SETUP_KEY_REQUIRED_DETAIL = "Activation key required for this device. Check your welcome email or contact support."


def activation_key_count() -> int:
    # The count comes from the global DEVICE_LIMIT only. A per-account
    # device_limit_override never raises it, and a hub configured below one
    # still issues one key.
    return max(1, int(DEVICE_LIMIT))


def activation_key_list(value) -> list:
    # One key, a newline-joined bundle (how a sealed record carries a set) or a
    # sequence of keys, as a plain list. Empty and None mean no key.
    if not value:
        return []
    if isinstance(value, str):
        return [part for part in value.split(ACTIVATION_KEY_SEPARATOR) if part]
    return [str(part) for part in value if part]


def fetch_activation_extra_keys(conn: sqlite3.Connection, account_number: str) -> list:
    return conn.execute(
        "SELECT key_id, slot, secret_hash, expires_at, used_at "
        "FROM activation_extra_keys WHERE account_number = ? ORDER BY slot",
        (account_number,),
    ).fetchall()


def activation_bundle_states(conn: sqlite3.Connection, account_number: str, keys: list) -> list:
    # For each plaintext key of a sealed bundle, how the account's stored keys
    # see it right now: "live" (stored, unused, not expired), "used", "expired"
    # or "unknown" (no stored slot matches it, which is what a replaced set
    # looks like). Read only. A stored expiry is never changed here or by any
    # caller: an expired key stays expired. Two keys never share one slot.
    row = conn.execute(
        "SELECT activation_secret_hash, activation_secret_expires_at, activation_secret_used_at "
        "FROM users WHERE account_number = ?", (account_number,),
    ).fetchone()
    slots = []
    if row is not None:
        if row["activation_secret_hash"]:
            slots.append((row["activation_secret_hash"], row["activation_secret_used_at"],
                          row["activation_secret_expires_at"]))
        slots.extend((extra["secret_hash"], extra["used_at"], extra["expires_at"])
                     for extra in fetch_activation_extra_keys(conn, account_number))
    claimed = set()
    states = []
    checked_at = now_utc()
    for key in keys:
        index = next((i for i, slot in enumerate(slots)
                      if i not in claimed and activation_secret_matches(slot[0], key)), None)
        if index is None:
            states.append("unknown")
            continue
        claimed.add(index)
        _stored_hash, used_at, expires_at = slots[index]
        if used_at is not None:
            states.append("used")
        elif expires_at and ((parse_iso_datetime(expires_at) or checked_at) <= checked_at):
            states.append("expired")
        else:
            states.append("live")
    return states


def account_may_receive_keys(user, target_email: str) -> bool:
    # The authority every key mail needs, read from the users row under the
    # writer lock immediately before the keys are recovered, reused or minted
    # (K3-05): the account still exists and is active, its entitlement has not
    # run out, and the address the mail was queued for is still the one on the
    # account. A mail queued for a superseded address must never be sent.
    if user is None or user["status"] != "active":
        return False
    expiry = parse_iso_datetime(user["expiration_date"])
    if user["expiration_date"] and (expiry is None or expiry <= utcnow()):
        return False
    wanted = str(target_email or "").strip().lower()
    return bool(wanted) and str(user["email"] or "").strip().lower() == wanted


def issue_activation_secrets(
    conn: sqlite3.Connection,
    account_number: str,
    ttl: Optional[timedelta] = None,
    count: Optional[int] = None,
) -> list:
    # Mints the account's whole key set and returns the plaintext keys, slot 1
    # first. Like issue_activation_secret this REPLACES every earlier key of the
    # account, used or not, so a resend or a lapsed-account repurchase leaves
    # exactly one live set. The caller owns the transaction and must commit.
    # `count` can only lower the number of keys, never raise it above
    # DEVICE_LIMIT. All keys are written inside one savepoint: either every key
    # exists afterwards or the account's keys are exactly what they were.
    wanted = activation_key_count()
    if count is not None:
        wanted = max(1, min(int(count), wanted))
    if not conn.in_transaction:
        # RELEASE of an outermost savepoint commits. Open the transaction here
        # so the caller, not this function, decides when the keys become durable.
        conn.execute("BEGIN IMMEDIATE")
    conn.execute("SAVEPOINT activation_key_set")
    try:
        issued = [issue_activation_secret(conn, account_number, ttl)]
        row = conn.execute(
            "SELECT activation_secret_hash, activation_secret_expires_at FROM users WHERE account_number = ?",
            (account_number,),
        ).fetchone()
        if row is None:
            raise LookupError("setup keys can only be issued to an existing account")
        conn.execute("DELETE FROM activation_extra_keys WHERE account_number = ?", (account_number,))
        created_at = now_utc().isoformat(timespec="seconds")
        for slot in range(2, wanted + 1):
            secret = secrets.token_urlsafe(32)
            conn.execute(
                "INSERT INTO activation_extra_keys "
                "(key_id, account_number, slot, secret_hash, expires_at, created_at) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (secrets.token_hex(16), account_number, slot, _hash_activation_secret(secret),
                 row["activation_secret_expires_at"], created_at),
            )
            issued.append(secret)
    except BaseException:
        conn.execute("ROLLBACK TO SAVEPOINT activation_key_set")
        conn.execute("RELEASE SAVEPOINT activation_key_set")
        raise
    conn.execute("RELEASE SAVEPOINT activation_key_set")
    return issued


def verify_and_consume_activation_secret(
    conn: sqlite3.Connection,
    account_number: str,
    presented: str,
    *,
    consume: bool = True,
    consumed: Optional[dict] = None,
) -> bool:
    # `consumed`, when given, receives the slot and the stored secret_hash of
    # the key this call spent, and only when it spent one, so the caller can
    # record on the device row which key enrolled it (owner ruling 2026-10-25).
    if not presented:
        return False
    row = conn.execute(
        """
        SELECT activation_secret_hash,
               activation_secret_expires_at,
               activation_secret_used_at
          FROM users
         WHERE account_number = ?
        """,
        (account_number,),
    ).fetchone()

    # Every key slot of the account: slot 1 is the users row, slots 2..N are
    # activation_extra_keys rows. (table, key_id, hash, expires_at, used_at, slot)
    slots = []
    if row is not None:
        if row["activation_secret_hash"]:
            slots.append((
                "users", "", row["activation_secret_hash"],
                row["activation_secret_expires_at"], row["activation_secret_used_at"], 1,
            ))
        for extra in fetch_activation_extra_keys(conn, account_number):
            slots.append((
                "extra", extra["key_id"], extra["secret_hash"], extra["expires_at"], extra["used_at"],
                extra["slot"],
            ))

    if not slots:
        hmac.compare_digest(_ACTIVATION_DUMMY_HASH, _hash_activation_secret(presented))
        return False

    # Compare against every slot, with no early exit, then judge only the slot
    # that matched: its own used mark and its own expiry decide, so one key
    # being spent or expired never affects another key of the set.
    presented_hash = _hash_activation_secret(presented)
    legacy_digest = token_digest(presented)
    hits = [
        hmac.compare_digest(slot[2], presented_hash) | hmac.compare_digest(slot[2], legacy_digest)
        for slot in slots
    ]
    if not any(hits):
        return False
    table, key_id, stored_hash, expires_raw, used_at, slot_number = slots[hits.index(True)]

    if used_at is not None:
        return False

    if expires_raw:
        exp = parse_iso_datetime(expires_raw)
        if exp is None or exp <= now_utc():
            return False

    if not consume:
        return True

    used_now = now_utc().isoformat(timespec="seconds")
    if table == "users":
        cur = conn.execute(
            """
            UPDATE users
               SET activation_secret_used_at = ?
             WHERE account_number = ?
               AND activation_secret_used_at IS NULL
               AND activation_secret_hash = ?
               AND COALESCE(activation_secret_expires_at, '') = ?
            """,
            (used_now, account_number, stored_hash, expires_raw or ""),
        )
    else:
        cur = conn.execute(
            """
            UPDATE activation_extra_keys
               SET used_at = ?
             WHERE key_id = ?
               AND account_number = ?
               AND used_at IS NULL
               AND secret_hash = ?
               AND COALESCE(expires_at, '') = ?
            """,
            (used_now, key_id, account_number, stored_hash, expires_raw or ""),
        )
    if cur.rowcount != 1:
        return False
    if consumed is not None:
        consumed.clear()
        consumed.update(slot=int(slot_number), secret_hash=stored_hash)
    return True


def record_device_activation_key(
    conn: sqlite3.Connection,
    account_number: str,
    device_id: str,
    consumed: Optional[dict],
    *,
    pending: bool = False,
    clear: bool = False,
) -> None:
    # Owner ruling 2026-10-25 ("Key returns"): the device row remembers which
    # setup key admitted the device now on it, written in the transaction that
    # consumed the key, together with the bearer issued by that enrolment.
    # Every other write of the row by an enrolment replaces the record:
    #   pending: a Double VPN Core enrolment that commits its row before it
    #            spends the key. Slot 0 returns nothing and is the first row
    #            reused at the device cap, so a failed attempt never keeps an
    #            earlier device's key and never pushes a real device out.
    #   clear:   any other enrolment that spent no key. Free-access rows never
    #            carry a record, so they are not rewritten on every login.
    # A reconnect with the device's own bearer passes neither and keeps it.
    if consumed:
        conn.execute(
            "UPDATE devices SET activation_key_slot = ?, activation_key_hash = ?, "
            "activation_key_bearer_hash = device_auth_token_hash "
            "WHERE account_number = ? AND device_id = ?",
            (consumed["slot"], consumed["secret_hash"], account_number, device_id),
        )
    elif pending or clear:
        conn.execute(
            "UPDATE devices SET activation_key_slot = ?, activation_key_hash = NULL, "
            "activation_key_bearer_hash = NULL "
            "WHERE account_number = ? AND device_id = ?",
            (0 if pending else None, account_number, device_id),
        )


def return_device_activation_key(
    conn: sqlite3.Connection,
    account_number: str,
    slot,
    secret_hash: Optional[str],
) -> bool:
    # Owner ruling 2026-10-25 ("Key returns"): deactivating a device makes the
    # setup key that enrolled it valid again. Call it only after THIS
    # transaction deleted the device row that recorded (slot, secret_hash).
    # It clears the used mark of exactly that key: same account, same slot and
    # the hash still stored for that slot. A key set rotated since (hash
    # differs), a device enrolled before the ruling (nothing recorded) and a
    # record another device of the account still holds return nothing. The
    # key's expiry is never touched, so an expired key stays expired. Nothing
    # returns unless the account is active and unexpired right now, read in
    # this transaction with the hub's own expiry rule (expire_account_runtime_if_due):
    # a key spent before a lapse must not come back with a later renewal.
    if not account_number or slot is None or not secret_hash:
        return False
    try:
        slot = int(slot)
    except (TypeError, ValueError):
        return False
    if slot < 1:
        return False
    user = conn.execute(
        "SELECT status, expiration_date FROM users WHERE account_number = ?",
        (account_number,),
    ).fetchone()
    if user is None or str(user["status"] or "") != "active":
        return False
    raw_expiration = str(user["expiration_date"] or "").strip()
    expires_at = parse_iso_datetime(raw_expiration)
    if not raw_expiration or expires_at is None or utcnow() >= expires_at:
        return False
    if conn.execute(
        "SELECT 1 FROM devices WHERE account_number = ? AND activation_key_slot = ? "
        "AND activation_key_hash = ? LIMIT 1",
        (account_number, slot, secret_hash),
    ).fetchone() is not None:
        return False
    if slot == 1:
        cur = conn.execute(
            "UPDATE users SET activation_secret_used_at = NULL "
            "WHERE account_number = ? AND activation_secret_hash = ? "
            "AND activation_secret_used_at IS NOT NULL",
            (account_number, secret_hash),
        )
    else:
        cur = conn.execute(
            "UPDATE activation_extra_keys SET used_at = NULL "
            "WHERE account_number = ? AND slot = ? AND secret_hash = ? AND used_at IS NOT NULL",
            (account_number, slot, secret_hash),
        )
    return cur.rowcount == 1


def device_key_record_is_current(row) -> bool:
    # The record describes the device on the row only while the row still
    # carries the bearer issued with it. Any later enrolment rotates the
    # bearer, including one by an older hub build that does not know the
    # record exists, so a stale record never returns the earlier key.
    recorded_bearer = row["activation_key_bearer_hash"] or ""
    return bool(recorded_bearer) and hmac.compare_digest(
        recorded_bearer, row["device_auth_token_hash"] or ""
    )


def deactivate_device_returning_key(conn: sqlite3.Connection, account_number: str, device_id: str) -> int:
    # Deletes one device of the account and, when this call is the one that
    # removed it, returns the setup key it recorded, in the same transaction.
    # Only the owner's /logout and an admin or support removal of a device use
    # this; every other removal deletes the row and returns no key.
    if not conn.in_transaction:
        conn.execute("BEGIN IMMEDIATE")
    recorded = conn.execute(
        "SELECT activation_key_slot, activation_key_hash, activation_key_bearer_hash, "
        "device_auth_token_hash FROM devices WHERE account_number = ? AND device_id = ?",
        (account_number, device_id),
    ).fetchone()
    deleted = conn.execute(
        "DELETE FROM devices WHERE account_number = ? AND device_id = ?",
        (account_number, device_id),
    ).rowcount
    if deleted == 1 and recorded is not None and device_key_record_is_current(recorded):
        return_device_activation_key(
            conn, account_number, recorded["activation_key_slot"], recorded["activation_key_hash"],
        )
    return deleted


def deactivate_account_devices_returning_keys(conn: sqlite3.Connection, account_number: str) -> int:
    # A support device reset: every device of the account is deactivated and
    # each returns the key it recorded, in the same transaction.
    if not conn.in_transaction:
        conn.execute("BEGIN IMMEDIATE")
    recorded = conn.execute(
        "SELECT activation_key_slot, activation_key_hash, activation_key_bearer_hash, "
        "device_auth_token_hash FROM devices WHERE account_number = ?",
        (account_number,),
    ).fetchall()
    deleted = conn.execute("DELETE FROM devices WHERE account_number = ?", (account_number,)).rowcount
    if deleted:
        for row in recorded:
            if device_key_record_is_current(row):
                return_device_activation_key(
                    conn, account_number, row["activation_key_slot"], row["activation_key_hash"],
                )
    return deleted


def verify_advisory_request_authorized(
    conn: sqlite3.Connection,
    *,
    account_number: str,
    requested_client_public_key: str,
    request: Request,
) -> bool:
    bearer = bearer_token_from_request(request)
    if bearer:
        rows = conn.execute(
            "SELECT device_auth_token_hash FROM devices "
            "WHERE account_number = ? AND client_public_key = ?",
            (account_number, requested_client_public_key),
        ).fetchall()
        if any(device_auth_token_matches(row["device_auth_token_hash"], bearer) for row in rows):
            return True
    presented = request.headers.get("x-wins-activation", "").strip()
    if not presented:
        return False
    # Checked, never consumed: any one unused, unexpired key of the account
    # qualifies, exactly as the single users-row key did.
    return verify_and_consume_activation_secret(conn, account_number, presented, consume=False)


def _activation_outbox_keys() -> tuple[bytes, bytes]:
    root = hmac.new(_ACTIVATION_SECRET_PEPPER, b"wins-activation-outbox-root/v1", hashlib.sha256).digest()
    return (
        hmac.new(root, b"enc/v1", hashlib.sha256).digest(),
        hmac.new(root, b"mac/v1", hashlib.sha256).digest(),
    )


def _activation_outbox_stream(key: bytes, nonce: bytes, length: int) -> bytes:
    output = bytearray()
    for counter in range((length + 31) // 32):
        output.extend(hmac.new(key, nonce + counter.to_bytes(8, "big"), hashlib.sha256).digest())
    return bytes(output[:length])


def _activation_outbox_aad(delivery_id: str, account_number: str) -> bytes:
    return json.dumps([delivery_id, account_number], separators=(",", ":")).encode("utf-8")


# A sealed delivery carries a whole key set: one 43 character key per device
# slot plus a separator. 64 bytes per slot leaves room, and 256 stays the floor
# so a hub at the default limit keeps the bounds it always had. The sealed
# envelope (nonce, ciphertext and tag in base64) stays under twice the
# plaintext bound.
ACTIVATION_DELIVERY_MAX_PLAINTEXT = max(256, 64 * activation_key_count())
ACTIVATION_DELIVERY_MAX_SEALED = max(512, 2 * ACTIVATION_DELIVERY_MAX_PLAINTEXT)


def seal_activation_delivery(secret: str, delivery_id: str, account_number: str) -> str:
    # Encrypt-then-MAC with independent HMAC-SHA256 keys and a random nonce.
    # This uses the same stdlib PRF construction as the prepaid outbox, with
    # distinct keys and framing. HMAC alone would not conceal the credential.
    plaintext = secret.encode("utf-8")
    if not 1 <= len(plaintext) <= ACTIVATION_DELIVERY_MAX_PLAINTEXT:
        raise ValueError("invalid activation delivery secret length")
    enc_key, mac_key = _activation_outbox_keys()
    nonce = secrets.token_bytes(32)
    stream = _activation_outbox_stream(enc_key, nonce, len(plaintext))
    ciphertext = bytes(left ^ right for left, right in zip(plaintext, stream))
    aad = _activation_outbox_aad(delivery_id, account_number)
    tag = hmac.new(mac_key, b"wao1|" + aad + b"|" + nonce + ciphertext, hashlib.sha256).digest()
    return "wao1|" + "|".join(base64.b64encode(value).decode("ascii") for value in (nonce, ciphertext, tag))


def open_activation_delivery(sealed: str, delivery_id: str, account_number: str) -> str:
    if not isinstance(sealed, str) or len(sealed) > ACTIVATION_DELIVERY_MAX_SEALED:
        raise ValueError("invalid activation delivery envelope")
    parts = sealed.split("|")
    if len(parts) != 4 or parts[0] != "wao1":
        raise ValueError("invalid activation delivery envelope")
    try:
        nonce, ciphertext, tag = (base64.b64decode(value, validate=True) for value in parts[1:])
    except (ValueError, TypeError) as exc:
        raise ValueError("malformed activation delivery envelope") from exc
    if len(nonce) != 32 or len(tag) != 32 or not 1 <= len(ciphertext) <= ACTIVATION_DELIVERY_MAX_PLAINTEXT:
        raise ValueError("invalid activation delivery envelope lengths")
    enc_key, mac_key = _activation_outbox_keys()
    aad = _activation_outbox_aad(delivery_id, account_number)
    expected = hmac.new(mac_key, b"wao1|" + aad + b"|" + nonce + ciphertext, hashlib.sha256).digest()
    if not hmac.compare_digest(expected, tag):
        raise ValueError("activation delivery authentication failed")
    stream = _activation_outbox_stream(enc_key, nonce, len(ciphertext))
    return bytes(left ^ right for left, right in zip(ciphertext, stream)).decode("utf-8")


def enqueue_activation_delivery(
    conn: sqlite3.Connection, delivery_id: str, target_email: str,
    subscriber_name: str, account_number: str, plan_type: str, activation_secrets,
) -> None:
    # No commit here: granting access, event completion and delivery are atomic.
    # One row, one sealed bundle: every key of the set travels in the same
    # delivery, so a retry re-sends the same keys and never mints new ones.
    now = utcnow().isoformat()
    conn.execute("""
        INSERT INTO activation_delivery_outbox (
            delivery_id, account_number, target_email, subscriber_name,
            plan_type, sealed_secret, next_attempt_at, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        delivery_id, account_number, target_email.strip().lower(),
        subscriber_name or "Wins VPN User", plan_type,
        seal_activation_delivery(
            ACTIVATION_KEY_SEPARATOR.join(activation_key_list(activation_secrets)),
            delivery_id, account_number,
        ), now, now,
    ))


def claim_activation_delivery_batch(limit: int = 20) -> list[dict]:
    now = utcnow()
    now_text = now.isoformat()
    claimed = []
    with get_db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        rows = conn.execute("""
            SELECT * FROM activation_delivery_outbox
            WHERE (status IN ('pending', 'failed') OR (status='sending' AND lease_until <= ?))
              AND next_attempt_at <= ? AND (lease_until IS NULL OR lease_until <= ?)
            ORDER BY next_attempt_at, created_at LIMIT ?
        """, (now_text, now_text, now_text, max(1, min(int(limit), 100)))).fetchall()
        for row in rows:
            item = dict(row)
            item["lease_token"] = secrets.token_hex(16)
            item["attempts"] += 1
            conn.execute("""
                UPDATE activation_delivery_outbox SET status='sending', attempts=?, lease_token=?, lease_until=?
                WHERE delivery_id=?
            """, (item["attempts"], item["lease_token"], (now + timedelta(minutes=5)).isoformat(), item["delivery_id"]))
            claimed.append(item)
    return claimed


def finish_activation_delivery(item: dict, sent: bool, error: str = "") -> None:
    now = utcnow()
    delay = min(3600, 30 * (2 ** min(max(int(item["attempts"]) - 1, 0), 7)))
    with get_db() as conn:
        if sent:
            conn.execute("""
                UPDATE activation_delivery_outbox SET status='sent', sealed_secret='',
                    lease_token=NULL, lease_until=NULL, last_error=NULL, sent_at=?
                WHERE delivery_id=? AND status='sending' AND lease_token=?
            """, (now.isoformat(), item["delivery_id"], item["lease_token"]))
        else:
            conn.execute("""
                UPDATE activation_delivery_outbox SET status='failed', lease_token=NULL,
                    lease_until=NULL, next_attempt_at=?, last_error=?
                WHERE delivery_id=? AND status='sending' AND lease_token=?
            """, ((now + timedelta(seconds=delay)).isoformat(), error[:100] or "smtp_not_accepted",
                  item["delivery_id"], item["lease_token"]))


def _prepare_activation_delivery(item: dict) -> Optional[list]:
    # Revalidate custody immediately before delivery. A resend, consumption,
    # refund or deletion must not cause an obsolete key to be emailed. A
    # delivery carries a whole key set, so every key in it must still be one of
    # the account's current, unused keys or nothing is sent. Returns the keys
    # to mail, or None when the delivery was cancelled or its lease was lost.
    with get_db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        delivery = conn.execute("""
            SELECT sealed_secret FROM activation_delivery_outbox
            WHERE delivery_id=? AND status='sending' AND lease_token=? AND lease_until>?
        """, (item["delivery_id"], item["lease_token"], utcnow().isoformat())).fetchone()
        if delivery is None:
            return None
        keys = activation_key_list(
            open_activation_delivery(delivery["sealed_secret"], item["delivery_id"], item["account_number"])
        )
        user = conn.execute("""
            SELECT status, email, expiration_date FROM users WHERE account_number=?
        """, (item["account_number"],)).fetchone()
        # Every key of the delivery must still be one of the account's current,
        # unused, unexpired keys. A stored expiry is never refreshed or cleared
        # here: a queued or failed delivery does not prove its keys never
        # reached anyone, so an expired key stays expired and its mail is
        # cancelled instead.
        valid = (
            account_may_receive_keys(user, item["target_email"])
            and bool(keys)
            and all(state == "live" for state in activation_bundle_states(conn, item["account_number"], keys))
        )
        if not valid:
            conn.execute("""
                UPDATE activation_delivery_outbox SET status='cancelled', sealed_secret='',
                    lease_token=NULL, lease_until=NULL, last_error='credential_superseded_or_account_inactive'
                WHERE delivery_id=? AND lease_token=?
            """, (item["delivery_id"], item["lease_token"]))
            return None
    return keys


def drain_activation_delivery_outbox_once() -> int:
    sent_count = 0
    # Claim each message just before sending, so slow SMTP cannot age a batch
    # past its lease while another worker starts delivering the same messages.
    for _ in range(20):
        batch = claim_activation_delivery_batch(limit=1)
        if not batch:
            break
        item = batch[0]
        try:
            keys = _prepare_activation_delivery(item)
            if keys is None:
                continue
            sent = send_account_email(item["target_email"], item["subscriber_name"],
                                      item["account_number"], item["plan_type"], keys)
        except Exception as exc:
            # Exception text may contain addresses or credentials from SMTP.
            finish_activation_delivery(item, False, type(exc).__name__)
            continue
        finish_activation_delivery(item, bool(sent))
        sent_count += int(bool(sent))
    return sent_count


async def activation_delivery_outbox_sweep_loop() -> None:
    while True:
        try:
            await asyncio.to_thread(drain_activation_delivery_outbox_once)
        except Exception as exc:
            logger.error("Activation delivery outbox sweep failed: %s", type(exc).__name__)
        await asyncio.sleep(30)


_activation_delivery_task = None
_hub_wal_guard = None


def retain_hub_wal_sidecars():
    """Keep WAL metadata available to readers in read-only mount namespaces."""
    global _hub_wal_guard
    if _hub_wal_guard is not None:
        return
    connection = sqlite3.connect(Path(DB_PATH).resolve().as_uri() + '?mode=rw', uri=True, timeout=30)
    try:
        connection.execute('PRAGMA query_only=ON')
        if connection.execute('PRAGMA journal_mode').fetchone()[0].lower() != 'wal':
            raise sqlite3.OperationalError('Hub database must already be in WAL mode')
        # SQLite initializes the sidecars on the first database read. Do not
        # hold a transaction: writers and checkpoints must remain independent.
        connection.execute('SELECT 1 FROM sqlite_schema LIMIT 1').fetchall()
    except Exception:
        connection.close()
        raise
    _hub_wal_guard = connection


def release_hub_wal_sidecars():
    global _hub_wal_guard
    if _hub_wal_guard is not None:
        _hub_wal_guard.close()
        _hub_wal_guard = None


@app.on_event("shutdown")
async def stop_activation_delivery_worker():
    global _activation_delivery_task
    if _activation_delivery_task is not None:
        _activation_delivery_task.cancel()
        try:
            await _activation_delivery_task
        except asyncio.CancelledError:
            pass
        _activation_delivery_task = None
    release_hub_wal_sidecars()


def require_verify_authorization(
    *,
    activation_secret_hash: Optional[str],
    device_row: Optional[sqlite3.Row],
    requested_client_public_key: str,
    request: Request,
    account_number: str,
    activation_secret_expires_at: Optional[str] = None,
    additional_activation_secrets: tuple = (),
) -> str:
    # Returns "device" for a reconnect authorized by this exact device bearer token,
    # or "enrollment" for a caller who proved the account activation secret.
    # additional_activation_secrets holds the (hash, expires_at) pair of each
    # extra setup key (slots 2..N); any one of the account's keys proves it.
    if device_row is not None:
        key_unchanged = requested_client_public_key == (device_row["client_public_key"] or "")
        if key_unchanged and device_auth_token_matches(
            device_row["device_auth_token_hash"], bearer_token_from_request(request)
        ):
            return "device"
    activation_secret = request.headers.get("x-wins-activation", "").strip()
    checked_at = now_utc()

    def _expired(raw):
        parsed = parse_iso_datetime(raw) if raw else None
        return parsed is not None and parsed <= checked_at

    # The account's keys are expired only when every one of them is. The exact
    # per-key verdict (used, expired) is taken again at consumption time.
    if all(_expired(raw) for raw in [activation_secret_expires_at, *(item[1] for item in additional_activation_secrets)]):
        security_alert(2, "verify with expired activation secret", request=request, details={
            "account_hash": security_event_hash(account_number),
        })
        raise HTTPException(
            status_code=401,
            detail=SETUP_KEY_REFUSED_DETAIL if activation_secret else SETUP_KEY_REQUIRED_DETAIL,
        )
    if any([activation_secret_matches(stored, activation_secret)
            for stored in [activation_secret_hash, *(item[0] for item in additional_activation_secrets)]]):
        return "enrollment"
    security_alert(2, "verify without device token or activation secret", request=request, details={
        "account_hash": security_event_hash(account_number),
    })
    raise HTTPException(
        status_code=401,
        detail=SETUP_KEY_REFUSED_DETAIL if activation_secret else SETUP_KEY_REQUIRED_DETAIL,
    )

def smtp_dispatch_message(msg, to_email: str) -> bool:
    """The one SMTP2GO send path, extracted from send_account_email so the
    donor acknowledgment reuses the same transport, credentials, TLS setup and
    log lines instead of introducing a second provider or dependency."""
    try:
        with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=20) as server:
            server.ehlo()
            server.starttls(context=ssl.create_default_context())
            server.ehlo()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(msg["From"], to_email, msg.as_string())
        logger.info("SMTP dispatch sent")
        return True
    except Exception as exc:
        logger.error("SMTP dispatch failed: %s", exc)
        return False

