@app.post("/pay/wallet/create-order")
async def wallet_create_order(order_request: WalletCreateOrderRequest, request: Request):
    return await asyncio.to_thread(_wallet_create_order_sync, order_request, request)


def _wallet_create_order_sync(order_request: WalletCreateOrderRequest, request: Request):
    # Apple Pay / Google Pay / card checkout for the two FIXED-PRICE one-time
    # lifetime passes via PayPal Advanced Checkout (Orders v2). This only mints
    # a CAPTURE-intent order; the account grant happens later, when the
    # resulting PAYMENT.CAPTURE.COMPLETED webhook runs the exact same
    # classify_lifetime_payment -> validate_lifetime_payment_contract ->
    # upsert_paypal_account path the hosted-link lifetime purchases use. No
    # grant happens here, so wallet and redirect purchases provision
    # identically and cannot double- or under-grant.
    option_key = (order_request.option_key or "").strip()
    if option_key not in WALLET_LIFETIME_OPTION_KEYS:
        # Recurring (one_month/one_year) and variable (donation) options are
        # intentionally out of scope for wallet checkout.
        raise HTTPException(status_code=400, detail="Unsupported wallet payment option")
    if not paypal_enabled():
        raise HTTPException(status_code=503, detail="PayPal is not configured")
    try:
        amount_text, currency = resolve_wallet_lifetime_amount(option_key)
    except RuntimeError:
        raise HTTPException(status_code=503, detail="Lifetime pricing is not configured")
    referral_code = normalize_referral_code(order_request.referral_code)
    promo_code = normalize_promo_code(order_request.promo_code)
    with get_db() as conn:
        ensure_schema(conn)
        referrer = referral_account_for_code(conn, referral_code)
        # Same throttle + retention discipline as GET /pay before any PayPal
        # order-creation call.
        enforce_payment_click_limits(conn, request, option_key)
        record_payment_click(conn, request, option_key, "wallet", referral_code if referrer else "", referrer)
        promo_problem = checkout_promo_problem(conn, order_request.promo_code, promo_code, option_key, bool(referrer))
    # Raised after the block so the click and rate-limit increments commit.
    if promo_problem:
        raise HTTPException(status_code=400, detail=CHECKOUT_PROMO_MESSAGES[promo_problem])
    # custom_id is the one order field PayPal reliably echoes onto the capture
    # resource, so it carries both the classification marker (the exact
    # option_key, which classify_lifetime_payment matches) and, when present,
    # the normalized referral marker the webhook already understands
    # (wins_ref_<code>). Real referral codes are alphanumeric-only, so an
    # attacker-supplied code can never inject a lifetime/no_support marker.
    custom_id = option_key if not referrer else f"{option_key}|wins_ref_{referral_code}"
    custom_id = custom_id[:127]
    description = {
        "lifetime_support": "Win's VPN Lifetime Access + Tech Support",
        "lifetime_no_support": "Win's VPN Lifetime Access (No Tech Support)",
    }[option_key]
    payload = {
        "intent": "CAPTURE",
        "purchase_units": [
            {
                "reference_id": option_key,
                "custom_id": custom_id,
                "description": description[:127],
                "amount": {"currency_code": currency, "value": amount_text},
            }
        ],
    }
    # H-1: record the hub-owned order with the SERVER-resolved fixed lifetime
    # amount/currency BEFORE creating the PayPal order, so the capture webhook can
    # bind the returned PayPal order id back to a row THIS hub priced. Wallet
    # checkout collects the buyer email at PayPal, so buyer_email is stored empty
    # here and the payer email from PayPal is used at provision time (see the
    # PAYMENT.CAPTURE.COMPLETED branch); the referral, however, is taken from this
    # stored order, never re-parsed from the provider-echoed custom_id.
    hub_order_id = f"wins-wallet-{secrets.token_urlsafe(12)}"
    with get_db() as conn:
        ensure_schema(conn)
        conn.execute(
            """
            INSERT INTO payment_orders (
                hub_order_id, provider, plan_key, expected_amount,
                expected_currency, buyer_email, referral_code, status, created_at, promo_code
            ) VALUES (?, 'paypal_wallet', ?, ?, ?, '', ?, 'creating', ?, ?)
            """,
            (
                hub_order_id,
                option_key,
                amount_text,
                currency,
                referral_code if referrer else "",
                utcnow().isoformat(),
                promo_code,
            ),
        )
    try:
        result = paypal_json_request("POST", "/v2/checkout/orders", payload)
    except Exception as exc:
        logger.warning("PayPal wallet order creation failed: %s", exc)
        with get_db() as conn:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='paypal_wallet' AND status='creating'",
                (hub_order_id,),
            )
        raise HTTPException(status_code=502, detail="Unable to create PayPal order")
    order_id = str(result.get("id") or "")
    if not order_id or not re.fullmatch(r"[A-Za-z0-9-]{6,64}", order_id):
        logger.warning("PayPal wallet order creation returned no usable order id")
        with get_db() as conn:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='paypal_wallet' AND status='creating'",
                (hub_order_id,),
            )
        raise HTTPException(status_code=502, detail="Unable to create PayPal order")
    with get_db() as conn:
        bound = conn.execute(
            "UPDATE payment_orders SET provider_order_id=?, status='pending' WHERE hub_order_id=? AND provider='paypal_wallet' AND status='creating'",
            (order_id, hub_order_id),
        ).rowcount
        if bound != 1:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='paypal_wallet' AND status='creating'",
                (hub_order_id,),
            )
            logger.warning("Could not bind PayPal wallet order to its hub order")
            raise HTTPException(status_code=502, detail="Unable to create PayPal order")
    return {"order_id": order_id}

@app.post("/pay/wallet/capture")
async def wallet_capture(capture_request: WalletCaptureRequest, request: Request):
    return await asyncio.to_thread(_wallet_capture_sync, capture_request, request)


def _wallet_capture_sync(capture_request: WalletCaptureRequest, request: Request):
    # Capture an order minted by /pay/wallet/create-order. This endpoint does
    # NOT provision: a successful capture makes PayPal fire
    # PAYMENT.CAPTURE.COMPLETED, and /webhook/paypal is the single grant path
    # (idempotent, deduped on PayPal's own event id) shared with hosted-link
    # purchases. The audit row below is local defense-in-depth only.
    order_id = (capture_request.order_id or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9-]{6,64}", order_id):
        raise HTTPException(status_code=400, detail="Invalid order id")
    if not paypal_enabled():
        raise HTTPException(status_code=503, detail="PayPal is not configured")
    audit_event_id = f"wallet-capture:{order_id}"
    with get_db() as conn:
        ensure_schema(conn)
        check_rate_limit(conn, rate_limit_bucket("wallet-capture-ip", request_origin_bucket_value(request)), 20, 60)
        order = conn.execute(
            "SELECT plan_key, status FROM payment_orders "
            "WHERE provider='paypal_wallet' AND provider_order_id=?",
            (order_id,),
        ).fetchone()
        if order is None:
            raise HTTPException(status_code=404, detail="Unknown wallet order")
        if (order["plan_key"] not in WALLET_LIFETIME_OPTION_KEYS
                or order["status"] not in {"pending", "processing", "failed", "settled"}):
            raise HTTPException(status_code=409, detail="Wallet order is not eligible for capture")
        # Reserve one capture attempt; duplicates must be processed and
        # revalidated with PayPal before reporting capture success.
        first_attempt = reserve_paypal_event(conn, audit_event_id, "WALLET.CAPTURE", "")
        existing_event = conn.execute(
            "SELECT status FROM paypal_events WHERE event_id=?", (audit_event_id,)
        ).fetchone()
    if not first_attempt:
        if existing_event is None or existing_event["status"] != "processed":
            raise HTTPException(status_code=409, detail="PayPal capture is still processing")
        # Older releases recorded APPROVED or missing provider states as
        # processed. Revalidate that durable legacy state before reporting it.
        try:
            existing = paypal_json_request("GET", f"/v2/checkout/orders/{urllib.parse.quote(order_id)}")
        except Exception:
            raise HTTPException(status_code=502, detail="Unable to confirm PayPal capture")
        confirmed = isinstance(existing, dict) and str(existing.get("status") or "").upper() == "COMPLETED"
        if not confirmed:
            with get_db() as conn:
                finish_paypal_event(conn, audit_event_id, "failed", error="capture_not_confirmed")
            raise HTTPException(status_code=409, detail="PayPal capture has not completed")
        return {"status": "already_captured", "order_id": order_id}
    try:
        result = paypal_json_request("POST", f"/v2/checkout/orders/{urllib.parse.quote(order_id)}/capture")
    except Exception as exc:
        logger.warning("PayPal wallet capture failed: %s", exc)
        # A repeat capture of an already-completed order raises here (PayPal
        # 422 ORDER_ALREADY_CAPTURED). Confirm the order's real state: a
        # COMPLETED order is an idempotent success (the webhook has/will
        # provision it); anything else is a genuine failure.
        existing_status = ""
        try:
            existing = paypal_json_request("GET", f"/v2/checkout/orders/{urllib.parse.quote(order_id)}")
            existing_status = str(existing.get("status") or "").upper()
        except Exception:
            existing_status = ""
        with get_db() as conn:
            if existing_status == "COMPLETED":
                finish_paypal_event(conn, audit_event_id, "processed", error="already_captured")
            else:
                finish_paypal_event(conn, audit_event_id, "failed", error=str(exc)[:200])
        if existing_status == "COMPLETED":
            return {"status": "already_captured", "order_id": order_id}
        raise HTTPException(status_code=502, detail="Unable to capture PayPal order")
    order_status = str(result.get("status") or "").upper() if isinstance(result, dict) else ""
    if order_status != "COMPLETED":
        with get_db() as conn:
            finish_paypal_event(conn, audit_event_id, "failed", error="capture_not_completed")
        raise HTTPException(
            status_code=409 if order_status else 502,
            detail="PayPal capture has not completed",
        )
    with get_db() as conn:
        finish_paypal_event(conn, audit_event_id, "processed")
    return {"status": "COMPLETED", "order_id": order_id}

class CryptoInvoiceRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="ignore")
    plan_key: str = Field(validation_alias=AliasChoices("plan_key", "plankey", "plan"))
    referral_code: str = Field(default="", validation_alias=AliasChoices("referral_code", "referralcode", "ref"))
    promo_code: str = Field(default="", max_length=64, validation_alias=AliasChoices("promo_code", "promocode", "promo"))
    # Optional buyer identity. Provisioning needs an email (upsert_paypal_account
    # keys the account by it); the website can pass it here, otherwise BTCPay
    # captures it at checkout and the webhook reads metadata.buyerEmail.
    email: str = Field(default="", validation_alias=AliasChoices("email", "buyer_email", "buyeremail"))
    name: str = Field(default="", validation_alias=AliasChoices("name", "buyer_name", "buyername"))

@app.post("/pay/crypto/create-invoice")
async def crypto_create_invoice(invoice_request: CryptoInvoiceRequest, request: Request):
    return await asyncio.to_thread(_crypto_create_invoice_sync, invoice_request, request)


def _crypto_create_invoice_sync(invoice_request: CryptoInvoiceRequest, request: Request):
    # Self-hosted crypto (BTC/XMR/DASH) checkout via a BTCPay Greenfield invoice.
    # Exactly like /pay/wallet/create-order this ONLY mints an invoice and NEVER
    # grants access; /webhook/btcpay is the single, idempotent grant path, so a
    # crypto purchase provisions through the same upsert_paypal_account primitive
    # as PayPal and can neither double- nor under-grant.
    plan_key = (invoice_request.plan_key or "").strip()
    if plan_key not in CRYPTO_PLAN_KEYS:
        raise HTTPException(status_code=400, detail="Unsupported crypto plan")
    if not btcpay_checkout_enabled():
        raise HTTPException(status_code=503, detail="Crypto payments are not configured")
    referral_code = normalize_referral_code(invoice_request.referral_code)
    promo_code = normalize_promo_code(invoice_request.promo_code)
    buyer_email = (invoice_request.email or "").strip().lower()[:254]
    if buyer_email:
        if any(ord(char) < 32 or ord(char) == 127 for char in buyer_email) or not MONERO_EMAIL_RE.fullmatch(buyer_email):
            raise HTTPException(status_code=400, detail="Invalid email address")
    buyer_name = re.sub(r"[\x00-\x1f\x7f]", "", (invoice_request.name or "")).strip()[:128]
    amount_usd = ""
    with get_db() as conn:
        ensure_schema(conn)
        referrer = referral_account_for_code(conn, referral_code)
        # Same throttle + retention discipline as GET /pay before any invoice call.
        enforce_payment_click_limits(conn, request, plan_key)
        record_payment_click(conn, request, plan_key, "crypto", referral_code if referrer else "", referrer)
        promo_problem = checkout_promo_problem(conn, invoice_request.promo_code, promo_code, plan_key, bool(referrer))
        try:
            amount_usd = validate_crypto_amount(crypto_price_usd(conn, plan_key))
        except RuntimeError:
            amount_usd = ""
    # Raise AFTER the block so the click + rate-limit increment durably commit
    # even when pricing is unconfigured (mirrors wallet_create_order's ordering).
    if promo_problem:
        raise HTTPException(status_code=400, detail=CHECKOUT_PROMO_MESSAGES[promo_problem])
    if not amount_usd:
        raise HTTPException(status_code=503, detail="Crypto pricing is not configured")
    hub_order_id = f"wins-crypto-{secrets.token_urlsafe(12)}"
    metadata = {
        "plan_key": plan_key,
        "hub_order_id": hub_order_id,
        "orderId": hub_order_id,
        "hub_source": "crypto",
        "itemDesc": f"Win's VPN {crypto_plan_label(plan_key)}",
    }
    if referrer:
        # Only a resolvable, alphanumeric-only referral code is forwarded, so it
        # can never smuggle a lifetime/no_support control marker into the grant.
        metadata["referral"] = referral_code
    if buyer_email:
        metadata["buyerEmail"] = buyer_email
    if buyer_name:
        metadata["buyerName"] = buyer_name
    # H-1: record the hub-owned order with the SERVER-resolved expected amount
    # BEFORE the outbound BTCPay call, so /webhook/btcpay can bind the returned
    # invoice id back to a row THIS hub priced. A foreign invoice on the shared
    # store -- even one whose mutable metadata names a valuable plan -- matches
    # no payment_orders row and therefore can never provision. Only referral
    # codes that resolved to a real referrer are persisted (never raw input).
    with get_db() as conn:
        ensure_schema(conn)
        conn.execute(
            """
            INSERT INTO payment_orders (
                hub_order_id, provider, plan_key, expected_amount,
                expected_currency, buyer_email, referral_code, status, created_at, promo_code
            ) VALUES (?, 'btcpay', ?, ?, 'USD', ?, ?, 'creating', ?, ?)
            """,
            (
                hub_order_id,
                plan_key,
                amount_usd,
                buyer_email,
                referral_code if referrer else "",
                utcnow().isoformat(),
                promo_code,
            ),
        )
    try:
        invoice = btcpay_create_invoice(amount_usd, metadata)
    except Exception as exc:
        logger.warning("BTCPay invoice creation failed: %s", exc)
        with get_db() as conn:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='btcpay' AND status='creating'",
                (hub_order_id,),
            )
        raise HTTPException(status_code=502, detail="Unable to create crypto invoice")
    invoice_id = str(invoice.get("id") or "")
    checkout_url = ""
    try:
        checkout_url = validated_btcpay_checkout_url(invoice.get("checkoutLink"))
    except ValueError:
        logger.warning("BTCPay invoice returned an invalid checkout origin")
    # H-1: require a well-formed invoice id, then atomically bind it to the order
    # (creating -> pending). Until this bind lands the order is unprovisionable,
    # and it can only ever be claimed once by the settlement webhook.
    if not invoice_id or not checkout_url or not re.fullmatch(r"[A-Za-z0-9_-]{8,128}", invoice_id):
        logger.warning("BTCPay invoice creation returned an incomplete or malformed invoice")
        with get_db() as conn:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='btcpay' AND status='creating'",
                (hub_order_id,),
            )
        raise HTTPException(status_code=502, detail="Unable to create crypto invoice")
    with get_db() as conn:
        bound = conn.execute(
            "UPDATE payment_orders SET provider_order_id=?, status='pending' WHERE hub_order_id=? AND provider='btcpay' AND status='creating'",
            (invoice_id, hub_order_id),
        ).rowcount
        if bound != 1:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='btcpay' AND status='creating'",
                (hub_order_id,),
            )
            logger.warning("Could not bind BTCPay invoice to its hub order")
            raise HTTPException(status_code=502, detail="Unable to create crypto invoice")
    return {
        "invoice_id": invoice_id,
        "invoiceid": invoice_id,
        "checkout_url": checkout_url,
        "checkouturl": checkout_url,
        "plan_key": plan_key,
    }

