@app.post("/pay/monero/create-order")
async def monero_create_order(order_request: MoneroOrderRequest, request: Request):
    return await asyncio.to_thread(_monero_create_order_sync, order_request, request)


def _monero_create_order_sync(order_request: MoneroOrderRequest, request: Request):
    # Maximum-privacy Monero-direct order. Like /pay/crypto/create-invoice and
    # /pay/wallet/create-order this ONLY mints a receive address and records a
    # pending order; it NEVER grants. run_monero_poll_sweep is the single,
    # idempotent grant path once the payment confirms on-chain. No public checkout
    # page and no inbound webhook are involved.
    plan_key = (order_request.plan_key or "").strip()
    if plan_key not in CRYPTO_PLAN_KEYS:
        raise HTTPException(status_code=400, detail="Unsupported crypto plan")
    if not monero_rpc_enabled():
        raise HTTPException(status_code=503, detail="Monero payments are not configured")
    referral_code = normalize_referral_code(order_request.referral_code)
    promo_code = normalize_promo_code(order_request.promo_code)
    # L-9/L-10: a Monero order has NO checkout page to collect an address later, so a
    # valid delivery email is MANDATORY up front -- otherwise a paid order could only
    # ever dead-letter into manual_review. The settle sweep keeps a no-email safety net
    # for legacy pending rows created before this requirement.
    try:
        buyer_email = normalize_monero_buyer_email(order_request.email)
    except ValueError:
        raise HTTPException(status_code=400, detail="A valid delivery email is required for Monero orders")
    referrer = ""
    amount_usd = ""
    manual_hint = ""
    last_quote_text = ""
    with get_db() as conn:
        ensure_schema(conn)
        referrer = referral_account_for_code(conn, referral_code)
        # Same throttle + retention discipline as /pay and the BTCPay path.
        enforce_payment_click_limits(conn, request, plan_key)
        record_payment_click(conn, request, plan_key, "monero", referral_code if referrer else "", referrer)
        promo_problem = checkout_promo_problem(conn, order_request.promo_code, promo_code, plan_key, bool(referrer))
        manual_hint = (get_setting(conn, "monero_price_manual_usd", "") or "").strip()
        # M-6: the last persisted live quote is the deviation baseline for the oracle.
        last_quote_text = (get_setting(conn, "monero_last_quote_usd_per_xmr", "") or "").strip()
        try:
            amount_usd = validate_crypto_amount(crypto_price_usd(conn, plan_key))
        except RuntimeError:
            amount_usd = ""
    # Raise AFTER the block so the click + rate-limit increment durably commit even
    # when pricing is unconfigured (mirrors the BTCPay path's ordering).
    if promo_problem:
        raise HTTPException(status_code=400, detail=CHECKOUT_PROMO_MESSAGES[promo_problem])
    if not amount_usd:
        raise HTTPException(status_code=503, detail="Crypto pricing is not configured")
    # M-6: resolve the XMR/USD rate under the price-oracle bounds (allowlisted HTTPS
    # origins, no redirects, capped body, median-of->=2 OR <=20% deviation from the last
    # persisted quote). The network fetch runs OUTSIDE any db block so no writer lock is
    # held during the price I/O. quote_source/quote_at are persisted with the order.
    last_quote = _to_positive_decimal(last_quote_text) or Decimal(0)
    try:
        usd_per_xmr, quote_source = resolve_monero_usd_per_xmr(manual_hint, last_quote)
        amount_atomic = monero_usd_to_atomic(amount_usd, usd_per_xmr)
    except RuntimeError as exc:
        # Price feed unavailable / unparseable / beyond the reviewed deviation bound --
        # 503 and NEVER guess a rate.
        logger.warning("Monero price conversion unavailable: %s", exc)
        raise HTTPException(status_code=503, detail="Monero pricing is temporarily unavailable")
    if amount_atomic <= 0:
        raise HTTPException(status_code=503, detail="Monero pricing is temporarily unavailable")
    quote_usd_per_xmr_text = format(usd_per_xmr, "f")
    quote_at = utcnow().isoformat()
    hub_order_id = f"wins-monero-{secrets.token_urlsafe(12)}"
    # H-1: record the hub-owned order with the SERVER-resolved expected USD amount
    # BEFORE minting the receive address, so the settle sweep can bind and verify
    # against a row THIS hub priced. Monero orders are only ever created here (no
    # external party), so this is defense-in-depth provenance atop monero_orders.
    def _retire_creating_monero_order() -> None:
        with get_db() as conn:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='monero' AND status='creating'",
                (hub_order_id,),
            )
    with get_db() as conn:
        ensure_schema(conn)
        conn.execute(
            """
            INSERT INTO payment_orders (
                hub_order_id, provider, plan_key, expected_amount,
                expected_currency, buyer_email, referral_code, status, created_at, promo_code
            ) VALUES (?, 'monero', ?, ?, 'USD', ?, ?, 'creating', ?, ?)
            """,
            (
                hub_order_id,
                plan_key,
                amount_usd,
                buyer_email,
                referral_code if referrer else "",
                utcnow().isoformat(),
                promo_code,
            ),
        )
    try:
        # Mint a FRESH subaddress under account 0, labelled with the order id.
        address_result = monero_rpc("create_address", {"account_index": 0, "label": hub_order_id})
    except Exception as exc:
        logger.warning("Monero create_address failed: %s", exc)
        _retire_creating_monero_order()
        raise HTTPException(status_code=502, detail="Unable to create Monero order")
    subaddress = str(address_result.get("address") or "")
    raw_index = address_result.get("address_index")
    if not subaddress or raw_index is None:
        logger.warning("Monero create_address returned an incomplete address")
        _retire_creating_monero_order()
        raise HTTPException(status_code=502, detail="Unable to create Monero order")
    try:
        subaddress_index = int(raw_index)
    except (TypeError, ValueError):
        logger.warning("Monero create_address returned a non-integer address_index")
        _retire_creating_monero_order()
        raise HTTPException(status_code=502, detail="Unable to create Monero order")
    created_at = utcnow()
    expires_at = created_at + timedelta(minutes=MONERO_ORDER_TTL_MINUTES)
    amount_xmr = monero_atomic_to_xmr_str(amount_atomic)
    with get_db() as conn:
        ensure_schema(conn)
        conn.execute("""
            INSERT INTO monero_orders (
                hub_order_id, subaddress, subaddress_index, plan_key, amount_atomic,
                referral_code, buyer_email, status, created_at, expires_at, tx_hash,
                quote_usd_per_xmr, quote_source, quote_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, '', ?, ?, ?)
        """, (
            hub_order_id, subaddress, subaddress_index, plan_key, amount_atomic,
            referral_code if referrer else "", buyer_email, created_at.isoformat(), expires_at.isoformat(),
            quote_usd_per_xmr_text, quote_source, quote_at,
        ))
        # M-6: advance the deviation baseline only from a LIVE quote; a manual override
        # must not silently move the band future live quotes are checked against.
        if quote_source != "manual":
            set_setting(conn, "monero_last_quote_usd_per_xmr", quote_usd_per_xmr_text)
        # H-1: bind the minted subaddress as this order's provider id and flip it
        # live (creating -> pending). If the bind cannot land, retire BOTH rows so
        # nothing dangles as grantable.
        bound = conn.execute(
            "UPDATE payment_orders SET provider_order_id=?, status='pending' WHERE hub_order_id=? AND provider='monero' AND status='creating'",
            (subaddress, hub_order_id),
        ).rowcount
        if bound != 1:
            conn.execute(
                "UPDATE payment_orders SET status='failed' WHERE hub_order_id=? AND provider='monero' AND status='creating'",
                (hub_order_id,),
            )
            conn.execute(
                "UPDATE monero_orders SET status='expired' WHERE hub_order_id=? AND status='pending'",
                (hub_order_id,),
            )
            logger.warning("Could not bind Monero subaddress to its hub order")
            raise HTTPException(status_code=502, detail="Unable to create Monero order")
    return {
        "order_id": hub_order_id,
        "orderid": hub_order_id,
        "address": subaddress,
        "amount_xmr": amount_xmr,
        "amountxmr": amount_xmr,
        "amount_atomic": amount_atomic,
        "amountatomic": amount_atomic,
        "expires_at": expires_at.isoformat(),
        "expiresat": expires_at.isoformat(),
        "plan_key": plan_key,
        "plankey": plan_key,
    }

