def _render_referral_landing_sync(referral_code: str, request: Request):
    code = normalize_referral_code(referral_code)
    if not code:
        raise HTTPException(status_code=404, detail="Referral link not found")
    with get_db() as conn:
        ensure_schema(conn)
        referrer = referral_account_for_code(conn, code)
        if not referrer:
            raise HTTPException(status_code=404, detail="Referral link not found")
        display_name_row = conn.execute("SELECT subscriber_name FROM users WHERE account_number = ?", (referrer,)).fetchone()
        display_name = (display_name_row["subscriber_name"] if display_name_row else "a Win's VPN user") or "a Win's VPN user"
        options = payment_options(code, relative_urls=True, source="referral")
        # M-5: throttle + retention before recording the referral-landing click.
        enforce_payment_click_limits(conn, request, "referral_landing")
        record_payment_click(conn, request, "referral_landing", "referral", code, referrer)
    links = "\n".join(
        f'<a class="option" href="{html.escape(option["url"])}">{html.escape(option["label"])}</a>'
        for option in options
        if option.get("kind") != "donation"
    )
    body = f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Win's VPN Referral</title>
  <style>
    body {{ margin:0; font-family: Arial, sans-serif; background:#eef9ff; color:#102033; }}
    main {{ max-width: 620px; margin: 0 auto; padding: 48px 20px; }}
    h1 {{ margin: 0 0 12px; font-size: 32px; }}
    p {{ line-height: 1.55; }}
    .option {{ display:block; margin:12px 0; padding:15px 16px; border-radius:8px; background:#1266f1; color:white; text-decoration:none; font-weight:700; }}
    .note {{ margin-top:22px; color:#3f5369; font-size:14px; }}
  </style>
</head>
<body>
  <main>
    <h1>Start Win's VPN</h1>
    <p>{html.escape(display_name)} invited you. After your activation is completed, both accounts receive 20% extra VPN time.</p>
    {links}
    <p class="note">Referral bonuses are applied automatically after PayPal confirms the purchase.</p>
  </main>
</body>
</html>"""
    return HTMLResponse(body)

