@app.post("/account/status")
async def account_status(
    status_request: AccountStatusRequest,
    request: Request,
    background_tasks: BackgroundTasks,
):
    return await asyncio.to_thread(
        _account_status_sync, status_request, request, background_tasks
    )


def _account_status_sync(
    status_request: AccountStatusRequest,
    request: Request,
    background_tasks: BackgroundTasks,
):
    acc = normalize_account_number(status_request.account_number)
    dev_id = (status_request.device_id or "").strip()
    if not dev_id:
        raise HTTPException(status_code=401, detail="Unauthorized")
    with get_db() as conn:
        ensure_schema(conn)
        check_rate_limit(
            conn,
            rate_limit_bucket("account-status-ip", request_origin_bucket_value(request)),
            VERIFY_IP_RATE_LIMIT_PER_MINUTE,
            60,
        )
        check_rate_limit(
            conn,
            rate_limit_bucket("account-status-account", acc),
            VERIFY_ACCOUNT_RATE_LIMIT_PER_HOUR,
            3600,
        )
        # The /logout pattern (L77): persist the increments before the bearer
        # check, or its 401 (and the 404 below) rolls them back and a failing
        # caller is never limited. Only ensure_schema and the buckets precede.
        conn.commit()
        require_device_auth_token(conn, acc, dev_id, request, action="account status")
        user_row = conn.execute(
            "SELECT status, expiration_date FROM users WHERE account_number = ?",
            (acc,),
        ).fetchone()
        if not user_row:
            raise HTTPException(status_code=404, detail="Account not found")
        user = dict(user_row)
        if expire_account_runtime_if_due(conn, acc, background_tasks):
            user["status"] = "expired"
        exp_out = str(user.get("expiration_date") or "")
        payload = {
            "status": "ok" if user.get("status") == "active" else user.get("status"),
            "account_number": acc,
            "accountnumber": acc,
            "expiration_date": exp_out,
            "expirationdate": exp_out,
            **announcement_fields(conn),
        }
        payload.update(account_referral_payload(conn, acc))
    return payload

