@app.post("/legal/accept")
def legal_accept():
    # M-6: this endpoint used to write a legal_acceptances row from a bare,
    # unauthenticated account_number+device_id supplied directly by the
    # caller -- anyone could forge an acceptance record for any account, or
    # grow the table without bound, without ever proving they controlled
    # that account or device. Legal acceptance is now recorded only as a
    # transactional side effect of authenticated activation (paid /verify or
    # server-derived /free/verify), via ensure_legal_acceptance_for_activation,
    # which stamps the exact current document hash/flags for a real device
    # row. This route is retired; legacy callers get a stable, unambiguous
    # response instead of a silent 404.
    raise HTTPException(status_code=410, detail="This endpoint has been retired. Legal acceptance is recorded automatically during activation.")

@app.post("/verify")
async def verify_account(fastapi_request: Request, login: LoginRequest, background_tasks: BackgroundTasks):
    try:
        return await _verify_account_impl(fastapi_request, login, background_tasks)
    except HTTPException as exc:
        logger.warning("verify_account HTTPException on %s: %s %s", fastapi_request.url.path, exc.status_code, exc.detail)
        raise
    except Exception as exc:
        logger.exception("verify_account unhandled crash on %s: %s", fastapi_request.url.path, exc)
        raise

async def _verify_account_impl(fastapi_request: Request, login: LoginRequest, background_tasks: BackgroundTasks):
    return await asyncio.to_thread(
        _verify_account_sync, fastapi_request, login, background_tasks
    )


def _verify_account_sync(fastapi_request: Request, login: LoginRequest, background_tasks: BackgroundTasks):
    deferred_activation_secret = ""
    authorization_kind = ""
    double_vpn_lease_token = ""
    # The slot and stored hash of the setup key this request spends, recorded
    # on the device row in the same transaction (owner ruling 2026-10-25).
    consumed_activation_key = {}
    logger.info("Verify request received: path=%s login_free_access=%s account_hash=%s", fastapi_request.url.path, login.free_access, security_event_hash(normalize_account_number(login.account_number)))
    if fastapi_request.url.path == "/verify":
        # M-4: /free/verify (see verify_free_access below) calls this same
        # function directly with a LoginRequest it built itself server-side,
        # free_access already set correctly for that trusted path -- so this
        # check must not affect it. request.url.path reflects the route
        # Starlette actually matched to reach this code, which a caller
        # cannot spoof: only a genuine call to the public, paid /verify
        # route lands here with this path. A caller-supplied free_access
        # flag on that route must never relax paid rate limiting or device
        # limit enforcement, so force it off before any of that logic runs.
        login.free_access = False
    acc = normalize_account_number(login.account_number)
    try:
        requested_client_public_key = validate_wireguard_public_key(login.client_public_key)
    except HTTPException:
        alert_failed_login(fastapi_request, "invalid_client_public_key", acc, detail="Invalid client public key.", status_code=400)
    # Client-owned winn/3 identity (Fable 5.1 ruling 2026-09-29). Validated
    # before any database work, like client_public_key above.
    requested_winn3_static_public = validate_winn3_static_public(login.winn3_static_public)
    try:
        client_owns_winn3_key = winn3_capability_bool(
            login.supports_winn3_client_key, "supports_winn3_client_key"
        )
        # w3r/2: supports_winn3_relay is an `Any` wire field (a `bool` would coerce
        # "true" and 1 into a capability the client never advertised), so the strict
        # check runs HERE, before any database work. The full capability map is
        # rebuilt later in the request; checking late would leave the AmneziaWG
        # Double's committed Core assignment behind a 400.
        winn3_capability_bool(
            getattr(login, "supports_winn3_relay", None), "supports_winn3_relay"
        )
    except Winn3ContractError as exc:
        raise HTTPException(
            status_code=400,
            detail="Client capability advertisement is malformed.",
        ) from exc
    if requested_winn3_static_public and requested_winn3_static_public == requested_client_public_key:
        raise HTTPException(
            status_code=400,
            detail="winn3 static public key must not reuse the AWG client key.",
        )
    if not requested_client_public_key and not WINN3_HUB_MINTED_KEYS_ALLOWED:
        # The legacy AmneziaWG mint (and the serving of a stored hub-minted
        # AWG private key) ends with the same lever as the winn/3 mint. The
        # free path has always refused this; see _prepare_free_login_sync.
        raise HTTPException(status_code=400, detail="Client public key is required.")
    selection_generation, ordinary_v3_failure_generation = typed_selection_generations(login)

    with ExitStack() as deferred_cleanup, get_db() as conn:
        ensure_schema(conn)
        cleanup_stale_devices(conn, background_tasks)
        if not login.free_access:
            try:
                enforce_verify_rate_limits(conn, fastapi_request, acc)
            except HTTPException:
                security_alert(3, "rate-limited app login", request=fastapi_request, details={
                    "account_hash": security_event_hash(acc),
                })
                raise
            # No commit needed: the precheck above is read-only and has nothing
            # to flush. The failure bucket is committed by
            # consume_verify_auth_failure at the point a failure is determined.
        if len("".join(filter(str.isdigit, acc))) != 12:
            # C3: MALFORMED, not a credential failure. No bucket consumed.
            alert_failed_login(fastapi_request, "invalid_account_format", acc, detail="Invalid account format.", status_code=400)
        if get_setting(conn, "maintenance_mode", "false") == "true":
            raise HTTPException(status_code=503, detail="System Maintenance underway.")

        user_row = conn.execute(
            "SELECT status, expiration_date, hardware_hash, email, subscriber_name, renewal_source, activation_secret_hash, activation_secret_expires_at FROM users WHERE account_number = ?",
            (acc,),
        ).fetchone()
        if not user_row:
            # C3: a GENUINE credential failure -- an account number that does
            # not exist is exactly what credential guessing looks like. This is
            # the one place on /verify that consumes the backoff budget.
            if not login.free_access:
                consume_verify_auth_failure(conn, fastapi_request, acc)
            alert_failed_login(fastapi_request, "account_not_found", acc)
        user = dict(user_row)
        is_free_access_account = (
            acc == FREE_ACCESS_ACCOUNT_NUMBER
            or (user.get("renewal_source") or "") == "free_access"
        )
        if is_free_access_account and not login.free_access:
            raise HTTPException(status_code=403, detail="Free account must use the free server.")
        if user.get("status") != "active":
            alert_failed_login(fastapi_request, "account_inactive", acc)
        if expire_account_runtime_if_due(conn, acc, background_tasks):
            # alert_failed_login raises. Commit the status, device deletion,
            # and durable revocation outbox before returning that terminal 401.
            conn.commit()
            alert_failed_login(fastapi_request, "account_expired", acc, detail="Account Expired. Renew subscription.")
        device_identity = (login.device_fingerprint or login.device_id or "").strip()
        device_bucket = device_identity_bucket(device_identity)
        source_bucket = security_event_hash(f"device-source:{request_origin_bucket_value(fastapi_request)}")
        selected_slug = (login.location or "auto").strip().lower()
        smart_recommended_slug = ""
        smart_router_trigger = "connection_initiation"
        if selected_slug in {"", "auto"} and not login.free_access:
            # Advisory work happens before BEGIN IMMEDIATE so a slow or failed
            # AI service never holds the activation writer lock. The selected
            # slug is revalidated for policy, health, and capacity below.
            route_device_row = conn.execute(
                "SELECT location_slug FROM devices WHERE account_number = ? AND device_id = ?",
                (acc, login.device_id),
            ).fetchone()
            if not route_device_row and device_bucket:
                route_device_row = conn.execute(
                    """
                    SELECT location_slug FROM devices
                    WHERE account_number = ? AND hardware_hash = ?
                    ORDER BY last_seen DESC
                    LIMIT 1
                    """,
                    (acc, device_bucket),
                ).fetchone()
            if not route_device_row and not login.free_access:
                _recog_model = (login.device_model or "").strip()
                _clean_recog = re.sub(r"\s*\([a-zA-Z0-9_-]+\)$", "", _recog_model).strip().lower()
                _generic = {"", "unknown", "android", "device", "unknown android", "unknown device", "android device", "ios device", "windows device", "linux device", "mac device", "app", "audit-harness"}
                if _clean_recog and _clean_recog not in _generic:
                    _cands = conn.execute("SELECT location_slug, device_model FROM devices WHERE account_number = ? ORDER BY last_seen DESC", (acc,)).fetchall()
                    for _c in _cands:
                        _cm = re.sub(r"\s*\([a-zA-Z0-9_-]+\)$", "", (_c["device_model"] or "").strip()).strip().lower()
                        if _cm and _cm not in _generic and (_clean_recog == _cm or _clean_recog in _cm or _cm in _clean_recog):
                            route_device_row = _c
                            break
            route_existing_slug = (
                str(route_device_row["location_slug"] or "").strip().lower()
                if route_device_row else ""
            )
            if not verify_advisory_request_authorized(
                conn, account_number=acc,
                requested_client_public_key=requested_client_public_key,
                request=fastapi_request,
            ):
                consume_verify_auth_failure(conn, fastapi_request, acc)
                raise HTTPException(
                    status_code=401,
                    detail=(
                        SETUP_KEY_REFUSED_DETAIL
                        if fastapi_request.headers.get("x-wins-activation", "").strip()
                        else SETUP_KEY_REQUIRED_DETAIL
                    ),
                )
            # Cleanup issued DELETEs before advisory authorization and therefore
            # owns SQLite's implicit writer transaction even before BEGIN IMMEDIATE.
            # Persist only that housekeeping now. Admission authority is re-read
            # under the explicit writer lock after the advisory returns.
            conn.commit()
            smart_router_trigger = smart_router_trigger_for_existing_node(
                conn,
                route_existing_slug,
            )
            smart_recommended_slug = smart_router_recommend_node(
                conn,
                existing_slug=route_existing_slug,
                platform=login.platform,
                free_only=False,
                trigger=smart_router_trigger,
                selection_generation=selection_generation,
                ordinary_v3_failure_generation=ordinary_v3_failure_generation,
            )
        # M-1: locate the device and authorize the paid activation BEFORE any
        # account or legal mutation. The commit here only flushes the earlier
        # schema/cleanup/rate-limit work so BEGIN IMMEDIATE starts on a clean
        # writer transaction (cleanup_stale_devices leaves an open transaction on
        # the free path); it deliberately no longer persists any hardware_hash or
        # legal-acceptance record. Serializing admission in one writer transaction
        # also stops simultaneous requests from all seeing the final free slot
        # before any of them committed. If authorization fails below, the whole
        # transaction -- including the mutations that follow it -- is rolled back.
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        # Re-read authority after acquiring the admission writer lock.
        # Earlier routing advice cannot authorize a revoked account or key.
        user_row = conn.execute(
            "SELECT status, expiration_date, hardware_hash, email, subscriber_name, renewal_source, activation_secret_hash, activation_secret_expires_at FROM users WHERE account_number = ?",
            (acc,),
        ).fetchone()
        if user_row is None or user_row["status"] != "active":
            raise HTTPException(status_code=401, detail="Account is no longer active.")
        user = dict(user_row)
        if expire_account_runtime_if_due(conn, acc, background_tasks):
            conn.commit()
            raise HTTPException(status_code=401, detail="Account Expired. Renew subscription.")
        if not login.free_access and (
            acc == FREE_ACCESS_ACCOUNT_NUMBER
            or (user.get("renewal_source") or "") == "free_access"
        ):
            raise HTTPException(status_code=403, detail="Free account must use the free server.")
        mark_stale_nodes_offline(conn)
        device_row = conn.execute("SELECT * FROM devices WHERE account_number = ? AND device_id = ?", (acc, login.device_id)).fetchone()
        if not device_row and device_bucket:
            device_row = conn.execute(
                """
                SELECT * FROM devices
                WHERE account_number = ? AND hardware_hash = ?
                ORDER BY last_seen DESC
                LIMIT 1
                """,
                (acc, device_bucket),
            ).fetchone()
        if not device_row and not login.free_access:
            _recog_model = (login.device_model or "").strip()
            _clean_recog = re.sub(r"\s*\([a-zA-Z0-9_-]+\)$", "", _recog_model).strip().lower()
            _generic = {"", "unknown", "android", "device", "unknown android", "unknown device", "android device", "ios device", "windows device", "linux device", "mac device", "app", "audit-harness"}
            if _clean_recog and _clean_recog not in _generic:
                _cands = conn.execute("SELECT * FROM devices WHERE account_number = ? ORDER BY last_seen DESC", (acc,)).fetchall()
                for _c in _cands:
                    _cm = re.sub(r"\s*\([a-zA-Z0-9_-]+\)$", "", (_c["device_model"] or "").strip()).strip().lower()
                    if _cm and _cm not in _generic and (_clean_recog == _cm or _clean_recog in _cm or _cm in _clean_recog):
                        device_row = _c
                        break
        if not device_row and login.free_access and login.device_id.startswith("free-"):
            device_row = conn.execute("SELECT * FROM devices WHERE device_id = ?", (login.device_id,)).fetchone()
        if not device_row and not login.free_access:
            count = conn.execute("SELECT COUNT(*) AS cnt FROM devices WHERE account_number = ?", (acc,)).fetchone()["cnt"]
            effective_limit = _hoppy_effective_device_limit(conn, acc)
            if count >= effective_limit:
                # A Double VPN Core enrolment that never spent its key
                # (activation_key_slot 0) is reused before any real device.
                device_row = conn.execute(
                    """
                    SELECT * FROM devices
                    WHERE account_number = ?
                    ORDER BY CASE WHEN activation_key_slot = 0 THEN 0 ELSE 1 END ASC,
                             COALESCE(last_seen, '1970-01-01T00:00:00') ASC
                    LIMIT 1
                    """,
                    (acc,),
                ).fetchone()
        if not login.free_access:
            # H-1: free access is a shared, secret-less account by design
            # (see FREE_ACCESS_ACCOUNT_NUMBER) and is out of scope here --
            # every paid account_number+device_id combination must clear
            # this check before any device row is created, reassigned, or
            # has its public key rotated below.
            try:
                authorization_kind = require_verify_authorization(
                    activation_secret_hash=user.get("activation_secret_hash"),
                    device_row=device_row,
                    requested_client_public_key=requested_client_public_key,
                    request=fastapi_request,
                    account_number=acc,
                    activation_secret_expires_at=user.get("activation_secret_expires_at"),
                    additional_activation_secrets=tuple(
                        (extra["secret_hash"], extra["expires_at"])
                        for extra in fetch_activation_extra_keys(conn, acc)
                    ),
                )
                if authorization_kind == "enrollment":
                    presented = fastapi_request.headers.get("x-wins-activation", "").strip()
                    # Core readiness requires an intermediate commit. Keep
                    # enrollment retryable until its final response is ready.
                    if not verify_and_consume_activation_secret(
                        conn, acc, presented, consume=not bool(login.double_vpn),
                        consumed=consumed_activation_key,
                    ):
                        raise HTTPException(
                            status_code=401,
                            detail=SETUP_KEY_REFUSED_DETAIL,
                        )
                    if login.double_vpn:
                        deferred_activation_secret = presented
            except HTTPException as exc:
                if exc.status_code == 401:
                    conn.rollback()
                    consume_verify_auth_failure(conn, fastapi_request, acc)
                raise

        if requested_winn3_static_public:
            # After authorization, so an unauthenticated caller cannot probe
            # which keys exist; before any write this request makes. The
            # rollback also undoes an activation-key consumption above.
            own_device_ids = {login.device_id}
            if device_row:
                own_device_ids.add(str(device_row["device_id"] or ""))
                if requested_winn3_static_public == str(device_row["client_public_key"] or "").strip():
                    conn.rollback()
                    raise HTTPException(
                        status_code=400,
                        detail="winn3 static public key must not reuse the AWG client key.",
                    )
            if winn3_static_public_in_use(
                conn, requested_winn3_static_public, own_device_ids=own_device_ids
            ):
                conn.rollback()
                raise HTTPException(
                    status_code=409,
                    detail="This winn3 key is already registered to another device.",
                    headers={"X-Wins-Error-Code": "winn3_static_public_in_use"},
                )

        # M-1: only after authorization (or the deliberate free-access skip) do we
        # persist the legacy hardware_hash and the signed legal-acceptance record,
        # in the same transaction as the device admission below.
        if not user.get("hardware_hash"):
            conn.execute("UPDATE users SET hardware_hash = ? WHERE account_number = ?", (device_bucket or device_identity_bucket(login.device_id), acc))
        ensure_legal_acceptance_for_activation(
            conn,
            fastapi_request,
            login,
            acc,
            user.get("email") or "",
            login.device_id,
        )
        existing_location_slug = str(device_row["location_slug"] or "").strip().lower() if device_row else ""

        if login.free_access:
            node_row = select_free_node(
                conn,
                selected_slug,
                existing_slug=existing_location_slug,
                platform=login.platform,
                selection_generation=selection_generation,
                ordinary_v3_failure_generation=ordinary_v3_failure_generation,
            )
        else:
            node_row = select_online_node(
                conn,
                selected_slug,
                require_selected=selected_slug not in {"", "auto"},
                existing_slug=existing_location_slug,
                platform=login.platform,
                preferred_slug=smart_recommended_slug,
                advisory_is_distress=smart_router_trigger == "distress",
                selection_generation=selection_generation,
                ordinary_v3_failure_generation=ordinary_v3_failure_generation,
            )
        if not node_row:
            if login.free_access:
                raise HTTPException(status_code=503, detail="Free VPN server is not online yet.")
            if selected_slug not in {"", "auto"}:
                raise HTTPException(status_code=503, detail="Selected VPN server is unavailable or full.")
            raise HTTPException(status_code=503, detail="No VPN nodes currently online.")
        node = dict(node_row)
        if node.get("status") == "congested":
            raise HTTPException(status_code=503, detail="Server is currently full.")
        if node.get("status") in {"maintenance", "offline"}:
            raise HTTPException(status_code=503, detail="Server is offline or in maintenance.")
        consumes_new_slot = not device_row or existing_location_slug != str(node.get("slug") or "").strip().lower()
        if consumes_new_slot and not node_accepts_new_peer(conn, node):
            raise HTTPException(status_code=503, detail="Server is currently full. Please choose another location.")
        # Paid only (owner ruling 2026-10-13): a free account is refused Double VPN
        # whatever the legacy double_vpn_free_access setting says.
        if login.free_access and login.double_vpn:
            raise HTTPException(status_code=403, detail="Double VPN is not available for free access.")
        double_vpn_requested = bool(login.double_vpn and not login.free_access)
        core = select_double_vpn_core(conn) if double_vpn_requested else None
        if double_vpn_requested and not core:
            raise HTTPException(status_code=503, detail="Double VPN core is not available yet.")
        # w3r/1: a ciphertext relay Double VPN. When every relay gate holds this
        # device is a plain single-hop winn/3 device for assignment purposes (no
        # Core assignment row, no Core acknowledgement wait, no enrollment
        # lease) and `double_relay` carries the Double labels and the relay
        # endpoint. Any failing gate leaves double_relay None and the request
        # continues below exactly as it did before this lane.
        double_relay = None
        if double_vpn_requested and core and winn3_relay_enabled():
            # The inner pool gate needs to know whether this request will rotate
            # the device's winn3 identity (which nulls its address and makes the
            # allocator issue a new one): the SAME three conditions as
            # rotate_winn3_identity below, evaluated before anything is written.
            relay_rotates_identity = bool(device_row) and bool(
                ((device_row["device_id"] or login.device_id) != login.device_id)
                or (
                    requested_client_public_key
                    and requested_client_public_key != (device_row["client_public_key"] or "").strip()
                )
                or (not login.free_access and authorization_kind == "enrollment")
            )
            double_relay = resolve_served_double_relay(
                conn, login=login, node=node, core=core,
                device_row=device_row, rotates_identity=relay_rotates_identity,
            )
        if double_relay:
            double_vpn_requested = False
            if deferred_activation_secret:
                # The deferral exists for the Core wait this path never makes:
                # consume the activation key now, in this transaction, exactly
                # as a single hop enrollment does. A rollback below undoes it.
                if not verify_and_consume_activation_secret(
                    conn, acc, deferred_activation_secret, consumed=consumed_activation_key
                ):
                    conn.rollback()
                    consume_verify_auth_failure(conn, fastapi_request, acc)
                    raise HTTPException(
                        status_code=401,
                        detail=SETUP_KEY_REFUSED_DETAIL,
                    )
                deferred_activation_secret = ""
        if double_vpn_requested and deferred_activation_secret:
            double_vpn_lease_token = acquire_double_vpn_enrollment_lease(
                conn, acc, login.device_id
            )
            deferred_cleanup.callback(
                release_double_vpn_enrollment_lease,
                acc,
                double_vpn_lease_token,
            )

        old_peer_to_remove = ""
        old_peer_node_ip = ""
        old_location_slug = ""
        # The previous gateway's bounded Winn3 departure grace, when this
        # request moves an unchanged v3 identity (see issue_winn3_departure_grant).
        winn3_departure = None
        # L77 (Sol RF-1): set when an unchanged v3 identity leaves a node that
        # node_admits_peer() refuses; answered with a 503 before remote writes.
        winn3_departure_closed = False
        winn3_identity_rotated = False
        # Set when this request REPLACES the device's winn/3 public key with a
        # client-owned one while keeping its inner address (ruling, Q1 Step 1).
        winn3_client_key_replaced = False
        # Issue a fresh bearer for enrollment, including slot replacement.
        # Authenticated reconnects retain their bearer; legacy rows are backfilled.
        issued_device_auth_token = None
        if device_row:
            device_cfg = dict(device_row)
            old_device_id = device_cfg.get("device_id") or login.device_id
            old_public_key = (device_cfg.get("client_public_key") or "").strip()
            old_location_slug = device_cfg.get("location_slug") or ""
            if old_location_slug and old_location_slug != node["slug"]:
                old_node = conn.execute("SELECT endpoint, ssh_host FROM nodes WHERE slug = ?", (old_location_slug,)).fetchone()
                if old_node:
                    old_peer_node_ip = old_node["ssh_host"] or extract_node_host(old_node["endpoint"] or "")
                if old_public_key:
                    old_peer_to_remove = old_public_key
            if requested_client_public_key and requested_client_public_key != old_public_key:
                old_peer_to_remove = old_public_key
                if old_location_slug:
                    old_node = conn.execute("SELECT endpoint, ssh_host FROM nodes WHERE slug = ?", (old_location_slug,)).fetchone()
                    if old_node:
                        old_peer_node_ip = old_node["ssh_host"] or extract_node_host(old_node["endpoint"] or "")
                device_cfg["client_private_key"] = ""
                device_cfg["client_public_key"] = requested_client_public_key
                device_cfg["preshared_key"] = maybe_generate_preshared_key()
            elif not AWG_PRESHARED_KEYS_ENABLED and (device_cfg.get("preshared_key") or ""):
                device_cfg["preshared_key"] = ""
            if requested_client_public_key and (device_cfg.get("client_private_key") or ""):
                # The device supplied its own AWG key and it equals the stored
                # public: never keep, or serve, a hub-minted private copy.
                device_cfg["client_private_key"] = ""
            if (not login.free_access and authorization_kind == "enrollment") or not (device_cfg.get("device_auth_token_hash") or ""):
                issued_device_auth_token = secrets.token_urlsafe(32)
                device_cfg["device_auth_token_hash"] = token_digest(issued_device_auth_token)
            rotate_winn3_identity = (
                old_device_id != login.device_id
                or (requested_client_public_key and requested_client_public_key != old_public_key)
                or (not login.free_access and authorization_kind == "enrollment")
            )
            # A client-supplied winn/3 public key that differs from the one on
            # file replaces it: the private copy is NULLed, the inner address is
            # kept, and the old key is retired (no departure grace for it).
            # This runs on every /verify, served v3 or not, so a hub-minted key
            # leaves the database the first time its device checks in on a
            # client-key build; the devices UPDATE trigger queues the registry
            # republish that stops the gateway admitting the old key.
            winn3_client_key_replaced = bool(
                not rotate_winn3_identity
                and requested_winn3_static_public
                and requested_winn3_static_public
                != (device_cfg.get("winn3_static_public") or "").strip()
            )
            winn3_identity_rotated = bool(rotate_winn3_identity or winn3_client_key_replaced)
            if rotate_winn3_identity:
                conn.execute(
                    "UPDATE devices SET winn3_inner_v4=NULL, "
                    "winn3_static_private=NULL, winn3_static_public=NULL WHERE device_id=?",
                    (old_device_id,),
                )
                for field in ("winn3_inner_v4", "winn3_static_private", "winn3_static_public"):
                    device_cfg[field] = ""
            elif winn3_client_key_replaced:
                try:
                    conn.execute(
                        "UPDATE devices SET winn3_static_public=?, winn3_static_private=NULL "
                        "WHERE device_id=?",
                        (requested_winn3_static_public, old_device_id),
                    )
                except sqlite3.IntegrityError as exc:
                    # The UNIQUE backstop caught what the admission check did
                    # not. Same answer as that check, and nothing committed.
                    if not winn3_static_public_conflict(exc):
                        raise
                    conn.rollback()
                    raise HTTPException(
                        status_code=409,
                        detail="This winn3 key is already registered to another device.",
                        headers={"X-Wins-Error-Code": "winn3_static_public_in_use"},
                    ) from None
                device_cfg["winn3_static_public"] = requested_winn3_static_public
                device_cfg["winn3_static_private"] = ""
            elif requested_winn3_static_public and (device_cfg.get("winn3_static_private") or "").strip():
                conn.execute(
                    "UPDATE devices SET winn3_static_private=NULL WHERE device_id=?",
                    (old_device_id,),
                )
                device_cfg["winn3_static_private"] = ""
            seen_at = utcnow().isoformat()
            conn.execute(
                """
                UPDATE devices
                SET device_id = ?, last_seen = ?, updated_at = ?, device_model = ?, location_slug = ?,
                    account_number = ?,
                    hardware_hash = ?, source_ip_bucket = ?,
                    client_private_key = ?, client_public_key = ?, preshared_key = ?,
                    device_auth_token_hash = ?
                WHERE device_id = ?
                """,
                (
                    login.device_id,
                    seen_at,
                    seen_at,
                    login.device_model,
                    node["slug"],
                    acc,
                    device_bucket,
                    source_bucket,
                    device_cfg.get("client_private_key") or "",
                    device_cfg.get("client_public_key") or "",
                    device_cfg.get("preshared_key") or "",
                    device_cfg.get("device_auth_token_hash") or "",
                    old_device_id,
                ),
            )
            if old_location_slug and old_location_slug != node["slug"]:
                # Arriving at a node supersedes any grant this device still
                # holds there, and leaving a node replaces any older one.
                retire_winn3_departure_grants(
                    conn, login.device_id, (node["slug"], old_location_slug)
                )
                # L46 F2 (repo port, lane L57): a closed node carries no
                # customer authorization, so leaving it earns no allowance
                # there and charges nothing to the account's departure budget.
                # L77 (Sol RF-1): the switch no longer takes the immediate-
                # removal branch; it is deferred before any remote write (see
                # winn3_departure_closed below).
                old_node_row = conn.execute(
                    "SELECT * FROM nodes WHERE slug = ?", (old_location_slug,)
                ).fetchone()
                winn3_departure_closed = bool(
                    old_node_row is not None
                    and not node_admits_peer(old_node_row)
                    and not winn3_identity_rotated
                    and str(device_cfg.get("account_number") or "") == acc
                    and (device_cfg.get("winn3_static_public") or "").strip()
                    and (device_cfg.get("winn3_inner_v4") or "").strip()
                )
                if (
                    node_admits_peer(old_node_row)
                    and not winn3_identity_rotated
                    and str(device_cfg.get("account_number") or "") == acc
                    and (device_cfg.get("winn3_static_public") or "").strip()
                    and (device_cfg.get("winn3_inner_v4") or "").strip()
                ):
                    winn3_departure = {
                        "device_id": login.device_id,
                        "account_number": acc,
                        "node_slug": old_location_slug,
                        "static_public": device_cfg["winn3_static_public"],
                        "inner_v4": device_cfg["winn3_inner_v4"],
                    }
            if device_bucket and (login.free_access or authorization_kind == "enrollment"):
                duplicate_rows = conn.execute(
                    """
                    SELECT d.client_public_key, d.location_slug, n.endpoint, n.ssh_host
                    FROM devices d
                    LEFT JOIN nodes n ON n.slug = d.location_slug
                    WHERE d.account_number = ? AND d.hardware_hash = ? AND d.device_id != ?
                    """,
                    (acc, device_bucket, login.device_id),
                ).fetchall()
                for duplicate in duplicate_rows:
                    duplicate_key = (duplicate["client_public_key"] or "").strip()
                    if duplicate_key:
                        duplicate_node_ip = duplicate["ssh_host"] or extract_node_host(duplicate["endpoint"] or "")
                        if duplicate_node_ip:
                            queue_peer_revocation(conn, duplicate_node_ip, duplicate_key, background_tasks)
                conn.execute(
                    "DELETE FROM devices WHERE account_number = ? AND hardware_hash = ? AND device_id != ?",
                    (acc, device_bucket, login.device_id),
                )
            _recog_model = (login.device_model or "").strip()
            _clean_recog = re.sub(r"\s*\([a-zA-Z0-9_-]+\)$", "", _recog_model).strip().lower()
            _generic = {"", "unknown", "android", "device", "unknown android", "unknown device", "android device", "ios device", "windows device", "linux device", "mac device", "app", "audit-harness"}
            if _clean_recog and _clean_recog not in _generic and not login.free_access and authorization_kind == "enrollment":
                _dup_rows = conn.execute("SELECT device_id, device_model, client_public_key, location_slug FROM devices WHERE account_number = ? AND device_id != ?", (acc, login.device_id)).fetchall()
                for _dup in _dup_rows:
                    _dm = re.sub(r"\s*\([a-zA-Z0-9_-]+\)$", "", (_dup["device_model"] or "").strip()).strip().lower()
                    if _dm and _dm not in _generic and (_clean_recog == _dm or _clean_recog in _dm or _dm in _clean_recog):
                        _dk = (_dup["client_public_key"] or "").strip()
                        _ds = _dup["location_slug"] or ""
                        if _dk and _ds:
                            _dn = conn.execute("SELECT endpoint, ssh_host FROM nodes WHERE slug = ?", (_ds,)).fetchone()
                            if _dn:
                                _dip = _dn["ssh_host"] or extract_node_host(_dn["endpoint"] or "")
                                if _dip:
                                    queue_peer_revocation(conn, _dip, _dk, background_tasks)
                        conn.execute("DELETE FROM devices WHERE device_id = ?", (_dup["device_id"],))
            device_cfg["device_id"] = login.device_id
            device_cfg["hardware_hash"] = device_bucket
            device_cfg["source_ip_bucket"] = source_bucket
            device_cfg["device_model"] = login.device_model
            device_cfg["location_slug"] = node["slug"]
        else:
            count = conn.execute("SELECT COUNT(*) AS cnt FROM devices WHERE account_number = ?", (acc,)).fetchone()["cnt"]
            if not login.free_access and count >= _hoppy_effective_device_limit(conn, acc):
                alert_failed_login(fastapi_request, "device_limit_reached", acc, detail="Device limit reached. Log out of another device first.", status_code=429)
            if requested_client_public_key:
                client_private_key = ""
                client_public_key = requested_client_public_key
                preshared_key = maybe_generate_preshared_key()
            else:
                client_private_key, client_public_key, preshared_key = generate_wireguard_material()
                if not AWG_PRESHARED_KEYS_ENABLED:
                    preshared_key = ""
            issued_device_auth_token = secrets.token_urlsafe(32)
            device_cfg = {
                "device_id": login.device_id,
                "account_number": acc,
                "device_model": login.device_model,
                "hardware_hash": device_bucket,
                "source_ip_bucket": source_bucket,
                "vpn_internal_ip": allocate_internal_ip(conn),
                "client_private_key": client_private_key,
                "client_public_key": client_public_key,
                "preshared_key": preshared_key,
                "last_seen": utcnow().isoformat(),
                "location_slug": node["slug"],
                "device_auth_token_hash": token_digest(issued_device_auth_token),
            }
            conn.execute("""
                INSERT INTO devices (
                    device_id, account_number, device_model, hardware_hash, source_ip_bucket,
                    vpn_internal_ip, client_private_key, client_public_key, preshared_key,
                    last_seen, location_slug, updated_at, device_auth_token_hash
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                device_cfg["device_id"], device_cfg["account_number"], device_cfg["device_model"],
                device_cfg["hardware_hash"], device_cfg["source_ip_bucket"], device_cfg["vpn_internal_ip"],
                device_cfg["client_private_key"], device_cfg["client_public_key"], device_cfg["preshared_key"],
                device_cfg["last_seen"], device_cfg["location_slug"], device_cfg["last_seen"],
                device_cfg["device_auth_token_hash"],
            ))
        # Owner ruling 2026-10-25 ("Key returns"): the row the request just
        # wrote records the key it spent, so deactivating it returns that key.
        record_device_activation_key(
            conn, acc, login.device_id, consumed_activation_key,
            pending=bool(deferred_activation_secret),
            clear=authorization_kind == "enrollment",
        )

        device_cfg["node_max_peers"] = normalized_node_max_peers(node.get("max_peers"))
        double_assignment = None
        core_exit_peer = None
        if double_vpn_requested and core:
            core_exit_peer = ensure_core_exit_peer(conn, core["core_id"], node["slug"])
            assignment_row = conn.execute(
                "SELECT * FROM double_vpn_assignments WHERE device_id = ?",
                (login.device_id,),
            ).fetchone()
            core_client_ip = assignment_row["client_ip"] if assignment_row else allocate_core_client_ip(conn)
            assigned_at = assignment_row["assigned_at"] if assignment_row else utcnow().isoformat()
            seen_at = utcnow().isoformat()
            conn.execute(
                """
                INSERT INTO double_vpn_assignments (
                    device_id, account_number, core_id, exit_slug, client_public_key,
                    client_ip, preshared_key, status, assigned_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
                ON CONFLICT(device_id) DO UPDATE SET
                    account_number=excluded.account_number,
                    core_id=excluded.core_id,
                    exit_slug=excluded.exit_slug,
                    client_public_key=excluded.client_public_key,
                    client_ip=excluded.client_ip,
                    preshared_key=excluded.preshared_key,
                    status='active',
                    applied_revision=CASE
                        WHEN double_vpn_assignments.status='active'
                         AND double_vpn_assignments.core_id=excluded.core_id
                         AND double_vpn_assignments.exit_slug=excluded.exit_slug
                         AND double_vpn_assignments.client_public_key=excluded.client_public_key
                         AND double_vpn_assignments.client_ip=excluded.client_ip
                         AND COALESCE(double_vpn_assignments.preshared_key,'')=COALESCE(excluded.preshared_key,'')
                        THEN double_vpn_assignments.applied_revision
                        ELSE NULL
                    END,
                    runtime_validated_at=CASE
                        WHEN double_vpn_assignments.status='active'
                         AND double_vpn_assignments.core_id=excluded.core_id
                         AND double_vpn_assignments.exit_slug=excluded.exit_slug
                         AND double_vpn_assignments.client_public_key=excluded.client_public_key
                         AND double_vpn_assignments.client_ip=excluded.client_ip
                         AND COALESCE(double_vpn_assignments.preshared_key,'')=COALESCE(excluded.preshared_key,'')
                        THEN double_vpn_assignments.runtime_validated_at
                        ELSE NULL
                    END,
                    updated_at=excluded.updated_at
                """,
                (
                    login.device_id,
                    acc,
                    core["core_id"],
                    node["slug"],
                    device_cfg.get("client_public_key") or "",
                    core_client_ip,
                    device_cfg.get("preshared_key") or "",
                    assigned_at,
                    seen_at,
                ),
            )
            conn.execute(
                "UPDATE double_vpn_assignments SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL, updated_at=? WHERE account_number=? AND device_id != ? AND client_public_key=?",
                (seen_at, acc, login.device_id, device_cfg.get("client_public_key") or ""),
            )
            double_assignment = conn.execute(
                "SELECT * FROM double_vpn_assignments WHERE device_id = ?",
                (login.device_id,),
            ).fetchone()
        else:
            conn.execute(
                "UPDATE double_vpn_assignments SET status='inactive', applied_revision=NULL, runtime_validated_at=NULL, updated_at=? WHERE device_id=?",
                (utcnow().isoformat(), login.device_id),
            )

        direct_endpoint = node.get("endpoint") or ""
        stealth_endpoint = node.get("stealth_endpoint") or ""
        if not direct_endpoint or not node.get("public_key"):
            raise HTTPException(status_code=503, detail="Selected node is missing runtime keys.")
        if login.stealth_mode and not stealth_endpoint:
            raise HTTPException(status_code=503, detail="Selected node has no Xray stealth endpoint registered.")

        node_ssh_host = node.get("ssh_host") or extract_node_host(node.get("endpoint") or "")
        if double_vpn_requested and core and core_exit_peer:
            if not sync_peer_to_node(node_ssh_host, {
                "client_public_key": core["exit_public_key"],
                "vpn_internal_ip": core_exit_peer["core_exit_ip"],
                "preshared_key": "",
                "node_max_peers": node.get("max_peers"),
            }):
                conn.rollback()
                mark_node_management_status(conn, node["slug"], "failed", "double vpn exit peer sync failed")
                conn.commit()
                raise HTTPException(status_code=503, detail="Selected Double VPN exit node is not ready. Please try again in a minute.")
            mark_node_management_status(conn, node["slug"], "ok")
        if old_peer_to_remove and old_peer_node_ip:
            queue_peer_revocation(conn, old_peer_node_ip, old_peer_to_remove, background_tasks)

        if double_vpn_requested and core and double_assignment:
            assignment_payload = next(
                (
                    item
                    for item in active_core_assignment_payloads(conn, core["core_id"])
                    if item["device_id"] == login.device_id
                ),
                None,
            )
            if not assignment_payload:
                raise HTTPException(
                    status_code=503,
                    detail="Double VPN assignment is not available for Core synchronization.",
                )
            expected_assignment_revision = assignment_payload["assignment_revision"]
            # Release the SQLite writer before waiting. The Core pull agent
            # cannot observe or acknowledge this exact assignment revision
            # until the transaction is durable.
            conn.commit()
            if not _wait_for_core_assignment_ready_sync(
                core["core_id"], login.device_id, expected_assignment_revision
            ):
                logger.warning(
                    "Core assignment readiness timed out core=%s device=%s revision=%s",
                    mask_id(core["core_id"]),
                    mask_id(login.device_id),
                    expected_assignment_revision[:12],
                )
                raise HTTPException(
                    status_code=503,
                    detail="Double VPN Core assignment is still being prepared. Please try again.",
                    headers={
                        "X-Wins-Error-Code": "double_vpn_assignment_preparing",
                        "Retry-After": "5",
                    },
                )
            # Authority may have changed while the Core prepared this assignment.
            # Hold the writer lock through final validation and consumption.
            conn.execute("BEGIN IMMEDIATE")
            current = conn.execute(
                "SELECT d.device_auth_token_hash, u.status, u.expiration_date "
                "FROM devices d JOIN users u ON u.account_number=d.account_number "
                "WHERE d.device_id=? AND d.account_number=?",
                (login.device_id, acc),
            ).fetchone()
            current_expiry = parse_iso_datetime(current["expiration_date"]) if current else None
            current_assignment = next(
                (item for item in active_core_assignment_payloads(conn, core["core_id"])
                 if item["device_id"] == login.device_id),
                None,
            )
            if (
                current is None
                or current["status"] != "active"
                or current_expiry is None
                or current_expiry <= utcnow()
                or current["expiration_date"] != user.get("expiration_date")
                or not hmac.compare_digest(
                    current["device_auth_token_hash"] or "",
                    device_cfg.get("device_auth_token_hash") or "",
                )
                or current_assignment is None
                or not hmac.compare_digest(
                    current_assignment["assignment_revision"], expected_assignment_revision
                )
            ):
                raise HTTPException(
                    status_code=409,
                    detail="Double VPN enrollment changed while preparing. Please retry.",
                )

        stealth_host, stealth_port = split_host_port(stealth_endpoint, int(node.get("stealth_public_port") or 80))
        _, direct_port = split_host_port(direct_endpoint, int(node.get("wg_port") or 9110))
        regional_aliases = parse_aliases(node.get("regional_aliases"))
        config_direct_awg_enabled = bool(
            node.get("direct_awg_enabled")
            if node.get("direct_awg_enabled") is not None else 1
        )
        config_client_ip = device_cfg["vpn_internal_ip"]
        config_tunnel_gateway_ipv4 = normalize_private_tunnel_gateway_ipv4(
            node.get("tunnel_gateway_ipv4")
        )
        config_server_public_key = node.get("public_key")
        config_server_endpoint = direct_endpoint
        config_stealth_endpoint = stealth_endpoint
        config_protocol = "xray-vless-ws+amneziawg" if login.stealth_mode else "amneziawg"
        config_dns = "10.8.1.1"
        config_xray_uuid = (node.get("xray_uuid") or "").strip()
        config_xray_host = stealth_host
        config_xray_port = stealth_port
        config_xray_server_name = node.get("xray_sni") or stealth_host
        config_xray_path = node.get("xray_path") or "/wins-stealth-tunnel"
        config_xray_security = (node.get("xray_security") or "none").lower()
        config_xray_transports = parse_xray_transports(
            node.get("stealth_transports"), config_xray_port, config_xray_security
        )
        config_xray_remote_awg_port = int(node.get("wg_port") or direct_port or 9110)
        if login.stealth_mode and not re.fullmatch(
            r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}",
            config_xray_uuid,
        ):
            raise HTTPException(status_code=503, detail="Selected node has no valid Xray identity registered.")
        if double_vpn_requested and core and double_assignment:
            # The data-plane/customer AWG default remains UDP 9110. The
            # physical Double VPN first hop has a distinct 9210 fallback; an
            # explicit registered port still wins.
            core_host, core_port = split_host_port(core["ingress_endpoint"], 9210)
            if not core_host or not core["ingress_public_key"]:
                raise HTTPException(status_code=503, detail="Double VPN core is missing ingress runtime data.")
            core_stealth_host, core_stealth_port = split_host_port(core["stealth_endpoint"] or "", 80)
            if login.stealth_mode and (not core_stealth_host or not core["xray_uuid"]):
                raise HTTPException(status_code=503, detail="Double VPN stealth core is not registered yet.")
            config_client_ip = double_assignment["client_ip"]
            config_tunnel_gateway_ipv4 = normalize_private_tunnel_gateway_ipv4(
                core["tunnel_gateway_ipv4"]
            )
            if not config_tunnel_gateway_ipv4:
                raise HTTPException(
                    status_code=503,
                    detail="Double VPN core is missing a valid tunnel gateway registration.",
                )
            config_server_public_key = core["ingress_public_key"]
            config_server_endpoint = f"{core_host}:{core_port}"
            config_stealth_endpoint = core["stealth_endpoint"] or ""
            regional_aliases = parse_aliases(core["regional_aliases"] or "[]")
            config_direct_awg_enabled = bool(
                core["direct_awg_enabled"]
                if core["direct_awg_enabled"] is not None else 0
            )
            config_protocol = "double-vpn+xray-vless-ws+amneziawg" if login.stealth_mode else "double-vpn+amneziawg"
            config_xray_uuid = core["xray_uuid"] or ""
            config_xray_host = core_stealth_host
            config_xray_port = core_stealth_port
            config_xray_server_name = core_stealth_host
            config_xray_path = core["xray_path"] or "/wins-core-tunnel"
            config_xray_security = (core["xray_security"] or "none").lower()
            config_xray_transports = parse_xray_transports(
                core["stealth_transports"], config_xray_port, config_xray_security
            )
            config_xray_remote_awg_port = core_port
        if not config_tunnel_gateway_ipv4:
            raise HTTPException(
                status_code=503,
                detail="Selected VPN route is missing a valid tunnel gateway registration.",
            )
        xray_config = {
            "enabled": bool(login.stealth_mode and config_xray_host),
            "uuid": config_xray_uuid,
            "host": config_xray_host,
            "port": config_xray_port,
            "server_name": config_xray_server_name,
            "path": config_xray_path,
            "security": config_xray_security,
            "transports": config_xray_transports,
            "local_port": 42110,
            "remote_awg_host": "127.0.0.1",
            "remote_awg_port": config_xray_remote_awg_port,
            "fallback_hosts": regional_aliases,
            "regional_aliases": regional_aliases,
        }
        platform_support = platform_support_metadata(login.platform)
        try:
            client_capabilities = request_client_capabilities(login)
        except Winn3ContractError as exc:
            logger.error(
                "refusing client capability advertisement (reason=%s keys=%s)",
                exc.reason, ",".join(exc.keys) or "-",
            )
            raise HTTPException(
                status_code=400,
                detail="Client capability advertisement is malformed.",
            ) from exc
        # SYNC-02: a Double VPN client handshakes with the Core's core0, so it
        # must be handed core0's profile, not the exit's. Only the Core's own
        # report proves what core0 runs; without one there is nothing to serve
        # but a guess, so Double VPN through that Core is withheld until it
        # reports (an older Core agent, or a Core whose core0 config was
        # unreadable on its last registration).
        use_core_obfuscation = False
        if double_vpn_requested and core and double_assignment:
            core_obfuscation_json = (
                core["obfuscation_json"] if "obfuscation_json" in core.keys() else None
            )
            if core_obfuscation_json and str(core_obfuscation_json).strip():
                use_core_obfuscation = True
                try:
                    config_obfuscation = parse_obfuscation(core_obfuscation_json)
                except ObfuscationProfileError as exc:
                    logger.error(
                        "refusing Double VPN through core %s: obfuscation registration is unusable (reason=%s keys=%s)",
                        core["core_id"], exc.reason, ",".join(exc.keys) or "-",
                    )
                    raise HTTPException(
                        status_code=503,
                        detail="Double VPN core is missing a valid obfuscation registration.",
                    ) from exc
            else:
                logger.error(
                    "refusing Double VPN through core %s: the core has not reported its core0 obfuscation profile",
                    core["core_id"],
                )
                raise HTTPException(
                    status_code=503,
                    detail="Double VPN core has not reported its obfuscation profile yet.",
                    headers={"X-Wins-Error-Code": "double_vpn_core_profile_unreported"},
                )
        try:
            if not use_core_obfuscation:
                config_obfuscation = parse_obfuscation(node.get("obfuscation_json"))
        except ObfuscationProfileError as exc:
            # Fail closed, and loudly. Serving DEFAULT_OBFUSCATION here would
            # hand this client parameters the node is not running; because
            # AmneziaWG parameters are not negotiated that is a connection
            # failure, not a downgrade, and the old code produced it with no
            # error and no log. Refusing is the same treatment the tunnel
            # gateway registration gets a few lines above, and it keeps "what
            # the node runs" and "what clients are handed" one fact, not two.
            # Reason and key names only -- never the values.
            logger.error(
                "refusing to serve node %s: obfuscation registration is unusable (reason=%s keys=%s)",
                node["slug"], exc.reason, ",".join(exc.keys) or "-",
            )
            raise HTTPException(
                status_code=503,
                detail="Selected VPN route is missing a valid obfuscation registration.",
            ) from exc
        # Winn Protocol v3 serving gate. Explicit winn/1 nodes stay winn/1.
        # A node registered winn/3 is served winn/3 or the request is refused;
        # it is never rewritten to winn/1. See resolve_served_winn_protocol.
        try:
            served_protocol_version, served_protocol_params, winn3_gate_reason = (
                resolve_served_winn_protocol(
                    node,
                    capabilities=client_capabilities,
                    obfuscation=config_obfuscation,
                    stealth_mode=bool(login.stealth_mode),
                    double_vpn_active=bool(double_vpn_requested),
                    mtu=1280,
                )
            )
        except Winn3ContractError as exc:
            logger.error(
                "refusing to serve node %s as winn/3 (reason=%s); not rewriting "
                "to winn/1",
                node["slug"], exc.reason,
            )
            raise HTTPException(
                status_code=503,
                detail="Selected Winn Protocol v3 node cannot be served for this request.",
            ) from exc
        if served_protocol_version == WINN_PROTOCOL_V3:
            # Slug and param KEY NAMES only. Never the values: gateway_endpoint
            # and spa_target are node addresses.
            logger.info(
                "serving winn/3 for node %s (carrier=%s param_keys=%s)",
                node["slug"],
                served_protocol_params.get("carrier", WINN3_CARRIER_DIRECT_AWG),
                ",".join(sorted(served_protocol_params.keys())) or "-",
            )
        # Standalone v3 signed gateway descriptor. Strictly downstream of the
        # gate above: served ONLY when that gate already chose winn/3, so every
        # refusal it makes -- stealth_active, Double VPN, unclassifiable
        # obfuscation, an out-of-range MTU, a bad params blob -- is inherited
        # rather than re-implemented, and no second piece of logic exists that
        # could disagree with the first.
        served_winn3_descriptor, winn3_descriptor_reason = ({}, "")
        try:
            served_winn3_descriptor, winn3_descriptor_reason = (
                resolve_served_winn3_descriptor(
                    node,
                    capabilities=client_capabilities,
                    served_protocol_version=served_protocol_version,
                )
            )
        except Winn3ContractError as exc:
            logger.error(
                "refusing to serve node %s winn/3 descriptor (reason=%s); "
                "not rewriting to winn/1",
                node["slug"], exc.reason,
            )
            raise HTTPException(
                status_code=503,
                detail="Selected Winn Protocol v3 node cannot be served for this request.",
            ) from exc
        if served_winn3_descriptor:
            # Slug, generation and sequence only. NEVER a descriptor field:
            # `endpoint` is a node address and `admission_secret` is the
            # per-gateway secret this whole design exists to protect.
            _winn3_state = winn3_rotation_state(node)
            logger.info(
                "serving winn/3 descriptor for node %s (gen=%s seq=%s phase=%s)",
                node["slug"],
                _winn3_state.get("current_generation"),
                _winn3_state.get("current_seq"),
                _winn3_state.get("phase"),
            )
        if double_relay and not (
            served_protocol_version == WINN_PROTOCOL_V3
            and served_winn3_descriptor
            and (served_protocol_params or {}).get("carrier") == WINN3_CARRIER_WINN3
        ):
            # A relay Double is a standalone winn/3 single hop plus labels. If
            # the final resolution is anything else (the exit changed between
            # the gate and here) the Double label must not be served at all.
            conn.rollback()
            logger.error(
                "refusing the winn3 relay for node %s: the final resolution is not standalone winn/3",
                node["slug"],
            )
            raise HTTPException(
                status_code=503,
                detail="Double VPN relay changed while preparing. Please retry.",
                headers={
                    "X-Wins-Error-Code": "double_vpn_relay_changed",
                    "Retry-After": "1",
                },
            )
        if double_relay:
            logger.info(
                "serving winn3 relay core=%s exit=%s port=%s",
                mask_id(double_relay["core_id"]), node["slug"], double_relay["port"],
            )
        # The PER-DEVICE half of a standalone config, and it is strictly
        # downstream of the descriptor again: the descriptor is the gateway's
        # half (endpoint, static key, admission profile, inner next hop) and
        # this is the device's half (its inner address and its own X25519
        # static private key). Neither half is usable alone, so this is served
        # only when the descriptor already is, and the pair is all-or-nothing.
        #
        # A device that cannot be issued material must not be handed a
        # descriptor without a device half (the client refuses that by name)
        # and must not be rewritten to winn/1. Fail closed.
        # An identity already on file may hold authority elsewhere; one minted
        # by this request cannot (lane L17 v3 recovery barrier).
        # A client-supplied key counts as "on file" even when this request
        # adopted it: the client may re-present a key it used before, whose
        # authority at some gateway is not yet withdrawn, so the recovery
        # barrier stays on for it (conservative: at worst a retryable 503).
        winn3_key_on_file = bool((device_cfg.get("winn3_static_public") or "").strip())
        served_winn3_device, winn3_device_reason = (
            resolve_served_winn3_device_config(
                conn, device_cfg, descriptor_envelope=served_winn3_descriptor,
                requested_static_public=requested_winn3_static_public,
                client_owns_key=client_owns_winn3_key,
            )
        )
        if served_winn3_descriptor and not served_winn3_device:
            logger.error(
                "refusing winn/3 for node %s: the per-device standalone "
                "material could not be issued (reason=%s); not rewriting to "
                "winn/1",
                node["slug"], winn3_device_reason,
            )
            if winn3_device_reason == "winn3-static-public-in-use":
                # The UNIQUE backstop caught a client-key collision on the
                # allocation path. Answer exactly like the admission check
                # (409 + code) so the client-key app rotates its key once;
                # a bare 503 would leave it retrying the same key forever.
                # Nothing is committed: the rollback discards this request.
                conn.rollback()
                raise HTTPException(
                    status_code=409,
                    detail="This winn3 key is already registered to another device.",
                    headers={"X-Wins-Error-Code": "winn3_static_public_in_use"},
                )
            if double_relay:
                # A relay was planned (the inner pool gate said an address
                # existed) and the allocation still failed, for example a
                # concurrent request took the last address. Nothing of this
                # request may survive: get_db's close would discard it anyway,
                # the explicit rollback states the intent and survives any
                # future wrapper that commits on the way out.
                conn.rollback()
            raise HTTPException(
                status_code=503,
                detail="Selected Winn Protocol v3 node cannot be served for this request.",
            )
        # Whether the destination does not already authorize this identity.
        winn3_destination_is_new = not (
            device_row
            and str(old_location_slug or "").strip().lower() == node["slug"]
            and not winn3_identity_rotated
        )
        if served_winn3_descriptor and served_winn3_device and winn3_departure_closed:
            # L77 (Sol OI-DG-1 / RF-1): this unchanged v3 identity is leaving
            # a node that node_admits_peer() refuses (operator-closed, withdrawn
            # or retired). A closed node carries no grant, so completing the
            # switch would republish that node's registry WITHOUT the device
            # and the reply, which usually travels through that gateway's
            # tunnel, could be refused. Answer a retryable 503 BEFORE any
            # remote write instead: no gateway changes, the reply returns
            # through the current tunnel, and nothing is committed. The retry
            # succeeds once the closure cleanup (resync_active_peers_to_node ->
            # close_node_runtime) has unbound the device from the closed node,
            # after which the request is an ordinary admission with no
            # previous node to republish.
            conn.rollback()
            logger.warning(
                "Winn3 switch from closed node %s to node %s deferred until its closure cleanup",
                old_location_slug, node["slug"],
            )
            raise HTTPException(
                status_code=503,
                detail="Server switch deferred while the previous server releases this device. Please retry shortly.",
                headers={
                    "X-Wins-Error-Code": "winn3_switch_deferred_departure_closed",
                    "Retry-After": "60",
                },
            )
        if served_winn3_descriptor and served_winn3_device and (
            winn3_departure is not None or (winn3_destination_is_new and winn3_key_on_file)
        ):
            # Reserve authorization capacity and the account's departure budget
            # BEFORE any remote authorization of this request, AWG included. A
            # deferral changes no gateway, so the reply returns through the
            # current tunnel and the current connection keeps working.
            winn3_deferral, winn3_allowance = winn3_switch_deferral(
                conn,
                identity=winn3_departure or {
                    "device_id": login.device_id,
                    "account_number": acc,
                    "static_public": device_cfg.get("winn3_static_public") or "",
                },
                destination_slug=node["slug"],
                current_slug=old_location_slug,
                departing=winn3_departure is not None,
            )
            if winn3_deferral is None and winn3_departure is not None and not winn3_allowance:
                # Only an explicitly disabled grace reaches here: that
                # configuration removes immediately. Untrusted charge history
                # never does; winn3_switch_deferral defers it instead.
                logger.warning(
                    "Winn3 departure allowance withheld for node %s; removing immediately",
                    old_location_slug,
                )
                winn3_departure = None
            if winn3_deferral is not None:
                deferral_code, deferral_detail, deferral_retry = winn3_deferral
                conn.rollback()
                logger.warning(
                    "Winn3 switch from node %s to node %s deferred (%s, retry in %ss)",
                    old_location_slug, node["slug"], deferral_code, deferral_retry,
                )
                raise HTTPException(
                    status_code=503,
                    detail=deferral_detail,
                    headers={
                        "X-Wins-Error-Code": deferral_code,
                        "Retry-After": str(deferral_retry),
                    },
                )
        device_cfg["traffic_tier"] = freecap_tier(acc, str(user.get("expiration_date") or ""), str(user.get("renewal_source") or ""))
        # Validate the complete route before installing its remote AWG peer.
        if not double_vpn_requested and not sync_peer_to_node(node_ssh_host, device_cfg):
            conn.rollback()
            # A lost SSH acknowledgment does not prove the peer was absent.
            # Reconcile against committed authority using the durable outbox.
            queue_peer_revocation(
                conn, node_ssh_host, device_cfg.get("client_public_key") or ""
            )
            mark_node_management_status(conn, node["slug"], "failed", "peer sync failed")
            conn.commit()
            raise HTTPException(status_code=503, detail="Selected VPN node is not ready. Please try again in a minute.")
        elif not double_vpn_requested:
            mark_node_management_status(conn, node["slug"], "ok")
        if served_winn3_descriptor and served_winn3_device:
            # Publish while the admission transaction still owns its writer
            # lock. A failed publication must not consume the activation key
            # or commit a device whose bearer the client has never received.
            # An identity this node did not already authorize is published
            # PROVISIONAL (finite) because this transaction can still roll
            # back, and is finalized after commit.
            winn3_destination_publish = {
                "expect_static_public": device_cfg.get("winn3_static_public") or "",
            }
            if winn3_destination_is_new:
                winn3_destination_publish["provisional"] = {
                    winn3_destination_publish["expect_static_public"]:
                        int(winn3_clock()) + WINN3_PROVISIONAL_DESTINATION_SECONDS,
                }
            if not sync_winn3_registry_to_node(
                conn,
                node_ssh_host,
                node["slug"],
                **winn3_destination_publish,
            ):
                conn.rollback()
                conn.execute("""
                    INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
                    VALUES (?, 0, 0)
                    ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0
                """, (node["slug"],))
                if not double_vpn_requested:
                    queue_peer_revocation(
                        conn, node_ssh_host, device_cfg.get("client_public_key") or ""
                    )
                mark_node_management_status(
                    conn, node["slug"], "failed", "Winn3 peer registry sync failed"
                )
                conn.commit()
                raise HTTPException(
                    status_code=503,
                    detail="Selected Winn Protocol v3 node is still synchronizing authorization. Please retry.",
                    headers={
                        "X-Wins-Error-Code": "winn3_peer_registry_sync_failed",
                        "Retry-After": "5",
                    },
                )
            mark_node_management_status(conn, node["slug"], "ok")
            # A location change makes the old node's full snapshot stale. The
            # device must not receive its new descriptor while the same static
            # identity remains authorized at the previous gateway WITHOUT A
            # BOUND. This request usually travels through that gateway's
            # tunnel, so removing the identity outright lets the gateway refuse
            # the reply and every retry. An unchanged identity is therefore
            # republished there with a bounded not_after that the gateway
            # enforces by itself; a rotated identity, an exhausted budget or a
            # disabled grace still gets the immediate removal.
            if winn3_departure is not None:
                issue_winn3_departure_grant(conn, **winn3_departure)
            if (
                old_location_slug
                and old_location_slug != node["slug"]
                and (
                    not old_peer_node_ip
                    or not sync_winn3_registry_to_node(
                        conn, old_peer_node_ip, old_location_slug
                    )
                )
            ):
                conn.rollback()
                # The selected node's AWG installation also preceded this
                # failure. Revalidate it against restored authority at drain.
                if not double_vpn_requested:
                    queue_peer_revocation(
                        conn, node_ssh_host, device_cfg.get("client_public_key") or ""
                    )
                # A remote replacement can succeed before its caller reports
                # failure. Reconcile both gateways from the restored database.
                for repair_slug in (node["slug"], old_location_slug):
                    conn.execute("""
                        INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
                        VALUES (?, 0, 0)
                        ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0
                    """, (repair_slug,))
                mark_node_management_status(
                    conn,
                    old_location_slug,
                    "failed",
                    "Winn3 stale peer registry removal failed",
                )
                conn.commit()
                raise HTTPException(
                    status_code=503,
                    detail="Previous Winn Protocol v3 node is still removing authorization. Please retry.",
                    headers={
                        "X-Wins-Error-Code": "winn3_peer_registry_stale_removal_failed",
                        "Retry-After": "5",
                    },
                )
            if (
                old_location_slug
                and old_location_slug != node["slug"]
                and old_peer_node_ip
            ):
                mark_node_management_status(conn, old_location_slug, "ok")
            if "provisional" in winn3_destination_publish:
                # The provisional entry must be finalized. The queue row
                # commits with the switch; the background drain and, failing
                # that, the sweep publish the committed, unbounded entry.
                conn.execute("""
                    INSERT INTO winn3_registry_refreshes (node_slug, attempts, next_attempt_at)
                    VALUES (?, 0, 0)
                    ON CONFLICT(node_slug) DO UPDATE SET attempts=0, next_attempt_at=0
                """, (node["slug"],))
            conn.commit()
            if "provisional" in winn3_destination_publish and background_tasks is not None:
                background_tasks.add_task(drain_winn3_registry_refreshes, 4, [node["slug"]])
        # THE STANDALONE PLAN, resolved through the SAME helper the gate used
        # (added 2026-08-10, ds_iosconfig3). One function on both paths so the
        # numbers emitted here can never contradict the gate that admitted the
        # request -- the descriptor serving path refuses to keep two pieces of
        # logic that could disagree, and this plan is exactly that shape. A
        # request the gate refused standalone winn/3 on never reaches here (it
        # failed closed as HTTP 503), and a relay carrier never reads either
        # field, so both stay byte-for-byte today's config for every explicit
        # winn/1 client in the field.
        served_carrier = (served_protocol_params or {}).get(
            "carrier", WINN3_CARRIER_DIRECT_AWG
        )
        served_winn3_path_mtu = ""
        served_winn3_plan_classes = ""
        if served_carrier == WINN3_CARRIER_WINN3:
            _plan_ok, _plan_reason, _plan_mtu, _plan_classes = (
                winn3_standalone_plan_for_node(node)
            )
            if _plan_ok:
                served_winn3_path_mtu = str(_plan_mtu)
                served_winn3_plan_classes = ",".join(_plan_classes)
        vpn_config = {
            "client_ip": config_client_ip,
            "tunnel_gateway_ipv4": config_tunnel_gateway_ipv4,
            "client_private_key": device_cfg["client_private_key"],
            "client_public_key": device_cfg["client_public_key"],
            # Winn Protocol v3 STANDALONE, per-device. Empty strings unless
            # this request is being served a descriptor, which is the default
            # for every client in the field.
            #
            # WHY THEY ARE HERE AND NOT IN protocol_params. That surface is a
            # closed twenty-key allowlist whose one inviolable rule is that
            # nothing key-shaped is ever served through it, and
            # WINN3_PARAM_NAME_NEVER_SERVED matches `static_private` by
            # construction -- it would refuse this value, correctly, by design.
            # vpn_config is the surface that already carries a per-device
            # private key to its own device, one line above.
            #
            # WHY NOT ON THE DESCRIPTOR. The descriptor is one signed object
            # per NODE, identical for every device; these are per DEVICE. A
            # descriptor carrying them would have to be re-signed per device by
            # a key the hub deliberately does not hold.
            "winn3_inner_v4": served_winn3_device.get("winn3_inner_v4", ""),
            # "" for every device that supplied its own winn3_static_public;
            # non-empty only on the legacy hub-minted path (ruling Q1).
            "winn3_static_private": served_winn3_device.get("winn3_static_private", ""),
            # Echo of the public key on file, served with winn3_inner_v4. The
            # client-key app refuses a config whose echo is not its own key.
            "winn3_static_public": served_winn3_device.get("winn3_static_public", ""),
            # The STANDALONE PLAN (added 2026-08-10, ds_iosconfig3). The outer
            # path MTU and the migration-plan carrier classes the client hands
            # to driver.NewSizing for its floor -- read per-device off
            # vpn_config, never off protocol_params (a closed allowlist that
            # carries neither, matching the discipline that keeps `static_private`
            # here). Empty strings for every relay carrier and every winn/1
            # request, which is byte-for-byte today's behaviour: the client's
            # _configString treats an empty value as absent, and an absent
            # standalone plan is what the gate above already refused to serve.
            "winn3_path_mtu": served_winn3_path_mtu,
            "winn3_carrier_classes": served_winn3_plan_classes,
            "server_public_key": config_server_public_key,
            "preshared_key": device_cfg["preshared_key"],
            "server_endpoint": config_server_endpoint,
            "stealth_gateway_endpoint": config_stealth_endpoint,
            "regional_aliases": regional_aliases,
            "stealth_active": login.stealth_mode,
            "double_vpn_active": bool(double_vpn_requested),
            "direct_awg_enabled": config_direct_awg_enabled,
            "double_vpn_core_id": core["core_id"] if core else "",
            "double_vpn_exit_slug": node["slug"] if double_vpn_requested else "",
            "protocol": config_protocol,
            "node_slug": node["slug"],
            "mtu": 1280,
            "dns": config_dns,
            "obfuscation": config_obfuscation,
            # Winn Protocol version and params. These are no longer copied
            # straight off the node row: the row says what the node CAN speak,
            # and resolve_served_winn_protocol above decides what THIS request
            # is served, because the client fails closed on a winn/3 config it
            # cannot honour. A node with no winn/3 registration yields exactly
            # the values this line produced before ("winn/1", {}).
            #
            # winn3_gate_reason names why, for the readiness endpoint and the
            # tests. It is not served to the client: it would tell anyone who
            # can make a request which nodes speak winn/3.
            "protocol_version": served_protocol_version,
            "protocol_params": served_protocol_params,
            # Standalone v3 gateway descriptor, or ABSENT. Deliberately not a
            # protocol_params key: that surface is a closed twenty-key
            # allowlist and its one inviolable rule is that nothing key-shaped
            # is ever served through it. This is a separate, offline-signed,
            # separately-gated object. An empty dict rather than a null so the
            # field's type never varies; winn3_descriptor_reason names why it
            # is empty and is NOT served -- it would tell anyone who can make a
            # request which nodes carry descriptors.
            "winn3_descriptor": served_winn3_descriptor,
            "xray": xray_config,
            "server_schema_version": platform_support["schema_version"],
            "platform": normalize_client_platform(login.platform),
            "client_capabilities": client_capabilities,
            "clientcapabilities": client_capabilities,
            "platform_support": platform_support,
            "platformsupport": platform_support,
        }
        if double_relay:
            # w3r/1: a relay Double VPN carries the Double labels. They are set
            # here, after the config literal above (whose "double_vpn_active"
            # line the deployment validator pins as written), and BEFORE the
            # compat copy below reads them. double_vpn_core_id is already the
            # relay Core's id: `core` is non-None exactly when a Double was
            # requested.
            vpn_config["double_vpn_active"] = True
            vpn_config["double_vpn_exit_slug"] = node["slug"]
        # Compatibility copy for the temporary split-script response schema.
        vpn_config_compat = {
            "clientip": vpn_config["client_ip"],
            "tunnelgatewayipv4": vpn_config["tunnel_gateway_ipv4"],
            "clientprivatekey": vpn_config["client_private_key"],
            "clientpublickey": vpn_config["client_public_key"],
            "serverpublickey": vpn_config["server_public_key"],
            "presharedkey": vpn_config["preshared_key"],
            "serverendpoint": vpn_config["server_endpoint"],
            "stealthactive": vpn_config["stealth_active"],
            "doublevpnactive": vpn_config["double_vpn_active"],
            "directawgenabled": vpn_config["direct_awg_enabled"],
            "doublevpncoreid": vpn_config["double_vpn_core_id"],
            "doublevpnexitslug": vpn_config["double_vpn_exit_slug"],
            "regionalaliases": vpn_config["regional_aliases"],
            "nodeslug": vpn_config["node_slug"],
            "mtu": vpn_config["mtu"],
            "dns": vpn_config["dns"],
            "obfuscation": vpn_config["obfuscation"],
            # Winn Protocol forward-compat seam, mirrored into the no-underscore
            # split-script compat copy (see vpn_config above).
            "protocol_version": vpn_config["protocol_version"],
            "protocolversion": vpn_config["protocol_version"],
            "protocol_params": vpn_config["protocol_params"],
            "protocolparams": vpn_config["protocol_params"],
            "winn3_descriptor": vpn_config["winn3_descriptor"],
            "winn3descriptor": vpn_config["winn3_descriptor"],
            # Both spellings, like every other key in this compat copy. A
            # standalone start needs all six key-bearing fields, so a client
            # reading the no-underscore schema must be able to find these two.
            "winn3_inner_v4": vpn_config["winn3_inner_v4"],
            "winn3innerv4": vpn_config["winn3_inner_v4"],
            "winn3_static_private": vpn_config["winn3_static_private"],
            "winn3staticprivate": vpn_config["winn3_static_private"],
            "winn3_static_public": vpn_config["winn3_static_public"],
            "winn3staticpublic": vpn_config["winn3_static_public"],
            # Both spellings, like every other key in this compat copy. The
            # standalone plan is OPTIONAL on the client and an omitted value
            # means the engine's own fleet default, so the no-underscore schema
            # must be able to find these two or it silently plans at a
            # different MTU than the gateway.
            "winn3_path_mtu": vpn_config["winn3_path_mtu"],
            "winn3pathmtu": vpn_config["winn3_path_mtu"],
            "winn3_carrier_classes": vpn_config["winn3_carrier_classes"],
            "winn3carrierclasses": vpn_config["winn3_carrier_classes"],
            "xray": vpn_config["xray"],
            "protocol": vpn_config["protocol"],
            "stealthgatewayendpoint": vpn_config["stealth_gateway_endpoint"],
            "serverschemaversion": vpn_config["server_schema_version"],
            "platform": vpn_config["platform"],
            "clientcapabilities": vpn_config["client_capabilities"],
            "platformsupport": vpn_config["platform_support"],
        }
        if double_relay:
            # ABSENT, not null, whenever a relay is not served. The endpoint is
            # a path and is not signed: the session is end to end encrypted to
            # the exit's signed key, so a wrong endpoint is a failed connect
            # and never a disclosure.
            vpn_config["winn3_relay"] = {"v": 1, "endpoint": double_relay["endpoint"]}
            vpn_config_compat["winn3_relay"] = vpn_config["winn3_relay"]
            vpn_config_compat["winn3relay"] = vpn_config["winn3_relay"]
        selected_node = {
            "slug": node.get("slug") or "auto",
            "name": node.get("name") or "Auto Selected",
            "flag": node.get("flag") or "🌐",
            "status": node.get("status") or "online",
        }
        exp_out = FREE_ACCESS_LABEL if login.free_access else user.get("expiration_date")
        response_payload = {
            "status": "authenticated",
            "free_access": bool(login.free_access),
            "freeaccess": bool(login.free_access),
            "plan": "free" if login.free_access else "paid",
            "account_number": acc,
            "accountnumber": acc,
            **announcement_fields(conn),
            "expiration_date": exp_out,
            "expirationdate": exp_out,
            "legal": {
                "document_version": LEGAL_DOCUMENT_VERSION,
                "document_hash": LEGAL_DOCUMENT_HASH,
                "terms_url": LEGAL_TERMS_URL,
                "privacy_url": LEGAL_PRIVACY_URL,
                "hold_harmless_url": LEGAL_HOLD_HARMLESS_URL,
                "limitation_url": LEGAL_LIMITATION_URL,
            },
            "payment_options": payment_options(),
            "selected_node": selected_node,
            "selectednode": selected_node,
            "platform_support": platform_support,
            "platformsupport": platform_support,
            "client_capabilities": client_capabilities,
            "clientcapabilities": client_capabilities,
            "vpn_config": vpn_config,
            "vpnconfig": vpn_config_compat,
        }
        if issued_device_auth_token:
            # Enrollment and legacy backfill return a fresh bearer. Plain
            # reconnects retain the stored token. The client must persist this
            # token and send Authorization: Bearer for authenticated device APIs.
            response_payload["device_auth_token"] = issued_device_auth_token
            response_payload["deviceauthtoken"] = issued_device_auth_token
        if login.free_access:
            response_payload.update({
                "referral_code": "",
                "referralcode": "",
                "referral_link": "",
                "referrallink": "",
                "referral_backup_link": "",
                "referralbackuplink": "",
            })
        else:
            response_payload.update(account_referral_payload(conn, acc))
        if double_vpn_lease_token and conn.execute(
            "SELECT 1 FROM double_vpn_enrollment_leases "
            "WHERE account_number=? AND lease_token=? AND expires_at>?",
            (acc, double_vpn_lease_token, time.time()),
        ).fetchone() is None:
            raise HTTPException(
                status_code=409,
                detail="Double VPN enrollment lease expired or changed. Please retry.",
                headers={"Retry-After": "5"},
            )
        if deferred_activation_secret and not verify_and_consume_activation_secret(
            conn, acc, deferred_activation_secret, consumed=consumed_activation_key
        ):
            raise HTTPException(
                status_code=401,
                detail=SETUP_KEY_REFUSED_DETAIL,
            )
        if deferred_activation_secret:
            record_device_activation_key(conn, acc, login.device_id, consumed_activation_key)
        return response_payload

@app.get("/free/status")
async def free_status(platform: str = "unknown"):
    return await asyncio.to_thread(_free_status_sync, platform)


def _free_status_sync(platform: str = "unknown"):
    with get_db() as conn:
        ensure_schema(conn)
        mark_stale_nodes_offline(conn)
        node = select_free_node(conn, platform=platform)
        free_slugs = current_free_node_slugs(conn, platform=platform)
        double_vpn_core = select_double_vpn_core(conn) if DOUBLE_VPN_ENABLED else None
        double_vpn_available = bool(double_vpn_core)
        platform_support = platform_support_metadata(platform)
        if not FREE_ACCESS_ENABLED or not node:
            double_vpn_free_enabled = double_vpn_free_access_enabled(conn)
            return {
                "status": "unavailable",
                "free_access": FREE_ACCESS_ENABLED,
                "freeaccess": FREE_ACCESS_ENABLED,
                "double_vpn_available": double_vpn_available,
                "doublevpnavailable": double_vpn_available,
                "double_vpn_free_access_enabled": double_vpn_free_enabled,
                "doublevpnfreeaccessenabled": double_vpn_free_enabled,
                "free_node_slugs": free_slugs,
                "freeNodeSlugs": free_slugs,
                **announcement_fields(conn),
                "expiration_date": FREE_ACCESS_LABEL,
                "expirationdate": FREE_ACCESS_LABEL,
                "platform_support": platform_support,
                "platformsupport": platform_support,
            }
        double_vpn_free_enabled = double_vpn_free_access_enabled(conn)
        selected_node = {
            "slug": node["slug"] or FREE_ACCESS_NODE_SLUG,
            "name": node["name"] or FREE_ACCESS_LABEL,
            "flag": node["flag"] or "🌐",
            "status": node["status"] or "online",
            "transports": node_transport_availability(node),
        }
        return {
            "status": "ok",
            "free_access": True,
            "freeaccess": True,
            "double_vpn_available": double_vpn_available,
            "doublevpnavailable": double_vpn_available,
            "double_vpn_free_access_enabled": double_vpn_free_enabled,
            "doublevpnfreeaccessenabled": double_vpn_free_enabled,
            "free_node_slugs": free_slugs,
            "freeNodeSlugs": free_slugs,
            "plan": "free",
            **announcement_fields(conn),
            "expiration_date": FREE_ACCESS_LABEL,
            "expirationdate": FREE_ACCESS_LABEL,
            "selected_node": selected_node,
            "selectednode": selected_node,
            "platform_support": platform_support,
            "platformsupport": platform_support,
        }

@app.post("/free/verify")
async def verify_free_access(fastapi_request: Request, free_request: FreeAccessRequest, background_tasks: BackgroundTasks):
    login = await asyncio.to_thread(
        _prepare_free_login_sync, fastapi_request, free_request, background_tasks
    )
    return await verify_account(fastapi_request, login, background_tasks)


def _prepare_free_login_sync(fastapi_request: Request, free_request: FreeAccessRequest, background_tasks: BackgroundTasks):
    if not FREE_ACCESS_ENABLED:
        raise HTTPException(status_code=503, detail="Free VPN access is not enabled.")
    requested_client_public_key = validate_wireguard_public_key(free_request.client_public_key)
    if not requested_client_public_key:
        raise HTTPException(status_code=400, detail="Client public key is required.")
    # Refuse a malformed winn/3 key before the free identity is written below;
    # _verify_account_sync validates it again on the built LoginRequest.
    requested_winn3_static_public = validate_winn3_static_public(free_request.winn3_static_public)
    selection_generation, ordinary_v3_failure_generation = typed_selection_generations(free_request)
    free_identity_value = free_request.device_fingerprint or free_request.device_id
    account_number, synthetic_device_id, hardware_fingerprint = free_identity_for_device(free_identity_value)
    smart_recommended_slug = ""
    smart_router_trigger = "connection_initiation"
    requested_free_slug = (free_request.location or "auto").strip().lower()
    if requested_free_slug in {"", "auto"}:
        # Keep the advisory network call outside the free-admission write
        # transaction. The recommendation is revalidated inside it.
        with get_db() as route_conn:
            route_existing = route_conn.execute(
                "SELECT location_slug FROM devices WHERE device_id = ?",
                (synthetic_device_id,),
            ).fetchone()
            route_existing_slug = (
                str(route_existing["location_slug"] or "").strip().lower()
                if route_existing else ""
            )
            smart_router_trigger = smart_router_trigger_for_existing_node(
                route_conn,
                route_existing_slug,
            )
            smart_recommended_slug = smart_router_recommend_node(
                route_conn,
                existing_slug=route_existing_slug,
                platform=free_request.platform,
                free_only=False,
                trigger=smart_router_trigger,
                selection_generation=selection_generation,
                ordinary_v3_failure_generation=ordinary_v3_failure_generation,
            )
    with get_db() as conn:
        ensure_schema(conn)
        enforce_free_verify_rate_limits(conn, fastapi_request, hardware_fingerprint)
        if get_setting(conn, "maintenance_mode", "false") == "true":
            raise HTTPException(status_code=503, detail="System Maintenance underway.")
        existing_device = conn.execute(
            "SELECT location_slug FROM devices WHERE device_id = ?",
            (synthetic_device_id,),
        ).fetchone()
        existing_slug = str(existing_device["location_slug"] or "") if existing_device else ""
        # M-2: throttle only the RATE at which brand-new free identities are
        # admitted. Returning devices (existing_device is not None) bypass this
        # entirely, so legitimate concurrent users and reconnect spikes are never
        # capped. This targets a distributed flood of attacker-chosen fresh
        # device identities -- which each dodge the per-device limiter and would
        # otherwise consume free peer/node capacity -- without a hard active
        # device cap. Deliberately conservative/env-tunable; the durable fix is
        # Turnstile / platform attestation on /free/verify (flagged for review).
        if existing_device is None:
            check_rate_limit(conn, "free-new-device-global", FREE_NEW_DEVICE_RATE_LIMIT_PER_HOUR, 3600)
            # As in enforce_free_verify_rate_limits: persist the increment
            # before the fallible node selection below, or a 503 there would
            # roll it back and refund the attempt.
            conn.commit()
        node = select_free_node(
            conn,
            free_request.location,
            existing_slug=existing_slug,
            platform=free_request.platform,
            preferred_slug=smart_recommended_slug,
            advisory_is_distress=smart_router_trigger == "distress",
            selection_generation=selection_generation,
            ordinary_v3_failure_generation=ordinary_v3_failure_generation,
        )
        if not node:
            raise HTTPException(status_code=503, detail="Free VPN server is not online yet.")
        existing = conn.execute("SELECT renewal_source FROM users WHERE account_number = ?", (account_number,)).fetchone()
        if existing and (existing["renewal_source"] or "") not in {"", "free_access"}:
            raise HTTPException(status_code=409, detail="Free identity collision. Please reinstall or contact support.")
        conn.execute("""
            INSERT INTO users (
                account_number, email, subscriber_name, status, expiration_date,
                hardware_hash, renewal_source, created_at
            )
            VALUES (?, '', 'Free VPN User', 'active', ?, ?, 'free_access', ?)
            ON CONFLICT(account_number) DO UPDATE SET
                subscriber_name='Free VPN User',
                status='active',
                expiration_date=excluded.expiration_date,
                hardware_hash=excluded.hardware_hash,
                renewal_source='free_access'
        """, (account_number, lifetime_expiry(), hardware_fingerprint, utcnow().isoformat()))
        selected_slug = node["slug"] or FREE_ACCESS_NODE_SLUG
        record_free_access_event(
            conn,
            fastapi_request,
            "verify_stealth" if free_request.stealth_mode else "verify",
            account_number,
            hardware_fingerprint,
            requested_client_public_key,
            free_request.platform,
            free_request.device_model,
            selected_slug,
            free_request.stealth_mode,
        )

    login = LoginRequest(
        account_number=account_number,
        device_id=synthetic_device_id,
        device_fingerprint=hardware_fingerprint,
        device_model=f"{free_request.device_model} ({free_request.platform})",
        platform=free_request.platform,
        app_version=free_request.app_version,
        locale=free_request.locale,
        location=selected_slug,
        stealth_mode=free_request.stealth_mode,
        double_vpn=free_request.double_vpn,
        client_public_key=requested_client_public_key,
        winn3_static_public=requested_winn3_static_public or None,
        supports_winn3_client_key=free_request.supports_winn3_client_key,
        supports_awg=free_request.supports_awg,
        supports_xray=free_request.supports_xray,
        supports_split_tunnel=free_request.supports_split_tunnel,
        supports_per_app_split_tunnel=free_request.supports_per_app_split_tunnel,
        supports_double_vpn=free_request.supports_double_vpn,
        supports_winn3=free_request.supports_winn3,
        supports_winn3_spa=free_request.supports_winn3_spa,
        supports_winn3_descriptor=free_request.supports_winn3_descriptor,
        supports_winn3_dualauth=free_request.supports_winn3_dualauth,
        supports_winn3_relay=free_request.supports_winn3_relay,
        selection_generation=selection_generation,
        ordinary_v3_failure_generation=ordinary_v3_failure_generation,
        free_access=True,
        legal_version=free_request.legal_version,
        legal_hash=free_request.legal_hash,
        accepted_terms=free_request.accepted_terms,
        accepted_hold_harmless=free_request.accepted_hold_harmless,
        accepted_limitation_liability=free_request.accepted_limitation_liability,
        accepted_electronic_records=free_request.accepted_electronic_records,
        accepted_android_vpn_service_disclosure=free_request.accepted_android_vpn_service_disclosure,
        android_vpn_service_disclosure_version=free_request.android_vpn_service_disclosure_version,
        android_vpn_service_disclosure_accepted_at=free_request.android_vpn_service_disclosure_accepted_at,
        acceptance_method=free_request.acceptance_method,
    )
    return login

def perform_authenticated_device_logout(
    conn: sqlite3.Connection,
    background_tasks: BackgroundTasks,
    request: Request,
    account_number: str,
    device_id: str,
    action: str,
) -> Optional[sqlite3.Row]:
    # M-8: shared authenticated logout used by both /logout and /free/logout so
    # one route handler never calls another. Authenticate this exact device
    # BEFORE any state change, then remove the node peer, deactivate any Double
    # VPN assignment, and delete the device row. Returns the pre-deletion device
    # row (or None) so a caller can record an audit event only after a
    # successful authorization.
    require_device_auth_token(conn, account_number, device_id, request, action)
    device = conn.execute(
        "SELECT client_public_key, device_model, location_slug FROM devices WHERE account_number = ? AND device_id = ?",
        (account_number, device_id),
    ).fetchone()
    if device:
        node = conn.execute("SELECT endpoint, ssh_host FROM nodes WHERE slug = ?", (device["location_slug"],)).fetchone()
        if node:
            node_ip = (node["ssh_host"] or extract_node_host(node["endpoint"] or ""))
            if node_ip and device["client_public_key"]:
                queue_peer_revocation(conn, node_ip, device["client_public_key"], background_tasks)
        conn.execute(
            "DELETE FROM double_vpn_assignments WHERE account_number = ? AND device_id = ?",
            (account_number, device_id),
        )
    # The owner deactivating this device returns the setup key that enrolled
    # it (owner ruling 2026-10-25), in this transaction.
    deactivate_device_returning_key(conn, account_number, device_id)
    if device and background_tasks is not None:
        background_tasks.add_task(drain_winn3_registry_refreshes)
    return device

@app.post("/free/logout")
async def free_logout_device(background_tasks: BackgroundTasks, request: Request, device_id: Optional[str] = None, deviceid: Optional[str] = None):
    body = {}
    content_type = request.headers.get("content-type", "")
    if "application/json" in content_type:
        try:
            decoded = await request.json()
            if isinstance(decoded, dict):
                body = decoded
        except Exception:
            body = {}
    elif "application/x-www-form-urlencoded" in content_type or "multipart/form-data" in content_type:
        body = await request.form()
    dev = device_id or deviceid or body.get("device_id") or body.get("deviceid") or ""
    if not dev:
        raise HTTPException(status_code=400, detail="Missing device_id/deviceid")
    return await asyncio.to_thread(free_logout_device_sync, background_tasks, request, dev)

def free_logout_device_sync(background_tasks: BackgroundTasks, request: Request, dev: str):
    account_number, synthetic_device_id, hardware_fingerprint = free_identity_for_device(dev)
    with get_db() as conn:
        ensure_schema(conn)
        # M-8: rate-limit and authenticate BEFORE recording any audit event or
        # deleting state. The previous flow committed a free_access_event -- and
        # even fabricated one for a device that never existed -- from
        # caller-supplied identity before authentication happened inside a nested
        # /logout call. Commit the rate-limit increment first so a failed-auth
        # flood still counts against the limit, then authenticate + delete, and
        # only then (for a device that actually existed) record the event.
        check_rate_limit(conn, rate_limit_bucket("free-logout-ip", request_origin_bucket_value(request)), 20, 60)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        device = perform_authenticated_device_logout(
            conn, background_tasks, request, account_number, synthetic_device_id, "free logout"
        )
        if device is not None:
            record_free_access_event(
                conn,
                request,
                "logout",
                account_number,
                hardware_fingerprint,
                device["client_public_key"] or "",
                "",
                device["device_model"] or "Device",
                device["location_slug"] or "",
                False,
            )
    return {"ok": True}

@app.post("/logout")
async def logout_device(background_tasks: BackgroundTasks, request: Request, account_number: Optional[str] = None, accountnumber: Optional[str] = None, device_id: Optional[str] = None, deviceid: Optional[str] = None):
    form = {}
    content_type = request.headers.get("content-type", "")
    if "application/json" in content_type:
        try:
            decoded = await request.json()
            if isinstance(decoded, dict):
                form = decoded
        except Exception:
            form = {}
    elif "application/x-www-form-urlencoded" in content_type or "multipart/form-data" in content_type:
        form = await request.form()
    acc = normalize_account_number(account_number or accountnumber or form.get("account_number") or form.get("accountnumber") or "")
    dev = device_id or deviceid or form.get("device_id") or form.get("deviceid") or ""
    if not acc or not dev:
        raise HTTPException(status_code=400, detail="Missing account_number/accountnumber or device_id/deviceid")
    return await asyncio.to_thread(logout_device_sync, background_tasks, request, acc, dev)

def logout_device_sync(background_tasks: BackgroundTasks, request: Request, acc: str, dev: str):
    with get_db() as conn:
        ensure_schema(conn)
        # L77 (Sol OI-LO-2): the /free/logout M-8 pattern. Rate-limit by
        # request origin and COMMIT the increment before the device lookup,
        # so a failed-auth flood still counts (an HTTPException below rolls
        # back everything after this commit) and an exhausted source never
        # reaches the database lookup or the invalid-token security event.
        check_rate_limit(conn, rate_limit_bucket("logout-ip", request_origin_bucket_value(request)), 20, 60)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        # M-5: /logout must not trust account_number+device_id alone once a
        # device has a scoped auth token on file (see require_device_auth_token
        # for the transitional fallback covering pre-M-5 device rows).
        perform_authenticated_device_logout(conn, background_tasks, request, acc, dev, "logout")
        return {"ok": True}

# ---------------------------------------------------------------------------
# Account deletion (Apple Guideline 5.1.1(v) / Play Data Safety)
#
# Four authenticated routes -- request / confirm / cancel / status -- built on
# a quorum of DISTINCT device confirmations so that one stolen or compromised
# device can never destroy an account by itself, while every user still has a
# path that terminates. See ACCOUNT_DELETION_QUORUM and
# ACCOUNT_DELETION_SINGLE_DEVICE_DELAY_DAYS for the policy rationale.
# ---------------------------------------------------------------------------

def required_deletion_confirmations(active_device_count: int) -> int:
    # min(quorum, live active-device count), evaluated at request time from
    # the account's real devices -- never from DEVICE_LIMIT. An account with
    # fewer devices than the quorum must reach unanimity of what it actually
    # has; an account with more never has to reach unanimity at all (3 devices
    # -> 2 confirmations, so a lost or broken device does not trap the user).
    if active_device_count <= 0:
        return 0
    return min(ACCOUNT_DELETION_QUORUM, active_device_count)

def account_deletion_active_devices(conn: sqlite3.Connection, account_number: str) -> list:
    # "Active" is defined exactly as cleanup_stale_devices defines survivable:
    # a row whose last_seen is within STALE_DEVICE_RETENTION_DAYS. Rows with a
    # NULL last_seen are already stale by that rule and are excluded.
    #
    # A device with no device_auth_token_hash is also excluded: H-1 makes
    # require_device_auth_token fail closed on an empty hash, so such a row can
    # never actually confirm. Counting it would raise the required confirmation
    # count without adding anyone able to satisfy it, i.e. manufacture an
    # unsatisfiable quorum. Excluding it can only ever lower the requirement.
    if STALE_DEVICE_RETENTION_DAYS > 0:
        cutoff = (utcnow() - timedelta(days=STALE_DEVICE_RETENTION_DAYS)).isoformat()
        return conn.execute(
            """
            SELECT device_id, device_auth_token_hash, client_public_key, location_slug
            FROM devices
            WHERE account_number = ?
              AND device_auth_token_hash IS NOT NULL AND device_auth_token_hash != ''
              AND last_seen IS NOT NULL AND last_seen >= ?
            ORDER BY device_id
            """,
            (account_number, cutoff),
        ).fetchall()
    return conn.execute(
        """
        SELECT device_id, device_auth_token_hash, client_public_key, location_slug
        FROM devices
        WHERE account_number = ?
          AND device_auth_token_hash IS NOT NULL AND device_auth_token_hash != ''
        ORDER BY device_id
        """,
        (account_number,),
    ).fetchall()

def account_deletion_device_binding(request_id: str, device_id: str, device_auth_token_hash: str) -> str:
    # Pins a stored confirmation to (this request, this device, this device's
    # current credential generation). Recomputed on every count; a row whose
    # binding no longer reproduces is ignored.
    #
    # This is what makes a confirmation non-transferable and non-replayable:
    #  * request_id  -- a confirmation captured under an earlier, cancelled
    #                   request cannot be counted toward a new one.
    #  * device_id   -- device A's row can never satisfy device B's slot; the
    #                   composite primary key means one device is one vote.
    #  * token hash  -- logging the device out and re-enrolling it mints a new
    #                   device_auth_token, so a thief cannot cycle one physical
    #                   device through enrolment twice to fake a two-device
    #                   quorum.
    # The output is a keyed digest, not the credential digest itself, so this
    # column is useless to anyone who reads it.
    return hmac.new(
        RATE_LIMIT_SECRET.encode(),
        f"deletion-binding:{request_id}:{device_id}:{device_auth_token_hash}".encode(),
        hashlib.sha256,
    ).hexdigest()[:32]

def load_pending_deletion_request(conn: sqlite3.Connection, account_number: str) -> Optional[sqlite3.Row]:
    return conn.execute(
        "SELECT * FROM account_deletion_requests WHERE account_number = ? AND status = 'pending'",
        (account_number,),
    ).fetchone()

def valid_deletion_confirmation_device_ids(conn: sqlite3.Connection, request_id: str, account_number: str) -> set:
    # Only confirmations from devices that are STILL active and whose binding
    # still reproduces are counted. A device that was logged out, evicted by
    # the device limit, or re-enrolled after confirming silently stops
    # counting, so consent has to be genuinely concurrent across devices.
    active = {
        row["device_id"]: (row["device_auth_token_hash"] or "")
        for row in account_deletion_active_devices(conn, account_number)
    }
    confirmed = set()
    for row in conn.execute(
        "SELECT device_id, device_binding FROM account_deletion_confirmations WHERE request_id = ? AND account_number = ?",
        (request_id, account_number),
    ).fetchall():
        device_id = row["device_id"]
        if device_id not in active:
            continue
        expected = account_deletion_device_binding(request_id, device_id, active[device_id])
        if hmac.compare_digest(expected, row["device_binding"] or ""):
            confirmed.add(device_id)
    return confirmed

async def read_request_body_mapping(request: Request) -> dict:
    # Same tolerant JSON-or-form body handling the existing /logout and
    # /free/logout routes use, so the app's transport does not have to change.
    content_type = request.headers.get("content-type", "")
    if "application/json" in content_type:
        try:
            decoded = await request.json()
            if isinstance(decoded, dict):
                return decoded
        except Exception:
            return {}
    elif "application/x-www-form-urlencoded" in content_type or "multipart/form-data" in content_type:
        return dict(await request.form())
    return {}

def authenticate_deletion_caller(conn: sqlite3.Connection, request: Request, action: str, body: dict) -> tuple:
    # Shared front door for all four routes. Rate limit BEFORE authentication
    # (mirroring the M-8 fix on /free/logout) so a failed-auth flood still
    # counts against the limit, then prove this exact device with its own
    # scoped bearer token. Account deletion is the single most dangerous
    # operation on the service: no route below is reachable on an account
    # number alone.
    acc = normalize_account_number(body.get("account_number") or body.get("accountnumber") or "")
    dev = str(body.get("device_id") or body.get("deviceid") or "").strip()
    if not acc or not dev:
        raise HTTPException(status_code=400, detail="Missing account_number/accountnumber or device_id/deviceid")
    check_rate_limit(
        conn,
        rate_limit_bucket("account-deletion-ip", request_origin_bucket_value(request)),
        ACCOUNT_DELETION_IP_RATE_LIMIT_PER_MINUTE,
        60,
    )
    check_rate_limit(
        conn,
        rate_limit_bucket("account-deletion-account", acc),
        ACCOUNT_DELETION_ACCOUNT_RATE_LIMIT_PER_HOUR,
        3600,
    )
    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    require_device_auth_token(conn, acc, dev, request, action)
    active_ids = {row["device_id"] for row in account_deletion_active_devices(conn, acc)}
    if dev not in active_ids:
        # Authenticated, but the row is stale or credential-less: it cannot be
        # part of a quorum it is not counted in.
        raise HTTPException(status_code=403, detail="This device is not an active device on the account.")
    return acc, dev

def account_deletion_status_payload(
    conn: sqlite3.Connection,
    account_number: str,
    device_id: str,
    pending: Optional[sqlite3.Row],
    override_stage: str = "",
) -> dict:
    active_count = len(account_deletion_active_devices(conn, account_number))
    required = required_deletion_confirmations(active_count)
    confirmed_ids = (
        valid_deletion_confirmation_device_ids(conn, pending["request_id"], account_number)
        if pending is not None else set()
    )
    if override_stage:
        stage = override_stage
    elif pending is None:
        stage = "unavailable" if active_count <= 0 else "none"
    elif int(pending["single_device_path"] or 0) == 1 and len(confirmed_ids) >= int(pending["required_confirmations"] or 0):
        stage = "awaiting_delay"
    else:
        stage = "awaiting_confirmations"
    return {
        "ok": True,
        "stage": stage,
        "active_device_count": active_count,
        "confirmed_device_count": len(confirmed_ids),
        "required_confirmations": int(pending["required_confirmations"]) if pending is not None else required,
        "this_device_confirmed": device_id in confirmed_ids,
        "execute_after": (pending["execute_after"] or "") if pending is not None else "",
        "request_id": (pending["request_id"] if pending is not None else ""),
        "single_device_delay_days": ACCOUNT_DELETION_SINGLE_DEVICE_DELAY_DAYS,
        "quorum": ACCOUNT_DELETION_QUORUM,
    }

def execute_account_deletion(
    conn: sqlite3.Connection,
    background_tasks: Optional[BackgroundTasks],
    account_number: str,
    pending: sqlite3.Row,
    confirmations_received: int,
) -> dict:
    # Real DELETEs, not a soft flag. Runs inside the caller's writer
    # transaction so a partial erase can never be observed or committed.
    acc = account_number
    tombstone = deleted_account_tombstone(acc)

    devices = conn.execute(
        """
        SELECT d.device_id, d.client_public_key, d.location_slug, n.endpoint, n.ssh_host
        FROM devices d
        LEFT JOIN nodes n ON n.slug = d.location_slug
        WHERE d.account_number = ?
        """,
        (acc,),
    ).fetchall()
    for row in devices:
        client_key = (row["client_public_key"] or "").strip()
        node_ip = row["ssh_host"] or extract_node_host(row["endpoint"] or "")
        if client_key and node_ip:
            queue_peer_revocation(conn, node_ip, client_key, background_tasks)

    # --- Referral graph: preserve the OTHER party, erase this party's id. ---
    # A referral row links two accounts. Deleting it would destroy the
    # referrer's record of why they hold bonus days and would defeat
    # claw_back_referral_bonus; leaving the account number in place would
    # retain exactly the identifier we promised to erase. So the deleted
    # account's number is replaced by a one-way tombstone on rows that belong
    # to someone else, and the referrer's already-granted bonus days are NOT
    # clawed back: the funding payment still stands, and a third party must
    # not lose time because someone else exercised a privacy right.
    referral_tombstoned = 0
    referral_tombstoned += conn.execute(
        "UPDATE referral_rewards SET referred_account_number = ? WHERE referred_account_number = ?",
        (tombstone, acc),
    ).rowcount
    referral_tombstoned += conn.execute(
        "UPDATE referral_rewards SET referrer_account_number = ? WHERE referrer_account_number = ?",
        (tombstone, acc),
    ).rowcount
    referral_tombstoned += conn.execute(
        "UPDATE users SET referred_by_account_number = ? WHERE referred_by_account_number = ?",
        (tombstone, acc),
    ).rowcount
    referral_tombstoned += conn.execute(
        "UPDATE payment_clicks SET referrer_account_number = ? WHERE referrer_account_number = ?",
        (tombstone, acc),
    ).rowcount
    # Prepaid-card ledger: which code was claimed stays (double-redemption
    # fraud control), by whom becomes a tombstone.
    referral_tombstoned += conn.execute(
        "UPDATE redemption_codes SET account_number = ? WHERE account_number = ?",
        (tombstone, acc),
    ).rowcount
    # R2: promo uses keep the campaign's history, not the deleted number.
    conn.execute(
        "UPDATE promo_redemptions SET account_number = ? || '#' || created_at WHERE account_number = ?",
        (tombstone, acc),
    )

    # --- Hard deletes -------------------------------------------------------
    # devices carries client_private_key, the server-stored WireGuard private
    # key for each device; destroying it is the whole point of the exercise.
    # PRAGMA foreign_keys=ON is set in get_db(), so every row referencing
    # users(account_number) must go before the users row itself.
    conn.execute("DELETE FROM double_vpn_assignments WHERE account_number = ?", (acc,))
    devices_deleted = conn.execute("DELETE FROM devices WHERE account_number = ?", (acc,)).rowcount
    if devices_deleted and background_tasks is not None:
        background_tasks.add_task(drain_winn3_registry_refreshes)
    legal_deleted = conn.execute("DELETE FROM legal_acceptances WHERE account_number = ?", (acc,)).rowcount
    conn.execute("DELETE FROM free_access_events WHERE account_number = ?", (acc,))
    # Live credential/delivery artefacts for an account that will not exist:
    # the sealed setup key and any queued fulfilment email.
    conn.execute("DELETE FROM redemption_fulfillments WHERE account_number = ?", (acc,))
    conn.execute("DELETE FROM redemption_outbox WHERE account_number = ?", (acc,))
    conn.execute("DELETE FROM hoppy_agent_mail_outbox WHERE account_ref = ?", (_hoppy_account_ref(acc),))
    conn.execute("DELETE FROM activation_extra_keys WHERE account_number = ?", (acc,))
    conn.execute("DELETE FROM account_deletion_confirmations WHERE account_number = ?", (acc,))
    conn.execute("DELETE FROM account_deletion_requests WHERE account_number = ?", (acc,))
    users_deleted = conn.execute("DELETE FROM users WHERE account_number = ?", (acc,)).rowcount

    # --- PII-free audit record ---------------------------------------------
    # Deliberately survives the deletion, so it must not restate what was
    # deleted. Only keyed one-way references and counters are written: no
    # account number, email, device id, IP address, or key material.
    conn.execute(
        """
        INSERT OR REPLACE INTO account_deletion_audit (
            audit_id, account_ref, request_ref, active_device_count, required_confirmations,
            confirmations_received, single_device_path, devices_deleted,
            legal_acceptances_deleted, referral_rows_tombstoned, outcome, completed_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            secrets.token_hex(16),
            security_event_hash(f"deletion-audit-account:{acc}"),
            security_event_hash(f"deletion-audit-request:{pending['request_id']}"),
            int(pending["active_device_count"] or 0),
            int(pending["required_confirmations"] or 0),
            int(confirmations_received),
            int(pending["single_device_path"] or 0),
            int(devices_deleted),
            int(legal_deleted),
            int(referral_tombstoned),
            "completed" if users_deleted else "completed_no_user_row",
            utcnow().isoformat(),
        ),
    )
    logger.info(
        "Account deletion completed (devices=%s legal=%s referral_tombstoned=%s)",
        devices_deleted, legal_deleted, referral_tombstoned,
    )
    return {
        "devices_deleted": devices_deleted,
        "legal_acceptances_deleted": legal_deleted,
        "referral_rows_tombstoned": referral_tombstoned,
        "users_deleted": users_deleted,
    }

def resolve_due_account_deletions(conn: sqlite3.Connection, background_tasks: Optional[BackgroundTasks] = None) -> int:
    # Completes single-device requests whose waiting period has elapsed. The
    # promise made in the UI -- "your account is erased automatically when the
    # waiting period ends" -- must not depend on the user coming back, so this
    # also runs from a periodic sweep (see account_deletion_sweep_loop).
    now = utcnow()
    due = conn.execute(
        """
        SELECT * FROM account_deletion_requests
        WHERE status = 'pending' AND execute_after IS NOT NULL AND execute_after != '' AND execute_after <= ?
        """,
        (now.isoformat(),),
    ).fetchall()
    completed = 0
    for pending in due:
        acc = pending["account_number"]
        confirmed = valid_deletion_confirmation_device_ids(conn, pending["request_id"], acc)
        if len(confirmed) < int(pending["required_confirmations"] or 0):
            # Every confirming device disappeared while the clock ran. Do not
            # erase an account on stale consent; drop the request instead.
            conn.execute(
                "UPDATE account_deletion_requests SET status='cancelled', resolved_at=?, resolution='lapsed_no_valid_confirmations' WHERE request_id=?",
                (now.isoformat(), pending["request_id"]),
            )
            continue
        execute_account_deletion(conn, background_tasks, acc, pending, len(confirmed))
        completed += 1
    return completed

def sweep_due_account_deletions() -> int:
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        return resolve_due_account_deletions(conn, None)


async def account_deletion_sweep_loop():
    # Hourly, best-effort. Wrapped so a transient DB error can never take the
    # control plane down; the next tick retries.
    while True:
        try:
            await asyncio.sleep(3600)
            completed = await asyncio.to_thread(sweep_due_account_deletions)
            if completed:
                logger.info("Account deletion sweep completed %s scheduled deletion(s)", completed)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("Account deletion sweep failed: %s", type(exc).__name__)

@app.post("/account/deletion/status")
async def account_deletion_status(request: Request, background_tasks: BackgroundTasks):
    body = await read_request_body_mapping(request)
    return await asyncio.to_thread(
        _account_deletion_status_sync, request, background_tasks, body
    )


def _account_deletion_status_sync(request: Request, background_tasks: BackgroundTasks, body: dict):
    with get_db() as conn:
        ensure_schema(conn)
        acc, dev = authenticate_deletion_caller(conn, request, "account deletion status", body)
        resolve_due_account_deletions(conn, background_tasks)
        pending = load_pending_deletion_request(conn, acc)
        payload = account_deletion_status_payload(conn, acc, dev, pending)
        payload["policy"] = account_deletion_policy_text(payload["active_device_count"])
        return payload

@app.post("/account/deletion/request")
async def account_deletion_request(request: Request, background_tasks: BackgroundTasks):
    body = await read_request_body_mapping(request)
    return await asyncio.to_thread(
        _account_deletion_request_sync, request, background_tasks, body
    )


def _account_deletion_request_sync(request: Request, background_tasks: BackgroundTasks, body: dict):
    with get_db() as conn:
        ensure_schema(conn)
        acc, dev = authenticate_deletion_caller(conn, request, "account deletion request", body)
        resolve_due_account_deletions(conn, background_tasks)
        existing = load_pending_deletion_request(conn, acc)
        if existing is not None:
            # Idempotent: a second request while one is pending joins the
            # existing request as a confirmation rather than opening a rival
            # one that could never reach quorum.
            record_deletion_confirmation(conn, existing, acc, dev)
            return finalize_deletion_progress(conn, background_tasks, acc, dev, existing)

        active = account_deletion_active_devices(conn, acc)
        active_count = len(active)
        if active_count <= 0:
            # 0 active devices: nothing can authorise the erase, and this
            # route is unreachable anyway because authenticate_deletion_caller
            # already requires the caller to BE an active device. Stated
            # explicitly so the contract is unambiguous rather than implied.
            raise HTTPException(
                status_code=409,
                detail="This account has no active devices. Activate a device, then request deletion from it.",
            )
        required = required_deletion_confirmations(active_count)
        single_device = 1 if active_count == 1 else 0
        request_id = secrets.token_urlsafe(24)
        now = utcnow()
        execute_after = (
            (now + timedelta(days=ACCOUNT_DELETION_SINGLE_DEVICE_DELAY_DAYS)).isoformat()
            if single_device else None
        )
        conn.execute(
            """
            INSERT INTO account_deletion_requests (
                request_id, account_number, status, active_device_count, required_confirmations,
                single_device_path, execute_after, requested_at
            ) VALUES (?, ?, 'pending', ?, ?, ?, ?, ?)
            """,
            (request_id, acc, active_count, required, single_device, execute_after, now.isoformat()),
        )
        pending = load_pending_deletion_request(conn, acc)
        # The requesting device has already proved itself with its own scoped
        # token, so its request IS its confirmation. Making it confirm again
        # in a second call would add friction without adding a second device.
        record_deletion_confirmation(conn, pending, acc, dev)
        security_alert(3, "account deletion requested", request=request, details={
            "account_hash": security_event_hash(acc),
            "active_devices": active_count,
            "required_confirmations": required,
        })
        return finalize_deletion_progress(conn, background_tasks, acc, dev, pending)

@app.post("/account/deletion/confirm")
async def account_deletion_confirm(request: Request, background_tasks: BackgroundTasks):
    body = await read_request_body_mapping(request)
    return await asyncio.to_thread(
        _account_deletion_confirm_sync, request, background_tasks, body
    )


def _account_deletion_confirm_sync(request: Request, background_tasks: BackgroundTasks, body: dict):
    with get_db() as conn:
        ensure_schema(conn)
        acc, dev = authenticate_deletion_caller(conn, request, "account deletion confirm", body)
        resolve_due_account_deletions(conn, background_tasks)
        pending = load_pending_deletion_request(conn, acc)
        if pending is None:
            raise HTTPException(status_code=404, detail="No deletion request is pending for this account.")
        supplied_request_id = str(body.get("request_id") or "").strip()
        if supplied_request_id and not hmac.compare_digest(supplied_request_id, pending["request_id"]):
            # The client is confirming something other than the request that is
            # actually open -- a stale screen, or a replay of a confirmation
            # meant for a request that has since been cancelled.
            raise HTTPException(status_code=409, detail="This deletion request is no longer current.")
        record_deletion_confirmation(conn, pending, acc, dev)
        return finalize_deletion_progress(conn, background_tasks, acc, dev, pending)

@app.post("/account/deletion/cancel")
async def account_deletion_cancel(request: Request, background_tasks: BackgroundTasks):
    body = await read_request_body_mapping(request)
    return await asyncio.to_thread(
        _account_deletion_cancel_sync, request, background_tasks, body
    )


def _account_deletion_cancel_sync(request: Request, background_tasks: BackgroundTasks, body: dict):
    with get_db() as conn:
        ensure_schema(conn)
        acc, dev = authenticate_deletion_caller(conn, request, "account deletion cancel", body)
        pending = load_pending_deletion_request(conn, acc)
        if pending is None:
            return account_deletion_status_payload(conn, acc, dev, None, override_stage="cancelled")
        # ANY active device may cancel, including one the real owner activates
        # after a theft. That is the escape hatch that makes the single-device
        # waiting period safe.
        conn.execute(
            "UPDATE account_deletion_requests SET status='cancelled', resolved_at=?, resolution='cancelled_by_device' WHERE request_id=?",
            (utcnow().isoformat(), pending["request_id"]),
        )
        conn.execute("DELETE FROM account_deletion_confirmations WHERE request_id = ?", (pending["request_id"],))
        security_alert(3, "account deletion cancelled", request=request, details={
            "account_hash": security_event_hash(acc),
        })
        return account_deletion_status_payload(conn, acc, dev, None, override_stage="cancelled")

def record_deletion_confirmation(conn: sqlite3.Connection, pending: sqlite3.Row, account_number: str, device_id: str) -> None:
    # PRIMARY KEY (request_id, device_id) is what caps a device at ONE vote:
    # confirming repeatedly from the same device can only ever rewrite its own
    # single row, never add a second.
    #
    # The conflict clause refreshes the binding rather than ignoring the write.
    # A device that legitimately re-enrolled mid-request (logout + activate
    # again) has a new device_auth_token, so its original binding no longer
    # reproduces and had stopped counting; without the refresh its slot would
    # be stuck at zero forever and the user could never finish deleting. The
    # refresh restores exactly one vote for that device -- never two, because
    # the row is keyed by device_id.
    row = conn.execute(
        "SELECT device_auth_token_hash FROM devices WHERE account_number = ? AND device_id = ?",
        (account_number, device_id),
    ).fetchone()
    token_hash = (row["device_auth_token_hash"] if row else "") or ""
    conn.execute(
        """
        INSERT INTO account_deletion_confirmations (
            request_id, device_id, account_number, device_binding, confirmed_at
        ) VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(request_id, device_id) DO UPDATE SET
            device_binding = excluded.device_binding,
            confirmed_at = excluded.confirmed_at
        """,
        (
            pending["request_id"],
            device_id,
            account_number,
            account_deletion_device_binding(pending["request_id"], device_id, token_hash),
            utcnow().isoformat(),
        ),
    )

def finalize_deletion_progress(
    conn: sqlite3.Connection,
    background_tasks: BackgroundTasks,
    account_number: str,
    device_id: str,
    pending: sqlite3.Row,
) -> dict:
    confirmed = valid_deletion_confirmation_device_ids(conn, pending["request_id"], account_number)
    required = int(pending["required_confirmations"] or 0)
    single_device = int(pending["single_device_path"] or 0) == 1
    if len(confirmed) >= required and not single_device:
        # Quorum of distinct devices reached: erase now.
        execute_account_deletion(conn, background_tasks, account_number, pending, len(confirmed))
        return {
            "ok": True,
            "stage": "completed",
            "active_device_count": 0,
            "confirmed_device_count": len(confirmed),
            "required_confirmations": required,
            "this_device_confirmed": True,
            "execute_after": "",
            "request_id": "",
            "single_device_delay_days": ACCOUNT_DELETION_SINGLE_DEVICE_DELAY_DAYS,
            "quorum": ACCOUNT_DELETION_QUORUM,
        }
    payload = account_deletion_status_payload(conn, account_number, device_id, pending)
    payload["policy"] = account_deletion_policy_text(payload["active_device_count"])
    return payload

def account_deletion_policy_text(active_device_count: int) -> str:
    # The applicable rule, in plain language, returned with every status so the
    # app can state what WILL happen rather than guessing. Mirrors
    # accountDeletionPolicyCopy() in lib/account_deletion.dart.
    required = required_deletion_confirmations(active_device_count)
    if active_device_count <= 0:
        return ("This account has no active devices, so there is no device that can authorise "
                "deletion. Activate a device with your account number and setup key, then delete "
                "the account from it.")
    if active_device_count == 1:
        return (f"This account has 1 active device. Deletion normally needs {ACCOUNT_DELETION_QUORUM} "
                "different devices to confirm, so that a lost or stolen device cannot destroy the "
                "account on its own. With only one device there is no second device to confirm, so "
                f"deletion starts a {ACCOUNT_DELETION_SINGLE_DEVICE_DELAY_DAYS}-day waiting period "
                "and completes automatically when it ends. Signing in on any device during that "
                "time lets you cancel.")
    return (f"This account has {active_device_count} active devices. Deletion must be confirmed from "
            f"{required} different devices, so a single lost or stolen device cannot destroy the "
            f"account. You do not need every device: if one is lost or broken, the remaining "
            f"{required} can still complete the deletion. Any active device can cancel while the "
            "request is pending.")

class _CloudflareNoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_CLOUDFLARE_NO_REDIRECT_OPENER = urllib.request.build_opener(_CloudflareNoRedirect)


def cloudflare_api_json(method: str, url: str, token: str, payload: Optional[dict] = None) -> dict:
    if not token:
        raise HTTPException(status_code=503, detail="Cloudflare management credential is unavailable")
    body = None if payload is None else json.dumps(payload, separators=(",", ":")).encode()
    request = urllib.request.Request(
        url,
        data=body,
        method=method,
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
    )
    try:
        with _CLOUDFLARE_NO_REDIRECT_OPENER.open(request, timeout=30) as response:
            decoded = json.loads(response.read().decode())
    except Exception as exc:
        logger.error("Cloudflare management request failed: %s", type(exc).__name__)
        raise HTTPException(status_code=502, detail="Cloudflare management request failed") from exc
    if not isinstance(decoded, dict) or decoded.get("success") is not True:
        logger.error("Cloudflare management API rejected an operation")
        raise HTTPException(status_code=502, detail="Cloudflare management API rejected the operation")
    return decoded

def management_tunnel_hostname(kind: str, identifier: str) -> str:
    normalized_kind = str(kind or "").strip().lower()
    slug = str(identifier or "").strip().lower()
    if normalized_kind not in {"node", "core"}:
        raise HTTPException(status_code=500, detail="Unsupported management tunnel kind")
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", slug):
        raise HTTPException(status_code=400, detail=f"{normalized_kind} identifier must be 2-40 lowercase letters, digits, or hyphens")
    secret = (MANAGEMENT_NAME_HMAC_KEY or ADMIN_SECRET_TOKEN).encode()
    opaque_tag = hmac.new(secret, f"{normalized_kind}-management:{slug}".encode(), hashlib.sha256).hexdigest()[:16]
    # Keep the management name exactly one label below the zone. Cloudflare's
    # standard edge certificate covers *.winsvpn.com, not
    # *.mgmt.example.test; the latter fails TLS before the SSH WebSocket can be
    # established. The maximum left-label length is 62 bytes (RFC limit 63).
    ssh_hostname = f"{normalized_kind}-{slug}-{opaque_tag}.{NODE_MANAGEMENT_TUNNEL_ZONE_NAME}"
    if len(ssh_hostname.split(".", 1)[0].encode("idna")) > 63:
        raise HTTPException(status_code=400, detail=f"{normalized_kind} identifier is too long for the management tunnel hostname")
    return ssh_hostname

def node_management_hostname(node_slug: str) -> str:
    return management_tunnel_hostname("node", node_slug)

def core_management_hostname(core_id: str) -> str:
    return management_tunnel_hostname("core", core_id)

def ensure_cloudflare_access_application(ssh_hostname: str) -> str:
    if not HIDE_CONTROL_ORIGIN or not REQUIRE_CLOUDFLARE_ACCESS:
        return ""
    if not re.fullmatch(r"[a-fA-F0-9]{32}", CLOUDFLARE_TUNNEL_ACCOUNT_ID):
        raise HTTPException(status_code=503, detail="Cloudflare Access account is not configured")
    if not CLOUDFLARE_ACCESS_API_TOKEN:
        raise HTTPException(status_code=503, detail="Cloudflare Access API token is not configured")
    if not re.fullmatch(r"[a-fA-F0-9-]{36}", CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID):
        raise HTTPException(status_code=503, detail="Cloudflare Access service-token UUID is not configured")
    if not TUNNEL_SERVICE_TOKEN_ID.endswith(".access") or len(TUNNEL_SERVICE_TOKEN_SECRET) < 32:
        raise HTTPException(status_code=503, detail="Cloudflare Access service-token credentials are unavailable")

    host = normalize_hostname(ssh_hostname)
    if not re.fullmatch(r"[a-z0-9.-]{4,253}", host) or "." not in host:
        raise HTTPException(status_code=500, detail="Management Access hostname is invalid")
    api = f"https://api.cloudflare.com/client/v4/accounts/{CLOUDFLARE_TUNNEL_ACCOUNT_ID}/access/apps"
    listing = cloudflare_api_json("GET", f"{api}?per_page=1000", CLOUDFLARE_ACCESS_API_TOKEN)
    matches = [
        item for item in listing.get("result", [])
        if isinstance(item, dict) and normalize_hostname(item.get("domain") or "") == host
    ]
    if len(matches) > 1:
        raise HTTPException(status_code=409, detail="Multiple Cloudflare Access applications protect the management hostname")
    app_name = f"winsvpn-management-{host.split('.', 1)[0]}"[:350]
    policy_name = f"{app_name}-service-auth"[:350]
    payload = {
        "name": app_name,
        "domain": host,
        "type": "self_hosted",
        "session_duration": "24h",
        "app_launcher_visible": False,
        "skip_interstitial": True,
        "policies": [{
            "name": policy_name,
            "precedence": 1,
            "decision": "non_identity",
            "include": [{
                "service_token": {"token_id": CLOUDFLARE_ACCESS_SERVICE_TOKEN_UUID},
            }],
        }],
    }
    if matches and re.fullmatch(r"[a-fA-F0-9-]{36}", str(matches[0].get("id") or "")):
        app_id = str(matches[0]["id"])
        configured = cloudflare_api_json("PUT", f"{api}/{app_id}", CLOUDFLARE_ACCESS_API_TOKEN, payload)
    else:
        configured = cloudflare_api_json("POST", api, CLOUDFLARE_ACCESS_API_TOKEN, payload)
        app_id = str((configured.get("result") or {}).get("id") or "")
    result = configured.get("result") or {}
    if not re.fullmatch(r"[a-fA-F0-9-]{36}", app_id):
        app_id = str(result.get("id") or "")
    if not re.fullmatch(r"[a-fA-F0-9-]{36}", app_id) or normalize_hostname(result.get("domain") or "") != host:
        raise HTTPException(status_code=502, detail="Cloudflare returned an invalid Access application")
    return app_id

def ensure_ssh_management_tunnel(kind: str, identifier: str) -> dict[str, object]:
    normalized_kind = str(kind or "").strip().lower()
    slug = str(identifier or "").strip().lower()
    ssh_hostname = management_tunnel_hostname(normalized_kind, slug)
    if not re.fullmatch(r"[a-fA-F0-9]{32}", CLOUDFLARE_TUNNEL_ACCOUNT_ID):
        raise HTTPException(status_code=503, detail="Cloudflare Tunnel account is not configured")
    if not re.fullmatch(r"[a-z0-9.-]{4,253}", NODE_MANAGEMENT_TUNNEL_ZONE_NAME) or "." not in NODE_MANAGEMENT_TUNNEL_ZONE_NAME:
        raise HTTPException(status_code=503, detail="Management tunnel zone is invalid")
    if not re.fullmatch(r"[a-fA-F0-9]{32}", NODE_MANAGEMENT_TUNNEL_ZONE_ID):
        raise HTTPException(status_code=503, detail="Management tunnel zone ID is invalid")
    tunnel_name = f"winsvpn-{normalized_kind}-{slug}"
    legacy_ssh_hostname = f"{ssh_hostname.split('.', 1)[0]}.mgmt.{NODE_MANAGEMENT_TUNNEL_ZONE_NAME}" if normalized_kind == "node" else ""
    api = f"https://api.cloudflare.com/client/v4/accounts/{CLOUDFLARE_TUNNEL_ACCOUNT_ID}/cfd_tunnel"
    query = urllib.parse.urlencode({"name": tunnel_name, "is_deleted": "false"})
    listing = cloudflare_api_json("GET", f"{api}?{query}", CLOUDFLARE_TUNNEL_API_TOKEN)
    matches = [item for item in listing.get("result", []) if isinstance(item, dict) and item.get("name") == tunnel_name and not item.get("deleted_at")]
    if matches:
        tunnel_id = str(matches[0].get("id") or "")
    else:
        created = cloudflare_api_json(
            "POST",
            api,
            CLOUDFLARE_TUNNEL_API_TOKEN,
            {"name": tunnel_name, "config_src": "cloudflare"},
        )
        tunnel_id = str((created.get("result") or {}).get("id") or "")
    if not re.fullmatch(r"[a-fA-F0-9-]{36}", tunnel_id):
        raise HTTPException(status_code=502, detail="Cloudflare returned an invalid management tunnel ID")
    cloudflare_api_json(
        "PUT",
        f"{api}/{tunnel_id}/configurations",
        CLOUDFLARE_TUNNEL_API_TOKEN,
        {"config": {"ingress": [
            {"hostname": ssh_hostname, "service": "ssh://127.0.0.1:22", "originRequest": {"connectTimeout": 10}},
            {"service": "http_status:404"},
        ]}},
    )
    dns_api = f"https://api.cloudflare.com/client/v4/zones/{NODE_MANAGEMENT_TUNNEL_ZONE_ID}/dns_records"
    dns_query = urllib.parse.urlencode({"name": ssh_hostname})
    dns_listing = cloudflare_api_json("GET", f"{dns_api}?{dns_query}", CLOUDFLARE_WINS_API_TOKEN)
    records = [item for item in dns_listing.get("result", []) if isinstance(item, dict)]
    dns_payload = {
        "type": "CNAME",
        "name": ssh_hostname,
        "content": f"{tunnel_id}.cfargotunnel.com",
        "ttl": 1,
        "proxied": True,
    }
    if records and records[0].get("id"):
        current = records[0]
        dns_unchanged = (
            str(current.get("type") or "").upper() == "CNAME"
            and normalize_hostname(current.get("name") or "") == ssh_hostname
            and normalize_hostname(current.get("content") or "") == normalize_hostname(dns_payload["content"])
            and current.get("proxied") is True
            and int(current.get("ttl") or 1) == 1
        )
        if not dns_unchanged:
            cloudflare_api_json("PUT", f"{dns_api}/{current['id']}", CLOUDFLARE_WINS_API_TOKEN, dns_payload)
    else:
        cloudflare_api_json("POST", dns_api, CLOUDFLARE_WINS_API_TOKEN, dns_payload)
    # Remove the former two-label record after replacing the tunnel ingress.
    # Besides being unusable with a standard wildcard edge certificate, it is
    # an unnecessary stale management name.
    if legacy_ssh_hostname and legacy_ssh_hostname != ssh_hostname:
        legacy_query = urllib.parse.urlencode({"name": legacy_ssh_hostname})
        legacy_listing = cloudflare_api_json("GET", f"{dns_api}?{legacy_query}", CLOUDFLARE_WINS_API_TOKEN)
        for record in legacy_listing.get("result", []):
            if isinstance(record, dict) and record.get("id"):
                cloudflare_api_json("DELETE", f"{dns_api}/{record['id']}", CLOUDFLARE_WINS_API_TOKEN)
    access_application_id = ensure_cloudflare_access_application(ssh_hostname)
    token_response = cloudflare_api_json("GET", f"{api}/{tunnel_id}/token", CLOUDFLARE_TUNNEL_API_TOKEN)
    connector_token = str(token_response.get("result") or "")
    if len(connector_token) < 80 or any(ch.isspace() for ch in connector_token):
        raise HTTPException(status_code=502, detail="Cloudflare returned an invalid management connector token")
    return {
        "tunnel_id": tunnel_id,
        "ssh_host": ssh_hostname,
        "tunnel_token": connector_token,
        "access_required": bool(HIDE_CONTROL_ORIGIN and REQUIRE_CLOUDFLARE_ACCESS),
        "access_application_id": access_application_id,
    }

def ensure_node_management_tunnel(node_slug: str) -> dict[str, object]:
    return ensure_ssh_management_tunnel("node", node_slug)

def ensure_core_management_tunnel(core_id: str) -> dict[str, object]:
    return ensure_ssh_management_tunnel("core", core_id)

# --- Hub-brokered edge operations (L41, Round CF) ---------------------------
#
# WHY THIS EXISTS. Every data plane and Core used to hold CLOUDFLARE_API_TOKEN
# for the app-cloud stealth zone. Cloudflare API tokens scope to whole zones,
# never to single records, so one seized node yielded DNS, redirect-rule,
# zone-setting and Origin CA authority over every stealth hostname. The hub
# now holds that one credential and performs each edge operation for an
# authenticated node or Core, restricted to canonical hostnames the OPERATOR
# assigned to that subject. Nodes and Cores hold no Cloudflare credential and
# no credential that can change an assignment.
#
# AUTHORITY SPLIT.
#   * Node and Core tokens (the deployed hub's own subject records) authorize
#     operations on that subject's assigned names only.
#   * EDGE_ADMIN_TOKEN, a hub-only operator credential that is never the fleet
#     ADMIN_TOKEN and is never delivered to any node, is the only credential
#     that can change hostname assignments or the reservation inventory.
#   * The reservation inventory (zone apex plus every live and retired hub
#     route) is operator-owned and FAIL-CLOSED: until the operator attests it,
#     every edge operation answers 503.
#
# Nodes reach these endpoints only through HUB_API_BASE, the Cloudflare-fronted
# hub hostname. No response carries the Cloudflare token or a hub address.

CLOUDFLARE_APPCLOUD_API_TOKEN = os.getenv("CLOUDFLARE_APPCLOUD_API_TOKEN", "").strip()
CLOUDFLARE_APPCLOUD_ZONE_ID = os.getenv("CLOUDFLARE_APPCLOUD_ZONE_ID", "").strip()
CLOUDFLARE_APPCLOUD_ZONE_NAME = (os.getenv("CLOUDFLARE_APPCLOUD_ZONE_NAME", "") or "app-cloud-sync.net").strip().lower().rstrip(".")
CLOUDFLARE_APPCLOUD_RECORDS = os.getenv("CLOUDFLARE_APPCLOUD_RECORDS", "").strip().lower()
CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS = (
    os.getenv("CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS", "") or "app-cloud-sync.net sync.app-cloud-sync.net"
).strip().lower()
EDGE_ADMIN_TOKEN = os.getenv("EDGE_ADMIN_TOKEN", "").strip()

EDGE_SUBJECT_KINDS = {"node", "core"}
EDGE_MAX_HOSTNAMES = 16
EDGE_MAX_ACME_TXT_PER_NAME = 4
EDGE_LABEL_RE = re.compile(r"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")
EDGE_ACME_VALIDATION_RE = re.compile(r"^[A-Za-z0-9_-]{20,128}$")
EDGE_CLOUDFLARE_ID_RE = re.compile(r"^[A-Za-z0-9-]{1,128}$")
# ONE lease serializes every zone-changing path: subject operations,
# assignment changes, reservation changes and redirect transactions. It is
# extended to EDGE_ZONE_LEASE_SECONDS at every fence, and a fence fails unless
# more than EDGE_CF_CALL_BUDGET_SECONDS remain, so each Cloudflare call (30 s
# socket timeout) starts with the lease valid well past its end. Waits stay
# inside the hub nginx proxy_read_timeout (90 s) and the Cloudflare origin
# timeout in front of it.
EDGE_ZONE_LEASE_SECONDS = 120
EDGE_CF_CALL_BUDGET_SECONDS = 45
EDGE_ZONE_LEASE_WAIT_SECONDS = 30


class EdgeAcmeChallengeRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    action: str
    hostname: str
    validation: str


class EdgeHostnameBindingRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    subject_kind: str
    subject_id: str
    hostnames: list[str] = Field(default_factory=list)
    action: str = "bind"
    # Unbinding a hostname that still has plaintext exception pairs is refused
    # unless the operator asks to remove those pairs first, under the same lease.
    remove_exceptions: bool = False


class EdgeReservationRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    action: str
    hostnames: list[str] = Field(default_factory=list)


def create_edge_broker_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_hostname_bindings (
            hostname TEXT PRIMARY KEY,
            subject_kind TEXT NOT NULL,
            subject_id TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_reserved_hostnames (
            hostname TEXT PRIMARY KEY,
            created_at TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_zone_state (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_zone_leases (
            name TEXT PRIMARY KEY,
            holder TEXT NOT NULL,
            expires_at TEXT NOT NULL
        )
    """)
    edge_create_extra_tables(conn)


@contextmanager
def edge_db():
    with get_db() as conn:
        ensure_schema(conn)
        create_edge_broker_tables(conn)
        yield conn


def edge_state_get(conn: sqlite3.Connection, key: str) -> Optional[str]:
    row = conn.execute("SELECT value FROM edge_zone_state WHERE key = ?", (key,)).fetchone()
    return row["value"] if row else None


def edge_state_set(conn: sqlite3.Connection, key: str, value: str) -> None:
    conn.execute("INSERT OR REPLACE INTO edge_zone_state (key, value) VALUES (?, ?)", (key, value))


def edge_state_delete(conn: sqlite3.Connection, key: str) -> None:
    conn.execute("DELETE FROM edge_zone_state WHERE key = ?", (key,))


# An exception pair in any of these states pins its hostname: it cannot be
# unassigned (without first removing the pair) or assigned to anyone else.
EDGE_PINNING_EXCEPTION_STATES = ("armed", "committed", "pending", "rollback_failed")


def edge_exceptions_naming(conn: sqlite3.Connection, host: str) -> list:
    if not conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'edge_plaintext_exceptions'"
    ).fetchone():
        return []
    placeholders = ", ".join("?" for _ in EDGE_PINNING_EXCEPTION_STATES)
    return [
        dict(row) for row in conn.execute(
            "SELECT hostname, path, subject_kind, subject_id, transaction_id, state FROM edge_plaintext_exceptions "
            f"WHERE hostname = ? AND state IN ({placeholders})",
            (host, *EDGE_PINNING_EXCEPTION_STATES),
        ).fetchall()
    ]


def edge_valid_fqdn(host: str) -> bool:
    if not host or len(host) > 253 or "." not in host:
        return False
    return all(EDGE_LABEL_RE.fullmatch(label) for label in host.split("."))


def edge_require_zone() -> str:
    if not CLOUDFLARE_APPCLOUD_API_TOKEN:
        raise HTTPException(status_code=503, detail="Edge broker credential is not configured on the hub")
    if not re.fullmatch(r"[a-fA-F0-9]{32}", CLOUDFLARE_APPCLOUD_ZONE_ID):
        raise HTTPException(status_code=503, detail="Edge broker zone ID is not configured on the hub")
    if not edge_valid_fqdn(CLOUDFLARE_APPCLOUD_ZONE_NAME):
        raise HTTPException(status_code=503, detail="Edge broker zone name is invalid")
    return CLOUDFLARE_APPCLOUD_ZONE_ID


def require_edge_admin_token(token: Optional[str], request: Optional[Request], action: str) -> None:
    # A dedicated operator credential. It must differ from the fleet
    # ADMIN_TOKEN, which older installers delivered to nodes.
    if len(EDGE_ADMIN_TOKEN) < 32 or any(ch.isspace() for ch in EDGE_ADMIN_TOKEN):
        raise HTTPException(status_code=503, detail="Edge administration credential is not configured on the hub")
    if ADMIN_SECRET_TOKEN and hmac.compare_digest(EDGE_ADMIN_TOKEN.encode(), str(ADMIN_SECRET_TOKEN).encode()):
        raise HTTPException(status_code=503, detail="Edge administration credential must differ from the fleet admin token")
    supplied = hashlib.sha256(str(token or "").encode()).digest()
    expected = hashlib.sha256(EDGE_ADMIN_TOKEN.encode()).digest()
    if not token or not hmac.compare_digest(supplied, expected):
        security_alert(2, "invalid edge admin token", request=request, details={"action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")


def edge_validate_kind(kind: Any) -> str:
    normalized = str(kind or "").strip().lower()
    if normalized not in EDGE_SUBJECT_KINDS:
        raise HTTPException(status_code=400, detail="subject_kind must be 'node' or 'core'")
    return normalized


def edge_validate_subject(subject: Any) -> str:
    normalized = str(subject or "").strip().lower()
    if not EDGE_LABEL_RE.fullmatch(normalized) or len(normalized) < 2:
        raise HTTPException(status_code=400, detail="Subject identifier must be a valid lowercase DNS label")
    return normalized


def edge_canonical_hostname(value: Any) -> str:
    return normalize_hostname(value).rstrip(".")


def edge_reserved_hostnames(conn: sqlite3.Connection) -> set:
    # Apex, configured live and retired hub routes, and the operator's
    # inventory rows. The inventory is the authority; the env lists are a
    # floor that the inventory can only extend.
    reserved = {CLOUDFLARE_APPCLOUD_ZONE_NAME}
    for raw in re.split(r"[\s,]+", f"{CLOUDFLARE_APPCLOUD_RECORDS} {CLOUDFLARE_RETIRED_APPCLOUD_HUB_RECORDS}"):
        host = edge_canonical_hostname(raw)
        if host:
            reserved.add(host)
    for row in conn.execute("SELECT hostname FROM edge_reserved_hostnames").fetchall():
        reserved.add(row["hostname"])
    return reserved


def edge_require_inventory(conn: sqlite3.Connection) -> None:
    if not edge_state_get(conn, "reservations_attested_at"):
        raise HTTPException(
            status_code=503,
            detail="The edge reservation inventory has not been attested by the operator; edge operations are closed",
        )


def edge_normalize_candidate(conn: sqlite3.Connection, value: Any) -> str:
    host = edge_canonical_hostname(value)
    zone = CLOUDFLARE_APPCLOUD_ZONE_NAME
    if not edge_valid_fqdn(host) or host == zone or not host.endswith("." + zone):
        raise HTTPException(status_code=400, detail="Hostname must be a valid name inside the edge zone")
    if host in edge_reserved_hostnames(conn):
        raise HTTPException(status_code=403, detail="Hostname is reserved for the hub")
    return host


def edge_implicit_default_owners(conn: sqlite3.Connection, host: str) -> list:
    zone = CLOUDFLARE_APPCLOUD_ZONE_NAME
    if not host.endswith("." + zone):
        return []
    label = host[: -(len(zone) + 1)]
    if "." in label or not EDGE_LABEL_RE.fullmatch(label):
        return []
    owners = []
    if conn.execute("SELECT 1 FROM nodes WHERE slug = ?", (label,)).fetchone():
        owners.append(("node", label))
    if conn.execute("SELECT 1 FROM core_servers WHERE core_id = ?", (label,)).fetchone():
        owners.append(("core", label))
    return owners


def edge_allowed_hostnames(conn: sqlite3.Connection, kind: str, subject: str) -> list:
    reserved = edge_reserved_hostnames(conn)
    allowed = []
    default = f"{subject}.{CLOUDFLARE_APPCLOUD_ZONE_NAME}"
    if edge_valid_fqdn(default) and default not in reserved:
        bound = conn.execute(
            "SELECT subject_kind, subject_id FROM edge_hostname_bindings WHERE hostname = ?", (default,)
        ).fetchone()
        if bound is not None:
            if (bound["subject_kind"], bound["subject_id"]) == (kind, subject):
                allowed.append(default)
        elif edge_implicit_default_owners(conn, default) == [(kind, subject)]:
            allowed.append(default)
    for row in conn.execute(
        "SELECT hostname FROM edge_hostname_bindings WHERE subject_kind = ? AND subject_id = ? ORDER BY hostname",
        (kind, subject),
    ).fetchall():
        if row["hostname"] not in allowed and row["hostname"] not in reserved:
            allowed.append(row["hostname"])
    return allowed


def edge_require_hostnames(conn: sqlite3.Connection, kind: str, subject: str, hostnames: Any,
                           request: Optional[Request] = None) -> list:
    raw = list(hostnames or [])
    if not raw:
        raise HTTPException(status_code=400, detail="At least one hostname is required")
    if len(raw) > EDGE_MAX_HOSTNAMES:
        raise HTTPException(status_code=400, detail="Too many hostnames in one edge request")
    allowed = set(edge_allowed_hostnames(conn, kind, subject))
    normalized = []
    for item in raw:
        host = edge_normalize_candidate(conn, item)
        if host not in allowed:
            security_alert(2, "edge hostname outside subject assignment", request=request, details={
                "kind": kind, "subject": subject, "hostname_hash": security_event_hash(host),
            })
            raise HTTPException(status_code=403, detail="Hostname is not assigned to this subject")
        if host not in normalized:
            normalized.append(host)
    return normalized


def edge_cf_request(method: str, path: str, payload: Optional[dict] = None) -> tuple:
    """One Cloudflare call with the app-zone credential. Returns (status, body)
    without raising on a Cloudflare-side rejection. Never logs the credential,
    request bodies, or hostnames."""
    url = f"https://api.cloudflare.com/client/v4/{path.lstrip('/')}"
    body = None if payload is None else json.dumps(payload, separators=(",", ":")).encode()
    request = urllib.request.Request(
        url,
        data=body,
        method=method,
        headers={"Authorization": f"Bearer {CLOUDFLARE_APPCLOUD_API_TOKEN}", "Content-Type": "application/json"},
    )
    try:
        with _CLOUDFLARE_NO_REDIRECT_OPENER.open(request, timeout=30) as response:
            status = int(getattr(response, "status", 200) or 200)
            raw = response.read()
    except urllib.error.HTTPError as exc:
        status = int(exc.code)
        raw = exc.read() or b""
    except Exception as exc:
        logger.error("Edge broker Cloudflare request failed: %s", type(exc).__name__)
        raise HTTPException(status_code=502, detail="Edge broker could not reach Cloudflare") from exc
    try:
        decoded = json.loads(raw.decode() or "{}")
    except (UnicodeDecodeError, json.JSONDecodeError):
        decoded = {}
    if not isinstance(decoded, dict):
        decoded = {}
    return status, decoded


def edge_cf(method: str, path: str, payload: Optional[dict] = None) -> dict:
    status, decoded = edge_cf_request(method, path, payload)
    if decoded.get("success") is not True:
        codes = ",".join(
            str(item.get("code")) for item in decoded.get("errors") or [] if isinstance(item, dict)
        )[:120]
        logger.error("Edge broker Cloudflare operation rejected: method=%s status=%s codes=%s", method, status, codes or "-")
        raise HTTPException(status_code=502, detail="Cloudflare rejected the edge operation")
    return decoded


class EdgeLease:
    def __init__(self, name: str, holder: str):
        self.name = name
        self.holder = holder


@contextmanager
def edge_zone_lease(name: str = "zone"):
    holder = secrets.token_hex(16)
    deadline = time.monotonic() + EDGE_ZONE_LEASE_WAIT_SECONDS
    while True:
        now = utcnow()
        with edge_db() as conn:
            conn.execute("DELETE FROM edge_zone_leases WHERE name = ? AND expires_at <= ?", (name, now.isoformat()))
            cursor = conn.execute(
                "INSERT OR IGNORE INTO edge_zone_leases (name, holder, expires_at) VALUES (?, ?, ?)",
                (name, holder, (now + timedelta(seconds=EDGE_ZONE_LEASE_SECONDS)).isoformat()),
            )
            acquired = cursor.rowcount == 1
        if acquired:
            break
        if time.monotonic() >= deadline:
            raise HTTPException(status_code=409, detail="Another edge redirect change is in progress; retry later")
        time.sleep(1)
    try:
        yield EdgeLease(name, holder)
    finally:
        with edge_db() as conn:
            conn.execute("DELETE FROM edge_zone_leases WHERE name = ? AND holder = ?", (name, holder))


def edge_lease_fence(lease: EdgeLease) -> None:
    """Re-validate and extend the lease immediately before a Cloudflare call.
    Fails (409, nothing further changed) when the lease has expired, was taken
    over, or has too little time left to cover the call."""
    now = utcnow()
    with edge_db() as conn:
        cursor = conn.execute(
            "UPDATE edge_zone_leases SET expires_at = ? WHERE name = ? AND holder = ? AND expires_at > ?",
            (
                (now + timedelta(seconds=EDGE_ZONE_LEASE_SECONDS)).isoformat(),
                lease.name, lease.holder,
                (now + timedelta(seconds=EDGE_CF_CALL_BUDGET_SECONDS)).isoformat(),
            ),
        )
        held = cursor.rowcount == 1
    if not held:
        logger.error("Edge zone lease lost before a Cloudflare call; stopping without further change")
        raise HTTPException(status_code=409, detail="The edge zone lease expired or was lost; no further change was made")


class EdgeGuard:
    """Checked immediately before EVERY Cloudflare call, reads included: the
    lease is still held (and extended), the reservation inventory is still
    attested, and, for a subject operation, every hostname it acts on is still
    assigned to that subject. Assignment and reservation changes take the same
    lease, so they cannot interleave with a running operation; the recheck
    also catches any change made behind the API."""

    def __init__(self, lease: "EdgeLease", kind: Optional[str] = None, subject: Optional[str] = None,
                 hostnames: Any = ()):
        self.lease = lease
        self.kind = kind
        self.subject = subject
        self.hostnames = list(hostnames or [])

    def check(self) -> None:
        edge_lease_fence(self.lease)
        with edge_db() as conn:
            edge_require_inventory(conn)
            if self.kind and self.hostnames:
                allowed = set(edge_allowed_hostnames(conn, self.kind, self.subject))
                if any(host not in allowed for host in self.hostnames):
                    logger.error("Edge hostname assignment changed during an operation; stopping without further change")
                    raise HTTPException(
                        status_code=403,
                        detail="A hostname in this operation is no longer assigned to this subject; nothing further was changed",
                    )


def edge_cf_guarded(guard: EdgeGuard, method: str, path: str, payload: Optional[dict] = None) -> dict:
    guard.check()
    return edge_cf(method, path, payload)


def edge_cf_request_guarded(guard: EdgeGuard, method: str, path: str, payload: Optional[dict] = None) -> tuple:
    guard.check()
    return edge_cf_request(method, path, payload)


def edge_txt_value(content: Any) -> str:
    value = str(content or "").strip()
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        value = value[1:-1]
    return value


def edge_acme_challenge(kind: str, subject: str, payload: Any, request: Optional[Request] = None) -> dict:
    zone_id = edge_require_zone()
    action = str(getattr(payload, "action", "") or "").strip().lower()
    if action not in {"present", "cleanup"}:
        raise HTTPException(status_code=400, detail="action must be present or cleanup")
    validation = str(getattr(payload, "validation", "") or "").strip()
    if not EDGE_ACME_VALIDATION_RE.fullmatch(validation):
        raise HTTPException(status_code=400, detail="validation is not an ACME DNS-01 token")
    with edge_db() as conn:
        edge_require_inventory(conn)
        host = edge_require_hostnames(conn, kind, subject, [getattr(payload, "hostname", "")], request)[0]
    record_name = f"_acme-challenge.{host}"
    query = urllib.parse.urlencode({"type": "TXT", "name": record_name, "per_page": 100})
    with edge_zone_lease() as lease:
        guard = EdgeGuard(lease, kind, subject, [host])
        return edge_acme_challenge_locked(guard, zone_id, record_name, query, action, validation)


def edge_acme_challenge_locked(guard: EdgeGuard, zone_id: str, record_name: str, query: str,
                               action: str, validation: str) -> dict:
    listing = edge_cf_guarded(guard, "GET", f"zones/{zone_id}/dns_records?{query}")
    records = [
        item for item in listing.get("result") or []
        if isinstance(item, dict)
        and str(item.get("type") or "").upper() == "TXT"
        # normalize_hostname() rejects the underscore label, so compare raw.
        and str(item.get("name") or "").strip().lower().rstrip(".") == record_name
    ]
    matching = [item for item in records if edge_txt_value(item.get("content")) == validation]
    if action == "present":
        if matching:
            return {"ok": True, "state": "present"}
        if len(records) >= EDGE_MAX_ACME_TXT_PER_NAME:
            raise HTTPException(status_code=409, detail="Too many pending ACME challenge records for this hostname")
        edge_cf_guarded(guard, "POST", f"zones/{zone_id}/dns_records", {"type": "TXT", "name": record_name, "content": validation, "ttl": 60})
        return {"ok": True, "state": "created"}
    removed = 0
    for item in matching:
        record_id = str(item.get("id") or "")
        if EDGE_CLOUDFLARE_ID_RE.fullmatch(record_id):
            edge_cf_guarded(guard, "DELETE", f"zones/{zone_id}/dns_records/{record_id}")
            removed += 1
    return {"ok": True, "state": "removed", "removed": removed}


def edge_authorize_node(slug: str, token: Optional[str], request: Optional[Request], action: str) -> str:
    subject = edge_validate_subject(slug)
    with edge_db() as conn:
        require_node_token(conn, subject, token, request, action)
        row = conn.execute("SELECT retired_at FROM nodes WHERE slug = ?", (subject,)).fetchone()
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="A retired node cannot perform edge operations")
    return subject


def edge_authorize_core(core_id: str, token: Optional[str], request: Optional[Request], action: str) -> str:
    subject = edge_validate_subject(core_id)
    with edge_db() as conn:
        require_core_token(conn, subject, token, request, action)
    return subject


def edge_hostname_listing(kind: str, subject: str) -> dict:
    edge_require_zone()
    with edge_db() as conn:
        edge_require_inventory(conn)
        hosts = edge_allowed_hostnames(conn, kind, subject)
    return {"ok": True, "zone": CLOUDFLARE_APPCLOUD_ZONE_NAME, "hostnames": hosts}


@app.get("/api/v1/nodes/{slug}/edge/hostnames")
def node_edge_hostnames(slug: str, request: Request, x_node_token: Optional[str] = Header(default=None)):
    subject = edge_authorize_node(slug, x_node_token, request, "edge hostnames")
    return edge_hostname_listing("node", subject)


@app.post("/api/v1/nodes/{slug}/edge/acme-challenge")
def node_edge_acme_challenge(slug: str, payload: EdgeAcmeChallengeRequest, request: Request, x_node_token: Optional[str] = Header(default=None)):
