@app.post("/admin/edge/reservations")
def admin_edge_reservations(payload: EdgeReservationRequest, request: Request, x_edge_admin_token: Optional[str] = Header(default=None)):
    """Operator-owned reservation inventory. `add` and `remove` change it and
    CLEAR the attestation; `attest` records that the inventory now covers the
    zone apex and every live and retired hub route, and is refused while any
    assigned hostname is reserved."""
    require_edge_admin_token(x_edge_admin_token, request, "edge reservations")
    edge_require_zone()
    action = str(getattr(payload, "action", "") or "").strip().lower()
    if action not in {"add", "remove", "attest"}:
        raise HTTPException(status_code=400, detail="action must be add, remove, or attest")
    zone = CLOUDFLARE_APPCLOUD_ZONE_NAME
    raw = list(getattr(payload, "hostnames", None) or [])
    if action != "attest" and (not raw or len(raw) > 64):
        raise HTTPException(status_code=400, detail="Between 1 and 64 hostnames are required")
    hosts = []
    for item in raw:
        host = edge_canonical_hostname(item)
        if not edge_valid_fqdn(host) or not (host == zone or host.endswith("." + zone)):
            raise HTTPException(status_code=400, detail="Reserved names must be the zone apex or names inside it")
        hosts.append(host)
    with edge_zone_lease() as lease:
        # Fence first, then open the database: the fence writes the lease row
        # on its own connection and must not wait behind this one.
        edge_lease_fence(lease)
        with edge_db() as conn:
            if action == "add":
                for host in hosts:
                    if conn.execute("SELECT 1 FROM edge_hostname_bindings WHERE hostname = ?", (host,)).fetchone():
                        raise HTTPException(status_code=409, detail="A hostname to reserve is assigned to a subject; unassign it first")
                    conn.execute(
                        "INSERT OR IGNORE INTO edge_reserved_hostnames (hostname, created_at) VALUES (?, ?)",
                        (host, utcnow().isoformat()),
                    )
                edge_state_delete(conn, "reservations_attested_at")
            elif action == "remove":
                for host in hosts:
                    conn.execute("DELETE FROM edge_reserved_hostnames WHERE hostname = ?", (host,))
                edge_state_delete(conn, "reservations_attested_at")
            else:
                reserved = edge_reserved_hostnames(conn)
                conflicts = [
                    row["hostname"] for row in conn.execute("SELECT hostname FROM edge_hostname_bindings").fetchall()
                    if row["hostname"] in reserved
                ]
                if conflicts:
                    raise HTTPException(status_code=409, detail=f"{len(conflicts)} assigned hostname(s) are reserved; resolve before attesting")
                edge_state_set(conn, "reservations_attested_at", utcnow().isoformat())
            reserved_now = sorted(edge_reserved_hostnames(conn))
            attested = bool(edge_state_get(conn, "reservations_attested_at"))
    security_alert(4, f"edge reservations {action}", request=request, details={"count": len(hosts)})
    return {"ok": True, "reserved": reserved_now, "attested": attested}


@app.post("/admin/edge/hostname-bindings")
def admin_edge_hostname_bindings(payload: EdgeHostnameBindingRequest, request: Request, x_edge_admin_token: Optional[str] = Header(default=None)):
    require_edge_admin_token(x_edge_admin_token, request, "edge hostname binding")
    edge_require_zone()
    kind = edge_validate_kind(getattr(payload, "subject_kind", ""))
    subject = edge_validate_subject(getattr(payload, "subject_id", ""))
    action = str(getattr(payload, "action", "") or "bind").strip().lower()
    if action not in {"bind", "unbind"}:
        raise HTTPException(status_code=400, detail="action must be bind or unbind")
    raw = list(getattr(payload, "hostnames", None) or [])
    if not raw or len(raw) > EDGE_MAX_HOSTNAMES:
        raise HTTPException(status_code=400, detail="Between 1 and 16 hostnames are required")
    remove_exceptions = bool(getattr(payload, "remove_exceptions", False))
    with edge_zone_lease() as lease:
        edge_lease_fence(lease)
        # Phase 1: validate everything, change nothing.
        to_remove = []
        with edge_db() as conn:
            edge_require_inventory(conn)
            hosts = [edge_normalize_candidate(conn, item) for item in raw]
            for host in hosts:
                row = conn.execute(
                    "SELECT subject_kind, subject_id FROM edge_hostname_bindings WHERE hostname = ?", (host,)
                ).fetchone()
                owner = (row["subject_kind"], row["subject_id"]) if row else None
                pins = edge_exceptions_naming(conn, host)
                if action == "bind":
                    if owner not in (None, (kind, subject)):
                        raise HTTPException(status_code=409, detail="Hostname is already assigned to another subject")
                    implicit = edge_implicit_default_owners(conn, host)
                    if owner is None and implicit and (kind, subject) not in implicit:
                        raise HTTPException(status_code=409, detail="Hostname is another subject's default name")
                    if owner is None and pins:
                        raise HTTPException(status_code=409, detail="Plaintext exceptions still name this hostname; it cannot be assigned")
                elif owner == (kind, subject) and pins:
                    if any(pin["state"] not in {"armed", "committed"} for pin in pins):
                        raise HTTPException(status_code=409, detail="An unsettled exception transaction names this hostname; reconcile it first")
                    if not remove_exceptions:
                        raise HTTPException(
                            status_code=409,
                            detail="Plaintext exceptions still name this hostname; unbind with remove_exceptions to remove them first",
                        )
                    to_remove.extend(pins)
        # Phase 2: remove the pinned exceptions from Cloudflare first, under the
        # same lease, so an unassigned hostname never keeps a live exception.
        if to_remove:
            edge_remove_exceptions_locked(EdgeGuard(lease), to_remove)
        # Phase 3: apply the assignment change.
        with edge_db() as conn:
            for host in hosts:
                if edge_exceptions_naming(conn, host) and action == "unbind":
                    raise HTTPException(status_code=409, detail="Plaintext exceptions still name this hostname")
                row = conn.execute(
                    "SELECT subject_kind, subject_id FROM edge_hostname_bindings WHERE hostname = ?", (host,)
                ).fetchone()
                owner = (row["subject_kind"], row["subject_id"]) if row else None
                if action == "bind":
                    conn.execute(
                        "INSERT OR IGNORE INTO edge_hostname_bindings (hostname, subject_kind, subject_id, created_at) VALUES (?, ?, ?, ?)",
                        (host, kind, subject, utcnow().isoformat()),
                    )
                elif owner == (kind, subject):
                    conn.execute("DELETE FROM edge_hostname_bindings WHERE hostname = ?", (host,))
            allowed = edge_allowed_hostnames(conn, kind, subject)
    security_alert(4, f"edge hostnames {action}", request=request, details={"kind": kind, "subject": subject, "count": len(hosts)})
    return {"ok": True, "subject_kind": kind, "subject_id": subject, "hostnames": allowed}

# --- Full edge broker: DNS, Origin CA, plaintext exceptions (L41, Round CF) --
#
# PLAINTEXT EXCEPTIONS ARE EXACT PAIRS. The zone-wide dynamic redirect keeps
# HTTP-to-HTTPS for everything except exact (hostname, path) pairs, each owned
# by the subject that requested it. The rule is rendered as a disjunction of
# pairs, never as independent host and path sets, so node B asking for
# (B, /b) can never open (A, /b).
#
# ZONE STATE IS TRANSACTIONAL. Every change runs under one lease that is
# re-validated and extended (fenced) immediately before each Cloudflare call.
# Before any mutation the broker verifies that the live managed rule and
# Always Use HTTPS are exactly what its own records predict; any difference is
# a 409 with no mutation. Always Use HTTPS goes back to its recorded baseline
# only when no retained exception still needs it off.

EDGE_ORIGIN_CA_VALIDITY_DAYS = {7, 30, 90, 365, 730, 1095, 5475}
EDGE_ORIGIN_CA_REQUEST_TYPES = {"origin-rsa", "origin-ecc"}
EDGE_REDIRECT_PHASE = "http_request_dynamic_redirect"
EDGE_REDIRECT_RULE_REF = "winsvpn_preserve_plaintext_websocket_paths"
EDGE_REDIRECT_TARGET_EXPRESSION = 'concat("https://", http.host, http.request.uri.path)'
EDGE_REDIRECT_DESCRIPTION = "Redirect HTTP to HTTPS except exact Win s VPN plaintext WebSocket (host, path) pairs"
EDGE_MAX_EXPRESSION_LENGTH = 4000
EDGE_PATH_RE = re.compile(r"^/[A-Za-z0-9._~!$&()*+,;=:@%/-]{1,127}$")
EDGE_TXN_ID_RE = re.compile(r"^[0-9a-f]{32}$")
EDGE_CSR_RE = re.compile(
    r"^-----BEGIN (?:NEW )?CERTIFICATE REQUEST-----\n[A-Za-z0-9+/=\n]{64,12000}\n-----END (?:NEW )?CERTIFICATE REQUEST-----\n$"
)


class EdgeDnsRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    hostnames: list[str] = Field(default_factory=list)
    ipv4: str = ""


class EdgeOriginCertificateRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    csr: str
    hostnames: list[str] = Field(default_factory=list)
    requested_validity: int = 730
    request_type: str = "origin-rsa"


class EdgePlaintextExemptionRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    path: str
    hostnames: list[str] = Field(default_factory=list)


class EdgePlaintextAdoptRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True, extra="forbid")
    pairs: list[dict] = Field(default_factory=list)
    expected_expression: str = ""
    baseline_always_use_https: str = ""


def edge_create_extra_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_origin_certificates (
            certificate_id TEXT PRIMARY KEY,
            subject_kind TEXT NOT NULL,
            subject_id TEXT NOT NULL,
            hostnames_json TEXT NOT NULL,
            expires_on TEXT NOT NULL DEFAULT '',
            issued_at TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_redirect_transactions (
            transaction_id TEXT PRIMARY KEY,
            subject_kind TEXT NOT NULL,
            subject_id TEXT NOT NULL,
            state TEXT NOT NULL,
            created_at TEXT NOT NULL,
            closed_at TEXT
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS edge_plaintext_exceptions (
            hostname TEXT NOT NULL,
            path TEXT NOT NULL,
            subject_kind TEXT NOT NULL,
            subject_id TEXT NOT NULL,
            transaction_id TEXT NOT NULL,
            state TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (hostname, path, transaction_id)
        )
    """)


def edge_public_ipv4(value: Any) -> str:
    try:
        address = ipaddress.IPv4Address(str(value or "").strip())
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="ipv4 must be an IPv4 address") from exc
    if not address.is_global or address.is_multicast:
        raise HTTPException(status_code=400, detail="ipv4 must be a public unicast address")
    return str(address)


def edge_upsert_proxied_a(guard: EdgeGuard, zone_id: str, hostname: str, ipv4: str) -> str:
    query = urllib.parse.urlencode({"name": hostname, "per_page": 100})
    listing = edge_cf_guarded(guard, "GET", f"zones/{zone_id}/dns_records?{query}")
    records = [
        item for item in listing.get("result") or []
        if isinstance(item, dict) and edge_canonical_hostname(item.get("name")) == hostname
    ]
    a_records = [item for item in records if str(item.get("type") or "").upper() == "A"]
    blocking = [item for item in records if str(item.get("type") or "").upper() not in {"A", "TXT"}]
    if blocking:
        raise HTTPException(status_code=409, detail="Hostname already holds a non-A record; operator review required")
    if len(a_records) > 1:
        raise HTTPException(status_code=409, detail="Hostname holds several A records; operator review required")
    # Always proxied, always automatic TTL: a node can never publish a DNS-only
    # record that advertises an origin address in the clear.
    payload = {"type": "A", "name": hostname, "content": ipv4, "ttl": 1, "proxied": True}
    if a_records:
        current = a_records[0]
        record_id = str(current.get("id") or "")
        if not EDGE_CLOUDFLARE_ID_RE.fullmatch(record_id):
            raise HTTPException(status_code=502, detail="Cloudflare returned an invalid DNS record ID")
        if (
            str(current.get("content") or "") == ipv4
            and current.get("proxied") is True
            and int(current.get("ttl") or 1) == 1
        ):
            return "unchanged"
        edge_cf_guarded(guard, "PUT", f"zones/{zone_id}/dns_records/{record_id}", payload)
        return "updated"
    edge_cf_guarded(guard, "POST", f"zones/{zone_id}/dns_records", payload)
    return "created"


def edge_dns_upsert(kind: str, subject: str, payload: Any, request: Optional[Request] = None) -> dict:
    zone_id = edge_require_zone()
    ipv4 = edge_public_ipv4(getattr(payload, "ipv4", ""))
    with edge_db() as conn:
        edge_require_inventory(conn)
        hosts = edge_require_hostnames(conn, kind, subject, getattr(payload, "hostnames", None), request)
    with edge_zone_lease() as lease:
        guard = EdgeGuard(lease, kind, subject, hosts)
        results = {host: edge_upsert_proxied_a(guard, zone_id, host, ipv4) for host in hosts}
    security_alert(4, "edge DNS upserted", request=request, details={"kind": kind, "subject": subject, "count": len(hosts)})
    return {"ok": True, "records": results}


def edge_issue_origin_certificate(kind: str, subject: str, payload: Any, request: Optional[Request] = None) -> dict:
    edge_require_zone()
    with edge_db() as conn:
        edge_require_inventory(conn)
        hosts = edge_require_hostnames(conn, kind, subject, getattr(payload, "hostnames", None), request)
    csr = str(getattr(payload, "csr", "") or "").replace("\r\n", "\n").strip() + "\n"
    if not EDGE_CSR_RE.fullmatch(csr):
        raise HTTPException(status_code=400, detail="csr must be one PEM certificate request")
    try:
        validity = int(getattr(payload, "requested_validity", 0) or 0)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="requested_validity is invalid") from exc
    if validity not in EDGE_ORIGIN_CA_VALIDITY_DAYS:
        raise HTTPException(status_code=400, detail="requested_validity must be one of 7,30,90,365,730,1095,5475")
    request_type = str(getattr(payload, "request_type", "") or "origin-rsa").strip().lower()
    if request_type not in EDGE_ORIGIN_CA_REQUEST_TYPES:
        raise HTTPException(status_code=400, detail="request_type must be origin-rsa or origin-ecc")
    # The certificate is bound to the hub-validated `hostnames`; the CSR
    # contributes only the public key.
    with edge_zone_lease() as lease:
        issued = edge_cf_guarded(EdgeGuard(lease, kind, subject, hosts), "POST", "certificates", {
            "csr": csr, "hostnames": hosts, "request_type": request_type, "requested_validity": validity,
        })
    result = issued.get("result") or {}
    certificate = str(result.get("certificate") or "")
    certificate_id = str(result.get("id") or "")
    if "-----BEGIN CERTIFICATE-----" not in certificate:
        raise HTTPException(status_code=502, detail="Cloudflare returned no Origin CA certificate")
    if EDGE_CLOUDFLARE_ID_RE.fullmatch(certificate_id):
        with edge_db() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO edge_origin_certificates "
                "(certificate_id, subject_kind, subject_id, hostnames_json, expires_on, issued_at) VALUES (?, ?, ?, ?, ?, ?)",
                (certificate_id, kind, subject, json.dumps(hosts), str(result.get("expires_on") or "")[:64], utcnow().isoformat()),
            )
    security_alert(4, "edge origin certificate issued", request=request, details={"kind": kind, "subject": subject, "count": len(hosts)})
    return {"ok": True, "certificate": certificate, "certificate_id": certificate_id, "hostnames": hosts}


def edge_redirect_rule(expression: str) -> dict:
    return {
        "ref": EDGE_REDIRECT_RULE_REF,
        "expression": expression,
        "description": EDGE_REDIRECT_DESCRIPTION,
        "action": "redirect",
        "action_parameters": {
            "from_value": {
                "target_url": {"expression": EDGE_REDIRECT_TARGET_EXPRESSION},
                "status_code": 301,
                "preserve_query_string": True,
            },
        },
        "enabled": True,
    }


def edge_render_pairs(pairs: Any) -> Optional[str]:
    """Render exact (hostname, path) pairs. None means no managed rule."""
    unique = sorted({(host, path) for host, path in pairs})
    if not unique:
        return None
    clauses = " or ".join(f'(http.host eq "{host}" and http.request.uri.path eq "{path}")' for host, path in unique)
    # `ssl` is the Rules field for client-to-edge encryption; the scheme field
    # is not available in the Single Redirect phase.
    expression = f"(not ssl and not ({clauses}))"
    edge_expression_usage_alert(len(expression), len(unique))
    if len(expression) > EDGE_MAX_EXPRESSION_LENGTH:
        raise HTTPException(status_code=409, detail="Too many plaintext exceptions for one redirect expression")
    return expression


# SYNC-21 guard (2026-09-29). Every node draws its own random XRAY_PATH, so
# every host and alias is its own pair, and one ~106-character clause each
# fits about 37 pairs under EDGE_MAX_EXPRESSION_LENGTH (Cloudflare's own
# ceiling is 4,096 characters per rule expression). Past it the next node's
# edge request is a 409. This alerts before that; it changes no rule. The
# rule shape itself is an owner design item (OI-SYNC_V3-DESIGN-2).
EDGE_EXPRESSION_ALERT_PCT = 80


def edge_expression_usage_alert(length: int, pairs: int) -> None:
    used_pct = 100 * int(length) // EDGE_MAX_EXPRESSION_LENGTH
    if used_pct < EDGE_EXPRESSION_ALERT_PCT:
        return
    bucket = 100 if used_pct >= 100 else (90 if used_pct >= 90 else EDGE_EXPRESSION_ALERT_PCT)
    security_alert(
        2 if used_pct >= 100 else 3,
        "edge plaintext exception rule nearing the expression cap",
        details={"used_pct_at_least": bucket, "limit": EDGE_MAX_EXPRESSION_LENGTH},
    )
    logger.warning(
        "edge plaintext exception rule is %d%% of its %d-character cap (%d pairs)",
        used_pct, EDGE_MAX_EXPRESSION_LENGTH, pairs,
    )


def edge_redirect_entrypoint(guard: EdgeGuard, zone_id: str) -> Optional[dict]:
    status, decoded = edge_cf_request_guarded(guard, "GET", f"zones/{zone_id}/rulesets/phases/{EDGE_REDIRECT_PHASE}/entrypoint")
    if decoded.get("success") is True:
        result = decoded.get("result")
        return result if isinstance(result, dict) else {}
    if status == 404:
        return None
    logger.error("Edge broker could not read the redirect entrypoint: status=%s", status)
    raise HTTPException(status_code=502, detail="Cloudflare rejected the redirect entrypoint read")


def edge_managed_rules(entry: Optional[dict]) -> list:
    return [
        rule for rule in (entry or {}).get("rules") or []
        if isinstance(rule, dict) and rule.get("ref") == EDGE_REDIRECT_RULE_REF
    ]


def edge_always_use_https(guard: EdgeGuard, zone_id: str) -> str:
    value = str((edge_cf_guarded(guard, "GET", f"zones/{zone_id}/settings/always_use_https").get("result") or {}).get("value") or "")
    if value not in {"on", "off"}:
        raise HTTPException(status_code=502, detail="Cloudflare returned an unexpected Always Use HTTPS value")
    return value


def edge_rule_matches(rule: Optional[dict], expression: Optional[str]) -> bool:
    if expression is None:
        return rule is None
    if rule is None:
        return False
    from_value = ((rule.get("action_parameters") or {}).get("from_value") or {})
    return (
        rule.get("expression") == expression
        and rule.get("action") == "redirect"
        and rule.get("enabled") is True
        and from_value.get("status_code") == 301
        and (from_value.get("target_url") or {}).get("expression") == EDGE_REDIRECT_TARGET_EXPRESSION
        and from_value.get("preserve_query_string") is True
    )


def edge_observe(guard: EdgeGuard, zone_id: str) -> tuple:
    entry = edge_redirect_entrypoint(guard, zone_id)
    managed = edge_managed_rules(entry)
    if len(managed) > 1:
        raise HTTPException(status_code=409, detail="Several managed redirect rules exist; operator review required")
    return entry, (managed[0] if managed else None), edge_always_use_https(guard, zone_id)


def edge_write_rule(guard: EdgeGuard, zone_id: str, entry: Optional[dict], current: Optional[dict],
                    expression: Optional[str]) -> None:
    if edge_rule_matches(current, expression):
        return
    ruleset_id = str((entry or {}).get("id") or "")
    if expression is None:
        rule_id = str((current or {}).get("id") or "")
        if not EDGE_CLOUDFLARE_ID_RE.fullmatch(ruleset_id) or not EDGE_CLOUDFLARE_ID_RE.fullmatch(rule_id):
            raise HTTPException(status_code=502, detail="Cloudflare returned invalid redirect rule IDs")
        edge_cf_guarded(guard, "DELETE", f"zones/{zone_id}/rulesets/{ruleset_id}/rules/{rule_id}")
    elif not ruleset_id:
        edge_cf_guarded(guard, "POST", f"zones/{zone_id}/rulesets", {
            "name": "Win s VPN selective HTTPS redirects", "kind": "zone",
            "phase": EDGE_REDIRECT_PHASE, "rules": [edge_redirect_rule(expression)],
        })
    elif current is not None:
        rule_id = str(current.get("id") or "")
        if not EDGE_CLOUDFLARE_ID_RE.fullmatch(ruleset_id) or not EDGE_CLOUDFLARE_ID_RE.fullmatch(rule_id):
            raise HTTPException(status_code=502, detail="Cloudflare returned invalid redirect rule IDs")
        edge_cf_guarded(guard, "PATCH", f"zones/{zone_id}/rulesets/{ruleset_id}/rules/{rule_id}", edge_redirect_rule(expression))
    else:
        if not EDGE_CLOUDFLARE_ID_RE.fullmatch(ruleset_id):
            raise HTTPException(status_code=502, detail="Cloudflare returned an invalid ruleset ID")
        edge_cf_guarded(guard, "POST", f"zones/{zone_id}/rulesets/{ruleset_id}/rules", edge_redirect_rule(expression))
    after = edge_managed_rules(edge_redirect_entrypoint(guard, zone_id))
    if len(after) > 1 or not edge_rule_matches(after[0] if after else None, expression):
        raise HTTPException(status_code=502, detail="Managed redirect did not read back as written")


def edge_set_always_use_https(guard: EdgeGuard, zone_id: str, value: str) -> None:
    edge_cf_guarded(guard, "PATCH", f"zones/{zone_id}/settings/always_use_https", {"value": value})
    if edge_always_use_https(guard, zone_id) != value:
        raise HTTPException(status_code=502, detail="Always Use HTTPS did not read back as written")


def edge_live_pairs(conn: sqlite3.Connection) -> list:
    return [
        dict(row) for row in conn.execute(
            "SELECT hostname, path, subject_kind, subject_id, transaction_id, state FROM edge_plaintext_exceptions "
            "WHERE state IN ('armed', 'committed') ORDER BY hostname, path"
        ).fetchall()
    ]


def edge_verify_recorded_state(current: Optional[dict], auh: str, live: list) -> Optional[str]:
    """The broker's records predict the zone exactly: the managed rule is the
    rendering of the retained pairs, and Always Use HTTPS is off while any pair
    is retained. Returns the predicted expression; raises 409 otherwise."""
    expected = edge_render_pairs((row["hostname"], row["path"]) for row in live)
    if not edge_rule_matches(current, expected):
        raise HTTPException(
            status_code=409,
            detail="The managed redirect does not match the broker's recorded exceptions; nothing was changed "
                   "(a legacy rule must first be adopted with POST /admin/edge/plaintext-exceptions/adopt)",
        )
    if live and auh != "off":
        raise HTTPException(status_code=409, detail="Always Use HTTPS is on while exceptions are retained; nothing was changed")
    return expected


def edge_close_transaction(transaction_id: str, state: str, pair_state: Optional[str] = None) -> None:
    with edge_db() as conn:
        conn.execute(
            "UPDATE edge_redirect_transactions SET state = ?, closed_at = ? WHERE transaction_id = ?",
            (state, utcnow().isoformat() if state not in {"armed", "pending"} else None, transaction_id),
        )
        if pair_state:
            conn.execute(
                "UPDATE edge_plaintext_exceptions SET state = ? WHERE transaction_id = ?", (pair_state, transaction_id)
            )


def edge_plaintext_exemption_begin(kind: str, subject: str, payload: Any, request: Optional[Request] = None) -> dict:
    zone_id = edge_require_zone()
    path = str(getattr(payload, "path", "") or "").strip()
    if not EDGE_PATH_RE.fullmatch(path):
        raise HTTPException(status_code=400, detail="path must be an absolute URL path of safe characters")
    with edge_db() as conn:
        edge_require_inventory(conn)
        requested = getattr(payload, "hostnames", None) or edge_allowed_hostnames(conn, kind, subject)
        hosts = edge_require_hostnames(conn, kind, subject, requested, request)
    wanted = {(host, path) for host in hosts}
    transaction_id = secrets.token_hex(16)
    with edge_zone_lease() as lease:
        guard = EdgeGuard(lease, kind, subject, hosts)
        guard.check()
        with edge_db() as conn:
            live = edge_live_pairs(conn)
            for row in live:
                if (row["hostname"], row["path"]) in wanted and (row["subject_kind"], row["subject_id"]) != (kind, subject):
                    raise HTTPException(status_code=409, detail="That exception pair is recorded for another subject")
        entry, current, auh = edge_observe(guard, zone_id)
        before_expression = edge_verify_recorded_state(current, auh, live)
        live_keys = {(row["hostname"], row["path"]) for row in live}
        new_pairs = sorted(wanted - live_keys)
        # A repeat request for pairs this subject already holds is idempotent:
        # no transaction is created. The subject's open (armed) transactions are
        # read from the transaction table FIRST, before either the no-op reply
        # or a new transaction, so one whose pairs an unbind removed is seen
        # too. While any is open, only a request whose pair set EXACTLY equals
        # that one transaction's full, still-armed pair set gets its ID back to
        # settle; a subset, a superset, any other overlap, a disjoint request
        # or an all-committed request is refused without an ID, so a retry can
        # never commit pairs it did not ask for and no open transaction is
        # passed over. Only with no open transaction may every requested pair
        # already committed return the idempotent success.
        with edge_db() as conn:
            subject_open = [
                row["transaction_id"] for row in conn.execute(
                    "SELECT transaction_id FROM edge_redirect_transactions "
                    "WHERE subject_kind = ? AND subject_id = ? AND state = 'armed' ORDER BY transaction_id",
                    (kind, subject),
                ).fetchall()
            ]
            txn_rows = conn.execute(
                "SELECT hostname, path, state FROM edge_plaintext_exceptions WHERE transaction_id = ?",
                (subject_open[0],),
            ).fetchall() if len(subject_open) == 1 else []
        if subject_open:
            txn_pairs = {(pair["hostname"], pair["path"]) for pair in txn_rows}
            if (len(subject_open) == 1 and not new_pairs and txn_rows
                    and all(pair["state"] == "armed" for pair in txn_rows)
                    and txn_pairs == wanted):
                return {"ok": True, "transaction_id": subject_open[0], "state": "armed", "added": 0, "hostnames": hosts, "path": path}
            raise HTTPException(
                status_code=409,
                detail="An earlier plaintext exception transaction for this subject is still open and does not match this request exactly; commit or roll it back first",
            )
        if not new_pairs:
            return {"ok": True, "transaction_id": None, "state": "committed", "added": 0, "hostnames": hosts, "path": path}
        with edge_db() as conn:
            conn.execute(
                "INSERT INTO edge_redirect_transactions (transaction_id, subject_kind, subject_id, state, created_at) "
                "VALUES (?, ?, ?, 'pending', ?)",
                (transaction_id, kind, subject, utcnow().isoformat()),
            )
            for host, pair_path in new_pairs:
                conn.execute(
                    "INSERT INTO edge_plaintext_exceptions "
                    "(hostname, path, subject_kind, subject_id, transaction_id, state, created_at) "
                    "VALUES (?, ?, ?, ?, ?, 'pending', ?)",
                    (host, pair_path, kind, subject, transaction_id, utcnow().isoformat()),
                )
        target_expression = edge_render_pairs(live_keys | set(new_pairs))
        try:
            edge_write_rule(guard, zone_id, entry, current, target_expression)
            if auh == "on":
                # Only after the exact exceptions are installed and read back.
                edge_set_always_use_https(guard, zone_id, "off")
            with edge_db() as conn:
                if not live:
                    edge_state_set(conn, "baseline_always_use_https", auh)
            edge_close_transaction(transaction_id, "armed", "armed")
        except HTTPException:
            try:
                entry_now, current_now, auh_now = edge_observe(guard, zone_id)
                edge_write_rule(guard, zone_id, entry_now, current_now, before_expression)
                if auh_now != auh:
                    edge_set_always_use_https(guard, zone_id, auh)
                edge_close_transaction(transaction_id, "rolled_back", "rolled_back")
            except HTTPException:
                edge_close_transaction(transaction_id, "rollback_failed", "rollback_failed")
                logger.error("Edge redirect transaction %s could not be undone automatically", transaction_id)
            raise
    security_alert(4, "edge plaintext exception armed", request=request, details={"kind": kind, "subject": subject, "count": len(new_pairs)})
    return {"ok": True, "transaction_id": transaction_id, "added": len(new_pairs), "hostnames": hosts, "path": path}


def edge_load_transaction(conn: sqlite3.Connection, kind: str, subject: str, transaction_id: str) -> Any:
    if not EDGE_TXN_ID_RE.fullmatch(str(transaction_id or "")):
        raise HTTPException(status_code=400, detail="transaction_id is invalid")
    row = conn.execute("SELECT * FROM edge_redirect_transactions WHERE transaction_id = ?", (transaction_id,)).fetchone()
    # Another subject's transaction is indistinguishable from a missing one.
    if row is None or (row["subject_kind"], row["subject_id"]) != (kind, subject):
        raise HTTPException(status_code=404, detail="Unknown edge transaction")
    return row


def edge_plaintext_exemption_commit(kind: str, subject: str, transaction_id: str) -> dict:
    with edge_db() as conn:
        row = edge_load_transaction(conn, kind, subject, transaction_id)
        if row["state"] == "committed":
            return {"ok": True, "state": "committed"}
        if row["state"] != "armed":
            raise HTTPException(status_code=409, detail=f"Edge transaction is {row['state']}, not armed")
    # Commit rechecks, under the zone lease, the transaction's ORIGINAL opened
    # hostname set (every pair it recorded, whatever its state now), not the
    # pairs that are still armed. A pair removed by an unbind, or any hostname
    # no longer assigned to the subject, means the transaction lost part of
    # what it opened: it is refused (409) and left armed for rollback.
    with edge_zone_lease() as lease:
        edge_lease_fence(lease)
        with edge_db() as conn:
            row = edge_load_transaction(conn, kind, subject, transaction_id)
            if row["state"] != "armed":
                raise HTTPException(status_code=409, detail=f"Edge transaction is {row['state']}, not armed")
            opened = conn.execute(
                "SELECT hostname, state FROM edge_plaintext_exceptions WHERE transaction_id = ?",
                (transaction_id,),
            ).fetchall()
            if not opened:
                # Only older code created a transaction with no pair (a repeat
                # request). It opened nothing, so nothing can have been lost:
                # settle it as committed so a recorded handle reconciles.
                conn.execute(
                    "UPDATE edge_redirect_transactions SET state = 'committed', closed_at = ? WHERE transaction_id = ?",
                    (utcnow().isoformat(), transaction_id),
                )
                return {"ok": True, "state": "committed", "settled_empty": True}
            if any(pair["state"] != "armed" for pair in opened):
                raise HTTPException(
                    status_code=409,
                    detail="An exception this transaction opened was removed (for example by an unbind); roll it back instead",
                )
            allowed = set(edge_allowed_hostnames(conn, kind, subject))
            if any(pair["hostname"] not in allowed for pair in opened):
                raise HTTPException(
                    status_code=409,
                    detail="A hostname in this transaction is no longer assigned to this subject; roll it back instead",
                )
            now_iso = utcnow().isoformat()
            conn.execute(
                "UPDATE edge_redirect_transactions SET state = 'committed', closed_at = ? WHERE transaction_id = ?",
                (now_iso, transaction_id),
            )
            conn.execute(
                "UPDATE edge_plaintext_exceptions SET state = 'committed' WHERE transaction_id = ? AND state = 'armed'",
                (transaction_id,),
            )
    return {"ok": True, "state": "committed"}


def edge_remove_exceptions_locked(guard: EdgeGuard, pins: list) -> None:
    """Remove the given exception pairs from the live rule. The caller holds
    the zone lease. The recorded state is verified first (409, no mutation, on
    any difference); Always Use HTTPS returns to its baseline only when no
    other exception is retained."""
    zone_id = edge_require_zone()
    guard.check()
    remove = {(pin["hostname"], pin["path"], pin["transaction_id"]) for pin in pins}
    with edge_db() as conn:
        live = edge_live_pairs(conn)
        baseline = edge_state_get(conn, "baseline_always_use_https")
    entry, current, auh = edge_observe(guard, zone_id)
    edge_verify_recorded_state(current, auh, live)
    retained = [pair for pair in live if (pair["hostname"], pair["path"], pair["transaction_id"]) not in remove]
    target_expression = edge_render_pairs((pair["hostname"], pair["path"]) for pair in retained)
    target_auh = "off" if retained else (baseline if baseline in {"on", "off"} else auh)
    edge_write_rule(guard, zone_id, entry, current, target_expression)
    if target_auh != auh:
        edge_set_always_use_https(guard, zone_id, target_auh)
    with edge_db() as conn:
        for hostname, path, transaction_id in remove:
            conn.execute(
                "UPDATE edge_plaintext_exceptions SET state = 'removed_on_unbind' "
                "WHERE hostname = ? AND path = ? AND transaction_id = ?",
                (hostname, path, transaction_id),
            )
        if not retained:
            edge_state_delete(conn, "baseline_always_use_https")


def edge_plaintext_exemption_rollback(kind: str, subject: str, transaction_id: str, request: Optional[Request] = None) -> dict:
    zone_id = edge_require_zone()
    with edge_db() as conn:
        row = edge_load_transaction(conn, kind, subject, transaction_id)
    if row["state"] != "armed":
        raise HTTPException(status_code=409, detail=f"Edge transaction is {row['state']}; only an armed transaction rolls back")
    with edge_zone_lease() as lease:
        # Removing this subject's own exceptions stays allowed even if its
        # names were unassigned since; only the lease and inventory are checked.
        guard = EdgeGuard(lease)
        guard.check()
        with edge_db() as conn:
            live = edge_live_pairs(conn)
            baseline = edge_state_get(conn, "baseline_always_use_https")
        entry, current, auh = edge_observe(guard, zone_id)
        # Verify the complete expected post-transaction state before any
        # mutation: rule and setting exactly as the records predict.
        edge_verify_recorded_state(current, auh, live)
        retained = [pair for pair in live if pair["transaction_id"] != transaction_id]
        target_expression = edge_render_pairs((pair["hostname"], pair["path"]) for pair in retained)
        # The setting returns to its baseline only when no retained exception
        # still needs it off.
        target_auh = "off" if retained else (baseline if baseline in {"on", "off"} else auh)
        try:
            edge_write_rule(guard, zone_id, entry, current, target_expression)
            if target_auh != auh:
                edge_set_always_use_https(guard, zone_id, target_auh)
        except HTTPException:
            edge_close_transaction(transaction_id, "rollback_failed")
            raise
        with edge_db() as conn:
            if not retained:
                edge_state_delete(conn, "baseline_always_use_https")
        edge_close_transaction(transaction_id, "rolled_back", "rolled_back")
    security_alert(4, "edge plaintext exception rolled back", request=request, details={"kind": kind, "subject": subject})
    return {"ok": True, "state": "rolled_back"}


