@app.post("/admin/edge/plaintext-exceptions/adopt")
def admin_edge_plaintext_adopt(payload: EdgePlaintextAdoptRequest, request: Request, x_edge_admin_token: Optional[str] = Header(default=None)):
    """One-time operator conversion of a legacy host-set/path-set rule into
    exact owned pairs. The operator names every pair to keep, the exact
    expression expected live, and the Always Use HTTPS baseline to restore when
    the last exception is gone. Anything unexpected is a 409 with no change."""
    require_edge_admin_token(x_edge_admin_token, request, "edge plaintext adopt")
    zone_id = edge_require_zone()
    baseline = str(getattr(payload, "baseline_always_use_https", "") or "").strip().lower()
    if baseline not in {"on", "off"}:
        raise HTTPException(status_code=400, detail="baseline_always_use_https must be on or off")
    expected_expression = str(getattr(payload, "expected_expression", "") or "")
    pairs = []
    with edge_db() as conn:
        edge_require_inventory(conn)
        for item in list(getattr(payload, "pairs", None) or [])[:64]:
            kind = edge_validate_kind((item or {}).get("subject_kind"))
            subject = edge_validate_subject((item or {}).get("subject_id"))
            pair_path = str((item or {}).get("path") or "").strip()
            if not EDGE_PATH_RE.fullmatch(pair_path):
                raise HTTPException(status_code=400, detail="Each adopted pair needs a safe absolute path")
            host = edge_require_hostnames(conn, kind, subject, [(item or {}).get("hostname")], request)[0]
            pairs.append((host, pair_path, kind, subject))
        if len({(host, pair_path) for host, pair_path, _k, _s in pairs}) != len(pairs):
            raise HTTPException(status_code=400, detail="Adopted pairs must be unique")
    transaction_id = secrets.token_hex(16)
    with edge_zone_lease() as lease:
        guard = EdgeGuard(lease)
        guard.check()
        with edge_db() as conn:
            if edge_live_pairs(conn):
                raise HTTPException(status_code=409, detail="Exceptions are already recorded; adoption is a one-time conversion")
        entry, current, auh = edge_observe(guard, zone_id)
        live_expression = str((current or {}).get("expression") or "")
        if live_expression != expected_expression:
            raise HTTPException(status_code=409, detail="The live managed redirect is not the expected legacy rule; nothing was changed")
        target = edge_render_pairs((host, pair_path) for host, pair_path, _k, _s in pairs)
        edge_write_rule(guard, zone_id, entry, current, target)
        if pairs and auh == "on":
            edge_set_always_use_https(guard, zone_id, "off")
        elif not pairs and auh != baseline:
            edge_set_always_use_https(guard, zone_id, baseline)
        with edge_db() as conn:
            conn.execute(
                "INSERT INTO edge_redirect_transactions (transaction_id, subject_kind, subject_id, state, created_at, closed_at) "
                "VALUES (?, 'operator', 'adopt', 'committed', ?, ?)",
                (transaction_id, utcnow().isoformat(), utcnow().isoformat()),
            )
            for host, pair_path, kind, subject in pairs:
                conn.execute(
                    "INSERT INTO edge_plaintext_exceptions "
                    "(hostname, path, subject_kind, subject_id, transaction_id, state, created_at) "
                    "VALUES (?, ?, ?, ?, ?, 'committed', ?)",
                    (host, pair_path, kind, subject, transaction_id, utcnow().isoformat()),
                )
            if pairs:
                edge_state_set(conn, "baseline_always_use_https", baseline)
    security_alert(4, "edge plaintext exceptions adopted", request=request, details={"count": len(pairs)})
    return {"ok": True, "adopted": len(pairs)}

@app.post("/admin/nodes/bootstrap-management-tunnel")
def bootstrap_node_management_tunnel(
    payload: NodeManagementTunnelBootstrap,
    request: Request,
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin_token(x_admin_token, request=request, action="bootstrap node management tunnel")
    try:
        host_keys = normalized_management_ssh_host_keys(payload.ssh_host_keys)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    result = ensure_node_management_tunnel(payload.node_slug)
    install_management_known_hosts(str(result["ssh_host"]), host_keys)
    security_alert(4, "node management tunnel bootstrapped", request=request, details={"slug": payload.node_slug})
    return {"ok": True, "management_mode": "cloudflare_tunnel", **result}

@app.post("/admin/core/bootstrap-management-tunnel")
def bootstrap_core_management_tunnel(
    payload: CoreManagementTunnelBootstrap,
    request: Request,
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin_token(x_admin_token, request=request, action="bootstrap Core management tunnel")
    core_id = str(payload.core_id or "").strip().lower()
    ssh_user = str(payload.ssh_user or "ubuntu").strip().lower()
    if not re.fullmatch(r"[a-z_][a-z0-9_-]{0,31}", ssh_user):
        raise HTTPException(status_code=400, detail="Core ssh_user is invalid")
    try:
        host_keys = normalized_management_ssh_host_keys(payload.ssh_host_keys)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    result = ensure_core_management_tunnel(core_id)
    install_management_known_hosts(str(result["ssh_host"]), host_keys)
    with get_db() as conn:
        ensure_schema(conn)
        # A row created here has never registered. Like the token bootstrap,
        # create it 'maintenance' rather than inherit the schema's 'online'
        # default; the first register_core sets the real status, and an
        # existing row keeps its status.
        conn.execute(
            """
            INSERT INTO core_servers (
                core_id, management_host, management_user, management_status,
                management_checked_at, management_error, status
            ) VALUES (?, ?, ?, 'unknown', NULL, '', 'maintenance')
            ON CONFLICT(core_id) DO UPDATE SET
                management_host=excluded.management_host,
                management_user=excluded.management_user,
                management_status='unknown',
                management_checked_at=NULL,
                management_error=''
            """,
            (core_id, result["ssh_host"], ssh_user),
        )
    security_alert(4, "Core management tunnel bootstrapped", request=request, details={"core_id": core_id})
    return {"ok": True, "management_mode": "cloudflare_tunnel", **result}

@app.post("/admin/core/verify-management")
def verify_core_management_tunnel(
    payload: CoreManagementVerifyRequest,
    request: Request,
    x_core_token: str = Header(...),
):
    # H-2: routine core-scoped endpoint -- core-token-only, never the
    # fleet-wide admin token (see require_core_token). Both real callers
    # (probe_hub_core_management's redeploy reuse-check and the deployed
    # wins-core-sync timer agent's verify_management_runtime) already hold
    # their own CORE_TOKEN before either can ever reach this endpoint, so
    # there is no routine or documented manual path that needs ADMIN_TOKEN
    # here; minting a *new* tunnel stays admin-token-only and separate, at
    # POST /admin/core/bootstrap-management-tunnel.
    core_id = str(payload.core_id or "").strip().lower()
    with get_db() as conn:
        ensure_schema(conn)
        require_core_token(conn, core_id, x_core_token, request, "verify Core management tunnel")
    expected_host = core_management_hostname(core_id)
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute(
            "SELECT management_host, management_user FROM core_servers WHERE core_id = ?",
            (core_id,),
        ).fetchone()
    if not row or normalize_hostname(row["management_host"] or "") != expected_host:
        raise HTTPException(status_code=409, detail="Core management tunnel metadata is not registered")
    ssh_user = str(row["management_user"] or "ubuntu").strip().lower()
    command = "systemctl is-active --quiet wins-core-management-tunnel.service && printf wins-core-management-ok"
    error = ""
    try:
        result = run_management_ssh_bounded(
            core_ssh_command(expected_host, ssh_user, command, connect_timeout=8),
            timeout=30,
            check=False,
            capture_output=True,
            text=True,
            env=management_ssh_env(),
        )
        ok = result.returncode == 0 and result.stdout.strip() == "wins-core-management-ok"
        if not ok:
            error = (result.stderr or result.stdout or "Core management probe failed").strip()[-300:]
    except Exception as exc:
        ok = False
        error = f"{type(exc).__name__}: Core management probe failed"
    with get_db() as conn:
        ensure_schema(conn)
        mark_core_management_status(conn, core_id, "ok" if ok else "failed", error)
    if not ok:
        logger.warning("Core management probe failed for %s: %s", mask_id(core_id), error)
    return {"ok": ok, "core_id": core_id, "management_status": "ok" if ok else "failed"}

def require_served_core_id(core_id: str) -> None:
    """IA-SYNC SYNC-25: this hub serves exactly one Double VPN Core
    (DOUBLE_VPN_CORE_ID); withdraw, complete and promote refuse any other id.
    The admin grant mint refuses a Core grant for another id up front, naming
    both values, instead of letting that Core install, register and then fail
    every rerun with "Core ID is invalid.". Only the mint: bootstrap-only rows
    and management tunnels for other ids stay a handled state (L44, edge
    broker), see OI-SYNC_HUB-5."""
    if core_id != DOUBLE_VPN_CORE_ID:
        raise HTTPException(
            status_code=409,
            detail=(f"This hub serves Double VPN Core '{DOUBLE_VPN_CORE_ID}', not '{core_id}'. "
                    "Use CORE_ID="
                    f"{DOUBLE_VPN_CORE_ID} on the Core, or change DOUBLE_VPN_CORE_ID on the hub first."),
        )

@app.post("/admin/bootstrap-grant")
def mint_bootstrap_grant(payload: BootstrapGrantRequest, request: Request, x_admin_token: str = Header(...)):
    # H-2: this is the only place the fleet-wide admin token still routinely
    # authorizes anything node/core-shaped -- minting a short-lived,
    # single-use grant that the operator relays to exactly one target's
    # one-touch invocation. The target never sees the admin token itself,
    # only this grant, and exchanges it (once) for its own scoped token via
    # /api/v1/nodes/register or /api/v1/core/bootstrap.
    require_admin_token(x_admin_token, request, "mint bootstrap grant")
    role = (payload.role or "").strip().lower()
    if role not in BOOTSTRAP_GRANT_ROLES:
        raise HTTPException(status_code=400, detail="role must be 'node' or 'core'.")
    subject_id = (payload.subject_id or "").strip().lower()
    if not subject_id or not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", subject_id):
        raise HTTPException(status_code=400, detail="subject_id is invalid.")
    try:
        ttl_seconds = int(payload.ttl_seconds or 0) or BOOTSTRAP_GRANT_TTL_SECONDS
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="ttl_seconds is invalid.") from exc
    if not 60 <= ttl_seconds <= BOOTSTRAP_GRANT_MAX_TTL_SECONDS:
        raise HTTPException(status_code=400, detail="ttl_seconds must be between 60 and 3600.")
    if role == "core":
        require_served_core_id(subject_id)
    with get_db() as conn:
        ensure_schema(conn)
        token = create_bootstrap_grant(conn, role, subject_id, ttl_seconds)
    security_alert(4, "bootstrap grant minted", request=request, details={"role": role, "subject_id": subject_id})
    return {
        "ok": True,
        "bootstrap_token": token,
        "role": role,
        "subject_id": subject_id,
        "expires_in_seconds": ttl_seconds,
    }

@app.post("/api/v1/core/bootstrap")
def bootstrap_core(payload: CoreBootstrapRequest, request: Request):
    # H-2: exchanges a single-use grant (from /admin/bootstrap-grant) for a
    # permanent per-core token, returned exactly once. Every routine core
    # endpoint thereafter authenticates with this token via require_core_token;
    # the fleet-wide admin token is never involved in this exchange at all.
    core_id = (payload.core_id or DOUBLE_VPN_CORE_ID).strip() or DOUBLE_VPN_CORE_ID
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", core_id):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    with get_db() as conn:
        ensure_schema(conn)
        if not consume_bootstrap_grant(conn, payload.bootstrap_token, "core", core_id):
            security_alert(2, "invalid or expired core bootstrap grant", request=request, details={"core_id": core_id})
            raise HTTPException(status_code=401, detail="Unauthorized")
        core_token = secrets.token_urlsafe(48)
        # A bootstrap-only row has never registered: no endpoints, no keys, no
        # heartbeat. The schema default status is 'online', which made such a
        # row (e.g. aicore-core0, 2026-09-25) display as an online Core forever,
        # because mark_stale_nodes_offline only closes promoted or pending Cores.
        # Create it as 'maintenance'; the first register_core sets the real
        # status. An existing row keeps its status.
        conn.execute(
            """
            INSERT INTO core_servers (core_id, core_token_hash, status) VALUES (?, ?, 'maintenance')
            ON CONFLICT(core_id) DO UPDATE SET core_token_hash = excluded.core_token_hash
            """,
            (core_id, token_digest(core_token)),
        )
    security_alert(4, "core bootstrap token issued", request=request, details={"core_id": core_id})
    return {"ok": True, "core_token": core_token}

@app.post("/api/v1/nodes/bootstrap")
def bootstrap_node(payload: NodeBootstrapRequest, request: Request):
    # H-2: mirrors bootstrap_core. Deliberately decoupled from the full
    # register_node payload -- a fresh data plane's AmneziaWG/public key
    # material is not available yet at the point in its one-touch install
    # where ADMIN_TOKEN is in scope, so this exchange needs only the slug.
    # The placeholder nodes row this may create stays invisible to real
    # clients: select_online_node/select_free_node/current_free_node_slugs
    # all require management_status='ok', which only a real, later
    # management-tunnel verification (never this endpoint) ever sets.
    slug = (payload.slug or "").strip().lower()
    if not slug:
        raise HTTPException(status_code=400, detail="slug is required.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        if not consume_bootstrap_grant(conn, payload.bootstrap_token, "node", slug):
            security_alert(2, "invalid or expired node bootstrap grant", request=request, details={"slug": slug})
            raise HTTPException(status_code=401, detail="Unauthorized")
        retired = conn.execute(
            "SELECT retired_at FROM nodes WHERE slug = ?", (slug,)
        ).fetchone()
        if node_is_retired(retired):
            raise HTTPException(status_code=409, detail="Retired node must be restored before bootstrap")
        node_token = secrets.token_urlsafe(48)
        conn.execute(
            """
            INSERT INTO nodes (slug, node_token_hash, operator_enabled, winn3_bootstrap_authorized, node_bootstrapped_at)
            VALUES (?, ?, 0, 1, ?)
            ON CONFLICT(slug) DO UPDATE SET node_token_hash = excluded.node_token_hash,
              winn3_bootstrap_authorized=1, node_bootstrapped_at=excluded.node_bootstrapped_at
            """,
            (slug, token_digest(node_token), utcnow().isoformat()),
        )
        row = conn.execute("SELECT * FROM nodes WHERE slug=?", (slug,)).fetchone()
        previous = winn3_stored_descriptor(row, clock_tolerant=True)
        ledger = parse_winn3_admission_ledger(row["winn3_admission_json"])
        floor = winn3_admission_sequence_floor(previous, ledger)
        if floor >= 0:
            ledger["sequence_floor"] = floor
        close_data_plane_promotion(conn, slug, utcnow().isoformat(), cause="rebootstrap")
        winn3_bump_deployment_generation(conn, slug)
        # HL-F3: a re-bootstrap opens a fresh deployment epoch, so the old
        # machine's healthy-proof streak is not evidence for the new one.
        conn.execute("UPDATE nodes SET deployment_released_at=NULL, deployment_completed_at=NULL, "
                     "deployment_withdrawal_id=NULL, deployment_withdrawn_at=NULL, deployment_prior_state_json=NULL, "
                     "winn3_descriptor_json=NULL, winn3_identity_sha256=NULL, winn3_admission_json=?, protocol_version=?, "
                     "protocol_params_json=NULL, path_mtu=NULL, carrier_classes=NULL, "
                     "data_plane_green_streak=0, data_plane_green_since=NULL WHERE slug=?",
                     (winn3_canonical(ledger).decode() if ledger else None, WINN_PROTOCOL_V1, slug))
    security_alert(4, "node bootstrap token issued", request=request, details={"slug": slug})
    return {"ok": True, "node_token": node_token}

DATA_PLANE_CODE_REVISION_RE = re.compile(r"^sha256:[0-9a-f]{64}(/staged)?$")


def sanitize_data_plane_code_revision(raw: object) -> Optional[str]:
    """Constrain the node's self-reported data-plane code revision.

    WHY THIS IS ACCEPTED FROM THE NODE AT ALL, when protocol_version and
    protocol_params_json deliberately are not (see the block comment in the
    upsert below). The distinction is what the value can DO:

      * protocol_params_json is handed to clients verbatim, and
        protocol_version decides what the client believes the node speaks. Both
        are capability claims, and a node self-asserting one changes what the
        hub serves to real users on the node's own say-so.
      * data_plane_code_revision changes nothing that is served. No selection
        path reads it, it is not a node identity attribute, and it cannot
        affect which node a client is given. It is a REPORT, and the honest
        framing is that it is the node's claim about itself -- useful exactly
        because today the hub has no claim at all and cannot tell which of the
        five committed installer revisions spain-madrid is running.

    A compromised node can lie here. A compromised node can already lie about
    its endpoint and its public key, which matter far more, so this adds no
    authority it did not have. What the shape below DOES prevent is using this
    text column as an injection channel for unbounded operator-visible strings:
    only a 64-hex sha256, optionally marked "/staged", or the two fixed words.

    Returns None for "the node said nothing", which stores as NULL and is
    distinct from the stored string 'unprovable'.
    """
    text = str(raw or "").strip()
    if not text:
        return None
    if text in ("unprovable", "unknown"):
        return text
    if DATA_PLANE_CODE_REVISION_RE.match(text):
        return text
    # Anything else is a node reporting something this hub does not understand.
    # Recorded as a fixed sentinel rather than dropped, so a malformed report is
    # still visibly a report and never silently indistinguishable from silence.
    return "unprovable"


WINN3_GATEWAY_REPORT_STATES = ("active", "inactive", "failed", "absent", "unknown")
WINN3_GATEWAY_REPORT_PLAN_RE = re.compile(r"^(udp|tcp|tls)(,(udp|tcp|tls)){0,2}$")
WINN3_GATEWAY_REPORT_LISTEN_RE = re.compile(r"^[0-9A-Fa-f.:\[\]]{1,47}:[0-9]{1,5}$")
WINN3_GATEWAY_REPORT_ID_RE = re.compile(r"^[A-Za-z0-9._:-]{1,128}$")
WINN3_GATEWAY_REPORT_CIDR_RE = re.compile(r"^[0-9]{1,3}(\.[0-9]{1,3}){3}/[0-9]{1,2}$")


def sanitize_winn3_gateway_report(raw: Any) -> Optional[dict]:
    """The node's v3 gateway self-report, narrowed to known keys and shapes.

    Same standing as data_plane_code_revision: a node's claim about itself,
    accepted because it changes nothing that is served (no selection or serve
    path reads it) and lets the hub NAME a disagreement before a client meets
    it. None means "not reported". A field whose shape is wrong is kept as
    unknown ("" or None) rather than guessed.
    """
    if not isinstance(raw, dict):
        return None
    state = str(raw.get("state") or "").strip().lower()
    report: dict = {"state": state if state in WINN3_GATEWAY_REPORT_STATES else "unknown"}
    for key in ("forward", "resolver"):
        value = raw.get(key)
        report[key] = value if isinstance(value, bool) else None
    listen = str(raw.get("listen") or "").strip()
    report["listen"] = listen if WINN3_GATEWAY_REPORT_LISTEN_RE.match(listen) else ""
    gateway_id = str(raw.get("gateway_id") or "")
    report["gateway_id"] = gateway_id if WINN3_GATEWAY_REPORT_ID_RE.match(gateway_id) else ""
    inner = str(raw.get("inner_v4") or "").strip()
    report["inner_v4"] = inner if winn3_is_inner_ipv4(inner) else ""
    plan = str(raw.get("plan") or "").strip().lower()
    report["plan"] = plan if WINN3_GATEWAY_REPORT_PLAN_RE.match(plan) else ""
    cidr = str(raw.get("forward_cidr") or "").strip()
    report["forward_cidr"] = cidr if WINN3_GATEWAY_REPORT_CIDR_RE.match(cidr) else ""
    mtu = raw.get("path_mtu")
    report["path_mtu"] = (
        mtu if isinstance(mtu, int) and not isinstance(mtu, bool) and 576 <= mtu <= 65535 else None
    )
    # D5: whether the installed binary names peer-registry-tier in
    # `winn3-gateway -mode features`. The key is kept only when the node sent a
    # boolean, so a report from an older installer, a missing binary or a probe
    # that failed keeps exactly the shape it always had and publishes no tier.
    peer_tier = raw.get("peer_tier")
    if isinstance(peer_tier, bool):
        report["peer_tier"] = peer_tier
    return report


def winn3_node_reports_peer_tier(node: Any) -> bool:
    """Whether this node's stored gateway report says its binary decodes tier.

    The gateway refuses a registry with a field it does not know, so the hub
    writes the tier word only for a node whose own register run reported true
    here. False and None both keep the node on today's document.
    """
    report = parse_winn3_gateway_report(_node_field(node, "winn3_gateway_report_json"))
    return isinstance(report, dict) and report.get("peer_tier") is True


def parse_winn3_gateway_report(value: Any) -> Optional[dict]:
    """A stored report back as a dict, or None for missing or unreadable."""
    if not value:
        return None
    try:
        decoded = json.loads(value)
    except Exception:
        return None
    return sanitize_winn3_gateway_report(decoded)


# --- Design 10.2 (P1): performance read-backs -------------------------------
#
# What a node says about its own queues, buffers and drops. Same standing as
# the gateway report above: a node's claim about itself, narrowed to known keys
# and shapes, never a 422. Two things read it: the drift alert in
# audit_winn3_contract_once (P-1, P-4, P-5, P-9) and the session-full steering
# in select_online_node (P-8). Nothing else served or allocated depends on it.
NODE_PERF_REPORT_VERSION = 1
# A report older than this (three heartbeats) says nothing about the node now.
NODE_PERF_FRESH_SECONDS = 360
# P-8: carrying sessions at or above this share of -max-sessions count as full
# for a new assignment.
NODE_V3_SESSIONS_FULL_PERCENT = 90
# Closed vocabulary (closed-vocabulary drift breaks scans): every reason the
# node can name. An unknown token is kept as one fixed sentinel, never raised.
NODE_PERF_DRIFT_REASONS = (
    "sysctl_below_floor",
    "udp_buffers_below_floor",
    "wan_qdisc_root",
    "wan_qdisc_limit",
    "wan_qdisc_flow_limit",
    "wan_qdisc_parameters",
    "wan_env_override",
    "perf_trial_env",
    "winn3gw_queues_failed",
    "winn3gw_queues_stale",
    "winn3gw0_qdisc_mismatch",
    "forward_async_gate",
)
NODE_PERF_UNRECOGNISED_REASON = "unrecognised_reason"
# A deliberate harness arm or an operator's queue override is worth showing
# but is not an emailed alert.
NODE_PERF_NOTICE_REASONS = ("perf_trial_env", "wan_env_override")
# One alert per node and reason set, repeated every 6 hours while it persists.
NODE_PERF_DRIFT_REALERT_SECONDS = 21600
_NODE_PERF_DRIFT_ALERTED: dict = {}
NODE_PERF_QUEUE_STATES = ("ok", "failed", "stale", "absent")
NODE_PERF_GATEWAY_STATES = ("active", "inactive", "failed", "activating", "deactivating", "reloading", "unknown")
NODE_PERF_GATEWAY_MODES = ("active", "reflector", "stopped")
NODE_PERF_GATE_STATES = ("enabled", "disabled")
NODE_PERF_USABLE_SOURCES = ("gate_line", "computed", "none")
# What the node's inbox_drops_delta counts (an interim proxy, see the node program).
NODE_PERF_INBOX_SOURCES = ("pipe_recv_errors_live_sessions",)
NODE_PERF_NIC_RESULTS = ("ok", "partial", "unsupported", "ethtool_missing", "no_wan_device")
NODE_PERF_OVERRIDE_RE = re.compile(r"^(?:WAN_FQ_|VPN_FQ_|WAN_QDISC_|RPS_)[A-Z0-9_]{1,48}$")
NODE_PERF_TOKEN_RE = re.compile(r"^[a-z_0-9]{1,16}$")
NODE_PERF_DEVICE_RE = re.compile(r"^[A-Za-z0-9_.-]{1,15}$")
NODE_PERF_FEATURE_RE = re.compile(r"^[a-z0-9-]{1,40}$")
# The gateway's own gate line (forward_cpugate.go), printable ASCII only.
NODE_PERF_GATE_LINE_RE = re.compile(r"^[ -~]{1,200}$")


def _perf_int(raw: Any, high: int = 1 << 62) -> Optional[int]:
    if isinstance(raw, bool) or not isinstance(raw, int) or not 0 <= raw <= high:
        return None
    return raw


def _perf_bool(raw: Any) -> Optional[bool]:
    return raw if isinstance(raw, bool) else None


def _perf_choice(raw: Any, allowed: tuple) -> Optional[str]:
    return raw if isinstance(raw, str) and raw in allowed else None


def sanitize_performance_report(raw: Any) -> Optional[dict]:
    """The node's performance read-backs, narrowed to known keys and shapes.

    None means "not reported". A field whose shape is wrong is kept as None
    (unknown), never guessed, and the drift list is cut to the closed set.
    """
    if not isinstance(raw, dict):
        return None
    gateway_raw = raw.get("gateway") if isinstance(raw.get("gateway"), dict) else {}
    sysctl_raw = raw.get("sysctl") if isinstance(raw.get("sysctl"), dict) else {}
    wan_raw = raw.get("wan_qdisc") if isinstance(raw.get("wan_qdisc"), dict) else {}
    queue_raw = raw.get("winn3gw") if isinstance(raw.get("winn3gw"), dict) else {}
    softnet_raw = raw.get("softnet") if isinstance(raw.get("softnet"), dict) else {}
    usable = gateway_raw.get("usable_cpus")
    usable = float(usable) if isinstance(usable, (int, float)) and not isinstance(usable, bool) \
        and 0 <= usable <= 4096 else None
    drift = []
    for reason in raw.get("drift") if isinstance(raw.get("drift"), list) else []:
        if isinstance(reason, str) and reason in NODE_PERF_DRIFT_REASONS:
            token = reason
        else:
            token = NODE_PERF_UNRECOGNISED_REASON
        if token not in drift:
            drift.append(token)
    overrides = sorted({
        name for name in (raw.get("env_overrides") if isinstance(raw.get("env_overrides"), list) else [])
        if isinstance(name, str) and NODE_PERF_OVERRIDE_RE.match(name)
    })[:16]
    report = {
        "v": NODE_PERF_REPORT_VERSION,
        "interval_s": _perf_int(raw.get("interval_s"), 86400),
        "softnet": {"dropped_delta": _perf_int(softnet_raw.get("dropped_delta"))},
        "gateway": {
            "state": _perf_choice(gateway_raw.get("state"), NODE_PERF_GATEWAY_STATES),
            "mode": _perf_choice(gateway_raw.get("mode"), NODE_PERF_GATEWAY_MODES),
            "carrying": _perf_int(gateway_raw.get("carrying"), 9999999),
            "max_sessions": _perf_int(gateway_raw.get("max_sessions"), 9999999),
            "inbox_drops_delta": _perf_int(gateway_raw.get("inbox_drops_delta")),
            "udp_read_buffer": _perf_int(gateway_raw.get("udp_read_buffer")),
            "udp_write_buffer": _perf_int(gateway_raw.get("udp_write_buffer")),
            "udp_rcvbuf_errors": _perf_int(gateway_raw.get("udp_rcvbuf_errors")),
            "udp_rcvbuf_errors_delta": _perf_int(gateway_raw.get("udp_rcvbuf_errors_delta")),
            "inbox_drops_source": _perf_choice(gateway_raw.get("inbox_drops_source"), NODE_PERF_INBOX_SOURCES),
            "async_flag": _perf_bool(gateway_raw.get("async_flag")),
            "async_gate": _perf_choice(gateway_raw.get("async_gate"), NODE_PERF_GATE_STATES),
            "gate_line": gateway_raw.get("gate_line") if isinstance(gateway_raw.get("gate_line"), str)
            and NODE_PERF_GATE_LINE_RE.match(gateway_raw.get("gate_line")) else None,
            "usable_cpus": usable,
            "usable_cpus_source": _perf_choice(gateway_raw.get("usable_cpus_source"), NODE_PERF_USABLE_SOURCES),
        },
        "sysctl": {
            "rmem_max": _perf_int(sysctl_raw.get("rmem_max")),
            "wmem_max": _perf_int(sysctl_raw.get("wmem_max")),
            "ok": _perf_bool(sysctl_raw.get("ok")),
        },
        "wan_qdisc": {
            "dev": wan_raw.get("dev") if isinstance(wan_raw.get("dev"), str)
            and NODE_PERF_DEVICE_RE.match(wan_raw.get("dev")) else None,
            "root": wan_raw.get("root") if isinstance(wan_raw.get("root"), str)
            and NODE_PERF_TOKEN_RE.match(wan_raw.get("root")) else None,
            "limit": _perf_int(wan_raw.get("limit")),
            "flow_limit": _perf_int(wan_raw.get("flow_limit")),
            "match": _perf_bool(wan_raw.get("match")),
        },
        "winn3gw": {
            "queues": _perf_choice(queue_raw.get("queues"), NODE_PERF_QUEUE_STATES),
            "root": queue_raw.get("root") if isinstance(queue_raw.get("root"), str)
            and NODE_PERF_TOKEN_RE.match(queue_raw.get("root")) else None,
            "qlen": _perf_int(queue_raw.get("qlen"), 10000000),
            "match": _perf_bool(queue_raw.get("match")),
        },
        "env_overrides": overrides,
        "perf_trial_env": _perf_bool(raw.get("perf_trial_env")),
        "drift": drift,
    }
    nic = raw.get("nic") if isinstance(raw.get("nic"), dict) else None
    if nic is not None:
        features = nic.get("features") if isinstance(nic.get("features"), dict) else {}
        ring = nic.get("ring") if isinstance(nic.get("ring"), dict) else {}
        report["nic"] = {
            "result": _perf_choice(nic.get("result"), NODE_PERF_NIC_RESULTS),
            "recorded_at": _perf_int(nic.get("recorded_at")),
            "features": {
                key: value for key, value in sorted(features.items())[:16]
                if isinstance(key, str) and NODE_PERF_FEATURE_RE.match(key)
                and value in ("on", "off", "on [fixed]", "off [fixed]")
            },
            "ring": {
                side: {k: _perf_int(v, 10000000) for k, v in sorted(ring[side].items())
                       if k in ("rx", "tx") and _perf_int(v, 10000000) is not None}
                for side in ("max", "current") if isinstance(ring.get(side), dict)
            },
        }
    return report


def parse_performance_report(value: Any) -> Optional[dict]:
    """A stored report back as a dict, or None for missing or unreadable."""
    if not value:
        return None
    try:
        decoded = json.loads(value)
    except Exception:
        return None
    return sanitize_performance_report(decoded)


def node_performance_report_fresh(node: Any, now: Optional[datetime] = None) -> Optional[dict]:
    """The node's stored performance report, only while it is still current."""
    reported = parse_iso_datetime(_node_field(node, "performance_reported_at"))
    if reported is None:
        return None
    if ((now or utcnow()) - reported).total_seconds() > NODE_PERF_FRESH_SECONDS:
        return None
    return parse_performance_report(_node_field(node, "performance_report_json"))


def node_performance_drift(node: Any, now: Optional[datetime] = None) -> list:
    """Drift reasons a current report names, or [] (not reported, stale, clean)."""
    report = node_performance_report_fresh(node, now)
    if not report:
        return []
    reasons = list(report["drift"])
    # A node whose own read-back says the gateway is not on the queue the
    # helper claims is named even when an older node build did not list it.
    queues = report["winn3gw"]
    if queues["queues"] == "failed" and "winn3gw_queues_failed" not in reasons:
        reasons.append("winn3gw_queues_failed")
    if queues["queues"] == "stale" and "winn3gw_queues_stale" not in reasons:
        reasons.append("winn3gw_queues_stale")
    return sorted(set(reasons))


def node_v3_sessions_full(conn: sqlite3.Connection, node: Any) -> bool:
    """P-8: is this node full for a NEW v3 assignment?

    True when its carrying sessions, plus the devices assigned to it since it
    last reported (the report lags an assignment by up to a heartbeat), reach
    NODE_V3_SESSIONS_FULL_PERCENT of the gateway's -max-sessions. A node that
    reports no forwarding gateway, has no fresh report, or whose figures cannot
    be read is never full here: unknown is not a reason to refuse anyone, and
    the stale-heartbeat sweep already deals with a node that went quiet.
    """
    # Only a node that serves winn/3 competes on session room: a winn/1 node's
    # gateway report says nothing about where a legacy client should go, and
    # steering by it would change legacy assignment behaviour.
    if str(_node_field(node, "protocol_version") or "").strip().lower() != WINN_PROTOCOL_V3:
        return False
    report = node_performance_report_fresh(node)
    if not report:
        return False
    gateway = report["gateway"]
    carrying, maximum = gateway["carrying"], gateway["max_sessions"]
    if gateway["mode"] != "active" or carrying is None or not maximum:
        return False
    if carrying * 100 >= maximum * NODE_V3_SESSIONS_FULL_PERCENT:
        return True
    reported = parse_iso_datetime(_node_field(node, "performance_reported_at"))
    slug = str(_node_field(node, "slug") or "")
    pending = 0
    for row in conn.execute(
        "SELECT updated_at FROM devices WHERE location_slug = ? "
        "AND COALESCE(winn3_inner_v4, '') != ''", (slug,),
    ).fetchall():
        seen = parse_iso_datetime(row["updated_at"])
        if seen is not None and reported is not None and seen > reported:
            pending += 1
    return (carrying + pending) * 100 >= maximum * NODE_V3_SESSIONS_FULL_PERCENT


def sanitize_origin_cert_not_after(raw: Any) -> Optional[str]:
    """The node's origin certificate notAfter as ISO 8601 UTC, or None."""
    text = str(raw or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.strptime(text, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError:
        return None
    return parsed.strftime("%Y-%m-%dT%H:%M:%SZ")


@app.post("/api/v1/nodes/register")
def register_node(payload: NodeRegistration, request: Request):
    # H-2: routine node-scoped endpoint -- per-node-token-only. A node
    # obtains its token exactly once, via /api/v1/nodes/bootstrap
    # (grant-gated), and every subsequent registration/re-registration
    # (this endpoint) authenticates with only that token; the fleet-wide
    # admin token is never accepted here.
    with get_db() as conn:
        ensure_schema(conn)
        existing_node_token_hash = fetch_node_token_hash(conn, payload.slug)
    if not node_token_matches(existing_node_token_hash, payload.secret_token):
        security_alert(2, "invalid node registration secret", request=request, details={
            "slug": payload.slug,
            "endpoint_hash": security_event_hash(payload.endpoint),
        })
        raise HTTPException(status_code=401, detail="Unauthorized")
    if not payload.public_key.strip():
        raise HTTPException(status_code=400, detail="Node public_key must not be empty")
    if not payload.endpoint.strip():
        raise HTTPException(status_code=400, detail="Node endpoint must not be empty")
    if payload.stealth_endpoint.strip() and not re.fullmatch(
        r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}",
        payload.xray_uuid.strip(),
    ):
        raise HTTPException(status_code=400, detail="Node xray_uuid must be a valid UUID when stealth_endpoint is enabled")
    status = payload.status if payload.status in {"online", "congested", "maintenance"} else "online"
    registered_max_peers = normalized_node_max_peers(payload.max_peers)
    registered_tunnel_gateway_ipv4 = normalize_private_tunnel_gateway_ipv4(
        payload.tunnel_gateway_ipv4
    )
    if payload.tunnel_gateway_ipv4.strip() and not registered_tunnel_gateway_ipv4:
        raise HTTPException(
            status_code=400,
            detail="Node tunnel_gateway_ipv4 must be a usable RFC1918 IPv4 address.",
        )
    # Validate at intake so an unusable profile never reaches the database,
    # where it would only surface much later as a 503 on somebody's login. What
    # is stored is re-serialized from the parsed form, so the stored blob and
    # the blob /api/v1/config serves are the same bytes rendered the same way.
    if payload.obfuscation_json and payload.obfuscation_json.strip():
        try:
            obfuscation_json = json.dumps(parse_obfuscation(payload.obfuscation_json))
        except ObfuscationProfileError as exc:
            logger.error(
                "rejecting registration for node %s: obfuscation_json is unusable (reason=%s keys=%s)",
                payload.slug, exc.reason, ",".join(exc.keys) or "-",
            )
            raise HTTPException(
                status_code=400,
                detail=f"Node obfuscation_json is unusable ({exc.reason}); it must carry every AmneziaWG parameter as a uint32.",
            ) from exc
    else:
        # The node reported no profile at all. Recording the legacy set keeps
        # the row servable, but from here on the hub is asserting a profile the
        # node never confirmed -- so say so rather than let it pass silently.
        obfuscation_json = json.dumps(DEFAULT_OBFUSCATION)
        logger.warning(
            "node %s registered without an obfuscation profile; recording the legacy default on its behalf",
            payload.slug,
        )
    resolved_ssh_host = payload.ssh_host or extract_node_host(payload.endpoint)
    if HIDE_CONTROL_ORIGIN:
        expected_management_host = node_management_hostname(payload.slug)
        if normalize_hostname(resolved_ssh_host) != expected_management_host:
            raise HTTPException(status_code=400, detail="Node ssh_host must be the provisioned management tunnel hostname")
    resolved_xray_sni = payload.xray_sni or split_host_port(payload.stealth_endpoint, payload.stealth_public_port)[0]
    regional_aliases_json = json.dumps(parse_aliases(payload.regional_aliases))
    try:
        registered_transports = parse_xray_transports(
            payload.stealth_transports,
            payload.stealth_public_port,
            (payload.xray_security or "none").lower(),
            strict=True,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f"Invalid Xray transports: {exc}") from exc
    if (
        payload.stealth_endpoint.strip()
        and any(item["security"] == "tls" for item in registered_transports)
        and not xray_tls_dns_candidate_available(
            payload.stealth_endpoint, payload.regional_aliases, payload.stealth_public_port
        )
    ):
        raise HTTPException(
            status_code=400,
            detail="Invalid Xray transports: a TLS route needs a DNS-named stealth host or regional alias.",
        )
    stealth_transports_json = json.dumps(registered_transports)
    payload_flag = normalize_country_flag(payload.flag)
    source_ip = request_origin_ip(request)
    if node_registration_is_blocked(payload.slug, payload.endpoint, payload.stealth_endpoint, resolved_ssh_host, source_ip):
        security_alert(3, "blocked retired node registration", request=request, details={
            "slug": payload.slug,
            "endpoint_host": extract_node_host(payload.endpoint),
            "ssh_host": resolved_ssh_host,
        })
        raise HTTPException(status_code=403, detail="Node registration is not allowed for this host")
    # Identity collision pre-flight. Sits with the other intake validations,
    # and outside any write transaction, so security_alert() can open its own
    # connection to record the event without this request waiting on itself.
    # The authoritative check is repeated inside the transaction below.
    with get_db() as conn:
        ensure_schema(conn)
        # Admin node-retirement lane (2026-08-07). Read in the same pre-flight
        # rather than on a connection of its own.
        existing_row = conn.execute(
            "SELECT retired_at FROM nodes WHERE slug = ?", (payload.slug,)
        ).fetchone()
        identity_collisions = node_identity_collisions(
            conn,
            payload.slug,
            endpoint=payload.endpoint,
            stealth_endpoint=payload.stealth_endpoint,
            public_key=payload.public_key,
            ssh_host=resolved_ssh_host,
        )
    # Admin node-retirement lane (2026-08-07). Checked BEFORE the collision
    # report because it is the more specific and more actionable answer: a
    # retired row has had its identity attributes released, so it would not
    # collide with anything and the caller would otherwise be waved straight
    # through and silently un-retired.
    #
    # This guard is what makes retirement mean something. The upsert below
    # writes status = excluded.status, so without it the node's own
    # wins-node-register.timer would flip a just-retired row back to 'online'
    # within 120 seconds and re-fill the identity columns the operator
    # deliberately released -- reversing an operator decision by machine, with
    # nobody told. Undoing a retirement is an operator action
    # (POST /admin/nodes/restore), symmetric with taking it.
    #
    # 409 and not 403: the credential is valid and the request is well formed;
    # it is the fleet state that makes it unacceptable. Same choice, same
    # reason, as the collision refusal below. Priority 3, not 2 -- the usual
    # cause is a decommissioned box that was left powered on, which is an
    # operator-hygiene event and not an authentication event.
    if node_is_retired(existing_row):
        logger.warning(
            "refusing registration for node %s: the row is retired and must be restored first",
            payload.slug,
        )
        security_alert(3, "registration attempt by a retired node", request=request, details={
            "slug": payload.slug,
        })
        raise HTTPException(
            status_code=409,
            detail=(
                "This node has been retired by an operator. No node record was changed. "
                "Restore it (POST /admin/nodes/restore) before it can register again."
            ),
        )
    if identity_collisions:
        collision = NodeIdentityCollision(identity_collisions)
        # Names only, both here and in the security event: the colliding values
        # are endpoints and public keys.
        logger.error(
            "refusing registration for node %s: identity collision (%s)",
            payload.slug, collision,
        )
        security_alert(2, "node registration identity collision", request=request, details={
            "slug": payload.slug,
            "attributes": ",".join(collision.attributes),
            "conflicting_slugs": ",".join(collision.slugs),
        })
        # The response deliberately names the attributes but NOT the other
        # slugs -- the caller has proven ownership of its own slug and nothing
        # else, and the operator has the full pairing in the hub log and in the
        # security event. 409, not 400: the request is well formed, the fleet
        # state is what makes it unacceptable.
        raise HTTPException(
            status_code=409,
            detail=(
                "Node registration conflicts with an existing node on: "
                + ", ".join(collision.attributes)
                + ". No node record was changed. Resolve the duplicate identity on the hub "
                "(or register under the slug that already holds it) and retry."
            ),
        )
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        mark_stale_nodes_offline(conn)
        authoritative_row = conn.execute(
            "SELECT retired_at FROM nodes WHERE slug = ?", (payload.slug,)
        ).fetchone()
        if node_is_retired(authoritative_row):
            raise HTTPException(
                status_code=409,
                detail="Retired node must be restored before registration",
            )
        now = utcnow()
        now_iso = now.isoformat()
        previous = conn.execute(
            "SELECT awg_rx_bytes, awg_tx_bytes, last_heartbeat, free_access_enabled, "
            "direct_awg_enabled, direct_awg_node_enabled, direct_awg_admin_override, "
            "load_band, load_candidate, load_candidate_count, load_reported_at, load_band_at FROM nodes WHERE slug = ?",
            (payload.slug,),
        ).fetchone()
        free_access_enabled = (
            int(previous["free_access_enabled"] or 0)
            if previous
            else int(initial_node_free_access_enabled(
                conn,
                payload.slug,
                payload.name,
                payload.endpoint,
                resolved_ssh_host,
            ))
        )
        if payload.direct_awg_enabled is None and previous:
            prior_node_flag = previous["direct_awg_node_enabled"]
            if prior_node_flag is None:
                prior_node_flag = previous["direct_awg_enabled"]
            reported_direct_awg_enabled = int(prior_node_flag if prior_node_flag is not None else 1)
        else:
            reported_direct_awg_enabled = 1 if payload.direct_awg_enabled is not False else 0
        admin_direct_awg_enabled = (
            int(previous["direct_awg_admin_override"])
            if previous and previous["direct_awg_admin_override"] is not None else 1
        )
        direct_awg_enabled = reported_direct_awg_enabled & admin_direct_awg_enabled
        rx_mbps = 0.0
        tx_mbps = 0.0
        if previous and previous["last_heartbeat"]:
            try:
                prev_rx = int(previous["awg_rx_bytes"] or 0)
                prev_tx = int(previous["awg_tx_bytes"] or 0)
                prev_time = datetime.fromisoformat(previous["last_heartbeat"])
                elapsed = max(1.0, (now - prev_time).total_seconds())
                rx_delta = int(payload.awg_rx_bytes or 0) - prev_rx
                tx_delta = int(payload.awg_tx_bytes or 0) - prev_tx
                baseline_ready = prev_rx > 0 or prev_tx > 0
                if baseline_ready and rx_delta >= 0:
                    rx_mbps = round((rx_delta * 8) / elapsed / 1_000_000, 3)
                if baseline_ready and tx_delta >= 0:
                    tx_mbps = round((tx_delta * 8) / elapsed / 1_000_000, 3)
            except Exception:
                rx_mbps = 0.0
                tx_mbps = 0.0
        # This is where the pre-upsert DELETE used to be. See
        # node_identity_collisions() for why it is gone and what replaced it.
        # Three things now stand in its place, all non-destructive:
        #
        # (1) The authoritative collision check, re-run inside the transaction
        #     that performs the upsert. The pre-flight above is what alerts;
        #     this is what guarantees. It exists because the pre-flight ran on
        #     its own connection, and a concurrent registration could have
        #     created a colliding row in between.
        if node_identity_collisions(
            conn,
            payload.slug,
            endpoint=payload.endpoint,
            stealth_endpoint=payload.stealth_endpoint,
            public_key=payload.public_key,
            ssh_host=resolved_ssh_host,
        ):
            raise HTTPException(
                status_code=409,
                detail="Node registration conflicts with an existing node. No node record was changed.",
            )
        # (2) A census taken before the write, checked after it. This endpoint
        #     must only ever add or update one row, so the node count cannot
        #     fall. It is a tripwire, not a check that can fire today -- the
        #     point is that if anyone ever reintroduces a destructive statement
        #     on this path, the request fails and the transaction rolls back
        #     (get_db() commits only on a clean exit) instead of quietly taking
        #     the fleet down. The fleet is small; COUNT(*) is free.
        nodes_before = int(conn.execute("SELECT COUNT(*) AS n FROM nodes").fetchone()["n"])
        prior_row = conn.execute(
            "SELECT endpoint FROM nodes WHERE slug = ?",
            (payload.slug,),
        ).fetchone()
        prior_endpoint = (prior_row["endpoint"] if prior_row else None)
        # protocol_version and protocol_params_json are DELIBERATELY absent from
        # this column list, and from the DO UPDATE clause. This is a decision,
        # not an oversight, and it is recorded here because the omission reads
        # like one:
        #
        #   * protocol_params_json is handed to the client verbatim --
        #     parse_protocol_params() returns whatever dict was stored and
        #     /verify copies it straight into the served config. Accepting it
        #     here would let anything holding one node token inject arbitrary
        #     JSON into every config issued for that node, with no validator in
        #     front of it. Writing that validator is Winn Protocol v3 design
        #     work, owned by the team building v3, not by the registration path.
        #   * protocol_version decides what the client believes the node speaks.
        #     A node self-asserting "winn/3" would have the hub advertise a
        #     post-quantum protocol on the node's own say-so, with nothing
        #     verifying the box implements it. The register payload is the wrong
        #     authority for that claim.
        #
        # Setting these stays an operator action (POST /admin/nodes/winn3,
        # which the install-time opt-in WINN3_SET_CARRIER_STANDALONE=1 drives
        # after the node is up) or the post-commit H2 job after its proofs.
        # Registration never applies the opt-in itself (it would skip the
        # sticky operator hold and the served-profile proof). Direct SQL is no
        # longer the only path. Note that the guard above is
        # what makes that safe: because a colliding registration is now refused
        # instead of deleting the other row, an operator-set winn/3 value can no
        # longer be destroyed and silently reset to the CREATE TABLE default by
        # a re-registration under a new slug. Same reasoning applies to
        # management_status, which is also absent by design -- only a real
        # management-tunnel verification may set it.
        #
        # operator_enabled is different: it is explicit in the INSERT as 0 so
        # a genuinely new row is dark even if an upgraded database still has
        # the historical DEFAULT 1. On conflict, only an empty bootstrap
        # placeholder is forced dark. A fully registered row preserves the
        # operator's current latch value across every heartbeat registration.
        conn.execute("""
            INSERT INTO nodes (
                slug, name, flag, endpoint, tunnel_gateway_ipv4, stealth_endpoint, public_key, preshared_key,
                status, last_heartbeat, obfuscation_json, ssh_host, wg_port, xray_path,
                xray_uuid, xray_security, xray_sni, stealth_public_port, xray_inbound_port,
                regional_aliases, stealth_transports, awg_rx_bytes, awg_tx_bytes, wan_rx_bytes, wan_tx_bytes,
                rx_mbps, tx_mbps, peer_count, max_peers, free_access_enabled,
                direct_awg_enabled, direct_awg_node_enabled,
                operator_enabled, data_plane_code_revision, last_online_registered_at
            )
            VALUES (
                ?, ?, ?, ?, ?, ?, ?, ?,
                ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                ?, ?, ?, ?, ?, ?, ?,
                ?, ?, ?, ?, ?, ?,
                0, ?, ?
            )
            ON CONFLICT(slug) DO UPDATE SET
                name=excluded.name,
                flag=excluded.flag,
                endpoint=excluded.endpoint,
                tunnel_gateway_ipv4=COALESCE(NULLIF(excluded.tunnel_gateway_ipv4, ''), nodes.tunnel_gateway_ipv4),
                stealth_endpoint=excluded.stealth_endpoint,
                public_key=excluded.public_key,
                preshared_key=excluded.preshared_key,
                status=excluded.status,
                last_heartbeat=excluded.last_heartbeat,
                obfuscation_json=excluded.obfuscation_json,
                ssh_host=excluded.ssh_host,
                wg_port=excluded.wg_port,
                xray_uuid=excluded.xray_uuid,
                xray_path=excluded.xray_path,
                xray_security=excluded.xray_security,
                xray_sni=excluded.xray_sni,
                stealth_public_port=excluded.stealth_public_port,
                xray_inbound_port=excluded.xray_inbound_port,
                regional_aliases=excluded.regional_aliases,
                stealth_transports=excluded.stealth_transports,
                awg_rx_bytes=excluded.awg_rx_bytes,
                awg_tx_bytes=excluded.awg_tx_bytes,
                wan_rx_bytes=excluded.wan_rx_bytes,
                wan_tx_bytes=excluded.wan_tx_bytes,
                rx_mbps=excluded.rx_mbps,
                tx_mbps=excluded.tx_mbps,
                peer_count=excluded.peer_count,
                max_peers=excluded.max_peers,
                direct_awg_enabled=excluded.direct_awg_enabled,
                direct_awg_node_enabled=excluded.direct_awg_node_enabled,
                -- L84: a registration that fills an EMPTY stored endpoint closes
                -- the latch (next CASE). That is an identity change, not a
                -- health measurement, and the same registration would satisfy
                -- any automatic reopen condition, so it is classified as an
                -- operator-equivalent closure: named, never marked automatic.
                -- All SET expressions read the pre-update row.
                latch_cause=CASE
                    WHEN COALESCE(nodes.endpoint, '') = ''
                         AND COALESCE(nodes.operator_enabled, 0) = 1
                    THEN 'register_empty_endpoint'
                    ELSE nodes.latch_cause
                END,
                health_closed_at=CASE
                    WHEN COALESCE(nodes.endpoint, '') = '' THEN NULL
                    ELSE nodes.health_closed_at
                END,
                health_closed_reason=CASE
                    WHEN COALESCE(nodes.endpoint, '') = '' THEN NULL
                    ELSE nodes.health_closed_reason
                END,
                operator_enabled=CASE
                    WHEN COALESCE(nodes.endpoint, '') = '' THEN 0
                    WHEN COALESCE(nodes.operator_enabled, 0) = 1 THEN 1
                    ELSE nodes.operator_enabled
                END,
                -- COALESCE, not a plain assignment: a node running an installer
                -- that predates the stamp sends nothing, and that must not wipe
                -- a revision the hub already knows. Note that "unprovable" is a
                -- VALUE, not nothing, so a node that regresses to an unprovable
                -- state does overwrite a good revision -- which is correct, and
                -- is the alarm firing rather than a bug.
                data_plane_code_revision=COALESCE(
                    excluded.data_plane_code_revision, nodes.data_plane_code_revision),
                -- IA-SYNC SYNC-08 (ruling B.4): only this full registration,
                -- which carries identity and revision, and only when it says
                -- online, stamps it. The status-only heartbeat routes never do.
                last_online_registered_at=COALESCE(
                    excluded.last_online_registered_at, nodes.last_online_registered_at)
        """, (
            payload.slug, payload.name, payload_flag, payload.endpoint, registered_tunnel_gateway_ipv4,
            payload.stealth_endpoint,
            payload.public_key, payload.preshared_key, status, now_iso, obfuscation_json,
            resolved_ssh_host, payload.wg_port, payload.xray_path, payload.xray_uuid.strip(),
            payload.xray_security, resolved_xray_sni,
            payload.stealth_public_port, payload.xray_inbound_port, regional_aliases_json, stealth_transports_json,
            max(0, int(payload.awg_rx_bytes or 0)), max(0, int(payload.awg_tx_bytes or 0)),
            max(0, int(payload.wan_rx_bytes or 0)), max(0, int(payload.wan_tx_bytes or 0)),
            rx_mbps, tx_mbps, max(0, int(payload.peer_count or 0)), registered_max_peers, free_access_enabled,
            direct_awg_enabled, reported_direct_awg_enabled,
            sanitize_data_plane_code_revision(payload.data_plane_code_revision),
            now_iso if status == "online" else None,
        ))
        # (3) The other half of the census. An upsert may leave the count equal
        #     (this slug already existed) or one higher (it did not). It may
        #     never leave it lower. Failing here rolls the whole transaction
        #     back, so a fleet cannot be reduced by a request to this endpoint
        #     even if some future edit tries to.
        nodes_after = int(conn.execute("SELECT COUNT(*) AS n FROM nodes").fetchone()["n"])
        if nodes_after < nodes_before:
            logger.error(
                "node registration for %s would have reduced the fleet from %d to %d; rolling back",
                payload.slug, nodes_before, nodes_after,
            )
            raise HTTPException(
                status_code=500,
                detail="Node registration was rejected because it would have removed other nodes.",
            )
        # Lane L85 / Round LD2 load report. Written only here, never by the
        # status-only /api/v1/nodes/heartbeat route, so load_reported_at is
        # fresh only when the node itself sent both the CPU and the active-users
        # ratio. A report without them clears load_reported_at, so the listing
        # shows null, but the confirmed band is held (see
        # node_load_prior_state) so one unknown report keeps its hysteresis.
        # Only the band and its timestamps are stored, never the ratios, so the
        # database holds no user count either.
        load_raw = node_load_raw_pct(payload)
        prior_band, prior_candidate, prior_count = node_load_prior_state(previous, now)
        load_band, load_candidate, load_candidate_count = node_load_band_step(
            load_raw, prior_band, prior_candidate, prior_count,
        )
        if load_raw is None:
            load_band = prior_band if prior_band in NODE_LOAD_BAND_PCT else None
            load_band_at = (previous["load_band_at"] or previous["load_reported_at"]) if previous and load_band else None
        else:
            load_band_at = now_iso
        conn.execute(
            "UPDATE nodes SET load_band = ?, load_candidate = ?, load_candidate_count = ?, "
            "load_reported_at = ?, load_band_at = ? WHERE slug = ?",
            (
                load_band, load_candidate, load_candidate_count,
                now_iso if load_raw is not None else None, load_band_at, payload.slug,
            ),
        )
        # SYNC-15/16/22: overwritten on every register, so a node that stops
        # reporting (an older installer) reads as "not reported", never as a
        # stale report that still looks current.
        gateway_report = sanitize_winn3_gateway_report(getattr(payload, "winn3_gateway", None))
        conn.execute(
            "UPDATE nodes SET winn3_gateway_report_json = ?, winn3_gateway_reported_at = ?, "
            "origin_cert_not_after = ? WHERE slug = ?",
            (
                json.dumps(gateway_report, sort_keys=True) if gateway_report is not None else None,
                now_iso if gateway_report is not None else None,
                sanitize_origin_cert_not_after(getattr(payload, "origin_cert_not_after", None)),
                payload.slug,
            ),
        )
        # Design 10.2 (P1): overwritten like the report above, so a node that
        # stops reporting (an older installer) reads as "not reported".
        performance_report = sanitize_performance_report(getattr(payload, "performance", None))
        conn.execute(
            "UPDATE nodes SET performance_report_json = ?, performance_reported_at = ? WHERE slug = ?",
            (
                json.dumps(performance_report, sort_keys=True) if performance_report is not None else None,
                now_iso if performance_report is not None else None,
                payload.slug,
            ),
        )
        # Registration supplies facts, never a carrier choice: the legacy
        # install-time opt-in checks neither the sticky operator hold nor a
        # served-profile proof, so the post-commit H2 job below is the only
        # automatic path to winn/3.
    winn3_schedule_auto_provision(payload.slug)
    return {"ok": True}

@app.post("/api/v1/nodes/{slug}/deployment/withdraw")
def withdraw_node_for_deployment(
    slug: str,
    request: Request,
    x_node_token: str = Header(...),
):
    """Acquire a node-scoped hub latch before an installer rerun mutates it."""
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    withdrawal_id = secrets.token_hex(16)
    now_iso = utcnow().isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        require_node_token(conn, node_slug, x_node_token, request, "node deployment withdrawal")
        row = conn.execute(
            "SELECT * FROM nodes WHERE slug=?", (node_slug,)
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="Retired node cannot enter deployment.")
        # IA-SYNC SYNC-08 (ruling A): the identity and latch this rerun starts
        # from, read before close_data_plane_promotion() zeroes the latch.
        prior_state = json.dumps(
            node_deployment_prior_state(row, now_iso), sort_keys=True, separators=(",", ":"))
        conn.execute(
            "UPDATE nodes SET status='maintenance', deployment_withdrawal_id=?, "
            "deployment_withdrawn_at=?, deployment_prior_state_json=?, "
            "deployment_completed_at=NULL, deployment_released_at=NULL, "
            "deployment_generation=deployment_generation+1, winn3_expected_transition_json=NULL, "
            "winn3_job_lease=NULL, winn3_job_lease_until=NULL WHERE slug=?",
            (withdrawal_id, now_iso, prior_state, node_slug),
        )
        invalidated = close_data_plane_promotion(
            conn, node_slug, now_iso, cause="installer_withdrawal")
    logger.warning(
        "node %s entered installer withdrawal (invalidated_assignments=%d)",
        node_slug,
        invalidated,
    )
    return {
        "ok": True,
        "slug": node_slug,
        "operator_enabled": False,
        "withdrawal_id": withdrawal_id,
        "invalidated_assignment_count": invalidated,
    }

@app.post("/api/v1/nodes/{slug}/deployment/complete")
def complete_node_deployment(
    slug: str,
    payload: DeploymentWithdrawalCompletion,
    request: Request,
    x_node_token: str = Header(...),
):
    """Release only the matching deployment block; never restore promotion."""
    node_slug = (slug or "").strip().lower()
    withdrawal_id = (payload.withdrawal_id or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    if not re.fullmatch(r"[0-9a-f]{32}", withdrawal_id):
        raise HTTPException(status_code=400, detail="Deployment withdrawal ID is invalid.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        require_node_token(conn, node_slug, x_node_token, request, "node deployment completion")
        released = conn.execute(
            "UPDATE nodes SET deployment_withdrawal_id=NULL, deployment_withdrawn_at=NULL, deployment_released_at=? "
            "WHERE slug=? AND deployment_withdrawal_id=? AND COALESCE(operator_enabled, 0)=0",
            (utcnow().isoformat(), node_slug, withdrawal_id),
        )
        if released.rowcount != 1:
            raise HTTPException(
                status_code=409,
                detail="Deployment completion did not match the active dark withdrawal.",
            )
        # IA-SYNC SYNC-08 (ruling B): an eligible rerun of a live node is
        # recorded as an installer_rerun closure that only the L84 path, under
        # its own switch and every proof the ruling lists, can reopen. Anything
        # else keeps the plain installer closure exactly as before.
        row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        prior = node_deployment_prior(row)
        completed_at = utcnow().isoformat()
        # H7 (design 3.17, "completion for a rerun"): a node that was never live
        # since its bootstrap (and was not live when this rerun withdrew it) is
        # a fresh_install go-live candidate when its own verified ticket says
        # go_live=auto. A live node keeps the installer_rerun path below, and
        # anything else stays the plain closure exactly as before; every
        # matching release set deployment_released_at above either way.
        fresh_ticket = None
        fresh_pending = False
        reset_nonce = None
        if int(prior.get("operator_enabled") or 0) != 1 and node_never_live_since_bootstrap(conn, row):
            fresh_ticket, _fresh_reasons = fresh_install_authority(conn, row)
            # H7 fix (Sol T1 item 2): the same reset authority as complete-fresh.
            # A slug that was live before its latest bootstrap is classed
            # fresh_install only under it, so the reset rule there cannot be
            # bypassed through a resume rerun; the release above still stands
            # and the node stays a plain closure for the manual promotion. The
            # completion records the reset nonce, as complete-fresh does, so a
            # later epoch's reuse check sees it.
            if fresh_ticket is not None:
                reset_refusals, reset_nonce = fresh_completion_reset_failures(conn, row)
                if reset_refusals:
                    fresh_ticket = None
        if fresh_ticket is not None:
            # HL-F3: as complete-fresh, the closure ends any earlier streak.
            marked = conn.execute(
                "UPDATE nodes SET health_closed_at=?, health_closed_reason='fresh_install', "
                "latch_cause='fresh_install_pending', deployment_completed_at=?, "
                "data_plane_green_streak=0, data_plane_green_since=NULL "
                "WHERE slug=? AND deployment_withdrawal_id IS NULL "
                "AND COALESCE(operator_enabled, 0)=0",
                (completed_at, completed_at, node_slug),
            )
            fresh_pending = marked.rowcount == 1
            if fresh_pending:
                revision_now = str(row["data_plane_code_revision"] or "").strip().lower()
                conn.execute(
                    "INSERT OR REPLACE INTO node_fresh_completions "
                    "(slug, epoch, installer_sha256, ticket_nonce, completed_at) VALUES (?, ?, ?, ?, ?)",
                    (node_slug, node_bootstrap_epoch(row),
                     revision_now.removeprefix("sha256:") if NODE_RERUN_REVISION_RE.fullmatch(revision_now) else "",
                     reset_nonce or fresh_ticket["nonce"], completed_at),
                )
        if fresh_pending:
            reasons, lineage_rule = [], ""
        else:
            reasons, lineage_rule = installer_rerun_reopen_eligibility(conn, row, prior)
            if not NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED:
                reasons.append("installer rerun automatic reopen is disabled "
                               "(NODE_INSTALLER_RERUN_AUTO_REOPEN_ENABLED=0)")
        pending = False
        if not reasons and not fresh_pending:
            # HL-F3: the same rule for the rerun closure the L84 gate judges.
            marked = conn.execute(
                "UPDATE nodes SET health_closed_at=?, health_closed_reason='installer_rerun', "
                "latch_cause='installer_rerun_pending', deployment_completed_at=?, "
                "data_plane_green_streak=0, data_plane_green_since=NULL "
                "WHERE slug=? AND deployment_withdrawal_id IS NULL "
                "AND COALESCE(operator_enabled, 0)=0",
                (completed_at, completed_at, node_slug),
            )
            pending = marked.rowcount == 1
            if not pending:
                reasons.append("node state changed during completion")
        revision = str(row["data_plane_code_revision"] or "") if row is not None else ""
    # Design 10.3 (P-11, P-12): only after the release has committed, so the job
    # and the canary read the released row. Neither can fail the completion.
    trigger_winn3_golive_after_release(node_slug)
    if fresh_pending:
        security_alert(3, "node completed fresh install rerun; automatic go-live pending proofs", details={
            "slug": node_slug, "revision": revision,
        })
    elif pending:
        security_alert(3, "node completed installer rerun; automatic reopen pending proofs", details={
            "slug": node_slug, "revision": revision, "lineage_rule": lineage_rule,
        })
    else:
        security_alert(2, "node completed installer rerun; manual evidenced promotion required",
                       details={"slug": node_slug, "reasons": reasons})
    # auto_reopen_pending keeps its meaning for the node-side message (the hub
    # will open the node by itself once the proofs pass); auto_golive_pending
    # names the class.
    return {"ok": True, "slug": node_slug, "operator_enabled": False,
            "auto_reopen_pending": pending or fresh_pending,
            "auto_golive_pending": fresh_pending, "reasons": reasons}

@app.post("/api/v1/nodes/{slug}/deployment/complete-fresh")
def complete_fresh_node_deployment(
    slug: str,
    payload: FreshDeploymentCompletion,
    request: Request,
    x_node_token: str = Header(...),
):
    """Complete a plain fresh install or a same-slug reset (design 3.17, H7).

    A fresh install has no withdrawal, so it never reaches the rerun completion
    route. One BEGIN IMMEDIATE transaction: the node token; a retired node is
    refused; the node must be never live since its bootstrap (operator_enabled
    0, no open withdrawal, no promotion row at or after node_bootstrapped_at);
    a slug that was live before this bootstrap also needs a stored t1 reset
    ticket that verifies now, is unexpired and was not used by an earlier
    completion (fresh_completion_reset_failures; the signer consumes it later,
    at sign, and refuses a spent nonce there); installer_sha256 must equal the
    digest in the row's data_plane_code_revision, which the final registration
    just reported; and
    a completion already recorded is idempotent for the same digest and refused
    for any other. It then sets deployment_released_at and
    deployment_completed_at, and, when the verified ticket carries go_live=auto
    and WINN3_FRESH_INSTALL_AUTO_GOLIVE is on, records the closure as
    health_closed_reason='fresh_install'. It never opens operator_enabled and
    never carries the admin token."""
    node_slug = (slug or "").strip().lower()
    digest = (payload.installer_sha256 or "").strip()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise HTTPException(status_code=400, detail="installer_sha256 must be 64 lowercase hex characters.")
    reasons: list[str] = []
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        require_node_token(conn, node_slug, x_node_token, request, "node fresh deployment completion")
        row = conn.execute("SELECT * FROM nodes WHERE slug=?", (node_slug,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Node not found.")
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="Retired node cannot complete a deployment.")
        epoch = node_bootstrap_epoch(row)
        if str(row["deployment_withdrawal_id"] or "").strip() or int(row["operator_enabled"] or 0) != 0:
            raise HTTPException(
                status_code=409,
                detail="Fresh completion refused: the node has an open withdrawal or is open.",
            )
        if node_promoted_since_bootstrap(conn, node_slug, epoch):
            raise HTTPException(
                status_code=409,
                detail="Fresh completion refused: the node has been live since its bootstrap.",
            )
        if str(row["data_plane_code_revision"] or "").strip().lower() != "sha256:" + digest:
            raise HTTPException(
                status_code=409,
                detail="Fresh completion refused: installer_sha256 differs from the registered revision.",
            )
        recorded = conn.execute(
            "SELECT installer_sha256 FROM node_fresh_completions WHERE slug=? AND epoch=?",
            (node_slug, epoch),
        ).fetchone()
        if str(row["deployment_completed_at"] or "").strip():
            if recorded is not None and recorded["installer_sha256"] == digest:
                return {"ok": True, "slug": node_slug, "operator_enabled": False,
                        "auto_golive_pending": str(row["health_closed_reason"] or "") == "fresh_install",
                        "reasons": [], "idempotent": True}
            raise HTTPException(
                status_code=409,
                detail="Fresh completion refused: a different completion is already recorded.",
            )
        # H7 fix (Sol T1 item 2; Claude T1 note): reset authority runs after
        # the idempotence check, so an identical completion already committed
        # in this epoch stays idempotent once signing has consumed (or time has
        # expired) its reset ticket. It still guards every new completion.
        refusals, reset_nonce = fresh_completion_reset_failures(conn, row)
        if refusals:
            raise HTTPException(status_code=409, detail="Fresh completion refused: " + "; ".join(refusals))
        ticket, reasons = fresh_install_authority(conn, row)
        now_iso = utcnow().isoformat()
        stamped = conn.execute(
            "UPDATE nodes SET deployment_released_at=?, deployment_completed_at=? "
            "WHERE slug=? AND deployment_withdrawal_id IS NULL AND COALESCE(operator_enabled, 0)=0 "
            "AND retired_at IS NULL",
            (now_iso, now_iso, node_slug),
        )
        pending = False
        if stamped.rowcount != 1:
            raise HTTPException(status_code=409, detail="Fresh completion refused: the node changed concurrently.")
        if ticket is not None:
            # HL-F3: the reopen gate counts only a healthy-proof streak that
            # began after this closure, so a streak of the machine before the
            # completion ends here and the prober's next green run starts one.
            marked = conn.execute(
                "UPDATE nodes SET health_closed_at=?, health_closed_reason='fresh_install', "
                "latch_cause='fresh_install_pending', "
                "data_plane_green_streak=0, data_plane_green_since=NULL "
                "WHERE slug=? AND deployment_withdrawal_id IS NULL AND COALESCE(operator_enabled, 0)=0 "
                "AND retired_at IS NULL",
                (now_iso, node_slug),
            )
            pending = marked.rowcount == 1
            if not pending:
                reasons.append("node state changed during completion")
        conn.execute(
            "INSERT OR REPLACE INTO node_fresh_completions "
            "(slug, epoch, installer_sha256, ticket_nonce, completed_at) VALUES (?, ?, ?, ?, ?)",
            (node_slug, epoch, digest, reset_nonce or (ticket["nonce"] if ticket is not None else None), now_iso),
        )
    # Design 10.3 (P-11, P-12): complete-fresh is the other completion route.
    # After its release has committed; neither can fail the completion.
    trigger_winn3_golive_after_release(node_slug)
    if pending:
        security_alert(3, "node completed fresh install; automatic go-live pending proofs", details={
            "slug": node_slug, "revision": "sha256:" + digest,
        })
    else:
        security_alert(2, "node completed fresh install; manual evidenced promotion required",
                       details={"slug": node_slug, "reasons": reasons})
    return {"ok": True, "slug": node_slug, "operator_enabled": False,
            "auto_golive_pending": pending, "reasons": reasons}

def parse_core_assignment_acknowledgements(
    acknowledgements: list[dict[str, str]], *, maximum: int
) -> dict[str, str]:
    if len(acknowledgements) > maximum:
        raise HTTPException(status_code=400, detail="Too many Core assignment acknowledgements.")
    reported_revisions: dict[str, str] = {}
    for acknowledgement in acknowledgements:
        device_id = str(acknowledgement.get("device_id") or "").strip()
        revision = str(acknowledgement.get("assignment_revision") or "").strip().lower()
        if (
            not device_id
            or len(device_id) > 200
            or any(ord(char) < 32 for char in device_id)
            or not re.fullmatch(r"[0-9a-f]{64}", revision)
            or device_id in reported_revisions
        ):
            raise HTTPException(status_code=400, detail="Invalid Core assignment acknowledgement.")
        reported_revisions[device_id] = revision
    return reported_revisions

def apply_core_registration_runtime_state(
    conn: sqlite3.Connection,
    core_id: str,
    reported_revisions: dict[str, str],
    now_iso: str,
    *,
    runtime_ready: bool,
) -> int:
    # runtime_ready reports the health of the Core process and its complete
    # synchronization snapshot. A new assignment may be committed after that
    # snapshot; it must wait on its own revision acknowledgement without
    # incorrectly taking the otherwise healthy Core out of service.
    conn.execute(
        "UPDATE core_servers SET runtime_ready=? WHERE core_id=?",
        (1 if runtime_ready else 0, core_id),
    )
    if not runtime_ready:
        conn.execute(
            "UPDATE double_vpn_assignments SET runtime_validated_at=NULL WHERE core_id=?",
            (core_id,),
        )
        return 0

    expected_revisions = {
        item["device_id"]: item["assignment_revision"]
        for item in active_core_assignment_payloads(conn, core_id)
    }
    acknowledged_count = 0
    for device_id, revision in reported_revisions.items():
        if not hmac.compare_digest(expected_revisions.get(device_id, ""), revision):
            continue
        cursor = conn.execute(
            """
            UPDATE double_vpn_assignments
            SET applied_revision=?, runtime_validated_at=?
            WHERE core_id=? AND device_id=? AND status='active'
            """,
            (revision, now_iso, core_id, device_id),
        )
        acknowledged_count += max(0, int(cursor.rowcount or 0))
    return acknowledged_count

@app.post("/api/v1/core/assignments/ack")
def acknowledge_core_assignments(
    payload: CoreAssignmentAcknowledgementBatch,
    request: Request,
    x_core_token: str = Header(...),
):
    # H-2: routine core-scoped endpoint -- core-token-only, never the
    # fleet-wide admin token (see require_core_token).
    core_id = (payload.core_id or DOUBLE_VPN_CORE_ID).strip() or DOUBLE_VPN_CORE_ID
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", core_id):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    with get_db() as conn:
        ensure_schema(conn)
        require_core_token(conn, core_id, x_core_token, request, "core assignment acknowledgement")
    reported_revisions = parse_core_assignment_acknowledgements(
        payload.acknowledgements, maximum=1024
    )
    if not reported_revisions:
        return {"ok": True, "core_id": core_id, "acknowledged_assignment_count": 0}
    now_iso = utcnow().isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        if not conn.execute(
            "SELECT 1 FROM core_servers WHERE core_id=?", (core_id,)
        ).fetchone():
            raise HTTPException(status_code=404, detail="Core is not registered.")
        expected_revisions = {
            item["device_id"]: item["assignment_revision"]
            for item in active_core_assignment_payloads(conn, core_id)
        }
        if any(
            not hmac.compare_digest(expected_revisions.get(device_id, ""), revision)
            for device_id, revision in reported_revisions.items()
        ):
            raise HTTPException(status_code=409, detail="Core assignment revision changed; resynchronize.")
        for device_id, revision in reported_revisions.items():
            conn.execute(
                """
                UPDATE double_vpn_assignments
                SET applied_revision=?, runtime_validated_at=?
                WHERE core_id=? AND device_id=? AND status='active'
                """,
                (revision, now_iso, core_id, device_id),
            )
    return {
        "ok": True,
        "core_id": core_id,
        "acknowledged_assignment_count": len(reported_revisions),
    }

@app.post("/api/v1/core/register")
def register_core(payload: CoreRegistration, request: Request, x_core_token: str = Header(...)):
    # H-2: routine core-scoped endpoint -- core-token-only. A core obtains
    # its token exactly once, via /api/v1/core/bootstrap (grant-gated), and
    # every subsequent registration/re-registration (this endpoint) uses
    # only that token; the fleet-wide admin token is never accepted here.
    core_id = (payload.core_id or DOUBLE_VPN_CORE_ID).strip() or DOUBLE_VPN_CORE_ID
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", core_id):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    with get_db() as conn:
        ensure_schema(conn)
        require_core_token(conn, core_id, x_core_token, request, "core registration")
    management_host = normalize_hostname(payload.management_host or "")
    management_user = str(payload.management_user or "ubuntu").strip().lower()
    if not re.fullmatch(r"[a-z_][a-z0-9_-]{0,31}", management_user):
        raise HTTPException(status_code=400, detail="Core management user is invalid.")
    if HIDE_CONTROL_ORIGIN and management_host != core_management_hostname(core_id):
        # During a rolling hub-first upgrade, an older Core may still need to
        # report itself unavailable. It may not claim readiness until the new
        # origin-hiding management connector has been installed and verified.
        if payload.runtime_ready or management_host:
            raise HTTPException(status_code=400, detail="Core management_host must be the provisioned management tunnel hostname")
    if not payload.ingress_endpoint.strip() or not payload.ingress_public_key.strip() or not payload.exit_public_key.strip():
        raise HTTPException(status_code=400, detail="Core ingress endpoint, ingress public key, and exit public key are required.")
    try:
        core_ingress_host, core_ingress_port = split_host_port(payload.ingress_endpoint, 9210)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Core ingress endpoint is invalid.")
    if not core_ingress_host.strip() or core_ingress_port < 1 or core_ingress_port > 65535:
        raise HTTPException(status_code=400, detail="Core ingress endpoint is invalid.")
    registered_tunnel_gateway_ipv4 = normalize_private_tunnel_gateway_ipv4(
        payload.tunnel_gateway_ipv4
    )
    if payload.tunnel_gateway_ipv4.strip() and not registered_tunnel_gateway_ipv4:
        raise HTTPException(
            status_code=400,
            detail="Core tunnel_gateway_ipv4 must be a usable RFC1918 IPv4 address.",
        )
    core_stealth_port = split_host_port(payload.stealth_endpoint, 80)[1]
    try:
        registered_core_transports = parse_xray_transports(
            payload.stealth_transports,
            core_stealth_port,
            (payload.xray_security or "none").lower(),
            strict=True,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f"Invalid core Xray transports: {exc}") from exc
    if (
        payload.stealth_endpoint.strip()
        and any(item["security"] == "tls" for item in registered_core_transports)
        and not xray_tls_dns_candidate_available(
            payload.stealth_endpoint, payload.regional_aliases, core_stealth_port
        )
    ):
        raise HTTPException(
            status_code=400,
            detail="Invalid core Xray transports: a TLS route needs a DNS-named stealth host or regional alias.",
        )
    core_stealth_transports = json.dumps(registered_core_transports)
    core_regional_aliases = json.dumps(parse_aliases(payload.regional_aliases))
    # SYNC-02: same intake rule as a node's profile. An unusable profile never
    # reaches the database; an absent one (older Core agent) is stored as NULL,
    # which _verify_account_sync reads as "not reported", never as a default.
    core_obfuscation_json = None
    if payload.obfuscation_json and payload.obfuscation_json.strip():
        try:
            core_obfuscation_json = json.dumps(parse_obfuscation(payload.obfuscation_json))
        except ObfuscationProfileError as exc:
            logger.error(
                "rejecting registration for core %s: obfuscation_json is unusable (reason=%s keys=%s)",
                core_id, exc.reason, ",".join(exc.keys) or "-",
            )
            raise HTTPException(
                status_code=400,
                detail=f"Core obfuscation_json is unusable ({exc.reason}); it must carry every AmneziaWG parameter as a uint32.",
            ) from exc
    # Kept for rolling compatibility with an older Core. New Core agents use
    # /api/v1/core/assignments/ack in bounded batches before registering ready.
    reported_revisions = parse_core_assignment_acknowledgements(
        payload.applied_assignment_revisions, maximum=1024
    )
    now_iso = utcnow().isoformat()
    acknowledged_count = 0
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        mark_stale_nodes_offline(conn)
        conn.execute("""
            INSERT INTO core_servers (
                core_id, name, region, management_host, management_user, ingress_endpoint, tunnel_gateway_ipv4, stealth_endpoint,
                ingress_public_key, exit_public_key, xray_uuid, xray_path,
                xray_security, stealth_transports, regional_aliases, direct_awg_enabled, status, runtime_ready,
                last_heartbeat, runtime_checked_at, obfuscation_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(core_id) DO UPDATE SET
                name=excluded.name,
                region=excluded.region,
                management_host=COALESCE(NULLIF(excluded.management_host, ''), core_servers.management_host),
                management_user=excluded.management_user,
                ingress_endpoint=excluded.ingress_endpoint,
                tunnel_gateway_ipv4=COALESCE(NULLIF(excluded.tunnel_gateway_ipv4, ''), core_servers.tunnel_gateway_ipv4),
                stealth_endpoint=excluded.stealth_endpoint,
                ingress_public_key=excluded.ingress_public_key,
                exit_public_key=excluded.exit_public_key,
                xray_uuid=excluded.xray_uuid,
                xray_path=excluded.xray_path,
                xray_security=excluded.xray_security,
                stealth_transports=excluded.stealth_transports,
                regional_aliases=excluded.regional_aliases,
                direct_awg_enabled=excluded.direct_awg_enabled,
                status=excluded.status,
                runtime_ready=excluded.runtime_ready,
                last_heartbeat=excluded.last_heartbeat,
                runtime_checked_at=excluded.runtime_checked_at,
                obfuscation_json=excluded.obfuscation_json
        """, (
            core_id,
            payload.name or DOUBLE_VPN_CORE_NAME,
            payload.region or DOUBLE_VPN_CORE_REGION,
            management_host,
            management_user,
            payload.ingress_endpoint,
            registered_tunnel_gateway_ipv4,
            payload.stealth_endpoint,
            payload.ingress_public_key,
            payload.exit_public_key,
            payload.xray_uuid,
            payload.xray_path or "/wins-core-tunnel",
            (payload.xray_security or "none").lower(),
            core_stealth_transports,
            core_regional_aliases,
            1 if payload.direct_awg_enabled else 0,
            payload.status if payload.status in {"online", "maintenance"} else "online",
            1 if payload.runtime_ready else 0,
            now_iso,
            now_iso,
            core_obfuscation_json,
        ))
        runtime_ready = bool(payload.runtime_ready)
        acknowledged_count = apply_core_registration_runtime_state(
            conn,
            core_id,
            reported_revisions,
            now_iso,
            runtime_ready=runtime_ready,
        )
        # w3r/1: a bad or absent relay report clears the stored one and never
        # fails the registration that keeps the AmneziaWG Double VPN alive.
        store_core_relay_report(conn, core_id, payload.relay, now_iso)
        promoted_row = conn.execute(
            "SELECT COALESCE(promoted, 0) AS promoted, pending_promotion_id, "
            "active_promotion_id FROM core_servers WHERE core_id = ?",
            (core_id,),
        ).fetchone()
        promoted = bool(promoted_row and int(promoted_row["promoted"] or 0))
    return {
        "ok": True,
        "core_id": core_id,
        "runtime_ready": runtime_ready,
        "promoted": promoted,
        "pending_promotion_id": str(promoted_row["pending_promotion_id"] or ""),
        "active_promotion_id": str(promoted_row["active_promotion_id"] or ""),
        "acknowledged_assignment_count": acknowledged_count,
    }

@app.post("/api/v1/core/{core_id}/deployment/withdraw")
def withdraw_core_for_deployment(
    core_id: str,
    request: Request,
    x_core_token: str = Header(...),
):
    """Acquire a Core-scoped hub latch before an installer rerun mutates it."""
    requested_core = (core_id or "").strip().lower()
    if requested_core != DOUBLE_VPN_CORE_ID:
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    withdrawal_id = secrets.token_hex(16)
    now_iso = utcnow().isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        require_core_token(conn, requested_core, x_core_token, request, "Core deployment withdrawal")
        conn.execute(
            "UPDATE core_servers SET status='maintenance', deployment_withdrawal_id=?, "
            "deployment_withdrawn_at=? WHERE core_id=?",
            (withdrawal_id, now_iso, requested_core),
        )
        invalidated = close_core_promotion(conn, requested_core, now_iso)
    logger.warning(
        "Double VPN Core %s entered installer withdrawal (invalidated_assignments=%d)",
        requested_core,
        invalidated,
    )
    return {
        "ok": True,
        "core_id": requested_core,
        "runtime_ready": False,
        "promoted": False,
        "pending_promotion_id": "",
        "active_promotion_id": "",
        "withdrawal_id": withdrawal_id,
        "invalidated_assignment_count": invalidated,
    }

@app.post("/api/v1/core/{core_id}/deployment/complete")
def complete_core_deployment(
    core_id: str,
    payload: DeploymentWithdrawalCompletion,
    request: Request,
    x_core_token: str = Header(...),
):
    """Release only the matching deployment block; never restore promotion."""
    requested_core = (core_id or "").strip().lower()
    withdrawal_id = (payload.withdrawal_id or "").strip().lower()
    if requested_core != DOUBLE_VPN_CORE_ID:
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    if not re.fullmatch(r"[0-9a-f]{32}", withdrawal_id):
        raise HTTPException(status_code=400, detail="Deployment withdrawal ID is invalid.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        require_core_token(conn, requested_core, x_core_token, request, "Core deployment completion")
        released = conn.execute(
            "UPDATE core_servers SET deployment_withdrawal_id=NULL, deployment_withdrawn_at=NULL "
            "WHERE core_id=? AND deployment_withdrawal_id=? "
            "AND COALESCE(promoted, 0)=0 AND pending_promotion_id IS NULL "
            "AND active_promotion_id IS NULL",
            (requested_core, withdrawal_id),
        )
        if released.rowcount != 1:
            raise HTTPException(
                status_code=409,
                detail="Deployment completion did not match the active dark withdrawal.",
            )
    return {
        "ok": True,
        "core_id": requested_core,
        "promoted": False,
        "pending_promotion_id": "",
        "active_promotion_id": "",
    }

@app.post("/admin/core/promote")
def admin_promote_core(
    request: Request,
    core_id: str = Form(default=DOUBLE_VPN_CORE_ID),
    confirm_core_id: str = Form(default=""),
    evidence_sha256: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    """Request Core promotion; the Core opens the latch after build exclusion."""
    require_admin_token(x_admin_token, request, "promote Double VPN Core")
    requested_core = (core_id or "").strip().lower()
    confirmation = (confirm_core_id or "").strip().lower()
    evidence_digest = (evidence_sha256 or "").strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", requested_core):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    if requested_core != DOUBLE_VPN_CORE_ID:
        raise HTTPException(status_code=400, detail="Only the configured Double VPN Core can be promoted.")
    if confirmation != requested_core:
        raise HTTPException(
            status_code=400,
            detail="confirm_core_id must exactly repeat the Core ID being promoted.",
        )
    if not re.fullmatch(r"[0-9a-f]{64}", evidence_digest):
        raise HTTPException(
            status_code=400,
            detail=(
                "Core promotion requires evidence_sha256 to be the 64-character "
                "SHA-256 of frozen, secret-safe gate evidence."
            ),
        )
    cutoff = (utcnow() - timedelta(seconds=DOUBLE_VPN_CORE_STALE_SECONDS)).isoformat()
    promotion_id = secrets.token_hex(16)
    requested_at = utcnow().isoformat()
    operator_source_hash = security_event_hash(request_origin_bucket_value(request))
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT * FROM core_servers WHERE core_id = ?", (requested_core,)
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Core is not registered.")
        if bool(row["promoted"]):
            raise HTTPException(status_code=409, detail="Core is already promoted.")
        if row["pending_promotion_id"]:
            raise HTTPException(status_code=409, detail="Core promotion is already pending acknowledgement.")
        eligible = conn.execute(
            f"SELECT 1 FROM core_servers WHERE core_id = ? AND {CORE_SELF_READY_SQL}",
            (requested_core, cutoff, cutoff, cutoff),
        ).fetchone()
        if not eligible:
            failures = core_promotion_readiness_failures(row, cutoff)
            raise HTTPException(
                status_code=409,
                detail=(
                    "Core remains dark; promotion gates failed: "
                    + "; ".join(failures or ["readiness predicate rejected the Core"])
                    + ". No Core record was changed."
                ),
            )
        claimed = conn.execute(
            "UPDATE core_servers SET pending_promotion_id=?, "
            "pending_promotion_evidence_sha256=?, "
            "pending_promotion_operator_source_hash=?, pending_promotion_requested_at=? "
            "WHERE core_id=? AND COALESCE(promoted, 0)=0 AND pending_promotion_id IS NULL "
            "AND deployment_withdrawal_id IS NULL",
            (promotion_id, evidence_digest, operator_source_hash, requested_at, requested_core),
        )
        if claimed.rowcount != 1:
            raise HTTPException(
                status_code=409,
                detail="Core promotion state changed concurrently. No promotion request was recorded.",
            )
    security_alert(4, "Double VPN Core promotion requested", request=request, details={
        "core_id": requested_core,
        "promotion_id": promotion_id,
        "evidence_sha256": evidence_digest,
    })
    logger.warning(
        "Double VPN Core %s promotion requested by operator (promotion_id=%s, evidence_sha256=%s)",
        requested_core, promotion_id, evidence_digest,
    )
    return {
        "ok": True,
        "core_id": requested_core,
        "promoted": False,
        "promotion_pending": True,
        "promotion_id": promotion_id,
        "requested_at": requested_at,
        "evidence_sha256": evidence_digest,
    }

@app.post("/api/v1/core/promotion/ack")
def acknowledge_core_promotion(
    payload: CorePromotionAcknowledgement,
    request: Request,
    x_core_token: str = Header(...),
):
    """Open exactly one pending promotion while the Core excludes builds."""
    core_id = (payload.core_id or DOUBLE_VPN_CORE_ID).strip().lower()
    promotion_id = (payload.promotion_id or "").strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", core_id):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    if not re.fullmatch(r"[0-9a-f]{32}", promotion_id):
        raise HTTPException(status_code=400, detail="Core promotion ID is invalid.")
    with get_db() as conn:
        ensure_schema(conn)
        require_core_token(conn, core_id, x_core_token, request, "Core promotion acknowledgement")
    cutoff = (utcnow() - timedelta(seconds=DOUBLE_VPN_CORE_STALE_SECONDS)).isoformat()
    promoted_at = utcnow().isoformat()
    idempotent = False
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        mark_stale_nodes_offline(conn)
        row = conn.execute("SELECT * FROM core_servers WHERE core_id=?", (core_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Core is not registered.")
        if bool(row["promoted"]) and hmac.compare_digest(
            str(row["active_promotion_id"] or ""), promotion_id
        ):
            idempotent = True
            promoted_at_row = conn.execute(
                "SELECT promoted_at FROM core_promotion_events WHERE promotion_id=?", (promotion_id,)
            ).fetchone()
            promoted_at = str(promoted_at_row["promoted_at"] if promoted_at_row else promoted_at)
        else:
            if bool(row["promoted"]) or not hmac.compare_digest(
                str(row["pending_promotion_id"] or ""), promotion_id
            ):
                raise HTTPException(status_code=409, detail="Core promotion is not pending for this generation.")
            eligible = conn.execute(
                f"SELECT 1 FROM core_servers WHERE core_id=? AND {CORE_SELF_READY_SQL}",
                (core_id, cutoff, cutoff, cutoff),
            ).fetchone()
            if not eligible:
                failures = core_promotion_readiness_failures(row, cutoff)
                raise HTTPException(
                    status_code=409,
                    detail="Core remains dark; acknowledgement gates failed: "
                    + "; ".join(failures or ["readiness predicate rejected the Core"]),
                )
            evidence_digest = str(row["pending_promotion_evidence_sha256"] or "")
            operator_source_hash = str(row["pending_promotion_operator_source_hash"] or "")
            if not re.fullmatch(r"[0-9a-f]{64}", evidence_digest) or not operator_source_hash:
                raise HTTPException(status_code=409, detail="Core promotion evidence is incomplete.")
            claimed = conn.execute(
                "UPDATE core_servers SET promoted=1, active_promotion_id=?, "
                "pending_promotion_id=NULL, pending_promotion_evidence_sha256=NULL, "
                "pending_promotion_operator_source_hash=NULL, pending_promotion_requested_at=NULL "
                "WHERE core_id=? AND COALESCE(promoted, 0)=0 AND pending_promotion_id=? "
                "AND deployment_withdrawal_id IS NULL",
                (promotion_id, core_id, promotion_id),
            )
            if claimed.rowcount != 1:
                raise HTTPException(status_code=409, detail="Core promotion changed concurrently.")
            conn.execute(
                "INSERT INTO core_promotion_events ("
                " promotion_id, core_id, promoted_at, evidence_sha256, operator_source_hash,"
                " core_status, management_status, management_checked_at, runtime_ready,"
                " runtime_checked_at, last_heartbeat"
                ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    promotion_id, core_id, promoted_at, evidence_digest, operator_source_hash,
                    str(row["status"] or "unknown"), str(row["management_status"] or "unknown"),
                    str(row["management_checked_at"]), int(bool(row["runtime_ready"])),
                    str(row["runtime_checked_at"]), str(row["last_heartbeat"]),
                ),
            )
    if not idempotent:
        security_alert(4, "Double VPN Core promoted", request=request, details={
            "core_id": core_id,
            "promotion_id": promotion_id,
        })
        logger.warning(
            "Double VPN Core %s acknowledged promotion while build-excluded (promotion_id=%s)",
            core_id,
            promotion_id,
        )
    return {
        "ok": True,
        "core_id": core_id,
        "runtime_ready": True,
        "promoted": True,
        "pending_promotion_id": "",
        "active_promotion_id": promotion_id,
        "promotion_id": promotion_id,
        "promoted_at": promoted_at,
        "idempotent": idempotent,
    }

@app.post("/admin/core/withdraw")
def admin_withdraw_core(
    request: Request,
    core_id: str = Form(default=DOUBLE_VPN_CORE_ID),
    x_admin_token: str = Header(...),
):
    """Withdraw a Core immediately and invalidate all of its live assignments."""
    require_admin_token(x_admin_token, request, "withdraw Double VPN Core")
    requested_core = (core_id or "").strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", requested_core):
        raise HTTPException(status_code=400, detail="Core ID is invalid.")
    if requested_core != DOUBLE_VPN_CORE_ID:
        raise HTTPException(status_code=400, detail="Only the configured Double VPN Core can be withdrawn.")
    now_iso = utcnow().isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT promoted, pending_promotion_id FROM core_servers WHERE core_id = ?", (requested_core,)
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Core is not registered.")
        was_promoted = bool(row["promoted"])
        was_pending = bool(row["pending_promotion_id"])
        invalidated_count = close_core_promotion(conn, requested_core, now_iso)
    security_alert(4, "Double VPN Core withdrawn", request=request, details={
        "core_id": requested_core,
        "was_promoted": was_promoted,
        "was_pending": was_pending,
        "invalidated_assignment_count": invalidated_count,
    })
    logger.warning(
        "Double VPN Core %s withdrawn by operator (was_promoted=%s, invalidated_assignments=%d)",
        requested_core, was_promoted, invalidated_count,
    )
    return {
        "ok": True,
        "core_id": requested_core,
        "promoted": False,
        "was_promoted": was_promoted,
        "was_pending": was_pending,
        "invalidated_assignment_count": invalidated_count,
    }

@app.get("/admin/core/promotions")
def admin_list_core_promotions(request: Request, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "list Double VPN Core promotions")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT promotion_id, core_id, promoted_at, evidence_sha256, operator_source_hash,"
            " core_status, management_status, management_checked_at, runtime_ready,"
            " runtime_checked_at, last_heartbeat FROM core_promotion_events "
            "ORDER BY promoted_at DESC, promotion_id DESC LIMIT 200"
        ).fetchall()
    return {"ok": True, "promotions": [dict(row) for row in rows]}

_SSH_KEY_TYPES_FOR_BLOB = ("ssh-ed25519", "ssh-rsa", "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384",
                           "ecdsa-sha2-nistp521", "sk-ssh-ed25519@openssh.com", "sk-ecdsa-sha2-nistp256@openssh.com",
                           "ssh-dss")
_SITE_AI_TUNNEL_PREFIX = 'restrict,port-forwarding,permitlisten="127.0.0.1:'
_SITE_AI_TUNNEL_LOCK = threading.Lock()
# H0 (D3): the Core's site-AI reverse tunnel logs in as this dedicated non-root
# account. Its authorized keys file is the one this endpoint writes; root's
# authorized_keys is outside the hub unit's writable set. The account's sshd
# Match block (harden_control_sshd) allows remote forwarding and nothing else.
SITE_AI_TUNNEL_SSH_USER = "wins-site-ai"


def _site_ai_ownership_path() -> str:
    return os.getenv("SITE_AI_TUNNEL_OWNERSHIP_FILE", "/root/vpn_auth/site_ai_tunnel_owned.json")


def _site_ai_authorized_keys_path() -> str:
    return os.getenv("SITE_AI_TUNNEL_AUTHORIZED_KEYS_FILE", "/var/lib/wins-site-ai-tunnel/authorized_keys")


@contextmanager
def _site_ai_ownership_flock():
    lock_path = _site_ai_ownership_path() + ".lock"
    fd = os.open(lock_path, os.O_CREAT | os.O_RDWR, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        yield
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


def _site_ai_owned_lines() -> set:
    # The exact authorized_keys lines this endpoint wrote (stripped). Only a
    # line that also carries the endpoint's restricted prefix counts, so a
    # tampered record cannot claim an unrestricted operator line.
    path = _site_ai_ownership_path()
    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except FileNotFoundError:
        return set()
    except (OSError, ValueError):
        # Unreadable ownership record: own nothing, so nothing is removed.
        return set()
    lines = data.get("lines") if isinstance(data, dict) else None
    if not isinstance(lines, list):
        return set()
    return {l.strip() for l in lines if isinstance(l, str) and _is_site_ai_tunnel_line(l)}


def _site_ai_save_owned_lines(lines: set) -> None:
    path = _site_ai_ownership_path()
    tmp = f"{path}.tmp.{os.getpid()}"
    fd = os.open(tmp, os.O_CREAT | os.O_WRONLY | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump({"lines": sorted(l.strip() for l in lines)}, handle)
    os.replace(tmp, path)


def _site_ai_key_blob_valid(key_type: str, blob: str) -> bool:
    # The blob must be real base64 whose embedded wire-format type string
    # equals the declared type, with a sane size (ed25519 is exactly 51 bytes).
    if not re.fullmatch(r"[A-Za-z0-9+/]+={0,2}", blob or ""):
        return False
    try:
        raw = base64.b64decode(blob, validate=True)
    except Exception:
        return False
    if len(raw) < 4:
        return False
    tlen = int.from_bytes(raw[:4], "big")
    if tlen <= 0 or 4 + tlen > len(raw) or raw[4:4 + tlen] != key_type.encode("ascii"):
        return False
    if key_type == "ssh-ed25519":
        return len(raw) == 51
    if key_type == "ssh-rsa":
        return 200 <= len(raw) <= 2048
    return False


def _authorized_key_line_blob(line: str) -> str:
    # The base64 key blob of an authorized_keys line (the field after the key
    # type, whether or not options precede it), or "" if none.
    fields = line.strip().split()
    for i, field in enumerate(fields[:-1]):
        if field in _SSH_KEY_TYPES_FOR_BLOB:
            return fields[i + 1]
    return ""


def _is_site_ai_tunnel_line(line: str) -> bool:
    return line.strip().startswith(_SITE_AI_TUNNEL_PREFIX)


@app.post("/api/v1/site-ai/tunnel-key")
def register_site_ai_tunnel_key(payload: SiteAiTunnelKeyRequest, request: Request, x_core_token: str = Header(...)):
    # H-2: routine core-scoped endpoint -- core-token-only, never the
    # fleet-wide admin token (see require_core_token).
    core_id = (payload.core_id or DOUBLE_VPN_CORE_ID).strip() or DOUBLE_VPN_CORE_ID
    with get_db() as conn:
        ensure_schema(conn)
        require_core_token(conn, core_id, x_core_token, request, "site AI tunnel key registration")
    key = (payload.public_key or "").strip()
    parts = key.split()
    if len(parts) < 2 or parts[0] not in {"ssh-ed25519", "ssh-rsa"} or not _site_ai_key_blob_valid(parts[0], parts[1]):
        raise HTTPException(status_code=400, detail="Invalid SSH public key.")
    listen_port = int(payload.listen_port or 11435)
    if listen_port < 1024 or listen_port > 65535:
        raise HTTPException(status_code=400, detail="Invalid tunnel listen port.")
    # The hub, not the caller, chooses the loopback port this key may bind:
    # it is the port of SITE_AI_LOCAL_ENDPOINT, the only address the hub ever
    # calls through this tunnel. A core token that could name any port could
    # squat a hub loopback service port (the hub API itself listens on
    # 127.0.0.1:8000) across a hub restart and impersonate it to nginx.
    try:
        expected_port = urllib.parse.urlsplit(SITE_AI_LOCAL_ENDPOINT).port
    except ValueError:
        expected_port = None
    if expected_port is None:
        raise HTTPException(status_code=503, detail="Site AI local endpoint has no explicit port.")
    if listen_port != expected_port:
        raise HTTPException(status_code=400, detail="Tunnel listen port must match the hub site-AI endpoint port.")
    label = re.sub(r"[^A-Za-z0-9_.@:-]+", "-", (payload.label or "wins-core-site-ai").strip())[:80] or "wins-core-site-ai"
    # H0 (D3): the dedicated forwarding account's keys file, never root's.
    # sshd reads it as that account, so it is root-owned 0644 in a root-owned
    # 0755 directory, which StrictModes accepts.
    authorized = Path(_site_ai_authorized_keys_path())
    ssh_dir = authorized.parent
    ssh_dir.mkdir(mode=0o755, parents=True, exist_ok=True)
    key_blob = parts[1]
    restricted_line = (
        f'restrict,port-forwarding,permitlisten="127.0.0.1:{listen_port}" '
        f'{parts[0]} {parts[1]} {label}'
    )
    # Ownership: this endpoint may remove ONLY the exact lines it wrote
    # itself, as recorded verbatim in its own ownership record. Every other
    # line (operator keys, operator-managed forwarding lines, even one that
    # reuses a site-AI blob) is kept byte for byte, and a request that names a
    # key present in any line it does not own is refused, so a core token can
    # never remove or re-scope an operator line.
    with _SITE_AI_TUNNEL_LOCK, _site_ai_ownership_flock():
        existing = authorized.read_text(encoding="utf-8", errors="ignore").splitlines() if authorized.exists() else []
        owned = _site_ai_owned_lines()
        for line in existing:
            if line.strip() not in owned and _authorized_key_line_blob(line) == key_blob:
                raise HTTPException(status_code=409, detail="This key is already authorized for another purpose.")
        kept = [line for line in existing if line.strip() not in owned]
        kept.append(restricted_line)
        # Record the new line before writing, so a crash between the two
        # writes can only leave an orphaned restricted line, never let a later
        # call treat an operator line as owned.
        _site_ai_save_owned_lines(owned | {restricted_line})
        tmp_path = ssh_dir / f".authorized_keys.site-ai.{os.getpid()}"
        tmp_path.write_text("\n".join(kept).strip() + "\n", encoding="utf-8")
        os.chmod(tmp_path, 0o644)
        os.replace(tmp_path, authorized)
        os.chmod(ssh_dir, 0o755)
        os.chmod(authorized, 0o644)
        _site_ai_save_owned_lines({restricted_line})
    ssh_host_keys = []
    for host_key_path in sorted(Path("/etc/ssh").glob("ssh_host_*_key.pub")):
        host_key_parts = host_key_path.read_text(encoding="utf-8", errors="ignore").strip().split()
        if (
            len(host_key_parts) >= 2
            and host_key_parts[0] in {"ssh-ed25519", "ssh-rsa", "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521"}
            and re.fullmatch(r"[A-Za-z0-9+/=]+", host_key_parts[1])
        ):
            ssh_host_keys.append(f"{host_key_parts[0]} {host_key_parts[1]}")
    if not ssh_host_keys:
        raise HTTPException(status_code=503, detail="Control Hub SSH host keys are unavailable.")
    return {
        "ok": True,
        "listen": f"127.0.0.1:{listen_port}",
        "label": label,
        "ssh_user": SITE_AI_TUNNEL_SSH_USER,
        "ssh_host_keys": ssh_host_keys,
    }

@app.get("/api/v1/core/assignments")
def core_assignments(request: Request, core_id: str = DOUBLE_VPN_CORE_ID, x_core_token: str = Header(...)):
    # H-2: routine core-scoped endpoint -- core-token-only, never the
    # fleet-wide admin token (see require_core_token).
    requested_core = (core_id or DOUBLE_VPN_CORE_ID).strip() or DOUBLE_VPN_CORE_ID
    with get_db() as conn:
        ensure_schema(conn)
        require_core_token(conn, requested_core, x_core_token, request, "core assignments")
        assignments = active_core_assignment_payloads(conn, requested_core)
        relay = core_relay_list_payload(conn, requested_core)
    response = {"ok": True, "core_id": requested_core, "assignments": assignments}
    if relay is not None:
        # w3r/1: static per exit, no device data. ABSENT otherwise, so the
        # response is byte for byte what it was before this lane.
        response["relay"] = relay
    return response

@app.post("/api/v1/nodes/heartbeat")
def heartbeat(payload: NodeHeartbeat, request: Request):
    with get_db() as conn:
        ensure_schema(conn)
        # H-9: heartbeat is node-token-only -- the global admin token is never
        # accepted here, so a node's heartbeat credential cannot be used to
        # impersonate any other node or reach an /admin/ route.
        require_node_token(conn, payload.slug, payload.secret_token, request, "node heartbeat")
        row = conn.execute(
            "SELECT retired_at FROM nodes WHERE slug = ?", (payload.slug,)
        ).fetchone()
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="Retired node cannot heartbeat until restored")
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        mark_stale_nodes_offline(conn)
        conn.execute("UPDATE nodes SET status = ?, last_heartbeat = ? WHERE slug = ? AND retired_at IS NULL", (payload.status, utcnow().isoformat(), payload.slug))
    winn3_schedule_auto_provision(payload.slug)
    return {"ok": True}

@app.post("/api/v1/nodes/{slug}/heartbeat")
async def heartbeat_path(slug: str, payload: NodeHeartbeat, request: Request):
    payload.slug = slug
    return await asyncio.to_thread(heartbeat, payload, request)

@app.post("/admin/nodes/free-access")
def admin_set_node_free_access(
    request: Request,
    slug: str = Form(...),
    enabled: bool = Form(...),
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "set node free access")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT slug, retired_at FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="Retired node must be restored before changing tier")
        conn.execute("UPDATE nodes SET free_access_enabled = ? WHERE slug = ?", (1 if enabled else 0, node_slug))
        free_slugs = current_free_node_slugs(conn)
    return {"ok": True, "slug": node_slug, "free_access_enabled": bool(enabled), "free_node_slugs": free_slugs}

@app.post("/admin/nodes/direct-awg")
def admin_set_node_direct_awg(
    request: Request,
    slug: str = Form(...),
    enabled: bool = Form(...),
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "set node direct AWG")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT slug FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")
        conn.execute(
            "UPDATE nodes SET direct_awg_admin_override = ?, "
            "direct_awg_enabled = CASE WHEN ? THEN COALESCE(direct_awg_node_enabled, direct_awg_enabled, 1) ELSE 0 END "
            "WHERE slug = ?",
            (1 if enabled else 0, 1 if enabled else 0, node_slug),
        )
        effective = conn.execute(
            "SELECT direct_awg_enabled FROM nodes WHERE slug = ?", (node_slug,)
        ).fetchone()["direct_awg_enabled"]
    return {"ok": True, "slug": node_slug, "direct_awg_enabled": bool(effective)}

# --- Winn Protocol v3 node capability gate ----------------------------------
#
# WHY THIS ENDPOINT EXISTS. register_node() deliberately refuses to write
# protocol_version and protocol_params_json (see the block comment there): a
# node self-asserting "winn/3" would have the hub advertise a protocol on the
# node's own say-so, and protocol_params_json is handed to clients verbatim, so
# accepting it there would let one node token inject arbitrary JSON into every
# config issued for that node. That comment closes with "Setting these stays an
# operator action (direct SQL today) until v3 brings its own gated, validated
# path." THIS IS THAT PATH, and it is the same shape as /admin/nodes/tier:
# admin-token gated, writes only columns the serving path reads, every
# transition reversible, and no hand-edited database.
#
# WHAT IT ADDS OVER DIRECT SQL, which is the whole point:
#
#   * VALIDATION. validate_winn3_protocol_params refuses anything the shipped
#     client would refuse. Direct SQL cannot: a single mistyped key in the blob
#     is a refused connection for EVERY client of that node, with the client
#     showing "please update the app" and nothing on the hub logging a thing.
#   * READINESS. A node whose endpoint is not an IP literal, or whose
#     obfuscation profile is not winn/3-classifiable, cannot serve winn/3 at
#     all -- and neither fact is visible from the protocol columns. Both are
#     checked here, before the flip, and named in the response.
#   * REVERSIBILITY IN ONE CALL. enabled=false restores winn/1 with no params,
#     which is byte-for-byte the pre-change state of the row. It is never
#     refused, whatever the node's readiness -- a rollback that can fail is not
#     a rollback.
#
# The node row is otherwise untouched: no identity attribute, no credential,
# no tier, no management_status. Turning winn/3 on and off cannot change which
# clients a node serves, only which protocol it is advertised as speaking.
@app.post("/admin/nodes/winn3")
def admin_set_node_winn3(
    request: Request,
    slug: str = Form(...),
    enabled: bool = Form(...),
    protocol_params_json: str = Form(default=""),
    path_mtu: str = Form(default=""),
    carrier_classes: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "set node winn/3 capability")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT *"
            " FROM nodes WHERE slug = ?",
            (node_slug,),
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")

        # The standalone migration plan (added 2026-08-10, ds_iosconfig3).
        # Form fields are the new full state of the two columns: an empty
        # path_mtu stores NULL (the fleet default), an empty carrier_classes
        # stores NULL (no plan -- refused for a standalone node below). The
        # effective values are what the served plan would actually be, which is
        # the only quantity the client's engine ever sees.
        plan_path_mtu_raw = (path_mtu or "").strip()
        plan_classes = parse_winn3_carrier_classes(carrier_classes)
        stored_path_mtu: Optional[int] = None
        if plan_path_mtu_raw:
            try:
                parsed_path_mtu = int(plan_path_mtu_raw)
            except (TypeError, ValueError):
                raise HTTPException(
                    status_code=400,
                    detail="path_mtu is not a valid integer.",
                ) from None
            if not (WINN3_MIN_MTU <= parsed_path_mtu <= WINN3_MAX_MTU):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"path_mtu {parsed_path_mtu} is outside the accepted "
                        f"range of {WINN3_MIN_MTU}..{WINN3_MAX_MTU}."
                    ),
                )
            stored_path_mtu = parsed_path_mtu
        for class_name in plan_classes:
            if class_name not in WINN3_CARRIER_CLASSES:
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"carrier_classes entry {class_name!r} is not a known "
                        "carrier class (known: "
                        + ", ".join(WINN3_CARRIER_CLASSES)
                        + ")."
                    ),
                )
        if not stored_path_mtu:
            effective_plan_mtu = WINN3_DEFAULT_PATH_MTU
        else:
            effective_plan_mtu = stored_path_mtu

        if not enabled:
            winn3_bump_deployment_generation(conn, node_slug)
            conn.execute("UPDATE nodes SET winn3_operator_hold=1 WHERE slug=?", (node_slug,))
            # The rollback. Deliberately does no validation and checks no
            # readiness: it restores the shipping default, which is always
            # safe and always available. The two plan columns are cleared with
            # it so a rollback genuinely returns the node to the shipping
            # default rather than leaving half a registration behind.
            conn.execute(
                "UPDATE nodes SET protocol_version = ?, protocol_params_json = NULL,"
                " path_mtu = NULL, carrier_classes = NULL WHERE slug = ?",
                (WINN_PROTOCOL_V1, node_slug),
            )
            logger.info("node %s protocol set to %s", node_slug, WINN_PROTOCOL_V1)
            return {
                "ok": True,
                "slug": node_slug,
                "protocol_version": WINN_PROTOCOL_V1,
                "protocol_params_keys": [],
                "path_mtu": None,
                "carrier_classes": "",
            }

        if row["winn3_operator_hold"]:
            # Explicit authorization clears the sticky hold. The automatic
            # path still needs its prospective-row canary before a carrier flip.
            conn.execute("UPDATE nodes SET winn3_operator_hold=0 WHERE slug=?", (node_slug,))
            return {"ok": True, "slug": node_slug, "operator_hold": False,
                    "protocol_version": row["protocol_version"], "hold_cleared": True}
        raw = (protocol_params_json or "").strip()
        if not raw:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Rejected: production winn/3 registration requires the exact "
                    "standalone carrier winn3 and complete nonempty protocol params."
                ),
            )
        try:
            candidate = json.loads(raw)
        except Exception:
            raise HTTPException(
                status_code=400,
                detail="protocol_params_json is not valid JSON.",
            ) from None
        try:
            params = require_production_winn3_registration_params(candidate)
        except Winn3ContractError as exc:
            # Reason and key NAMES only. The values are endpoints and profile
            # identifiers and must not reach a response body or a log line.
            logger.warning(
                "refused winn/3 registration for node %s (reason=%s keys=%s)",
                node_slug, exc.reason, ",".join(exc.keys) or "-",
            )
            raise HTTPException(
                status_code=400,
                detail=(
                    "Rejected: the shipped client would refuse these winn/3 parameters "
                    f"(reason={exc.reason}"
                    + (f" keys={','.join(exc.keys)}" if exc.keys else "")
                    + ")."
                ),
            ) from None

        # Readiness, checked BEFORE the write. Both of these are node facts the
        # protocol columns cannot express, and either one makes every winn/3
        # connection to this node refuse.
        try:
            obfuscation = parse_obfuscation(row["obfuscation_json"])
        except ObfuscationProfileError as exc:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Node has no usable obfuscation registration "
                    f"(reason={exc.reason}); it cannot serve winn/1 either. "
                    "Re-register the node first."
                ),
            ) from None
        blockers = []
        if not winn3_is_ip_literal_endpoint(row["endpoint"]):
            blockers.append("endpoint_not_ip_literal")
        obfuscation_problems = winn3_obfuscation_problems(obfuscation)
        if obfuscation_problems:
            blockers.append(
                "obfuscation_not_classifiable:" + ",".join(obfuscation_problems)
            )
        if blockers:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Node is not able to serve winn/3 yet: "
                    + "; ".join(blockers)
                    + ". No node record was changed."
                ),
            )

        # THE STANDALONE PLAN GATE, at REGISTRATION (added 2026-08-10,
        # ds_iosconfig3). A standalone node (carrier=winn3) with a plan the
        # client's NewSizing would refuse can never serve winn/3 to anyone: the
        # client fails closed with no fallback, and `path_mtu` in the
        # 1280..1420 dead zone is the never-promotes session wearing the same
        # clothes. The hub refuses the REGISTRATION now -- deliberately before
        # the write -- so it never stores a node it cannot serve. Relay
        # carriers never read either field, so there is nothing to gate, but
        # the SHAPE of a recorded plan is still validated above.
        if params.get("carrier", WINN3_CARRIER_DIRECT_AWG) == WINN3_CARRIER_WINN3:
            plan_ok, plan_reason = winn3_standalone_plan_servable(
                effective_plan_mtu, plan_classes
            )
            if not plan_ok:
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "Rejected: a standalone winn/3 node needs a migration "
                        "plan the client can actually run (reason="
                        + plan_reason
                        + "). The fleet default path MTU is "
                        + str(WINN3_DEFAULT_PATH_MTU)
                        + "; a plan at or above it containing udp, with any "
                        "additional classes among "
                        + ", ".join(WINN3_CARRIER_CLASSES)
                        + " is required."
                    ),
                )

        stored = json.dumps(params, sort_keys=True, separators=(",", ":"))
        conn.execute(
            "UPDATE nodes SET protocol_version = ?, protocol_params_json = ?,"
            " path_mtu = ?, carrier_classes = ? WHERE slug = ?",
            (WINN_PROTOCOL_V3, stored, stored_path_mtu,
             ",".join(plan_classes) or None, node_slug),
        )
        logger.info(
            "node %s protocol set to %s (carrier=%s param_keys=%s path_mtu=%s)"
            " classes=%s",
            node_slug, WINN_PROTOCOL_V3,
            params.get("carrier", WINN3_CARRIER_DIRECT_AWG),
            ",".join(sorted(params.keys())) or "-",
            effective_plan_mtu,
            ",".join(plan_classes) or "-",
        )
    # Design 10.3 (P-12): after the operator carrier transaction has committed,
    # request the post-flip proof of the live served path now instead of at the
    # next 15 minute timer. It never fails the flip.
    try:
        request_winn3_canary_proof(node_slug, "carrier-flip")
    except Exception as exc:
        logger.error("winn3 post-flip canary request failed: %s", type(exc).__name__)
    return {
        "ok": True,
        "slug": node_slug,
        "protocol_version": WINN_PROTOCOL_V3,
        "protocol_params_keys": sorted(params.keys()),
        "carrier": params.get("carrier", WINN3_CARRIER_DIRECT_AWG),
        "spa_required": winn3_params_require_spa(params),
        "path_mtu": stored_path_mtu,
        "effective_path_mtu": effective_plan_mtu,
        "carrier_classes": ",".join(plan_classes) or "",
        # Named rather than assumed: a non-direct-awg carrier needs
        # winn-carrier-server and fourteen credential files ON THE NODE, and
        # the hub cannot see any of that from here.
        "requires_node_side_carrier_server": (
            params.get("carrier", WINN3_CARRIER_DIRECT_AWG) != WINN3_CARRIER_DIRECT_AWG
        ),
    }

@app.get("/admin/nodes/winn3")
def admin_list_node_winn3(request: Request, x_admin_token: str = Header(...)):
    """Per-node winn/3 readiness. The pre-flight for a deploy night.

    Node-scoped only. It cannot tell you whether any given CLIENT will be
    served winn/3, because that also depends on the client's advertised
    capabilities and on whether the request asked for stealth mode.
    """
    require_admin_token(x_admin_token, request, "list node winn/3 capability")
    with get_db() as conn:
        ensure_schema(conn)
        # winn3_node_readiness reads path_mtu, carrier_classes and
        # winn3_descriptor_json off the row via _node_field /
        # winn3_stored_descriptor. A sqlite3.Row that did not SELECT those
        # columns treats them as absent: path_mtu becomes the fleet default,
        # carrier_classes becomes [], the descriptor becomes {}, and a fully
        # provisioned standalone node always reports path-mtu-plan-empty plus
        # winn3_descriptor_missing_or_invalid. Do not drop these columns.
        # SYNC-03/15/16: the canary columns (winn3_canary_is_fresh) and the
        # gateway report (winn3_gateway_report_blockers) are read off the row
        # the same way; without them every node reads canary-not-fresh and
        # gateway-not-reported whatever its real state.
        # H3: a live proof must also follow the completion, the release and the
        # carrier flip, so those three markers are read the same way.
        rows = conn.execute(
            "SELECT slug, name, endpoint, obfuscation_json, protocol_version,"
            " protocol_params_json, path_mtu, carrier_classes,"
            " winn3_descriptor_json, winn3_canary_status, winn3_canary_ok_at,"
            " winn3_identity_sha256, deployment_generation, winn3_canary_identity_sha256,"
            " winn3_canary_seq, winn3_canary_generation,"
            " deployment_completed_at, deployment_released_at, winn3_carrier_flipped_at,"
            " winn3_gateway_report_json FROM nodes ORDER BY LOWER(slug) ASC"
        ).fetchall()
        report = []
        collisions = winn3_canary_device_collisions(conn)
        in_use = winn3_inner_addresses_in_use(conn)
        inner_pools = {}
        for row in rows:
            try:
                obfuscation = parse_obfuscation(row["obfuscation_json"])
            except ObfuscationProfileError:
                obfuscation = {}
            entry = winn3_node_readiness(row, obfuscation, canary_collisions=collisions)
            entry["name"] = row["name"]
            # SYNC-06 guard (Q2 Stage 0): this node's pool and its free count.
            node_pool = winn3_node_inner_slice(row)
            usage = winn3_inner_slice_usage(conn, node_pool, in_use) if node_pool is not None else None
            entry["inner_pool"] = usage["pool"] if usage else None
            entry["winn3_inner_free"] = usage["free"] if usage else None
            if usage:
                inner_pools[usage["pool"]] = usage
            report.append(entry)
    return {
        "ok": True,
        "known_protocol_params": sorted(WINN3_KNOWN_PROTOCOL_PARAMS),
        "supported_carriers": list(WINN3_SUPPORTED_CARRIERS),
        "nodes": report,
        # SYNC-06 guard: every node pool in use, keyed by its CIDR.
        "inner_pools": inner_pools,
    }


# WHY THIS ENDPOINT EXISTS, and why it does not sign anything.
#
# A winn/3 client cannot reach a standalone v3 gateway without a descriptor
# naming it: the gateway's static X25519 key, its GatewayID, its admission
# secret, its tag length, its padding policy and its freshness parameters are
# ALL unnegotiated (winn3/core/params.go:238-243 says so in terms -- "there is
# no field to carry them and no error signal to report a mismatch, so a client
# and a gateway that disagree produce a rejection indistinguishable from a
# dropped packet"). The descriptor is the only channel that carries them.
#
# The hub app holds NO signing key and cannot read one. It holds the PUBLIC
# halves of g1..g3 and accepts only an envelope that already verifies. The
# active slot's private key lives in the separate signer service
# (wins-descriptor-signer). New or changed identities require a matching
# unused t1 ticket and verification of the node's signed identity. Renewal
# uses the retained payload within its renewal window and per-slug limit.
# Normal fleet quotas apply unless a ticketed identity issuance spends an
# operator-granted recovery allowance. The reasoning is the
# announcement lane's, at a larger blast radius: /admin/* is one fleet-wide
# shared token, and a forged descriptor is not defacement -- it is an
# attacker's static key, admission secret and endpoint delivered to a client as
# authentic. A leaked admin token must be able to WITHHOLD gateway material,
# never to MINT it outside that policy.
#
# What a leaked token CAN still do, and what stops it:
#   * withhold  -- a client with no descriptor simply has no standalone v3.
#                  Non-fatal by design; see the handoff on refusal semantics.
#   * replay    -- reinstating a RETIRED descriptor would resurrect a burnt
#                  admission secret. `seq` is strictly increasing per node and
#                  enforced below, which is the only defence against this and
#                  is why seq is inside the signed bytes.
#   * clear     -- enabled=false. Reversible, never refused, and it costs the
#                  fleet nothing because the descriptor is additive.
#   * ask the signer to sign: renewal uses the retained identity without a
#     new ticket. New or changed identities require the matching unused t1
#     ticket. Renewal limits, normal fleet quotas and any operator-granted
#     recovery allowance apply. The token cannot read the signing key.
def winn3_store_descriptor(conn: sqlite3.Connection, row: Any, payload_b64: str, signature_b64: str) -> tuple:
    """Shared validated store. The caller owns the writer transaction."""
    node_slug = row["slug"]
    payload_b64 = (payload_b64 or "").strip()
    signature_b64 = (signature_b64 or "").strip()
    if not payload_b64 or not signature_b64:
        raise HTTPException(
            status_code=400,
            detail="Both descriptor_payload_b64 and descriptor_sig_b64 are required.",
        )
    try:
        payload_bytes = base64.b64decode(payload_b64, validate=True)
        signature_bytes = base64.b64decode(signature_b64, validate=True)
    except Exception:
        raise HTTPException(
            status_code=400,
            detail="descriptor_payload_b64 / descriptor_sig_b64 must be base64.",
        ) from None
    if len(payload_bytes) > WINN3_MAX_DESCRIPTOR_BYTES:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Descriptor payload is {len(payload_bytes)} bytes, over the "
                f"{WINN3_MAX_DESCRIPTOR_BYTES}-byte ceiling."
            ),
        )
    try:
        decoded = json.loads(payload_bytes.decode("utf-8"))
    except Exception:
        raise HTTPException(
            status_code=400,
            detail="Descriptor payload is not UTF-8 JSON.",
        ) from None

    # Validate BEFORE verifying, so that a well-formed-but-wrong descriptor
    # reports the field that is wrong instead of an opaque signature
    # failure. Both run; neither is skipped.
    try:
        descriptor = validate_winn3_descriptor_payload(decoded, slug=node_slug)
    except Winn3ContractError as exc:
        # Reason and field NAMES only. `endpoint` is a node address and
        # `admission_secret` is the per-gateway secret.
        logger.warning(
            "refused winn/3 descriptor for node %s (reason=%s fields=%s)",
            node_slug, exc.reason, ",".join(exc.keys) or "-",
        )
        raise HTTPException(
            status_code=400,
            detail=(
                "Rejected: descriptor is not one this hub will serve "
                f"(reason={exc.reason}"
                + (f" fields={','.join(exc.keys)}" if exc.keys else "")
                + ")."
            ),
        ) from None
    try:
        accepted_slot = winn3_verify_descriptor_signature(
            payload_bytes, signature_bytes, descriptor["kid"]
        )
    except Winn3ContractError as exc:
        logger.warning(
            "refused winn/3 descriptor for node %s (reason=%s fields=%s)",
            node_slug, exc.reason, ",".join(exc.keys) or "-",
        )
        raise HTTPException(
            status_code=400,
            detail=f"Rejected: descriptor signature (reason={exc.reason}).",
        ) from None

    ledger = parse_winn3_admission_ledger(
        row["winn3_admission_json"] if "winn3_admission_json" in row.keys() else None
    )
    previous_descriptor = winn3_stored_descriptor(row)
    sequence_floor = winn3_admission_sequence_floor(previous_descriptor, ledger)
    # ROLLBACK DEFENCE. Strictly increasing across both a currently served
    # descriptor and a descriptor that enabled=false has withheld. A
    # captured envelope whose admission secret may already be burnt must
    # never become current again merely because serving was disabled.
    if descriptor["seq"] <= sequence_floor:
        raise HTTPException(
            status_code=409,
            detail=(
                "Rejected: descriptor seq must strictly increase "
                f"(stored floor={sequence_floor}). No node record was changed."
            ),
        )

    now = utcnow()
    current = ledger.get("current") if isinstance(ledger.get("current"), dict) else {}
    new_ledger: dict = {
        "sequence_floor": descriptor["seq"],
        "current": {
            "generation": descriptor["admission_gen"],
            "seq": descriptor["seq"],
            "ttl_s": descriptor["_ttl_s"],
            "promoted_at": now.isoformat(),
        }
    }
    rotated = False
    previous_generation = (
        previous_descriptor.get("admission_gen")
        if previous_descriptor else current.get("generation")
    )
    previous_seq = (
        previous_descriptor.get("seq")
        if previous_descriptor else current.get("seq")
    )
    previous_ttl = (
        previous_descriptor.get("_ttl_s")
        if previous_descriptor else current.get("ttl_s")
    )
    if (isinstance(previous_generation, int)
            and previous_generation != descriptor["admission_gen"]):
        # A generation change is a ROTATION. The previous generation stays
        # on the books, with the ttl it was issued under, because that ttl
        # is what bounds how long a cached config may still be handing it
        # to a client.
        rotated = True
        new_ledger["previous"] = {
            "generation": previous_generation,
            "seq": previous_seq,
            "ttl_s": previous_ttl,
            "promoted_at": str(current.get("promoted_at") or ""),
        }
    elif ((previous_descriptor or current)
            and isinstance(ledger.get("previous"), dict)):
        # Same generation, re-issued (e.g. a longer ttl). An in-flight
        # rotation must NOT be forgotten by a re-issue, or the retirement
        # floor for the old key would silently disappear.
        new_ledger["previous"] = ledger["previous"]
        new_ledger["current"]["promoted_at"] = str(
            current.get("promoted_at") or now.isoformat()
        )

    # B-02 (Sol audit, 2026-08-28): a rotation may not CLAIM an inner
    # address the hub has already issued to a device. The allocator
    # reserves router/resolver addresses in the forward direction (a
    # stored descriptor keeps its claim), but the STORE path never
    # checked the reverse: a valid higher-sequence signed rotation
    # naming an issued device's inner_router_v4 was accepted, and every
    # session for that device then collided with its own next hop.
    # Refuse the rotation; the operator re-issues it with addresses the
    # pool still owns. Names no device identifiers in the error.
    _collision_row = conn.execute(
        "SELECT device_id FROM devices WHERE winn3_inner_v4 IN (?, ?)",
        (descriptor["inner_router_v4"], descriptor["inner_resolver_v4"]),
    ).fetchone()
    if _collision_row is not None:
        raise HTTPException(
            status_code=409,
            detail=(
                "descriptor-claims-issued-device-address: the "
                "inner_router_v4/inner_resolver_v4 in this descriptor is "
                "already allocated to a device. Re-issue the descriptor "
                "with addresses the pool still owns, or de-provision the "
                "device first (B-02)."
            ),
        )

    conn.execute(
        "UPDATE nodes SET winn3_descriptor_json = ?, winn3_admission_json = ?, winn3_identity_sha256 = ?"
        " WHERE slug = ?",
        (
            json.dumps(
                {"payload": payload_b64, "sig": signature_b64},
                sort_keys=True, separators=(",", ":"),
            ),
            json.dumps(new_ledger, sort_keys=True, separators=(",", ":")),
            winn3_identity_digest(descriptor),
            node_slug,
        ),
    )
    stored_row = conn.execute(
        "SELECT slug, winn3_descriptor_json, winn3_admission_json FROM nodes"
        " WHERE slug = ?",
        (node_slug,),
    ).fetchone()
    logger.info(
        "node %s winn/3 descriptor stored (kid=%s gen=%s seq=%s rotated=%s)",
        node_slug, accepted_slot, descriptor["admission_gen"],
        descriptor["seq"], rotated,
    )
    return descriptor, accepted_slot, rotated, stored_row

@app.post("/admin/nodes/winn3/descriptor")
def admin_set_node_winn3_descriptor(
    request: Request,
    slug: str = Form(...),
    enabled: bool = Form(...),
    descriptor_payload_b64: str = Form(default=""),
    descriptor_sig_b64: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "set node winn/3 descriptor")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT * FROM nodes WHERE slug = ?",
            (node_slug,),
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")

        if not enabled:
            winn3_bump_deployment_generation(conn, node_slug)
            # The rollback. No validation, no readiness check, never refused:
            # a rollback that can fail is not a rollback. The signed envelope
            # is withheld immediately, while the nonsecret admission ledger is
            # retained as the durable replay floor. Clearing both used to let
            # the same old envelope pass the strictly-increasing check on the
            # next enable, resurrecting a retired admission secret.
            previous_descriptor = winn3_stored_descriptor(row, clock_tolerant=True)
            ledger = parse_winn3_admission_ledger(
                row["winn3_admission_json"]
                if "winn3_admission_json" in row.keys() else None
            )
            sequence_floor = winn3_admission_sequence_floor(
                previous_descriptor, ledger
            )
            if sequence_floor >= 0:
                ledger["sequence_floor"] = sequence_floor
            conn.execute(
                "UPDATE nodes SET winn3_descriptor_json = NULL,"
                " winn3_admission_json = ?, winn3_identity_sha256 = ? WHERE slug = ?",
                (
                    json.dumps(ledger, sort_keys=True, separators=(",", ":"))
                    if ledger else None,
                    winn3_identity_digest(previous_descriptor) if previous_descriptor
                    else row["winn3_identity_sha256"],
                    node_slug,
                ),
            )
            logger.info("node %s winn/3 descriptor cleared", node_slug)
            return {
                "ok": True,
                "slug": node_slug,
                "descriptor": {},
                "rotation": {"phase": "none"},
            }

        descriptor, accepted_slot, rotated, stored_row = winn3_store_descriptor(
            conn, row, descriptor_payload_b64, descriptor_sig_b64)
        winn3_bump_deployment_generation(conn, node_slug)

    rotation = winn3_rotation_state(stored_row)
    return {
        "ok": True,
        "slug": node_slug,
        "accepted_key_slot": accepted_slot,
        "rotated": rotated,
        # Public fields only. The admission secret is returned as a LENGTH.
        "descriptor": winn3_descriptor_public_fields(descriptor),
        "rotation": rotation,
        # Named rather than assumed: the hub cannot see the gateway's key set.
        # Until an operator has installed this generation ON THE GATEWAY, every
        # client served this descriptor seals initiations the gateway silently
        # drops.
        "requires_gateway_side_key_install": True,
    }

@app.get("/api/v1/nodes/{slug}/winn3/descriptor")
def node_winn3_descriptor_view(slug: str, request: Request, x_node_token: str = Header(...)):
    """Node-token-only public descriptor view. No signed secret-bearing bytes."""
    with get_db() as conn:
        ensure_schema(conn)
        require_node_token(conn, slug, x_node_token, request, "node winn3 descriptor view")
        row = conn.execute("SELECT * FROM nodes WHERE slug=?", (slug,)).fetchone()
        if row is None or node_is_retired(row):
            raise HTTPException(status_code=409, detail="Node unavailable.")
        descriptor = winn3_stored_descriptor(row)
        return {"ok": True, "slug": slug, "descriptor": winn3_descriptor_public_fields(descriptor),
                "identity_sha256": winn3_identity_digest(descriptor) if descriptor else "",
                "generation": row["deployment_generation"], "operator_hold": bool(row["winn3_operator_hold"])}

@app.get("/admin/nodes/winn3/descriptor")
def admin_list_node_winn3_descriptors(
    request: Request, x_admin_token: str = Header(...)
):
    """Per-node descriptor and rotation state. The pre-flight for a rotation.

    Returns NO secret. `admission_secret_bytes` is a length; that is the only
    property of it an operator needs to see and the only one that discloses
    nothing.
    """
    require_admin_token(x_admin_token, request, "list node winn/3 descriptors")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT slug, name, endpoint, protocol_version, protocol_params_json,"
            " winn3_descriptor_json, winn3_admission_json FROM nodes"
            " ORDER BY LOWER(slug) ASC"
        ).fetchall()
        report = []
        for row in rows:
            descriptor = winn3_stored_descriptor(row)
            entry = {
                "slug": row["slug"],
                "name": row["name"],
                "has_descriptor": bool(
                    parse_winn3_descriptor_envelope(row["winn3_descriptor_json"])
                ),
                "descriptor_valid": bool(descriptor),
                "descriptor": winn3_descriptor_public_fields(descriptor),
                "rotation": winn3_rotation_state(row),
            }
            # IA-SYNC SYNC-07: when the signed descriptor stops serving, and
            # how long is left, including for one that already expired.
            expiry = winn3_descriptor_expiry(row)
            entry["descriptor_not_after"] = expiry["not_after"]
            entry["descriptor_seconds_left"] = expiry["seconds_left"]
            entry["descriptor_expiry_state"] = expiry["state"]
            report.append(entry)
    ring = sorted(winn3_descriptor_public_keys().keys())
    return {
        "ok": True,
        # Which g-slots this hub can verify against. An empty list means every
        # upload will be refused, which is a BUILD mistake, not an attack, and
        # says so plainly rather than reporting a bad signature.
        "verification_key_slots": ring,
        "verification_available": bool(ring),
        "descriptor_domain": WINN3_DESCRIPTOR_DOMAIN.decode("ascii"),
        "supported_algorithms": list(WINN3_DESCRIPTOR_SUPPORTED_ALGS),
        "max_live_admission_keys": WINN3_MAX_LIVE_ADMISSION_KEYS,
        "max_admission_hmac_budget": WINN3_MAX_ADMISSION_HMAC_BUDGET,
        # BOTH MUST ALWAYS BE EMPTY. The first says no protocol_params key has
        # acquired a name that says it carries key material; the second says
        # every key-shaped descriptor field is on the redaction list. They are
        # reported here rather than only asserted in a test because the person
        # who would break either one is reading this endpoint, not the suite.
        "allowlist_key_shaped_names": winn3_key_shaped_names_in_params_allowlist(),
        "unguarded_descriptor_secret_fields": winn3_unguarded_descriptor_secret_fields(),
        "nodes": report,
    }


class SignerTicketEnvelope(BaseModel):
    payload: str
    sig: str


class SignerTicketPost(BaseModel):
    slug: str
    ticket: SignerTicketEnvelope


@app.post("/admin/nodes/winn3/signer-ticket")
def admin_post_node_winn3_signer_ticket(
    payload: SignerTicketPost,
    request: Request,
    x_admin_token: str = Header(...),
):
    """Store the exact signed t1 ticket bytes (3.8, H4).

    The operator's prepare_subject mints and posts the ticket here during the
    preparation it already performs. The hub re-verifies the bytes (t1
    signature, canonical form, closed field set, enums, lifetime) and stores
    them verbatim. The signer stays the authority for the epoch and the nonce
    at spend; the hub re-verifies the stored bytes again at use (3.17), reading
    go_live and tier from the verified ticket bytes only.
    """
    require_admin_token(x_admin_token, request, "post node winn/3 signer ticket")
    node_slug = str(getattr(payload, "slug", "") or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    # The ticket is posted by prepare_subject BEFORE the node installs, and the
    # nodes row only exists after /api/v1/nodes/bootstrap, so the slug cannot
    # be required to exist. It has the shape a bootstrap grant accepts.
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,39}", node_slug):
        raise HTTPException(status_code=400, detail="slug is invalid.")
    envelope = getattr(payload, "ticket", None)
    payload_b64 = str(getattr(envelope, "payload", "") or "").strip()
    sig_b64 = str(getattr(envelope, "sig", "") or "").strip()
    if not payload_b64 or not sig_b64:
        raise HTTPException(
            status_code=400,
            detail="ticket.payload and ticket.sig are both required.",
        )
    try:
        payload_bytes = base64.b64decode(payload_b64, validate=True)
        signature_bytes = base64.b64decode(sig_b64, validate=True)
    except Exception:
        raise HTTPException(
            status_code=400,
            detail="ticket.payload / ticket.sig must be base64.",
        ) from None
    try:
        winn3_verify_signer_ticket_signature(payload_bytes, signature_bytes)
        ticket = winn3_decode_signer_ticket(payload_bytes, slug=node_slug)
    except Winn3ContractError as exc:
        # Reason and field NAMES only; the values are node addresses.
        logger.warning(
            "refused a signer ticket for node %s (reason=%s fields=%s)",
            node_slug, exc.reason, ",".join(exc.keys) or "-",
        )
        raise HTTPException(
            status_code=400,
            detail=f"Rejected: signer ticket (reason={exc.reason}).",
        ) from None
    with get_db() as conn:
        ensure_schema(conn)
        conn.execute(
            "INSERT OR REPLACE INTO winn3_signer_tickets"
            " (slug, action, epoch, nonce, payload, sig, go_live, tier, not_after, posted_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                node_slug, ticket["action"], ticket["epoch"], ticket["nonce"],
                payload_b64, sig_b64, ticket["go_live"], ticket["tier"],
                ticket["not_after"], utcnow().isoformat(),
            ),
        )
    logger.info(
        "stored the winn/3 signer ticket for node %s (action=%s epoch=%s)",
        node_slug, ticket["action"], ticket["epoch"],
    )
    return {
        "ok": True,
        "slug": node_slug,
        "action": ticket["action"],
        "epoch": ticket["epoch"],
        "nonce": ticket["nonce"],
        "stored": True,
    }


@app.get("/admin/nodes/winn3/signer-ticket")
def admin_get_node_winn3_signer_ticket(
    request: Request,
    slug: str = "",
    x_admin_token: str = Header(...),
):
    """The signer's current ticket epoch, and one slug's stored tickets.

    The operator mints under the epoch the signer itself reports: the app can
    neither read nor write the signer's config (3.8). Without a slug the route
    fails closed when the signer is unreachable; with a slug it lists the
    stored ticket bytes verbatim, for the operator and the later use-time
    re-verification (3.17).
    """
    require_admin_token(x_admin_token, request, "list node winn/3 signer tickets")
    if slug:
        node_slug = slug.strip().lower()
        with get_db() as conn:
            ensure_schema(conn)
            rows = conn.execute(
                "SELECT slug, action, epoch, nonce, payload, sig, go_live, tier,"
                " not_after, posted_at FROM winn3_signer_tickets"
                " WHERE slug = ? ORDER BY posted_at ASC, nonce ASC",
                (node_slug,),
            ).fetchall()
        return {"ok": True, "slug": node_slug, "tickets": [dict(row) for row in rows]}
    status = winn3_signer_status()
    if status is None or not status.get("ok"):
        raise HTTPException(
            status_code=503,
            detail="The descriptor signer is unreachable; the ticket epoch is unknown.",
        )
    return {
        "ok": True,
        "signer_reachable": True,
        "epoch": status.get("epoch"),
        "active_slot": status.get("active_slot"),
        "key_ready": status.get("key_ready"),
        "ledger_present": status.get("ledger_present"),
        "disabled": status.get("disabled"),
        "recovery_pending": status.get("recovery_pending"),
    }


@app.post("/admin/nodes/winn3/admission/retire")
def admin_retire_node_winn3_previous_admission(
    request: Request,
    slug: str = Form(...),
    force: bool = Form(default=False),
    x_admin_token: str = Header(...),
):
    """Close a rotation: drop the PREVIOUS generation from the hub's books.

    This is bookkeeping, not an act on the gateway. The hub cannot remove a key
    from a gateway's key set and does not pretend to; what it can do is refuse
    to tell an operator it is safe before the floor computed in
    winn3_rotation_state has passed, and record that the rotation closed.

    The floor is promoted_at + previous ttl + (2*spread+1)*window. It is a
    FLOOR, not a guarantee: a client that fast-connected from a cache older
    than the ttl and cannot reach the hub still holds the old key. `force`
    exists for the one case that overrides the arithmetic -- a key believed
    LEAKED, where stranding some clients is better than leaving it live -- and
    it says so in the log, because a forced retirement is the one event in this
    whole path that can knock a user offline.
    """
    require_admin_token(x_admin_token, request, "retire node winn/3 admission key")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute(
            "SELECT slug, winn3_descriptor_json, winn3_admission_json FROM nodes"
            " WHERE slug = ?",
            (node_slug,),
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")
        state = winn3_rotation_state(row)
        if state["phase"] != "overlap":
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Node is not mid-rotation (phase={state['phase']}). "
                    "Nothing to retire."
                ),
            )
        if not state["safe_to_retire_previous"] and not force:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Too early: the previous admission key is still reachable "
                    f"from a cached config for another {state['seconds_until_retire']}s "
                    f"(floor {state['retire_after']}). Retiring now would strand "
                    "clients that have not refetched. Pass force=true only if "
                    "the key is believed leaked."
                ),
            )
        ledger = parse_winn3_admission_ledger(
            row["winn3_admission_json"] if "winn3_admission_json" in row.keys() else None
        )
        retired = ledger.pop("previous", {})
        conn.execute(
            "UPDATE nodes SET winn3_admission_json = ? WHERE slug = ?",
            (json.dumps(ledger, sort_keys=True, separators=(",", ":")), node_slug),
        )
        stored_row = conn.execute(
            "SELECT slug, winn3_descriptor_json, winn3_admission_json FROM nodes"
            " WHERE slug = ?",
            (node_slug,),
        ).fetchone()
        logger.info(
            "node %s winn/3 admission generation %s retired (forced=%s)",
            node_slug, retired.get("generation"), bool(force),
        )
    return {
        "ok": True,
        "slug": node_slug,
        "retired_generation": retired.get("generation"),
        "forced": bool(force),
        "rotation": winn3_rotation_state(stored_row),
        # The gateway still holds the key until an operator removes it there.
        # Saying so is the whole value of this response: the hub's books and
        # the gateway's key set are two different things and the gap between
        # them is where a rotation goes wrong.
        "requires_gateway_side_key_removal": True,
    }

WINN3_KEY_DIGEST_RE = re.compile(r"[0-9a-f]{64}")


def parse_winn3_key_digest(value: Optional[str], field: str, *, required: bool) -> Optional[str]:
    """One lowercase-hex SHA-256 digest, or None when optional and absent.

    The refusal names the FIELD and never echoes the value: an operator who
    pastes the wrong file here may be pasting a private key, and a 400 body is
    logged by proxies the hub does not control.
    """
    text = (value or "").strip().lower()
    if not text:
        if required:
            raise HTTPException(status_code=400, detail=f"{field} is required.")
        return None
    if not WINN3_KEY_DIGEST_RE.fullmatch(text):
        raise HTTPException(
            status_code=400,
            detail=f"{field} must be a SHA-256 digest: 64 hex characters.",
        )
    return text


class Winn3RecoveryWaiverRefused(Exception):
    def __init__(self, status_code: int, detail: str):
        super().__init__(detail)
        self.status_code, self.detail = status_code, detail


def winn3_waive_recovery_node(slug: str, reason: str) -> dict:
    """Take one permanently lost, closed node out of authority recovery.

    After a hub rebuild, recovery counts every winn/3 node row and every slug the
    ledger names, and a node leaves it only through a confirmed publication or
    read-back made after recovery began. A machine that is gone for good can
    never give one, so node_auto_reopen_arm stays disarmed and no node can go
    live automatically. This records, in the ledger's own meta, that the
    operator gave the slug up, and only when the evidence allows it: the node row
    is closed (operator_enabled 0) or gone, this process has entered recovery and
    the slug is what holds it open, the ledger shows nothing of the slug still in
    force (winn3_slug_authority_in_force: every entry past its not_after plus the
    skew bound, none lifetime), and the slug has no retired gateway. The waiver is
    re-checked on every read (winn3_recovery_waived_slugs) and a new recovery
    drops it. The slug stays in the charge-journal accounting, so budget trust
    still waits for the charge window. Residual risk: the ledger only knows what
    this hub wrote, so the operator is attesting that the machine is gone."""
    node_slug = str(slug or "").strip().lower()
    note = re.sub(r"[^\x20-\x7e]", " ", str(reason or "")).strip()[:200]
    if not node_slug:
        raise Winn3RecoveryWaiverRefused(400, "Missing node slug.")
    if len(note) < 8:
        raise Winn3RecoveryWaiverRefused(400, "A reason of at least 8 characters is required.")
    now = winn3_clock()
    with get_db() as conn:
        ensure_schema(conn)
        node = conn.execute(
            "SELECT operator_enabled, ssh_host, endpoint FROM nodes WHERE slug = ?", (node_slug,)
        ).fetchone()
        if node is not None and int(node["operator_enabled"] or 0) != 0:
            raise Winn3RecoveryWaiverRefused(
                409, "Node is open. Close it (tier off) before waiving its recovery.")
        with winn3_authority_ledger() as ledger:
            if node_slug in winn3_recovery_waived_slugs(conn, ledger):
                return {"slug": node_slug, "waived": True, "already_waived": True}
        view = winn3_recovery_state(conn, now)
        if not view["paired"]:
            raise Winn3RecoveryWaiverRefused(
                409, "This hub process has not entered authority recovery yet. Retry after the next reconcile pass.")
        if node_slug not in view["unrecovered"]:
            raise Winn3RecoveryWaiverRefused(409, "Node is not holding authority recovery open.")
        hosts = winn3_node_hosts(conn)
        gateway = winn3_gateway_of(
            (node["ssh_host"] or extract_node_host(node["endpoint"] or "")) if node is not None else "")
        with winn3_authority_ledger() as ledger:
            ledger.execute("BEGIN IMMEDIATE")
            if winn3_slug_authority_in_force(ledger, node_slug, now):
                raise Winn3RecoveryWaiverRefused(
                    409, "The authority ledger shows entries for this node still in force: a published "
                         "entry has not passed its not_after plus the skew bound, or never expires.")
            if any(pair[0] == node_slug for pair in winn3_retired_gateways(ledger, hosts, now)):
                raise Winn3RecoveryWaiverRefused(
                    409, "The ledger still names a retired gateway for this slug.")
            row = ledger.execute(
                "SELECT value FROM winn3_ledger_meta WHERE key='recovery_waived'").fetchone()
            try:
                recorded = json.loads(row["value"]) if row is not None else {}
            except ValueError:
                recorded = {}
            if not isinstance(recorded, dict):
                recorded = {}
            recorded[node_slug] = {"reason": note, "at": utcnow().isoformat(), "gateway": gateway}
            ledger.execute(
                "INSERT OR REPLACE INTO winn3_ledger_meta (key, value) VALUES ('recovery_waived', ?)",
                (json.dumps(recorded, sort_keys=True),),
            )
            ledger.commit()
        after = winn3_recovery_state(conn, winn3_clock())
    logger.warning("Winn3 authority recovery waived for node %s: %s", node_slug, note)
    return {"slug": node_slug, "waived": True, "already_waived": False, "reason": note,
            "recovery_complete": bool(after["complete"]), "unrecovered": sorted(after["unrecovered"])}


@app.post("/admin/nodes/winn3/recovery-waive")
def admin_winn3_recovery_waive(
    request: Request,
    slug: str = Form(...),
    confirm_slug: str = Form(default=""),
    reason: str = Form(...),
    x_admin_token: str = Header(...),
):
    """Give up a permanently lost, closed node so authority recovery can finish
    (winn3_waive_recovery_node). Needs the exact confirmation slug and a reason."""
    require_admin_token(x_admin_token, request, "waive winn3 recovery node")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    if (confirm_slug or "").strip().lower() != node_slug:
        raise HTTPException(status_code=400, detail="Confirmation slug does not match.")
    try:
        result = winn3_waive_recovery_node(node_slug, reason)
    except Winn3RecoveryWaiverRefused as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail)
    if not result.get("already_waived"):
        security_alert(2, "winn3 recovery waiver recorded", request=request,
                       details={"slug": node_slug, "reason": result.get("reason", "")})
    return {"ok": True, **result}


@app.post("/admin/nodes/winn3/key-digests")
def admin_record_node_winn3_key_digests(
    request: Request,
    slug: str = Form(...),
    ech_public_key_sha256: str = Form(...),
    ech_config_list_sha256: str = Form(...),
    leaf_spki_sha256: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    """Record one node's cover-set PUBLIC digests; refuse a cross-node duplicate.

    Digests only. The hub cannot verify that a digest is what the node really
    serves (it never sees the key), so this is a uniqueness ledger, not an
    attestation: its value is that a node registering another node's ECH
    public key or leaf SPKI is refused with a 409 and nothing is recorded.
    Re-recording the same node replaces its row (a rotation).
    """
    require_admin_token(x_admin_token, request, "record node winn/3 key digests")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    ech_public = parse_winn3_key_digest(
        ech_public_key_sha256, "ech_public_key_sha256", required=True)
    ech_list = parse_winn3_key_digest(
        ech_config_list_sha256, "ech_config_list_sha256", required=True)
    leaf_spki = parse_winn3_key_digest(
        leaf_spki_sha256, "leaf_spki_sha256", required=False)
    with get_db() as conn:
        ensure_schema(conn)
        if not conn.execute(
            "SELECT slug FROM nodes WHERE slug = ?", (node_slug,)
        ).fetchone():
            raise HTTPException(status_code=404, detail="Node not found.")
        for column, digest, label in (
            ("ech_public_key_sha256", ech_public, "ECH public key"),
            ("leaf_spki_sha256", leaf_spki, "Winn leaf SPKI"),
        ):
            if digest is None:
                continue
            clash = conn.execute(
                f"SELECT slug FROM winn3_node_key_digests"
                f" WHERE {column} = ? AND slug != ?",
                (digest, node_slug),
            ).fetchone()
            if clash:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        f"{label} is already recorded for node {clash['slug']}. "
                        "Per-node keys must be distinct; generate this node's "
                        "own key on the node. Nothing was recorded."
                    ),
                )
        now = utcnow().isoformat()
        try:
            conn.execute(
                "INSERT INTO winn3_node_key_digests"
                " (slug, ech_public_key_sha256, ech_config_list_sha256,"
                "  leaf_spki_sha256, recorded_at)"
                " VALUES (?, ?, ?, ?, ?)"
                " ON CONFLICT(slug) DO UPDATE SET"
                "  ech_public_key_sha256=excluded.ech_public_key_sha256,"
                "  ech_config_list_sha256=excluded.ech_config_list_sha256,"
                "  leaf_spki_sha256=excluded.leaf_spki_sha256,"
                "  recorded_at=excluded.recorded_at",
                (node_slug, ech_public, ech_list, leaf_spki, now),
            )
        except sqlite3.IntegrityError:
            # A concurrent registration took the same digest between the
            # pre-check and the write. The unique index is the real guard.
            raise HTTPException(
                status_code=409,
                detail=(
                    "A key digest collided with another node's at write time. "
                    "Per-node keys must be distinct. Nothing was recorded."
                ),
            ) from None
        logger.info("node %s winn/3 key digests recorded", node_slug)
    return {
        "ok": True,
        "slug": node_slug,
        "ech_public_key_sha256": ech_public,
        "ech_config_list_sha256": ech_list,
        "leaf_spki_sha256": leaf_spki,
        "recorded_at": now,
    }


@app.get("/admin/nodes/winn3/key-digests")
def admin_list_node_winn3_key_digests(request: Request, x_admin_token: str = Header(...)):
    """Every node's recorded public digests, and which nodes have none yet."""
    require_admin_token(x_admin_token, request, "list node winn/3 key digests")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT slug, ech_public_key_sha256, ech_config_list_sha256,"
            " leaf_spki_sha256, recorded_at FROM winn3_node_key_digests"
            " ORDER BY LOWER(slug) ASC"
        ).fetchall()
        unrecorded = [
            r["slug"] for r in conn.execute(
                "SELECT slug FROM nodes WHERE slug NOT IN"
                " (SELECT slug FROM winn3_node_key_digests)"
                " ORDER BY LOWER(slug) ASC"
            ).fetchall()
        ]
    nodes = [dict(r) for r in rows]
    return {
        "ok": True,
        "nodes": nodes,
        "distinct_ech_public_keys": len({n["ech_public_key_sha256"] for n in nodes}),
        "nodes_without_digests": unrecorded,
    }

@app.post("/admin/nodes/tier")
def admin_set_node_tier(
    request: Request,
    slug: str = Form(...),
    tier: str = Form(...),
    evidence_sha256: str = Form(default=""),
    confirm_slug: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    """Withdraw, re-tier, or explicitly promote one data-plane node.

    An off-to-free/premium transition is the manual promotion step. It requires
    positive hub health, an exact confirmation slug, and the digest of frozen
    external gate evidence. The evidence row and latch flip share a transaction.
    """
    require_admin_token(x_admin_token, request, "set node tier")
    node_slug = (slug or "").strip().lower()
    requested = (tier or "").strip().lower()
    evidence_digest = (evidence_sha256 or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    if requested not in {"off", "free", "premium"}:
        raise HTTPException(status_code=400, detail="Tier must be one of: off, free, premium.")
    promotion_id = None
    promoted_at = None
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT slug, retired_at, operator_enabled, status, management_status,"
            " management_checked_at, data_plane_status, data_plane_ok_at,"
            " data_plane_code_revision, deployment_withdrawal_id,"
            # L77: the per-transport proof and the columns that say which
            # transports this node advertises and whether the probe can test them.
            " data_plane_udp_status, data_plane_udp_ok_at,"
            " data_plane_stealth_status, data_plane_stealth_ok_at,"
            " data_plane_stealth_tls_status, data_plane_stealth_tls_ok_at,"
            " protocol_version, direct_awg_enabled, endpoint, wg_port,"
            " stealth_endpoint, stealth_transports, xray_security, xray_path, xray_uuid,"
            " ssh_host, public_key, stealth_public_port, regional_aliases"
            " FROM nodes WHERE slug = ?",
            (node_slug,),
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="Retired node must be restored before changing tier")
        if requested == "off":
            # Withdrawal never needs positive health or evidence. It closes the
            # outer policy latch and live assignments in this transaction.
            close_data_plane_promotion(conn, node_slug, utcnow().isoformat(), cause="operator_off")
        elif node_is_operator_enabled(row):
            # Free <-> premium on an already enabled node is only a tier change,
            # not a second promotion and not a second evidence record.
            conn.execute(
                "UPDATE nodes SET free_access_enabled = ? WHERE slug = ?",
                (1 if requested == "free" else 0, node_slug),
            )
        else:
            if str(row["deployment_withdrawal_id"] or "").strip():
                raise HTTPException(
                    status_code=409,
                    detail="Node remains off while an installer deployment withdrawal is active.",
                )
            if (confirm_slug or "").strip().lower() != node_slug:
                raise HTTPException(
                    status_code=400,
                    detail="confirm_slug must exactly repeat the node slug being promoted.",
                )
            if not re.fullmatch(r"[0-9a-f]{64}", evidence_digest):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "Promoting an off node requires evidence_sha256 to be the "
                        "64-character SHA-256 of the frozen, secret-safe gate evidence."
                    ),
                )
            # The complete readiness gate, off-node gate included: the same
            # function the L84 automatic reopen uses.
            readiness_failures = node_promotion_readiness_failures(conn, row, evidence_digest)
            if readiness_failures:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Node remains off; promotion gates failed: "
                        + "; ".join(readiness_failures)
                        + ". No node record was changed."
                    ),
                )
            promotion_id = secrets.token_hex(16)
            promoted_at = utcnow().isoformat()
            claimed = conn.execute(
                "UPDATE nodes SET operator_enabled = 1, free_access_enabled = ?, "
                "latch_cause = 'operator_promotion', health_closed_at = NULL, "
                "health_closed_reason = NULL "
                "WHERE slug = ? AND COALESCE(operator_enabled, 0) = 0 AND retired_at IS NULL "
                "AND deployment_withdrawal_id IS NULL",
                (1 if requested == "free" else 0, node_slug),
            )
            if claimed.rowcount != 1:
                raise HTTPException(
                    status_code=409,
                    detail="Node promotion state changed concurrently. No promotion evidence was recorded.",
                )
            if not consume_offnode_gate(conn, node_slug, evidence_digest, "promoted"):
                raise HTTPException(
                    status_code=409,
                    detail="Offnode gate record was used concurrently. No promotion was recorded.",
                )
            conn.execute(
                "INSERT INTO node_promotion_events ("
                " promotion_id, slug, promoted_at, tier, evidence_sha256, operator_source_hash,"
                " node_status, management_status, management_checked_at, data_plane_status,"
                " data_plane_ok_at, data_plane_code_revision"
                ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    promotion_id,
                    node_slug,
                    promoted_at,
                    requested,
                    evidence_digest,
                    security_event_hash(request_origin_bucket_value(request)),
                    str(row["status"] or "unknown"),
                    str(row["management_status"] or "unknown"),
                    row["management_checked_at"],
                    str(row["data_plane_status"] or "unknown"),
                    row["data_plane_ok_at"],
                    row["data_plane_code_revision"],
                ),
            )
        current = conn.execute(
            "SELECT free_access_enabled, operator_enabled FROM nodes WHERE slug = ?",
            (node_slug,),
        ).fetchone()
        free_slugs = current_free_node_slugs(conn)
    if promotion_id:
        security_alert(4, "data-plane node promoted", request=request, details={
            "slug": node_slug,
            "promotion_id": promotion_id,
            "evidence_sha256": evidence_digest,
        })
        logger.warning(
            "node %s promoted to %s by operator (promotion_id=%s, evidence_sha256=%s)",
            node_slug, requested, promotion_id, evidence_digest,
        )
    return {
        "ok": True,
        "slug": node_slug,
        "tier": node_tier_label(current),
        "operator_enabled": node_is_operator_enabled(current),
        "free_access_enabled": is_free_node(current),
        "free_node_slugs": free_slugs,
        "promotion_id": promotion_id,
        "promoted_at": promoted_at,
        "evidence_sha256": evidence_digest if promotion_id else None,
    }

