@app.post("/admin/nodes/offnode-gate")
def admin_record_offnode_gate(
    request: Request,
    slug: str = Form(...),
    gate_sha256: str = Form(...),
    node_report: str = Form(...),
    external_evidence_sha256: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    """L46 F2 v3: record a node-side gate result, after verifying it here.

    The hub recomputes everything it can: the node is closed and not retired;
    its closure cleanup is confirmed; the snapshot digest is recomputed from the
    database; the node report (offnode_node_check.sh output) passes the gate
    rules with no AWG peer at all and, for winn/3, an exact snapshot match and a
    gateway started after the file's last change; and gate_sha256 equals the
    canonical digest of (slug, snapshot digest, cleanup confirmation time,
    external evidence digest, SHA-256 of the report bytes). What the hub cannot
    verify is that the report was produced on the node: that rests on the
    operator running the script there.
    """
    require_admin_token(x_admin_token, request, "record offnode gate")
    node_slug = (slug or "").strip().lower()
    digest = (gate_sha256 or "").strip().lower()
    external = (external_evidence_sha256 or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise HTTPException(status_code=400, detail="gate_sha256 must be 64 lowercase hex characters.")
    if external and not re.fullmatch(r"[0-9a-f]{64}", external):
        raise HTTPException(status_code=400, detail="external_evidence_sha256 must be 64 lowercase hex characters.")
    raw = (node_report or "").encode("utf-8")
    if not raw or len(raw) > OFFNODE_GATE_REPORT_MAX_BYTES:
        raise HTTPException(status_code=400, detail="node_report is empty or too large.")
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        node = conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        if node is None:
            raise HTTPException(status_code=404, detail="Node not found.")
        failures = []
        if node_admits_peer(node) or str(node["retired_at"] or "").strip():
            failures.append("node latch is open or the node is retired")
        cleanup = conn.execute("SELECT * FROM node_closure_cleanup WHERE slug = ?", (node_slug,)).fetchone()
        if cleanup is None or cleanup["state"] != "confirmed":
            failures.append("closure cleanup is not confirmed (resync the node first)")
        try:
            expected = offnode_expected_v3_sha256(conn, node_slug)
        except Exception:
            expected = ""
            failures.append("the node's v3 snapshot cannot be computed")
        failures += offnode_node_report_failures(node_report, node["protocol_version"], expected)
        confirmed_at = (cleanup["confirmed_at"] or "") if cleanup is not None else ""
        report_sha = hashlib.sha256(raw).hexdigest()
        if offnode_gate_digest(node_slug, expected, confirmed_at, external, report_sha) != digest:
            failures.append("gate_sha256 does not match the canonical digest of this report and hub state")
        if failures:
            raise HTTPException(status_code=409, detail="Gate not recorded: " + "; ".join(failures))
        recorded_at = utcnow().isoformat()
        conn.execute(
            "INSERT OR REPLACE INTO node_offnode_gates (gate_sha256, slug, recorded_at, cleanup_confirmed_at,"
            " expected_v3_sha256, external_evidence_sha256, node_report, node_report_sha256, used_at, used_for)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL)",
            (digest, node_slug, recorded_at, confirmed_at, expected, external, node_report, report_sha),
        )
    logger.info("off-node gate recorded for node %s (gate %s)", node_slug, digest[:16])
    return {"ok": True, "slug": node_slug, "gate_sha256": digest, "recorded_at": recorded_at}

@app.post("/admin/nodes/retire")
def admin_retire_node(
    request: Request,
    slug: str = Form(...),
    reason: str = Form(default=""),
    confirm_last_servable_node: str = Form(default=""),
    offnode_gate_sha256: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    """Retire one node: withdraw it and release its identity claim, reversibly.

    L46 F2 v3: retirement blanks the management host, after which the hub can
    never clean or check the node again. So it is refused unless the node is
    already closed, its closure cleanup is confirmed, and offnode_gate_sha256
    names a node-side gate record this hub verified (POST
    /admin/nodes/offnode-gate). The record is consumed and the cleanup record
    is kept with state 'retired'.

    Admin node-retirement lane (2026-08-07). The supported answer to step 4 of
    CONTROL_PLANE_REGISTER_IDENTITY_COLLISION_GUARD_20260807.md 6.1 ("if the
    old row genuinely must be retired"), which was direct SQL against a live
    database until now, and to the follow-up named in 6.3.

    Nothing is deleted. See create_node_retirements_table() and the retirement
    block above node_identity_collisions() for what is written and why.
    Reversed by POST /admin/nodes/restore.
    """
    require_admin_token(x_admin_token, request, "retire node")
    node_slug = (slug or "").strip().lower()
    retirement_reason = str(reason or "").strip()[:300]
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    # Pre-flight, read-only and on its own connection, so security_alert() can
    # record a refusal without this request waiting on a transaction it is
    # holding open. The authoritative versions of both checks are re-run inside
    # the write transaction below.
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        servable_before = servable_node_slugs(conn)
    if not row:
        raise HTTPException(status_code=404, detail="Node not found.")
    if node_is_retired(row):
        raise HTTPException(status_code=409, detail="Node is already retired.")
    servable_after = [candidate for candidate in servable_before if candidate != node_slug]
    # The last-node guard. The fleet has exactly one node and every user in
    # Myanmar depends on it; an endpoint that can empty the fleet by accident
    # has reproduced the defect this whole lane exists to remove, only with
    # better manners. So emptying it is refused by default, and the override is
    # a field that cannot be supplied by accident: it must repeat the exact
    # slug being retired. A boolean "force" would be typo-reachable and could
    # be left set in an operator's saved curl invocation; echoing the slug
    # cannot be aimed at the wrong node.
    if not servable_after:
        if confirm_last_servable_node.strip().lower() != node_slug:
            security_alert(3, "refused node retirement that would empty the fleet", request=request, details={
                "slug": node_slug,
                "servable_before": str(len(servable_before)),
            })
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Retiring '{node_slug}' would leave 0 servable nodes "
                    f"(currently {len(servable_before)}). No node record was changed. "
                    "If that is genuinely intended, resend with "
                    f"confirm_last_servable_node={node_slug}."
                ),
            )
    with get_db() as conn:
        ensure_schema(conn)
        # Authoritative re-reads inside the transaction that performs the
        # write, closing the window in which a concurrent change could have
        # retired this row or removed the last other servable node between the
        # pre-flight and here.
        row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Node not found.")
        if node_is_retired(row):
            raise HTTPException(status_code=409, detail="Node is already retired.")
        servable_before = servable_node_slugs(conn)
        servable_after = [candidate for candidate in servable_before if candidate != node_slug]
        if not servable_after and confirm_last_servable_node.strip().lower() != node_slug:
            raise HTTPException(
                status_code=409,
                detail="Retiring this node would leave 0 servable nodes. No node record was changed.",
            )
        retire_failures = []
        if node_admits_peer(row):
            retire_failures.append("node latch is open (tier it off, resync it and run the node-side gate first)")
        retire_failures += verify_offnode_gate_for_use(conn, node_slug, offnode_gate_sha256)
        if retire_failures:
            raise HTTPException(
                status_code=409,
                detail="Retirement refused until runtime cleanup is verified: " + "; ".join(retire_failures)
                + ". No node record was changed.",
            )
        was_servable = node_slug in servable_before
        retired_at = utcnow().isoformat()
        retirement_id = secrets.token_hex(16)
        # The row is claimed first, with `AND retired_at IS NULL` doing the
        # claiming: if a concurrent retirement of the same slug already landed,
        # this matches zero rows and the whole transaction is abandoned rather
        # than filing a second tombstone for a retirement it did not perform.
        # `row` was read above, so the snapshot below is still the
        # pre-retirement state.
        claimed = conn.execute(
            """
            UPDATE nodes
            SET retired_at = ?,
                operator_enabled = 0,
                status = 'offline',
                management_status = 'unknown',
                management_checked_at = ?,
                management_error = 'retired by operator',
                endpoint = '',
                stealth_endpoint = '',
                public_key = '',
                ssh_host = '',
                latch_cause = 'operator_retire',
                health_closed_at = NULL,
                health_closed_reason = NULL
            WHERE slug = ? AND retired_at IS NULL
            """,
            (retired_at, retired_at, node_slug),
        )
        if claimed.rowcount != 1:
            raise HTTPException(status_code=409, detail="Node is already retired.")
        if not consume_offnode_gate(conn, node_slug, offnode_gate_sha256, "retired"):
            raise HTTPException(status_code=409, detail="Offnode gate record was used concurrently. No node record was changed.")
        # The tombstone goes in the SAME transaction as the row it describes.
        # get_db() commits only on a clean exit, so a retirement whose recovery
        # record cannot be written does not happen at all -- there is no state
        # in which the row is retired and the record is missing. This is the
        # specific thing the register lane found missing from the deleted-row
        # case (4.4: "no undo log, no tombstone, and no audit row").
        conn.execute(
            "INSERT INTO node_retirements ("
            " retirement_id, slug, retired_at, reason, was_servable,"
            " servable_before, servable_after, last_servable_confirmed, state_json"
            ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                retirement_id, node_slug, retired_at, retirement_reason, 1 if was_servable else 0,
                len(servable_before), len(servable_after),
                1 if not servable_after else 0,
                node_retirement_state_json(row),
            ),
        )
        remaining_servable = servable_node_slugs(conn)
    # Design 10.3 (P-12): a retired slug leaves no pending canary request, no
    # limit entry and no deferred request.
    remove_winn3_canary_request(node_slug)
    # After the commit, so the fleet-emptied alert is only ever raised for a
    # retirement that actually happened.
    if remaining_servable:
        security_alert(4, "node retired", request=request, details={
            "slug": node_slug,
            "retirement_id": retirement_id,
            "servable_remaining": str(len(remaining_servable)),
        })
    else:
        # Priority 1 deliberately. P1/P2 are the emailed priorities by default,
        # and "the fleet now serves nobody" is the single most consequential
        # state this hub can be in.
        security_alert(1, "fleet has no servable node after retirement", request=request, details={
            "slug": node_slug,
            "retirement_id": retirement_id,
        })
    logger.warning(
        "node %s retired by operator (retirement_id=%s); %d servable node(s) remain",
        node_slug, retirement_id, len(remaining_servable),
    )
    return {
        "ok": True,
        "slug": node_slug,
        "retired_at": retired_at,
        "retirement_id": retirement_id,
        # Names only, never values -- these are endpoints and public keys.
        "identity_released": list(NODE_RETIREMENT_IDENTITY_RELEASE),
        "servable_nodes_remaining": len(remaining_servable),
        "restore_with": "POST /admin/nodes/restore",
    }

@app.post("/admin/nodes/restore")
def admin_restore_node(
    request: Request,
    slug: str = Form(...),
    x_admin_token: str = Header(...),
):
    """Undo a retirement: put the row's recorded state back.

    Admin node-retirement lane (2026-08-07). This is the "what can an operator
    undo" half of the retirement contract, and it is the reason retiring is
    allowed to release the identity attributes at all.

    Three things it deliberately does NOT restore:

      * management_status is set to 'unknown', never to whatever it was. Only a
        real management-tunnel verification may assert 'ok' -- the same rule the
        register lane applied to registration, for the same reason: the hub must
        not claim it can reach a box on the strength of a record about the past.
        The recorded value is still in the tombstone, so the operator can see
        what it used to be.
      * status is set to 'offline'. The node's own heartbeat/registration is
        what makes it 'online', and after a restore that is a fact to be
        observed rather than asserted.
      * operator_enabled is set to 0. Recovery restores identity and policy
        metadata, but it never reopens the customer-serving latch. Fresh gate
        evidence and a separate operator promotion are required.

    So a restore does not by itself put a node back in front of users. The
    sequence that does is in the handoff document.
    """
    require_admin_token(x_admin_token, request, "restore retired node")
    node_slug = (slug or "").strip().lower()
    if not node_slug:
        raise HTTPException(status_code=400, detail="Missing node slug.")
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        tombstone = latest_node_retirement(conn, node_slug) if row else None
    if not row:
        raise HTTPException(status_code=404, detail="Node not found.")
    if not node_is_retired(row):
        raise HTTPException(status_code=409, detail="Node is not retired.")
    if not tombstone:
        raise HTTPException(
            status_code=409,
            detail="No unrestored retirement record exists for this node; restore it by hand from a database backup.",
        )
    try:
        recorded = json.loads(tombstone["state_json"])
    except Exception:
        recorded = None
    if not isinstance(recorded, dict):
        raise HTTPException(status_code=500, detail="Retirement record is unreadable; restore by hand from a database backup.")
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT * FROM nodes WHERE slug = ?", (node_slug,)).fetchone()
        if not row or not node_is_retired(row):
            raise HTTPException(status_code=409, detail="Node is not retired.")
        # Putting the identity attributes back is a claim on them, so it is
        # subject to exactly the same check a registration is. Something else
        # may have taken this endpoint / stealth record / public key / management
        # host while the node was retired -- that is a normal outcome of
        # retiring a renamed box and re-provisioning it. Refusing here is what
        # stops a restore from recreating the duplicate-identity state the
        # register guard exists to prevent.
        restore_collisions = node_identity_collisions(
            conn,
            node_slug,
            endpoint=str(recorded.get("endpoint") or ""),
            stealth_endpoint=str(recorded.get("stealth_endpoint") or ""),
            public_key=str(recorded.get("public_key") or ""),
            ssh_host=str(recorded.get("ssh_host") or ""),
        )
        if restore_collisions:
            collision = NodeIdentityCollision(restore_collisions)
            logger.error(
                "refusing to restore node %s: identity collision (%s)", node_slug, collision,
            )
            raise HTTPException(
                status_code=409,
                detail=(
                    "Cannot restore this node: another node now claims "
                    + ", ".join(collision.attributes)
                    + ". No node record was changed."
                ),
            )
        # Only columns that exist on this database AND were recorded, minus the
        # ones this endpoint owns explicitly below. The intersection with the
        # live table is what keeps a stored key from ever reaching the SQL text
        # as an unvalidated identifier.
        live_columns = table_columns(conn, "nodes")
        owned = {
            "slug", "retired_at", "management_status", "management_checked_at",
            "management_error", "status", "operator_enabled",
            # L84: a tombstone must never restore an automatic-closure mark
            # (which would make a restored node eligible for automatic reopen)
            # or stale proof streaks.
            "health_closed_at", "health_closed_reason", "latch_cause",
            "data_plane_green_streak", "data_plane_green_since",
            "data_plane_probe_error_streak",
        }
        restorable = sorted(
            column for column in recorded
            if column in live_columns
            and column not in owned
            and column not in NODE_RETIREMENT_UNRECORDED_COLUMNS
            and re.fullmatch(r"[a-z_][a-z0-9_]*", column)
        )
        now_iso = utcnow().isoformat()
        assignments = ", ".join(f"{column} = ?" for column in restorable)
        values = [recorded.get(column) for column in restorable]
        conn.execute(
            f"UPDATE nodes SET {assignments + ', ' if assignments else ''}"
            "retired_at = NULL, operator_enabled = 0, status = 'offline', management_status = 'unknown',"
            " health_closed_at = NULL, health_closed_reason = NULL, latch_cause = 'operator_restore',"
            " data_plane_green_streak = 0, data_plane_green_since = NULL,"
            " management_checked_at = ?, management_error = 'restored; management tunnel not re-verified'"
            " WHERE slug = ? AND retired_at IS NOT NULL",
            (*values, now_iso, node_slug),
        )
        conn.execute(
            "UPDATE node_retirements SET restored_at = ? WHERE retirement_id = ? AND restored_at IS NULL",
            (now_iso, tombstone["retirement_id"]),
        )
    security_alert(4, "retired node restored", request=request, details={
        "slug": node_slug,
        "retirement_id": tombstone["retirement_id"],
    })
    logger.warning("retired node %s restored by operator (retirement_id=%s)", node_slug, tombstone["retirement_id"])
    return {
        "ok": True,
        "slug": node_slug,
        "restored_at": now_iso,
        "retirement_id": tombstone["retirement_id"],
        "columns_restored": len(restorable),
        "operator_enabled": False,
        "management_status": "unknown",
        "note": (
            "Not servable yet by design: the node must heartbeat/register back to 'online', a real "
            "management-tunnel verification (POST /admin/nodes/resync-peers) must set management_status='ok', "
            "and an operator must promote it with fresh frozen evidence."
        ),
    }

@app.get("/admin/nodes/retirements")
def admin_list_node_retirements(request: Request, x_admin_token: str = Header(...)):
    """The retirement ledger. Names, timestamps and counts -- never state_json,
    which carries endpoints and public keys."""
    require_admin_token(x_admin_token, request, "list node retirements")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT retirement_id, slug, retired_at, reason, was_servable, servable_before,"
            " servable_after, last_servable_confirmed, restored_at"
            " FROM node_retirements ORDER BY retired_at DESC, retirement_id DESC LIMIT 200"
        ).fetchall()
    return {"ok": True, "retirements": [dict(row) for row in rows]}

# SYNC-18: a resync pass is one sequential SSH push per peer, run inside the
# request, and it can outlast the node's own 90 s request. The rules:
#  * one pass per target at a time; the fleet pass (key "") excludes every node
#    pass and every node pass excludes the fleet pass, since both push that
#    node's peers. A WAITING fleet pass also holds new node passes back, so
#    overlapping node passes cannot starve it;
#  * a second caller waits up to PEER_RESYNC_JOIN_WAIT_SECONDS for the running
#    pass instead of failing at once, and gets 409 if it is still running. At
#    most PEER_RESYNC_MAX_WAITERS callers wait at once; more get 409 at once,
#    because every waiter holds one of the shared worker-pool threads (AnyIO's
#    default 40) that the Core's registration and assignment calls also need;
#  * a node pass that finished with no failures is remembered with the node's
#    AWG runtime identity (sent by the node, see wins-node-register). A later
#    request for the same slug and identity within PEER_RESYNC_REUSE_SECONDS
#    gets that result without a new pass. Every pass tagged with an identity
#    was started by a request the node sent after that runtime was up, so the
#    peers it pushed went into that runtime. Any failed or raised pass for the
#    node (a failed fleet pass counts for every node) removes the remembered
#    result: newer contrary evidence always wins;
#  * a request carrying a fresh token (the installer's post-hardening
#    management check sends one per check) accepts only a pass that STARTED
#    after the first request with that token reached the hub, so a check after
#    hardening can never be answered by a pass from before it. Each token keeps
#    its own first-seen time (up to PEER_RESYNC_FRESH_TOKENS_PER_NODE per node,
#    oldest dropped first, all dropped after PEER_RESYNC_FRESH_TOKEN_TTL_SECONDS),
#    so two checks for one node never reset each other's floor.
# The hub runs as one uvicorn process, so process-local state is the whole lock.
PEER_RESYNC_JOIN_WAIT_SECONDS = 75.0
PEER_RESYNC_REUSE_SECONDS = 600.0
PEER_RESYNC_MAX_WAITERS = 8
PEER_RESYNC_FRESH_TOKEN_TTL_SECONDS = 3600.0
PEER_RESYNC_FRESH_TOKENS_PER_NODE = 8
PEER_RESYNC_IDENTITY_RE = re.compile(r"[A-Za-z0-9_.:+-]{1,200}")
PEER_RESYNC_FRESH_TOKEN_RE = re.compile(r"[0-9a-f]{16,64}")
_PEER_RESYNC_CONDITION = threading.Condition()
_PEER_RESYNC_INFLIGHT: dict[str, float] = {}
_PEER_RESYNC_COMPLETED: dict[str, tuple[str, float, float, dict]] = {}
_PEER_RESYNC_FRESH: dict[str, dict[str, float]] = {}
_PEER_RESYNC_WAITERS = [0]
_PEER_RESYNC_FLEET_WAITERS = [0]

class PeerResyncBusy(Exception):
    pass

def _peer_resync_conflicts(key: str) -> bool:
    if key == "":
        return bool(_PEER_RESYNC_INFLIGHT)
    return (key in _PEER_RESYNC_INFLIGHT or "" in _PEER_RESYNC_INFLIGHT
            or _PEER_RESYNC_FLEET_WAITERS[0] > 0)

def _peer_resync_fresh_floor(key: str, fresh_token: str, now: float) -> float:
    for slug in list(_PEER_RESYNC_FRESH):
        tokens = _PEER_RESYNC_FRESH[slug]
        for token, seen in list(tokens.items()):
            if now - seen > PEER_RESYNC_FRESH_TOKEN_TTL_SECONDS:
                del tokens[token]
        if not tokens:
            del _PEER_RESYNC_FRESH[slug]
    tokens = _PEER_RESYNC_FRESH.setdefault(key, {})
    seen = tokens.get(fresh_token)
    if seen is not None:
        return seen
    tokens[fresh_token] = now
    while len(tokens) > PEER_RESYNC_FRESH_TOKENS_PER_NODE:
        # A dropped token that comes back gets a new, later floor: stricter,
        # never weaker.
        del tokens[min(tokens, key=tokens.get)]
    return now

def resync_active_peers_to_node_exclusive(
    node_slug: str = "", runtime_identity: Optional[str] = None,
    wait_seconds: Optional[float] = None, fresh_token: Optional[str] = None,
) -> dict[str, Any]:
    key = str(node_slug or "").strip().lower()
    identity = runtime_identity or None
    wait = PEER_RESYNC_JOIN_WAIT_SECONDS if wait_seconds is None else wait_seconds
    deadline = time.monotonic() + max(0.0, float(wait))
    waiting = False
    with _PEER_RESYNC_CONDITION:
        not_before = (
            _peer_resync_fresh_floor(key, fresh_token, time.monotonic())
            if key and fresh_token else None
        )
        try:
            while True:
                now = time.monotonic()
                if key and identity:
                    done = _PEER_RESYNC_COMPLETED.get(key)
                    if (done and done[0] == identity
                            and now - done[1] <= PEER_RESYNC_REUSE_SECONDS
                            and (not_before is None or done[2] >= not_before)):
                        return dict(done[3], reused_completed_pass=True)
                if not _peer_resync_conflicts(key):
                    started = now
                    _PEER_RESYNC_INFLIGHT[key] = started
                    break
                remaining = deadline - now
                if remaining <= 0:
                    raise PeerResyncBusy(key)
                if not waiting:
                    if _PEER_RESYNC_WAITERS[0] >= PEER_RESYNC_MAX_WAITERS:
                        raise PeerResyncBusy(key)
                    waiting = True
                    _PEER_RESYNC_WAITERS[0] += 1
                    if key == "":
                        _PEER_RESYNC_FLEET_WAITERS[0] += 1
                _PEER_RESYNC_CONDITION.wait(remaining)
        finally:
            if waiting:
                _PEER_RESYNC_WAITERS[0] -= 1
                if key == "":
                    _PEER_RESYNC_FLEET_WAITERS[0] -= 1
                _PEER_RESYNC_CONDITION.notify_all()
    result = None
    try:
        result = resync_active_peers_to_node(node_slug)
        return result
    finally:
        with _PEER_RESYNC_CONDITION:
            _PEER_RESYNC_INFLIGHT.pop(key, None)
            succeeded = (isinstance(result, dict) and result.get("ok") is True
                         and not result.get("failed"))
            if succeeded:
                if key and identity:
                    _PEER_RESYNC_COMPLETED[key] = (identity, time.monotonic(), started, dict(result))
            elif key:
                _PEER_RESYNC_COMPLETED.pop(key, None)
            else:
                _PEER_RESYNC_COMPLETED.clear()
            _PEER_RESYNC_CONDITION.notify_all()

def peer_resync_busy_response() -> HTTPException:
    return HTTPException(
        status_code=409,
        detail="A peer resync for this node is already running.",
        headers={"Retry-After": "30"},
    )

@app.post("/admin/nodes/resync-peers")
async def admin_resync_node_peers(request: Request, x_admin_token: str = Header(...)):
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "resync node peers")
    node_slug = (request.query_params.get("node_slug") or request.query_params.get("nodeslug") or "").strip()
    content_type = request.headers.get("content-type", "")
    if not node_slug and "application/json" in content_type:
        try:
            body = await request.json()
            if isinstance(body, dict):
                node_slug = str(body.get("node_slug") or body.get("nodeslug") or "").strip()
        except Exception:
            node_slug = ""
    if not node_slug and ("application/x-www-form-urlencoded" in content_type or "multipart/form-data" in content_type):
        form = await request.form()
        node_slug = str(form.get("node_slug") or form.get("nodeslug") or "").strip()
    try:
        return await asyncio.to_thread(resync_active_peers_to_node_exclusive, node_slug)
    except PeerResyncBusy:
        raise peer_resync_busy_response() from None

@app.post("/api/v1/nodes/{slug}/resync-peers")
def node_resync_own_peers(slug: str, request: Request, x_node_token: str = Header(...)):
    # H-9: node-token-only self-service resync. The slug comes from the URL
    # path and the supplied token must hash-match *that exact* node's stored
    # token, so node A can never trigger (or piggyback observations on) a
    # resync of node B -- only the admin-only route above can resync an
    # arbitrary/other node or the whole fleet.
    node_slug = (slug or "").strip().lower()
    with get_db() as conn:
        ensure_schema(conn)
        require_node_token(conn, node_slug, x_node_token, request, "node resync-peers")
    # SYNC-18: the node's AWG runtime identity (container and start time; not
    # a secret). Optional: an older node sends none and never reuses a pass.
    runtime_identity = str(request.query_params.get("runtime_identity") or "")
    if runtime_identity and not PEER_RESYNC_IDENTITY_RE.fullmatch(runtime_identity):
        raise HTTPException(status_code=400, detail="runtime_identity is malformed.")
    # SYNC-18 round 3: the installer's management check asks for a pass that
    # started after the check began (one random token per check).
    fresh_token = str(request.query_params.get("fresh") or "")
    if fresh_token and not PEER_RESYNC_FRESH_TOKEN_RE.fullmatch(fresh_token):
        raise HTTPException(status_code=400, detail="fresh is malformed.")
    try:
        return resync_active_peers_to_node_exclusive(
            node_slug, runtime_identity or None, fresh_token=fresh_token or None)
    except PeerResyncBusy:
        raise peer_resync_busy_response() from None

@app.get("/api/v1/pubkey")
def get_pubkey(
    request: Request,
    slug: str = "",
    core_id: str = "",
    x_node_token: Optional[str] = Header(default=None),
    x_core_token: Optional[str] = Header(default=None),
):
    # H-2: node/core-token-only. Both the data-plane and Core one-touch
    # installers bootstrap their own scoped token (via /api/v1/nodes/bootstrap
    # or /api/v1/core/bootstrap) before ever calling this endpoint, so the
    # fleet-wide admin token is never accepted here at all.
    node_slug = (slug or "").strip().lower()
    core_identifier = (core_id or "").strip().lower()
    if node_slug:
        with get_db() as conn:
            ensure_schema(conn)
            require_node_token(conn, node_slug, x_node_token, request, "pubkey")
    elif core_identifier:
        with get_db() as conn:
            ensure_schema(conn)
            require_core_token(conn, core_identifier, x_core_token, request, "pubkey")
    else:
        raise HTTPException(status_code=400, detail="slug or core_id is required")
    try:
        # H0 (D3): /root/.ssh is read-only to the hub. ensure_hub_ssh_key in
        # the installer generates the key before the hub starts; the hub only
        # reads the public half, and a missing key is an error here, never a
        # reason to write root's SSH directory.
        with open("/root/.ssh/id_rsa.pub", "r", encoding="utf-8") as f:
            return {"pubkey": f.read().strip()}
    except Exception as exc:
        logger.error("Unable to return hub SSH public key: %s", exc)
        return {"pubkey": ""}

@app.post("/admin/announce")
def set_announcement(
    request: Request,
    msg: Optional[str] = Form(default=None),
    announcement_payload_b64: str = Form(default=""),
    announcement_sig_b64: str = Form(default=""),
    x_admin_token: str = Header(...),
):
    """Post the global announcement.

    Signed form (the only form once ANNOUNCE_REQUIRE_SIGNED=1): the envelope
    produced OFFLINE by tools/winn3_sign_announcement.py. The hub verifies it
    against ANNOUNCE_PUBKEY_A1..A3, requires seq above the stored floor, and
    stores it verbatim. It holds no signing key and cannot sign anything.

    Plaintext form (`msg`): accepted only while ANNOUNCE_REQUIRE_SIGNED=0;
    stored unsigned and clears the envelope, exactly as before the ceremony.
    """
    require_admin_token(x_admin_token, request, "set announcement")
    if (announcement_payload_b64 or "").strip() or (announcement_sig_b64 or "").strip():
        with get_db() as conn:
            ensure_schema(conn)
            try:
                seq, kid = store_verified_announcement(
                    conn, announcement_payload_b64, announcement_sig_b64
                )
            except AnnouncementContractError as exc:
                # Fail loudly, and write nothing: every check runs before the
                # first set_setting. Reason only, never the payload or text.
                logger.warning(
                    "Announcement envelope refused (reason=%s); announcement unchanged.",
                    exc.reason,
                )
                raise HTTPException(
                    status_code=400,
                    detail=f"Announcement envelope refused (reason={exc.reason}); nothing was changed.",
                ) from None
        return {"ok": True, "signed": True, "seq": seq, "kid": kid}
    if ANNOUNCE_REQUIRE_SIGNED:
        raise HTTPException(
            status_code=400,
            detail=(
                "Signed announcement required: post announcement_payload_b64 and "
                "announcement_sig_b64 from tools/winn3_sign_announcement.py; nothing was changed."
            ),
        )
    if msg is None:
        raise HTTPException(
            status_code=400,
            detail="Provide msg, or announcement_payload_b64 and announcement_sig_b64.",
        )
    with get_db() as conn:
        ensure_schema(conn)
        store_unsigned_announcement(conn, msg)
    # Pre-ceremony hub: plaintext still moves, exactly as before, so installing
    # this hub build alone cannot break announcements for anyone. Enforcing
    # clients show their bundled default until a signed envelope is posted.
    logger.warning("Announcement stored WITHOUT a signature (plaintext form).")
    return {"ok": True, "signed": False, "seq": None}

