@app.post("/admin/app-version-gate")
def set_app_version_gate(
    request: Request,
    min_supported: str = Form(""),
    latest: str = Form(""),
    update_url: str = Form(""),
    x_admin_token: str = Header(...),
):
    # Force-update gate: clients older than min_supported are blocked from
    # connecting (the client fails open on an empty/"0.0.0" value, so leaving
    # min empty disables the gate). update_url is the download page the client
    # opens; empty falls back to the public website. latest is advisory only.
    require_admin_token(x_admin_token, request, "set app version gate")
    min_supported = (min_supported or "").strip()
    latest = (latest or "").strip()
    update_url = (update_url or "").strip()
    release_version_pattern = re.compile(
        r"(0|[1-9]\d{0,8})\.(0|[1-9]\d{0,8})\.(0|[1-9]\d{0,8})\Z"
    )
    def _is_release_version(value):
        return release_version_pattern.fullmatch(value) is not None
    # A non-empty min/latest must be a plain dotted version so a typo cannot
    # set a value that either blocks everyone or the client cannot parse.
    if min_supported and not _is_release_version(min_supported):
        raise HTTPException(status_code=400, detail="min_supported must be a dotted version like 1.0.15, or empty to disable the gate.")
    if latest and not _is_release_version(latest):
        raise HTTPException(status_code=400, detail="latest must be a dotted version like 1.0.16, or empty.")
    if update_url and not update_url.lower().startswith("https://"):
        raise HTTPException(status_code=400, detail="update_url must be an https:// URL, or empty.")
    with get_db() as conn:
        ensure_schema(conn)
        set_setting(conn, "min_supported_app_version", min_supported or "0.0.0")
        set_setting(conn, "latest_app_version", latest)
        set_setting(conn, "app_update_url", update_url)
    return {
        "ok": True,
        "min_supported_app_version": min_supported or "0.0.0",
        "latest_app_version": latest,
        "app_update_url": update_url,
    }

@app.post("/admin/provision")
def provision_account(request: Request, background_tasks: BackgroundTasks, name: str = Form(...), email: str = Form(...), duration: str = Form("1m"), x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "provision account")
    try:
        delta = parse_duration(duration)
    except DurationParseError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    with get_db() as conn:
        ensure_schema(conn)
        # K3-07: the lookup, the insert or renewal and the key mint are one step
        # under the writer lock, so two provisions of one address cannot both
        # create an account and no other writer can change the row in between.
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute("SELECT account_number, expiration_date FROM users WHERE email = ?", (email,)).fetchone()
        if existing:
            existing = dict(existing)
            base = parse_iso_datetime(existing.get("expiration_date")) or utcnow()
            if base < utcnow():
                base = utcnow()
            expiry = (base + delta).isoformat()
            conn.execute("UPDATE users SET subscriber_name = ?, status = 'active', expiration_date = ? WHERE account_number = ?", (name, expiry, existing["account_number"]))
            account_number = existing["account_number"]
            ensure_referral_code(conn, account_number)
            plan_type = f"Renewal {duration}"
            activation_secrets = []
        else:
            account_number = new_account_number(conn, background_tasks=background_tasks)
            expiry = (utcnow() + delta).isoformat()
            conn.execute("INSERT INTO users (account_number, email, subscriber_name, status, expiration_date, referral_code) VALUES (?, ?, ?, 'active', ?, ?)", (account_number, email, name, expiry, new_referral_code(conn)))
            plan_type = duration
            # H-1: a brand-new account needs its own activation secrets minted
            # before anyone can enroll a device on it: one setup key per device
            # slot, all stored in this transaction and all sent in one email.
            # The fresh row is always active, unexpired (every duration is
            # positive) and on this address, so the common guard always passes
            # it; it still goes through that guard, and a refusal rolls the
            # insert back.
            created = conn.execute(
                "SELECT status, email, expiration_date FROM users WHERE account_number=?", (account_number,),
            ).fetchone()
            if not account_may_receive_keys(created, email):
                raise HTTPException(status_code=409, detail="Account cannot receive setup keys.")
            activation_secrets = issue_activation_secrets(conn, account_number)
    email_sent = send_account_email(email, name, account_number, plan_type, activation_secrets)
    return {"status": "ok", "account_number": account_number, "accountnumber": account_number, "email_sent": email_sent}

@app.post("/admin/renew")
def renew_account(request: Request, account_number: str = Form(...), duration: str = Form("1m"), x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "renew account")
    acc = normalize_account_number(account_number)
    try:
        delta = parse_duration(duration)
    except DurationParseError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT account_number, expiration_date FROM users WHERE account_number = ?", (acc,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Account not found")
        base = parse_iso_datetime(row["expiration_date"]) or utcnow()
        if base < utcnow():
            base = utcnow()
        expiry = (base + delta).isoformat()
        conn.execute(
            "UPDATE users SET status='active', expiration_date=?, renewal_source='manual' WHERE account_number=?",
            (expiry, acc),
        )
    return {"status": "ok", "account_number": acc, "accountnumber": acc, "expiration_date": expiry, "expirationdate": expiry}

@app.post("/admin/device/remove")
def admin_remove_device(
    request: Request,
    background_tasks: BackgroundTasks,
    account_number: str = Form(...),
    device_id: Optional[str] = Form(None),
    device_model: Optional[str] = Form(None),
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "remove device from account")
    acc = normalize_account_number(account_number)
    target_id = (device_id or "").strip()
    target_model = (device_model or "").strip()
    if not target_id and not target_model:
        raise HTTPException(status_code=400, detail="Must supply device_id or device_model")
    with get_db() as conn:
        ensure_schema(conn)
        # One writer transaction from the lookup to the key return, so the
        # device found is the device removed and its key is returned once.
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        row = None
        if target_id:
            row = conn.execute(
                "SELECT device_id, device_model, client_public_key, location_slug FROM devices WHERE account_number = ? AND device_id = ?",
                (acc, target_id),
            ).fetchone()
        if not row and target_model:
            exact_matches = conn.execute(
                "SELECT device_id, device_model, client_public_key, location_slug, last_seen FROM devices WHERE account_number = ? AND LOWER(device_model) = LOWER(?) ORDER BY last_seen DESC",
                (acc, target_model),
            ).fetchall()
            if len(exact_matches) == 1:
                row = exact_matches[0]
            elif len(exact_matches) > 1:
                if not target_id:
                    matched_list = [{"device_id": m["device_id"], "device_model": m["device_model"], "last_seen": m["last_seen"]} for m in exact_matches]
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "error": "multiple_devices_match",
                            "message": f"Multiple devices match model '{target_model}'. Specify device_id for exact removal.",
                            "matching_devices": matched_list,
                        },
                    )
            else:
                fuzzy_matches = conn.execute(
                    "SELECT device_id, device_model, client_public_key, location_slug, last_seen FROM devices WHERE account_number = ? AND LOWER(device_model) LIKE LOWER(?) ORDER BY last_seen DESC",
                    (acc, f"%{target_model}%"),
                ).fetchall()
                if len(fuzzy_matches) == 1:
                    row = fuzzy_matches[0]
                elif len(fuzzy_matches) > 1:
                    if not target_id:
                        matched_list = [{"device_id": m["device_id"], "device_model": m["device_model"], "last_seen": m["last_seen"]} for m in fuzzy_matches]
                        raise HTTPException(
                            status_code=409,
                            detail={
                                "error": "multiple_devices_match",
                                "message": f"Multiple devices match '{target_model}'. Specify device_id for exact removal.",
                                "matching_devices": matched_list,
                            },
                        )
        if not row:
            raise HTTPException(status_code=404, detail=f"Device matching '{target_id or target_model}' not found on account {acc}")

        found_dev_id = row["device_id"]
        found_model = row["device_model"]
        client_key = (row["client_public_key"] or "").strip()
        loc_slug = row["location_slug"]

        # A support removal returns the device's setup key (owner ruling 2026-10-25).
        deactivate_device_returning_key(conn, acc, found_dev_id)
        conn.execute(
            "DELETE FROM double_vpn_assignments WHERE account_number = ? AND device_id = ?",
            (acc, found_dev_id),
        )
        if client_key and loc_slug:
            node = conn.execute("SELECT endpoint, ssh_host FROM nodes WHERE slug = ?", (loc_slug,)).fetchone()
            if node:
                node_ip = node["ssh_host"] or extract_node_host(node["endpoint"] or "")
                if node_ip:
                    queue_peer_revocation(conn, node_ip, client_key, background_tasks)
        background_tasks.add_task(drain_winn3_registry_refreshes)

        remaining = conn.execute("SELECT COUNT(*) AS cnt FROM devices WHERE account_number = ?", (acc,)).fetchone()["cnt"]

    return {
        "status": "ok",
        "account_number": acc,
        "removed_device": {
            "device_id": found_dev_id,
            "device_model": found_model,
        },
        "remaining_devices_count": remaining,
    }

@app.get("/admin/device/list")
def admin_list_devices(
    request: Request,
    account_number: str,
    x_admin_token: str = Header(...),
):
    require_admin_token(x_admin_token, request, "list devices for account")
    acc = normalize_account_number(account_number)
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT device_id, device_model, location_slug, vpn_internal_ip, last_seen FROM devices WHERE account_number = ? ORDER BY last_seen DESC",
            (acc,),
        ).fetchall()
        return {
            "status": "ok",
            "account_number": acc,
            "devices": [dict(r) for r in rows],
        }

@app.post("/admin/resend")
def resend_email(request: Request, background_tasks: BackgroundTasks, email: str = Form(...), x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "resend activation email")
    with get_db() as conn:
        ensure_schema(conn)
        # K3-07: look the account up, check it and mint under one writer lock.
        # Reading the address first and locking afterwards let a concurrent
        # change send valid keys to a superseded address, and an inactive or
        # expired account must not have its keys rotated or mailed at all.
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        user = conn.execute(
            "SELECT account_number, subscriber_name, status, email, expiration_date FROM users WHERE email = ?", (email,),
        ).fetchone()
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        if not account_may_receive_keys(user, email):
            raise HTTPException(status_code=409, detail="Account cannot receive setup keys.")
        user = dict(user)
        # H-1: only the digest is ever persisted, so the original activation
        # secrets cannot be recovered for resend, rotate them instead. This
        # intentionally invalidates every not-yet-used prior secret for this
        # account and issues one fresh set; it does not affect devices that
        # already completed enrollment and hold their own device_auth_token.
        activation_secrets = issue_activation_secrets(conn, user["account_number"])
    email_sent = send_account_email(email, user.get("subscriber_name") or "Wins VPN User", user["account_number"], "Resend Credentials", activation_secrets)
    return {"status": "ok", "email_sent": email_sent, "account_number": user["account_number"], "accountnumber": user["account_number"]}

@app.post("/admin/donor-acknowledgment/issue")
def admin_issue_donor_acknowledgment(
    request: Request,
    background_tasks: BackgroundTasks,
    donor_name: str = Form(...),
    amount: str = Form(...),
    contribution_date: str = Form(...),
    email: str = Form(""),
    currency: str = Form("USD"),
    noncash_description: str = Form(""),
    goods_description: str = Form(""),
    goods_fmv: str = Form("0"),
    amount_words: str = Form(""),
    x_admin_token: str = Header(...),
):
    """Issue one acknowledgment by hand. This is also the retroactive path:
    DONOR_ACKNOWLEDGMENT_REQUIREMENTS.md section 7 finds that donors of $250 or
    more since the 2026-06-11 effective date of exemption may hold nothing
    usable, and the contemporaneous window for the 2026 tax year is still open.
    `amount` and `contribution_date` accept parallel comma-separated lists so a
    donor's whole year can be acknowledged on one certificate."""
    require_admin_token(x_admin_token, request, "issue donor acknowledgment")
    amounts = [part.strip() for part in str(amount).split(",") if part.strip()]
    dates = [part.strip() for part in str(contribution_date).split(",") if part.strip()]
    if not amounts or not dates or len(amounts) != len(dates):
        raise HTTPException(
            status_code=400,
            detail="amount and contribution_date must be non-empty and the same length",
        )
    try:
        result = donor_issue_and_deliver(
            background_tasks=background_tasks,
            donor_name=donor_name,
            donor_email=email,
            gifts=[{"date": d, "amount": a} for d, a in zip(dates, amounts)],
            currency=currency,
            noncash_description=noncash_description,
            goods_description=goods_description,
            goods_fmv=goods_fmv,
            amount_words=amount_words,
        )
    except DonorCertificateError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return result


@app.post("/admin/donor-acknowledgment/resend")
def admin_resend_donor_acknowledgment(
    request: Request,
    background_tasks: BackgroundTasks,
    ack_number: str = Form(...),
    email: str = Form(""),
    x_admin_token: str = Header(...),
):
    """Re-send, optionally attaching an address that was not on file at the
    time (a crypto donor who later supplies one). Never mints a new number."""
    require_admin_token(x_admin_token, request, "resend donor acknowledgment")
    reference = str(ack_number).strip()
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute(
            "SELECT ack_number FROM donation_acknowledgments WHERE ack_number = ?", (reference,)
        ).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Unknown acknowledgment number")
        if email.strip():
            conn.execute(
                "UPDATE donation_acknowledgments SET donor_email = ? WHERE ack_number = ?",
                (email.strip(), reference),
            )
    background_tasks.add_task(donor_deliver_acknowledgment, reference)
    return {"status": "queued", "ack_number": reference}


@app.post("/admin/donor-acknowledgment/annual-summary")
def admin_donor_annual_summary(
    request: Request,
    background_tasks: BackgroundTasks,
    email: str = Form(...),
    tax_year: str = Form(...),
    x_admin_token: str = Header(...),
):
    """One certificate covering every gift already acknowledged for a donor in
    a tax year. Pub. 1771 suggests charities send these no later than January
    31 of the following year."""
    require_admin_token(x_admin_token, request, "issue donor annual summary")
    try:
        return donor_issue_annual_summary(email, tax_year, background_tasks)
    except DonorCertificateError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@app.get("/admin/donor-acknowledgments")
def admin_list_donor_acknowledgments(request: Request, x_admin_token: str = Header(...)):
    """Ledger view. `undelivered=1` is the one that matters operationally: it
    lists every acknowledgment that has not reached its donor, including the
    $250-or-more gifts where a donor cannot deduct without it."""
    require_admin_token(x_admin_token, request, "list donor acknowledgments")
    params = request.query_params
    tax_year = str(params.get("tax_year", "") or "").strip()
    undelivered = str(params.get("undelivered", "") or "").strip().lower() in {"1", "true", "yes", "on"}
    required_only = str(params.get("required_only", "") or "").strip().lower() in {"1", "true", "yes", "on"}
    clauses = []
    args: list = []
    if tax_year:
        clauses.append("tax_year = ?")
        args.append(tax_year)
    if undelivered:
        clauses.append("delivery_status != 'sent'")
    if required_only:
        clauses.append("ack_required = 1")
    where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            f"""
            SELECT ack_number, tax_year, kind, donor_name, donor_email, amount_total,
                   largest_single_gift, currency, gift_count, tier, ack_required,
                   quid_pro_quo, provider, render_status, delivery_status,
                   delivery_detail, delivery_attempts, delivered_at, issued_at
            FROM donation_acknowledgments {where}
            ORDER BY tax_year DESC, sequence DESC LIMIT 500
            """,
            tuple(args),
        ).fetchall()
        totals = conn.execute(
            """
            SELECT COUNT(*) AS total,
                   SUM(CASE WHEN delivery_status = 'sent' THEN 1 ELSE 0 END) AS sent,
                   SUM(CASE WHEN ack_required = 1 AND delivery_status != 'sent' THEN 1 ELSE 0 END)
                       AS required_not_delivered
            FROM donation_acknowledgments
            """
        ).fetchone()
    return {
        "acknowledgments": [dict(row) for row in rows],
        "counts": {
            "total": int(totals["total"] or 0),
            "sent": int(totals["sent"] or 0),
            "required_not_delivered": int(totals["required_not_delivered"] or 0),
        },
        "signatory_configured": bool(DONOR_ACK_SIGNATORY_NAME),
        "template_path": DONOR_CERT_TEMPLATE_PATH,
        "retention_policy": donor_acknowledgment_retention_note(),
    }

@app.post("/webhook/paypal")
async def paypal_webhook(request: Request, background_tasks: BackgroundTasks):
    raw_body = await request.body()
    return await asyncio.to_thread(_paypal_webhook_sync, request, background_tasks, raw_body)


def _paypal_webhook_sync(request: Request, background_tasks: BackgroundTasks, raw_body: bytes):
    try:
        payload = json.loads(raw_body.decode() or "{}")
    except Exception:
        return {"status": "ignored", "reason": "invalid_json"}
    event = payload.get("event_type", "")
    resource = payload.get("resource") or {}
    logger.info("PayPal webhook received: %s", event)
    if not (paypal_enabled() and PAYPAL_WEBHOOK_ID):
        logger.warning("PayPal webhook ignored because PAYPAL_CLIENT_ID/PAYPAL_CLIENT_SECRET/PAYPAL_WEBHOOK_ID are not configured")
        return {"status": "ignored", "event": event, "reason": "paypal_credentials_not_configured"}
    if not verify_paypal_webhook_signature(dict(request.headers), raw_body, payload):
        security_alert(2, "invalid paypal webhook signature", request=request, details={
            "event": event,
            "event_id_hash": security_event_hash(payload.get("id", "")),
        })
        raise HTTPException(status_code=400, detail="Invalid PayPal webhook signature or PayPal credentials not configured")

    subscription_events = {"BILLING.SUBSCRIPTION.ACTIVATED", "BILLING.SUBSCRIPTION.UPDATED", "BILLING.SUBSCRIPTION.RE-ACTIVATED", "PAYMENT.SALE.COMPLETED"}
    stop_events = {"BILLING.SUBSCRIPTION.CANCELLED", "BILLING.SUBSCRIPTION.SUSPENDED", "BILLING.SUBSCRIPTION.EXPIRED", "BILLING.SUBSCRIPTION.PAYMENT.FAILED"}
    refund_events = {"PAYMENT.SALE.REFUNDED", "PAYMENT.SALE.REVERSED", "PAYMENT.CAPTURE.REFUNDED", "PAYMENT.CAPTURE.REVERSED"}
    denied_events = {"PAYMENT.CAPTURE.DENIED", "PAYMENT.CAPTURE.DECLINED", "PAYMENT.SALE.DENIED"}
    if event.startswith("PAYMENT.SALE."):
        subscription_id = str(resource.get("billing_agreement_id") or resource.get("subscription_id") or "")
    elif event.startswith("BILLING.SUBSCRIPTION."):
        subscription_id = str(resource.get("id") or resource.get("billing_agreement_id") or resource.get("subscription_id") or "")
    else:
        # A capture ID is a payment reference, never a subscription ID.
        subscription_id = ""
    event_id = paypal_event_id(payload, raw_body)
    subscription_revision = 0
    subscription_before = ()
    with get_db() as conn:
        ensure_schema(conn)
        if not reserve_paypal_event(conn, event_id, event, subscription_id):
            existing = conn.execute(
                "SELECT status FROM paypal_events WHERE event_id=?", (event_id,)
            ).fetchone()
            if existing is not None and existing["status"] in {"processed", "ignored"}:
                return {"status": "duplicate", "event": event}
            raise HTTPException(
                status_code=409,
                detail="PayPal event processing is still in progress. Please retry.",
                headers={"Retry-After": "10"},
            )

        if subscription_id and event in (subscription_events | stop_events | refund_events):
            subscription_revision = advance_paypal_subscription_authority(conn, subscription_id)
            subscription_before = paypal_subscription_snapshot(conn, subscription_id)

    try:
        if event in stop_events and subscription_id:
            # Signed events may arrive after a newer activation or purchase.
            # Snapshot local authority, close SQLite, then read current provider state.
            authority_query = """
                SELECT account_number, paypal_subscription_id, status, paypal_status,
                       expiration_date, last_paypal_sync
                FROM users WHERE paypal_subscription_id=? ORDER BY account_number
            """
            with get_db() as conn:
                before = [tuple(row) for row in conn.execute(authority_query, (subscription_id,))]
            if not before:
                with get_db() as conn:
                    finish_paypal_event(conn, event_id, "ignored", error="subscription_not_current")
                return {"status": "ignored", "event": event, "reason": "subscription_not_current"}
            details = fetch_paypal_subscription(subscription_id)
            if not isinstance(details, dict) or details.get("id") != subscription_id:
                raise RuntimeError("PayPal stop verification returned a different subscription")
            paypal_status = str(details.get("status") or "").upper()
            if paypal_status in PAYPAL_ACTIVE_STATUSES:
                with get_db() as conn:
                    finish_paypal_event(conn, event_id, "ignored", error="subscription_currently_active")
                return {"status": "ignored", "event": event, "reason": "subscription_currently_active"}
            if paypal_status not in PAYPAL_INACTIVE_STATUSES:
                raise RuntimeError("PayPal stop verification did not establish a terminal local posture")
            with get_db() as conn:
                conn.execute("BEGIN IMMEDIATE")
                require_paypal_subscription_authority(conn, subscription_id, subscription_revision,
                                                      subscription_before)
                current = [tuple(row) for row in conn.execute(authority_query, (subscription_id,))]
                if current != before:
                    raise RuntimeError("Subscription authority changed during PayPal stop verification")
                conn.execute("UPDATE users SET status='expired', paypal_status=?, last_paypal_sync=? WHERE paypal_subscription_id=?", (paypal_status, utcnow().isoformat(), subscription_id))
                for row in current:
                    revoke_account_runtime(conn, row[0], background_tasks)
                    claw_back_referral_bonus(conn, row[0])
                finish_paypal_event(conn, event_id, "processed", account_number=(current[0][0] if current else ""))
            return {"status": "ok", "event": event, "subscription_id": mask_id(subscription_id), "revoked": len(current)}

        if event in subscription_events and subscription_id:
            # Never grant from webhook fields alone. Re-read the signed-in app's
            # subscription object and require PayPal's definitive ACTIVE state.
            details = fetch_paypal_subscription(subscription_id)
            if not isinstance(details, dict) or details.get("id") != subscription_id:
                raise RuntimeError("PayPal grant verification returned a different subscription")
            merged = details
            plan_id = str(merged.get("plan_id") or resource.get("plan_id") or "")
            paypal_status = str(merged.get("status") or "UNKNOWN").upper()
            allowed_plan_ids = {value for value in {PAYPAL_PLAN_1M, PAYPAL_PLAN_1Y, PAYPAL_PLAN_PERSONAL} if value}
            if plan_id not in allowed_plan_ids:
                with get_db() as conn:
                    finish_paypal_event(conn, event_id, "ignored", error="unrecognized_subscription_plan")
                return {"status": "ignored", "event": event, "reason": "unrecognized_subscription_plan"}
            if paypal_status not in PAYPAL_ACTIVE_STATUSES:
                with get_db() as conn:
                    conn.execute("BEGIN IMMEDIATE")
                    require_paypal_subscription_authority(conn, subscription_id, subscription_revision,
                                                          subscription_before)
                    existing = conn.execute("SELECT account_number FROM users WHERE paypal_subscription_id=?", (subscription_id,)).fetchall()
                    if paypal_status in PAYPAL_INACTIVE_STATUSES:
                        conn.execute("UPDATE users SET status='expired', paypal_status=?, last_paypal_sync=? WHERE paypal_subscription_id=?", (paypal_status, utcnow().isoformat(), subscription_id))
                        for row in existing:
                            revoke_account_runtime(conn, row["account_number"], background_tasks)
                            claw_back_referral_bonus(conn, row["account_number"])
                    else:
                        conn.execute("UPDATE users SET paypal_status=?, last_paypal_sync=? WHERE paypal_subscription_id=?", (paypal_status, utcnow().isoformat(), subscription_id))
                    finish_paypal_event(conn, event_id, "processed", account_number=(existing[0]["account_number"] if existing else ""), error=f"subscription_not_active:{paypal_status}")
                return {"status": "ignored", "event": event, "reason": "subscription_not_active", "subscription_status": paypal_status}
            payer_id = str(find_first_key(merged, {"payer_id"}) or find_first_key(resource, {"payer_id"}) or "")
            email = extract_paypal_email(merged, resource, payload)
            subscriber_name = extract_paypal_name(merged, resource, payload)
            next_time = None
            if isinstance(merged.get("billing_info"), dict):
                next_time = merged["billing_info"].get("next_billing_time")
            next_time = next_time or resource.get("next_billing_time")
            referral_code = extract_referral_code(merged, resource, payload)
            if not email:
                raise RuntimeError("active PayPal subscription did not include a customer email")
            payment_references = paypal_payment_references(event, resource)
            payment_reference = payment_references[0] if payment_references else subscription_id
            with get_db() as conn:
                conn.execute("BEGIN IMMEDIATE")
                require_paypal_subscription_authority(conn, subscription_id, subscription_revision,
                                                      subscription_before)
                terminal_payment = any(conn.execute(
                    "SELECT 1 FROM paypal_terminal_payments WHERE payment_reference=?", (reference,)
                ).fetchone() is not None for reference in payment_references)
                payment_hold = conn.execute("""
                    SELECT 1 FROM users WHERE (paypal_subscription_id=? OR email=?)
                    AND UPPER(COALESCE(paypal_status, '')) IN ('REFUNDED', 'REVERSED')
                    LIMIT 1
                """, (subscription_id, email)).fetchone() is not None
                durable_hold = conn.execute(
                    "SELECT payment_hold FROM paypal_subscription_authority WHERE subscription_id=?",
                    (subscription_id,),
                ).fetchone()
                if terminal_payment or payment_hold or (durable_hold and durable_hold["payment_hold"]):
                    finish_paypal_event(conn, event_id, "ignored", error="subscription_payment_hold")
                    return {"status": "ignored", "event": event, "reason": "subscription_payment_hold"}
                account_number, created, expiry, activation_secrets = upsert_paypal_account(conn, email=email, subscriber_name=subscriber_name, subscription_id=subscription_id, plan_id=plan_id, payer_id=payer_id, paypal_status=paypal_status, next_billing_time=next_time, referral_code=referral_code, purchase_reference=subscription_id, paypal_purchase_reference=payment_reference)
                if activation_secrets:
                    enqueue_activation_delivery(conn, f"paypal:{event_id}", email, subscriber_name,
                                                account_number, f"PayPal {plan_id or 'subscription'}", activation_secrets)
                finish_paypal_event(conn, event_id, "processed", account_number=account_number)
            return {"status": "ok", "event": event, "created": created, "subscription_status": paypal_status}

        if event in refund_events:
            terminal_refund, payment_references, refund_subscription_id = paypal_refund_is_terminal(event, resource)
            subscription_id = subscription_id or refund_subscription_id
            if not terminal_refund:
                with get_db() as conn:
                    finish_paypal_event(conn, event_id, "processed", error="partial_refund_no_revocation")
                return {"status": "ok", "event": event, "revoked": 0, "partial_refund": True}
            if not payment_references and not subscription_id:
                raise RuntimeError("PayPal refund/reversal could not be correlated to an entitlement")
            with get_db() as conn:
                ensure_schema(conn)
                conn.commit()
                conn.execute("BEGIN IMMEDIATE")
                if subscription_id:
                    advance_paypal_subscription_authority(conn, subscription_id)
                    conn.execute(
                        "UPDATE paypal_subscription_authority SET payment_hold=1 WHERE subscription_id=?",
                        (subscription_id,),
                    )
                for payment_reference in payment_references:
                    conn.execute(
                        "INSERT OR IGNORE INTO paypal_terminal_payments "
                        "(payment_reference, event_id, recorded_at) VALUES (?, ?, ?)",
                        (payment_reference, event_id, utcnow().isoformat()),
                    )
                clauses = []
                parameters = []
                if payment_references:
                    clauses.append(f"paypal_purchase_reference IN ({','.join('?' for _ in payment_references)})")
                    parameters.extend(payment_references)
                if subscription_id:
                    clauses.append("paypal_subscription_id=?")
                    parameters.append(subscription_id)
                rows = conn.execute(f"SELECT account_number FROM users WHERE {' OR '.join(clauses)}", tuple(parameters)).fetchall()
                paypal_status = "REVERSED" if event.endswith(".REVERSED") else "REFUNDED"
                for row in rows:
                    conn.execute("UPDATE users SET status='expired', paypal_status=?, last_paypal_sync=? WHERE account_number=?", (paypal_status, utcnow().isoformat(), row["account_number"]))
                for row in rows:
                    revoke_account_runtime(conn, row["account_number"], background_tasks)
                    claw_back_referral_bonus(conn, row["account_number"])
                finish_paypal_event(conn, event_id, "processed", account_number=(rows[0]["account_number"] if rows else ""))
            return {"status": "ok", "event": event, "revoked": len(rows)}

        if event in denied_events:
            # Denied / declined captures are terminal non-grants: the buyer was not
            # charged, so no account is provisioned and no existing entitlement is
            # revoked. Marked as processed (not failed) so PayPal does not retry a
            # denied payment as if it were a transient error.
            with get_db() as conn:
                finish_paypal_event(conn, event_id, "ignored", error="payment_denied")
            return {"status": "ignored", "event": event, "reason": "payment_denied"}

        if event in {"PAYMENT.CAPTURE.COMPLETED", "PAYMENT.SALE.COMPLETED"}:
            lifetime_plan_id, lifetime_label = classify_lifetime_payment(payload)
            if lifetime_plan_id:
                # Provider reads happen off the event loop, before the grant transaction.
                email, subscriber_name = resolve_paypal_payment_customer(event, resource, payload)
                if email:
                    payment_references = paypal_payment_references(event, resource)
                    if not payment_references:
                        raise RuntimeError("completed PayPal payment did not include a durable transaction ID")
                    referral_code = extract_referral_code(resource, payload)
                    # H-1: if this capture belongs to a hub-created wallet order,
                    # bind and verify it before granting. The PayPal order id rides
                    # on the capture resource (supplementary_data.related_ids.
                    # order_id); a bound order lets us confirm the captured
                    # amount/currency/plan match what THIS hub priced and provision
                    # from the order's stored referral rather than the
                    # provider-echoed custom_id. Hosted-link lifetime captures carry
                    # no such order and fall through to the unchanged grant below.
                    wallet_order_id = normalize_paypal_reference(find_first_key(resource, {"order_id"}))
                    wallet_grant_referral = referral_code
                    wallet_grant_promo = ""
                    with get_db() as conn:
                        ensure_schema(conn)
                        conn.commit()
                        conn.execute("BEGIN IMMEDIATE")
                        terminal_payment = any(
                            conn.execute(
                                "SELECT 1 FROM paypal_terminal_payments WHERE payment_reference=?",
                                (payment_reference,),
                            ).fetchone() is not None
                            for payment_reference in payment_references
                        )
                        if terminal_payment:
                            finish_paypal_event(conn, event_id, "ignored", error="payment_already_refunded_or_reversed")
                            return {"status": "ignored", "event": event, "reason": "payment_already_refunded_or_reversed"}
                        order = None
                        if wallet_order_id:
                            order = conn.execute(
                                """
                                SELECT hub_order_id, plan_key, expected_amount,
                                       expected_currency, referral_code, promo_code, status
                                FROM payment_orders
                                WHERE provider='paypal_wallet' AND provider_order_id=?
                                """,
                                (wallet_order_id,),
                            ).fetchone()
                        if order is not None:
                            if order["status"] == "settled":
                                finish_paypal_event(conn, event_id, "processed", error="wallet_order_already_settled")
                                return {"status": "duplicate", "event": event, "plan": lifetime_plan_id}
                            claimed = conn.execute(
                                "UPDATE payment_orders SET status='processing' WHERE provider='paypal_wallet' AND provider_order_id=? AND status IN ('pending', 'failed', 'processing')",
                                (wallet_order_id,),
                            ).rowcount
                            if claimed != 1:
                                finish_paypal_event(conn, event_id, "processed", error="wallet_order_not_claimable")
                                return {"status": "duplicate", "event": event, "plan": lifetime_plan_id}
                            captured_amount = resource.get("amount") if isinstance(resource.get("amount"), dict) else {}
                            try:
                                captured = Decimal(str(captured_amount.get("value") or captured_amount.get("total") or ""))
                                expected = Decimal(str(order["expected_amount"] or ""))
                            except (InvalidOperation, TypeError, ValueError):
                                captured = expected = Decimal("-1")
                            captured_currency = str(captured_amount.get("currency_code") or captured_amount.get("currency") or "").upper()
                            wallet_contract_ok = (
                                order["plan_key"] == lifetime_plan_id
                                and captured_currency == order["expected_currency"]
                                and expected.is_finite()
                                and captured.is_finite()
                                and expected > 0
                                and captured == expected
                            )
                            if not wallet_contract_ok:
                                conn.execute("UPDATE payment_orders SET status='manual_review' WHERE provider='paypal_wallet' AND provider_order_id=?", (wallet_order_id,))
                                finish_paypal_event(conn, event_id, "failed", error="wallet_settlement_contract_mismatch")
                                conn.commit()
                                security_alert(1, "paypal wallet settlement contract mismatch", request=request, details={
                                    "event": event,
                                    "event_id_hash": security_event_hash(event_id),
                                })
                                raise RuntimeError("PayPal wallet settlement contract mismatch")
                            # Provision from the order's stored referral (never the
                            # provider-echoed custom_id); the buyer email still comes
                            # from PayPal, the only identity source for wallet checkout.
                            wallet_grant_referral = normalize_referral_code(order["referral_code"])
                            wallet_grant_promo = normalize_promo_code(order["promo_code"])
                        elif not validate_lifetime_payment_contract(resource, lifetime_plan_id):
                            security_alert(1, "PayPal lifetime payment contract mismatch", request=request, details={
                                "event": event,
                                "event_id_hash": security_event_hash(event_id),
                            })
                            finish_paypal_event(conn, event_id, "ignored", error="lifetime_amount_currency_mismatch")
                            return {"status": "ignored", "event": event, "reason": "lifetime_amount_currency_mismatch"}
                        account_number, created, expiry, activation_secrets = upsert_paypal_account(conn, email=email, subscriber_name=subscriber_name, subscription_id="", plan_id=lifetime_plan_id, payer_id=str(find_first_key(resource, {"payer_id"}) or ""), paypal_status="ACTIVE", next_billing_time=None, duration_text="10y", referral_code=wallet_grant_referral, purchase_reference=payment_references[0], paypal_purchase_reference=payment_references[0], promo_code=wallet_grant_promo)
                        if order is not None:
                            conn.execute("UPDATE payment_orders SET status='settled', settled_at=? WHERE provider='paypal_wallet' AND provider_order_id=?", (utcnow().isoformat(), wallet_order_id))
                        if activation_secrets:
                            enqueue_activation_delivery(conn, f"paypal:{event_id}", email, subscriber_name,
                                                        account_number, lifetime_label, activation_secrets)
                        finish_paypal_event(conn, event_id, "processed", account_number=account_number)
                    return {"status": "ok", "event": event, "created": created, "plan": lifetime_plan_id}
                raise RuntimeError("completed lifetime PayPal payment did not include a customer email")
            # Not a lifetime pass, not a subscription payment: this is the
            # donation path. Until now such captures were ignored outright, so
            # the site's promise that "Donation receipts are sent by email
            # after payment" had nothing behind it -- see section 7 of
            # DONOR_ACKNOWLEDGMENT_REQUIREMENTS.md, which records that as a
            # real defect rather than a theoretical one. There is no competing
            # receipt path to conflict with; this establishes the first one.
            if DONOR_ACK_AUTO_ISSUE and classify_donation_payment(payload):
                donation_references = paypal_payment_references(event, resource)
                donation_reference = donation_references[0] if donation_references else event_id
                try:
                    with get_db() as conn:
                        ensure_schema(conn)
                        conn.commit()
                        conn.execute("BEGIN IMMEDIATE")
                        donation = donor_acknowledge_paypal_donation(conn, payload, resource, donation_reference)
                        finish_paypal_event(conn, event_id, "processed",
                                            error=str(donation.get("reason") or donation.get("status") or "")[:120])
                except sqlite3.IntegrityError:
                    # The partial UNIQUE index on (provider, provider_reference)
                    # is the authority on "one gift, one number", not the SELECT
                    # that precedes the INSERT. Landing here means another
                    # handler committed this same capture id first. That is a
                    # duplicate delivery of one webhook, not a failure: it must
                    # not raise, because a 500 tells PayPal to redeliver an event
                    # that was already honoured. The gift keeps the number the
                    # winning writer minted.
                    with get_db() as conn:
                        settled = conn.execute(
                            "SELECT ack_number FROM donation_acknowledgments "
                            "WHERE provider = 'paypal' AND provider_reference = ?",
                            (donation_reference,),
                        ).fetchone()
                        finish_paypal_event(conn, event_id, "processed",
                                            error="donation_already_acknowledged")
                    return {"status": "ok", "event": event, "donation": {
                        "status": "duplicate",
                        "ack_number": (settled["ack_number"] if settled else ""),
                    }}
                except DonorCertificateError as exc:
                    with get_db() as conn:
                        finish_paypal_event(conn, event_id, "ignored", error=f"donation_not_acknowledgeable:{exc}")
                    return {"status": "ignored", "event": event, "reason": "donation_not_acknowledgeable"}
                if donation.get("status") == "issued" and donation.get("delivery_status") == "pending":
                    background_tasks.add_task(donor_deliver_acknowledgment, donation["ack_number"])
                return {"status": "ok", "event": event, "donation": donation}
            with get_db() as conn:
                finish_paypal_event(conn, event_id, "ignored", error="one_time_payment_missing_lifetime_marker")
            return {"status": "ignored", "event": event, "reason": "one_time_payment_missing_lifetime_marker"}

        with get_db() as conn:
            finish_paypal_event(conn, event_id, "ignored", error="unsupported_event")
        return {"status": "ignored", "event": event}
    except Exception as exc:
        with get_db() as conn:
            finish_paypal_event(conn, event_id, "failed", error=str(exc))
        raise

@app.post("/webhook/btcpay")
async def btcpay_webhook(request: Request, background_tasks: BackgroundTasks):
    raw_body = await request.body()
    return await asyncio.to_thread(_btcpay_webhook_sync, request, background_tasks, raw_body)


def _btcpay_webhook_sync(request: Request, background_tasks: BackgroundTasks, raw_body: bytes):
    if not btcpay_enabled():
        logger.warning("BTCPay webhook ignored because BTCPAY_* are not fully configured")
        return {"status": "ignored", "reason": "btcpay_not_configured"}
    # Verify the HMAC-SHA256 signature over the RAW body BEFORE parsing or trusting
    # any field -- same rigor as verify_paypal_webhook_signature.
    if not verify_btcpay_webhook_signature(dict(request.headers), raw_body):
        security_alert(2, "invalid btcpay webhook signature", request=request, details={
            "body_sha256": hashlib.sha256(raw_body).hexdigest(),
        })
        raise HTTPException(status_code=400, detail="Invalid BTCPay webhook signature")
    try:
        payload = json.loads(raw_body.decode() or "{}")
    except Exception:
        return {"status": "ignored", "reason": "invalid_json"}
    if not isinstance(payload, dict):
        return {"status": "ignored", "reason": "invalid_json"}
    event_type = str(payload.get("type") or "")
    invoice_id = str(payload.get("invoiceId") or "")
    logger.info("BTCPay webhook received: %s", event_type)
    # Act ONLY on the settled/confirmed signal. Created/ReceivedPayment/Processing/
    # Expired/Invalid are ignored WITHOUT reserving the dedupe id, so an early
    # non-settled delivery can never poison the later settled delivery.
    if event_type not in BTCPAY_SETTLED_EVENT_TYPES:
        return {"status": "ignored", "event": event_type, "reason": "unhandled_event_type"}
    if not invoice_id:
        return {"status": "ignored", "event": event_type, "reason": "missing_invoice_id"}
    # Dedupe on the BTCPay invoice id, namespaced so it can never collide with a
    # PayPal event id in the shared paypal_events table (the same reuse the
    # wallet-capture path relies on). The first settled delivery grants; every
    # later settled delivery -- including the sibling settled event type -- is a
    # no-op duplicate. Mirrors reserve_paypal_event exactly.
    dedupe_id = f"btcpay:{invoice_id}"
    with get_db() as conn:
        ensure_schema(conn)
        if not reserve_paypal_event(conn, dedupe_id, event_type, ""):
            existing = conn.execute(
                "SELECT status FROM paypal_events WHERE event_id=?", (dedupe_id,)
            ).fetchone()
            if existing is not None and existing["status"] in {"processed", "ignored"}:
                return {"status": "duplicate", "event": event_type}
            raise HTTPException(
                status_code=409,
                detail="BTCPay invoice processing is still in progress. Please retry.",
                headers={"Retry-After": "10"},
            )
    try:
        # Never grant from webhook fields alone: re-read the authoritative invoice
        # for its settled status AND its metadata (the delivery body carries
        # neither the amount nor the plan).
        invoice = btcpay_fetch_invoice(invoice_id)
        status = str(invoice.get("status") or "").strip().lower()
        if status not in BTCPAY_SETTLED_INVOICE_STATUSES:
            # The exception handler releases this reservation as failed.
            # A successful HTTP response would acknowledge an unsettled invoice
            # and could suppress the later settlement during the live lease.
            raise HTTPException(
                status_code=409,
                detail="BTCPay invoice settlement is not ready. Please retry.",
                headers={"Retry-After": "10"},
            )
        metadata = invoice.get("metadata") if isinstance(invoice.get("metadata"), dict) else {}
        plan_key = str(metadata.get("plan_key") or "").strip()
        if plan_key not in CRYPTO_PLAN_KEYS:
            with get_db() as conn:
                finish_paypal_event(conn, dedupe_id, "ignored", error="unrecognized_or_missing_plan_key")
            return {"status": "ignored", "event": event_type, "reason": "unrecognized_plan"}
        email = btcpay_invoice_buyer_email(invoice)
        if not email:
            # A settled invoice with no usable email cannot be auto-provisioned.
            # Alert and dead-letter it (retryable) rather than silently dropping a
            # real payment.
            security_alert(1, "settled btcpay invoice without buyer email", request=request, details={
                "invoice_id_hash": security_event_hash(invoice_id),
                "plan_key": plan_key,
            })
            raise RuntimeError("settled crypto invoice did not include a buyer email")
        subscriber_name = (str(metadata.get("buyerName") or "").strip() or "Wins VPN User")[:128]
        grant_plan_id, duration_text = crypto_grant_params(plan_key)
        label = crypto_plan_label(plan_key)
        with get_db() as conn:
            ensure_schema(conn)
            # H-1: bind this settlement to the hub-created order BEFORE granting.
            # BEGIN IMMEDIATE takes the writer lock so two concurrent settled
            # deliveries cannot both claim the same order (belt-and-suspenders on
            # top of the reserve_paypal_event dedupe above).
            conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            order = conn.execute(
                """
                SELECT hub_order_id, plan_key, expected_amount, expected_currency,
                       buyer_email, referral_code, promo_code, status
                FROM payment_orders
                WHERE provider='btcpay' AND provider_order_id=?
                """,
                (invoice_id,),
            ).fetchone()
            if order is None:
                # A settled invoice on the shared BTCPay store with NO hub order
                # bound to it -- exactly the H-1 foreign/reused-credential invoice.
                # Never grant; mark the dedupe row terminal so it is not retried,
                # and alert for review.
                finish_paypal_event(conn, dedupe_id, "ignored", error="btcpay_invoice_not_bound_to_hub_order")
                conn.commit()
                security_alert(1, "settled btcpay invoice not bound to a hub order", request=request, details={
                    "invoice_id_hash": security_event_hash(invoice_id),
                    "plan_key": plan_key,
                })
                return {"status": "ignored", "event": event_type, "reason": "unknown_invoice"}
            if order["status"] == "settled":
                finish_paypal_event(conn, dedupe_id, "processed", error="order_already_settled")
                return {"status": "duplicate", "event": event_type, "plan": plan_key}
            claimed = conn.execute(
                "UPDATE payment_orders SET status='processing' WHERE provider='btcpay' AND provider_order_id=? AND status IN ('pending', 'failed', 'processing')",
                (invoice_id,),
            ).rowcount
            if claimed != 1:
                finish_paypal_event(conn, dedupe_id, "processed", error="btcpay_order_not_claimable")
                return {"status": "duplicate", "event": event_type, "plan": plan_key}
            # H-1 settlement contract. requested is the invoice's own USD amount;
            # expected is the amount THIS hub locked at create time; paid falls
            # back to the invoice amount because a Greenfield "Settled" invoice is
            # guaranteed fully paid. hub_order_id/plan_key/currency must ALL match
            # the bound order, requested must equal what we priced, and paid must
            # cover it. The bound order owns the accepted purchase price;
            # changing the catalog price cannot invalidate that purchase.
            try:
                requested = Decimal(str(invoice.get("amount") or ""))
                paid = Decimal(str(invoice.get("paidAmount") or invoice.get("amount") or ""))
                expected = Decimal(str(order["expected_amount"] or ""))
            except (InvalidOperation, TypeError, ValueError):
                requested = paid = expected = Decimal("-1")
            contract_ok = (
                status == "settled"
                and str(metadata.get("hub_order_id") or "") == order["hub_order_id"]
                and str(metadata.get("plan_key") or "") == order["plan_key"]
                and plan_key == order["plan_key"]
                and str(invoice.get("currency") or "").upper() == order["expected_currency"]
                and expected.is_finite()
                and requested.is_finite()
                and paid.is_finite()
                and expected > 0
                and requested == expected
                and paid >= expected
            )
            if not contract_ok:
                conn.execute(
                    "UPDATE payment_orders SET status='manual_review' WHERE provider='btcpay' AND provider_order_id=?",
                    (invoice_id,),
                )
                finish_paypal_event(conn, dedupe_id, "failed", error="btcpay_settlement_contract_mismatch")
                conn.commit()
                security_alert(1, "btcpay settlement contract mismatch", request=request, details={
                    "invoice_id_hash": security_event_hash(invoice_id),
                    "plan_key": plan_key,
                })
                raise RuntimeError("BTCPay settlement contract mismatch")
            # Provision from the ORDER's stored provenance, never provider-returned
            # mutable metadata: the referral comes only from the order (a code that
            # resolved to a real referrer at create time), and the email prefers
            # the order's stored value, falling back to the invoice's checkout
            # email only when the buyer supplied none up front (BTCPay collects it
            # on its own hosted page). The bound invoice id is the purchase ref.
            grant_email = (order["buyer_email"] or "").strip().lower() or email
            grant_referral = normalize_referral_code(order["referral_code"])
            grant_promo = normalize_promo_code(order["promo_code"])
            account_number, created, expiry, activation_secrets = upsert_paypal_account(
                conn,
                email=grant_email,
                subscriber_name=subscriber_name,
                subscription_id="",
                plan_id=grant_plan_id,
                payer_id="",
                paypal_status="ACTIVE",
                next_billing_time=None,
                duration_text=duration_text,
                referral_code=grant_referral,
                purchase_reference=invoice_id,
                paypal_purchase_reference=invoice_id,
                promo_code=grant_promo,
            )
            conn.execute(
                "UPDATE payment_orders SET status='settled', settled_at=? WHERE provider='btcpay' AND provider_order_id=?",
                (utcnow().isoformat(), invoice_id),
            )
            if activation_secrets:
                enqueue_activation_delivery(conn, dedupe_id, grant_email, subscriber_name,
                                            account_number, f"Crypto {label}", activation_secrets)
            finish_paypal_event(conn, dedupe_id, "processed", account_number=account_number)
        return {"status": "ok", "event": event_type, "created": created, "plan": plan_key}
    except Exception as exc:
        with get_db() as conn:
            finish_paypal_event(conn, dedupe_id, "failed", error=str(exc))
        raise

@app.post("/admin/paypal/sync")
async def admin_paypal_sync(request: Request, lookahead_hours: int = Form(default=PAYPAL_SYNC_LOOKAHEAD_HOURS), x_admin_token: str = Header(...)):
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "paypal sync")
    return await asyncio.to_thread(sync_due_paypal_subscriptions, lookahead_hours)

@app.post("/admin/monero/poll")
async def admin_monero_poll(request: Request, background_tasks: BackgroundTasks, x_admin_token: str = Header(...)):
    # The timer and manual poll share the sweep lease. Each settlement commits
    # its activation outbox row atomically; no credential enters the response.
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "monero poll")
    if not monero_rpc_enabled():
        return {"enabled": False, "detail": "Monero wallet RPC is not configured"}
    return await run_monero_poll_sweep()

@app.get("/admin/paypal/dead-letter")
def admin_paypal_dead_letter(request: Request, status: str = "failed", limit: int = 50, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "paypal dead-letter list")
    status = (status or "failed").strip().lower()
    if status not in {"failed", "processing", "ignored", "processed"}:
        raise HTTPException(status_code=400, detail="Unsupported PayPal event status filter")
    limit = max(1, min(int(limit or 50), 200))
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT event_id, event_type, paypal_subscription_id, account_number,
                   status, attempts, last_error, received_at, updated_at
            FROM paypal_events
            WHERE status = ?
            ORDER BY COALESCE(updated_at, received_at) DESC
            LIMIT ?
        """, (status, limit)).fetchall()
        events = []
        for row in rows:
            item = dict(row)
            masked_subscription_id = mask_id(item.get("paypal_subscription_id"))
            item["paypal_subscription_id"] = masked_subscription_id
            item["paypal_subscription_id_masked"] = masked_subscription_id
            events.append(item)
        return {"status": status, "count": len(events), "events": events}

@app.post("/admin/paypal/retry")
def admin_paypal_retry(request: Request, background_tasks: BackgroundTasks, event_id: str = Form(...), x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "paypal dead-letter retry")
    event_id = (event_id or "").strip()
    if not event_id:
        raise HTTPException(status_code=400, detail="event_id is required")
    with get_db() as conn:
        ensure_schema(conn)
        row = conn.execute("SELECT * FROM paypal_events WHERE event_id = ?", (event_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="PayPal event not found")
        subscription_id = (row["paypal_subscription_id"] or "").strip()
        if not subscription_id:
            raise HTTPException(status_code=400, detail="This event has no subscription id to resync")
        conn.execute(
            "UPDATE paypal_events SET status='processing', attempts=COALESCE(attempts, 0) + 1, updated_at=? WHERE event_id=?",
            (utcnow().isoformat(), event_id),
        )
        try:
            result = sync_one_paypal_subscription(conn, subscription_id, background_tasks)
            finish_paypal_event(conn, event_id, "processed", account_number=result.get("account_number", ""))
            result["event_id"] = event_id
            result["subscription_id"] = mask_id(subscription_id)
            return {"status": "retried", "result": result}
        except Exception as exc:
            # Discard the sync's own uncommitted writes before recording the
            # failure; committing here would keep a half-applied resync.
            conn.rollback()
            finish_paypal_event(conn, event_id, "failed", error=str(exc))
            conn.commit()
            raise HTTPException(status_code=502, detail=f"PayPal retry failed: {exc}")

@app.get("/admin/payment-clicks")
def admin_payment_clicks(request: Request, days: int = 30, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "payment click summary")
    days = max(1, min(int(days or 30), 365))
    cutoff = (utcnow() - timedelta(days=days)).isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT option_key, source, COUNT(*) AS clicks, MIN(clicked_at) AS first_click, MAX(clicked_at) AS last_click
            FROM payment_clicks
            WHERE clicked_at >= ?
            GROUP BY option_key, source
            ORDER BY clicks DESC, last_click DESC
        """, (cutoff,)).fetchall()
        total = conn.execute("SELECT COUNT(*) AS clicks FROM payment_clicks WHERE clicked_at >= ?", (cutoff,)).fetchone()["clicks"]
        return {"days": days, "total_clicks": total, "groups": [dict(row) for row in rows]}

@app.get("/admin/free-access-events")
def admin_free_access_events(request: Request, days: int = 7, limit: int = 200, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "free access event list")
    days = max(1, min(int(days or 7), FREE_ACCESS_EVENTS_RETENTION_DAYS))
    limit = max(1, min(int(limit or 200), 500))
    cutoff = (utcnow() - timedelta(days=days)).isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT action, account_number, device_id_bucket, source_ip_bucket,
                   client_public_key_fingerprint, platform, device_model,
                   node_slug, stealth_mode, user_agent_hash, created_at
            FROM free_access_events
            WHERE created_at >= ?
            ORDER BY created_at DESC
            LIMIT ?
        """, (cutoff, limit)).fetchall()
        summary = conn.execute("""
            SELECT COUNT(*) AS events,
                   COUNT(DISTINCT device_id_bucket) AS devices,
                   COUNT(DISTINCT source_ip_bucket) AS sources
            FROM free_access_events
            WHERE created_at >= ?
        """, (cutoff,)).fetchone()
        return {
            "days": days,
            "limit": limit,
            "summary": dict(summary),
            "events": [dict(row) for row in rows],
        }

# --- Phase 3: prepaid redemption codes (roadmap A7 / A7a, HANDOFF 3e + 3j) ---
#
# One contiguous block so the whole feature can be reviewed in one place. The
# only edit outside it is the single create_redemption_tables(conn) call added
# to ensure_schema().
#
# Shape of a redemption, in order, and why the order is the design:
#   1. rate limit on gateway-observed identity only (never a client header)
#   2. ONE BEGIN IMMEDIATE transaction: claim the code, create the account,
#      store the setup-key digest, seal the setup key into a short-lived
#      fulfillment record, append the immutable audit event, insert the outbox
#      row. No network call is made while that writer lock is held.
#   3. commit
#   4. the durability barrier (litestream sync -wait -json), fail-closed
#   5. only then acknowledge -- returning the setup key exactly once
# An idempotent retry re-enters at 2, finds the fulfillment record, and STILL
# crosses the barrier at 4. That is the HANDOFF 3j invariant: the row saying
# "done" is not evidence that the row is replicated.

# Crockford Base32. I, L, O and U are absent by construction, which is what
# lets the website normalise 1/I, 0/O and U/V rather than reject them
# (web/index.html, normaliseRedemptionCode). 26 payload symbols = 130 raw
# bits; the 27th symbol is a Crockford check symbol and carries no secret
# entropy. See mint_redemption_code for the exact effective-entropy figure.
REDEMPTION_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
REDEMPTION_PAYLOAD_SYMBOLS = 26
REDEMPTION_CODE_SYMBOLS = REDEMPTION_PAYLOAD_SYMBOLS + 1
REDEMPTION_GROUP_SIZE = 4

# A dedicated, versioned redemption keyring -- deliberately NOT ADMIN_TOKEN and
# deliberately NOT RATE_LIMIT_SECRET, which already falls back to SPA_HMAC or
# ADMIN_TOKEN (see the RATE_LIMIT_SECRET assignment near the top of this file).
# Extending that fallback chain is exactly the coupling this key exists to
# avoid. Format: "v1:<hex>,v2:<hex>"; REDEMPTION_KEY_ACTIVE_VERSION names the
# version new batches are minted under. Older versions stay in the ring so
# already-printed cards keep verifying after a rotation -- a one-shot code's
# HMAC cannot be recomputed under a new key without the plaintext, so rotation
# is forward-only by construction.
REDEMPTION_KEYS_RAW = os.getenv("REDEMPTION_KEYS", "").strip()
REDEMPTION_KEY_ACTIVE_VERSION = os.getenv("REDEMPTION_KEY_ACTIVE_VERSION", "v1").strip() or "v1"

# How long a fulfillment record (the sealed setup key) survives so a customer
# whose HTTP response was lost can retry the same code and recover the same
# entitlement. Short by design: it is the only place a usable setup key exists
# at rest, and it is sealed even there.
REDEMPTION_FULFILLMENT_TTL_SECONDS = max(60, min(3600, int(os.getenv("REDEMPTION_FULFILLMENT_TTL_SECONDS", "900"))))
# Rolling windows, never lifetime counters (Part C, C3). Ceiling well under the
# 15-minute maximum backoff C3 mandates.
REDEMPTION_IP_RATE_LIMIT_PER_MINUTE = int(os.getenv("REDEMPTION_IP_RATE_LIMIT_PER_MINUTE", "8"))
REDEMPTION_IP_RATE_LIMIT_PER_HOUR = int(os.getenv("REDEMPTION_IP_RATE_LIMIT_PER_HOUR", "40"))
# A code is one-shot, so repeated attempts against one code are always abuse.
REDEMPTION_CODE_RATE_LIMIT_PER_HOUR = int(os.getenv("REDEMPTION_CODE_RATE_LIMIT_PER_HOUR", "5"))
REDEMPTION_RETRY_AFTER_SECONDS = max(1, min(900, int(os.getenv("REDEMPTION_RETRY_AFTER_SECONDS", "300"))))
REDEMPTION_OUTBOX_MAX_ATTEMPTS = max(1, int(os.getenv("REDEMPTION_OUTBOX_MAX_ATTEMPTS", "12")))
REDEMPTION_OUTBOX_LEASE_SECONDS = max(30, int(os.getenv("REDEMPTION_OUTBOX_LEASE_SECONDS", "300")))
REDEMPTION_OUTBOX_BATCH_LIMIT = max(1, min(200, int(os.getenv("REDEMPTION_OUTBOX_BATCH_LIMIT", "25"))))
REDEMPTION_BATCH_MAX_CODES = max(1, min(20000, int(os.getenv("REDEMPTION_BATCH_MAX_CODES", "5000"))))
# Kept in lockstep with the guarded DELETE trigger in create_redemption_tables.
REDEMPTION_DECLINED_EVENT_RETENTION_DAYS = 30

# --- durability barrier (HANDOFF 3j) ---------------------------------------
# RPO 0 for acknowledged money/entitlement/identity writes requires that a
# critical endpoint does not acknowledge success until its transaction is
# confirmed replicated remotely. Litestream's `sync -wait` blocks until both
# WAL-to-LTX conversion and LTX-to-remote replication complete.
#
# ONE interface is pinned: the COMMAND-LINE interface, whose replicated field
# is `replica_txid`. The IPC API calls the same field `replicated_txid`; a
# parser reading the wrong name sees "absent", and an absent field must never
# compare equal to anything, so seeing `replicated_txid` without `replica_txid`
# is treated as an unexpected interface and FAILS CLOSED rather than passing.
LITESTREAM_BIN = os.getenv("LITESTREAM_BIN", "/usr/local/bin/litestream")
# LSR integration on H0: the control socket the installer writes into
# /etc/litestream.yml. `litestream sync` does not read that file; without
# -socket it dials /var/run/litestream.sock, which is outside the one runtime
# directory (/run/litestream) bound into this unit's empty /run.
LITESTREAM_SOCKET_PATH = "/run/litestream/litestream.sock"
# Pinned release. The deployment script verifies the downloaded archive against
# LITESTREAM_SHA256 before installing, and refuses to install without it; this
# constant is the runtime half of the same pin.
# `sync -wait` requires 0.5.9+ and its `-json` output requires 0.5.12+. Keep
# this in lockstep with LITESTREAM_VERSION_DEFAULT in the installer above.
LITESTREAM_PINNED_VERSION = os.getenv("LITESTREAM_PINNED_VERSION", "0.5.17").strip()
LITESTREAM_SYNC_TIMEOUT_SECONDS = max(1, min(120, int(os.getenv("LITESTREAM_SYNC_TIMEOUT_SECONDS", "30"))))
# The JSON key carrying the database identity in `litestream sync -json`
# output. Pinned as a named constant precisely so a field-name drift between
# Litestream versions is a one-line, reviewed change and never a silent
# false-positive durability check: any other shape fails closed.
#
# CONFIRMED against the real 0.5.15 binary, not inferred. A successful
# `sync -wait -timeout 30 -json` emits exactly:
#     {"db_path": "...", "txid": N, "replica_txid": N, "duration_ms": M}
# `duration_ms` is additional and ignored; unknown extra keys are not grounds to
# reject. The load-bearing observation is that `replica_txid` is tagged
# `omitempty` in the release binary, so DROPPING `-wait` makes the field VANISH
# rather than report a stale value -- which is precisely why a parser that used
# .get(..., 0) or compared a default would silently pass. Absent must fail.
LITESTREAM_DB_PATH_FIELD = "db_path"
# Fail-closed switch. When the barrier is disabled the endpoint does not
# quietly acknowledge unreplicated writes -- it refuses to issue entitlements
# at all, because "no barrier" and "RPO 0" cannot both be true.
DURABILITY_BARRIER_ENABLED = os.getenv("DURABILITY_BARRIER_ENABLED", "1").strip().lower() in {"1", "true", "yes", "on"}
DURABILITY_BARRIER_REQUIRED = os.getenv("DURABILITY_BARRIER_REQUIRED", "1").strip().lower() in {"1", "true", "yes", "on"}

REDEMPTION_DECLINED_RESPONSE = {
    "ok": False,
    "status": "not_redeemable",
    # C4 / 3e.8: "invalid" and "already redeemed" deliberately share one
    # status, one body and one HTTP code. The website already renders a single
    # message for both (web/index.html) -- this is the server half of that
    # contract, and it is the half that actually matters.
    "message": "That code is not valid, or has already been redeemed.",
}


class DurabilityBarrierError(RuntimeError):
    """Raised when a committed write could not be confirmed replicated.

    Every call site treats this as retryable-but-not-successful: the customer
    gets a 503 and no setup key, the code stays claimed, the fulfillment record
    stays sealed, and an identical retry recovers the same entitlement -- after
    crossing the barrier itself.
    """

    def __init__(self, reason: str, detail: str = ""):
        self.reason = reason
        self.detail = detail
        super().__init__(f"{reason}: {detail}" if detail else reason)


def _redemption_keyring() -> list:
    # Parsed on every call rather than cached at import so a rotated
    # /root/vpn_auth.env takes effect on service restart without a code change,
    # and so the tests can exercise malformed keyrings.
    ring = []
    seen = set()
    for chunk in REDEMPTION_KEYS_RAW.split(","):
        chunk = chunk.strip()
        if not chunk or ":" not in chunk:
            continue
        version, _, material = chunk.partition(":")
        version = version.strip()
        material = material.strip()
        if not version or not material or version in seen:
            continue
        # A short key is a misconfiguration, not something to paper over.
        if len(material) < 32:
            logger.warning("Ignoring redemption key version %s: key material is too short", version)
            continue
        seen.add(version)
        ring.append((version, material.encode()))
    return ring


def redemption_enabled() -> bool:
    ring = _redemption_keyring()
    return bool(ring) and any(version == REDEMPTION_KEY_ACTIVE_VERSION for version, _ in ring)


def _redemption_key_material(version: str) -> bytes:
    for candidate, material in _redemption_keyring():
        if candidate == version:
            return material
    raise HTTPException(status_code=503, detail="Redemption is not configured on this hub.")


def _hkdf_sha256(key_material: bytes, info: bytes, length: int = 32) -> bytes:
    # RFC 5869 HKDF over SHA-256, stdlib only. The extract salt is fixed
    # because the input is already a high-entropy per-deployment key; the
    # expand step is what provides domain separation between the lookup HMAC
    # and the two fulfillment subkeys, so one leaked subkey never yields the
    # others.
    prk = hmac.new(b"\x00" * hashlib.sha256().digest_size, key_material, hashlib.sha256).digest()
    out = b""
    block = b""
    counter = 1
    while len(out) < length:
        block = hmac.new(prk, block + info + bytes([counter]), hashlib.sha256).digest()
        out += block
        counter += 1
    return out[:length]


def normalize_redemption_code(raw: Any) -> str:
    # Byte-for-byte the same folding the website performs before it POSTs
    # (web/index.html normaliseRedemptionCode): upper-case, drop everything
    # outside A-Z0-9, then fold the four confusable letters Crockford Base32
    # does not use. Doing it again here is not redundant -- the app and any
    # future client must land on the identical canonical string, because that
    # string is the HMAC input.
    text = str(raw or "").upper()
    text = re.sub(r"[^A-Z0-9]", "", text)
    text = text.replace("I", "1").replace("L", "1").replace("O", "0").replace("U", "V")
    return text[:64]


def crockford_check_symbol(payload: str) -> str:
    # Crockford's check symbol: the payload's base-32 value mod 37. 37 is
    # prime, which is what guarantees detection of every single-symbol error
    # and every adjacent transposition.
    value = 0
    for ch in payload:
        index = REDEMPTION_ALPHABET.find(ch)
        if index < 0:
            raise ValueError("payload contains a non-Crockford symbol")
        value = value * 32 + index
    return REDEMPTION_ALPHABET[value % 37] if value % 37 < 32 else ""


def redemption_code_well_formed(normalized: str) -> bool:
    if len(normalized) != REDEMPTION_CODE_SYMBOLS:
        return False
    if any(ch not in REDEMPTION_ALPHABET for ch in normalized):
        return False
    expected = crockford_check_symbol(normalized[:-1])
    # An empty expected symbol means this payload's check value landed in
    # 32..36, which mint_redemption_code never issues -- so the code cannot be
    # one of ours regardless of what its final symbol is.
    return bool(expected) and hmac.compare_digest(expected, normalized[-1])


def format_redemption_code(normalized: str) -> str:
    return "-".join(
        normalized[i:i + REDEMPTION_GROUP_SIZE]
        for i in range(0, len(normalized), REDEMPTION_GROUP_SIZE)
    )


def mint_redemption_code() -> str:
    # 26 uniform draws from a 32-symbol alphabet = 130 raw bits, then a
    # Crockford check symbol appended.
    #
    # The check value is `payload mod 37`. Crockford maps values 32..36 to
    # '*', '~', '$', '=' and 'U' -- and every one of those five is destroyed by
    # the normalisation the website already performs ('*~$=' are stripped as
    # non-alphanumeric, 'U' is folded to 'V'). So issuance rejects any payload
    # whose check value lands there and draws again. That keeps the whole code
    # inside the 32-symbol alphabet, preserves Crockford's mod-37 detection
    # property, and costs a measurable, stated amount of entropy:
    #
    #   effective entropy = log2(#{payload : payload mod 37 < 32})
    #                     = log2(32**26 * 32/37)
    #                     = 130 - log2(37/32)
    #                     = 129.7905 bits
    #
    # after normalisation and with the checksum symbol removed, which is the
    # figure HANDOFF 3e.1 asks for. The check symbol contributes zero.
    while True:
        payload = "".join(secrets.choice(REDEMPTION_ALPHABET) for _ in range(REDEMPTION_PAYLOAD_SYMBOLS))
        check = crockford_check_symbol(payload)
        if check:
            return payload + check


def redemption_code_hash(normalized: str, version: str) -> str:
    # Server-keyed HMAC, not a bare hash: domain-separated from every other
    # token digest in this database, unusable for testing candidate codes by
    # anyone holding only a database copy, and stable only within one
    # deployment so the same code never fingerprints identically across
    # exports, backups and systems.
    key = _hkdf_sha256(_redemption_key_material(version), b"wins-redeem-lookup-hmac/v1")
    return hmac.new(key, f"wins-redeem:{version}:{normalized}".encode(), hashlib.sha256).hexdigest()


def redemption_idempotency_key(normalized: str, version: str) -> str:
    # Derived ONLY from the code, never from a client-supplied value. The
    # request being retried is "this code", so the code is the idempotency
    # key: a customer who re-types the same code after a lost response must
    # land on the same fulfillment record, and a client that invents a fresh
    # key per attempt must not be able to route around it.
    key = _hkdf_sha256(_redemption_key_material(version), b"wins-redeem-idempotency/v1")
    return hmac.new(key, f"wins-redeem-idem:{version}:{normalized}".encode(), hashlib.sha256).hexdigest()


def _fulfillment_keystream(key: bytes, nonce: bytes, length: int) -> bytes:
    out = b""
    counter = 0
    while len(out) < length:
        out += hmac.new(key, nonce + counter.to_bytes(8, "big"), hashlib.sha256).digest()
        counter += 1
    return out[:length]


def seal_fulfillment_secret(plaintext: str, version: str, aad: str) -> str:
    # Encrypt-then-MAC with two HKDF-separated subkeys: an HMAC-SHA256 counter
    # keystream for confidentiality and an HMAC-SHA256 tag over
    # version | aad | nonce | ciphertext for integrity and binding.
    #
    # Why not AES-GCM: server/control-plane-requirements.lock is a
    # hash-pinned, pip-compile-generated lock, and `cryptography` is not in it.
    # Adding a dependency there requires regenerating the lock on linux/amd64
    # with network access (the recipe is documented at the top of
    # control-plane-requirements.in), which is a separate, reviewable supply-
    # chain change -- not something to smuggle in behind a redemption endpoint.
    # This construction uses only hmac/hashlib/secrets from the standard
    # library and is bound to the record it belongs to by the AAD, so a sealed
    # setup key cannot be transplanted onto another fulfillment row.
    material = _redemption_key_material(version)
    enc_key = _hkdf_sha256(material, b"wins-redeem-fulfillment-enc/v1")
    mac_key = _hkdf_sha256(material, b"wins-redeem-fulfillment-mac/v1")
    nonce = secrets.token_bytes(16)
    data = plaintext.encode()
    stream = _fulfillment_keystream(enc_key, nonce, len(data))
    ciphertext = bytes(a ^ b for a, b in zip(data, stream))
    tag = hmac.new(
        mac_key,
        b"wins-redeem-seal/v1|" + version.encode() + b"|" + aad.encode() + b"|" + nonce + b"|" + ciphertext,
        hashlib.sha256,
    ).digest()
    return "|".join([
        "wrs1",
        base64.b64encode(nonce).decode(),
        base64.b64encode(ciphertext).decode(),
        base64.b64encode(tag).decode(),
    ])


def open_fulfillment_secret(sealed: str, version: str, aad: str) -> str:
    parts = str(sealed or "").split("|")
    if len(parts) != 4 or parts[0] != "wrs1":
        raise ValueError("unrecognised sealed fulfillment record")
    try:
        nonce = base64.b64decode(parts[1], validate=True)
        ciphertext = base64.b64decode(parts[2], validate=True)
        tag = base64.b64decode(parts[3], validate=True)
    except Exception as exc:
        raise ValueError("malformed sealed fulfillment record") from exc
    material = _redemption_key_material(version)
    enc_key = _hkdf_sha256(material, b"wins-redeem-fulfillment-enc/v1")
    mac_key = _hkdf_sha256(material, b"wins-redeem-fulfillment-mac/v1")
    expected = hmac.new(
        mac_key,
        b"wins-redeem-seal/v1|" + version.encode() + b"|" + aad.encode() + b"|" + nonce + b"|" + ciphertext,
        hashlib.sha256,
    ).digest()
    if not hmac.compare_digest(expected, tag):
        raise ValueError("sealed fulfillment record failed authentication")
    stream = _fulfillment_keystream(enc_key, nonce, len(ciphertext))
    return bytes(a ^ b for a, b in zip(ciphertext, stream)).decode()


def parse_litestream_sync_result(exit_code: Any, stdout: str, stderr: str, expected_db_path: str) -> dict:
    # THE PINNED PARSER (HANDOFF 3j). Accept only when ALL FIVE hold:
    #   process exit == 0
    #   db_path      == canonical expected path
    #   txid         is a positive integer
    #   replica_txid is a positive integer
    #   replica_txid == txid
    # Missing, null, wrong-type, malformed and unexpected-interface fields all
    # fail closed. There is deliberately NO comparison against an application
    # commit id: SQLite exposes no Litestream transaction id, Litestream's txid
    # is its own LTX position, and because the barrier runs AFTER the commit the
    # confirmed position already encompasses it.
    def _positive_int(value: Any) -> Optional[int]:
        # bool is a subclass of int in Python; True must never be read as 1.
        if isinstance(value, bool) or not isinstance(value, int):
            return None
        return value if value > 0 else None

    if exit_code != 0:
        raise DurabilityBarrierError("exit_status", f"exit={exit_code} stderr={str(stderr or '')[:200]}")
    text = str(stdout or "").strip()
    if not text:
        raise DurabilityBarrierError("empty_output")
    try:
        payload = json.loads(text)
    except Exception as exc:
        raise DurabilityBarrierError("malformed_json", str(exc)[:200]) from exc
    if not isinstance(payload, dict):
        raise DurabilityBarrierError("unexpected_payload_shape", type(payload).__name__)
    if "replica_txid" not in payload and "replicated_txid" in payload:
        # `replicated_txid` is the IPC interface's name for this field. We pin
        # the CLI interface; reading a different interface's schema is exactly
        # the silent false positive HANDOFF 3j warns about, so seeing the other
        # name where ours should be is a hard stop rather than a fallback.
        raise DurabilityBarrierError("unexpected_interface", "response uses the IPC field name, not the pinned CLI name")
    reported_path = payload.get(LITESTREAM_DB_PATH_FIELD)
    if not isinstance(reported_path, str) or not reported_path:
        raise DurabilityBarrierError("db_path_missing_or_wrong_type", repr(reported_path)[:120])
    if os.path.realpath(reported_path) != os.path.realpath(expected_db_path):
        raise DurabilityBarrierError("db_path_mismatch", f"{reported_path} != {expected_db_path}")
    if "replica_txid" not in payload:
        raise DurabilityBarrierError("replica_txid_missing")
    txid = _positive_int(payload.get("txid"))
    replica_txid = _positive_int(payload.get("replica_txid"))
    if txid is None:
        raise DurabilityBarrierError("txid_missing_or_wrong_type", repr(payload.get("txid"))[:120])
    if replica_txid is None:
        raise DurabilityBarrierError("replica_txid_missing_or_wrong_type", repr(payload.get("replica_txid"))[:120])
    if replica_txid != txid:
        raise DurabilityBarrierError("replica_behind_primary", f"replica_txid={replica_txid} txid={txid}")
    return {"db_path": reported_path, "txid": txid, "replica_txid": replica_txid}


def _run_litestream_sync(db_path: str) -> tuple:
    # Isolated so tests can substitute a fake runner that exercises every
    # failure mode without a Litestream install. Returns (exit, stdout, stderr).
    command = [
        LITESTREAM_BIN, "sync",
        "-socket", LITESTREAM_SOCKET_PATH,
        "-wait",
        "-timeout", str(LITESTREAM_SYNC_TIMEOUT_SECONDS),
        "-json",
        db_path,
    ]
    try:
        completed = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=LITESTREAM_SYNC_TIMEOUT_SECONDS + 5,
            check=False,
        )
    except FileNotFoundError as exc:
        raise DurabilityBarrierError("litestream_unavailable", str(exc)[:200]) from exc
    except subprocess.TimeoutExpired as exc:
        raise DurabilityBarrierError("timeout", f"litestream sync exceeded {LITESTREAM_SYNC_TIMEOUT_SECONDS + 5}s") from exc
    except Exception as exc:
        raise DurabilityBarrierError("litestream_invocation_failed", str(exc)[:200]) from exc
    return completed.returncode, completed.stdout, completed.stderr


_DURABILITY_BARRIER_RUNNER = _run_litestream_sync


def run_durability_barrier(db_path: Optional[str] = None, *, runner=None) -> dict:
    # Commit -> barrier -> validate -> acknowledge. Called AFTER the
    # transaction has committed and BEFORE any success is returned or any
    # external side effect is released, on EVERY path including an idempotent
    # retry that found an already-committed result.
    target = db_path or DB_PATH
    if not DURABILITY_BARRIER_ENABLED:
        if DURABILITY_BARRIER_REQUIRED:
            raise DurabilityBarrierError("barrier_disabled", "DURABILITY_BARRIER_ENABLED=0 with DURABILITY_BARRIER_REQUIRED=1")
        # Explicitly opted out on both switches: a non-production/disposable
        # deployment that has accepted it cannot claim RPO 0.
        return {"skipped": True, "db_path": target}
    exit_code, stdout, stderr = (runner or _DURABILITY_BARRIER_RUNNER)(target)
    return parse_litestream_sync_result(exit_code, stdout, stderr, target)


def create_redemption_tables(conn: sqlite3.Connection):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS redemption_batches (
            batch_id TEXT PRIMARY KEY,
            label TEXT,
            partner TEXT,
            plan_key TEXT,
            duration TEXT DEFAULT '1m',
            issued_count INTEGER DEFAULT 0,
            canary_count INTEGER DEFAULT 0,
            key_version TEXT,
            expires_at TEXT,
            revoked_at TEXT,
            revoked_reason TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    # code_hash is a keyed HMAC; the plaintext code exists only on the printed
    # card and in the one-time encrypted export handed to the printer.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS redemption_codes (
            code_hash TEXT NOT NULL,
            key_version TEXT NOT NULL,
            batch_id TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'unused',
            is_canary INTEGER NOT NULL DEFAULT 0,
            account_number TEXT,
            expires_at TEXT,
            redeemed_at TEXT,
            redeemed_source_bucket TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (code_hash, key_version)
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_redemption_codes_batch ON redemption_codes(batch_id, status)")
    # Append-only audit log. The UPDATE trigger below is unconditional; the
    # DELETE trigger permits exactly one thing -- pruning DECLINED probe rows
    # once they are older than REDEMPTION_DECLINED_EVENT_RETENTION_DAYS -- so
    # an attacker cannot grow this table without bound while every grant,
    # recovery, revocation and canary event stays immutable forever.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS redemption_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE,
            occurred_at TEXT NOT NULL,
            outcome TEXT NOT NULL,
            batch_id TEXT,
            code_hash TEXT,
            key_version TEXT,
            account_number TEXT,
            idempotency_key TEXT,
            source_ip_bucket TEXT,
            user_agent_hash TEXT,
            detail TEXT
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_redemption_events_occurred ON redemption_events(occurred_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_redemption_events_batch ON redemption_events(batch_id, outcome)")
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS redemption_events_append_only_update
        BEFORE UPDATE ON redemption_events
        BEGIN
            SELECT RAISE(ABORT, 'redemption_events is append-only');
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS redemption_events_append_only_delete
        BEFORE DELETE ON redemption_events
        WHEN OLD.outcome <> 'declined'
          OR OLD.occurred_at >= strftime('%Y-%m-%dT%H:%M:%S', 'now', '-30 days')
        BEGIN
            SELECT RAISE(ABORT, 'redemption_events is append-only');
        END
    """)
    # The sealed setup key. Never plaintext at rest, never logged, short TTL,
    # explicit deletion (acknowledge early via /api/redeem/ack, or the outbox
    # sweep hard-deletes at expiry).
    conn.execute("""
        CREATE TABLE IF NOT EXISTS redemption_fulfillments (
            idempotency_key TEXT PRIMARY KEY,
            code_hash TEXT NOT NULL,
            key_version TEXT NOT NULL,
            batch_id TEXT,
            account_number TEXT NOT NULL,
            expiration_date TEXT,
            sealed_setup_key TEXT NOT NULL,
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            acknowledged_at TEXT
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_redemption_fulfillments_expiry ON redemption_fulfillments(expires_at)")
    # Transactional outbox. Written inside the same transaction as the claim;
    # drained afterwards, never during.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS redemption_outbox (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            idempotency_key TEXT NOT NULL UNIQUE,
            kind TEXT NOT NULL,
            account_number TEXT,
            target_email TEXT,
            batch_id TEXT,
            status TEXT NOT NULL DEFAULT 'pending',
            attempts INTEGER NOT NULL DEFAULT 0,
            lease_until TEXT,
            last_error TEXT,
            delivered_at TEXT,
            barrier_confirmed_at TEXT,
            created_at TEXT NOT NULL,
            completed_at TEXT
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_redemption_outbox_status ON redemption_outbox(status, lease_until)")
    # The welcome mail's own sealed copy of the whole key set (K3-04), kept apart
    # from the API fulfillment record so that acknowledging or expiring that
    # record never destroys keys the API did not show. NULL on rows written
    # before this column and on rows with no email to mail.
    add_column_if_missing(conn, "redemption_outbox", "sealed_secret", "TEXT")
    # R2 (promo, referral, prepaid channels). Additive and idempotent: old
    # batches read as channel 'direct', old code rows keep NULL serials and
    # NULL grant spans (a refund of such a row needs manual reconciliation).
    for column, ddl in (
        ("channel", "TEXT NOT NULL DEFAULT 'direct'"),
        ("distribution_reference", "TEXT NOT NULL DEFAULT ''"),
    ):
        add_column_if_missing(conn, "redemption_batches", column, ddl)
    for column, ddl in (
        ("serial", "TEXT"),
        ("grant_mode", "TEXT"),
        ("grant_start", "TEXT"),
        ("grant_end", "TEXT"),
        ("referral_bonus_days", "INTEGER NOT NULL DEFAULT 0"),
        ("promo_code", "TEXT"),
        ("promo_bonus_days", "INTEGER NOT NULL DEFAULT 0"),
        ("revoked_reason", "TEXT"),
        ("refund_reference", "TEXT"),
    ):
        add_column_if_missing(conn, "redemption_codes", column, ddl)
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_redemption_codes_serial "
        "ON redemption_codes(serial) WHERE serial IS NOT NULL"
    )
    # Promo campaigns grant bonus days only (never a price change). The code is
    # a public marketing string, not a bearer secret, so it is stored as typed
    # (normalised); value is bounded by bonus_days, max_uses and expires_at.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS promo_campaigns (
            code TEXT PRIMARY KEY,
            bonus_days INTEGER NOT NULL CHECK (bonus_days BETWEEN 1 AND 365),
            max_uses INTEGER NOT NULL CHECK (max_uses BETWEEN 1 AND 100000),
            uses INTEGER NOT NULL DEFAULT 0,
            expires_at TEXT NOT NULL,
            plan_keys TEXT NOT NULL DEFAULT '',
            stack_referral INTEGER NOT NULL DEFAULT 0,
            note TEXT NOT NULL DEFAULT '',
            revoked_at TEXT,
            revoked_reason TEXT,
            created_at TEXT NOT NULL
        )
    """)
    # One use per campaign per account. reversed_at marks a use whose funding
    # purchase was refunded; the campaign's use count is not given back.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS promo_redemptions (
            code TEXT NOT NULL,
            account_number TEXT NOT NULL,
            purchase_reference TEXT NOT NULL,
            bonus_days INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            reversed_at TEXT,
            PRIMARY KEY (code, account_number)
        )
    """)


def record_redemption_event(
    conn: sqlite3.Connection,
    *,
    outcome: str,
    request: Optional[Request] = None,
    batch_id: str = "",
    code_hash: str = "",
    key_version: str = "",
    account_number: str = "",
    idempotency_key: str = "",
    detail: str = "",
) -> str:
    event_id = secrets.token_hex(16)
    user_agent = (request.headers.get("user-agent", "") if request else "")
    conn.execute("""
        INSERT INTO redemption_events (
            event_id, occurred_at, outcome, batch_id, code_hash, key_version,
            account_number, idempotency_key, source_ip_bucket, user_agent_hash, detail
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        event_id,
        utcnow().isoformat(),
        outcome,
        batch_id or None,
        code_hash or None,
        key_version or None,
        account_number or None,
        idempotency_key or None,
        security_event_hash(request_origin_bucket_value(request)) if request else None,
        security_event_hash(user_agent) if user_agent else None,
        (detail or "")[:200] or None,
    ))
    return event_id


def _redemption_rate_limit_buckets(request: Request, code_hashes: list) -> list:
    # 3e.7: gateway-observed trusted client identity ONLY.
    # request_origin_bucket_value -> _trusted_forwarded_client_ip, which honours
    # a forwarding header only when the immediate TCP peer is inside
    # TRUSTED_PROXY_NETWORKS and otherwise falls back to the real socket peer.
    # No client-supplied header reaches this. Not widened here.
    source = request_origin_bucket_value(request)
    buckets = [
        (rate_limit_bucket("redeem-ip-minute", source), REDEMPTION_IP_RATE_LIMIT_PER_MINUTE, 60),
        (rate_limit_bucket("redeem-ip-hour", source), REDEMPTION_IP_RATE_LIMIT_PER_HOUR, 3600),
    ]
    for code_hash in code_hashes:
        buckets.append(
            (rate_limit_bucket("redeem-code", code_hash), REDEMPTION_CODE_RATE_LIMIT_PER_HOUR, 3600)
        )
    return buckets

def _redemption_rate_limited(retry_after: bool = True) -> HTTPException:
    # C5.2: machine-readable retry-after so the client can honour backoff
    # instead of hammering its own limiter. The per-code bucket is keyed by
    # the HMAC of whatever was typed, so a 429 exists for invalid input
    # exactly as it does for valid input and leaks nothing.
    return HTTPException(
        status_code=429,
        detail="Too many attempts. Please wait and try again.",
        headers={"Retry-After": str(REDEMPTION_RETRY_AFTER_SECONDS)} if retry_after else {},
    )

def precheck_redemption_rate_limits(conn: sqlite3.Connection, request: Request, code_hashes: list):
    # C3: READ-ONLY. This used to consume every bucket at the top of
    # /api/redeem, which meant a SUCCESSFUL redemption, an idempotent recovery
    # and an acknowledgement all burned the same budget a brute-force attempt
    # does. Shared-egress customers exhausted it without a single failure.
    #
    # Consumption now happens in consume_redemption_failure_budget, once the
    # transaction has actually declined.
    for bucket, limit, _window in _redemption_rate_limit_buckets(request, code_hashes):
        try:
            precheck_rate_limit(conn, bucket, limit)
        except HTTPException as exc:
            if exc.status_code != 429:
                raise
            raise _redemption_rate_limited()

def consume_redemption_failure_budget(conn: sqlite3.Connection, request: Request, code_hashes: list):
    # Called ONLY after redeem_code_transaction returned "declined" -- a
    # well-formed code that is invalid or already redeemed. That is the genuine
    # redemption failure. NOT called for a malformed code, a successful grant,
    # an idempotent recovery, or an acknowledgement.
    try:
        for bucket, limit, window in _redemption_rate_limit_buckets(request, code_hashes):
            consume_auth_failure(conn, bucket, limit, window)
    except HTTPException as exc:
        if exc.status_code != 429:
            raise
        # Commit the increment that tripped the limit before unwinding.
        # get_db() only commits on the success path, so without this the
        # rejecting increment is rolled back when the connection closes.
        conn.commit()
        raise _redemption_rate_limited()
    conn.commit()


def require_durability_barrier(request: Optional[Request], context: str, details: Optional[dict] = None) -> None:
    # Single fail-closed wrapper so every acknowledgement path -- customer
    # facing and admin -- turns a barrier failure into a retryable 503 rather
    # than a success or an opaque 500.
    try:
        run_durability_barrier()
    except DurabilityBarrierError as exc:
        logger.error("Durability barrier failed for %s (%s); withholding acknowledgement", context, exc.reason)
        security_alert(1, "redemption durability barrier failed", request=request, details={
            "context": context,
            "reason": exc.reason,
            **(details or {}),
        })
        raise HTTPException(
            status_code=503,
            detail="The change was accepted but could not be confirmed as replicated. Retry the identical request.",
            headers={"Retry-After": "5"},
        )


def _redemption_code_candidates(normalized: str) -> list:
    # One (version, hash, idempotency key) triple per configured key version.
    # The same work is done for every input, valid or not.
    candidates = []
    for version, _material in _redemption_keyring():
        candidates.append((version, redemption_code_hash(normalized, version), redemption_idempotency_key(normalized, version)))
    return candidates


# --- R2: channels, promo campaigns, existing-account extension -----------
# Where a batch went. Retail channels sell a fixed access term and must not
# expire before redemption (term-denominated, no stored value; see
# out/SYNTHESIS.md 2.5). giveaway and support codes were never paid for, so
# they earn no referral bonus.
REDEMPTION_CHANNELS = ("direct", "printer", "amazon", "reseller", "giveaway", "support")
REDEMPTION_RETAIL_CHANNELS = ("printer", "amazon", "reseller")
REDEMPTION_REFERRAL_INELIGIBLE_CHANNELS = ("giveaway", "support")
PROMO_CODE_PATTERN = re.compile(r"[A-Z0-9][A-Z0-9_-]{3,31}")
PROMO_PLAN_KEYS = ("prepaid", "one_month", "one_year", "lifetime_support", "lifetime_no_support")

# R2-EN: every message below is a new English string; its Burmese lives in the website's translations.my map and the app's _t map, keyed by this exact English.
REDEMPTION_REFUSAL_MESSAGES = {
    "account_not_found": "That account number was not found. Check it, or leave the field empty to create a new account. Your code has not been used.",
    "account_inactive": "That account is not active. Redeem the code for a new account instead, or contact support. Your code has not been used.",
    "account_recurring": "That account renews through a PayPal subscription and cannot be extended with a prepaid code. Redeem it for a new account, or contact support. Your code has not been used.",
    "account_not_eligible": "That account cannot be extended with a prepaid code. Contact support. Your code has not been used.",
    "referral_invalid": "That referral code cannot be used. Check it or leave the field empty. Your code has not been used.",
    "referral_not_allowed": "Referral codes cannot be used with this card. Leave the field empty. Your code has not been used.",
    "referral_used": "This account has already received its one referral bonus. Leave the referral field empty. Your code has not been used.",
    "promo_invalid": "That promo code is not valid or has expired. Check it or leave the field empty. Your code has not been used.",
    "promo_no_stack": "That promo code cannot be combined with a referral code. Remove one of them. Your code has not been used.",
    "promo_used": "This account has already used that promo code. Leave the field empty. Your code has not been used.",
}


def normalize_promo_code(value: Any) -> str:
    text = str(value or "").strip().upper()
    return text if PROMO_CODE_PATTERN.fullmatch(text) else ""


def promo_campaign_usable(conn: sqlite3.Connection, code: str, plan_key: Optional[str] = None) -> bool:
    # plan_key None skips the plan check (settlement re-validates nothing the
    # order creation already checked except liveness and quota).
    row = conn.execute("SELECT * FROM promo_campaigns WHERE code = ?", (code,)).fetchone()
    if row is None or row["revoked_at"]:
        return False
    if str(row["expires_at"] or "") <= utcnow().isoformat():
        return False
    if int(row["uses"] or 0) >= int(row["max_uses"] or 0):
        return False
    plans = [p for p in str(row["plan_keys"] or "").split(",") if p]
    return plan_key is None or not plans or plan_key in plans


def promo_campaign_stacks(conn: sqlite3.Connection, code: str) -> bool:
    row = conn.execute("SELECT stack_referral FROM promo_campaigns WHERE code = ?", (code,)).fetchone()
    return bool(row and int(row["stack_referral"] or 0))


# R2-EN: new English strings returned by the hub-priced checkout routes.
CHECKOUT_PROMO_MESSAGES = {
    "promo_invalid": "That promo code is not valid for this plan or has expired.",
    "promo_no_stack": "That promo code cannot be combined with a referral code.",
}


def checkout_promo_problem(conn: sqlite3.Connection, raw_code: Any, promo_code: str, plan_key: str,
                           referral_applies: bool) -> str:
    # Checkout (BTCPay, Monero, wallet) validates a typed promo before any
    # provider call; the stored order then carries it to settlement, where
    # grant_promo_days applies it once per account. PayPal subscriptions and
    # hosted PayPal links never take a promo: PayPal's next_billing_time is
    # authoritative for subscriptions and would overwrite bonus days.
    if not str(raw_code or "").strip():
        return ""
    if not promo_code or not promo_campaign_usable(conn, promo_code, plan_key):
        return "promo_invalid"
    if referral_applies and not promo_campaign_stacks(conn, promo_code):
        return "promo_no_stack"
    return ""


def grant_promo_days(conn: sqlite3.Connection, code: str, account_number: str, purchase_reference: str,
                     expiry: datetime, referral_applied: bool) -> tuple:
    """Add a campaign's bonus days once per account. Caller holds the writer
    transaction. Returns (new_expiry, days). Never raises for an unusable
    campaign: a settled payment must still grant its paid term."""
    code = normalize_promo_code(code)
    if not code or not account_number:
        return expiry, 0
    if not promo_campaign_usable(conn, code) or (referral_applied and not promo_campaign_stacks(conn, code)):
        return expiry, 0
    if conn.execute(
        "SELECT 1 FROM promo_redemptions WHERE code = ? AND account_number = ?", (code, account_number)
    ).fetchone():
        return expiry, 0
    row = conn.execute("SELECT bonus_days FROM promo_campaigns WHERE code = ?", (code,)).fetchone()
    days = int(row["bonus_days"] or 0) if row else 0
    if days <= 0:
        return expiry, 0
    # The quota guard lives in the UPDATE itself, so concurrent writers can
    # never push uses past max_uses.
    if conn.execute(
        "UPDATE promo_campaigns SET uses = uses + 1 WHERE code = ? AND uses < max_uses", (code,)
    ).rowcount != 1:
        return expiry, 0
    conn.execute(
        "INSERT INTO promo_redemptions (code, account_number, purchase_reference, bonus_days, created_at) "
        "VALUES (?, ?, ?, ?, ?)",
        (code, account_number, str(purchase_reference or "")[:128], days, utcnow().isoformat()),
    )
    return expiry + timedelta(days=days), days


def redemption_account_credential_ok(conn: sqlite3.Connection, account_number: str, device_id: str,
                                     request: Request) -> bool:
    # Either an enrolled device's bearer token for this exact account and
    # device, or the account's unused, unexpired setup key (checked, never
    # consumed: the holder still needs it to enrol). Account number alone is
    # never a credential.
    bearer = bearer_token_from_request(request)
    if bearer and device_id:
        row = conn.execute(
            "SELECT device_auth_token_hash FROM devices WHERE account_number = ? AND device_id = ?",
            (account_number, device_id),
        ).fetchone()
        if row is not None and device_auth_token_matches(row["device_auth_token_hash"], bearer):
            return True
    supplied = str(request.headers.get("x-wins-activation", "") or "").strip()
    return bool(supplied) and verify_and_consume_activation_secret(conn, account_number, supplied, consume=False)


def redemption_extension_refusal(conn: sqlite3.Connection, account_number: str, device_id: str,
                                 request: Request, now: datetime) -> tuple:
    """Return (refusal_reason, user_row). An empty reason means the account may
    be extended. Unauthenticated callers may only ADD time to a currently
    active account: nothing is disclosed, emailed or changed except expiry."""
    if not re.fullmatch(r"\d{4}-\d{4}-\d{4}", account_number or "") or account_number == FREE_ACCESS_ACCOUNT_NUMBER:
        return "account_not_found", None
    user = conn.execute("SELECT * FROM users WHERE account_number = ?", (account_number,)).fetchone()
    if user is None:
        return "account_not_found", None
    if str(user["paypal_subscription_id"] or "").strip():
        # PayPal's next_billing_time is authoritative for these accounts and a
        # stop/refund event expires the whole account, so prepaid days would
        # either be lost or break the next renewal (M-1 guard).
        return "account_recurring", user
    status = str(user["status"] or "").lower()
    expiry = parse_iso_datetime(user["expiration_date"])
    if (status not in {"active", "expired"} or expiry is None
            or str(user["renewal_source"] or "") == "free_access"):
        return "account_not_eligible", user
    if status == "active" and expiry > now:
        return "", user
    if redemption_account_credential_ok(conn, account_number, device_id, request):
        return "", user
    return "account_inactive", user


def redeem_code_transaction(conn: sqlite3.Connection, normalized: str, request: Request, target_email: str,
                            target_account: str = "", device_id: str = "", referral_code: str = "",
                            promo_code: str = "") -> tuple:
    """Every durable DATABASE state transition for one redemption, in ONE
    BEGIN IMMEDIATE transaction. No network call happens inside it.

    Returns (outcome, payload). Outcomes: "granted", "recovered", "declined",
    and (R2) "refused": a valid unused code whose request cannot be honoured
    (target account, referral or promo); the code is NOT consumed.

    R2: target_account extends an existing account instead of creating one.
    An extension never issues, returns, seals or emails a setup key and never
    changes the account's email (see redemption_extension_refusal).
    """
    now = utcnow()
    now_iso = now.isoformat()
    candidates = _redemption_code_candidates(normalized)
    target_account = normalize_account_number(target_account) if target_account else ""
    referral_input = str(referral_code or "").strip()
    promo_input = str(promo_code or "").strip()

    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    try:
        # --- idempotent recovery ------------------------------------------
        # Checked FIRST and under the writer lock, so a retry that races the
        # original request cannot slip past into a second claim attempt.
        for version, code_hash, idem_key in candidates:
            row = conn.execute(
                "SELECT * FROM redemption_fulfillments WHERE idempotency_key = ?",
                (idem_key,),
            ).fetchone()
            if not row:
                continue
            if str(row["expires_at"] or "") <= now_iso:
                continue
            # R2-AUDIT-04: an extension is recovered only for a retry that names
            # the same account. Anyone else holding the spent code gets the
            # ordinary decline, never the account number or its expiry.
            recovered_mode = conn.execute(
                "SELECT grant_mode FROM redemption_codes WHERE code_hash = ? AND key_version = ?",
                (row["code_hash"], row["key_version"]),
            ).fetchone()
            if (recovered_mode is not None and recovered_mode["grant_mode"] == "extend"
                    and target_account != str(row["account_number"] or "")):
                record_redemption_event(
                    conn, outcome="declined", request=request, batch_id=row["batch_id"] or "",
                    code_hash=code_hash, key_version=version, detail="recovery_target_mismatch",
                )
                conn.commit()
                return ("declined", {})
            try:
                # The sealed record carries the whole key set (empty for an
                # extension). The response shows the first key, as it always has.
                recovered_keys = activation_key_list(open_fulfillment_secret(
                    row["sealed_setup_key"], row["key_version"], f"{idem_key}|{row['account_number']}"
                ))
                setup_key = recovered_keys[0] if recovered_keys else ""
            except ValueError as exc:
                # The sealed record exists but will not open: its key version
                # was dropped from the ring, or the row was tampered with.
                # NEVER fall through to the claim path -- that would report a
                # spent code as invalid and strand the customer. Fail loudly
                # and retryably so an operator can restore the key version.
                conn.rollback()
                logger.error("Sealed fulfillment record failed to open for %s: %s", mask_id(idem_key), exc)
                security_alert(1, "redemption fulfillment record unreadable", request=request, details={
                    "batch_id": row["batch_id"] or "",
                    "key_version": row["key_version"],
                })
                raise HTTPException(
                    status_code=503,
                    detail="Your code was accepted but the result could not be read back. Contact support with no further attempts.",
                )
            record_redemption_event(
                conn,
                outcome="recovered",
                request=request,
                batch_id=row["batch_id"] or "",
                code_hash=code_hash,
                key_version=version,
                account_number=row["account_number"],
                idempotency_key=idem_key,
            )
            grant = conn.execute(
                "SELECT grant_mode, referral_bonus_days, promo_bonus_days FROM redemption_codes "
                "WHERE code_hash = ? AND key_version = ?",
                (row["code_hash"], row["key_version"]),
            ).fetchone()
            conn.commit()
            # An extension sealed an empty key, so its retry discloses nothing
            # beyond the account number and expiry the caller supplied.
            return ("recovered", {
                "account_number": row["account_number"],
                "setup_key": setup_key,
                "expiration_date": row["expiration_date"],
                "idempotency_key": idem_key,
                "batch_id": row["batch_id"] or "",
                "mode": (grant["grant_mode"] if grant is not None and grant["grant_mode"] else "new"),
                "referral_bonus_days": int(grant["referral_bonus_days"] or 0) if grant is not None else 0,
                "promo_bonus_days": int(grant["promo_bonus_days"] or 0) if grant is not None else 0,
            })

        # --- validate + claim ---------------------------------------------
        matched = None
        for version, code_hash, idem_key in candidates:
            row = conn.execute(
                "SELECT * FROM redemption_codes WHERE code_hash = ? AND key_version = ?",
                (code_hash, version),
            ).fetchone()
            if row is not None:
                matched = (version, code_hash, idem_key, row)
                break

        if matched is None:
            # Unknown code. Same work, same event shape, same response as an
            # already-spent one.
            record_redemption_event(
                conn, outcome="declined", request=request,
                code_hash=candidates[0][1] if candidates else "",
                key_version=candidates[0][0] if candidates else "",
                detail="unknown_code",
            )
            conn.commit()
            return ("declined", {})

        version, code_hash, idem_key, code_row = matched
        batch = conn.execute(
            "SELECT * FROM redemption_batches WHERE batch_id = ?", (code_row["batch_id"],)
        ).fetchone()

        # A canary is never sold, so any attempt to redeem one proves the print
        # run leaked and names which run. It NEVER grants, and the caller gets
        # the ordinary declined response so the prober learns nothing.
        if int(code_row["is_canary"] or 0) == 1:
            conn.execute(
                "UPDATE redemption_codes SET status='canary_tripped', redeemed_at=?, redeemed_source_bucket=? "
                "WHERE code_hash=? AND key_version=? AND status='unused'",
                (now_iso, security_event_hash(request_origin_bucket_value(request)), code_hash, version),
            )
            record_redemption_event(
                conn, outcome="canary", request=request, batch_id=code_row["batch_id"],
                code_hash=code_hash, key_version=version, detail="canary_code_presented",
            )
            conn.commit()
            security_alert(1, "redemption canary code presented", request=request, details={
                "batch_id": code_row["batch_id"],
                "partner": (batch["partner"] if batch else "") or "",
            })
            return ("declined", {})

        reason = ""
        if str(code_row["status"] or "") != "unused":
            reason = "already_redeemed"
        elif batch is None:
            reason = "orphan_batch"
        elif batch["revoked_at"]:
            reason = "batch_revoked"
        elif str(code_row["expires_at"] or "") and str(code_row["expires_at"]) <= now_iso:
            reason = "code_expired"
        elif str(batch["expires_at"] or "") and str(batch["expires_at"]) <= now_iso:
            reason = "batch_expired"
        if reason:
            record_redemption_event(
                conn, outcome="declined", request=request, batch_id=code_row["batch_id"],
                code_hash=code_hash, key_version=version, detail=reason,
            )
            conn.commit()
            return ("declined", {})

        # --- R2 pre-checks --------------------------------------------------
        # Every refusal is decided BEFORE the claim, so a refused request
        # never consumes the code and never leaves a partial write behind.
        refusal = ""
        extend_user = None
        # R2-AUDIT-02: target-independent checks run first, so a bad referral
        # or promo gets the same answer whatever account number comes with it
        # and cannot be used to probe accounts without spending the code.
        referral = ""
        referrer = ""
        if referral_input:
            referral = normalize_referral_code(referral_input)
            if str(batch["channel"] or "direct") in REDEMPTION_REFERRAL_INELIGIBLE_CHANNELS:
                refusal = "referral_not_allowed"
            else:
                referrer = referral_account_for_code(conn, referral) if referral else ""
                if not referrer:
                    refusal = "referral_invalid"
        promo = ""
        if not refusal and promo_input:
            promo = normalize_promo_code(promo_input)
            if not promo or not promo_campaign_usable(conn, promo, "prepaid"):
                refusal = "promo_invalid"
        if not refusal and target_account:
            refusal, extend_user = redemption_extension_refusal(conn, target_account, device_id, request, now)
        if not refusal and referrer and target_account:
            if normalize_account_number(referrer) == target_account:
                refusal = "referral_invalid"
            elif conn.execute(
                "SELECT 1 FROM referral_rewards WHERE referred_account_number = ?", (target_account,)
            ).fetchone():
                # R2-AUDIT-06: one referral bonus per account; refuse rather
                # than spend the card on a bonus that cannot be paid.
                refusal = "referral_used"
        if not refusal and promo:
            if target_account and conn.execute(
                "SELECT 1 FROM promo_redemptions WHERE code = ? AND account_number = ?", (promo, target_account)
            ).fetchone():
                refusal = "promo_used"
            elif referrer and not promo_campaign_stacks(conn, promo):
                refusal = "promo_no_stack"
        if refusal:
            record_redemption_event(
                conn, outcome="declined", request=request, batch_id=code_row["batch_id"],
                code_hash=code_hash, key_version=version, detail=f"refused:{refusal}",
            )
            conn.commit()
            return ("refused", {"reason": refusal})

        mode = "extend" if extend_user is not None else "new"
        account_number = target_account if extend_user is not None else new_account_number(conn)
        # THE compare-and-set. BEGIN IMMEDIATE serialises writers and this
        # UPDATE only fires while the row is still 'unused', so of N concurrent
        # requests exactly one can see rowcount == 1 and mint an account.
        claimed = conn.execute(
            "UPDATE redemption_codes SET status='redeemed', account_number=?, redeemed_at=?, redeemed_source_bucket=?, grant_mode=? "
            "WHERE code_hash=? AND key_version=? AND status='unused'",
            (account_number, now_iso, security_event_hash(request_origin_bucket_value(request)), mode, code_hash, version),
        ).rowcount
        if claimed != 1:
            record_redemption_event(
                conn, outcome="declined", request=request, batch_id=code_row["batch_id"],
                code_hash=code_hash, key_version=version, detail="lost_claim_race",
            )
            conn.commit()
            return ("declined", {})

        # An active extension stacks on the remaining term; a lapsed one (only
        # reachable with a credential) starts now. Refunds remove exactly
        # grant_end - grant_start, which includes this grant's own bonuses.
        start = now
        if extend_user is not None:
            current_expiry = parse_iso_datetime(extend_user["expiration_date"])
            if (str(extend_user["status"] or "").lower() == "active"
                    and current_expiry is not None and current_expiry > now):
                start = current_expiry
        expiry_dt = start + parse_duration(batch["duration"])
        purchase_reference = f"redemption:{version}:{code_hash[:32]}"
        referral_days = 0
        if referrer:
            expiry_dt, referral_days, referrer = apply_referral_bonus(
                conn,
                referral_code=referral,
                referred_account_number=account_number,
                base_start=start,
                base_expiry=expiry_dt,
                purchase_reference=purchase_reference,
            )
        promo_days = 0
        if promo:
            expiry_dt, promo_days = grant_promo_days(
                conn, promo, account_number, purchase_reference, expiry_dt, referral_days > 0,
            )
        expiry = expiry_dt.isoformat()
        if extend_user is not None:
            # Expiry and referral bookkeeping only. Email, setup key and
            # devices are untouched: nothing here can hand the account over.
            conn.execute(
                "UPDATE users SET status='active', expiration_date=?, renewal_source='redemption', "
                "referred_by_account_number=COALESCE(NULLIF(?, ''), referred_by_account_number), "
                "referral_bonus_days=COALESCE(referral_bonus_days, 0) + ?, "
                "referral_bonus_applied_at=CASE WHEN ? > 0 THEN ? ELSE referral_bonus_applied_at END "
                "WHERE account_number=?",
                (expiry, referrer if referral_days else "", referral_days, referral_days, now_iso, account_number),
            )
            setup_keys = []
            setup_key = ""
        else:
            conn.execute(
                "INSERT INTO users (account_number, email, subscriber_name, status, expiration_date, renewal_source, referral_code, "
                "referred_by_account_number, referral_bonus_days, referral_bonus_applied_at) "
                "VALUES (?, ?, ?, 'active', ?, 'redemption', ?, ?, ?, ?)",
                (account_number, target_email or "", "Wins VPN User", expiry, new_referral_code(conn),
                 referrer if referral_days else "", referral_days, now_iso if referral_days else None),
            )
            # 3a / C1: the existing high-entropy setup key. No server-side PIN is
            # created here, or anywhere. The welcome email is the only channel
            # that can carry a full set, so a redemption with an email address
            # gets one key per device slot and one without gets the single key
            # the response shows. The response shows the first key either way.
            setup_keys = issue_activation_secrets(conn, account_number, count=None if target_email else 1)
            setup_key = setup_keys[0]
        conn.execute(
            "UPDATE redemption_codes SET grant_start=?, grant_end=?, referral_bonus_days=?, promo_code=?, promo_bonus_days=? "
            "WHERE code_hash=? AND key_version=?",
            (start.isoformat(), expiry, referral_days, promo if promo_days else None, promo_days, code_hash, version),
        )
        conn.execute("""
            INSERT INTO redemption_fulfillments (
                idempotency_key, code_hash, key_version, batch_id, account_number,
                expiration_date, sealed_setup_key, created_at, expires_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            idem_key, code_hash, version, code_row["batch_id"], account_number, expiry,
            seal_fulfillment_secret(ACTIVATION_KEY_SEPARATOR.join(setup_keys), version, f"{idem_key}|{account_number}"),
            now_iso,
            (now + timedelta(seconds=REDEMPTION_FULFILLMENT_TTL_SECONDS)).isoformat(),
        ))
        if extend_user is None:
            # No outbox row for an extension: the drain rotates a fresh setup
            # key when the sealed copy is gone, which must never happen for an
            # account the caller did not prove they own.
            conn.execute("""
                INSERT INTO redemption_outbox (
                    idempotency_key, kind, account_number, target_email, batch_id, status, created_at, sealed_secret
                ) VALUES (?, 'redemption_welcome_email', ?, ?, ?, 'pending', ?, ?)
            """, (idem_key, account_number, target_email or "", code_row["batch_id"], now_iso,
                  seal_activation_delivery(ACTIVATION_KEY_SEPARATOR.join(setup_keys),
                                           f"redemption:{idem_key}", account_number)
                  if target_email else None))
        record_redemption_event(
            conn, outcome="granted", request=request, batch_id=code_row["batch_id"],
            code_hash=code_hash, key_version=version, account_number=account_number,
            idempotency_key=idem_key, detail="extend" if extend_user is not None else "",
        )
        conn.commit()
        return ("granted", {
            "account_number": account_number,
            "setup_key": setup_key,
            "expiration_date": expiry,
            "idempotency_key": idem_key,
            "batch_id": code_row["batch_id"],
            "mode": mode,
            "referral_bonus_days": referral_days,
            "promo_bonus_days": promo_days,
        })
    except Exception:
        conn.rollback()
        raise


class RedemptionRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    code: str = Field(default="", max_length=128)
    # Optional. The website sends none; the app may, so the welcome email can
    # go out as a second channel. Never required, because a prepaid card has no
    # buyer identity by design.
    email: str = Field(default="", max_length=254)
    # R2, all optional. account_number extends that account instead of
    # creating one; device_id pairs with an Authorization bearer (or an
    # X-Wins-Activation setup key) to prove ownership for a lapsed account.
    # None of these feeds the idempotency key, which stays the code alone.
    account_number: str = Field(default="", max_length=32)
    device_id: str = Field(default="", max_length=128)
    referral_code: str = Field(default="", max_length=64)
    promo_code: str = Field(default="", max_length=64)


@app.post("/api/redeem")
def redeem_prepaid_code(request: Request, payload: RedemptionRequest):
    if not redemption_enabled():
        raise HTTPException(status_code=503, detail="Redemption is not configured on this hub.")
    normalized = normalize_redemption_code(payload.code)
    target_email = str(payload.email or "").strip()[:254]

    with get_db() as conn:
        ensure_schema(conn)
        candidates = _redemption_code_candidates(normalized) if normalized else []
        precheck_redemption_rate_limits(conn, request, [c[1] for c in candidates])
        if not redemption_code_well_formed(normalized):
            # A malformed code cannot exist in the table, so it takes the same
            # declined path with the same body -- the checksum saves a database
            # round trip, it does not change what the caller can observe.
            #
            # C3: NO bucket is consumed here. A malformed request is not a
            # credential failure. This is not an oracle either: the Crockford
            # checksum is computable offline, so an attacker already knows
            # whether their input is well-formed without asking this server.
            conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            record_redemption_event(
                conn, outcome="declined", request=request,
                code_hash=candidates[0][1] if candidates else "",
                key_version=candidates[0][0] if candidates else "",
                detail="malformed_code",
            )
            conn.commit()
            return JSONResponse(status_code=200, content=dict(REDEMPTION_DECLINED_RESPONSE))
        outcome, result = redeem_code_transaction(
            conn, normalized, request, target_email,
            target_account=str(payload.account_number or "").strip()[:32],
            device_id=str(payload.device_id or "").strip()[:128],
            referral_code=str(payload.referral_code or "").strip()[:64],
            promo_code=str(payload.promo_code or "").strip()[:64],
        )
        if outcome == "declined" or outcome == "refused":
            # C3: THE genuine redemption failure -- a well-formed code that is
            # invalid or already redeemed. Consumed atomically here, after the
            # outcome is known, and never on the grant or recovery paths below.
            # R2: a refusal (bad target account, referral or promo) also
            # spends budget, so account numbers cannot be probed cheaply.
            consume_redemption_failure_budget(conn, request, [c[1] for c in candidates])

    if outcome == "declined":
        return JSONResponse(status_code=200, content=dict(REDEMPTION_DECLINED_RESPONSE))
    if outcome == "refused":
        # Reachable only with a well-formed, unused, live code. The code was
        # not consumed, so the client lets the user correct the request.
        reason = str(result.get("reason") or "account_not_eligible")
        return JSONResponse(
            status_code=200,
            content={
                "ok": False,
                "status": reason,
                "message": REDEMPTION_REFUSAL_MESSAGES.get(reason, REDEMPTION_REFUSAL_MESSAGES["account_not_eligible"]),
            },
            headers={"Cache-Control": "private, no-store, max-age=0"},
        )

    # HANDOFF 3j INVARIANT. Reached on BOTH the fresh grant and the idempotent
    # recovery. The recovery path is exactly where skipping this hides: the row
    # says done, so the barrier looks redundant -- but nothing has confirmed
    # that row is replicated, and the original request may have failed the
    # barrier and returned 503 precisely for that reason.
    require_durability_barrier(request, "api-redeem", {"batch_id": result.get("batch_id", "")})

    # The setup key is returned exactly once here, in a POST response body.
    # Never in a URL, never in a query string, never logged, never in a
    # referrer, never in an analytics event -- and no-store so no intermediary
    # or browser cache keeps a copy of the one response that carries it.
    extended = result.get("mode") == "extend"
    return JSONResponse(
        status_code=200,
        content={
            "ok": True,
            "status": "extended" if extended else "redeemed",
            "mode": "extend" if extended else "new",
            "account_number": result["account_number"],
            "setup_key": "" if extended else result["setup_key"],
            "expiration_date": result["expiration_date"],
            "referral_bonus_days": int(result.get("referral_bonus_days") or 0),
            "promo_bonus_days": int(result.get("promo_bonus_days") or 0),
            "recovered": outcome == "recovered",
            # R2-EN: the extension message is new; the new-account copy is unchanged.
            "message": (
                "Account extended. Your existing credentials and devices are unchanged."
                if extended else
                "Redeemed. Save your account number and setup key now: the setup key is shown only once."
            ),
        },
        headers={"Cache-Control": "private, no-store, max-age=0", "Referrer-Policy": "no-referrer"},
    )


@app.post("/api/redeem/ack")
def acknowledge_redemption(request: Request, payload: RedemptionRequest):
    # Explicit deletion semantics for the fulfillment record. A client that has
    # safely stored its first setup key can destroy that API recovery copy
    # immediately instead of waiting out the TTL. The API never shows keys 2 and
    # up, so a welcome mail that carries them (an email on file and extra keys)
    # is NOT cancelled here: it is the only way the customer receives them.
    # Presenting the code is the authorisation:
    # it is the same bearer credential that produced the record.
    if not redemption_enabled():
        raise HTTPException(status_code=503, detail="Redemption is not configured on this hub.")
    normalized = normalize_redemption_code(payload.code)
    with get_db() as conn:
        ensure_schema(conn)
        candidates = _redemption_code_candidates(normalized) if normalized else []
        # C3: acknowledgement NEVER consumes the authentication backoff budget.
        # It is a client reporting that it stored its setup key safely -- the
        # most successful outcome this endpoint has. Only the read-only
        # precheck applies, so an already-exhausted caller is still shed.
        precheck_redemption_rate_limits(conn, request, [c[1] for c in candidates])
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        deleted = 0
        barrier_needed = False
        for version, code_hash, idem_key in candidates:
            deleted += conn.execute(
                "DELETE FROM redemption_fulfillments WHERE idempotency_key = ?", (idem_key,)
            ).rowcount
            cancelled = conn.execute(
                "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, completed_at=?, lease_until=NULL "
                "WHERE idempotency_key=? AND status='pending' AND NOT ("
                "COALESCE(target_email, '') <> '' AND EXISTS ("
                "SELECT 1 FROM activation_extra_keys "
                "WHERE activation_extra_keys.account_number=redemption_outbox.account_number))",
                (utcnow().isoformat(), idem_key),
            ).rowcount
            if deleted or cancelled:
                barrier_needed = True
                record_redemption_event(
                    conn, outcome="fulfillment_acknowledged", request=request,
                    code_hash=code_hash, key_version=version, idempotency_key=idem_key,
                )
                break
            # A fulfillment and its outbox row exist only for a code that was
            # redeemed (a refund moves it on to refunded). Primary-key lookup.
            if conn.execute(
                "SELECT 1 FROM redemption_codes WHERE code_hash = ? AND key_version = ? "
                "AND status IN ('redeemed', 'refunded')",
                (code_hash, version),
            ).fetchone() is not None:
                barrier_needed = True
        conn.commit()
    # R2: a retry after a 503 finds the row already deleted (deleted == 0) but
    # the earlier delete may still be unreplicated, so the barrier runs on every
    # acknowledgement of a redeemed or refunded code, not only the first.
    # R22 Y1 F1: a code that never had a fulfillment (garbage, empty, unused,
    # revoked, canary) has nothing to replicate. Ack never consumes the failure
    # budget, so running the litestream sync for it would let any caller spend
    # that subprocess per request; it gets the same uniform body without it.
    if barrier_needed:
        require_durability_barrier(request, "api-redeem-ack")
    # Uniform response: acknowledging a record that never existed and one that
    # did must look the same.
    return {"ok": True}


def claim_redemption_outbox_batch(conn: sqlite3.Connection, limit: int, lease_token: str) -> list:
    # Short BEGIN IMMEDIATE claim; the writer lock is never held across the
    # email send or across the barrier.
    now_iso = utcnow().isoformat()
    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    # K3-06: a pending row that has used every attempt can never be claimed
    # again, so it is terminal. Close it and purge its sealed key copy (this
    # also catches rows that reached the cap before this build).
    conn.execute(
        "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, "
        "completed_at=?, lease_until=NULL WHERE status='pending' AND attempts>=? "
        "AND (lease_until IS NULL OR lease_until<?)",
        (now_iso, REDEMPTION_OUTBOX_MAX_ATTEMPTS, now_iso),
    )
    rows = conn.execute("""
        SELECT * FROM redemption_outbox
        WHERE status IN ('pending', 'delivered')
          AND (status = 'delivered' OR attempts < ?)
          AND (lease_until IS NULL OR lease_until < ?)
        ORDER BY id ASC
        LIMIT ?
    """, (REDEMPTION_OUTBOX_MAX_ATTEMPTS, now_iso, limit)).fetchall()
    for row in rows:
        conn.execute(
            "UPDATE redemption_outbox SET lease_until = ?, attempts = attempts + 1 WHERE id = ? AND status IN ('pending', 'delivered')",
            (lease_token, row["id"]),
        )
    conn.commit()
    return [dict(row) for row in rows]


def release_redemption_outbox_lease(conn: sqlite3.Connection, item_id: int, lease_token: str, error: str = "", *, undo_attempt: bool = False) -> None:
    released = conn.execute(
        "UPDATE redemption_outbox SET lease_until = NULL, last_error = ?, "
        "attempts = CASE WHEN ? THEN MAX(attempts - 1, 0) ELSE attempts END "
        "WHERE id = ? AND lease_until = ?",
        ((error or "")[:200] or None, int(undo_attempt), item_id, lease_token),
    ).rowcount
    if released and not undo_attempt:
        # K3-06: the attempt that just failed was the last one allowed. The row
        # is terminal now, so it is closed and its sealed key copy purged here.
        conn.execute(
            "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, completed_at=? "
            "WHERE id=? AND status='pending' AND attempts>=?",
            (utcnow().isoformat(), item_id, REDEMPTION_OUTBOX_MAX_ATTEMPTS),
        )
    conn.commit()


def sweep_expired_redemption_fulfillments(conn: sqlite3.Connection) -> int:
    # Explicit deletion at expiry of the API recovery copy of the first setup
    # key; after it, a lost-response retry can no longer recover that key from
    # the API. The welcome mail keeps its own sealed copy of the whole set
    # (redemption_outbox.sealed_secret) until the mail is delivered or cancelled.
    now_iso = utcnow().isoformat()
    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    removed = conn.execute(
        "DELETE FROM redemption_fulfillments WHERE expires_at <= ?", (now_iso,)
    ).rowcount
    conn.execute(
        "DELETE FROM redemption_events WHERE outcome = 'declined' AND occurred_at < ?",
        ((utcnow() - timedelta(days=REDEMPTION_DECLINED_EVENT_RETENTION_DAYS)).isoformat(),),
    )
    conn.commit()
    return removed


def _activation_mail_can_send(to_email: str) -> bool:
    # The cases in which send_account_email refuses without trying.
    return bool(SMTP_USER and SMTP_PASS and to_email and re.match(r"[^@]+@[^@]+\.[^@]+", to_email))


def _redemption_outbox_setup_key(conn: sqlite3.Connection, item: dict) -> Optional[list]:
    # Custody of the keys a welcome mail carries. A row written by this build
    # holds its own sealed copy of the whole set (sealed_secret), so the mail no
    # longer depends on the API fulfillment record: acknowledging or expiring
    # that record costs nothing, and every retry re-sends the SAME keys. A row
    # from before the column falls back to the fulfillment record (sealed onto
    # the row on first use) and, past that, to one rotation whose result is
    # sealed on the row before it is mailed, so retries of a rotation reuse it
    # as well. Returns the keys to mail (a list, whole set at once) or None when
    # the mail was cancelled.
    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    outbox = conn.execute(
        "SELECT status, sealed_secret FROM redemption_outbox WHERE id=? AND idempotency_key=?",
        (item["id"], item["idempotency_key"]),
    ).fetchone()
    if outbox is None or outbox["status"] != "pending":
        conn.commit()
        return None
    # K3-05: whichever way the keys would be obtained (the sealed copy, the API
    # record or a rotation), the account must still be the one the mail was
    # queued for. If not, cancel and purge the sealed copy before anything is
    # recovered or minted.
    user = conn.execute(
        "SELECT status, email, expiration_date FROM users WHERE account_number=?",
        (item["account_number"],),
    ).fetchone()
    if not account_may_receive_keys(user, item["target_email"]):
        conn.execute(
            "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, "
            "completed_at=?, lease_until=NULL WHERE id=? AND status='pending'",
            (utcnow().isoformat(), item["id"]),
        )
        conn.commit()
        return None
    row = conn.execute(
        "SELECT * FROM redemption_fulfillments WHERE idempotency_key = ?", (item["idempotency_key"],)
    ).fetchone()
    delivery_id = f"redemption:{item['idempotency_key']}"
    keys = []
    if outbox["sealed_secret"]:
        keys = activation_key_list(open_activation_delivery(
            outbox["sealed_secret"], delivery_id, item["account_number"]
        ))
    elif row is not None and str(row["expires_at"] or "") > utcnow().isoformat():
        keys = activation_key_list(open_fulfillment_secret(
            row["sealed_setup_key"], row["key_version"], f"{item['idempotency_key']}|{row['account_number']}"
        ))
    if keys:
        states = activation_bundle_states(conn, item["account_number"], keys)
        # The API showed key 1, so the buyer may already have spent it: it is
        # simply not mailed again. Every other key was never shown, so one that
        # is spent, expired or no longer stored (the set was replaced) means the
        # bundle is no longer ours to send. Nothing is re-enabled or rotated.
        intact = states[0] in ("live", "used") and all(state == "live" for state in states[1:])
        deliverable = [key for key, state in zip(keys, states) if state == "live"]
        if not intact or not deliverable:
            conn.execute(
                "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, "
                "completed_at=?, lease_until=NULL WHERE id=? AND status='pending'",
                (utcnow().isoformat(), item["id"]),
            )
            conn.commit()
            return None
        if not outbox["sealed_secret"]:
            conn.execute(
                "UPDATE redemption_outbox SET sealed_secret=? WHERE id=?",
                (seal_activation_delivery(ACTIVATION_KEY_SEPARATOR.join(keys),
                                          delivery_id, item["account_number"]), item["id"]),
            )
            conn.commit()
            # New state behind the pre-send barrier: replicate it before the
            # keys leave in an email (state commit -> barrier -> side effect).
            run_durability_barrier()
            return deliverable
        conn.commit()
        return deliverable
    # A restored or in-place upgraded database can still hold mail that an
    # acknowledgement taken before S-HUB-01 left pending. The user saved that
    # key, so cancel the mail rather than rotate it (the same rule as
    # server/db/reconcile_redemption_ack_outbox.sql, applied row by row).
    acknowledged_at = conn.execute(
        "SELECT MAX(occurred_at) FROM redemption_events "
        "WHERE idempotency_key=? AND outcome='fulfillment_acknowledged'",
        (item["idempotency_key"],),
    ).fetchone()[0]
    if acknowledged_at is not None:
        conn.execute(
            "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, completed_at=?, lease_until=NULL "
            "WHERE id=? AND status='pending'",
            (acknowledged_at, item["id"]),
        )
        conn.commit()
        return None
    # R22 F2b (arbiter): the sealed key is gone and the user already activated
    # with it. A rotation would mail a live key and re-open activation, so the
    # late welcome mail is cancelled instead; support resend still works.
    # R23 A-1: an account row that is gone (only an inconsistent restore leaves
    # its mail behind) has no key to back, so its mail is cancelled too.
    used = conn.execute(
        "SELECT activation_secret_used_at FROM users WHERE account_number = ?",
        (item["account_number"],),
    ).fetchone()
    # Any key of the set already spent means the buyer activated with one.
    extra_used = conn.execute(
        "SELECT 1 FROM activation_extra_keys WHERE account_number = ? AND used_at IS NOT NULL LIMIT 1",
        (item["account_number"],),
    ).fetchone()
    if used is None or used[0] is not None or extra_used is not None:
        conn.execute(
            "UPDATE redemption_outbox SET status='cancelled', sealed_secret=NULL, completed_at=?, lease_until=NULL "
            "WHERE id=? AND status='pending'",
            (utcnow().isoformat(), item["id"]),
        )
        conn.commit()
        return None
    # R23 A-1: rotating replaces the key the buyer was shown. When
    # send_account_email would refuse without trying (no SMTP credentials, a
    # supported hub state, or an unusable optional address), keep that key and
    # retry instead, as drain_hoppy_agent_mail_outbox does; otherwise every
    # retry destroys a key and mails nothing.
    if not _activation_mail_can_send(str(item.get("target_email") or "")):
        conn.commit()
        raise RuntimeError("activation email cannot be sent (SMTP not configured or address unusable)")
    rotated = issue_activation_secrets(conn, item["account_number"])
    # K3-04: the rotated set is sealed on the row in the same transaction, so a
    # failed attempt retries these keys instead of minting a different set.
    conn.execute(
        "UPDATE redemption_outbox SET sealed_secret=? WHERE id=?",
        (seal_activation_delivery(ACTIVATION_KEY_SEPARATOR.join(rotated),
                                  delivery_id, item["account_number"]), item["id"]),
    )
    conn.commit()
    # The rotated hashes are new state behind the pre-send barrier: replicate
    # them before the keys leave in an email (state commit -> barrier -> side effect).
    run_durability_barrier()
    return rotated


def drain_redemption_outbox(limit: int = REDEMPTION_OUTBOX_BATCH_LIMIT) -> dict:
    # Required order on every critical path (HANDOFF 3j):
    #   atomic state + outbox commit -> barrier -> external side effect
    #   -> completion marker -> barrier -> lease release (the acknowledgement)
    #
    # A background job has no HTTP 200, so its completion marker IS its
    # acknowledgement and the barrier must precede it. A row whose post-delivery
    # barrier fails stays status='delivered' with barrier_confirmed_at NULL --
    # still claimable, so another worker finishes the durability half WITHOUT
    # re-sending the email.
    lease_token = (utcnow() + timedelta(seconds=REDEMPTION_OUTBOX_LEASE_SECONDS)).isoformat()
    summary = {"claimed": 0, "delivered": 0, "confirmed": 0, "deferred": 0, "failed": 0, "swept": 0, "errors": []}
    with get_db() as conn:
        ensure_schema(conn)
        summary["swept"] = sweep_expired_redemption_fulfillments(conn)
        batch = claim_redemption_outbox_batch(conn, limit, lease_token)
    summary["claimed"] = len(batch)

    for item in batch:
        # Barrier BEFORE any external side effect: never email about a grant
        # that is not yet confirmed replicated.
        if str(item.get("status")) == "pending":
            try:
                run_durability_barrier()
            except DurabilityBarrierError as exc:
                summary["deferred"] += 1
                summary["errors"].append({"id": item["id"], "error": f"pre_barrier:{exc.reason}"})
                with get_db() as conn:
                    release_redemption_outbox_lease(conn, item["id"], lease_token, f"pre_barrier:{exc.reason}", undo_attempt=True)
                continue
            try:
                if item.get("target_email"):
                    with get_db() as conn:
                        setup_keys = _redemption_outbox_setup_key(conn, item)
                    if setup_keys is None:
                        continue
                    delivered = send_account_email(
                        item["target_email"], "Wins VPN User", item["account_number"],
                        "Prepaid Card Redemption", setup_keys,
                    )
                    if not delivered:
                        raise RuntimeError("activation email provider returned failure")
                with get_db() as conn:
                    conn.commit()
                    conn.execute("BEGIN IMMEDIATE")
                    marked = conn.execute(
                        "UPDATE redemption_outbox SET status='delivered', delivered_at=?, sealed_secret=NULL WHERE id=? AND status='pending'",
                        (utcnow().isoformat(), item["id"]),
                    ).rowcount
                    conn.commit()
                if not marked:
                    # Acknowledged (or otherwise closed) while the mail was in
                    # flight: that already ended the row, so there is no
                    # delivery of ours to mark or confirm.
                    summary["errors"].append({"id": item["id"], "error": "closed_during_send"})
                    continue
                summary["delivered"] += 1
            except DurabilityBarrierError as exc:
                # The rotated key's barrier failed before any mail: like the
                # pre-send barrier, a replica outage defers without spending
                # an attempt.
                summary["deferred"] += 1
                summary["errors"].append({"id": item["id"], "error": f"pre_send_barrier:{exc.reason}"})
                with get_db() as conn:
                    release_redemption_outbox_lease(conn, item["id"], lease_token, f"pre_send_barrier:{exc.reason}", undo_attempt=True)
                continue
            except Exception as exc:  # noqa: BLE001 - reported per item below
                summary["failed"] += 1
                summary["errors"].append({"id": item["id"], "error": str(exc)[:200]})
                logger.warning("Redemption outbox delivery failed for %s: %s", mask_id(item["idempotency_key"]), exc)
                with get_db() as conn:
                    release_redemption_outbox_lease(conn, item["id"], lease_token, str(exc)[:200])
                continue

        # Barrier again, now covering the completion marker, BEFORE the lease
        # is released and the item is acknowledged as done.
        try:
            run_durability_barrier()
        except DurabilityBarrierError as exc:
            summary["deferred"] += 1
            summary["errors"].append({"id": item["id"], "error": f"post_barrier:{exc.reason}"})
            with get_db() as conn:
                release_redemption_outbox_lease(conn, item["id"], lease_token, f"post_barrier:{exc.reason}")
            continue
        with get_db() as conn:
            conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            conn.execute(
                "UPDATE redemption_outbox SET status='completed', barrier_confirmed_at=?, completed_at=?, lease_until=NULL "
                "WHERE id=? AND status='delivered'",
                (utcnow().isoformat(), utcnow().isoformat(), item["id"]),
            )
            conn.commit()
        summary["confirmed"] += 1
    return summary


# ---- Donor acknowledgment outbox drain (mirrors redemption_outbox pattern) ----
# The donation_acknowledgments table already has delivery_status/attempts but
# had no durable drain: background_tasks.add_task fired once and any SMTP
# or barrier failure left the row stuck. This drain provides the same
# lease + barrier + retry semantics as drain_redemption_outbox so a
# successful PayPal webhook is never lost to a transient mail failure.
DONOR_ACK_OUTBOX_BATCH_LIMIT = int(os.getenv("DONOR_ACK_OUTBOX_BATCH_LIMIT", "20"))
DONOR_ACK_OUTBOX_MAX_ATTEMPTS = int(os.getenv("DONOR_ACK_OUTBOX_MAX_ATTEMPTS", "8"))
DONOR_ACK_OUTBOX_LEASE_SECONDS = int(os.getenv("DONOR_ACK_OUTBOX_LEASE_SECONDS", "300"))


def drain_donor_acknowledgment_outbox(limit: int = DONOR_ACK_OUTBOX_BATCH_LIMIT) -> dict:
    """Claim donation_acknowledgments with delivery_status in ('pending','failed')
    that are not leased, deliver via SMTP, and confirm durability.

    Mirrors drain_redemption_outbox: barrier before send (never email about
    a row not yet replicated), lease release on barrier failure so another
    worker can retry without re-sending, and barrier before marking sent.
    Idempotent: re-delivery restates the same ack_number and same PDF.
    """
    lease_token = (utcnow() + timedelta(seconds=DONOR_ACK_OUTBOX_LEASE_SECONDS)).isoformat()
    summary: dict = {"claimed": 0, "sent": 0, "confirmed": 0, "deferred": 0, "failed": 0, "errors": []}
    with get_db() as conn:
        ensure_schema(conn)
        # Claim batch under BEGIN IMMEDIATE (writer lock not held across SMTP).
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        now_iso = utcnow().isoformat()
        rows = conn.execute(
            """
            SELECT ack_number FROM donation_acknowledgments
            WHERE delivery_status IN ('pending','failed')
              AND delivery_attempts < ?
              AND (delivery_detail IS NULL OR delivery_detail NOT LIKE 'lease:%'
                   OR substr(delivery_detail, 7) < ?)
              AND (delivered_at IS NULL OR delivered_at < ? OR delivery_status='failed')
            ORDER BY issued_at ASC LIMIT ?
            """,
            (DONOR_ACK_OUTBOX_MAX_ATTEMPTS, now_iso, now_iso, limit),
        ).fetchall()
        # Use delivery_detail as lease holder (opportunistic, no schema migration):
        # prefix with lease:<token> while held. Cleaner than adding a column.
        ack_numbers = [r["ack_number"] for r in rows]
        for ack in ack_numbers:
            conn.execute(
                "UPDATE donation_acknowledgments SET delivery_detail = ? WHERE ack_number = ? AND delivery_status IN ('pending','failed')",
                (f"lease:{lease_token}", ack),
            )
        conn.commit()
    summary["claimed"] = len(ack_numbers)
    for ack_number in ack_numbers:
        # Barrier before external side effect.
        try:
            run_durability_barrier()
        except DurabilityBarrierError as exc:
            summary["deferred"] += 1
            summary["errors"].append({"ack_number": ack_number, "error": f"pre_barrier:{exc.reason}"})
            with get_db() as conn:
                conn.execute(
                    "UPDATE donation_acknowledgments SET delivery_detail = ? WHERE ack_number = ? AND delivery_detail = ?",
                    (f"pre_barrier:{exc.reason}"[:300], ack_number, f"lease:{lease_token}"),
                )
                conn.commit()
            continue
        try:
            result = donor_deliver_acknowledgment(ack_number)
            if result.get("delivery_status") == "sent":
                summary["sent"] += 1
            else:
                summary["failed"] += 1
                summary["errors"].append({"ack_number": ack_number, "error": str(result.get("delivery_status"))[:120]})
                # Release lease on deliver failure so next drain can retry.
                with get_db() as conn:
                    conn.execute(
                        "UPDATE donation_acknowledgments SET delivery_detail = ? WHERE ack_number = ? AND delivery_detail = ?",
                        (str(result.get("delivery_status"))[:300], ack_number, f"lease:{lease_token}"),
                    )
                    conn.commit()
                continue
        except Exception as exc:  # noqa: BLE001
            summary["failed"] += 1
            summary["errors"].append({"ack_number": ack_number, "error": str(exc)[:200]})
            logger.warning("Donor acknowledgment outbox delivery failed for %s: %s", ack_number, exc)
            with get_db() as conn:
                conn.execute(
                    "UPDATE donation_acknowledgments SET delivery_detail = ? WHERE ack_number = ? AND delivery_detail = ?",
                    (str(exc)[:300], ack_number, f"lease:{lease_token}"),
                )
                conn.commit()
            continue
        # Barrier covering the completion marker before lease release.
        try:
            run_durability_barrier()
        except DurabilityBarrierError as exc:
            summary["deferred"] += 1
            summary["errors"].append({"ack_number": ack_number, "error": f"post_barrier:{exc.reason}"})
            # Row is already marked sent; post_barrier failure means the mark
            # may not be replicated yet -- leave as-is for next drain to confirm.
            continue
        summary["confirmed"] += 1
    return summary


@app.post("/admin/redemption/batch")
def admin_issue_redemption_batch(
    request: Request,
    batch_id: str = Form(...),
    count: int = Form(...),
    duration: str = Form("1m"),
    label: str = Form(""),
    partner: str = Form(""),
    plan_key: str = Form(""),
    canaries: int = Form(2),
    expires_in_days: int = Form(0),
    channel: str = Form("direct"),
    distribution_reference: str = Form(""),
    x_admin_token: str = Header(...),
):
    # Mints a batch and returns the plaintext codes EXACTLY ONCE, for the
    # one-time encrypted export handed to the printer. Nothing else in this
    # process ever sees a plaintext code again: only the keyed HMAC is stored.
    # R2: each code also gets a printable serial (<BATCH_ID>-00001) stored in
    # the clear; it identifies the card for refunds without the secret.
    # tools/redemption_export.py turns this response into the encrypted
    # delivery file and drops canaries.
    require_admin_token(x_admin_token, request, "issue redemption batch")
    channel = (channel if isinstance(channel, str) else "direct").strip().lower() or "direct"
    distribution_reference = (distribution_reference if isinstance(distribution_reference, str) else "").strip()[:200]
    # R2-EN: new admin validation strings.
    if channel not in REDEMPTION_CHANNELS:
        raise HTTPException(status_code=400, detail="channel must be one of: " + ", ".join(REDEMPTION_CHANNELS))
    if channel in REDEMPTION_RETAIL_CHANNELS and int(expires_in_days or 0) != 0:
        raise HTTPException(status_code=400, detail="Retail prepaid codes must not expire before redemption; use expires_in_days=0.")
    try:
        parse_duration(duration)
    except DurationParseError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    duration = duration.strip().lower()
    if not redemption_enabled():
        raise HTTPException(status_code=503, detail="Redemption is not configured on this hub.")
    batch_id = str(batch_id or "").strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9._-]{2,63}", batch_id):
        raise HTTPException(status_code=400, detail="batch_id must be 3-64 chars of a-z0-9._-")
    count = int(count or 0)
    if count < 1 or count > REDEMPTION_BATCH_MAX_CODES:
        raise HTTPException(status_code=400, detail=f"count must be between 1 and {REDEMPTION_BATCH_MAX_CODES}")
    canaries = max(0, min(int(canaries or 0), count))
    version = REDEMPTION_KEY_ACTIVE_VERSION
    now = utcnow()
    expires_at = (now + timedelta(days=int(expires_in_days))).isoformat() if int(expires_in_days or 0) > 0 else ""

    issued = []
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        try:
            if conn.execute("SELECT 1 FROM redemption_batches WHERE batch_id = ?", (batch_id,)).fetchone():
                raise HTTPException(status_code=409, detail="That batch_id already exists")
            conn.execute("""
                INSERT INTO redemption_batches (
                    batch_id, label, partner, plan_key, duration, issued_count,
                    canary_count, key_version, expires_at, created_at,
                    channel, distribution_reference
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                batch_id, str(label or "")[:200], str(partner or "")[:120],
                str(plan_key or "")[:64], duration, count, canaries,
                version, expires_at or None, now.isoformat(),
                channel, distribution_reference,
            ))
            # Canaries are placed at random positions so their index in the
            # printed run carries no signal.
            canary_positions = set(secrets.SystemRandom().sample(range(count), canaries)) if canaries else set()
            for index in range(count):
                code = mint_redemption_code()
                is_canary = 1 if index in canary_positions else 0
                serial = f"{batch_id.upper()}-{index + 1:05d}"
                conn.execute("""
                    INSERT INTO redemption_codes (
                        code_hash, key_version, batch_id, status, is_canary, expires_at, created_at, serial
                    ) VALUES (?, ?, ?, 'unused', ?, ?, ?, ?)
                """, (
                    redemption_code_hash(code, version), version, batch_id, is_canary,
                    expires_at or None, now.isoformat(), serial,
                ))
                issued.append({"code": format_redemption_code(code), "canary": bool(is_canary), "serial": serial})
            record_redemption_event(
                conn, outcome="batch_issued", request=request, batch_id=batch_id,
                key_version=version, detail=f"count={count} canaries={canaries} channel={channel}",
            )
            conn.commit()
        except Exception:
            conn.rollback()
            raise

    require_durability_barrier(request, "admin-redemption-batch", {"batch_id": batch_id})
    return {
        "status": "ok",
        "batch_id": batch_id,
        "channel": channel,
        "key_version": version,
        "count": count,
        "canaries": canaries,
        "duration": duration,
        "expires_at": expires_at,
        "codes": issued,
        "warning": "These plaintext codes are returned once. Export them encrypted and destroy every other copy.",
    }


@app.post("/admin/redemption/revoke")
def admin_revoke_redemption_batch(
    request: Request,
    batch_id: str = Form(...),
    reason: str = Form(""),
    x_admin_token: str = Header(...),
):
    # Bulk invalidation for a print run lost in transit. Already-redeemed codes
    # keep their history; only unused ones are killed.
    require_admin_token(x_admin_token, request, "revoke redemption batch")
    batch_id = str(batch_id or "").strip().lower()
    now_iso = utcnow().isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        try:
            row = conn.execute("SELECT batch_id FROM redemption_batches WHERE batch_id = ?", (batch_id,)).fetchone()
            if row is None:
                conn.commit()
                raise HTTPException(status_code=404, detail="Unknown batch_id")
            conn.execute(
                "UPDATE redemption_batches SET revoked_at=?, revoked_reason=? WHERE batch_id=? AND revoked_at IS NULL",
                (now_iso, str(reason or "")[:200], batch_id),
            )
            revoked = conn.execute(
                "UPDATE redemption_codes SET status='revoked' WHERE batch_id=? AND status='unused'",
                (batch_id,),
            ).rowcount
            record_redemption_event(
                conn, outcome="batch_revoked", request=request, batch_id=batch_id,
                detail=f"revoked={revoked} reason={str(reason or '')[:80]}",
            )
            conn.commit()
        except HTTPException:
            raise
        except Exception:
            conn.rollback()
            raise
    require_durability_barrier(request, "admin-redemption-revoke", {"batch_id": batch_id})
    return {"status": "ok", "batch_id": batch_id, "revoked_codes": revoked}


@app.get("/admin/redemption/batches")
def admin_list_redemption_batches(request: Request, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "list redemption batches")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT b.batch_id, b.label, b.partner, b.plan_key, b.duration, b.issued_count,
                   b.canary_count, b.key_version, b.expires_at, b.revoked_at, b.revoked_reason, b.created_at,
                   b.channel, b.distribution_reference,
                   SUM(CASE WHEN c.status = 'unused' THEN 1 ELSE 0 END) AS unused,
                   SUM(CASE WHEN c.status = 'redeemed' THEN 1 ELSE 0 END) AS redeemed,
                   SUM(CASE WHEN c.status = 'revoked' THEN 1 ELSE 0 END) AS revoked,
                   SUM(CASE WHEN c.status = 'refunded' THEN 1 ELSE 0 END) AS refunded,
                   SUM(CASE WHEN c.status = 'canary_tripped' THEN 1 ELSE 0 END) AS canary_tripped
            FROM redemption_batches b
            LEFT JOIN redemption_codes c ON c.batch_id = b.batch_id
            GROUP BY b.batch_id
            ORDER BY b.created_at DESC
        """).fetchall()
        return {"batches": [dict(row) for row in rows]}


@app.post("/admin/redemption/outbox/drain")
async def admin_drain_redemption_outbox(request: Request, x_admin_token: str = Header(...)):
    # Internal-only: the wins-redemption-outbox systemd timer curls it locally
    # with the admin token, exactly like /admin/monero/poll.
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "redemption outbox drain")
    return await asyncio.to_thread(drain_redemption_outbox)


@app.post("/admin/redemption/revoke-code")
def admin_revoke_redemption_code(
    request: Request,
    serial: str = Form(...),
    reason: str = Form(""),
    reference: str = Form(""),
    x_admin_token: str = Header(...),
):
    # R2: one card, by its printed serial. An unused code is revoked (lost or
    # returned card). A redeemed code is withdrawn for a channel refund or
    # chargeback: exactly its granted span (term plus this grant's own
    # referral and promo days) leaves the account's current expiry, floored at
    # now, and only the referral reward funded by THIS redemption is clawed
    # back. Grants are additive, so later purchases on the account survive.
    # Idempotent: a second call reports the existing terminal status.
    require_admin_token(x_admin_token, request, "revoke redemption code")
    serial = (serial if isinstance(serial, str) else "").strip().upper()
    reason = (reason if isinstance(reason, str) else "").strip()[:200]
    reference = (reference if isinstance(reference, str) else "").strip()[:128]
    if not re.fullmatch(r"[A-Z0-9][A-Z0-9._-]{2,63}-[0-9]{5}", serial):
        raise HTTPException(status_code=400, detail="serial must look like BATCH-ID-00001")
    now = utcnow()
    now_iso = now.isoformat()
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        try:
            row = conn.execute("SELECT * FROM redemption_codes WHERE serial = ?", (serial,)).fetchone()
            if row is None:
                conn.commit()
                raise HTTPException(status_code=404, detail="Unknown serial")
            status = str(row["status"] or "")
            result = {"status": "ok", "serial": serial, "batch_id": row["batch_id"]}
            if status in ("revoked", "refunded", "canary_tripped"):
                conn.commit()
                return {**result, "result": f"already_{status}"}
            account = str(row["account_number"] or "")
            withdrawn_days = 0.0
            if status == "unused":
                conn.execute(
                    "UPDATE redemption_codes SET status='revoked', revoked_reason=?, refund_reference=? "
                    "WHERE code_hash=? AND key_version=? AND status='unused'",
                    (reason or None, reference or None, row["code_hash"], row["key_version"]),
                )
                outcome, result["result"] = "code_revoked", "revoked_unused"
            else:
                grant_start = parse_iso_datetime(row["grant_start"])
                grant_end = parse_iso_datetime(row["grant_end"])
                if grant_start is None or grant_end is None:
                    conn.commit()
                    raise HTTPException(status_code=409, detail="This code predates grant tracking; reconcile the account manually.")
                user = conn.execute("SELECT * FROM users WHERE account_number = ?", (account,)).fetchone() if account else None
                if user is not None and str(user["paypal_subscription_id"] or "").strip():
                    conn.commit()
                    raise HTTPException(status_code=409, detail="The account now renews through PayPal; reconcile it manually.")
                if user is not None:
                    span = grant_end - grant_start
                    current = parse_iso_datetime(user["expiration_date"]) or now
                    new_expiry = max(now, current - span)
                    withdrawn_days = round(max(0.0, (current - new_expiry).total_seconds()) / 86400.0, 2)
                    conn.execute(
                        "UPDATE users SET expiration_date=?, referral_bonus_days=MAX(COALESCE(referral_bonus_days, 0) - ?, 0) "
                        "WHERE account_number=?",
                        (new_expiry.isoformat(), int(row["referral_bonus_days"] or 0), account),
                    )
                    expire_account_runtime_if_due(conn, account)
                # R2-AUDIT-01: deletion and recycling tombstone the reward and
                # promo rows instead of deleting them precisely so a later
                # refund still finds them. `account` is then the tombstone,
                # which is what the reward row carries; the promo row is found
                # by this card's own purchase reference.
                reference_key = f"redemption:{row['key_version']}:{str(row['code_hash'])[:32]}"
                if account:
                    reward = conn.execute(
                        "SELECT purchase_reference FROM referral_rewards WHERE referred_account_number = ? AND clawed_back_at IS NULL",
                        (account,),
                    ).fetchone()
                    if reward is not None and reward["purchase_reference"] == reference_key:
                        claw_back_referral_bonus(conn, account)
                conn.execute(
                    "UPDATE promo_redemptions SET reversed_at=? WHERE purchase_reference=? AND reversed_at IS NULL",
                    (now_iso, reference_key),
                )
                # Withdraw any live delivery artefacts for this grant.
                conn.execute(
                    "DELETE FROM redemption_fulfillments WHERE code_hash=? AND key_version=?",
                    (row["code_hash"], row["key_version"]),
                )
                for event in conn.execute(
                    "SELECT idempotency_key FROM redemption_events WHERE code_hash=? AND key_version=? "
                    "AND outcome='granted' AND idempotency_key IS NOT NULL",
                    (row["code_hash"], row["key_version"]),
                ).fetchall():
                    conn.execute(
                        "UPDATE redemption_outbox SET status='completed', sealed_secret=NULL, completed_at=?, last_error='withdrawn' "
                        "WHERE idempotency_key=? AND status='pending'",
                        (now_iso, event["idempotency_key"]),
                    )
                conn.execute(
                    "UPDATE redemption_codes SET status='refunded', revoked_reason=?, refund_reference=? "
                    "WHERE code_hash=? AND key_version=? AND status='redeemed'",
                    (reason or None, reference or None, row["code_hash"], row["key_version"]),
                )
                outcome, result["result"] = "code_refunded", "withdrawn"
                result["withdrawn_days"] = withdrawn_days
            record_redemption_event(
                conn, outcome=outcome, request=request, batch_id=row["batch_id"],
                code_hash=row["code_hash"], key_version=row["key_version"],
                detail=f"serial={serial} reason={reason[:60]} ref={reference[:60]}",
            )
            conn.commit()
        except HTTPException:
            raise
        except Exception:
            conn.rollback()
            raise
    require_durability_barrier(request, "admin-redemption-revoke-code", {"batch_id": result["batch_id"]})
    return result


@app.post("/admin/promo/create")
def admin_create_promo(
    request: Request,
    bonus_days: int = Form(...),
    max_uses: int = Form(...),
    expires_at: str = Form(""),
    expires_in_days: int = Form(0),
    code: str = Form(""),
    plan_keys: str = Form(""),
    stack_referral: str = Form("false"),
    note: str = Form(""),
    x_admin_token: str = Header(...),
):
    # R2: a campaign grants bonus days only. Leave code empty to generate a
    # random 10-symbol code for a private campaign; pass a vanity code
    # (WELCOME7) for a public one. Campaigns are immutable except revocation.
    require_admin_token(x_admin_token, request, "create promo")
    now = utcnow()
    raw_code = (code if isinstance(code, str) else "").strip()
    if raw_code:
        promo = normalize_promo_code(raw_code)
        if not promo:
            raise HTTPException(status_code=400, detail="code must be 4-32 characters of A-Z, 0-9, _ or -")
    else:
        promo = "".join(secrets.choice(REDEMPTION_ALPHABET) for _ in range(10))
    try:
        bonus_days = int(bonus_days)
        max_uses = int(max_uses)
        expires_in_days = int(expires_in_days or 0)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="bonus_days, max_uses and expires_in_days must be integers")
    expiry = parse_iso_datetime(expires_at) if isinstance(expires_at, str) and expires_at.strip() else None
    if expiry is None and expires_in_days > 0:
        expiry = now + timedelta(days=expires_in_days)
    plans = sorted({p.strip() for p in (plan_keys if isinstance(plan_keys, str) else "").split(",") if p.strip()})
    stack = str(stack_referral if stack_referral is not None else "").strip().lower() in {"1", "true", "yes"}
    # R2-EN: new admin validation strings.
    if not 1 <= bonus_days <= 365 or not 1 <= max_uses <= 100000:
        raise HTTPException(status_code=400, detail="bonus_days must be 1-365 and max_uses 1-100000")
    if expiry is None or expiry <= now or expiry > now + timedelta(days=730):
        raise HTTPException(status_code=400, detail="Give expires_at (ISO 8601) or expires_in_days; the expiry must be within 2 years")
    if any(p not in PROMO_PLAN_KEYS for p in plans):
        raise HTTPException(status_code=400, detail="plan_keys may only contain: " + ", ".join(PROMO_PLAN_KEYS))
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        try:
            if conn.execute("SELECT 1 FROM promo_campaigns WHERE code = ?", (promo,)).fetchone():
                conn.commit()
                raise HTTPException(status_code=409, detail="That promo code already exists; campaigns are immutable")
            conn.execute(
                "INSERT INTO promo_campaigns (code, bonus_days, max_uses, uses, expires_at, plan_keys, stack_referral, note, created_at) "
                "VALUES (?, ?, ?, 0, ?, ?, ?, ?, ?)",
                (promo, bonus_days, max_uses, expiry.isoformat(), ",".join(plans), int(stack),
                 (note if isinstance(note, str) else "")[:200], now.isoformat()),
            )
            record_redemption_event(conn, outcome="promo_created", request=request,
                                    detail=f"code={promo} days={bonus_days} max={max_uses}")
            conn.commit()
        except HTTPException:
            raise
        except Exception:
            conn.rollback()
            raise
    require_durability_barrier(request, "admin-promo-create")
    return {"status": "ok", "code": promo, "bonus_days": bonus_days, "max_uses": max_uses,
            "expires_at": expiry.isoformat(), "plan_keys": plans, "stack_referral": stack}


@app.post("/admin/promo/revoke")
def admin_revoke_promo(request: Request, code: str = Form(...), reason: str = Form(""),
                       x_admin_token: str = Header(...)):
    # Stops future uses; granted days and the use history stay.
    require_admin_token(x_admin_token, request, "revoke promo")
    promo = normalize_promo_code(code)
    with get_db() as conn:
        ensure_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        try:
            changed = conn.execute(
                "UPDATE promo_campaigns SET revoked_at=COALESCE(revoked_at, ?), revoked_reason=COALESCE(revoked_reason, ?) WHERE code=?",
                (utcnow().isoformat(), (reason if isinstance(reason, str) else "")[:200], promo),
            ).rowcount
            if not changed:
                conn.commit()
                raise HTTPException(status_code=404, detail="Unknown promo code")
            record_redemption_event(conn, outcome="promo_revoked", request=request, detail=f"code={promo}")
            conn.commit()
        except HTTPException:
            raise
        except Exception:
            conn.rollback()
            raise
    require_durability_barrier(request, "admin-promo-revoke")
    return {"status": "ok", "code": promo}


@app.get("/admin/promo/list")
def admin_list_promos(request: Request, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "list promos")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT c.*, (SELECT COUNT(*) FROM promo_redemptions r WHERE r.code = c.code AND r.reversed_at IS NOT NULL) AS reversed "
            "FROM promo_campaigns c ORDER BY c.created_at DESC"
        ).fetchall()
        return {"promos": [dict(row) for row in rows]}


@app.post("/admin/donor-acknowledgment/outbox/drain")
async def admin_drain_donor_acknowledgment_outbox(request: Request, x_admin_token: str = Header(...)):
    # Mirrors /admin/redemption/outbox/drain. The wins-donor-ack-outbox
    # systemd timer curls this locally with the admin token.
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "donor acknowledgment outbox drain")
    return await asyncio.to_thread(drain_donor_acknowledgment_outbox)


# =============================================================================
# EMERGENCY DISPATCH RELAY  --  POST /emergency/dispatch
# =============================================================================
# Terminates the duress ("panic PIN") dispatch the app already sends. The client
# contract is fixed and is NOT negotiable from this side; see
# lib/duress_dispatch.dart (DuressDispatch.toWirePayload) and
# lib/gateway_failover.dart (emergencyDispatchGateways). The app POSTs:
#
#   {"kind":"emergency","contact":<str>,"lat":<float?>,"lng":<float?>,
#    "captured_at":<iso8601 utc>,"message":<str>,
#    "account_number":<str?>,"device_id":<str?>,"app_version":<str?>}
#
# with an optional "Authorization: Bearer <device token>" header, and treats ANY
# 2xx as delivered. That last fact is the whole safety contract of this file:
#
#   A 2xx FROM THIS ROUTE CAUSES THE HANDSET TO WIPE ITS ONLY COPY OF THE ALERT
#   (and, on Android, to fire clearApplicationUserData()).
#
# So this route returns 2xx only after the alert is COMMITTED to the outbox
# below. Anything that could lose it returns 5xx instead, which leaves the
# device holding the alert for a later retry. Never "optimise" that away.
#
# Threat model: the user is being physically coerced while this fires, and hub
# logs/disks may be seized afterwards. Everything here is written so that a
# seized log tells an attacker nothing beyond "an endpoint was exercised".
# -----------------------------------------------------------------------------
# LOGGING RULE FOR THIS WHOLE BLOCK (do not relax it):
#   static strings and aggregate counts ONLY. Never the contact, coordinates,
#   captured_at, account number, device id, bearer token, request body, client
#   IP, or any exception *message* (SMTP failure text routinely quotes the
#   recipient address). Exception TYPE names are permitted. The service name is
#   never written into the outgoing message either -- see
#   emergency_message_body().
# =============================================================================

from email.utils import formatdate, make_msgid


def _emergency_flag(name: str, default: bool) -> bool:
    raw = os.getenv(name)
    if raw is None or not raw.strip():
        return default
    return raw.strip().lower() in {"1", "true", "yes", "on"}


def _emergency_int(name: str, default: int, minimum: int = 0) -> int:
    try:
        return max(minimum, int(os.getenv(name, str(default))))
    except (TypeError, ValueError):
        return default


# Master switch. Off => 503 (the handset keeps its copy), never a silent 200.
EMERGENCY_DISPATCH_ENABLED = _emergency_flag("EMERGENCY_DISPATCH_ENABLED", False)

# OWNER DECISION (blocking for the email channel). The From address is part of
# the message the trusted contact receives and keeps. A branded sender would
# link the user to this service on the recipient's device, which is precisely
# what the client-side design spent its effort avoiding, so there is no
# branded default: set EMERGENCY_FROM_EMAIL to a neutral address on a neutral
# domain that is verified with the SMTP relay. Until it is set, alerts are
# accepted and held (never lost) and the operator backlog notice fires.
EMERGENCY_FROM_EMAIL = os.getenv("EMERGENCY_FROM_EMAIL", "").strip()
EMERGENCY_FROM_NAME = os.getenv("EMERGENCY_FROM_NAME", "Safety Notification").strip()
# Deliberate, informed downgrade: relay from the branded EMAIL_SENDER when no
# neutral sender exists. Delivers the alert at the cost of leaking the service
# domain to the recipient. Default off; owner's call.
EMERGENCY_ALLOW_BRANDED_SENDER = _emergency_flag("EMERGENCY_ALLOW_BRANDED_SENDER", False)

# "auto" routes on the shape of the contact. Force a single channel by name.
EMERGENCY_DISPATCH_CHANNEL = os.getenv("EMERGENCY_DISPATCH_CHANNEL", "auto").strip().lower()

# Pacing, NOT admission control. Exceeding any of these delays a delivery; it
# never refuses or discards one. See emergency_pacing_delay().
EMERGENCY_IP_BURST_PER_MINUTE = _emergency_int("EMERGENCY_IP_BURST_PER_MINUTE", 6, 0)
EMERGENCY_CONTACT_BURST_PER_HOUR = _emergency_int("EMERGENCY_CONTACT_BURST_PER_HOUR", 4, 0)
EMERGENCY_GLOBAL_NEW_PER_HOUR = _emergency_int("EMERGENCY_GLOBAL_NEW_PER_HOUR", 60, 0)
EMERGENCY_DEFER_SECONDS = _emergency_int("EMERGENCY_DEFER_SECONDS", 120, 1)
EMERGENCY_MAX_DEFER_SECONDS = _emergency_int("EMERGENCY_MAX_DEFER_SECONDS", 900, 1)

EMERGENCY_OUTBOX_BATCH_LIMIT = _emergency_int("EMERGENCY_OUTBOX_BATCH_LIMIT", 25, 1)
EMERGENCY_SWEEP_INTERVAL_SECONDS = _emergency_int("EMERGENCY_SWEEP_INTERVAL_SECONDS", 60, 5)
EMERGENCY_LEASE_SECONDS = _emergency_int("EMERGENCY_LEASE_SECONDS", 120, 10)
EMERGENCY_BACKLOG_NOTICE_SECONDS = _emergency_int("EMERGENCY_BACKLOG_NOTICE_SECONDS", 3600, 60)
# Retention of the delivered-marker rows that make retries idempotent. The
# destination and coordinates are scrubbed at delivery, long before this.
EMERGENCY_DEDUPE_RETENTION_DAYS = _emergency_int("EMERGENCY_DEDUPE_RETENTION_DAYS", 30, 1)

EMERGENCY_MAX_CONTACT_LENGTH = 254  # matches kMaxTrustedContactLength in the app
EMERGENCY_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
EMERGENCY_PHONE_RE = re.compile(r"^\+?[0-9][0-9 ().-]{5,31}$")


class EmergencyChannelUnavailable(Exception):
    """No transport exists for this destination *yet* -- an owner-configuration
    gap, not a delivery failure. Carries a static reason token only; never an
    exception message, which could quote the recipient."""

    def __init__(self, reason: str):
        super().__init__(reason)
        self.reason = reason


def create_emergency_dispatch_tables(conn: sqlite3.Connection):
    # A transactional outbox, not a fire-and-forget send. The handset destroys
    # its copy on 2xx, so the hub must have durably accepted ownership of the
    # alert before it answers, and must keep retrying afterwards. Rows are
    # therefore never deleted on failure -- only on retention expiry, and only
    # after they have been delivered and scrubbed.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS emergency_outbox (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            dedupe_key TEXT NOT NULL UNIQUE,
            channel TEXT NOT NULL,
            destination TEXT NOT NULL,
            lat REAL,
            lng REAL,
            captured_at TEXT,
            status TEXT NOT NULL DEFAULT 'pending',
            attempts INTEGER NOT NULL DEFAULT 0,
            repeat_count INTEGER NOT NULL DEFAULT 0,
            not_before REAL NOT NULL DEFAULT 0,
            lease_until REAL,
            accepted_at TEXT NOT NULL,
            delivered_at TEXT,
            last_failure_kind TEXT
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_emergency_outbox_due "
        "ON emergency_outbox(status, not_before)"
    )


# ------------------------------- payload -----------------------------------

def emergency_sanitize_contact(raw: Any) -> str:
    # Mirrors sanitizeTrustedContact() in lib/duress_dispatch.dart. Dropping C0
    # controls and DEL is what stops a contact value from smuggling extra
    # headers or lines into a server-composed email or SMS; the client already
    # does it, and the server repeats it because the server is what builds the
    # headers.
    text = "".join(ch for ch in str(raw or "") if ord(ch) >= 0x20 and ord(ch) != 0x7F)
    text = text.strip()
    return text[:EMERGENCY_MAX_CONTACT_LENGTH]


def emergency_coordinate(raw: Any, limit: float) -> Optional[float]:
    # An unusable coordinate degrades the alert; it must never reject it. A
    # dispatch with no location still tells the contact that help is needed.
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    if value != value or value in (float("inf"), float("-inf")):
        return None
    if abs(value) > limit:
        return None
    return value


def emergency_captured_at(raw: Any) -> str:
    """Normalised ISO-8601 UTC capture time, or "" when it is unusable.

    "" also covers the epoch, which is what DuressDispatch.fromQueueJson()
    substitutes for a corrupt queue record -- treating that as a real timestamp
    would let two genuinely different alerts collide on one dedupe key.
    """
    text = str(raw or "").strip()
    if not text:
        return ""
    candidate = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        parsed = datetime.fromisoformat(candidate)
    except (TypeError, ValueError):
        return ""
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    if parsed.year <= 1970:
        return ""
    return parsed.replace(microsecond=0).isoformat()


def emergency_dedupe_key(contact: str, lat: Optional[float], lng: Optional[float],
                         captured_at: str) -> str:
    """Stable across the handset's offline retries, distinct for a genuinely new
    alert.

    captured_at is stamped once, when the duress code is entered, and is
    persisted verbatim in the on-device queue, so every retry of ONE alert
    hashes the same and every fresh duress entry -- a user still in danger,
    triggering again -- hashes differently and is relayed again.

    When captured_at is unusable the key falls back to the hour the hub
    received it. Retries inside that hour still collapse; the suppression can
    never outlive it. Duplicate delivery is a far smaller harm than a dropped
    alert, so the fallback is deliberately weak.
    """
    if captured_at:
        stamp = captured_at
    else:
        stamp = "rx-hour:%d" % int(time.time() // 3600)
    material = "|".join([
        contact,
        "" if lat is None else "%.4f" % lat,
        "" if lng is None else "%.4f" % lng,
        stamp,
    ])
    return hmac.new(RATE_LIMIT_SECRET.encode(),
                    ("emergency:" + material).encode(), hashlib.sha256).hexdigest()


def emergency_resolve_channel(contact: str) -> str:
    if EMERGENCY_DISPATCH_CHANNEL not in ("", "auto"):
        return EMERGENCY_DISPATCH_CHANNEL
    if EMERGENCY_EMAIL_RE.match(contact):
        return "email"
    if EMERGENCY_PHONE_RE.match(contact):
        return "sms"
    return "unroutable"


# ------------------------------- channels ----------------------------------
# Pluggable by design: the owner has not chosen a delivery channel. Add one by
# writing a function with this signature and registering it below. A channel
# raises EmergencyChannelUnavailable when it cannot be used at all (missing
# configuration) and any other exception for a transient failure; both leave
# the row in the outbox to be retried.

def emergency_message_subject() -> str:
    return "Safety notification"


def emergency_message_body(lat: Optional[float], lng: Optional[float],
                           captured_at: str) -> str:
    # Composed HERE, from the structured fields, rather than forwarding the
    # client's "message" verbatim. Two reasons, both load-bearing:
    #  1. It keeps this route worthless as an open relay for attacker-chosen
    #     text -- the only caller-controlled bytes that reach a recipient are a
    #     destination and two numbers.
    #  2. It guarantees the wording, which is the part a coercer may end up
    #     reading, names no application, no service, and no VPN.
    lines = [
        "Someone who listed you as their emergency contact has asked for you to "
        "be notified. They may need help.",
        "",
    ]
    if lat is not None and lng is not None:
        lines.append("Last known approximate location: %.6f, %.6f" % (lat, lng))
        lines.append("Map: https://www.google.com/maps/search/?api=1&query=%.6f,%.6f"
                     % (lat, lng))
        lines.append("This position is approximate and may be several kilometres out.")
    else:
        lines.append("No location was available.")
    if captured_at:
        lines.append("Recorded at (UTC): %s" % captured_at)
    lines += [
        "",
        "This message was sent automatically. Replying to it will not reach them.",
    ]
    return "\n".join(lines)


def emergency_email_sender() -> str:
    if EMERGENCY_FROM_EMAIL:
        return EMERGENCY_FROM_EMAIL
    if EMERGENCY_ALLOW_BRANDED_SENDER:
        return EMAIL_SENDER
    return ""


def emergency_channel_email(destination: str, subject: str, body: str) -> None:
    sender = emergency_email_sender()
    if not sender:
        raise EmergencyChannelUnavailable("neutral_sender_not_configured")
    if not (SMTP_USER and SMTP_PASS):
        raise EmergencyChannelUnavailable("transport_not_configured")
    if not EMERGENCY_EMAIL_RE.match(destination):
        raise EmergencyChannelUnavailable("destination_not_an_address")
    # Belt and braces over emergency_sanitize_contact(): a header may not carry
    # CR/LF under any circumstances.
    if any(ch in destination for ch in "\r\n"):
        raise EmergencyChannelUnavailable("destination_rejected")
    domain = sender.rsplit("@", 1)[-1] or "localhost"
    msg = MIMEText(body, "plain", "utf-8")
    msg["Subject"] = subject
    msg["From"] = "%s <%s>" % (EMERGENCY_FROM_NAME, sender) if EMERGENCY_FROM_NAME else sender
    msg["To"] = destination
    msg["Date"] = formatdate(localtime=False)
    # Default make_msgid() embeds this host's FQDN. Pin it to the sender domain
    # so the hub's hostname does not travel with the alert.
    msg["Message-ID"] = make_msgid(domain=domain)
    msg["Auto-Submitted"] = "auto-generated"
    # NOTE: deliberately NOT smtp_dispatch_message(). That helper is correct for
    # every other caller, but its failure branch logs the exception text, and
    # SMTP rejection strings routinely quote the recipient address. Same
    # transport, same credentials, no logging.
    with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=20) as server:
        server.ehlo()
        server.starttls(context=ssl.create_default_context())
        server.ehlo()
        server.login(SMTP_USER, SMTP_PASS)
        server.sendmail(sender, [destination], msg.as_string())


def emergency_channel_sms(destination: str, subject: str, body: str) -> None:
    # OWNER DECISION -- not implemented. No SMS provider is configured on this
    # hub and this task does not sign up for one. Wire a provider here (its
    # credentials belong in the systemd EnvironmentFile, never in this file)
    # and the queued phone-number alerts drain automatically.
    raise EmergencyChannelUnavailable("sms_channel_not_implemented")


def emergency_channel_messenger(destination: str, subject: str, body: str) -> None:
    # OWNER DECISION -- not implemented. Signal/Telegram/Matrix all need an
    # account, a registered number or a bot token, plus a policy on what the
    # relay's own metadata reveals. Left explicit rather than silently absent.
    raise EmergencyChannelUnavailable("messenger_channel_not_implemented")


def emergency_channel_unroutable(destination: str, subject: str, body: str) -> None:
    raise EmergencyChannelUnavailable("contact_shape_unrecognised")


EMERGENCY_CHANNELS = {
    "email": emergency_channel_email,
    "sms": emergency_channel_sms,
    "messenger": emergency_channel_messenger,
    "unroutable": emergency_channel_unroutable,
}


# ------------------------------- pacing ------------------------------------

def emergency_consume_bucket(conn: sqlite3.Connection, bucket: str, limit: int,
                             window_seconds: int) -> bool:
    """Count one hit and report whether the bucket is now over its limit.

    Same atomic INSERT .. ON CONFLICT .. RETURNING primitive as
    check_rate_limit(), but it RETURNS instead of raising: on this route a
    limit must never become a refusal.
    """
    if limit <= 0:
        return False
    now = time.time()
    row = conn.execute(
        """
        INSERT INTO rate_limits (bucket, count, reset_at) VALUES (?, 1, ?)
        ON CONFLICT(bucket) DO UPDATE SET
          count = CASE WHEN rate_limits.reset_at <= ? THEN 1 ELSE rate_limits.count + 1 END,
          reset_at = CASE WHEN rate_limits.reset_at <= ? THEN excluded.reset_at ELSE rate_limits.reset_at END
        RETURNING count
        """,
        (bucket, now + window_seconds, now, now),
    ).fetchone()
    try:
        return int(row["count"]) > limit
    except (TypeError, ValueError, KeyError):
        return False


def emergency_pacing_delay(conn: sqlite3.Connection, request: Request, contact: str,
                           trusted: bool) -> float:
    """Seconds to hold a NEW alert before its first delivery attempt.

    This is the whole rate-limiting design, and it is deliberately not a
    rejection: a refused duress alert is a person who does not get help. A
    flood therefore cannot deny the endpoint to anyone -- it can only make its
    own alerts queue behind a short delay, which removes the endpoint's value
    for spamming a mailbox or probing which contacts exist, while a genuine
    alert (one device, one or two dispatches) never trips a bucket at all.

    A caller holding a valid device token is paced by nothing: it has already
    proved it is a real enrolled device, which is the one thing an abuser
    cannot manufacture in bulk.
    """
    delay = 0.0
    if trusted:
        return delay
    if emergency_consume_bucket(
        conn,
        rate_limit_bucket("emergency-ip", request_origin_bucket_value(request)),
        EMERGENCY_IP_BURST_PER_MINUTE,
        60,
    ):
        delay = max(delay, float(EMERGENCY_DEFER_SECONDS))
    if emergency_consume_bucket(
        conn,
        rate_limit_bucket("emergency-contact", contact),
        EMERGENCY_CONTACT_BURST_PER_HOUR,
        3600,
    ):
        delay = max(delay, float(EMERGENCY_DEFER_SECONDS))
    return min(delay, float(EMERGENCY_MAX_DEFER_SECONDS))


def emergency_trusted_caller(conn: sqlite3.Connection, request: Request) -> bool:
    """True when the bearer token belongs to some enrolled device.

    WHY THIS ROUTE CANNOT REQUIRE AUTHENTICATION
    --------------------------------------------
    The alert is produced by _armDuress() at the same moment the app is
    destroying its own credentials, and the realistic case (handset offline
    during the inspection) delivers it from _retryDuressDispatch() on a LATER
    launch -- after the wipe, from a store that by design retains nothing but
    the queued dispatch. There is then no token and no account number to send.
    Requiring auth would reject exactly the alerts that matter most, and would
    also mean the hub could only relay for accounts it can still identify --
    which is the correlation this feature exists to avoid.

    So authentication is OPPORTUNISTIC: proof of a real device buys a
    pacing-free lane, and its absence costs nothing but a possible short delay.
    Abuse is contained by what the endpoint can be made to *do* (see
    emergency_message_body: an attacker cannot choose the text) rather than by
    who is allowed to call it.

    Nothing about the outcome is stored or logged -- not the account, not the
    device, not even the fact that the token was valid.
    """
    try:
        token = bearer_token_from_request(request)
        if not token:
            return False
        row = conn.execute(
            "SELECT 1 FROM devices WHERE device_auth_token_hash = ? LIMIT 1",
            (token_digest(token),),
        ).fetchone()
        return row is not None
    except Exception:
        return False


# ------------------------------- delivery ----------------------------------

def emergency_backoff_seconds(attempts: int) -> float:
    return float(min(EMERGENCY_MAX_DEFER_SECONDS, 30 * (2 ** min(max(attempts, 0), 7))))


def claim_emergency_batch(conn: sqlite3.Connection, limit: int, lease: float) -> list:
    now = time.time()
    rows = conn.execute(
        """
        SELECT * FROM emergency_outbox
        WHERE status IN ('pending', 'held')
          AND not_before <= ?
          AND (lease_until IS NULL OR lease_until <= ?)
        ORDER BY not_before ASC, id ASC
        LIMIT ?
        """,
        (now, now, limit),
    ).fetchall()
    claimed = []
    for row in rows:
        cur = conn.execute(
            "UPDATE emergency_outbox SET lease_until = ?, attempts = attempts + 1 "
            "WHERE id = ? AND (lease_until IS NULL OR lease_until <= ?)",
            (lease, row["id"], now),
        )
        if cur.rowcount:
            claimed.append(dict(row))
    return claimed


def deliver_emergency_row(item: dict) -> None:
    channel = EMERGENCY_CHANNELS.get(item.get("channel") or "", emergency_channel_unroutable)
    channel(
        item.get("destination") or "",
        emergency_message_subject(),
        emergency_message_body(item.get("lat"), item.get("lng"),
                               item.get("captured_at") or ""),
    )


def drain_emergency_outbox(limit: int = 0) -> dict:
    """Attempt every due alert. Synchronous; run it off the event loop.

    Returns aggregate counts only -- they are safe to log and are what the
    admin view reports.
    """
    limit = limit or EMERGENCY_OUTBOX_BATCH_LIMIT
    delivered = 0
    held = 0
    failed = 0
    with get_db() as conn:
        ensure_schema(conn)
        # Close any implicit transaction ensure_schema may have opened before
        # asking for the write lock, or BEGIN IMMEDIATE raises "cannot start a
        # transaction within a transaction" and every queued alert stalls.
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        batch = claim_emergency_batch(conn, limit, time.time() + EMERGENCY_LEASE_SECONDS)
        conn.commit()
        for item in batch:
            try:
                deliver_emergency_row(item)
            except EmergencyChannelUnavailable as exc:
                held += 1
                # Configuration gap, not a bad alert. Hold it and keep it.
                conn.execute(
                    "UPDATE emergency_outbox SET status='held', lease_until=NULL, "
                    "not_before=?, last_failure_kind=? WHERE id=?",
                    (time.time() + emergency_backoff_seconds(item["attempts"]),
                     exc.reason, item["id"]),
                )
                conn.commit()
                continue
            except Exception as exc:
                failed += 1
                # TYPE name only. An SMTP rejection string quotes the recipient.
                conn.execute(
                    "UPDATE emergency_outbox SET status='pending', lease_until=NULL, "
                    "not_before=?, last_failure_kind=? WHERE id=?",
                    (time.time() + emergency_backoff_seconds(item["attempts"]),
                     type(exc).__name__, item["id"]),
                )
                conn.commit()
                continue
            delivered += 1
            # Delivered: scrub the destination and the coordinates immediately.
            # What remains is an irreversible HMAC that keeps a later retry
            # idempotent and proves nothing about anyone.
            conn.execute(
                "UPDATE emergency_outbox SET status='delivered', delivered_at=?, "
                "lease_until=NULL, destination='', lat=NULL, lng=NULL, "
                "captured_at=NULL, last_failure_kind=NULL WHERE id=?",
                (utcnow().isoformat(), item["id"]),
            )
            conn.commit()
        cutoff = (utcnow() - timedelta(days=EMERGENCY_DEDUPE_RETENTION_DAYS)).isoformat()
        conn.execute(
            "DELETE FROM emergency_outbox WHERE status='delivered' AND delivered_at < ?",
            (cutoff,),
        )
        conn.commit()
    if delivered or held or failed:
        # Counts only. No identifier of any kind, and nothing that names this
        # service or its purpose.
        logger.info("relay drain: %d sent, %d held, %d retry", delivered, held, failed)
    return {"delivered": delivered, "held": held, "retry": failed}


def emergency_backlog_count(conn: sqlite3.Connection) -> int:
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM emergency_outbox WHERE status IN ('pending','held')"
    ).fetchone()
    return int(row["n"]) if row else 0


_EMERGENCY_BACKLOG_NOTICE_AT = [0.0]


def emergency_backlog_notice(count: int) -> None:
    """Tell the OPERATOR that undeliverable alerts are accumulating.

    Without this, "queue instead of drop" degrades into "drop slowly": alerts
    for a channel nobody has configured would sit in the outbox unnoticed. The
    notice carries a fixed subject, a fixed body and one integer -- no
    destination, no location, no time of capture, nothing about any user.
    """
    now = time.time()
    if now - _EMERGENCY_BACKLOG_NOTICE_AT[0] < EMERGENCY_BACKLOG_NOTICE_SECONDS:
        return
    _EMERGENCY_BACKLOG_NOTICE_AT[0] = now
    logger.error("relay backlog: %d undelivered", count)
    if not (SECURITY_ALERT_EMAIL and SMTP_USER and SMTP_PASS):
        return
    try:
        msg = MIMEText(
            "%d queued relay item(s) could not be delivered.\n\n"
            "Check the configured delivery channel and credentials on the hub.\n"
            "This notice contains no item detail by design.\n" % count,
            "plain",
            "utf-8",
        )
        msg["Subject"] = "Hub relay backlog requires attention"
        msg["From"] = EMAIL_SENDER
        msg["To"] = SECURITY_ALERT_EMAIL
        with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=20) as server:
            server.ehlo()
            server.starttls(context=ssl.create_default_context())
            server.ehlo()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(EMAIL_SENDER, [SECURITY_ALERT_EMAIL], msg.as_string())
    except Exception as exc:
        logger.error("relay backlog notice failed: %s", type(exc).__name__)


def notify_emergency_backlog():
    with get_db() as conn:
        ensure_schema(conn)
        backlog = emergency_backlog_count(conn)
    if backlog:
        emergency_backlog_notice(backlog)


async def emergency_outbox_sweep_loop():
    # The client wipes its copy on 2xx, so retrying is the hub's job from that
    # moment on. Fully guarded: a failure here can never affect request
    # handling, and the next tick retries.
    while True:
        try:
            await asyncio.sleep(EMERGENCY_SWEEP_INTERVAL_SECONDS)
            await asyncio.to_thread(drain_emergency_outbox)
            await asyncio.to_thread(notify_emergency_backlog)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.error("relay sweep failed: %s", type(exc).__name__)


# -------------------------------- route ------------------------------------

@app.post("/emergency/dispatch")
async def emergency_dispatch(request: Request, background_tasks: BackgroundTasks):
    if not EMERGENCY_DISPATCH_ENABLED:
        # 503, never 200: a 200 would make the handset destroy the only copy.
        raise HTTPException(status_code=503, detail="Unavailable")

    # Everything up to the commit is wrapped: an exception escaping this handler
    # would reach global_exception_handler(), which logs the REQUEST PATH. On
    # every other route that is a useful breadcrumb; on this one it is the one
    # log line that says a duress alert was attempted.
    try:
        body = await read_request_body_mapping(request)
    except HTTPException:
        raise
    except Exception as exc:
        logger.error("relay parse failed: %s", type(exc).__name__)
        raise HTTPException(status_code=503, detail="Unavailable")
    return await asyncio.to_thread(_emergency_dispatch_sync, request, background_tasks, body)


def _emergency_dispatch_sync(request: Request, background_tasks: BackgroundTasks, body: dict):
    try:
        # The app may include account_number / device_id / app_version, and may
        # send a bearer token. NONE of them are read into a variable that is
        # stored, logged, or composed into the outgoing message. The bearer token
        # is used once, in emergency_trusted_caller(), and discarded. This is the
        # point in the system where the client's careful minimisation would be
        # undone if the server were careless, so it is stated rather than assumed.
        contact = emergency_sanitize_contact(body.get("contact"))
        if not contact:
            # Nowhere to deliver. The app never builds a dispatch without a
            # contact, so this is a malformed or hostile body, and no retry could
            # fix it.
            raise HTTPException(status_code=400, detail="Missing contact")
        lat = emergency_coordinate(body.get("lat"), 90.0)
        lng = emergency_coordinate(body.get("lng"), 180.0)
        if lat is None or lng is None:
            lat = lng = None
        captured_at = emergency_captured_at(body.get("captured_at"))
        channel = emergency_resolve_channel(contact)
        key = emergency_dedupe_key(contact, lat, lng, captured_at)
    except HTTPException:
        raise
    except Exception as exc:
        logger.error("relay parse failed: %s", type(exc).__name__)
        raise HTTPException(status_code=503, detail="Unavailable")

    try:
        with get_db() as conn:
            ensure_schema(conn)
            trusted = emergency_trusted_caller(conn, request)
            delay = emergency_pacing_delay(conn, request, contact, trusted)
            conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            now = time.time()
            row = conn.execute(
                """
                INSERT INTO emergency_outbox (
                    dedupe_key, channel, destination, lat, lng, captured_at,
                    status, not_before, accepted_at
                ) VALUES (?, ?, ?, ?, ?, ?, 'pending', ?, ?)
                ON CONFLICT(dedupe_key) DO UPDATE SET
                    repeat_count = emergency_outbox.repeat_count + 1,
                    not_before = MIN(emergency_outbox.not_before, excluded.not_before)
                RETURNING id, status, repeat_count, not_before
                """,
                (key, channel, contact, lat, lng, captured_at or None,
                 now + delay, utcnow().isoformat()),
            ).fetchone()
            item_id = int(row["id"])
            state = str(row["status"])
            first_time = int(row["repeat_count"]) == 0
            if first_time and emergency_consume_bucket(
                conn,
                rate_limit_bucket("emergency-global-new", "global"),
                EMERGENCY_GLOBAL_NEW_PER_HOUR,
                3600,
            ) and not trusted:
                # Enumeration/spray ceiling. Still accepted, still delivered --
                # just paced, so a sprayer cannot use delivery timing as an
                # oracle and cannot exhaust the relay for real users.
                conn.execute(
                    "UPDATE emergency_outbox SET not_before = MAX(not_before, ?) WHERE id = ?",
                    (now + min(EMERGENCY_DEFER_SECONDS * 2, EMERGENCY_MAX_DEFER_SECONDS),
                     item_id),
                )
            due_now = conn.execute(
                "SELECT not_before FROM emergency_outbox WHERE id = ?", (item_id,)
            ).fetchone()["not_before"] <= time.time()
            conn.commit()
    except HTTPException:
        raise
    except Exception as exc:
        # Nothing was committed, so the handset MUST keep its copy. 5xx is the
        # only honest answer here.
        logger.error("relay accept failed: %s", type(exc).__name__)
        raise HTTPException(status_code=503, detail="Unavailable")

    # Committed. From here a 2xx is safe: the alert survives a crash, and the
    # sweep loop owns every retry.
    if state == "delivered":
        return {"status": "ok", "state": "already_relayed"}
    if due_now:
        background_tasks.add_task(_emergency_deliver_now)
    return {"status": "ok", "state": "queued"}


async def _emergency_deliver_now():
    # First attempt straight after the response, so an uncontended alert is
    # relayed in seconds rather than waiting for the sweep tick.
    try:
        await asyncio.to_thread(drain_emergency_outbox)
    except Exception as exc:
        logger.error("relay immediate attempt failed: %s", type(exc).__name__)


@app.get("/admin/emergency/outbox")
def admin_emergency_outbox(request: Request, x_admin_token: str = Header(...)):
    # Counts by state ONLY. There is deliberately no way to read a queued
    # alert's destination or location back out of this hub over HTTP.
    require_admin_token(x_admin_token, request, "relay outbox status")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT status, COUNT(*) AS n FROM emergency_outbox GROUP BY status"
        ).fetchall()
        reasons = conn.execute(
            "SELECT last_failure_kind AS kind, COUNT(*) AS n FROM emergency_outbox "
            "WHERE status IN ('pending','held') AND last_failure_kind IS NOT NULL "
            "GROUP BY last_failure_kind"
        ).fetchall()
        return {
            "counts": {str(r["status"]): int(r["n"]) for r in rows},
            "held_reasons": {str(r["kind"]): int(r["n"]) for r in reasons},
            "channel": EMERGENCY_DISPATCH_CHANNEL,
            "email_sender_configured": bool(emergency_email_sender()),
        }


@app.post("/admin/emergency/outbox/drain")
async def admin_drain_emergency_outbox(request: Request, x_admin_token: str = Header(...)):
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "relay outbox drain")
    return await asyncio.to_thread(drain_emergency_outbox)

# =============================================================================
# Hoppy agent Tier 1 control-plane API (design: docs/design/HOPPY_AGENT_V1_20260811.md)
# -----------------------------------------------------------------------------
# The deterministic policy engine's Tier 1 actions as real, self-authorising
# endpoints. Everything here follows two invariants established by the carve
# out in this file: identity comes from a signed, short-lived, account-scoped
# token, never from the conversation; and every mutation is idempotent on a
# server-derived key, writes an append-only audit row with actor
# 'hoppy-agent', and admits only operations the tier allows.
#
# HOPPY_AGENT_HMAC separates this surface from ADMIN_SECRET_TOKEN on purpose.
# A token minted from it binds account_number AND action AND expiry in one
# HMAC, so neither the conversation/model nor a body field can redirect an
# action to another account or to a forbidden action. Refunds, payment method
# changes, account deletion, email-on-file changes, prepaid code operations
# and anything touching servers/key material are Tier 2 and have NO endpoint
# here; the only way to perform them is ordinary admin/operator tooling, and
# no request shape can cross into them.
# =============================================================================
HOPPY_AGENT_HMAC = os.getenv("HOPPY_AGENT_HMAC") or ""
HOPPY_AGENT_TOKEN_TTL_SECONDS = max(30, min(900, int(os.getenv("HOPPY_AGENT_TOKEN_TTL_SECONDS", "300"))))
HOPPY_AGENT_CLOCK_SKEW_SECONDS = max(0, min(120, int(os.getenv("HOPPY_AGENT_CLOCK_SKEW_SECONDS", "30"))))
HOPPY_AGENT_IP_RATE_LIMIT_PER_MINUTE = int(os.getenv("HOPPY_AGENT_IP_RATE_LIMIT_PER_MINUTE", "12"))
HOPPY_AGENT_ACCOUNT_RATE_LIMIT_PER_HOUR = int(os.getenv("HOPPY_AGENT_ACCOUNT_RATE_LIMIT_PER_HOUR", "24"))
HOPPY_AGENT_OUTBOX_MAX_ATTEMPTS = max(1, int(os.getenv("HOPPY_AGENT_OUTBOX_MAX_ATTEMPTS", "10")))
HOPPY_AGENT_OUTBOX_LEASE_SECONDS = max(30, int(os.getenv("HOPPY_AGENT_OUTBOX_LEASE_SECONDS", "300")))
HOPPY_AGENT_OUTBOX_BATCH_LIMIT = max(1, min(200, int(os.getenv("HOPPY_AGENT_OUTBOX_BATCH_LIMIT", "20"))))
HOPPY_AGENT_AUDIT_RETENTION_DAYS = 365


def create_hoppy_agent_tables(conn: sqlite3.Connection):
    # Idempotency ledger. idempotency_key is the ONLY identity of a logical
    # action; result_json is the exact response a replay must return, so an
    # identical retry after a lost response cannot double-execute.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS hoppy_agent_actions (
            idempotency_key TEXT PRIMARY KEY,
            account_ref TEXT NOT NULL,
            action TEXT NOT NULL,
            request_id TEXT NOT NULL,
            result_json TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
    """)
    # Append-only audit trail. actor is always 'hoppy-agent' (design: "logged
    # with an actor of hoppy-agent"). account_ref and request_id are one-way
    # hashes so this row cannot become a PII dump; the idempotency_key ties it
    # back to the action row. UPDATE is forbidden outright; DELETE is permitted
    # only for defined retention pruning, mirroring redemption_events.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS hoppy_agent_audit (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE,
            occurred_at TEXT NOT NULL,
            actor TEXT NOT NULL,
            action TEXT NOT NULL,
            account_ref TEXT NOT NULL,
            idempotency_key TEXT,
            source_ip_bucket TEXT,
            user_agent_hash TEXT,
            outcome TEXT NOT NULL,
            detail TEXT
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_hoppy_agent_audit_occurred ON hoppy_agent_audit(occurred_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_hoppy_agent_audit_action ON hoppy_agent_audit(action, occurred_at)")
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS hoppy_agent_audit_append_only_update
        BEFORE UPDATE ON hoppy_agent_audit
        BEGIN
            SELECT RAISE(ABORT, 'hoppy_agent_audit is append-only');
        END
    """)
    conn.execute("""
        CREATE TRIGGER IF NOT EXISTS hoppy_agent_audit_append_only_delete
        BEFORE DELETE ON hoppy_agent_audit
        WHEN OLD.occurred_at >= strftime('%Y-%m-%dT%H:%M:%S', 'now', '-365 days')
        BEGIN
            SELECT RAISE(ABORT, 'hoppy_agent_audit is append-only');
        END
    """)
    # Transactional mail outbox, mirroring redemption_outbox. Anything that
    # sends mail writes HERE inside the action transaction; a background drain
    # delivers and confirms, never inside the mutation.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS hoppy_agent_mail_outbox (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            idempotency_key TEXT NOT NULL UNIQUE,
            kind TEXT NOT NULL,
            account_ref TEXT NOT NULL,
            target_email TEXT,
            status TEXT NOT NULL DEFAULT 'pending',
            attempts INTEGER NOT NULL DEFAULT 0,
            lease_until TEXT,
            last_error TEXT,
            delivered_at TEXT,
            barrier_confirmed_at TEXT,
            created_at TEXT NOT NULL,
            completed_at TEXT
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_hoppy_agent_mail_status ON hoppy_agent_mail_outbox(status, lease_until)")
    # The credentials-resend mail's own sealed copy of the key set it mails
    # (K3-03), written when the set is first minted so every retry of the same
    # outbox row re-sends the same keys. NULL until then, and again after delivery.
    add_column_if_missing(conn, "hoppy_agent_mail_outbox", "sealed_secret", "TEXT")
    # Per-account device-limit override (NULL = use the global DEVICE_LIMIT)
    # and the stored preferred region/server.
    add_column_if_missing(conn, "users", "device_limit_override", "INTEGER")
    add_column_if_missing(conn, "users", "preferred_region", "TEXT")
    add_column_if_missing(conn, "users", "preferred_server", "TEXT")


def hoppy_agent_enabled() -> bool:
    return bool(HOPPY_AGENT_HMAC)


def _hoppy_account_ref(account: str) -> str:
    return security_event_hash(f"hoppy-account:{account}")


def _hoppy_sign(account: str, action: str, expiry: int) -> str:
    msg = f"hoppy-agent:v1:{account}:{action}:{expiry}".encode()
    return hmac.new(HOPPY_AGENT_HMAC.encode(), msg, hashlib.sha256).hexdigest()


def mint_hoppy_agent_token(account: str, action: str = "") -> tuple:
    # Intended for a policy engine / test harness holding HOPPY_AGENT_HMAC.
    # Real deployments mint these east-west, never over a public surface.
    expiry = int(time.time()) + HOPPY_AGENT_TOKEN_TTL_SECONDS
    sig = _hoppy_sign(account, action, expiry)
    return f"hoppy-v1.{account}.{action}.{expiry}.{sig}", expiry


def require_hoppy_agent_auth(request: Request, action: str, expected_account: str) -> str:
    if not hoppy_agent_enabled():
        raise HTTPException(status_code=503, detail="Hoppy agent API is not configured on this hub.")
    supplied = request.headers.get("x-hoppy-agent-token") or ""
    parts = supplied.split(".")
    if len(parts) != 5 or parts[0] != "hoppy-v1":
        security_alert(2, "hoppy agent malformed token", request=request, details={"action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")
    _version, account, act, exp_str, sig = parts
    if account != expected_account:
        security_alert(2, "hoppy agent account mismatch", request=request, details={
            "action": action,
            "account_ref": _hoppy_account_ref(expected_account),
        })
        raise HTTPException(status_code=403, detail="Forbidden")
    if act and act != action:
        security_alert(2, "hoppy agent action mismatch", request=request, details={
            "action": action,
            "token_action": (act or "")[:40],
        })
        raise HTTPException(status_code=403, detail="Forbidden")
    try:
        expiry = int(exp_str)
    except (TypeError, ValueError):
        security_alert(2, "hoppy agent bad expiry", request=request, details={"action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")
    now = int(time.time())
    if expiry < now - HOPPY_AGENT_CLOCK_SKEW_SECONDS or expiry > now + HOPPY_AGENT_TOKEN_TTL_SECONDS + HOPPY_AGENT_CLOCK_SKEW_SECONDS:
        security_alert(2, "hoppy agent token outside window", request=request, details={
            "action": action,
            "account_ref": _hoppy_account_ref(expected_account),
        })
        raise HTTPException(status_code=401, detail="Unauthorized")
    expected = _hoppy_sign(account, act, expiry)
    if not hmac.compare_digest(expected, sig):
        security_alert(2, "hoppy agent bad signature", request=request, details={"action": action})
        raise HTTPException(status_code=401, detail="Unauthorized")
    return account


def hoppy_agent_idempotency_key(
    account: str,
    action: str,
    request_id: str,
    *,
    resource: str = "",
) -> str:
    resource_binding = hashlib.sha256(resource.encode()).hexdigest() if resource else "-"
    return hmac.new(
        HOPPY_AGENT_HMAC.encode(),
        f"hoppy-agent-idem:{account}:{action}:{request_id}:{resource_binding}".encode(),
        hashlib.sha256,
    ).hexdigest()


def _hoppy_request_id(payload) -> str:
    request_id = str(getattr(payload, "request_id", "") or "").strip()
    if not request_id:
        raise HTTPException(status_code=400, detail="Missing request_id")
    return request_id


def _hoppy_try_replay(conn: sqlite3.Connection, idempotency_key: str):
    row = conn.execute(
        "SELECT result_json FROM hoppy_agent_actions WHERE idempotency_key = ?",
        (idempotency_key,),
    ).fetchone()
    return row["result_json"] if row else None


def _hoppy_store_idempotency(conn: sqlite3.Connection, idempotency_key: str, account: str, action: str, request_id: str, result_json: str):
    conn.execute("""
        INSERT INTO hoppy_agent_actions (idempotency_key, account_ref, action, request_id, result_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
    """, (
        idempotency_key,
        _hoppy_account_ref(account),
        action,
        (request_id or "")[:128],
        result_json,
        utcnow().isoformat(),
    ))


def _hoppy_record_audit(conn: sqlite3.Connection, request, action: str, account: str, idempotency_key: str, outcome: str, detail: str = ""):
    event_id = secrets.token_hex(16)
    conn.execute("""
        INSERT INTO hoppy_agent_audit (
            event_id, occurred_at, actor, action, account_ref, idempotency_key,
            source_ip_bucket, user_agent_hash, outcome, detail
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        event_id,
        utcnow().isoformat(),
        "hoppy-agent",
        action,
        _hoppy_account_ref(account),
        idempotency_key,
        security_event_hash(request_origin_bucket_value(request)) if request else None,
        security_event_hash(request.headers.get("user-agent", "")) if request and request.headers.get("user-agent") else None,
        outcome,
        (detail or "")[:200] or None,
    ))


def _hoppy_effective_device_limit(conn: sqlite3.Connection, account: str) -> int:
    row = conn.execute(
        "SELECT device_limit_override FROM users WHERE account_number = ?", (account,)
    ).fetchone()
    if row is not None and row["device_limit_override"] is not None:
        try:
            override = int(row["device_limit_override"])
            if override >= 1:
                return override
        except (TypeError, ValueError):
            pass
    return DEVICE_LIMIT


def _hoppy_masked_email(email: str) -> str:
    email = (email or "").strip()
    if not email or "@" not in email:
        return ""
    local, _, domain = email.partition("@")
    shown = local[0] if local else ""
    masked = f"{shown}***@{domain}"
    return masked


class HoppyDeviceRevokeRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    account_number: str = Field(default="", max_length=64)
    accountnumber: str = Field(default="", max_length=64)
    device_id: str = Field(default="", max_length=256)
    request_id: str = Field(default="", max_length=128)


class HoppyAccountRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    account_number: str = Field(default="", max_length=64)
    accountnumber: str = Field(default="", max_length=64)
    request_id: str = Field(default="", max_length=128)


class HoppyPreferredServerRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    account_number: str = Field(default="", max_length=64)
    accountnumber: str = Field(default="", max_length=64)
    region: str = Field(default="", max_length=128)
    server: str = Field(default="", max_length=128)
    request_id: str = Field(default="", max_length=128)


def _hoppy_resolve_account(payload) -> str:
    acc = normalize_account_number(
        getattr(payload, "account_number", None) or getattr(payload, "accountnumber", None) or ""
    )
    return acc


@app.post("/api/agent/v1/device-limit-reset")
def hoppy_agent_device_limit_reset(request: Request, background_tasks: BackgroundTasks, payload: HoppyAccountRequest):
    # Tier 1: clear the authenticated account's device list and reset its
    # device-limit override back to the platform default. Scoped to the token.
    acc = _hoppy_resolve_account(payload)
    if not acc:
        raise HTTPException(status_code=400, detail="Missing account_number/accountnumber")
    request_id = _hoppy_request_id(payload)
    require_hoppy_agent_auth(request, "device-limit-reset", acc)
    with get_db() as conn:
        ensure_schema(conn)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-reset-ip", request_origin_bucket_value(request)), HOPPY_AGENT_IP_RATE_LIMIT_PER_MINUTE, 60)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-reset-account", acc), HOPPY_AGENT_ACCOUNT_RATE_LIMIT_PER_HOUR, 3600)
        user = conn.execute("SELECT account_number, email FROM users WHERE account_number = ?", (acc,)).fetchone()
        if user is None:
            raise HTTPException(status_code=404, detail="Account not found")
        idem = hoppy_agent_idempotency_key(acc, "device-limit-reset", request_id)
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            return JSONResponse(status_code=200, content=json.loads(replayed))
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            return JSONResponse(status_code=200, content=json.loads(replayed))
        # Persist peer removals in the same transaction that clears
        # the device rows. device_limit_override NULL restores the global default.
        devices = conn.execute(
            "SELECT client_public_key, location_slug FROM devices WHERE account_number = ?",
            (acc,),
        ).fetchall()
        conn.execute("DELETE FROM double_vpn_assignments WHERE account_number = ?", (acc,))
        # A support reset deactivates every device and returns each one's
        # setup key (owner ruling 2026-10-25).
        cleared = deactivate_account_devices_returning_keys(conn, acc)
        conn.execute("UPDATE users SET device_limit_override = NULL WHERE account_number = ?", (acc,))
        for drow in devices:
            client_key = (drow["client_public_key"] or "").strip()
            if not client_key:
                continue
            node = conn.execute(
                "SELECT ssh_host, endpoint FROM nodes WHERE slug = ?", (drow["location_slug"],)
            ).fetchone()
            if node is None:
                continue
            node_ip = node["ssh_host"] or extract_node_host(node["endpoint"] or "")
            if node_ip:
                queue_peer_revocation(conn, node_ip, client_key, background_tasks)
        if cleared:
            background_tasks.add_task(drain_winn3_registry_refreshes)
        _hoppy_record_audit(conn, request, "device-limit-reset", acc, idem, "completed", f"cleared={cleared}")
        result = {
            "ok": True,
            "action": "device-limit-reset",
            "account_ref": _hoppy_account_ref(acc),
            "cleared_device_count": cleared,
            "device_limit": _hoppy_effective_device_limit(conn, acc),
        }
        _hoppy_store_idempotency(conn, idem, acc, "device-limit-reset", request_id, json.dumps(result))
        conn.commit()
    return JSONResponse(status_code=200, content=result)


@app.post("/api/agent/v1/device-revoke")
def hoppy_agent_device_revoke(request: Request, background_tasks: BackgroundTasks, payload: HoppyDeviceRevokeRequest):
    # Tier 1: revoke ONE named device session on the authenticated account.
    acc = _hoppy_resolve_account(payload)
    device_id = (payload.device_id or "").strip()
    if not acc:
        raise HTTPException(status_code=400, detail="Missing account_number/accountnumber")
    if not device_id:
        raise HTTPException(status_code=400, detail="Missing device_id")
    request_id = _hoppy_request_id(payload)
    require_hoppy_agent_auth(request, "device-revoke", acc)
    with get_db() as conn:
        ensure_schema(conn)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-revoke-ip", request_origin_bucket_value(request)), HOPPY_AGENT_IP_RATE_LIMIT_PER_MINUTE, 60)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-revoke-account", acc), HOPPY_AGENT_ACCOUNT_RATE_LIMIT_PER_HOUR, 3600)
        user = conn.execute("SELECT account_number FROM users WHERE account_number = ?", (acc,)).fetchone()
        if user is None:
            raise HTTPException(status_code=404, detail="Account not found")
        idem = hoppy_agent_idempotency_key(
            acc, "device-revoke", request_id, resource=device_id
        )
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            return JSONResponse(status_code=200, content=json.loads(replayed))
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            return JSONResponse(status_code=200, content=json.loads(replayed))
        row = conn.execute(
            "SELECT device_id, client_public_key, location_slug FROM devices WHERE account_number = ? AND device_id = ?",
            (acc, device_id),
        ).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Device not found on this account")
        conn.execute(
            "DELETE FROM double_vpn_assignments WHERE account_number = ? AND device_id = ?",
            (acc, device_id),
        )
        # A support removal returns the device's setup key (owner ruling 2026-10-25).
        deactivate_device_returning_key(conn, acc, device_id)
        client_key = (row["client_public_key"] or "").strip()
        if client_key:
            node = conn.execute(
                "SELECT ssh_host, endpoint FROM nodes WHERE slug = ?", (row["location_slug"],)
            ).fetchone()
            if node is not None:
                node_ip = node["ssh_host"] or extract_node_host(node["endpoint"] or "")
                if node_ip:
                    queue_peer_revocation(conn, node_ip, client_key, background_tasks)
        background_tasks.add_task(drain_winn3_registry_refreshes)
        _hoppy_record_audit(conn, request, "device-revoke", acc, idem, "completed")
        result = {
            "ok": True,
            "action": "device-revoke",
            "account_ref": _hoppy_account_ref(acc),
            "revoked_device": True,
        }
        _hoppy_store_idempotency(conn, idem, acc, "device-revoke", request_id, json.dumps(result))
        conn.commit()
    return JSONResponse(status_code=200, content=result)


@app.post("/api/agent/v1/credentials-resend")
def hoppy_agent_credentials_resend(request: Request, payload: HoppyAccountRequest):
    # Tier 1: resend the account's enrollment credentials to the EMAIL ALREADY
    # ON FILE. The target address is read ONLY from the users record; any
    # address a caller puts in the body is ignored. Accepting a body-supplied
    # address would be an account take-over, so this is enforced, not assumed.
    acc = _hoppy_resolve_account(payload)
    if not acc:
        raise HTTPException(status_code=400, detail="Missing account_number/accountnumber")
    request_id = _hoppy_request_id(payload)
    require_hoppy_agent_auth(request, "credentials-resend", acc)
    with get_db() as conn:
        ensure_schema(conn)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-resend-ip", request_origin_bucket_value(request)), HOPPY_AGENT_IP_RATE_LIMIT_PER_MINUTE, 60)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-resend-account", acc), HOPPY_AGENT_ACCOUNT_RATE_LIMIT_PER_HOUR, 3600)
        user = conn.execute(
            "SELECT account_number, subscriber_name, email FROM users WHERE account_number = ?", (acc,)
        ).fetchone()
        if user is None:
            raise HTTPException(status_code=404, detail="Account not found")
        target_email = (user["email"] or "").strip()
        if not target_email:
            conn.rollback()
            raise HTTPException(status_code=409, detail="No email address on file for this account")
        idem = hoppy_agent_idempotency_key(acc, "credentials-resend", request_id)
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            conn.commit()
            return JSONResponse(status_code=200, content=json.loads(replayed))
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            conn.commit()
            return JSONResponse(status_code=200, content=json.loads(replayed))
        _hoppy_record_audit(conn, request, "credentials-resend", acc, idem, "queued", f"target={_hoppy_masked_email(target_email)}")
        conn.execute("""
            INSERT INTO hoppy_agent_mail_outbox (idempotency_key, kind, account_ref, target_email, status, created_at)
            VALUES (?, 'credentials_resend', ?, ?, 'pending', ?)
        """, (idem, _hoppy_account_ref(acc), target_email, utcnow().isoformat()))
        result = {
            "ok": True,
            "action": "credentials-resend",
            "account_ref": _hoppy_account_ref(acc),
            "delivery_to_on_file_email": True,
            "target_email": _hoppy_masked_email(target_email),
        }
        _hoppy_store_idempotency(conn, idem, acc, "credentials-resend", request_id, json.dumps(result))
        conn.commit()
    return JSONResponse(status_code=200, content=result)


def _hoppy_account_receipt(conn: sqlite3.Connection, account: str) -> dict:
    user = conn.execute(
        "SELECT account_number, subscriber_name, email, status, expiration_date, renewal_source "
        "FROM users WHERE account_number = ?",
        (account,),
    ).fetchone()
    if user is None:
        raise HTTPException(status_code=404, detail="Account not found")
    email = (user["email"] or "").strip()
    if not email:
        raise HTTPException(status_code=409, detail="No email address on file for this account")
    ordered = conn.execute(
        "SELECT hub_order_id, provider, plan_key, expected_amount, expected_currency, status, created_at, settled_at "
        "FROM payment_orders WHERE buyer_email = ? AND status = 'settled' ORDER BY COALESCE(settled_at, created_at) DESC LIMIT 1",
        (email,),
    ).fetchone()
    return {
        "account_number": user["account_number"],
        "subscriber_name": user["subscriber_name"] or "Wins VPN User",
        "email": email,
        "status": user["status"],
        "expiration_date": str(user["expiration_date"] or ""),
        "renewal_source": user["renewal_source"] or "",
        "last_settled_order": dict(ordered) if ordered else None,
    }


def send_hoppy_receipt_email(record: dict) -> bool:
    to_email = record.get("email") or ""
    if not SMTP_USER or not SMTP_PASS or not to_email or not re.match(r"[^@]+@[^@]+\.[^@]+", to_email):
        return False
    name = html.escape(record.get("subscriber_name") or "Wins VPN User")
    account = html.escape(record.get("account_number") or "")
    status = html.escape(record.get("status") or "")
    exp = html.escape(record.get("expiration_date") or "")
    order = record.get("last_settled_order")
    msg = MIMEMultipart("alternative")
    msg["Subject"] = "Wins VPN Receipt"
    msg["From"] = EMAIL_SENDER
    msg["To"] = to_email
    order_html = ""
    order_plain = ""
    if order:
        amt = html.escape(f"{order.get('expected_amount') or ''} {order.get('expected_currency') or ''}".strip())
        order_id = html.escape(order.get("hub_order_id") or "")
        settled = html.escape(order.get("settled_at") or order.get("created_at") or "")
        order_html = f"<p>Last settled order <strong>{order_id}</strong> for <strong>{amt}</strong> on {settled}.</p>"
        order_plain = f"Last settled order {order_id} for {amt} on {settled}.\n"
    html_body = f"""
    <html><body style="font-family:Arial,sans-serif;background:#0b0b0f;color:#fff;padding:20px">
    <div style="max-width:600px;margin:auto;background:#121216;padding:30px;border-radius:10px;border:1px solid #1e1e24">
      <h2 style="color:#448aff">Wins VPN Receipt</h2>
      <p>Hello {name},</p>
      <p>Account number: <strong>{account}</strong><br>Status: {status}<br>Expiration: {exp}</p>
      {order_html}
      <p>This is a reissued receipt for your account. Keep it for your records.</p>
      <p style="font-size:12px;color:#888">Win's VPN Inc. operates the service. Win Empire LLC designs and builds the software and infrastructure.</p>
    </div></body></html>
    """
    plain = f"""Wins VPN Receipt

Hello {name},

Account number: {account}
Status: {status}
Expiration: {exp}
{order_plain}
This is a reissued receipt for your account. Keep it for your records.

Win's VPN Inc. operates the service. Win Empire LLC designs and builds the software and infrastructure.
"""
    msg.attach(MIMEText(plain, "plain"))
    msg.attach(MIMEText(html_body, "html"))
    return smtp_dispatch_message(msg, to_email)


