@app.post("/api/agent/v1/preferred-server")
def hoppy_agent_preferred_server(request: Request, payload: HoppyPreferredServerRequest):
    # Tier 1: change the preferred server or region for the authenticated
    # account. region/server may be 'auto' or an existing node slug; a request
    # for a server that does not exist is refused rather than stored.
    acc = _hoppy_resolve_account(payload)
    region = (payload.region or "").strip().lower()
    server = (payload.server or "").strip().lower()
    if not acc:
        raise HTTPException(status_code=400, detail="Missing account_number/accountnumber")
    if not region and not server:
        raise HTTPException(status_code=400, detail="Missing region/server")
    request_id = _hoppy_request_id(payload)
    require_hoppy_agent_auth(request, "preferred-server", acc)
    with get_db() as conn:
        ensure_schema(conn)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-pref-ip", request_origin_bucket_value(request)), HOPPY_AGENT_IP_RATE_LIMIT_PER_MINUTE, 60)
        check_rate_limit(conn, rate_limit_bucket("hoppy-agent-pref-account", acc), HOPPY_AGENT_ACCOUNT_RATE_LIMIT_PER_HOUR, 3600)
        user = conn.execute("SELECT account_number FROM users WHERE account_number = ?", (acc,)).fetchone()
        if user is None:
            raise HTTPException(status_code=404, detail="Account not found")
        target_region = (region or server or "").strip().lower()
        if target_region not in {"", "auto"}:
            node = conn.execute(
                "SELECT slug FROM nodes WHERE lower(slug) = lower(?) AND retired_at IS NULL",
                (target_region,),
            ).fetchone()
            if node is None:
                raise HTTPException(status_code=404, detail="Unknown server or region")
        idem = hoppy_agent_idempotency_key(acc, "preferred-server", request_id)
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            conn.commit()
            return JSONResponse(status_code=200, content=json.loads(replayed))
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        replayed = _hoppy_try_replay(conn, idem)
        if replayed is not None:
            conn.commit()
            return JSONResponse(status_code=200, content=json.loads(replayed))
        new_region = "" if target_region in {"", "auto"} else target_region
        conn.execute(
            "UPDATE users SET preferred_region = ?, preferred_server = ? WHERE account_number = ?",
            (new_region, new_region, acc),
        )
        _hoppy_record_audit(conn, request, "preferred-server", acc, idem, "completed", f"region={new_region or 'auto'}")
        result = {
            "ok": True,
            "action": "preferred-server",
            "account_ref": _hoppy_account_ref(acc),
            "preferred_region": new_region or "auto",
        }
        _hoppy_store_idempotency(conn, idem, acc, "preferred-server", request_id, json.dumps(result))
        conn.commit()
    return JSONResponse(status_code=200, content=result)


def claim_hoppy_agent_mail_batch(conn: sqlite3.Connection, limit: int, lease_token: str) -> list:
    now_iso = utcnow().isoformat()
    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    # K3-06: a pending row that has used every attempt is terminal. Close it and
    # purge its sealed key copy (this also catches rows stuck before this build).
    conn.execute(
        "UPDATE hoppy_agent_mail_outbox SET status='cancelled', sealed_secret=NULL, "
        "completed_at=?, lease_until=NULL WHERE status='pending' AND attempts>=? "
        "AND (lease_until IS NULL OR lease_until<?)",
        (now_iso, HOPPY_AGENT_OUTBOX_MAX_ATTEMPTS, now_iso),
    )
    rows = conn.execute("""
        SELECT * FROM hoppy_agent_mail_outbox
        WHERE status IN ('pending', 'delivered')
          AND (status = 'delivered' OR attempts < ?)
          AND (lease_until IS NULL OR lease_until < ?)
        ORDER BY id ASC
        LIMIT ?
    """, (HOPPY_AGENT_OUTBOX_MAX_ATTEMPTS, now_iso, limit)).fetchall()
    for row in rows:
        conn.execute(
            "UPDATE hoppy_agent_mail_outbox SET lease_until = ?, attempts = attempts + 1 WHERE id = ? AND status IN ('pending', 'delivered')",
            (lease_token, row["id"]),
        )
    conn.commit()
    return [dict(row) for row in rows]


def release_hoppy_agent_mail_lease(conn: sqlite3.Connection, item_id: int, lease_token: str, error: str = "", *, undo_attempt: bool = False) -> None:
    released = conn.execute(
        "UPDATE hoppy_agent_mail_outbox SET lease_until = NULL, last_error = ?, "
        "attempts = CASE WHEN ? THEN MAX(attempts - 1, 0) ELSE attempts END "
        "WHERE id = ? AND lease_until = ?",
        ((error or "")[:200] or None, int(undo_attempt), item_id, lease_token),
    ).rowcount
    if released and not undo_attempt:
        # K3-06: the attempt that just failed was the last one allowed. The row
        # is terminal now, so it is closed and its sealed key copy purged here.
        conn.execute(
            "UPDATE hoppy_agent_mail_outbox SET status='cancelled', sealed_secret=NULL, completed_at=? "
            "WHERE id=? AND status='pending' AND attempts>=?",
            (utcnow().isoformat(), item_id, HOPPY_AGENT_OUTBOX_MAX_ATTEMPTS),
        )
    conn.commit()


def _hoppy_account_ref_map(conn: sqlite3.Connection) -> dict:
    # account_ref is a one-way hash, so resolving one outbox item means
    # hashing every account number. Build the map once per drain instead of
    # once per item (the drain previously scanned the whole users table up to
    # three times per item).
    return {
        _hoppy_account_ref(row["account_number"]): row
        for row in conn.execute(
            "SELECT account_number, email, subscriber_name FROM users"
        ).fetchall()
    }


def _hoppy_credentials_secret(conn: sqlite3.Connection, item: dict, account_refs: Optional[dict] = None) -> tuple:
    # Rotate onto the account the item references, resolving the hashed ref to
    # a live account (the account itself is not stored on the outbox row).
    # Returns (keys, account_number, subscriber_name). The FIRST attempt mints
    # the account's new key set, which replaces its earlier keys, and seals it
    # on the outbox row in the same transaction. Every later attempt of the same
    # row re-sends that sealed set: an ambiguous SMTP failure that may already
    # have delivered it must not invalidate it on the retry (K3-03). If any key
    # of the sealed set has since been used, expired or replaced, the mail is
    # cancelled: the customer already holds working keys or a newer set.
    cand = (account_refs or _hoppy_account_ref_map(conn)).get(item["account_ref"])
    conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    outbox = conn.execute(
        "SELECT sealed_secret FROM hoppy_agent_mail_outbox "
        "WHERE id=? AND idempotency_key=? AND status='pending'",
        (item["id"], item["idempotency_key"]),
    ).fetchone()
    if outbox is None:
        conn.commit()
        return None, None, None
    # K3-05: re-read the account under the writer lock, on the first attempt and
    # on a sealed retry alike. It must still exist, be active and unexpired, and
    # still carry the address the mail was queued for. Otherwise nothing is
    # reused or minted and the sealed copy is purged.
    user = conn.execute(
        "SELECT account_number, email, subscriber_name, status, expiration_date "
        "FROM users WHERE account_number=?", (cand["account_number"],),
    ).fetchone() if cand is not None else None
    if not account_may_receive_keys(user, item.get("target_email") or (cand["email"] if cand else "")):
        conn.execute(
            "UPDATE hoppy_agent_mail_outbox SET status='cancelled', sealed_secret=NULL, "
            "completed_at=?, lease_until=NULL WHERE id=? AND status='pending'",
            (utcnow().isoformat(), item["id"]),
        )
        conn.commit()
        return None, None, None
    cand = user
    delivery_id = f"hoppy:{item['idempotency_key']}"
    if outbox["sealed_secret"]:
        secret = activation_key_list(open_activation_delivery(
            outbox["sealed_secret"], delivery_id, cand["account_number"]
        ))
    else:
        secret = issue_activation_secrets(conn, cand["account_number"])
        conn.execute(
            "UPDATE hoppy_agent_mail_outbox SET sealed_secret=? WHERE id=?",
            (seal_activation_delivery(ACTIVATION_KEY_SEPARATOR.join(secret),
                                      delivery_id, cand["account_number"]), item["id"]),
        )
    if not secret or any(state != "live" for state in activation_bundle_states(conn, cand["account_number"], secret)):
        conn.execute(
            "UPDATE hoppy_agent_mail_outbox SET status='cancelled', sealed_secret=NULL, "
            "completed_at=?, lease_until=NULL WHERE id=? AND status='pending'",
            (utcnow().isoformat(), item["id"]),
        )
        conn.commit()
        return None, None, None
    conn.commit()
    # R24 Argon 1: the minted hashes are new state behind the pre-send barrier;
    # replicate them before the keys leave in an email, as
    # _redemption_outbox_setup_key does (state commit -> barrier -> side effect).
    run_durability_barrier()
    return secret, cand["account_number"], cand["subscriber_name"] or "Wins VPN User"


def _hoppy_mail_resolve_account(conn: sqlite3.Connection, item: dict, account_refs: Optional[dict] = None) -> sqlite3.Row:
    return (account_refs or _hoppy_account_ref_map(conn)).get(item["account_ref"])


def drain_hoppy_agent_mail_outbox(limit: int = HOPPY_AGENT_OUTBOX_BATCH_LIMIT) -> dict:
    # Mirrors drain_redemption_outbox: commit -> barrier -> send -> completion
    # marker -> barrier -> lease release. A row whose post-delivery barrier
    # fails stays 'delivered' with barrier_confirmed_at NULL so another worker
    # can finish the durability half without re-sending.
    lease_token = (utcnow() + timedelta(seconds=HOPPY_AGENT_OUTBOX_LEASE_SECONDS)).isoformat()
    summary = {"claimed": 0, "delivered": 0, "confirmed": 0, "deferred": 0, "failed": 0, "errors": []}
    with get_db() as conn:
        ensure_schema(conn)
        batch = claim_hoppy_agent_mail_batch(conn, limit, lease_token)
    summary["claimed"] = len(batch)
    account_refs: dict = {}
    if batch:
        with get_db() as conn:
            account_refs = _hoppy_account_ref_map(conn)
    for item in batch:
        if str(item.get("status")) == "pending":
            try:
                run_durability_barrier()
            except DurabilityBarrierError as exc:
                summary["deferred"] += 1
                summary["errors"].append({"id": item["id"], "error": f"pre_barrier:{exc.reason}"})
                with get_db() as conn:
                    release_hoppy_agent_mail_lease(conn, item["id"], lease_token, f"pre_barrier:{exc.reason}", undo_attempt=True)
                continue
            try:
                with get_db() as conn:
                    account_row = _hoppy_mail_resolve_account(conn, item, account_refs)
                    target_email = item.get("target_email") or (account_row["email"] if account_row else "")
                sent = False
                if item.get("kind") == "credentials_resend":
                    # Minting replaces the setup keys on file, once per outbox row
                    # (retries re-send the sealed set). Skip it when
                    # send_account_email would refuse without trying (no SMTP
                    # credentials, unusable address), or the first attempt of
                    # this row would invalidate the customer's current keys for nothing.
                    if (
                        SMTP_USER and SMTP_PASS and target_email
                        and re.match(r"[^@]+@[^@]+\.[^@]+", target_email)
                    ):
                        with get_db() as conn:
                            secret, acc, sub_name = _hoppy_credentials_secret(conn, item, account_refs)
                        if acc:
                            sent = send_account_email(target_email, sub_name, acc, "Resend Credentials", secret)
                elif item.get("kind") == "receipt_reissue":
                    record = None
                    with get_db() as conn:
                        account_row = _hoppy_mail_resolve_account(conn, item, account_refs)
                        if account_row is not None:
                            record = _hoppy_account_receipt(conn, account_row["account_number"])
                    if record is not None:
                        sent = send_hoppy_receipt_email(record)
                if not sent:
                    summary["failed"] += 1
                    summary["errors"].append({"id": item["id"], "error": "smtp_unavailable_or_send_failed"})
                    with get_db() as conn:
                        release_hoppy_agent_mail_lease(conn, item["id"], lease_token, "smtp_unavailable_or_send_failed")
                    continue
                with get_db() as conn:
                    conn.commit()
                    conn.execute("BEGIN IMMEDIATE")
                    conn.execute(
                        "UPDATE hoppy_agent_mail_outbox SET status='delivered', delivered_at=?, sealed_secret=NULL WHERE id=? AND status='pending'",
                        (utcnow().isoformat(), item["id"]),
                    )
                    conn.commit()
                summary["delivered"] += 1
            except DurabilityBarrierError as exc:
                # The rotated key's barrier failed before any mail: like the
                # pre-send barrier, a replica outage defers without spending
                # an attempt.
                summary["deferred"] += 1
                summary["errors"].append({"id": item["id"], "error": f"pre_send_barrier:{exc.reason}"})
                with get_db() as conn:
                    release_hoppy_agent_mail_lease(conn, item["id"], lease_token, f"pre_send_barrier:{exc.reason}", undo_attempt=True)
                continue
            except Exception as exc:  # noqa: BLE001 - reported per item
                summary["failed"] += 1
                summary["errors"].append({"id": item["id"], "error": str(exc)[:200]})
                with get_db() as conn:
                    release_hoppy_agent_mail_lease(conn, item["id"], lease_token, str(exc)[:200])
                continue
        try:
            run_durability_barrier()
        except DurabilityBarrierError as exc:
            summary["deferred"] += 1
            summary["errors"].append({"id": item["id"], "error": f"post_barrier:{exc.reason}"})
            with get_db() as conn:
                release_hoppy_agent_mail_lease(conn, item["id"], lease_token, f"post_barrier:{exc.reason}")
            continue
        with get_db() as conn:
            conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            conn.execute(
                "UPDATE hoppy_agent_mail_outbox SET status='completed', barrier_confirmed_at=?, completed_at=?, lease_until=NULL "
                "WHERE id=? AND status='delivered'",
                (utcnow().isoformat(), utcnow().isoformat(), item["id"]),
            )
            conn.commit()
        summary["confirmed"] += 1
    return summary


@app.post("/admin/hoppy-agent/outbox/drain")
async def admin_drain_hoppy_agent_outbox(request: Request, x_admin_token: str = Header(...)):
    await asyncio.to_thread(require_admin_token, x_admin_token, request, "hoppy agent outbox drain")
    return await asyncio.to_thread(drain_hoppy_agent_mail_outbox)


@app.get("/admin/hoppy-agent/outbox")
def admin_hoppy_agent_outbox_status(request: Request, x_admin_token: str = Header(...)):
    require_admin_token(x_admin_token, request, "hoppy agent outbox status")
    with get_db() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT status, COUNT(*) AS n FROM hoppy_agent_mail_outbox GROUP BY status"
        ).fetchall()
        audit_rows = conn.execute(
            "SELECT action, COUNT(*) AS n FROM hoppy_agent_audit GROUP BY action"
        ).fetchall()
        return {
            "counts": {str(r["status"]): int(r["n"]) for r in rows},
            "actions": {str(r["action"]): int(r["n"]) for r in audit_rows},
            "configured": hoppy_agent_enabled(),
        }
PYEOF
  set +C
  record_app_code_stamp
}

setup_python() {
  (
  require_root_owned_venv || exit 1
  log "Creating virtualenv and installing Python packages"
  python3 -I -m venv "${VENV_DIR}"
  require_root_owned_venv || exit 1
  # M-3: intentionally no separate, unpinned network upgrade of pip/wheel
  # themselves here. The pip bundled by python3-venv on the reviewed Ubuntu
  # 24.04 target (pip 24.0) already supports --require-hashes and
  # --only-binary=:all: fine (verified against this exact lock file); an
  # extra unhashed upgrade step would reopen the same dependency-
  # substitution gap --require-hashes below closes for every other package.
  #
  # Exact top-level + transitive pins, hash-pinned for `pip install
  # --require-hashes` (see server/control-plane-requirements.lock in the
  # source repo, generated via server/control-plane-requirements.in with
  # `pip-compile --generate-hashes`, and validated end-to-end with
  # --require-hashes --only-binary=:all: in a matching Ubuntu 24.04/py3.12/
  # amd64 container). This is a self-contained ONE-TOUCH script, so the lock
  # content is written out locally rather than assumed to exist on the box.
  # Regenerate it from the source repo's .lock file -- do not hand-edit.
  # Root installs only from input outside the app's writable directory.
  local requirements_lock
  requirements_lock="$(mktemp /root/.wins-control-plane-requirements.XXXXXX)" || exit 1
  trap 'rm -f -- "${requirements_lock}"' EXIT
  chmod 0600 "${requirements_lock}" || exit 1
  cat > "${requirements_lock}" <<'REQLOCKEOF'
