  "${VENV_DIR}/bin/python" -I -m pip install --require-hashes --only-binary=:all: -r "${requirements_lock}" >/dev/null
  rm -f -- "${APP_DIR}/control-plane-requirements.lock"
  /usr/bin/python3 -I -S -c 'import sys; compile(open(sys.argv[1], "rb").read(), sys.argv[1], "exec")' "${APP_DIR}/main.py"
  )
}

write_sqlite_bootstrap() {
  # CP-5: the live hub, the prober and Litestream keep writing while this
  # runs. Every connection waits up to 30 s for a lock instead of failing on
  # the first busy one (the sqlite3 CLI's default timeout is 0).
  mkdir -p "${APP_DIR}"
  # ${APP_DIR} is writable by the hub app, and sqlite3 opens (or creates) the
  # database through a link, so a planted one is refused, not followed.
  if [[ -L "${DB_PATH}" ]]; then
    err "${DB_PATH} is a symlink; refusing to open the hub database through it."
    return 1
  fi
  sqlite3 -cmd '.timeout 30000' "${DB_PATH}" <<'EOF'
CREATE TABLE IF NOT EXISTS users (
  account_number TEXT PRIMARY KEY,
  email TEXT,
  subscriber_name TEXT DEFAULT 'Wins VPN User',
  status TEXT DEFAULT 'active',
  expiration_date TEXT,
  hardware_hash TEXT,
  paypal_subscription_id TEXT,
  paypal_plan_id TEXT,
  paypal_payer_id TEXT,
  paypal_status TEXT,
  paypal_purchase_reference TEXT,
  last_paypal_sync TEXT,
  renewal_source TEXT,
  referral_code TEXT UNIQUE,
  referred_by_account_number TEXT,
  referral_bonus_days INTEGER DEFAULT 0,
  referral_bonus_applied_at TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS devices (
  device_id TEXT PRIMARY KEY,
  account_number TEXT,
  device_model TEXT DEFAULT 'Unknown Android',
  hardware_hash TEXT,
  source_ip_bucket TEXT,
  vpn_internal_ip TEXT UNIQUE,
  client_private_key TEXT,
  client_public_key TEXT,
  preshared_key TEXT,
  last_seen TEXT,
  location_slug TEXT,
  updated_at TEXT,
  device_auth_token_hash TEXT,
  activation_key_slot INTEGER,
  activation_key_hash TEXT,
  activation_key_bearer_hash TEXT
);
CREATE TABLE IF NOT EXISTS nodes (
  slug TEXT PRIMARY KEY,
  name TEXT,
  flag TEXT,
  endpoint TEXT,
  tunnel_gateway_ipv4 TEXT,
  stealth_endpoint TEXT,
  public_key TEXT,
  preshared_key TEXT,
  status TEXT DEFAULT 'online',
  last_heartbeat TEXT,
  obfuscation_json TEXT,
  ssh_host TEXT,
  wg_port INTEGER DEFAULT 9110,
  xray_uuid TEXT,
  xray_path TEXT DEFAULT '/wins-stealth-tunnel',
  xray_security TEXT DEFAULT 'none',
  xray_sni TEXT,
  stealth_public_port INTEGER DEFAULT 80,
  xray_inbound_port INTEGER DEFAULT 10085,
  regional_aliases TEXT DEFAULT '[]',
  stealth_transports TEXT DEFAULT '[]',
  awg_rx_bytes INTEGER DEFAULT 0,
  awg_tx_bytes INTEGER DEFAULT 0,
  wan_rx_bytes INTEGER DEFAULT 0,
  wan_tx_bytes INTEGER DEFAULT 0,
  rx_mbps REAL DEFAULT 0,
  tx_mbps REAL DEFAULT 0,
  peer_count INTEGER DEFAULT 0,
  free_access_enabled INTEGER DEFAULT 0
);
CREATE TABLE IF NOT EXISTS core_servers (
  core_id TEXT PRIMARY KEY,
  name TEXT,
  region TEXT,
  management_host TEXT,
  management_user TEXT DEFAULT 'ubuntu',
  management_status TEXT DEFAULT 'unknown',
  management_checked_at TEXT,
  management_error TEXT,
  ingress_endpoint TEXT,
  tunnel_gateway_ipv4 TEXT,
  stealth_endpoint TEXT,
  ingress_public_key TEXT,
  exit_public_key TEXT,
  xray_uuid TEXT,
  xray_path TEXT DEFAULT '/wins-core-tunnel',
  xray_security TEXT DEFAULT 'none',
  stealth_transports TEXT DEFAULT '[]',
  regional_aliases TEXT DEFAULT '[]',
  direct_awg_enabled INTEGER NOT NULL DEFAULT 1,
  status TEXT DEFAULT 'online',
  runtime_ready INTEGER NOT NULL DEFAULT 0,
  promoted INTEGER NOT NULL DEFAULT 0,
  pending_promotion_id TEXT,
  pending_promotion_evidence_sha256 TEXT,
  pending_promotion_operator_source_hash TEXT,
  pending_promotion_requested_at TEXT,
  active_promotion_id TEXT,
  last_heartbeat TEXT,
  runtime_checked_at TEXT
);
CREATE TABLE IF NOT EXISTS double_vpn_assignments (
  device_id TEXT PRIMARY KEY,
  account_number TEXT,
  core_id TEXT,
  exit_slug TEXT,
  client_public_key TEXT,
  client_ip TEXT UNIQUE,
  preshared_key TEXT,
  status TEXT DEFAULT 'active',
  applied_revision TEXT,
  runtime_validated_at TEXT,
  assigned_at TEXT,
  updated_at TEXT,
  FOREIGN KEY(account_number) REFERENCES users(account_number),
  FOREIGN KEY(core_id) REFERENCES core_servers(core_id),
  FOREIGN KEY(exit_slug) REFERENCES nodes(slug)
);
CREATE TABLE IF NOT EXISTS core_exit_peers (
  core_id TEXT,
  exit_slug TEXT,
  core_exit_ip TEXT UNIQUE,
  table_id INTEGER,
  iface TEXT,
  updated_at TEXT,
  PRIMARY KEY(core_id, exit_slug),
  FOREIGN KEY(core_id) REFERENCES core_servers(core_id),
  FOREIGN KEY(exit_slug) REFERENCES nodes(slug)
);
CREATE TABLE IF NOT EXISTS system_settings (
  key TEXT PRIMARY KEY,
  value TEXT
);
CREATE TABLE IF NOT EXISTS paypal_events (
  event_id TEXT PRIMARY KEY,
  event_type TEXT,
  paypal_subscription_id TEXT,
  account_number TEXT,
  status TEXT,
  attempts INTEGER DEFAULT 0,
  last_error TEXT,
  received_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT
);
CREATE TABLE IF NOT EXISTS rate_limits (
  bucket TEXT PRIMARY KEY,
  count INTEGER DEFAULT 0,
  reset_at REAL
);
CREATE TABLE IF NOT EXISTS payment_clicks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  option_key TEXT,
  source TEXT,
  referral_code TEXT,
  referrer_account_number TEXT,
  source_ip_bucket TEXT,
  user_agent_hash TEXT,
  referer_hash TEXT,
  clicked_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS referral_rewards (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  referral_code TEXT,
  referrer_account_number TEXT,
  referred_account_number TEXT UNIQUE,
  purchase_reference TEXT,
  base_days INTEGER DEFAULT 0,
  bonus_days INTEGER DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS free_access_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  action TEXT,
  account_number TEXT,
  device_id_bucket TEXT,
  source_ip_bucket TEXT,
  client_public_key_fingerprint TEXT,
  platform TEXT,
  device_model TEXT,
  node_slug TEXT,
  stealth_mode INTEGER DEFAULT 0,
  user_agent_hash TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS legal_documents (
  version TEXT PRIMARY KEY,
  document_hash TEXT,
  title TEXT,
  body_text TEXT,
  effective_date TEXT,
  is_current INTEGER DEFAULT 1,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS legal_acceptances (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  acceptance_id TEXT UNIQUE,
  account_number TEXT,
  email TEXT,
  device_id_bucket TEXT,
  source_ip_bucket TEXT,
  user_agent_hash TEXT,
  platform TEXT,
  app_version TEXT,
  locale TEXT,
  acceptance_method TEXT,
  document_version TEXT,
  document_hash TEXT,
  accepted_terms INTEGER DEFAULT 0,
  accepted_hold_harmless INTEGER DEFAULT 0,
  accepted_limitation_liability INTEGER DEFAULT 0,
  accepted_electronic_records INTEGER DEFAULT 0,
  accepted_android_vpn_service_disclosure INTEGER DEFAULT 0,
  android_vpn_service_disclosure_version TEXT DEFAULT '',
  android_vpn_service_disclosure_accepted_at TEXT DEFAULT '',
  signature_hmac TEXT,
  accepted_at TEXT DEFAULT CURRENT_TIMESTAMP
);
EOF

  sqlite_add_column_if_missing() {
    local table="$1"
    local column="$2"
    local ddl="$3"
    local present
    # A failed inspection is an error, never "column absent".
    present="$(sqlite3 -cmd '.timeout 30000' "${DB_PATH}" "SELECT 1 FROM pragma_table_info('${table}') WHERE name='${column}' LIMIT 1;")" || {
      err "Could not read the ${table} schema in ${DB_PATH}; refusing to guess whether ${column} exists."
      return 1
    }
    if [[ "${present}" != "1" ]]; then
      sqlite3 -cmd '.timeout 30000' "${DB_PATH}" "ALTER TABLE ${table} ADD COLUMN ${column} ${ddl};"
    fi
  }

  sqlite_add_column_if_missing users paypal_subscription_id "TEXT"
  sqlite_add_column_if_missing users paypal_plan_id "TEXT"
  sqlite_add_column_if_missing users paypal_payer_id "TEXT"
  sqlite_add_column_if_missing users paypal_status "TEXT"
  sqlite_add_column_if_missing users paypal_purchase_reference "TEXT"
  sqlite_add_column_if_missing users last_paypal_sync "TEXT"
  sqlite_add_column_if_missing users renewal_source "TEXT"
  sqlite_add_column_if_missing users referral_code "TEXT"
  sqlite_add_column_if_missing users referred_by_account_number "TEXT"
  sqlite_add_column_if_missing users referral_bonus_days "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing users referral_bonus_applied_at "TEXT"

  sqlite_add_column_if_missing devices hardware_hash "TEXT"
  sqlite_add_column_if_missing devices source_ip_bucket "TEXT"
  sqlite_add_column_if_missing devices updated_at "TEXT"
  sqlite_add_column_if_missing devices device_auth_token_hash "TEXT"
  sqlite_add_column_if_missing devices activation_key_slot "INTEGER"
  sqlite_add_column_if_missing devices activation_key_hash "TEXT"
  sqlite_add_column_if_missing devices activation_key_bearer_hash "TEXT"

  sqlite_add_column_if_missing legal_acceptances accepted_android_vpn_service_disclosure "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing legal_acceptances android_vpn_service_disclosure_version "TEXT DEFAULT ''"
  sqlite_add_column_if_missing legal_acceptances android_vpn_service_disclosure_accepted_at "TEXT DEFAULT ''"

  sqlite_add_column_if_missing nodes ssh_host "TEXT"
  sqlite_add_column_if_missing nodes tunnel_gateway_ipv4 "TEXT"
  sqlite_add_column_if_missing nodes wg_port "INTEGER DEFAULT 9110"
  sqlite_add_column_if_missing nodes xray_uuid "TEXT"
  sqlite_add_column_if_missing nodes xray_path "TEXT DEFAULT '/wins-stealth-tunnel'"
  sqlite_add_column_if_missing nodes xray_security "TEXT DEFAULT 'none'"
  sqlite_add_column_if_missing nodes xray_sni "TEXT"
  sqlite_add_column_if_missing nodes stealth_public_port "INTEGER DEFAULT 80"
  sqlite_add_column_if_missing nodes xray_inbound_port "INTEGER DEFAULT 10085"
  sqlite_add_column_if_missing nodes regional_aliases "TEXT DEFAULT '[]'"
  sqlite_add_column_if_missing nodes stealth_transports "TEXT DEFAULT '[]'"
  sqlite_add_column_if_missing nodes awg_rx_bytes "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing nodes awg_tx_bytes "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing nodes wan_rx_bytes "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing nodes wan_tx_bytes "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing nodes rx_mbps "REAL DEFAULT 0"
  sqlite_add_column_if_missing nodes tx_mbps "REAL DEFAULT 0"
  sqlite_add_column_if_missing nodes peer_count "INTEGER DEFAULT 0"
  sqlite_add_column_if_missing nodes direct_awg_enabled "INTEGER DEFAULT 1"
  sqlite_add_column_if_missing nodes node_token_hash "TEXT"

  sqlite_add_column_if_missing core_servers stealth_endpoint "TEXT"
  sqlite_add_column_if_missing core_servers tunnel_gateway_ipv4 "TEXT"
  sqlite_add_column_if_missing core_servers xray_uuid "TEXT"
  sqlite_add_column_if_missing core_servers xray_path "TEXT DEFAULT '/wins-core-tunnel'"
  sqlite_add_column_if_missing core_servers xray_security "TEXT DEFAULT 'none'"
  sqlite_add_column_if_missing core_servers stealth_transports "TEXT DEFAULT '[]'"
  sqlite_add_column_if_missing core_servers regional_aliases "TEXT DEFAULT '[]'"
  sqlite_add_column_if_missing core_servers direct_awg_enabled "INTEGER NOT NULL DEFAULT 1"
  sqlite_add_column_if_missing core_servers promoted "INTEGER NOT NULL DEFAULT 0"
  sqlite_add_column_if_missing core_servers pending_promotion_id "TEXT"
  sqlite_add_column_if_missing core_servers pending_promotion_evidence_sha256 "TEXT"
  sqlite_add_column_if_missing core_servers pending_promotion_operator_source_hash "TEXT"
  sqlite_add_column_if_missing core_servers pending_promotion_requested_at "TEXT"
  sqlite_add_column_if_missing core_servers active_promotion_id "TEXT"
  sqlite_add_column_if_missing core_servers last_heartbeat "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments core_id "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments exit_slug "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments client_public_key "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments client_ip "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments preshared_key "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments status "TEXT DEFAULT 'active'"
  sqlite_add_column_if_missing double_vpn_assignments applied_revision "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments runtime_validated_at "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments assigned_at "TEXT"
  sqlite_add_column_if_missing double_vpn_assignments updated_at "TEXT"
  sqlite_add_column_if_missing core_exit_peers core_exit_ip "TEXT"
  sqlite_add_column_if_missing core_exit_peers table_id "INTEGER"
  sqlite_add_column_if_missing core_exit_peers iface "TEXT"
  sqlite_add_column_if_missing core_exit_peers updated_at "TEXT"

  sqlite_add_column_if_missing payment_clicks referral_code "TEXT"
  sqlite_add_column_if_missing payment_clicks referrer_account_number "TEXT"

  sqlite3 -cmd '.timeout 30000' "${DB_PATH}" <<'EOF'
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_referral_code ON users(referral_code) WHERE referral_code IS NOT NULL AND referral_code != '';
CREATE INDEX IF NOT EXISTS idx_users_referred_by ON users(referred_by_account_number);
CREATE INDEX IF NOT EXISTS idx_devices_account_number ON devices(account_number);
CREATE INDEX IF NOT EXISTS idx_devices_account_hardware ON devices(account_number, hardware_hash);
CREATE INDEX IF NOT EXISTS idx_devices_last_seen ON devices(account_number, last_seen);
CREATE INDEX IF NOT EXISTS idx_core_servers_status ON core_servers(status, last_heartbeat);
CREATE INDEX IF NOT EXISTS idx_double_vpn_assignments_core_exit ON double_vpn_assignments(core_id, exit_slug, status);
CREATE INDEX IF NOT EXISTS idx_double_vpn_assignments_account ON double_vpn_assignments(account_number);
CREATE INDEX IF NOT EXISTS idx_core_exit_peers_core ON core_exit_peers(core_id);
CREATE INDEX IF NOT EXISTS idx_users_paypal_subscription_id ON users(paypal_subscription_id);
CREATE INDEX IF NOT EXISTS idx_users_paypal_purchase_reference ON users(paypal_purchase_reference);
CREATE INDEX IF NOT EXISTS idx_paypal_events_subscription_id ON paypal_events(paypal_subscription_id);
CREATE INDEX IF NOT EXISTS idx_paypal_events_status ON paypal_events(status);
CREATE INDEX IF NOT EXISTS idx_payment_clicks_referral_code ON payment_clicks(referral_code);
CREATE INDEX IF NOT EXISTS idx_referral_rewards_referrer ON referral_rewards(referrer_account_number);
CREATE UNIQUE INDEX IF NOT EXISTS idx_referral_rewards_purchase_reference ON referral_rewards(purchase_reference) WHERE purchase_reference IS NOT NULL AND purchase_reference != '';
CREATE INDEX IF NOT EXISTS idx_free_access_events_created_at ON free_access_events(created_at);
CREATE INDEX IF NOT EXISTS idx_free_access_events_device ON free_access_events(device_id_bucket);
CREATE INDEX IF NOT EXISTS idx_free_access_events_source ON free_access_events(source_ip_bucket);
CREATE INDEX IF NOT EXISTS idx_legal_acceptances_account ON legal_acceptances(account_number);
CREATE INDEX IF NOT EXISTS idx_legal_acceptances_device ON legal_acceptances(device_id_bucket);
CREATE INDEX IF NOT EXISTS idx_legal_acceptances_document ON legal_acceptances(document_version, document_hash);
CREATE UNIQUE INDEX IF NOT EXISTS idx_legal_acceptances_unique_current ON legal_acceptances(account_number, device_id_bucket, document_version, document_hash);
INSERT OR IGNORE INTO system_settings (key, value) VALUES ('global_announcement', 'Welcome to Win''s VPN! Thank you for helping yourself by using our services!!');
INSERT OR IGNORE INTO system_settings (key, value) VALUES ('maintenance_mode', 'false');
INSERT OR IGNORE INTO system_settings (key, value) VALUES ('double_vpn_free_access_enabled', 'false');
EOF
  # The check above ran before sqlite3; the hub app can rename the database
  # and plant a link at its name while that run holds the old file, and
  # chmod follows a link. Check again at the chmod.
  if [[ -L "${DB_PATH}" || ! -f "${DB_PATH}" ]]; then
    err "${DB_PATH} is no longer a regular file after the schema bootstrap; refusing to change the mode of what is at that name."
    return 1
  fi
  chmod 600 "${DB_PATH}"
  # chmod follows a link, and the hub app can plant one at either sidecar
  # name in ${APP_DIR}: change the mode of a regular file only.
  local sqlite_sidecar
  for sqlite_sidecar in "${DB_PATH}-wal" "${DB_PATH}-shm"; do
    [[ -f "${sqlite_sidecar}" && ! -L "${sqlite_sidecar}" ]] || continue
    chmod 600 "${sqlite_sidecar}"
  done
}

# One-time cleanup for the retired hub-side announcement signer (Fable 5.1
# ruling 2026-09-29, IA-CP-06). Removes the LoadCredential drop-in and the
# /etc/winn/announce key home. A key file found there was on a seizable disk
# and must be treated as rotated out, so it is shredded and the event logged;
# sign with an offline successor (a2) from then on. Idempotent: a host that
# never had either (every fresh install) is a no-op. Paths overridable for
# tests only.
#
# Every refusal happens BEFORE anything is changed:
#   * another drop-in that mentions the announce key (it would fail the hub
#     unit at its next start once the key home is gone), or one grep cannot read;
#   * a key home that is a symlink, or that sits under a symlinked parent
#     (its real path differs), so nothing outside the named path is touched;
#   * a key home path that exists but is not a directory (a regular file
#     there may itself be the retired key);
#   * a key home whose listing fails (find missing, or an I/O or permission
#     error): the listing is captured, and its status checked, before any
#     change, so a failed listing never reads as an empty home;
#   * any entry in the key home that is not a regular file (a subdirectory,
#     symlink, FIFO, socket or device), or whose name holds a newline or
#     another control character: it may hold or point at key material that
#     this function would otherwise leave unshredded after already changing
#     things.
# The removal loop works on that same captured listing. An entry that stopped
# being a regular file after the pre-scan (only a concurrent change can do
# that) is refused loudly, never removed with a tolerant rm.
# A regular file with more than one hard link is UNLINKED, never shredded:
# shredding would overwrite the same inode where it is reachable outside the
# key home. Its bytes then survive elsewhere, which the warning says. Both
# link-count queries must succeed and agree: unlink only when `-links +1`
# names the file and `-links 1` does not, shred only when `-links 1` names it
# and `-links +1` does not. A failed, empty or contradictory answer refuses
# the file (neither shred nor unlink).
# A refusal inside the removal loop still prints the SECURITY/EXPOSED warning
# for whatever that run already removed.
retire_hub_announce_signing_home() {
  local announce_dir="${CONTROL_ANNOUNCE_DIR:-/etc/winn/announce}"
  local dropin="${CONTROL_ANNOUNCE_DROPIN:-/etc/systemd/system/$(basename "${SERVICE_FILE}").d/announce-signing.conf}"
  local entry other rc real_dir listing="" many one failed=0 shredded=0 unshredded=0 linked=0
  for other in "$(dirname "${dropin}")"/*.conf; do
    [[ -e "${other}" || -L "${other}" ]] || continue
    [[ "${other}" == "${dropin}" ]] && continue
    rc=0
    grep -qi 'announce' -- "${other}" 2>/dev/null || rc=$?
    if (( rc != 1 )); then
      err "${other} references the retired announcement signing key (or cannot be read). Remove that line by hand (systemctl cat wins-hub.service shows it); nothing was changed."
      return 1
    fi
  done
  if [[ -L "${announce_dir}" ]]; then
    err "${announce_dir} is a symlink; refusing to follow it. Remove it by hand after checking where it points; nothing was changed."
    return 1
  fi
  if [[ -e "${announce_dir}" && ! -d "${announce_dir}" ]]; then
    err "${announce_dir} exists but is not a directory; it may itself be the retired announcement signing key. Inspect it, shred or remove it by hand, then re-run; nothing was changed."
    return 1
  fi
  if [[ -d "${announce_dir}" ]]; then
    real_dir="$(cd -P -- "${announce_dir}" 2>/dev/null && pwd -P)" || real_dir=""
    if [[ -z "${real_dir}" || "${real_dir}" != "${announce_dir}" ]]; then
      err "${announce_dir} resolves to ${real_dir:-an unreadable path} through a symlinked parent; refusing. Nothing was changed."
      return 1
    fi
    # NUL-terminated names become lines; a newline inside a name becomes \001
    # and is refused below, so no name can split into another path.
    listing="$(set -o pipefail; find "${announce_dir}" -mindepth 1 -maxdepth 1 -print0 | tr '\n\0' '\001\n')" || {
      err "Could not list the retired announcement key home ${announce_dir} (find failed or is not installed); nothing was changed."
      return 1
    }
    while IFS= read -r entry; do
      [[ -n "${entry}" ]] || continue
      if [[ "${entry}" == *[[:cntrl:]]* ]]; then
        err "An entry in the retired announcement key home ${announce_dir} has a newline or another control character in its name. Inspect and remove it by hand, then re-run; nothing was changed."
        return 1
      fi
      if [[ -L "${entry}" || ! -f "${entry}" ]]; then
        err "${entry} in the retired announcement key home is not a regular file (a subdirectory, symlink or special file may hold or point at key material). Inspect and remove it by hand, then re-run; nothing was changed."
        return 1
      fi
    done <<< "${listing}"
  fi
  if [[ -e "${dropin}" || -L "${dropin}" ]]; then
    rm -f -- "${dropin}" || {
      err "Could not remove the retired announcement LoadCredential drop-in ${dropin}."
      return 1
    }
    warn "Removed the retired announcement LoadCredential drop-in ${dropin}; announcements are now signed offline."
  fi
  if [[ -d "${announce_dir}" ]]; then
    while IFS= read -r entry; do
      [[ -n "${entry}" ]] || continue
      if [[ -f "${entry}" && ! -L "${entry}" ]]; then
        many="" one=""
        if ! many="$(find "${entry}" -maxdepth 0 -links +1 -print 2>/dev/null)" \
            || ! one="$(find "${entry}" -maxdepth 0 -links 1 -print 2>/dev/null)" \
            || [[ "${many}" == "${entry}" && "${one}" == "${entry}" ]] \
            || [[ "${many}" != "${entry}" && "${one}" != "${entry}" ]]; then
          err "Could not confirm the hard-link count of ${entry} (a failed, empty or contradictory answer); it was neither shredded nor unlinked (an inode linked elsewhere would be overwritten). Inspect and remove it by hand, then re-run."
          failed=1
          break
        fi
        if [[ "${many}" == "${entry}" ]]; then
          rm -f -- "${entry}" || {
            err "Could not unlink ${entry} from the retired announcement key home."
            failed=1
            break
          }
          linked=$((linked + 1))
        elif shred -u -z -- "${entry}" 2>/dev/null; then
          shredded=$((shredded + 1))
        elif rm -f -- "${entry}"; then
          unshredded=$((unshredded + 1))
        else
          err "Could not remove ${entry} from the retired announcement key home."
          failed=1
          break
        fi
      elif [[ -e "${entry}" || -L "${entry}" ]]; then
        err "${entry} in the retired announcement key home stopped being a regular file after the pre-scan (a concurrent change). Inspect and remove it by hand, then re-run."
        failed=1
        break
      fi
    done <<< "${listing}"
    if (( shredded + unshredded + linked )); then
      warn "SECURITY: ${shredded} file(s) shredded, ${unshredded} removed WITHOUT shredding (shred unavailable or failed), ${linked} hard-linked file(s) unlinked but NOT shredded (their bytes remain wherever the other link points) in the retired announcement key home ${announce_dir}. Treat announcement key a1 as EXPOSED: sign with the offline successor a2 and rotate the client ring."
    fi
    (( ! failed )) || return 1
    rmdir -- "${announce_dir}" 2>/dev/null || {
      err "Could not remove the retired announcement key home ${announce_dir} (not empty?)."
      return 1
    }
    log "Removed the retired announcement key home ${announce_dir}."
  fi
  return 0
}

# H0 (D2): wins-hub.service sees an empty, read-only /run and gets back only
# the runtime directories below, bound read-only. A directory bound into the
# hub must already exist when the hub starts, or the bind is skipped until the
# next hub restart, so systemd-tmpfiles creates them at boot, before any
# service. The helper and Litestream recreate their sockets inside them, which
# the hub sees through the directory bind. H1: the descriptor signer's socket
# directory is created for wins-desc-signer, group root, so the hub (uid 0,
# no capability) reaches the socket only through its group bits.
write_hub_runtime_dirs() {
  cat > /etc/tmpfiles.d/wins-hub-runtime.conf <<'EOF'
# Runtime directories wins-hub.service binds into its private /run (H0, D2).
d /run/litestream 0755 root root -
d /run/wins-hub-spa-window 0700 root root -
d /run/wins-descriptor-signer 0750 wins-desc-signer root -
EOF
  chmod 0644 /etc/tmpfiles.d/wins-hub-runtime.conf
  systemd-tmpfiles --create /etc/tmpfiles.d/wins-hub-runtime.conf
}

# H0 (D1, D4, D5): the legacy SPA window's firewall rule and its expiry timer
# moved out of the hub app into this root helper, the one process that holds
# CAP_NET_ADMIN for it. It runs only root-owned code under the system
# interpreter in isolated mode, and its socket has one verb.
prepare_wins_xtables_lock() {
  command -v systemd-tmpfiles >/dev/null 2>&1 || {
    err "systemd-tmpfiles is required to prepare the xtables lock."
    return 1
  }
  install -d -m 0755 -o root -g root /etc/tmpfiles.d || return 1
  cat > /etc/tmpfiles.d/wins-xtables-lock.conf <<'EOF'
f /run/xtables.lock 0600 root root -
EOF
  chmod 0644 /etc/tmpfiles.d/wins-xtables-lock.conf || return 1
  systemd-tmpfiles --create /etc/tmpfiles.d/wins-xtables-lock.conf || return 1
  [[ -f /run/xtables.lock && ! -L /run/xtables.lock ]] || return 1
  [[ "$(stat -c '%u:%g:%a' /run/xtables.lock)" == "0:0:600" ]] || return 1
}

write_hub_spa_window_helper() {
  prepare_wins_xtables_lock || return 1
  install -d -m 0755 -o root -g root /usr/local/lib
  cat > /usr/local/lib/wins_hub_spa_window.py <<'SPAWINDOWEOF'
#!/usr/bin/env python3
"""wins-hub-spa-window: the one-verb SPA window helper (H0, D1 and D4).

The hub app holds no capability and cannot reach the service manager. This
helper is the only process that opens a legacy SPA API window. Its socket takes
one request line per connection, "open <IPv4>", only from wins-hub.service, and
answers the line "ok" or "refused". The rule text, the unique lease comment and
the systemd-owned cleanup timer are fixed here; the caller supplies nothing but
the validated source address.
"""
import collections
import ipaddress
import os
import secrets
import shutil
import socket
import struct
import subprocess
import sys
import time

SOCKET_PATH = "/run/wins-hub-spa-window/sock"
HUB_CGROUP_SUFFIX = "/wins-hub.service"
CHAIN = "WINVPN-HUB-INPUT"
WINDOW_SECONDS = 20
MAX_OPEN_WINDOWS = 32
REQUEST_MAX_BYTES = 64


def log(message):
    print(f"wins-hub-spa-window: {message}", flush=True)


def peer_is_hub(conn):
    raw = conn.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, struct.calcsize("3i"))
    pid, uid, _gid = struct.unpack("3i", raw)
    if uid != 0 or pid <= 0:
        return False
    try:
        with open(f"/proc/{pid}/cgroup", "r", encoding="ascii") as handle:
            lines = handle.read().splitlines()
    except (OSError, UnicodeDecodeError):
        return False
    return any(line.startswith("0::") and line.endswith(HUB_CGROUP_SUFFIX) for line in lines)


def open_window(source):
    """Arm the systemd-owned cleanup, then insert the window rule."""
    iptables = shutil.which("iptables")
    systemd_run = shutil.which("systemd-run")
    if not iptables or not systemd_run:
        raise RuntimeError("SPA firewall tools unavailable")
    lease = "winsvpn-spa-" + secrets.token_hex(16)
    rule = ["-p", "tcp", "-s", source, "--dport", "8000",
            "-m", "comment", "--comment", lease, "-j", "ACCEPT"]
    delete_rule = [iptables, "-w", "5", "-D", CHAIN, *rule]
    try:
        # A timer outlives a helper or hub restart. Refuse to open unless its
        # unique-rule cleanup is armed; no shell or caller-supplied unit.
        subprocess.run(
            [systemd_run, "--quiet", "--collect", "--unit=" + lease,
             f"--on-active={WINDOW_SECONDS}s", "--timer-property=AccuracySec=1ms",
             "--property=Type=exec",
             "--", *delete_rule],
            check=True, timeout=5, capture_output=True,
        )
        subprocess.run(
            [iptables, "-w", "5", "-I", CHAIN, "1", *rule],
            check=True, timeout=5, capture_output=True,
        )
    except Exception:
        # An insertion timeout has uncertain completion. Attempt immediate
        # removal as well as the already-armed independent timer.
        try:
            subprocess.run(delete_rule, check=False, timeout=5, capture_output=True)
        except Exception:
            log("immediate cleanup failed; timer retains custody")
        raise


def handle(conn, recent):
    conn.settimeout(2)
    if not peer_is_hub(conn):
        log("refused a peer that is not wins-hub.service")
        return b"refused\n"
    data = b""
    while b"\n" not in data and len(data) <= REQUEST_MAX_BYTES:
        chunk = conn.recv(REQUEST_MAX_BYTES + 1 - len(data))
        if not chunk:
            break
        data += chunk
    line, newline, rest = data.partition(b"\n")
    if not newline or rest or len(data) > REQUEST_MAX_BYTES:
        return b"refused\n"
    try:
        verb, address = line.decode("ascii").split(" ")
        source = str(ipaddress.IPv4Address(address))
    except (UnicodeDecodeError, ValueError):
        return b"refused\n"
    if verb != "open" or source != address:
        return b"refused\n"
    now = time.monotonic()
    while recent and now - recent[0] >= WINDOW_SECONDS:
        recent.popleft()
    if len(recent) >= MAX_OPEN_WINDOWS:
        log("refused: too many windows open")
        return b"refused\n"
    try:
        open_window(source)
    except Exception as exc:
        log(f"window refused: {type(exc).__name__}")
        return b"refused\n"
    recent.append(now)
    log("SPA window opened")
    return b"ok\n"


def main():
    os.umask(0o077)
    try:
        os.unlink(SOCKET_PATH)
    except FileNotFoundError:
        pass
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server.bind(SOCKET_PATH)
    os.chmod(SOCKET_PATH, 0o600)
    server.listen(8)
    recent = collections.deque()
    log("listening")
    while True:
        conn, _ = server.accept()
        with conn:
            try:
                conn.sendall(handle(conn, recent))
            except OSError as exc:
                log(f"connection error: {type(exc).__name__}")


if __name__ == "__main__":
    sys.exit(main())
SPAWINDOWEOF
  chown root:root /usr/local/lib/wins_hub_spa_window.py
  chmod 0644 /usr/local/lib/wins_hub_spa_window.py
  cat > /etc/systemd/system/wins-hub-spa-window.service <<'EOF'
[Unit]
Description=Wins VPN hub legacy SPA window helper (one verb: open a 20 s API window)
After=systemd-tmpfiles-setup.service
Before=wins-hub.service

[Service]
Type=simple
ExecStart=/usr/bin/python3 -I /usr/local/lib/wins_hub_spa_window.py
Restart=always
RestartSec=3
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/run/wins-hub-spa-window /run/xtables.lock
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
ProtectKernelLogs=true
ProtectClock=true
ProtectHostname=true
RestrictSUIDSGID=true
RestrictRealtime=true
RestrictNamespaces=true
MemoryDenyWriteExecute=true
RestrictAddressFamilies=AF_UNIX AF_NETLINK
CapabilityBoundingSet=CAP_NET_ADMIN
AmbientCapabilities=
SystemCallArchitectures=native
LockPersonality=true
LimitCORE=0

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  # The app listens for SPA only while the control origin is not hidden; the
  # helper runs exactly then, and is stopped otherwise.
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
    systemctl disable --now wins-hub-spa-window.service >/dev/null 2>&1 || true
  else
    systemctl enable wins-hub-spa-window.service
    systemctl restart wins-hub-spa-window.service
  fi
}

# H0 (D3): the Core's site-AI reverse tunnel logs in to a dedicated non-root
# account whose only power is remote forwarding (its Match block is in
# harden_control_sshd). The hub app writes that account's authorized keys
# file, which replaces the app's old write access to root's authorized_keys.
write_site_ai_tunnel_account() {
  id -u wins-site-ai >/dev/null 2>&1 \
    || useradd --system --home-dir /nonexistent --no-create-home --shell /usr/sbin/nologin wins-site-ai
  install -d -m 0755 -o root -g root /var/lib/wins-site-ai-tunnel
  if [[ ! -e /var/lib/wins-site-ai-tunnel/authorized_keys ]]; then
    install -m 0644 -o root -g root /dev/null /var/lib/wins-site-ai-tunnel/authorized_keys
  fi
}

# H0 (D8): master.log rotation runs in its own sandboxed unit, not in the
# distribution's logrotate.service, which runs as root with every capability
# over a directory the hub app writes. The policy itself is unchanged.
write_hub_logrotate() {
  install -d -m 0755 -o root -g root /etc/winsvpn
  install -d -m 0700 -o root -g root /var/lib/wins-hub-logrotate
  # M-7: bound the control-plane master.log so it cannot grow without limit. The
  # app logs via WatchedFileHandler, which reopens the file after logrotate
  # renames it, so a plain rename-and-recreate rotation is safe.
  cat > /etc/winsvpn/wins-hub-logrotate.conf <<'EOF'
/var/log/winsvpn/master.log {
    daily
    maxsize 100M
    rotate 14
    missingok
    notifempty
    compress
    delaycompress
}
EOF
  chown root:root /etc/winsvpn/wins-hub-logrotate.conf
  chmod 0644 /etc/winsvpn/wins-hub-logrotate.conf
  logrotate --debug --state /var/lib/wins-hub-logrotate/status /etc/winsvpn/wins-hub-logrotate.conf >/dev/null 2>&1 \
    || warn "logrotate dry-run for wins-hub-logrotate reported issues; review /etc/winsvpn/wins-hub-logrotate.conf."
  # The distribution's logrotate must no longer rotate this directory.
  rm -f /etc/logrotate.d/wins-winsvpn
  cat > /etc/systemd/system/wins-hub-logrotate.service <<'EOF'
[Unit]
Description=Rotate the Wins VPN hub master.log (sandboxed)

[Service]
Type=oneshot
ExecStart=/usr/sbin/logrotate --state /var/lib/wins-hub-logrotate/status /etc/winsvpn/wins-hub-logrotate.conf
Nice=19
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
PrivateNetwork=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/var/log/winsvpn /var/lib/wins-hub-logrotate
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
ProtectKernelLogs=true
ProtectClock=true
ProtectHostname=true
RestrictSUIDSGID=true
RestrictRealtime=true
RestrictNamespaces=true
MemoryDenyWriteExecute=true
RestrictAddressFamilies=AF_UNIX
CapabilityBoundingSet=
AmbientCapabilities=
SystemCallArchitectures=native
LockPersonality=true
EOF
  cat > /etc/systemd/system/wins-hub-logrotate.timer <<'EOF'
[Unit]
Description=Rotate the Wins VPN hub master.log daily

[Timer]
OnCalendar=daily
AccuracySec=1h
RandomizedDelaySec=1h
Persistent=true

[Install]
WantedBy=timers.target
EOF
  systemctl daemon-reload
  systemctl enable --now wins-hub-logrotate.timer
}

# H0 (D2): /etc/resolv.conf must resolve inside the hub's private /run. Only
# systemd-resolved's two published files are bound back in, so a resolver
# file anywhere else under /run would leave the hub without DNS. Refuse that
# here, by name, rather than start a hub that cannot resolve.
require_hub_resolver_config_bindable() {
  local target
  target="$(readlink -f /etc/resolv.conf 2>/dev/null || true)"
  case "${target}" in
    /run/systemd/resolve/stub-resolv.conf|/run/systemd/resolve/resolv.conf) return 0 ;;
    /run/*)
      err "/etc/resolv.conf resolves to ${target}, which the hub's private /run does not bind (H0, D2). Point it at systemd-resolved, or at a file outside /run, then re-run."
      return 1
      ;;
  esac
  return 0
}

# --- begin descriptor signer (H1, design v17 3.4 to 3.13) ---
# The online g-slot descriptor signer. It runs as wins-desc-signer, not root,
# because uid 0 reads a root-owned 0400 file without CAP_DAC_OVERRIDE (3.4).
# The key is placed only after the hardened hub unit (H0, 3.2) is in force,
# and wins-hub.service cannot see the signer's config or state directories.
# The signer keeps its own ledger; neither directory is in any backup.
DESCRIPTOR_SIGNER_USER="wins-desc-signer"
DESCRIPTOR_SIGNER_CONFIG_DIR="/etc/winsvpn/descriptor-signer"
DESCRIPTOR_SIGNER_STATE_DIR="/var/lib/wins-descriptor-signer"
DESCRIPTOR_SIGNER_DIGEST_DIR="/var/lib/wins-descriptor-signer-digest"
# File-based key injection lives only here, hidden from wins-hub.service:
# WINS_SECRETS_FILE=/etc/wins-descriptor-signer-input/secrets.env. Never the
# default secrets file or the defaults file, which the root hub app can read.
DESCRIPTOR_SIGNER_INPUT_DIR="/etc/wins-descriptor-signer-input"
# RFC 8410 SubjectPublicKeyInfo prefix for Ed25519, base64. It is 12 bytes, so
# base64(prefix || raw32) is this text followed by base64(raw32).
DESCRIPTOR_SIGNER_SPKI_PREFIX_B64="MCowBQYDK2VwAyEA"

# The user and the two directories wins-hub.service makes inaccessible. They
# must exist before the hub unit starts, or InaccessiblePaths= fails it.
write_descriptor_signer_account() {
  id -u "${DESCRIPTOR_SIGNER_USER}" >/dev/null 2>&1 \
    || useradd --system --user-group --home-dir /nonexistent --no-create-home \
         --shell /usr/sbin/nologin "${DESCRIPTOR_SIGNER_USER}"
  install -d -m 0755 -o root -g root /etc/winsvpn
  install -d -m 0700 -o "${DESCRIPTOR_SIGNER_USER}" -g "${DESCRIPTOR_SIGNER_USER}" \
    "${DESCRIPTOR_SIGNER_CONFIG_DIR}" "${DESCRIPTOR_SIGNER_STATE_DIR}"
  install -d -m 0755 -o "${DESCRIPTOR_SIGNER_USER}" -g "${DESCRIPTOR_SIGNER_USER}" \
    "${DESCRIPTOR_SIGNER_DIGEST_DIR}"
  install -d -m 0700 -o root -g root "${DESCRIPTOR_SIGNER_INPUT_DIR}"
}

# 3.4: the key's only route is a secrets file under DESCRIPTOR_SIGNER_INPUT_DIR,
# which wins-hub.service cannot read. The hub runs as root with
# ProtectHome=read-only, so it can read the defaults file and the default
# secrets file, and a key typed on a command line sits in /proc/<pid>/cmdline.
descriptor_signer_key_defined_by() {
  ( unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64; set +u
    # shellcheck source=/dev/null
    . "$1" >/dev/null 2>&1
    [[ -n "${WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64:-}" ]] )
}

descriptor_signer_key_route_ok() {
  local secrets
  [[ -n "${WINS_SECRETS_FILE:-}" && -f "${WINS_SECRETS_FILE}" ]] || return 1
  secrets="$(readlink -f -- "${WINS_SECRETS_FILE}")" || return 1
  [[ "${secrets}" == "${DESCRIPTOR_SIGNER_INPUT_DIR}/"* ]] || return 1
  descriptor_signer_key_defined_by "${secrets}" || return 1
  if [[ -n "${WINS_DEFAULTS_FILE:-}" && -f "${WINS_DEFAULTS_FILE}" ]] \
      && descriptor_signer_key_defined_by "${WINS_DEFAULTS_FILE}"; then
    return 1
  fi
}

# The partial vault moves /etc/winsvpn into a root-only mount the signer user
# cannot traverse. No key is placed where the signer could not read it.
descriptor_signer_config_dir_in_place() {
  [[ "$(readlink -f "${DESCRIPTOR_SIGNER_CONFIG_DIR}")" == "${DESCRIPTOR_SIGNER_CONFIG_DIR}" ]]
}

write_descriptor_signer_program() {
  install -d -m 0755 -o root -g root /usr/local/lib
  cat > /usr/local/lib/wins_descriptor_signer.py <<'DESCSIGNEREOF'
#!/usr/bin/env python3
"""wins-descriptor-signer: the hub's online descriptor signer (design v17, 3.4 to 3.13).

It runs as wins-desc-signer with no network and no capability, and it is the
only process that can read the active slot's Ed25519 key. Its socket comes
from systemd (wins-descriptor-signer.socket, 0660 wins-desc-signer:root), and
it answers only a uid 0 peer in the wins-hub.service cgroup. One JSON request
line per connection, one JSON reply line.

Verbs: sign, renew, rekey, supersede, suspend, unsuspend, status. There is no
"sign these bytes" call and no ledger bootstrap on the socket (3.12). A new or
changed identity needs an unused t1 ticket under the current ticket epoch
(3.8), and the node's host-key signature over its identity file (3.5 step 5).
A renewal re-signs the retained payload with only seq, iat and not_after
changed (3.7), and kid set to the active slot (3.10). Rules for
expected_prior_seq, orphans and superseded sequences are 3.13. Every issuance
is written and fsynced before its reply.

`digest` (run by wins-descriptor-signer-digest.service) writes the protected
checkpoint and the daily digest. It never signs.

The operator root CLIs (3.12) are separate argv modes, never socket verbs:
`ledger-bootstrap` creates the initial empty ledger the first time only (the
signer refuses a missing ledger; once a ledger has been installed, a missing
one is a loss and is reconciled), `reconcile` rebuilds a lost ledger
fail-closed, and
`restore-checkpoint` plus `confirm` cover the checkpoint path. reconcile and
restore-checkpoint leave RECOVERY-PENDING in the config directory, and the
signer refuses every change until the operator confirms. The confirmation may
grant the one-time recovery allowance of new identities. Every mode refuses
to run as a non-root user, and none is reachable from wins-hub.service.

Python standard library only, run as `python3 -I`. openssl signs and verifies,
the same path the hub verifies with.
"""
import base64
import binascii
import errno
import fcntl
import hashlib
import ipaddress
import json
import os
import pwd
import re
import signal
import socket
import sqlite3
import struct
import subprocess
import sys
import tempfile
import threading
import time

CONFIG_DIR = "/etc/winsvpn/descriptor-signer"
STATE_DIR = "/var/lib/wins-descriptor-signer"
WORK_DIR = "/run/wins-descriptor-signer/work"
DIGEST_DIR = "/var/lib/wins-descriptor-signer-digest"
HUB_KEY_HISTORY = "/etc/winsvpn/hub-key-history"
OPERATOR_SSH_KEYS = "/etc/winsvpn/operator-ssh-keys"
OPENSSL = "/usr/bin/openssl"
SSH_KEYGEN = "/usr/bin/ssh-keygen"
HUB_CGROUP_SUFFIX = "/wins-hub.service"
SO_PEERPIDFD = getattr(socket, "SO_PEERPIDFD", 77)
CLOCK = time.time

DESCRIPTOR_DOMAIN = b"winsvpn-winn3-descriptor/v1"
TICKET_DOMAIN = b"winsvpn-winn3-signer-ticket/v1"
IDENTITY_NAMESPACE = "winsvpn-winn3-identity/v1"
ADMISSION_FP_DOMAIN = b"winn3-admission-fingerprint-v1"
SLOTS = ("g1", "g2", "g3")
ED25519_SPKI_PREFIX = bytes.fromhex("302a300506032b6570032100")

LIFETIME_S = 14 * 86400
RENEW_WINDOW_S = 7 * 86400
TICKET_MAX_LIFETIME_S = 7 * 86400
DAY_S = 86400
MAX_NEW_IDENTITIES_PER_DAY = 4
MAX_SIGNATURES_PER_DAY = 64
MAX_SLUGS = 64
SEQ_REQUEST_BOUND = 2 ** 53 - 1 - 2 ** 32
SEQ_ISSUE_MAX = 2 ** 53 - 1
GATEWAY_PORT = 9111
REQUEST_MAX_BYTES = 65536
REFUSAL_FLUSH_S = 60
# The operator CLI's confirmation gate (3.12 step 6), kept beside DISABLED in
# the signer's config directory, which the app can neither read nor write.
RECOVERY_PENDING_FILE = "RECOVERY-PENDING"
# Written by the first CLI install of a ledger. A missing ledger beside this
# file is a LOSS, which is reconciled (3.12); only a host that never held a
# ledger may be bootstrapped.
LEDGER_INITIALIZED_FILE = "LEDGER-INITIALIZED"

# Format 3, with the client-supported constants only (3.6).
FORMAT_VERSION = 3
TAG_SIZE = 32
PADDING = "bucket"
BUCKET_WINDOW_S = 10
MAX_SKEW_S = 60

SLUG_RE = re.compile(r"[a-z0-9][a-z0-9_-]{0,62}")
HEX64_RE = re.compile(r"[0-9a-f]{64}")
NONCE_RE = re.compile(r"[0-9a-f]{32,64}")
HOST_KEY_FP_RE = re.compile(r"SHA256:[A-Za-z0-9+/]{43}")
TICKET_FIELDS = frozenset((
    "action", "endpoint_ip", "epoch", "gateway_id", "go_live",
    "host_key_sha256", "nonce", "not_after", "slug", "tier",
))
TICKET_ACTIONS = ("new", "reset", "endpoint", "rekey", "suspend", "unsuspend")
# Which ticket actions each identity verb spends.
VERB_ACTIONS = {"sign": ("new", "reset"), "rekey": ("rekey", "endpoint", "reset")}
# The public identity file the node publishes (2.5), canonical JSON.
IDENTITY_FIELDS = frozenset((
    "admission_fingerprint", "auth_ed25519_hex", "auth_mldsa65_hex",
    "credential_record_sha256", "endpoint", "gateway_id", "inner_resolver_v4",
    "inner_router_v4", "path_mtu", "plan", "slug", "ssh_host_ed25519_key",
    "static_pub_hex",
))
IDENTITY_DIGEST_FIELDS = (
    "node", "endpoint", "static_pub", "gateway_id", "inner_router_v4",
    "inner_resolver_v4", "auth_ed25519", "auth_mldsa65",
)


class Refused(Exception):
    """A request the policy refuses. Carries a reason, never a value."""


def log(message):
    print(f"wins-descriptor-signer: {message}", flush=True)


def now():
    return int(CLOCK())


def canonical(obj):
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def b64(raw):
    return base64.b64encode(raw).decode("ascii")


def b64decode_strict(value, reason):
    if not isinstance(value, str):
        raise Refused(reason)
    try:
        return base64.b64decode(value, validate=True)
    except (binascii.Error, ValueError):
        raise Refused(reason) from None


def int_field(value, reason):
    if not isinstance(value, int) or isinstance(value, bool):
        raise Refused(reason)
    return value


def admission_fingerprint(secret):
    return hashlib.sha256(ADMISSION_FP_DOMAIN + secret.encode("ascii")).hexdigest()[:16]


def identity_sha256(payload):
    """winn3_identity_sha256 (3.17): the signed identity fields, fingerprint for the secret.
    Raises ValueError unless admission_secret is the base64 of 64 ASCII hex
    bytes: the one shape issue() mints and the hub's winn3_identity_digest
    accepts (H4R-Q-SECRET)."""
    fields = {name: payload.get(name, "") for name in IDENTITY_DIGEST_FIELDS}
    try:
        secret = base64.b64decode(payload["admission_secret"], validate=True).decode("ascii")
    except (KeyError, TypeError, ValueError):
        # binascii.Error and UnicodeDecodeError are both ValueError.
        raise ValueError("admission-secret-malformed") from None
    if not HEX64_RE.fullmatch(secret):
        raise ValueError("admission-secret-malformed")
    fields["admission_fingerprint"] = admission_fingerprint(secret)
    return hashlib.sha256(canonical(fields)).hexdigest()


def inner_ipv4(value):
    if not isinstance(value, str) or value.count(".") != 3:
        return False
    try:
        address = ipaddress.IPv4Address(value)
    except ValueError:
        return False
    return str(address) == value and not (address.is_unspecified or address.is_multicast or address.is_loopback)


def read_config_file(name):
    with open(os.path.join(CONFIG_DIR, name), "r", encoding="ascii") as handle:
        return handle.read()


def load_config():
    """The installer's signer config and ticket epoch. Never written here.
    A malformed file raises ValueError, the one failure both callers refuse
    on: nested too deep to parse, not an object, or a key that is not text."""
    try:
        config = json.loads(read_config_file("signer.json"))
    except RecursionError:
        raise ValueError("signer.json") from None
    if not isinstance(config, dict):
        raise ValueError("signer.json")
    slot = config.get("active_slot")
    if slot not in SLOTS:
        raise ValueError("active_slot")
    pub_text = config.get("active_slot_pubkey", "")
    if not isinstance(pub_text, str):
        raise ValueError("active_slot_pubkey")
    pub = base64.b64decode(pub_text, validate=True)
    if len(pub) != 32:
        raise ValueError("active_slot_pubkey")
    t1 = config.get("ticket_pubkey_t1") or ""
    if not isinstance(t1, str):
        raise ValueError("ticket_pubkey_t1")
    t1_raw = base64.b64decode(t1, validate=True) if t1 else b""
    if t1 and len(t1_raw) != 32:
        raise ValueError("ticket_pubkey_t1")
    epoch_text = read_config_file("ticket-epoch").strip()
    if not epoch_text.isdigit():
        raise ValueError("ticket-epoch")
    return {"slot": slot, "pub": pub, "t1": t1_raw, "epoch": int(epoch_text),
            "key_path": os.path.join(CONFIG_DIR, f"{slot}.ed25519.pem")}


def signer_disabled():
    return os.path.lexists(os.path.join(CONFIG_DIR, "DISABLED"))


# --------------------------------------------------------------- openssl --

def run_tool(argv, stdin=None):
    return subprocess.run(argv, input=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                          timeout=15, check=False, env={"PATH": "/usr/bin:/bin", "LC_ALL": "C"})


def write_private(path, blob):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "wb") as handle:
        handle.write(blob)


def ed25519_verify(public_raw, message, signature):
    if len(signature) != 64:
        return False
    with tempfile.TemporaryDirectory(dir=WORK_DIR) as work:
        paths = [os.path.join(work, name) for name in ("key.der", "msg.bin", "sig.bin")]
        for path, blob in zip(paths, (ED25519_SPKI_PREFIX + public_raw, message, signature)):
            write_private(path, blob)
        done = run_tool([OPENSSL, "pkeyutl", "-verify", "-rawin", "-pubin", "-inkey", paths[0],
                         "-keyform", "DER", "-sigfile", paths[2], "-in", paths[1]])
    return done.returncode == 0


def ed25519_sign(key_path, message):
    # Ed25519 is one-shot: openssl needs a seekable -in, so the message (which
    # carries the admission secret) is written only in the private work dir.
    with tempfile.TemporaryDirectory(dir=WORK_DIR) as work:
        path = os.path.join(work, "msg.bin")
        write_private(path, message)
        done = run_tool([OPENSSL, "pkeyutl", "-sign", "-rawin", "-inkey", key_path, "-in", path])
    if done.returncode != 0 or len(done.stdout) != 64:
        raise Refused("signing-failed")
    return done.stdout


def key_public_raw(key_path):
    done = run_tool([OPENSSL, "pkey", "-in", key_path, "-pubout", "-outform", "DER"])
    der = done.stdout
    if done.returncode != 0 or len(der) != 44 or not der.startswith(ED25519_SPKI_PREFIX):
        return None
    return der[12:]


# --------------------------------------------------------------- ledger --

def empty_ledger():
    return {"version": 1, "slugs": {}, "nonces": {}, "refusals": {}, "audit": [], "audit_head": ""}


def audit_entry_hash(prev, entry):
    body = {key: value for key, value in entry.items() if key != "hash"}
    return hashlib.sha256(prev.encode("ascii") + canonical(body)).hexdigest()


def audit_chain_ok(ledger):
    # A ledger whose audit fields are missing or mistyped does not verify: the
    # check answers False, it never raises (a raise would skip the callers'
    # refusal and, in the CLIs, clear a recovery gate). That includes a value
    # nested too deep to re-serialize for its hash (RecursionError).
    try:
        prev = ""
        for entry in ledger["audit"]:
            if entry.get("prev") != prev or audit_entry_hash(prev, entry) != entry.get("hash"):
                return False
            prev = entry["hash"]
        return ledger["audit_head"] == prev
    except (AttributeError, KeyError, TypeError, ValueError, UnicodeError, RecursionError):
        return False


def audit(ledger, event, **fields):
    prev = ledger["audit_head"]
    entry = {"n": len(ledger["audit"]), "at": now(), "event": event, **fields, "prev": prev}
    entry["hash"] = audit_entry_hash(prev, entry)
    ledger["audit"].append(entry)
    ledger["audit_head"] = entry["hash"]


def fsync_dir(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def atomic_write(path, blob, mode):
    directory = os.path.dirname(path)
    fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=directory)
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, "wb") as handle:
            handle.write(blob)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise
    fsync_dir(directory)


class LedgerLock:
    # H4 (3.12): a request runs whole under the exclusive lock, and the
    # ledger write inside it takes the lock again. flock on a second
    # descriptor would block on the first, so a thread that already holds the
    # exclusive lock re-enters without a second flock. Another thread, and
    # every other process, still waits.
    _held = threading.local()

    def __init__(self, exclusive):
        self.mode = fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH
        self.fd = None

    def __enter__(self):
        if getattr(LedgerLock._held, "depth", 0):
            LedgerLock._held.depth += 1
            return self
        # O_NOFOLLOW: the directory belongs to the signer user, and the
        # operator CLIs open this file as root.
        self.fd = os.open(os.path.join(STATE_DIR, "ledger.lock"),
                          os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
        try:
            if cli_is_root():
                # On a fresh install the operator's root CLI (ledger-bootstrap) is
                # the first to take this lock. The signer service and the digest
                # unit are not root and could not open a root-owned 0600 file.
                ids = signer_user_ids()
                if ids is not None:
                    cli_chown(self.fd, ids)
            fcntl.flock(self.fd, self.mode)
        except BaseException:
            os.close(self.fd)
            self.fd = None
            raise
        if self.mode == fcntl.LOCK_EX:
            LedgerLock._held.depth = 1
        return self

    def __exit__(self, *exc):
        if self.fd is None:
            LedgerLock._held.depth -= 1
            return
        if self.mode == fcntl.LOCK_EX:
            LedgerLock._held.depth = 0
        os.close(self.fd)
        self.fd = None


def read_ledger():
    path = os.path.join(STATE_DIR, "ledger.json")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        raise ValueError("ledger-missing; operator initialization or reconciliation required") from None
    ledger = json.loads(raw)
    if not isinstance(ledger, dict) or ledger.get("version") != 1:
        raise ValueError("ledger-malformed")
    # H4: a parseable file of the wrong shape is a malformed ledger, not a
    # crash in a later caller that indexes into it.
    shapes = {"slugs": dict, "nonces": dict, "refusals": dict, "audit": list, "audit_head": str}
    if any(not isinstance(ledger.get(key), kind) for key, kind in shapes.items()):
        raise ValueError("ledger-malformed")
    return ledger, raw


def ledger_on_disk():
    """H4's view of read_ledger for the operator CLIs and the reload path:
    (ledger or None, present). present is False only when ledger.json does not
    exist; a file that is unreadable, does not parse or has the wrong shape is
    present and None. Never raises for those states (3.12)."""
    try:
        ledger, _raw = read_ledger()
    except (OSError, ValueError, RecursionError):
        return None, os.path.lexists(os.path.join(STATE_DIR, "ledger.json"))
    return ledger, True


def write_ledger(ledger):
    with LedgerLock(True):
        atomic_write(os.path.join(STATE_DIR, "ledger.json"), canonical(ledger), 0o600)


def ledger_stamp():
    """Identity of ledger.json on disk. It changes whenever the file is
    replaced: by the signer's own atomic write or by an operator CLI (3.12)."""
    try:
        info = os.stat(os.path.join(STATE_DIR, "ledger.json"))
    except OSError:
        return None
    return (info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def slug_record(ledger, slug, create=False):
    record = ledger["slugs"].get(slug)
    if record is None and create:
        # A slug a reconciled ledger never recorded is suspended and keeps the
        # recovery gap: missing suspension state is treated as suspended, and
        # an allocated-but-unstored sequence must not be reissued (3.12).
        recovered = ledger.get("reconciled") is True
        record = {"state": "suspended" if recovered else "active",
                  "floor": RECONCILE_GAP - 1 if recovered else -1,
                  "presented_stored": -1, "issuances": []}
        ledger["slugs"][slug] = record
    return record


def live_issuance(record):
    live = [item for item in (record or {}).get("issuances", []) if not item["superseded"]]
    return max(live, key=lambda item: item["seq"]) if live else None


def compact(record):
    """Remove returned envelope bytes only for burned sequences."""
    for item in record["issuances"]:
        if item["superseded"]:
            item.pop("payload", None)
            item.pop("sig", None)


def issued_since(ledger, since, kind=None, slug=None):
    count = 0
    for name, record in ledger["slugs"].items():
        if slug is not None and name != slug:
            continue
        for item in record["issuances"]:
            if item.get("recovery_allowance", False):
                continue
            if item["issued_at"] > since and (kind is None or item["kind"] == kind):
                count += 1
    return count


def window_spends(ledger, since, kind=None, slug=None):
    """Synthetic window spends written by the reconciliation (3.12 step 5):
    every rate-limit window starts fully spent at the time of recovery and
    ages out of the rolling 24 h window on its own."""
    count = 0
    for spend in ledger.get("window_spends", []):
        if spend["at"] > since and (kind is None or spend["kind"] == kind) \
                and (slug is None or spend.get("slug") == slug):
            count += spend.get("count", 1)
    return count


# ---------------------------------------------------------- verification --

def verify_ticket(config, ledger, envelope, slug, actions):
    if not config["t1"]:
        raise Refused("ticket-key-not-configured")
    if not isinstance(envelope, dict) or set(envelope) != {"payload", "sig"}:
        raise Refused("ticket-malformed")
    payload_raw = b64decode_strict(envelope["payload"], "ticket-malformed")
    signature = b64decode_strict(envelope["sig"], "ticket-malformed")
    # The domain keeps a descriptor signature from ever passing as a ticket.
    if not ed25519_verify(config["t1"], TICKET_DOMAIN + b"\x00" + payload_raw, signature):
        raise Refused("ticket-signature-invalid")
    try:
        ticket = json.loads(payload_raw)
    except (ValueError, RecursionError):
        raise Refused("ticket-malformed") from None
    if not isinstance(ticket, dict) or set(ticket) != TICKET_FIELDS:
        raise Refused("ticket-malformed")
    # One byte form, so every reader of the stored ticket (3.17) parses the
    # same fields: no duplicate keys, no whitespace variants.
    if canonical(ticket) != payload_raw:
        raise Refused("ticket-not-canonical")
    if ticket["slug"] != slug:
        raise Refused("ticket-wrong-slug")
    if ticket["action"] not in TICKET_ACTIONS or ticket["action"] not in actions:
        raise Refused("ticket-wrong-action")
    if int_field(ticket["epoch"], "ticket-malformed") != config["epoch"]:
        raise Refused("ticket-epoch-stale")
    not_after = int_field(ticket["not_after"], "ticket-malformed")
    if not_after <= now():
        raise Refused("ticket-expired")
    if not_after > now() + TICKET_MAX_LIFETIME_S:
        raise Refused("ticket-lifetime-too-long")
    if ticket["go_live"] not in ("auto", "manual") or ticket["tier"] not in ("free", "premium"):
        raise Refused("ticket-malformed")
    if not isinstance(ticket["nonce"], str) or not NONCE_RE.fullmatch(ticket["nonce"]):
        raise Refused("ticket-malformed")
    if not isinstance(ticket["host_key_sha256"], str) or not HOST_KEY_FP_RE.fullmatch(ticket["host_key_sha256"]):
        raise Refused("ticket-malformed")
    if not inner_ipv4(ticket["endpoint_ip"]) or not isinstance(ticket["gateway_id"], str):
        raise Refused("ticket-malformed")
    if ticket["nonce"] in ledger["nonces"]:
        raise Refused("ticket-already-spent")
    return ticket


def host_key_fingerprint(line):
    parts = line.split() if isinstance(line, str) else []
    if len(parts) < 2 or parts[0] != "ssh-ed25519":
        raise Refused("identity-host-key-malformed")
    blob = b64decode_strict(parts[1], "identity-host-key-malformed")
    if blob[:4] != struct.pack(">I", 11) or blob[4:15] != b"ssh-ed25519" or len(blob) != 51:
        raise Refused("identity-host-key-malformed")
    digest = base64.b64encode(hashlib.sha256(blob).digest()).decode("ascii").rstrip("=")
    return "SHA256:" + digest, parts[1]


def verify_identity(slug, identity_raw, signature_raw, ticket):
    try:
        identity = json.loads(identity_raw)
    except (ValueError, RecursionError):
        raise Refused("identity-malformed") from None
    if not isinstance(identity, dict) or set(identity) != IDENTITY_FIELDS:
        raise Refused("identity-malformed")
    if canonical(identity) != identity_raw:
        raise Refused("identity-not-canonical")
    if identity["slug"] != slug:
        raise Refused("identity-wrong-slug")
    # The node's host key must be the one the operator pinned in the ticket.
    fingerprint, blob = host_key_fingerprint(identity["ssh_host_ed25519_key"])
    if fingerprint != ticket["host_key_sha256"]:
        raise Refused("identity-host-key-not-ticketed")
    with tempfile.TemporaryDirectory(dir=WORK_DIR) as work:
        allowed = os.path.join(work, "allowed_signers")
        sig_path = os.path.join(work, "identity.sshsig")
        write_private(allowed, f'{slug} namespaces="{IDENTITY_NAMESPACE}" ssh-ed25519 {blob}\n'.encode("ascii"))
        write_private(sig_path, signature_raw)
        done = run_tool([SSH_KEYGEN, "-Y", "verify", "-f", allowed, "-I", slug,
                         "-n", IDENTITY_NAMESPACE, "-s", sig_path], stdin=identity_raw)
    if done.returncode != 0:
        raise Refused("identity-host-signature-invalid")
    endpoint = identity["endpoint"]
    host, _, port = endpoint.rpartition(":") if isinstance(endpoint, str) else ("", "", "")
    if port != str(GATEWAY_PORT) or not inner_ipv4(host) or host != ticket["endpoint_ip"]:
        raise Refused("identity-endpoint-not-ticketed")
    if identity["gateway_id"] != ticket["gateway_id"]:
        raise Refused("identity-gateway-id-not-ticketed")
    gateway_id = identity["gateway_id"]
    raw_id = gateway_id.encode("utf-8") if isinstance(gateway_id, str) else b""
    if not 1 <= len(raw_id) <= 255 or raw_id[:1].isspace() or raw_id[-1:].isspace():
        raise Refused("identity-gateway-id-malformed")
    router = identity["inner_router_v4"]
    if not inner_ipv4(router) or identity["inner_resolver_v4"] != router:
        raise Refused("identity-inner-address-malformed")
    sizes = (("static_pub_hex", 32), ("auth_ed25519_hex", 32), ("auth_mldsa65_hex", 1952))
    for name, size in sizes:
        value = identity[name]
        if not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{%d}" % (2 * size), value):
            raise Refused("identity-key-size")
    if not isinstance(identity["admission_fingerprint"], str) or not re.fullmatch(r"[0-9a-f]{16}", identity["admission_fingerprint"]):
        raise Refused("identity-malformed")
    return identity


# ---------------------------------------------------------------- policy --

def refuse_count(ledger, reason):
    day = time.strftime("%Y-%m-%d", time.gmtime(now()))
    bucket = ledger["refusals"].setdefault(day, {})
    bucket[reason] = bucket.get(reason, 0) + 1
    for old in sorted(ledger["refusals"])[:-8]:
        del ledger["refusals"][old]


def envelope(item, orphan):
    return {"ok": True, "seq": item["seq"], "payload": item["payload"], "sig": item["sig"],
            "kid": item["kid"], "identity_sha256": item["identity_sha256"],
            "admission_gen": item["admission_gen"], "not_after": item["not_after"],
            "go_live": item["go_live"], "tier": item["tier"], "orphan": orphan}


def common_fields(request):
    slug = request.get("slug")
    if not isinstance(slug, str) or not SLUG_RE.fullmatch(slug):
        raise Refused("slug-malformed")
    generation = int_field(request.get("generation"), "generation-malformed")
    if generation < 0:
        raise Refused("generation-malformed")
    return slug, generation


def issue(config, ledger, request, verb):
    """sign, rekey and renew: the 3.13 rules, then a new issuance or a re-fetch."""
    slug, generation = common_fields(request)
    eps = int_field(request.get("expected_prior_seq"), "expected-prior-seq-malformed")
    if eps < -1 or eps > SEQ_REQUEST_BOUND:
        raise Refused("expected-prior-seq-out-of-bound")
    record = slug_record(ledger, slug)
    # H4 (3.12 step 3): in a ledger reconciled without a checkpoint, a slug
    # it never recorded is suspended too.
    if (record is None and ledger.get("reconciled") is True) \
            or (record is not None and record["state"] == "suspended"):
        raise Refused("slug-suspended")
    ticket_envelope = request.get("ticket") if verb != "renew" else None
    nonce = "-"
    if verb != "renew":
        try:
            nonce = json.loads(b64decode_strict(ticket_envelope["payload"], "ticket-malformed"))["nonce"]
        except (TypeError, KeyError, ValueError, RecursionError):
            raise Refused("ticket-malformed") from None
        if not isinstance(nonce, str):
            raise Refused("ticket-malformed")
    key = f"{slug}|{verb}|{nonce}|{eps}"
    # A retry of a recorded issuance gets the identical bytes, unless burned.
    # The generation is not in the key (3.13); a retry from a cycle whose
    # generation moved is the orphan re-fetch, and says so.
    for item in (record or {}).get("issuances", []):
        if item["key"] == key and not item["superseded"] and "payload" in item:
            return envelope(item, item["generation"] != generation), False
    live = live_issuance(record)
    if live is not None:
        if eps > live["seq"] or eps < record["presented_stored"]:
            raise Refused("expected-prior-seq-stale")
        if eps < live["seq"]:
            # Orphaned issuance: hand back the live envelope; issue nothing.
            changed = eps > record["presented_stored"]
            record["presented_stored"] = max(record["presented_stored"], eps)
            return envelope(live, True), changed
    elif verb == "renew":
        raise Refused("no-live-issuance")
    t = now()
    since = t - DAY_S
    # 3.12 step 6: granted only by the operator root CLI, spent here (3.8).
    remaining = int_field(
        ledger.get("recovery_allowance_remaining", 0),
        "recovery-allowance-malformed",
    )
    if remaining < 0 or remaining > MAX_SLUGS:
        raise Refused("recovery-allowance-malformed")
    use_allowance = verb != "renew" and remaining > 0
    # H4 (3.12 step 5): window_spends are the windows a reconciliation
    # started as fully spent; they age out of the 24 h window on their own.
    if not use_allowance and issued_since(ledger, since) \
            + window_spends(ledger, since, kind="signature") >= MAX_SIGNATURES_PER_DAY:
        raise Refused("rate-limit-signatures")
    if verb == "renew":
        if live["not_after"] - t >= RENEW_WINDOW_S:
            raise Refused("outside-renewal-window")
        if issued_since(ledger, since, kind="renewal", slug=slug) \
                + window_spends(ledger, since, kind="renewal", slug=slug):
            raise Refused("rate-limit-renewal")
        payload = json.loads(base64.b64decode(live["payload"]))
        ticket = None
        kind, go_live, tier = "renewal", live["go_live"], live["tier"]
        admission_gen = live["admission_gen"]
    else:
        ticket = verify_ticket(config, ledger, ticket_envelope, slug, VERB_ACTIONS[verb])
        if ticket["action"] == "new" and record is not None and record["issuances"]:
            raise Refused("ticket-new-for-known-slug")
        identity_raw = b64decode_strict(request.get("identity"), "identity-malformed")
        signature_raw = b64decode_strict(request.get("identity_sig"), "identity-malformed")
        identity = verify_identity(slug, identity_raw, signature_raw, ticket)
        secret = request.get("admission_secret")
        if not isinstance(secret, str) or not HEX64_RE.fullmatch(secret):
            raise Refused("admission-secret-malformed")
        if admission_fingerprint(secret) != identity["admission_fingerprint"]:
            raise Refused("admission-secret-fingerprint-mismatch")
        if not use_allowance and issued_since(ledger, since, kind="identity") \
                + window_spends(ledger, since, kind="identity") >= MAX_NEW_IDENTITIES_PER_DAY:
            raise Refused("rate-limit-new-identities")
        known = [name for name, item in ledger["slugs"].items() if item["issuances"]]
        if slug not in known and len(known) >= MAX_SLUGS:
            raise Refused("slug-cap")
        prior_gens = [item["admission_gen"] for item in (record or {}).get("issuances", [])]
        admission_gen = max(prior_gens) + 1 if prior_gens else 1
        payload = {
            "v": FORMAT_VERSION, "alg": "ed25519", "node": slug,
            "endpoint": identity["endpoint"],
            "inner_router_v4": identity["inner_router_v4"],
            "inner_resolver_v4": identity["inner_resolver_v4"],
            "static_pub": b64(bytes.fromhex(identity["static_pub_hex"])),
            "gateway_id": b64(identity["gateway_id"].encode("utf-8")),
            # The 64 ASCII hex bytes, base64'd, never hex-decoded.
            "admission_secret": b64(secret.encode("ascii")),
            "tag_size": TAG_SIZE, "padding": PADDING,
            "bucket_window_s": BUCKET_WINDOW_S, "max_skew_s": MAX_SKEW_S,
            "auth_ed25519": b64(bytes.fromhex(identity["auth_ed25519_hex"])),
            "auth_mldsa65": b64(bytes.fromhex(identity["auth_mldsa65_hex"])),
        }
        kind, go_live, tier = "identity", ticket["go_live"], ticket["tier"]
    record = slug_record(ledger, slug, create=True)
    seq = max(record["floor"], eps) + 1
    if seq > SEQ_ISSUE_MAX:
        raise Refused("sequence-exhausted")
    payload.update({"kid": config["slot"], "seq": seq, "iat": t, "not_after": t + LIFETIME_S,
                    "admission_gen": admission_gen})
    payload_raw = canonical(payload)
    message = DESCRIPTOR_DOMAIN + b"\x00" + payload_raw
    signature = ed25519_sign(config["key_path"], message)
    if not ed25519_verify(config["pub"], message, signature):
        raise Refused("signing-self-check-failed")
    item = {"key": key, "verb": verb, "kind": kind, "seq": seq, "kid": config["slot"],
            "payload": b64(payload_raw), "sig": b64(signature),
            "identity_sha256": identity_sha256(payload), "admission_gen": admission_gen,
            "issued_at": t, "not_after": t + LIFETIME_S, "generation": generation,
            "eps": eps, "go_live": go_live, "tier": tier, "superseded": False,
            "ticket_action": ticket["action"] if ticket else "", "nonce": nonce}
    # 3.5 step 5 audit evidence: the exact verified inputs. Burning the
    # envelope later never removes them.
    if ticket is not None:
        item["identity"] = request["identity"]
        item["identity_sig"] = request["identity_sig"]
        item["ticket"] = {
            "payload": ticket_envelope["payload"],
            "sig": ticket_envelope["sig"],
        }
    item["recovery_allowance"] = use_allowance
    if use_allowance:
        ledger["recovery_allowance_remaining"] = remaining - 1
    record["issuances"].append(item)
    record["floor"] = seq
    record["presented_stored"] = max(record["presented_stored"], eps)
    if ticket is not None:
        ledger["nonces"][nonce] = {"slug": slug, "action": ticket["action"], "epoch": ticket["epoch"], "spent_at": t}
        audit(ledger, "ticket-spend", slug=slug, action=ticket["action"], nonce=nonce,
              seq=seq, identity_sha256=item["identity_sha256"], generation=generation)
    else:
        audit(ledger, "renew", slug=slug, seq=seq, identity_sha256=item["identity_sha256"], generation=generation)
    compact(record)
    return envelope(item, False), True


def supersede(ledger, request):
    slug, generation = common_fields(request)
    seq = int_field(request.get("seq"), "sequence-malformed")
    record = slug_record(ledger, slug)
    item = next((entry for entry in (record or {}).get("issuances", []) if entry["seq"] == seq), None)
    if item is None:
        raise Refused("unknown-sequence")
    if item["superseded"]:
        return {"ok": True, "seq": seq, "superseded": True}, False
    if seq <= record["presented_stored"]:
        raise Refused("sequence-presented-as-stored")
    item["superseded"] = True
    item.pop("payload", None)
    item.pop("sig", None)
    audit(ledger, "supersede", slug=slug, seq=seq, generation=generation)
    return {"ok": True, "seq": seq, "superseded": True}, True


def set_state(config, ledger, request, action):
    slug = request.get("slug")
    if not isinstance(slug, str) or not SLUG_RE.fullmatch(slug):
        raise Refused("slug-malformed")
    target = "suspended" if action == "suspend" else "active"
    envelope_ = request.get("ticket")
    try:
        nonce = json.loads(b64decode_strict(envelope_["payload"], "ticket-malformed"))["nonce"]
    except (TypeError, KeyError, ValueError, RecursionError):
        raise Refused("ticket-malformed") from None
    spent = ledger["nonces"].get(nonce) if isinstance(nonce, str) else None
    record = slug_record(ledger, slug)
    if spent and spent["slug"] == slug and spent["action"] == action and record and record["state"] == target:
        return {"ok": True, "slug": slug, "state": target}, False
    ticket = verify_ticket(config, ledger, envelope_, slug, (action,))
    record = slug_record(ledger, slug, create=True)
    record["state"] = target
    ledger["nonces"][nonce] = {"slug": slug, "action": action, "epoch": ticket["epoch"], "spent_at": now()}
    audit(ledger, action, slug=slug, nonce=nonce)
    return {"ok": True, "slug": slug, "state": target}, True


def status(config, ledger, ledger_ok, key_ready):
    slugs = {}
    for name, record in sorted(ledger["slugs"].items()):
        live = live_issuance(record)
        slugs[name] = {"state": record["state"], "live_seq": live["seq"] if live else None,
                       "not_after": live["not_after"] if live else None,
                       "identity_sha256": live["identity_sha256"] if live else None}
    # H4: ledger_present says whether ledger.json exists (bootstrap or
    # reconcile), recovery_pending whether the operator's gate is up (3.12).
    return {"ok": True, "active_slot": config["slot"] if config else None, "key_ready": key_ready,
            "disabled": signer_disabled(), "ledger_ok": ledger_ok,
            "ledger_present": os.path.lexists(os.path.join(STATE_DIR, "ledger.json")),
            "recovery_pending": recovery_pending(),
            "epoch": config["epoch"] if config else None, "slugs": slugs}


ISSUING_VERBS = ("sign", "renew", "rekey")
VERBS = ISSUING_VERBS + ("supersede", "suspend", "unsuspend", "status")


def recovery_pending():
    """The operator CLI's gate (3.12 step 6): while RECOVERY-PENDING exists
    in the signer's config directory, the signer refuses every change until
    the operator confirms. Mirrors the DISABLED kill switch."""
    return os.path.lexists(os.path.join(CONFIG_DIR, RECOVERY_PENDING_FILE))


class Signer:
    def __init__(self):
        self.config = None
        self.key_ready = False
        try:
            self.config = load_config()
        except (OSError, ValueError) as exc:
            log(f"config unavailable: {type(exc).__name__}")
        if self.config is not None:
            self.key_ready = key_public_raw(self.config["key_path"]) == self.config["pub"]
            if not self.key_ready:
                log("the active slot key is missing or does not match its pinned public half")
        self.load_ledger()
        self.last_refusal_flush = 0
        # H4: refusal counts not yet on disk. They are kept apart from the
        # ledger so a reload of an operator-replaced ledger carries them
        # forward, and so nothing is written while a recovery is pending (3.12).
        self.refusal_pending = {}

    def load_ledger(self):
        # H4: the file identity this copy was read from (reload check below).
        self.stamp = ledger_stamp()
        self.ledger_present = True
        try:
            self.ledger, _raw = read_ledger()
            self.ledger_ok = audit_chain_ok(self.ledger)
        except ValueError as exc:
            # 3.12: missing or malformed authorization state is never rebuilt
            # here, and never overwritten by a refusal-counter flush.
            log(f"ledger unavailable ({exc}); refusing every change")
            self.ledger, self.ledger_ok, self.ledger_present = empty_ledger(), False, False
        except Exception as exc:
            # Present but unusable now (EACCES, EIO, RecursionError, MemoryError):
            # refuse every change and read it again on the next request. The stamp
            # is forgotten, so the old in-memory copy is never served or written back.
            log(f"ledger unreadable ({type(exc).__name__}); refusing every change")
            self.ledger, self.ledger_ok, self.ledger_present = empty_ledger(), False, False
            self.stamp = None
        if self.ledger_present and not self.ledger_ok:
            log("ledger audit chain does not verify; refusing every change")

    def reload_ledger(self):
        self.load_ledger()
        if self.ledger_ok:
            for day, counts in self.refusal_pending.items():
                target = self.ledger["refusals"].setdefault(day, {})
                for reason, count in counts.items():
                    target[reason] = target.get(reason, 0) + count

    def handle(self, request):
        # H4: the whole request runs under the ledger lock the operator CLIs
        # also take for their whole operation, so a CLI can never replace the
        # ledger between this request's reload check and its write (3.12).
        with LedgerLock(True):
            return self.handle_locked(request)

    def handle_locked(self, request):
        if not isinstance(request, dict) or request.get("verb") not in VERBS:
            return {"ok": False, "error": "unknown-verb"}
        verb = request["verb"]
        # H4: the operator CLIs (ledger-bootstrap, reconcile,
        # restore-checkpoint, confirm) replace ledger.json under a running
        # signer (3.12). Any request, status included, first reloads a ledger
        # that changed on disk, so a running signer never serves, or writes
        # back, a stale in-memory copy.
        if ledger_stamp() != self.stamp:
            self.reload_ledger()
            log("reloaded the ledger: it changed on disk (operator CLI)")
        if self.config is not None:
            try:
                self.config["epoch"] = load_config()["epoch"]
            except (OSError, ValueError):
                if verb != "status":
                    return {"ok": False, "error": "config-unavailable"}
                # An unreadable epoch is reported as unknown, never as the
                # copy read at startup: reconcile increments it (3.12 step 1).
                self.config["epoch"] = None
        if verb == "status":
            return status(self.config, self.ledger, self.ledger_ok, self.key_ready)
        working = json.loads(canonical(self.ledger))
        try:
            if not self.ledger_ok:
                raise Refused("ledger-integrity")
            if recovery_pending():
                raise Refused("recovery-unconfirmed")
            if self.config is None:
                raise Refused("config-unavailable")
            if signer_disabled():
                raise Refused("signer-disabled")
            if verb in ISSUING_VERBS:
                if not self.key_ready:
                    raise Refused("signer-key-unavailable")
                reply, changed = issue(self.config, working, request, verb)
            elif verb == "supersede":
                reply, changed = supersede(working, request)
            else:
                reply, changed = set_state(self.config, working, request, verb)
        except Refused as exc:
            reason = str(exc)
            log(f"refused {verb}: {reason}")
            refuse_count(self.ledger, reason)
            refuse_count({"refusals": self.refusal_pending}, reason)
            if not recovery_pending() and now() - self.last_refusal_flush >= REFUSAL_FLUSH_S:
                self.flush()
            return {"ok": False, "error": reason}
        if changed:
            # Written and fsynced before the reply leaves (3.7).
            try:
                write_ledger(working)
            except OSError as exc:
                log(f"ledger write failed: {type(exc).__name__}")
                return {"ok": False, "error": "ledger-write-failed"}
            self.ledger = working
            self.refusal_pending = {}
            self.stamp = ledger_stamp()
        return reply

    def flush(self):
        if not self.ledger_present:
            return
        # H4: nor a ledger whose chain does not verify, nor while a recovery
        # is pending: the staged ledger is what the confirmation checks.
        if not self.ledger_ok or recovery_pending():
            return
        try:
            write_ledger(self.ledger)
            self.refusal_pending = {}
            self.stamp = ledger_stamp()
            self.last_refusal_flush = now()
        except OSError as exc:
            log(f"refusal counter flush failed: {type(exc).__name__}")


# ---------------------------------------------------------------- socket --

def pidfd_pid(pidfd):
    with open(f"/proc/self/fdinfo/{pidfd}", "r", encoding="ascii") as handle:
        for line in handle:
            if line.startswith("Pid:"):
                return int(line.split()[1])
    return -1


def pidfd_alive(pidfd):
    try:
        signal.pidfd_send_signal(pidfd, 0)
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def cgroup_is_hub(pid, proc="/proc"):
    try:
        with open(f"{proc}/{pid}/cgroup", "r", encoding="ascii") as handle:
            lines = handle.read().splitlines()
    except (OSError, UnicodeDecodeError):
        return False
    return any(line.startswith("0::") and line.endswith(HUB_CGROUP_SUFFIX) for line in lines)


def peer_is_hub(conn):
    """uid 0 and the wins-hub.service cgroup. A pidfd pins the process (3.4)."""
    raw = conn.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, struct.calcsize("3i"))
    pid, uid, _gid = struct.unpack("3i", raw)
    if uid != 0 or pid <= 0:
        return False
    try:
        pidfd = conn.getsockopt(socket.SOL_SOCKET, SO_PEERPIDFD)
    except OSError as exc:
        if exc.errno != errno.ENOPROTOOPT:
            return False
        # Kernel without SO_PEERPIDFD (before 6.5): pid then /proc.
        return cgroup_is_hub(pid)
    if pidfd < 0:
        return False
    try:
        if pidfd_pid(pidfd) != pid:
            return False
        hub = cgroup_is_hub(pid)
        # Still the same live process after the read, so the pid was not reused.
        return hub and pidfd_alive(pidfd) and pidfd_pid(pidfd) == pid
    except (OSError, ValueError):
        return False
    finally:
        os.close(pidfd)


def read_request(conn):
    data = b""
    while b"\n" not in data and len(data) <= REQUEST_MAX_BYTES:
        chunk = conn.recv(REQUEST_MAX_BYTES + 1 - len(data))
        if not chunk:
            break
        data += chunk
    line, newline, rest = data.partition(b"\n")
    if not newline or rest or len(data) > REQUEST_MAX_BYTES:
        return None
    # Outside serve_connection's catch: a request nested too deep to parse
    # (RecursionError) is malformed, never the end of serve().
    try:
        return json.loads(line)
    except (ValueError, RecursionError):
        return None


def serve_connection(signer, conn):
    conn.settimeout(5)
    if not peer_is_hub(conn):
        log("refused a peer that is not wins-hub.service")
        reply = {"ok": False, "error": "peer-refused"}
    else:
        request = read_request(conn)
        try:
            reply = {"ok": False, "error": "request-malformed"} if request is None else signer.handle(request)
        except Exception as exc:  # noqa: BLE001 - one bad request never stops the signer
            log(f"request failed: {type(exc).__name__}")
            reply = {"ok": False, "error": "internal-error"}
    conn.sendall(canonical(reply) + b"\n")


def systemd_socket():
    if os.environ.get("LISTEN_PID") != str(os.getpid()) or os.environ.get("LISTEN_FDS") != "1":
        raise SystemExit("wins-descriptor-signer: expected one socket from wins-descriptor-signer.socket")
    return socket.socket(fileno=3)


def serve():
    os.umask(0o077)
    server = systemd_socket()
    signer = Signer()
    log("serving")
    # One connection at a time: every request for every slug is serialized,
    # which is the per-slug lock 3.13 asks for.
    while True:
        conn, _ = server.accept()
        with conn:
            try:
                serve_connection(signer, conn)
            except (OSError, subprocess.TimeoutExpired) as exc:
                log(f"connection error: {type(exc).__name__}")


# ---------------------------------------------------------------- digest --

def file_sha256(path):
    try:
        with open(path, "rb") as handle:
            return hashlib.sha256(handle.read()).hexdigest()
    except FileNotFoundError:
        return "absent"
    except OSError:
        return "unreadable"


def digest():
    """Checkpoint (3.12) and the daily digest (3.9). Reads the ledger only."""
    os.umask(0o077)
    checkpoint_path = os.path.join(STATE_DIR, "checkpoint.json")
    # H4: one ledger snapshot and the checkpoint written from it, both under
    # the exclusive lock, so no operator CLI replaces the ledger in between.
    with LedgerLock(True):
        try:
            ledger, raw = read_ledger()
            chain_ok = audit_chain_ok(ledger)
        except (ValueError, RecursionError) as exc:
            # Reported as BROKEN below; the last valid checkpoint is kept.
            log(f"ledger unavailable ({exc})")
            ledger, raw, chain_ok = empty_ledger(), b"", False
        ledger_sha256 = hashlib.sha256(raw).hexdigest()
        checkpoint = {"version": 1, "written_at": now(), "ledger_sha256": ledger_sha256,
                      "audit_head": ledger.get("audit_head", ""), "chain_ok": chain_ok, "ledger": ledger}
        # H4: nothing is checkpointed while a recovery is pending (3.12): the
        # staged ledger is not confirmed yet.
        if chain_ok and not recovery_pending():
            atomic_write(checkpoint_path, canonical(checkpoint), 0o600)
    # Every recorded event, every day: a late or missed run leaves no gap.
    spends = [
        {
            key: entry[key]
            for key in ("at", "event", "slug", "action", "seq", "identity_sha256")
            if key in entry
        }
        for entry in ledger.get("audit", [])
    ]
    slugs = {}
    for name, record in sorted(ledger.get("slugs", {}).items()):
        live = live_issuance(record)
        slugs[name] = {"state": record["state"], "highest_seq": record["floor"],
                       "live_seq": live["seq"] if live else None,
                       "not_after": live["not_after"] if live else None,
                       "identity_sha256": live["identity_sha256"] if live else None}
    day = time.strftime("%Y-%m-%d", time.gmtime(now()))
    report = {"version": 1, "date": day, "chain_ok": chain_ok,
              "audit_head": ledger.get("audit_head", ""), "ledger_sha256": ledger_sha256,
              "checkpoint_sha256": file_sha256(checkpoint_path),
              "hub_key_history_sha256": file_sha256(HUB_KEY_HISTORY),
              "operator_ssh_keys_sha256": file_sha256(OPERATOR_SSH_KEYS),
              "events": spends, "slugs": slugs,
              "refusals": ledger.get("refusals", {})}
    lines = [f"Wins VPN descriptor signer daily digest {day}",
             f"audit chain: {'verifies' if chain_ok else 'BROKEN'}; head {report['audit_head'] or '-'}",
             f"ledger sha256 {ledger_sha256}; checkpoint sha256 {report['checkpoint_sha256']}",
             f"hub key history sha256 {report['hub_key_history_sha256']}",
             f"operator allow-list sha256 {report['operator_ssh_keys_sha256']}", "",
             "Recorded events (compare each identity digest with the one the installer printed):"]
    lines += [f"  {item['at']} {item['event']} {item.get('slug', '-')} {item.get('action', '-')} "
              f"seq={item.get('seq', '-')} identity={item.get('identity_sha256', '-')}" for item in spends] or ["  none"]
    lines += ["", "Slugs:"]
    lines += [f"  {name} {info['state']} highest_seq={info['highest_seq']} live_seq={info['live_seq']} "
              f"not_after={info['not_after']} identity={info['identity_sha256']}" for name, info in slugs.items()] or ["  none"]
    lines += ["", "Refusals by day: " + json.dumps(report["refusals"], sort_keys=True)]
    atomic_write(os.path.join(DIGEST_DIR, "latest.json"), canonical(report) + b"\n", 0o644)
    atomic_write(os.path.join(DIGEST_DIR, "latest.txt"), ("\n".join(lines) + "\n").encode("utf-8"), 0o644)
    # A broken chain is reported in the digest, not by failing: the mail unit
    # requires this one, and a broken chain is what must reach the operator.
    log(f"digest written; chain {'ok' if chain_ok else 'BROKEN'}")
    return 0


# ---------------------------------------------------- operator root CLIs --
#
# ledger-bootstrap, reconcile, restore-checkpoint and confirm are OPERATOR
# ROOT CLIs (3.12). They are deliberately not socket verbs: the app cannot
# reach them, so a compromised app cannot replay bootstrap to pin an older
# validly signed identity and then renew it, and cannot grant or raise the
# recovery allowance. reconcile and restore-checkpoint leave RECOVERY-PENDING
# in the signer's config directory, and the signer refuses every change until
# the operator confirms. Every mode refuses to run as a non-root user.

SIGNER_USER = "wins-desc-signer"
RECONCILE_GAP = 1_000_000
DEFAULT_HUB_DB = "/root/vpn_auth/vpn_users.db"
DEFAULT_ENV_FILE = "/root/vpn_auth.env"
DEFAULT_DIGEST_FILE = "/var/lib/wins-descriptor-signer-digest/latest.json"


def cli_is_root():
    return os.geteuid() == 0


def cli_fail(message):
    sys.stderr.write(f"wins-descriptor-signer: {message}\n")
    return 2


def signer_user_ids():
    """(uid, gid) of the signer service user, or None. The operator CLIs
    refuse to write a ledger the signer service could not read."""
    try:
        entry = pwd.getpwnam(SIGNER_USER)
        return entry.pw_uid, entry.pw_gid
    except KeyError:
        return None


def cli_chown(fd, owner):
    """Hand an open file to its service user (the operator CLI runs as root).
    By descriptor: the signer user owns these directories, so a path could be
    swapped for a symlink between the file's creation and the chown."""
    os.fchown(fd, *owner)


def cli_install(path, blob, mode, owner):
    """Temp file, fsync, chown, rename, directory fsync: the ledger and the
    config files cross from the operator's root shell to the signer user
    without ever being readable by anyone else."""
    directory = os.path.dirname(path)
    fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=directory)
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, "wb") as handle:
            handle.write(blob)
            handle.flush()
            os.fsync(handle.fileno())
            cli_chown(handle.fileno(), owner)
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise
    fsync_dir(directory)


def install_ledger(ledger):
    """Install the ledger under the caller's lock, owned by the signer user."""
    ids = signer_user_ids()
    if ids is None:
        return cli_fail("the signer service user is missing; refusing to write a ledger it could not read")
    initialized = os.path.join(CONFIG_DIR, LEDGER_INITIALIZED_FILE)
    if not os.path.lexists(initialized):
        cli_install(initialized, b"1\n", 0o440, (0, ids[1]))
    cli_install(os.path.join(STATE_DIR, "ledger.json"), canonical(ledger), 0o600, ids)
    return 0


def bump_ticket_epoch():
    """3.12 step 1: increment the ticket epoch. Every ticket minted under an
    older epoch is refused, whether it was consumed or not."""
    try:
        current = int(read_config_file("ticket-epoch").strip())
    except (OSError, ValueError):
        return None
    ids = signer_user_ids()
    owner = (0, ids[1]) if ids is not None else (0, 0)
    cli_install(os.path.join(CONFIG_DIR, "ticket-epoch"), f"{current + 1}\n".encode("ascii"), 0o440, owner)
    return current + 1


def write_pending_marker(kind, ledger):
    """The gate for the ledger about to be installed. It names that ledger by
    digest, so the confirmation acts only on the staged recovery, and carries a
    random id the confirmation records in the ledger: an interrupted
    confirmation, run again, never grants the allowance twice."""
    ids = signer_user_ids()
    owner = (0, ids[1]) if ids is not None else (0, 0)
    blob = canonical({"kind": kind, "at": now(), "id": os.urandom(16).hex(),
                      "ledger_sha256": hashlib.sha256(canonical(ledger)).hexdigest()}) + b"\n"
    cli_install(os.path.join(CONFIG_DIR, RECOVERY_PENDING_FILE), blob, 0o440, owner)


def clear_pending_marker():
    try:
        os.unlink(os.path.join(CONFIG_DIR, RECOVERY_PENDING_FILE))
    except FileNotFoundError:
        pass
    fsync_dir(CONFIG_DIR)


def load_env_data(path):
    """Parse a KEY=VALUE environment file as data. Never sourced."""
    env = {}
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as handle:
            for raw in handle:
                line = raw.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                env[key.strip()] = value.strip().strip('"').strip("'")
    except OSError:
        return None
    return env


def ring_from_env(env):
    ring = {}
    for slot in SLOTS:
        encoded = (env or {}).get(f"WINN3_DESCRIPTOR_PUBKEY_{slot.upper()}", "")
        try:
            raw = base64.b64decode(encoded, validate=True) if encoded else b""
        except (binascii.Error, ValueError):
            raw = b""
        if len(raw) == 32:
            ring[slot] = raw
    return ring


def cli_verify_stored_descriptor(ring, slug, envelope_raw):
    """The stored descriptor, but only if it verifies (3.12 step 2). Returns
    (payload dict, payload bytes, signature) or None."""
    try:
        envelope = json.loads(envelope_raw)
        payload_bytes = base64.b64decode(envelope["payload"], validate=True)
        signature = base64.b64decode(envelope["sig"], validate=True)
        payload = json.loads(payload_bytes.decode("utf-8"))
    except (ValueError, KeyError, TypeError, UnicodeDecodeError, binascii.Error, RecursionError):
        return None
    if not isinstance(payload, dict) or payload.get("node") != slug:
        return None
    seq = payload.get("seq")
    if isinstance(seq, bool) or not isinstance(seq, int) or seq < 0:
        return None
    kid = payload.get("kid")
    raw = ring.get(kid) if isinstance(kid, str) else None
    if raw is None:
        return None
    if not ed25519_verify(raw, DESCRIPTOR_DOMAIN + b"\x00" + payload_bytes, signature):
        return None
    # The rebuilt issuance keeps the payload for renewal (3.13), so the fields
    # identity_sha256 reads must be present and shaped.
    if not all(isinstance(payload.get(name), str) for name in IDENTITY_DIGEST_FIELDS):
        return None
    if not isinstance(payload.get("admission_secret"), str):
        return None
    return payload, payload_bytes, signature


def collect_hub_state(db_path):
    """Read-only pass over the hub database: every slug's stored descriptor
    and retained admission sequences (3.12 step 4's known values). Every node
    slug is returned, including one with no v3 state: it may hold an allocated
    but unstored sequence, so reconciliation must still suspend it."""
    state = {}
    try:
        conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=10)
    except sqlite3.Error:
        return None
    try:
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT slug, winn3_descriptor_json, winn3_admission_json FROM nodes").fetchall()
    except sqlite3.Error:
        return None
    finally:
        conn.close()
    for row in rows:
        slug = row["slug"]
        if not isinstance(slug, str) or not SLUG_RE.fullmatch(slug):
            continue
        entry = {"descriptor": None, "sequences": set()}
        ledger = row["winn3_admission_json"]
        if isinstance(ledger, str) and ledger.strip():
            try:
                parsed = json.loads(ledger)
            except (ValueError, RecursionError):
                parsed = None
            if isinstance(parsed, dict):
                current = parsed.get("current")
                previous = parsed.get("previous")
                # These numbers are unsigned input from a database the app
                # can write. They only ever raise a floor, and a value above
                # the request bound would leave the slug unable to issue.
                for value in (parsed.get("sequence_floor"),
                              current.get("seq") if isinstance(current, dict) else None,
                              previous.get("seq") if isinstance(previous, dict) else None):
                    if isinstance(value, int) and not isinstance(value, bool) \
                            and 0 <= value <= SEQ_REQUEST_BOUND:
                        entry["sequences"].add(value)
        raw = row["winn3_descriptor_json"]
        if isinstance(raw, str) and raw.strip():
            entry["descriptor"] = raw
        state[slug] = entry
    return state


def collect_digest_state(digest_path):
    """Per-slug known sequences in the last daily digest (3.12 step 4). The
    digest is public: it carries no secret."""
    # An absent digest is an operator's known case. A digest that is present
    # and malformed is not: silently dropping it would lower a floor, so it is
    # refused (None) and the operator fixes or removes it by hand.
    try:
        with open(digest_path, "rb") as handle:
            report = json.loads(handle.read())
    except FileNotFoundError:
        return {}
    except (OSError, ValueError, RecursionError):
        return None
    slugs = report.get("slugs") if isinstance(report, dict) else None
    state = {}
    if not isinstance(slugs, dict):
        return None
    # The signer's own digest still runs when its ledger is missing or its
    # chain is broken (H1: it reports BROKEN, rc 0), and then lists no or
    # untrusted slugs. Read as evidence it would lower a floor, so it is
    # refused like a malformed one: the operator passes the last trusted
    # digest's values (--digest or --high-water) or moves this file aside.
    if report.get("chain_ok") is False:
        return None
    for slug, info in slugs.items():
        if not isinstance(slug, str) or not SLUG_RE.fullmatch(slug) or not isinstance(info, dict):
            return None
        seqs = set()
        for key in ("highest_seq", "live_seq"):
            value = info.get(key)
            if value is None or (value == -1 and not isinstance(value, bool)):
                continue
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                return None
            seqs.add(value)
        state[slug] = seqs
    return state


def collect_high_water(path):
    """The operator's recorded high-water mark: {"slug": highest sequence}.
    Optional; absent means the stored descriptor and the digest are the only
    known values. Returns None on a malformed file or entry: a value that is
    dropped silently would lower a floor."""
    if not path:
        return {}
    try:
        with open(path, "rb") as handle:
            data = json.loads(handle.read())
    except (OSError, ValueError, RecursionError):
        return None
    if not isinstance(data, dict):
        return None
    state = {}
    for slug, value in data.items():
        if not isinstance(slug, str) or not SLUG_RE.fullmatch(slug) \
                or not isinstance(value, int) or isinstance(value, bool) or value < 0:
            return None
        state[slug] = {value}
    return state


def ledger_is_lost():
    """True when the ledger is missing, unparseable, broken or empty: the only
    states the operator CLIs may replace. A healthy non-empty ledger is never
    touched by bootstrap, reconcile or restore. A ledger whose audit chain does
    not verify is unusable (the signer refuses every change on it), so it is
    recoverable, never a state the operator is stuck with."""
    ledger, _present = ledger_on_disk()
    if ledger is None or not audit_chain_ok(ledger):
        return True
    return not (ledger["slugs"] or ledger["nonces"] or ledger["audit"])


def build_reconciled_ledger(hub_state, digest_state, high_water, ring, t):
    """3.12 steps 2 to 5, fail-closed. Every slug is suspended (missing
    suspension state is treated as suspended); the pinned identity is rebuilt
    from the highest-sequence stored descriptor that verifies; every other
    known sequence is burned and can never be renewed; each floor is the
    maximum known value plus the fixed gap; every rate-limit window starts
    fully spent."""
    ledger = empty_ledger()
    # Marks a ledger rebuilt without a checkpoint: a slug it never recorded is
    # suspended and starts at the recovery gap (slug_record, issue).
    ledger["reconciled"] = True
    ledger["window_spends"] = [
        {"at": t, "kind": "identity", "count": MAX_NEW_IDENTITIES_PER_DAY},
        {"at": t, "kind": "signature", "count": MAX_SIGNATURES_PER_DAY},
    ]
    slugs = set(hub_state or {}) | set(digest_state or {}) | set(high_water or {})
    for slug in sorted(slugs):
        hub = (hub_state or {}).get(slug) or {"descriptor": None, "sequences": set()}
        known = set(hub["sequences"]) | (digest_state or {}).get(slug, set()) \
            | (high_water or {}).get(slug, set())
        verified = cli_verify_stored_descriptor(ring, slug, hub["descriptor"]) \
            if hub["descriptor"] else None
        live_seq = verified[0]["seq"] if verified else None
        if live_seq is not None:
            known.add(live_seq)
        identity_digest = None
        if verified is not None:
            try:
                identity_digest = identity_sha256(verified[0])
            except ValueError:
                # Ring-signed, but not a descriptor this signer minted: its
                # admission_secret is not the base64 of 64 ASCII hex bytes
                # (H4R-Q-SECRET). Its signed sequence stays known, so it still
                # sets the floor, and it is burned below like any other known
                # sequence: no live identity is rebuilt from it, and the slug
                # comes back only through a fresh ticketed identity.
                sys.stderr.write(f"wins-descriptor-signer: reconcile: {slug} seq {live_seq}: the stored "
                                 "descriptor verifies but its admission secret is malformed; "
                                 "burned, no live identity rebuilt\n")
                verified, live_seq = None, None
        record = {"state": "suspended", "floor": max(known, default=-1) + RECONCILE_GAP,
                  "presented_stored": -1, "issuances": []}
        if verified is not None:
            payload, payload_bytes, signature = verified
            record["issuances"].append({
                "key": f"{slug}|reconcile|-|{live_seq}", "verb": "reconcile", "kind": "identity",
                "seq": live_seq, "kid": str(payload.get("kid") or ""),
                "payload": b64(payload_bytes), "sig": b64(signature),
                "identity_sha256": identity_digest,
                "admission_gen": payload["admission_gen"] if isinstance(payload.get("admission_gen"), int) else 0,
                "issued_at": payload["iat"] if isinstance(payload.get("iat"), int) else t,
                "not_after": payload["not_after"] if isinstance(payload.get("not_after"), int) else t,
                # The authorizing ticket is lost with the ledger, so its
                # go_live and tier stay honestly unknown until the next
                # ticketed issuance records them.
                "generation": 0, "eps": -1, "go_live": None, "tier": None,
                "superseded": False, "ticket_action": "reconcile", "nonce": "", "recovery_allowance": False})
        for seq in sorted(known):
            if seq == live_seq:
                continue
            # A lower identity is recorded as superseded and can never be
            # renewed (3.12 step 2). issued_at 0 keeps it out of every rate
            # window, which the synthetic spends already cover.
            record["issuances"].append({
                "key": f"{slug}|reconcile|burned|{seq}", "verb": "reconcile", "kind": "burned",
                "seq": seq, "kid": "", "identity_sha256": "", "admission_gen": 0,
                "issued_at": 0, "not_after": 0, "generation": 0, "eps": -1,
                "go_live": None, "tier": None, "superseded": True,
                "ticket_action": "", "nonce": "", "recovery_allowance": False})
        ledger["slugs"][slug] = record
        ledger["window_spends"].append({"at": t, "slug": slug, "kind": "renewal", "count": 1})
    return ledger


def cli_ledger_bootstrap(args):
    if args:
        return cli_fail("ledger-bootstrap takes no arguments")
    with LedgerLock(True):
        # Only a missing or semantically empty ledger may be bootstrapped: a
        # non-empty or corrupt ledger is reconciled (3.12), never overwritten.
        ledger, present = ledger_on_disk()
        if recovery_pending() or (not present and os.path.lexists(
                os.path.join(CONFIG_DIR, LEDGER_INITIALIZED_FILE))):
            return cli_fail("ledger-bootstrap: a ledger was installed here before and is lost, or a "
                            "recovery is pending; reconcile or restore it (3.12), bootstrap is only "
                            "the first initialization")
        if present and (ledger is None or not audit_chain_ok(ledger) or ledger.get("reconciled")
                        or ledger["slugs"] or ledger["nonces"] or ledger["audit"]):
            return cli_fail("ledger-bootstrap: the ledger is not empty; bootstrap runs only "
                            "against an empty ledger (3.12)")
        rc = install_ledger(empty_ledger())
    if rc:
        return rc
    print("wins-descriptor-signer: initial empty ledger created (ledger-bootstrap, 3.12)")
    return 0


def cli_reconcile(args):
    db_path = DEFAULT_HUB_DB
    digest_path = DEFAULT_DIGEST_FILE
    high_water_path = ""
    env_path = DEFAULT_ENV_FILE
    i = 0
    while i < len(args):
        if args[i] == "--db" and i + 1 < len(args):
            db_path = args[i + 1]
            i += 2
        elif args[i] == "--digest" and i + 1 < len(args):
            digest_path = args[i + 1]
            i += 2
        elif args[i] == "--high-water" and i + 1 < len(args):
            high_water_path = args[i + 1]
            i += 2
        elif args[i] == "--env-file" and i + 1 < len(args):
            env_path = args[i + 1]
            i += 2
        else:
            return cli_fail(f"reconcile: unknown argument {args[i]!r}")
    if os.path.lexists(os.path.join(STATE_DIR, "checkpoint.json")):
        return cli_fail("reconcile: a checkpoint exists; restore it (restore-checkpoint), or "
                        "remove an unusable one by hand, before reconciling")
    ring = ring_from_env(load_env_data(env_path))
    if not ring:
        return cli_fail(f"reconcile: no descriptor verification keys in {env_path}")
    hub_state = collect_hub_state(db_path)
    if hub_state is None:
        return cli_fail(f"reconcile: cannot read the hub database at {db_path}")
    high_water = collect_high_water(high_water_path)
    if high_water is None:
        return cli_fail(f"reconcile: {high_water_path} is not a JSON object of slug to sequence")
    digest_state = collect_digest_state(digest_path)
    if digest_state is None:
        return cli_fail(f"reconcile: {digest_path} is present but is not a valid daily digest, or "
                        "was written from a missing or broken ledger (chain_ok false); pass the last "
                        "trusted digest with --digest or its values with --high-water, or move this "
                        "one aside by hand")
    with LedgerLock(True):
        if not ledger_is_lost():
            return cli_fail("reconcile: the ledger is not lost; restore a checkpoint or investigate")
        ledger = build_reconciled_ledger(hub_state, digest_state, high_water, ring, now())
        audit(ledger, "reconcile", slugs=len(ledger["slugs"]))
        epoch = bump_ticket_epoch()
        if epoch is None:
            return cli_fail("reconcile: the ticket epoch is missing or malformed; fix it by hand")
        # The gate goes up before the ledger it guards is installed, inside the
        # lock: a crash between the two leaves a gated signer, never an
        # ungated reconciled ledger (3.12 step 6).
        write_pending_marker("reconcile", ledger)
        rc = install_ledger(ledger)
        if rc:
            return rc
    print(f"wins-descriptor-signer: reconciled {len(ledger['slugs'])} slug(s): every slug suspended, "
          f"floors at the maximum known sequence + {RECONCILE_GAP}, ticket epoch now {epoch}")
    print("wins-descriptor-signer: the signer refuses every change until the operator confirms (confirm)")
    return 0


def cli_restore_checkpoint(args):
    if args:
        return cli_fail("restore-checkpoint takes no arguments")
    with LedgerLock(True):
        if not ledger_is_lost():
            return cli_fail("restore-checkpoint: the ledger is not lost; reconcile or investigate instead")
        try:
            with open(os.path.join(STATE_DIR, "checkpoint.json"), "rb") as handle:
                checkpoint = json.loads(handle.read())
        except (OSError, ValueError, RecursionError):
            return cli_fail("restore-checkpoint: no readable checkpoint.json in the signer's state directory")
        if not isinstance(checkpoint, dict) or checkpoint.get("version") != 1 \
                or not isinstance(checkpoint.get("ledger"), dict):
            return cli_fail("restore-checkpoint: the checkpoint is malformed")
        ledger = checkpoint["ledger"]
        if hashlib.sha256(canonical(ledger)).hexdigest() != checkpoint.get("ledger_sha256") \
                or ledger.get("audit_head") != checkpoint.get("audit_head") \
                or not audit_chain_ok(ledger):
            return cli_fail("restore-checkpoint: the checkpoint does not verify; it is not restored")
        write_pending_marker("restore", ledger)
        rc = install_ledger(ledger)
        if rc:
            return rc
    print(f"wins-descriptor-signer: checkpoint restored ({len(ledger['slugs'])} slug(s)); "
          "the signer refuses every change until the operator confirms (confirm)")
    return 0


def cli_confirm(args):
    allowance = None
    i = 0
    while i < len(args):
        if args[i] == "--allowance" and i + 1 < len(args):
            raw = args[i + 1]
            i += 2
            if not raw.isascii() or not raw.isdigit() or (len(raw) > 1 and raw.startswith("0")):
                return cli_fail("confirm: --allowance must be a whole number of new identities")
            if len(raw) > 4:
                # Above the cap whatever the ledger holds; int() refuses 4300+ digits.
                return cli_fail(f"confirm: the allowance exceeds the {MAX_SLUGS}-slug cap (3.8)")
            allowance = int(raw)
        else:
            return cli_fail(f"confirm: unknown argument {args[i]!r}")
    with LedgerLock(True):
        if not recovery_pending():
            return cli_fail("confirm: no recovery is pending")
        try:
            pending = json.loads(read_config_file(RECOVERY_PENDING_FILE))
        except (OSError, ValueError, RecursionError):
            return cli_fail("confirm: the recovery marker is unreadable")
        if not isinstance(pending, dict) or not isinstance(pending.get("id"), str) \
                or not isinstance(pending.get("ledger_sha256"), str):
            return cli_fail("confirm: the recovery marker is malformed")
        ledger, _present = ledger_on_disk()
        if ledger is None or not audit_chain_ok(ledger):
            return cli_fail("confirm: the ledger is missing or does not verify; reconcile again")
        if ledger.get("recovery_confirmation") == pending["id"]:
            # A confirmation that installed the ledger and was interrupted
            # before the gate came down: finish it, grant nothing twice.
            clear_pending_marker()
            print("wins-descriptor-signer: recovery was already confirmed; the signer serves again")
            return 0
        if hashlib.sha256(canonical(ledger)).hexdigest() != pending["ledger_sha256"]:
            return cli_fail("confirm: the ledger is not the staged recovery; reconcile again")
        if allowance is not None and allowance > len(ledger["slugs"]):
            return cli_fail(f"confirm: an allowance of {allowance} exceeds the ledger's "
                            f"{len(ledger['slugs'])} slug(s) (3.12 step 6)")
        if allowance is not None and allowance > MAX_SLUGS:
            return cli_fail(f"confirm: an allowance of {allowance} exceeds the {MAX_SLUGS}-slug cap (3.8)")
        if allowance is not None:
            # H1's field: the signer spends it one unit per ticketed identity
            # issuance and refuses a value outside 0..MAX_SLUGS (3.8, 3.12).
            ledger["recovery_allowance_remaining"] = allowance
        ledger["recovery_confirmation"] = pending["id"]
        audit(ledger, "recovery-confirm", allowance=allowance)
        rc = install_ledger(ledger)
        if rc:
            return rc
        clear_pending_marker()
    if allowance:
        print(f"wins-descriptor-signer: recovery confirmed; one-time allowance of "
              f"{allowance} new identities granted")
    else:
        print("wins-descriptor-signer: recovery confirmed; the signer serves again")
    return 0


def operator_cli(mode, args):
    """The operator root CLIs (3.12). Never on the app socket: no verb, no
    grant and no bootstrap is reachable from wins-hub.service."""
    if not cli_is_root():
        return cli_fail(f"{mode}: operator root only")
    # The CLIs run with the signer service stopped, and WORK_DIR is the
    # service's RuntimeDirectory, which then does not exist: verifying a stored
    # descriptor needs a work directory of the CLI's own.
    global WORK_DIR
    previous_work_dir = WORK_DIR
    try:
        with tempfile.TemporaryDirectory(prefix="wins-descriptor-operator-") as work:
            WORK_DIR = work
            if mode == "ledger-bootstrap":
                return cli_ledger_bootstrap(args)
            if mode == "reconcile":
                return cli_reconcile(args)
            if mode == "restore-checkpoint":
                return cli_restore_checkpoint(args)
            if mode == "confirm":
                return cli_confirm(args)
            return cli_fail(f"unknown operator mode {mode!r}")
    finally:
        WORK_DIR = previous_work_dir


def main(argv):
    if argv[1:] == ["serve"]:
        return serve()
    if argv[1:] == ["digest"]:
        return digest()
    if len(argv) >= 2 and argv[1] in ("ledger-bootstrap", "reconcile", "restore-checkpoint", "confirm"):
        return operator_cli(argv[1], argv[2:])
    sys.stderr.write("usage: wins_descriptor_signer.py serve|digest|ledger-bootstrap|"
                     "reconcile [--db P] [--digest P] [--high-water P] [--env-file P]|"
                     "restore-checkpoint|confirm [--allowance N]\n"
                     "The operator modes run as root only and are never on the app socket (3.12).\n")
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))
DESCSIGNEREOF
  chown root:root /usr/local/lib/wins_descriptor_signer.py
  chmod 0644 /usr/local/lib/wins_descriptor_signer.py
  cat > /usr/local/lib/wins_descriptor_signer_digest_mail.py <<'DESCDIGESTMAILEOF'
#!/usr/bin/env python3
"""Mail the descriptor signer's daily digest (design v17 3.9, 3.12).

The signer has no network, so it only writes the digest. This sender reads
that text and the hub's SMTP settings as data (KEY=VALUE, nothing executed)
and mails it to SECURITY_ALERT_EMAIL. A day with no digest mail is itself a
signal the operator watches for.
"""
import re
import smtplib
import ssl
import sys
from email.mime.text import MIMEText

ENV_FILE = "/root/vpn_auth.env"
DIGEST = "/var/lib/wins-descriptor-signer-digest/latest.txt"
KEYS = ("SMTP_SERVER", "SMTP_PORT", "SMTP_USER", "SMTP_PASS", "EMAIL_SENDER", "SECURITY_ALERT_EMAIL")


def load_env(path):
    env = {}
    quote_escape = "'\"'\"'"
    with open(path, "r", encoding="utf-8") as handle:
        for raw in handle:
            line = raw.rstrip("\r\n")
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            match = re.fullmatch(r"([A-Z][A-Z0-9_]*)='(.*)'", line)
            if match is None:
                continue
            key, body = match.groups()
            if key not in KEYS:
                continue
            if "'" in body.replace(quote_escape, ""):
                raise ValueError("malformed quoted SMTP setting")
            env[key] = body.replace(quote_escape, "'")
    return env


def main():
    env = load_env(ENV_FILE)
    with open(DIGEST, "r", encoding="utf-8") as handle:
        body = handle.read()
    if not env.get("SMTP_USER") or not env.get("SMTP_PASS"):
        print("wins-descriptor-signer-digest-mail: SMTP is not configured; digest not sent", flush=True)
        return 1
    message = MIMEText(body, "plain", "utf-8")
    message["Subject"] = "Wins VPN descriptor signer daily digest"
    message["From"] = env.get("EMAIL_SENDER") or "support@winsvpn.org"
    message["To"] = env.get("SECURITY_ALERT_EMAIL") or "security@winsvpn.com"
    port = int(env.get("SMTP_PORT") or "2525")
    with smtplib.SMTP(env.get("SMTP_SERVER") or "mail.smtp2go.com", port, timeout=20) as smtp:
        smtp.ehlo()
        smtp.starttls(context=ssl.create_default_context())
        smtp.ehlo()
        smtp.login(env["SMTP_USER"], env["SMTP_PASS"])
        smtp.send_message(message)
    print("wins-descriptor-signer-digest-mail: digest sent", flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())
DESCDIGESTMAILEOF
  chown root:root /usr/local/lib/wins_descriptor_signer_digest_mail.py
  chmod 0644 /usr/local/lib/wins_descriptor_signer_digest_mail.py
}

# The socket is made by PID 1, 0660 wins-desc-signer:root, so only uid 0 or
# group root can connect; the signer then admits only wins-hub.service (3.4).
# The service's own runtime directory is the work subdirectory, which holds
# openssl's seekable temp files; the parent stays put across signer restarts,
# because wins-hub.service binds it into its private /run.
write_descriptor_signer_units() {
  cat > /etc/systemd/system/wins-descriptor-signer.socket <<'EOF'
[Unit]
Description=Wins VPN descriptor signer socket (wins-hub.service only)
After=systemd-tmpfiles-setup.service
Before=wins-hub.service

[Socket]
ListenStream=/run/wins-descriptor-signer/sock
SocketUser=wins-desc-signer
SocketGroup=root
SocketMode=0660
DirectoryMode=0750
Accept=no

[Install]
WantedBy=sockets.target
EOF
  cat > /etc/systemd/system/wins-descriptor-signer.service <<'EOF'
[Unit]
Description=Wins VPN descriptor signer (policy-bound online g slot)
Requires=wins-descriptor-signer.socket
After=wins-descriptor-signer.socket

[Service]
Type=simple
User=wins-desc-signer
Group=wins-desc-signer
ExecStart=/usr/bin/python3 -I /usr/local/lib/wins_descriptor_signer.py serve
Restart=on-failure
RestartSec=3
UMask=0077
StateDirectory=wins-descriptor-signer
StateDirectoryMode=0700
RuntimeDirectory=wins-descriptor-signer/work
RuntimeDirectoryMode=0700
# /etc/winsvpn is 0700 root once the installer finishes (mark_control_role,
# resolve_backup_host_id, write_hub_recovery_contract), which this user cannot
# traverse. PID 1 binds the signer's own directory into an empty /etc/winsvpn.
TemporaryFileSystem=/etc/winsvpn:ro
BindReadOnlyPaths=/etc/winsvpn/descriptor-signer
PrivateNetwork=yes
IPAddressDeny=any
RestrictAddressFamilies=AF_UNIX
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
ProtectKernelLogs=true
ProtectClock=true
ProtectHostname=true
RestrictSUIDSGID=true
RestrictRealtime=true
RestrictNamespaces=true
MemoryDenyWriteExecute=true
CapabilityBoundingSet=
AmbientCapabilities=
SystemCallArchitectures=native
LockPersonality=true
LimitCORE=0
EOF
  cat > /etc/systemd/system/wins-descriptor-signer-digest.service <<'EOF'
[Unit]
Description=Wins VPN descriptor signer checkpoint and daily digest

[Service]
Type=oneshot
User=wins-desc-signer
Group=wins-desc-signer
ExecStart=/usr/bin/python3 -I /usr/local/lib/wins_descriptor_signer.py digest
UMask=0077
StateDirectory=wins-descriptor-signer
StateDirectoryMode=0700
ReadWritePaths=/var/lib/wins-descriptor-signer-digest
# Same reason as the signer unit: only the two public files the digest hashes,
# plus the recovery marker alone (3.12: nothing is checkpointed while a
# recovery is pending; the key beside it stays out of this namespace).
TemporaryFileSystem=/etc/winsvpn:ro
BindReadOnlyPaths=-/etc/winsvpn/hub-key-history -/etc/winsvpn/operator-ssh-keys -/etc/winsvpn/descriptor-signer/RECOVERY-PENDING
PrivateNetwork=yes
IPAddressDeny=any
RestrictAddressFamilies=AF_UNIX
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
ProtectKernelLogs=true
ProtectClock=true
ProtectHostname=true
RestrictSUIDSGID=true
RestrictRealtime=true
RestrictNamespaces=true
MemoryDenyWriteExecute=true
CapabilityBoundingSet=
AmbientCapabilities=
SystemCallArchitectures=native
LockPersonality=true
LimitCORE=0
EOF
  cat > /etc/systemd/system/wins-descriptor-signer-digest-mail.service <<'EOF'
[Unit]
Description=Mail the Wins VPN descriptor signer daily digest
Requires=wins-descriptor-signer-digest.service
After=wins-descriptor-signer-digest.service network-online.target

[Service]
Type=oneshot
User=root
ExecStart=/usr/bin/python3 -I /usr/local/lib/wins_descriptor_signer_digest_mail.py
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=read-only
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
RestrictNamespaces=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
CapabilityBoundingSet=
AmbientCapabilities=
SystemCallArchitectures=native
LockPersonality=true
LimitCORE=0
EOF
  cat > /etc/systemd/system/wins-descriptor-signer-digest.timer <<'EOF'
[Unit]
Description=Daily Wins VPN descriptor signer digest

[Timer]
OnCalendar=*-*-* 05:45:00
RandomizedDelaySec=10m
Persistent=true
Unit=wins-descriptor-signer-digest-mail.service

[Install]
WantedBy=timers.target
EOF
  systemctl daemon-reload
}

# signer.json and ticket-epoch: root-owned, readable by the signer's group,
# and unreachable from the hub app. The epoch is only ever created here; the
# operator's reconciliation CLI (3.12) is what increments it.
write_descriptor_signer_config() {
  local slot pub t1 tmp
  slot="$(descriptor_signer_active_slot)" || return 1
  pub="$(winn3_descriptor_ring_pinned_pubkey "${slot}")" || return 1
  t1="$(descriptor_signer_ticket_pubkey)" || return 1
  tmp="$(mktemp "${DESCRIPTOR_SIGNER_CONFIG_DIR}/.signer.json.XXXXXX")" || return 1
  printf '{"active_slot":"%s","active_slot_pubkey":"%s","ticket_pubkey_t1":"%s"}\n' \
    "${slot}" "${pub}" "${t1}" > "${tmp}"
  chown "root:${DESCRIPTOR_SIGNER_USER}" "${tmp}" && chmod 0440 "${tmp}" \
    && mv -f -- "${tmp}" "${DESCRIPTOR_SIGNER_CONFIG_DIR}/signer.json" || {
    rm -f -- "${tmp}"
    err "Could not write ${DESCRIPTOR_SIGNER_CONFIG_DIR}/signer.json."
    return 1
  }
  if [[ ! -e "${DESCRIPTOR_SIGNER_CONFIG_DIR}/ticket-epoch" ]]; then
    tmp="$(mktemp "${DESCRIPTOR_SIGNER_CONFIG_DIR}/.ticket-epoch.XXXXXX")" || return 1
    printf '1\n' > "${tmp}"
    chown "root:${DESCRIPTOR_SIGNER_USER}" "${tmp}" && chmod 0440 "${tmp}" \
      && mv -f -- "${tmp}" "${DESCRIPTOR_SIGNER_CONFIG_DIR}/ticket-epoch" || {
      rm -f -- "${tmp}"
      err "Could not create ${DESCRIPTOR_SIGNER_CONFIG_DIR}/ticket-epoch."
      return 1
    }
  fi
  [[ "$(cat "${DESCRIPTOR_SIGNER_CONFIG_DIR}/ticket-epoch")" =~ ^[0-9]+$ ]] || {
    err "${DESCRIPTOR_SIGNER_CONFIG_DIR}/ticket-epoch is not a whole number; fix it by hand."
    return 1
  }
}

# Base64 of the DER SubjectPublicKeyInfo of a private key file. openssl reads
# the key; nothing here prints or copies it.
descriptor_signer_key_spki_b64() {
  openssl pkey -in "$1" -pubout -outform DER 2>/dev/null | openssl base64 -A
}

# 3.10: the injected key's public half must equal the active slot's pinned
# constant, or nothing is placed. The secret variable is scrubbed whatever the
# outcome. DESCRIPTOR_SIGNER_KEY_READY says whether a matching key is in place.
DESCRIPTOR_SIGNER_KEY_READY=0
provision_descriptor_signer_key() {
  local slot pin dest tmpdir rc=0 owner
  DESCRIPTOR_SIGNER_KEY_READY=0
  # The operator-intent capture (IA-CP-01) may hold its own copy of the value.
  unset 'WINS_OPERATOR_INTENT_PENDING[WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64]'
  unset 'WINS_OPERATOR_INTENT_OWNED[WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64]'
  slot="$(descriptor_signer_active_slot)" || { unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64; return 1; }
  pin="$(winn3_descriptor_ring_pinned_pubkey "${slot}")" || {
    unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
    return 1
  }
  dest="${DESCRIPTOR_SIGNER_CONFIG_DIR}/${slot}.ed25519.pem"
  if ! descriptor_signer_config_dir_in_place; then
    if [[ -n "${WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64:-}" ]]; then
      unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
      err "${DESCRIPTOR_SIGNER_CONFIG_DIR} resolves elsewhere (partial vault?). The signer key was not placed."
      return 1
    fi
    warn "${DESCRIPTOR_SIGNER_CONFIG_DIR} resolves elsewhere (partial vault?); automatic signing stays off."
    return 0
  fi
  if [[ -n "${WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64:-}" ]] && ! descriptor_signer_key_route_ok; then
    unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
    err "WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64 is accepted only from ${DESCRIPTOR_SIGNER_INPUT_DIR}/secrets.env (root 0600, run with WINS_SECRETS_FILE=${DESCRIPTOR_SIGNER_INPUT_DIR}/secrets.env), never from the defaults file or another secrets file, which wins-hub.service can read, nor from the process environment. Nothing was placed."
    return 1
  fi
  if [[ -n "${WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64:-}" ]]; then
    export -n WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
    tmpdir="$(mktemp -d "${DESCRIPTOR_SIGNER_INJECT_TMPDIR:-/run}/wins-desc-signer-key.XXXXXX")" || {
      unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
      err "Could not create a private directory for the signer key."
      return 1
    }
    chmod 0700 "${tmpdir}"
    ( umask 077 && printf '%s' "${WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64}" \
        | openssl base64 -d -A > "${tmpdir}/key.pem" ) || rc=1
    unset WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64
    if (( rc == 0 )) && [[ "$(descriptor_signer_key_spki_b64 "${tmpdir}/key.pem")" == "${DESCRIPTOR_SIGNER_SPKI_PREFIX_B64}${pin}" ]]; then
      install -o "${DESCRIPTOR_SIGNER_USER}" -g "${DESCRIPTOR_SIGNER_USER}" -m 0400 \
        "${tmpdir}/key.pem" "${DESCRIPTOR_SIGNER_CONFIG_DIR}/.${slot}.ed25519.pem.new" \
        && mv -f -- "${DESCRIPTOR_SIGNER_CONFIG_DIR}/.${slot}.ed25519.pem.new" "${dest}" || rc=1
    else
      rc=2
    fi
    if command -v shred >/dev/null 2>&1; then
      shred -u -- "${tmpdir}/key.pem" 2>/dev/null || rm -f -- "${tmpdir}/key.pem"
    else
      rm -f -- "${tmpdir}/key.pem"
    fi
    rm -rf -- "${tmpdir}"
    if (( rc == 2 )); then
      err "The injected descriptor signer key is not slot ${slot}'s pinned key (or is not an Ed25519 private key). Nothing was placed."
      return 1
    fi
    (( rc == 0 )) || { err "Could not place the descriptor signer key."; return 1; }
    log "Placed the ${slot} descriptor signer key (public half matches the pinned ring)."
  fi
  if [[ ! -e "${dest}" && ! -L "${dest}" ]]; then
    warn "No ${slot} descriptor signer key on this hub; automatic signing stays off until WINN3_DESCRIPTOR_SIGNER_KEY_PEM_B64 is injected (through ${DESCRIPTOR_SIGNER_INPUT_DIR}/secrets.env)."
    return 0
  fi
  owner="$(stat -c '%U:%a' "${dest}" 2>/dev/null || true)"
  if [[ -L "${dest}" || ! -f "${dest}" || "${owner}" != "${DESCRIPTOR_SIGNER_USER}:400" ]]; then
    err "${dest} must be a regular file owned by ${DESCRIPTOR_SIGNER_USER} with mode 0400 (got ${owner:-unreadable}). Fix it by hand; it was not changed."
    return 1
  fi
  if [[ "$(descriptor_signer_key_spki_b64 "${dest}")" != "${DESCRIPTOR_SIGNER_SPKI_PREFIX_B64}${pin}" ]]; then
    err "${dest} does not match slot ${slot}'s pinned public key. Signing stays off; it was not changed."
    return 1
  fi
  DESCRIPTOR_SIGNER_KEY_READY=1
}

start_descriptor_signer() {
  if (( DESCRIPTOR_SIGNER_KEY_READY )); then
    systemctl enable --now wins-descriptor-signer.socket
    systemctl restart wins-descriptor-signer.service
    systemctl enable --now wins-descriptor-signer-digest.timer
    # Fleet reset TP-H4: the signer answers ledger-missing to every sign,
    # renew and rekey until root installs a ledger, and no step of this
    # installer does that. Name the one command that applies.
    if [[ ! -e "${DESCRIPTOR_SIGNER_STATE_DIR}/ledger.json" ]]; then
      if [[ -e "${DESCRIPTOR_SIGNER_CONFIG_DIR}/LEDGER-INITIALIZED" ]]; then
        warn "The descriptor signer's ledger was installed on this hub and is now missing: every sign, renew and rekey answers ledger-missing. Restore it as root with"
        warn "  python3 -I /usr/local/lib/wins_descriptor_signer.py restore-checkpoint   (a checkpoint exists), or"
        warn "  python3 -I /usr/local/lib/wins_descriptor_signer.py reconcile            (no checkpoint)"
        warn "then 'confirm'. Never ledger-bootstrap: it refuses a ledger that was installed before."
      else
        warn "The descriptor signer key is in place but no ledger is installed: every sign, renew and rekey answers ledger-missing until root runs ONE of"
        warn "  python3 -I /usr/local/lib/wins_descriptor_signer.py ledger-bootstrap   (the first signer this hub, and its descriptors, ever had)"
        warn "  python3 -I /usr/local/lib/wins_descriptor_signer.py reconcile          (a hub rebuilt after its signer had already signed; then 'confirm')"
      fi
    fi
  else
    systemctl disable --now wins-descriptor-signer.socket wins-descriptor-signer.service \
      wins-descriptor-signer-digest.timer >/dev/null 2>&1 || true
  fi
}
# --- end descriptor signer ---

write_systemd() {
  local bind_host="0.0.0.0"
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
    bind_host="127.0.0.1"
  fi
  require_hub_resolver_config_bindable || return 1
  # systemd validates ReadWritePaths before ExecStart, so create every writable
  # exception before the hardened unit is started for the first time.
  # H0 (D3): /var/lib/wins-hub-ssh holds the app's own SSH working files; root's
  # /root/.ssh is no longer in the hub's writable set.
  install -d -m 700 "${APP_DIR}" /var/lib/wins-hub-ssh /var/lib/wins-security-alerts /var/log/winsvpn
  install -d -m 0755 -o root -g root /var/lib/wins-canary-results
  install -d -m 0700 -o root -g root /var/lib/wins-canary-requests
  # H1: the signer user owns the runtime directory tmpfiles creates below.
  write_descriptor_signer_account || return 1
  write_hub_runtime_dirs
  write_hub_spa_window_helper
  write_site_ai_tunnel_account
  write_hub_logrotate
  write_descriptor_signer_program
  write_descriptor_signer_units
  write_descriptor_signer_config || return 1
  # The hub holds NO announcement signing key (Fable 5.1 ruling 2026-09-29,
  # IA-CP-06): announcements are signed offline by
  # tools/winn3_sign_announcement.py and only VERIFIED here, against the
  # ANNOUNCE_PUBKEY_A1..A3 public keys write_env() puts in ${ENV_FILE}. Retire
  # the old key home and LoadCredential drop-in on hosts that still carry them.
  retire_hub_announce_signing_home || return 1
  cat > "${SERVICE_FILE}" <<EOF
[Unit]
Description=Wins VPN Enterprise Hub
After=network-online.target
Wants=network-online.target

[Service]
User=root
UMask=0077
WorkingDirectory=${APP_DIR}
EnvironmentFile=${ENV_FILE}
Environment=OTEL_SDK_DISABLED=true
# WINN3_DESCRIPTOR_PUBKEY_G1 and WINN3_INNER_POOL_CIDR are written into THIS
# file by write_env() -> write_winn3_runtime_env(). Not into
# ${LEGACY_ENV_FILE} as the sole copy, and not into /etc/winn/server.env.
# Announcements are signed OFFLINE; this unit loads no announcement signing
# credential. ANNOUNCE_PUBKEY_A1..A3 (public) are written into the file above.
# This unit loads no DESCRIPTOR signing credential either: the active slot's
# descriptor key is held by the separate wins-descriptor-signer service, and
# the app cannot read or copy that key. The app asks the signer to sign over
# the signer socket. New or changed identities require the matching unused
# t1 ticket and verification of the node's signed identity. Renewal uses the
# retained identity within its renewal window and per-slug limit. Normal
# fleet quotas apply except for ticketed recovery-allowance issuances.
ExecStart=${VENV_DIR}/bin/python -m uvicorn main:app --host ${bind_host} --port 8000 --no-access-log
Restart=always
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=read-only
# H0 (D3): root's /root/.ssh is not writable here. The app's own SSH working
# files are in /var/lib/wins-hub-ssh, and the only authorized keys file it
# writes is the non-root site-AI forwarding account's.
ReadWritePaths=${APP_DIR} /var/lib/wins-hub-ssh /var/lib/wins-site-ai-tunnel /var/lib/wins-security-alerts /var/log/winsvpn
# A read-only mount inside APP_DIR protects executed dependencies and cannot
# be renamed or removed from inside the app's mount namespace.
ReadOnlyPaths=${VENV_DIR}
# The same for the hub code itself: the app cannot unlink main.py and plant a
# link at its name for the next installer run to write the hub code through.
ReadOnlyPaths=${APP_DIR}/main.py
ReadOnlyPaths=/var/lib/wins-canary-results
ReadWritePaths=/var/lib/wins-canary-requests
# H1 (3.4): a second barrier behind the signer's own file modes. The app can
# neither read the signer key, config and ticket epoch nor its ledger.
InaccessiblePaths=/etc/winsvpn/descriptor-signer /var/lib/wins-descriptor-signer
InaccessiblePaths=/etc/wins-descriptor-signer-input
# H0 (D1, D2): an empty, read-only /run. Only the runtime endpoints the app
# uses are bound back in, read-only: the Litestream control socket (durability
# barrier), the SPA helper socket, and the resolver file /etc/resolv.conf
# points to. The service manager's private socket, the system bus and every
# other broker socket under /run stay unreachable. H1: the descriptor signer's
# socket directory is bound too; the signer admits only this unit's cgroup.
TemporaryFileSystem=/run:ro
BindReadOnlyPaths=/run/litestream /run/wins-hub-spa-window /run/wins-descriptor-signer
BindReadOnlyPaths=-/run/systemd/resolve/stub-resolv.conf -/run/systemd/resolve/resolv.conf
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
ProtectKernelLogs=true
ProtectClock=true
ProtectHostname=true
RestrictSUIDSGID=true
RestrictRealtime=true
RestrictNamespaces=true
MemoryDenyWriteExecute=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6 AF_NETLINK
# H0 (D4): no capability. The SPA firewall window, the app's only use of one,
# is in wins-hub-spa-window.service.
CapabilityBoundingSet=
AmbientCapabilities=
SystemCallArchitectures=native
TasksMax=256
LockPersonality=true
# F-11: this process holds the account database, every hub secret and every
# live session in memory. A core dump of it is a verbatim copy of all of that,
# written outside every retention window this system enforces. Explicit here as
# well as in DefaultLimitCORE so the guarantee is auditable on the unit itself.
LimitCORE=0

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable --now wins-hub.service
  systemctl restart wins-hub.service
  # H1: the key is placed only now, with the hardened hub unit above in force
  # (H0 is a hard predecessor of key placement, design 3.2).
  provision_descriptor_signer_key || return 1
  start_descriptor_signer
}

sshd_effective_value_is() {
  local effective="$1" option="$2" accepted="$3" actual candidate
  local -a candidates
  actual="$(awk -v key="${option}" '$1 == key {$1=""; sub(/^[[:space:]]+/, ""); value=(value == "" ? $0 : value " " $0)} END {print value}' <<<"${effective}")"
  IFS='|' read -r -a candidates <<<"${accepted}"
  for candidate in "${candidates[@]}"; do
    [[ "${actual}" == "${candidate}" ]] && return 0
  done
  err "Effective sshd option ${option}=${actual:-<missing>}; expected ${accepted}."
  return 1
}

ssh_recovery_state_file="/etc/winsvpn/ssh-recovery-state"
ssh_recovery_disable_helper="/usr/local/sbin/winsvpn-disable-ssh-password-recovery"
ssh_recovery_service="/etc/systemd/system/winsvpn-disable-ssh-password-recovery.service"
ssh_recovery_timer="/etc/systemd/system/winsvpn-disable-ssh-password-recovery.timer"

ensure_ssh_recovery_account() {
  local account="$1" password="$2"
  if ! id -u "${account}" >/dev/null 2>&1; then
    useradd --create-home --shell /bin/bash \
      --comment "Win's VPN temporary SSH password-recovery account" "${account}"
  fi
  # Clear any expiry a prior disable cycle may have set, and install a fresh
  # password every time recovery is (re-)enabled so the operator-supplied
  # HUB_SSH_RECOVERY_PASSWORD is always the one that is actually active.
  chage -E -1 "${account}"
  printf '%s:%s\n' "${account}" "${password}" | chpasswd
  usermod -aG sudo "${account}"
}

# Removes login ability rather than the OS account itself, so an in-progress
# recovery session is not killed mid-use and no audit/home-directory history
# is destroyed; this is the security-relevant meaning of "remove the
# temporary recovery account" -- it can no longer authenticate, by password
# or otherwise, until a future recovery window explicitly re-enables it.
disable_ssh_recovery_account_access() {
  local account="$1"
  id -u "${account}" >/dev/null 2>&1 || return 0
  usermod -L -e 1 "${account}" 2>/dev/null || true
  gpasswd -d "${account}" sudo >/dev/null 2>&1 || true
}

write_ssh_recovery_disable_helper() {
  cat > "${ssh_recovery_disable_helper}" <<'EOF'
#!/usr/bin/env bash
# Restores the control-plane hub to key-only SSH after a temporary
# HUB_SSH_PASSWORD_AUTH=1 recovery window expires (M-21). Idempotent and
# self-cleaning: safe to run more than once, and safe to run after a reboot
# even if the recovery window's transient state is otherwise gone, because
# the systemd timer that invokes this is itself an absolute-deadline,
# Persistent=true unit (see schedule_ssh_recovery_expiry) rather than a
# boot-relative one.
set -Eeuo pipefail
log() { echo "[$(date -u '+%Y-%m-%dT%H:%M:%SZ')] winsvpn-disable-ssh-password-recovery: $*"; }

state_file="/etc/winsvpn/ssh-recovery-state"
sshd_config="/etc/ssh/sshd_config.d/20-winsvpn-hub.conf"
account=""
cidr=""
if [[ -r "${state_file}" ]]; then
  # shellcheck disable=SC1090
  source "${state_file}"
  account="${ACCOUNT:-}"
  cidr="${CIDR:-}"
fi

if [[ -n "${account}" ]]; then
  id -u "${account}" >/dev/null 2>&1 && {
    usermod -L -e 1 "${account}" 2>/dev/null || true
    gpasswd -d "${account}" sudo >/dev/null 2>&1 || true
    log "locked recovery account ${account}"
  }
fi

if [[ -f "${sshd_config}" ]] && grep -q '^Match User [^ ]* Address ' "${sshd_config}"; then
  candidate="$(mktemp)"
  backup="$(mktemp)"
  cp -a -- "${sshd_config}" "${backup}"
  # Strip the temporary "Match User <recovery_account> Address <cidr> ...
  # Match all" block that harden_control_sshd appends while recovery is
  # active; the base directives above it are already key-only and are left
  # untouched. H0 (D3): only a block with an Address is the recovery block;
  # the permanent "Match User wins-site-ai" block above it stays.
  awk '/^Match User [^ ]+ Address / {skip=1} {if (!skip) print} skip && /^Match all$/ {skip=0}' "${sshd_config}" > "${candidate}"
  install -o root -g root -m 644 "${candidate}" "${sshd_config}"
  rm -f "${candidate}"
  if sshd -t; then
    if systemctl reload ssh 2>/dev/null || systemctl reload sshd 2>/dev/null; then
      log "restored key-only sshd_config and reloaded sshd"
    else
      log "WARNING: sshd reload failed after restoring key-only config; manual review required"
    fi
    rm -f "${backup}"
  else
    install -o root -g root -m 644 "${backup}" "${sshd_config}"
    rm -f "${backup}"
    log "WARNING: key-only sshd config failed 'sshd -t' validation; restored the prior (still-active-recovery) config for manual review instead of leaving sshd unparseable"
  fi
else
  log "sshd_config already key-only; nothing to restore"
fi

if [[ -n "${cidr}" ]] && command -v iptables >/dev/null 2>&1; then
  removed=0
  while iptables -C WINVPN-HUB-INPUT -s "${cidr}" -p tcp --dport 22 -m comment --comment winsvpn-ssh-recovery -j ACCEPT 2>/dev/null; do
    iptables -D WINVPN-HUB-INPUT -s "${cidr}" -p tcp --dport 22 -m comment --comment winsvpn-ssh-recovery -j ACCEPT
    removed=1
  done
  if ((removed == 1)); then
    iptables-save > /etc/iptables/rules.v4 2>/dev/null || true
    chmod 600 /etc/iptables/rules.v4 /etc/iptables/rules.v6 2>/dev/null || true
    netfilter-persistent save >/dev/null 2>&1 || true
    chmod 600 /etc/iptables/rules.v4 /etc/iptables/rules.v6 2>/dev/null || true
    log "removed recovery firewall allowance for ${cidr}"
  fi
fi

rm -f "${state_file}"
systemctl disable --now winsvpn-disable-ssh-password-recovery.timer >/dev/null 2>&1 || true
rm -f /etc/systemd/system/winsvpn-disable-ssh-password-recovery.timer \
      /etc/systemd/system/winsvpn-disable-ssh-password-recovery.service
systemctl daemon-reload >/dev/null 2>&1 || true
log "SSH password recovery window closed; key-only mode restored"
EOF
  chmod 700 "${ssh_recovery_disable_helper}"
}

schedule_ssh_recovery_expiry() {
  local minutes="$1" account="$2" cidr="$3" deadline_epoch deadline_calendar
  write_ssh_recovery_disable_helper
  install -d -m 700 /etc/winsvpn
  deadline_epoch=$(( $(date -u +%s) + minutes * 60 ))
  deadline_calendar="$(date -u -d "@${deadline_epoch}" '+%Y-%m-%d %H:%M:%S UTC')"
  cat > "${ssh_recovery_state_file}" <<EOF
ACCOUNT=${account}
CIDR=${cidr}
DEADLINE_EPOCH=${deadline_epoch}
EOF
  chmod 600 "${ssh_recovery_state_file}"

  cat > "${ssh_recovery_service}" <<EOF
[Unit]
Description=Restore Win's VPN hub SSH to key-only mode after a temporary recovery window
[Service]
Type=oneshot
ExecStart=${ssh_recovery_disable_helper}
EOF

  # OnCalendar with an absolute timestamp (not OnActiveSec/OnBootSec, which
  # are relative to timer-start/boot and would silently re-arm a fresh 30
  # minutes on every reboot) plus Persistent=true is what makes the deadline
  # survive a reboot: systemd records the last trigger and, if the absolute
  # time has already passed by the time the unit starts again at boot, fires
  # it immediately instead of waiting or resetting the countdown.
  cat > "${ssh_recovery_timer}" <<EOF
[Unit]
Description=Expire Win's VPN hub SSH password recovery window at ${deadline_calendar}
[Timer]
OnCalendar=${deadline_calendar}
Persistent=true
AccuracySec=30s
Unit=winsvpn-disable-ssh-password-recovery.service
[Install]
WantedBy=timers.target
EOF

  systemctl daemon-reload
  systemctl enable --now winsvpn-disable-ssh-password-recovery.timer
  log "SSH password recovery for ${account} from ${cidr} expires at ${deadline_calendar}"
}

harden_control_sshd() {
  log "Applying control-plane SSH attempt limits"
  local password_auth="${HUB_SSH_PASSWORD_AUTH:-$HUB_SSH_PASSWORD_AUTH_DEFAULT}"
  local recovery_enabled=0
  local recovery_cidr="${HUB_SSH_RECOVERY_CIDR:-$HUB_SSH_RECOVERY_CIDR_DEFAULT}"
  local recovery_account="${HUB_SSH_RECOVERY_ACCOUNT:-$HUB_SSH_RECOVERY_ACCOUNT_DEFAULT}"
  local recovery_minutes="${HUB_SSH_RECOVERY_MINUTES:-$HUB_SSH_RECOVERY_MINUTES_DEFAULT}"
  # 20-* wins before Ubuntu's 50-cloud-init.conf while leaving the emergency
  # 10-winsvpn-recovery.conf able to take precedence during console recovery.
  local sshd_config="/etc/ssh/sshd_config.d/20-winsvpn-hub.conf"
  local recovery_config="/etc/ssh/sshd_config.d/10-winsvpn-recovery.conf"
  local legacy_config="/etc/ssh/sshd_config.d/99-winsvpn-hub.conf"
  # M-21: root never gets password authentication, recovery window or not.
  # PasswordAuthentication also stays "no" by default even during recovery --
  # only a Match block scoped to the named non-root recovery account (and,
  # defense-in-depth, its required source CIDR) ever flips it to "yes".
  local candidate backup_dir effective
  local expected_root="prohibit-password|without-password"
  local expected_password="no"
  local had_sshd_config=0 had_recovery_config=0 had_legacy_config=0
  install -d -m 755 /run/sshd
  mkdir -p /etc/ssh/sshd_config.d
  if [[ "${password_auth}" != "0" && "${password_auth,,}" != "false" && "${password_auth,,}" != "no" ]]; then
    recovery_enabled=1
  fi
  if ! host_has_authorized_ssh_key; then
    err "Refusing to configure sshd because no non-empty authorized_keys file was found. Install an SSH public key before deployment; HUB_SSH_PASSWORD_AUTH is a scoped, temporary recovery account, not a substitute for key-based access."
    return 1
  fi
  if ((recovery_enabled == 1)); then
    valid_ipv4_cidr "${recovery_cidr}" || {
      err "HUB_SSH_RECOVERY_CIDR must be an IPv4 CIDR such as 203.0.113.4/32."
      return 1
    }
    valid_unix_username "${recovery_account}" && [[ "${recovery_account}" != "root" ]] || {
      err "HUB_SSH_RECOVERY_ACCOUNT must be a valid, non-root Unix username."
      return 1
    }
    : "${HUB_SSH_RECOVERY_PASSWORD:?HUB_SSH_RECOVERY_PASSWORD is required when HUB_SSH_PASSWORD_AUTH is enabled}"
    ensure_ssh_recovery_account "${recovery_account}" "${HUB_SSH_RECOVERY_PASSWORD}"
  fi

  candidate="$(mktemp)"
  backup_dir="$(mktemp -d)"
  if [[ -e "${sshd_config}" || -L "${sshd_config}" ]]; then
    cp -a -- "${sshd_config}" "${backup_dir}/current"
    had_sshd_config=1
  fi
  if [[ -e "${legacy_config}" || -L "${legacy_config}" ]]; then
    cp -a -- "${legacy_config}" "${backup_dir}/legacy"
    had_legacy_config=1
  fi
  if [[ -e "${recovery_config}" || -L "${recovery_config}" ]]; then
    cp -a -- "${recovery_config}" "${backup_dir}/recovery"
    had_recovery_config=1
  fi

  cat > "${candidate}" <<EOF
Port 22
MaxAuthTries 5
LoginGraceTime 30
PermitEmptyPasswords no
PermitRootLogin prohibit-password
PasswordAuthentication no
KbdInteractiveAuthentication no
ChallengeResponseAuthentication no
PubkeyAuthentication yes
X11Forwarding no
AllowAgentForwarding no
AllowTcpForwarding remote
GatewayPorts no
UsePAM yes
PermitUserRC no
PermitUserEnvironment no
Match User wins-site-ai
    AuthorizedKeysFile /var/lib/wins-site-ai-tunnel/authorized_keys
    AllowTcpForwarding remote
    PermitListen 127.0.0.1:*
    AllowStreamLocalForwarding no
    PermitTunnel no
    PermitTTY no
    X11Forwarding no
    AllowAgentForwarding no
    ForceCommand /usr/sbin/nologin
Match all
EOF
  # H0 (D3): PermitUserRC and PermitUserEnvironment switch off the deferred
  # login hooks a login directory can carry (~/.ssh/rc, ~/.ssh/environment).
  # The Match block above is the Core site-AI tunnel's non-root forwarding
  # account: its keys file is the one the hub app writes, and it can open a
  # loopback remote forward and nothing else, not even a session.
  if ((recovery_enabled == 1)); then
    cat >> "${candidate}" <<EOF
Match User ${recovery_account} Address ${recovery_cidr}
    PasswordAuthentication yes
    KbdInteractiveAuthentication no
Match all
EOF
  fi

  rollback_control_sshd_dropins() {
    if ((had_sshd_config == 1)); then
      rm -f -- "${sshd_config}"
      cp -a -- "${backup_dir}/current" "${sshd_config}"
    else
      rm -f -- "${sshd_config}"
    fi
    if ((had_legacy_config == 1)); then
      rm -f -- "${legacy_config}"
      cp -a -- "${backup_dir}/legacy" "${legacy_config}"
    else
      rm -f -- "${legacy_config}"
    fi
    if ((had_recovery_config == 1)); then
      rm -f -- "${recovery_config}"
      cp -a -- "${backup_dir}/recovery" "${recovery_config}"
    else
      rm -f -- "${recovery_config}"
    fi
  }

  ssh-keygen -A
  if ! install -o root -g root -m 644 "${candidate}" "${sshd_config}" ||
     ! rm -f -- "${recovery_config}" ||
     ! rm -f -- "${legacy_config}" ||
     ! sshd -t ||
     ! effective="$(sshd -T -C 'user=root,host=localhost,addr=127.0.0.1')" ||
     ! sshd_effective_value_is "${effective}" port "22" ||
     ! sshd_effective_value_is "${effective}" permitrootlogin "${expected_root}" ||
     ! sshd_effective_value_is "${effective}" passwordauthentication "${expected_password}" ||
     ! sshd_effective_value_is "${effective}" kbdinteractiveauthentication "no" ||
     ! sshd_effective_value_is "${effective}" pubkeyauthentication "yes" ||
     ! sshd_effective_value_is "${effective}" allowtcpforwarding "remote" ||
     ! sshd_effective_value_is "${effective}" permituserrc "no" ||
     ! sshd_effective_value_is "${effective}" permituserenvironment "no" ||
     ! effective="$(sshd -T -C 'user=wins-site-ai,host=localhost,addr=127.0.0.1')" ||
     ! sshd_effective_value_is "${effective}" authorizedkeysfile "/var/lib/wins-site-ai-tunnel/authorized_keys" ||
     ! sshd_effective_value_is "${effective}" allowtcpforwarding "remote" ||
     ! sshd_effective_value_is "${effective}" permittty "no" ||
     ! sshd_effective_value_is "${effective}" forcecommand "/usr/sbin/nologin"; then
    rollback_control_sshd_dropins
    rm -f -- "${candidate}"
    rm -rf -- "${backup_dir}"
    unset -f rollback_control_sshd_dropins
    err "Control-plane SSH hardening failed syntax/effective-config validation; the prior drop-ins were restored."
    return 1
  fi
  if ((recovery_enabled == 1)) && {
       ! effective="$(sshd -T -C "user=${recovery_account},host=localhost,addr=${recovery_cidr%%/*}")" ||
       ! sshd_effective_value_is "${effective}" passwordauthentication "yes"
     }; then
    rollback_control_sshd_dropins
    rm -f -- "${candidate}"
    rm -rf -- "${backup_dir}"
    unset -f rollback_control_sshd_dropins
    err "SSH recovery Match block failed effective-config validation for ${recovery_account}@${recovery_cidr}; the prior drop-ins were restored."
    return 1
  fi
  rm -f -- "${candidate}"

  if ! systemctl reload ssh 2>/dev/null && ! systemctl reload sshd 2>/dev/null; then
    rollback_control_sshd_dropins
    sshd -t || err "The restored SSH configuration is invalid; console recovery is required."
    systemctl reload ssh 2>/dev/null || systemctl reload sshd 2>/dev/null || true
    rm -rf -- "${backup_dir}"
    unset -f rollback_control_sshd_dropins
    err "Control-plane SSH reload failed; the prior drop-ins were restored."
    return 1
  fi
  rm -rf -- "${backup_dir}"
  unset -f rollback_control_sshd_dropins

  if ((recovery_enabled == 1)); then
    schedule_ssh_recovery_expiry "${recovery_minutes}" "${recovery_account}" "${recovery_cidr}"
  else
    disable_ssh_recovery_account_access "${recovery_account}"
    if [[ -x "${ssh_recovery_disable_helper}" || -f "${ssh_recovery_timer}" ]]; then
      "${ssh_recovery_disable_helper}" 2>/dev/null || true
    fi
  fi
}

ensure_hub_origin_cert() {
  local cert_dir="/etc/winsvpn/tls" cert_file key_file domain san_csv=""
  cert_file="${cert_dir}/hub-origin.crt"
  key_file="${cert_dir}/hub-origin.key"
  if [[ -s "${cert_file}" && -s "${key_file}" && "${REGENERATE_HUB_ORIGIN_CERT:-0}" != "1" ]]; then
    return 0
  fi
  mkdir -p "${cert_dir}"
  chmod 700 "${cert_dir}"
  for domain in "${HUB_DOMAIN}" "${SYNC_DOMAINS[@]}"; do
    [[ -n "${domain}" ]] || continue
    case ",${san_csv}," in
      *",DNS:${domain},"*) ;;
      *) san_csv="${san_csv:+${san_csv},}DNS:${domain}" ;;
    esac
  done
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" != "1" ]]; then
    san_csv="${san_csv:+${san_csv},}IP:${IONOS_HUB_IP}"
  fi
  openssl req -x509 -nodes -newkey rsa:2048 -days 3650 \
    -keyout "${key_file}" \
    -out "${cert_file}" \
    -subj "/CN=${HUB_DOMAIN}" \
    -addext "subjectAltName=${san_csv}" >/dev/null 2>&1
  chmod 600 "${key_file}"
  chmod 644 "${cert_file}"
}

# IA-CP-08: one digest over the content, owner and mode of each named path (a
# symlink hashes as its target name, a missing path as absent), so a rerun can
# tell whether anything a service reads actually changed before restarting it.
wins_files_digest() {
  local path
  for path in "$@"; do
    if [[ -L "${path}" ]]; then
      printf '%s link %s\n' "${path}" "$(readlink "${path}")"
    elif [[ -f "${path}" ]]; then
      printf '%s %s ' "${path}" "$(stat -c '%u:%g:%a' "${path}")"
      sha256sum < "${path}"
    else
      printf '%s absent\n' "${path}"
    fi
  done | sha256sum | awk '{print $1}'
}

# Every file write_nginx renders, plus the certificates nginx loads. The
# rendered set is what write_nginx snapshots and restores when `nginx -t`
# rejects the new configuration; the certificates only feed the digest.
wins_nginx_rendered_paths() {
  printf '%s\n' \
    "${WINS_NGINX_MAIN_CONFIG:-/etc/nginx/nginx.conf}" \
    /etc/systemd/system/nginx.service.d/30-wins-performance.conf \
    /etc/nginx/snippets/wins-hub-proxy-common.conf \
    /etc/nginx/snippets/wins-hub-locations.conf \
    /etc/nginx/conf.d/wins-server-names-hash.conf \
    /etc/nginx/conf.d/wins-realip.conf \
    /etc/nginx/conf.d/wins-webhook-ratelimit.conf \
    /etc/nginx/conf.d/wins-edge-ratelimit.conf \
    /etc/nginx/conf.d/wins-admin-ratelimit.conf \
    "${NGINX_SITE}" \
    /etc/nginx/sites-enabled/default \
    /etc/nginx/sites-enabled/wins-hub.conf
}

# IA-CP-08: restart UNIT only when DIGEST differs from the digest recorded at
# its last restart by this installer. Recording after the restart (never
# before) means a run that dies in between restarts again next time, and a
# certificate or file changed between runs is still picked up.
wins_restart_if_changed() {
  local unit="$1" name="$2" digest="$3" state_dir state
  state_dir="${WINSVPN_DEPLOY_STATE_DIR:-/var/lib/winsvpn-deployment}"
  state="${state_dir}/${name}.applied.sha256"
  install -d -m 700 "${state_dir}"
  if [[ -f "${state}" && "$(cat "${state}")" == "${digest}" ]]; then
    log "${unit}: configuration unchanged since its last restart; not restarted."
    return 0
  fi
  systemctl restart "${unit}"
  printf '%s\n' "${digest}" > "${state}"
  chmod 600 "${state}"
}

wins_nginx_config_digest() {
  local -a paths=()
  mapfile -t paths < <(wins_nginx_rendered_paths)
  wins_files_digest "${paths[@]}" \
    /etc/winsvpn/tls/hub-origin.crt /etc/winsvpn/tls/hub-origin.key \
    "${WEBSITE_TLS_CERT}" "${WEBSITE_TLS_KEY}"
}

# Copy every rendered path (or an "absent" marker) into $1 so a rejected
# configuration can be put back exactly as it was.
wins_nginx_snapshot() {
  local dir="$1" path index=0
  while IFS= read -r path; do
    if [[ -e "${path}" || -L "${path}" ]]; then
      cp -a -- "${path}" "${dir}/${index}"
    else
      : > "${dir}/${index}.absent"
    fi
    index=$((index + 1))
  done < <(wins_nginx_rendered_paths)
}

wins_nginx_restore() {
  local dir="$1" path index=0
  while IFS= read -r path; do
    if [[ -e "${dir}/${index}.absent" ]]; then
      rm -f -- "${path}"
    elif [[ -e "${dir}/${index}" || -L "${dir}/${index}" ]]; then
      rm -f -- "${path}"
      cp -a -- "${dir}/${index}" "${path}"
    fi
    index=$((index + 1))
  done < <(wins_nginx_rendered_paths)
}

write_nginx() {
  local nginx_snapshot_dir=""
  ensure_hub_origin_cert
  local nginx_main_config="${WINS_NGINX_MAIN_CONFIG:-/etc/nginx/nginx.conf}"
  local nginx_worker_connections="${NGINX_WORKER_CONNECTIONS:-8192}"
  local nginx_nofile_limit="${NGINX_WORKER_NOFILE_LIMIT:-65535}"
  local website_tls_block=""
  local website_tls_enabled="0"
  local default_https_names=()
  local nginx_name website_name skip_name listen_http="80" listen_https="443"
  local name_candidate longest_server_name_length=0 server_name_bucket_size=64
  local origin_server_names="${HUB_DOMAIN} ${SYNC_DOMAINS[*]} _"
  [[ "${nginx_worker_connections}" =~ ^[0-9]+$ \
      && "${nginx_worker_connections}" -ge 1024 \
      && "${nginx_worker_connections}" -le 65535 ]] || {
    err "NGINX_WORKER_CONNECTIONS must be an integer from 1024 through 65535."
    return 1
  }
  [[ "${nginx_nofile_limit}" =~ ^[0-9]+$ \
      && "${nginx_nofile_limit}" -ge "${nginx_worker_connections}" \
      && "${nginx_nofile_limit}" -le 1048576 ]] || {
    err "NGINX_WORKER_NOFILE_LIMIT must be at least NGINX_WORKER_CONNECTIONS and no more than 1048576."
    return 1
  }
  [[ -s "${nginx_main_config}" ]] || {
    err "Nginx main configuration is missing: ${nginx_main_config}"
    return 1
  }
  # IA-CP-10: in direct-origin mode the Cloudflare edge is the socket peer, so
  # its official ranges must be trusted for CF-Connecting-IP or every client
  # (and every rate-limit key) is an edge address. Fetched before any file is
  # written so a failed fetch changes nothing.
  local -a realip_cidrs=()
  local realip_ranges="" realip_cidr realip_conf
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" != "1" ]]; then
    if realip_ranges="$(cloudflare_origin_ipv4_ranges)"; then
      mapfile -t realip_cidrs <<<"${realip_ranges}"
    elif [[ "${CONTROL_DIRECT_CLOUDFLARE_ONLY:-$CONTROL_DIRECT_CLOUDFLARE_ONLY_DEFAULT}" == "1" ]]; then
      err "Cloudflare-only direct origin needs the official Cloudflare IPv4 ranges for real-IP resolution; nginx was not changed."
      return 1
    else
      warn "Could not fetch Cloudflare IPv4 ranges; direct-origin nginx trusts only loopback for CF-Connecting-IP."
    fi
  fi
  # IA-CP-08: snapshot every rendered file; a configuration `nginx -t`
  # rejects is rolled back instead of being left on disk for the next boot.
  nginx_snapshot_dir="$(mktemp -d)"
  chmod 700 "${nginx_snapshot_dir}"
  wins_nginx_snapshot "${nginx_snapshot_dir}"
  python3 - "${nginx_main_config}" "${nginx_worker_connections}" "${nginx_nofile_limit}" <<'PYEOF'
import re
import sys
from pathlib import Path

path = Path(sys.argv[1])
connections = int(sys.argv[2])
nofile = int(sys.argv[3])
source = path.read_text(encoding="utf-8")

source, worker_count = re.subn(
    r"(?m)^[ \t]*worker_processes[ \t]+[^;]+;[ \t]*$",
    "worker_processes auto;",
    source,
    count=1,
)
if worker_count != 1:
    raise SystemExit("Nginx worker_processes directive is missing or ambiguous")

source, connection_count = re.subn(
    r"(?m)^([ \t]*)worker_connections[ \t]+[0-9]+;[ \t]*$",
    rf"\g<1>worker_connections {connections};",
    source,
    count=1,
)
if connection_count != 1:
    raise SystemExit("Nginx worker_connections directive is missing or ambiguous")

rlimit_line = f"worker_rlimit_nofile {nofile};"
source, rlimit_count = re.subn(
    r"(?m)^[ \t]*worker_rlimit_nofile[ \t]+[0-9]+;[ \t]*$",
    rlimit_line,
    source,
    count=1,
)
if rlimit_count == 0:
    events_match = re.search(r"(?m)^[ \t]*events[ \t]*\{", source)
    if not events_match:
        raise SystemExit("Nginx events context is missing")
    source = source[:events_match.start()] + rlimit_line + "\n" + source[events_match.start():]

path.write_text(source, encoding="utf-8")
PYEOF
  install -d -m 755 /etc/systemd/system/nginx.service.d
  cat > /etc/systemd/system/nginx.service.d/30-wins-performance.conf <<EOF
[Service]
LimitNOFILE=${nginx_nofile_limit}
EOF
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
    listen_http="127.0.0.1:80"
    listen_https="127.0.0.1:443"
  else
    origin_server_names="${HUB_DOMAIN} ${SYNC_DOMAINS[*]} ${IONOS_HUB_IP} _"
  fi
  mkdir -p /var/www/winsvpn/downloads /etc/nginx/snippets
  cat > /etc/nginx/snippets/wins-hub-proxy-common.conf <<'EOF'
proxy_http_version 1.1;
proxy_set_header Host $host;
# M-10: forward only the address nginx resolved itself ($remote_addr, set from
# CF-Connecting-IP via the set_real_ip_from allow-list in wins-realip.conf) and
# never the raw client-supplied X-Forwarded-For / CF-Connecting-IP headers. A
# client cannot prepend a spoofed hop, because $proxy_add_x_forwarded_for and
# $http_cf_connecting_ip are no longer passed through.
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $remote_addr;
proxy_set_header CF-Connecting-IP $remote_addr;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_set_header Connection "";
proxy_socket_keepalive on;
proxy_read_timeout 90s;
proxy_connect_timeout 15s;
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "DENY" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;
add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
add_header Content-Security-Policy "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'" always;
add_header Cache-Control "no-store" always;
EOF
  cat > /etc/nginx/snippets/wins-hub-locations.conf <<'EOF'
root /var/www/winsvpn;
index index.html;

server_tokens off;
proxy_hide_header X-Powered-By;
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "DENY" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;
add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

# C3 layer 1: edge load shedding, counting ALL requests. Applied to the
# authenticated and redemption surfaces, which is where a flood would land.
# /healthz stays unshed so an outage cannot be masked by its own rate limit.
location = /healthz { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
location = /nodes { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
location = /verify {
    limit_req zone=wins_edge burst=60 nodelay;
    limit_conn wins_edge_conn 40;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
location = /logout { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
location = /account/status { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
# Account deletion (Apple 5.1.1(v) / Play Data Safety). Needs its own prefix
# location for the same reason /emergency/dispatch does: the catch-all at the
# bottom serves the STATIC SITE, not the hub -- without this block every
# /account/deletion/* POST is silently swallowed by try_files instead of
# reaching FastAPI, and the in-app deletion flow is dead on arrival. Note
# `= /account/status` above is an EXACT match and does not cover this prefix.
#
# Unlike /emergency/dispatch, there is no life-safety reason to skip edge
# shedding here, so this follows the ordinary convention for an authenticated,
# mutating surface (same as /verify and /api/): main.py itself calls account
# deletion "the single most dangerous operation on the service" and already
# applies its own app-layer rate limits (account-deletion-ip,
# account-deletion-account) ahead of this -- the edge limiter below is the
# load-shedding layer, a different purpose than that app-layer backoff (see
# the C3 comment near check_rate_limit).
location /account/deletion/ {
    limit_req zone=wins_edge burst=60 nodelay;
    limit_conn wins_edge_conn 40;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
# Duress emergency relay. It needs its own location because the catch-all at the
# bottom serves the STATIC SITE, not the hub -- without this block the app's POST
# never reaches FastAPI and every alert rots in the on-device queue.
#
# Deliberately NOT rate-limited at the edge, unlike every other authenticated
# surface here. limit_req/limit_conn answer 429, and a 429 on this path is the
# one thing in the whole system that can refuse a duress alert outright. The
# application layer paces this route instead (emergency_pacing_delay), where
# over-limit traffic is delayed and still delivered rather than rejected. The
# cheap bound that costs nobody anything is the body size: a real dispatch is a
# few hundred bytes.
location = /emergency/dispatch {
    client_max_body_size 8k;
    access_log off;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
location /api/ {
    limit_req zone=wins_edge burst=60 nodelay;
    limit_conn wins_edge_conn 40;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
# F-12: /admin/ carries edge load shedding like every authenticated surface,
# but on its own tighter zone (10r/s, burst 20 nodelay) plus a per-IP
# connection cap (20). This layer answers 429 at the edge; it is load shedding,
# not authentication backoff -- the hub's app-level admin rate limits still
# run behind it and are the final word (see the C3 comment near
# check_rate_limit).
location /admin/ {
    limit_req zone=wins_admin burst=20 nodelay;
    limit_conn wins_admin_conn 20;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
location /free/ { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
location /legal/ { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
location /pay/ { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
location /paypal/ { proxy_pass http://127.0.0.1:8000; include /etc/nginx/snippets/wins-hub-proxy-common.conf; }
# IA-CP-12: referral links (PUBLIC_REFERRAL_BASE, https://winsvpn.org/referral/)
# are hub routes (/ref/{code}, /referral/{code}). Without these locations the
# static catch-all below answered them with index.html and the landing page
# never rendered. Edge-shed like every other surface that writes a row per hit.
location /ref/ {
    limit_req zone=wins_edge burst=60 nodelay;
    limit_conn wins_edge_conn 40;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
location /referral/ {
    limit_req zone=wins_edge burst=60 nodelay;
    limit_conn wins_edge_conn 40;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}
# M-5: PayPal webhook ingress is rate-limited (zone defined in
# wins-webhook-ratelimit.conf) and capped to a small body ahead of the app.
# This is defense-in-depth in front of -- never a substitute for -- the
# mandatory PayPal-Transmission signature verification the app still performs.
location /webhook/ {
    limit_req zone=wins_webhook burst=20 nodelay;
    limit_req_status 429;
    client_max_body_size 128k;
    proxy_pass http://127.0.0.1:8000;
    include /etc/nginx/snippets/wins-hub-proxy-common.conf;
}

location /downloads/ {
    try_files $uri =404;
    access_log off;
    expires 4h;
}

# IA-CP-03: camouflage every package as an opaque download. `add_header
# Content-Type` APPENDS a second Content-Type after the one nginx derives from
# the extension (.apk, .exe, .msix), so the real type still leaked. An empty
# types map plus default_type replaces it instead. A location that declares any
# add_header inherits none from the server level, so the server-level security
# headers above are repeated here verbatim.
location /pkg/ {
    try_files $uri =404;
    access_log off;
    expires 4h;
    types { }
    default_type application/octet-stream;
    add_header Content-Disposition "attachment";
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
}

location /assets/ {
    try_files $uri =404;
    access_log off;
    expires 1d;
}

# These product-specific command endpoints do not exist on the Nginx/FastAPI hub.
location = /shell { return 404; }
location ~* ^/(?:CFIDE|geoserver|solr|actuator|manager|cgi-bin)(?:/|$) { return 404; }
location = /HNAP1 { return 404; }

location / {
    try_files $uri $uri/ /index.html;
}
EOF
  if [[ -s "${WEBSITE_TLS_CERT}" && -s "${WEBSITE_TLS_KEY}" && "${#WEBSITE_TLS_DOMAINS[@]}" -gt 0 ]]; then
    website_tls_enabled="1"
    website_tls_block=$(cat <<EOF

server {
    listen ${listen_https} ssl;
    server_name ${WEBSITE_TLS_DOMAINS[*]};

    ssl_certificate ${WEBSITE_TLS_CERT};
    ssl_certificate_key ${WEBSITE_TLS_KEY};
    ssl_protocols TLSv1.3;
    ssl_session_timeout 1d;
    ssl_session_cache shared:WINSVPNSSL:10m;
    access_log off;
    error_log /var/log/nginx/wins-hub.error.log warn;
    client_max_body_size 2m;

    include /etc/nginx/snippets/wins-hub-locations.conf;
}
EOF
)
  fi
  for nginx_name in "${HUB_DOMAIN}" "${SYNC_DOMAINS[@]}" "_"; do
    [[ -n "${nginx_name}" ]] || continue
    skip_name="0"
    if [[ "${website_tls_enabled}" == "1" ]]; then
      for website_name in "${WEBSITE_TLS_DOMAINS[@]}"; do
        if [[ "${nginx_name}" == "${website_name}" ]]; then
          skip_name="1"
          break
        fi
      done
    fi
    [[ "${skip_name}" == "0" ]] && default_https_names+=("${nginx_name}")
  done
  for name_candidate in \
    "${HUB_DOMAIN}" \
    "${SYNC_DOMAINS[@]}" \
    "${WEBSITE_TLS_DOMAINS[@]}" \
    "${IONOS_HUB_IP}" \
    "_"; do
    if (( ${#name_candidate} > longest_server_name_length )); then
      longest_server_name_length=${#name_candidate}
    fi
  done
  while (( server_name_bucket_size < longest_server_name_length + 32 )); do
    server_name_bucket_size=$((server_name_bucket_size * 2))
  done
  (( server_name_bucket_size <= 512 )) || {
    err "Generated Nginx server name exceeds the supported DNS-name bucket size."
    return 1
  }
  grep -Eq '^[[:space:]]*include[[:space:]]+/etc/nginx/conf\.d/\*\.conf;' /etc/nginx/nginx.conf || {
    err "Nginx does not include /etc/nginx/conf.d/*.conf inside its http context."
    wins_nginx_restore "${nginx_snapshot_dir}"
    rm -rf -- "${nginx_snapshot_dir}"
    return 1
  }
  printf 'server_names_hash_bucket_size %s;\n' "${server_name_bucket_size}" \
    > /etc/nginx/conf.d/wins-server-names-hash.conf
  # M-10: resolve the true client IP from CF-Connecting-IP, but only when the
  # immediate peer is a trusted proxy. Loopback is the local cloudflared/nginx
  # hop and is always trusted (nginx binds loopback under HIDE_CONTROL_ORIGIN=1,
  # so cloudflared is the $remote_addr and legitimately carries CF-Connecting-IP).
  # IA-CP-10: in direct-origin mode the validated official Cloudflare IPv4
  # ranges fetched above are trusted too (the hub firewall is IPv4-only, and
  # in Cloudflare-only mode those ranges are the only web ingress). Without a
  # matching set_real_ip_from entry nginx keeps $remote_addr as the real socket
  # peer, so a client-supplied CF-Connecting-IP from anywhere else is ignored,
  # not trusted.
  realip_conf=$'set_real_ip_from 127.0.0.1/32;\nset_real_ip_from ::1/128;\n'
  for realip_cidr in "${realip_cidrs[@]}"; do
    [[ -n "${realip_cidr}" ]] || continue
    realip_conf+="set_real_ip_from ${realip_cidr};"$'\n'
  done
  realip_conf+=$'real_ip_header CF-Connecting-IP;\nreal_ip_recursive on;\n'
  printf '%s' "${realip_conf}" > /etc/nginx/conf.d/wins-realip.conf
  # M-5: dedicated PayPal-webhook rate-limit zone, keyed on the nginx-resolved
  # client address (post real_ip). Enforced by the /webhook/ location; the app's
  # PayPal signature verification remains mandatory and independent of this.
  cat > /etc/nginx/conf.d/wins-webhook-ratelimit.conf <<'EOF'
limit_req_zone $binary_remote_addr zone=wins_webhook:10m rate=10r/s;
EOF
  # C3 LAYER 1 -- EDGE LOAD SHEDDING. This layer counts ALL HTTP requests and
  # exists to keep the box up. It is deliberately NOT the authentication
  # backoff: the application layer counts only genuine credential and
  # redemption FAILURES (see precheck_rate_limit / consume_auth_failure).
  #
  # Separating them is the whole point. A single counter that sheds load AND
  # backs off authentication has to be tuned for one or the other; tuned for
  # brute force it takes down every client behind one carrier-grade NAT egress,
  # and tuned for shared egress it stops slowing an attacker. So this one is set
  # generously and per-IP, and the strict one lives in the app and only sees
  # failures.
  #
  # burst+nodelay rather than a hard cutoff: a normal client that opens several
  # requests at once is absorbed, while a sustained flood is still shed.
  cat > /etc/nginx/conf.d/wins-edge-ratelimit.conf <<'EOF'
limit_req_zone $binary_remote_addr zone=wins_edge:10m rate=30r/s;
limit_conn_zone $binary_remote_addr zone=wins_edge_conn:10m;
limit_req_status 429;
limit_conn_status 429;
EOF
  # F-12: dedicated admin-surface rate/connection limit zones, keyed on the
  # nginx-resolved client address (post real_ip), so a spoofed
  # X-Forwarded-For / CF-Connecting-IP cannot buy a fresh budget. Tighter than
  # wins_edge (10r/s vs 30r/s) because /admin/ is the privileged surface.
  # Enforced by the /admin/ location below; the app's own admin backoff
  # (require_admin_token + security_alert, and the hub's check_rate_limit
  # budget) stays untouched and remains the authority over authentication.
  cat > /etc/nginx/conf.d/wins-admin-ratelimit.conf <<'EOF'
limit_req_zone $binary_remote_addr zone=wins_admin:10m rate=10r/s;
limit_conn_zone $binary_remote_addr zone=wins_admin_conn:10m;
EOF
  cat > "${NGINX_SITE}" <<EOF
server {
    listen ${listen_http} default_server;
    server_name ${origin_server_names};

    access_log off;
    error_log /var/log/nginx/wins-hub.error.log warn;
    client_max_body_size 2m;

    include /etc/nginx/snippets/wins-hub-locations.conf;
}
${website_tls_block}

server {
    listen ${listen_https} ssl default_server;
    server_name ${default_https_names[*]};

    ssl_certificate /etc/winsvpn/tls/hub-origin.crt;
    ssl_certificate_key /etc/winsvpn/tls/hub-origin.key;
    ssl_protocols TLSv1.3;
    ssl_session_timeout 1d;
    ssl_session_cache shared:WINSVPNSSL:10m;
    access_log off;
    error_log /var/log/nginx/wins-hub.error.log warn;
    client_max_body_size 2m;

    include /etc/nginx/snippets/wins-hub-locations.conf;
}
EOF
  rm -f /etc/nginx/sites-enabled/default
  ln -sf "${NGINX_SITE}" /etc/nginx/sites-enabled/wins-hub.conf
  if ! nginx -t; then
    err "nginx -t rejected the rendered configuration; restored the previous files and left the running nginx untouched."
    wins_nginx_restore "${nginx_snapshot_dir}"
    rm -rf -- "${nginx_snapshot_dir}"
    return 1
  fi
  rm -rf -- "${nginx_snapshot_dir}"
  systemctl daemon-reload
  systemctl enable --now nginx
  # IA-CP-08: an unchanged rerun no longer restarts nginx.
  wins_restart_if_changed nginx nginx "$(wins_nginx_config_digest)"
}

cloudflare_origin_ipv4_ranges() {
  local ranges=""
  ranges="$(curl -fsS --connect-timeout 5 --max-time 20 --retry 2 \
    https://www.cloudflare.com/ips-v4)" || {
    err "Could not retrieve Cloudflare's official IPv4 origin ranges."
    return 1
  }
  python3 - "${ranges}" <<'PYEOF'
import ipaddress
import sys

values = []
for raw in sys.argv[1].splitlines():
    value = raw.strip()
    if not value:
        continue
    try:
        network = ipaddress.ip_network(value, strict=True)
    except ValueError as exc:
        raise SystemExit(f"invalid Cloudflare IPv4 range: {value}") from exc
    if network.version != 4:
        raise SystemExit(f"non-IPv4 Cloudflare origin range: {value}")
    normalized = str(network)
    if normalized not in values:
        values.append(normalized)
if len(values) < 10:
    raise SystemExit("Cloudflare IPv4 range response was unexpectedly short")
print("\n".join(values))
PYEOF
}

# IA-CP-02: fail2ban ignoreip for the hub sshd jail. The f2b-sshd jump now
# runs before every tcp/22 ACCEPT (see write_iptables), so a ban applies to any
# source. The sources the firewall trusts for administration (every
# HUB_ADMIN_SSH_CIDRS entry and the IPv4 deploy source pinned from
# SSH_CONNECTION) are added to ignoreip, so they can never ban themselves out:
# their reachability is exactly what it was when the jump sat below their
# ACCEPTs. The temporary recovery CIDR is deliberately NOT ignored; bans on the
# password window are the point of the fix.
hub_fail2ban_ignoreips() {
  local entry deploy_source
  local -a entries=()
  for entry in ${HUB_FAIL2BAN_IGNOREIPS:-$HUB_FAIL2BAN_IGNOREIPS_DEFAULT} \
      ${HUB_ADMIN_SSH_CIDRS:-$HUB_ADMIN_SSH_CIDRS_DEFAULT}; do
    [[ " ${entries[*]} " == *" ${entry} "* ]] || entries+=("${entry}")
  done
  deploy_source="${SSH_CONNECTION:-}"
  deploy_source="${deploy_source%% *}"
  if [[ "${deploy_source}" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ \
      && " ${entries[*]} " != *" ${deploy_source}/32 "* ]]; then
    entries+=("${deploy_source}/32")
  fi
  printf '%s\n' "${entries[*]}"
}

# Run a command under a wall-clock bound when coreutils timeout exists (it
# does on every supported hub). $1 is a timeout(1) duration, decimals allowed.
# Exit 124 means the bound was hit (137 when the command had to be killed).
hub_bounded() {
  local secs="$1"
  shift
  if command -v timeout >/dev/null 2>&1; then
    timeout -k 1 "${secs}" "$@"
  else
    "$@"
  fi
}

# Milliseconds on a monotonic clock; one place so the restart proof's
# deadline is testable. Wall-clock time (EPOCHREALTIME, date) can step under
# NTP and would stretch or shrink the deadline (N-6, Turn 7). On Linux this
# reads /proc/uptime with the read builtin (CLOCK_BOOTTIME, 10 ms steps, no
# subprocess); elsewhere it asks python3 for time.monotonic().
hub_now() {
  local up=""
  if [[ -r /proc/uptime ]] && read -r up _ </proc/uptime && [[ "${up}" =~ ^([0-9]+)\.([0-9]{2})$ ]]; then
    printf '%s\n' "$((10#${BASH_REMATCH[1]} * 1000 + 10#${BASH_REMATCH[2]} * 10))"
  else
    python3 -c 'import time; print(int(time.monotonic() * 1000))'
  fi
}

# Whole seconds of wall-clock time (the epoch), with the printf builtin (no
# subprocess). Only for the end of a fail2ban bantime, which fail2ban measures
# on the wall clock too (N-13, Turns 8 and 9); never for the deadline.
hub_wall_now() {
  printf '%(%s)T\n' -1
}

# Milliseconds as a timeout(1) duration. Never zero: timeout treats 0 as no
# limit at all.
hub_duration() {
  local ms="$1"
  ((ms >= 1)) || ms=1
  printf '%d.%03d\n' "$((ms / 1000))" "$((ms % 1000))"
}

# Run one external command of the firewall helpers. Inside the restart proof,
# which declares _HUB_F2B_DEADLINE local so no other caller ever sees it, the
# command is bounded by the time left and returns 124 at once when none is
# left: every subprocess of the proof, the python validators and parsers
# included, ends by the deadline (Sol N-7, Turn 7). Elsewhere it runs as
# before.
hub_run() {
  local bound
  if [[ -n "${_HUB_F2B_DEADLINE:-}" ]]; then
    bound="$(hub_f2b_budget)" || return 124
    hub_bounded "${bound}" "$@"
  else
    "$@"
  fi
}

# SC-1 / OI-CPA-2 (Turns 3 to 5, fail closed): one definite read of the
# live filter table. iptables-save takes no xtables lock, so lock contention
# cannot make it lie. stdout and stderr are captured to files, byte for byte.
# The ONLY definite answers are:
#   - exit 0, a zero-byte stderr, and a zero-byte stdout (a pristine host); or
#   - exit 0, a zero-byte stderr, and a stdout that hub_ruleset_validate
#     accepts completely. Its *filter section is printed; a well-formed
#     ruleset without one means "no hub chains".
# Anything else is retried, then reported as UNKNOWN (return 1): a non-zero
# exit, ANY stderr byte, whitespace included (iptables-nft prints
# "# Warning: iptables-legacy tables present" there while stdout stays empty
# and the exit is 0), whitespace-only stdout, or stdout that does not
# validate. Callers must treat UNKNOWN as "refuse", never as "no chain" or
# "no bans".
hub_filter_ruleset_dump() {
  # $1: attempts (default 3, 2 s apart). $2: per-call timeout, a timeout(1)
  # duration (default 30). hub_f2b_prove_restart passes 1 and its remaining
  # budget so its deadline is a real wall-clock bound (Sol N-7, Turn 6).
  # Returns 124 instead of 1 when the last attempt hit its timeout, so a
  # caller with a deadline can tell "ran out of time" from "unreadable".
  # Inside the restart proof every command here (mktemp, the save, the
  # validator) is bounded by the time left before its deadline (hub_run); the
  # removal of the two temporary files runs even after it, bounded to 1 s.
  local attempts="${1:-3}" call_timeout="${2:-30}"
  local save_bin="${IPTABLES_SAVE_BIN:-iptables-save}" attempt out_file err_file cause section rc timed_out=0 bound
  rc=0
  out_file="$(hub_run mktemp)" || rc=$?
  if ((rc != 0)); then
    err "Could not create a temporary file to read iptables-save output."
    ((rc == 124 || rc == 137)) && return 124
    return 1
  fi
  err_file="$(hub_run mktemp)" || rc=$?
  if ((rc != 0)); then
    hub_bounded 1 rm -f -- "${out_file}" || true
    err "Could not create a temporary file to read iptables-save diagnostics."
    ((rc == 124 || rc == 137)) && return 124
    return 1
  fi
  for ((attempt = 1; attempt <= attempts; attempt++)); do
    rc=0
    timed_out=0
    bound="${call_timeout}"
    if [[ -n "${_HUB_F2B_DEADLINE:-}" ]]; then
      bound="$(hub_f2b_budget)" || {
        timed_out=1
        cause="the deadline was reached"
        break
      }
    fi
    hub_bounded "${bound}" "${save_bin}" >"${out_file}" 2>"${err_file}" || rc=$?
    if ((rc == 124 || rc == 137)); then
      timed_out=1
      cause="timed out after ${bound}s"
    elif ((rc != 0)); then
      cause="exit ${rc}: $(<"${err_file}")"
    elif [[ -s "${err_file}" ]]; then
      cause="exit 0 but stderr was not empty: $(<"${err_file}")"
    elif [[ ! -s "${out_file}" ]]; then
      hub_bounded 1 rm -f -- "${out_file}" "${err_file}" || true
      return 0
    else
      section="$(hub_ruleset_validate <"${out_file}" 2>"${err_file}")" || rc=$?
      if ((rc == 0)); then
        hub_bounded 1 rm -f -- "${out_file}" "${err_file}" || true
        [[ -z "${section}" ]] || printf '%s\n' "${section}"
        return 0
      elif ((rc == 124 || rc == 137)); then
        timed_out=1
        cause="validating the output was cut off by the deadline"
      else
        # Seat C N-9: name the first rejected line.
        cause="exit 0 but the output is not a well-formed iptables-save ruleset ($(<"${err_file}"))"
      fi
    fi
    ((attempt < attempts)) && sleep 2
  done
  hub_bounded 1 rm -f -- "${out_file}" "${err_file}" || true
  err "Could not read the live filter table with '${save_bin}' (${attempts} attempts). Last cause: ${cause:0:400}"
  err "Recovery: run '${save_bin}' as root and check it exits 0 with no warning. A 'legacy tables present' warning means rules live in iptables-legacy while iptables points at nft; move them to one backend, then rerun this installer."
  if ((timed_out == 1)); then
    return 124
  fi
  return 1
}

# Strict iptables-save grammar (Turn 5). Reads a complete save on stdin;
# exits 0 and prints the *filter section when every line is valid, exits 3
# otherwise. Accepted, and nothing else:
#   - outside a table: "# Generated by ..." and "# Completed on ..." only
#     (Seat C N-5: iptables-nft-save reports a table it cannot show as
#     "# Table `filter' is incompatible, use 'nft' tool." and exits 0);
#   - "*<table>" for raw, mangle, filter, nat, security, each at most once;
#   - chain declarations, before any rule of the table, once per chain:
#     ":<chain> <policy> [<packets>:<bytes>]" with policy ACCEPT or DROP for
#     a built-in chain and "-" for a user chain;
#   - "-A <declared chain> <rule body>" whose body is a sequence of options:
#     an optional "!", then an option token (-s -d -p -i -o -m -j -g -f, or
#     --long-name), then its arguments. -s/-d take one IPv4 network, -p one
#     protocol name or a number up to 255, -i/-o one interface, -m one match
#     name, -j/-g one target name and at most one -j/-g per rule. A long
#     option must be in the ARITY table (iptables 1.8.10 matches and targets)
#     and takes exactly that many arguments, none of which may look like an
#     option (free-text ones such as --comment may); port arguments must be
#     numbers up to 65535, lo:hi ranges or service names, and a comma list
#     only for the multiport options; --tcp-flags, --ctstate and --state
#     values must be comma lists of the names iptables 1.8.10 knows. An
#     unlisted option, a missing argument (Sol T5: "--dport -j DROP"), a value
#     outside those grammars (Sol N-11) or a surplus token is UNKNOWN, and the
#     refusal names the line. Other option values are checked for shape only
#     (not empty, not an option). Quoting must balance (shlex);
#   - "COMMIT" closing the open table.
hub_ruleset_validate() {
  hub_run python3 -c '
import ipaddress, re, shlex, sys

BUILTIN = {
    "raw": {"PREROUTING", "OUTPUT"},
    "mangle": {"PREROUTING", "INPUT", "FORWARD", "OUTPUT", "POSTROUTING"},
    "filter": {"INPUT", "FORWARD", "OUTPUT"},
    "nat": {"PREROUTING", "INPUT", "OUTPUT", "POSTROUTING"},
    "security": {"INPUT", "FORWARD", "OUTPUT"}}
NAME = re.compile(r"^[A-Za-z0-9_.+-]{1,28}$")
IFACE = re.compile(r"^[A-Za-z0-9_.:@+-]{1,16}$")
PROTO = re.compile(r"^[a-z][a-z0-9-]*$")
LONG = re.compile(r"^--[a-z0-9][a-z0-9-]*$")
SHORT_WITH_ARG = {"-s", "-d", "-p", "-i", "-o", "-m", "-j", "-g"}


# Long options seen in iptables-save output on a hub, with the number of
# arguments each takes (iptables 1.8.10 extensions). An option not listed is
# rejected: the reader then answers UNKNOWN and names the line, which is
# safer than guessing an arity.
ARITY = {}
for _name in (
    "--dport --sport --dports --sports --destination-port --source-port --destination-ports "
    "--source-ports --ports --comment --ctstate --state --ctproto --ctorigsrc --ctorigdst "
    "--ctreplsrc --ctrepldst --ctorigsrcport --ctorigdstport --ctreplsrcport --ctrepldstport "
    "--ctstatus --ctexpire --ctdir --limit --limit-burst --log-prefix --log-level --reject-with "
    "--queue-num --queue-balance --to-destination --to-source --to-ports --to --mark --set-mark "
    "--set-xmark --and-mark --or-mark --xor-mark --nfmask --ctmask --icmp-type --tcp-option --mss "
    "--set-mss --string --algo --from --hex-string --name --seconds --hitcount --mask "
    "--hashlimit-upto --hashlimit-above --hashlimit-burst --hashlimit-mode --hashlimit-srcmask "
    "--hashlimit-dstmask --hashlimit-name --hashlimit-htable-size --hashlimit-htable-max "
    "--hashlimit-htable-expire --hashlimit-htable-gcinterval --hashlimit-rate-interval --u32 "
    "--src-range --dst-range --length --ttl-eq --ttl-gt --ttl-lt --ttl-set --ttl-dec --ttl-inc "
    "--tos --set-tos --and-tos --or-tos --xor-tos --mode --every --packet --probability "
    "--timestart --timestop --datestart --datestop --weekdays --monthdays --connlimit-upto "
    "--connlimit-above --connlimit-mask --pkt-type --dir --pol --reqid --spi --proto "
    "--tunnel-src --tunnel-dst --nflog-group --nflog-prefix --nflog-range --nflog-size "
    "--nflog-threshold --uid-owner --gid-owner --path --cgroup --zone --zone-orig --zone-reply "
    "--helper --ctevents --expevents --timeout --src-type --dst-type --set-dscp --set-dscp-class "
    "--dscp --dscp-class --mac-source --physdev-in --physdev-out --set-class --packets-eq "
    "--bytes-eq --packets-lt --bytes-lt --packets-gt --bytes-gt --save-mark-mask --restore-mark-mask "
    "--ahspi --espspi --ipcompspi --bytecode --cluster-hash-seed --cluster-local-node "
    "--cluster-local-nodemask --cluster-total-nodes --clustermac --connbytes --connbytes-dir "
    "--connbytes-mode --cpu --dst-group --src-group --gateway --genre --hash-init --hashmode "
    "--label --led-delay --led-trigger-id --left-shift-mark --right-shift-mark --local-node "
    "--total-nodes --log --nfacct-name --object-pinned --oif --on-ip --on-port --quota --realm "
    "--selctx --strip-options --tproxy-mark --ttl --ulog-cprange --ulog-nlgroup --ulog-prefix "
    "--ulog-qthreshold --vaddr --vdir --vmethod --vport --vportctl --vproto --wscale --dccp-types "
    "--dccp-option --ecn-ip-ect "
    # N-12, Turn 8: the AUDIT and HMARK targets, as iptables 1.8.10 saves them
    # (measured on colima-l80, nf_tables and legacy).
    "--type --hmark-tuple --hmark-mod --hmark-offset --hmark-rnd --hmark-src-prefix "
    "--hmark-dst-prefix --hmark-sport-mask --hmark-dport-mask --hmark-spi-mask --hmark-proto-mask "
    "--hmark-sport --hmark-dport --hmark-spi"
    ).split():
    ARITY[_name] = 1
for _name in (
    "--log-tcp-sequence --log-tcp-options --log-ip-options --log-uid --log-macdecode --random "
    "--random-fully --persistent --queue-bypass --fail-open --clamp-mss-to-pmtu --syn --transparent "
    "--nowildcard --rsource --rdest --set --rcheck --update --remove --rttl --reap "
    "--hashlimit-rate-match --connlimit-saddr --connlimit-daddr --next --strict --socket-exists "
    "--suppl-groups --notrack --limit-iface-in --limit-iface-out --return-nomatch --update-counters "
    "--update-subcounters --physdev-is-in --physdev-is-out --physdev-is-bridged --save-mark "
    "--restore-mark --kerneltz --utc --contiguous --exist --ecn-tcp-cwr --ecn-tcp-ece "
    "--accept-local --loose --validmark --invert --alarm --ecn --sack-perm --timestamp --icase "
    "--ipvs --led-always-blink --map-mark --map-prio --map-queue --new --restore --save "
    "--restore-skmark --queue-cpu-fanout --checksum-fill --ecn-tcp-remove"
    ).split():
    ARITY[_name] = 0
for _name in ("--tcp-flags", "--match-set", "--set-counters", "--add-set", "--del-set", "--map-set",
              "--chunk-types"):
    ARITY[_name] = 2
# N-12, Turn 8: the same name can take a different number of arguments after a
# target. The ecn MATCH takes --ecn-tcp-cwr and --ecn-tcp-ece as flags; the
# ECN TARGET saves them with a value ("-j ECN --ecn-tcp-ece 1 --ecn-tcp-cwr 1").
TARGET_ARITY = {"ECN": {"--ecn-tcp-cwr": 1, "--ecn-tcp-ece": 1}}
# Options whose argument is free text (it may itself look like an option).
FREE = {"--comment", "--log-prefix", "--nflog-prefix", "--string", "--hex-string", "--path", "--u32"}
PORT_OPTS = {"--dport", "--sport", "--dports", "--sports", "--destination-port", "--source-port",
             "--destination-ports", "--source-ports", "--ports"}
# tcp, udp, sctp and dccp take ONE port or one lo:hi range; only multiport
# takes a comma list (N-11, Turn 7).
SINGLE_PORT_OPTS = {"--dport", "--sport", "--destination-port", "--source-port"}
SERVICE = re.compile(r"^[a-z][a-z0-9-]*$")
# Value grammars of iptables 1.8.10 (libxt_tcp, libxt_conntrack): a value the
# extension would refuse to load cannot come from a real save (N-11, Turn 7).
TCP_FLAGS = {"FIN", "SYN", "RST", "PSH", "ACK", "URG", "ALL", "NONE"}
CTSTATES = {"INVALID", "NEW", "RELATED", "ESTABLISHED", "UNTRACKED", "SNAT", "DNAT"}
STATES = {"INVALID", "NEW", "RELATED", "ESTABLISHED", "UNTRACKED"}
# N-12, Turn 8 (libxt_AUDIT, libxt_HMARK): the AUDIT type is saved in lower
# case, and the HMARK tuple is a comma list of these words.
AUDIT_TYPES = {"accept", "drop", "reject"}
HMARK_TUPLE = {"src", "dst", "sport", "dport", "spi", "proto", "ct"}
WORD_LISTS = {"--tcp-flags": TCP_FLAGS, "--ctstate": CTSTATES, "--state": STATES,
              "--type": AUDIT_TYPES, "--hmark-tuple": HMARK_TUPLE}


def is_option(tok):
    return tok in SHORT_WITH_ARG or tok == "-f" or bool(LONG.match(tok))


def valid_ports(arg):
    if not arg:
        return False
    for part in arg.split(","):
        pieces = part.split(":")
        if len(pieces) > 2:
            return False
        for piece in pieces:
            if piece.isdigit():
                if int(piece) > 65535:
                    return False
            elif not SERVICE.match(piece):
                return False
    return True


def valid_arg(opt, arg):
    if opt in FREE:
        return True
    if opt in SINGLE_PORT_OPTS and "," in arg:
        return False
    if opt in PORT_OPTS:
        return valid_ports(arg)
    if opt in WORD_LISTS:
        return all(word in WORD_LISTS[opt] for word in arg.split(","))
    if arg == "" or arg == "!":
        return False
    if arg.startswith("-") and not re.fullmatch(r"-[0-9]+", arg):
        return False
    return True


def valid_protocol(arg):
    if arg.isdigit():
        return int(arg) <= 255
    return bool(PROTO.match(arg))


def valid_body(tokens):
    if not tokens:
        return False
    i, targets, target = 0, 0, ""
    while i < len(tokens):
        if tokens[i] == "!":
            i += 1
            if i >= len(tokens) or not is_option(tokens[i]):
                return False
        opt = tokens[i]
        if not is_option(opt):
            return False
        i += 1
        if opt == "-f":
            continue
        if opt in SHORT_WITH_ARG:
            if i >= len(tokens) or is_option(tokens[i]) or tokens[i] == "!":
                return False
            arg = tokens[i]
            i += 1
            if opt in ("-s", "-d"):
                try:
                    if ipaddress.ip_network(arg, strict=False).version != 4:
                        return False
                except ValueError:
                    return False
            elif opt == "-p":
                if not valid_protocol(arg):
                    return False
            elif opt in ("-i", "-o"):
                if not IFACE.match(arg):
                    return False
            else:
                if not NAME.match(arg):
                    return False
                if opt in ("-j", "-g"):
                    targets += 1
                    target = arg
            continue
        arity = TARGET_ARITY.get(target, {}).get(opt, ARITY.get(opt))
        if arity is None:
            return False
        for _ in range(arity):
            if i >= len(tokens) or not valid_arg(opt, tokens[i]):
                return False
            i += 1
    return targets <= 1


def main():
    data = sys.stdin.read()
    if not data.endswith("\n"):
        sys.stderr.write("no final newline")
        return 3
    result = check(data[:-1].split("\n"))
    if isinstance(result, str):
        sys.stderr.write("first rejected line: " + result[:200])
        return 3
    if result is not None:
        print("\n".join(result))
    return 0


def check(lines):
    tables, table, chains, cur, rules_started = {}, None, set(), [], False
    for line in lines:
        if table is None:
            if line.startswith("# Generated by ") or line.startswith("# Completed on "):
                continue
            m = re.fullmatch(r"\*([a-z]+)", line)
            if not m or m.group(1) not in BUILTIN or m.group(1) in tables:
                return line
            table, chains, cur, rules_started = m.group(1), set(), [line], False
            continue
        if line == "COMMIT":
            cur.append(line)
            tables[table] = cur
            table = None
            continue
        m = re.fullmatch(r":(\S+) (\S+) \[([0-9]+):([0-9]+)\]", line)
        if m:
            chain, policy = m.group(1), m.group(2)
            if rules_started or chain in chains or not NAME.match(chain):
                return line
            if chain in BUILTIN[table]:
                if policy not in ("ACCEPT", "DROP"):
                    return line
            elif policy != "-":
                return line
            chains.add(chain)
            cur.append(line)
            continue
        if line.startswith("-A "):
            try:
                tokens = shlex.split(line)
            except ValueError:
                return line
            if len(tokens) < 3 or tokens[1] not in chains or not valid_body(tokens[2:]):
                return line
            rules_started = True
            cur.append(line)
            continue
        return line
    if table is not None:
        return "(end of input inside a table)"
    if not tables:
        return "(no table)"
    if "filter" not in tables:
        # Well-formed, but no filter table: definitely no hub chains.
        return None
    return tables["filter"]


sys.exit(main())
'
}

# Prints "present" or "absent" for one filter-table chain; returns 1 on
# UNKNOWN.
hub_filter_chain_state() {
  local chain="$1" dump
  dump="$(hub_filter_ruleset_dump)" || return 1
  if [[ $'\n'"${dump}" == *$'\n'":${chain} "* ]]; then
    printf 'present\n'
  else
    printf 'absent\n'
  fi
}

hub_input_chain_state() {
  hub_filter_chain_state WINVPN-HUB-INPUT
}

# The f2b-sshd rules that block an exempt source, read from a filter-table
# dump on stdin. A rule blocks unless its target is RETURN, ACCEPT, LOG or
# NFLOG (so DROP, REJECT and any jump count). Its source blocks an exempt
# source when it OVERLAPS any ignoreip network: a /32 inside an admin CIDR, a
# wide CIDR covering the deploy source, a rule with no -s, or a negated -s.
# Mode "spec" prints each rule's arguments after "-A f2b-sshd", separated by
# US (0x1f), exactly as iptables-save printed them, for an exact -D. Mode
# "line" prints the rules as dumped, for messages.
hub_f2b_exempt_ban_rules() {
  python3 -c '
import ipaddress, shlex, sys
nets = []
for entry in sys.argv[1].split():
    try:
        net = ipaddress.ip_network(entry, strict=False)
    except ValueError:
        continue
    if net.version == 4:
        nets.append(net)
mode = sys.argv[2]
# Free-text values are values, never options (Sol N-10, Turn 7): a comment
# "-s" or "-j" must not be read as the source or the target.
FREE = {"--comment", "--log-prefix", "--nflog-prefix", "--string", "--hex-string", "--path", "--u32"}


def first(body, name):
    i, neg = 0, False
    while i < len(body):
        tok = body[i]
        i += 1
        if tok == "!":
            neg = True
            continue
        if tok == name and i < len(body):
            return body[i], neg
        if tok in FREE:
            i += 1
        neg = False
    return None, False


seen = set()
for line in sys.stdin.read().splitlines():
    if not line.startswith("-A f2b-sshd "):
        continue
    args = shlex.split(line.replace(chr(92) + chr(39), chr(39)))
    target, _ = first(args[2:], "-j")
    if target in {"RETURN", "ACCEPT", "LOG", "NFLOG"}:
        continue
    source = ipaddress.ip_network("0.0.0.0/0")
    value, negated = first(args[2:], "-s")
    if value is not None and not negated:
        source = ipaddress.ip_network(value, strict=False)
    if not any(source.overlaps(n) for n in nets):
        continue
    if line in seen:
        continue
    seen.add(line)
    print("\x1f".join(args[2:]) if mode == "spec" else "-A f2b-sshd " + shlex.join(args[2:]))
' "$(hub_fail2ban_ignoreips)" "$1"
}

# SC-1 second guarantee, fail closed: delete from the live f2b-sshd chain every
# rule that blocks an exempt source (exactly as iptables-save printed it, so
# extra matches such as comments do not stop the deletion), then RE-READ the
# table and prove none is left. Returns 1 (the caller must refuse its firewall
# commit) when the table cannot be read, a helper fails, or such a rule
# survives. Only ever removes rules that block addresses this hub already
# exempts; never adds one. fail2ban-client unbanip is best effort for single
# host bans: the kernel rule is what can cut the session.
hub_f2b_purge_ignored_bans() {
  local live_iptables="$1" dump specs rec source remaining i
  local -a records=() spec=()
  dump="$(hub_filter_ruleset_dump)" || return 1
  specs="$(hub_f2b_exempt_ban_rules spec <<<"${dump}")" || {
    err "Could not evaluate f2b-sshd rules against the ignoreip set."
    return 1
  }
  if [[ -n "${specs}" ]]; then
    mapfile -t records <<<"${specs}"
    for rec in "${records[@]}"; do
      IFS=$'\x1f' read -r -a spec <<<"${rec}"
      source=""
      for ((i = 0; i + 1 < ${#spec[@]}; i++)); do
        [[ "${spec[i]}" == "-s" ]] && source="${spec[i + 1]}"
      done
      warn "Removing an f2b-sshd rule that blocks an exempt source (admin CIDR or deploy source): -A f2b-sshd ${spec[*]}"
      while "${live_iptables}" -w 10 -D f2b-sshd "${spec[@]}" 2>/dev/null; do :; done
      if [[ "${source}" == */32 ]] && command -v fail2ban-client >/dev/null 2>&1; then
        fail2ban-client set sshd unbanip "${source%/32}" >/dev/null 2>&1 \
          || warn "fail2ban-client could not unban ${source}; the kernel rule is gone and fail2ban's own restart with the current ignoreip will not restore it."
      fi
    done
  fi
  dump="$(hub_filter_ruleset_dump)" || return 1
  remaining="$(hub_f2b_exempt_ban_rules line <<<"${dump}")" || {
    err "Could not re-check f2b-sshd rules against the ignoreip set."
    return 1
  }
  if [[ -n "${remaining}" ]]; then
    err "f2b-sshd rules that block an exempt source survived deletion:"
    while IFS= read -r rec; do
      err "  ${rec}"
    done <<<"${remaining}"
    err "Recovery: inspect with: iptables-save -t filter | grep -- '-A f2b-sshd'. Remove each rule listed above with: iptables -D f2b-sshd <the same arguments> (or fail2ban-client set sshd unbanip <ip>), then rerun this installer."
    return 1
  fi
  return 0
}

# OI-CPA-10A / Sol N-1 (Turn 5): prove new tcp/22 traffic reaches f2b-sshd
# before anything could accept it. Reads a filter section on stdin; exits 0
# when all of these hold, and prints the reason and exits 1 otherwise:
#   - the f2b-sshd chain is declared;
#   - INPUT has an unconditional "-j WINVPN-HUB-INPUT", and no INPUT rule
#     before it could accept tcp/22;
#   - WINVPN-HUB-INPUT has a jump to f2b-sshd that matches ALL tcp/22 packets
#     (-p tcp, dport 22 or a dports list containing 22, no other condition),
#     and no rule before it could accept tcp/22.
# "Could accept tcp/22" is conservative: any target other than DROP, REJECT,
# LOG, NFLOG and f2b-sshd (a narrower ban jump), on a rule whose protocol is absent,
# tcp or negated and whose destination-port condition is absent, negated or
# includes 22. A conntrack ESTABLISHED accept counts.
hub_f2b_traversal_check() {
  hub_run python3 -c '
import shlex, sys

lines = sys.stdin.read().splitlines()
declared = {l.split()[0][1:] for l in lines if l.startswith(":")}
if "f2b-sshd" not in declared:
    print("the f2b-sshd chain is missing"); sys.exit(1)
rules = {}
for line in lines:
    if line.startswith("-A "):
        t = shlex.split(line)
        rules.setdefault(t[1], []).append(t[2:])

NON_BYPASS = {"DROP", "REJECT", "LOG", "NFLOG", "f2b-sshd"}
# Options whose argument is free text, as in hub_ruleset_validate.
FREE = {"--comment", "--log-prefix", "--nflog-prefix", "--string", "--hex-string", "--path", "--u32"}


def options(body):
    # (option, value, negated) for every option of a rule body, in order. The
    # token after a free-text option is its value, never an option: iptables
    # prints a plain comment unquoted, so "--comment -p -j ACCEPT" is an
    # unconditional ACCEPT whose comment is "-p" (Sol N-10, Turn 7). The body
    # passed hub_ruleset_validate, so no other argument looks like an option.
    out, i, neg = [], 0, False
    while i < len(body):
        tok = body[i]
        i += 1
        if tok == "!":
            neg = True
            continue
        if not tok.startswith("-"):
            neg = False
            continue
        out.append((tok, body[i] if i < len(body) else None, neg))
        neg = False
        if tok in FREE:
            i += 1
    return out


def opt(body, name):
    for tok, value, neg in options(body):
        if tok == name and value is not None:
            return value, neg
    return None, False


def ports(value):
    out = set()
    for part in value.split(","):
        if ":" in part:
            lo, hi = part.split(":", 1)
            try:
                out.update(range(int(lo or 0), int(hi or 65535) + 1))
            except ValueError:
                return None
        else:
            try:
                out.add(int(part))
            except ValueError:
                return None
    return out


def could_match_tcp22(body):
    proto, neg = opt(body, "-p")
    if proto is not None and not neg and proto not in ("tcp", "6"):
        return False
    for name in ("--dport", "--dports", "--destination-port", "--destination-ports"):
        value, vneg = opt(body, name)
        if value is not None and not vneg:
            p = ports(value)
            if p is not None and 22 not in p:
                return False
    return True


def target(body):
    for name in ("-j", "-g"):
        value, _ = opt(body, name)
        if value is not None:
            return value
    return None


def covers_all_tcp22(body):
    # Exactly {-p tcp, one destination-port set containing 22, -j f2b-sshd},
    # with -m tcp or -m multiport only to load that port option. Any other
    # match (-m socket, a second port set, a negation, a source) can make the
    # jump skip new tcp/22 packets, so it is not covering.
    proto, neg = opt(body, "-p")
    if proto not in ("tcp", "6") or neg or "!" in body:
        return False
    allowed = {"-p", "-m", "--dport", "--dports", "--destination-port", "--destination-ports", "-j"}
    names = [tok for tok in body if tok.startswith("-")]
    if any(n not in allowed for n in names):
        return False
    modules = [body[i + 1] for i, tok in enumerate(body[:-1]) if tok == "-m"]
    if any(m not in ("tcp", "multiport") for m in modules) or len(modules) != len(set(modules)):
        return False
    port_names = [n for n in names if n.startswith("--")]
    if len(port_names) != 1:
        return False
    value, _ = opt(body, port_names[0])
    p = ports(value) if value is not None else None
    return p is not None and 22 in p


def first_bypass(chain, stop):
    for body in rules.get(chain, []):
        if stop(body):
            return None, True
        t = target(body)
        if t not in NON_BYPASS and could_match_tcp22(body):
            return body, False
    return None, False


def hub_jump(body):
    return target(body) == "WINVPN-HUB-INPUT" and all(tok in ("-j", "WINVPN-HUB-INPUT") for tok in body)


bypass, reached = first_bypass("INPUT", hub_jump)
if not reached:
    if bypass is None:
        print("INPUT has no unconditional jump to WINVPN-HUB-INPUT")
    else:
        print("INPUT can accept tcp/22 before WINVPN-HUB-INPUT: -A INPUT " + shlex.join(bypass))
    sys.exit(1)


def f2b_jump(body):
    return target(body) == "f2b-sshd" and covers_all_tcp22(body)


bypass, reached = first_bypass("WINVPN-HUB-INPUT", f2b_jump)
if not reached:
    if bypass is None:
        print("WINVPN-HUB-INPUT has no jump to f2b-sshd covering all tcp/22 traffic")
    else:
        print("WINVPN-HUB-INPUT can accept tcp/22 before f2b-sshd: -A WINVPN-HUB-INPUT " + shlex.join(bypass))
    sys.exit(1)
sys.exit(0)
'
}

# OI-CPA-10A / Sol N-1: one definite read, then the traversal proof. An
# unreadable table is a failure.
hub_f2b_require_jump() {
  local context="$1" dump reason
  dump="$(hub_filter_ruleset_dump)" || return 1
  if ! reason="$(hub_f2b_traversal_check <<<"${dump}")"; then
    err "SSH does not reliably traverse f2b-sshd ${context}: ${reason:-the traversal check failed}. No ban would apply to that traffic."
    err "Recovery: check 'journalctl -u fail2ban' for an actionstart error and 'iptables-save -t filter' for the INPUT and WINVPN-HUB-INPUT chains, then rerun this installer."
    return 1
  fi
  return 0
}

# OI-CPA-10A and F2B-VERSION (Turns 5 and 6): after a fail2ban restart,
# prove the action really re-initialised the ban chain. One observation
# (hub_f2b_restart_observe) requires, in order:
#   1. the actionstart stamp ($2): the action writes it as its last step, only
#      after the flush AND the link succeeded, and the caller removed it before
#      the restart, so it proves THIS actionstart succeeded (a failed flush,
#      exit 4, never writes it, even when a restored chain and jump survive).
#      The stamp is mandatory: an empty $2 names no file, so it cannot pass;
#   2. "fail2ban-client get sshd actions" names wins-iptables-hub, so the
#      running jail uses this action;
#   3. unless $3 is 0, the traversal proof on a definite read of the filter
#      table. The restart that main() runs BEFORE the first firewall write
#      passes 0: on a hub whose chain survived from rules.v4 the old jump may
#      still sit below the accepts until that write moves it, and the post
#      commit proof in write_iptables covers the final order;
#   4. "fail2ban-client status sshd" with exactly one "Banned IP list:" line;
#   5. f2b-sshd holds exactly one "-s <net> -j DROP" per IPv4 ban (address or
#      CIDR) and nothing else. IPv6 bans are reported, not compared: the hub
#      action is IPv4 only and IPv6 SSH is closed by policy (Seat C N-6).
# Bans held before the restart ($1) that are neither ignored nor restored are
# PENDING: the proof keeps polling for them for the WHOLE window, because
# restored tickets wait in fail2ban's queue and are absent from both views
# until the actions thread takes them (Sol N-6). The remaining polls are
# spread so the last one ends half a poll before the deadline (N-14, Turn 8),
# and when none fits the proof sleeps out the rest of the window. Only then is
# a ban that is still pending reported as lost, with the elapsed time
# measured, and the proof FAILS (N-6, Turn 7): the deploy stops until an
# operator has seen it. A ban whose bantime has ended is EXPIRED, not pending
# (N-13, Turn 8), and the verdict judges that again at its own time (Turn 9).
# Observations that stop before the deadline (a command killed early) fail
# the proof without any claim about lost bans (Sol N-6, Turn 8).
# The deadline is real, total time (Sol N-7, Turns 6 and 7):
# HUB_F2B_PROOF_SECONDS (default 15) from the first line of the proof, on a
# monotonic millisecond clock (hub_now). Every subprocess of the proof is
# bounded by the time left: the version lookup, the jail calls, the table
# read (one attempt), and through hub_run the temporary files and the python
# validator, traversal check, status parser and comparison. A command the
# deadline cuts short (exit 124) says nothing about the jail, so it never
# replaces the last observation that completed. Outside the clock: timeout(1)'s
# own 1 s kill grace for a command that ignores SIGTERM, and the removal of
# the read's two temporary files (bounded to 1 s).
hub_f2b_left() {
  printf '%s\n' "$((_HUB_F2B_DEADLINE - $(hub_now)))"
}

# The time left as a timeout(1) duration; returns 1 when none is left.
hub_f2b_budget() {
  local left
  left="$(hub_f2b_left)"
  ((left > 0)) || return 1
  hub_duration "${left}"
}

# One observation. Prints "OK <v4 bans> | pending <ips> | v6 <ips>" and returns
# 0 when the proof holds; prints the reason and returns 1 when this
# observation does not hold; prints the reason and returns 2 when the deadline
# cut it short.
hub_f2b_restart_observe() {
  local before="$1" stamp="$2" traversal="${3:-1}" budget rc dump actions status banned flat
  budget="$(hub_f2b_budget)" || { echo "the deadline was reached"; return 2; }
  if [[ ! -e "${stamp}" ]]; then
    echo "actionstart has not completed successfully (no ${stamp:-actionstart stamp}): the flush or the link failed, or the action has not run yet"
    return 1
  fi
  rc=0
  actions="$(hub_bounded "${budget}" fail2ban-client get sshd actions 2>&1)" || rc=$?
  if ((rc == 124 || rc == 137)); then
    echo "fail2ban-client get sshd actions was cut off by the deadline"
    return 2
  elif ((rc != 0)); then
    echo "fail2ban-client get sshd actions failed: ${actions:0:200}"
    return 1
  fi
  # 1.0.2 prints "The jail sshd has the following actions:" then the names
  # joined by ", "; compare whole names only.
  flat="${actions//$'\n'/ }"
  flat="${flat//,/ }"
  if [[ " ${flat} " != *" wins-iptables-hub "* ]]; then
    echo "the sshd jail does not run the wins-iptables-hub action: ${actions:0:200}"
    return 1
  fi
  budget="$(hub_f2b_budget)" || { echo "the deadline was reached"; return 2; }
  rc=0
  dump="$(hub_filter_ruleset_dump 1 "${budget}" 2>&1)" || rc=$?
  if ((rc == 124)); then
    echo "the filter table read was cut off by the deadline"
    return 2
  elif ((rc != 0)); then
    echo "the filter table is unreadable: ${dump:0:300}"
    return 1
  fi
  if [[ "${traversal}" != "0" ]]; then
    rc=0
    hub_f2b_traversal_check <<<"${dump}" || rc=$?
    if ((rc == 124 || rc == 137)); then
      echo "the traversal check was cut off by the deadline"
      return 2
    elif ((rc != 0)); then
      return 1
    fi
  fi
  budget="$(hub_f2b_budget)" || { echo "the deadline was reached"; return 2; }
  rc=0
  status="$(hub_bounded "${budget}" fail2ban-client status sshd 2>&1)" || rc=$?
  if ((rc == 124 || rc == 137)); then
    echo "fail2ban-client status sshd was cut off by the deadline"
    return 2
  elif ((rc != 0)); then
    echo "fail2ban-client status sshd failed: ${status:0:200}"
    return 1
  fi
  rc=0
  banned="$(hub_run python3 -c '
import sys
found = [l for l in sys.stdin.read().splitlines() if "Banned IP list:" in l]
if len(found) != 1:
    sys.exit(1)
print(" ".join(sorted(set(found[0].split("Banned IP list:", 1)[1].split()))))
' <<<"${status}")" || rc=$?
  if ((rc == 124 || rc == 137)); then
    echo "reading the jail's banned list was cut off by the deadline"
    return 2
  elif ((rc != 0)); then
    echo "fail2ban-client status sshd has no single 'Banned IP list:' line"
    return 1
  fi
  rc=0
  hub_run python3 -c '
import ipaddress, shlex, sys, time
banned, before, ignore = (x.split() for x in sys.argv[1:4])
v4, v6 = set(), []
for entry in banned:
    try:
        net = ipaddress.ip_network(entry, strict=False)
    except ValueError:
        print("fail2ban lists an unparseable ban: " + entry)
        sys.exit(1)
    if net.version == 4:
        v4.add(str(net))
    else:
        v6.append(entry)
seen = set()
for line in sys.stdin.read().splitlines():
    if not line.startswith("-A f2b-sshd "):
        continue
    body = shlex.split(line)[2:]
    if len(body) == 4 and body[0] == "-s" and body[2:] == ["-j", "DROP"]:
        try:
            net = str(ipaddress.ip_network(body[1], strict=False))
        except ValueError:
            net = ""
        if net in v4 and net not in seen:
            seen.add(net)
            continue
    print("f2b-sshd holds a rule fail2ban does not account for: -A f2b-sshd " + shlex.join(body))
    sys.exit(1)
missing = sorted(v4 - seen)
if missing:
    print("fail2ban reports bans with no kernel rule: " + " ".join(missing))
    sys.exit(1)
nets = []
for entry in ignore:
    try:
        nets.append(ipaddress.ip_network(entry, strict=False))
    except ValueError:
        pass
listed = set()
for entry in banned:
    listed.add(str(ipaddress.ip_network(entry, strict=False)))
pending, expired = [], []
# N-13, Turn 8: a "before" entry may carry the end of its bantime as
# "<ip>@<epoch seconds>" (hub_f2b_bans_before). fail2ban does not restore a
# ticket whose bantime has ended and unbans a live one when it ends, so such a
# ban is EXPIRED, not pending. The printed end is cut to whole seconds, so it
# counts as ended only from one second later. Wall-clock time is right here:
# fail2ban measures bantime on the wall clock too. Whole seconds from
# hub_wall_now, read just before this ran (Turn 9): the verdict applies the
# same rule on the same clock (hub_f2b_split_pending), and with an integer
# end, floor(now) >= end + 1 holds exactly when now >= end + 1 does.
now = int(sys.argv[4])
for entry in sorted(set(before)):
    address, _, end = entry.partition("@")
    try:
        net = ipaddress.ip_network(address, strict=False)
    except ValueError:
        continue
    if str(net) in listed:
        continue
    if any(net.version == n.version and net.subnet_of(n) for n in nets):
        continue
    if end.isdigit() and now >= int(end) + 1:
        expired.append(address)
        continue
    pending.append(address)
print("OK " + " ".join(sorted(v4)) + " | pending " + " ".join(pending) + " | v6 " + " ".join(v6)
      + " | expired " + " ".join(expired))
' "${banned}" "${before}" "$(hub_fail2ban_ignoreips)" "$(hub_wall_now)" <<<"${dump}" || rc=$?
  if ((rc == 124 || rc == 137)); then
    echo "comparing the kernel with the jail was cut off by the deadline"
    return 2
  fi
  # Any other failure (python's own exit 2 included) is a failed observation.
  ((rc == 0)) || return 1
}

# N-13 (Sol, Turn 8): an observation judges expiry at its own time, and the
# verdict comes later (after the naps that wait out the window). Apply the
# same rule again at the verdict: $1 is the wall clock (hub_wall_now), $2 the
# pending addresses of the last observation, $3 the snapshot ("<ip>" or
# "<ip>@<end>"). Prints "<still pending> | expired <ended since>". An address
# counts as ended only when every snapshot entry for it carries an end and
# now >= end + 1; one with no entry, no end or an end still to come stays
# pending. Each address is printed once. Builtins only, so it needs no time
# from the proof's budget.
hub_f2b_split_pending() {
  local now="$1" address entry end state still="" ended=""
  local -a addresses=() entries=()
  read -r -a addresses <<<"${2:-}"
  read -r -a entries <<<"${3:-}"
  for address in "${addresses[@]}"; do
    [[ " ${still} ${ended} " != *" ${address} "* ]] || continue
    state=""
    for entry in "${entries[@]}"; do
      [[ "${entry%%@*}" == "${address}" ]] || continue
      end="${entry#*@}"
      if [[ "${entry}" == *@* && "${end}" =~ ^[0-9]{1,18}$ ]] && ((now >= 10#${end} + 1)); then
        [[ -n "${state}" ]] || state="ended"
      else
        state="live"
      fi
    done
    if [[ "${state}" == "ended" ]]; then
      ended+="${ended:+ }${address}"
    else
      still+="${still:+ }${address}"
    fi
  done
  printf '%s | expired %s\n' "${still}" "${ended}"
}

hub_f2b_prove_restart() {
  local before="${1:-}" stamp="${2:-}" traversal="${3:-1}" budget_s start obs="" cut="" matched=0 rc cur
  local pending="" v6="" expired="" bans left version="" t0 cost need nap elapsed span cycles fit why
  local split ended=""
  # Local: only this proof and the helpers it calls see the deadline (hub_run).
  local _HUB_F2B_DEADLINE
  budget_s="${HUB_F2B_PROOF_SECONDS:-15}"
  [[ "${budget_s}" =~ ^[0-9]+$ ]] && ((budget_s >= 1)) || budget_s=15
  start="$(hub_now)"
  _HUB_F2B_DEADLINE=$((start + budget_s * 1000))
  # The version goes into the log line and is looked up inside the budget.
  left="$(hub_f2b_left)"
  if ((left > 0)); then
    ((left <= 5000)) || left=5000
    version="$(hub_bounded "$(hub_duration "${left}")" fail2ban-client version 2>/dev/null || true)"
    version="${version%%$'\n'*}"
  fi
  while (($(hub_f2b_left) > 0)); do
    rc=0
    t0="$(hub_now)"
    cur="$(hub_f2b_restart_observe "${before}" "${stamp}" "${traversal}")" || rc=$?
    cost=$(($(hub_now) - t0))
    if ((rc == 2)); then
      cut="${cur}"
      break
    fi
    obs="${cur}"
    matched=0
    if ((rc == 0)); then
      matched=1
      pending="${obs#*| pending }"
      pending="${pending%% | v6 *}"
      [[ -z "${pending// /}" ]] && break
    fi
    left="$(hub_f2b_left)"
    # The next poll needs about as long as this one took; half again is kept
    # in hand. N-14 (Turn 8): the polls still to come are spread evenly, so
    # the LAST one ends cost/2 before the deadline instead of wherever 1 s
    # naps happen to leave it. Run the fewest polls that keep every nap
    # within 1 s, but never more than fit: when one poll costs more than 1 s
    # the nap grows instead of going negative.
    need=$((cost + cost / 2))
    if ((left > need)); then
      span=$((left - need))
      cycles=$(((span + 2 * cost + 999) / (1000 + cost)))
      fit=$((span / (cost > 0 ? cost : 1) + 1))
      ((cycles <= fit)) || cycles="${fit}"
      nap=$(((span - (cycles - 1) * cost) / cycles))
      sleep "$(hub_duration "${nap}")"
    elif ((matched == 1 && left > 0)); then
      # Bans are still pending and no further poll fits: wait out the window
      # before calling them lost (N-6, Turn 7).
      sleep "$(hub_duration "${left}")"
      break
    else
      break
    fi
  done
  # N-13 (Turn 9): the pending list comes from the last observation; a ban
  # whose bantime ended since then is expired, not lost (nor pending below).
  if ((matched == 1)) && [[ -n "${pending// /}" ]]; then
    split="$(hub_f2b_split_pending "$(hub_wall_now)" "${pending}" "${before}")"
    pending="${split%% | expired *}"
    ended="${split#* | expired }"
  fi
  elapsed="$(hub_duration "$(($(hub_now) - start))")"
  left="$(hub_f2b_left)"
  # Sol N-6 (Turn 8): exit 124 or 137 before the deadline is not the deadline.
  # A command killed early (SIGKILL, the out-of-memory killer) ends the
  # observations with time still left; nothing then supports "the whole
  # window" or "lost", so report the true elapsed time and fail closed. The
  # same holds for pending bans when the loop stopped early for any reason.
  if ((left > 0)) && [[ -n "${cut}" || ( "${matched}" == 1 && -n "${pending// /}" ) ]]; then
    why="the loop stopped early"
    [[ -z "${cut}" ]] || why="an observation ended with exit 124 or 137 before the deadline (reported as \"${cut}\"), so a command was killed and was not cut off by the deadline"
    if ((matched == 1)) && [[ -n "${pending// /}" ]]; then
      why="${why}. The bans still pending (${pending}) were not observed for the whole window and are not reported as lost"
    fi
    err "fail2ban restart NOT proven: the observations stopped after ${elapsed}s with $(hub_duration "${left}")s of the ${budget_s}s window left; ${why}."
    err "Recovery: check 'journalctl -k' and 'journalctl -u fail2ban' for a killed process, then rerun this installer."
    return 1
  fi
  if ((matched == 1)); then
    bans="${obs#OK }"
    bans="${bans%% | pending *}"
    v6="${obs##*| v6 }"
    v6="${v6%% | expired *}"
    expired="${obs##*| expired }"
    [[ "${obs}" == *"| expired "* ]] || expired=""
    expired="${expired}${expired:+${ended:+ }}${ended}"
    if [[ -n "${pending// /}" ]]; then
      err "FAIL2BAN BANS LOST ACROSS THE RESTART: ${pending}. They were banned before, are not ignored, their bantime has not ended, and they were still not restored after ${elapsed}s (the whole ${budget_s}s window): database persistence off, or a fail2ban other than noble's 1.0.2. fail2ban restart NOT proven."
      err "Recovery: check 'fail2ban-client get dbfile' and the package version, and ban an address again with 'fail2ban-client set sshd banip <ip>' if it still needs it. A rerun takes the jail's current list as its baseline, so it does not report these addresses again."
      return 1
    fi
    if [[ -n "${bans// /}" ]]; then
      log "fail2ban restart proven after ${elapsed}s: actionstart succeeded and f2b-sshd matches the jail's banned list (${bans}); fail2ban ${version:-version unknown}."
    else
      log "fail2ban restart proven after ${elapsed}s: actionstart succeeded and f2b-sshd matches the jail's empty banned list; fail2ban ${version:-version unknown}."
    fi
    if [[ -n "${expired// /}" ]]; then
      log "fail2ban bans whose bantime ended since the pre-restart snapshot, not expected back: ${expired}."
    fi
    if [[ -n "${v6// /}" ]]; then
      warn "fail2ban lists IPv6 bans (${v6}) that the IPv4 hub action cannot enforce; IPv6 SSH is closed by the hub's ip6tables policy."
    fi
    return 0
  fi
  err "fail2ban restart NOT proven within ${budget_s}s (elapsed ${elapsed}s): ${obs:-${cut:-no observation completed}}."
  err "A failed actionstart (for example a failed flush, exit 4) leaves the restored chain, jump and stale bans in place while fail2ban still answers ping and status, and never writes the actionstart stamp."
  err "Recovery: check 'journalctl -u fail2ban' for actionstart errors, compare 'iptables-save -t filter' with 'fail2ban-client status sshd', fix the cause, then rerun this installer."
  return 1
}

# N-13 (Turn 8): the bans the running jail holds before the restart, each with
# the end of its bantime, as "<ip>@<epoch seconds>" (a plain "<ip>" when the
# ban is permanent). fail2ban does not restore a ticket whose bantime has ended
# (1.0.2 Jail.restoreCurrentBans skips a remaining bantime <= 0), so the
# restart proof must not count such a ban as lost (hub_f2b_restart_observe).
# fail2ban 1.0.2 "get <jail> banip --with-time" prints one line per ban,
#   <ip> \t<YYYY-mm-dd HH:MM:SS> + <bantime> = <YYYY-mm-dd HH:MM:SS>
# (BanManager.getBanList, joined by newlines in the client's beautifier), with
# the daemon's local time (MyTime.time2str); TZ is dropped here so python
# reads /etc/localtime as the daemon does ($1, a zone name, replaces that only
# for the test suite's fixtures; the installer passes none). If that command
# fails or a line does not parse, the "status sshd" list is used with no end
# times (every ban counted, as in Turn 7) and a warning says so, on stderr:
# the caller captures stdout (N-15, Turn 9). No jail: no bans.
# N-16 (Sol, Turn 8): the printed time has no offset, so in the hour a DST
# change repeats one stamp names two instants. The LATER one is taken, so an
# end is never read early and a missing ban never looks expired before its
# bantime really ends (an end in the first fold reads an hour late, which can
# only report a loss). A stamp that no instant prints (the hour skipped in
# spring) does not parse.
# N-17 (Seat C, Turn 9): a zone that moves its STANDARD offset back
# (Europe/Volgograd 2020-12-27, Europe/Moscow 2014-10-26) repeats an hour with
# the same DST flag on both sides, and glibc mktime then returns whichever
# fold its cached offset favours. So the candidates are every instant within
# 3 hours of the three mktime guesses, on a 15-minute grid (every UTC offset
# in use is a multiple of 15 minutes, and every repeated hour is shorter than
# 3 hours), that localtime prints back as the stamp; the latest one wins.
hub_f2b_bans_before() {
  local out
  if out="$(fail2ban-client get sshd banip --with-time 2>/dev/null)" && out="$(python3 -c '
import os, re, sys, time
if sys.argv[1]:
    os.environ["TZ"] = sys.argv[1]
else:
    os.environ.pop("TZ", None)
time.tzset()
STAMP = r"(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d)"
LINE = re.compile(r"(\S+) \t" + STAMP + r" \+ (-?\d+) = " + STAMP)
out = []
for line in sys.stdin.read().splitlines():
    if not line.strip():
        continue
    m = LINE.fullmatch(line)
    if not m:
        sys.exit(1)
    if m.group(3) == "-1":
        out.append(m.group(1))
        continue
    tm = time.strptime(m.group(4), "%Y-%m-%d %H:%M:%S")
    # N-17: every instant near the mktime guesses that prints this stamp.
    ends = set()
    for dst in (-1, 0, 1):
        try:
            guess = int(time.mktime(tm[:8] + (dst,)))
        except (OverflowError, ValueError):
            continue
        for t in range(guess - 10800, guess + 10801, 900):
            if time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(t)) == m.group(4):
                ends.add(t)
    if not ends:
        sys.exit(1)
    out.append(m.group(1) + "@" + str(max(ends)))
print(" ".join(out))
' "${1:-}" <<<"${out}")"; then
    printf '%s\n' "${out}"
    return 0
  fi
  if out="$(fail2ban-client status sshd 2>/dev/null)"; then
    warn "Could not read the sshd jail's bans with their end times ('fail2ban-client get sshd banip --with-time'); the restart proof counts every current ban, so one whose bantime ends during the restart may be reported as lost." >&2
    sed -n 's/.*Banned IP list:[[:space:]]*//p' <<<"${out}" | head -n 1
  fi
  return 0
}

write_iptables() {
  log "Applying rollback-safe atomic hub firewall rules"
  local enforce_drop="${HUB_FIREWALL_ENFORCE_DROP:-1}"
  # Where the ruleset is persisted. Always /etc/iptables on a hub; the
  # override exists so the test suite can run this function without touching
  # the host (Sol N-2, Turn 5).
  local rules_dir="${HUB_IPTABLES_RULES_DIR:-/etc/iptables}"
  local blocked_cidr
  local cloudflare_cidr
  local -a cloudflare_cidrs=()
  local -a nfqueue_target=(-j NFQUEUE --queue-num 0)
  local trusted_cidr
  local transaction snapshot filter_body nat_body restore_bin save_bin live_iptables

  case "${SURICATA_NFQUEUE_FAIL_OPEN:-$SURICATA_NFQUEUE_FAIL_OPEN_DEFAULT}" in
    0) ;;
    1)
      warn "SURICATA_NFQUEUE_FAIL_OPEN=1: queued application traffic will bypass IPS if Suricata is unavailable."
      nfqueue_target+=(--queue-bypass)
      ;;
    *)
      err "SURICATA_NFQUEUE_FAIL_OPEN must be 0 (fail closed) or 1 (fail open)."
      return 1
      ;;
  esac

  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" != "1" \
      && "${CONTROL_DIRECT_CLOUDFLARE_ONLY:-$CONTROL_DIRECT_CLOUDFLARE_ONLY_DEFAULT}" == "1" ]]; then
    mapfile -t cloudflare_cidrs < <(cloudflare_origin_ipv4_ranges)
    ((${#cloudflare_cidrs[@]} >= 10)) || {
      err "Cloudflare-only recovery ingress has no validated IPv4 allowlist; firewall was not changed."
      return 1
    }
  fi

  transaction="$(mktemp)"
  snapshot="$(mktemp)"
  filter_body="$(mktemp)"
  nat_body="$(mktemp)"
  chmod 600 "${transaction}" "${snapshot}" "${filter_body}" "${nat_body}"
  restore_bin="${IPTABLES_RESTORE_BIN:-iptables-restore}"
  save_bin="${IPTABLES_SAVE_BIN:-iptables-save}"
  live_iptables="$(command -v iptables)"
  cleanup_hub_firewall_transaction() {
    unset -f iptables 2>/dev/null || true
    rm -f -- "${transaction}" "${snapshot}" "${filter_body}" "${nat_body}"
  }
  # Deliberately not using `trap ... RETURN` here. A RETURN trap set inside
  # this function does correctly fire when THIS function returns, but it is
  # not automatically cleared afterward: it stays globally armed, and its
  # closure over transaction/snapshot/filter_body/nat_body goes stale the
  # moment write_iptables actually returns. main() calls write_iptables three
  # times and then keeps going for dozens more steps before falling off its
  # own end with no explicit `exit`; that final, ordinary return from main()
  # is itself a function return, so the stale trap fires there too, against
  # locals that no longer exist -- an unbound-variable crash under `set -u`,
  # right after every real deployment step already succeeded (confirmed by
  # reproducing this exact main()-wraps-write_iptables shape on bash 5.2).
  # Explicit calls on every exit path below avoid that entirely.
  hub_restore_rule() {
    local file="$1" argument separator=""
    shift
    for argument in "$@"; do
      [[ "${argument}" != *[[:space:]]* ]] || {
        err "Refusing unsafe whitespace in generated hub firewall argument."
        return 1
      }
      printf '%s%s' "${separator}" "${argument}" >> "${file}"
      separator=' '
    done
    printf '\n' >> "${file}"
  }
  # Collect every owned-chain mutation in restore syntax. Read-only checks still
  # query the active ruleset. Nothing below becomes packet-visible until one
  # iptables-restore COMMIT swaps the complete filter table update.
  iptables() {
    local table=filter operation
    local -a arguments=("$@")
    if [[ "${arguments[0]:-}" == "-t" ]]; then
      table="${arguments[1]}"
      arguments=("${arguments[@]:2}")
    fi
    operation="${arguments[0]:-}"
    case "${operation}" in
      -N) return 0 ;;
      -F|-A|-I)
        if [[ "${table}" == "filter" ]]; then
          hub_restore_rule "${filter_body}" "${arguments[@]}"
        elif [[ "${table}" == "nat" ]]; then
          hub_restore_rule "${nat_body}" "${arguments[@]}"
        else
          err "Unsupported hub firewall transaction table: ${table}"
          return 1
        fi
        ;;
      -P)
        [[ "${table}" == "filter" && "${arguments[1]:-}" == "FORWARD" && "${arguments[2]:-}" == "DROP" ]] || {
          err "Unsupported hub firewall policy mutation."
          return 1
        }
        ;;
      *) command "${live_iptables}" "$@" ;;
    esac
  }

  iptables -N WINVPN-HUB-INPUT
  iptables -F WINVPN-HUB-INPUT
  iptables -N WINVPN-HUB-FORWARD
  iptables -F WINVPN-HUB-FORWARD
  iptables -N WINVPN-HUB-OUTPUT
  iptables -F WINVPN-HUB-OUTPUT
  command "${live_iptables}" -C INPUT -j WINVPN-HUB-INPUT 2>/dev/null || iptables -I INPUT 1 -j WINVPN-HUB-INPUT
  command "${live_iptables}" -C FORWARD -j WINVPN-HUB-FORWARD 2>/dev/null || iptables -I FORWARD 1 -j WINVPN-HUB-FORWARD
  command "${live_iptables}" -C OUTPUT -j WINVPN-HUB-OUTPUT 2>/dev/null || iptables -I OUTPUT 1 -j WINVPN-HUB-OUTPUT
  iptables -P FORWARD DROP
  # IA-CP-02: the fail2ban jump is the FIRST rule of the chain, ahead of the
  # loopback/ESTABLISHED accepts and every tcp/22 ACCEPT (admin CIDRs, deploy
  # source, recovery window). Emitted after those accepts, a ban never dropped
  # a packet from any source that could reach sshd at all, including the
  # password-enabled recovery CIDR. Admin CIDRs and the deploy source stay
  # unbannable through fail2ban's ignoreip (hub_fail2ban_ignoreips), which
  # keeps their access exactly as before. The action file inserts at the same
  # position 1, so a fail2ban restart puts the jump back in the same place.
  # Sol N-1 (Turn 4): whether f2b-sshd exists comes from the definite
  # filter-table read, not a lock-free `iptables -n -L` probe whose transient
  # failure used to drop the jump silently. UNKNOWN refuses the transaction.
  local f2b_chain_state
  f2b_chain_state="$(hub_filter_chain_state f2b-sshd)" || {
    err "Refusing to apply the hub firewall: cannot tell whether the f2b-sshd chain exists; active rules were not changed."
    cleanup_hub_firewall_transaction
    return 1
  }
  if [[ "${f2b_chain_state}" == "present" ]]; then
    iptables -A WINVPN-HUB-INPUT -p tcp -m multiport --dports 22 -j f2b-sshd
  fi

  if [[ "${INSTALL_CONTROL_IDS_IPS:-1}" == "1" ]] \
      && command -v suricata >/dev/null 2>&1 \
      && systemctl is-active --quiet suricata.service \
      && systemctl show suricata.service -p ExecStart --value \
        | grep -E -- '(^|[[:space:]])-q[[:space:]]+0([[:space:]]|$)' >/dev/null \
      && suricata --build-info 2>/dev/null | grep -Ei 'NFQ' >/dev/null; then
    if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" == "1" ]]; then
      # Cloudflare Tunnel terminates at local Nginx. Queue that decrypted HTTP
      # stream before accepting loopback so Suricata remains inline IPS.
      iptables -A WINVPN-HUB-INPUT -i lo -p tcp --dport 80 \
        "${nfqueue_target[@]}"
      iptables -A WINVPN-HUB-OUTPUT -o lo -p tcp --sport 80 \
        "${nfqueue_target[@]}"
    elif [[ "${CONTROL_DIRECT_CLOUDFLARE_ONLY:-$CONTROL_DIRECT_CLOUDFLARE_ONLY_DEFAULT}" == "1" ]]; then
      # During direct-origin recovery, queue only traffic which came from a
      # current Cloudflare edge. Arbitrary Internet scans are dropped without
      # consuming Suricata queue capacity. Also queue Nginx's decrypted API
      # traffic on loopback so HTTPS requests are visible to HTTP IPS rules.
      iptables -A WINVPN-HUB-INPUT -i lo -p tcp --dport 8000 \
        "${nfqueue_target[@]}"
      iptables -A WINVPN-HUB-OUTPUT -o lo -p tcp --sport 8000 \
        "${nfqueue_target[@]}"
      for cloudflare_cidr in "${cloudflare_cidrs[@]}"; do
        iptables -A WINVPN-HUB-INPUT -s "${cloudflare_cidr}" -p tcp \
          -m multiport --dports 80,443 "${nfqueue_target[@]}"
        iptables -A WINVPN-HUB-OUTPUT -d "${cloudflare_cidr}" -p tcp \
          -m multiport --sports 80,443 "${nfqueue_target[@]}"
      done
    else
      iptables -A WINVPN-HUB-INPUT -p tcp -m multiport --dports 80,443 \
        "${nfqueue_target[@]}"
      iptables -A WINVPN-HUB-OUTPUT -p tcp -m multiport --sports 80,443 \
        "${nfqueue_target[@]}"
    fi
  fi
  iptables -A WINVPN-HUB-INPUT -i lo -j ACCEPT
  iptables -A WINVPN-HUB-INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
  for trusted_cidr in ${HUB_ADMIN_SSH_CIDRS:-$HUB_ADMIN_SSH_CIDRS_DEFAULT}; do
    iptables -A WINVPN-HUB-INPUT -s "${trusted_cidr}" -p tcp --dport 22 -j ACCEPT
  done
  # AUDIT 2026-08-11, Finding 1. HUB_ADMIN_SSH_CIDRS_DEFAULT is "" (line 385), so on a
  # fresh host the loop above iterates an empty list and emits NO tcp/22 accept at all.
  # HUB_SSH_RECOVERY_CIDR_DEFAULT is likewise "" (line 392) and HUB_ALLOW_GLOBAL_SSH
  # defaults to 0, so nothing else opens 22 either, and this chain ends `-j DROP`. Only
  # the ESTABLISHED,RELATED rule above kept the deploying session alive, which made the
  # lockout invisible during deployment and total once that session closed. Keep the
  # deploying operator's own source, exactly as the core script does at lines 1407-1409.
  # Review 2026-08-11 found the original version of this block FAILED OPEN: when
  # SSH_CONNECTION is empty or IPv6 (sudo's env_reset strips it on the documented
  # `sudo bash` invocation) it silently emitted nothing, so the chain still ended in DROP
  # with no tcp/22 accept while appearing fixed. Fail CLOSED instead, and say which case
  # applies. The temporary recovery CIDR below is deliberately NOT counted as reachability:
  # it expires on a timer and is disabled by default.
  hub_deploy_source="${SSH_CONNECTION:-}"
  hub_deploy_source="${hub_deploy_source%% *}"
  if [[ "${hub_deploy_source}" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
    iptables -A WINVPN-HUB-INPUT -s "${hub_deploy_source}/32" -p tcp --dport 22 \
      -m comment --comment winsvpn-deploy-source -j ACCEPT
  elif [[ -z "${HUB_ADMIN_SSH_CIDRS:-$HUB_ADMIN_SSH_CIDRS_DEFAULT}" \
      && "${HUB_ALLOW_GLOBAL_SSH:-0}" != "1" \
      && "${HUB_ALLOW_UNPINNED_SSH:-0}" != "1" ]]; then
    err "Refusing to apply the hub firewall: SSH_CONNECTION is empty or non-IPv4 (sudo strips it; run from a direct root SSH session over IPv4) and HUB_ADMIN_SSH_CIDRS is empty, so this chain would end in DROP with no tcp/22 accept at all. Set HUB_ADMIN_SSH_CIDRS, or set HUB_ALLOW_UNPINNED_SSH=1 only with working provider console access."
    cleanup_hub_firewall_transaction
    return 1
  else
    warn "Deploy-source SSH pin unavailable (SSH_CONNECTION empty or non-IPv4); tcp/22 reachability now depends entirely on HUB_ADMIN_SSH_CIDRS matching your current egress address."
  fi
  local recovery_password_auth="${HUB_SSH_PASSWORD_AUTH:-$HUB_SSH_PASSWORD_AUTH_DEFAULT}"
  if [[ "${recovery_password_auth}" != "0" && "${recovery_password_auth,,}" != "false" && "${recovery_password_auth,,}" != "no" \
      && -n "${HUB_SSH_RECOVERY_CIDR:-$HUB_SSH_RECOVERY_CIDR_DEFAULT}" ]]; then
    # M-21: while a temporary recovery window is active, allow SSH (any
    # account's auth, including the recovery account's password) from this
    # one required CIDR only. winsvpn-disable-ssh-password-recovery removes
    # this rule directly (see below); it does not re-run write_iptables.
    iptables -A WINVPN-HUB-INPUT -s "${HUB_SSH_RECOVERY_CIDR:-$HUB_SSH_RECOVERY_CIDR_DEFAULT}" -p tcp --dport 22 \
      -m comment --comment winsvpn-ssh-recovery -j ACCEPT
  fi
  for blocked_cidr in ${HUB_BLOCK_TUNNEL_SOURCE_CIDRS:-10.8.0.0/16 10.88.0.0/16}; do
    iptables -A WINVPN-HUB-INPUT -s "${blocked_cidr}" -j DROP
  done
  if [[ "${HUB_ALLOW_GLOBAL_SSH:-0}" == "1" ]]; then
    warn "HUB_ALLOW_GLOBAL_SSH=1 exposes SSH globally; trusted CIDR restriction is disabled."
    iptables -A WINVPN-HUB-INPUT -p tcp --dport 22 -j ACCEPT
  fi
  if [[ "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" != "1" ]]; then
    if [[ "${CONTROL_DIRECT_CLOUDFLARE_ONLY:-$CONTROL_DIRECT_CLOUDFLARE_ONLY_DEFAULT}" == "1" ]]; then
      for cloudflare_cidr in "${cloudflare_cidrs[@]}"; do
        iptables -A WINVPN-HUB-INPUT -s "${cloudflare_cidr}" -p tcp \
          -m multiport --dports 80,443 -j ACCEPT
      done
    else
      warn "CONTROL_DIRECT_CLOUDFLARE_ONLY=0 exposes direct TCP 80/443 ingress globally."
      iptables -A WINVPN-HUB-INPUT -p tcp --dport 80 -j ACCEPT
      iptables -A WINVPN-HUB-INPUT -p tcp --dport 443 -j ACCEPT
    fi
    if [[ "${CONTROL_LEGACY_SPA_UDP:-$CONTROL_LEGACY_SPA_UDP_DEFAULT}" == "1" ]]; then
      warn "CONTROL_LEGACY_SPA_UDP=1 exposes the legacy UDP 62201 recovery knock."
      iptables -A WINVPN-HUB-INPUT -p udp --dport 62201 -j ACCEPT
    fi
  fi
  if [[ "${enforce_drop}" == "1" ]]; then
    iptables -A WINVPN-HUB-INPUT -j DROP
  else
    iptables -A WINVPN-HUB-INPUT -j RETURN
  fi
  iptables -A WINVPN-HUB-FORWARD -j DROP
  iptables -A WINVPN-HUB-OUTPUT -j RETURN

  # F-13 (mirrors data-plane B-5 and the core failure-hold): pin the built-in
  # IPv4 INPUT policy inside the atomic restore transaction. Until now only
  # :FORWARD was staged, so INPUT's policy was whatever the platform or a
  # previous operator left behind; if the position-1 jump to
  # WINVPN-HUB-INPUT (or the chain itself) were ever removed out-of-band, every
  # unrelated listener on the box would fall back to ACCEPT. With
  # enforce_drop=1 (the default, and the only mode used in-tree) the terminal
  # -j DROP made this invisible in normal operation: pinning :INPUT DROP
  # changes no accepted/dropped packet, it only closes the removal path. The
  # enforce_drop=0 escape hatch deliberately leaves the policy unstaged, which
  # is exactly its pre-F-13 behavior. The live ruleset and
  # /etc/iptables/rules.v4 stay consistent by construction: iptables-save runs
  # only after this transaction commits and persists the pinned policy.
  {
    printf '%s\n' '*filter'
    [[ "${enforce_drop}" == "1" ]] && printf '%s\n' ':INPUT DROP [0:0]'
    printf '%s\n' ':FORWARD DROP [0:0]' \
      ':WINVPN-HUB-INPUT - [0:0]' ':WINVPN-HUB-FORWARD - [0:0]' \
      ':WINVPN-HUB-OUTPUT - [0:0]'
    cat "${filter_body}"
    printf '%s\n' 'COMMIT' '*nat'
    cat "${nat_body}"
    printf '%s\n' 'COMMIT'
  } > "${transaction}"
  # SC-1 / OI-CPA-2: immediately before the commit that makes the f2b-sshd
  # jump the first rule, prove no ban on an admin CIDR address or the deploy
  # source is left in f2b-sshd. If that cannot be proven, change nothing: the
  # deploying SSH session must never be cut by its own firewall write.
  if ! hub_f2b_purge_ignored_bans "${live_iptables}"; then
    err "Refusing to apply the hub firewall: cannot prove f2b-sshd holds no rule blocking an exempt source (admin CIDR or deploy source)."
    err "The hub chains and rules.v4 were not changed, but f2b-sshd rules that blocked exempt sources may already have been removed."
    cleanup_hub_firewall_transaction
    return 1
  fi
  "${save_bin}" > "${snapshot}"
  "${restore_bin}" --wait 10 --test --noflush < "${transaction}" || {
    err "Hub firewall transaction validation failed; active rules were not changed."
    cleanup_hub_firewall_transaction
    return 1
  }
  if ! "${restore_bin}" --wait 10 --noflush < "${transaction}"; then
    err "Hub firewall transaction failed; restoring the exact pre-deployment ruleset."
    "${restore_bin}" --wait 10 < "${snapshot}" || {
      err "Hub firewall rollback failed. Keep the existing SSH session open and use the provider console."
      cleanup_hub_firewall_transaction
      return 1
    }
    cleanup_hub_firewall_transaction
    return 1
  fi
  # Sol N-1: the committed ruleset must route tcp/22 through f2b-sshd whenever
  # that chain exists. Checked on a fresh read before anything is persisted.
  if [[ "${f2b_chain_state}" == "present" ]] \
      && ! hub_f2b_require_jump "after the hub firewall commit"; then
    cleanup_hub_firewall_transaction
    return 1
  fi
  cleanup_hub_firewall_transaction

  if command -v ip6tables >/dev/null 2>&1; then
    ip6tables -P INPUT DROP 2>/dev/null || true
    ip6tables -P FORWARD DROP 2>/dev/null || true
    ip6tables -P OUTPUT DROP 2>/dev/null || true
    ip6tables-save > "${rules_dir}/rules.v6" 2>/dev/null || true
  fi

  iptables-save > "${rules_dir}/rules.v4"
  chmod 600 "${rules_dir}/rules.v4" "${rules_dir}/rules.v6" 2>/dev/null || true
  netfilter-persistent save || true
  chmod 600 "${rules_dir}/rules.v4" "${rules_dir}/rules.v6" 2>/dev/null || true
}

write_suricata_noise_pruner() {
  cat > /usr/local/bin/wins-suricata-prune-rules <<'PYEOF'
#!/usr/bin/env python3
import re
import sys
from pathlib import Path

DROP_SIDS = {
    "2042145", "2210008", "2210022", "2210023", "2210027", "2210029", "2210045",
    "2260000", "2260001", "2260002", "2260003", "2221010", "2221014", "2221028",
    "2221045", "2200074", "2049201", "2049202", "9000002", "2001219", "2038967",
    "2011465", "2034125", "2019526", "2101071", "2012230", "2520103", "2522103",
    "2009955", "2049400", "2049401", "2015940", "2044504", "2060800",
    "2026849", "2026850", "2034253", "2101129", "2056027", "2002823", "2002825",
}
DROP_PATTERNS = [
    r"SURICATA STREAM",
    r"SURICATA Applayer",
    r"SURICATA HTTP missing Host header",
    r"SURICATA HTTP Host header invalid",
    r"SURICATA HTTP unable to match response to request",
    r"SURICATA HTTP Unexpected Request body",
    r"SURICATA TCPv4 invalid checksum",
    r"ET DYN_DNS",
    r"DYNAMIC_DNS HTTP Request",
    r"from-ks",
    r"ET INFO SSH-2\.0",
    r"ET INFO External IP Lookup",
    r"ET FILE_SHARING File Hosting Service Domain",
    r"pythonhosted",
    r"ET SCAN Potential SSH Scan",
    r"ET SCAN MS Terminal Server Traffic on Non-standard Port",
    r"ET SCAN Zmap User-Agent",
    r"ET DROP Dshield Block Listed Source",
    r"ET DROP Spamhaus DROP Listed Traffic Inbound",
    r"ET CINS Active Threat Intelligence Poor Reputation IP",
    r"ET COMPROMISED Known Compromised or Hostile Host Traffic",
    r"ET USER_AGENTS Suspcious LeakIX User-Agent",
    r"ET INFO Go-http-client User-Agent",
    r"ET INFO User-Agent .*python-requests",
    r"ET WEB_SERVER /bin/sh In URI",
    r"ET WEB_SERVER WEB-PHP phpinfo access",
    r"GPL WEB_SERVER \.htpasswd access",
    r"ET WEB_SERVER Likely Malicious Request for /proc/self/environ",
    r"ET WEB_SERVER Tilde in URI",
    r"ET WEB_SERVER /etc/passwd Detected in URI",
    r"ET WEB_SERVER /etc/hosts Detected in URI",
    r"ET SCAN SFTP/FTP Password Exposure via sftp-config\.json",
    r"ET INFO Request for Visual Studio Code sftp\.json",
    r"ET EXPLOIT Apache HTTP Server 2\.4\.49",
    r"ET WEB_SPECIFIC_APPS PHP-CGI OS Command Injection",
    r"ET TOR Known Tor Exit Node Traffic",
    r"ET TOR Known Tor Relay/Router",
]
SID_RE = re.compile(r"\bsid\s*:\s*(\d+)\s*;")
PATTERN_RE = [re.compile(pattern, re.IGNORECASE) for pattern in DROP_PATTERNS]

def should_drop_rule(line: str) -> bool:
    stripped = line.lstrip()
    if not stripped or stripped.startswith("#"):
        return False
    match = SID_RE.search(line)
    if match and match.group(1) in DROP_SIDS:
        return True
    return any(pattern.search(line) for pattern in PATTERN_RE)

def main() -> int:
    rule_path = Path(sys.argv[1] if len(sys.argv) > 1 else "/var/lib/suricata/rules/suricata.rules")
    if not rule_path.exists():
        print(f"{rule_path} does not exist; nothing to prune")
        return 0
    original = rule_path.read_text(encoding="utf-8", errors="ignore").splitlines(keepends=True)
    kept = []
    removed = 0
    for line in original:
        if should_drop_rule(line):
            removed += 1
            continue
        kept.append(line)
    if removed:
        backup = rule_path.with_suffix(rule_path.suffix + ".wins-noise.bak")
        backup.write_text("".join(original), encoding="utf-8")
        rule_path.write_text("".join(kept), encoding="utf-8")
    print(f"wins-suricata-prune-rules removed {removed} noisy rule(s) from {rule_path}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
PYEOF
  sed -i 's/\r$//' /usr/local/bin/wins-suricata-prune-rules
  chmod 700 /usr/local/bin/wins-suricata-prune-rules
}

# CP-6: install_control_ids_ips rewrites suricata.yaml and wins-local.rules
# and then updates the imported rules. These two take a last-good copy of all
# three first and put that set back if the new set fails review or
# `suricata -T`, so a rejected configuration is never left for the next
# Suricata restart or reboot to load. A file that did not exist is removed.
suricata_deploy_snapshot() { # <snapshot dir> <file>...
  local snap="$1" f
  shift
  for f in "$@"; do
    if [[ -e "${f}" ]]; then
      cp -p -- "${f}" "${snap}/${f//\//_}"
    else
      : > "${snap}/${f//\//_}.absent"
    fi
  done
}

suricata_deploy_restore() { # <snapshot dir> <file>...
  local snap="$1" f
  shift
  for f in "$@"; do
    if [[ -e "${snap}/${f//\//_}" ]]; then
      cp -p -- "${snap}/${f//\//_}" "${f}.wins-restore"
      mv -f -- "${f}.wins-restore" "${f}"
    elif [[ -e "${snap}/${f//\//_}.absent" ]]; then
      rm -f -- "${f}"
    fi
  done
  rm -rf -- "${snap}"
}

install_control_ids_ips() {
  [[ "${INSTALL_CONTROL_IDS_IPS:-1}" == "1" ]] || {
    warn "Control-plane IDS/IPS install skipped because INSTALL_CONTROL_IDS_IPS=0"
    return 0
  }

  log "Configuring control-plane IDS/IPS with Suricata and Fail2Ban"
  rm -f /usr/local/bin/wins-suricata-prune-rules
  local wan_if hub_cidr cfg rules_dir local_rules ids_snapshot
  local -a ids_files
  wan_if="$(ip -o route show default 2>/dev/null | awk '{print $5; exit}')"
  wan_if="${wan_if:-eth0}"
  hub_cidr="$(ip -4 -o addr show dev "${wan_if}" 2>/dev/null | awk '{print $4; exit}')"
  hub_cidr="${hub_cidr:-${IONOS_HUB_IP}/32}"
  cfg="/etc/suricata/suricata.yaml"
  rules_dir="/var/lib/suricata/rules"
  local_rules="${rules_dir}/wins-local.rules"

  [[ -s "${cfg}" ]] || { err "Suricata config not found at ${cfg}"; exit 1; }
  mkdir -p "${rules_dir}" /etc/fail2ban/action.d /etc/fail2ban/jail.d
  [[ -f "${cfg}.wins-pre-ids" ]] || cp "${cfg}" "${cfg}.wins-pre-ids"
  ids_files=("${cfg}" "${local_rules}" "${rules_dir}/suricata.rules")
  ids_snapshot="$(mktemp -d /run/wins-suricata-deploy.XXXXXX)"
  suricata_deploy_snapshot "${ids_snapshot}" "${ids_files[@]}"

  # A1-ARGON-F1 (the data-plane and Core twins): a rewrite that fails (part
  # way, too) puts the last-good set back, like every refusal after it.
  if ! python3 - "${cfg}" "${wan_if}" "${hub_cidr}" "${HIDE_CONTROL_ORIGIN:-$HIDE_CONTROL_ORIGIN_DEFAULT}" "${CONTROL_DIRECT_CLOUDFLARE_ONLY:-$CONTROL_DIRECT_CLOUDFLARE_ONLY_DEFAULT}" <<'PYEOF'
import os
import sys
from pathlib import Path

import yaml

cfg_path = Path(sys.argv[1])
wan_if = sys.argv[2]
hub_cidr = sys.argv[3]
origin_hidden = sys.argv[4] == "1"
cloudflare_proxy = origin_hidden or sys.argv[5] == "1"

data = yaml.safe_load(cfg_path.read_text(encoding="utf-8")) or {}
vars_section = data.setdefault("vars", {})
address_groups = vars_section.setdefault("address-groups", {})
home_nets = [hub_cidr]
if cloudflare_proxy:
    home_nets.append("127.0.0.1/32")
address_groups["HOME_NET"] = "[" + ",".join(home_nets) + "]"
address_groups["EXTERNAL_NET"] = "any"

data["default-rule-path"] = "/var/lib/suricata/rules"
data["rule-files"] = ["suricata.rules", "wins-local.rules"]
data["runmode"] = "autofp"
data["max-pending-packets"] = 2048
data["detect-engine"] = [{"profile": "low"}, {"sgh-mpm-context": "auto"}]
cpu_count = max(1, os.cpu_count() or 1)
threading = data.setdefault("threading", {})
threading["detect-thread-ratio"] = round(min(1.0, 4.0 / cpu_count), 3)
data["flow"] = {
    "memcap": "64mb",
    "hash-size": 65536,
    "prealloc": 10000,
    "emergency-recovery": 30,
}
stream = data.setdefault("stream", {})
stream["memcap"] = "64mb"
stream["checksum-validation"] = True
stream["inline"] = "auto"
stream["reassembly"] = {"memcap": "128mb", "depth": "1mb", "toserver-chunk-size": 2560, "toclient-chunk-size": 2560, "randomize-chunk-size": True}
data["nfq"] = [{"mode": "accept", "repeat-mark": 1, "repeat-mask": 1, "route-queue": 2, "batchcount": 20}]
data["unix-command"] = {
    "enabled": True,
    "filename": "/var/run/suricata/suricata-command.socket",
}
data["outputs"] = [
    {"fast": {"enabled": True, "filename": "fast.log", "append": True}},
    {"eve-log": {
        "enabled": True,
        "filetype": "regular",
        "filename": "eve.json",
        "community-id": True,
        "xff": {
            "enabled": cloudflare_proxy,
            "mode": "extra-data",
            "deployment": "reverse",
            "header": "CF-Connecting-IP",
        },
        "types": [
            {"alert": {"tagged-packets": False}},
            {"stats": {"totals": True, "threads": False, "deltas": True}},
        ],
    }},
]

cfg_path.write_text("%YAML 1.1\n---\n" + yaml.safe_dump(data, sort_keys=False), encoding="utf-8")
PYEOF
  then
    suricata_deploy_restore "${ids_snapshot}" "${ids_files[@]}"
    err "Could not rewrite ${cfg}; the last-good Suricata configuration and rules are back in place."
    return 1
  fi

  cat > "${local_rules}" <<'EOF'
# Wins VPN IPS policy: only deterministic exploit/secret-disclosure requests
# are dropped. ET Open remains alert-only to avoid community-rule false blocks.
drop http $EXTERNAL_NET any -> $HOME_NET [80,443,8000] (msg:"WINS IPS secret environment file request"; flow:established,to_server; http.uri; content:"/.env"; nocase; sid:9900001; rev:2;)
drop http $EXTERNAL_NET any -> $HOME_NET [80,443,8000] (msg:"WINS IPS process environment disclosure request"; flow:established,to_server; http.uri; content:"/proc/self/environ"; nocase; sid:9900002; rev:2;)
drop http $EXTERNAL_NET any -> $HOME_NET [80,443,8000] (msg:"WINS IPS system password file request"; flow:established,to_server; http.uri; content:"/etc/passwd"; nocase; sid:9900003; rev:2;)
drop http $EXTERNAL_NET any -> $HOME_NET [80,443,8000] (msg:"WINS IPS Git configuration disclosure request"; flow:established,to_server; http.uri; content:"/.git/config"; nocase; sid:9900004; rev:2;)
drop http $EXTERNAL_NET any -> $HOME_NET [80,443,8000] (msg:"WINS IPS encoded path traversal request"; flow:established,to_server; http.uri.raw; content:"%2e%2e"; nocase; sid:9900005; rev:2;)
EOF
  cat > /etc/suricata/disable.conf <<'EOF'
# Intentionally empty. Keep hostile probes and exploit attempts visible for
# forensics; control email volume in the alert monitor instead of deleting IDS
# evidence. Add a SID here only after reproducing and documenting a false alert.
EOF
  cat > /etc/suricata/modify.conf <<'EOF'
# ET/community rules are evidence-only. Convert every imported blocking or
# bypass action to alert; the five reviewed WINS rules live in a separate local
# file and therefore remain the only IPS drop rules.
re:. "^(drop|reject|rejectsrc|rejectdst|rejectboth|pass)[ \t]+" "alert "
EOF
  # M-7: bound Suricata log growth/retention. The reviewed OISF package ships no
  # logrotate policy, so eve.json/fast.log would otherwise append without limit
  # until the filesystem fills. postrotate reopens log files in place.
  cat > /etc/logrotate.d/wins-suricata <<'EOF'
/var/log/suricata/eve.json /var/log/suricata/fast.log {
    daily
    maxsize 100M
    rotate 14
    missingok
    notifempty
    compress
    delaycompress
    sharedscripts
    postrotate
        /usr/bin/suricatasc -c reopen-log-files >/dev/null 2>&1 ||
          /bin/systemctl kill --kill-who=main --signal=USR2 suricata.service
    endscript
}
EOF
  chown root:root /etc/logrotate.d/wins-suricata
  chmod 0644 /etc/logrotate.d/wins-suricata
  logrotate --debug /etc/logrotate.d/wins-suricata >/dev/null 2>&1 \
    || warn "logrotate dry-run for wins-suricata reported issues; review /etc/logrotate.d/wins-suricata."
  cat > /usr/local/bin/wins-suricata-action-policy <<'EOF'
#!/usr/bin/env bash
set -Eeuo pipefail
rules_dir="/var/lib/suricata/rules"
actual="$(grep -hE '^[[:space:]]*(drop|reject|rejectsrc|rejectdst|rejectboth|pass)[[:space:]]' \
  "${rules_dir}/suricata.rules" "${rules_dir}/wins-local.rules" 2>/dev/null \
  | sed -nE 's/^[[:space:]]*(drop|reject|rejectsrc|rejectdst|rejectboth|pass)[[:space:]].*sid:([0-9]+).*/\1:\2/p' \
  | sort -t: -k2,2n || true)"
expected=$'drop:9900001\ndrop:9900002\ndrop:9900003\ndrop:9900004\ndrop:9900005'
blocking_count="$(grep -hE '^[[:space:]]*(drop|reject|rejectsrc|rejectdst|rejectboth|pass)[[:space:]]' \
  "${rules_dir}/suricata.rules" "${rules_dir}/wins-local.rules" 2>/dev/null | wc -l)"
if [[ "${blocking_count}" != "5" || "${actual}" != "${expected}" ]]; then
  echo "Suricata action policy violation: only reviewed WINS drop SIDs 9900001-9900005 may block." >&2
  printf 'Observed actions/SIDs:\n%s\n' "${actual:-none}" >&2
  exit 1
fi
EOF
  chmod 700 /usr/local/bin/wins-suricata-action-policy
  touch "${rules_dir}/suricata.rules"
  # CP-6: never write the download straight over the active rules. The shared
  # IA-CP-13 updater stages it, reviews it, swaps it in, runs the action
  # policy and `suricata -T`, and puts the previous ruleset back on failure.
  write_suricata_update_script
  WINS_SURICATA_UPDATE_NO_RELOAD=1 /usr/local/bin/wins-suricata-update \
    || warn "Suricata rule update did not complete; the previous ruleset stays active (bundled/local rules on a first install)."
  if grep -Eq '^[[:space:]]*(drop|reject|rejectsrc|rejectdst|rejectboth|pass)[[:space:]]' "${rules_dir}/suricata.rules"; then
    suricata_deploy_restore "${ids_snapshot}" "${ids_files[@]}"
    err "Imported Suricata rules still contain a blocking or bypass action; refusing inline activation. The last-good Suricata configuration and rules are back in place."
    return 1
  fi
  if ! /usr/local/bin/wins-suricata-action-policy; then
    suricata_deploy_restore "${ids_snapshot}" "${ids_files[@]}"
    err "The new Suricata rules fail the IPS action policy; the last-good Suricata configuration and rules are back in place and Suricata was not restarted."
    return 1
  fi
  suricata --build-info | grep -Ei 'NFQ' >/dev/null || {
    suricata_deploy_restore "${ids_snapshot}" "${ids_files[@]}"
    err "Installed Suricata build lacks NFQUEUE inline IPS support."
    return 1
  }
  if ! suricata -T -c "${cfg}" -v; then
    suricata_deploy_restore "${ids_snapshot}" "${ids_files[@]}"
    err "The new Suricata configuration and rules fail suricata -T; the last-good configuration and rules are back in place and Suricata was not restarted."
    return 1
  fi
  rm -rf -- "${ids_snapshot}"
  local mem_total_mb suricata_max_mb suricata_high_mb
  mem_total_mb="$(( $(awk '/MemTotal:/ {print $2; exit}' /proc/meminfo) / 1024 ))"
  suricata_max_mb=$((mem_total_mb * 50 / 100))
  ((suricata_max_mb < 768)) && suricata_max_mb=768
  ((suricata_max_mb > 1536)) && suricata_max_mb=1536
  suricata_high_mb=$((suricata_max_mb * 80 / 100))
  install -d -m 755 /etc/systemd/system/suricata.service.d
  cat > /etc/systemd/system/suricata.service.d/30-wins-inline-ips.conf <<EOF
[Service]
ExecStartPre=/bin/rm -f /var/run/suricata/suricata-command.socket
ExecStart=
ExecStart=/usr/bin/suricata -D --pidfile /run/suricata.pid -q 0 -c /etc/suricata/suricata.yaml
MemoryHigh=${suricata_high_mb}M
MemoryMax=${suricata_max_mb}M
TasksMax=512
OOMScoreAdjust=-250
EOF
  # GCP redeploy follow-up: the packaged suricata.service has no
  # RuntimeDirectory, so the unix-command socket dir under /var/run/suricata
  # (tmpfs) vanishes after reboot and Suricata fails to start. Mirror the
  # fleet-wide runtime mitigation permanently: a runtime drop-in plus a
  # tmpfiles.d entry create /run/suricata 0755 before every start.
  cat > /etc/systemd/system/suricata.service.d/31-wins-runtime-dir.conf <<'EOF'
[Service]
RuntimeDirectory=suricata
RuntimeDirectoryMode=0755
EOF
  cat > /etc/tmpfiles.d/winsvpn-suricata.conf <<'EOF'
d /run/suricata 0755 root root -
EOF
  systemctl daemon-reload
  systemctl enable --now suricata
  systemctl restart suricata
  wait_for_suricata

  write_hub_fail2ban_config
}

# IA-CP-02 / SC-1: the hub fail2ban action file, jail (with the current
# ignoreip) and a restart, as one step. install_control_ids_ips runs it as
# before, and main() now also runs it BEFORE the first write_iptables on a hub
# whose chain already exists. That first write_iptables moves the f2b-sshd jump
# to the head of the chain; if fail2ban were still running with the previous
# ignoreip, a ban it already held on an admin CIDR address or the deploy source
# would go live and cut the deploying SSH session before the later restart
# could clear it. A restart with the new ignoreip drops those bans (fail2ban
# does not restore a ban on an ignored address). hub_f2b_purge_ignored_bans in
# write_iptables is the second, fail2ban-independent guarantee.
# $1 is "early" for that pre-firewall call: the restart proof then skips the
# tcp/22 traversal check (see hub_f2b_restart_observe), because the firewall
# write that fixes the order has not run yet. Every other call proves it.
write_hub_fail2ban_config() {
  local traversal=1
  [[ "${1:-}" != "early" ]] || traversal=0
  install -d -m 755 /etc/fail2ban/action.d /etc/fail2ban/jail.d
  cat > /etc/fail2ban/action.d/wins-iptables-hub.conf <<'EOF'
[Definition]
actionstart = iptables -N f2b-<name> 2>/dev/null || true
              iptables -w 10 -F f2b-<name> && { iptables -w 10 -C WINVPN-HUB-INPUT -p <protocol> -m multiport --dports <port> -j f2b-<name> 2>/dev/null || iptables -w 10 -I WINVPN-HUB-INPUT 1 -p <protocol> -m multiport --dports <port> -j f2b-<name>; } && mkdir -p /run/winsvpn-fail2ban && : > /run/winsvpn-fail2ban/<name>.actionstart
actionstop = rm -f /run/winsvpn-fail2ban/<name>.actionstart
             iptables -D WINVPN-HUB-INPUT -p <protocol> -m multiport --dports <port> -j f2b-<name> 2>/dev/null || true
             iptables -F f2b-<name> 2>/dev/null || true
             iptables -X f2b-<name> 2>/dev/null || true
actioncheck = iptables -n -L WINVPN-HUB-INPUT >/dev/null 2>&1
actionban = iptables -I f2b-<name> 1 -s <ip> -j DROP
actionunban = iptables -D f2b-<name> -s <ip> -j DROP

[Init]
port = ssh
protocol = tcp
EOF

  local ignore_ips
  ignore_ips="$(hub_fail2ban_ignoreips)"
  cat > /etc/fail2ban/jail.d/wins-hub.local <<EOF
[DEFAULT]
bantime = 1h
findtime = 1h
maxretry = 10
backend = systemd
banaction = wins-iptables-hub
ignoreip = ${ignore_ips}

[sshd]
enabled = true
port = ssh
logpath = %(sshd_log)s
EOF

  # F2B-VERSION: record what the running jail bans now, so bans the restart
  # fails to restore can be reported. Best effort: no jail yet means none.
  # N-13 (Turn 8): with the end of each ban's bantime, so a ban that simply
  # expires during the restart is not reported as lost.
  local bans_before=""
  # The action writes this stamp as its LAST step, only after the flush and
  # the link both succeeded; remove it first so only this start can write it.
  local actionstart_stamp=/run/winsvpn-fail2ban/sshd.actionstart
  rm -f -- "${actionstart_stamp}"
  bans_before="$(hub_f2b_bans_before)"
  systemctl enable --now fail2ban
  systemctl restart fail2ban
  wait_for_fail2ban
  # OI-CPA-10A: actionstart flushes f2b-sshd before linking it (a DROP
  # restored from rules.v4 must not outlive its ticket), and the flush and the
  # insert are chained so either failure fails actionstart. fail2ban can still
  # answer ping/status with a failed action, and a restored chain and jump can
  # survive a failed flush, so prove the result: tcp/22 reaches f2b-sshd
  # first, and f2b-sshd holds exactly the jail's bans. Anything else stops the
  # deploy.
  hub_f2b_prove_restart "${bans_before}" "${actionstart_stamp}" "${traversal}"
}

write_threat_triage_engine() {
  log "Installing adaptive, human-confirmed security alert triage engine"
  install -d -m 755 /usr/local/lib
  install -d -m 700 /var/lib/wins-security-alerts
  cat > /usr/local/lib/wins_threat_triage.py <<'PYEOF'
#!/usr/bin/env python3
import argparse
import ipaddress
import json
import os
import sqlite3
from contextlib import closing
from datetime import UTC, datetime, timedelta
from pathlib import Path

MODEL_VERSION = "wins-triage-v3-local-health-context"
ENV_FILE = Path("/root/vpn_auth.env")


def load_env(path: Path) -> dict:
    env = dict(os.environ)
    try:
        if not path.exists():
            return env
        raw_lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return env
    for raw in raw_lines:
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] == "'":
            value = value[1:-1].replace('\'"\'"\'', "'")
        elif len(value) >= 2 and value[0] == value[-1] == '"':
            value = value[1:-1]
        env[key.strip()] = value
    return env


ENV = load_env(ENV_FILE)
EVENTS_DB = Path(os.environ.get(
    "WINS_SECURITY_EVENTS_DB",
    ENV.get("SECURITY_EVENTS_DB", "/var/lib/wins-security-alerts/security_events.db"),
))
TRIAGE_ENABLED = ENV.get("SECURITY_TRIAGE_ENABLED", "1").strip().lower() not in {"0", "false", "no", "off"}
ABSENT_PRODUCTS = {
    item.strip().lower()
    for item in ENV.get(
        "SECURITY_TRIAGE_ABSENT_PRODUCTS",
        "coldfusion,geoserver,apache solr,tomcat manager,spring actuator,hnap,dvr,camera web interface",
    ).split(",")
    if item.strip()
}
PRESENT_PRODUCTS = {
    item.strip().lower()
    for item in ENV.get(
        "SECURITY_TRIAGE_PRESENT_PRODUCTS",
        "nginx,fastapi,openssh,suricata",
    ).split(",")
    if item.strip()
}
HEALTH_USER_AGENT = ENV.get("WINS_HEALTH_USER_AGENT", "curl/8.5.0").strip()
EXPECTED_LOCAL_HTTP_REQUESTS = {
    ("GET", "/healthz"),
    ("GET", "/nodes"),
    ("POST", "/admin/paypal/sync"),
    ("POST", "/admin/monero/poll"),
}
def _parse_admin_ssh_networks(raw: str) -> tuple:
    networks = []
    for token in str(raw or "").replace(",", " ").split():
        try:
            networks.append(ipaddress.ip_network(token.strip(), strict=False))
        except ValueError:
            continue
    return tuple(networks)


ADMIN_SSH_NETWORKS = _parse_admin_ssh_networks(ENV.get("HUB_ADMIN_SSH_CIDRS", ""))
THREAT_TERMS = (
    "/etc/passwd", "path traversal", "webshell", "command injection", "remote code execution",
    "shellcode", "malware", "trojan", "ransomware", "botnet", "command and control",
    "credential theft", "sql injection", "arbitrary file", "exploit",
)
HIGH_RISK_CATEGORIES = (
    "attempted administrator privilege gain", "successful administrator privilege gain",
    "web application attack", "malware command and control", "network trojan",
    "shellcode detect", "trojan activity", "credential theft",
)
FEEDBACK_LABELS = {"false_positive", "benign_expected", "threat"}


def now_iso() -> str:
    return datetime.now(UTC).isoformat()


def configure_security_events_connection(conn: sqlite3.Connection) -> None:
    conn.execute("PRAGMA busy_timeout=10000")
    journal_mode = conn.execute("PRAGMA journal_mode=WAL").fetchone()[0]
    if str(journal_mode).lower() != "wal":
        raise RuntimeError("security events database refused WAL mode")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA foreign_keys=ON")

def _add_column_if_missing(conn: sqlite3.Connection, table: str, column: str, ddl: str):
    existing = {row[1] for row in conn.execute(f"PRAGMA table_info({table})")}
    if column not in existing:
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {ddl}")


def ensure_schema(conn: sqlite3.Connection):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS security_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE,
            observed_at_utc TEXT NOT NULL,
            observed_at_eastern TEXT NOT NULL,
            priority INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            source_ip TEXT,
            source_ip_bucket TEXT,
            request_path TEXT,
            details_hash TEXT,
            details_json TEXT,
            email_status TEXT,
            email_error TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    for column, ddl in (
        ("triage_label", "TEXT"),
        ("triage_score", "INTEGER"),
        ("triage_confidence", "REAL"),
        ("triage_reasons", "TEXT"),
        ("triage_model_version", "TEXT"),
        ("triage_feedback_state", "TEXT"),
    ):
        _add_column_if_missing(conn, "security_events", column, ddl)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS security_feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE NOT NULL,
            feature_key TEXT NOT NULL,
            label TEXT NOT NULL CHECK(label IN ('false_positive','benign_expected','threat')),
            reason TEXT NOT NULL,
            confirmed_by TEXT NOT NULL,
            confirmed_at TEXT NOT NULL
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_feedback_feature ON security_feedback(feature_key, label)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_triage ON security_events(triage_label, triage_score)")
    os.chmod(EVENTS_DB, 0o600)


def _flatten_strings(value) -> list[str]:
    if isinstance(value, dict):
        result = []
        for item in value.values():
            result.extend(_flatten_strings(item))
        return result
    if isinstance(value, (list, tuple, set)):
        result = []
        for item in value:
            result.extend(_flatten_strings(item))
        return result
    if value is None:
        return []
    return [str(value)]


def feature_key(event_type: str, details: dict) -> str:
    signature_id = str((details or {}).get("signature_id") or "").strip()
    return f"sid:{signature_id}" if signature_id else f"event:{event_type.strip().lower()}"


def feedback_counts(conn: sqlite3.Connection, key: str) -> dict[str, int]:
    counts = {"false_positive": 0, "benign_expected": 0, "threat": 0}
    for label, count in conn.execute(
        "SELECT label, COUNT(*) FROM security_feedback WHERE feature_key=? GROUP BY label",
        (key,),
    ):
        counts[str(label)] = int(count)
    return counts


def source_in_admin_ssh_network(source_ip: str) -> bool:
    try:
        address = ipaddress.ip_address(str(source_ip or "").strip())
    except ValueError:
        return False
    return any(address.version == network.version and address in network for network in ADMIN_SSH_NETWORKS)


def _is_loopback(value: object) -> bool:
    try:
        return ipaddress.ip_address(str(value or "").strip()).is_loopback
    except ValueError:
        return False


def expected_local_health_event(details: dict) -> bool:
    """Recognize only the installer's loopback probes, not a Suricata SID globally."""
    details = details or {}
    transport_source = details.get("transport_src_ip") or details.get("src_ip")
    destination = details.get("dest_ip") or details.get("destination_ip")
    user_agent = str(details.get("http_user_agent") or "").strip()
    method = str(details.get("http_method") or "GET").strip().upper()
    raw_path = str(details.get("http_url") or details.get("request_path") or "").strip()
    path = raw_path.split("?", 1)[0]
    return bool(
        HEALTH_USER_AGENT
        and user_agent == HEALTH_USER_AGENT
        and _is_loopback(transport_source)
        and _is_loopback(destination)
        and (method, path) in EXPECTED_LOCAL_HTTP_REQUESTS
    )


def classify_event(event_type: str, priority: int, source_ip: str, details: dict) -> dict:
    details = details or {}
    priority = int(priority or 4)
    score = {1: 75, 2: 55, 3: 35}.get(priority, 25)
    reasons = [f"suricata_or_event_priority_p{priority}"]
    product_parts = [details.get("signature"), details.get("category"), *_flatten_strings(details.get("metadata"))]
    text_parts = [event_type, *product_parts]
    text = " ".join(str(item or "") for item in text_parts).lower()
    product_text = " ".join(str(item or "") for item in product_parts).lower()
    key = feature_key(event_type, details)

    if not TRIAGE_ENABLED:
        return {
            "label": "needs_review", "score": score, "confidence": 0.0,
            "reasons": ["triage_disabled"], "model_version": MODEL_VERSION,
            "feedback_state": "disabled", "feature_key": key,
        }

    if event_type == "suricata alert":
        if expected_local_health_event(details):
            score = min(score, 5)
            reasons.append("expected_pinned_loopback_health_probe")
        else:
            if any(term in text for term in HIGH_RISK_CATEGORIES):
                score += 15
                reasons.append("high_risk_suricata_category")
            if any(term in text for term in THREAT_TERMS):
                score += 20
                reasons.append("exploit_or_malware_indicator")
            action = str(details.get("action") or "").lower()
            verdict = str(details.get("verdict_action") or "").lower()
            if action in {"blocked", "drop", "reject"} or verdict in {"drop", "reject"}:
                score += 5
                reasons.append("ips_block_or_reject")
            absent_hits = sorted(product for product in ABSENT_PRODUCTS if product in product_text)
            present_hits = sorted(product for product in PRESENT_PRODUCTS if product in product_text)
            if absent_hits and not present_hits:
                score = min(score, 28)
                reasons.append("targets_verified_absent_product:" + ",".join(absent_hits[:3]))
            elif present_hits:
                score += 8
                reasons.append("targets_present_product:" + ",".join(present_hits[:3]))
    elif event_type == "successful ssh login":
        if source_in_admin_ssh_network(source_ip):
            score = min(score, 20)
            reasons.append("successful_ssh_from_configured_admin_cidr")
        else:
            score = max(score, 55)
            reasons.append("successful_ssh_outside_or_unknown_admin_cidr")
    elif event_type == "admin privilege escalation":
        score = max(score, 70)
        reasons.append("privileged_host_event")

    feedback = {"false_positive": 0, "benign_expected": 0, "threat": 0}
    try:
        EVENTS_DB.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        with closing(sqlite3.connect(EVENTS_DB, timeout=10)) as conn, conn:
            configure_security_events_connection(conn)
            ensure_schema(conn)
            feedback = feedback_counts(conn, key)
    except Exception:
        reasons.append("feedback_store_unavailable")
    false_count = feedback["false_positive"] + feedback["benign_expected"]
    threat_count = feedback["threat"]
    if false_count and not threat_count:
        score -= min(30, 8 * false_count)
        reasons.append(f"human_false_positive_feedback:{false_count}")
    elif threat_count and not false_count:
        score += min(30, 8 * threat_count)
        reasons.append(f"human_threat_feedback:{threat_count}")
    elif false_count and threat_count:
        reasons.append("conflicting_human_feedback")

    score = max(0, min(100, int(score)))
    if score >= 65:
        label = "likely_threat"
    elif score <= 30:
        label = "likely_false_positive"
    else:
        label = "needs_review"
    total_feedback = false_count + threat_count
    confidence = 0.45 + abs(score - 50) / 100 + min(total_feedback, 5) * 0.05
    if false_count and threat_count:
        confidence -= 0.20
    if label != "needs_review" and total_feedback == 0:
        confidence = min(confidence, 0.75)
    confidence = round(max(0.0, min(0.98, confidence)), 2)
    return {
        "label": label,
        "score": score,
        "confidence": confidence,
        "reasons": list(dict.fromkeys(reasons))[:8],
        "model_version": MODEL_VERSION,
        "feedback_state": f"false_positive={false_count},threat={threat_count}",
        "feature_key": key,
    }


def submit_feedback(event_id: str, label: str, reason: str):
    if os.geteuid() != 0:
        raise PermissionError("feedback requires root")
    label = label.strip().lower()
    if label not in FEEDBACK_LABELS:
        raise ValueError("label must be false_positive, benign_expected, or threat")
    reason = " ".join(reason.strip().split())[:500]
    if len(reason) < 8:
        raise ValueError("feedback reason must contain at least 8 characters")
    with closing(sqlite3.connect(EVENTS_DB, timeout=10)) as conn, conn:
        configure_security_events_connection(conn)
        ensure_schema(conn)
        row = conn.execute(
            "SELECT event_type, details_json FROM security_events WHERE event_id=?",
            (event_id,),
        ).fetchone()
        if not row:
            raise ValueError("event_id was not found")
        try:
            details = json.loads(row[1] or "{}")
        except Exception:
            details = {}
        key = feature_key(str(row[0]), details)
        conn.execute("""
            INSERT INTO security_feedback(event_id, feature_key, label, reason, confirmed_by, confirmed_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(event_id) DO UPDATE SET
                feature_key=excluded.feature_key,
                label=excluded.label,
                reason=excluded.reason,
                confirmed_by=excluded.confirmed_by,
                confirmed_at=excluded.confirmed_at
        """, (event_id, key, label, reason, f"uid:{os.geteuid()}", now_iso()))
        conn.execute(
            "UPDATE security_events SET triage_feedback_state=? WHERE event_id=?",
            (f"human_confirmed:{label}", event_id),
        )


def reclassify_events(limit: int, include_stale: bool = False):
    """Backfill missing classifier results without overwriting human labels."""
    bounded_limit = max(1, min(int(limit or 1), 50000))
    with closing(sqlite3.connect(EVENTS_DB, timeout=10)) as conn, conn:
        configure_security_events_connection(conn)
        conn.row_factory = sqlite3.Row
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT event_id, priority, event_type, source_ip, details_json
            FROM security_events
            WHERE COALESCE(triage_feedback_state, '') NOT LIKE 'human_confirmed:%'
              AND (
                    triage_label IS NULL OR trim(triage_label) = ''
                    OR triage_model_version IS NULL OR trim(triage_model_version) = ''
                    OR (? = 1 AND triage_model_version != ?)
              )
            ORDER BY id ASC LIMIT ?
        """, (1 if include_stale else 0, MODEL_VERSION, bounded_limit)).fetchall()

    updates = []
    invalid_details = 0
    for row in rows:
        try:
            details = json.loads(row["details_json"] or "{}")
            if not isinstance(details, dict):
                details = {}
                invalid_details += 1
        except Exception:
            details = {}
            invalid_details += 1
        # source_ip is no longer persisted (privacy fix: only source_ip_bucket, a keyed
        # hash, is stored going forward). For events recorded after that change this reads
        # back NULL/"unknown", so source_in_admin_ssh_network() fails closed (returns False)
        # instead of correctly recognizing an admin-network source. That's an accepted,
        # bounded tradeoff: it only affects this backfill/reclassification pass, never the
        # real-time classification done at insert time with the live in-memory IP.
        triage = classify_event(
            str(row["event_type"] or "unknown"),
            int(row["priority"] or 4),
            str(row["source_ip"] or "unknown"),
            details,
        )
        updates.append((
            triage.get("label", "needs_review"),
            int(triage.get("score", 50)),
            float(triage.get("confidence", 0.0)),
            json.dumps(triage.get("reasons", []), separators=(",", ":")),
            triage.get("model_version", MODEL_VERSION),
            triage.get("feedback_state", "none"),
            row["event_id"],
        ))

    if updates:
        with closing(sqlite3.connect(EVENTS_DB, timeout=10)) as conn, conn:
            configure_security_events_connection(conn)
            ensure_schema(conn)
            conn.executemany("""
                UPDATE security_events
                SET triage_label=?, triage_score=?, triage_confidence=?,
                    triage_reasons=?, triage_model_version=?, triage_feedback_state=?
                WHERE event_id=?
                  AND COALESCE(triage_feedback_state, '') NOT LIKE 'human_confirmed:%'
            """, updates)
    result = {
        "processed": len(updates),
        "invalid_details": invalid_details,
        "model_version": MODEL_VERSION,
        "include_stale": bool(include_stale),
    }
    print(json.dumps(result, sort_keys=True))
    return result


def list_events(limit: int):
    with closing(sqlite3.connect(EVENTS_DB, timeout=10)) as conn, conn:
        configure_security_events_connection(conn)
        conn.row_factory = sqlite3.Row
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT event_id, observed_at_utc, priority, event_type, source_ip_bucket,
                   triage_label, triage_score, triage_confidence, triage_feedback_state,
                   email_status
            FROM security_events
            ORDER BY id DESC LIMIT ?
        """, (max(1, min(limit, 500)),)).fetchall()
    print(json.dumps([dict(row) for row in rows], indent=2, sort_keys=True))


def report(hours: int):
    cutoff = (datetime.now(UTC) - timedelta(hours=max(1, min(hours, 24 * 90)))).isoformat()
    with closing(sqlite3.connect(EVENTS_DB, timeout=10)) as conn, conn:
        configure_security_events_connection(conn)
        ensure_schema(conn)
        rows = conn.execute("""
            SELECT COALESCE(triage_label, 'unclassified'), COUNT(*)
            FROM security_events WHERE observed_at_utc >= ?
            GROUP BY COALESCE(triage_label, 'unclassified') ORDER BY COUNT(*) DESC
        """, (cutoff,)).fetchall()
        pending = conn.execute("""
            SELECT COUNT(*) FROM security_events
            WHERE observed_at_utc >= ? AND COALESCE(triage_label, 'needs_review')='needs_review'
        """, (cutoff,)).fetchone()[0]
    print(json.dumps({
        "hours": hours,
        "counts": dict(rows),
        "needs_review": int(pending),
        "model_version": MODEL_VERSION,
    }, sort_keys=True))


def main():
    parser = argparse.ArgumentParser(description="Win's VPN adaptive security alert triage")
    sub = parser.add_subparsers(dest="command", required=True)
    list_parser = sub.add_parser("list")
    list_parser.add_argument("--limit", type=int, default=50)
    feedback_parser = sub.add_parser("feedback")
    feedback_parser.add_argument("event_id")
    feedback_parser.add_argument("label", choices=sorted(FEEDBACK_LABELS))
    feedback_parser.add_argument("--reason", required=True)
    report_parser = sub.add_parser("report")
    report_parser.add_argument("--hours", type=int, default=24)
    reclassify_parser = sub.add_parser("reclassify")
    reclassify_parser.add_argument("--limit", type=int, default=5000)
    reclassify_parser.add_argument("--include-stale", action="store_true")
    classify_parser = sub.add_parser("classify")
    classify_parser.add_argument("--event-type", default="suricata alert")
    classify_parser.add_argument("--priority", type=int, default=2)
    classify_parser.add_argument("--source", default="unknown")
    classify_parser.add_argument("--details-json", default="{}")
    args = parser.parse_args()
    if args.command == "list":
        list_events(args.limit)
    elif args.command == "feedback":
        submit_feedback(args.event_id, args.label, args.reason)
        print("feedback recorded; future scores will use the human-confirmed label")
    elif args.command == "report":
        report(args.hours)
    elif args.command == "reclassify":
        reclassify_events(args.limit, include_stale=args.include_stale)
    elif args.command == "classify":
        details = json.loads(args.details_json)
        print(json.dumps(classify_event(args.event_type, args.priority, args.source, details), sort_keys=True))


if __name__ == "__main__":
    main()
