sys.path.insert(0, "/usr/local/lib")
from wins_threat_triage import (
    classify_event,
    ensure_schema as ensure_triage_schema,
    expected_local_health_event,
    source_in_admin_ssh_network,
)

ENV_FILE = Path("/root/vpn_auth.env")
STATE_DIR = Path("/var/lib/wins-security-alerts")
EVE_PATH = Path("/var/log/suricata/eve.json")

def load_env(path: Path) -> dict:
    env = dict(os.environ)
    if not path.exists():
        return env
    for raw in path.read_text(encoding="utf-8", errors="ignore").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] == "'":
            value = value[1:-1].replace('\'"\'"\'', "'")
        elif len(value) >= 2 and value[0] == value[-1] == '"':
            value = value[1:-1]
        env[key.strip()] = value
    return env

ENV = load_env(ENV_FILE)
SMTP_SERVER = ENV.get("SMTP_SERVER", "mail.smtp2go.com")
SMTP_PORT = int(ENV.get("SMTP_PORT", "2525") or "2525")
SMTP_USER = ENV.get("SMTP_USER", "")
SMTP_PASS = ENV.get("SMTP_PASS", "")
EMAIL_SENDER = ENV.get("EMAIL_SENDER", "support@winsvpn.org")
SECURITY_ALERT_EMAIL = ENV.get("SECURITY_ALERT_EMAIL", "security@winsvpn.com")
EXEMPT_IPS = {x.strip() for x in ENV.get("SECURITY_ALERT_EXEMPT_IPS", "127.0.0.1,::1").split(",") if x.strip()}
LOOPBACK_EXEMPT_IPS = {"127.0.0.1", "::1", "localhost"}
LOCAL_IPS = {x.strip() for x in ENV.get("SECURITY_ALERT_LOCAL_IPS", ENV.get("IONOS_HUB_IP", "")).split(",") if x.strip()}
THROTTLE_SECONDS = int(ENV.get("SECURITY_ALERT_THROTTLE_SECONDS", "300") or "300")
# Key logins from HUB_ADMIN_SSH_CIDRS are the operator's own sessions; mail the
# first one per source and user per window, record the rest as throttled.
TRUSTED_LOGIN_THROTTLE_SECONDS = int(ENV.get("SECURITY_ALERT_TRUSTED_LOGIN_THROTTLE_SECONDS", "21600") or "21600")
MAX_EMAILS_PER_RUN = int(ENV.get("SECURITY_ALERT_MAX_EMAILS_PER_RUN", "20") or "20")
# L-14: no hardcoded fallback -- a key that is baked into this generated
# script (and therefore effectively public) would let anyone precompute a
# lookup table and de-anonymize the IPs/account numbers this secret is used
# to hash in security-event records. Reuse one of the other strong secrets
# already present in this deployment, and refuse to start rather than run
# with no real secret at all.
RATE_LIMIT_SECRET = ENV.get("RATE_LIMIT_SECRET") or ENV.get("SPA_HMAC") or ENV.get("ADMIN_TOKEN") or ""
if len(RATE_LIMIT_SECRET) < 32:
    raise SystemExit("A random security-event hashing secret (RATE_LIMIT_SECRET, SPA_HMAC, or ADMIN_TOKEN, at least 32 characters) is required in /root/vpn_auth.env")
SECURITY_EVENTS_DB = Path(ENV.get("SECURITY_EVENTS_DB", "/var/lib/wins-security-alerts/security_events.db"))
SECURITY_EVENTS_RETENTION_DAYS = int(ENV.get("SECURITY_EVENTS_RETENTION_DAYS", "180") or "180")
SECURITY_ALERT_TIMEZONE = ENV.get("SECURITY_ALERT_TIMEZONE", "America/New_York")
EMAIL_PRIORITIES = {
    int(x.strip()) for x in ENV.get("SECURITY_ALERT_EMAIL_PRIORITIES", "1,2").split(",")
    if x.strip().isdigit()
}
SUPPRESS_SIGNATURE_IDS = {
    x.strip() for x in ENV.get("SECURITY_ALERT_SUPPRESS_SIGNATURE_IDS", "2042145").split(",")
    if x.strip()
}
SUPPRESS_SIGNATURE_PATTERNS = [
    x.strip().lower() for x in ENV.get(
        "SECURITY_ALERT_SUPPRESS_SIGNATURE_PATTERNS",
        "ET DYN_DNS,DYNAMIC_DNS HTTP Request,from-ks",
    ).split(",")
    if x.strip()
]
NO_RECORD_SIGNATURE_IDS = {
    x.strip() for x in ENV.get(
        "SECURITY_ALERT_NO_RECORD_SIGNATURE_IDS",
        "",
    ).split(",")
    if x.strip()
}
NO_RECORD_SIGNATURE_PATTERNS = [
    x.strip().lower() for x in ENV.get(
        "SECURITY_ALERT_NO_RECORD_SIGNATURE_PATTERNS",
        "SURICATA STREAM,SURICATA Applayer,SURICATA TCPv4 invalid checksum",
    ).split(",")
    if x.strip()
]
NO_RECORD_INBOUND_PATTERNS = [
    x.strip().lower() for x in ENV.get(
        "SECURITY_ALERT_NO_RECORD_INBOUND_PATTERNS",
        "",
    ).split(",")
    if x.strip()
]
try:
    SECURITY_ALERT_TZ = ZoneInfo(SECURITY_ALERT_TIMEZONE)
except Exception:
    SECURITY_ALERT_TZ = timezone(timedelta(hours=-5), "EST")
EMAILS_SENT = 0

STATE_DIR.mkdir(mode=0o700, parents=True, exist_ok=True)

def event_hash(value) -> str:
    # GENERAL-PURPOSE digest for this monitor's own internal identifiers. The
    # json.dumps() is LOAD-BEARING and must not be removed: throttle_ok() hashes
    # throttle_identity()'s *dict*, and dicts have no str() form that is stable
    # across key insertion order. Do not "unify" this with the bucket helper
    # below -- they hash different kinds of thing for different reasons.
    payload = json.dumps(value, sort_keys=True, default=str)
    return hmac.new(RATE_LIMIT_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()[:24]

def canonical_event_hash(value) -> str:
    # CANONICAL keyed digest for every security_events column that a SECOND
    # producer also writes. Character-for-character main.py's
    # security_event_hash() and the wins-security-events CLI's: str()-encoded,
    # 16 hex chars. If one of the three changes, all three must.
    #
    # Deliberately NOT event_hash() above, and deliberately named for neither
    # column that uses it. event_hash() JSON-encodes first -- so an already-str
    # value "x" is digested as '"x"', quotes and escapes included -- and keeps
    # 24 chars. That is correct for the dicts and internal identifiers it
    # digests, and wrong for any column the hub writes too, because the two
    # encodings can never agree on the same input.
    #
    # Used by source_ip_bucket_value() below and by record_event()'s
    # details_hash. Add a call here, not a fourth derivation.
    return hmac.new(RATE_LIMIT_SECRET.encode(), str(value or "").encode(), hashlib.sha256).hexdigest()[:16]

_SECURITY_DETAIL_HASH_KEYS = {
    "src_ip", "transport_src_ip", "source_ip", "http_url",
    "http_user_agent", "request_path", "path", "url",
}

def minimize_security_details(value):
    """Return a fixed-point copy safe for persistence or outbound email."""
    if isinstance(value, dict):
        minimized = {}
        for raw_key, raw_value in value.items():
            key = str(raw_key)
            if key.endswith(("_hash", "_bucket", "_fingerprint")):
                minimized[key] = raw_value
            elif key in _SECURITY_DETAIL_HASH_KEYS:
                serialized = json.dumps(raw_value, sort_keys=True, default=str, separators=(",", ":"))
                minimized[f"{key}_hash"] = canonical_event_hash(serialized)
            else:
                minimized[key] = minimize_security_details(raw_value)
        return minimized
    if isinstance(value, list):
        return [minimize_security_details(item) for item in value]
    return value

def source_ip_bucket_value(value) -> str:
    # CANONICAL security_events.source_ip_bucket derivation (2026-08-07).
    # Character-for-character main.py's security_event_hash() and the
    # wins-security-events CLI's: str()-encoded, 16 hex chars. If one of the
    # three changes, all three must.
    #
    # WHY THIS EXISTS: this monitor used to bucket source IPs with event_hash()
    # above, which JSON-encodes first (so "1.2.3.4" was hashed as '"1.2.3.4"',
    # quotes included) and keeps 24 chars. The hub and the operator's CLI used
    # the 16-char str() form. The two never collided, so
    # `wins-security-events --source-ip <ip>` silently returned nothing for
    # every row this monitor wrote -- most rows, since it runs every 60s off
    # Suricata's eve.json -- and an empty result was indistinguishable from
    # "that address never appeared". The hub's form won because the CLI was
    # already written to match it, because main.py derives ~50 other bucket and
    # hash columns with it, and because moving the monitor is a three-call-site
    # change against the hub's much larger blast radius.
    #
    # Rows this monitor wrote BEFORE that fix keep their 24-char buckets and
    # cannot be migrated: the bucket is a one-way HMAC and source_ip is
    # deliberately NULL, so there is no input left to re-derive from. The CLI
    # searches both forms and names which one matched; the legacy rows age out
    # on SECURITY_EVENTS_RETENTION_DAYS.
    #
    # The derivation itself was factored out to canonical_event_hash() above
    # (2026-08-07, second pass) when details_hash was found to need the same
    # form. Same bytes, one implementation; this wrapper keeps the
    # column-specific name and the reasoning above.
    return canonical_event_hash(value)

def now_utc() -> datetime:
    return datetime.now(UTC)

def time_text(dt_utc: datetime) -> tuple[str, str]:
    utc_text = dt_utc.astimezone(UTC).strftime("%Y-%m-%d %H:%M:%S UTC")
    local_text = dt_utc.astimezone(SECURITY_ALERT_TZ).strftime("%Y-%m-%d %H:%M:%S %Z")
    return utc_text, local_text

def details_json(details: dict) -> str:
    return json.dumps(minimize_security_details(details or {}), sort_keys=True, default=str, indent=2)

def configure_security_events_connection(conn: sqlite3.Connection) -> None:
    conn.execute("PRAGMA busy_timeout=10000")
    journal_mode = conn.execute("PRAGMA journal_mode=WAL").fetchone()[0]
    if str(journal_mode).lower() != "wal":
        raise RuntimeError("security events database refused WAL mode")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA foreign_keys=ON")

def ensure_events_db(conn: sqlite3.Connection):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS security_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE,
            observed_at_utc TEXT NOT NULL,
            observed_at_eastern TEXT NOT NULL,
            priority INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            source_ip TEXT,
            source_ip_bucket TEXT,
            request_path TEXT,
            details_hash TEXT,
            details_json TEXT,
            email_status TEXT,
            email_error TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_observed_at ON security_events(observed_at_utc)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_priority_type ON security_events(priority, event_type)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_security_events_source ON security_events(source_ip_bucket)")
    ensure_triage_schema(conn)
    cutoff = now_utc() - timedelta(days=SECURITY_EVENTS_RETENTION_DAYS)
    conn.execute("DELETE FROM security_events WHERE observed_at_utc < ?", (cutoff.isoformat(),))
    # M-17: idempotently scrub any legacy plaintext source_ip left by rows
    # written before new monitor writes switched to keyed buckets only. Runs in
    # the same transaction as the schema/retention maintenance above.
    conn.execute("UPDATE security_events SET source_ip = NULL WHERE source_ip IS NOT NULL AND source_ip != ''")
    conn.execute("""
        CREATE TABLE IF NOT EXISTS security_event_migrations (
            migration_id TEXT PRIMARY KEY,
            applied_at TEXT NOT NULL
        )
    """)
    migration_id = "details-minimization-v1"
    if conn.execute(
        "SELECT 1 FROM security_event_migrations WHERE migration_id=?",
        (migration_id,),
    ).fetchone() is None:
        for row_id, request_path, raw_details in conn.execute(
            "SELECT id, request_path, details_json FROM security_events"
        ).fetchall():
            try:
                decoded = json.loads(raw_details or "{}")
            except Exception:
                decoded = {"legacy_payload_hash": canonical_event_hash(raw_details or "")}
            if not isinstance(decoded, dict):
                decoded = {"legacy_payload_hash": canonical_event_hash(raw_details or "")}
            minimized_text = json.dumps(
                minimize_security_details(decoded), sort_keys=True, default=str, indent=2
            )
            conn.execute(
                "UPDATE security_events SET request_path=?, details_hash=?, details_json=? WHERE id=?",
                (
                    canonical_event_hash(request_path) if request_path else "",
                    canonical_event_hash(minimized_text),
                    minimized_text,
                    row_id,
                ),
            )
        conn.execute(
            "INSERT INTO security_event_migrations(migration_id, applied_at) VALUES (?, ?)",
            (migration_id, now_utc().isoformat()),
        )

def record_event(priority: int, event_type: str, source_ip: str, details: dict, email_status: str) -> str:
    event_id = hmac.new(
        RATE_LIMIT_SECRET.encode(),
        json.dumps({
            "ts": time.time_ns(),
            "p": priority,
            "event": event_type,
            "source": source_ip or "unknown",
            "details": details or {},
        }, sort_keys=True, default=str).encode(),
        hashlib.sha256,
    ).hexdigest()[:32]
    try:
        SECURITY_EVENTS_DB.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        dt = now_utc()
        _, local_text = time_text(dt)
        detail_text = details_json(details)
        try:
            triage = classify_event(event_type, priority, source_ip, details)
        except Exception:
            triage = {
                "label": "needs_review",
                "score": 50,
                "confidence": 0.0,
                "reasons": ["classifier_unavailable"],
                "model_version": "fail-safe",
                "feedback_state": "unavailable",
            }
        with closing(sqlite3.connect(SECURITY_EVENTS_DB, timeout=10)) as conn, conn:
            configure_security_events_connection(conn)
            ensure_events_db(conn)
            conn.execute("""
                INSERT OR IGNORE INTO security_events (
                    event_id, observed_at_utc, observed_at_eastern, priority, event_type,
                    source_ip, source_ip_bucket, request_path, details_hash, details_json, email_status,
                    triage_label, triage_score, triage_confidence, triage_reasons,
                    triage_model_version, triage_feedback_state
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                event_id,
                dt.isoformat(),
                local_text,
                int(priority),
                event_type,
                None,
                source_ip_bucket_value(source_ip or "unknown"),
                "",
                # details_hash: canonical_event_hash(), NOT event_hash(). main.py's
                # record_security_event() writes this same column with the 16-char
                # str() form; event_hash() would JSON-encode detail_text first --
                # adding the surrounding quotes and escaping the payload's own --
                # and keep 24 chars, so identical details hashed to different
                # values depending only on which producer wrote the row.
                canonical_event_hash(detail_text),
                detail_text,
                email_status,
                triage.get("label", "needs_review"),
                int(triage.get("score", 50)),
                float(triage.get("confidence", 0.0)),
                json.dumps(triage.get("reasons", []), separators=(",", ":")),
                triage.get("model_version", "unknown"),
                triage.get("feedback_state", "none"),
            ))
    except Exception as exc:
        print(f"security event DB write failed: {exc}", file=sys.stderr)
    return event_id

def update_event_email_status(event_id: str, status: str, error: str = ""):
    if not event_id:
        return
    try:
        with closing(sqlite3.connect(SECURITY_EVENTS_DB, timeout=10)) as conn, conn:
            configure_security_events_connection(conn)
            conn.execute(
                "UPDATE security_events SET email_status = ?, email_error = ? WHERE event_id = ?",
                (status, error[:500], event_id),
            )
    except Exception as exc:
        print(f"security event DB update failed: {exc}", file=sys.stderr)

def alert_body(priority: int, event_type: str, source_ip: str, details: dict, event_id: str) -> str:
    _, local_text = time_text(now_utc())
    # Same contract as main.py's format_security_alert_body (2026-08-07 audit
    # §3.5). record_event() above writes None into security_events.source_ip and
    # keeps only source_ip_bucket_value(source_ip or "unknown") in source_ip_bucket; this
    # email must not re-export what that row deliberately dropped, because it
    # leaves the host through a third-party relay every 60 seconds.
    #
    # Use source_ip_bucket_value(), NOT event_hash(): the value printed here has
    # to be the value stored in THIS row so an operator can find it. Since
    # 2026-08-07 that is the canonical 16-char str()-encoded form shared with
    # main.py and the wins-security-events CLI. Keep this expression identical
    # to record_event()'s.
    #
    # details_json() returns a copy with client/source addresses and HTTP
    # destination fields keyed-hashed. The raw in-memory dict remains available
    # to classification and suppression logic, but never enters email or SQLite.
    rows = [
        ("Time (ET)", local_text),
        ("Priority", f"P{priority}"),
        ("Event", event_type),
        ("Source bucket", source_ip_bucket_value(source_ip or "unknown")),
        ("Event ID", event_id or "n/a"),
    ]
    triage_reasons = []
    try:
        with closing(sqlite3.connect(SECURITY_EVENTS_DB, timeout=10)) as conn, conn:
            configure_security_events_connection(conn)
            row = conn.execute("""
                SELECT triage_label, triage_score, triage_confidence, triage_reasons
                FROM security_events WHERE event_id=?
            """, (event_id,)).fetchone()
        if row:
            rows.extend([
                ("Triage", row[0] or "needs_review"),
                ("Risk score", str(row[1] if row[1] is not None else 50)),
                ("Confidence", f"{float(row[2] or 0.0):.2f}"),
            ])
            triage_reasons = json.loads(row[3] or "[]")
    except Exception:
        rows.append(("Triage", "needs_review"))
    lines = [f"{label:<14}: {value}" for label, value in rows]
    if triage_reasons:
        lines.append("Triage reasons : " + ", ".join(str(item) for item in triage_reasons[:8]))
    lines.append("Details       :")
    lines.append(details_json(details))
    return "\n".join(lines)

def throttle_identity(priority: int, event_type: str, source_ip: str, details: dict) -> dict:
    signature_text = alert_text(details)
    if event_type == "suricata alert":
        family = str((details or {}).get("signature_id") or "")
        if any(marker in signature_text for marker in (
            "/etc/passwd",
            "path traversal",
            "webshell",
            "mirai",
            "exploit",
        )):
            family = "http-exploit-probe"
        return {
            "p": int(priority),
            "event": event_type,
            "family": family,
            "source": source_ip or "unknown",
            "dest": str((details or {}).get("dest_ip") or (details or {}).get("destination_ip") or ""),
            "port": str((details or {}).get("dest_port") or ""),
        }
    # line_hash differs on every journal line, so keeping it made every key
    # unique and the throttle never held (435 login mails, 2026-10-22..31).
    return {
        "p": int(priority),
        "event": event_type,
        "source": source_ip or "unknown",
        "details": {k: v for k, v in (details or {}).items() if k != "line_hash"},
    }

def throttle_window(event_type: str, details: dict) -> int:
    if (event_type == "successful ssh login"
            and (details or {}).get("trusted_admin_source") is True
            and (details or {}).get("method") == "publickey"):
        return max(THROTTLE_SECONDS, TRUSTED_LOGIN_THROTTLE_SECONDS)
    return THROTTLE_SECONDS

def throttle_ok(priority: int, event_type: str, source_ip: str, details: dict) -> bool:
    key = event_hash(throttle_identity(priority, event_type, source_ip, details))
    path = STATE_DIR / f"monitor-{key}.last"
    now = time.time()
    try:
        previous = float(path.read_text(encoding="utf-8").strip()) if path.exists() else 0.0
    except Exception:
        previous = 0.0
    if now - previous < throttle_window(event_type, details):
        return False
    # Atomic replace: wins-hub can write this directory, and a write through
    # a planted link would let it overwrite any host file as this root job.
    write_journal_cursor(path, now)
    return True

def event_involves_exempt_ip(source_ip: str, details: dict) -> bool:
    candidates = {source_ip or ""}
    for key in ("src_ip", "source_ip", "dest_ip", "destination_ip", "client_ip", "remote_ip"):
        value = (details or {}).get(key)
        if value:
            candidates.add(str(value))
    return bool(candidates & (EXEMPT_IPS | LOOPBACK_EXEMPT_IPS))

def email_enabled_for_priority(priority: int) -> bool:
    return int(priority) in EMAIL_PRIORITIES

def alert_text(details: dict) -> str:
    return " ".join(str((details or {}).get(k) or "") for k in ("signature", "category")).lower()

def inbound_to_local(details: dict) -> bool:
    dest_ip = str((details or {}).get("dest_ip") or (details or {}).get("destination_ip") or "").strip()
    src_ip = str((details or {}).get("src_ip") or (details or {}).get("source_ip") or "").strip()
    return bool(dest_ip and dest_ip in LOCAL_IPS and src_ip not in LOCAL_IPS)

def no_record_by_policy(event_type: str, details: dict) -> bool:
    if event_type != "suricata alert":
        return False
    signature_id = str((details or {}).get("signature_id") or "").strip()
    if signature_id and signature_id in NO_RECORD_SIGNATURE_IDS:
        return True
    signature_text = alert_text(details)
    if any(pattern in signature_text for pattern in NO_RECORD_SIGNATURE_PATTERNS):
        return True
    if inbound_to_local(details):
        return any(pattern in signature_text for pattern in NO_RECORD_INBOUND_PATTERNS)
    return False

def suppressed_by_policy(event_type: str, details: dict) -> bool:
    signature_id = str((details or {}).get("signature_id") or "").strip()
    if signature_id and signature_id in SUPPRESS_SIGNATURE_IDS:
        return True
    if event_type != "suricata alert" and "signature" not in (details or {}) and "category" not in (details or {}):
        return False
    signature_text = " ".join(str((details or {}).get(k) or "") for k in ("signature", "category")).lower()
    return any(pattern in signature_text for pattern in SUPPRESS_SIGNATURE_PATTERNS)

def send_alert(priority: int, event_type: str, source_ip: str, details: dict, *, bypass_exempt: bool = False):
    global EMAILS_SENT
    source_ip = source_ip or "unknown"
    if no_record_by_policy(event_type, details):
        return
    if event_type == "suricata alert" and expected_local_health_event(details):
        record_event(priority, event_type, source_ip, details, "expected_health_check")
        return
    if not bypass_exempt and event_involves_exempt_ip(source_ip, details):
        record_event(priority, event_type, source_ip, details, "exempt")
        return
    if suppressed_by_policy(event_type, details):
        record_event(priority, event_type, source_ip, details, "suppressed")
        return
    if not email_enabled_for_priority(priority):
        record_event(priority, event_type, source_ip, details, "log_only")
        return
    if not throttle_ok(priority, event_type, source_ip, details):
        record_event(priority, event_type, source_ip, details, "throttled")
        return
    if EMAILS_SENT >= MAX_EMAILS_PER_RUN:
        record_event(priority, event_type, source_ip, details, "capped")
        return
    event_id = record_event(priority, event_type, source_ip, details, "queued")
    if not (SMTP_USER and SMTP_PASS and SECURITY_ALERT_EMAIL):
        update_event_email_status(event_id, "skipped")
        print("security alert skipped: SMTP/security recipient not configured", file=sys.stderr)
        return
    body = alert_body(priority, event_type, source_ip, details, event_id)
    msg = MIMEText(body, "plain")
    # Keyed bucket, not the raw address -- see alert_body(). Same expression as
    # record_event()'s source_ip_bucket write.
    msg["Subject"] = (
        f"[Wins VPN Security P{priority}] {event_type} "
        f"from source {source_ip_bucket_value(source_ip or 'unknown')}"
    )
    msg["From"] = EMAIL_SENDER
    msg["To"] = SECURITY_ALERT_EMAIL
    try:
        with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=20) as server:
            server.ehlo()
            server.starttls(context=ssl.create_default_context())
            server.ehlo()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(EMAIL_SENDER, [SECURITY_ALERT_EMAIL], msg.as_string())
        update_event_email_status(event_id, "sent")
        EMAILS_SENT += 1
    except Exception as exc:
        update_event_email_status(event_id, "failed", str(exc))
        print(f"Security alert email failed: {exc}", file=sys.stderr)

def monitor_suricata():
    offset_path = STATE_DIR / "suricata-eve.offset"
    identity_path = STATE_DIR / "suricata-eve.identity"
    if not EVE_PATH.exists():
        return
    with EVE_PATH.open("r", encoding="utf-8", errors="ignore") as f:
        # The offset is only meaningful for the file it was taken from. After
        # logrotate renames eve.json, a new file that has already grown past
        # the old offset must be read from its start, not from that offset.
        info = os.fstat(f.fileno())
        identity = f"{info.st_dev}:{info.st_ino}"
        if not offset_path.exists():
            write_journal_cursor(offset_path, info.st_size)
            write_journal_cursor(identity_path, identity)
            return
        try:
            offset = int(offset_path.read_text(encoding="utf-8").strip() or "0")
        except (OSError, ValueError):
            offset = 0
        try:
            previous_identity = identity_path.read_text(encoding="utf-8").strip()
        except FileNotFoundError:
            # A state directory from before the identity marker: keep the
            # offset rather than replaying the whole current log once.
            previous_identity = identity
        except (OSError, ValueError):
            previous_identity = ""
        if previous_identity != identity or offset < 0 or info.st_size < offset:
            offset = 0
        f.seek(offset)
        for line in f:
            try:
                event = json.loads(line)
            except Exception:
                continue
            if event.get("event_type") != "alert":
                continue
            alert = event.get("alert") or {}
            try:
                severity = int(alert.get("severity") or 4)
            except Exception:
                severity = 4
            if severity not in (1, 2, 3):
                continue
            client_source = str(alert.get("xff") or event.get("xff") or event.get("src_ip") or "unknown").strip()
            http = event.get("http") if isinstance(event.get("http"), dict) else {}
            send_alert(severity, "suricata alert", client_source, {
                "src_ip": client_source,
                "transport_src_ip": event.get("src_ip"),
                "src_port": event.get("src_port"),
                "signature_id": alert.get("signature_id"),
                "signature_rev": alert.get("rev"),
                "signature": alert.get("signature"),
                "category": alert.get("category"),
                "action": alert.get("action"),
                "metadata": alert.get("metadata") or {},
                "proto": event.get("proto"),
                "app_proto": event.get("app_proto"),
                "direction": event.get("direction"),
                "flow_id": event.get("flow_id"),
                "dest_ip": event.get("dest_ip"),
                "dest_port": event.get("dest_port"),
                "http_method": http.get("http_method"),
                "http_url": http.get("url"),
                "http_user_agent": http.get("http_user_agent"),
                "verdict_action": (event.get("verdict") or {}).get("action") if isinstance(event.get("verdict"), dict) else None,
            })
        write_journal_cursor(offset_path, f.tell())
        # The identity marker is written last: a crash between the two writes
        # can replay alerts after a rotation, but cannot skip them.
        write_journal_cursor(identity_path, identity)

IP_RE = re.compile(r"(?:from|rhost=)\s*([0-9a-fA-F:.]+)")

def source_from_line(line: str) -> str:
    match = IP_RE.search(line)
    return match.group(1) if match else "local"

def write_journal_cursor(path: Path, timestamp: int | float | str) -> None:
    fd, temporary = tempfile.mkstemp(prefix=".journal-cursor-", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(str(timestamp))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        Path(temporary).unlink(missing_ok=True)

def monitor_journal():
    state_path = STATE_DIR / "journal-auth.last"
    now = int(time.time())
    try:
        since = int(float(state_path.read_text(encoding="utf-8").strip() or str(now - 60)))
    except Exception:
        since = now - 60
    # Bound each run to a 300 s window: after an outage or a login flood the
    # backlog drains one window per run, instead of being read whole into
    # memory and timing out before the cursor moves (which wedged the monitor).
    until = now if since >= now else min(now, since + 300)
    cmd = ["journalctl", f"--since=@{since}", f"--until=@{until}", "-o", "short-unix", "--no-pager"]
    result = subprocess.run(cmd, check=True, capture_output=True, text=True, timeout=25)
    for line in result.stdout.splitlines():
        lowered = line.lower()
        if "failed password" in lowered or "invalid user" in lowered:
            send_alert(3, "failed ssh login", source_from_line(line), {
                "line_hash": event_hash(line),
            })
        elif "sshd[" in lowered and (
            "accepted publickey" in lowered
            or "accepted password" in lowered
            or "accepted keyboard-interactive" in lowered
        ):
            source_ip = source_from_line(line)
            method_match = re.search(r"accepted\s+([a-z-]+)", lowered)
            user_match = re.search(r"for\s+(\S+)\s+from", line, re.IGNORECASE)
            send_alert(2, "successful ssh login", source_ip, {
                "method": method_match.group(1) if method_match else "unknown",
                "user": user_match.group(1) if user_match else "unknown",
                "trusted_admin_source": source_in_admin_ssh_network(source_ip),
                "line_hash": event_hash(line),
            })
        elif "sudo:" in lowered and ("authentication failure" in lowered or "user not in sudoers" in lowered or " command=" in lowered):
            send_alert(2, "admin privilege escalation", source_from_line(line), {
                "mechanism": "sudo",
                "line_hash": event_hash(line),
            })
        elif "wins-boot-integrity" in line and ("BOOT-CHAIN MISMATCH" in line or "BOOT-CHAIN UNRECORDED" in line):
            # TP-R2 (b): the boot chain on the unencrypted /boot changed outside a
            # sanctioned install or upgrade, or was never recorded.
            send_alert(1, "boot chain integrity mismatch", "local", {
                "unrecorded": "BOOT-CHAIN UNRECORDED" in line,
                "line_hash": event_hash(line),
            }, bypass_exempt=True)
        elif "wins-grub-superuser-guard" in line and "GRUB-SUPERUSER" in line:
            # TP-R2 (a) guard: a grub package update changed 10_linux; the guard
            # restored unattended boots (reapplied, or removed the superuser),
            # or FAILED to (FLEET1 Turn 3: never reported as a repair).
            send_alert(1, "grub superuser guard acted", "local", {
                "removed": "GRUB-SUPERUSER REMOVED" in line,
                "failed": "GRUB-SUPERUSER FAILED" in line,
                "line_hash": event_hash(line),
            }, bypass_exempt=True)
        elif "su:" in lowered and ("authentication failure" in lowered or "failed su" in lowered or "session opened for user root" in lowered):
            send_alert(2, "admin privilege escalation", source_from_line(line), {
                "mechanism": "su",
                "line_hash": event_hash(line),
            })
    write_journal_cursor(state_path, until)


def main():
    if "--test-email" in sys.argv:
        send_alert(2, "security alert test", "monitor", {"test": True})
        print("test security alert submitted")
        return
    monitor_suricata()
    monitor_journal()
    # FLEET2: proof of a COMPLETED run. wins-alert-watchdog (every 5 min, and
    # OnFailure of this unit) and the external hub watcher alert when it is
    # older than 5 min, so a monitor that stops firing or keeps failing is
    # itself an alert (it was silent from 2026-10-02 to 2026-10-09).
    write_journal_cursor(STATE_DIR / "monitor.ok", int(time.time()))

if __name__ == "__main__":
    main()
PYEOF
  sed -i 's/\r$//' /usr/local/bin/wins-security-alert-monitor
  chmod 700 /usr/local/bin/wins-security-alert-monitor

  cat > /etc/systemd/system/wins-security-alert-monitor.service <<'EOF'
[Unit]
Description=Wins VPN security email alert monitor
After=network-online.target suricata.service fail2ban.service
Wants=network-online.target
OnFailure=wins-alert-watchdog.service

[Service]
Type=oneshot
ExecStart=/usr/local/bin/wins-security-alert-monitor
TimeoutStartSec=75
UMask=0077
# wins-hub.service can write the state directory below; this root job must
# never be able to write anywhere else on the host through a link planted
# there. Reads (journal, eve.json, the env file) keep their current reach.
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=read-only
ReadWritePaths=/var/lib/wins-security-alerts
CapabilityBoundingSet=CAP_DAC_READ_SEARCH
LimitCORE=0
EOF

  # FLEET2 (owner, 2026-10-10): a wall-clock timer. The monotonic form
  # (OnBootSec= plus OnUnitActiveSec=) has no base when its service has not
  # run this boot and can sit "elapsed" with no next run (CP-14, CP-14b); it
  # stopped this monitor from 2026-10-02 until a restart on 2026-10-09. An
  # OnCalendar= timer always computes its next elapse from the clock, a failed
  # or slow run never stops it, and Persistent=true runs a missed minute at
  # boot. restart (not just enable --now) re-arms a timer that an older unit
  # left elapsed.
  cat > /etc/systemd/system/wins-security-alert-monitor.timer <<'EOF'
[Unit]
Description=Run Wins VPN security email alert monitor every minute

[Timer]
OnCalendar=*-*-* *:*:00
AccuracySec=5s
Persistent=true
Unit=wins-security-alert-monitor.service

[Install]
WantedBy=timers.target
EOF

  systemctl daemon-reload
  systemctl enable wins-security-alert-monitor.timer
  systemctl restart wins-security-alert-monitor.timer
}

# --- FLEET2: tamper alerts that a local root cannot silence (owner, 2026-10-10)
# "If someone were to change the password like if rogue data center employee
# does it, it should be alerted to me via email." The checks run OFF the host
# they check, and the baseline lives with the checker:
#   * wins-attest-collect (read-only, writes nothing) reports digests of the
#     account, sudo, PAM, sshd, host-key, boot-chain and persistence files,
#     per-account password STATE and a change tag (never a hash), SSH key
#     fingerprints, boot_id, boot time, uptime, logins since boot from the
#     RAM-only journal (counts by user, method and fingerprint; no address),
#     and hypervisor agent states.
#   * wins-fleet-attest --role hub run (every 2 min) pipes the collector to
#     every non-retired node over SSH (the hub key, pinned host keys, the
#     Cloudflare Access ProxyCommand, exactly like node_ssh_command), runs it
#     on the hub itself, compares with the baseline under
#     /var/lib/wins-fleet-attest, checks node heartbeats, and mails
#     SECURITY_ALERT_EMAIL through a retrying outbox. Nothing on a node has to
#     stay installed or running for the check to happen, so there is no node
#     agent to disable.
#   * wins-alert-watchdog (every 5 min, and OnFailure of the monitor and the
#     attestation) mails when the monitor or the attestation stops completing
#     runs, a timer is inactive (it restarts it once an hour) or mail is stuck.
#   * a daily digest (11:00 UTC) is mailed even when all is clear, so silence
#     is itself the signal.
#   * the hub itself is watched from outside its data center by
#     server/wins_hub_watch_setup.sh on an owner-controlled host that the hub
#     cannot log in to (setup refuses otherwise), through a forced-command
#     key (install_hub_watcher_key below).
# Maintenance: `wins-fleet-attest --role hub window <target>|all --minutes N
# --kinds ... --reason ...` before planned work, `ack <target> --reason ...`
# after a legitimate change. Both run as root on the hub only and each mails a
# notice; credentials, SSH keys, host keys, the sshd settings that decide who
# may log in and how (ssh_auth), console logins and logins by a key outside
# the accepted set are never covered by a window.
FLEET_ATTEST_STATE_DIR="/var/lib/wins-fleet-attest"
HUB_WATCHER_SSH_PUBKEY_FILE_DEFAULT="${HUB_WATCHER_SSH_PUBKEY_FILE:-/root/winsvpn-hub-watcher.pub}"
WINS_GUEST_AGENT_UNITS_DEFAULT="qemu-guest-agent.service open-vm-tools.service vmtoolsd.service"

write_fleet_attest() {
  log "Installing off-host tamper attestation, alert watchdog and daily digest (FLEET2)"
  install -d -m 0700 "${FLEET_ATTEST_STATE_DIR}" || return 1
  install -d -m 0755 /usr/local/lib /usr/local/sbin || return 1
  install_generated_file 0644 /usr/local/lib/wins-attest-collect.py <<'ATTESTCOLLECTEOF'
#!/usr/bin/env python3
"""wins-attest-collect (FLEET2): a read-only tamper snapshot for off-host checks.

The hub runs it on every node over SSH as `python3 -I - <nonce>` with this
file on stdin, so nothing on the node has to stay installed or running for
the check to happen; the hub runs it on itself from
/usr/local/lib/wins-attest-collect.py; the external hub watcher gets it from
the hub's forced command. It writes nothing and prints one JSON object.

What it reports, and what it never reports:
  * file digests (sha256) of the account, sudo, PAM, sshd, host-key, boot
    chain and persistence files, never their contents;
  * per account: name, uid, gid, home, shell, the password STATE (locked,
    empty or usable), the shadow last-change day and a 16-hex tag that only
    tells whether the shadow password field changed; never a hash;
  * authorized_keys entries as key type and SHA256 fingerprint;
  * boot identity (boot_id, boot time, uptime), kernel, cmdline digest;
  * logins since boot from the RAM-only journal as counts by user, method
    and key fingerprint, and console ttys; never an address or a port;
  * hypervisor and cloud agent unit states.
A root attacker on the running host can forge any of this; the hub keeps the
baseline and also trusts only what it sees from outside (see the FLEET2 seat
record).
"""
import base64
import glob
import hashlib
import json
import os
import re
import subprocess
import sys
import time

VERSION = 1
NONCE_RE = re.compile(r"^[0-9a-f]{32}$")
FILES = {
    "accounts": ["/etc/passwd", "/etc/group", "/etc/shadow", "/etc/gshadow", "/etc/subuid", "/etc/subgid"],
    "sudo": ["/etc/sudoers", "/etc/sudoers.d/*"],
    "pam": ["/etc/pam.d/*", "/etc/security/access.conf", "/etc/security/pam_env.conf",
            "/etc/nsswitch.conf", "/etc/ld.so.preload", "/etc/login.defs", "/etc/securetty"],
    "ssh": ["/etc/ssh/sshd_config", "/etc/ssh/sshd_config.d/*",
            "/etc/dropbear/initramfs/authorized_keys", "/etc/dropbear/initramfs/dropbear.conf"],
    "hostkeys": ["/etc/ssh/ssh_host_*_key.pub"],
    "boot": ["/boot/vmlinuz-*", "/boot/initrd.img-*", "/boot/grub/grub.cfg",
             "/boot/grub/x86_64-efi/core.efi", "/boot/grub/i386-pc/core.img",
             "/boot/efi/EFI/*/grub.cfg", "/boot/efi/EFI/*/*.efi", "/boot/efi/EFI/BOOT/*.EFI",
             "/etc/default/grub", "/etc/default/grub.d/*", "/etc/grub.d/*", "/etc/kernel/cmdline"],
    "persistence": ["/etc/crontab", "/etc/cron.d/*", "/var/spool/cron/crontabs/*", "/etc/rc.local",
                    "/etc/systemd/system/*.service", "/etc/systemd/system/*.timer",
                    "/etc/systemd/system/*.path", "/etc/systemd/system/*.socket",
                    "/etc/systemd/system/*.d/*.conf", "/etc/systemd/system/*.wants/*",
                    "/etc/profile.d/*", "/etc/environment",
                    "/etc/apt/apt.conf.d/*", "/root/.bashrc", "/root/.profile"],
}
BOOT_PACKAGES = re.compile(r"^(linux-image|linux-modules|linux-signed|grub|shim|initramfs-tools|systemd-boot|dracut)")
AGENT_UNITS = ("qemu-guest-agent.service", "open-vm-tools.service", "vmtoolsd.service",
               "google-guest-agent.service", "walinuxagent.service", "amazon-ssm-agent.service",
               "snap.amazon-ssm-agent.amazon-ssm-agent.service", "cloud-init.service")
SSHD_FIELDS = ("port", "permitrootlogin", "passwordauthentication", "kbdinteractiveauthentication",
               "pubkeyauthentication", "authorizedkeysfile", "authorizedkeyscommand",
               "authorizedkeyscommanduser", "authorizedprincipalsfile", "trustedusercakeys",
               "allowusers", "allowgroups", "permitemptypasswords", "usepam", "hostbasedauthentication")
# The fields that decide WHO may log in and HOW. They are reported apart from
# the rest (sshd.auth, not sshd.fields) so the checker treats a change to them
# like a key change: never covered by a maintenance window. A planted
# AuthorizedKeysCommand or TrustedUserCAKeys is a key grant by another name.
SSHD_AUTH_FIELDS = ("permitrootlogin", "passwordauthentication", "kbdinteractiveauthentication",
                    "pubkeyauthentication", "authorizedkeysfile", "authorizedkeyscommand",
                    "authorizedkeyscommanduser", "authorizedprincipalsfile", "trustedusercakeys",
                    "permitemptypasswords", "usepam", "hostbasedauthentication")
# FLEET2 Turn 2 (from the glm seat): kernel command-line markers of a
# single-user, rescue, emergency or init-replacing boot. Only the marker
# names leave the host, never the command line itself.
RESCUE_TOKENS = {"single", "s", "1", "emergency", "rescue", "-b", "rd.shell", "systemd.debug-shell"}
RESCUE_PREFIXES = ("init=", "rd.break", "break=", "rdinit=", "systemd.unit=rescue", "systemd.unit=emergency",
                   "systemd.unit=single")
KEY_TYPE = re.compile(r"^(ssh-(ed25519|rsa|dss)|ecdsa-sha2-nistp(256|384|521)|sk-(ssh-ed25519|ecdsa-sha2-nistp256)@openssh\.com)(-cert-v01@openssh\.com)?$")
ACCEPTED = re.compile(r"Accepted (\S+) for (\S+) from \S+ port \d+ \S+?(?:: (\S+) (SHA256:\S+))?$")


SAFE_PATH = "/usr/sbin:/usr/bin:/sbin:/bin"


class Collector:
    def __init__(self, root=""):
        self.root = root.rstrip("/")
        self.errors = []

    def p(self, path):
        return self.root + path

    def error(self, what, exc):
        self.errors.append("%s: %s" % (what, type(exc).__name__ if isinstance(exc, BaseException) else exc))

    def read_bytes(self, path, limit=None):
        with open(self.p(path), "rb") as handle:
            return handle.read() if limit is None else handle.read(limit)

    def read_text(self, path):
        return self.read_bytes(path).decode("utf-8", "replace")

    def digest(self, path):
        if os.path.islink(self.p(path)):
            # A masked or enabled unit is a link; its target is the content.
            try:
                return "link:" + os.readlink(self.p(path))
            except OSError as exc:
                self.error(path, exc)
                return "unreadable"
        try:
            h = hashlib.sha256()
            with open(self.p(path), "rb") as handle:
                for chunk in iter(lambda: handle.read(1 << 20), b""):
                    h.update(chunk)
            return h.hexdigest()
        except FileNotFoundError:
            return None
        except OSError as exc:
            self.error(path, exc)
            return "unreadable"

    def expand(self, patterns):
        out = set()
        for pattern in patterns:
            for hit in glob.glob(self.p(pattern)):
                if os.path.islink(hit) or os.path.isfile(hit):
                    out.add(hit[len(self.root):] if self.root else hit)
        return sorted(out)

    def files(self):
        result = {}
        for category, patterns in FILES.items():
            entries = {}
            for path in self.expand(patterns):
                value = self.digest(path)
                if value is not None:
                    entries[path] = value
            result[category] = entries
        return result

    def run(self, argv, timeout=20):
        try:
            done = subprocess.run(argv, capture_output=True, text=True, errors="replace",
                                  timeout=timeout, env={"PATH": SAFE_PATH, "LC_ALL": "C"})
        except (OSError, subprocess.SubprocessError) as exc:
            self.error(argv[0], exc)
            return None
        return done

    def accounts(self):
        shadow = {}
        try:
            for line in self.read_text("/etc/shadow").splitlines():
                parts = line.split(":")
                if len(parts) >= 3 and parts[0]:
                    shadow[parts[0]] = (parts[1], parts[2])
        except OSError as exc:
            self.error("/etc/shadow", exc)
        rows = []
        try:
            lines = self.read_text("/etc/passwd").splitlines()
        except OSError as exc:
            self.error("/etc/passwd", exc)
            lines = []
        for line in lines:
            parts = line.split(":")
            if len(parts) < 7 or not parts[0] or parts[0].startswith(("#", "+", "-")):
                continue
            name, field, uid, gid, _gecos, home, shell = parts[:7]
            if field not in ("x", "*", "!"):
                secret = field              # a hash in passwd itself
            else:
                secret = shadow.get(name, ("!", ""))[0]
            if secret == "":
                state = "empty"
            elif secret.startswith(("!", "*")):
                state = "locked"
            else:
                state = "usable"
            tag = hashlib.sha256(b"wins-attest-pw-v1\0" + name.encode() + b"\0" + secret.encode()).hexdigest()[:16]
            rows.append({"name": name, "uid": uid, "gid": gid, "home": home, "shell": shell,
                         "pw": state, "pwtag": tag, "lastchg": shadow.get(name, ("", ""))[1]})
        rows.sort(key=lambda r: r["name"])
        return rows

    @staticmethod
    def split_key_line(line):
        """(options, type, blob) of one authorized_keys line, or None."""
        text = line.strip()
        if not text or text.startswith("#"):
            return "skip"
        options = ""
        first = text.split(None, 1)[0]
        if not KEY_TYPE.match(first):
            quoted, i = False, 0
            while i < len(text):
                ch = text[i]
                if ch == "\\" and quoted:
                    i += 2
                    continue
                if ch == '"':
                    quoted = not quoted
                elif ch in " \t" and not quoted:
                    break
                i += 1
            options, text = text[:i], text[i:].strip()
        fields = text.split()
        if len(fields) < 2 or not KEY_TYPE.match(fields[0]):
            return None
        return options, fields[0], fields[1]

    @staticmethod
    def fingerprint(blob):
        raw = base64.b64decode(blob.encode(), validate=True)
        return "SHA256:" + base64.b64encode(hashlib.sha256(raw).digest()).decode().rstrip("=")

    def key_file(self, path):
        try:
            data = self.read_bytes(path)
        except FileNotFoundError:
            return None
        except OSError as exc:
            self.error(path, exc)
            return {"digest": "unreadable", "keys": [], "unparsed": 0}
        keys, unparsed = [], 0
        for line in data.decode("utf-8", "replace").splitlines():
            parsed = self.split_key_line(line)
            if parsed == "skip":
                continue
            if parsed is None:
                unparsed += 1
                continue
            options, key_type, blob = parsed
            try:
                fp = self.fingerprint(blob)
            except ValueError:
                unparsed += 1
                continue
            entry = {"type": key_type, "fp": fp}
            if options:
                # The options decide what the key may do (command=, from=,
                # restrict); their digest shows a change without copying them.
                entry["opts"] = hashlib.sha256(options.encode()).hexdigest()[:16]
            keys.append(entry)
        keys.sort(key=lambda k: (k["fp"], k.get("opts", "")))
        return {"digest": hashlib.sha256(data).hexdigest(), "keys": keys, "unparsed": unparsed}

    def authorized_keys(self, accounts, sshd):
        templates = (sshd.get("auth", {}).get("authorizedkeysfile") or ".ssh/authorized_keys .ssh/authorized_keys2").split()
        for extra in (".ssh/authorized_keys", ".ssh/authorized_keys2"):
            if extra not in templates:
                templates.append(extra)
        result = {}
        for row in accounts:
            home = row["home"] or "/"
            seen = set()
            for template in templates:
                if template == "none":
                    continue
                path = template.replace("%%", "\0").replace("%h", home).replace("%u", row["name"]).replace("%U", row["uid"]).replace("\0", "%")
                if not path.startswith("/"):
                    path = home.rstrip("/") + "/" + path
                path = os.path.normpath(path)
                if path in seen:
                    continue
                seen.add(path)
                entry = self.key_file(path)
                if entry is not None:
                    result.setdefault(row["name"], {})[path] = entry
        return result

    def sshd(self):
        done = self.run(["sshd", "-T"], timeout=15)
        if done is None or done.returncode != 0:
            if done is not None:
                self.errors.append("sshd -T: exit %d" % done.returncode)
            return {"digest": "unavailable", "fields": {}, "auth": {}}
        fields, auth, rest = {}, {}, []
        for line in done.stdout.splitlines():
            key, _, value = line.partition(" ")
            if key in SSHD_AUTH_FIELDS:
                auth[key] = (auth[key] + " " + value) if key in auth else value
                continue
            rest.append(line)
            if key in SSHD_FIELDS:
                fields[key] = (fields[key] + " " + value) if key in fields else value
        # The digest covers every line the auth section does not report, so
        # the ssh and ssh_auth kinds never overlap: an auth change never moves
        # this digest, and acking either kind leaves nothing behind for the other.
        return {"digest": hashlib.sha256("\n".join(rest).encode()).hexdigest(), "fields": fields, "auth": auth}

    def boot_packages(self):
        try:
            text = self.read_text("/var/lib/dpkg/status")
        except OSError as exc:
            self.error("/var/lib/dpkg/status", exc)
            return []
        out = []
        for stanza in text.split("\n\n"):
            fields = dict(re.findall(r"^(Package|Status|Version): (.*)$", stanza, re.M))
            if fields.get("Status", "").endswith(" installed") and BOOT_PACKAGES.match(fields.get("Package", "")):
                out.append("%s=%s" % (fields["Package"], fields.get("Version", "")))
        return sorted(out)

    def identity(self):
        ident = {}
        try:
            ident["boot_id"] = self.read_text("/proc/sys/kernel/random/boot_id").strip()
        except OSError as exc:
            self.error("boot_id", exc)
            ident["boot_id"] = ""
        try:
            ident["uptime"] = float(self.read_text("/proc/uptime").split()[0])
        except (OSError, ValueError, IndexError) as exc:
            self.error("uptime", exc)
            ident["uptime"] = -1.0
        try:
            match = re.search(r"^btime (\d+)$", self.read_text("/proc/stat"), re.M)
            ident["btime"] = int(match.group(1)) if match else 0
        except OSError as exc:
            self.error("btime", exc)
            ident["btime"] = 0
        try:
            cmdline = self.read_bytes("/proc/cmdline")
            ident["cmdline_sha256"] = hashlib.sha256(cmdline).hexdigest()
            markers = set()
            for token in cmdline.decode("utf-8", "replace").split():
                low = token.lower()
                if low in RESCUE_TOKENS:
                    markers.add(low)
                for prefix in RESCUE_PREFIXES:
                    if low.startswith(prefix):
                        markers.add(prefix)
            ident["rescue"] = sorted(markers)
        except OSError as exc:
            self.error("cmdline", exc)
            ident["cmdline_sha256"] = "unreadable"
            ident["rescue"] = []
        ident["kernel"] = os.uname().release
        return ident

    def logins(self):
        done = self.run(["journalctl", "-b", "0", "-o", "json", "--no-pager",
                         "--output-fields=MESSAGE,SYSLOG_IDENTIFIER",
                         "-t", "login", "-t", "sshd", "-t", "sshd-session", "-t", "su", "-t", "sudo"], timeout=30)
        result = {"state": "ok", "console": {}, "console_failed": 0, "ttys": [], "ssh": {},
                  "ssh_failed": 0, "su": 0, "sudo": {}}
        if done is None or done.returncode != 0:
            result["state"] = "unavailable"
            if done is not None:
                self.errors.append("journalctl: exit %d" % done.returncode)
            return result
        ttys = set()
        for raw in done.stdout.splitlines():
            try:
                entry = json.loads(raw)
            except ValueError:
                continue
            ident, msg = str(entry.get("SYSLOG_IDENTIFIER", "")), entry.get("MESSAGE", "")
            if not isinstance(msg, str):
                continue
            if ident == "login":
                hit = re.search(r"pam_unix\(login:session\): session opened for user (\S+?)(?:\(uid=\d+\))?\s", msg + " ")
                if hit:
                    result["console"][hit.group(1)] = result["console"].get(hit.group(1), 0) + 1
                tty = re.search(r"LOGIN ON (\S+)", msg)
                if tty:
                    ttys.add(tty.group(1))
                if "FAILED LOGIN" in msg or "authentication failure" in msg:
                    result["console_failed"] += 1
            elif ident in ("sshd", "sshd-session"):
                hit = ACCEPTED.search(msg)
                if hit:
                    key = "%s %s %s" % (hit.group(2), hit.group(1), hit.group(4) or "-")
                    result["ssh"][key] = result["ssh"].get(key, 0) + 1
                elif "Failed password" in msg or "Invalid user" in msg:
                    result["ssh_failed"] += 1
            elif ident == "su":
                if "session opened for user" in msg:
                    result["su"] += 1
            elif ident == "sudo":
                hit = re.match(r"\s*(\S+) : .*COMMAND=", msg)
                if hit:
                    result["sudo"][hit.group(1)] = result["sudo"].get(hit.group(1), 0) + 1
        result["ttys"] = sorted(ttys)
        return result

    def agents(self):
        states = {}
        for unit in AGENT_UNITS:
            done = self.run(["systemctl", "is-active", unit], timeout=10)
            state = done.stdout.strip() if done is not None else "unknown"
            if state not in ("inactive", "unknown", ""):
                states[unit] = state
        return states

    def collect(self, nonce):
        accounts = self.accounts()
        sshd = self.sshd()
        obs = {
            "v": VERSION,
            "nonce": nonce,
            "now": time.time(),
            **self.identity(),
            "files": self.files(),
            "accounts": accounts,
            "sshd": sshd,
            "authorized_keys": self.authorized_keys(accounts, sshd),
            "boot_pkgs": self.boot_packages(),
            "logins": self.logins(),
            "agents": self.agents(),
        }
        obs["errors"] = sorted(set(self.errors))
        return obs


def main(argv):
    nonce = argv[1] if len(argv) > 1 else ""
    if not NONCE_RE.match(nonce):
        sys.stderr.write("usage: wins-attest-collect <32 hex nonce>\n")
        return 2
    sys.stdout.write(json.dumps(Collector().collect(nonce), sort_keys=True, separators=(",", ":")) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
ATTESTCOLLECTEOF
  (( $? == 0 )) || return 1
  install_generated_file 0700 /usr/local/sbin/wins-fleet-attest <<'FLEETATTESTEOF'
#!/usr/bin/env python3
"""wins-fleet-attest (FLEET2): off-host tamper verification and alert mail.

Roles:
  --role hub      on the hub: pulls wins-attest-collect from every
                  non-retired node over SSH (pinned host key, the hub key),
                  runs it on the hub itself, compares each result with a
                  baseline kept HERE (never on the node), watches node
                  heartbeats and the alerting pipeline, and mails
                  SECURITY_ALERT_EMAIL through SMTP2GO with a retrying outbox.
  --role watcher  on a host outside the hub's data center (the owner's
                  machine): pulls the hub's report through a forced-command
                  key and mails through its own SMTP credentials, so a dead,
                  rebooted or silenced hub is still reported.

Commands: run | watchdog | digest | status | hub-report |
          ack TARGET --reason TEXT [--kinds K,..] |
          window TARGET|all --minutes N --kinds K,.. --reason TEXT | window TARGET --close
ack and window run as root on this host only, and each one mails a notice, so
neither can quietly silence an alert. Credentials, keys, host keys, the sshd
settings that decide who may log in and how (ssh_auth), console logins and
unknown-key logins are never covered by a window.
"""
import argparse
import concurrent.futures
import fcntl
import hashlib
import ipaddress
import json
import os
import re
import secrets
import selectors
import signal
import smtplib
import sqlite3
import ssl
import subprocess
import sys
import tempfile
import time
from datetime import datetime, timezone
from email.message import EmailMessage
from email.utils import formatdate, make_msgid

COLLECTOR = "/usr/local/lib/wins-attest-collect.py"
PYTHON = "/usr/bin/python3"
SAFE_PATH = "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
NAME_RE = re.compile(r"^[a-z0-9][a-z0-9-]{0,62}$")
NONCE_RE = re.compile(r"^[0-9a-f]{32}$")

# kind: (priority, windowable, baseline sections)
PERSISTENT = {
    "credentials": (1, False, ("accounts",)),
    "keys": (1, False, ("authorized_keys",)),
    "hostkeys": (1, False, ("files.hostkeys",)),
    "ssh_auth": (1, False, ("sshd.auth",)),
    "ssh": (1, True, ("sshd.digest", "sshd.fields", "files.ssh")),
    "sudo_pam": (1, True, ("files.sudo", "files.pam")),
    "boot": (1, True, ("files.boot", "kernel", "cmdline_sha256", "boot_pkgs")),
    "accounts": (2, True, ("accounts", "files.accounts")),
    "persistence": (2, True, ("files.persistence",)),
    "agents": (2, True, ("agents",)),
    "collector": (2, True, ("errors",)),
}
# Condition kinds: open while the condition holds, keyed on a stable basis.
CONDITIONS = {"unreachable": True, "hostkey_mismatch": False, "unmanaged": True,
              "heartbeat": True, "pipeline": False, "state": False, "rescue_boot": False}
# Event kinds: mailed once (through the retrying outbox), never stored open.
EVENTS = {"reboot": True, "console_login": False, "ssh_login": False, "su_sudo": False,
          "inconsistent": False, "recovered": True}
WINDOWABLE = ({k for k, v in PERSISTENT.items() if v[1]} | {k for k, v in CONDITIONS.items() if v}
              | {k for k, v in EVENTS.items() if v})
WINDOW_MAX_MINUTES = 360
REALERT = {1: 6 * 3600, 2: 24 * 3600}
TIMER = {"hub": "wins-fleet-attest.timer", "watcher": "wins-hub-watch.timer"}


def utc(ts):
    return datetime.fromtimestamp(float(ts), timezone.utc).strftime("%Y-%m-%d %H:%M:%SZ") if ts else "never"


def age(now, ts):
    if not ts:
        return "never"
    s = int(now - float(ts))
    return "%ds" % s if s < 120 else ("%dm" % (s // 60) if s < 7200 else "%.1fh" % (s / 3600))


def ago(now, ts):
    return "never" if not ts else age(now, ts) + " ago"


def load_env(path):
    """KEY='value' lines as write_env_kv writes them (also KEY=value); data only."""
    env = {}
    try:
        lines = open(path, encoding="utf-8").read().splitlines()
    except OSError:
        return env
    for line in lines:
        m = re.fullmatch(r"\s*(?:export\s+)?([A-Z][A-Z0-9_]*)=(.*)", line)
        if not m:
            continue
        key, value = m.group(1), m.group(2).strip()
        if len(value) >= 2 and value[0] == value[-1] == "'":
            value = value[1:-1].replace("'\"'\"'", "'")
        elif len(value) >= 2 and value[0] == value[-1] == '"':
            value = value[1:-1]
        env[key] = value
    return env


def write_json(path, data):
    directory = os.path.dirname(path)
    fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(data, handle, sort_keys=True, separators=(",", ":"))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def read_json(path, default=None):
    try:
        with open(path, encoding="utf-8") as handle:
            return json.load(handle)
    except FileNotFoundError:
        return default


def section(obs, name):
    value = obs
    for part in name.split("."):
        value = (value or {}).get(part) if isinstance(value, dict) else None
    return value


def set_section(obs, name, value):
    parts = name.split(".")
    target = obs
    for part in parts[:-1]:
        target = target.setdefault(part, {})
    target[parts[-1]] = value


# ---------------------------------------------------------------- comparisons
def diff_map(old, new, label=""):
    old, new = old or {}, new or {}
    items = ["added: %s%s" % (label, k) for k in sorted(set(new) - set(old))]
    items += ["removed: %s%s" % (label, k) for k in sorted(set(old) - set(new))]
    items += ["changed: %s%s" % (label, k) for k in sorted(set(old) & set(new)) if old[k] != new[k]]
    return items


def cmp_credentials(base, cur):
    old = {r["name"]: r for r in base.get("accounts") or []}
    new = {r["name"]: r for r in cur.get("accounts") or []}
    items = []
    for name in sorted(new):
        n, o = new[name], old.get(name)
        if o is None:
            if n["pw"] != "locked" or n["uid"] == "0":
                items.append("new account %s with uid %s and %s password" % (name, n["uid"], n["pw"]))
            continue
        if n["pwtag"] != o["pwtag"] and not (n["pw"] == o["pw"] == "locked"):
            items.append("password of %s changed (%s -> %s; shadow last-change day %s -> %s)"
                         % (name, o["pw"], n["pw"], o.get("lastchg") or "?", n.get("lastchg") or "?"))
        if n["uid"] == "0" and o["uid"] != "0":
            items.append("%s now has uid 0" % name)
    return items


def cmp_accounts(base, cur):
    old = {r["name"]: r for r in base.get("accounts") or []}
    new = {r["name"]: r for r in cur.get("accounts") or []}
    items = []
    for name in sorted(set(old) | set(new)):
        if name not in old:
            items.append("account added: %s (uid %s, shell %s)" % (name, new[name]["uid"], new[name]["shell"]))
        elif name not in new:
            items.append("account removed: %s" % name)
        else:
            for field in ("uid", "gid", "home", "shell"):
                if old[name][field] != new[name][field]:
                    items.append("%s %s: %s -> %s" % (name, field, old[name][field], new[name][field]))
    return items + diff_map(section(base, "files.accounts"), section(cur, "files.accounts"))


def key_set(obs):
    out = {}
    for user, files in (obs.get("authorized_keys") or {}).items():
        for path, entry in files.items():
            for key in entry.get("keys", []):
                out[(user, path, key["fp"], key.get("opts", ""))] = key["type"]
            out[(user, path, "#unparsed", "")] = entry.get("unparsed", 0)
    return out


def cmp_keys(base, cur):
    old, new = key_set(base), key_set(cur)
    items = []
    for k in sorted(set(new) | set(old)):
        user, path, fp, opts = k
        if fp == "#unparsed":
            if old.get(k, 0) != new.get(k, 0):
                items.append("%s (%s): %s unparsable line(s), was %s" % (path, user, new.get(k, 0), old.get(k, 0)))
            continue
        extra = " with options" if opts else ""
        if k not in old:
            items.append("key added for %s in %s: %s %s%s" % (user, path, new[k], fp, extra))
        elif k not in new:
            items.append("key removed for %s in %s: %s %s%s" % (user, path, old[k], fp, extra))
    return items


def cmp_sshd_fields(base, cur, part):
    of = (base.get("sshd") or {}).get(part) or {}
    nf = (cur.get("sshd") or {}).get(part) or {}
    return ["sshd %s: %s -> %s" % (key, of.get(key, "(unset)"), nf.get(key, "(unset)"))
            for key in sorted(set(of) | set(nf)) if of.get(key) != nf.get(key)]


def cmp_ssh_auth(base, cur):
    return cmp_sshd_fields(base, cur, "auth")


def cmp_ssh(base, cur):
    items = cmp_sshd_fields(base, cur, "fields")
    ob, nb = base.get("sshd") or {}, cur.get("sshd") or {}
    # A digest change that no reported field explains. The collector keeps
    # the auth lines out of this digest, so an auth change is never doubled
    # here and a non-auth change beside it is named in the same run.
    if ob.get("digest") != nb.get("digest") and not items:
        items.append("sshd effective configuration changed (sshd -T)")
    return items + diff_map(section(base, "files.ssh"), section(cur, "files.ssh"))


def cmp_boot(base, cur):
    items = diff_map(section(base, "files.boot"), section(cur, "files.boot"))
    for key in ("kernel", "cmdline_sha256"):
        if base.get(key) != cur.get(key):
            items.append("%s: %s -> %s" % (key, str(base.get(key))[:16], str(cur.get(key))[:16]))
    pkgs = diff_map({p: 1 for p in base.get("boot_pkgs") or []}, {p: 1 for p in cur.get("boot_pkgs") or []}, "package ")
    return items + pkgs


def boot_explained(base, cur):
    """A boot-file change that came with a boot package change and changed
    neither the running kernel nor its command line (an apt kernel or GRUB
    update not yet booted). Anything else in /boot is unexplained."""
    return (base.get("boot_pkgs") != cur.get("boot_pkgs")
            and base.get("kernel") == cur.get("kernel")
            and base.get("cmdline_sha256") == cur.get("cmdline_sha256"))


def cmp_agents(base, cur):
    old, new = base.get("agents") or {}, cur.get("agents") or {}
    return ["%s: %s -> %s" % (u, old.get(u, "inactive"), new.get(u, "inactive"))
            for u in sorted(set(old) | set(new)) if old.get(u) != new.get(u)]


def cmp_collector(base, cur):
    old = set(base.get("errors") or [])
    return ["collector error: %s" % e for e in sorted(set(cur.get("errors") or []) - old)]


COMPARE = {
    "credentials": cmp_credentials, "keys": cmp_keys, "accounts": cmp_accounts, "ssh": cmp_ssh,
    "ssh_auth": cmp_ssh_auth,
    "boot": cmp_boot, "agents": cmp_agents, "collector": cmp_collector,
    "hostkeys": lambda b, c: diff_map(section(b, "files.hostkeys"), section(c, "files.hostkeys")),
    "sudo_pam": lambda b, c: (diff_map(section(b, "files.sudo"), section(c, "files.sudo"))
                              + diff_map(section(b, "files.pam"), section(c, "files.pam"))),
    "persistence": lambda b, c: diff_map(section(b, "files.persistence"), section(c, "files.persistence")),
}


def persistent_findings(base, cur):
    out = {}
    for kind, (priority, _w, _s) in PERSISTENT.items():
        items = COMPARE[kind](base, cur)
        if not items:
            continue
        if kind == "boot" and boot_explained(base, cur):
            priority = 3
        out[kind] = {"priority": priority, "items": items}
    return out


def known_fingerprints(obs, user):
    return {k["fp"] for entry in ((obs.get("authorized_keys") or {}).get(user) or {}).values()
            for k in entry.get("keys", [])}


def event_findings(prev, cur, base, hub_now, prev_seen_at):
    """Events between the previous good observation and this one."""
    ev = []
    if prev is None:
        return ev
    same_boot = cur.get("boot_id") == prev.get("boot_id")
    if not same_boot:
        ev.append(("reboot", 1, "rebooted: boot %s -> %s, up since %s (kernel %s)" % (
            str(prev.get("boot_id"))[:8], str(cur.get("boot_id"))[:8], utc(cur.get("btime")), cur.get("kernel"))))
        if cur.get("btime") and prev_seen_at and cur["btime"] < prev_seen_at - 300:
            ev.append(("inconsistent", 1, "the new boot claims to have started at %s, before the previous boot "
                       "was last seen alive at %s (report may be forged)" % (utc(cur["btime"]), utc(prev_seen_at))))
    elif abs(int(cur.get("btime") or 0) - int(prev.get("btime") or 0)) > 120:
        ev.append(("inconsistent", 2, "boot time moved by %ds on the same boot_id" %
                   (int(cur.get("btime") or 0) - int(prev.get("btime") or 0))))
    skew = float(cur.get("now") or 0) - hub_now
    if abs(skew) > 300:
        ev.append(("inconsistent", 2, "clock differs from this checker by %ds" % skew))
    before = (prev.get("logins") or {}) if same_boot else {}
    now_l = cur.get("logins") or {}
    for user, count in sorted((now_l.get("console") or {}).items()):
        new = count - int((before.get("console") or {}).get(user, 0))
        if new > 0:
            ev.append(("console_login", 1, "console login as %s (%d new; ttys %s)" %
                       (user, new, ", ".join(now_l.get("ttys") or []) or "unknown")))
    failed = int(now_l.get("console_failed", 0)) - int(before.get("console_failed", 0))
    if failed > 0:
        ev.append(("console_login", 2, "%d failed console login attempt(s)" % failed))
    for key, count in sorted((now_l.get("ssh") or {}).items()):
        new = count - int((before.get("ssh") or {}).get(key, 0))
        if new <= 0:
            continue
        user, method, fp = (key.split(" ", 2) + ["", "", ""])[:3]
        if method == "publickey" and fp in known_fingerprints(base, user):
            continue
        ev.append(("ssh_login", 1, "SSH login as %s by %s %s (%d), not a key in the accepted set" % (user, method, fp, new)))
    su = int(now_l.get("su", 0)) - int(before.get("su", 0))
    if su > 0:
        ev.append(("su_sudo", 2, "%d su session(s)" % su))
    for user, count in sorted((now_l.get("sudo") or {}).items()):
        new = count - int((before.get("sudo") or {}).get(user, 0))
        if new > 0:
            ev.append(("su_sudo", 2, "%d sudo command(s) by %s" % (new, user)))
    return ev


def pipeline_conditions(p, now):
    """The hub's alerting pipeline as its report states it (watcher role)."""
    bad = []
    for key, limit, text in (("monitor_ok_at", 300, "security monitor has not completed a run for %s"),
                             ("attest_finished_at", 600, "fleet attestation has not completed a run for %s"),
                             ("watchdog_ok_at", 900, "alert watchdog has not run for %s"),
                             ("mail_ok_at", 26 * 3600, "no alert mail delivered for %s")):
        ts = p.get(key)
        if not ts or now - float(ts) > limit:
            bad.append(text % age(now, ts))
    if p.get("outbox_oldest") and now - float(p["outbox_oldest"]) > 1800:
        bad.append("mail queue stuck for %s (%s message(s))" % (age(now, p["outbox_oldest"]), p.get("outbox_depth")))
    parked = list(p.get("parked") or [])
    if parked:
        bad.append("%d alert mail(s) refused by SMTP (5xx) and parked: %s" % (
            len(parked), ", ".join(re.sub(r"[^A-Za-z0-9-]", "?", str(s))[:24] for s in parked[:10])))
    return bad


def rejected_for_good(exc):
    """A reply the server will give again for THIS message: a 5xx after DATA
    (content refused) or every recipient refused with a 5xx. Connection,
    greeting, authentication and sender failures belong to the account or
    the network and keep blocking the queue until they clear."""
    if isinstance(exc, smtplib.SMTPDataError):
        return 500 <= int(exc.smtp_code) <= 599
    if isinstance(exc, smtplib.SMTPRecipientsRefused):
        codes = [int(code) for code, _ in exc.recipients.values()]
        return bool(codes) and all(500 <= code <= 599 for code in codes)
    return False


ATTEST_OUTPUT_MAX_BYTES = 8 << 20


class AttestOutputTooLarge(Exception):
    pass


def run_attest_bounded(argv, input_text, env, timeout=75):
    """Bound combined stdout and stderr while reading, including SSH children."""
    deadline = time.monotonic() + timeout
    with tempfile.TemporaryFile() as source:
        if input_text is not None:
            source.write(input_text.encode("utf-8"))
            source.seek(0)
        proc = subprocess.Popen(argv, stdin=source, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, env=env, start_new_session=True)
        output = {"stdout": bytearray(), "stderr": bytearray()}
        total = 0
        try:
            with selectors.DefaultSelector() as ready:
                ready.register(proc.stdout, selectors.EVENT_READ, "stdout")
                ready.register(proc.stderr, selectors.EVENT_READ, "stderr")
                while ready.get_map():
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        raise subprocess.TimeoutExpired(argv, timeout)
                    for key, _ in ready.select(remaining):
                        chunk = os.read(key.fd, min(65536, ATTEST_OUTPUT_MAX_BYTES - total + 1))
                        if not chunk:
                            ready.unregister(key.fileobj)
                            continue
                        total += len(chunk)
                        if total > ATTEST_OUTPUT_MAX_BYTES:
                            raise AttestOutputTooLarge()
                        output[key.data].extend(chunk)
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise subprocess.TimeoutExpired(argv, timeout)
                code = proc.wait(timeout=remaining)
            return subprocess.CompletedProcess(argv, code,
                output["stdout"].decode("utf-8", "replace"),
                output["stderr"].decode("utf-8", "replace"))
        finally:
            if proc.returncode is None:
                # Kill the whole session (ssh and any ProxyCommand child) before
                # reaping, while the leader still holds the group id.
                group = proc.pid
                try:
                    os.killpg(group, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                proc.wait(timeout=5)
            proc.stdout.close()
            proc.stderr.close()


# ---------------------------------------------------------------- the checker
class Attest:
    def __init__(self, role, state_dir, env_file, collector=COLLECTOR):
        self.role = role
        self.state = state_dir
        self.env = load_env(env_file)
        self.collector = collector
        self.now = time.time()
        self.alerts = []      # (target, kind, priority, text)
        self.logged = []
        for sub in ("targets", "outbox"):
            os.makedirs(os.path.join(self.state, sub), mode=0o700, exist_ok=True)

    # ------------------------------------------------------------ state
    def target_path(self, name):
        if not NAME_RE.match(name):
            raise ValueError("bad target name")
        return os.path.join(self.state, "targets", name + ".json")

    def load_target(self, name):
        try:
            return read_json(self.target_path(name), None)
        except ValueError:
            self.alert(name, "state", 1, "checker state for this target was unreadable; a new baseline is recorded")
            return None

    def save_target(self, name, st):
        write_json(self.target_path(name), st)

    def alert(self, target, kind, priority, text):
        # Report fields are data from a host that may be compromised: one
        # printable line each, bounded, before they reach a log or a mail.
        text = re.sub(r"[^ -~]", "?", str(text))[:2000]
        rec = {"ts": self.now, "target": target, "kind": kind, "priority": priority, "text": text}
        (self.alerts if priority <= 2 else self.logged).append(rec)

    # ------------------------------------------------------------ targets
    def targets(self):
        if self.role == "watcher":
            host = self.env.get("HUB_WATCH_SSH_HOST", "")
            return [{"name": "hub", "host": host, "user": self.env.get("HUB_WATCH_SSH_USER", "root"),
                     "port": self.env.get("HUB_WATCH_SSH_PORT", "22"), "access": False, "forced": True,
                     "key": "/etc/winsvpn/hub-watch_ed25519", "known_hosts": "/etc/winsvpn/hub-watch.known_hosts"}]
        out = [{"name": "hub", "local": True}]
        db = self.env.get("DATABASE_PATH") or "/root/vpn_auth/vpn_users.db"
        kh = self.env.get("MANAGEMENT_KNOWN_HOSTS_PATH") or os.path.join(os.path.dirname(db), "managed_known_hosts")
        try:
            conn = sqlite3.connect("file:%s?mode=ro" % db, uri=True, timeout=10)
            try:
                rows = conn.execute("SELECT slug, ssh_host, last_heartbeat, retired_at FROM nodes").fetchall()
            finally:
                conn.close()
        except sqlite3.Error as exc:
            self.alert("hub", "pipeline", 1, "node list unreadable (%s); nodes were not checked" % type(exc).__name__)
            rows = []
        for slug, host, heartbeat, retired in rows:
            slug = str(slug or "").strip().lower()
            if retired or not NAME_RE.match(slug) or slug == "hub":
                continue
            out.append({"name": slug, "host": str(host or "").strip().lower(), "user": "root", "port": "22",
                        "access": True, "heartbeat": heartbeat, "key": "/root/.ssh/id_rsa", "known_hosts": kh})
        try:
            extra = open("/etc/winsvpn/attest-targets", encoding="utf-8").read().splitlines()
        except OSError:
            extra = []
        for line in extra:
            parts = line.split()
            if len(parts) >= 4 and not line.startswith("#") and NAME_RE.match(parts[0]):
                out.append({"name": parts[0], "host": parts[1], "user": parts[2], "port": parts[3],
                            "access": len(parts) > 4 and parts[4] == "access", "key": "/root/.ssh/id_rsa",
                            "known_hosts": "/etc/winsvpn/attest-known_hosts"})
        return out

    def ssh_argv(self, t, remote):
        host = t["host"]
        try:
            ipaddress.ip_address(host)
            literal = True
        except ValueError:
            literal = False
        if not host or not re.fullmatch(r"[a-z0-9.:-]{1,253}", host):
            raise LookupError("no management host is recorded")
        if t.get("access") and literal and self.env.get("HIDE_CONTROL_ORIGIN", "1") != "0":
            raise LookupError("direct-IP management is disabled while the control origin is hidden")
        pinned = False
        names = {host} if str(t["port"]) == "22" else {"[%s]:%s" % (host, t["port"])}
        try:
            st = os.stat(t["known_hosts"])
            if not st.st_mode & 0o077:
                pinned = any(set(line.split(None, 1)[0].split(",")) & names
                             for line in open(t["known_hosts"], encoding="utf-8")
                             if line.strip() and not line.startswith("#"))
        except OSError:
            pass
        if not pinned:
            raise LookupError("no pinned SSH host key for this target")
        argv = ["ssh", "-i", t["key"], "-p", str(t["port"]), "-o", "BatchMode=yes", "-o", "ConnectTimeout=15",
                "-o", "ConnectionAttempts=1", "-o", "StrictHostKeyChecking=yes",
                "-o", "UserKnownHostsFile=" + t["known_hosts"], "-o", "GlobalKnownHostsFile=/dev/null",
                "-o", "UpdateHostKeys=no", "-o", "ServerAliveInterval=10", "-o", "ServerAliveCountMax=3",
                "-o", "IdentitiesOnly=yes", "-o", "LogLevel=ERROR", "-o", "RequestTTY=no"]
        if t.get("access") and not literal:
            argv += ["-o", "ProxyCommand=/usr/bin/cloudflared access ssh --hostname %h"]
        return argv + ["%s@%s" % (t["user"], host), remote]

    def collect(self, t):
        """(observation, failure) for one target; failure is (kind, reason)."""
        nonce = secrets.token_hex(16)
        env = {"PATH": SAFE_PATH, "LC_ALL": "C", "HOME": "/root"}
        try:
            if t.get("local"):
                argv, stdin = [PYTHON, "-I", self.collector, nonce], None
            elif t.get("forced"):
                argv, stdin = self.ssh_argv(t, nonce), None
            else:
                argv = self.ssh_argv(t, "python3 -I - " + nonce)
                stdin = open(self.collector, encoding="utf-8").read()
                for key in ("TUNNEL_SERVICE_TOKEN_ID", "TUNNEL_SERVICE_TOKEN_SECRET"):
                    if self.env.get(key):
                        env[key] = self.env[key]
        except LookupError as exc:
            return None, ("unmanaged", str(exc))
        try:
            done = run_attest_bounded(argv, stdin, env)
        except AttestOutputTooLarge:
            return None, ("unreachable", "report output exceeds limit")
        except subprocess.TimeoutExpired:
            return None, ("unreachable", "timed out")
        except OSError as exc:
            return None, ("unreachable", type(exc).__name__)
        if done.returncode != 0:
            err = done.stderr
            # Only a classification leaves this function: ssh's stderr can
            # name addresses and is never mailed.
            if "Host key verification failed" in err or "IDENTIFICATION HAS CHANGED" in err:
                return None, ("hostkey_mismatch", "the SSH host key no longer matches the pinned key")
            if "Permission denied" in err:
                return None, ("unreachable", "the checker key was refused")
            return None, ("unreachable", "exit %d" % done.returncode)
        try:
            obs = json.loads(done.stdout)
        except ValueError:
            return None, ("unreachable", "unparsable report")
        if not isinstance(obs, dict) or obs.get("v") != 1:
            return None, ("unreachable", "unparsable report")
        if obs.get("nonce") != nonce:
            obs["_nonce_mismatch"] = True
        return obs, None

    # ------------------------------------------------------------ evaluation
    def window_active(self, st, kind):
        w = st.get("window")
        return bool(w and self.now < w["until"] and kind in w["kinds"])

    def note(self, name, st, kind, priority, text):
        """An event: mailed (P1/P2) unless covered by an active window."""
        if priority <= 2 and self.window_active(st, kind):
            priority = 3
            text += " (inside the maintenance window: %s)" % st["window"]["reason"]
        self.alert(name, kind, priority, text)

    def condition(self, name, st, kind, priority, items, basis):
        """Open, keep or re-mail a condition finding; basis is its stable key."""
        key = hashlib.sha256(json.dumps([kind, basis], sort_keys=True).encode()).hexdigest()[:16]
        cur = st["open"].get(kind)
        in_window = self.window_active(st, kind)
        # An acknowledged condition (a node known to be down) stays logged
        # until it changes or clears; the ack itself was mailed.
        acked = st.get("acked", {}).get(kind) == key
        mail_p = 3 if in_window or acked else priority
        if cur is None or cur["key"] != key:
            st["open"][kind] = {"key": key, "priority": priority, "items": items,
                                "first": cur["first"] if cur else self.now,
                                "last_sent": self.now if mail_p <= 2 else 0}
            self.alert(name, kind, mail_p, "; ".join(items))
            return
        cur["items"], cur["priority"] = items, priority
        if mail_p <= 2 and self.now - (cur.get("last_sent") or 0) >= REALERT[mail_p]:
            cur["last_sent"] = self.now
            self.alert(name, kind, mail_p, "STILL OPEN since %s: %s" % (utc(cur["first"]), "; ".join(items)))

    def close(self, name, st, kinds, recovered_text=None):
        for kind in kinds:
            st.setdefault("acked", {}).pop(kind, None)
            cur = st["open"].pop(kind, None)
            if cur is None:
                continue
            if recovered_text and cur["priority"] <= 2:
                self.note(name, st, "recovered", 2, recovered_text % age(self.now, st.get("last_seen_at") or cur["first"]))
            else:
                self.alert(name, kind, 3, "resolved: " + "; ".join(cur["items"][:5]))

    def evaluate(self, t, obs, failure):
        name = t["name"]
        st = self.load_target(name) or {"open": {}}
        st.setdefault("open", {})
        self.close_window_if_expired(name, st)
        if t.get("heartbeat") is not None:
            self.check_heartbeat(name, st, t["heartbeat"], reachable=failure is None)
        if failure:
            kind, reason = failure
            if kind == "unreachable":
                st["fail_streak"] = st.get("fail_streak", 0) + 1
                # Two misses (2 to 4 min dark) are already worth a P2: a rescue
                # boot that rewrites a disk and reboots takes minutes, and a
                # forged report afterwards cannot hide the gap. Five misses
                # (about 10 min) escalate to P1. Recovery is mailed too.
                if st["fail_streak"] >= 2:
                    pri = 1 if st["fail_streak"] >= 5 else 2
                    self.condition(name, st, "unreachable", pri,
                                   ["off-host check failed %d times in a row (%s); last good check %s"
                                    % (st["fail_streak"], reason, utc(st.get("last_seen_at")))], "down-p%d" % pri)
            else:
                self.condition(name, st, kind, 1 if kind == "hostkey_mismatch" else 2, [reason], reason)
            st["checked_at"] = self.now
            self.save_target(name, st)
            return st
        st["fail_streak"] = 0
        self.close(name, st, ["unreachable"], "reachable again; the outage lasted about %s")
        self.close(name, st, ["hostkey_mismatch", "unmanaged"])
        # A rescue, single-user or init-replacing command line is P1 for as long
        # as that boot lasts, keyed on the boot, never covered by a window.
        if obs.get("rescue"):
            self.condition(name, st, "rescue_boot", 1, ["running a boot whose kernel command line carries rescue or "
                           "single-user markers: %s" % ", ".join(map(str, obs["rescue"]))], [obs.get("boot_id"), obs["rescue"]])
        else:
            self.close(name, st, ["rescue_boot"])
        if obs.pop("_nonce_mismatch", False):
            self.note(name, st, "inconsistent", 1, "the report did not echo this run's nonce (replayed or forged)")
        if self.role == "watcher" or name == "hub":
            pipe = obs.pop("pipeline", None)
            if self.role == "watcher":
                bad = pipeline_conditions(pipe or {}, self.now)
                if bad:
                    self.condition(name, st, "pipeline", 1, bad, sorted(b.split(" for ")[0] for b in bad))
                else:
                    self.close(name, st, ["pipeline"])
        if "baseline" not in st:
            st["baseline"], st["last"], st["last_seen_at"] = obs, obs, self.now
            keys = sum(len(e.get("keys", [])) for f in (obs.get("authorized_keys") or {}).values() for e in f.values())
            usable = [r["name"] for r in obs.get("accounts") or [] if r["pw"] != "locked"]
            self.alert(name, "baseline", 2, "baseline recorded: %d accounts (with a usable or empty password: %s), "
                       "%d authorized key(s), boot %s, kernel %s, active agents: %s" % (
                           len(obs.get("accounts") or []), ", ".join(usable) or "none", keys,
                           str(obs.get("boot_id"))[:8], obs.get("kernel"), ", ".join(sorted(obs.get("agents") or {})) or "none"))
            st["checked_at"] = self.now
            self.save_target(name, st)
            return st
        for kind, pri, text in event_findings(st.get("last"), obs, st["baseline"], self.now, st.get("last_seen_at")):
            self.note(name, st, kind, pri, text)
        found = persistent_findings(st["baseline"], obs)
        boot = found.get("boot")
        if boot and boot["priority"] == 3:
            # An explained boot change (package update, not yet booted) is
            # taken into the baseline at once, so a later unexplained change
            # can never hide behind an old explanation.
            for sec in PERSISTENT["boot"][2]:
                set_section(st["baseline"], sec, section(obs, sec))
            self.alert(name, "boot", 3, "boot files changed with a package update (accepted): " + "; ".join(boot["items"][:20]))
            found.pop("boot")
        for kind in PERSISTENT:
            if kind in found:
                f = found[kind]
                self.condition(name, st, kind, f["priority"], f["items"], f["items"])
            elif kind in st["open"]:
                self.close(name, st, [kind])
        st["last"], st["last_seen_at"], st["checked_at"] = obs, self.now, self.now
        self.save_target(name, st)
        return st

    def check_heartbeat(self, name, st, heartbeat, reachable=False):
        limit = int(self.env.get("NODE_HEARTBEAT_STALE_SECONDS") or 600)
        try:
            hb = datetime.fromisoformat(str(heartbeat).replace("Z", "+00:00"))
            if hb.tzinfo is None:
                hb = hb.replace(tzinfo=timezone.utc)
            hb_ts = hb.timestamp()
        except ValueError:
            return
        if self.now - hb_ts > limit:
            # Turn 2 (from the kimi seat): a node that still answers this
            # check but stopped heartbeating had its agent stopped or its
            # registration refused: a tamper hypothesis, P1. A node that is
            # dark both ways is already reported as unreachable.
            if reachable:
                self.condition(name, st, "heartbeat", 1, ["no heartbeat since %s (%s) although the off-host check still "
                               "reaches it: its heartbeat agent was stopped or its registration is refused"
                               % (utc(hb_ts), age(self.now, hb_ts))], "stale-reachable")
            else:
                self.condition(name, st, "heartbeat", 2, ["no heartbeat since %s (%s)" % (utc(hb_ts), age(self.now, hb_ts))], "stale")
        else:
            self.close(name, st, ["heartbeat"])

    def close_window_if_expired(self, name, st):
        w = st.get("window")
        if not w or self.now < w["until"]:
            return
        st.pop("window")
        blocking = [k for k, v in st.get("open", {}).items() if k not in WINDOWABLE and v["priority"] <= 2]
        if blocking:
            self.alert(name, "window", 2, "maintenance window (%s) closed; the baseline was NOT advanced because "
                       "these findings need an explicit ack: %s" % (w["reason"], ", ".join(sorted(blocking))))
            return
        accepted = []
        for kind in w["kinds"]:
            if kind in PERSISTENT and kind in st["open"]:
                accepted.append("%s: %s" % (kind, "; ".join(st["open"].pop(kind)["items"][:20])))
                for sec in PERSISTENT[kind][2]:
                    set_section(st["baseline"], sec, section(st.get("last") or {}, sec))
        self.alert(name, "window", 2 if accepted else 3, "maintenance window (%s) closed; accepted into the baseline: %s"
                   % (w["reason"], " | ".join(accepted) or "no changes"))

    # ------------------------------------------------------------ pipeline
    def pipeline(self):
        """This host's own alerting pipeline (hub role)."""
        out = {"monitor_ok_at": None, "attest_finished_at": None, "watchdog_ok_at": None}
        for key, path in (("monitor_ok_at", "/var/lib/wins-security-alerts/monitor.ok"),
                          ("attest_finished_at", os.path.join(self.state, "status.json")),
                          ("watchdog_ok_at", os.path.join(self.state, "watchdog.ok"))):
            try:
                out[key] = os.stat(path).st_mtime
            except OSError:
                pass
        mail = read_json(os.path.join(self.state, "mail.json"), {}) or {}
        out["mail_ok_at"] = mail.get("ok_at")
        box = self.outbox()
        out["outbox_depth"] = len(box)
        out["outbox_oldest"] = min((os.stat(p).st_mtime for p in box), default=None)
        out["parked"] = ["%s-%d" % (self.role, int(i["seq"])) for i in (read_json(p, {}) or {} for p in box) if i.get("parked")]
        return out

    # ------------------------------------------------------------ mail
    def outbox(self):
        d = os.path.join(self.state, "outbox")
        return sorted(os.path.join(d, f) for f in os.listdir(d) if f.endswith(".json"))

    def queue_alerts(self, header="Tamper"):
        if not self.alerts:
            return
        top = min(a["priority"] for a in self.alerts)
        shown = self.alerts[:50]
        summary = "; ".join("%s %s" % (a["target"], a["kind"]) for a in shown)
        subject = "[Wins VPN %s P%d] %d alert(s): %s" % (header, top, len(self.alerts), summary)
        lines = ["Win's VPN %s alerts from the %s checker, %s" % (header.lower(), self.role, utc(self.now)), ""]
        for a in shown:
            lines.append("P%d %-12s %-16s %s" % (a["priority"], a["target"], a["kind"], a["text"]))
        if len(self.alerts) > len(shown):
            lines.append("... and %d more (wins-fleet-attest status)" % (len(self.alerts) - len(shown)))
        lines += ["", "Accept a legitimate change: wins-fleet-attest --role %s ack <target> --reason '<why>'" % self.role,
                  "Before planned work:       wins-fleet-attest --role %s window <target> --minutes N --kinds reboot,boot --reason '<why>'" % self.role]
        self.queue(subject[:200], "\n".join(lines) + "\n")
        self.alerts = []

    def queue(self, subject, body, **extra):
        seq = self.next_seq()
        write_json(os.path.join(self.state, "outbox", "%013d-%06d.json" % (int(self.now * 1000), seq)),
                   {"subject": subject, "body": body, "seq": seq, "created": self.now, **extra})

    def next_seq(self):
        path = os.path.join(self.state, "seq.json")
        seq = int((read_json(path, {}) or {}).get("seq", 0)) + 1
        write_json(path, {"seq": seq})
        return seq

    def smtp_send(self, msg):
        host = self.env.get("SMTP_SERVER") or "mail.smtp2go.com"
        port = int(self.env.get("SMTP_PORT") or "2525")
        ctx = ssl.create_default_context()
        if port == 465:
            server = smtplib.SMTP_SSL(host, port, timeout=20, context=ctx)
        else:
            server = smtplib.SMTP(host, port, timeout=20)
        with server:
            if port != 465:
                server.ehlo()
                server.starttls(context=ctx)
                server.ehlo()
            server.login(self.env["SMTP_USER"], self.env["SMTP_PASS"])
            server.send_message(msg)

    def flush(self, limit=5):
        """Send queued mail oldest first; a failure keeps it for the next run.

        A message the server refuses for good (rejected_for_good: a 5xx for
        this one message) is never deleted unsent and keeps holding the newer
        messages until one of them is delivered after its refusal, in the same
        or a later run. That delivery proves the refusal is about the message,
        not the account or the server, and the message is then parked: it
        stays in the outbox (still counted by outbox_oldest), no longer holds
        the queue, is tried every run until it has been refused three times
        and every 6 h after that, and is reported once by a fixed-text notice,
        then by the daily digest and to the watcher until it is delivered or
        removed. Until that proof a run tries the oldest unparked message and
        at most one message never refused before, so a channel that refuses
        everything costs at most two refused sends a run and keeps the whole
        queue. A 4xx, a connection, login or sender failure, or a refused
        notice holds the queue as before; a notice is never parked."""
        status_path = os.path.join(self.state, "mail.json")
        status = read_json(status_path, {}) or {}
        sent_times = [t for t in status.get("sent_times", []) if self.now - t < 3600]
        sender = self.env.get("EMAIL_SENDER") or "support@winsvpn.org"
        to = self.env.get("SECURITY_ALERT_EMAIL") or "security@winsvpn.com"
        sent = tried = 0
        held = []       # refused for good, not parked: parked once a newer message is delivered
        probing = False
        for path in self.outbox():
            if sent >= limit or tried >= limit or len(sent_times) >= int(self.env.get("ATTEST_MAIL_PER_HOUR") or 20):
                break
            if not (self.env.get("SMTP_USER") and self.env.get("SMTP_PASS")):
                status.update(error="SMTP is not configured", error_at=self.now)
                break
            item = read_json(path, None)
            if item.get("parked"):
                if int(item.get("rejected", 0)) >= 3 and self.now - float(item.get("tried_at") or 0) < 6 * 3600:
                    continue
            elif probing and item.get("rejected"):
                held.append(path)       # refused in an earlier run; this run's probe decides for it too
                continue
            tried += 1
            msg = EmailMessage()
            msg["Subject"] = item["subject"]
            msg["From"] = sender
            msg["To"] = to
            msg["Date"] = formatdate(item["created"], usegmt=True)
            msg["Message-ID"] = make_msgid(domain=sender.rsplit("@", 1)[-1])
            msg["Auto-Submitted"] = "auto-generated"
            msg["X-Wins-Alert-Seq"] = "%s-%d" % (self.role, item["seq"])
            msg.set_content(item["body"] + "\n(sequence %s-%d; a gap in this number means a lost alert)\n" % (self.role, item["seq"]))
            try:
                self.smtp_send(msg)
            except (OSError, smtplib.SMTPException) as exc:
                status.update(error=type(exc).__name__, error_at=self.now)
                if not rejected_for_good(exc) or item.get("dead_letter_notice"):
                    break
                item.update(rejected=int(item.get("rejected", 0)) + 1, tried_at=self.now,
                            error=re.sub(r"[^ -~]", "?", "%s: %s" % (type(exc).__name__, exc))[:200])
                self.keep(path, item)
                if item.get("parked"):
                    continue
                held.append(path)
                if probing:
                    break               # the probe was refused too: no proof, the queue stays held
                probing = True
                continue
            os.unlink(path)
            sent += 1
            sent_times.append(self.now)
            status.update(ok_at=self.now, last_seq=item["seq"])
            for older in held:          # a newer message went through after their refusal
                self.park(older)
            held, probing = [], False
        status["sent_times"] = sent_times
        write_json(status_path, status)
        return sent

    def keep(self, path, item):
        """Rewrite a kept outbox entry without moving its age, so outbox_oldest
        and the stuck-queue alarms keep counting from when it was queued."""
        st = os.stat(path)
        write_json(path, item)
        os.utime(path, ns=(st.st_atime_ns, st.st_mtime_ns))

    def park(self, path):
        item = read_json(path, None)
        item.update(parked=True, parked_at=self.now)
        self.keep(path, item)
        # Fixed text: the sequence number and the reply class only, never the
        # refused message's subject or body (a node may have chosen them).
        self.queue("[Wins VPN Alerting P1] alert mail %s-%d was refused by SMTP (5xx) and parked" % (self.role, int(item["seq"])),
                   "SMTP refused alert message %s-%d with a permanent 5xx reply, and a newer message was delivered "
                   "after it, so the refusal is about that one message. It stays in %s on the %s checker, is tried "
                   "again (every 6 h after three refusals) and no longer holds newer alerts back. Read it there as "
                   "root and remove it once handled; until then the daily digest and the watcher report it and the "
                   "queue counts as stuck.\n" % (self.role, int(item["seq"]), os.path.dirname(path), self.role),
                   dead_letter_notice=True)

    # ------------------------------------------------------------ commands
    def log(self):
        path = os.path.join(self.state, "log.jsonl")
        if os.path.exists(path) and os.path.getsize(path) > (4 << 20):
            lines = open(path, encoding="utf-8").read().splitlines()[-10000:]
            with open(path, "w", encoding="utf-8") as handle:
                handle.write("\n".join(lines) + "\n")
        with open(path, "a", encoding="utf-8") as handle:
            for rec in self.alerts + self.logged:
                handle.write(json.dumps(rec, sort_keys=True) + "\n")

    def cmd_run(self):
        targets = self.targets()
        # All targets at once: each call is bounded at 75 s, inside the unit's
        # 110 s start timeout, however many nodes there are.
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(32, max(1, len(targets)))) as pool:
            results = list(pool.map(lambda t: (t, *self.collect(t)), targets))
        for t, obs, failure in results:
            try:
                self.evaluate(t, obs, failure)
            except Exception as exc:  # one hostile or broken report never stops the others
                self.alert(t["name"], "inconsistent", 1, "the report could not be evaluated (%s); treat this target "
                           "as untrusted until it is checked by hand" % type(exc).__name__)
        if self.role == "hub":
            self.check_own_pipeline()
        self.log()
        self.queue_alerts()
        self.flush()
        write_json(os.path.join(self.state, "status.json"), {"finished_at": self.now, "targets": [t["name"] for t in targets]})

    def check_own_pipeline(self):
        st = self.load_target("hub") or {"open": {}}
        if "baseline" not in st:
            return
        st.setdefault("open", {})
        p = self.pipeline()
        bad = []
        if not p["monitor_ok_at"] or self.now - p["monitor_ok_at"] > 300:
            bad.append("security monitor has not completed a run for %s" % age(self.now, p["monitor_ok_at"]))
        if not p["watchdog_ok_at"] or self.now - p["watchdog_ok_at"] > 900:
            bad.append("alert watchdog has not run for %s" % age(self.now, p["watchdog_ok_at"]))
        if bad:
            self.condition("hub", st, "pipeline", 1, bad, sorted(b.split(" has ")[0] for b in bad))
        else:
            self.close("hub", st, ["pipeline"])
        self.save_target("hub", st)

    def cmd_watchdog(self):
        """Every 5 min and OnFailure of the monitor and attest units."""
        p = self.pipeline()
        bad, restart = [], []
        checks = [("attest_finished_at", 600, TIMER[self.role], "fleet attestation")]
        if self.role == "hub":
            checks.insert(0, ("monitor_ok_at", 300, "wins-security-alert-monitor.timer", "security monitor"))
        for key, limit, timer, label in checks:
            state = subprocess.run(["systemctl", "is-active", timer], capture_output=True, text=True).stdout.strip()
            if state != "active":
                bad.append("%s timer is %s" % (label, state or "unknown"))
                restart.append(timer)
            elif not p[key] or self.now - p[key] > limit:
                bad.append("%s has not completed a run for %s" % (label, age(self.now, p[key])))
        if p["outbox_oldest"] and self.now - p["outbox_oldest"] > 1800:
            bad.append("mail queue stuck for %s (%d message(s))" % (age(self.now, p["outbox_oldest"]), p["outbox_depth"]))
        wd = read_json(os.path.join(self.state, "watchdog.json"), {}) or {}
        for timer in restart:
            if self.now - wd.get("restarted", {}).get(timer, 0) > 3600:
                subprocess.run(["systemctl", "restart", timer], capture_output=True)
                wd.setdefault("restarted", {})[timer] = self.now
                bad.append("restarted %s" % timer)
        key = "|".join(sorted(b.split(" for ")[0] for b in bad))
        if bad and (key != wd.get("key") or self.now - wd.get("sent", 0) >= 3600):
            self.alert("pipeline", "pipeline", 1, "; ".join(bad))
            wd.update(key=key, sent=self.now)
        elif not bad:
            wd.update(key="", sent=0)
        write_json(os.path.join(self.state, "watchdog.json"), wd)
        self.log()
        self.queue_alerts("Alerting")
        self.flush()
        with open(os.path.join(self.state, "watchdog.ok"), "w") as handle:
            handle.write(str(self.now))

    def cmd_digest(self):
        p = self.pipeline()
        lines, open_count = [], 0
        for f in sorted(os.listdir(os.path.join(self.state, "targets"))):
            st = read_json(os.path.join(self.state, "targets", f), {}) or {}
            last = st.get("last") or {}
            opens = st.get("open") or {}
            open_count += sum(1 for v in opens.values() if v["priority"] <= 2)
            lines.append("  %-14s %s; checked %s; boot %s up %.1fd%s" % (
                f[:-5], "OPEN" if opens else "ok", ago(self.now, st.get("checked_at")),
                str(last.get("boot_id"))[:8], float(last.get("uptime") or 0) / 86400,
                "; window until %s" % utc(st["window"]["until"]) if st.get("window") else ""))
            for kind, v in sorted(opens.items()):
                lines.append("      P%d %s since %s: %s" % (v["priority"], kind, utc(v["first"]), "; ".join(v["items"][:6])))
        day = []
        try:
            for raw in open(os.path.join(self.state, "log.jsonl"), encoding="utf-8"):
                rec = json.loads(raw)
                if self.now - rec["ts"] < 86400:
                    day.append(rec)
        except OSError:
            pass
        head = "ALL CLEAR" if open_count == 0 else "%d OPEN FINDING(S)" % open_count
        pipe = "Alerting pipeline: attestation run %s, watchdog %s, last mail delivered %s, queue %d" % (
            ago(self.now, p["attest_finished_at"]), ago(self.now, p["watchdog_ok_at"]),
            ago(self.now, p["mail_ok_at"]), p["outbox_depth"])
        if self.role == "hub":
            pipe += ", security monitor run %s" % ago(self.now, p["monitor_ok_at"])
        if p["parked"]:
            pipe += "; PARKED after a permanent SMTP refusal (5xx): %s" % ", ".join(p["parked"])
        body = ["Win's VPN daily security digest (%s checker), %s" % (self.role, utc(self.now)), "", "Overall: " + head, "",
                pipe, "", "Targets:"] + lines + ["", "Last 24 h: %d mailed alert(s), %d logged-only entries." % (
                    sum(1 for r in day if r["priority"] <= 2), sum(1 for r in day if r["priority"] > 2))]
        body += ["  %s P%d %s %s: %s" % (utc(r["ts"]), r["priority"], r["target"], r["kind"], r["text"][:160])
                 for r in day if r["priority"] > 2][-30:]
        body += ["", "This mail arrives every day. If it stops, the alerting path itself is down."]
        self.queue("[Wins VPN Digest] %s (%s)" % (head, self.role), "\n".join(body) + "\n")
        self.flush()

    def cmd_hub_report(self):
        nonce = os.environ.get("SSH_ORIGINAL_COMMAND", "").strip()
        if not NONCE_RE.match(nonce):
            sys.stderr.write("refused\n")
            return 2
        done = subprocess.run([PYTHON, "-I", self.collector, nonce], capture_output=True, text=True, timeout=90)
        obs = json.loads(done.stdout)
        obs["pipeline"] = self.pipeline()
        sys.stdout.write(json.dumps(obs, sort_keys=True, separators=(",", ":")) + "\n")
        return 0

    def cmd_ack(self, name, reason, kinds):
        t = next((x for x in self.targets() if x["name"] == name), None)
        if t is None:
            raise SystemExit("unknown target %s" % name)
        st = self.load_target(name) or {"open": {}}
        st.setdefault("open", {})
        kinds = kinds or sorted(set(PERSISTENT) | set(CONDITIONS))
        conds = [k for k in kinds if k in CONDITIONS and k in st["open"]]
        for k in conds:
            st.setdefault("acked", {})[k] = st["open"][k]["key"]
        if conds:
            self.alert(name, "ack", 2, "operator acknowledged (%s): %s; mail for it resumes if it changes, and it "
                       "clears when the target is seen healthy" % (reason, ", ".join(conds)))
        if any(k in PERSISTENT for k in kinds):
            obs, failure = self.collect(t)
            if failure:
                raise SystemExit("cannot ack: %s (%s)" % failure)
            obs.pop("pipeline", None)
            obs.pop("_nonce_mismatch", None)
            base = st.get("baseline") or obs
            before = persistent_findings(base, obs)
            for kind in kinds:
                for sec in PERSISTENT.get(kind, (0, 0, ()))[2]:
                    set_section(base, sec, section(obs, sec))
            after = persistent_findings(base, obs)
            accepted = ["%s: %s" % (k, "; ".join(v["items"][:20])) for k, v in before.items() if k not in after]
            for k in kinds:
                if k in PERSISTENT:
                    st["open"].pop(k, None)
            st.update(baseline=base, last=obs, last_seen_at=self.now)
            self.alert(name, "ack", 2, "operator accepted the current state (%s); accepted: %s" % (reason, " | ".join(accepted) or "no differences"))
        self.save_target(name, st)
        self.log()
        self.queue_alerts()
        self.flush()

    def cmd_window(self, name, minutes, kinds, reason, close):
        names = [t["name"] for t in self.targets()] if name == "all" else [name]
        for n in names:
            st = self.load_target(n) or {"open": {}}
            if close:
                if st.get("window"):
                    st["window"]["until"] = self.now
                    self.alert(n, "window", 2, "maintenance window closed early by the operator")
            else:
                st["window"] = {"until": self.now + minutes * 60, "kinds": kinds, "reason": reason, "opened": self.now}
            self.save_target(n, st)
        if not close:
            self.alert(name, "window", 2, "maintenance window opened for %d min (%s): %s; credentials, keys, host keys, "
                       "sshd authentication settings, console logins and unknown-key logins still alert"
                       % (minutes, reason, ", ".join(kinds)))
        self.log()
        self.queue_alerts()
        self.flush()


def main(argv):
    ap = argparse.ArgumentParser(prog="wins-fleet-attest")
    ap.add_argument("--role", choices=("hub", "watcher"), required=True)
    sub = ap.add_subparsers(dest="cmd", required=True)
    for c in ("run", "watchdog", "digest", "status", "hub-report"):
        sub.add_parser(c)
    a = sub.add_parser("ack")
    a.add_argument("target")
    a.add_argument("--reason", required=True)
    a.add_argument("--kinds", default="")
    w = sub.add_parser("window")
    w.add_argument("target")
    w.add_argument("--minutes", type=int, default=0)
    w.add_argument("--kinds", default="")
    w.add_argument("--reason", default="")
    w.add_argument("--close", action="store_true")
    args = ap.parse_args(argv[1:])
    # Arguments are checked before the root gate and before any state
    # directory exists, so a bad kind is refused by name whoever runs this.
    kinds = [k for k in getattr(args, "kinds", "").split(",") if k]
    reason = re.sub(r"[^ -~]", "", getattr(args, "reason", ""))[:200]
    if args.cmd in ("ack", "window") and not (args.target == "all" or NAME_RE.match(args.target)):
        raise SystemExit("bad target name")
    if args.cmd == "ack" and (not reason or set(kinds) - set(PERSISTENT) - set(CONDITIONS)):
        raise SystemExit("ack needs --reason and known kinds")
    if args.cmd == "window" and not args.close:
        bad = set(kinds) - WINDOWABLE
        if not kinds or bad or not reason or not 1 <= args.minutes <= WINDOW_MAX_MINUTES:
            raise SystemExit("window needs --minutes 1..%d, --reason and kinds from: %s%s" % (
                WINDOW_MAX_MINUTES, ", ".join(sorted(WINDOWABLE)), (" (never windowable: %s)" % ", ".join(sorted(bad))) if bad else ""))
    if os.geteuid() != 0:
        raise SystemExit("wins-fleet-attest runs as root only")
    hub = args.role == "hub"
    app = Attest(args.role, "/var/lib/wins-fleet-attest" if hub else "/var/lib/wins-hub-watch",
                 "/root/vpn_auth.env" if hub else "/etc/winsvpn/hub-watch.env")
    if args.cmd == "hub-report":
        return app.cmd_hub_report()
    if args.cmd == "status":
        for f in sorted(os.listdir(os.path.join(app.state, "targets"))):
            st = read_json(os.path.join(app.state, "targets", f), {}) or {}
            print("%-14s checked %s; open: %s" % (f[:-5], ago(app.now, st.get("checked_at")),
                                                      ", ".join("P%d %s" % (v["priority"], k) for k, v in sorted((st.get("open") or {}).items())) or "none"))
        return 0
    lock = open(os.path.join(app.state, ".lock"), "w")
    deadline = time.time() + 100
    while True:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            break
        except BlockingIOError:
            if time.time() > deadline:
                raise SystemExit("another wins-fleet-attest run holds the lock")
            time.sleep(1)
    app.now = time.time()
    if args.cmd == "run":
        app.cmd_run()
    elif args.cmd == "watchdog":
        app.cmd_watchdog()
    elif args.cmd == "digest":
        app.cmd_digest()
    elif args.cmd == "ack":
        app.cmd_ack(args.target, reason, kinds)
    elif args.cmd == "window":
        app.cmd_window(args.target, args.minutes, kinds, reason, args.close)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
