run_prepublication_gateway_canary() {
  local attempts="${PUBLIC_CANARY_ATTEMPTS:-6}"
  local interval="${PUBLIC_CANARY_INTERVAL_SECONDS:-10}"
  local canary_bin="${WINS_GATEWAY_CANARY_BIN:-/usr/local/bin/wins-gateway-canary}"
  local attempt
  [[ "${canary_bin}" == "/usr/local/bin/wins-gateway-canary" ]] || {
    err "Prepublication canary must use the reviewed sandboxed gateway canary."
    return 1
  }
  [[ "${attempts}" =~ ^[1-9][0-9]*$ && "${attempts}" -le 30 ]] || {
    err "PUBLIC_CANARY_ATTEMPTS must be an integer from 1 through 30."
    return 1
  }
  [[ "${interval}" =~ ^[0-9]+$ && "${interval}" -le 300 ]] || {
    err "PUBLIC_CANARY_INTERVAL_SECONDS must be an integer from 0 through 300."
    return 1
  }
  log "Validating public hub and every advertised backup route before publishing the active-gateway pointer"
  for attempt in $(seq 1 "${attempts}"); do
    if systemctl start wins-gateway-canary-prepublication.service; then
      log "Prepublication public gateway canary passed"
      return 0
    fi
    if [[ "${attempt}" -lt "${attempts}" ]]; then
      warn "Public canary attempt ${attempt}/${attempts} failed; retrying after DNS/tunnel convergence"
      sleep "${interval}"
    fi
  done
  err "Public gateway canary failed. The active-gateway pointer was not published."
  return 1
}

write_backup_helper() {
