set -Eeuo pipefail
mkdir -p /root/.config/rclone
cat > /root/.config/rclone/rclone.conf
chmod 600 /root/.config/rclone/rclone.conf
echo "rclone config written to /root/.config/rclone/rclone.conf"
EOF
