}

write_embedded_rclone_config() {
  if [[ "${INSTALL_EMBEDDED_RCLONE_CONFIG:-0}" == "1" ]]; then
    warn "Embedded rclone credentials are disabled. Install /root/.config/rclone/rclone.conf from an external secret store."
  fi
  return 0
}

write_admin_cli() {
  cat > /usr/local/bin/wins-admin <<'PYEOF'
#!/usr/bin/env python3
import json, os, sys, sqlite3, subprocess, urllib.parse, urllib.request
from datetime import datetime, timezone
from pathlib import Path

# Root-owned file only. /root/vpn_auth/.env is a mirror in the hub app's
# writable directory (write_env writes the same keys to both); read after this
# one it let the app choose DATABASE_PATH, which sqlite3.connect creates as
# root wherever it points.
ENV_PATHS = [Path('/root/vpn_auth.env')]
ENV = {}
for p in ENV_PATHS:
    if p.exists():
        for line in p.read_text(errors='ignore').splitlines():
            if '=' in line and not line.lstrip().startswith('#'):
                k, v = line.split('=', 1)
                v = v.strip()
                if len(v) >= 2 and v[0] == v[-1] == "'":
                    v = v[1:-1].replace('\'"\'"\'', "'")
                elif len(v) >= 2 and v[0] == v[-1] == '"':
                    v = v[1:-1]
                ENV[k.strip()] = v
DB = ENV.get('DATABASE_PATH') or ENV.get('DATABASEPATH') or '/root/vpn_auth/vpn_users.db'
TOKEN = ENV.get('ADMIN_TOKEN') or ENV.get('ADMINTOKEN')
if not TOKEN:
    raise SystemExit('ADMIN_TOKEN is missing from the root-owned hub environment')
BASE = 'http://127.0.0.1:8000'


class _AdminNoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_ADMIN_NO_REDIRECT_OPENER = urllib.request.build_opener(_AdminNoRedirect)


def utcnow():
    return datetime.now(timezone.utc).replace(tzinfo=None)

def db():
    conn = sqlite3.connect(DB, timeout=20)
    conn.row_factory = sqlite3.Row
    return conn

def post_form(path, data):
    body = urllib.parse.urlencode(data).encode()
    req = urllib.request.Request(BASE + path, data=body, headers={'x-admin-token': TOKEN, 'Content-Type': 'application/x-www-form-urlencoded'})
    with _ADMIN_NO_REDIRECT_OPENER.open(req, timeout=20) as r:
        print(r.read().decode())

def get_json(path):
    req = urllib.request.Request(BASE + path, headers={'x-admin-token': TOKEN})
    with _ADMIN_NO_REDIRECT_OPENER.open(req, timeout=20) as r:
        body = r.read().decode()
        try:
            print(json.dumps(json.loads(body), indent=2))
        except Exception:
            print(body)

def status():
    subprocess.run(['systemctl','--no-pager','--full','status','wins-hub.service'], check=False)
    subprocess.run(['curl','-sS',BASE+'/healthz'], check=False)
    print()

def mask_value(value):
    value = value or ''
    if os.environ.get('WINS_SHOW_SECRETS') == '1':
        return value
    if not value:
        return '(empty)'
    if len(value) <= 8:
        return '****'
    return value[:4] + '...' + value[-4:]

def provision_duration(duration, label):
    name = input('Subscriber name [Wins VPN User]: ').strip() or 'Wins VPN User'
    email = input('Email: ').strip()
    post_form('/admin/provision', {'name': name, 'email': email, 'duration': duration})

def renew_existing():
    acc = input('Account number: ').strip()
    duration = input('Renew duration [1m, 3m, 1y, 10y]: ').strip() or '1m'
    post_form('/admin/renew', {'account_number': acc, 'duration': duration})

def list_users():
    with db() as c:
        rows = c.execute('SELECT account_number,email,subscriber_name,status,expiration_date,created_at FROM users ORDER BY created_at DESC LIMIT 100').fetchall()
        for r in rows:
            print(f"{r['account_number']} | {r['status']} | {r['expiration_date']} | {r['email']} | {r['subscriber_name']}")

def show_devices():
    acc = input('Account number: ').strip()
    with db() as c:
        rows = c.execute('SELECT device_id,device_model,vpn_internal_ip,last_seen,location_slug FROM devices WHERE account_number=? ORDER BY last_seen DESC', (acc,)).fetchall()
        if not rows:
            print(f"No devices found for account {acc}")
            return
        print(f"\nActive devices for {acc} ({len(rows)} total):")
        for idx, r in enumerate(rows, 1):
            model = r['device_model'] or 'Unknown device'
            print(f"  [{idx}] {model} | IP: {r['vpn_internal_ip']} | Location: {r['location_slug']} | ID: {r['device_id']} | Last seen: {r['last_seen']}")

def deactivate_device():
    acc = input('Account number: ').strip()
    with db() as c:
        rows = c.execute('SELECT device_id,device_model,vpn_internal_ip,last_seen,location_slug FROM devices WHERE account_number=? ORDER BY last_seen DESC', (acc,)).fetchall()
    if not rows:
        print(f"No active devices found for account {acc}")
        return
    print(f"\nActive devices for account {acc}:")
    for idx, r in enumerate(rows, 1):
        model = r['device_model'] or 'Unknown device'
        print(f"  [{idx}] {model} (Location: {r['location_slug']}, IP: {r['vpn_internal_ip']}, ID: {r['device_id']})")
    selection = input("\nEnter device number [1..N], device model name, or device ID to remove (or 'c' to cancel): ").strip()
    if not selection or selection.lower() == 'c':
        print("Cancelled.")
        return
    target_id = None
    target_model = None
    if selection.isdigit():
        idx = int(selection) - 1
        if 0 <= idx < len(rows):
            target_id = rows[idx]['device_id']
            target_model = rows[idx]['device_model']
    if not target_id:
        for r in rows:
            if r['device_id'].lower() == selection.lower():
                target_id = r['device_id']
                target_model = r['device_model']
                break
            if selection.lower() in (r['device_model'] or '').lower():
                target_id = r['device_id']
                target_model = r['device_model']
                break
    if not target_id:
        print(f"No device matching '{selection}' found.")
        return
    print(f"Removing device '{target_model}' (ID: {target_id})...")
    post_form('/admin/device/remove', {'account_number': acc, 'device_id': target_id})

def resend():
    email = input('Email: ').strip()
    post_form('/admin/resend', {'email': email})

def announce():
    # Announcements are signed OFFLINE (tools/winn3_sign_announcement.py); the
    # hub only verifies. Give the path of the envelope JSON the tool printed.
    path = input('Signed envelope JSON path (blank = unsigned plaintext): ').strip()
    if path:
        try:
            envelope = json.loads(Path(path).read_text(encoding='utf-8'))
        except Exception as exc:
            print(f'Cannot read envelope JSON: {exc.__class__.__name__}')
            return
        if not isinstance(envelope, dict):
            print('Envelope JSON must be an object with payload and sig.')
            return
        payload = str(envelope.get('payload') or '').strip()
        sig = str(envelope.get('sig') or '').strip()
        if not payload or not sig:
            print('Envelope JSON must carry payload and sig.')
            return
        post_form('/admin/announce', {
            'announcement_payload_b64': payload,
            'announcement_sig_b64': sig,
        })
        return
    if ENV.get('ANNOUNCE_REQUIRE_SIGNED', '0').strip().lower() in {'1', 'true', 'yes', 'on'}:
        print('This hub requires a signed announcement (ANNOUNCE_REQUIRE_SIGNED=1).')
        return
    msg = input('Announcement text (UNSIGNED; enforcing apps will not show it): ')
    post_form('/admin/announce', {'msg': msg})

def maintenance():
    enabled = input('Maintenance mode? [y/N]: ').strip().lower().startswith('y')
    post_form('/admin/maintenance', {'enabled': str(enabled).lower()})

def set_double_vpn_free_access():
    # Owner ruling 2026-10-13: Double VPN is for paid accounts only. Free access
    # turns on only for an explicit yes word; Enter, a typo or anything else
    # posts false.
    answer = input('Allow free users to use Double VPN core first hop? [y/N]: ').strip().lower()
    enabled_bool = answer in {'y', 'yes'}
    post_form('/admin/double-vpn/free-access', {'enabled': str(enabled_bool).lower()})

def nodes():
    with db() as c:
        rows = c.execute('SELECT slug,name,endpoint,stealth_endpoint,status,last_heartbeat,ssh_host,regional_aliases,rx_mbps,tx_mbps,awg_rx_bytes,awg_tx_bytes,peer_count,max_peers,free_access_enabled,direct_awg_enabled,operator_enabled FROM nodes ORDER BY LOWER(name) ASC, LOWER(slug) ASC').fetchall()
        for r in rows:
            rx_gb = (r['awg_rx_bytes'] or 0) / 1073741824
            tx_gb = (r['awg_tx_bytes'] or 0) / 1073741824
            rx_mbps = float(r['rx_mbps'] or 0)
            tx_mbps = float(r['tx_mbps'] or 0)
            operator_enabled = int(r['operator_enabled'] if r['operator_enabled'] is not None else 0)
            if operator_enabled != 1:
                access = 'off'
            else:
                access = 'free' if int(r['free_access_enabled'] or 0) == 1 else 'premium'
            direct_awg = 'direct-awg' if int(r['direct_awg_enabled'] if r['direct_awg_enabled'] is not None else 1) == 1 else 'tcp-fallback-only'
            print(f"{r['slug']} | {access} | {direct_awg} | {r['status']} | peers={r['peer_count'] or 0}/{r['max_peers'] or 'fallback'} | rx={rx_mbps:.3f} Mbps tx={tx_mbps:.3f} Mbps | total_rx={rx_gb:.2f} GiB total_tx={tx_gb:.2f} GiB | {r['endpoint']} | stealth={r['stealth_endpoint']} | aliases={r['regional_aliases'] or '[]'} | ssh={r['ssh_host']} | {r['last_heartbeat']}")

def mark_node():
    slug = input('Node slug: ').strip()
    new = input('Status [online/congested/maintenance/offline]: ').strip() or 'online'
    with db() as c:
        c.execute(
            'UPDATE nodes SET status=?, last_heartbeat=?, management_status=?, management_checked_at=?, management_error=? WHERE slug=?',
            (new, utcnow().isoformat(), 'unknown', utcnow().isoformat(), '', slug),
        )
        c.commit()
    print('Updated')

def set_node_free_access():
    nodes()
    slug = input('Node slug: ').strip()
    enabled = input('Make this node free? [y/N]: ').strip().lower().startswith('y')
    post_form('/admin/nodes/free-access', {'slug': slug, 'enabled': str(enabled).lower()})

def set_node_tier():
    nodes()
    slug = input('Node slug: ').strip()
    tier = input('Tier [off/free/premium]: ').strip().lower()
    if tier not in {'off', 'free', 'premium'}:
        print('Tier must be off, free, or premium')
        return
    payload = {'slug': slug, 'tier': tier}
    if tier in {'free', 'premium'}:
        payload['evidence_sha256'] = input(
            'Frozen secret-safe gate evidence SHA-256 (required when promoting from off): '
        ).strip().lower()
        payload['confirm_slug'] = input(
            f'Type {slug} again if this is a promotion from off: '
        ).strip().lower()
    post_form('/admin/nodes/tier', payload)

def set_node_direct_awg():
    nodes()
    slug = input('Node slug: ').strip()
    enabled = input('Allow direct AWG UDP for this node? [y/N]: ').strip().lower().startswith('y')
    post_form('/admin/nodes/direct-awg', {'slug': slug, 'enabled': str(enabled).lower()})

def promote_core():
    core_id = input('Double VPN Core ID: ').strip().lower()
    evidence_sha256 = input(
        'Frozen secret-safe Core gate evidence SHA-256: '
    ).strip().lower()
    confirm_core_id = input(f'Type {core_id} again to promote this Core: ').strip().lower()
    post_form('/admin/core/promote', {
        'core_id': core_id,
        'confirm_core_id': confirm_core_id,
        'evidence_sha256': evidence_sha256,
    })

def withdraw_core():
    core_id = input('Double VPN Core ID: ').strip().lower()
    confirmation = input(
        f'Type WITHDRAW {core_id} to withdraw it and deactivate its assignments: '
    ).strip()
    if confirmation != f'WITHDRAW {core_id}':
        print('Withdrawal cancelled')
        return
    post_form('/admin/core/withdraw', {'core_id': core_id})

def backup():
    subprocess.run(['systemctl', 'start', 'wins-hub-backup.service'], check=False)

def paypal_dead_letters():
    status = input('Event status [failed]: ').strip() or 'failed'
    limit = input('Limit [50]: ').strip() or '50'
    get_json('/admin/paypal/dead-letter?' + urllib.parse.urlencode({'status': status, 'limit': limit}))

def paypal_retry():
    event_id = input('PayPal event_id to retry: ').strip()
    post_form('/admin/paypal/retry', {'event_id': event_id})

def secrets():
    print(f'Env: /root/vpn_auth.env')
    print(f'DB: {DB}')
    print(f'Admin token: {mask_value(TOKEN)}')
    print(f'SPA key: {mask_value(ENV.get("SPA_KEY") or ENV.get("SPAKEY") or "")}')
    print(f'SPA HMAC: {mask_value(ENV.get("SPA_HMAC") or ENV.get("SPAHMAC") or "")}')
    print(f'Xray UUID: {mask_value(ENV.get("XRAY_UUID") or ENV.get("XRAYUUID") or "")}')
    print('Set WINS_SHOW_SECRETS=1 only in a private root shell to reveal full values.')

def menu():
    actions = {
        '1': status,
        '2': lambda: provision_duration('1m', '1-month'),
        '3': lambda: provision_duration('1y', '1-year'),
        '4': lambda: provision_duration('10y', 'lifetime'),
        '5': renew_existing,
        '6': list_users,
        '7': show_devices,
        '8': deactivate_device,
        '9': resend,
        '10': announce,
        '11': maintenance,
        '12': nodes,
        '13': mark_node,
        '14': backup,
        '15': secrets,
        '16': paypal_dead_letters,
        '17': paypal_retry,
        '18': set_node_free_access,
        '19': set_node_direct_awg,
        '20': set_double_vpn_free_access,
        '21': set_node_tier,
        '22': promote_core,
        '23': withdraw_core,
    }
    while True:
        print("""\nWins VPN Admin Menu
 1) System status
 2) Create 1-month account manually
 3) Create 1-year account manually
 4) Create lifetime account manually
 5) Renew existing account
 6) List latest accounts
 7) Show devices for account
 8) Deactivate one device
 9) Resend activation email
10) Set global announcement
11) Toggle maintenance mode
12) List data-plane nodes
13) Mark node status manually
14) Run hub backup now
15) Show local secrets/paths, masked
16) List PayPal dead-letter events
17) Retry one PayPal dead-letter event
18) Set node free/premium access
19) Set node direct AWG/TCP fallback
20) Toggle Double VPN core for free users
21) Set node tier: off / free / premium (promotion requires frozen evidence)
22) Promote Double VPN Core from dark state (requires frozen evidence)
23) Withdraw Double VPN Core and deactivate its assignments
 0) Exit""")
        choice = input('Select: ').strip()
        if choice == '0': return
        fn = actions.get(choice)
        if fn:
            try: fn()
            except Exception as e: print('ERROR:', e)
        else:
            print('Invalid choice')

if __name__ == '__main__':
    menu()
PYEOF
  chmod +x /usr/local/bin/wins-admin
  ln -sf /usr/local/bin/wins-admin /usr/local/bin/wins-menu
}

# ---------------------------------------------------------------------------
# IA-SYNC SYNC-04: the health-forging keepalive. tools/apply_kansas_winn3.py
# (removed from the repo) wrote /root/vpn_auth/keepalive_nodes.py, which sets
# status online, operator_enabled 1, management ok, a fresh last_heartbeat and
# a fresh v3 canary on a fixed list of nodes every time it runs. From cron it
# reopens closed nodes past the evidenced promotion gate, voids the installer
# withdrawal latch and hides outages (it hid a Chicago outage). No installer
# writes it.
#
# Round 3. Found by name AND by content: a crontab line, a periodic job, a
# systemd unit or drop-in (under /etc, /lib, /usr/lib, /usr/local/lib and
# /run) that names keepalive_nodes, runs the forging SQL (an UPDATE of nodes
# that sets health or latch columns) or posts to a node heartbeat route. On
# --deploy every match is quarantined (moved, never deleted; units stopped and
# disabled first), every step is checked, and a rescan must come back empty.
# Turn 4 (Sol N-10): moving a file does not stop a command that is already
# running. A unit (a linked one too) must stop, and what a forging timer
# triggers with it; anything left in its cgroup is ended; a drop-in's
# commands are ended inside its parent's cgroup after the daemon-reload; and
# each is verified gone (unit inactive, no such process in the cgroup) or the
# deploy stops. A stop or a verification that fails is never only warned.
# Retirement is GATED (OI-SYNC_HUB-1): while any open winn/3 slug lacks a real
# external canary (a binding, a probe binary that runs, the binding's key
# files, and a fresh canary verdict) it refuses before writing anything and
# names each slug and why, because a winn/3 row without a fresh canary is
# served to no direct client. HUB_RETIRE_HEALTH_KEEPALIVE_FORCE=1 retires
# anyway; that darkens the named slugs and is an owner decision.
# WINS_KEEPALIVE_ROOT prefixes every path, for tests only.
WINS_KEEPALIVE_MARKER="keepalive_nodes"
WINS_KEEPALIVE_DEFAULT_SCRIPT="/root/vpn_auth/keepalive_nodes.py"
WINS_KEEPALIVE_TOKEN_RE='/[^[:space:];|&"'"'"'=]*keepalive_nodes[^[:space:];|&"'"'"']*'
# The columns the forger writes. One list for the one-line and the multi-line check.
WINS_KEEPALIVE_COLUMNS_RE='management_status|operator_enabled|last_heartbeat|winn3_canary_status|data_plane_status'
# One line that forges: the marker, the forging UPDATE, or a heartbeat post.
WINS_KEEPALIVE_LINE_RE="keepalive_nodes|update[[:space:]]+nodes[[:space:]]+set.*(${WINS_KEEPALIVE_COLUMNS_RE})|/api/v1/nodes/([a-z0-9-]+/)?heartbeat"
WINS_KEEPALIVE_UNIT_DIRS="/etc/systemd/system /lib/systemd/system /usr/lib/systemd/system /usr/local/lib/systemd/system /run/systemd/system"

# _keepalive_file_forges FILE: true when FILE (a whole script or unit) names
# the keepalive, posts to a heartbeat route, or carries the forging SQL, which
# in a script may span lines (an UPDATE of nodes plus a health/latch column).
_keepalive_file_forges() {
  local f="$1"
  grep -qsiE -- "${WINS_KEEPALIVE_LINE_RE}" "${f}" && return 0
  grep -qsiE -- 'update[[:space:]]+nodes' "${f}" \
    && grep -qsiE -- "${WINS_KEEPALIVE_COLUMNS_RE}" "${f}"
}

_keepalive_collect_tokens() {
  grep -iE -- "${WINS_KEEPALIVE_LINE_RE}" "$1" 2>/dev/null | grep -oE "${WINS_KEEPALIVE_TOKEN_RE}" || true
}

# health_keepalive_scan prints one "kind<TAB>path" line per finding, paths
# without the test root: cron (a crontab or cron.d file with a forging line),
# usercron:<user> (a spool crontab), periodic (a file under /etc/cron.<x>/
# that forges), unit (a systemd unit or drop-in that forges, linked or not),
# script (a keepalive script a runner names, or the default path), link (any
# other symlink that forges or sits at a script path; never followed or edited).
health_keepalive_scan() {
  local root="${WINS_KEEPALIVE_ROOT:-}" f rel token dir
  local -A scripts=()
  for f in "${root}/etc/crontab" "${root}"/etc/cron.d/*; do
    [[ -e "${f}" || -L "${f}" ]] || continue
    rel="${f#"${root}"}"
    if [[ -L "${f}" ]]; then
      _keepalive_file_forges "${f}" && printf 'link\t%s\n' "${rel}"
      continue
    fi
    [[ -f "${f}" ]] || continue
    grep -qsiE -- "${WINS_KEEPALIVE_LINE_RE}" "${f}" || continue
    printf 'cron\t%s\n' "${rel}"
    while IFS= read -r token; do scripts["${token}"]=1; done < <(_keepalive_collect_tokens "${f}")
  done
  for f in "${root}"/var/spool/cron/crontabs/*; do
    [[ -f "${f}" && ! -L "${f}" ]] || continue
    grep -qsiE -- "${WINS_KEEPALIVE_LINE_RE}" "${f}" || continue
    printf 'usercron:%s\t%s\n' "$(basename -- "${f}")" "${f#"${root}"}"
    while IFS= read -r token; do scripts["${token}"]=1; done < <(_keepalive_collect_tokens "${f}")
  done
  for dir in "${root}"/etc/cron.*; do
    [[ -d "${dir}" && "${dir}" != "${root}/etc/cron.d" ]] || continue
    for f in "${dir}"/*; do
      [[ -e "${f}" || -L "${f}" ]] || continue
      _keepalive_file_forges "${f}" || continue
      if [[ -L "${f}" ]]; then printf 'link\t%s\n' "${f#"${root}"}"; else printf 'periodic\t%s\n' "${f#"${root}"}"; fi
      while IFS= read -r token; do scripts["${token}"]=1; done < <(_keepalive_collect_tokens "${f}")
    done
  done
  local -A unit_dirs_seen=()
  local real_dir
  for dir in ${WINS_KEEPALIVE_UNIT_DIRS}; do
    # /lib is a symlink to /usr/lib on current Ubuntu: scan each real
    # directory once, or one file would be found (and moved) twice.
    [[ -d "${root}${dir}" ]] || continue
    real_dir="$(cd "${root}${dir}" && pwd -P)" || continue
    [[ -z "${unit_dirs_seen[${real_dir}]:-}" ]] || continue
    unit_dirs_seen["${real_dir}"]=1
    for f in "${root}${dir}"/*.service "${root}${dir}"/*.timer \
        "${root}${dir}"/*.service.d/*.conf "${root}${dir}"/*.timer.d/*.conf; do
      [[ -e "${f}" || -L "${f}" ]] || continue
      _keepalive_file_forges "${f}" || continue
      # A linked unit (a symlink here) is a unit: it is stopped and verified
      # like one, and only the link itself is moved.
      printf 'unit\t%s\n' "${f#"${root}"}"
      while IFS= read -r token; do scripts["${token}"]=1; done < <(_keepalive_collect_tokens "${f}")
    done
    # Turn 5: a top-level type drop-in (service.d/, timer.d/) applies to every
    # unit of that type. It is reported as typedropin and never retired
    # automatically: ending its commands would mean matching processes in
    # every service on the hub. A deploy refuses until it is removed by hand.
    for f in "${root}${dir}"/service.d/*.conf "${root}${dir}"/timer.d/*.conf; do
      [[ -e "${f}" || -L "${f}" ]] || continue
      _keepalive_file_forges "${f}" || continue
      printf 'typedropin\t%s\n' "${f#"${root}"}"
    done
  done
  scripts["${WINS_KEEPALIVE_DEFAULT_SCRIPT}"]=1
  for token in "${!scripts[@]}"; do
    [[ "$(basename -- "${token}")" == *"${WINS_KEEPALIVE_MARKER}"* ]] || continue
    f="${root}${token}"
    if [[ -L "${f}" ]]; then
      printf 'link\t%s\n' "${token}"
    elif [[ -f "${f}" ]]; then
      printf 'script\t%s\n' "${token}"
    fi
  done
  return 0
}

# health_keepalive_canary_coverage prints, for the hub database, one line per
# winn/3 slug and a summary:
#   COVERED <slug>
#   UNCOVERED <slug> <reason>[; <reason>...]
#   CLOSED <slug>                       (operator latch closed: serves nothing either way)
#   SUMMARY open=<n> covered=<n> uncovered=<slugs|none>
#   ERROR <why>                         (the database cannot be read)
# Nothing at all when there is no database. A slug is covered only when ALL
# hold: a canary binding names it (WINN3_CANARY_NODES, or the legacy
# WINN3_CANARY_NODE_SLUG with WINN3_CANARY_KEY_DIR/GATEWAY_ENDPOINT/GATEWAY_ID/
# INNER_V4); WINN3_CANARY_BIN is an executable file that runs (-h, 10 s); the
# binding's key_dir holds client.key, static.pub and admission.key; and the
# slug's winn3_canary_status is ok, checked within
# WINN3_CANARY_HARD_STALE_MINUTES. While the keepalive runs that last column
# is forged, so the first three (which it cannot forge) carry the gate.
# Turn 4b (Seat C N-10): every WINN3_CANARY_* value is the one this deploy will
# write: a non-empty value the installer was given (environment or defaults
# file, both exported) wins, as the operator-intent rule of write_env has it;
# otherwise the env file's value, read the way the installer reads that file
# (bash source), so any quoting bash accepts is read the same. Neither: no
# binding, and the gate refuses. Turn 5: like load_existing_envs, the legacy
# ${LEGACY_ENV_FILE} is sourced first and ${ENV_FILE} over it.
# FU-SYNCHUB (Sol N-18, Seat C N-10): the values are no longer a model of
# write_env's precedence. _keepalive_deploy_canary_env runs write_env's own
# sequence (operator intent snapshot, load_existing_envs, reapply, and the
# unexported secrets-file overlay) in a subshell, so coverage is judged on
# the final binding the deploy writes, after every overlay it applies.
health_keepalive_canary_coverage() {
  local root="${WINS_KEEPALIVE_ROOT:-}"
  local db="${root}${DB_PATH:-/root/vpn_auth/vpn_users.db}"
  local -a kv=()
  [[ -e "${db}" ]] || return 0
  mapfile -d '' -t kv < <(_keepalive_deploy_canary_env)
  if (( ${#kv[@]} == 0 )) || [[ "${kv[${#kv[@]}-1]}" != WINS-KEEPALIVE-ENV-OK ]]; then
    printf 'ERROR the runtime environment this deploy would write cannot be read (an env file or the secrets file %s failed to load)\n' "${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}"
    return 0
  fi
  unset 'kv[${#kv[@]}-1]'
  python3 - "${db}" "${root}" ${kv[@]+"${kv[@]}"} <<'WINS_KEEPALIVE_CANARY_PY' || printf 'ERROR coverage check failed to run\n'
import base64, datetime, json, os, re, sqlite3, subprocess, sys
db, root = sys.argv[1:3]
pairs = sys.argv[3:]
values = dict(zip(pairs[0::2], pairs[1::2]))
bindings = {}
for entry in values.get("WINN3_CANARY_NODES", "").split():
    fields = entry.split("|")
    if len(fields) == 6:
        bindings.setdefault(fields[0].strip().lower(), {"key_dir": fields[3], "complete": all(fields)})
legacy = values.get("WINN3_CANARY_NODE_SLUG", "").strip().lower()
if legacy and legacy not in bindings:
    bindings[legacy] = {"key_dir": values.get("WINN3_CANARY_KEY_DIR", ""), "complete": all(
        values.get(k, "") for k in ("WINN3_CANARY_KEY_DIR", "WINN3_CANARY_GATEWAY_ENDPOINT",
                                    "WINN3_CANARY_GATEWAY_ID", "WINN3_CANARY_INNER_V4"))}
probe = values.get("WINN3_CANARY_BIN", "") or "/usr/local/bin/winn3-probe"
probe_path = root + probe
probe_problem = ""
if not os.path.isfile(probe_path) or not os.access(probe_path, os.X_OK):
    probe_problem = f"probe {probe} is missing or not executable"
else:
    try:
        rc = subprocess.run([probe_path, "-h"], capture_output=True, timeout=10).returncode
        if rc in (126, 127) or rc < 0:
            probe_problem = f"probe {probe} does not run (rc {rc})"
    except (OSError, subprocess.TimeoutExpired) as exc:
        probe_problem = f"probe {probe} does not run ({type(exc).__name__})"
try:
    stale = int(values.get("WINN3_CANARY_HARD_STALE_MINUTES", "") or 30)
except ValueError:
    stale = 30
now = datetime.datetime.now(datetime.timezone.utc)
def timestamp(text):
    try:
        t = datetime.datetime.fromisoformat(str(text).replace("Z", "+00:00"))
        if t.tzinfo is None:
            t = t.replace(tzinfo=datetime.timezone.utc)
        return t.astimezone(datetime.timezone.utc)
    except (TypeError, ValueError, OverflowError):
        return None
def fresh(text):
    t = timestamp(text)
    return t is not None and datetime.timedelta(seconds=-60) <= now - t <= datetime.timedelta(minutes=stale)
try:
    conn = sqlite3.connect("file:%s?mode=ro" % db, uri=True)
    conn.row_factory = sqlite3.Row
    cols = {r[1] for r in conn.execute("PRAGMA table_info(nodes)")}
    rows = conn.execute("SELECT * FROM nodes").fetchall()
    if not legacy and not values.get("WINN3_CANARY_NODES", "").strip():
        if conn.execute("SELECT 1 FROM sqlite_master WHERE name='winn3_canary_bindings'").fetchone():
            for binding in conn.execute("SELECT * FROM winn3_canary_bindings"):
                item = dict(binding)
                bindings[item["slug"]] = {"key_dir": item["key_dir"], "complete": all(item.values())}
except sqlite3.Error as exc:
    print("ERROR database unreadable (%s)" % type(exc).__name__)
    sys.exit(0)
open_slugs, covered, uncovered = [], [], []
for row in rows:
    data = dict(row)
    if str(data.get("protocol_version") or "").strip().lower() != "winn/3":
        continue
    if str(data.get("retired_at") or "").strip():
        continue
    slug = str(data.get("slug") or "").strip().lower()
    if int(data.get("operator_enabled") or 0) != 1:
        print("CLOSED %s" % slug)
        continue
    open_slugs.append(slug)
    reasons = []
    binding = bindings.get(slug)
    if binding is None:
        reasons.append("no canary binding")
    else:
        if not binding["complete"]:
            reasons.append("canary binding incomplete")
        key_dir = root + binding["key_dir"] if binding["key_dir"] else ""
        missing = [n for n in ("client.key", "static.pub", "admission.key")
                   if not key_dir or not os.path.isfile(os.path.join(key_dir, n))]
        if missing:
            reasons.append("key_dir %s lacks %s" % (binding["key_dir"] or "(none)", ",".join(missing)))
    if probe_problem:
        reasons.append(probe_problem)
    # The hub's own rule (winn3_canary_is_fresh): status ok AND winn3_canary_ok_at
    # inside the window. A fresh checked_at beside an old ok_at is not fresh.
    if str(data.get("winn3_canary_status") or "").strip().lower() != "ok" or not fresh(data.get("winn3_canary_ok_at")):
        reasons.append("no fresh canary verdict (status %s)" % (data.get("winn3_canary_status") or "unknown"))
    try:
        envelope = json.loads(data.get("winn3_descriptor_json") or "")
        descriptor = json.loads(base64.b64decode(envelope["payload"], validate=True))
        if (not data.get("winn3_identity_sha256") or
                data.get("winn3_canary_identity_sha256") != data["winn3_identity_sha256"] or
                data.get("winn3_canary_seq") != descriptor["seq"] or
                data.get("winn3_canary_generation") != data.get("deployment_generation")):
            reasons.append("canary identity, sequence or generation mismatch")
        checked = timestamp(data.get("winn3_canary_ok_at"))
        released = timestamp(data.get("deployment_released_at"))
        flipped = timestamp(data.get("winn3_carrier_flipped_at"))
        if released is None or flipped is None or flipped < released:
            reasons.append("no valid post-release carrier flip")
        for field in ("deployment_completed_at", "deployment_released_at", "winn3_carrier_flipped_at"):
            raw = data.get(field)
            boundary = timestamp(raw)
            if raw not in (None, "") and boundary is None:
                reasons.append("invalid " + field)
            elif boundary is not None and (checked is None or checked <= boundary):
                reasons.append("canary predates " + field)
    except (ValueError, KeyError, TypeError):
        reasons.append("no valid stored descriptor binding")
    if reasons:
        uncovered.append(slug)
        print("UNCOVERED %s %s" % (slug, "; ".join(reasons)))
    else:
        covered.append(slug)
        print("COVERED %s" % slug)
print("SUMMARY open=%d covered=%d uncovered=%s" % (len(open_slugs), len(covered), ",".join(sorted(uncovered)) or "none"))
WINS_KEEPALIVE_CANARY_PY
}

# _keepalive_deploy_canary_env: NAME, NUL, VALUE, NUL for every WINN3_CANARY_*
# exactly as write_env leaves it, then the marker WINS-KEEPALIVE-ENV-OK. It
# runs write_env's own steps, in write_env's order, in a subshell (nothing in
# this shell changes): snapshot_operator_intent, load_existing_envs (legacy
# file, then ${ENV_FILE}), reapply_operator_intent, overlay_wins_secrets_file.
# No marker when the secrets file is refused, so the gate fails closed then.
_keepalive_deploy_canary_env() {
  ( _keepalive_write_env_steps )
}

# _keepalive_write_env_steps: the body of _keepalive_deploy_canary_env; run it
# only in a subshell. The paths are locals, which the steps it calls see.
_keepalive_write_env_steps() {
  local root="${WINS_KEEPALIVE_ROOT:-}" name
  local ENV_FILE="${root}${ENV_FILE:-/root/vpn_auth.env}"
  local LEGACY_ENV_FILE="${root}${LEGACY_ENV_FILE:-/root/vpn_auth/.env}"
  local WINS_SECRETS_FILE="${root}${WINS_SECRETS_FILE:-/root/winsvpn-secrets.env}"
  exec 3>&1 1>&2
  snapshot_operator_intent
  load_existing_envs
  reapply_operator_intent
  overlay_wins_secrets_file || return 1
  for name in ${!WINN3_CANARY_@}; do printf '%s\0%s\0' "${name}" "${!name}" >&3; done
  printf 'WINS-KEEPALIVE-ENV-OK\0' >&3
}

# _keepalive_coverage_passes COVERAGE: 0 when the coverage output lets the
# keepalive go (no database, or every open winn/3 slug covered and no error).
# One rule for the deploy gate and the --preflight preview.
_keepalive_coverage_passes() {
  [[ -z "$1" ]] && return 0
  ! grep -q '^ERROR ' <<<"$1" && grep -q '^SUMMARY .* uncovered=none$' <<<"$1"
}

# health_keepalive_gate: 0 when retiring the keepalive darkens no open winn/3
# slug (or the operator forced it), 1 with every reason named otherwise.
health_keepalive_gate() {
  local coverage
  coverage="$(health_keepalive_canary_coverage)"
  if [[ -z "${coverage}" ]]; then
    log "Health keepalive gate: no hub database yet; nothing can be darkened."
    return 0
  fi
  if _keepalive_coverage_passes "${coverage}"; then
    log "Health keepalive gate: every open winn/3 slug has a real external canary ($(grep '^SUMMARY' <<<"${coverage}"))."
    return 0
  fi
  while IFS= read -r line; do
    case "${line}" in
      UNCOVERED*|ERROR*|SUMMARY*) warn "Health keepalive gate: ${line}" ;;
    esac
  done <<<"${coverage}"
  if [[ "${HUB_RETIRE_HEALTH_KEEPALIVE_FORCE:-0}" == "1" ]]; then
    warn "SECURITY: HUB_RETIRE_HEALTH_KEEPALIVE_FORCE=1: retiring the keepalive anyway. Every UNCOVERED slug above stops serving direct sessions within WINN3_CANARY_HARD_STALE_MINUTES, because its v3 health was never proven."
    return 0
  fi
  err "Health keepalive gate: refusing to retire the keepalive while the open winn/3 slugs above lack a real external canary; nothing was changed. Install winn3-probe at WINN3_CANARY_BIN, bind each slug in WINN3_CANARY_NODES with its key_dir, let the canary run, then rerun; or set HUB_RETIRE_HEALTH_KEEPALIVE_FORCE=1 to accept the outage by owner decision."
  return 1
}

# report_health_forging_keepalive: report only (used by --preflight). Turn 4b
# (Seat C N-12): returns 1 and says so whenever the gate preview shows that a
# deploy would refuse to retire what it found, so --preflight does not pass.
report_health_forging_keepalive() {
  local findings kind path line coverage refuse=0 typedropin=0 dropin_refuse=0
  local -A dropin_units=()
  findings="$(health_keepalive_scan | LC_ALL=C sort -u)"
  if [[ -z "${findings}" ]]; then
    log "Health keepalive check: no keepalive_nodes script or runner found."
    return 0
  fi
  coverage="$(health_keepalive_canary_coverage)"
  if ! _keepalive_coverage_passes "${coverage}" && [[ "${HUB_RETIRE_HEALTH_KEEPALIVE_FORCE:-0}" != "1" ]]; then
    refuse=1
  fi
  if grep -q $'^typedropin\t' <<<"${findings}"; then
    typedropin=1
  fi
  # FU-SYNCHUB: the deploy's drop-in precheck, as a preview (it writes nothing).
  _keepalive_dropins_precheck "${findings}" || dropin_refuse=1
  while IFS=$'\t' read -r kind path; do
    if [[ "${kind}" == typedropin ]]; then
      warn "SECURITY: health-forging keepalive ${kind} at ${path} (it forges node health in every unit of its type; a deploy refuses until it is removed by hand)."
    elif (( refuse )); then
      warn "SECURITY: health-forging keepalive ${kind} at ${path} (it forges node health; a deploy will refuse to retire it until the gate preview below passes)."
    else
      warn "SECURITY: health-forging keepalive ${kind} at ${path} (it forges node health; a deploy quarantines it)."
    fi
  done <<<"${findings}"
  while IFS= read -r line; do
    [[ -n "${line}" ]] && warn "Health keepalive gate (preview): ${line}"
  done <<<"${coverage}"
  if (( refuse )); then
    err "Health keepalive gate (preview): a deploy would refuse to retire the health-forging keepalive while the open winn/3 slugs above lack a real external canary. Bind them (WINN3_CANARY_NODES, key_dir, winn3-probe) or set HUB_RETIRE_HEALTH_KEEPALIVE_FORCE=1 by owner decision."
    return 1
  fi
  if (( typedropin )); then
    err "Health keepalive (preview): a deploy would refuse: a top-level systemd type drop-in forges health and is never retired automatically."
    return 1
  fi
  if (( dropin_refuse )); then
    err "Health keepalive (preview): a deploy would refuse: see the drop-in check above."
    return 1
  fi
  return 0
}

_keepalive_quarantine_name() { tr '/' '_' <<<"$1"; }

# _keepalive_unit_pattern UNIT: sets the caller's pre, suf and wild (bash
# dynamic scope) to the rule of _keepalive_cgroup_members below: a template
# or a dash prefix (wild=1) names every unit NAME with NAME == pre*suf;
# anything else (wild=0) names itself. Turn 9: the one rule for
# _keepalive_cgroup_members and _keepalive_dropin_snapshot.
_keepalive_unit_pattern() {
  local unit="$1"
  pre=""; suf=""; wild=0
  if [[ "${unit}" == *@.* ]]; then
    pre="${unit%%@*}@"; suf=".${unit##*.}"; wild=1
  elif [[ "${unit}" == *-.* ]]; then
    pre="${unit%.*}"; suf=".${unit##*.}"; wild=1
    [[ "${pre}" == "-" ]] && pre=""
  fi
  return 0
}

# _keepalive_cgroup_members UNIT: "PID<TAB>UNIT-NAME" for each process whose
# systemd cgroup (v2, or the v1 name=systemd hierarchy) is a unit UNIT names
# or one below it, zombies left out. UNIT may be a drop-in parent that names
# several units, matched one path component at a time: a template
# (name@.service) every instance (name@x.service); a dash prefix
# (foo-.service, Turn 5 N-15) every unit of that type whose name starts foo-
# (systemd applies foo-.service.d to foo-bar.service and foo-bar-baz.service);
# "-.service" every service.
# Turn 7 (Sol N-20): a component is the unit name as systemd escapes it for
# the cgroup tree (cg_escape: a name that starts with "_" or "." or could
# clash with a kernel file gets one more leading "_"; on systemd 255
# _foo.service runs in __foo.service and cpu.service in _cpu.service). It is
# compared after systemd's own cg_unescape, which drops one leading "_". A
# pattern (template, dash prefix) names no single unit whose ControlGroup
# systemd could report, so the rule is applied to every component instead.
_keepalive_cgroup_members() {
  local unit="$1" root="${WINS_KEEPALIVE_ROOT:-}" d hier cgpath _ comp pre="" suf="" wild=0
  local -a comps=()
  _keepalive_unit_pattern "${unit}"
  for d in "${root}"/proc/[0-9]*; do
    [[ -r "${d}/cgroup" ]] || continue
    grep -qsE '^State:[[:space:]]*Z' "${d}/status" && continue
    { while IFS=: read -r _ hier cgpath; do
        [[ -z "${hier}" || "${hier}" == name=systemd ]] || continue
        IFS=/ read -r -a comps <<<"${cgpath}"
        for comp in ${comps[@]+"${comps[@]}"}; do
          comp="${comp#_}"
          if (( wild )); then
            [[ "${comp}" == "${pre}"*"${suf}" ]] || continue
          else
            [[ "${comp}" == "${unit}" ]] || continue
          fi
          printf '%s\t%s\n' "${d##*/}" "${comp}"
          break 2
        done
      done < "${d}/cgroup"; } 2>/dev/null || true
  done
  return 0
}

# _keepalive_cgroup_pids UNIT: the PIDs of _keepalive_cgroup_members UNIT.
_keepalive_cgroup_pids() {
  local pid _
  while IFS=$'\t' read -r pid _; do
    printf '%s\n' "${pid}"
  done < <(_keepalive_cgroup_members "$1")
  return 0
}

# _keepalive_pids_alive PID...: the PIDs that still exist and are not zombies.
_keepalive_pids_alive() {
  local root="${WINS_KEEPALIVE_ROOT:-}" pid
  for pid in "$@"; do
    [[ -e "${root}/proc/${pid}" ]] || continue
    grep -qsE '^State:[[:space:]]*Z' "${root}/proc/${pid}/status" && continue
    printf '%s\n' "${pid}"
  done
  return 0
}

# _keepalive_end_pids PID...: SIGTERM, wait, SIGKILL, wait. 0 only when every
# PID is gone. WINS_KEEPALIVE_STOP_TICKS (0.2 s each, default 50) is for tests.
# shellcheck disable=SC2086 # PIDs, one per word
_keepalive_end_pids() {
  local sig tick alive="$*" ticks="${WINS_KEEPALIVE_STOP_TICKS:-50}"
  for sig in TERM KILL; do
    alive="$(_keepalive_pids_alive ${alive})"
    [[ -n "${alive}" ]] || return 0
    kill -s "${sig}" ${alive} 2>/dev/null || true
    for (( tick = 0; tick < ticks; tick++ )); do
      alive="$(_keepalive_pids_alive ${alive})"
      [[ -n "${alive}" ]] || return 0
      sleep 0.2
    done
  done
  [[ -z "$(_keepalive_pids_alive ${alive})" ]]
}

# _keepalive_unit_quiet UNIT: 0 when systemd reports UNIT inactive or failed
# and no process is left in its cgroup. An unanswered query is not quiet.
_keepalive_unit_quiet() {
  local state
  state="$(systemctl show -p ActiveState --value "$1" 2>/dev/null)" || return 1
  [[ "${state}" == inactive || "${state}" == failed ]] || return 1
  [[ -z "$(_keepalive_cgroup_pids "$1")" ]]
}

# _keepalive_stop_unit UNIT: UNIT was just stopped by systemd. Stop what a
# forging timer triggers, end anything left in each cgroup (KillMode=process
# or none leaves it there), and verify each one quiet. Appends every unit it
# verified to the caller's stopped array (bash dynamic scope).
_keepalive_stop_unit() {
  local unit="$1" u triggers
  local -a all=("${unit}")
  if [[ "${unit}" == *.timer ]]; then
    triggers="$(systemctl show -p Triggers --value "${unit}" 2>/dev/null)" \
      || { err "Health keepalive: cannot read what ${unit} triggers."; return 1; }
    for u in ${triggers}; do
      systemctl stop "${u}" >/dev/null 2>&1 \
        || { err "Health keepalive: cannot stop ${u}, which the health-forging ${unit} triggers."; return 1; }
      all+=("${u}")
    done
  fi
  for u in "${all[@]}"; do
    # shellcheck disable=SC2046 # one PID per word
    _keepalive_end_pids $(_keepalive_cgroup_pids "${u}") \
      || { err "Health keepalive: a process in the cgroup of ${u} survived SIGKILL."; return 1; }
    _keepalive_unit_quiet "${u}" \
      || { err "Health keepalive: ${u} is not verified stopped (systemd does not report it inactive, or a process is left in its cgroup)."; return 1; }
    stopped+=("${u}")
  done
  return 0
}

# Turn 9 (N-22, N-23): every decision about what a drop-in started is made
# from ONE listing of /proc. With two listings, a child forked between them
# looked unexplained (N-22, a spurious refusal), and a launcher that exited
# between them hid its reparented child from both checks (N-23, a return of 0
# with the child alive).
# _keepalive_dropin_snapshot PARENT DROPIN [UNIT...]: one pass over /proc that
# fills the caller's arrays (bash dynamic scope). ka_ppid: the parent of every
# live process. ka_order: the members, in listing order: the processes whose
# systemd cgroup (v2, or the v1 name=systemd hierarchy; components unescaped
# as in _keepalive_cgroup_members) is PARENT's, by the same template and dash
# prefix rule, or a UNIT's (a systemd Id the drop-in applies to, see
# _keepalive_dropin_units). ka_unit: the first UNIT, in argument order, whose
# cgroup holds a member. ka_cmd: a member's command line (quotes dropped,
# blanks collapsed). ka_hit: the members the drop-in started: a command line
# that forges, or one equal to one of the drop-in's Exec*= commands, and every
# member that descends from one of those. Zombies are left out, and so is a
# process whose /proc entry is gone by the time it is read.
_keepalive_dropin_snapshot() {
  local parent="$1" dropin="$2" root="${WINS_KEEPALIVE_ROOT:-}" line cmd pid changed u d hier cgpath _ comp
  local pre="" suf="" wild=0 member state pp
  local -a comps=()
  local -A execs=() incg=()
  while IFS= read -r line; do
    line="${line#*=}"
    while [[ "${line}" == [-@:+!\|]* ]]; do line="${line:1}"; done
    line="$(_keepalive_norm "${line}")"
    [[ -n "${line}" ]] && execs["${line}"]=1
  done < <(grep -E '^[[:space:]]*Exec[A-Za-z]*[[:space:]]*=' "${dropin}" 2>/dev/null || true)
  _keepalive_unit_pattern "${parent}"
  for d in "${root}"/proc/[0-9]*; do
    pid="${d##*/}"; state=""; pp=""
    { while IFS= read -r line; do
        case "${line}" in
          State:*) state="${line#State:}" ;;
          PPid:*) pp="${line#PPid:}"; break ;;
        esac
      done < "${d}/status"; } 2>/dev/null || continue
    pp="${pp//[[:space:]]/}"; state="${state//[[:space:]]/}"
    [[ "${pp}" =~ ^[0-9]+$ && "${state}" != Z* ]] || continue
    ka_ppid["${pid}"]="${pp}"
    incg=()
    { while IFS=: read -r _ hier cgpath; do
        [[ -z "${hier}" || "${hier}" == name=systemd ]] || continue
        IFS=/ read -r -a comps <<<"${cgpath}"
        for comp in ${comps[@]+"${comps[@]}"}; do
          comp="${comp#_}"
          # Turn 10 (N-24): an if, not &&. The loop returns its last command's
          # status, so an empty last component (a trailing "0::/" line on a v1
          # host with cgroup2 mounted) must not read as a failed read below.
          if [[ -n "${comp}" ]]; then incg["${comp}"]=1; fi
        done
      done < "${d}/cgroup"; } 2>/dev/null || continue
    member=0
    for comp in "${!incg[@]}"; do
      if [[ "${comp}" == "${parent}" ]] || { (( wild )) && [[ "${comp}" == "${pre}"*"${suf}" ]]; }; then
        member=1
        break
      fi
    done
    for u in "${@:3}"; do
      [[ -n "${incg[${u}]:-}" ]] || continue
      ka_unit["${pid}"]="${u}"
      member=1
      break
    done
    (( member )) || continue
    # 2>/dev/null comes first: a failed < redirection reports on the stderr in
    # place when it is applied. An entry that cannot be read but is still
    # there counts, with no command line (it cannot be shown to be a forger).
    if ! cmd="$(tr '\0' ' ' 2>/dev/null < "${d}/cmdline")"; then
      [[ -e "${d}" ]] || continue
      cmd=""
    fi
    cmd="$(_keepalive_norm "${cmd}")"
    ka_cmd["${pid}"]="${cmd}"
    ka_order+=("${pid}")
    [[ -n "${cmd}" ]] || continue
    if [[ -n "${execs[${cmd}]:-}" ]] || grep -qiE -- "${WINS_KEEPALIVE_LINE_RE}" <<<"${cmd}"; then
      ka_hit["${pid}"]=1
    fi
  done
  changed=1
  while (( changed )); do
    changed=0
    for pid in ${ka_order[@]+"${ka_order[@]}"}; do
      [[ -z "${ka_hit[${pid}]:-}" && -n "${ka_hit[${ka_ppid[${pid}]:-x}]:-}" ]] || continue
      ka_hit["${pid}"]=1
      changed=1
    done
  done
  return 0
}

# _keepalive_dropin_pids PARENT DROPIN [UNIT...]: the processes the drop-in
# started (ka_hit of one _keepalive_dropin_snapshot) that are still there.
_keepalive_dropin_pids() {
  local pid
  local -a ka_order=()
  local -A ka_ppid=() ka_cmd=() ka_unit=() ka_hit=()
  _keepalive_dropin_snapshot "$@"
  for pid in ${ka_order[@]+"${ka_order[@]}"}; do
    [[ -n "${ka_hit[${pid}]:-}" ]] || continue
    [[ -n "$(_keepalive_pids_alive "${pid}")" ]] || continue
    printf '%s\n' "${pid}"
  done
  return 0
}

_keepalive_norm() {
  local s="${1//[\'\"]/}"
  s="$(tr -s '[:space:]' ' ' <<<"${s}")"
  s="${s# }"
  printf '%s' "${s% }"
}

# FU-SYNCHUB (Sol N-16, N-17, SOL-N-10). Which units a drop-in reaches is
# asked of systemd, not read from the directory name, and which processes it
# may have started is decided by cgroup membership, not by matching its
# Exec*= text (systemd expands ${VAR} and %-specifiers before exec).

# _keepalive_cgroup_units TYPE: the TYPE units (systemd hierarchy path
# components ending .TYPE, unescaped as in _keepalive_cgroup_members) that
# hold a live process now, one per line.
_keepalive_cgroup_units() {
  local type="$1" root="${WINS_KEEPALIVE_ROOT:-}" d hier cgpath _ comp
  local -a comps=()
  local -A ka_seen=()
  for d in "${root}"/proc/[0-9]*; do
    [[ -r "${d}/cgroup" ]] || continue
    grep -qsE '^State:[[:space:]]*Z' "${d}/status" && continue
    { while IFS=: read -r _ hier cgpath; do
        [[ -z "${hier}" || "${hier}" == name=systemd ]] || continue
        IFS=/ read -r -a comps <<<"${cgpath}"
        for comp in ${comps[@]+"${comps[@]}"}; do
          comp="${comp#_}"
          if [[ "${comp}" == ?*".${type}" ]]; then ka_seen["${comp}"]=1; fi
        done
      done < "${d}/cgroup"; } 2>/dev/null || true
  done
  for comp in "${!ka_seen[@]}"; do printf '%s\n' "${comp}"; done
  return 0
}

# _keepalive_dropin_names_unit PARENT NAME: 0 when systemd applies the drop-in
# directory PARENT.d to the unit NAME by name: NAME is PARENT, an instance of
# the template PARENT (x@.service), or starts with the dash prefix of PARENT
# (foo-.service). A bare -.service is left to DropInPaths.
_keepalive_dropin_names_unit() {
  local parent="$1" name="$2"
  [[ "${name}" == "${parent}" ]] && return 0
  if [[ "${parent}" == *@.* ]]; then
    [[ "${name}" == "${parent%%@*}@"*".${parent##*.}" ]]
    return
  fi
  if [[ "${parent}" == ?*-.* ]]; then
    [[ "${name}" == "${parent%.*}"*".${parent##*.}" ]]
    return
  fi
  return 1
}

# _keepalive_dropin_units PARENT DROPIN: the systemd Ids (one per line) of the
# units the drop-in file DROPIN (in PARENT.d) applies to. Candidates are PARENT
# itself (an alias resolves to its unit's Id) and every unit of PARENT's type
# that holds a process now. A candidate counts when systemd names it by Id for
# PARENT, when its name or Id is one PARENT.d reaches by name, or when its
# DropInPaths lists DROPIN. 1 when systemd does not answer for a candidate.
_keepalive_dropin_units() {
  local parent="$1" dropin="$2" root="${WINS_KEEPALIVE_ROOT:-}" u props id p want hit
  local -a dpaths=()
  local -A cand=() ka_seen=()
  want="$(readlink -f -- "${dropin}" 2>/dev/null)" || want="${dropin}"
  [[ "${parent}" == *@.* || "${parent}" == *-.* ]] || cand["${parent}"]=1
  while IFS= read -r u; do
    [[ -n "${u}" ]] && cand["${u}"]=1
  done < <(_keepalive_cgroup_units "${parent##*.}")
  for u in "${!cand[@]}"; do
    props="$(systemctl show -p Id,DropInPaths -- "${u}" 2>/dev/null)" || return 1
    id="$(sed -n 's/^Id=//p' <<<"${props}" | head -n 1)"
    [[ -n "${id}" ]] || return 1
    hit=0
    if _keepalive_dropin_names_unit "${parent}" "${u}" || _keepalive_dropin_names_unit "${parent}" "${id}"; then
      hit=1
    fi
    read -r -a dpaths <<<"$(sed -n 's/^DropInPaths=//p' <<<"${props}")"
    for p in ${dpaths[@]+"${dpaths[@]}"}; do
      [[ "$(readlink -f -- "${root}${p}" 2>/dev/null || printf '%s' "${root}${p}")" == "${want}" ]] && hit=1
    done
    if (( hit )) && [[ -z "${ka_seen[${id}]:-}" ]]; then
      ka_seen["${id}"]=1
      printf '%s\n' "${id}"
    fi
  done
  return 0
}

# _keepalive_dropin_main_trusted DROPIN: 0 when the drop-in only adds side
# commands (ExecStartPre/Post, ExecCondition, ExecReload, ExecStop/StopPost)
# or describes itself. Any other line (ExecStart=, Environment=, User=, a
# continuation, ...) can change the unit's own main process, which then may be
# the drop-in's too. An unreadable file is not trusted.
_keepalive_dropin_main_trusted() {
  local rc=0
  grep -qvE '^[[:space:]]*($|[#;]|\[|(Description|Documentation|ExecStartPre|ExecStartPost|ExecCondition|ExecReload|ExecStop|ExecStopPost)[[:space:]]*=)' "$1" || rc=$?
  (( rc == 1 ))
}

# _keepalive_descends PID ANCESTOR: 0 when PID is ANCESTOR or descends from it,
# by the parents in the caller's snapshot (ka_ppid; Turn 9: the same listing
# the decision is made from).
_keepalive_descends() {
  local pid="$1" n
  [[ "$2" =~ ^[1-9][0-9]*$ ]] || return 1
  for (( n = 0; n < 64; n++ )); do
    [[ "${pid}" == "$2" ]] && return 0
    [[ "${pid}" =~ ^[1-9][0-9]*$ && "${pid}" != 1 ]] || return 1
    pid="${ka_ppid[${pid}]:-}"
  done
  return 1
}

# _keepalive_dropin_judge MODE PARENT DROPIN UNIT...: from one
# _keepalive_dropin_snapshot, one line "PID (command) in UNIT" for each process
# in a UNIT's cgroup that the drop-in may have started and that is not its
# forger (ka_hit): every process other than the unit's MainPID and its
# descendants, and every process at all when the drop-in can change the main
# process. MODE left adds, from the same snapshot, "PID (command), a health
# forger, in PARENT" for each forger. A process is left out only when it is
# gone by the time it would be reported. 1 when systemd does not report a
# MainPID.
_keepalive_dropin_judge() {
  local mode="$1" parent="$2" dropin="$3" u main pid trusted=0
  local -a ka_order=()
  local -A ka_ppid=() ka_cmd=() ka_unit=() ka_hit=()
  shift 3
  _keepalive_dropin_snapshot "${parent}" "${dropin}" "$@"
  _keepalive_dropin_main_trusted "${dropin}" && trusted=1
  for u in "$@"; do
    main=""
    for pid in ${ka_order[@]+"${ka_order[@]}"}; do
      [[ "${ka_unit[${pid}]:-}" == "${u}" ]] || continue
      if [[ -z "${main}" ]]; then
        main="$(systemctl show -p MainPID --value -- "${u}" 2>/dev/null)" || return 1
        # Only a service has a main process; any other unit type has none.
        [[ -z "${main}" && "${u}" != *.service ]] && main=0
        [[ "${main}" =~ ^[0-9]+$ ]] || return 1
      fi
      [[ -z "${ka_hit[${pid}]:-}" ]] || continue
      if (( trusted )) && _keepalive_descends "${pid}" "${main}"; then
        continue
      fi
      [[ -n "$(_keepalive_pids_alive "${pid}")" ]] || continue
      printf '%s (%s) in %s\n' "${pid}" "${ka_cmd[${pid}]:-}" "${u}"
    done
  done
  [[ "${mode}" == left ]] || return 0
  for pid in ${ka_order[@]+"${ka_order[@]}"}; do
    [[ -n "${ka_hit[${pid}]:-}" ]] || continue
    [[ -n "$(_keepalive_pids_alive "${pid}")" ]] || continue
    printf '%s (%s), a health forger, in %s\n' "${pid}" "${ka_cmd[${pid}]:-}" "${parent}"
  done
  return 0
}

# _keepalive_dropin_unexplained PARENT DROPIN UNIT...: the "in UNIT" lines of
# _keepalive_dropin_judge. 1 when systemd does not report a MainPID.
_keepalive_dropin_unexplained() {
  _keepalive_dropin_judge unexplained "$@"
}

# _keepalive_dropins_precheck FINDINGS: for each forging drop-in among
# FINDINGS, record in the caller's dropin_units (bash dynamic scope) the units
# systemd says it applies to, and refuse (1, every reason named) when systemd
# does not answer or when a process runs there that the drop-in may have
# started and that cannot be ended as a forger. Writes nothing; the deploy runs
# it before the quarantine exists and --preflight runs it as a preview.
_keepalive_dropins_precheck() {
  local root="${WINS_KEEPALIVE_ROOT:-}" kind path parent units left rc=0
  while IFS=$'\t' read -r kind path; do
    [[ "${kind}" == unit && "${path}" == */*.d/*.conf ]] || continue
    parent="$(basename -- "$(dirname -- "${path}")")"
    parent="${parent%.d}"
    if ! units="$(_keepalive_dropin_units "${parent}" "${root}${path}")"; then
      err "Health keepalive: systemd did not say which units the drop-in ${path} applies to (systemctl show failed), so what it started cannot be found. Nothing was changed."
      rc=1
      continue
    fi
    dropin_units["${path}"]="$(paste -sd ' ' - <<<"${units}")"
    # shellcheck disable=SC2086 # unit names, one per word
    if ! left="$(_keepalive_dropin_unexplained "${parent}" "${root}${path}" ${units})"; then
      err "Health keepalive: systemd did not report the main process of a unit the drop-in ${path} applies to (${dropin_units[${path}]}). Nothing was changed."
      rc=1
      continue
    fi
    if [[ -n "${left}" ]]; then
      err "Health keepalive: the drop-in ${path} applies to ${dropin_units[${path}]}, where process(es) run that it may have started and that are not recognisably a health forger or the unit's own main process: $(tr '\n' ';' <<<"${left}") Nothing was changed. Remove the drop-in, run systemctl daemon-reload, restart or stop those units, then rerun."
      rc=1
    fi
  done <<<"$1"
  return "${rc}"
}

# Turn 7 (Sol N-19): the precheck can only name the units that exist then.
# After the drop-in moved and systemd reloaded, the units it reached are
# found again (and on every wait), so a unit that started in between (a new
# template instance, a new dash-prefix unit) is checked as well.
# _keepalive_dropin_units_now PARENT UNIT...: one per line, each UNIT the
# precheck recorded; every unit whose cgroup PARENT names now (the
# _keepalive_cgroup_members pattern: the unit itself, a template's
# instances, a dash prefix's units) and that PARENT.d reaches by name (a bare
# -.service.d reaches no unit by name on systemd 255; what it reached is in
# the recorded DropInPaths units); and every unit of PARENT's type that
# holds a process now and has an alias (systemd's Names, other than its Id)
# that PARENT.d reaches by name. A unit's Id is its cgroup's name, so for the
# Id the cgroup pattern decides. 1 when systemd does not answer.
_keepalive_dropin_units_now() {
  local parent="$1" u id props n _
  local -a names=() cand=()
  local -A ka_seen=()
  shift
  for u in "$@"; do
    [[ -n "${u}" && -z "${ka_seen[${u}]:-}" ]] || continue
    ka_seen["${u}"]=1
    printf '%s\n' "${u}"
  done
  while IFS=$'\t' read -r _ u; do
    [[ -n "${u}" && -z "${ka_seen[${u}]:-}" ]] || continue
    _keepalive_dropin_names_unit "${parent}" "${u}" || continue
    ka_seen["${u}"]=1
    printf '%s\n' "${u}"
  done < <(_keepalive_cgroup_members "${parent}")
  mapfile -t cand < <(_keepalive_cgroup_units "${parent##*.}")
  for u in ${cand[@]+"${cand[@]}"}; do
    [[ -n "${u}" && -z "${ka_seen[${u}]:-}" ]] || continue
    props="$(systemctl show -p Id,Names -- "${u}" 2>/dev/null)" || return 1
    id="$(sed -n 's/^Id=//p' <<<"${props}" | head -n 1)"
    [[ -n "${id}" ]] || return 1
    read -r -a names <<<"$(sed -n 's/^Names=//p' <<<"${props}")"
    for n in ${names[@]+"${names[@]}"}; do
      [[ "${n}" != "${id}" ]] || continue
      if _keepalive_dropin_names_unit "${parent}" "${n}"; then
        [[ -n "${ka_seen[${id}]:-}" ]] || printf '%s\n' "${id}"
        ka_seen["${id}"]=1
        break
      fi
    done
  done
  return 0
}

# _keepalive_dropin_left PARENT DROPIN UNIT...: after retirement, what may
# still be the drop-in's: both kinds of _keepalive_dropin_judge line, from one
# snapshot. A forger was already ended once, so one that is there now (one
# that started late, or a child its ended or exited launcher left) is
# reported, not excused. 1 when systemd does not report a MainPID.
_keepalive_dropin_left() {
  _keepalive_dropin_judge left "$@"
}

# _keepalive_filter_file SRC DST: SRC without its forging lines. Prints the
# number of lines kept that are neither blank, comments nor VAR=value.
_keepalive_filter_file() {
  grep -viE -- "${WINS_KEEPALIVE_LINE_RE}" "$1" > "$2" || [[ $? -eq 1 ]] || return 1
  grep -cvE '^[[:space:]]*($|#|[A-Za-z_][A-Za-z0-9_]*=)' "$2" || true
}

# retire_health_forging_keepalive: gate, report, then quarantine (--deploy).
# Returns 1, naming the step, when the gate refuses, any step fails, or
# anything that forges is still in place afterwards.
retire_health_forging_keepalive() {
  local root="${WINS_KEEPALIVE_ROOT:-}" findings kind path f user tmp kept quarantine stamp q name
  local moved=0 units=0 remaining parent entry pids dq dunits dstored left tick
  local -a stopped=() dropins=()
  local -A dropin_units=()
  findings="$(health_keepalive_scan | LC_ALL=C sort -u)"
  if [[ -z "${findings}" ]]; then
    log "Health keepalive check: no keepalive_nodes script or runner found."
    return 0
  fi
  health_keepalive_gate || return 1
  if grep -q $'^typedropin\t' <<<"${findings}"; then
    err "Health keepalive: a top-level systemd type drop-in forges health and applies to every unit of its type: $(grep $'^typedropin\t' <<<"${findings}" | cut -f2 | tr '\n' ' ')(never retired automatically). Remove it by hand, run systemctl daemon-reload, restart the units it reached, then rerun. Nothing was changed."
    return 1
  fi
  # FU-SYNCHUB: before anything is written, systemd names the units each
  # forging drop-in reaches, and a process there that the drop-in may have
  # started but that is not ended as a forger refuses the deploy.
  _keepalive_dropins_precheck "${findings}" || return 1
  stamp="$(date -u +%Y%m%dT%H%M%SZ)" || { err "Health keepalive: date failed."; return 1; }
  quarantine="${root}/var/backups/winsvpn-retired/keepalive-${stamp}-$$"
  install -d -m 0700 "${root}/var/backups/winsvpn-retired" "${quarantine}" \
    || { err "Health keepalive: cannot create the quarantine ${quarantine#"${root}"}; nothing was retired."; return 1; }
  while IFS=$'\t' read -r kind path; do
    f="${root}${path}"
    q="${quarantine}/$(_keepalive_quarantine_name "${path}")"
    case "${kind}" in
      cron)
        cp -p -- "${f}" "${q}" || { err "Health keepalive: cannot back up ${path}; left in place."; return 1; }
        tmp="$(mktemp "${f}.wins-keepalive.XXXXXX")" \
          || { err "Health keepalive: cannot stage a rewrite of ${path}; left in place."; return 1; }
        if ! kept="$(_keepalive_filter_file "${f}" "${tmp}")"; then
          rm -f -- "${tmp}"
          err "Health keepalive: cannot filter ${path}; left in place."
          return 1
        fi
        if [[ "${path}" == /etc/cron.d/* && "${kept:-0}" == "0" ]]; then
          rm -f -- "${tmp}"
          mv -f -- "${f}" "${q}.removed" || { err "Health keepalive: cannot move ${path} into quarantine; left in place."; return 1; }
          warn "SECURITY: quarantined ${path} (it only ran the health-forging keepalive)."
        else
          chmod --reference="${f}" "${tmp}" 2>/dev/null || chmod 0644 "${tmp}" \
            || { rm -f -- "${tmp}"; err "Health keepalive: cannot set the mode of the rewrite of ${path}; left in place."; return 1; }
          mv -f -- "${tmp}" "${f}" \
            || { rm -f -- "${tmp}"; err "Health keepalive: cannot rewrite ${path}; left in place."; return 1; }
          warn "SECURITY: removed the health-forging line(s) from ${path}; original kept in ${quarantine#"${root}"}."
        fi
        moved=$((moved + 1))
        ;;
      usercron:*)
        user="${kind#usercron:}"
        cp -p -- "${f}" "${quarantine}/crontab-${user}" \
          || { err "Health keepalive: cannot back up the crontab of ${user}; left in place."; return 1; }
        tmp="$(mktemp)" || { err "Health keepalive: mktemp failed for the crontab of ${user}."; return 1; }
        # Read through crontab(1), never guessed: a failed read must not be
        # written back as an empty crontab.
        if ! crontab -u "${user}" -l > "${tmp}.all" 2>/dev/null; then
          rm -f -- "${tmp}" "${tmp}.all"
          err "Could not read the crontab of ${user}; the health-forging keepalive is still scheduled (${path})."
          return 1
        fi
        if ! { grep -viE -- "${WINS_KEEPALIVE_LINE_RE}" "${tmp}.all" > "${tmp}" || [[ $? -eq 1 ]]; } \
            || ! crontab -u "${user}" "${tmp}"; then
          rm -f -- "${tmp}" "${tmp}.all"
          err "Could not rewrite the crontab of ${user}; the health-forging keepalive is still scheduled (${path})."
          return 1
        fi
        rm -f -- "${tmp}" "${tmp}.all"
        warn "SECURITY: removed the health-forging line(s) from the crontab of ${user}; original kept in ${quarantine#"${root}"}."
        moved=$((moved + 1))
        ;;
      unit)
        name="$(basename -- "${path}")"
        if [[ "${path}" == */*.d/*.conf ]]; then
          # A drop-in: its parent unit stays. Its commands run in the parent's
          # cgroup and outlive the file, so after the daemon-reload below they
          # are ended and verified gone.
          parent="$(basename -- "$(dirname -- "${path}")")"
          parent="${parent%.d}"
          mv -f -- "${f}" "${q}" || { err "Health keepalive: cannot move ${path} into quarantine; left in place."; return 1; }
          dropins+=("${parent}"$'\t'"${q}"$'\t'"${dropin_units[${path}]:-}")
          if [[ "${parent}" == *-.* ]]; then
            warn "SECURITY: quarantined the health-forging systemd drop-in ${path}; it applies to every ${parent%.*}*.${parent##*.} unit, and those units stay."
          else
            warn "SECURITY: quarantined the health-forging systemd drop-in ${path}; its parent ${parent} stays."
          fi
        else
          # Stop before the file goes, and prove it stopped, so a running
          # timer or service cannot outlive its unit file. disable also
          # removes a linked unit's link, so the link is copied first.
          if [[ -L "${f}" ]]; then
            cp -P -- "${f}" "${q}" || { err "Health keepalive: cannot back up the linked unit ${path}; left in place."; return 1; }
          fi
          if ! systemctl disable --now "${name}" >/dev/null 2>&1; then
            systemctl stop "${name}" >/dev/null 2>&1 \
              || { err "Health keepalive: cannot stop ${name}; it may still be forging, so ${path} was left in place. Stop it by hand, then rerun."; return 1; }
            warn "Health keepalive: systemctl disable --now ${name} failed, but it stopped; quarantining the file anyway."
          fi
          _keepalive_stop_unit "${name}" \
            || { err "Health keepalive: ${name} may still be forging, so ${path} was left in place. Stop it by hand, then rerun."; return 1; }
          if [[ -e "${f}" || -L "${f}" ]]; then
            mv -f -- "${f}" "${q}" || { err "Health keepalive: cannot move ${path} into quarantine; left in place."; return 1; }
          fi
          warn "SECURITY: stopped and quarantined the health-forging systemd ${path}."
        fi
        units=$((units + 1))
        moved=$((moved + 1))
        ;;
      periodic|script|link)
        if [[ "${kind}" == link && "${path}" == /etc/crontab ]]; then
          err "Health keepalive: /etc/crontab is a symlink that forges health; resolve it by hand, then rerun."
          return 1
        fi
        # mv moves a symlink itself, never its target.
        mv -f -- "${f}" "${q}" || { err "Health keepalive: cannot move ${path} into quarantine; left in place."; return 1; }
        if [[ "${kind}" != link ]]; then
          chmod 0600 "${q}" || { err "Health keepalive: cannot make the quarantined ${path} non-executable."; return 1; }
        fi
        warn "SECURITY: quarantined the health-forging ${kind} ${path}."
        moved=$((moved + 1))
        ;;
    esac
  done <<<"${findings}"
  if (( units > 0 )); then
    systemctl daemon-reload >/dev/null 2>&1 \
      || { err "Health keepalive: systemctl daemon-reload failed after quarantining unit files."; return 1; }
  fi
  # Nothing quarantined may still run: every stopped unit stays quiet after
  # the reload, and a drop-in's commands are ended inside its parent.
  for name in ${stopped[@]+"${stopped[@]}"}; do
    _keepalive_unit_quiet "${name}" \
      || { err "Health keepalive: ${name} is running again after the daemon-reload."; return 1; }
  done
  # Turn 7 (Sol N-19): the units it reaches are found again now, and on every
  # wait below, so a unit that started after the precheck is checked too.
  # shellcheck disable=SC2086 # dunits, dstored: systemd unit Ids, one per word
  for entry in ${dropins[@]+"${dropins[@]}"}; do
    IFS=$'\t' read -r parent dq dstored <<<"${entry}"
    dunits="$(_keepalive_dropin_units_now "${parent}" ${dstored})" \
      || { err "Health keepalive: systemd did not say which units the retired drop-in of ${parent} reaches now."; return 1; }
    dunits="${dunits//$'\n'/ }"
    pids="$(_keepalive_dropin_pids "${parent}" "${dq}" ${dunits})"
    if [[ -n "${pids}" ]]; then
      # shellcheck disable=SC2086 # one PID per word
      _keepalive_end_pids ${pids} \
        || { err "Health keepalive: a health-forging process the drop-in started in ${parent} (${dunits:-no running unit}) survived SIGKILL: $(tr '\n' ' ' <<<"$(_keepalive_pids_alive ${pids})")"; return 1; }
      warn "SECURITY: ended the health-forging process(es) $(tr '\n' ' ' <<<"${pids}")that a drop-in started in ${parent} (${dunits:-no running unit})."
    fi
    # Turn 8 (Sol N-21): ending them waited, and a unit the drop-in reaches
    # may have started meanwhile, so the units are found again before any
    # check that follows.
    dunits="$(_keepalive_dropin_units_now "${parent}" ${dstored})" \
      || { err "Health keepalive: systemd did not say which units the retired drop-in of ${parent} reaches now."; return 1; }
    dunits="${dunits//$'\n'/ }"
    pids="$(_keepalive_dropin_pids "${parent}" "${dq}" ${dunits})"
    [[ -z "${pids}" ]] \
      || { err "Health keepalive: a health-forging process the drop-in started is still running in ${parent}: $(tr '\n' ' ' <<<"${pids}")(${dunits:-no running unit}). Stop or restart those units by hand, then rerun."; return 1; }
    # A child an ended forger left behind (its sleep, say) is orphaned and
    # outlives it briefly; it gets the same stop window to exit. A process
    # still there afterwards (or a forger that started meanwhile) refuses.
    for (( tick = 0; ; tick++ )); do
      left="$(_keepalive_dropin_left "${parent}" "${dq}" ${dunits})" \
        || { err "Health keepalive: systemd did not report the main process of a unit the drop-in of ${parent} reached (${dunits:-no running unit})."; return 1; }
      (( tick < ${WINS_KEEPALIVE_STOP_TICKS:-50} && ${#left} > 0 )) || break
      sleep 0.2
      dunits="$(_keepalive_dropin_units_now "${parent}" ${dstored})" \
        || { err "Health keepalive: systemd did not say which units the retired drop-in of ${parent} reaches now."; return 1; }
      dunits="${dunits//$'\n'/ }"
    done
    [[ -z "${left}" ]] \
      || { err "Health keepalive: after the drop-in of ${parent} was retired, process(es) it may have started still run: $(tr '\n' ';' <<<"${left}") Stop or restart those units by hand, then rerun."; return 1; }
  done
  # Turn 8 (Sol N-21): each check above was followed by the waits of the
  # drop-ins after it. One last pass, with no wait after it, finds every
  # drop-in's units again and checks every stopped unit; anything that
  # started meanwhile refuses.
  # shellcheck disable=SC2086 # dunits, dstored: systemd unit Ids, one per word
  if (( ${#dropins[@]} > 0 )); then
    for name in ${stopped[@]+"${stopped[@]}"}; do
      _keepalive_unit_quiet "${name}" \
        || { err "Health keepalive: ${name} is running again (it started while the retirement waited)."; return 1; }
    done
    for entry in "${dropins[@]}"; do
      IFS=$'\t' read -r parent dq dstored <<<"${entry}"
      dunits="$(_keepalive_dropin_units_now "${parent}" ${dstored})" \
        || { err "Health keepalive: systemd did not say which units the retired drop-in of ${parent} reaches now."; return 1; }
      dunits="${dunits//$'\n'/ }"
      left="$(_keepalive_dropin_left "${parent}" "${dq}" ${dunits})" \
        || { err "Health keepalive: systemd did not report the main process of a unit the drop-in of ${parent} reached (${dunits:-no running unit})."; return 1; }
      [[ -z "${left}" ]] \
        || { err "Health keepalive: while the retirement waited, the drop-in of ${parent} came to reach process(es) it may have started: $(tr '\n' ';' <<<"${left}") Stop or restart those units by hand, then rerun."; return 1; }
    done
  fi
  remaining="$(health_keepalive_scan || true)"
  if [[ -n "${remaining}" ]]; then
    err "Health keepalive: still in place after retirement: $(tr '\n\t' '; ' <<<"${remaining}")"
    return 1
  fi
  log "Health keepalive check: ${moved} item(s) quarantined in ${quarantine#"${root}"}; a rescan finds nothing that forges and nothing quarantined still runs. Rows it forged stay until a real health result or an operator changes them; the hub reports open nodes without promotion evidence."
  return 0
}
